import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

/**
 * This is a pure frontend application with NO backend API (contract is []).
 * Import/export operates on client-side downloadable JSON config files.
 * The "import confirmation cancel" is a UI dialog interaction.
 *
 * From vitest+fetch we verify:
 * 1. The app contains import/export logic covering all required data domains
 * 2. Version info is present in exports (Round 12)
 * 3. Breakpoint hidden states and styles are part of the data model
 * 4. Confirmation dialog exists for import to prevent accidental overwrite
 * 5. Cancel import preserves current state (logic is present)
 */

async function fetchAppHtml() {
  const res = await fetch(`${BASE_URL}`);
  const text = await res.text();
  return { res, text };
}

async function fetchAppBundle() {
  const { text: html } = await fetchAppHtml();
  const scriptMatches = html.match(/src="([^"]*\.js[^"]*)"/g) || [];
  let bundleContent = '';
  for (const match of scriptMatches) {
    const src = match.replace(/src="/, '').replace(/"$/, '');
    const url = src.startsWith('http') ? src : `${BASE_URL}${src.startsWith('/') ? '' : '/'}${src}`;
    try {
      const res = await fetch(url);
      if (res.ok) {
        bundleContent += await res.text();
      }
    } catch {
      // skip
    }
  }
  return bundleContent;
}

describe('import_restore_preserves_page_and_breakpoint_state', () => {
  it('should serve the application successfully', async () => {
    const res = await fetch(`${BASE_URL}`);
    expect(res.status).toBe(200);
    const html = await res.text();
    expect(html.length).toBeGreaterThan(100);
  });

  it('should include export functionality with version info (Round 12)', async () => {
    const bundle = await fetchAppBundle();
    const hasExport = bundle.includes('export') || bundle.includes('Export') || bundle.includes('导出');
    expect(hasExport, 'App should have export functionality').toBe(true);

    const hasVersion = bundle.includes('version') || bundle.includes('Version');
    expect(hasVersion, 'Exported config should include version information').toBe(true);
  });

  it('should handle page name preservation through export/import cycle', async () => {
    const bundle = await fetchAppBundle();
    // The data model must include page name in both export and import
    const hasPageName = (
      (bundle.includes('name') || bundle.includes('pageName')) &&
      (bundle.includes('pages') || bundle.includes('page'))
    );
    expect(hasPageName, 'App should preserve page names in export/import').toBe(true);
  });

  it('should handle block ordering preservation through export/import cycle', async () => {
    const bundle = await fetchAppBundle();
    const hasBlockOrder = (
      bundle.includes('blocks') &&
      (bundle.includes('order') || bundle.includes('index') || bundle.includes('Array') || bundle.includes('map') || bundle.includes('forEach'))
    );
    expect(hasBlockOrder, 'App should preserve block ordering through export/import').toBe(true);
  });

  it('should include breakpoint hidden state in data model for export/import', async () => {
    const bundle = await fetchAppBundle();
    // Breakpoint visibility per block must be part of export data
    const hasBreakpointHidden = (
      bundle.includes('hidden') &&
      (bundle.includes('mobile') || bundle.includes('tablet') || bundle.includes('desktop'))
    );
    expect(hasBreakpointHidden, 'App should include breakpoint hidden states in export/import data model').toBe(true);

    // Should be directly asserted, not conditionally checked
    const hasBreakpointSettings = (
      bundle.includes('breakpointSettings') ||
      bundle.includes('breakpoint_settings') ||
      bundle.includes('visibility')
    );
    expect(hasBreakpointSettings, 'App should have a breakpointSettings structure per block').toBe(true);
  });

  it('should include styles in data model for export/import', async () => {
    const bundle = await fetchAppBundle();
    const hasStyles = (
      bundle.includes('styles') ||
      bundle.includes('style') ||
      bundle.includes('alignment') ||
      bundle.includes('borderRadius') ||
      bundle.includes('padding')
    );
    expect(hasStyles, 'App should include styles in export/import data model').toBe(true);
  });

  it('should require confirmation before import overwrites current content (Round 10/14)', async () => {
    const bundle = await fetchAppBundle();
    // Round 10: 套用模板前如果当前页面已有未保存改动，要先有明确确认
    // Round 14: 取消导入确认，当前编辑内容必须原封不动保留
    const hasConfirmation = (
      bundle.includes('confirm') ||
      bundle.includes('确认') ||
      bundle.includes('Confirm') ||
      bundle.includes('cancel') ||
      bundle.includes('取消')
    );
    expect(hasConfirmation, 'App should have confirmation dialog before import overwrites content').toBe(true);
  });

  it('should preserve current content when import is cancelled (Round 14)', async () => {
    const bundle = await fetchAppBundle();
    // When user cancels import, the current editing content must remain unchanged
    // This means the import logic should only apply changes AFTER confirmation
    const hasCancelPreservation = (
      (bundle.includes('cancel') || bundle.includes('取消') || bundle.includes('Cancel')) &&
      (bundle.includes('return') || bundle.includes('reject') || bundle.includes('abort') || bundle.includes('restore'))
    );
    expect(hasCancelPreservation, 'App should preserve current content when import confirmation is cancelled').toBe(true);
  });

  it('should include version field with a defined format in exported data', async () => {
    const bundle = await fetchAppBundle();
    // Round 12: version info for future compatibility
    // Should have an explicit version value assignment
    const hasVersionAssignment = (
      bundle.includes('version:') ||
      bundle.includes('version =') ||
      bundle.includes('"version"') ||
      bundle.includes("'version'")
    );
    expect(hasVersionAssignment, 'App should assign a version value in exported config').toBe(true);
  });
});

import { describe, it, expect, beforeAll, afterAll } from 'vitest';
import { chromium, Browser, Page } from 'playwright';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

let browser: Browser;

beforeAll(async () => {
  browser = await chromium.launch({ headless: true });
});

afterAll(async () => {
  if (browser) await browser.close();
});

async function createPage(): Promise<Page> {
  const context = await browser.newContext();
  const page = await context.newPage();
  return page;
}

async function clearLocalStorage(page: Page) {
  await page.evaluate(() => localStorage.clear());
}

async function waitForApp(page: Page) {
  await page.goto(BASE_URL, { waitUntil: 'networkidle' });
  await page.waitForTimeout(1000);
}

describe('round9_autosave_restore_state', () => {
  it('should load the editor application successfully', async () => {
    const res = await fetch(BASE_URL);
    expect(res.status).toBe(200);
    const html = await res.text();
    expect(html).toBeTruthy();
    expect(html).toMatch(/<div\s+id=["']root["']/i);
  });

  it('should show initial guidance state when no saved data exists (empty localStorage)', async () => {
    const page = await createPage();
    try {
      await waitForApp(page);
      await clearLocalStorage(page);
      await page.reload({ waitUntil: 'networkidle' });
      await page.waitForTimeout(1000);

      const bodyText = await page.textContent('body');
      expect(bodyText).toBeTruthy();

      // When no saved data, editor should show an initial/empty/guidance state
      // Check for guidance text or empty state indicators
      const hasGuidance = await page.evaluate(() => {
        const text = document.body.innerText.toLowerCase();
        return text.includes('开始') || text.includes('添加') || text.includes('拖') ||
               text.includes('empty') || text.includes('start') || text.includes('add') ||
               text.includes('drag') || text.includes('引导') || text.includes('空白') ||
               text.includes('no block') || text.includes('get started');
      });
      expect(hasGuidance, 'Editor should show initial guidance state when localStorage is empty').toBe(true);
    } finally {
      await page.context().close();
    }
  });

  it('should auto-save editor state and restore after refresh, including blocks, page settings, and styles', async () => {
    const page = await createPage();
    try {
      await waitForApp(page);
      await clearLocalStorage(page);
      await page.reload({ waitUntil: 'networkidle' });
      await page.waitForTimeout(1000);

      // Try to add blocks by clicking material/component items in the left panel
      const addButtons = await page.$$('[class*="material"] button, [class*="component"] button, [class*="sidebar"] button, [class*="panel"] button, [data-testid*="add"], [class*="素材"] button, [class*="block-type"], [class*="component-item"], button:has-text("标题"), button:has-text("文本"), button:has-text("按钮"), button:has-text("heading"), button:has-text("text"), button:has-text("button"), button:has-text("图片"), button:has-text("image"), [class*="add"]');

      let addedBlocks = 0;
      for (const btn of addButtons.slice(0, 3)) {
        try {
          await btn.click();
          await page.waitForTimeout(500);
          addedBlocks++;
        } catch { /* button might not be interactable */ }
      }

      // If no obvious add buttons found, try clicking items in the left sidebar area
      if (addedBlocks === 0) {
        const leftPanelItems = await page.$$('[class*="left"] [class*="item"], [class*="素材"] *, [class*="material"] *, aside:first-of-type [class*="item"], [class*="component-list"] > *');
        for (const item of leftPanelItems.slice(0, 3)) {
          try {
            await item.click();
            await page.waitForTimeout(500);
            addedBlocks++;
          } catch { /* skip */ }
        }
      }

      // Wait for autosave debounce to complete
      await page.waitForTimeout(3000);

      // Capture current state from localStorage
      const savedData = await page.evaluate(() => {
        const keys = Object.keys(localStorage);
        const data: Record<string, string> = {};
        for (const k of keys) {
          data[k] = localStorage.getItem(k) || '';
        }
        return data;
      });

      // There should be something saved in localStorage
      const savedKeys = Object.keys(savedData);
      expect(savedKeys.length, 'localStorage should have saved data after editing').toBeGreaterThan(0);

      // At least one key should contain parseable JSON with editor state
      let foundEditorState = false;
      for (const key of savedKeys) {
        try {
          const parsed = JSON.parse(savedData[key]);
          if (parsed && typeof parsed === 'object') {
            const str = JSON.stringify(parsed).toLowerCase();
            if (str.includes('block') || str.includes('page') || str.includes('区块') || str.includes('section') || str.includes('component')) {
              foundEditorState = true;
              break;
            }
          }
        } catch { /* not JSON */ }
      }
      expect(foundEditorState, 'localStorage should contain editor state data (blocks, pages, etc.)').toBe(true);

      // Capture a snapshot of the page content before refresh
      const contentBefore = await page.evaluate(() => document.body.innerText);

      // Refresh the page to test restore
      await page.reload({ waitUntil: 'networkidle' });
      await page.waitForTimeout(2000);

      // After refresh, the state should be restored - localStorage should still have data
      const savedDataAfter = await page.evaluate(() => {
        const keys = Object.keys(localStorage);
        return keys.length;
      });
      expect(savedDataAfter, 'localStorage data should persist across page refresh').toBeGreaterThan(0);

      // The page content after refresh should resemble the content before refresh
      const contentAfter = await page.evaluate(() => document.body.innerText);
      expect(contentAfter).toBeTruthy();
      // The page should not be showing empty guidance anymore if we had added content
      // (this is a soft check since we may not have successfully added blocks)
    } finally {
      await page.context().close();
    }
  });

  it('should show a clear prompt and allow reset when localStorage contains corrupted data', async () => {
    const page = await createPage();
    try {
      await waitForApp(page);

      // Inject corrupted data into localStorage keys that the app likely uses
      await page.evaluate(() => {
        localStorage.clear();
        // Try various common key names the app might use for autosave
        const possibleKeys = [
          'editor-state', 'editorState', 'editor_state',
          'autosave', 'auto-save', 'autoSave',
          'project', 'project-data', 'projectData',
          'page-builder', 'pageBuilder', 'page_builder',
          'app-state', 'appState', 'app_state',
          'draft', 'state', 'data', 'save',
          'webpage-generator', 'builder-state'
        ];
        for (const key of possibleKeys) {
          localStorage.setItem(key, '{{{CORRUPTED_DATA_NOT_VALID_JSON!!!');
        }
      });

      // Reload to trigger the corrupt data detection
      await page.reload({ waitUntil: 'networkidle' });
      await page.waitForTimeout(2000);

      const bodyText = await page.evaluate(() => document.body.innerText.toLowerCase());

      // The app should show an error/warning prompt about corrupted data
      const hasCorruptionNotice = bodyText.includes('损坏') || bodyText.includes('corrupt') ||
        bodyText.includes('无法') || bodyText.includes('解析') || bodyText.includes('错误') ||
        bodyText.includes('error') || bodyText.includes('invalid') || bodyText.includes('parse') ||
        bodyText.includes('清空') || bodyText.includes('clear') || bodyText.includes('reset') ||
        bodyText.includes('重新') || bodyText.includes('恢复') || bodyText.includes('failed');

      expect(hasCorruptionNotice, 'Editor should display a clear prompt when corrupted data is detected in localStorage').toBe(true);

      // Look for a clear/reset button to allow user to start fresh
      const resetButtons = await page.$$('button');
      let hasResetAction = false;
      for (const btn of resetButtons) {
        const btnText = (await btn.textContent() || '').toLowerCase();
        if (btnText.includes('清空') || btnText.includes('重新') || btnText.includes('clear') ||
            btnText.includes('reset') || btnText.includes('重置') || btnText.includes('确认') ||
            btnText.includes('confirm') || btnText.includes('ok') || btnText.includes('开始')) {
          hasResetAction = true;
          // Click the reset button
          try {
            await btn.click();
            await page.waitForTimeout(1000);
          } catch { /* might not be clickable */ }
          break;
        }
      }

      expect(hasResetAction, 'Editor should provide a button to clear corrupted data and restart').toBe(true);

      // After clearing, the editor should not be stuck
      const afterResetText = await page.evaluate(() => document.body.innerText);
      expect(afterResetText).toBeTruthy();
    } finally {
      await page.context().close();
    }
  });

  it('should serve the page without any server-side errors regardless of state', async () => {
    for (let i = 0; i < 3; i++) {
      const res = await fetch(BASE_URL);
      expect(res.status, `page load attempt ${i + 1} should succeed`).toBe(200);
    }
  });
});

import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function request(path, options = {}) {
  const res = await fetch(`${BASE_URL}${path}`, {
    headers: {
      'Content-Type': 'application/json',
      ...(options.headers || {}),
    },
    ...options,
  });
  const text = await res.text();
  let body;
  try {
    body = text ? JSON.parse(text) : null;
  } catch {
    body = text;
  }
  return { res, body };
}

async function safeDelete(path) {
  try {
    await fetch(`${BASE_URL}${path}`, { method: 'DELETE' });
  } catch {}
}

function uid(prefix = 'e2e') {
  return `${prefix}-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
}

describe('round21_multi_page_project_state', () => {
  it('should support create/copy/switch/delete page with uniqueness and limits, keep per-page isolated state, and include multi-page data in export/import', async () => {
    let projectId;
    let importedProjectId;

    try {
      // Step 1: Create project with initial page
      const created = await request('/api/projects', {
        method: 'POST',
        body: JSON.stringify({
          name: uid('multipage'),
          pages: [
            {
              name: 'Page 1',
              settings: { title: 'Page1 Title' },
              blocks: [{ type: 'text', content: { text: 'Page1 Block' } }],
              breakpoints: { mobile: 375, tablet: 768, desktop: 1200 },
              styles: { color: '#111111' },
            },
          ],
        }),
      });
      expect(created.res.status).toBe(201);
      projectId = created.body?.id;
      expect(projectId).toBeTruthy();

      // Step 2: Add Page 2 with distinct content
      const addPage2 = await request(`/api/projects/${projectId}/pages`, {
        method: 'POST',
        body: JSON.stringify({
          name: 'Page 2',
          settings: { title: 'Page2 Title' },
          blocks: [{ type: 'hero', content: { title: 'Hero 2' } }],
          breakpoints: { mobile: 360, tablet: 800, desktop: 1366 },
          styles: { color: '#222222' },
        }),
      });
      expect(addPage2.res.status).toBe(201);
      expect(addPage2.body?.name).toBe('Page 2');

      // Step 3: Duplicate page name should be rejected
      const duplicatePage = await request(`/api/projects/${projectId}/pages`, {
        method: 'POST',
        body: JSON.stringify({ name: 'Page 2' }),
      });
      expect([400, 409, 422]).toContain(duplicatePage.res.status);

      // Step 4: Copy Page 2 as Page 3
      const copyPage = await request(`/api/projects/${projectId}/pages/copy`, {
        method: 'POST',
        body: JSON.stringify({ sourcePage: 'Page 2', name: 'Page 3' }),
      });
      // Also try alternate endpoint if the first fails
      let copyResult = copyPage;
      if (![200, 201].includes(copyPage.res.status)) {
        const altCopy = await request(`/api/projects/${projectId}/pages/Page%202/copy`, {
          method: 'POST',
          body: JSON.stringify({ name: 'Page 3' }),
        });
        copyResult = altCopy;
      }
      expect([200, 201]).toContain(copyResult.res.status);
      expect(copyResult.body?.name).toBe('Page 3');

      // Step 4b: Verify copied page has same content as source
      const getAfterCopy = await request(`/api/projects/${projectId}`);
      expect(getAfterCopy.res.status).toBe(200);
      const page2Data = getAfterCopy.body?.pages?.find((p) => p.name === 'Page 2');
      const page3Data = getAfterCopy.body?.pages?.find((p) => p.name === 'Page 3');
      expect(page3Data, 'copied Page 3 should exist').toBeTruthy();
      if (page2Data && page3Data) {
        // Blocks should match source
        expect(
          page3Data.blocks?.length,
          'copied page should have same number of blocks as source'
        ).toBe(page2Data.blocks?.length);
        if (page2Data.blocks?.[0] && page3Data.blocks?.[0]) {
          expect(
            page3Data.blocks[0].type,
            'copied page block type should match source'
          ).toBe(page2Data.blocks[0].type);
        }
        // Breakpoints should match source
        if (page2Data.breakpoints && page3Data.breakpoints) {
          expect(page3Data.breakpoints.desktop).toBe(page2Data.breakpoints.desktop);
        }
        // Styles should match source
        if (page2Data.styles && page3Data.styles) {
          expect(page3Data.styles.color).toBe(page2Data.styles.color);
        }
      }

      // Step 5: Add pages 4 and 5 to reach the 5-page limit
      const addPage4 = await request(`/api/projects/${projectId}/pages`, {
        method: 'POST',
        body: JSON.stringify({ name: 'Page 4', blocks: [] }),
      });
      expect([200, 201]).toContain(addPage4.res.status);

      const addPage5 = await request(`/api/projects/${projectId}/pages`, {
        method: 'POST',
        body: JSON.stringify({ name: 'Page 5', blocks: [] }),
      });
      expect([200, 201]).toContain(addPage5.res.status);

      // Step 6: Exceeding 5-page limit should be rejected
      const overLimitPage = await request(`/api/projects/${projectId}/pages`, {
        method: 'POST',
        body: JSON.stringify({ name: 'Page 6' }),
      });
      expect([400, 422]).toContain(overLimitPage.res.status);

      // Step 7: Switch to Page 2 and verify current page indicator
      const switchPage2 = await request(`/api/projects/${projectId}/pages/Page%202/select`, {
        method: 'POST',
      });
      expect([200, 204]).toContain(switchPage2.res.status);

      // Verify the project state indicates current active page
      const projectAfterSwitch = await request(`/api/projects/${projectId}`);
      expect(projectAfterSwitch.res.status).toBe(200);
      const currentPageIndicator =
        projectAfterSwitch.body?.currentPage ||
        projectAfterSwitch.body?.activePage ||
        projectAfterSwitch.body?.selectedPage;
      if (currentPageIndicator !== undefined) {
        expect(
          currentPageIndicator === 'Page 2' || currentPageIndicator === 1,
          `expected current page to indicate Page 2, got ${currentPageIndicator}`
        ).toBe(true);
      }

      // Step 8: Update Page 2 content
      const updatePage2 = await request(`/api/projects/${projectId}/pages/Page%202`, {
        method: 'PUT',
        body: JSON.stringify({
          name: 'Page 2',
          settings: { title: 'Page2 Updated' },
          blocks: [{ type: 'hero', content: { title: 'Updated Hero 2' } }],
          breakpoints: { mobile: 390, tablet: 820, desktop: 1440 },
          styles: { color: '#333333' },
        }),
      });
      expect([200, 204]).toContain(updatePage2.res.status);

      // Step 9: Verify all pages maintain their isolated state
      const getProject = await request(`/api/projects/${projectId}`);
      expect(getProject.res.status).toBe(200);
      expect(Array.isArray(getProject.body?.pages)).toBe(true);
      expect(getProject.body.pages.length).toBe(5);

      const page1 = getProject.body.pages.find((p) => p.name === 'Page 1');
      const page2 = getProject.body.pages.find((p) => p.name === 'Page 2');
      expect(page1, 'Page 1 should exist').toBeTruthy();
      expect(page2, 'Page 2 should exist').toBeTruthy();

      // Page 1 should be unchanged
      expect(page1?.settings?.title).toBe('Page1 Title');
      expect(page1?.blocks?.[0]?.content?.text).toBe('Page1 Block');

      // Page 2 should reflect the update
      expect(page2?.settings?.title).toBe('Page2 Updated');
      expect(page2?.breakpoints?.desktop).toBe(1440);
      expect(page2?.styles?.color).toBe('#333333');

      // Step 10: Verify undo/redo isolation between pages
      // Perform an edit on Page 2 that gets recorded in history
      const page2Edit = await request(`/api/projects/${projectId}/pages/Page%202`, {
        method: 'PUT',
        body: JSON.stringify({
          name: 'Page 2',
          settings: { title: 'Page2 Edit For Undo' },
          blocks: [{ type: 'hero', content: { title: 'Edit For Undo' } }],
          breakpoints: { mobile: 390, tablet: 820, desktop: 1440 },
          styles: { color: '#333333' },
        }),
      });
      expect([200, 204]).toContain(page2Edit.res.status);

      // Try to undo on Page 2
      const undoPage2 = await request(`/api/projects/${projectId}/pages/Page%202/undo`, {
        method: 'POST',
      });
      // If undo endpoint exists, verify Page 1 is unaffected
      if ([200, 204].includes(undoPage2.res.status)) {
        const afterUndo = await request(`/api/projects/${projectId}`);
        expect(afterUndo.res.status).toBe(200);
        const p1AfterUndo = afterUndo.body?.pages?.find((p) => p.name === 'Page 1');
        expect(
          p1AfterUndo?.settings?.title,
          'Page 1 should not be affected by Page 2 undo'
        ).toBe('Page1 Title');
        expect(
          p1AfterUndo?.blocks?.[0]?.content?.text,
          'Page 1 blocks should not be affected by Page 2 undo'
        ).toBe('Page1 Block');
      }

      // Step 11: Delete pages down to test minimum 1 page constraint
      const deletePage4 = await request(`/api/projects/${projectId}/pages/Page%204`, { method: 'DELETE' });
      expect([200, 204]).toContain(deletePage4.res.status);

      const deletePage5 = await request(`/api/projects/${projectId}/pages/Page%205`, { method: 'DELETE' });
      expect([200, 204]).toContain(deletePage5.res.status);

      const deletePage3 = await request(`/api/projects/${projectId}/pages/Page%203`, { method: 'DELETE' });
      expect([200, 204]).toContain(deletePage3.res.status);

      const deletePage2Final = await request(`/api/projects/${projectId}/pages/Page%202`, { method: 'DELETE' });
      expect([200, 204]).toContain(deletePage2Final.res.status);

      // Attempting to delete the last remaining page should fail
      const deleteLastRemaining = await request(`/api/projects/${projectId}/pages/Page%201`, { method: 'DELETE' });
      expect([400, 422]).toContain(deleteLastRemaining.res.status);

      // Step 12: Re-add pages for export/import test
      const addPageForExport = await request(`/api/projects/${projectId}/pages`, {
        method: 'POST',
        body: JSON.stringify({
          name: 'Export Page',
          settings: { title: 'Export Title' },
          blocks: [{ type: 'text', content: { text: 'Export Block' } }],
        }),
      });
      expect([200, 201]).toContain(addPageForExport.res.status);

      // Step 13: Export project with multi-page data
      const exportProject = await request(`/api/projects/${projectId}/export`);
      expect(exportProject.res.status).toBe(200);
      const exportedPages = exportProject.body?.pages || exportProject.body?.project?.pages;
      expect(Array.isArray(exportedPages), 'export should contain pages array').toBe(true);
      expect(exportedPages.length).toBeGreaterThanOrEqual(2);

      // Step 14: Import the exported data as a new project
      const importProject = await request('/api/projects/import', {
        method: 'POST',
        body: JSON.stringify(exportProject.body),
      });
      expect([200, 201]).toContain(importProject.res.status);
      importedProjectId = importProject.body?.id;
      expect(importedProjectId).toBeTruthy();

      // Step 15: Verify imported project has all pages
      const importedData = await request(`/api/projects/${importedProjectId}`);
      expect(importedData.res.status).toBe(200);
      expect(Array.isArray(importedData.body?.pages)).toBe(true);
      expect(
        importedData.body.pages.length,
