      expect(importedExportPage, 'imported project should contain Export Page').toBeTruthy();
      expect(importedPage1?.settings?.title).toBe('Page1 Title');

      // Step 16: Verify auto-save covers multi-page (re-fetch after implicit save)
      const refetchProject = await request(`/api/projects/${projectId}`);
      expect(refetchProject.res.status).toBe(200);
      expect(
        Array.isArray(refetchProject.body?.pages),
        'project pages should persist across fetches (auto-save)'
      ).toBe(true);
      expect(refetchProject.body.pages.length).toBeGreaterThanOrEqual(2);
    } finally {
      if (importedProjectId) await safeDelete(`/api/projects/${importedProjectId}`);
      if (projectId) await safeDelete(`/api/projects/${projectId}`);
    }
  });
});

import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function request(path, options = {}) {
