describe('corrupted_archive_rejected_without_blocking', () => {
  /*
   * This test verifies that the editor application:
   * 1. Loads successfully (is not blocked/crashed)
   * 2. Contains logic to handle corrupted localStorage data
   * 3. If a state restoration API exists, it properly rejects corrupted data
   *
   * Note: Full localStorage corruption testing requires a browser environment
   * (Playwright/Puppeteer). These tests verify the server-side and static
   * asset aspects, plus any API-level state restoration endpoints.
   */

  it('should load the editor page successfully even when no archive exists', async () => {
    const res = await fetch(BASE_URL);
    expect(res.status).toBe(200);
    const html = await res.text();
    expect(html).toBeTruthy();
    // The page should contain the root element for the React app
    expect(html).toMatch(/<div\s+id=["']root["']/i);
    // The page should include script tags to load the application
    expect(html).toMatch(/<script/i);
  });

  it('should serve the application JS bundle that includes localStorage error handling', async () => {
    const res = await fetch(BASE_URL);
    expect(res.status).toBe(200);
    const html = await res.text();

    // Extract JS bundle URLs from the HTML
    const scriptMatches = html.match(/src=["']([^"']+\.js[^"']*)["']/g);
    expect(scriptMatches, 'expected at least one JS bundle in the page').toBeTruthy();
    expect(scriptMatches.length).toBeGreaterThan(0);

    // Load and inspect JS bundles for required error handling patterns
    let hasLocalStorageRef = false;
    let hasJSONParse = false;
    let hasErrorHandling = false;
    let hasClearOrReset = false;

    for (const match of scriptMatches) {
      const srcMatch = match.match(/src=["']([^"']+)["']/);
      if (!srcMatch) continue;
      const src = srcMatch[1];
      const jsUrl = src.startsWith('http') ? src : `${BASE_URL}${src.startsWith('/') ? '' : '/'}${src}`;

      try {
        const jsRes = await fetch(jsUrl);
        if (jsRes.status !== 200) continue;
        const jsContent = await jsRes.text();
        if (jsContent.length < 50) continue;

        if (jsContent.includes('localStorage') || jsContent.includes('localStore') || jsContent.includes('local_storage')) {
          hasLocalStorageRef = true;
        }
        if (jsContent.includes('JSON.parse')) {
          hasJSONParse = true;
        }
        if (jsContent.includes('catch') || jsContent.includes('.catch') || jsContent.includes('try{') || jsContent.includes('try {')) {
          hasErrorHandling = true;
        }
        // Check for clear/reset/remove patterns that indicate corruption recovery capability
        if (jsContent.includes('removeItem') || jsContent.includes('clear') || jsContent.includes('reset') || jsContent.includes('清空') || jsContent.includes('重新开始')) {
          hasClearOrReset = true;
        }
      } catch {
        continue;
      }
    }

    // The app must reference localStorage (for auto-save/restore)
    expect(hasLocalStorageRef, 'application code should reference localStorage for save/restore').toBe(true);
    // The app must use JSON.parse (to deserialize stored data)
    expect(hasJSONParse, 'application code should use JSON.parse for data deserialization').toBe(true);
    // The app must have error handling (try/catch around localStorage/parse operations)
    expect(hasErrorHandling, 'application code must contain error handling logic (try/catch)').toBe(true);
    // The app should have clear/reset capability for corrupted data recovery
    expect(hasClearOrReset, 'application code should have clear/reset capability for corruption recovery').toBe(true);
  });

  it('should not return error status codes on initial page load and all assets load correctly', async () => {
    const pageRes = await fetch(BASE_URL);
    expect(pageRes.status).toBeLessThan(400);

    const html = await pageRes.text();
    const assetUrls = [];
    const cssMatches = html.match(/href=["']([^"']+\.css[^"']*)["']/g) || [];
    const jsMatches = html.match(/src=["']([^"']+\.js[^"']*)["']/g) || [];

    for (const match of [...cssMatches, ...jsMatches].slice(0, 10)) {
      const urlMatch = match.match(/(?:href|src)=["']([^"']+)["']/);
      if (urlMatch) {
        const assetPath = urlMatch[1];
        const fullUrl = assetPath.startsWith('http') ? assetPath : `${BASE_URL}${assetPath.startsWith('/') ? '' : '/'}${assetPath}`;
        assetUrls.push(fullUrl);
      }
    }

    // All discovered assets must load without server errors
    for (const url of assetUrls) {
      const assetRes = await fetch(url);
      expect(assetRes.status, `expected asset ${url} to load without error`).toBeLessThan(400);
    }
  });

  it('should reject corrupted state data if a state restoration API endpoint exists', async () => {
    // Probe for state restoration endpoints that might accept localStorage-style data
    const stateEndpoints = [
      '/api/editor/state',
      '/api/editor/restore',
      '/api/state',
      '/api/projects/restore',
    ];

    let workingEndpoint = null;
    for (const ep of stateEndpoints) {
      const probe = await request(ep, { method: 'GET' });
      if (probe.res.status !== 404) {
        workingEndpoint = ep;
        break;
      }
      const probePost = await request(ep, {
        method: 'POST',
        body: JSON.stringify({ test: true }),
      });
      if (probePost.res.status !== 404) {
        workingEndpoint = ep;
        break;
      }
    }

    if (workingEndpoint) {
      // Test 1: Send completely invalid JSON-like garbage
      const corruptedResult = await request(workingEndpoint, {
        method: 'POST',
        body: '{this is not valid json at all!!!',
        headers: { 'Content-Type': 'application/json' },
      });
      expect(
        [400, 422].includes(corruptedResult.res.status),
        `corrupted data should be rejected at ${workingEndpoint}, got ${corruptedResult.res.status}`
      ).toBe(true);

      // Test 2: Send data with wrong structure
      const wrongStructure = await request(workingEndpoint, {
        method: 'POST',
        body: JSON.stringify({ corrupted: true, data: 'not a valid state' }),
      });
      expect(
        [400, 422].includes(wrongStructure.res.status),
        `wrong structure should be rejected at ${workingEndpoint}, got ${wrongStructure.res.status}`
      ).toBe(true);

      // Verify the endpoint provides an error message
      if (wrongStructure.body && typeof wrongStructure.body === 'object') {
        const hasMsg = wrongStructure.body.message || wrongStructure.body.error || wrongStructure.body.errors;
        expect(hasMsg, 'rejection should include clear error description').toBeTruthy();
      }
    }

    // Regardless of API endpoint availability, verify the app still loads
    const finalCheck = await fetch(BASE_URL);
    expect(finalCheck.status).toBe(200);
    const finalHtml = await finalCheck.text();
    expect(finalHtml).toMatch(/<div\s+id=["']root["']/i);
  });

  it('should handle import of corrupted/unparseable configuration file gracefully', async () => {
    // This tests the import API path with corrupted data, which is the API-accessible
    // equivalent of loading corrupted localStorage data
    const importEndpoints = [
      '/api/projects/import',
      '/api/import',
      '/api/editor/import',
    ];

    let workingImportEndpoint = null;
    for (const ep of importEndpoints) {
      const probe = await request(ep, {
        method: 'POST',
        body: JSON.stringify({ probe: true }),
      });
      if (probe.res.status !== 404) {
        workingImportEndpoint = ep;
        break;
      }
    }

    if (workingImportEndpoint) {
      // Corrupted data: looks like a config file but has mangled fields
      const corruptedConfig = await request(workingImportEndpoint, {
        method: 'POST',
        body: JSON.stringify({
          version: null,
          pages: null,
          blocks: 12345,
          settings: 'corrupted',
        }),
      });
      expect(
        [400, 422].includes(corruptedConfig.res.status),
        `corrupted config import should be rejected, got ${corruptedConfig.res.status}`
      ).toBe(true);

      // Verify error provides clear message about what's wrong
      if (corruptedConfig.body && typeof corruptedConfig.body === 'object') {
        const errorText = JSON.stringify(corruptedConfig.body).toLowerCase();
        const isDescriptive = errorText.includes('invalid') ||
          errorText.includes('corrupt') ||
          errorText.includes('format') ||
          errorText.includes('parse') ||
          errorText.includes('field') ||
          errorText.includes('required') ||
          errorText.includes('error');
        expect(
          isDescriptive,
          `error message should clearly describe what's wrong: ${errorText}`
        ).toBe(true);
      }
    }

    // Final verification: the editor app itself is still accessible and not blocked
    const appCheck = await fetch(BASE_URL);
    expect(appCheck.status).toBe(200);
  });
});

import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

/**
 * This is a pure frontend application with NO backend API (contract is []).
 * Legacy file import and migration is client-side logic.
 *
 * From vitest+fetch we verify:
 * 1. The app contains migration/compatibility logic for legacy files
 * 2. Default values are filled for missing breakpoint and style settings
 * 3. Unknown fields are safely ignored
 * 4. Re-export after legacy import produces versioned complete files
 * 5. Historical block content is stably preserved
 */

async function fetchAppHtml() {
  const res = await fetch(`${BASE_URL}`);
  const text = await res.text();
  return { res, text };
}

async function fetchAppBundle() {
  const { text: html } = await fetchAppHtml();
  const scriptMatches = html.match(/src="([^"]*\.js[^"]*)"/g) || [];
  let bundleContent = '';
  for (const match of scriptMatches) {
    const src = match.replace(/src="/, '').replace(/"$/, '');
    const url = src.startsWith('http') ? src : `${BASE_URL}${src.startsWith('/') ? '' : '/'}${src}`;
    try {
      const res = await fetch(url);
      if (res.ok) {
        bundleContent += await res.text();
      }
    } catch {
      // skip
    }
  }
  return bundleContent;
}

