import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function request(path, options = {}) {
  const res = await fetch(`${BASE_URL}${path}`, {
    headers: {
      'Content-Type': 'application/json',
      ...(options.headers || {}),
    },
    ...options,
  });

  let body = null;
  const text = await res.text();
  try {
    body = text ? JSON.parse(text) : null;
  } catch {
    body = text;
  }

  return { res, body };
}

async function safeDelete(path) {
  try {
    await fetch(`${BASE_URL}${path}`, { method: 'DELETE' });
  } catch {
    // ignore cleanup errors
  }
}

function uid(prefix = 'e2e') {
  return `${prefix}-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
}

/**
 * Try multiple candidate endpoints for a given action.
 * Returns the first successful result (matching acceptStatuses), or the last attempt.
 */
async function tryEndpoints(candidates, acceptStatuses = [200, 201]) {
  let lastResult = null;
  for (const { path, options } of candidates) {
    const result = await request(path, options);
    lastResult = result;
    if (acceptStatuses.includes(result.res.status)) {
      return { ...result, usedPath: path };
    }
  }
  return { ...lastResult, usedPath: candidates[candidates.length - 1]?.path };
}

describe('round10_template_save_apply', () => {
