import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

/**
 * This is a pure frontend application with no backend API (API contract is []).
 * Import/export operates on downloadable JSON config files on the client side.
 * We verify:
 * 1. The app is served and contains import/export related UI and logic
 * 2. Validation rules for import are present (reject missing fields, bad format, >20 blocks)
 * 3. Export includes version info (Round 12), page settings, blocks, breakpoints, styles
 * 4. Invalid imports don't destroy current state
 */

async function fetchAppHtml() {
  const res = await fetch(`${BASE_URL}`);
  const text = await res.text();
  return { res, text };
}

async function fetchAppBundle() {
  const { text: html } = await fetchAppHtml();
  const scriptMatches = html.match(/src="([^"]*\.js[^"]*)"/g) || [];
  let bundleContent = '';
  for (const match of scriptMatches) {
    const src = match.replace(/src="/, '').replace(/"$/, '');
    const url = src.startsWith('http') ? src : `${BASE_URL}${src.startsWith('/') ? '' : '/'}${src}`;
    try {
      const res = await fetch(url);
      if (res.ok) {
        bundleContent += await res.text();
      }
    } catch {
      // skip
    }
  }
  return bundleContent;
}

