import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function request(path, options = {}) {
  const res = await fetch(`${BASE_URL}${path}`, {
    headers: {
      'Content-Type': 'application/json',
      ...(options.headers || {}),
    },
    ...options,
  });
  const text = await res.text();
  let body;
  try {
    body = text ? JSON.parse(text) : null;
  } catch {
    body = text;
  }
  return { res, body };
}

async function safeDelete(path) {
  try {
    await fetch(`${BASE_URL}${path}`, { method: 'DELETE' });
  } catch {}
}

function uid(prefix = 'e2e') {
  return `${prefix}-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
}

function makeBlocks(count) {
  return Array.from({ length: count }, (_, i) => ({
    type: 'text',
    content: { text: `Block ${i + 1}` },
  }));
}

let projectsPath = '/api/projects';

async function probeProjectsPath() {
  const probe = await request('/api/projects', { method: 'GET' });
  if (probe.res.status === 404) {
    const alt = await request('/api/editor/projects', { method: 'GET' });
    if (alt.res.status !== 404) {
      projectsPath = '/api/editor/projects';
    }
  }
}

async function tryImport(projectId, payload) {
  const candidates = [
    `${projectsPath}/${projectId}/import`,
    '/api/projects/import',
    '/api/import',
  ];
  for (const path of candidates) {
    const result = await request(path, {
      method: 'POST',
      body: JSON.stringify(typeof payload === 'object' ? { ...payload, projectId } : payload),
    });
    if (result.res.status !== 404) return result;
  }
  return request(candidates[0], { method: 'POST', body: JSON.stringify(payload) });
}

async function tryPageUpdate(projectId, pageName, payload) {
  const candidates = [
    { path: `${projectsPath}/${projectId}/pages/${encodeURIComponent(pageName)}`, method: 'PUT' },
    { path: `${projectsPath}/${projectId}/pages/${encodeURIComponent(pageName)}`, method: 'PATCH' },
    { path: `${projectsPath}/${projectId}`, method: 'PUT' },
  ];
  for (const c of candidates) {
    const result = await request(c.path, {
      method: c.method,
      body: JSON.stringify(payload),
    });
    if (result.res.status !== 404) return result;
  }
  return request(candidates[0].path, { method: 'PUT', body: JSON.stringify(payload) });
}

