      projectId = created.body?.id || created.body?.projectId;
      expect(projectId).toBeTruthy();

      // Perform 60 sequential edits to exceed the 50-step undo limit
      for (let i = 0; i < 60; i++) {
        const editRes = await tryPageUpdate(projectId, 'Home', {
          name: 'Home',
          settings: { title: `Edit step ${i + 1}` },
          blocks: [{ type: 'text', content: { text: `Step ${i + 1}` } }],
