      }

      // Check undo history via history endpoint or undo attempts
      const historyEndpoints = [
        `${projectsPath}/${projectId}/pages/Home/history`,
        `${projectsPath}/${projectId}/history`,
      ];

      let historyChecked = false;
      for (const ep of historyEndpoints) {
        const historyList = await request(ep);
        if (historyList.res.status === 200 && Array.isArray(historyList.body)) {
          expect(
            historyList.body.length,
            `expected undo history capped at 50, got ${historyList.body.length}`
          ).toBeLessThanOrEqual(50);
          historyChecked = true;
          break;
        }
      }

      // Alternative: try undoing 51 times; at most 50 should succeed
      if (!historyChecked) {
        const undoEndpoints = [
          `${projectsPath}/${projectId}/pages/Home/undo`,
          `${projectsPath}/${projectId}/undo`,
        ];
        let undoPath = undoEndpoints[0];
        // Find a working undo endpoint
        for (const ep of undoEndpoints) {
          const probe = await request(ep, { method: 'POST' });
          if (probe.res.status !== 404) {
            undoPath = ep;
            break;
          }
        }

        let undoCount = 0;
        for (let i = 0; i < 55; i++) {
          const undoRes = await request(undoPath, { method: 'POST' });
          if ([200, 204].includes(undoRes.res.status)) {
            undoCount++;
          } else {
            break;
          }
        }
        // Should have been able to undo at most 50 times
        expect(
          undoCount,
          `expected at most 50 successful undos, got ${undoCount}`
        ).toBeLessThanOrEqual(50);
      }
