      // Get initial block order
      const initial = await request(`${projectsPath}/${projectId}`);
      expect(initial.res.status).toBe(200);
      const initialPage = initial.body?.pages?.[0] || initial.body?.page;
      const initialOrder = (initialPage?.blocks || []).map((b) => b.content?.text);
      expect(initialOrder.length).toBe(5);

      // Try to find and use preview endpoints
      const previewEndpoints = [
        `${projectsPath}/${projectId}/preview`,
        `${projectsPath}/${projectId}/pages/Home/preview`,
      ];

      let previewEndpointFound = false;
      for (const mode of ['mobile', 'tablet', 'desktop']) {
        for (const ep of previewEndpoints) {
          const preview = await request(ep, {
            method: 'POST',
            body: JSON.stringify({ mode, breakpoint: mode }),
          });
          if ([200, 204].includes(preview.res.status)) {
            previewEndpointFound = true;
            // If preview returns data, verify block order in the response
            const previewBlocks = preview.body?.blocks || preview.body?.pages?.[0]?.blocks;
            if (Array.isArray(previewBlocks)) {
              const previewOrder = previewBlocks.map((b) => b.content?.text);
              expect(
                previewOrder,
                `block order should not change in ${mode} preview`
              ).toEqual(initialOrder);
            }
            break;
          }
          // Also try GET with query param
          const previewGet = await request(`${ep}?mode=${mode}`);
          if ([200, 204].includes(previewGet.res.status)) {
            previewEndpointFound = true;
            const pgBlocks = previewGet.body?.blocks || previewGet.body?.pages?.[0]?.blocks;
            if (Array.isArray(pgBlocks)) {
              const pgOrder = pgBlocks.map((b) => b.content?.text);
              expect(pgOrder, `block order should not change in ${mode} preview (GET)`).toEqual(initialOrder);
            }
            break;
          }
        }
      }

      // Regardless of whether preview endpoint exists, verify block order is unchanged after all attempts
      const afterPreview = await request(`${projectsPath}/${projectId}`);
      expect(afterPreview.res.status).toBe(200);
      const afterPage = afterPreview.body?.pages?.[0] || afterPreview.body?.page;
      const afterOrder = (afterPage?.blocks || []).map((b) => b.content?.text);
      expect(
        afterOrder,
        'block order must remain unchanged after switching preview modes'
      ).toEqual(initialOrder);
    } finally {
      if (projectId) await safeDelete(`${projectsPath}/${projectId}`);
    }
  });

  it('should not add blocks to page when favoriting a component', async () => {
    let projectId;
    let componentIdentifier;
    let favCleanupPath;
    try {
      await probeProjectsPath();

      const created = await request(projectsPath, {
        method: 'POST',
        body: JSON.stringify({
          name: uid('baseline-fav'),
          pages: [
            {
              name: 'Home',
              settings: { title: 'Favorite Test' },
              blocks: makeBlocks(3),
            },
          ],
        }),
      });
      expect([200, 201].includes(created.res.status), `project creation failed: ${created.res.status}`).toBe(true);
      projectId = created.body?.id || created.body?.projectId;

      // Try to get component list from multiple candidate paths
      const componentPaths = ['/api/components', '/api/editor/components', '/api/blocks'];
      let allComponents;
      let componentsBasePath;
      for (const cp of componentPaths) {
        const probe = await request(cp);
        if (probe.res.status === 200) {
          const items = Array.isArray(probe.body) ? probe.body : (probe.body?.items || probe.body?.components || []);
          if (items.length > 0) {
            allComponents = items;
            componentsBasePath = cp;
            break;
          }
        }
      }

      // If no components endpoint found, we can still verify using a known component type
      if (!allComponents || allComponents.length === 0) {
        // Try favoriting with a known built-in type
        const knownTypes = ['text', 'heading', 'button', 'image'];
        for (const cType of knownTypes) {
          for (const bp of ['/api/components', '/api/editor/components']) {
            const favRes = await request(`${bp}/${cType}/favorite`, { method: 'POST' });
            if ([200, 201, 204].includes(favRes.res.status)) {
              componentIdentifier = cType;
              favCleanupPath = `${bp}/${cType}/favorite`;
              componentsBasePath = bp;
              break;
            }
          }
          if (componentIdentifier) break;
        }

        if (!componentIdentifier) {
          // Cannot test favoriting without working endpoint - but we should not silently skip
          // Instead verify the page content is still correct (baseline check)
          const verify = await request(`${projectsPath}/${projectId}`);
          expect(verify.res.status).toBe(200);
          const pg = verify.body?.pages?.[0] || verify.body?.page;
          expect((pg?.blocks || []).length).toBe(3);
          return;
        }
      } else {
        const component = allComponents[0];
        componentIdentifier = component.id || component.type;
        expect(componentIdentifier).toBeTruthy();
      }

      // Record block count before favorite
      const before = await request(`${projectsPath}/${projectId}`);
      expect(before.res.status).toBe(200);
      const beforePage = before.body?.pages?.[0] || before.body?.page;
      const blockCountBefore = (beforePage?.blocks || []).length;
      expect(blockCountBefore).toBe(3);

      // Favorite the component (if not already done above)
      if (!favCleanupPath && componentsBasePath) {
        const favRes = await request(`${componentsBasePath}/${componentIdentifier}/favorite`, {
          method: 'POST',
        });
        expect(
          [200, 201, 204].includes(favRes.res.status),
          `favoriting should succeed, got ${favRes.res.status}`
        ).toBe(true);
        favCleanupPath = `${componentsBasePath}/${componentIdentifier}/favorite`;
      }

      // Verify page blocks are unchanged - favoriting must not add blocks
      const after = await request(`${projectsPath}/${projectId}`);
      expect(after.res.status).toBe(200);
      const afterPage = after.body?.pages?.[0] || after.body?.page;
      const blockCountAfter = (afterPage?.blocks || []).length;
      expect(
        blockCountAfter,
        'favoriting should not add blocks to the page'
      ).toBe(blockCountBefore);

      // Also verify block content is identical
      const beforeBlockTexts = (beforePage?.blocks || []).map(b => b.content?.text);
      const afterBlockTexts = (afterPage?.blocks || []).map(b => b.content?.text);
      expect(afterBlockTexts, 'block content must be identical after favoriting').toEqual(beforeBlockTexts);
    } finally {
      // Cleanup favorite
      if (favCleanupPath) {
        await fetch(`${BASE_URL}${favCleanupPath}`, { method: 'DELETE' }).catch(() => {});
      }
      if (projectId) await safeDelete(`${projectsPath}/${projectId}`);
    }
  });
});

import { describe, it, expect, beforeAll, afterAll } from 'vitest';
import { chromium, Browser, Page } from 'playwright';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

let browser: Browser;

beforeAll(async () => {
  browser = await chromium.launch({ headless: true });
});

afterAll(async () => {
  if (browser) await browser.close();
});

async function createPage(): Promise<Page> {
  const context = await browser.newContext();
  const page = await context.newPage();
  return page;
}

async function waitForApp(page: Page) {
  await page.goto(BASE_URL, { waitUntil: 'networkidle' });
  await page.waitForTimeout(1500);
}

async function clearLocalStorage(page: Page) {
  await page.evaluate(() => localStorage.clear());
}

/**
 * Helper to find and click buttons/elements by text content
 */
async function clickByText(page: Page, texts: string[], tagSelector = 'button, [role="button"], a, [class*="btn"]') {
  const elements = await page.$$(tagSelector);
  for (const el of elements) {
    const elText = (await el.textContent() || '').toLowerCase().trim();
    for (const t of texts) {
      if (elText.includes(t.toLowerCase())) {
        try {
          await el.click();
          await page.waitForTimeout(500);
          return true;
        } catch { /* skip non-interactable */ }
      }
    }
  }
  return false;
}

