import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function request(path, options = {}) {
  const res = await fetch(`${BASE_URL}${path}`, {
    headers: {
      'Content-Type': 'application/json',
      ...(options.headers || {}),
    },
    ...options,
  });
  const text = await res.text();
  let body;
  try {
    body = text ? JSON.parse(text) : null;
  } catch {
    body = text;
  }
  return { res, body };
}

async function safeDelete(path) {
  try {
    await fetch(`${BASE_URL}${path}`, { method: 'DELETE' });
  } catch {}
}

function uid(prefix = 'e2e') {
  return `${prefix}-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
}

let projectsPath = '/api/projects';
let templatesPath = '/api/templates';

async function probePaths() {
  const pProbe = await request('/api/projects', { method: 'GET' });
  if (pProbe.res.status === 404) {
    const alt = await request('/api/editor/projects', { method: 'GET' });
    if (alt.res.status !== 404) projectsPath = '/api/editor/projects';
  }
  const tProbe = await request('/api/templates', { method: 'GET' });
  if (tProbe.res.status === 404) {
    const alt = await request('/api/editor/templates', { method: 'GET' });
    if (alt.res.status !== 404) templatesPath = '/api/editor/templates';
  }
}

async function saveTemplate(projectId, name, pageData) {
  // Try project-scoped endpoint first
  let result = await request(`${projectsPath}/${projectId}/templates`, {
    method: 'POST',
    body: JSON.stringify({ name }),
  });
  if (result.res.status === 404) {
    // Fallback: save to global templates endpoint with full page data
    result = await request(templatesPath, {
      method: 'POST',
      body: JSON.stringify({
        name,
        projectId,
        page: pageData,
      }),
    });
  }
  return result;
}

async function applyTemplate(projectId, templateId) {
  let result = await request(`${projectsPath}/${projectId}/templates/${templateId}/apply`, {
    method: 'POST',
  });
  if (result.res.status === 404) {
    result = await request(`${templatesPath}/${templateId}/apply`, {
      method: 'POST',
      body: JSON.stringify({ projectId }),
    });
  }
  return result;
}

async function getTemplateList() {
  const resp = await request(templatesPath);
  if (resp.res.status !== 200) return [];
  return Array.isArray(resp.body) ? resp.body : (resp.body?.templates || resp.body?.items || []);
}

describe('template_saved_and_reusable_in_session', () => {
  it('should save a template from current page, list it, apply it to restore content, and survive rule adjustments', async () => {
    let projectId;
    let templateId;
    let secondTemplateId;

    try {
      await probePaths();

      // Step 1: Create a project with meaningful content
      const projectName = uid('tpl-session');
      const pageData = {
        name: 'Main',
        settings: { title: 'Template Source Page' },
        blocks: [
          { type: 'text', content: { text: 'Block Alpha' } },
          { type: 'heading', content: { title: 'Hero Section' } },
          { type: 'text', content: { text: 'Block Beta' } },
        ],
        breakpoints: { mobile: 375, tablet: 768, desktop: 1200 },
        styles: { color: '#112233' },
      };
      const created = await request(projectsPath, {
        method: 'POST',
        body: JSON.stringify({
          name: projectName,
          pages: [pageData],
        }),
      });
      expect([200, 201].includes(created.res.status), `project creation failed: ${created.res.status}`).toBe(true);
      projectId = created.body?.id || created.body?.projectId;
      expect(projectId).toBeTruthy();

      // Step 2: Save current page as a template
      const templateName = uid('session-tpl').slice(0, 25);
      const saveTpl = await saveTemplate(projectId, templateName, pageData);
      expect([200, 201].includes(saveTpl.res.status), `template save failed: ${saveTpl.res.status}`).toBe(true);
      templateId = saveTpl.body?.id || saveTpl.body?.templateId;
      expect(templateId).toBeTruthy();

      // Step 3: Verify template appears in list with correct name
      const templates = await getTemplateList();
      const foundTpl = templates.find((t) => (t.id || t.templateId) === templateId);
      expect(foundTpl, 'saved template should appear in list').toBeTruthy();
      expect(foundTpl.name).toBe(templateName);

      // Step 3b: Verify simplified display (Round 12) - no createdAt
      expect('createdAt' in foundTpl, 'template should not expose createdAt per Round 12 simplification').toBe(false);
      expect('created_at' in foundTpl, 'template should not expose created_at per Round 12 simplification').toBe(false);

      // Step 4: Modify the project page to something different
      const updateCandidates = [
        { path: `${projectsPath}/${projectId}/pages/Main`, method: 'PUT' },
        { path: `${projectsPath}/${projectId}/pages/Main`, method: 'PATCH' },
        { path: `${projectsPath}/${projectId}`, method: 'PUT' },
      ];
      let updateRes;
      for (const c of updateCandidates) {
        updateRes = await request(c.path, {
          method: c.method,
          body: JSON.stringify({
            name: 'Main',
            settings: { title: 'Modified After Template Save' },
            blocks: [
              { type: 'text', content: { text: 'Completely Different' } },
            ],
            breakpoints: { mobile: 375, tablet: 768, desktop: 1200 },
            styles: { color: '#ffffff' },
            pages: [{
              name: 'Main',
              settings: { title: 'Modified After Template Save' },
              blocks: [{ type: 'text', content: { text: 'Completely Different' } }],
              breakpoints: { mobile: 375, tablet: 768, desktop: 1200 },
              styles: { color: '#ffffff' },
            }],
          }),
        });
        if ([200, 201, 204].includes(updateRes.res.status)) break;
      }
      expect(
        [200, 201, 204].includes(updateRes.res.status),
        `page update failed: ${updateRes.res.status}`
      ).toBe(true);

      // Confirm modification took effect
      const afterModify = await request(`${projectsPath}/${projectId}`);
      expect(afterModify.res.status).toBe(200);
      const modPage = afterModify.body?.pages?.[0] || afterModify.body?.page;
      expect(modPage?.settings?.title).toBe('Modified After Template Save');

      // Step 5: Apply the saved template to restore original content
      const applyTpl = await applyTemplate(projectId, templateId);
      expect(
        [200, 201].includes(applyTpl.res.status),
        `apply template failed: ${applyTpl.res.status}`
      ).toBe(true);

      // Step 6: Verify content is fully restored from template
      const restored = await request(`${projectsPath}/${projectId}`);
      expect(restored.res.status).toBe(200);
      const restoredPage = restored.body?.pages?.[0] || restored.body?.page;
      expect(restoredPage).toBeTruthy();

      expect(
        restoredPage.settings?.title,
        'title should be restored from template'
      ).toBe('Template Source Page');

      expect(
        restoredPage.blocks?.length,
        'block count should match template (3 blocks)'
      ).toBe(3);

      expect(restoredPage.blocks?.[0]?.content?.text).toBe('Block Alpha');
      expect(restoredPage.blocks?.[2]?.content?.text).toBe('Block Beta');

      // Verify breakpoints and styles restored (no conditional skip)
      expect(restoredPage.breakpoints, 'breakpoints must be restored from template').toBeTruthy();
      expect(restoredPage.breakpoints.mobile).toBe(375);

