      }
    } finally {
      if (secondTemplateId) await safeDelete(`${templatesPath}/${secondTemplateId}`);
      if (templateId) await safeDelete(`${templatesPath}/${templateId}`);
      if (projectId) await safeDelete(`${projectsPath}/${projectId}`);
    }
  });
});

import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

/**
 * This is a pure frontend application (React) with no backend API.
 * Templates are stored in localStorage. We cannot directly test localStorage
 * from a vitest+fetch context, so we verify:
 * 1. The app is served and contains template-related UI elements
 * 2. The validation rules are structurally present in the served app bundle
 * 3. We document the expected behavior for each validation scenario
 *
 * For thorough testing, these should be complemented with component-level
 * unit tests (testing validation functions directly) or E2E browser tests.
 */

async function fetchAppHtml() {
  const res = await fetch(`${BASE_URL}`);
  const text = await res.text();
  return { res, text };
}

async function fetchAppBundle() {
  const { text: html } = await fetchAppHtml();
  // Extract script src from HTML
  const scriptMatches = html.match(/src="([^"]*\.js[^"]*)"/g) || [];
  let bundleContent = '';
  for (const match of scriptMatches) {
    const src = match.replace(/src="/, '').replace(/"$/, '');
    const url = src.startsWith('http') ? src : `${BASE_URL}${src.startsWith('/') ? '' : '/'}${src}`;
    try {
      const res = await fetch(url);
      if (res.ok) {
        bundleContent += await res.text();
      }
    } catch {
      // skip unreachable scripts
    }
  }
  return bundleContent;
}

