import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function request(path, options = {}) {
  const res = await fetch(`${BASE_URL}${path}`, {
    headers: {
      'Content-Type': 'application/json',
      ...(options.headers || {}),
    },
    ...options,
  });
  const text = await res.text();
  let body;
  try {
    body = text ? JSON.parse(text) : null;
  } catch {
    body = text;
  }
  return { res, body };
}

async function safeDelete(path) {
  try {
    await fetch(`${BASE_URL}${path}`, { method: 'DELETE' });
  } catch {}
}

function uid(prefix = 'e2e') {
  return `${prefix}-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
}

// Discover working API endpoints by probing common patterns
async function discoverEndpoint(candidates) {
  for (const c of candidates) {
    try {
      const res = await fetch(`${BASE_URL}${c.path}`, {
        method: c.method || 'GET',
        headers: { 'Content-Type': 'application/json' },
        ...(c.body ? { body: JSON.stringify(c.body) } : {}),
      });
      if (res.status < 500 && res.status !== 404) {
        return c.path;
      }
    } catch {}
  }
  return candidates[0]?.path || '/api/unknown';
}

describe('round12_template_revision_and_export_version', () => {
