    let legacyTemplateId;
    let resaveTemplateId;
    let projectsPath = '/api/projects';
    let templatesPath = '/api/templates';

    try {
      // Probe for working project endpoint
      const projectProbe = await request('/api/projects', { method: 'GET' });
      if (projectProbe.res.status === 404) {
        const altProbe = await request('/api/editor/projects', { method: 'GET' });
        if (altProbe.res.status !== 404) projectsPath = '/api/editor/projects';
      }

      const templateProbe = await request('/api/templates', { method: 'GET' });
      if (templateProbe.res.status === 404) {
        const altProbe = await request('/api/editor/templates', { method: 'GET' });
        if (altProbe.res.status !== 404) templatesPath = '/api/editor/templates';
      }

      // Step 1: Create a project with one page
      const created = await request(projectsPath, {
        method: 'POST',
        body: JSON.stringify({
          name: uid('project'),
          pages: [
            {
              name: 'Home',
              settings: { title: 'Current Title' },
              blocks: [{ type: 'text', content: { text: 'Current Text' } }],
              breakpoints: { mobile: 375, tablet: 768, desktop: 1200 },
              styles: { color: '#222222' },
            },
          ],
        }),
      });
      expect([200, 201].includes(created.res.status), `project creation failed: ${created.res.status}`).toBe(true);
      projectId = created.body?.id || created.body?.projectId;
      expect(projectId).toBeTruthy();

      // Step 2: Create a legacy-style template (simulating old template data)
      const legacyName = uid('legacy').slice(0, 20);
      const legacyCreate = await request(templatesPath, {
        method: 'POST',
        body: JSON.stringify({
          name: legacyName,
          legacy: true,
          page: {
            settings: { title: 'Legacy Title' },
            blocks: [{ type: 'text', content: { text: 'Legacy Text' } }],
            breakpoints: { mobile: 320, tablet: 768, desktop: 1024 },
            styles: { color: '#999999' },
          },
        }),
      });
      expect([200, 201].includes(legacyCreate.res.status), `legacy template creation failed: ${legacyCreate.res.status}`).toBe(true);
      legacyTemplateId = legacyCreate.body?.id || legacyCreate.body?.templateId;
      expect(legacyTemplateId).toBeTruthy();

      // Step 3: Save current project page as a new template
      const tplName = uid('tpl').slice(0, 20);
      // Try project-scoped template save first, then fallback
      let saveCurrentAsTemplate = await request(`${projectsPath}/${projectId}/templates`, {
        method: 'POST',
        body: JSON.stringify({ name: tplName }),
      });
      if (saveCurrentAsTemplate.res.status === 404) {
        saveCurrentAsTemplate = await request(templatesPath, {
          method: 'POST',
          body: JSON.stringify({
            name: tplName,
            projectId,
            page: {
              settings: { title: 'Current Title' },
              blocks: [{ type: 'text', content: { text: 'Current Text' } }],
              breakpoints: { mobile: 375, tablet: 768, desktop: 1200 },
              styles: { color: '#222222' },
            },
          }),
        });
      }
      expect([200, 201].includes(saveCurrentAsTemplate.res.status), `template save failed: ${saveCurrentAsTemplate.res.status}`).toBe(true);
      templateId = saveCurrentAsTemplate.body?.id || saveCurrentAsTemplate.body?.templateId;
      expect(templateId).toBeTruthy();

      // Step 4: List templates and verify simplified format
      const listTemplates = await request(templatesPath);
      expect(listTemplates.res.status).toBe(200);
      const templateList = Array.isArray(listTemplates.body) ? listTemplates.body : (listTemplates.body?.templates || listTemplates.body?.items || []);
      expect(Array.isArray(templateList)).toBe(true);

      const currentTpl = templateList.find((t) => (t.id || t.templateId) === templateId);
      const legacyTpl = templateList.find((t) => (t.id || t.templateId) === legacyTemplateId);
      expect(currentTpl, 'expected current template in list').toBeTruthy();
      expect(legacyTpl, 'expected legacy template in list - old templates must not be lost').toBeTruthy();

      // Verify simplified display: name present, no createdAt (Round 12: no longer show creation time)
