      expect(legacyTpl.name).toBeTruthy();
      expect('createdAt' in currentTpl, 'simplified template should not expose createdAt').toBe(false);
      expect('created_at' in currentTpl, 'simplified template should not expose created_at').toBe(false);
      expect('createdAt' in legacyTpl, 'simplified legacy template should not expose createdAt').toBe(false);
      expect('created_at' in legacyTpl, 'simplified legacy template should not expose created_at').toBe(false);

      // Positive assertion on simplified fields: name must be present, blockCount is expected
      expect(typeof currentTpl.name).toBe('string');
      expect(typeof legacyTpl.name).toBe('string');
      // Templates as quick start points should show block count
      const blockCountField = 'blockCount' in currentTpl ? 'blockCount' : ('blocksCount' in currentTpl ? 'blocksCount' : null);
      if (blockCountField) {
