      // Version must be meaningful (non-empty string or positive number)
      if (versionType === 'string') {
        expect(version.trim().length > 0, 'version string must not be empty').toBe(true);
      } else if (versionType === 'number') {
        expect(version > 0, 'version number must be positive').toBe(true);
