      expect(
        page.blocks?.[0]?.content?.text,
        `expected legacy template text 'Legacy Text', got '${page.blocks?.[0]?.content?.text}'`
      ).toBe('Legacy Text');

      // Verify breakpoints from legacy template are restored (no conditional skip)
