      expect(page.breakpoints.mobile, 'legacy breakpoints mobile should be 320').toBe(320);
      expect(page.breakpoints.desktop, 'legacy breakpoints desktop should be 1024').toBe(1024);

      // Verify styles from legacy template are restored (no conditional skip)
      expect(page.styles, 'legacy template styles must be restored').toBeTruthy();
      expect(page.styles.color, 'legacy styles color should be #999999').toBe('#999999');

      // Step 7: Re-save as template to confirm save/apply path still works
      const resaveName = uid('resave').slice(0, 20);
      let resaveLegacy = await request(`${projectsPath}/${projectId}/templates`, {
        method: 'POST',
        body: JSON.stringify({ name: resaveName }),
      });
      if (resaveLegacy.res.status === 404) {
        resaveLegacy = await request(templatesPath, {
          method: 'POST',
          body: JSON.stringify({
            name: resaveName,
            projectId,
            page,
          }),
        });
      }
      expect([200, 201].includes(resaveLegacy.res.status), `resave template failed: ${resaveLegacy.res.status}`).toBe(true);
      resaveTemplateId = resaveLegacy.body?.id || resaveLegacy.body?.templateId;
      expect(resaveTemplateId).toBeTruthy();

      // Verify the resaved template appears in list
