      const afterResaveList = Array.isArray(listAfterResave.body) ? listAfterResave.body : (listAfterResave.body?.templates || listAfterResave.body?.items || []);
      const resavedTpl = afterResaveList.find((t) => (t.id || t.templateId) === resaveTemplateId);
