    const contact = project.pages.find((p) => p.id === 'contact');

    expect(home.settings.title, `expected Home page unchanged, got ${home.settings?.title}`).toBe('Home Original');
    expect(home.blocks[0].id, `expected Home block home-hero, got ${home.blocks[0]?.id}`).toBe('home-hero');

    expect(about.settings.title, `expected About page replaced title About Replaced, got ${about.settings?.title}`).toBe('About Replaced');
