describe('round16_component_favorites_persist', () => {
  it('should mark and unmark favorites, apply favorite search filtering, and keep favorite state after reload', async () => {
    const listResp = await request('GET', '/api/components');
    expect(listResp.res.status, `expected components list status 200, got ${listResp.res.status}`).toBe(200);
    expect(Array.isArray(listResp.data), 'expected components list array').toBe(true);
    expect(listResp.data.length >= 2, `expected at least 2 components, got ${listResp.data.length}`).toBe(true);

    const hero = listResp.data.find((c) => /hero/i.test(c.name || c.id || '')) || listResp.data[0];
    const feature = listResp.data.find((c) => c.id !== hero.id) || listResp.data[1];
    expect(hero?.id, 'expected hero-like component id').toBeTruthy();
    expect(feature?.id, 'expected second component id').toBeTruthy();

    const favOnResp = await request('POST', `/api/components/${hero.id}/favorite`, { favorite: true });
    expect([200, 201]).toContain(favOnResp.res.status);
    expect(favOnResp.data).toBeTruthy();
    const favOnData = favOnResp.data.component ?? favOnResp.data.data ?? favOnResp.data;
    expect(favOnData.id, `expected favorite response for ${hero.id}, got ${favOnData.id}`).toBe(hero.id);
    expect(favOnData.favorite === true || favOnData.isFavorite === true, `expected component ${hero.id} to be favorite`).toBe(true);

    const favoritesResp = await request('GET', '/api/components?favorites=true');
    expect(favoritesResp.res.status, `expected favorites query status 200, got ${favoritesResp.res.status}`).toBe(200);
    expect(Array.isArray(favoritesResp.data), 'expected favorites list array').toBe(true);
    expect(favoritesResp.data.some((c) => c.id === hero.id), `expected favorites list to include ${hero.id}`).toBe(true);

    const searchTerm = (hero.name || hero.id).slice(0, 4);
    const favoritesSearchResp = await request('GET', `/api/components?favorites=true&search=${encodeURIComponent(searchTerm)}`);
    expect(favoritesSearchResp.res.status).toBe(200);
    expect(Array.isArray(favoritesSearchResp.data), 'expected favorites search result array').toBe(true);
    expect(favoritesSearchResp.data.every((c) => c.id === hero.id || (c.name || '').toLowerCase().includes(searchTerm.toLowerCase())), 'expected favorites search results filtered by term').toBe(true);
    expect(favoritesSearchResp.data.some((c) => c.id === hero.id), `expected filtered favorites to include ${hero.id}`).toBe(true);

    const hideBySearchResp = await request('GET', '/api/components?favorites=true&search=zzzz-no-match');
    expect(hideBySearchResp.res.status).toBe(200);
    expect(Array.isArray(hideBySearchResp.data)).toBe(true);
    expect(hideBySearchResp.data.some((c) => c.id === hero.id), `expected no-match favorites search to exclude ${hero.id}`).toBe(false);

    const favOffResp = await request('POST', `/api/components/${hero.id}/favorite`, { favorite: false });
    expect([200, 201]).toContain(favOffResp.res.status);
    const favOffData = favOffResp.data.component ?? favOffResp.data.data ?? favOffResp.data;
    expect(favOffData.favorite === false || favOffData.isFavorite === false, `expected component ${hero.id} favorite state false after unfavorite`).toBe(true);

    const favoritesAfterOffResp = await request('GET', '/api/components?favorites=true');
    expect(favoritesAfterOffResp.res.status).toBe(200);
    expect(Array.isArray(favoritesAfterOffResp.data)).toBe(true);
    expect(favoritesAfterOffResp.data.some((c) => c.id === hero.id), `expected ${hero.id} to disappear from favorites immediately`).toBe(false);

    const markFeatureResp = await request('POST', `/api/components/${feature.id}/favorite`, { favorite: true });
    expect([200, 201]).toContain(markFeatureResp.res.status);

    const reloadResp = await request('GET', '/api/components');
    expect(reloadResp.res.status).toBe(200);
    expect(Array.isArray(reloadResp.data)).toBe(true);
