}

async function deleteProject(id) {
  if (!id) return;
  try {
    await fetch(`${BASE_URL}/api/projects/${id}`, { method: 'DELETE' });
  } catch {}
}

async function getProject(id) {
  const resp = await request('GET', `/api/projects/${id}`);
  expect(resp.res.status).toBe(200);
  return resp.data;
}

