import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function request(path, options = {}) {
  const res = await fetch(`${BASE_URL}${path}`, {
    headers: { 'Content-Type': 'application/json', ...(options.headers || {}) },
    ...options,
  });
  const text = await res.text();
  let body;
  try {
    body = text ? JSON.parse(text) : null;
  } catch {
    body = text;
  }
  return { status: res.status, body };
}

async function tryCleanup(path) {
  try {
    await fetch(`${BASE_URL}${path}`, { method: 'DELETE' });
  } catch {}
}

async function tryRequest(paths, options) {
  let lastResp;
  for (const path of paths) {
    lastResp = await request(path, options);
    if ([200, 201, 204].includes(lastResp.status)) return lastResp;
  }
  return lastResp;
}

function extractBattleState(body) {
  if (!body) return null;
  return body.data || body.state || body.battle || body;
}

function extractBattleLog(state) {
  if (!state) return [];
  return state.log || state.battleLog || state.events || state.history || state.report || [];
}

function getAIField(state) {
  return state?.aiField || state?.opponentField || state?.ai?.battlefield || state?.opponent?.battlefield || [];
}

function getAIHandCount(state) {
  const aiHand = state?.aiHand || state?.opponentHand || state?.ai?.hand || state?.opponent?.hand;
  if (typeof aiHand === 'number') return aiHand;
  if (Array.isArray(aiHand)) return aiHand.length;
  return null;
}

function getDifficulty(state) {
  return state?.difficulty || state?.aiDifficulty || state?.config?.difficulty || state?.settings?.difficulty || null;
}

function getAIPlayedCards(log) {
  // Extract AI play events from log
  return log.filter(entry => {
    if (typeof entry === 'string') {
      return entry.toLowerCase().includes('ai') && (entry.toLowerCase().includes('play') || entry.toLowerCase().includes('出牌'));
    }
    const actor = entry?.actor || entry?.player || entry?.source || '';
    const action = entry?.type || entry?.action || entry?.event || '';
    return (
      (typeof actor === 'string' && actor.toLowerCase().includes('ai') || actor.toLowerCase().includes('opponent')) &&
      (typeof action === 'string' && (action.toLowerCase().includes('play') || action.toLowerCase().includes('skip') || action.toLowerCase().includes('pass')))
    );
  }).map(entry => {
    if (typeof entry === 'string') return entry;
    return {
      action: entry?.type || entry?.action || entry?.event,
      card: entry?.card || entry?.cardId || entry?.cardName,
      cost: entry?.cost || entry?.manaCost,
      details: entry,
    };
  });
}

describe('ai_difficulty_changes_early_turn_behavior', () => {
  it('should produce distinguishable AI behavior across easy/normal/hard in the first 2 AI turns, include difficulty label, and handle no-legal-play gracefully', async () => {
    const difficulties = ['easy', 'normal', 'hard'];
    const battleIds = [];
    const aiResults = {};

    try {
      // First, try to ensure we have a valid deck. Try listing decks or using default.
      let deckId = 'default';
      const decksResp = await request('/api/decks', { method: 'GET' });
      if (decksResp.status === 200) {
        const decks = Array.isArray(decksResp.body) ? decksResp.body :
          (decksResp.body?.items || decksResp.body?.data || []);
        if (decks.length > 0) {
          deckId = decks[0].id || decks[0].deckId || 'default';
        }
      }

      for (const diff of difficulties) {
        // Start a battle for each difficulty
        const startResp = await tryRequest(
          ['/api/battles', '/api/battle/start', '/api/games'],
          {
            method: 'POST',
            body: JSON.stringify({ difficulty: diff, deckId }),
          }
        );
        expect([200, 201]).toContain(startResp.status);

        const battleData = extractBattleState(startResp.body);
        const battleId = battleData?.id || battleData?.battleId || battleData?.gameId || startResp.body?.id;
        expect(battleId, `Expected battle ID for difficulty=${diff}`).toBeTruthy();
        battleIds.push(battleId);

        // Verify difficulty label is present in battle state
        const initStateResp = await tryRequest(
          [`/api/battles/${battleId}`, `/api/battles/${battleId}/state`],
          { method: 'GET' }
        );
        expect(initStateResp.status).toBe(200);
        const initState = extractBattleState(initStateResp.body);
        const reportedDifficulty = getDifficulty(initState);
        expect(
          reportedDifficulty,
          `Battle state should include difficulty label for ${diff}, got state keys: ${Object.keys(initState || {})}`
        ).toBeTruthy();
        expect(reportedDifficulty).toBe(diff);

        const turnSnapshots = [];

        // Run 2 full rounds (player end turn → AI acts → repeat)
        for (let round = 0; round < 2; round++) {
          // Player ends turn (skips playing to keep things deterministic)
          const endResp = await tryRequest(
            [`/api/battles/${battleId}/end-turn`, `/api/battles/${battleId}/actions/end-turn`],
            { method: 'POST' }
          );
          expect(
            [200, 204].includes(endResp.status),
            `End turn failed for difficulty=${diff}, round=${round}, status=${endResp.status}`
          ).toBe(true);

          // Wait briefly for AI turn to process
          await new Promise(r => setTimeout(r, 500));

          // Get state after AI has acted
          const stateResp = await tryRequest(
            [`/api/battles/${battleId}`, `/api/battles/${battleId}/state`],
            { method: 'GET' }
          );
          expect(stateResp.status).toBe(200);

          const state = extractBattleState(stateResp.body);
          const log = extractBattleLog(state);
          const aiField = getAIField(state);
          const aiHandCount = getAIHandCount(state);
          const aiPlayedCards = getAIPlayedCards(log);

          turnSnapshots.push({
            round: round + 1,
            aiFieldCount: Array.isArray(aiField) ? aiField.length : 0,
            aiHandCount,
            logLength: log.length,
            aiPlayedCards,
            aiFieldCards: Array.isArray(aiField) ? aiField.map(c => {
              if (typeof c === 'string') return c;
              return c?.name || c?.cardName || c?.id || c?.cardId || JSON.stringify(c);
            }) : [],
            logEntries: log.slice(-10).map(e => {
              if (typeof e === 'string') return e;
              return {
                type: e?.type || e?.action || e?.event,
                card: e?.card || e?.cardId || e?.cardName,
                actor: e?.actor || e?.player || e?.source,
              };
            }),
          });
        }

        aiResults[diff] = turnSnapshots;
      }

      // Verify that AI behaviors are distinguishable across difficulties
      // Compare each pair and look for concrete behavioral differences
      const diffPairs = [['easy', 'normal'], ['normal', 'hard'], ['easy', 'hard']];
      let differenceCount = 0;
      const differenceDetails = [];

      for (const [d1, d2] of diffPairs) {
        const r1 = aiResults[d1];
        const r2 = aiResults[d2];
        if (!r1 || !r2) continue;

        for (let i = 0; i < Math.min(r1.length, r2.length); i++) {
          const snap1 = r1[i];
          const snap2 = r2[i];

          // Check concrete differences: field card contents, played cards, field counts
          const fieldCardsDiff = JSON.stringify(snap1.aiFieldCards) !== JSON.stringify(snap2.aiFieldCards);
          const playedCardsDiff = JSON.stringify(snap1.aiPlayedCards) !== JSON.stringify(snap2.aiPlayedCards);
          const fieldCountDiff = snap1.aiFieldCount !== snap2.aiFieldCount;
          const handCountDiff = snap1.aiHandCount !== null && snap2.aiHandCount !== null && snap1.aiHandCount !== snap2.aiHandCount;

          if (fieldCardsDiff || playedCardsDiff || fieldCountDiff || handCountDiff) {
            differenceCount++;
            differenceDetails.push({
              pair: `${d1} vs ${d2}`,
              round: i + 1,
              fieldCardsDiff,
              playedCardsDiff,
              fieldCountDiff,
              handCountDiff,
            });
          }
        }
      }

      expect(
        differenceCount,
        `AI behavior across easy/normal/hard should be distinguishable in the first 2 AI turns by played cards or field state. Results: ${JSON.stringify(aiResults, null, 2)}`
      ).toBeGreaterThan(0);

      // Verify each difficulty produced valid snapshots with log entries containing expected event types
      for (const diff of difficulties) {
        const snapshots = aiResults[diff];
        expect(snapshots).toBeTruthy();
        expect(snapshots.length).toBe(2);

        // Check that log contains AI-related events (play or skip/pass)
        const allLogEntries = snapshots.flatMap(s => s.logEntries);
        const hasAIEvents = allLogEntries.some(entry => {
          const entryStr = JSON.stringify(entry).toLowerCase();
          return entryStr.includes('ai') || entryStr.includes('opponent');
        });
        expect(
          hasAIEvents,
          `Expected AI-related log entries for difficulty=${diff}, got: ${JSON.stringify(allLogEntries)}`
        ).toBe(true);
      }

      // Verify AI handles no-legal-play gracefully
      // We check if any log entries contain skip/pass type events
      // If AI couldn't play, it should have recorded a skip event and not caused errors
      for (const diff of difficulties) {
        const snapshots = aiResults[diff];
        for (const snap of snapshots) {
          // If AI field count didn't increase, it means AI didn't play — check for skip/pass in log
          if (snap.aiPlayedCards.length === 0 && snap.aiFieldCount === 0) {
            const hasSkipEvent = snap.logEntries.some(entry => {
              const entryStr = JSON.stringify(entry).toLowerCase();
              return entryStr.includes('skip') || entryStr.includes('pass') || entryStr.includes('跳过') || entryStr.includes('结束');
            });
            expect(
              hasSkipEvent || snap.logLength > 0,
              `AI should record skip/pass event when no legal play available for difficulty=${diff}, round=${snap.round}`
            ).toBe(true);
          }
        }
      }

    } finally {
      // Cleanup all battles
      await Promise.all(battleIds.map(id => tryCleanup(`/api/battles/${id}`)));
    }
  });
});

import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function fetchPage(path = '/') {
  const res = await fetch(`${BASE_URL}${path}`);
  const html = await res.text();
  return { res, html };
}

async function fetchAllJs() {
  const { html } = await fetchPage('/');
  const scriptMatches = html.match(/src="([^"]*\.js[^"]*)"/g) || [];
  let allJs = '';
  for (const match of scriptMatches) {
    const srcMatch = match.match(/src="([^"]+)"/);
    if (!srcMatch) continue;
    let src = srcMatch[1];
    if (src.startsWith('/')) src = `${BASE_URL}${src}`;
    else if (!src.startsWith('http')) src = `${BASE_URL}/${src}`;
    try {
      const jsRes = await fetch(src);
      if (jsRes.ok) allJs += await jsRes.text();
    } catch {}
  }
  return allJs;
}

