import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function api(path, init = {}) {
  const res = await fetch(`${BASE_URL}${path}`, {
    headers: {
      'Content-Type': 'application/json',
      ...(init.headers || {}),
    },
    ...init,
  });
  const text = await res.text();
  let body = null;
  try {
    body = text ? JSON.parse(text) : null;
  } catch {
    body = text;
  }
  return { res, body };
}

async function apiRaw(path, init = {}) {
  const res = await fetch(`${BASE_URL}${path}`, init);
  const text = await res.text();
  let body = null;
  try {
    body = text ? JSON.parse(text) : null;
  } catch {
    body = text;
  }
  return { res, body };
}

function findField(obj, ...candidates) {
  if (!obj || typeof obj !== 'object') return undefined;
  for (const c of candidates) {
    if (obj[c] !== undefined) return obj[c];
  }
  return undefined;
}

async function tryPaths(paths, init = {}) {
  let result;
  for (const p of paths) {
    result = await api(p, init);
    if (result.res.status !== 404) return result;
  }
  return result;
}

async function tryPathsRaw(paths, init = {}) {
  let result;
  for (const p of paths) {
    result = await apiRaw(p, init);
    if (result.res.status !== 404) return result;
  }
  return result;
}

