import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function request(path, options = {}) {
  const res = await fetch(`${BASE_URL}${path}`, {
    headers: { 'Content-Type': 'application/json', ...(options.headers || {}) },
    ...options,
  });
  const text = await res.text();
  let body;
  try {
    body = text ? JSON.parse(text) : null;
  } catch {
    body = text;
  }
  return { status: res.status, body };
}

async function tryCleanup(path) {
  try {
    await fetch(`${BASE_URL}${path}`, { method: 'DELETE' });
  } catch {}
}

async function tryRequest(paths, options) {
  let lastResp;
  for (const path of paths) {
    lastResp = await request(path, options);
    if ([200, 201, 204].includes(lastResp.status)) return lastResp;
  }
  return lastResp;
}

function extractBattleState(body) {
  if (!body) return null;
  return body.data || body.state || body.battle || body;
}

function extractBattleLog(state) {
  if (!state) return [];
  return state.log || state.battleLog || state.events || state.history || state.report || [];
}

function getHand(state) {
  return state?.hand || state?.playerHand || state?.player?.hand || [];
}

function getResources(state) {
  return state?.resources ?? state?.mana ?? state?.energy ?? state?.player?.resources ?? 0;
}

function getField(state) {
  return state?.battlefield || state?.field || state?.playerField || state?.player?.battlefield || [];
}

describe('undo_last_play_restores_previous_battle_state', () => {
  it('should restore hand, resources, battlefield, and battle log when undoing last play; reject undo when not applicable; re-validate on replay', async () => {
    // Step 1: Start a new battle session with fixed/deterministic setup
    const startResp = await tryRequest(
      ['/api/battles', '/api/battle/start', '/api/games'],
      {
        method: 'POST',
        body: JSON.stringify({ difficulty: 'normal', deckId: 'default' }),
      }
    );
    expect([200, 201]).toContain(startResp.status);

    const battleData = extractBattleState(startResp.body);
    const battleId = battleData?.id || battleData?.battleId || battleData?.gameId || startResp.body?.id;
    expect(battleId).toBeTruthy();

    try {
      // Step 2: Get initial state (player's turn, should have hand cards)
      let stateResp = await tryRequest(
        [`/api/battles/${battleId}`, `/api/battles/${battleId}/state`],
        { method: 'GET' }
      );
      expect(stateResp.status).toBe(200);
      const initialState = extractBattleState(stateResp.body);

      const initialHand = getHand(initialState);
      const initialResources = getResources(initialState);
      const initialField = getField(initialState);
      const initialLog = extractBattleLog(initialState);

      expect(initialHand.length).toBeGreaterThan(0);
      expect(typeof initialResources).toBe('number');

      const handCountBefore = initialHand.length;
      const fieldCountBefore = Array.isArray(initialField) ? initialField.length : 0;
      const resourcesBefore = initialResources;
      const logLengthBefore = initialLog.length;

      // Step 3: Try undo BEFORE playing anything — should be rejected with non-2xx
      let undoBeforePlay = await tryRequest(
        [`/api/battles/${battleId}/undo`, `/api/battles/${battleId}/actions/undo`],
        { method: 'POST' }
      );
      // Should be rejected since nothing was played
      expect(
        [400, 403, 409, 422].includes(undoBeforePlay.status),
        `Undo before any play should be rejected with 4xx status, got status=${undoBeforePlay.status}, body=${JSON.stringify(undoBeforePlay.body)}`
      ).toBe(true);

      // Step 4: Play a card from hand
      const cardToPlay = initialHand[0];
      const cardId = typeof cardToPlay === 'string' ? cardToPlay : (cardToPlay?.id || cardToPlay?.cardId);

      const playResp = await tryRequest(
        [`/api/battles/${battleId}/play`, `/api/battles/${battleId}/actions/play`],
        {
          method: 'POST',
          body: JSON.stringify({ cardId: cardId, index: 0 }),
        }
      );
      expect([200, 201]).toContain(playResp.status);

      // Verify state changed after playing
      const afterPlayResp = await tryRequest(
        [`/api/battles/${battleId}`, `/api/battles/${battleId}/state`],
        { method: 'GET' }
      );
      expect(afterPlayResp.status).toBe(200);
      const afterPlayState = extractBattleState(afterPlayResp.body);

      const handAfterPlay = getHand(afterPlayState);
      const resourcesAfterPlay = getResources(afterPlayState);
      const fieldAfterPlay = getField(afterPlayState);
      const logAfterPlay = extractBattleLog(afterPlayState);

      expect(handAfterPlay.length).toBe(handCountBefore - 1);
      expect(Array.isArray(fieldAfterPlay) ? fieldAfterPlay.length : 0).toBe(fieldCountBefore + 1);
      expect(resourcesAfterPlay).toBeLessThanOrEqual(resourcesBefore);
      // Log should have grown (play event recorded)
      expect(logAfterPlay.length).toBeGreaterThan(logLengthBefore);

      // Step 5: Undo the play
      const undoResp = await tryRequest(
        [`/api/battles/${battleId}/undo`, `/api/battles/${battleId}/actions/undo`],
        { method: 'POST' }
      );
      expect([200, 204]).toContain(undoResp.status);

      // Step 6: Verify state restored after undo (hand, resources, field, AND log)
      const afterUndoResp = await tryRequest(
        [`/api/battles/${battleId}`, `/api/battles/${battleId}/state`],
        { method: 'GET' }
      );
      expect(afterUndoResp.status).toBe(200);
      const afterUndoState = extractBattleState(afterUndoResp.body);

      const handAfterUndo = getHand(afterUndoState);
      const resourcesAfterUndo = getResources(afterUndoState);
      const fieldAfterUndo = getField(afterUndoState);
      const logAfterUndo = extractBattleLog(afterUndoState);

      // Hand count should be restored
      expect(handAfterUndo.length).toBe(handCountBefore);
      // Resources should be restored
      expect(resourcesAfterUndo).toBe(resourcesBefore);
      // Battlefield should be restored
      expect(Array.isArray(fieldAfterUndo) ? fieldAfterUndo.length : 0).toBe(fieldCountBefore);
      // Battle log should be restored (play event entry removed)
      expect(logAfterUndo.length).toBeLessThanOrEqual(logLengthBefore);

      // Step 7: After undo, play again — should succeed since resources were restored
      const replayResp = await tryRequest(
        [`/api/battles/${battleId}/play`, `/api/battles/${battleId}/actions/play`],
        {
          method: 'POST',
          body: JSON.stringify({ cardId: cardId, index: 0 }),
        }
      );
      expect([200, 201]).toContain(replayResp.status);

      // Step 7b: Try to play a SECOND card in the same turn — should be rejected (1 card per turn limit)
      const handAfterReplay = getHand(extractBattleState(
        (await tryRequest([`/api/battles/${battleId}`, `/api/battles/${battleId}/state`], { method: 'GET' })).body
      ));
      if (handAfterReplay.length > 0) {
        const secondCard = handAfterReplay[0];
        const secondCardId = typeof secondCard === 'string' ? secondCard : (secondCard?.id || secondCard?.cardId);
        const secondPlayResp = await tryRequest(
          [`/api/battles/${battleId}/play`, `/api/battles/${battleId}/actions/play`],
          {
            method: 'POST',
            body: JSON.stringify({ cardId: secondCardId, index: 0 }),
          }
        );
        // Should be rejected — only 1 card per turn
        expect(
          [400, 403, 409, 422].includes(secondPlayResp.status),
          `Playing a second card in same turn after undo+replay should be rejected, got status=${secondPlayResp.status}`
        ).toBe(true);
      }

      // Step 8: End turn (move to AI turn), then try undo — should be rejected
      const endTurnResp = await tryRequest(
        [`/api/battles/${battleId}/end-turn`, `/api/battles/${battleId}/actions/end-turn`],
        { method: 'POST' }
      );
      // Assert end-turn succeeded (don't skip this with if)
      expect(
        [200, 204].includes(endTurnResp.status),
        `End turn should succeed, got status=${endTurnResp.status}`
      ).toBe(true);

      // Wait briefly for AI turn to process
      await new Promise(r => setTimeout(r, 500));

      const undoAfterEnd = await tryRequest(
        [`/api/battles/${battleId}/undo`, `/api/battles/${battleId}/actions/undo`],
        { method: 'POST' }
      );
      // Should be rejected since it's no longer player's current turn or turn has ended
      expect(
        [400, 403, 409, 422].includes(undoAfterEnd.status),
        `Undo after ending turn should be rejected with 4xx, got status=${undoAfterEnd.status}`
      ).toBe(true);

    } finally {
      await tryCleanup(`/api/battles/${battleId}`);
    }
  });
});

import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function getPage(path) {
  const res = await fetch(`${BASE_URL}${path}`, {
    headers: { 'Accept': 'text/html,application/json' },
  });
  const text = await res.text();
  return { res, text };
}

async function getAllBundleContent() {
  const mainPage = await getPage('/');
  const scriptMatches = mainPage.text.match(/src=["']([^"']*\.js[^"']*)["']/g) || [];
  const scriptUrls = scriptMatches.map(m => {
    const match = m.match(/src=["']([^"']*)["']/);
    return match ? match[1] : null;
  }).filter(Boolean);

  let allContent = mainPage.text;
  for (const url of scriptUrls) {
    try {
      const fullUrl = url.startsWith('http') ? url : `${BASE_URL}${url.startsWith('/') ? '' : '/'}${url}`;
      const jsRes = await fetch(fullUrl);
      if (jsRes.ok) {
        allContent += await jsRes.text();
      }
    } catch {}
  }
  return { mainPage, allContent };
}

