import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function request(path, options = {}) {
  const res = await fetch(`${BASE_URL}${path}`, {
    headers: { 'Content-Type': 'application/json', ...(options.headers || {}) },
    ...options,
  });
  const text = await res.text();
  let body;
  try {
    body = text ? JSON.parse(text) : null;
  } catch {
    body = text;
  }
  return { status: res.status, body };
}

async function tryRequest(paths, options) {
  let lastResp;
  for (const path of paths) {
    lastResp = await request(path, options);
    if ([200, 201, 204].includes(lastResp.status)) return lastResp;
  }
  return lastResp;
}

async function tryGet(paths) {
  let lastResp;
  for (const path of paths) {
    lastResp = await request(path, { method: 'GET' });
    if (lastResp.status === 200) return lastResp;
  }
  return lastResp;
}

function extractList(body) {
  if (Array.isArray(body)) return body;
  if (Array.isArray(body?.items)) return body.items;
  if (Array.isArray(body?.data)) return body.data;
  if (Array.isArray(body?.cards)) return body.cards;
  if (Array.isArray(body?.results)) return body.results;
  return [];
}

function extractStats(body) {
  if (!body) return null;
  if (body.stats) return body.stats;
  if (body.collection) return body.collection;
  if (typeof body.ownedCount === 'number') return body;
  if (body.data?.stats) return body.data.stats;
  return body;
}

function getOwnedCount(stats) {
  return stats?.ownedCount ?? stats?.owned ?? stats?.collected ?? 0;
}

function getTotalCount(stats) {
  return stats?.totalCount ?? stats?.total ?? stats?.totalCards ?? 0;
}

function getRatio(stats) {
  return stats?.ratio ?? stats?.completionRatio ?? stats?.percentage ?? stats?.completion ?? null;
}

describe('update_owned_status_recalculates_collection_stats', () => {
  let card1Id;
  let wasOriginallyOwned = false;

  async function markOwned(cardId, owned) {
    return await tryRequest(
      [`/api/cards/${cardId}/own`, `/api/collection/${cardId}`, `/api/cards/${cardId}`],
      {
        method: owned ? 'POST' : 'POST',
        body: JSON.stringify({ owned }),
      }
    );
  }

  async function markOwnedMultiMethod(cardId, owned) {
    let resp = await request(`/api/cards/${cardId}/own`, {
      method: 'POST',
      body: JSON.stringify({ owned }),
    });
    if ([200, 201, 204].includes(resp.status)) return resp;
    resp = await request(`/api/collection/${cardId}`, {
      method: 'PUT',
      body: JSON.stringify({ owned }),
    });
    if ([200, 201, 204].includes(resp.status)) return resp;
    resp = await request(`/api/cards/${cardId}`, {
      method: 'PATCH',
      body: JSON.stringify({ owned }),
    });
    return resp;
  }

  async function getStats() {
    return await tryGet(['/api/collection/stats', '/api/stats/collection', '/api/collection']);
  }

  it('should recalculate owned count, total cards, and completion ratio after toggling owned status, stats based on all cards not filtered', async () => {
    // Step 1: Get card list
    const cardsResp = await tryGet(['/api/cards', '/api/cards/search?q=', '/api/collection/cards']);
    expect(cardsResp.status).toBe(200);

    const allCards = extractList(cardsResp.body);
    expect(allCards.length).toBeGreaterThan(0);

    const card1 = allCards[0];
    card1Id = card1.id || card1.cardId || card1.card_id;
    expect(card1Id).toBeTruthy();

    const totalCards = allCards.length;

    // Step 2: Ensure card1 starts as NOT owned so we get predictable count changes
    const ensureUnownedResp = await markOwnedMultiMethod(card1Id, false);
    expect([200, 201, 204].includes(ensureUnownedResp.status)).toBe(true);

    // Step 3: Get baseline stats after ensuring card1 is not owned
    const baseStatsResp = await getStats();
    expect(baseStatsResp.status).toBe(200);
    const baseStats = extractStats(baseStatsResp.body);
    expect(baseStats).toBeTruthy();

    const baseOwned = getOwnedCount(baseStats);
    const baseTotal = getTotalCount(baseStats);
    expect(baseTotal).toBeGreaterThan(0);
    expect(baseTotal).toBe(totalCards);

    // Step 4: Mark card1 as owned
    const markResp = await markOwnedMultiMethod(card1Id, true);
    expect([200, 201, 204]).toContain(markResp.status);

    // Step 5: Verify stats updated - owned count should be exactly baseOwned + 1
    const afterOwnResp = await getStats();
    expect(afterOwnResp.status).toBe(200);
    const afterOwnStats = extractStats(afterOwnResp.body);
    const afterOwnCount = getOwnedCount(afterOwnStats);
    const afterOwnTotal = getTotalCount(afterOwnStats);

    expect(afterOwnCount).toBe(baseOwned + 1);
    // Total should remain the same (based on all cards)
    expect(afterOwnTotal).toBe(baseTotal);

    // Completion ratio must be present and correct
    const afterOwnRatio = getRatio(afterOwnStats);
    expect(afterOwnRatio).not.toBeNull();
    expect(typeof afterOwnRatio).toBe('number');
    expect(afterOwnRatio).toBeGreaterThan(0);
    expect(afterOwnRatio).toBeLessThanOrEqual(1.0);
    // Verify ratio is approximately correct
    const expectedRatio = (baseOwned + 1) / baseTotal;
    expect(Math.abs(afterOwnRatio - expectedRatio)).toBeLessThan(0.01);

    // Step 6: Toggle card1 back to not owned
    const unmarkResp = await markOwnedMultiMethod(card1Id, false);
    expect([200, 201, 204]).toContain(unmarkResp.status);

    // Step 7: Verify stats reflect the removal - should return to baseline
    const afterRemoveResp = await getStats();
    expect(afterRemoveResp.status).toBe(200);
    const afterRemoveStats = extractStats(afterRemoveResp.body);
    const afterRemoveCount = getOwnedCount(afterRemoveStats);
    const afterRemoveTotal = getTotalCount(afterRemoveStats);

    expect(afterRemoveCount).toBe(baseOwned);
    expect(afterRemoveTotal).toBe(baseTotal);

    const afterRemoveRatio = getRatio(afterRemoveStats);
    expect(afterRemoveRatio).not.toBeNull();
    expect(typeof afterRemoveRatio).toBe('number');
    if (baseOwned === 0) {
      expect(afterRemoveRatio).toBe(0);
    }

    // Step 8: Verify stats are based on ALL cards, not filtered subset
    // Get cards with a filter applied
    const rarities = allCards.map(c => c.rarity || c.rare || '').filter(Boolean);
    const uniqueRarities = [...new Set(rarities)];
    if (uniqueRarities.length > 0) {
      const filterRarity = uniqueRarities[0];
      const filteredCardsResp = await tryGet([
        `/api/cards?rarity=${encodeURIComponent(filterRarity)}`,
        `/api/cards/search?rarity=${encodeURIComponent(filterRarity)}`,
      ]);

      if (filteredCardsResp.status === 200) {
        const filteredCards = extractList(filteredCardsResp.body);
        // Filtered list may be smaller than total
        if (filteredCards.length < totalCards && filteredCards.length > 0) {
          // Now mark a card from the filtered results as owned
          const filteredCard = filteredCards[0];
          const filteredCardId = filteredCard.id || filteredCard.cardId || filteredCard.card_id;
          if (filteredCardId) {
            // First ensure it's not owned
            await markOwnedMultiMethod(filteredCardId, false);
            const statsBeforeFilter = await getStats();
            expect(statsBeforeFilter.status).toBe(200);
            const beforeFilterStats = extractStats(statsBeforeFilter.body);
            const beforeFilterTotal = getTotalCount(beforeFilterStats);

            // Mark it owned
            await markOwnedMultiMethod(filteredCardId, true);

            // Stats total should still be ALL cards, not just filtered
            const statsAfterFilter = await getStats();
            expect(statsAfterFilter.status).toBe(200);
            const afterFilterStats = extractStats(statsAfterFilter.body);
            const afterFilterTotal = getTotalCount(afterFilterStats);

            expect(afterFilterTotal).toBe(beforeFilterTotal);
            expect(afterFilterTotal).toBe(totalCards);

            // Cleanup: unmark it
            await markOwnedMultiMethod(filteredCardId, false);
          }
        }
      }
    }
  });
});

