import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function request(path, init) {
  const res = await fetch(`${BASE_URL}${path}`, {
    ...init,
    headers: {
      'Content-Type': 'application/json',
      ...(init?.headers || {}),
    },
  });

  const rawText = await res.text();
  let body = null;
  try {
    body = rawText ? JSON.parse(rawText) : null;
  } catch {
    body = rawText;
  }

  return {
    status: res.status,
    body,
    rawText,
  };
}

async function tryDelete(path) {
  try {
    await fetch(`${BASE_URL}${path}`, { method: 'DELETE' });
  } catch {
    // ignore cleanup failures
  }
}

async function tryRequest(paths, init) {
  let lastResp;
  for (const path of paths) {
    lastResp = await request(path, init);
    if ([200, 201, 204].includes(lastResp.status)) return lastResp;
  }
  return lastResp;
}

function extractList(body) {
  if (Array.isArray(body)) return body;
  if (Array.isArray(body?.items)) return body.items;
  if (Array.isArray(body?.data)) return body.data;
  if (Array.isArray(body?.results)) return body.results;
  return [];
}

function findByName(items, expectedName) {
  return items.find((item) => {
    const name = item?.name ?? item?.deckName ?? item?.title;
    return name === expectedName;
  });
}

describe('round24_invalid_input_guardrails', () => {
  it('should reject or safely degrade invalid deck-name/search/import inputs without polluting valid data', async () => {
    const createdDeckIds = [];
    const unique = `guardrail-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
    const validDeckName = `Valid Deck ${unique}`;

    try {
      // 1) Create a valid baseline deck to prove normal data remains intact.
      const createValid = await tryRequest(
        ['/api/decks'],
        {
          method: 'POST',
          body: JSON.stringify({ name: validDeckName, cards: [] }),
        }
      );

      expect([200, 201]).toContain(createValid.status);
      expect(createValid.body && typeof createValid.body === 'object').toBe(true);

      const validDeckId = createValid.body?.id ?? createValid.body?.deckId ?? createValid.body?.data?.id;
      expect(validDeckId, `expected created deck id in response, got: ${JSON.stringify(createValid.body)}`).toBeTruthy();
      createdDeckIds.push(validDeckId);

      const returnedValidName = createValid.body?.name ?? createValid.body?.deckName ?? createValid.body?.data?.name;
      expect(returnedValidName).toBe(validDeckName);

      // 2) Invalid deck creation attempts: blank / whitespace / overlong / abnormal numeric-like input.
      const invalidDeckPayloads = [
        { name: '', cards: [], desc: 'empty name' },
        { name: '   ', cards: [], desc: 'whitespace only name' },
        { name: 'X'.repeat(1025), cards: [], desc: 'overlong name' },
        { name: String(Number.MAX_SAFE_INTEGER), cards: [], desc: 'numeric-like name' },
      ];

      for (const payload of invalidDeckPayloads) {
        const { desc, ...payloadBody } = payload;
        const res = await request('/api/decks', {
          method: 'POST',
          body: JSON.stringify(payloadBody),
        });

        expect(
          [200, 201, 400, 409, 422].includes(res.status),
          `unexpected status for invalid deck payload (${desc}): ${res.status}, body=${res.rawText}`
        ).toBe(true);

        if ([400, 409, 422].includes(res.status)) {
          // Error responses should have a body explaining the issue
          expect(res.body !== null, `expected error response body for invalid deck payload (${desc})`).toBe(true);
        }

        if ([200, 201].includes(res.status)) {
          // If the server accepted it, it should have sanitized the name
          const returnedName = res.body?.name ?? res.body?.deckName ?? res.body?.data?.name;
          const returnedId = res.body?.id ?? res.body?.deckId ?? res.body?.data?.id;

          if (returnedId) {
            createdDeckIds.push(returnedId);
          }

          expect(
            typeof returnedName === 'string' && returnedName.trim().length > 0,
            `invalid deck payload (${desc}) should not persist blank/invalid name; actual response=${JSON.stringify(res.body)}`
          ).toBe(true);
        }
      }

      // 3) Verify baseline valid deck still exists and was not polluted.
      const listDecks = await request('/api/decks', { method: 'GET' });
      expect(
        [200].includes(listDecks.status),
        `unexpected deck-list status: ${listDecks.status}, body=${listDecks.rawText}`
      ).toBe(true);

      const decks = extractList(listDecks.body);
      expect(Array.isArray(decks)).toBe(true);

      const validDeck = findByName(decks, validDeckName);
      expect(validDeck, `expected baseline valid deck '${validDeckName}' to remain present after invalid submissions`).toBeTruthy();

      const actualName = validDeck?.name ?? validDeck?.deckName ?? validDeck?.title;
      expect(actualName).toBe(validDeckName);

      // 4) Invalid catalog search should reject or degrade safely.
      const invalidSearchTerms = [
        { q: '', desc: 'empty' },
        { q: '   ', desc: 'whitespace' },
        { q: 'X'.repeat(2048), desc: 'overlong' },
        { q: 'AbCdEfGh', desc: 'mixed case' },
      ];

      for (const { q, desc } of invalidSearchTerms) {
        let searchRes = await request(`/api/cards/search?q=${encodeURIComponent(q)}`, { method: 'GET' });
        if (![200, 400, 404, 422].includes(searchRes.status)) {
          searchRes = await request(`/api/cards?q=${encodeURIComponent(q)}`, { method: 'GET' });
        }

        expect(
          [200, 400, 404, 422].includes(searchRes.status),
          `unexpected search status for q='${desc}': ${searchRes.status}, body=${searchRes.rawText}`
        ).toBe(true);

        if (searchRes.status === 200) {
          const resultList = extractList(searchRes.body);
          expect(Array.isArray(resultList), `expected search response to be array-like for q='${desc}'`).toBe(true);
        }
      }

      // 5) Invalid save import should reject or degrade safely, and not overwrite baseline deck.
      const invalidImports = [
        {},
        { decks: 'not-an-array' },
        { decks: [{ name: '' }] },
        { decks: [{ name: ' '.repeat(5), cards: 'invalid' }] },
        { currency: -999999999, progress: null },
        { version: 999, stageResults: { stage_999: { rating: -5, completed: 'maybe' } } },
      ];

      for (const payload of invalidImports) {
        let importRes = await request('/api/saves/import', {
          method: 'POST',
          body: JSON.stringify(payload),
        });
        if (![200, 400, 404, 409, 422].includes(importRes.status)) {
          importRes = await request('/api/import', {
            method: 'POST',
            body: JSON.stringify(payload),
          });
        }

        expect(
          [200, 400, 404, 409, 422].includes(importRes.status),
          `unexpected import status for payload ${JSON.stringify(payload)}: ${importRes.status}, body=${importRes.rawText}`
        ).toBe(true);

        if ([400, 409, 422].includes(importRes.status)) {
          expect(importRes.body !== null, `expected structured error body for invalid import payload ${JSON.stringify(payload)}`).toBe(true);
        }
      }

      // 6) Re-check baseline deck after invalid import attempts.
      const recheckDecks = await request('/api/decks', { method: 'GET' });
      expect(
        [200].includes(recheckDecks.status),
        `unexpected deck-list recheck status: ${recheckDecks.status}, body=${recheckDecks.rawText}`
      ).toBe(true);

      const recheckedDecks = extractList(recheckDecks.body);
      const recheckedValidDeck = findByName(recheckedDecks, validDeckName);
      expect(recheckedValidDeck, `expected baseline valid deck '${validDeckName}' to still exist after invalid import attempts`).toBeTruthy();
      expect(recheckedValidDeck?.name ?? recheckedValidDeck?.deckName ?? recheckedValidDeck?.title).toBe(validDeckName);

    } finally {
      // cleanup
      await Promise.all(createdDeckIds.map((id) => tryDelete(`/api/decks/${id}`)));
    }
  });
});

import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function request(path, options = {}) {
  const res = await fetch(`${BASE_URL}${path}`, {
    headers: { 'Content-Type': 'application/json', ...(options.headers || {}) },
    ...options,
  });
  const text = await res.text();
  let body;
  try {
    body = text ? JSON.parse(text) : null;
  } catch {
    body = text;
  }
  return { res, body };
}

async function tryCleanup(path) {
  try {
    await fetch(`${BASE_URL}${path}`, { method: 'DELETE' });
  } catch {}
}

function extractId(body) {
  if (!body) return null;
  return body.id || body.saveId || body.data?.id || null;
}

function extractExportBody(body) {
  if (!body) return {};
  return body.data || body;
}

async function tryRequest(paths, options) {
  for (const path of paths) {
    const resp = await request(path, options);
    if ([200, 201, 204].includes(resp.res.status)) return resp;
  }
  // Return last attempt
  return await request(paths[paths.length - 1], options);
}

async function tryGet(paths) {
  for (const path of paths) {
    const resp = await request(path, { method: 'GET' });
    if (resp.res.status === 200) return resp;
  }
  return await request(paths[paths.length - 1], { method: 'GET' });
}

describe('reset_selected_data_only_preserves_others', () => {
  it('should reset only chosen data scope and preserve all non-selected data', async () => {
    const save = {
      version: 2,
      collection: { card_001: 1, card_002: 1 },
      decks: [{ id: 'deck-1', name: 'Deck 1', cards: ['card_001', 'card_002'] }],
      stageResults: { stage_1: { rating: 3, completed: true }, stage_2: { rating: 1, completed: true } },
      preferences: { language: 'zh-CN', musicVolume: 0.5, theme: 'dark' },
      selectedDeckId: 'deck-1',
      recentFilters: { category: 'support' },
      tutorialRead: { intro: true }
    };

    // Import save data
    const createResp = await tryRequest(
      ['/api/saves/import', '/api/saves', '/api/import'],
      { method: 'POST', body: JSON.stringify(save) }
    );
    expect([200, 201]).toContain(createResp.res.status);
    const saveId = extractId(createResp.body);
    expect(saveId).toBeTruthy();

    try {
      // --- Reset stageResults only ---
      const resetStageResp = await tryRequest(
        [`/api/saves/${saveId}/reset`],
        { method: 'POST', body: JSON.stringify({ targets: ['stageResults'] }) }
      );
      if (![200, 204].includes(resetStageResp.res.status)) {
        const patchResp = await request(`/api/saves/${saveId}/reset`, {
          method: 'PATCH',
          body: JSON.stringify({ targets: ['stageResults'] }),
        });
        expect([200, 204]).toContain(patchResp.res.status);
      } else {
        expect([200, 204]).toContain(resetStageResp.res.status);
      }

      // Fetch state after stageResults reset
      const afterStageReset = await tryGet([`/api/saves/${saveId}/export`, `/api/saves/${saveId}`]);
      expect(afterStageReset.res.status).toBe(200);
      const stageBody = extractExportBody(afterStageReset.body);

      // stageResults should be cleared
      const sr = stageBody.stageResults;
      expect(
        sr == null || (typeof sr === 'object' && Object.keys(sr).length === 0),
        `stageResults should be cleared after targeted reset, got ${JSON.stringify(sr)}`
      ).toBe(true);

      // preferences should stay unchanged
      expect(stageBody.preferences).toBeTruthy();
      expect(stageBody.preferences).toMatchObject({ language: 'zh-CN', musicVolume: 0.5, theme: 'dark' });

      // collection should stay unchanged
      expect(stageBody.collection).toEqual(save.collection);

      // selectedDeckId should stay unchanged
      expect(stageBody.selectedDeckId).toBe('deck-1');

      // decks should stay unchanged
      expect(stageBody.decks).toBeTruthy();
      expect(Array.isArray(stageBody.decks)).toBe(true);
      expect(stageBody.decks.length).toBe(1);
      expect(stageBody.decks[0].name).toBe('Deck 1');

      // tutorialRead should stay unchanged
      expect(stageBody.tutorialRead).toEqual(save.tutorialRead);

      // recentFilters should stay unchanged (was missing in original test)
      expect(stageBody.recentFilters).toEqual(save.recentFilters);

      // --- Reset preferences only ---
      const resetPrefResp = await tryRequest(
        [`/api/saves/${saveId}/reset`],
        { method: 'POST', body: JSON.stringify({ targets: ['preferences'] }) }
      );
      if (![200, 204].includes(resetPrefResp.res.status)) {
        const patchResp = await request(`/api/saves/${saveId}/reset`, {
          method: 'PATCH',
          body: JSON.stringify({ targets: ['preferences'] }),
        });
        expect([200, 204]).toContain(patchResp.res.status);
      } else {
        expect([200, 204]).toContain(resetPrefResp.res.status);
      }

      const afterPrefReset = await tryGet([`/api/saves/${saveId}/export`, `/api/saves/${saveId}`]);
      expect(afterPrefReset.res.status).toBe(200);
      const prefBody = extractExportBody(afterPrefReset.body);

      // preferences should be cleared
      const prefs = prefBody.preferences;
      expect(
        prefs == null || (typeof prefs === 'object' && Object.keys(prefs).length === 0),
        `preferences should be cleared after targeted reset, got ${JSON.stringify(prefs)}`
      ).toBe(true);

      // stageResults should STILL be empty (from the previous reset, not restored)
      const srAfterPrefReset = prefBody.stageResults;
      expect(
        srAfterPrefReset == null || (typeof srAfterPrefReset === 'object' && Object.keys(srAfterPrefReset).length === 0),
        `stageResults should still be cleared after preferences reset, got ${JSON.stringify(srAfterPrefReset)}`
      ).toBe(true);

      // collection should remain unchanged
      expect(prefBody.collection).toEqual(save.collection);

      // selectedDeckId should remain unchanged
      expect(prefBody.selectedDeckId).toBe('deck-1');

      // recentFilters should remain unchanged
      expect(prefBody.recentFilters).toEqual(save.recentFilters);

      // tutorialRead should remain unchanged
      expect(prefBody.tutorialRead).toEqual(save.tutorialRead);

      // decks should remain unchanged after preferences reset
      expect(prefBody.decks).toBeTruthy();
      expect(Array.isArray(prefBody.decks)).toBe(true);
      expect(prefBody.decks.length).toBe(1);
      expect(prefBody.decks[0].name).toBe('Deck 1');

      // --- Attempt to reset everything at once (should require confirmation or be rejected) ---
      const resetAllResp = await request(`/api/saves/${saveId}/reset`, {
        method: 'POST',
        body: JSON.stringify({ targets: ['collection', 'decks', 'stageResults', 'preferences'] }),
      });

      if ([400, 403, 409, 422].includes(resetAllResp.res.status)) {
        // Properly rejected — expected behavior per Round 23
        expect(resetAllResp.body).toBeTruthy();
      } else if ([200, 204].includes(resetAllResp.res.status)) {
        // If the server returned success, it MUST include a confirmation requirement
        // and data should NOT have been actually deleted yet
        const requiresConfirmation = resetAllResp.body?.requiresConfirmation ||
          resetAllResp.body?.confirmationRequired ||
          resetAllResp.body?.needConfirm ||
          resetAllResp.body?.confirm;

        // Verify data is still present (not silently wiped)
        const checkAfterAll = await tryGet([`/api/saves/${saveId}/export`, `/api/saves/${saveId}`]);
        expect(checkAfterAll.res.status).toBe(200);
        const allBody = extractExportBody(checkAfterAll.body);

        if (!requiresConfirmation) {
          // If no confirmation mechanism, then at minimum collection and decks must still exist
          // (Round 23: "不能一键误删全部收藏和卡组，除非有非常明确的二次确认")
          expect(
            allBody.collection != null || (allBody.decks && allBody.decks.length > 0),
            'Resetting all data without confirmation should not silently wipe collection and decks'
          ).toBe(true);
        }
      } else {
        // Unexpected status - fail explicitly
        expect.fail(`Unexpected status ${resetAllResp.res.status} for reset-all request`);
      }

    } finally {
      await tryCleanup(`/api/saves/${saveId}`);
    }
  });
});

