    expect(currentDeck.body.deckId || currentDeck.body.id, `expected current deck response to reference copied deck, got ${JSON.stringify(currentDeck.body)}`).toBe(copy.body.id);

    const createdDeckIds = [deckId, copy.body.id];
    for (let i = 0; i < 6; i++) {
      const extra = await request('/api/decks', {
        method: 'POST',
