      expect([200, 201]).toContain(perfectRun.res.status);
      expect(perfectRun.body.rating).toBe('perfect');
      expect(perfectRun.body.extraObjectiveMet).toBe(true);

      const listAfterPerfect = await request('/api/stages/results');
      expect(listAfterPerfect.res.status).toBe(200);
      const perfectEntry = listAfterPerfect.body.find((x) => x.stageId === stageId);
      expect(perfectEntry, `expected stage ${stageId} result entry after perfect clear, got ${JSON.stringify(listAfterPerfect.body)}`).toBeTruthy();
      expect(perfectEntry.bestRating || perfectEntry.rating).toBe('perfect');

      const worseAgainEnter = await request(`/api/stages/${stageId}/enter`, {
