      const listAfterWorseReplay = await request('/api/stages/results');
      expect(listAfterWorseReplay.res.status).toBe(200);
      const stillPerfect = listAfterWorseReplay.body.find((x) => x.stageId === stageId);
      expect(stillPerfect, `expected stage ${stageId} result entry after worse replay, got ${JSON.stringify(listAfterWorseReplay.body)}`).toBeTruthy();
      expect(stillPerfect.bestRating || stillPerfect.rating, `expected best rating to remain perfect after lower replay, got ${JSON.stringify(stillPerfect)}`).toBe('perfect');

      const quitEnter = await request(`/api/stages/${stageId}/enter`, {
        method: 'POST',
        headers: JSON_HEADERS,
        body: JSON.stringify({ deckId, difficulty: 'hard' })
