    }
  });
});

import { describe, it, expect, beforeAll, afterAll } from 'vitest';
import puppeteer from 'puppeteer';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

let browser;
let page;

async function launchBrowser() {
  browser = await puppeteer.launch({ headless: 'new', args: ['--no-sandbox', '--disable-setuid-sandbox'] });
  page = await browser.newPage();
}

async function closeBrowser() {
  if (browser) await browser.close();
}

async function navigateTo(path) {
  await page.goto(`${BASE_URL}${path}`, { waitUntil: 'networkidle0', timeout: 15000 });
}

async function clearLocalStorage() {
  await page.evaluate(() => localStorage.clear());
}

async function getLocalStorage() {
  return await page.evaluate(() => {
    const data = {};
    for (let i = 0; i < localStorage.length; i++) {
      const key = localStorage.key(i);
      try {
        data[key] = JSON.parse(localStorage.getItem(key));
      } catch {
        data[key] = localStorage.getItem(key);
      }
    }
    return data;
  });
}

async function setLocalStorage(key, value) {
  await page.evaluate((k, v) => {
    localStorage.setItem(k, typeof v === 'string' ? v : JSON.stringify(v));
  }, key, value);
}

async function clickText(text) {
  const escaped = text.replace(/'/g, "\\'");
  const sel = `xpath/.//button[contains(.,\'${escaped}\')] | .//a[contains(.,\'${escaped}\')] | .//*[contains(@role,\'button\') and contains(.,\'${escaped}\')]`;
  try {
    await page.waitForSelector(sel, { timeout: 3000 });
    await page.click(sel);
  } catch {
    const elements = await page.$$('button, a, [role="button"], [class*="tab"], [class*="nav"]');
    for (const el of elements) {
      const elText = await el.evaluate(e => e.textContent || '');
      if (elText.includes(text)) {
        await el.click();
        return;
      }
    }
    throw new Error(`Could not find clickable element with text: ${text}`);
  }
}

async function findAndClick(textOptions) {
  for (const text of textOptions) {
    try {
      await clickText(text);
      return true;
    } catch {
      continue;
    }
  }
  return false;
}

async function waitForText(text, timeout = 5000) {
  const start = Date.now();
  while (Date.now() - start < timeout) {
    const content = await page.content();
    if (content.includes(text)) return true;
    await new Promise(r => setTimeout(r, 200));
  }
  return false;
}

async function getPageText() {
  return await page.evaluate(() => document.body.innerText || document.body.textContent || '');
}

