      expect(exported.body.recentFilters, `expected export to include recentFilters, got ${JSON.stringify(exported.body)}`).toEqual(expect.objectContaining({ color: 'fire', manaCostMin: 2, ownedOnly: true }));
      expect(exported.body.inProgressBattle || exported.body.battleState || exported.body.activeRun, `expected export not to include in-progress battle state, got ${JSON.stringify(exported.body)}`).toBeFalsy();

      const reImport = await request('/api/save/import', {
        method: 'POST',
        headers: JSON_HEADERS,
        body: JSON.stringify(exported.body)
      });
      expect([200, 201]).toContain(reImport.res.status);

      const exportedAgain = await request('/api/save/export');
      expect(exportedAgain.res.status).toBe(200);
      expect(exportedAgain.body.currentDeckId).toBe(deck2.body.id);
      expect(exportedAgain.body.recentFilters).toEqual(expect.objectContaining({ color: 'fire', manaCostMin: 2, ownedOnly: true }));
      expect(exportedAgain.body.inProgressBattle || exportedAgain.body.battleState || exportedAgain.body.activeRun).toBeFalsy();
    } finally {
      for (const id of createdDeckIds) {
        await safeDelete(`/api/decks/${id}`);
      }
    }
  });
});

import { describe, it, expect, beforeAll, afterAll } from 'vitest';
import puppeteer from 'puppeteer';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

let browser;
let page;

async function launchBrowser() {
  browser = await puppeteer.launch({ headless: 'new', args: ['--no-sandbox', '--disable-setuid-sandbox'] });
  page = await browser.newPage();
}

async function closeBrowser() {
  if (browser) await browser.close();
}

async function navigateTo(path) {
  await page.goto(`${BASE_URL}${path}`, { waitUntil: 'networkidle0', timeout: 15000 });
}

async function clearLocalStorage() {
  await page.evaluate(() => localStorage.clear());
}

async function getLocalStorage() {
  return await page.evaluate(() => {
    const data = {};
    for (let i = 0; i < localStorage.length; i++) {
      const key = localStorage.key(i);
      try {
        data[key] = JSON.parse(localStorage.getItem(key));
      } catch {
        data[key] = localStorage.getItem(key);
      }
    }
    return data;
  });
}

async function findAndClick(textOptions, timeout = 3000) {
  for (const text of textOptions) {
    try {
      const elements = await page.$$('button, a, [role="button"], [class*="tab"], [class*="nav"], span, div[role], label, [class*="btn"]');
      for (const el of elements) {
        const elText = await el.evaluate(e => (e.textContent || '').trim());
        if (elText.includes(text)) {
          const isVisible = await el.evaluate(e => {
            const style = window.getComputedStyle(e);
            return style.display !== 'none' && style.visibility !== 'hidden' && e.offsetParent !== null;
          });
          if (isVisible) {
            await el.click();
            return true;
          }
        }
      }
    } catch {
      continue;
    }
  }
  return false;
}

async function getPageText() {
  return await page.evaluate(() => document.body.innerText || document.body.textContent || '');
}

async function typeInInput(selector, text) {
  const inputs = await page.$$(selector);
  for (const input of inputs) {
    const isVisible = await input.evaluate(e => {
      const style = window.getComputedStyle(e);
      return style.display !== 'none' && style.visibility !== 'hidden';
    });
    if (isVisible) {
      await input.click({ clickCount: 3 });
      await input.type(text);
      return true;
    }
  }
  return false;
}

