import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';
const jsonHeaders = { 'content-type': 'application/json' };

async function safeJson(res) {
  const text = await res.text();
  try {
    return text ? JSON.parse(text) : null;
  } catch {
    return { raw: text };
  }
}

async function safeDelete(path) {
  try {
    await fetch(`${BASE_URL}${path}`, { method: 'DELETE' });
  } catch {
    // ignore cleanup failures
  }
}

function uniqueName(prefix) {
  return `${prefix}-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
}

async function tryPost(paths, body) {
  for (const p of paths) {
    try {
      const res = await fetch(`${BASE_URL}${p}`, {
        method: 'POST',
        headers: jsonHeaders,
        body: JSON.stringify(body),
      });
      const json = await safeJson(res);
      if (res.status !== 404 || p === paths[paths.length - 1]) {
        return { res, json, usedPath: p };
      }
    } catch {
      continue;
    }
  }
  const res = await fetch(`${BASE_URL}${paths[0]}`, {
    method: 'POST',
    headers: jsonHeaders,
    body: JSON.stringify(body),
  });
  return { res, json: await safeJson(res), usedPath: paths[0] };
}

async function tryGet(paths) {
  for (const p of paths) {
    try {
      const res = await fetch(`${BASE_URL}${p}`);
      const json = await safeJson(res);
      if (res.status !== 404 || p === paths[paths.length - 1]) {
        return { res, json, usedPath: p };
      }
    } catch {
      continue;
    }
  }
  const res = await fetch(`${BASE_URL}${paths[0]}`);
  return { res, json: await safeJson(res), usedPath: paths[0] };
}

describe('validate_track_rules_and_legacy_defaults', () => {
  it('rejects tracks with multiple starts or finishes', async () => {
    const invalidTrack = {
      name: uniqueName('track-multi-start-finish'),
      layout: {
        width: 5,
        height: 5,
        tiles: [
          ['start', 'road', 'finish', 'road', 'wall'],
          ['road', 'road', 'road', 'road', 'wall'],
          ['start', 'road', 'road', 'road', 'wall'],
          ['road', 'road', 'road', 'finish', 'wall'],
          ['wall', 'wall', 'wall', 'wall', 'wall']
        ],
        start: [{ x: 0, y: 0 }, { x: 0, y: 2 }],
        finish: [{ x: 2, y: 0 }, { x: 3, y: 3 }],
      }
    };

    const result = await tryPost(['/api/tracks', '/tracks'], invalidTrack);

    if ([200, 201].includes(result.res.status)) {
      const badId = result.json?.id ?? result.json?.trackId;
      if (badId) {
        try {
          const validateResult = await tryPost(
            [`/api/tracks/${badId}/validate`, `/tracks/${badId}/validate`],
            {}
          );
          if (validateResult.res.status === 200) {
            const canStart = validateResult.json?.canStart ?? validateResult.json?.playable ?? validateResult.json?.valid;
            expect(canStart, 'multi start+finish track should not be playable').toBe(false);
          } else {
            expect([400, 422].includes(validateResult.res.status), `expected validation rejection for multi start+finish`).toBe(true);
          }
        } finally {
          await safeDelete(`/api/tracks/${badId}`);
          await safeDelete(`/tracks/${badId}`);
        }
      }
