import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';
const jsonHeaders = { 'Content-Type': 'application/json' };

async function safeJson(response) {
  const text = await response.text();
  try {
    return text ? JSON.parse(text) : null;
  } catch {
    return { raw: text };
  }
}

async function safeDelete(url) {
  try {
    await fetch(url, { method: 'DELETE' });
  } catch {}
}

function uniqueName(prefix) {
  return `${prefix}-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
}

function buildLargeString(size) {
  return 'X'.repeat(size);
}

function buildNormalTrackPayload() {
  return {
    name: uniqueName('verifier-normal-track'),
    description: 'normal sized verifier track payload',
    layout: {
      width: 4,
      height: 2,
      tiles: [
        ['start', 'road', 'road', 'finish'],
        ['road', 'road', 'road', 'road']
      ],
      segments: [
        { type: 'straight', length: 120 },
        { type: 'curve', radius: 40, angle: 90 },
        { type: 'straight', length: 80 }
      ],
      checkpoints: [
        { x: 0, y: 0 },
        { x: 120, y: 0 },
        { x: 160, y: 40 }
      ]
    },
    weather: {
      preset: 'clear'
    }
  };
}

function buildHugeTrackPayload() {
  return {
    name: uniqueName('verifier-huge-track'),
    description: 'intentionally oversized payload to verify explicit limit/degradation handling',
    layout: {
      encoded: buildLargeString(2_000_000)
    },
    weather: {
      preset: 'storm'
    }
  };
}

async function createTrack(payload) {
  const response = await fetch(`${BASE_URL}/tracks`, {
    method: 'POST',
    headers: jsonHeaders,
    body: JSON.stringify(payload)
  });
  const body = await safeJson(response);
  return { response, body };
}

async function getTrack(id) {
  const response = await fetch(`${BASE_URL}/tracks/${id}`);
  const body = await safeJson(response);
  return { response, body };
}

function matchesLimitSignal(text) {
  return /limit|too large|payload too large|oversize|oversized|degrad|reject|max|exceed|quota|truncat|partial|lite|reduced|simplified|paginat/.test((text || '').toLowerCase());
}

describe('round20_large_content_degradation_limits', () => {
  it('normal-sized track content works correctly', async () => {
    const normalPayload = buildNormalTrackPayload();
    const { response: normalResponse, body: normalBody } = await createTrack(normalPayload);

    expect(
      [200, 201].includes(normalResponse.status),
      `Normal-sized track should be accepted with 200/201, got ${normalResponse.status} and body ${JSON.stringify(normalBody)}`
    ).toBe(true);

    expect(normalBody).toBeTruthy();
    expect(typeof normalBody).toBe('object');

    const normalId = normalBody.id ?? normalBody.trackId ?? normalBody.data?.id;
    expect(normalId, `Normal-sized track creation should return an id, got body ${JSON.stringify(normalBody)}`).toBeTruthy();

    try {
      // Verify normal content is not marked as degraded
      const normalStatus = String(normalBody.status ?? normalBody.state ?? normalBody.result ?? '').toLowerCase();
      expect(
        !matchesLimitSignal(normalStatus),
        `Normal-sized content should not be marked as degraded/limited; got "${normalStatus}"`
      ).toBe(true);

      // Fetch it back
      const { response: fetchedRes, body: fetchedBody } = await getTrack(normalId);
      expect([200, 204]).toContain(fetchedRes.status);
      if (fetchedRes.status !== 204 && fetchedBody) {
        const fetchedName = fetchedBody.name ?? fetchedBody.data?.name;
        if (fetchedName !== undefined) {
          expect(fetchedName).toBe(normalPayload.name);
        }
      }
    } finally {
      await safeDelete(`${BASE_URL}/tracks/${normalId}`);
    }
  });

  it('oversized track creation is explicitly rejected or marked with a degradation signal', async () => {
    const hugePayload = buildHugeTrackPayload();
    const { response: hugeResponse, body: hugeBody } = await createTrack(hugePayload);
    const signalText = JSON.stringify(hugeBody || {}).toLowerCase();

    const oversizedRejected = [400, 413, 422].includes(hugeResponse.status);
    const oversizedAcceptedWithSignal = [200, 201, 202].includes(hugeResponse.status);

    expect(
      oversizedRejected || oversizedAcceptedWithSignal,
      `Oversized content should be rejected or accepted with degradation signal; got status ${hugeResponse.status}`
    ).toBe(true);

    if (oversizedRejected) {
      expect(hugeBody, 'Rejected oversized request should provide a response body with a reason').toBeTruthy();
      expect(
        matchesLimitSignal(signalText),
        `Rejected oversized content should include an explicit limit-related reason; got body ${JSON.stringify(hugeBody)}`
      ).toBe(true);
    }

    if (oversizedAcceptedWithSignal) {
      expect(hugeBody).toBeTruthy();
      const hugeId = hugeBody.id ?? hugeBody.trackId ?? hugeBody.data?.id;

      try {
        expect(
          matchesLimitSignal(signalText),
          `Oversized accepted content should expose a recognizable degradation/limit signal; got body ${JSON.stringify(hugeBody)}`
        ).toBe(true);
      } finally {
        if (hugeId) {
          await safeDelete(`${BASE_URL}/tracks/${hugeId}`);
        }
      }
    }
  });

  it('oversized import data is explicitly rejected with a clear limit reason', async () => {
    // Try the import endpoint first; fall back to POST /tracks if import doesn't exist
    const hugeImportData = buildLargeString(2_000_000);

    // Attempt import via dedicated import endpoint
    const importRes = await fetch(`${BASE_URL}/tracks/import`, {
      method: 'POST',
      headers: jsonHeaders,
      body: JSON.stringify({ data: hugeImportData, name: uniqueName('huge-import') })
    });
    const importBody = await safeJson(importRes);

    if (importRes.status === 404) {
      // Import endpoint doesn't exist; verify via regular creation (already tested above)
      // Just ensure the large payload via normal create is handled
      const createRes = await fetch(`${BASE_URL}/tracks`, {
        method: 'POST',
        headers: jsonHeaders,
        body: JSON.stringify({
          name: uniqueName('huge-import-fallback'),
          layout: { encoded: hugeImportData }
        })
      });
      const createBody = await safeJson(createRes);
      expect(
        [400, 413, 422, 200, 201, 202].includes(createRes.status),
        `Oversized import fallback should get meaningful status, got ${createRes.status}`
      ).toBe(true);
      if ([400, 413, 422].includes(createRes.status)) {
        expect(matchesLimitSignal(JSON.stringify(createBody))).toBe(true);
      }
      const fbId = createBody?.id ?? createBody?.trackId;
      if (fbId) await safeDelete(`${BASE_URL}/tracks/${fbId}`);
    } else {
      // Import endpoint exists
      expect(
        [400, 413, 422].includes(importRes.status) || [200, 201, 202].includes(importRes.status),
        `Import of oversized data should be rejected or accepted with signal; got ${importRes.status}`
      ).toBe(true);
      if ([400, 413, 422].includes(importRes.status)) {
        expect(
          matchesLimitSignal(JSON.stringify(importBody)),
          `Oversized import rejection should mention limit/size reason; got ${JSON.stringify(importBody)}`
        ).toBe(true);
      }
      const impId = importBody?.id ?? importBody?.trackId;
      if (impId) await safeDelete(`${BASE_URL}/tracks/${impId}`);
    }
  });

  it('super long leaderboard triggers degradation/pagination/truncation signal', async () => {
    // Create a normal track to attach scores to
    const trackPayload = buildNormalTrackPayload();
    const { response: trackRes, body: trackBody } = await createTrack(trackPayload);
    expect([200, 201]).toContain(trackRes.status);
    const trackId = trackBody.id ?? trackBody.trackId ?? trackBody.data?.id;
    expect(trackId).toBeTruthy();

    const createdScoreIds = [];

    try {
      // Submit many scores to build a long leaderboard
      const scoreCount = 200;
      const submissions = [];
      for (let i = 0; i < scoreCount; i++) {
        submissions.push(
          fetch(`${BASE_URL}/scores`, {
            method: 'POST',
            headers: jsonHeaders,
            body: JSON.stringify({
              trackId,
              nickname: `racer-${i}-${Date.now()}`,
              weather: 'clear',
              timeMs: 10000 + i * 100,
              valid: true
            })
          }).then(async (res) => {
            const b = await safeJson(res);
            if ([200, 201].includes(res.status)) {
              const sid = b?.id ?? b?.scoreId;
              if (sid) createdScoreIds.push(sid);
            }
            return { status: res.status, body: b };
          })
        );
      }
      await Promise.all(submissions);

      // Query leaderboard – expect pagination, truncation, or degradation signal
      const lbRes = await fetch(`${BASE_URL}/leaderboards?trackId=${encodeURIComponent(trackId)}&weather=clear`);
      const lbBody = await safeJson(lbRes);
      expect(lbRes.status).toBe(200);

      const entries = Array.isArray(lbBody) ? lbBody : (lbBody?.entries ?? lbBody?.items ?? lbBody?.data ?? []);
      const lbStr = JSON.stringify(lbBody || {}).toLowerCase();

      // Either the list is truncated (fewer entries than submitted) or there's a pagination/degradation signal
      const isTruncated = Array.isArray(entries) && entries.length < scoreCount;
      const hasSignal = matchesLimitSignal(lbStr) ||
        lbBody?.totalPages !== undefined ||
        lbBody?.nextPage !== undefined ||
        lbBody?.hasMore !== undefined ||
        lbBody?.total !== undefined ||
        lbBody?.page !== undefined;

      expect(
        isTruncated || hasSignal,
        `Long leaderboard should show truncation/pagination/degradation; got ${entries.length} entries out of ${scoreCount} submitted. Body keys: ${Object.keys(lbBody || {})}`
      ).toBe(true);
    } finally {
      await safeDelete(`${BASE_URL}/tracks/${trackId}`);
    }
  });

  it('oversized ghost record data is rejected or triggers degradation signal', async () => {
    // Create a normal track first
    const trackPayload = buildNormalTrackPayload();
    const { response: trackRes, body: trackBody } = await createTrack(trackPayload);
    expect([200, 201]).toContain(trackRes.status);
    const trackId = trackBody.id ?? trackBody.trackId ?? trackBody.data?.id;
    expect(trackId).toBeTruthy();

    try {
      // Build an oversized ghost record
      const hugeGhostData = [];
      for (let i = 0; i < 500000; i++) {
        hugeGhostData.push({ t: i * 16, x: Math.random() * 1000, y: Math.random() * 1000, angle: Math.random() * 360 });
      }

      // Try submitting via a ghost-specific endpoint first
      const ghostRes = await fetch(`${BASE_URL}/ghosts`, {
        method: 'POST',
        headers: jsonHeaders,
        body: JSON.stringify({
          trackId,
          nickname: uniqueName('ghost-huge'),
          timeMs: 5000,
          frames: hugeGhostData
        })
      });
      const ghostBody = await safeJson(ghostRes);

      if (ghostRes.status === 404) {
        // Ghost endpoint may be embedded in scores
        const scoreRes = await fetch(`${BASE_URL}/scores`, {
          method: 'POST',
          headers: jsonHeaders,
          body: JSON.stringify({
            trackId,
            nickname: uniqueName('ghost-huge-score'),
            weather: 'clear',
            timeMs: 5000,
            valid: true,
            ghost: hugeGhostData
          })
        });
        const scoreBody = await safeJson(scoreRes);
        const scoreStr = JSON.stringify(scoreBody || {}).toLowerCase();

        // Should either reject or accept with degradation signal
        expect(
          [400, 413, 422].includes(scoreRes.status) ||
          [200, 201, 202].includes(scoreRes.status),
          `Oversized ghost via scores should get meaningful status, got ${scoreRes.status}`
        ).toBe(true);

        if ([400, 413, 422].includes(scoreRes.status)) {
          expect(
            matchesLimitSignal(scoreStr),
            `Oversized ghost rejection should include limit reason; got ${JSON.stringify(scoreBody)}`
          ).toBe(true);
        } else if ([200, 201, 202].includes(scoreRes.status)) {
          // Check for degradation signal in body
          const hasGhostDegradation = matchesLimitSignal(scoreStr) ||
            scoreBody?.ghostAvailable === false ||
            scoreBody?.ghostTruncated === true ||
            /ghost/.test(scoreStr);
          // At minimum, the endpoint should handle it without server error
          expect(scoreRes.status).toBeLessThan(500);
        }
      } else {
        // Ghost endpoint exists
        const ghostStr = JSON.stringify(ghostBody || {}).toLowerCase();
        expect(
          [400, 413, 422, 200, 201, 202].includes(ghostRes.status),
          `Oversized ghost data should get meaningful status, got ${ghostRes.status}`
        ).toBe(true);

        if ([400, 413, 422].includes(ghostRes.status)) {
          expect(
            matchesLimitSignal(ghostStr),
            `Oversized ghost rejection should include limit reason; got ${JSON.stringify(ghostBody)}`
          ).toBe(true);
        } else {
          // Accepted – should contain degradation signal
          expect(
            matchesLimitSignal(ghostStr),
            `Oversized ghost accepted but should expose degradation signal; got ${JSON.stringify(ghostBody)}`
          ).toBe(true);
        }

        const gId = ghostBody?.id ?? ghostBody?.ghostId;
        if (gId) await safeDelete(`${BASE_URL}/ghosts/${gId}`);
      }
    } finally {
      await safeDelete(`${BASE_URL}/tracks/${trackId}`);
    }
  });

  it('normal score submission still works correctly under normal conditions', async () => {
    const trackPayload = buildNormalTrackPayload();
    const { response: trackRes, body: trackBody } = await createTrack(trackPayload);
    expect([200, 201]).toContain(trackRes.status);
    const trackId = trackBody.id ?? trackBody.trackId ?? trackBody.data?.id;
