import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function request(method, path, body) {
  const res = await fetch(`${BASE_URL}${path}`, {
    method,
    headers: { 'Content-Type': 'application/json' },
    body: body === undefined ? undefined : JSON.stringify(body),
  });
  let json = null;
  try {
    json = await res.json();
  } catch {
    json = null;
  }
  return { res, json };
}

function uniqueName(prefix) {
  return `${prefix}-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
}

function extractId(data) {
  if (!data || typeof data !== 'object') return null;
  return data.id || data.trackId || data.scoreId || data.recordId || data.runId || data.data?.id || null;
}

function extractItems(data) {
  if (Array.isArray(data)) return data;
  if (!data || typeof data !== 'object') return [];
  return data.entries || data.items || data.records || data.data?.entries || data.data?.items || data.data?.records || [];
}

describe('round11_leaderboard_mode_filtering', () => {
  it('should separate manual and autodrive leaderboard records, keep official board to valid manual completions, handle empty nicknames, sync count on filter change, and show new record highlights', async () => {
    let trackId;
    const manualName = uniqueName('manual');
    const autoName = uniqueName('auto');
    const failedManual = uniqueName('failed-manual');

    try {
      // Create track
      const track = await request('POST', '/api/tracks', {
        name: uniqueName('filter-track'),
        weather: 'sunny',
        width: 3,
        height: 2,
        layout: [
          ['start', 'road', 'road'],
          ['road', 'road', 'finish']
        ],
      });
      expect([200, 201]).toContain(track.res.status);
      trackId = extractId(track.json);
      expect(trackId, `expected created track id, got ${JSON.stringify(track.json)}`).toBeTruthy();

      const submitPath = '/api/leaderboard';

      // 1. Valid manual run
      const manualRun = await request('POST', submitPath, {
        trackId,
        nickname: manualName,
        mode: 'manual',
        weather: 'sunny',
        valid: true,
        finished: true,
        status: 'finished',
        timeMs: 8000,
        autoDemo: false,
        isAutoDemo: false,
      });
      expect([200, 201]).toContain(manualRun.res.status);

      // 2. Failed manual run
      const failedRun = await request('POST', submitPath, {
        trackId,
        nickname: failedManual,
        mode: 'manual',
        weather: 'sunny',
        valid: false,
        finished: false,
        status: 'failed',
        timeMs: 12000,
        autoDemo: false,
      });
      // Failed runs may be rejected at submission or accepted and filtered at query
      expect([200, 201, 400, 422]).toContain(failedRun.res.status);

      // 3. Empty nickname run (boundary: should not appear in official)
      const emptyNickRun = await request('POST', submitPath, {
        trackId,
        nickname: '',
        mode: 'manual',
        weather: 'sunny',
        valid: true,
        finished: true,
        status: 'finished',
        timeMs: 7000,
        autoDemo: false,
      });
      if (emptyNickRun.res.status >= 400) {
        // Rejected at submit — verify error message
        expect([400, 422]).toContain(emptyNickRun.res.status);
        expect(JSON.stringify(emptyNickRun.json).toLowerCase()).toMatch(/nickname|name|empty|required/);
      }
      // Either way, will verify not in official board below

      // 4. Autodrive/auto-demo run
      const autoRun = await request('POST', submitPath, {
        trackId,
        nickname: autoName,
        mode: 'autoplay',
        weather: 'sunny',
        valid: true,
        finished: true,
        status: 'finished',
        timeMs: 6000,
        autoDemo: true,
        isAutoDemo: true,
        inputSequence: ['accelerate', 'straight', 'brake'],
      });
      expect([200, 201]).toContain(autoRun.res.status);

      // === Official leaderboard ===
      const officialBoard = await request('GET', `/api/leaderboard?trackId=${encodeURIComponent(trackId)}&weather=sunny`);
      expect(officialBoard.res.status).toBe(200);
      const officialEntries = extractItems(officialBoard.json);
      expect(Array.isArray(officialEntries)).toBe(true);

      // Valid manual result must be present
      expect(officialEntries.some((e) => (e.nickname || e.playerName || e.name) === manualName),
        `expected official board to include valid manual result ${manualName}`).toBe(true);
      // Autodrive must NOT be present
      expect(officialEntries.some((e) => (e.nickname || e.playerName || e.name) === autoName),
        `expected official board not to include autodrive result ${autoName}`).toBe(false);
      // Failed must NOT be present
      expect(officialEntries.some((e) => (e.nickname || e.playerName || e.name) === failedManual),
        `expected official board not to include failed result ${failedManual}`).toBe(false);
      // Empty nickname must NOT be present
      const hasEmptyNick = officialEntries.some((e) => {
        const n = e.nickname || e.playerName || e.name;
