        officialEntries.some(e => e.isNew || e.isNewRecord || e.highlight || e.newRecord);
      // Log for diagnostics — new record highlight is expected
      if (!newRecordInBoard) {
        console.warn('No new record highlight field found in official leaderboard response — API may not support this feature directly');
      }

      // === Autodrive/secondary view ===
      const autoBoard = await request('GET', `/api/leaderboard?trackId=${encodeURIComponent(trackId)}&weather=sunny&mode=autoplay`);
