      // Manual result should NOT appear in autodrive view
      expect(autoEntries.some((e) => (e.nickname || e.playerName || e.name) === manualName),
        `expected autodrive board not to include manual result ${manualName}`).toBe(false);

      // Count for auto board — require it to exist, same as official
      const autoCount = autoBoard.json?.count ?? autoBoard.json?.total ?? autoBoard.json?.totalCount;
      expect(autoCount, 'autodrive board should have a count/total field').toBeDefined();
      expect(typeof autoCount).toBe('number');
      expect(autoCount).toBe(autoEntries.length);

    } finally {
