import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function request(method, path, body) {
  const res = await fetch(`${BASE_URL}${path}`, {
    method,
    headers: { 'Content-Type': 'application/json' },
    body: body === undefined ? undefined : JSON.stringify(body),
  });
  let json = null;
  try {
    json = await res.json();
  } catch {
    json = null;
  }
  return { res, json };
}

function uniqueName(prefix) {
  return `${prefix}-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
}

async function tryMultipleEndpoints(method, paths, body) {
  for (const p of paths) {
    try {
      const result = await request(method, p, body);
      if (result.res.status !== 404 || p === paths[paths.length - 1]) {
        return { ...result, usedPath: p };
      }
    } catch {
      continue;
    }
  }
  return request(method, paths[0], body);
}

async function createTrack(body) {
  return tryMultipleEndpoints('POST', ['/api/tracks', '/tracks'], body);
}

async function submitRun(body) {
  return tryMultipleEndpoints('POST', ['/api/runs', '/api/scores', '/runs', '/scores'], body);
}

async function getGhost(queryString) {
  return tryMultipleEndpoints('GET', [
    `/api/ghosts/best?${queryString}`,
    `/api/ghost/best?${queryString}`,
    `/api/ghosts?${queryString}`,
    `/ghosts/best?${queryString}`,
    `/ghosts?${queryString}`,
  ]);
}

async function restartSession(body) {
  return tryMultipleEndpoints('POST', [
    '/api/sessions/restart',
    '/api/races/restart',
    '/sessions/restart',
    '/races/restart',
  ], body);
}

async function getActiveGhost(queryString) {
  return tryMultipleEndpoints('GET', [
    `/api/sessions/active-ghost?${queryString}`,
    `/api/ghosts/active?${queryString}`,
    `/sessions/active-ghost?${queryString}`,
    `/ghosts/active?${queryString}`,
  ]);
}

async function modifyTrack(trackId, body) {
  const patchResult = await tryMultipleEndpoints('PATCH', [
    `/api/tracks/${trackId}`,
    `/tracks/${trackId}`,
  ], body);
  if (patchResult.res.status === 404 || patchResult.res.status === 405) {
    return tryMultipleEndpoints('PUT', [
      `/api/tracks/${trackId}`,
      `/tracks/${trackId}`,
    ], body);
  }
  return patchResult;
}

async function safeDelete(path) {
  try { await fetch(`${BASE_URL}${path}`, { method: 'DELETE' }); } catch {}
}

describe('round9_ghost_scoped_by_track_and_weather', () => {
  it('should return best ghost only for same track+weather, return nothing for no-history track, invalidate ghost after track modification, and reset ghost on restart', async () => {
    const ids = [];
    const driver = uniqueName('ghost-driver');

    try {
      // Step 1: Create track A with sunny weather
      const trackA = await createTrack({
        name: uniqueName('ghost-track-a'),
        weather: 'sunny',
        layout: {
          width: 5, height: 1,
          start: { x: 0, y: 0 },
          finish: { x: 4, y: 0 },
          tiles: [['start', 'road', 'road', 'road', 'finish']],
          segments: [{ x: 0, y: 0 }, { x: 4, y: 0 }],
        },
      });
      expect(trackA.res.status, `expected track A creation to return 200/201, got ${trackA.res.status}`).toBeOneOf([200, 201]);
      const trackAId = trackA.json?.id || trackA.json?.trackId;
      expect(trackAId, 'track A must have an id').toBeTruthy();
      ids.push(trackAId);

      // Step 2: Create track B with sunny weather
      const trackB = await createTrack({
        name: uniqueName('ghost-track-b'),
        weather: 'sunny',
        layout: {
          width: 5, height: 1,
          start: { x: 0, y: 0 },
          finish: { x: 4, y: 0 },
          tiles: [['start', 'road', 'road', 'road', 'finish']],
          segments: [{ x: 0, y: 0 }, { x: 4, y: 0 }],
        },
      });
      expect(trackB.res.status, `expected track B creation to return 200/201, got ${trackB.res.status}`).toBeOneOf([200, 201]);
      const trackBId = trackB.json?.id || trackB.json?.trackId;
      expect(trackBId, 'track B must have an id').toBeTruthy();
      ids.push(trackBId);

      // Step 3: Boundary - Query ghost for track A BEFORE any runs exist
      const ghostNoHistory = await getGhost(`trackId=${encodeURIComponent(trackAId)}&weather=sunny&nickname=${encodeURIComponent(driver)}`);
      if (ghostNoHistory.res.status === 200) {
        const ghostData = ghostNoHistory.json?.ghost || ghostNoHistory.json?.frames || ghostNoHistory.json?.data;
        const isEmpty = !ghostData || ghostData === null || (Array.isArray(ghostData) && ghostData.length === 0);
        expect(isEmpty, `expected no ghost for track with no history, but got non-empty data: ${JSON.stringify(ghostNoHistory.json)}`).toBe(true);
      } else {
        expect([204, 404].includes(ghostNoHistory.res.status), `expected 200-empty/204/404 for no-history ghost query, got ${ghostNoHistory.res.status}`).toBe(true);
      }

      // Step 4: Submit a valid run with ghost data on track A / sunny
      const runA = await submitRun({
        trackId: trackAId,
        nickname: driver,
        weather: 'sunny',
        valid: true,
        finished: true,
        status: 'finished',
        timeMs: 9000,
        ghost: { frames: [{ t: 0, x: 0, y: 0 }, { t: 9000, x: 4, y: 0 }] },
      });
      expect(runA.res.status, `expected valid run with ghost to return 200/201, got ${runA.res.status}`).toBeOneOf([200, 201]);

      // Step 5: Verify restart resets ghost BEFORE modifying the track
      const restart = await restartSession({
        trackId: trackAId,
        weather: 'sunny',
        nickname: driver,
      });
      expect(restart.res.status, `expected restart to return 200/201/204, got ${restart.res.status}`).toBeOneOf([200, 201, 204]);

      const activeGhost = await getActiveGhost(`trackId=${encodeURIComponent(trackAId)}&weather=sunny&nickname=${encodeURIComponent(driver)}`);
      if (activeGhost.res.status === 200 && activeGhost.json) {
        const state = activeGhost.json.state || activeGhost.json.status;
        const isActive = activeGhost.json.active;
        const position = activeGhost.json.position ?? activeGhost.json.currentFrame;
        const isReset = state === 'reset' || state === 'idle' || isActive === false || position === 0 || position === null || position === undefined;
        expect(isReset, `expected ghost to be reset after restart, got state=${state}, active=${isActive}, position=${position}`).toBe(true);
      }
      // 204 or 404 also acceptable

      // Step 6: Query ghost for same track + same weather - should still exist after restart
      const ghostSame = await getGhost(`trackId=${encodeURIComponent(trackAId)}&weather=sunny&nickname=${encodeURIComponent(driver)}`);
      expect(ghostSame.res.status, `expected same track/weather ghost lookup to return 200, got ${ghostSame.res.status}`).toBe(200);
      expect(ghostSame.json, 'expected same-scope ghost payload').toBeTruthy();

      // Step 7: Query ghost for same track + different weather - should NOT reuse sunny ghost
      const ghostDifferentWeather = await getGhost(`trackId=${encodeURIComponent(trackAId)}&weather=rainy&nickname=${encodeURIComponent(driver)}`);
      if (ghostDifferentWeather.res.status === 200) {
        // If 200 is returned, verify it's not the sunny ghost
        const gJson = ghostDifferentWeather.json;
        const hasGhostData = gJson && (gJson.ghost || gJson.frames || gJson.timeMs);
        if (hasGhostData) {
          // Must NOT be the sunny weather ghost
          const returnedWeather = gJson.weather || gJson.weatherPreset;
          expect(returnedWeather, `expected different weather query not to return sunny ghost, got weather=${returnedWeather}`).not.toBe('sunny');
        }
        // If no actual ghost data in 200, that's fine (empty result)
      } else {
        expect([204, 404].includes(ghostDifferentWeather.res.status), `expected 204/404 for different weather ghost query, got ${ghostDifferentWeather.res.status}`).toBe(true);
      }

      // Step 8: Query ghost for different track + same weather - should NOT reuse track A ghost
      const ghostDifferentTrack = await getGhost(`trackId=${encodeURIComponent(trackBId)}&weather=sunny&nickname=${encodeURIComponent(driver)}`);
      if (ghostDifferentTrack.res.status === 200) {
        const gJson = ghostDifferentTrack.json;
        const hasGhostData = gJson && (gJson.ghost || gJson.frames || gJson.timeMs);
        if (hasGhostData) {
          const returnedTrackId = gJson.trackId || gJson.track?.id || gJson.track;
          if (returnedTrackId) {
            expect(returnedTrackId, `expected different track query not to return track A ghost`).not.toBe(trackAId);
          }
        }
      } else {
        expect([204, 404].includes(ghostDifferentTrack.res.status), `expected 204/404 for different track ghost query, got ${ghostDifferentTrack.res.status}`).toBe(true);
      }

      // Step 9: Modify track A content to invalidate old ghost
      await modifyTrack(trackAId, {
        name: uniqueName('ghost-track-a-modified'),
        weather: 'sunny',
        layout: {
          width: 6, height: 1,
          start: { x: 0, y: 0 },
          finish: { x: 5, y: 0 },
          tiles: [['start', 'road', 'road', 'road', 'road', 'finish']],
          segments: [{ x: 0, y: 0 }, { x: 5, y: 0 }],
        },
      });

      // After modification, old ghost should not be blindly reused
      const ghostAfterModify = await getGhost(`trackId=${encodeURIComponent(trackAId)}&weather=sunny&nickname=${encodeURIComponent(driver)}`);
      if (ghostAfterModify.res.status === 200 && ghostAfterModify.json) {
        const gJson = ghostAfterModify.json;
        const ghostFrames = gJson.ghost?.frames || gJson.frames;
        const returnedTimeMs = gJson.timeMs;
        // The old ghost with timeMs=9000 should NOT be returned as-is for the modified track
        // Either no data, or it should be marked invalid/stale
        if (ghostFrames && ghostFrames.length > 0 && returnedTimeMs === 9000) {
          const isInvalidated = gJson.invalidated === true || gJson.stale === true || gJson.valid === false;
          expect(isInvalidated, `old ghost (timeMs=9000) should not be blindly reused after track modification without invalidation marker`).toBe(true);
        }
        // If timeMs is not 9000 or frames are empty, that's acceptable (ghost was cleared or replaced)
      }
      // 404 or 204 are also acceptable (ghost cleared after track modification)

    } finally {
      for (const id of ids.filter(Boolean)) {
        await safeDelete(`/api/tracks/${id}`);
        await safeDelete(`/tracks/${id}`);
      }
    }
  });
});

import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';
const jsonHeaders = { 'content-type': 'application/json' };

async function safeJson(res) {
  const text = await res.text();
  try {
    return text ? JSON.parse(text) : null;
  } catch {
    return { raw: text };
  }
}

async function safeDelete(path) {
  try {
    await fetch(`${BASE_URL}${path}`, { method: 'DELETE' });
  } catch {}
}

