describe('round3_leaderboard_persistence', () => {
  it('stores valid nickname submission and excludes invalid leaderboard records', async () => {
    const trackPayload = {
      name: uniqueName('round3-track'),
      weather: 'sunny',
      layout: {
        width: 4,
        height: 2,
        tiles: [
          ['start', 'road', 'road', 'finish'],
          ['road', 'road', 'road', 'road']
        ]
      }
    };

    const createTrackRes = await fetch(`${BASE_URL}/tracks`, {
      method: 'POST',
      headers: jsonHeaders,
      body: JSON.stringify(trackPayload)
    });
    const createTrackBody = await safeJson(createTrackRes);
    expect([200, 201]).toContain(createTrackRes.status);
    const trackId = createTrackBody.id ?? createTrackBody.trackId;
    expect(trackId).toBeTruthy();

    try {
      const validNick = uniqueName('nick').slice(0, 16);
      const validRes = await fetch(`${BASE_URL}/scores`, {
        method: 'POST',
        headers: jsonHeaders,
        body: JSON.stringify({ trackId, nickname: validNick, weather: 'sunny', timeMs: 1000, valid: true })
      });
      const validBody = await safeJson(validRes);
      expect([200, 201]).toContain(validRes.status);
      expect(validBody.nickname).toBe(validNick);

      const emptyRes = await fetch(`${BASE_URL}/scores`, {
        method: 'POST',
        headers: jsonHeaders,
        body: JSON.stringify({ trackId, nickname: '', weather: 'sunny', timeMs: 900, valid: true })
      });
      expect([400, 409, 422]).toContain(emptyRes.status);

      const tooLongRes = await fetch(`${BASE_URL}/scores`, {
        method: 'POST',
        headers: jsonHeaders,
        body: JSON.stringify({ trackId, nickname: 'z'.repeat(300), weather: 'sunny', timeMs: 800, valid: true })
      });
