      const failedRunRes = await fetch(`${BASE_URL}/scores`, {
        method: 'POST',
        headers: jsonHeaders,
        body: JSON.stringify({ trackId, nickname: 'failed-run', weather: 'sunny', timeMs: 700, valid: false })
      });
      const failedRunBody = await safeJson(failedRunRes);
      expect([200, 201, 400, 409, 422]).toContain(failedRunRes.status);
      if ([200, 201].includes(failedRunRes.status)) {
        expect(failedRunBody.valid ?? false).toBe(false);
      }

      const leaderboardRes = await fetch(`${BASE_URL}/leaderboards?trackId=${encodeURIComponent(trackId)}&weather=sunny`);
      const leaderboardBody = await safeJson(leaderboardRes);
      expect(leaderboardRes.status).toBe(200);
      const entries = Array.isArray(leaderboardBody) ? leaderboardBody : (leaderboardBody.entries ?? leaderboardBody.items ?? []);
      expect(Array.isArray(entries)).toBe(true);
      expect(entries.some((e) => e.nickname === validNick)).toBe(true);
      expect(entries.some((e) => e.nickname === '')).toBe(false);
      expect(entries.some((e) => e.nickname === 'failed-run')).toBe(false);

      const leaderboardRes2 = await fetch(`${BASE_URL}/leaderboards?trackId=${encodeURIComponent(trackId)}&weather=sunny`);
      const leaderboardBody2 = await safeJson(leaderboardRes2);
      expect(leaderboardRes2.status).toBe(200);
      const entries2 = Array.isArray(leaderboardBody2) ? leaderboardBody2 : (leaderboardBody2.entries ?? leaderboardBody2.items ?? []);
      expect(entries2.some((e) => e.nickname === validNick)).toBe(true);
    } finally {
      await safeDelete(`/tracks/${trackId}`);
    }
  });
});

