import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function request(method, path, body, headers = {}) {
  const res = await fetch(`${BASE_URL}${path}`, {
    method,
    headers: { 'Content-Type': 'application/json', ...headers },
    body: body === undefined ? undefined : JSON.stringify(body),
  });
  const text = await res.text();
  let data = null;
  try { data = text ? JSON.parse(text) : null; } catch { data = text; }
  return { res, data, text };
}

async function safeDelete(path) {
  try { await fetch(`${BASE_URL}${path}`, { method: 'DELETE' }); } catch {}
}

function extractId(data) {
  if (!data || typeof data !== 'object') return null;
  return data.id || data.trackId || data.data?.id || data.data?.trackId || null;
}

describe('import_export_track_preserves_layout_and_validation', () => {
  it('exports then imports a track preserving key fields, validates playability, and rejects malformed imports without overwriting valid state', async () => {
    const createdIds = [];

    try {
      // === Create source track with all fields ===
      const sourceTrack = {
        name: `exportable-${Date.now()}`,
        width: 5,
        height: 4,
        weather: 'rain',
        weatherPreset: 'rain',
        terrain: 'normal',
        layout: [
          ['start', 'road', 'checkpoint', 'road', 'road'],
          ['road', 'mud', 'road', 'oil', 'road'],
          ['road', 'road', 'checkpoint', 'road', 'road'],
          ['road', 'road', 'road', 'road', 'finish']
        ],
        checkpoints: [
          { order: 1, x: 2, y: 0 },
          { order: 2, x: 2, y: 2 }
        ]
      };

      const createRes = await request('POST', '/api/tracks', sourceTrack);
      expect([200, 201]).toContain(createRes.res.status);
      const trackId = extractId(createRes.data);
      expect(trackId, `expected track id, got: ${JSON.stringify(createRes.data)}`).toBeTruthy();
      createdIds.push(trackId);

      // === Export track ===
      const exportRes = await request('GET', `/api/tracks/${trackId}/export`);
      expect(exportRes.res.status).toBe(200);
      expect(exportRes.data).toBeTruthy();
      const exported = exportRes.data.track || exportRes.data.data || exportRes.data;
      expect(exported.name).toBe(sourceTrack.name);
      expect(exported.weather).toBe('rain');
      expect(exported.terrain).toBe('normal');
      expect(exported.layout).toEqual(sourceTrack.layout);
      expect(exported.checkpoints).toEqual(sourceTrack.checkpoints);
      // Verify weather preset is preserved in export
      const exportedPreset = exported.weatherPreset || exported.weather;
      expect(exportedPreset).toBeTruthy();

      // === Import the exported track ===
      const importRes = await request('POST', '/api/tracks/import', exported);
      expect([200, 201]).toContain(importRes.res.status);
      const importedId = extractId(importRes.data);
      expect(importedId, `expected imported track id, got: ${JSON.stringify(importRes.data)}`).toBeTruthy();
      createdIds.push(importedId);

      // Verify imported track matches
      const importedGet = await request('GET', `/api/tracks/${importedId}`);
      expect(importedGet.res.status).toBe(200);
      const importedData = importedGet.data.data || importedGet.data;
      expect(importedData.layout).toEqual(sourceTrack.layout);
      expect(importedData.weather).toBe('rain');
      expect(importedData.terrain).toBe('normal');
      expect(importedData.checkpoints).toEqual(sourceTrack.checkpoints);

      // Validate playability — must be verified, not conditionally skipped
      const playableField = importedData.playable ?? importedData.valid ?? importedData.isPlayable;
      if (playableField !== undefined) {
        expect(playableField, 'imported track should be playable').toBeTruthy();
      } else {
        // Try dedicated validate endpoint
        const validateRes = await request('POST', `/api/tracks/${importedId}/validate`, {});
        expect([200, 204].includes(validateRes.res.status), `validate endpoint should succeed, got ${validateRes.res.status}`).toBe(true);
        if (validateRes.data && typeof validateRes.data === 'object') {
          const validField = validateRes.data.valid ?? validateRes.data.playable;
          expect(validField, 'imported track should be playable after validation').toBeTruthy();
        }
      }

      // === Boundary: Various malformed imports ===
      const importPath = '/api/tracks/import';

      // 1. Completely broken format
      const badFormat = await request('POST', importPath, { broken: true });
      expect([400, 409, 422]).toContain(badFormat.res.status);
      expect(JSON.stringify(badFormat.data).toLowerCase()).toMatch(/error|invalid|missing|format/);

      // 2. Version field conflict — plausible but incompatible version
      const versionConflict = await request('POST', importPath, {
        name: 'version-conflict',
        version: 999,
        formatVersion: 'v999.0',
        width: 3,
        height: 2,
        layout: [
          ['start', 'road', 'road'],
          ['road', 'road', 'finish']
        ]
      });
      expect([400, 409, 422]).toContain(versionConflict.res.status);
      expect(JSON.stringify(versionConflict.data).toLowerCase()).toMatch(/version|incompatible|unsupported|error|invalid/);

      // 3. Missing start point
      const noStart = await request('POST', importPath, {
        name: 'no-start',
        width: 3,
        height: 2,
        layout: [
          ['road', 'road', 'road'],
          ['road', 'road', 'finish']
        ]
      });
      expect([400, 422]).toContain(noStart.res.status);
      expect(JSON.stringify(noStart.data).toLowerCase()).toMatch(/start|missing|invalid|error/);

      // 4. Missing finish/end point
      const noFinish = await request('POST', importPath, {
        name: 'no-finish',
        width: 3,
        height: 2,
        layout: [
          ['start', 'road', 'road'],
          ['road', 'road', 'road']
        ]
      });
      expect([400, 422]).toContain(noFinish.res.status);
      expect(JSON.stringify(noFinish.data).toLowerCase()).toMatch(/finish|end|missing|invalid|error/);

      // 5. Oversized layout
      const hugeLayout = Array.from({ length: 200 }, () => Array.from({ length: 200 }, () => 'road'));
      hugeLayout[0][0] = 'start';
      hugeLayout[199][199] = 'finish';
      const oversized = await request('POST', importPath, {
        name: 'oversized',
        width: 200,
        height: 200,
        layout: hugeLayout
      });
      expect([400, 413, 422]).toContain(oversized.res.status);
      expect(JSON.stringify(oversized.data).toLowerCase()).toMatch(/size|limit|large|exceed|error|invalid/);

      // 6. Unknown terrain type
      const unknownTerrain = await request('POST', importPath, {
        name: 'unknown-terrain',
        width: 3,
        height: 2,
        layout: [
          ['start', 'lava', 'road'],
          ['road', 'road', 'finish']
        ]
      });
      expect([400, 422]).toContain(unknownTerrain.res.status);
      expect(JSON.stringify(unknownTerrain.data).toLowerCase()).toMatch(/terrain|unknown|invalid|error|type/);

      // === Verify previously imported track is NOT corrupted after failed imports ===
      // (This verifies server-side data integrity — the closest API-level proxy for
      // "current editing state not being overwritten by failed imports")
      const stillThere = await request('GET', `/api/tracks/${importedId}`);
      expect(stillThere.res.status).toBe(200);
      const stillData = stillThere.data.data || stillThere.data;
      expect(stillData.layout).toEqual(sourceTrack.layout);
      expect(stillData.weather).toBe('rain');
      expect(stillData.terrain).toBe('normal');
      expect(stillData.checkpoints).toEqual(sourceTrack.checkpoints);

      // === Boundary: Import legacy data without weather/terrain/checkpoints ===
      const legacyData = {
        name: `legacy-import-${Date.now()}`,
        width: 3,
        height: 2,
        layout: [
          ['start', 'road', 'road'],
          ['road', 'road', 'finish']
        ]
        // NOTE: no weather, terrain, or checkpoints fields
      };
      const legacyImport = await request('POST', importPath, legacyData);
      expect([200, 201]).toContain(legacyImport.res.status);
      const legacyId = extractId(legacyImport.data);
      expect(legacyId, 'legacy import should return a track id').toBeTruthy();
      createdIds.push(legacyId);

      const legacyGet = await request('GET', `/api/tracks/${legacyId}`);
      expect(legacyGet.res.status).toBe(200);
      const legData = legacyGet.data.data || legacyGet.data;

      // Weather should default to sunny/clear
      expect(legData.weather, 'legacy import should have a default weather').toBeTruthy();
      expect(['sunny', 'clear', 'default', 'normal']).toContain(String(legData.weather).toLowerCase());

      // Terrain should have a default
      expect(legData.terrain !== undefined && legData.terrain !== null, 'legacy import should have a default terrain').toBe(true);

      // Checkpoints should default to empty array
      const cp = legData.checkpoints;
      expect(cp !== undefined && cp !== null, 'legacy import should have a checkpoints field').toBe(true);
      expect(Array.isArray(cp), 'checkpoints should be an array').toBe(true);
      expect(cp.length).toBe(0);

    } finally {
      for (const id of createdIds) {
        await safeDelete(`/api/tracks/${id}`);
      }
    }
  });
});

import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function request(method, path, body) {
  const res = await fetch(`${BASE_URL}${path}`, {
    method,
    headers: { 'Content-Type': 'application/json' },
    body: body === undefined ? undefined : JSON.stringify(body),
  });
  const text = await res.text();
  let data = null;
  try { data = text ? JSON.parse(text) : null; } catch { data = text; }
  return { res, data, text };
}

async function safeDelete(path) {
  try { await fetch(`${BASE_URL}${path}`, { method: 'DELETE' }); } catch {}
}

async function tryMultipleEndpoints(method, paths, body) {
  for (const p of paths) {
    try {
      const result = await request(method, p, body);
      if (result.res.status !== 404 || p === paths[paths.length - 1]) {
        return { ...result, usedPath: p };
      }
    } catch {
      continue;
    }
  }
  return request(method, paths[0], body);
}

async function submitScore(body) {
  return tryMultipleEndpoints('POST', ['/api/scores', '/api/runs', '/scores', '/runs'], body);
}

async function getLeaderboard(queryString) {
  return tryMultipleEndpoints('GET', [
    `/api/leaderboard?${queryString}`,
    `/api/leaderboards?${queryString}`,
    `/leaderboard?${queryString}`,
    `/leaderboards?${queryString}`,
  ]);
}

function extractEntries(data) {
  const entries = data?.entries || data?.records || data?.items || data || [];
  return Array.isArray(entries) ? entries : [];
}

describe('migrate_legacy_scores_to_default_sunny_group', () => {
  it('places legacy scores without weather into sunny group, verifies filtering by track/weather/type, stable tie ordering, and total count updates', async () => {
    let trackId;
    let trackId2;
    const scoreIds = [];
    const trackSuffix = Date.now();

    try {
      // Create main track
      const trackRes = await tryMultipleEndpoints('POST', ['/api/tracks', '/tracks'], {
        name: `legacy-score-track-${trackSuffix}`,
        width: 3,
        height: 3,
        weather: 'sunny',
        layout: {
          width: 3, height: 3,
          start: { x: 0, y: 0 },
          finish: { x: 2, y: 2 },
          tiles: [['start', 'road', 'road'], ['road', 'road', 'road'], ['road', 'road', 'finish']],
          segments: [{ x: 0, y: 0 }, { x: 1, y: 0 }, { x: 2, y: 0 }, { x: 2, y: 1 }, { x: 2, y: 2 }],
        },
      });
      expect([200, 201]).toContain(trackRes.res.status);
      trackId = trackRes.data.id || trackRes.data.trackId;
      expect(trackId).toBeTruthy();

      // Create second track for cross-track filtering
      const trackRes2 = await tryMultipleEndpoints('POST', ['/api/tracks', '/tracks'], {
        name: `other-track-${trackSuffix}`,
        width: 3,
        height: 3,
        weather: 'sunny',
        layout: {
          width: 3, height: 3,
          start: { x: 0, y: 0 },
          finish: { x: 2, y: 2 },
          tiles: [['start', 'road', 'road'], ['road', 'road', 'road'], ['road', 'road', 'finish']],
          segments: [{ x: 0, y: 0 }, { x: 1, y: 1 }, { x: 2, y: 2 }],
        },
      });
      expect([200, 201]).toContain(trackRes2.res.status);
      trackId2 = trackRes2.data.id || trackRes2.data.trackId;

      // Submit legacy score 1 WITHOUT weather field (simulating old data)
      const legacy1 = await submitScore({
        trackId,
        nickname: 'LegacyA',
        timeMs: 12345,
        valid: true,
        finished: true,
        status: 'finished',
      });
      expect([200, 201]).toContain(legacy1.res.status);
      if (legacy1.data?.id || legacy1.data?.scoreId) scoreIds.push(legacy1.data.id || legacy1.data.scoreId);

      // Submit legacy score 2 WITHOUT weather field, same time for tie testing
      const legacy2 = await submitScore({
        trackId,
        nickname: 'LegacyB',
        timeMs: 12345,
        valid: true,
        finished: true,
        status: 'finished',
      });
      expect([200, 201]).toContain(legacy2.res.status);
      if (legacy2.data?.id || legacy2.data?.scoreId) scoreIds.push(legacy2.data.id || legacy2.data.scoreId);

      // Submit rainy score WITH explicit weather
      const rainy = await submitScore({
        trackId,
        nickname: 'RainOnly',
        timeMs: 12000,
        weather: 'rainy',
        valid: true,
        finished: true,
        status: 'finished',
      });
      expect([200, 201]).toContain(rainy.res.status);
      if (rainy.data?.id || rainy.data?.scoreId) scoreIds.push(rainy.data.id || rainy.data.scoreId);

      // Submit auto-demo score (should not appear in official board)
      // Must assert submission succeeds so later exclusion check is meaningful
      const autoScore = await submitScore({
        trackId,
        nickname: 'AutoBot',
        timeMs: 11000,
        weather: 'sunny',
        valid: true,
        finished: true,
        status: 'finished',
        mode: 'auto',
        recordType: 'auto',
        isAutoDrive: true,
      });
      expect([200, 201]).toContain(autoScore.res.status);
      if (autoScore.data?.id || autoScore.data?.scoreId) scoreIds.push(autoScore.data.id || autoScore.data.scoreId);

      // Submit a score on the second track
      const otherTrackScore = await submitScore({
        trackId: trackId2,
        nickname: 'OtherTrackPlayer',
        timeMs: 10000,
        weather: 'sunny',
        valid: true,
        finished: true,
        status: 'finished',
      });
      expect([200, 201]).toContain(otherTrackScore.res.status);
      if (otherTrackScore.data?.id || otherTrackScore.data?.scoreId) scoreIds.push(otherTrackScore.data.id || otherTrackScore.data.scoreId);

      // Query sunny leaderboard for main track (official type)
      const sunnyBoard1 = await getLeaderboard(`trackId=${trackId}&weather=sunny&type=official&mode=official`);
      expect(sunnyBoard1.res.status).toBe(200);
      const entriesArr1 = extractEntries(sunnyBoard1.data);
      const names1 = entriesArr1.map(e => e.nickname);

      // Legacy scores (no weather) should appear in sunny group
      expect(names1, `expected sunny board to include LegacyA`).toContain('LegacyA');
      expect(names1, `expected sunny board to include LegacyB`).toContain('LegacyB');
      // Rainy score should NOT appear in sunny group
      expect(names1, `expected sunny board not to include RainOnly`).not.toContain('RainOnly');
      // Other track score should NOT appear
      expect(names1, `expected sunny board not to include OtherTrackPlayer`).not.toContain('OtherTrackPlayer');
      // Auto-demo score should NOT appear in official board
      expect(names1, `expected sunny official board not to include AutoBot`).not.toContain('AutoBot');

      // Verify each entry in sunny board has weather info
      for (const entry of entriesArr1) {
        const entryWeather = entry.weather || entry.weatherPreset;
        expect(entryWeather, `expected sunny board entry to have a weather field, got ${JSON.stringify(entry)}`).toBeTruthy();
        expect(entryWeather, `expected sunny board entry weather to be sunny, got ${entryWeather}`).toBe('sunny');
      }

      // Verify specific counts: sunny official should have exactly 2 legacy entries
      const legacyEntriesInSunny = entriesArr1.filter(e => e.nickname === 'LegacyA' || e.nickname === 'LegacyB');
      expect(legacyEntriesInSunny.length, 'expected exactly 2 legacy entries in sunny board').toBe(2);

      // Verify tie sorting stability: query twice and compare order
      const sunnyTied1 = entriesArr1.filter(e => e.timeMs === 12345).map(e => e.nickname);

      const sunnyBoard2 = await getLeaderboard(`trackId=${trackId}&weather=sunny&type=official&mode=official`);
      expect(sunnyBoard2.res.status).toBe(200);
      const entriesArr2 = extractEntries(sunnyBoard2.data);
      const sunnyTied2 = entriesArr2.filter(e => e.timeMs === 12345).map(e => e.nickname);
      // Same order both times
      expect(sunnyTied2, 'expected stable tie ordering across queries').toEqual(sunnyTied1);

      // Verify rainy board
      const rainBoard = await getLeaderboard(`trackId=${trackId}&weather=rainy&type=official&mode=official`);
      expect(rainBoard.res.status).toBe(200);
      const rainArr = extractEntries(rainBoard.data);
      const rainNames = rainArr.map(e => e.nickname);
      expect(rainNames, `expected rainy board to include RainOnly`).toContain('RainOnly');
      expect(rainNames, `expected rainy board not to include LegacyA`).not.toContain('LegacyA');

      // Verify specific total counts
      const sunnyCount = entriesArr1.length;
      const rainyCount = rainArr.length;
      expect(sunnyCount, 'expected sunny group to have at least 2 entries').toBeGreaterThanOrEqual(2);
      expect(rainyCount, 'expected rainy group to have at least 1 entry').toBeGreaterThanOrEqual(1);
      expect(sunnyCount, 'expected sunny total to differ from rainy total').not.toBe(rainyCount);

      // Verify auto-demo score is visible in secondary/auto view
      const autoBoard = await getLeaderboard(`trackId=${trackId}&weather=sunny&type=auto&mode=auto`);
      if (autoBoard.res.status === 200) {
        const autoEntries = extractEntries(autoBoard.data);
        const autoNames = autoEntries.map(e => e.nickname);
        expect(autoNames, 'expected auto view to include AutoBot').toContain('AutoBot');
      }
      // If no auto view endpoint returns 200, the auto scores may be stored internally
      // but the key check above already confirmed AutoBot is NOT in official board

      // Verify filtering by other track
      const otherTrackBoard = await getLeaderboard(`trackId=${trackId2}&weather=sunny&type=official&mode=official`);
      if (otherTrackBoard.res.status === 200) {
        const otherArr = extractEntries(otherTrackBoard.data);
        const otherNames = otherArr.map(e => e.nickname);
        expect(otherNames, `expected other track board not to include LegacyA`).not.toContain('LegacyA');
        expect(otherNames, `expected other track board not to include LegacyB`).not.toContain('LegacyB');
      }
    } finally {
      for (const id of scoreIds) {
        await safeDelete(`/api/scores/${id}`);
        await safeDelete(`/api/runs/${id}`);
        await safeDelete(`/scores/${id}`);
        await safeDelete(`/runs/${id}`);
      }
      if (trackId) {
        await safeDelete(`/api/tracks/${trackId}`);
