import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function request(path, init = {}) {
  const res = await fetch(`${BASE_URL}${path}`, {
    headers: {
      'content-type': 'application/json',
      ...(init.headers || {}),
    },
    ...init,
  });

  const contentType = res.headers.get('content-type') || '';
  let body = null;
  if (contentType.includes('application/json')) {
    body = await res.json();
  } else {
    body = await res.text();
  }

  return { res, body };
}

function trackName() {
  return `verifier-baseline-track-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
}

function extractId(body) {
  if (!body || typeof body !== 'object') return null;
  return body.id || body.trackId || body.data?.id || body.data?.trackId || null;
}

function extractLeaderboardItems(body) {
  if (Array.isArray(body)) return body;
  if (!body || typeof body !== 'object') return [];
  return body.items || body.records || body.entries || body.data?.items || body.data?.records || body.data?.entries || [];
}

