import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';
const jsonHeaders = { 'content-type': 'application/json' };

async function safeJson(res) {
  const text = await res.text();
  try {
    return text ? JSON.parse(text) : null;
  } catch {
    return { raw: text };
  }
}

async function safeDelete(path) {
  try {
    await fetch(`${BASE_URL}${path}`, { method: 'DELETE' });
  } catch {}
}

function uniqueName(prefix) {
  return `${prefix}-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
}

// Helper: try common API path patterns for creating a track
async function createTrack(payload) {
  const paths = ['/api/tracks', '/api/track'];
  for (const p of paths) {
    const res = await fetch(`${BASE_URL}${p}`, {
      method: 'POST',
      headers: jsonHeaders,
      body: JSON.stringify(payload)
    });
    if ([200, 201].includes(res.status)) {
      const body = await safeJson(res);
      return { res, body, path: p };
    }
    // consume body
    await res.text().catch(() => {});
  }
  // last resort: return the last attempt
  const res = await fetch(`${BASE_URL}/api/tracks`, {
    method: 'POST',
    headers: jsonHeaders,
    body: JSON.stringify(payload)
  });
  const body = await safeJson(res);
  return { res, body, path: '/api/tracks' };
}

function getTrackId(body) {
  return body?.id ?? body?.trackId ?? body?.track?.id ?? body?._id;
}

async function getTrack(trackId) {
  const paths = [`/api/tracks/${trackId}`, `/api/track/${trackId}`];
  for (const p of paths) {
    try {
      const res = await fetch(`${BASE_URL}${p}`);
      if (res.status === 200) {
        const body = await safeJson(res);
        return { res, body };
      }
      await res.text().catch(() => {});
    } catch {}
  }
  const res = await fetch(`${BASE_URL}/api/tracks/${trackId}`);
  const body = await safeJson(res);
  return { res, body };
}

async function validateTrack(trackId) {
  const paths = [
    { url: `/api/tracks/${trackId}/validate`, method: 'POST' },
    { url: `/api/tracks/${trackId}/validate`, method: 'GET' },
    { url: `/api/track/${trackId}/validate`, method: 'POST' }
  ];
  for (const p of paths) {
    try {
      const res = await fetch(`${BASE_URL}${p.url}`, { method: p.method });
      if ([200, 204, 400, 409, 422].includes(res.status)) {
        const body = await safeJson(res);
        return { res, body };
      }
      await res.text().catch(() => {});
    } catch {}
  }
  const res = await fetch(`${BASE_URL}/api/tracks/${trackId}/validate`, { method: 'POST' });
  const body = await safeJson(res);
  return { res, body };
}

async function simulateTrack(trackId, payload) {
  const paths = [
    `/api/tracks/${trackId}/simulate`,
    `/api/track/${trackId}/simulate`,
    `/api/simulate`
  ];
  for (const p of paths) {
    try {
      const finalPayload = p === '/api/simulate' ? { ...payload, trackId } : payload;
      const res = await fetch(`${BASE_URL}${p}`, {
        method: 'POST',
        headers: jsonHeaders,
        body: JSON.stringify(finalPayload)
      });
      if ([200, 201].includes(res.status)) {
        const body = await safeJson(res);
        return { res, body };
      }
      await res.text().catch(() => {});
    } catch {}
  }
  const res = await fetch(`${BASE_URL}/api/tracks/${trackId}/simulate`, {
    method: 'POST',
    headers: jsonHeaders,
    body: JSON.stringify(payload)
  });
  const body = await safeJson(res);
  return { res, body };
}

function isPlayable(body) {
  if (!body || typeof body !== 'object') return undefined;
  if ('playable' in body) return body.playable;
  if ('canStart' in body) return body.canStart;
  if ('valid' in body) return body.valid;
  if ('isPlayable' in body) return body.isPlayable;
  if ('canPlay' in body) return body.canPlay;
  return undefined;
}

describe('legacy_terrain_defaults_to_normal_road', () => {
