    try {
      const { res: legacyGetRes, body: legacyGetBody } = await getTrack(legacyId);
      expect(legacyGetRes.status).toBe(200);

      // Assert terrain is present and defaults to normal/road
      // Look for terrain in multiple possible locations
      const terrain = legacyGetBody.terrain
        ?? legacyGetBody.layout?.terrain
        ?? legacyGetBody.defaults?.terrain
        ?? legacyGetBody.terrainMap;

      // If terrain is returned as an object or array, verify all cells default to normal/road
      if (terrain !== undefined && terrain !== null) {
        const terrainStr = JSON.stringify(terrain);
