        ]
      }
    };

    const { res, body } = await createTrack(allWallTrack);

    if ([200, 201].includes(res.status)) {
      const allWallId = getTrackId(body);
      try {
        const { res: validateRes, body: validateBody } = await validateTrack(allWallId);
        expect([200, 400, 422].includes(validateRes.status)).toBe(true);

        if (validateRes.status === 200 && validateBody && typeof validateBody === 'object') {
          const playableValue = isPlayable(validateBody);
          expect(playableValue).toBeDefined();
          expect(playableValue).toBe(false);
        } else if ([400, 422].includes(validateRes.status)) {
          expect(JSON.stringify(validateBody)).toMatch(/cannot|unplayable|unreachable|blocked|invalid|no.*road|no.*walk|no.*path/i);
        }
      } finally {
        await safeDelete(`/api/tracks/${allWallId}`);
      }
    } else {
      expect([400, 409, 422]).toContain(res.status);
      expect(JSON.stringify(body)).toMatch(/cannot|unplayable|unreachable|blocked|invalid|no.*road|no.*walk|no.*path/i);
    }
  });

  it('different terrains produce observable driving differences under fixed input', async () => {
    // Create a track with normal road terrain
    const normalTrack = {
      name: uniqueName('terrain-normal'),
      layout: {
        width: 6,
        height: 2,
        tiles: [
          ['start', 'road', 'road', 'road', 'road', 'finish'],
          ['road', 'road', 'road', 'road', 'road', 'road']
        ]
      },
      terrain: { default: 'normal' }
    };

    // Create a track with low-grip terrain
    const lowGripTrack = {
      name: uniqueName('terrain-lowgrip'),
      layout: {
        width: 6,
        height: 2,
        tiles: [
          ['start', 'road', 'road', 'road', 'road', 'finish'],
          ['road', 'road', 'road', 'road', 'road', 'road']
        ]
      },
      terrain: { default: 'low_grip' }
    };

    // Create a track with slow/deceleration terrain
    const slowTrack = {
      name: uniqueName('terrain-slow'),
      layout: {
        width: 6,
        height: 2,
        tiles: [
          ['start', 'road', 'road', 'road', 'road', 'finish'],
          ['road', 'road', 'road', 'road', 'road', 'road']
        ]
      },
      terrain: { default: 'slow' }
    };

    const { res: normalRes, body: normalBody } = await createTrack(normalTrack);
    expect([200, 201]).toContain(normalRes.status);
    const normalId = getTrackId(normalBody);
    expect(normalId).toBeTruthy();

    const { res: lowGripRes, body: lowGripBody } = await createTrack(lowGripTrack);
    expect([200, 201]).toContain(lowGripRes.status);
    const lowGripId = getTrackId(lowGripBody);
    expect(lowGripId).toBeTruthy();

    const { res: slowRes, body: slowBody } = await createTrack(slowTrack);
    expect([200, 201]).toContain(slowRes.status);
    const slowId = getTrackId(slowBody);
    expect(slowId).toBeTruthy();

    try {
      const fixedInputs = [
        { action: 'forward', duration: 1 },
        { action: 'forward', duration: 1 },
        { action: 'forward', duration: 1 }
      ];

      const simPayload = { inputs: fixedInputs, weather: 'sunny' };

      // Run simulation on normal track
      const { res: simNormalRes, body: simNormalBody } = await simulateTrack(normalId, simPayload);
      expect([200, 201]).toContain(simNormalRes.status);

      // Run simulation on low grip track
      const { res: simLowGripRes, body: simLowGripBody } = await simulateTrack(lowGripId, simPayload);
      expect([200, 201]).toContain(simLowGripRes.status);

      // Run simulation on slow track
      const { res: simSlowRes, body: simSlowBody } = await simulateTrack(slowId, simPayload);
      expect([200, 201]).toContain(simSlowRes.status);

      // Extract the final metric (speed or position) from simulation results
      const getMetric = (body) => {
        if (!body || typeof body !== 'object') return null;
        const steps = body.steps ?? body.frames ?? body.results ?? body.history ?? [];
        if (Array.isArray(steps) && steps.length > 0) {
          const last = steps[steps.length - 1];
          return {
            speed: last.speed ?? last.velocity ?? last.currentSpeed ?? null,
            posX: last.position?.x ?? last.x ?? last.posX ?? null
          };
        }
        return {
          speed: body.finalSpeed ?? body.speed ?? body.result?.speed ?? null,
          posX: body.finalPosition?.x ?? body.position?.x ?? body.result?.position?.x ?? null
        };
      };

      const normalMetric = getMetric(simNormalBody);
      const lowGripMetric = getMetric(simLowGripBody);
      const slowMetric = getMetric(simSlowBody);

      // Ensure we actually got metric data back
      expect(normalMetric).toBeDefined();
      expect(lowGripMetric).toBeDefined();
      expect(slowMetric).toBeDefined();

      // At least speed or position should be non-null for comparison
      const normalVal = normalMetric.speed ?? normalMetric.posX;
      const lowGripVal = lowGripMetric.speed ?? lowGripMetric.posX;
      const slowVal = slowMetric.speed ?? slowMetric.posX;

      expect(normalVal).not.toBeNull();
      expect(lowGripVal).not.toBeNull();
      expect(slowVal).not.toBeNull();

      // At least one of the special terrains should differ from normal
      const hasDifference = (normalVal !== lowGripVal) || (normalVal !== slowVal);
      expect(hasDifference).toBe(true);

      // Directional assertions: slow terrain should result in lower speed or less distance than normal
      if (slowMetric.speed !== null && normalMetric.speed !== null) {
        expect(slowMetric.speed).toBeLessThan(normalMetric.speed);
      } else if (slowMetric.posX !== null && normalMetric.posX !== null) {
        expect(slowMetric.posX).toBeLessThanOrEqual(normalMetric.posX);
      }

      // Low grip terrain should also show different behavior from normal
      if (lowGripMetric.speed !== null && normalMetric.speed !== null) {
        expect(lowGripVal).not.toBe(normalVal);
      } else if (lowGripMetric.posX !== null && normalMetric.posX !== null) {
        expect(lowGripVal).not.toBe(normalVal);
      }
    } finally {
      await safeDelete(`/api/tracks/${normalId}`);
      await safeDelete(`/api/tracks/${lowGripId}`);
      await safeDelete(`/api/tracks/${slowId}`);
    }
  });
});

import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function request(method, path, body) {
  const res = await fetch(`${BASE_URL}${path}`, {
    method,
    headers: { 'Content-Type': 'application/json' },
    body: body === undefined ? undefined : JSON.stringify(body),
  });
  const text = await res.text();
  let data = null;
  try { data = text ? JSON.parse(text) : null; } catch { data = text; }
  return { res, data, text };
}

async function safeDelete(path) {
  try { await fetch(`${BASE_URL}${path}`, { method: 'DELETE' }); } catch {}
}

function extractId(data) {
  if (!data || typeof data !== 'object') return null;
  return data.id || data.trackId || data.scoreId || data.recordId || data.data?.id || null;
}

function extractItems(data) {
  if (Array.isArray(data)) return data;
  if (!data || typeof data !== 'object') return [];
  return data.entries || data.records || data.items || data.data?.entries || data.data?.records || data.data?.items || [];
}

