import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';
const jsonHeaders = { 'content-type': 'application/json' };

async function safeJson(res) {
  const text = await res.text();
  try {
    return text ? JSON.parse(text) : null;
  } catch {
    return { raw: text };
  }
}

async function safeDelete(path) {
  try {
    await fetch(`${BASE_URL}${path}`, { method: 'DELETE' });
  } catch {}
}

function uniqueName(prefix) {
  return `${prefix}-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
}

describe('round13_checkpoint_order_and_compat', () => {
  it('legacy no-checkpoint tracks remain playable', async () => {
    const legacyTrack = {
      name: uniqueName('round13-legacy'),
      layout: {
        width: 4,
        height: 2,
        tiles: [
          ['start', 'road', 'road', 'finish'],
          ['road', 'road', 'road', 'road']
        ]
      }
    };

    const legacyRes = await fetch(`${BASE_URL}/tracks`, {
      method: 'POST',
      headers: jsonHeaders,
      body: JSON.stringify(legacyTrack)
    });
    const legacyBody = await safeJson(legacyRes);
    expect([200, 201]).toContain(legacyRes.status);
    const legacyId = legacyBody.id ?? legacyBody.trackId;
    expect(legacyId).toBeTruthy();

    try {
      const legacyValidateRes = await fetch(`${BASE_URL}/tracks/${legacyId}/validate`, { method: 'POST' });
      const legacyValidateBody = await safeJson(legacyValidateRes);
      expect([200, 204]).toContain(legacyValidateRes.status);
      if (legacyValidateBody && typeof legacyValidateBody === 'object') {
        if ('playable' in legacyValidateBody) expect(legacyValidateBody.playable).toBe(true);
        if ('canStart' in legacyValidateBody) expect(legacyValidateBody.canStart).toBe(true);
        if ('valid' in legacyValidateBody) expect(legacyValidateBody.valid).toBe(true);
      }
    } finally {
      await safeDelete(`/tracks/${legacyId}`);
    }
  });

  it('enforces ordered checkpoints: valid order accepted, wrong order rejected, missing checkpoint rejected', async () => {
    const checkpointTrack = {
      name: uniqueName('round13-checkpoints'),
      checkpoints: [
        { order: 1, x: 1, y: 0 },
        { order: 2, x: 2, y: 0 }
      ],
      layout: {
        width: 4,
        height: 2,
        tiles: [
          ['start', 'checkpoint:1', 'checkpoint:2', 'finish'],
          ['road', 'road', 'road', 'road']
        ]
      }
    };

    const checkpointRes = await fetch(`${BASE_URL}/tracks`, {
      method: 'POST',
      headers: jsonHeaders,
      body: JSON.stringify(checkpointTrack)
    });
    const checkpointBody = await safeJson(checkpointRes);
    expect([200, 201]).toContain(checkpointRes.status);
    const checkpointId = checkpointBody.id ?? checkpointBody.trackId;
    expect(checkpointId).toBeTruthy();

    try {
      // Wrong order: [2, 1] should be rejected
      const wrongOrderRes = await fetch(`${BASE_URL}/scores`, {
        method: 'POST',
        headers: jsonHeaders,
        body: JSON.stringify({
          trackId: checkpointId,
          nickname: 'wrong-order',
          weather: 'sunny',
          timeMs: 999,
          valid: true,
          checkpointPasses: [2, 1]
        })
      });
      const wrongOrderBody = await safeJson(wrongOrderRes);
      expect([400, 409, 422]).toContain(wrongOrderRes.status);
      expect(JSON.stringify(wrongOrderBody)).toMatch(/checkpoint|order|sequence|invalid/i);

      // Missing checkpoint: [1] only (skipping checkpoint 2) should be rejected
      const missingCpRes = await fetch(`${BASE_URL}/scores`, {
        method: 'POST',
        headers: jsonHeaders,
        body: JSON.stringify({
          trackId: checkpointId,
          nickname: 'missing-cp',
          weather: 'sunny',
          timeMs: 800,
          valid: true,
          checkpointPasses: [1]
        })
      });
      const missingCpBody = await safeJson(missingCpRes);
      expect([400, 409, 422]).toContain(missingCpRes.status);
      expect(JSON.stringify(missingCpBody)).toMatch(/checkpoint|missing|incomplete|invalid|order|sequence/i);

      // Valid order with segment times
      const validOrderRes = await fetch(`${BASE_URL}/scores`, {
        method: 'POST',
        headers: jsonHeaders,
        body: JSON.stringify({
          trackId: checkpointId,
          nickname: 'valid-order',
          weather: 'sunny',
          timeMs: 1000,
          valid: true,
          checkpointPasses: [1, 2],
          segmentTimes: [450, 550],
          checkpointTimes: [450, 1000]
        })
      });
      const validOrderBody = await safeJson(validOrderRes);
      expect([200, 201]).toContain(validOrderRes.status);
      expect(validOrderBody.nickname ?? validOrderBody.data?.nickname).toBe('valid-order');

      // Leaderboard should contain valid-order but not wrong-order or missing-cp
      const leaderboardRes = await fetch(`${BASE_URL}/leaderboards?trackId=${encodeURIComponent(checkpointId)}&weather=sunny`);
      const leaderboardBody = await safeJson(leaderboardRes);
      expect(leaderboardRes.status).toBe(200);
      const entries = Array.isArray(leaderboardBody) ? leaderboardBody : (leaderboardBody.entries ?? leaderboardBody.items ?? leaderboardBody.data ?? []);
      expect(entries.some((e) => e.nickname === 'valid-order')).toBe(true);
      expect(entries.some((e) => e.nickname === 'wrong-order')).toBe(false);
      expect(entries.some((e) => e.nickname === 'missing-cp')).toBe(false);

      // Verify segment/checkpoint times summary in leaderboard entry
      const validEntry = entries.find((e) => e.nickname === 'valid-order');
      expect(validEntry).toBeTruthy();
      const hasTimes = validEntry.segmentTimes || validEntry.checkpointTimes || validEntry.segments || validEntry.splitTimes;
      expect(hasTimes, 'Leaderboard entry should contain segment/checkpoint time summary').toBeTruthy();
      if (Array.isArray(validEntry.segmentTimes)) {
        expect(validEntry.segmentTimes.length).toBeGreaterThan(0);
      }
      if (Array.isArray(validEntry.checkpointTimes)) {
        expect(validEntry.checkpointTimes.length).toBeGreaterThan(0);
      }
    } finally {
      await safeDelete(`/tracks/${checkpointId}`);
    }
  });

  it('rejects track creation when checkpoints exceed the allowed maximum', async () => {
    // Build a track with an excessive number of checkpoints (e.g., 100)
    const maxTestCount = 100;
    const checkpoints = [];
    const topRow = ['start'];
    for (let i = 1; i <= maxTestCount; i++) {
      checkpoints.push({ order: i, x: i, y: 0 });
      topRow.push(`checkpoint:${i}`);
    }
    topRow.push('finish');
    const bottomRow = topRow.map(() => 'road');

    const tooManyTrack = {
      name: uniqueName('round13-toomany-cp'),
      checkpoints,
      layout: {
        width: topRow.length,
        height: 2,
        tiles: [topRow, bottomRow]
      }
    };

    const res = await fetch(`${BASE_URL}/tracks`, {
      method: 'POST',
      headers: jsonHeaders,
      body: JSON.stringify(tooManyTrack)
    });
    const body = await safeJson(res);

    // Should be rejected or flagged due to checkpoint limit
    if ([400, 409, 422].includes(res.status)) {
      expect(JSON.stringify(body)).toMatch(/limit|max|too many|checkpoint|exceed|count/i);
    } else if ([200, 201].includes(res.status)) {
      // If accepted, verify via validation that it's flagged
      const trackId = body.id ?? body.trackId;
      if (trackId) {
        const valRes = await fetch(`${BASE_URL}/tracks/${trackId}/validate`, { method: 'POST' });
        const valBody = await safeJson(valRes);
        const valStr = JSON.stringify(valBody).toLowerCase();
        const hasWarning = /limit|max|too many|checkpoint|exceed|warning|count/.test(valStr);
        expect(hasWarning, `Expected checkpoint limit warning in validation, got ${JSON.stringify(valBody)}`).toBe(true);
        await safeDelete(`/tracks/${trackId}`);
      }
    } else {
      // Unexpected status
      expect.fail(`Expected 4xx rejection or 2xx with warning for too many checkpoints, got ${res.status}`);
    }
  });

  it('detects unreachable checkpoints during editing/validation phase', async () => {
    // Create a track where a checkpoint is placed on a wall / unreachable tile
    const unreachableTrack = {
      name: uniqueName('round13-unreachable-cp'),
      checkpoints: [
        { order: 1, x: 1, y: 0 },
        { order: 2, x: 1, y: 1 }  // placed on a wall tile
      ],
      layout: {
        width: 4,
        height: 2,
        tiles: [
          ['start', 'checkpoint:1', 'road', 'finish'],
          ['wall', 'wall', 'wall', 'wall']
        ]
      }
    };

    const createRes = await fetch(`${BASE_URL}/tracks`, {
      method: 'POST',
      headers: jsonHeaders,
      body: JSON.stringify(unreachableTrack)
    });
    const createBody = await safeJson(createRes);

    if ([400, 422].includes(createRes.status)) {
      // Rejected at creation time – check for meaningful error
      expect(JSON.stringify(createBody)).toMatch(/unreachable|inaccessible|invalid|checkpoint|blocked|wall|path/i);
      return;
    }

    expect([200, 201]).toContain(createRes.status);
    const trackId = createBody.id ?? createBody.trackId;
    expect(trackId).toBeTruthy();

    try {
      // Validate should flag the unreachable checkpoint
      const valRes = await fetch(`${BASE_URL}/tracks/${trackId}/validate`, { method: 'POST' });
      const valBody = await safeJson(valRes);
      const valStr = JSON.stringify(valBody).toLowerCase();

      // Either the status indicates a problem or the body contains a warning
      const hasIssue =
        [400, 422].includes(valRes.status) ||
        /unreachable|inaccessible|invalid|problem|error|warning|blocked|checkpoint/.test(valStr);

      if (valBody && typeof valBody === 'object') {
        if ('playable' in valBody) {
          expect(valBody.playable).toBe(false);
        } else if ('valid' in valBody) {
          expect(valBody.valid).toBe(false);
        } else {
          expect(hasIssue, `Expected unreachable checkpoint warning, got ${JSON.stringify(valBody)}`).toBe(true);
        }
      } else {
        expect(hasIssue, `Expected unreachable checkpoint detection, got status ${valRes.status}`).toBe(true);
      }
    } finally {
      await safeDelete(`/tracks/${trackId}`);
    }
  });
});

import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function request(method, path, body) {
  const res = await fetch(`${BASE_URL}${path}`, {
    method,
    headers: { 'Content-Type': 'application/json' },
    body: body === undefined ? undefined : JSON.stringify(body),
  });
  let json = null;
  try {
    json = await res.json();
  } catch {
    json = null;
  }
  return { res, json };
}

function uniqueName(prefix) {
  return `${prefix}-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
}

function extractId(data) {
  if (!data || typeof data !== 'object') return null;
  return data.id || data.trackId || data.sessionId || data.raceId || data.data?.id || null;
}

describe('round17_dynamic_weather_sandbox_only', () => {
  it('should allow dynamic weather only in sandbox, cap at 3 segments with progress info, merge/warn duplicates, fallback empty to default, and keep formal race weather fixed', async () => {
    let trackId;

    try {
      // Create a valid track
      const track = await request('POST', '/api/tracks', {
        name: uniqueName('dynamic-weather-track'),
        weather: 'sunny',
        width: 3,
        height: 2,
        layout: [
          ['start', 'road', 'road'],
          ['road', 'road', 'finish']
        ],
      });
      expect([200, 201]).toContain(track.res.status);
      trackId = extractId(track.json);
      expect(trackId, `expected track id, got ${JSON.stringify(track.json)}`).toBeTruthy();

      // === Sandbox: valid 3-segment dynamic weather ===
      const sandboxPath = `/api/sandbox/start`;
      const sandboxDynamic = await request('POST', sandboxPath, {
        trackId,
        weatherSequence: ['sunny', 'rain', 'wind'],
        inputSequence: ['accelerate', 'straight'],
      });
      expect(sandboxDynamic.res.status).toBe(200);
      const sandboxData = sandboxDynamic.json?.data || sandboxDynamic.json;
      const dynWeather = sandboxData?.weatherSequence || sandboxData?.dynamicWeather;
      expect(dynWeather, `expected sandbox to echo accepted dynamic weather sequence, got ${JSON.stringify(sandboxDynamic.json)}`).toBeTruthy();
      expect(Array.isArray(dynWeather)).toBe(true);
      expect(dynWeather.length).toBe(3);

      // Verify sandbox response includes per-segment progress/timing info
      const segments = sandboxData?.segments || sandboxData?.weatherSegments;
      if (segments) {
        expect(Array.isArray(segments)).toBe(true);
        expect(segments.length).toBe(3);
        for (const seg of segments) {
          // Each segment should have duration or progress indication
          const hasDuration = seg.duration !== undefined || seg.progress !== undefined || seg.startStep !== undefined;
          expect(hasDuration, `each weather segment should have duration/progress info, got: ${JSON.stringify(seg)}`).toBe(true);
        }
      }

      // Query sandbox session state to verify weather switching during progress
      const sandboxSessionId = sandboxData?.id || sandboxData?.sessionId;
      if (sandboxSessionId) {
        const statusRes = await request('GET', `/api/sandbox/${sandboxSessionId}/status`);
        if (statusRes.res.status === 200 && statusRes.json) {
          const statusData = statusRes.json.data || statusRes.json;
          // Should show current weather segment and vehicle state
          const currentWeather = statusData.currentWeather || statusData.weather;
          expect(currentWeather, 'sandbox status should show current weather').toBeTruthy();
        }
      }

      // === Sandbox: exceed 3 segments ===
      const tooLong = await request('POST', sandboxPath, {
        trackId,
        weatherSequence: ['sunny', 'rain', 'wind', 'snow'],
        inputSequence: ['accelerate'],
      });
      expect([400, 422]).toContain(tooLong.res.status);
      const tooLongMsg = JSON.stringify(tooLong.json).toLowerCase();
      expect(tooLongMsg).toMatch(/max|limit|exceed|too many|3|segments/);

      // === Sandbox: consecutive same weather should be merged or warned ===
      const duplicateWeather = await request('POST', sandboxPath, {
        trackId,
        weatherSequence: ['sunny', 'sunny'],
        inputSequence: ['accelerate'],
      });
      if ([200].includes(duplicateWeather.res.status)) {
        const dupData = duplicateWeather.json?.data || duplicateWeather.json;
        const mergedWeather = dupData?.weatherSequence || dupData?.dynamicWeather;
        const hasWarning = JSON.stringify(duplicateWeather.json).toLowerCase().match(/merge|duplicate|same|redundant|unnecessary/);
        const wasMerged = Array.isArray(mergedWeather) && mergedWeather.length === 1;
        expect(wasMerged || !!hasWarning, 'duplicate consecutive weather should be merged or warned').toBeTruthy();
      } else {
        expect([400, 422]).toContain(duplicateWeather.res.status);
        expect(JSON.stringify(duplicateWeather.json).toLowerCase()).toMatch(/duplicate|same|merge|redundant|unnecessary|repeat/);
      }

      // === Sandbox: empty weather sequence fallback to default ===
      const emptySequence = await request('POST', sandboxPath, {
        trackId,
        weatherSequence: [],
        inputSequence: ['accelerate'],
      });
      expect(emptySequence.res.status).toBe(200);
      const emptyData = emptySequence.json?.data || emptySequence.json;
      const fallbackWeather = emptyData?.weather || emptyData?.effectiveWeather;
      expect(fallbackWeather, `expected a default weather value when sequence is empty, got ${JSON.stringify(emptySequence.json)}`).toBeTruthy();
      expect(typeof fallbackWeather).toBe('string');
      expect(['sunny', 'clear', 'default', 'normal']).toContain(fallbackWeather.toLowerCase());

      // === Formal race: weather fixed, no dynamic weather allowed ===
      const formalStart = await request('POST', '/api/races/start', {
        trackId,
        weather: 'sunny',
        nickname: 'formal-tester',
      });
      expect([200, 201]).toContain(formalStart.res.status);
      const formalData = formalStart.json?.data || formalStart.json;
      const sessionId = formalData?.id || formalData?.sessionId || formalData?.raceId;
      expect(sessionId, `expected formal session id, got ${JSON.stringify(formalStart.json)}`).toBeTruthy();

      // Verify formal race weather is exactly what was requested
      const formalWeather = formalData?.weather || formalData?.session?.weather;
      expect(formalWeather).toBeTruthy();
      expect(formalWeather.toLowerCase()).toBe('sunny');

      // Attempt to inject dynamic weather into formal race — must be rejected with business error (not 404)
      const formalDynamic = await request('PATCH', `/api/races/${sessionId}`, {
        weatherSequence: ['sunny', 'rain'],
      });
      expect(
        [400, 403, 409, 422].includes(formalDynamic.res.status),
        `injecting dynamic weather into formal race should be rejected with 400/403/409/422, got ${formalDynamic.res.status}`
      ).toBe(true);

      // Attempt to change weather mid-formal-race — must be rejected with business error
      const formalWeatherChange = await request('PATCH', `/api/races/${sessionId}`, {
        weather: 'rain',
      });
      expect(
        [400, 403, 409, 422].includes(formalWeatherChange.res.status),
        `changing weather mid-formal-race should be rejected with 400/403/409/422, got ${formalWeatherChange.res.status}`
      ).toBe(true);

    } finally {
      if (trackId) {
        await fetch(`${BASE_URL}/api/tracks/${trackId}`, { method: 'DELETE' }).catch(() => {});
      }
    }
  });
});

import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';
const jsonHeaders = { 'content-type': 'application/json' };

async function safeJson(res) {
  const text = await res.text();
  try {
    return text ? JSON.parse(text) : null;
  } catch {
    return { raw: text };
  }
}

async function safeDelete(path) {
  try {
    await fetch(`${BASE_URL}${path}`, { method: 'DELETE' });
  } catch {}
}

function uniqueName(prefix) {
  return `${prefix}-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
}

async function createTrack(payload) {
  const paths = ['/api/tracks', '/api/track'];
  for (const p of paths) {
    const res = await fetch(`${BASE_URL}${p}`, {
      method: 'POST',
      headers: jsonHeaders,
      body: JSON.stringify(payload)
    });
    if ([200, 201].includes(res.status)) {
      const body = await safeJson(res);
      return { res, body, path: p };
    }
    await res.text().catch(() => {});
  }
  const res = await fetch(`${BASE_URL}/api/tracks`, {
    method: 'POST',
    headers: jsonHeaders,
    body: JSON.stringify(payload)
  });
  const body = await safeJson(res);
  return { res, body, path: '/api/tracks' };
}

function getTrackId(body) {
  return body?.id ?? body?.trackId ?? body?.track?.id ?? body?._id;
}

async function submitRun(payload) {
  const paths = ['/api/runs', '/api/run', '/api/scores'];
  for (const p of paths) {
    const res = await fetch(`${BASE_URL}${p}`, {
      method: 'POST',
      headers: jsonHeaders,
      body: JSON.stringify(payload)
    });
    if ([200, 201, 400, 409, 422].includes(res.status)) {
      const body = await safeJson(res);
      return { res, body, path: p };
    }
    await res.text().catch(() => {});
  }
  const res = await fetch(`${BASE_URL}/api/runs`, {
    method: 'POST',
    headers: jsonHeaders,
    body: JSON.stringify(payload)
  });
  const body = await safeJson(res);
  return { res, body, path: '/api/runs' };
}

async function getLeaderboard(params) {
  const qs = new URLSearchParams(params).toString();
  const paths = [`/api/leaderboards?${qs}`, `/api/leaderboard?${qs}`, `/api/scores?${qs}`];
  for (const p of paths) {
    try {
      const res = await fetch(`${BASE_URL}${p}`);
      if (res.status === 200) {
        const body = await safeJson(res);
        return { res, body };
      }
      await res.text().catch(() => {});
    } catch {}
  }
  const res = await fetch(`${BASE_URL}/api/leaderboards?${qs}`);
  const body = await safeJson(res);
  return { res, body };
}

function getRunId(body) {
  return body?.id ?? body?.runId ?? body?.scoreId ?? body?._id;
}

function extractEntries(body) {
  if (Array.isArray(body)) return body;
  return body?.entries ?? body?.items ?? body?.scores ?? body?.leaderboard ?? [];
}

describe('submit_score_validates_nickname_and_limits_top10', () => {
  const trackPayload = () => ({
    name: uniqueName('lb-track'),
    weather: 'sunny',
    layout: {
      width: 4,
      height: 2,
      tiles: [
        ['start', 'road', 'road', 'finish'],
        ['road', 'road', 'road', 'road']
      ]
    }
  });

  it('rejects empty nickname and overly long nickname, and confirms rejection did not create leaderboard entries', async () => {
    const { res: createTrackRes, body: createTrackBody } = await createTrack(trackPayload());
    expect([200, 201]).toContain(createTrackRes.status);
    const trackId = getTrackId(createTrackBody);
    expect(trackId).toBeTruthy();

    try {
      // Empty nickname should be rejected
      const { res: emptyNickRes, body: emptyNickBody } = await submitRun({
        trackId, weather: 'sunny', timeMs: 1200, nickname: '', recordType: 'manual'
      });
      expect([400, 409, 422]).toContain(emptyNickRes.status);
      const emptyErrStr = JSON.stringify(emptyNickBody);
      expect(emptyErrStr).toMatch(/nickname|name|required|empty|blank/i);

      // Overly long nickname should be rejected
      const { res: longNickRes, body: longNickBody } = await submitRun({
        trackId, weather: 'sunny', timeMs: 1201, nickname: 'x'.repeat(300), recordType: 'manual'
      });
      expect([400, 409, 422]).toContain(longNickRes.status);
      const longErrStr = JSON.stringify(longNickBody);
      expect(longErrStr).toMatch(/nickname|name|length|long|max|limit|exceed/i);

      // Verify leaderboard has no entries from the rejected submissions
      const { res: lbRes, body: lbBody } = await getLeaderboard({
        trackId, weather: 'sunny', recordType: 'manual'
      });
      expect(lbRes.status).toBe(200);
      const entries = extractEntries(lbBody);
      expect(Array.isArray(entries)).toBe(true);
      expect(entries.length).toBe(0);
    } finally {
      await safeDelete(`/api/tracks/${trackId}`);
    }
  });

  it('preserves valid score while nickname is being corrected (pending record flow)', async () => {
    const { res: createTrackRes, body: createTrackBody } = await createTrack(trackPayload());
    expect([200, 201]).toContain(createTrackRes.status);
    const trackId = getTrackId(createTrackBody);
    expect(trackId).toBeTruthy();

    try {
      const scoreData = { trackId, weather: 'sunny', timeMs: 2500, recordType: 'manual' };

      // Attempt 1: try submitting without nickname to create a pending record
      const { res: attempt1Res, body: attempt1Body } = await submitRun({ ...scoreData, nickname: '' });

      const pendingId = getRunId(attempt1Body);

      if ([200, 201].includes(attempt1Res.status) && pendingId) {
        // Server accepted a pending record without nickname -> patch it with a valid nickname
        const patchPaths = [
          `/api/runs/${pendingId}`,
          `/api/run/${pendingId}`,
          `/api/scores/${pendingId}`
        ];
        let patched = false;
        let patchBody = null;
        for (const pp of patchPaths) {
          for (const method of ['PATCH', 'PUT']) {
            try {
              const pRes = await fetch(`${BASE_URL}${pp}`, {
                method,
                headers: jsonHeaders,
                body: JSON.stringify({ nickname: 'FixedNick' })
              });
              if ([200, 204].includes(pRes.status)) {
                patchBody = await safeJson(pRes);
                patched = true;
                break;
              }
              await pRes.text().catch(() => {});
            } catch {}
          }
          if (patched) break;
        }

        if (patched) {
          // Verify the time was preserved
          const finalTime = patchBody?.timeMs ?? patchBody?.time;
          if (finalTime !== undefined) {
            expect(finalTime).toBe(2500);
          }
          const finalNick = patchBody?.nickname ?? patchBody?.player?.nickname;
          if (finalNick !== undefined) {
            expect(finalNick).toBe('FixedNick');
          }
        }
      } else {
        // Server rejected the empty nickname attempt (400/422) – this is also valid
        // In this case, verify that resubmitting with the same time and a valid nickname works
        expect([400, 409, 422]).toContain(attempt1Res.status);

        const { res: attempt2Res, body: attempt2Body } = await submitRun({
          ...scoreData, nickname: 'FixedNick'
        });
        expect([200, 201]).toContain(attempt2Res.status);

        const submittedNick = attempt2Body?.nickname ?? attempt2Body?.player?.nickname;
        expect(submittedNick).toBe('FixedNick');
        const submittedTime = attempt2Body?.timeMs ?? attempt2Body?.time;
        expect(submittedTime).toBe(2500);

        // Confirm the score appears in the leaderboard
        const { res: lbRes, body: lbBody } = await getLeaderboard({
          trackId, weather: 'sunny', recordType: 'manual'
        });
        expect(lbRes.status).toBe(200);
        const entries = extractEntries(lbBody);
        const found = entries.find(e => (e.nickname ?? e.player?.nickname) === 'FixedNick');
        expect(found).toBeDefined();
        expect(Number(found.timeMs ?? found.time)).toBe(2500);
      }
    } finally {
      await safeDelete(`/api/tracks/${trackId}`);
    }
  });

  it('caps leaderboard at top 10, applies stable sort for ties, and isolates by weather/recordType', async () => {
    const { res: createTrackRes, body: createTrackBody } = await createTrack(trackPayload());
    expect([200, 201]).toContain(createTrackRes.status);
    const trackId = getTrackId(createTrackBody);
    expect(trackId).toBeTruthy();

    try {
      // Submit 12 scores with ties at timeMs=1005
      const times = [1000, 1001, 1002, 1003, 1004, 1005, 1005, 1006, 1007, 1008, 1009, 1010];
      for (let i = 0; i < times.length; i++) {
        const { res: submitRes, body: submitBody } = await submitRun({
          trackId,
          weather: 'sunny',
          timeMs: times[i],
          nickname: `p${String(i).padStart(2, '0')}`,
          recordType: 'manual'
        });
        expect([200, 201]).toContain(submitRes.status);
        const nick = submitBody?.nickname ?? submitBody?.player?.nickname;
        expect(nick).toBe(`p${String(i).padStart(2, '0')}`);
      }

      // Also submit a score with different weather to test isolation
      const { res: rainyRes } = await submitRun({
        trackId,
        weather: 'rainy',
        timeMs: 500,
        nickname: 'rainyPlayer',
        recordType: 'manual'
      });
      expect([200, 201]).toContain(rainyRes.status);

      // Also submit an auto-demo score to test recordType isolation
      const { res: autoRes } = await submitRun({
        trackId,
        weather: 'sunny',
        timeMs: 100,
        nickname: 'autoBot',
        recordType: 'auto'
      });
      // auto submit may or may not be accepted depending on implementation
      // but if accepted, it must not appear in manual leaderboard

      // Fetch leaderboard for sunny + manual
      const { res: leaderboardRes, body: leaderboardBody } = await getLeaderboard({
        trackId, weather: 'sunny', recordType: 'manual'
      });
      expect(leaderboardRes.status).toBe(200);

      const entries = extractEntries(leaderboardBody);
      expect(Array.isArray(entries)).toBe(true);
      expect(entries.length).toBeLessThanOrEqual(10);
      expect(entries.length).toBe(10);

      // Verify sorted ascending by time
      const entryTimes = entries.map((e) => Number(e.timeMs ?? e.time));
      for (let i = 1; i < entryTimes.length; i++) {
        expect(entryTimes[i - 1]).toBeLessThanOrEqual(entryTimes[i]);
      }

      // Best entry should be in the list
      expect(entries.some((e) => (e.nickname ?? e.player?.nickname) === 'p00')).toBe(true);
      // Worst entries (p10, p11) should be excluded from top 10
      expect(entries.some((e) => (e.nickname ?? e.player?.nickname) === 'p11')).toBe(false);

      // Rainy score should NOT appear in sunny leaderboard (weather isolation)
      expect(entries.some((e) => (e.nickname ?? e.player?.nickname) === 'rainyPlayer')).toBe(false);

      // Auto-demo score should NOT appear in manual leaderboard (recordType isolation)
      expect(entries.some((e) => (e.nickname ?? e.player?.nickname) === 'autoBot')).toBe(false);

      // Verify weather consistency on all entries
      for (const e of entries) {
        const w = e.weather ?? e.weatherCondition;
        if (w !== undefined) {
          expect(w).toBe('sunny');
        }
      }

      // Stable sort check: fetch the leaderboard again and compare tie ordering
      const { res: leaderboardRes2, body: leaderboardBody2 } = await getLeaderboard({
        trackId, weather: 'sunny', recordType: 'manual'
      });
      expect(leaderboardRes2.status).toBe(200);
      const entries2 = extractEntries(leaderboardBody2);

      // Find entries with tied time in first fetch
      const tiedEntries1 = entries
        .filter((e) => Number(e.timeMs ?? e.time) === 1005)
        .map((e) => e.nickname ?? e.player?.nickname);
      const tiedEntries2 = entries2
        .filter((e) => Number(e.timeMs ?? e.time) === 1005)
        .map((e) => e.nickname ?? e.player?.nickname);
      // Tied entries should appear in the same order across fetches (stable sort)
      expect(tiedEntries1).toEqual(tiedEntries2);
    } finally {
      await safeDelete(`/api/tracks/${trackId}`);
    }
  });
});

