import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';
const jsonHeaders = { 'content-type': 'application/json' };

async function safeJson(res) {
  const text = await res.text();
  try {
    return text ? JSON.parse(text) : null;
  } catch {
    return { raw: text };
  }
}

async function safeDelete(path) {
  try {
    await fetch(`${BASE_URL}${path}`, { method: 'DELETE' });
  } catch {}
}

function uniqueName(prefix) {
  return `${prefix}-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
}

async function createTrack(payload) {
  const paths = ['/api/tracks', '/api/track'];
  for (const p of paths) {
    const res = await fetch(`${BASE_URL}${p}`, {
      method: 'POST',
      headers: jsonHeaders,
      body: JSON.stringify(payload)
    });
    if ([200, 201].includes(res.status)) {
      const body = await safeJson(res);
      return { res, body, basePath: p.replace(/s$/, '') };
    }
    await res.text().catch(() => {});
  }
  const res = await fetch(`${BASE_URL}/api/tracks`, {
    method: 'POST',
    headers: jsonHeaders,
    body: JSON.stringify(payload)
  });
  const body = await safeJson(res);
  return { res, body, basePath: '/api/tracks' };
}

function getTrackId(body) {
  return body?.id ?? body?.trackId ?? body?.track?.id ?? body?._id;
}

async function submitRun(payload) {
  const paths = ['/api/runs', '/api/run', '/api/scores'];
  for (const p of paths) {
    const res = await fetch(`${BASE_URL}${p}`, {
      method: 'POST',
      headers: jsonHeaders,
      body: JSON.stringify(payload)
    });
    if ([200, 201].includes(res.status)) {
      const body = await safeJson(res);
      return { res, body };
    }
    await res.text().catch(() => {});
  }
  const res = await fetch(`${BASE_URL}/api/runs`, {
    method: 'POST',
    headers: jsonHeaders,
    body: JSON.stringify(payload)
  });
  const body = await safeJson(res);
  return { res, body };
}

async function fetchGhost(params) {
  const qs = new URLSearchParams(params).toString();
  const paths = [`/api/ghosts?${qs}`, `/api/ghost?${qs}`];
  for (const p of paths) {
    try {
      const res = await fetch(`${BASE_URL}${p}`);
      if ([200, 404].includes(res.status)) {
        const body = await safeJson(res);
        return { res, body };
      }
      await res.text().catch(() => {});
    } catch {}
  }
  const res = await fetch(`${BASE_URL}/api/ghosts?${qs}`);
  const body = await safeJson(res);
  return { res, body };
}

async function getLeaderboard(params) {
  const qs = new URLSearchParams(params).toString();
  const paths = [`/api/leaderboards?${qs}`, `/api/leaderboard?${qs}`, `/api/scores?${qs}`];
  for (const p of paths) {
    try {
      const res = await fetch(`${BASE_URL}${p}`);
      if (res.status === 200) {
        const body = await safeJson(res);
        return { res, body };
      }
      await res.text().catch(() => {});
    } catch {}
  }
  const res = await fetch(`${BASE_URL}/api/leaderboards?${qs}`);
  const body = await safeJson(res);
  return { res, body };
}

function extractGhostData(body) {
  if (Array.isArray(body)) return body;
  return body?.ghost ?? body?.path ?? body?.frames ?? body?.data ?? body?.ghostData ?? [];
}

function extractEntries(body) {
  if (Array.isArray(body)) return body;
  return body?.entries ?? body?.items ?? body?.scores ?? body?.leaderboard ?? [];
}

function ghostLastTime(ghostData) {
  if (!Array.isArray(ghostData) || ghostData.length === 0) return null;
  const last = ghostData[ghostData.length - 1];
  return last?.t ?? last?.time ?? last?.timestamp ?? null;
}

const simpleTrackPayload = (name) => ({
  name: name ?? uniqueName('ghost-track'),
  weather: 'sunny',
  layout: {
    width: 4,
    height: 2,
    tiles: [
      ['start', 'road', 'road', 'finish'],
      ['road', 'road', 'road', 'road']
    ]
  }
});

