    const playerId = uniqueName('player-restart');
    const { res: createRes, body: createBody } = await createTrack(simpleTrackPayload());
    expect([200, 201]).toContain(createRes.status);
    const trackId = getTrackId(createBody);
    expect(trackId).toBeTruthy();

