      const { res: runRes } = await submitRun({
        trackId, playerId, nickname: 'restartUser', weather: 'sunny',
        timeMs: 800, valid: true, ghost: ghostFrames, recordType: 'manual'
      });
      expect([200, 201]).toContain(runRes.status);

      // Try to start a race session and then restart it to verify ghost resets
      // Attempt to use a race start endpoint
      let raceStarted = false;
      let raceId = null;
      const startPaths = [
        `/api/races/start`,
        `/api/race/start`,
        `/api/tracks/${trackId}/race/start`
      ];
      for (const sp of startPaths) {
        try {
          const startRes = await fetch(`${BASE_URL}${sp}`, {
            method: 'POST',
            headers: jsonHeaders,
            body: JSON.stringify({ trackId, playerId, weather: 'sunny', showGhost: true })
          });
          if ([200, 201].includes(startRes.status)) {
            const startBody = await safeJson(startRes);
            raceId = startBody?.raceId ?? startBody?.id ?? startBody?.sessionId;
            raceStarted = true;
            break;
          }
          await startRes.text().catch(() => {});
        } catch {}
      }

      if (raceStarted && raceId) {
        // Try restarting the race
        const restartPaths = [
          `/api/races/${raceId}/restart`,
          `/api/race/${raceId}/restart`,
          `/api/races/restart`
        ];
        let restarted = false;
        let restartBody = null;
        for (const rp of restartPaths) {
          try {
            const restartRes = await fetch(`${BASE_URL}${rp}`, {
              method: 'POST',
              headers: jsonHeaders,
              body: JSON.stringify({ raceId })
            });
            if ([200, 201, 204].includes(restartRes.status)) {
              restartBody = await safeJson(restartRes);
              restarted = true;
              break;
            }
            await restartRes.text().catch(() => {});
          } catch {}
        }

        if (restarted && restartBody) {
          // Check ghost position after restart
          const ghostPos = restartBody?.ghost?.position ?? restartBody?.ghostPosition ?? restartBody?.ghost;
          if (ghostPos) {
            const gx = ghostPos.x ?? ghostPos?.position?.x ?? 0;
            const gy = ghostPos.y ?? ghostPos?.position?.y ?? 0;
            expect(gx).toBe(0);
            expect(gy).toBe(0);
          }
        }
      }

      // Regardless of race API availability, verify ghost data always starts at origin
      const { res: ghostRes, body: ghostBody } = await fetchGhost({
        trackId, playerId, weather: 'sunny'
      });
      expect(ghostRes.status).toBe(200);

      const data = extractGhostData(ghostBody);
      expect(Array.isArray(data)).toBe(true);
      expect(data.length).toBeGreaterThan(0);

      // The first frame must always be at start position (t=0, origin)
      const firstFrame = data[0];
      expect(firstFrame.t ?? firstFrame.time ?? firstFrame.timestamp).toBe(0);
      expect(firstFrame.x).toBe(0);
      expect(firstFrame.y).toBe(0);

      // Fetching ghost a second time should yield identical first frame (consistent reset point)
      const { res: ghostRes2, body: ghostBody2 } = await fetchGhost({
        trackId, playerId, weather: 'sunny'
      });
      expect(ghostRes2.status).toBe(200);
      const data2 = extractGhostData(ghostBody2);
      expect(data2.length).toBeGreaterThan(0);
      const firstFrame2 = data2[0];
      expect(firstFrame2.t ?? firstFrame2.time ?? firstFrame2.timestamp).toBe(0);
      expect(firstFrame2.x).toBe(0);
      expect(firstFrame2.y).toBe(0);
    } finally {
      await safeDelete(`/api/tracks/${trackId}`);
    }
  });
});

import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';
const jsonHeaders = { 'content-type': 'application/json' };

async function safeJson(res) {
  const text = await res.text();
  try {
    return text ? JSON.parse(text) : null;
  } catch {
    return { raw: text };
  }
}

async function safeDelete(path) {
  try {
    await fetch(`${BASE_URL}${path}`, { method: 'DELETE' });
  } catch {}
}

function uniqueName(prefix) {
  return `${prefix}-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
}

describe('round6_terrain_compat_and_validation', () => {
  it('legacy track without terrain field defaults to normal road and is playable', async () => {
    const legacyTrack = {
      name: uniqueName('round6-legacy'),
      layout: {
        width: 4,
        height: 2,
        tiles: [
          ['start', 'road', 'road', 'finish'],
          ['road', 'road', 'road', 'road']
        ]
      }
    };

    const legacyRes = await fetch(`${BASE_URL}/api/tracks`, {
      method: 'POST',
      headers: jsonHeaders,
      body: JSON.stringify(legacyTrack)
    });
    const legacyBody = await safeJson(legacyRes);
    expect([200, 201]).toContain(legacyRes.status);
    const legacyId = legacyBody.id ?? legacyBody.trackId;
    expect(legacyId).toBeTruthy();

    try {
      const getLegacyRes = await fetch(`${BASE_URL}/api/tracks/${legacyId}`);
      const getLegacyBody = await safeJson(getLegacyRes);
      expect(getLegacyRes.status).toBe(200);

      // Assert terrain is present and defaults to normal/road
      const terrain = getLegacyBody.terrain ?? getLegacyBody.layout?.terrain ?? getLegacyBody.defaults?.terrain;
      expect(terrain).toBeDefined();
      expect(JSON.stringify(terrain)).toMatch(/normal|road/i);

      // Validate it's playable
      const validateRes = await fetch(`${BASE_URL}/api/tracks/${legacyId}/validate`, { method: 'POST' });
      const validateBody = await safeJson(validateRes);
      expect([200, 204]).toContain(validateRes.status);
      if (validateBody && typeof validateBody === 'object') {
        if ('playable' in validateBody) expect(validateBody.playable).toBe(true);
        if ('canStart' in validateBody) expect(validateBody.canStart).toBe(true);
      }
    } finally {
      await safeDelete(`/api/tracks/${legacyId}`);
    }
  });

  it('rejects track where finish is enclosed in walls (impossible to complete)', async () => {
    const impossibleTrack = {
      name: uniqueName('round6-impossible'),
      layout: {
        width: 4,
        height: 4,
        tiles: [
          ['wall', 'wall', 'wall', 'wall'],
          ['wall', 'start', 'wall', 'wall'],
          ['wall', 'wall', 'finish', 'wall'],
          ['wall', 'wall', 'wall', 'wall']
        ]
      }
    };

    const impossibleRes = await fetch(`${BASE_URL}/api/tracks`, {
      method: 'POST',
      headers: jsonHeaders,
      body: JSON.stringify(impossibleTrack)
    });
    const impossibleBody = await safeJson(impossibleRes);

    if ([200, 201].includes(impossibleRes.status)) {
      const impossibleId = impossibleBody.id ?? impossibleBody.trackId;
      expect(impossibleId).toBeTruthy();

      try {
        const validateRes = await fetch(`${BASE_URL}/api/tracks/${impossibleId}/validate`, { method: 'POST' });
        const validateBody = await safeJson(validateRes);
        expect([200, 400, 409, 422]).toContain(validateRes.status);
        if (validateRes.status === 200 && validateBody && typeof validateBody === 'object') {
          if ('playable' in validateBody) expect(validateBody.playable).toBe(false);
          if ('canStart' in validateBody) expect(validateBody.canStart).toBe(false);
        } else {
          expect(JSON.stringify(validateBody)).toMatch(/cannot|blocked|unreachable|invalid|unplayable/i);
        }
      } finally {
        await safeDelete(`/api/tracks/${impossibleId}`);
      }
    } else {
      expect([400, 409, 422]).toContain(impossibleRes.status);
      expect(JSON.stringify(impossibleBody)).toMatch(/cannot|blocked|unreachable|invalid|unplayable/i);
    }
  });

  it('rejects track with no walkable area at all', async () => {
    const noWalkTrack = {
      name: uniqueName('round6-nowalk'),
      layout: {
        width: 3,
        height: 3,
        tiles: [
          ['start', 'wall', 'wall'],
          ['wall', 'wall', 'wall'],
          ['wall', 'wall', 'finish']
        ]
      }
    };

    const res = await fetch(`${BASE_URL}/api/tracks`, {
      method: 'POST',
      headers: jsonHeaders,
      body: JSON.stringify(noWalkTrack)
    });
    const body = await safeJson(res);

    if ([200, 201].includes(res.status)) {
      const nwId = body.id ?? body.trackId;
      try {
        const validateRes = await fetch(`${BASE_URL}/api/tracks/${nwId}/validate`, { method: 'POST' });
        const validateBody = await safeJson(validateRes);
        expect([200, 400, 422]).toContain(validateRes.status);
        if (validateRes.status === 200 && validateBody && typeof validateBody === 'object') {
          if ('playable' in validateBody) expect(validateBody.playable).toBe(false);
          if ('canStart' in validateBody) expect(validateBody.canStart).toBe(false);
        } else {
          expect(JSON.stringify(validateBody)).toMatch(/cannot|unplayable|unreachable|blocked|invalid|no.*road/i);
        }
      } finally {
        await safeDelete(`/api/tracks/${nwId}`);
      }
    } else {
      expect([400, 409, 422]).toContain(res.status);
      expect(JSON.stringify(body)).toMatch(/cannot|unplayable|unreachable|blocked|invalid|no.*road/i);
    }
  });

  it('special terrain produces observable driving performance differences', async () => {
    // Create three tracks with different terrain types
    const makeTrack = (name, terrainType) => ({
      name: uniqueName(name),
      layout: {
        width: 6,
        height: 2,
        tiles: [
          ['start', 'road', 'road', 'road', 'road', 'finish'],
          ['road', 'road', 'road', 'road', 'road', 'road']
        ]
      },
      terrain: { default: terrainType }
    });

    const normalRes = await fetch(`${BASE_URL}/api/tracks`, { method: 'POST', headers: jsonHeaders, body: JSON.stringify(makeTrack('r6-normal', 'normal')) });
    const normalBody = await safeJson(normalRes);
    expect([200, 201]).toContain(normalRes.status);
    const normalId = normalBody.id ?? normalBody.trackId;

    const lowGripRes = await fetch(`${BASE_URL}/api/tracks`, { method: 'POST', headers: jsonHeaders, body: JSON.stringify(makeTrack('r6-lowgrip', 'low_grip')) });
    const lowGripBody = await safeJson(lowGripRes);
    expect([200, 201]).toContain(lowGripRes.status);
    const lowGripId = lowGripBody.id ?? lowGripBody.trackId;

    const slowRes = await fetch(`${BASE_URL}/api/tracks`, { method: 'POST', headers: jsonHeaders, body: JSON.stringify(makeTrack('r6-slow', 'slow')) });
    const slowBody = await safeJson(slowRes);
    expect([200, 201]).toContain(slowRes.status);
    const slowId = slowBody.id ?? slowBody.trackId;

    try {
      const fixedInputs = [
        { action: 'forward', duration: 1 },
        { action: 'forward', duration: 1 },
        { action: 'forward', duration: 1 }
      ];

      const simulate = async (trackId) => {
        const res = await fetch(`${BASE_URL}/api/tracks/${trackId}/simulate`, {
          method: 'POST',
          headers: jsonHeaders,
          body: JSON.stringify({ inputs: fixedInputs, weather: 'sunny' })
        });
        expect([200, 201]).toContain(res.status);
        return safeJson(res);
      };

      const simNormal = await simulate(normalId);
      const simLowGrip = await simulate(lowGripId);
      const simSlow = await simulate(slowId);

      const getMetric = (body) => {
        const steps = body.steps ?? body.frames ?? body.results ?? [];
        if (steps.length > 0) {
          const last = steps[steps.length - 1];
          return Number(last.speed ?? last.velocity ?? last.position?.x ?? last.x ?? 0);
        }
        return Number(body.finalSpeed ?? body.speed ?? body.position?.x ?? 0);
      };

      const normalMetric = getMetric(simNormal);
      const lowGripMetric = getMetric(simLowGrip);
      const slowMetric = getMetric(simSlow);

      // At least one terrain type must produce a different result than normal
      const hasDifference = normalMetric !== lowGripMetric || normalMetric !== slowMetric;
      expect(hasDifference).toBe(true);
    } finally {
      await safeDelete(`/api/tracks/${normalId}`);
      await safeDelete(`/api/tracks/${lowGripId}`);
      await safeDelete(`/api/tracks/${slowId}`);
    }
  });
});

