    expect((exportedTrack.checkpoints ?? []).length).toBe(2);
    expect(JSON.stringify(exportedTrack)).not.toMatch(/leaderboard|scores|entries/i);

    const importRes = await fetch(`${BASE_URL}/tracks/import`, {
      method: 'POST',
      headers: jsonHeaders,
      body: JSON.stringify({ data: exportBody })
    });
    const importBody = await safeJson(importRes);
    expect([200, 201]).toContain(importRes.status);
    const importedId = importBody.id ?? importBody.trackId;
    expect(importedId).toBeTruthy();
    cleanup.push(importedId);

    const importedGetRes = await fetch(`${BASE_URL}/tracks/${importedId}`);
    const importedGetBody = await safeJson(importedGetRes);
    expect(importedGetRes.status).toBe(200);
    expect(importedGetBody.name).toBe(originalTrack.name);
    expect(importedGetBody.weather ?? importedGetBody.weatherPreset).toBe('rainy');
    expect((importedGetBody.checkpoints ?? []).length).toBe(2);
    expect(JSON.stringify(importedGetBody.terrain ?? {})).toMatch(/normal|low_grip|slow|road/i);

    const validateRes = await fetch(`${BASE_URL}/tracks/${importedId}/validate`, { method: 'POST' });
    const validateBody = await safeJson(validateRes);
    expect([200, 204]).toContain(validateRes.status);
    if (validateBody && typeof validateBody === 'object') {
      if ('playable' in validateBody) expect(validateBody.playable).toBe(true);
      if ('canStart' in validateBody) expect(validateBody.canStart).toBe(true);
    }

    const importedLeaderboardRes = await fetch(`${BASE_URL}/leaderboards?trackId=${encodeURIComponent(importedId)}&weather=rainy&recordType=official`);
    const importedLeaderboardBody = await safeJson(importedLeaderboardRes);
    expect(importedLeaderboardRes.status).toBe(200);
    const importedEntries = Array.isArray(importedLeaderboardBody) ? importedLeaderboardBody : (importedLeaderboardBody.entries ?? importedLeaderboardBody.items ?? []);
    expect(Array.isArray(importedEntries)).toBe(true);
    expect(importedEntries.length).toBe(0);

    await Promise.all(cleanup.map((id) => safeDelete(`/tracks/${id}`)));
  });
});

import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function request(path, options = {}) {
  const res = await fetch(`${BASE_URL}${path}`, {
    headers: {
      'Content-Type': 'application/json',
      ...(options.headers || {}),
    },
    ...options,
  });

  const text = await res.text();
  let body;
  try {
    body = text ? JSON.parse(text) : null;
  } catch {
    body = text;
  }

  return { res, body };
}

function getId(obj) {
  if (!obj) return null;
  return obj.id || obj.caseId || obj.npcId || obj.characterId || obj.evidenceId || obj.questionId || null;
}

function extractList(body) {
  if (Array.isArray(body)) return body;
  if (!body) return [];
  for (const key of ['items', 'questions', 'history', 'messages', 'clues', 'evidence', 'characters', 'npcs', 'followUps']) {
    if (Array.isArray(body[key])) return body[key];
  }
  return [];
}

describe('dialogue_and_question_states_persist_across_navigation', () => {
  it('should persist dialogue history, asked/unlocked/locked/follow-up states, and testimony/note clues across navigation', async () => {
    const runId = `dialogue-persist-${Date.now()}`;

    // Create case
    const createCase = await request('/api/cases', {
      method: 'POST',
      body: JSON.stringify({ title: `Dialogue Persist ${runId}` }),
    });
    expect([200, 201]).toContain(createCase.res.status);
    const caseId = getId(createCase.body);
    expect(caseId).toBeTruthy();
    const basePath = `/api/cases/${caseId}`;

    try {
      // Get NPCs
      const npcsRes = await request(`${basePath}/npcs`, { method: 'GET' });
      expect(npcsRes.res.status).toBe(200);
      const npcList = extractList(npcsRes.body);
      expect(npcList.length).toBeGreaterThan(0);
      const npcId = getId(npcList[0]);
      expect(npcId).toBeTruthy();

      // Create evidence to enable question unlocking
      const createEvidence = await request(`${basePath}/evidence`, {
        method: 'POST',
        body: JSON.stringify({ itemId: `torn-letter-${runId}`, name: 'Torn Letter', category: 'physical', description: 'A torn letter found at the scene' }),
      });
      expect([200, 201]).toContain(createEvidence.res.status);
      const evidenceId = getId(createEvidence.body) || `torn-letter-${runId}`;

      // Get initial questions for NPC
      const initialQuestions = await request(`${basePath}/npcs/${npcId}/questions`, { method: 'GET' });
      expect(initialQuestions.res.status).toBe(200);
      const questionListBefore = extractList(initialQuestions.body);
      expect(questionListBefore.length).toBeGreaterThan(0);

      const unlockedBefore = questionListBefore.find(q => q.locked === false || q.unlocked === true);
      const lockedBefore = questionListBefore.find(q => q.locked === true || q.unlocked === false);
      expect(unlockedBefore, 'expected at least one initially unlocked question').toBeTruthy();

      // Verify locked question has hint/reason
      if (lockedBefore) {
        const lockedHint = lockedBefore.hint || lockedBefore.reason || lockedBefore.lockReason || lockedBefore.description;
        expect(lockedHint, `Locked question should have hint/reason, got ${JSON.stringify(lockedBefore)}`).toBeTruthy();
      }

      const askedQuestionIds = [];

      // Ask the unlocked question
      const firstQuestionId = getId(unlockedBefore) || unlockedBefore.questionId;
      const askFirst = await request(`${basePath}/npcs/${npcId}/ask`, {
        method: 'POST',
        body: JSON.stringify({ questionId: firstQuestionId }),
      });
      expect([200, 201]).toContain(askFirst.res.status);
      const firstAnswer = askFirst.body?.answer || askFirst.body?.reply || askFirst.body?.message;
      expect(firstAnswer, 'Ask response should include answer/reply/message').toBeTruthy();
      askedQuestionIds.push(firstQuestionId);

      // Record first answer content for persistence check
      const firstAnswerContent = String(firstAnswer);

      // Boundary: re-ask the same question (should be rejected or idempotent)
      const reAsk = await request(`${basePath}/npcs/${npcId}/ask`, {
        method: 'POST',
        body: JSON.stringify({ questionId: firstQuestionId }),
      });
      expect(
        [200, 201, 400, 409, 422].includes(reAsk.res.status),
        `Re-asking same question should be handled gracefully, got ${reAsk.res.status}`
      ).toBe(true);

      // Boundary: try to ask a locked question (should fail)
      if (lockedBefore) {
        const lockedQId = getId(lockedBefore) || lockedBefore.questionId;
        const askLocked = await request(`${basePath}/npcs/${npcId}/ask`, {
          method: 'POST',
          body: JSON.stringify({ questionId: lockedQId }),
        });
        expect(
          [400, 403, 422, 423].includes(askLocked.res.status),
          `Asking locked question should fail with 4xx, got ${askLocked.res.status}`
        ).toBe(true);
        const lockReasonInResponse = askLocked.body?.reason || askLocked.body?.message || askLocked.body?.error;
        expect(lockReasonInResponse, `Lock rejection should include reason`).toBeTruthy();
      }

      // Unlock question via evidence
      const unlockRes = await request(`${basePath}/npcs/${npcId}/unlock-questions`, {
        method: 'POST',
        body: JSON.stringify({ evidenceId }),
      });
      expect([200, 201]).toContain(unlockRes.res.status);

      // Get questions after unlock
      const postUnlockQuestions = await request(`${basePath}/npcs/${npcId}/questions`, { method: 'GET' });
      expect(postUnlockQuestions.res.status).toBe(200);
      const questionListAfterUnlock = extractList(postUnlockQuestions.body);

      // Find newly unlocked question
      const unlockedIds = (unlockRes.body?.unlockedQuestionIds || []);
      let newUnlockedId = unlockedIds[0];
      if (!newUnlockedId) {
        const newlyUnlocked = questionListAfterUnlock.find(q => {
          const qId = getId(q) || q.questionId;
          return (q.unlocked === true || q.locked === false) && !askedQuestionIds.includes(qId) && qId !== firstQuestionId;
        });
        newUnlockedId = newlyUnlocked ? (getId(newlyUnlocked) || newlyUnlocked.questionId) : null;
      }
      expect(newUnlockedId, 'Expected at least one question to become available after evidence unlock').toBeTruthy();

      // Ask the newly unlocked question
      const askUnlocked = await request(`${basePath}/npcs/${npcId}/ask`, {
        method: 'POST',
        body: JSON.stringify({ questionId: newUnlockedId }),
      });
      expect([200, 201]).toContain(askUnlocked.res.status);
      const secondAnswer = askUnlocked.body?.answer || askUnlocked.body?.reply || askUnlocked.body?.message;
      expect(secondAnswer, 'Unlocked question ask should include answer').toBeTruthy();
      askedQuestionIds.push(newUnlockedId);
      const secondAnswerContent = String(secondAnswer);

      // Check follow-up questions
      const followUpRes = await request(`${basePath}/npcs/${npcId}/follow-ups`, { method: 'GET' });
      let followUpExists = false;
      if (followUpRes.res.status === 200) {
        const followUpList = extractList(followUpRes.body);
        if (followUpList.length > 0) {
          followUpExists = true;
          const fu = followUpList[0];
          const isFollowUp = fu.type === 'follow_up' || fu.isFollowUp === true || fu.followUp === true || fu.category === 'follow_up';
          expect(isFollowUp, `Follow-up questions should be distinguishable from regular questions, got ${JSON.stringify(fu)}`).toBe(true);
        }
      }

      // Record dialogue history BEFORE navigation simulation
      const historyBefore = await request(`${basePath}/npcs/${npcId}/dialogue-history`, { method: 'GET' });
      expect(historyBefore.res.status).toBe(200);
      const historyListBefore = extractList(historyBefore.body);
      expect(historyListBefore.length).toBeGreaterThanOrEqual(2);

      // Record specific entries for content comparison
      const historyContentsBefore = historyListBefore.map(h => ({
        questionId: h.questionId || h.id,
        answer: h.answer || h.reply || h.message || h.text,
      }));

      // Check clues — verify testimony vs note types
      const cluesBefore = await request(`${basePath}/evidence`, { method: 'GET' });
      expect(cluesBefore.res.status).toBe(200);
      const clueListBefore = extractList(cluesBefore.body);
      const npcCluesBefore = clueListBefore.filter(clue => {
        return clue.npcId === npcId || clue.sourceNpcId === npcId ||
          clue.category === 'testimony' || clue.type === 'testimony' || clue.type === 'note';
      });
      // Record types for persistence check
      const clueTypesBefore = npcCluesBefore.map(c => ({
        id: c.id,
        type: c.type || c.category,
        title: c.title || c.name || c.summary,
      }));

      // === Simulate navigation: access other pages then come back ===
      // Access evidence board (simulates switching to another tab)
      await request(`${basePath}/evidence`, { method: 'GET' });
      // Access timeline (simulates switching to another tab)
      await request(`${basePath}/timeline`, { method: 'GET' });
      // Access case overview
      await request(basePath, { method: 'GET' });

      // === Now "navigate back" to NPC page — re-fetch everything ===

      // Re-check questions: asked status should persist
      const questionsAfterRefresh = await request(`${basePath}/npcs/${npcId}/questions`, { method: 'GET' });
      expect(questionsAfterRefresh.res.status).toBe(200);
      const questionListAfterRefresh = extractList(questionsAfterRefresh.body);

      for (const askedId of askedQuestionIds) {
        const askedRecord = questionListAfterRefresh.find(q => (getId(q) || q.questionId) === askedId);
        expect(askedRecord, `Asked question ${askedId} should still exist after navigation`).toBeTruthy();
        const isMarkedAsked = askedRecord.asked === true || askedRecord.hasAsked === true || askedRecord.status === 'asked';
        expect(isMarkedAsked, `Question ${askedId} should be marked as asked after navigation, got ${JSON.stringify(askedRecord)}`).toBe(true);
      }

      // Unlocked question should still be unlocked
      const unlockedRecord = questionListAfterRefresh.find(q => (getId(q) || q.questionId) === newUnlockedId);
      expect(unlockedRecord, 'Unlocked question should exist after navigation').toBeTruthy();
      expect(
        unlockedRecord.locked === false || unlockedRecord.unlocked === true,
        'Unlocked question should remain unlocked after navigation'
      ).toBe(true);

      // Locked questions should remain locked (ones we didn't unlock)
      if (lockedBefore) {
        const lockedId = getId(lockedBefore) || lockedBefore.questionId;
        if (lockedId !== newUnlockedId) {
          const lockedRecord = questionListAfterRefresh.find(q => (getId(q) || q.questionId) === lockedId);
          if (lockedRecord) {
            expect(
              lockedRecord.locked === true || lockedRecord.unlocked === false,
              'Unrelated locked question should remain locked'
            ).toBe(true);
          }
        }
      }

      // Dialogue history persists with same content
      const historyAfter = await request(`${basePath}/npcs/${npcId}/dialogue-history`, { method: 'GET' });
      expect(historyAfter.res.status).toBe(200);
      const historyListAfter = extractList(historyAfter.body);
      expect(historyListAfter.length).toBe(historyListBefore.length);

      // Verify specific content matches
      const historyContentsAfter = historyListAfter.map(h => ({
        questionId: h.questionId || h.id,
        answer: h.answer || h.reply || h.message || h.text,
      }));
      for (const beforeEntry of historyContentsBefore) {
        const matchingAfter = historyContentsAfter.find(a => a.questionId === beforeEntry.questionId);
        expect(matchingAfter, `Dialogue entry for question ${beforeEntry.questionId} should persist`).toBeTruthy();
        if (beforeEntry.answer && matchingAfter) {
          expect(matchingAfter.answer).toBe(beforeEntry.answer);
        }
      }

      // Clues persist with same types
      const cluesAfter = await request(`${basePath}/evidence`, { method: 'GET' });
      expect(cluesAfter.res.status).toBe(200);
      const clueListAfter = extractList(cluesAfter.body);
      const npcCluesAfter = clueListAfter.filter(clue => {
        return clue.npcId === npcId || clue.sourceNpcId === npcId ||
          clue.category === 'testimony' || clue.type === 'testimony' || clue.type === 'note';
      });
      expect(npcCluesAfter.length).toBe(npcCluesBefore.length);

      // Verify type preservation (testimony vs note distinction)
      for (const beforeClue of clueTypesBefore) {
        const afterClue = npcCluesAfter.find(c => c.id === beforeClue.id);
        expect(afterClue, `NPC clue ${beforeClue.id} should persist after navigation`).toBeTruthy();
        if (afterClue) {
          const afterType = afterClue.type || afterClue.category;
          expect(afterType).toBe(beforeClue.type);
          const afterTitle = afterClue.title || afterClue.name || afterClue.summary;
          expect(afterTitle).toBe(beforeClue.title);
        }
      }

      // Follow-up state persists
      if (followUpExists) {
        const followUpAfter = await request(`${basePath}/npcs/${npcId}/follow-ups`, { method: 'GET' });
        expect(followUpAfter.res.status).toBe(200);
        const followUpListAfter = extractList(followUpAfter.body);
        expect(followUpListAfter.length).toBeGreaterThan(0);
      }
    } finally {
      await request(basePath, { method: 'DELETE' }).catch(() => {});
    }
  });
});

import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function request(path, options = {}) {
  const res = await fetch(`${BASE_URL}${path}`, {
    headers: { 'Content-Type': 'application/json', ...(options.headers || {}) },
    ...options,
  });
  let body = null;
  const text = await res.text();
  try {
    body = text ? JSON.parse(text) : null;
  } catch {
    body = text;
  }
  return { res, body };
}

async function cleanup(path) {
  try {
    await fetch(`${BASE_URL}${path}`, { method: 'DELETE' });
  } catch {}
}

describe('review_mode_is_read_only_and_switches_with_imported_save', () => {
  it('should build review history from actual operations, be read-only, show draft-to-final report evolution, preserve invalidated reasoning traces, and switch content on import', async () => {
    // --- Session A: perform actual operations to generate history ---
    const suffixA = Date.now();
    const sessionRespA = await request('/api/sessions', {
      method: 'POST',
      body: JSON.stringify({ name: `review-session-A-${suffixA}` }),
    });
    expect([200, 201]).toContain(sessionRespA.res.status);
    const sessionIdA = sessionRespA.body?.id || sessionRespA.body?.sessionId;
    expect(sessionIdA).toBeTruthy();

    try {
      // Step 1: Collect evidence
      const ev1 = await request(`/api/sessions/${sessionIdA}/evidence/collect`, {
        method: 'POST',
        body: JSON.stringify({ areaId: 'scene', objectId: 'obj-knife', evidenceId: `knife-${suffixA}`, name: 'Knife' }),
      });
      expect([200, 201]).toContain(ev1.res.status);

      const ev2 = await request(`/api/sessions/${sessionIdA}/evidence/collect`, {
        method: 'POST',
        body: JSON.stringify({ areaId: 'scene', objectId: 'obj-letter', evidenceId: `letter-${suffixA}`, name: 'Letter' }),
      });
      expect([200, 201]).toContain(ev2.res.status);

      // Step 2: Interrogate an NPC
      const npcsResp = await request(`/api/sessions/${sessionIdA}/npcs`);
      if (npcsResp.res.status === 200) {
        const npcs = npcsResp.body?.items || npcsResp.body?.npcs || npcsResp.body || [];
        if (Array.isArray(npcs) && npcs.length > 0) {
          const npcId = npcs[0].id || npcs[0].npcId;
          if (npcId) {
            const questions = await request(`/api/sessions/${sessionIdA}/npcs/${npcId}/questions`);
            if (questions.res.status === 200) {
              const qs = questions.body?.items || questions.body?.questions || questions.body || [];
              if (Array.isArray(qs) && qs.length > 0) {
                const qId = qs[0].id || qs[0].questionId;
                if (qId) {
                  await request(`/api/sessions/${sessionIdA}/npcs/${npcId}/ask`, {
                    method: 'POST',
                    body: JSON.stringify({ questionId: qId }),
                  });
                }
              }
            }
          }
        }
      }

      // Step 3: Create a reasoning record
      const reasoning = await request(`/api/sessions/${sessionIdA}/reasoning`, {
        method: 'POST',
        body: JSON.stringify({ clueIds: [`knife-${suffixA}`, `letter-${suffixA}`], conclusion: 'Connected evidence A' }),
      });
      expect([200, 201]).toContain(reasoning.res.status);
      const reasoningId = reasoning.body?.id || reasoning.body?.reasoningId;
      expect(reasoningId).toBeTruthy();

      // Step 4: Save a draft report
      const draftResp = await request(`/api/sessions/${sessionIdA}/report`, {
        method: 'POST',
        body: JSON.stringify({
          suspectId: 'suspect_alpha',
          reasoning: 'Draft reasoning text.',
          keyEvidence: [`knife-${suffixA}`],
          status: 'draft',
        }),
      });
      expect([200, 201]).toContain(draftResp.res.status);

      // Step 5: Delete the reasoning (invalidate it)
      const delReasoning = await request(`/api/sessions/${sessionIdA}/reasoning/${reasoningId}`, { method: 'DELETE' });
      expect([200, 204]).toContain(delReasoning.res.status);

      // Step 6: Submit final report
      const finalResp = await request(`/api/sessions/${sessionIdA}/report`, {
        method: 'POST',
        body: JSON.stringify({
          suspectId: 'suspect_alpha',
          reasoning: 'Final reasoning after revision.',
          keyEvidence: [`knife-${suffixA}`],
          status: 'final',
        }),
      });
      expect([200, 201]).toContain(finalResp.res.status);

      // --- Verify review mode for session A ---
      const reviewA = await request(`/api/sessions/${sessionIdA}/review`, { method: 'GET' });
      expect(reviewA.res.status).toBe(200);
      const reviewBodyA = reviewA.body;

      // Review must be read-only
      const isReadOnly = reviewBodyA.readOnly ?? reviewBodyA.isReadOnly ?? reviewBodyA.readonly;
      expect(isReadOnly, 'Review mode should be marked as read-only').toBe(true);

      // Review history should be in chronological order and contain operation entries
      const historyA = reviewBodyA.history || reviewBodyA.items || reviewBodyA.entries || [];
      expect(historyA.length).toBeGreaterThanOrEqual(3);

      // Verify chronological order
      if (historyA.length > 1 && historyA[0].at) {
        for (let i = 1; i < historyA.length; i++) {
          if (historyA[i].at && historyA[i - 1].at) {
            expect(new Date(historyA[i - 1].at).getTime()).toBeLessThanOrEqual(new Date(historyA[i].at).getTime());
          }
        }
      }

      // Verify invalidated reasoning has a trace — match by reasoningId or conclusion text
      const invalidatedEntry = historyA.find((item) => {
        const itemStr = JSON.stringify(item).toLowerCase();
        const matchesReasoning = itemStr.includes(String(reasoningId).toLowerCase()) || itemStr.includes('connected evidence a');
        const isInvalidated = item.invalidated === true || item.status === 'invalidated' || item.status === 'deleted' || (item.changeNote && item.changeNote.length > 0) || (item.statusNote && item.statusNote.length > 0) || (item.note && item.note.length > 0);
        return matchesReasoning && isInvalidated;
      });
      // Fallback: if no exact match by id, look for any invalidated entry related to reasoning
      const fallbackInvalidated = invalidatedEntry || historyA.find((item) => {
        const itemStr = JSON.stringify(item).toLowerCase();
        return (itemStr.includes('reasoning') || itemStr.includes('推理')) && (item.invalidated === true || item.status === 'invalidated' || item.status === 'deleted');
      });
      expect(fallbackInvalidated, 'Review should preserve traces of the specific invalidated/deleted reasoning').toBeTruthy();
      const changeDescription = fallbackInvalidated.changeNote || fallbackInvalidated.statusNote || fallbackInvalidated.note || fallbackInvalidated.description || '';
      expect(changeDescription.length, 'Change note for invalidated entry should contain meaningful text explaining what changed').toBeGreaterThan(0);

      // Verify draft-to-final report evolution: at least 2 report entries (draft + final)
      const reportEntries = historyA.filter((item) => {
        const t = item.type || item.label || '';
        return /report|case_report|report_draft|report_final/i.test(t);
      });
      expect(reportEntries.length, 'Should have at least 2 report entries showing draft-to-final evolution').toBeGreaterThanOrEqual(2);
      // Verify we can distinguish draft and final among report entries
      const hasDraftEntry = reportEntries.some((e) => {
        const s = JSON.stringify(e).toLowerCase();
        return s.includes('draft');
      });
      const hasFinalEntry = reportEntries.some((e) => {
        const s = JSON.stringify(e).toLowerCase();
        return s.includes('final');
      });
      expect(hasDraftEntry, 'Report entries should include a draft stage').toBe(true);
      expect(hasFinalEntry, 'Report entries should include a final stage').toBe(true);

      // --- Verify read-only: attempt to modify via review endpoint ---
      const modifyResp = await request(`/api/sessions/${sessionIdA}/review`, {
        method: 'POST',
        body: JSON.stringify({ action: 'mutate_state', any: 'value' }),
      });
      expect([400, 403, 405]).toContain(modifyResp.res.status);

      // Also verify that after case is finalized, business endpoints reject modifications
      const tryCollectAfterFinal = await request(`/api/sessions/${sessionIdA}/evidence/collect`, {
        method: 'POST',
        body: JSON.stringify({ areaId: 'scene', objectId: 'obj-extra', evidenceId: `extra-${suffixA}`, name: 'ExtraItem' }),
      });
      // Should be rejected since case is closed/finalized (400/403/409)
      if (![200, 201].includes(tryCollectAfterFinal.res.status)) {
        expect([400, 403, 409]).toContain(tryCollectAfterFinal.res.status);
      }

      const tryReasoningAfterFinal = await request(`/api/sessions/${sessionIdA}/reasoning`, {
        method: 'POST',
        body: JSON.stringify({ clueIds: [`knife-${suffixA}`, `letter-${suffixA}`], conclusion: 'Should fail' }),
      });
      if (![200, 201].includes(tryReasoningAfterFinal.res.status)) {
        expect([400, 403, 409]).toContain(tryReasoningAfterFinal.res.status);
      }

      // --- Session B: create separate session with different operations ---
      const suffixB = Date.now() + 1;
      const sessionRespB = await request('/api/sessions', {
        method: 'POST',
        body: JSON.stringify({ name: `review-session-B-${suffixB}` }),
      });
      expect([200, 201]).toContain(sessionRespB.res.status);
      const sessionIdB = sessionRespB.body?.id || sessionRespB.body?.sessionId;
      expect(sessionIdB).toBeTruthy();

      try {
        // Collect different evidence in session B
        const evB = await request(`/api/sessions/${sessionIdB}/evidence/collect`, {
          method: 'POST',
          body: JSON.stringify({ areaId: 'garden', objectId: 'obj-watch', evidenceId: `watch-${suffixB}`, name: 'Watch' }),
        });
        expect([200, 201]).toContain(evB.res.status);

        // Submit final report for session B
        const finalB = await request(`/api/sessions/${sessionIdB}/report`, {
          method: 'POST',
          body: JSON.stringify({
            suspectId: 'suspect_beta',
            reasoning: 'Session B conclusion.',
            keyEvidence: [`watch-${suffixB}`],
            status: 'final',
          }),
        });
        expect([200, 201]).toContain(finalB.res.status);

        // --- Export session A's save data ---
        const exportA = await request(`/api/sessions/${sessionIdA}/export`, { method: 'GET' });
        expect(exportA.res.status).toBe(200);
        expect(exportA.body).toBeTruthy();
        const exportedDataA = exportA.body;

        // --- Import session A's save into session B's context ---
        const importResp = await request(`/api/sessions/${sessionIdB}/import`, {
          method: 'POST',
          body: JSON.stringify(exportedDataA),
        });
        expect([200, 201]).toContain(importResp.res.status);

        // --- Verify review mode for session B now shows session A's history (imported save) ---
        const reviewBAfterImport = await request(`/api/sessions/${sessionIdB}/review`, { method: 'GET' });
        expect(reviewBAfterImport.res.status).toBe(200);
        const historyBAfterImport = reviewBAfterImport.body?.history || reviewBAfterImport.body?.items || reviewBAfterImport.body?.entries || [];
        expect(historyBAfterImport.length).toBeGreaterThanOrEqual(1);

        // After import, the review should contain session A's Knife evidence, not (only) session B's Watch
        const hasKnifeEntry = historyBAfterImport.some((item) => {
          const txt = JSON.stringify(item).toLowerCase();
          return txt.includes('knife');
        });
        expect(hasKnifeEntry, 'After importing session A save, review should contain Knife evidence from A').toBe(true);

        // The old Watch-only history from session B should be replaced by the imported data
        // (imported save replaces current context)
        // We check that the review corresponds to the imported archive, not the old B state
        const hasSessionAContent = historyBAfterImport.some((item) => {
          const txt = JSON.stringify(item).toLowerCase();
          return txt.includes('knife') || txt.includes('connected evidence a') || txt.includes('draft reasoning text');
        });
        expect(hasSessionAContent, 'Review after import should correspond to the imported save data').toBe(true);
      } finally {
        await cleanup(`/api/sessions/${sessionIdB}`);
      }
    } finally {
      await cleanup(`/api/sessions/${sessionIdA}`);
    }
  });
});

import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function request(method, path, body) {
  const res = await fetch(`${BASE_URL}${path}`, {
    method,
    headers: body ? { 'Content-Type': 'application/json' } : undefined,
    body: body ? JSON.stringify(body) : undefined,
  });

  let json = null;
  const text = await res.text();
  try {
    json = text ? JSON.parse(text) : null;
  } catch {
    json = text;
  }
  return { res, body: json };
}

async function safeDelete(path) {
  try {
    await fetch(`${BASE_URL}${path}`, { method: 'DELETE' });
  } catch { /* ignore */ }
}

function getId(obj) {
  if (!obj) return null;
  return obj.id || obj.caseId || obj.saveId || null;
}

