    const id = created.body.id ?? created.body.caseId;
    expect(id, `Expected case id from creation, got ${JSON.stringify(created.body)}`).toBeTruthy();
    return id;
  }

  async function cleanupCase(id) {
    if (id) {
      await request(`/api/cases/${id}`, { method: 'DELETE' }).catch(() => {});
    }
  }

  async function setupFullConditions(caseId, overrides = {}) {
    const reportPayload = {
      suspectId: overrides.suspectId || 'suspect_true',
      reasoning: overrides.reasoning || '完整还原作案过程并提供三条关键依据。',
      keyEvidence: overrides.keyEvidence || ['clue_a', 'clue_b', 'clue_c'],
      status: overrides.reportStatus || 'final',
    };
    const reportRes = await request(`/api/cases/${caseId}/report`, {
      method: 'POST',
      body: JSON.stringify(reportPayload),
    });
    expect([200, 201]).toContain(reportRes.res.status);

    const timelinePayload = overrides.timeline || { id: 'event_clean', label: '无矛盾时间线', contradiction: false };
    const timelineRes = await request(`/api/cases/${caseId}/timeline`, {
      method: 'POST',
      body: JSON.stringify(timelinePayload),
    });
    expect([200, 201]).toContain(timelineRes.res.status);

    const suspicionPayload = {
      suspectId: overrides.suspicionSuspectId || overrides.suspectId || 'suspect_true',
