import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function request(path, options = {}) {
  const res = await fetch(`${BASE_URL}${path}`, {
    headers: {
      'Content-Type': 'application/json',
      ...(options.headers || {}),
    },
    ...options,
  });
  const text = await res.text();
  let body = null;
  try {
    body = text ? JSON.parse(text) : null;
  } catch {
    body = text;
  }
  return { res, body };
}

async function cleanup(paths) {
  for (const path of paths) {
    try {
      await fetch(`${BASE_URL}${path}`, { method: 'DELETE' });
    } catch {}
  }
}

describe('round4_reasoning_record_constraints', () => {
  it('should only allow 2-3 unique clue combinations, reject duplicates and boundary violations, list saved reasoning, and mark referenced clues', async () => {
    const suffix = Date.now();
    const cleanupPaths = [];

    try {
      // Create session
      const sessionResp = await request('/api/sessions', {
        method: 'POST',
        body: JSON.stringify({ name: `reasoning-session-${suffix}` })
      });
      expect([200, 201]).toContain(sessionResp.res.status);
      const sessionId = sessionResp.body?.id || sessionResp.body?.sessionId;
      expect(sessionId).toBeTruthy();
      cleanupPaths.push(`/api/sessions/${sessionId}`);

      // --- Empty state: reasoning list should show guidance ---
      const emptyList = await request(`/api/sessions/${sessionId}/reasoning`, { method: 'GET' });
      expect(emptyList.res.status).toBe(200);
      const emptyItems = emptyList.body?.items || emptyList.body?.reasoning || [];
      // Check for empty state guidance message
      const emptyMessage = emptyList.body?.message || emptyList.body?.hint || emptyList.body?.emptyMessage || '';
      if (emptyItems.length === 0) {
        expect(emptyMessage.length > 0 || emptyList.body?.empty === true, 'Empty reasoning list should include guidance or empty indicator').toBe(true);
      }

      // Collect 4 pieces of evidence for various tests
      for (const id of [`r1-${suffix}`, `r2-${suffix}`, `r3-${suffix}`, `r4-${suffix}`]) {
        const collect = await request(`/api/sessions/${sessionId}/evidence/collect`, {
          method: 'POST',
          body: JSON.stringify({ areaId: 'lab', objectId: `obj-${id}`, evidenceId: id, name: id })
        });
        expect([200, 201]).toContain(collect.res.status);
      }

      // --- Boundary: empty clueIds (nothing selected) ---
      const invalidEmpty = await request(`/api/sessions/${sessionId}/reasoning`, {
        method: 'POST',
        body: JSON.stringify({ clueIds: [], conclusion: 'nothing selected' })
      });
      expect([400, 422]).toContain(invalidEmpty.res.status);

      // --- Boundary: fewer than 2 clues ---
      const invalidTooFew = await request(`/api/sessions/${sessionId}/reasoning`, {
        method: 'POST',
        body: JSON.stringify({ clueIds: [`r1-${suffix}`], conclusion: 'too few' })
      });
      expect([400, 422]).toContain(invalidTooFew.res.status);

      // --- Boundary: more than 3 clues ---
      const invalidTooMany = await request(`/api/sessions/${sessionId}/reasoning`, {
        method: 'POST',
        body: JSON.stringify({ clueIds: [`r1-${suffix}`, `r2-${suffix}`, `r3-${suffix}`, `r4-${suffix}`], conclusion: 'too many' })
      });
      expect([400, 422]).toContain(invalidTooMany.res.status);

      // --- Boundary: duplicate clue IDs in same submission ---
      const invalidDuplicate = await request(`/api/sessions/${sessionId}/reasoning`, {
        method: 'POST',
        body: JSON.stringify({ clueIds: [`r1-${suffix}`, `r1-${suffix}`], conclusion: 'duplicate ids' })
      });
      expect([400, 409, 422]).toContain(invalidDuplicate.res.status);

      // --- Valid: 3 clues ---
      const valid = await request(`/api/sessions/${sessionId}/reasoning`, {
        method: 'POST',
        body: JSON.stringify({ clueIds: [`r1-${suffix}`, `r2-${suffix}`, `r3-${suffix}`], conclusion: 'linked sequence' })
      });
      expect([200, 201]).toContain(valid.res.status);
      const reasoningId = valid.body?.id || valid.body?.reasoningId;
      expect(reasoningId, `expected saved reasoning id, got ${JSON.stringify(valid.body)}`).toBeTruthy();

      // --- Duplicate combination: same clueIds should be rejected ---
      const duplicateCombo = await request(`/api/sessions/${sessionId}/reasoning`, {
        method: 'POST',
        body: JSON.stringify({ clueIds: [`r1-${suffix}`, `r2-${suffix}`, `r3-${suffix}`], conclusion: 'same combo again' })
      });
      expect([400, 409, 422]).toContain(duplicateCombo.res.status);

      // --- Also test same combo in different order (should still be rejected) ---
      const duplicateComboReorder = await request(`/api/sessions/${sessionId}/reasoning`, {
        method: 'POST',
        body: JSON.stringify({ clueIds: [`r3-${suffix}`, `r1-${suffix}`, `r2-${suffix}`], conclusion: 'reordered same combo' })
      });
      expect([400, 409, 422]).toContain(duplicateComboReorder.res.status);

      // --- List reasoning and verify saved record ---
      const list = await request(`/api/sessions/${sessionId}/reasoning`, { method: 'GET' });
      expect(list.res.status).toBe(200);
      const items = list.body?.items || list.body?.reasoning || [];
      expect(Array.isArray(items)).toBe(true);
      const saved = items.find(i => i.id === reasoningId || i.reasoningId === reasoningId);
      expect(saved, `expected saved reasoning in list, got ${JSON.stringify(items)}`).toBeTruthy();
      const savedClueIds = saved.clueIds || saved.clues || [];
      expect(savedClueIds.length, `expected saved reasoning to contain 3 clues, got ${JSON.stringify(saved)}`).toBe(3);

      // --- Verify clues are marked as referenced by reasoning ---
      const cluesResp = await request(`/api/sessions/${sessionId}/clues`, { method: 'GET' });
      expect(cluesResp.res.status).toBe(200);
      const clues = cluesResp.body?.clues || cluesResp.body?.items || [];
      expect(Array.isArray(clues)).toBe(true);
      for (const clueId of [`r1-${suffix}`, `r2-${suffix}`, `r3-${suffix}`]) {
        const clue = clues.find(c => c.id === clueId || c.evidenceId === clueId);
        expect(clue, `expected clue ${clueId} to exist, got ${JSON.stringify(clues)}`).toBeTruthy();
        expect(
          clue.referencedByReasoning === true ||
          clue.reasoningReferenced === true ||
          clue.highlighted === true ||
          (Array.isArray(clue.references) && clue.references.length > 0) ||
          (Array.isArray(clue.usedInReasoning) && clue.usedInReasoning.length > 0),
          `expected clue ${clueId} to be marked as used in reasoning, got ${JSON.stringify(clue)}`
        ).toBe(true);
      }
    } finally {
      await cleanup(cleanupPaths);
    }
  });
});

import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function request(path, options = {}) {
  const res = await fetch(`${BASE_URL}${path}`, {
    headers: {
      'Content-Type': 'application/json',
      ...(options.headers || {}),
    },
    ...options,
  });
  const text = await res.text();
  let body = null;
  try {
    body = text ? JSON.parse(text) : null;
  } catch {
    body = text;
  }
  return { res, body };
}

function extractId(obj, ...keys) {
  if (!obj) return null;
  for (const k of keys) {
    if (obj[k]) return obj[k];
  }
  return null;
}

async function tryRequest(paths, options = {}) {
  for (const path of paths) {
    const result = await request(path, options);
    if ([200, 201].includes(result.res.status)) return { ...result, path };
  }
  // Return last attempt
  return { ...(await request(paths[paths.length - 1], options)), path: paths[paths.length - 1] };
}

