      method: 'POST',
      body: JSON.stringify({ title: `closure-test-${suffix}` }),
    });
    if ([200, 201].includes(createCase.res.status)) {
      caseId = extractId(createCase.body, 'id', 'caseId');
      basePath = `/api/cases/${caseId}`;
    }
    if (!caseId) {
      const createSession = await request('/api/sessions', {
        method: 'POST',
        body: JSON.stringify({ name: `closure-session-${suffix}` }),
      });
      expect([200, 201]).toContain(createSession.res.status);
      caseId = extractId(createSession.body, 'id', 'sessionId', 'caseId');
      basePath = `/api/sessions/${caseId}`;
    }
