      const draftSave = await tryRequest(reportPaths, {
        method: 'POST',
        body: JSON.stringify({
          suspectId: 'suspect-A',
          logic: validLogic,
          keyEvidence: [ev1Id, ev2Id],
          status: 'draft',
        }),
      });
      expect([200, 201]).toContain(draftSave.res.status);
      const draftBody = draftSave.body;
      expect(draftBody).toBeTruthy();

      // Draft should persist and NOT have a final ending
      const getDraft = await tryRequest(reportPaths, { method: 'GET' });
      expect(getDraft.res.status).toBe(200);
      const draftData = getDraft.body?.report || getDraft.body?.closure || getDraft.body;
      expect(draftData).toBeTruthy();
      const draftStatus = draftData.status || draftData.state;
      // Draft should indicate it is a draft, not a final/submitted state
      expect(
        draftStatus === 'draft' || !draftData.ending || !draftData.endingType,
        `expected draft to not trigger final ending, got ${JSON.stringify(draftData)}`
      ).toBe(true);
      // Verify reasoning text preserved
      const draftLogic = draftData.logic || draftData.reasoning;
      expect(draftLogic).toBe(validLogic);

      // === Validation: key evidence > 3 should be rejected ===
      const tooManyEvidence = await tryRequest(reportPaths, {
        method: 'POST',
        body: JSON.stringify({
          suspectId: 'suspect-A',
          logic: validLogic,
          keyEvidence: [ev1Id, ev2Id, ev3Id, ev4Id],
          status: 'draft',
        }),
      });
      expect([400, 422]).toContain(tooManyEvidence.res.status);

      // === Validation: key evidence < 1 for final submission should be rejected ===
      const noEvidenceFinal = await tryRequest(reportPaths, {
        method: 'POST',
        body: JSON.stringify({
          suspectId: 'suspect-A',
          logic: validLogic,
          keyEvidence: [],
          status: 'final',
        }),
      });
      expect([400, 422]).toContain(noEvidenceFinal.res.status);

      // After failed submission, previous draft should still be preserved
      const afterFailGet = await tryRequest(reportPaths, { method: 'GET' });
      expect(afterFailGet.res.status).toBe(200);
      const afterFailData = afterFailGet.body?.report || afterFailGet.body?.closure || afterFailGet.body;
      const afterFailLogic = afterFailData?.logic || afterFailData?.reasoning;
      expect(afterFailLogic).toBe(validLogic);

      // === Step 2: Final submission — triggers ending ===
      const finalSubmit = await tryRequest(reportPaths, {
        method: 'POST',
        body: JSON.stringify({
          suspectId: 'suspect-A',
          logic: validLogic,
          keyEvidence: [ev1Id, ev2Id, ev3Id],
          status: 'final',
        }),
      });
      expect([200, 201]).toContain(finalSubmit.res.status);
      const finalBody = finalSubmit.body;
      expect(finalBody).toBeTruthy();

      // Verify ending was generated
      const endingType = finalBody.endingType || finalBody.ending || finalBody.result || finalBody.outcomeType || finalBody.status;
      expect(endingType, `expected final submission to produce an ending/result, got ${JSON.stringify(finalBody)}`).toBeTruthy();

      // Verify suspect identity in response
      const returnedSuspect = finalBody.suspectId || finalBody.suspect || (finalBody.closure && finalBody.closure.suspectId);
      expect(returnedSuspect).toBe('suspect-A');

      // Verify key evidence echoed back
      const returnedEvidence = finalBody.keyEvidence || finalBody.keyEvidences || finalBody.evidence || (finalBody.closure && finalBody.closure.keyEvidence) || [];
      expect(returnedEvidence.length).toBeGreaterThanOrEqual(1);

      // === Step 3: Verify case main view shows closure status ===
      const caseInfo = await request(basePath, { method: 'GET' });
      expect(caseInfo.res.status).toBe(200);
      const caseData = caseInfo.body;
      const caseStatus = caseData?.status || caseData?.caseStatus || caseData?.closureStatus || caseData?.state;
      // Case should indicate it is closed/submitted/resolved
      expect(
        caseStatus === 'closed' || caseStatus === 'submitted' || caseStatus === 'resolved' || caseStatus === 'final' ||
        caseData?.isClosed === true || caseData?.hasEnding === true || caseData?.ending != null,
        `expected case main view to show closure status, got ${JSON.stringify(caseData)}`
      ).toBe(true);
    } finally {
      // Cleanup
      await request(basePath || `/api/cases/${caseId}`, { method: 'DELETE' }).catch(() => {});
      if (basePath && basePath.includes('sessions')) {
        await request(`/api/sessions/${caseId}`, { method: 'DELETE' }).catch(() => {});
      }
    }
  });
});

