describe('round5_reasoning_dialogue_dependency', () => {
  it('should lock/unlock reasoning-dependent question based on reasoning existence while preserving already asked history', async () => {
    const suffix = Date.now();
    const cleanupPaths = [];

    try {
      // Create session (consistent path without /api prefix)
      const sessionResp = await request('/sessions', {
        method: 'POST',
        body: JSON.stringify({ title: `reasoning-dialogue-${suffix}`, scenario: 'detective-adventure' }),
      });
      expect([200, 201]).toContain(sessionResp.res.status);
      const sessionId = sessionResp.body?.id || sessionResp.body?.sessionId;
      expect(sessionId, `expected session id, got ${JSON.stringify(sessionResp.body)}`).toBeTruthy();
      cleanupPaths.push(`/sessions/${sessionId}`);

      // Collect two evidence items to use in reasoning
      const collectedClueIds = [];
      const { res: sceneRes, body: sceneBody } = await request(`/sessions/${sessionId}/scene`, { method: 'GET' });
      expect(sceneRes.status).toBe(200);
      const objects = sceneBody.objects || sceneBody.items || sceneBody.areas || [];
      expect(objects.length, 'scene should have inspectable objects').toBeGreaterThanOrEqual(2);

      for (let i = 0; i < 2 && i < objects.length; i++) {
        const obj = objects[i];
        const objId = obj.id || obj.objectId;
        // Inspect then collect
        await request(`/sessions/${sessionId}/scene/inspect`, {
          method: 'POST',
          body: JSON.stringify({ objectId: objId }),
        });
        const { res: collectRes, body: collectBody } = await request(`/sessions/${sessionId}/scene/collect`, {
          method: 'POST',
          body: JSON.stringify({ objectId: objId }),
        });
        expect([200, 201]).toContain(collectRes.status);
        const clueId = collectBody.clueId || collectBody.id || collectBody.evidenceId;
        expect(clueId, `expected clue id from collection, got ${JSON.stringify(collectBody)}`).toBeTruthy();
        collectedClueIds.push(clueId);
      }

      // Get list of NPCs
      const { res: npcsRes, body: npcsBody } = await request(`/sessions/${sessionId}/npcs`, { method: 'GET' });
      expect(npcsRes.status).toBe(200);
      const npcs = npcsBody.npcs || npcsBody.items || npcsBody || [];
      expect(npcs.length, 'should have NPCs available').toBeGreaterThanOrEqual(1);

      // Find an NPC that has a reasoning-dependent locked question
      let targetNpcId = null;
      let targetQuestionId = null;

      for (const npc of npcs) {
        const npcId = npc.id || npc.npcId;
        const { res: qRes, body: qBody } = await request(`/sessions/${sessionId}/npcs/${npcId}/questions`, { method: 'GET' });
        if (qRes.status !== 200) continue;
        const questions = qBody.questions || qBody.items || qBody || [];
        // Look for a question that is locked and requires reasoning
        const lockedQ = questions.find(
          (q) =>
            (q.locked === true || q.unlocked === false) &&
            (q.requiresReasoning || q.unlockCondition === 'reasoning' ||
             (q.unlockReason || '').toLowerCase().includes('推理') ||
             (q.unlockReason || '').toLowerCase().includes('reason'))
        );
        if (lockedQ) {
          targetNpcId = npcId;
          targetQuestionId = lockedQ.id || lockedQ.questionId;
          break;
        }
      }

      // If no explicitly reasoning-locked question found, try any locked question
      if (!targetNpcId) {
        for (const npc of npcs) {
          const npcId = npc.id || npc.npcId;
          const { res: qRes, body: qBody } = await request(`/sessions/${sessionId}/npcs/${npcId}/questions`, { method: 'GET' });
          if (qRes.status !== 200) continue;
          const questions = qBody.questions || qBody.items || qBody || [];
          const lockedQ = questions.find((q) => q.locked === true || q.unlocked === false);
          if (lockedQ) {
            targetNpcId = npcId;
            targetQuestionId = lockedQ.id || lockedQ.questionId;
            break;
          }
        }
      }

      expect(targetNpcId, 'should find an NPC with a locked question dependent on reasoning').toBeTruthy();
      expect(targetQuestionId, 'should find a locked question id').toBeTruthy();

      // Verify the question is locked BEFORE reasoning
      const { res: beforeRes, body: beforeBody } = await request(`/sessions/${sessionId}/npcs/${targetNpcId}/questions`, { method: 'GET' });
      expect(beforeRes.status).toBe(200);
      const beforeQuestions = beforeBody.questions || beforeBody.items || beforeBody || [];
      const depBefore = beforeQuestions.find((q) => (q.id || q.questionId) === targetQuestionId);
      expect(depBefore, `locked question ${targetQuestionId} should exist in question list before reasoning`).toBeTruthy();
      expect(
        depBefore.locked === true || depBefore.unlocked === false,
        `expected question locked before reasoning, got ${JSON.stringify(depBefore)}`
      ).toBe(true);

      // Create reasoning with collected clues
      const { res: reasoningRes, body: reasoningBody } = await request(`/sessions/${sessionId}/reasonings`, {
        method: 'POST',
        body: JSON.stringify({ clueIds: collectedClueIds, conclusion: 'motive exposed' }),
      });
      expect([200, 201]).toContain(reasoningRes.status);
      const reasoningId = reasoningBody.id || reasoningBody.reasoningId;
      expect(reasoningId, `expected reasoning id, got ${JSON.stringify(reasoningBody)}`).toBeTruthy();

      // Verify the question is now UNLOCKED after reasoning
      const { res: afterRes, body: afterBody } = await request(`/sessions/${sessionId}/npcs/${targetNpcId}/questions`, { method: 'GET' });
      expect(afterRes.status).toBe(200);
      const afterQuestions = afterBody.questions || afterBody.items || afterBody || [];
      const depAfter = afterQuestions.find((q) => (q.id || q.questionId) === targetQuestionId);
      expect(depAfter, `question ${targetQuestionId} should still exist after reasoning created`).toBeTruthy();
      expect(
        depAfter.unlocked === true || depAfter.locked === false,
        `expected question unlocked after reasoning, got ${JSON.stringify(depAfter)}`
      ).toBe(true);

      // Ask the now-unlocked question
      const { res: askRes, body: askBody } = await request(`/sessions/${sessionId}/npcs/${targetNpcId}/ask`, {
        method: 'POST',
        body: JSON.stringify({ questionId: targetQuestionId }),
      });
      expect([200, 201]).toContain(askRes.status);

      // Delete the reasoning that enabled the unlock
      const { res: removeRes } = await request(`/sessions/${sessionId}/reasonings/${reasoningId}`, { method: 'DELETE' });
      expect([200, 204]).toContain(removeRes.status);

      // Verify the question is RE-LOCKED after reasoning removal
      const { res: afterDeleteRes, body: afterDeleteBody } = await request(`/sessions/${sessionId}/npcs/${targetNpcId}/questions`, { method: 'GET' });
      expect(afterDeleteRes.status).toBe(200);
      const afterDeleteQuestions = afterDeleteBody.questions || afterDeleteBody.items || afterDeleteBody || [];
      const depDeleted = afterDeleteQuestions.find((q) => (q.id || q.questionId) === targetQuestionId);
      expect(depDeleted, `question ${targetQuestionId} should still appear after reasoning deletion`).toBeTruthy();
      expect(
        depDeleted.locked === true || depDeleted.unlocked === false,
        `expected question relocked after reasoning removal, got ${JSON.stringify(depDeleted)}`
      ).toBe(true);

      // Verify dialogue history still contains the previously asked question
      const { res: historyRes, body: historyBody } = await request(`/sessions/${sessionId}/npcs/${targetNpcId}`, { method: 'GET' });
      expect(historyRes.status).toBe(200);
      const history = historyBody.history || historyBody.dialogues || historyBody.conversations || [];
      expect(
        history.some(
          (h) =>
            (h.questionId === targetQuestionId) ||
            JSON.stringify(h).includes(targetQuestionId)
        ),
        `asked history for question ${targetQuestionId} should persist after reasoning invalidation, got ${JSON.stringify(history)}`
      ).toBe(true);

      // --- Simulate refresh: re-fetch all states and verify consistency ---
      const { res: refreshQRes, body: refreshQBody } = await request(`/sessions/${sessionId}/npcs/${targetNpcId}/questions`, { method: 'GET' });
      expect(refreshQRes.status).toBe(200);
      const refreshQuestions = refreshQBody.questions || refreshQBody.items || refreshQBody || [];
      const depRefresh = refreshQuestions.find((q) => (q.id || q.questionId) === targetQuestionId);
      expect(depRefresh, 'question should exist after simulated refresh').toBeTruthy();
      expect(
        depRefresh.locked === true || depRefresh.unlocked === false,
        `question should still be locked after refresh, got ${JSON.stringify(depRefresh)}`
      ).toBe(true);

      const { res: refreshHistRes, body: refreshHistBody } = await request(`/sessions/${sessionId}/npcs/${targetNpcId}`, { method: 'GET' });
      expect(refreshHistRes.status).toBe(200);
      const refreshHistory = refreshHistBody.history || refreshHistBody.dialogues || refreshHistBody.conversations || [];
      expect(
        refreshHistory.some(
          (h) =>
            (h.questionId === targetQuestionId) ||
            JSON.stringify(h).includes(targetQuestionId)
        ),
        'asked history should persist after simulated refresh'
      ).toBe(true);
    } finally {
      await cleanup(cleanupPaths);
    }
  });
});

