describe('round21_cross_chapter_reference_persistence', () => {
  it('should keep chapter-1 confirmed conclusions available as read-only chapter-2 references, reject draft conclusions with reason, and preserve relations after export/import', async () => {
    const cleanupPaths = [];

    try {
      // --- Step 1: Create a session with chapter structure ---
      const { res: createRes, body: createBody } = await request('/sessions', {
        method: 'POST',
        body: JSON.stringify({
          title: `verifier-cross-chapter-${Date.now()}`,
          scenario: 'detective-adventure',
        }),
      });
