      const sessionId = createBody.sessionId || createBody.id;
      expect(sessionId, `expected session id, got ${JSON.stringify(createBody)}`).toBeTruthy();
      cleanupPaths.push(`/sessions/${sessionId}`);

      // --- Step 2: Collect evidence and build reasoning in chapter 1 ---
      // Collect at least 2 clues for reasoning
      const clueIds = [];
      for (let i = 0; i < 2; i++) {
        const { res: clueRes, body: clueBody } = await request(`/sessions/${sessionId}/clues`, {
          method: 'POST',
          body: JSON.stringify({
            name: `Cross-Chapter Clue ${i + 1}`,
            summary: `Important clue ${i + 1} for chapter 1 conclusion`,
            category: 'evidence',
          }),
        });
        expect([200, 201]).toContain(clueRes.status);
        const clueId = clueBody.clueId || clueBody.id;
        expect(clueId).toBeTruthy();
        clueIds.push(clueId);
      }

      // Create a reasoning
      const { res: reasonRes, body: reasonBody } = await request(`/sessions/${sessionId}/reasonings`, {
        method: 'POST',
        body: JSON.stringify({ clueIds, conclusion: 'The suspect entered through the back door' }),
      });
      expect([200, 201]).toContain(reasonRes.status);

      // --- Step 3: Create a DRAFT case report for chapter 1 ---
      const { res: draftRes, body: draftBody } = await request(`/sessions/${sessionId}/report`, {
        method: 'POST',
        body: JSON.stringify({
          status: 'draft',
          suspectId: 'suspect-a',
          logic: 'Draft: suspect entered through back door',
          keyEvidenceIds: [clueIds[0]],
        }),
      });
      expect([200, 201]).toContain(draftRes.status);

      // --- Step 4: Verify chapter 2 references are LOCKED when chapter 1 is only draft ---
      const { res: ch2RefsLockedRes, body: ch2RefsLockedBody } = await request(
        `/sessions/${sessionId}/chapters/2/references`,
        { method: 'GET' }
      );
      // May return 200 with empty/locked list, or specific status
      if (ch2RefsLockedRes.status === 200) {
        const refs = ch2RefsLockedBody.items || ch2RefsLockedBody.references || ch2RefsLockedBody || [];
        if (Array.isArray(refs)) {
          // All references should be locked or list empty
          for (const ref of refs) {
            expect(
              ref.locked === true || ref.available === false,
              `chapter 2 reference should be locked while chapter 1 is draft: ${JSON.stringify(ref)}`
            ).toBe(true);
            // Verify reason is provided for lock
            const reason = ref.lockReason || ref.reason || ref.message || '';
            expect(
              reason.length,
              `locked reference should include a reason for why it's locked: ${JSON.stringify(ref)}`
            ).toBeGreaterThan(0);
          }
        }
      }

      // Attempt to create a reference from draft should fail
      const { res: draftRefRes, body: draftRefBody } = await request(
        `/sessions/${sessionId}/chapters/2/references`,
        {
          method: 'POST',
          body: JSON.stringify({ sourceChapter: 1, conclusionId: draftBody.id || draftBody.reportId }),
        }
      );
      expect(
        [400, 403, 409].includes(draftRefRes.status),
        `draft conclusion reference should be rejected, got ${draftRefRes.status}: ${JSON.stringify(draftRefBody)}`
      ).toBe(true);
      // Verify the rejection includes a reason
      const rejectReason = draftRefBody?.reason || draftRefBody?.message || draftRefBody?.error || '';
      expect(
        typeof rejectReason === 'string' && rejectReason.length > 0,
        `rejection should include reason explaining why draft cannot be referenced, got ${JSON.stringify(draftRefBody)}`
      ).toBe(true);

      // --- Step 5: Finalize chapter 1 report ---
      const { res: finalizeRes, body: finalizeBody } = await request(`/sessions/${sessionId}/report`, {
        method: 'PUT',
        body: JSON.stringify({
          status: 'final',
          suspectId: 'suspect-a',
          logic: 'Confirmed: suspect entered through back door based on key and note',
          keyEvidenceIds: [clueIds[0], clueIds[1]],
        }),
      });
      expect([200, 201]).toContain(finalizeRes.status);

      // --- Step 6: Create a cross-chapter reference from confirmed chapter 1 conclusion ---
      const conclusionId = finalizeBody.id || finalizeBody.reportId || finalizeBody.conclusionId;
      const { res: refRes, body: refBody } = await request(
        `/sessions/${sessionId}/chapters/2/references`,
        {
          method: 'POST',
          body: JSON.stringify({ sourceChapter: 1, conclusionId }),
        }
      );
      expect([200, 201]).toContain(refRes.status);
      expect(refBody).toBeTruthy();

      // Verify reference is read-only
      const isReadOnly = refBody.readOnly ?? refBody.readonly ?? refBody.editable === false;
      expect(
        isReadOnly,
        `cross-chapter reference should be read-only, got ${JSON.stringify(refBody)}`
      ).toBe(true);

      // Verify source chapter and content
      expect(refBody.sourceChapter || refBody.fromChapter).toBe(1);

      // Verify the reference content is substantive (title/content preserved)
      const refContent = refBody.content || refBody.conclusion || refBody.title || '';
      expect(
        typeof refContent === 'string' && refContent.length > 0,
        `reference should include conclusion content, got ${JSON.stringify(refBody)}`
      ).toBe(true);

      // --- Step 7: Verify references list in chapter 2 ---
      const { res: ch2RefsRes, body: ch2RefsBody } = await request(
        `/sessions/${sessionId}/chapters/2/references`,
        { method: 'GET' }
      );
      expect(ch2RefsRes.status).toBe(200);
      const refsList = ch2RefsBody.items || ch2RefsBody.references || ch2RefsBody || [];
      expect(Array.isArray(refsList)).toBe(true);
      const confirmedRef = refsList.find(
        (r) => (r.conclusionId || r.id) === conclusionId || r.sourceChapter === 1
      );
      expect(confirmedRef, `should find confirmed chapter-1 reference in chapter 2`).toBeTruthy();
      expect(
        confirmedRef.readOnly ?? confirmedRef.readonly ?? confirmedRef.editable === false,
        'reference should remain read-only in list'
      ).toBe(true);

      // --- Step 8: Export and re-import, verify cross-chapter references persist ---
      const { res: exportRes, body: exportBody } = await request(
        `/sessions/${sessionId}/export`,
        { method: 'GET' }
      );
      expect(exportRes.status).toBe(200);
      expect(exportBody).toBeTruthy();

      const { res: importRes, body: importBody } = await request('/sessions/import', {
        method: 'POST',
        body: JSON.stringify(exportBody),
      });
      expect([200, 201]).toContain(importRes.status);
      const importedSessionId = importBody.sessionId || importBody.id;
      expect(importedSessionId).toBeTruthy();
      cleanupPaths.push(`/sessions/${importedSessionId}`);

      // Verify references in imported save
      const { res: importedRefsRes, body: importedRefsBody } = await request(
        `/sessions/${importedSessionId}/chapters/2/references`,
        { method: 'GET' }
      );
      expect(importedRefsRes.status).toBe(200);
      const importedRefsList = importedRefsBody.items || importedRefsBody.references || importedRefsBody || [];
      expect(Array.isArray(importedRefsList)).toBe(true);

      const importedConfirmedRef = importedRefsList.find(
        (r) => r.sourceChapter === 1 || (r.conclusionId || r.id) === conclusionId
      );
      expect(
        importedConfirmedRef,
        `imported save should preserve chapter-1 reference in chapter 2, got ${JSON.stringify(importedRefsList)}`
      ).toBeTruthy();
      expect(
        importedConfirmedRef.readOnly ?? importedConfirmedRef.readonly ?? importedConfirmedRef.editable === false,
        'imported reference should remain read-only'
      ).toBe(true);

      // Verify content is preserved after import
      const importedRefContent =
        importedConfirmedRef.content || importedConfirmedRef.conclusion || importedConfirmedRef.title || '';
      expect(
        typeof importedRefContent === 'string' && importedRefContent.length > 0,
        `imported reference should preserve content, got ${JSON.stringify(importedConfirmedRef)}`
      ).toBe(true);
    } finally {
      for (const path of cleanupPaths) {
        await cleanup(path);
      }
    }
  });
});

import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function request(path, options = {}) {
  const res = await fetch(`${BASE_URL}${path}`, {
    headers: { 'Content-Type': 'application/json', ...(options.headers || {}) },
    ...options,
  });
  let body = null;
  const text = await res.text();
  try {
    body = text ? JSON.parse(text) : null;
  } catch {
    body = text;
  }
  return { res, body };
}

async function tryRequest(paths, options = {}) {
  for (const path of paths) {
    try {
      const result = await request(path, options);
      if ([200, 201].includes(result.res.status)) return { ...result, usedPath: path };
      if ([400, 403, 409, 422].includes(result.res.status)) return { ...result, usedPath: path };
    } catch {}
  }
  return request(paths[0], options);
}

async function createSession(suffix) {
  const attempts = [
    { path: '/api/sessions', body: { name: `notes-test-${suffix}` } },
    { path: '/api/cases', body: { title: `notes-test-${suffix}` } },
    { path: '/api/game/sessions', body: { name: `notes-test-${suffix}` } },
  ];
  for (const a of attempts) {
    try {
      const result = await request(a.path, { method: 'POST', body: JSON.stringify(a.body) });
      if ([200, 201].includes(result.res.status)) {
        const id = result.body?.id || result.body?.sessionId || result.body?.caseId;
        if (id) return { id, prefix: `${a.path}/${id}`, basePath: a.path };
      }
    } catch {}
  }
  throw new Error('Could not create session');
}

function extractArray(body, ...keys) {
  for (const key of keys) {
    if (body && Array.isArray(body[key])) return body[key];
  }
  if (Array.isArray(body)) return body;
  return [];
}

