        // After interrogation, notes should have grown or a new entry should exist
        const notesGrew = updatedNotes.length > initialNotesCount;
        const hasNewContent = updatedNotes.some(n =>
          (typeof n === 'string' && n.length > 0) ||
          (n?.content && n.content.length > 0) ||
          (n?.text && n.text.length > 0)
