        ).toBeTruthy();
      }

      // --- Verify clues/evidence updated ---
      const cluesAfter = await tryRequest([
        `${prefix}/clues`,
        `${prefix}/evidences`,
        `${prefix}/evidence`,
        `${prefix}/board`,
