        // If interrogation produced a timeline event, it should be pending/unconfirmed
        const newPending = tlAfterItems.filter(e =>
          e.status === 'pending' || e.status === 'unconfirmed' || e.confirmed === false || e.pending === true
        );
        // New pending events may exist if this interrogation triggers them
        if (tlAfterItems.length > tlBeforeItems.length) {
