  it('should preserve dialogue history after refusal and provide clear reason categorized as clue-insufficient, trust-low, or explicit-refusal', async () => {
    const suffix = Date.now();
    const session = await createSession(suffix);
    const { prefix } = session;
    const npcId = 'maid';

    try {
      // First establish some dialogue history
      const askNormal = await tryRequest([
        `${prefix}/interrogations/${npcId}/ask`,
        `${prefix}/npc/${npcId}/ask`,
        `${prefix}/interrogations`,
      ], {
        method: 'POST',
        body: JSON.stringify({ questionId: 'q_basic_info', npcId, kind: 'normal' }),
      });
      expect([200, 201]).toContain(askNormal.res.status);

      // Get history before refusal attempt
      const histBefore = await tryRequest([
        `${prefix}/interrogations/${npcId}/history`,
        `${prefix}/interrogations/history?npcId=${npcId}`,
        `${prefix}/npc/${npcId}/history`,
        `${prefix}/characters/${npcId}/history`,
      ], { method: 'GET' });
      const histBeforeItems = histBefore.res.status === 200
        ? extractArray(histBefore.body, 'history', 'items', 'dialogues')
        : [];
      const histBeforeCount = histBeforeItems.length;
      expect(histBeforeCount, 'should have at least 1 history entry before refusal test').toBeGreaterThanOrEqual(1);

      // Try a locked/sensitive question that should be refused
      const refusalResult = await tryRequest([
        `${prefix}/interrogations/${npcId}/ask`,
        `${prefix}/npc/${npcId}/ask`,
        `${prefix}/interrogations`,
      ], {
        method: 'POST',
        body: JSON.stringify({ questionId: 'q_locked_sensitive_topic', npcId, kind: 'normal' }),
      });

      // Analyze the refusal response
      const refusalBody = refusalResult.body || {};
      const refusalStatus = refusalResult.res.status;
      const isRefused = [400, 403, 409, 422].includes(refusalStatus) ||
        refusalBody.refused === true ||
        refusalBody.status === 'refused' ||
        refusalBody.locked === true;

      if (isRefused) {
        // Verify reason is specific and categorized
        const reason = String(refusalBody.reason || refusalBody.message || refusalBody.lockedReason || '').toLowerCase();
        expect(
          reason.length > 0,
          `refusal should include a reason, got ${JSON.stringify(refusalBody)}`
        ).toBe(true);

        // Check reason falls into one of the expected categories
        const isClueInsufficient = reason.includes('clue') || reason.includes('evidence') || reason.includes('线索') || reason.includes('证据');
        const isTrustLow = reason.includes('trust') || reason.includes('信任') || reason.includes('rapport') || reason.includes('好感');
        const isExplicitRefusal = reason.includes('refuse') || reason.includes('拒绝') || reason.includes('decline') || reason.includes('won\'t');
        const isLocked = reason.includes('locked') || reason.includes('锁') || reason.includes('condition') || reason.includes('条件');
        expect(
          isClueInsufficient || isTrustLow || isExplicitRefusal || isLocked,
          `refusal reason should indicate category (clue-insufficient, trust-low, or explicit-refusal), got: "${reason}"`
        ).toBe(true);
      }

      // Verify history is preserved after refusal
      const histAfter = await tryRequest([
        `${prefix}/interrogations/${npcId}/history`,
        `${prefix}/interrogations/history?npcId=${npcId}`,
        `${prefix}/npc/${npcId}/history`,
        `${prefix}/characters/${npcId}/history`,
      ], { method: 'GET' });
      expect(histAfter.res.status).toBe(200);
      const histAfterItems = extractArray(histAfter.body, 'history', 'items', 'dialogues');
      expect(Array.isArray(histAfterItems)).toBe(true);
      // Previous dialogue entries must still be there
      expect(
        histAfterItems.length,
        'dialogue history must be preserved after refusal'
      ).toBeGreaterThanOrEqual(histBeforeCount);

      // The first successful question should still be in history
      const hasOriginalEntry = histAfterItems.some(h =>
        (h.questionId || h.id) === 'q_basic_info' || h.npcId === npcId
      );
      expect(
        hasOriginalEntry || histAfterItems.length >= histBeforeCount,
        'original successful dialogue should remain in history after refusal'
      ).toBe(true);
    } finally {
      await request(`${prefix}`, { method: 'DELETE' }).catch(() => {});
    }
  });
});

