describe('question_unlock_and_repeat_constraints_enforced', () => {
  it('should mark asked questions, block infinite repeats, and show reasons for unavailable questions', async () => {
    const { res: createRes, body: createBody } = await request('/sessions', {
      method: 'POST',
      body: JSON.stringify({ title: `verifier-interrogation-${Date.now()}`, scenario: 'detective-adventure' }),
