    const { res: listRes1, body: listBody1 } = await request(`/sessions/${sessionId}/interrogations/${npcId}/questions`, { method: 'GET' });
    expect(listRes1.status, `expected question list status 200, got ${listRes1.status} with body ${JSON.stringify(listBody1)}`).toBe(200);

    const questions1 = listBody1.questions || listBody1.items || [];
    expect(Array.isArray(questions1), 'questions should be an array').toBe(true);
    expect(questions1.length, 'questions list should not be empty').toBeGreaterThan(0);

    const availableQuestion = questions1.find((q) => (q.available ?? q.enabled ?? !q.locked) === true);
    expect(availableQuestion, 'expected at least one available question').toBeTruthy();

    const lockedQuestion = questions1.find((q) => (q.available ?? q.enabled ?? !q.locked) === false);
    expect(lockedQuestion, 'expected at least one unavailable question for reason check').toBeTruthy();
    expect((lockedQuestion.reason || lockedQuestion.unavailableReason || '').trim().length, 'locked question should expose a short reason').toBeGreaterThan(0);

    const questionId = availableQuestion.questionId || availableQuestion.id;
    const { res: askRes1, body: askBody1 } = await request(`/sessions/${sessionId}/interrogations/${npcId}/ask`, {
