function getScore(suspect) {
  return suspect.score ?? suspect.suspicion ?? suspect.suspicionLevel ?? 0;
}

function getSuspectId(suspect) {
  return suspect.id || suspect.suspectId || suspect.name;
}

describe('round8_suspect_assessment_updates', () => {
  it('should show insufficient-info when no evidence exists, generate assessments with motive/opportunity/score, sort stably including same-score, and update when support is invalidated (including testimony)', async () => {
    const suffix = Date.now();
    const cleanupPaths = [];

    try {
      // Create session
      const sessionResp = await request('/api/sessions', {
        method: 'POST',
        body: JSON.stringify({ name: `suspect-session-${suffix}` }),
      });
      expect([200, 201]).toContain(sessionResp.res.status);
      const sessionId = sessionResp.body?.id || sessionResp.body?.sessionId;
      expect(sessionId).toBeTruthy();
      cleanupPaths.push(`/api/sessions/${sessionId}`);

      // --- Empty/insufficient state: should indicate info is insufficient ---
      const assessEmpty = await request(`/api/sessions/${sessionId}/suspects/assessment`, { method: 'GET' });
      expect(assessEmpty.res.status).toBe(200);
      const emptyItems = assessEmpty.body?.items || assessEmpty.body?.suspects || [];
      const insufficientMsg = assessEmpty.body?.message || assessEmpty.body?.hint || assessEmpty.body?.status || '';
      const isInsufficient =
        (typeof insufficientMsg === 'string' && insufficientMsg.length > 0) ||
        emptyItems.length === 0 ||
        emptyItems.every((s) => getScore(s) === 0 || getScore(s) === null || getScore(s) === undefined || s.status === 'insufficient');
      expect(isInsufficient, `Expected 'insufficient info' indication when no evidence exists, got ${JSON.stringify(assessEmpty.body)}`).toBe(true);

      // --- Collect evidence ---
      for (const id of [`sus1-${suffix}`, `sus2-${suffix}`]) {
        const collect = await request(`/api/sessions/${sessionId}/evidence/collect`, {
          method: 'POST',
          body: JSON.stringify({ areaId: 'garage', objectId: `obj-${id}`, evidenceId: id, name: id }),
        });
        expect([200, 201]).toContain(collect.res.status);
      }

      // --- Create testimony / ask NPC to generate oral evidence ---
      let testimonyCreated = false;
      const npcsResp = await request(`/api/sessions/${sessionId}/npcs`);
      if (npcsResp.res.status === 200) {
        const npcs = npcsResp.body?.items || npcsResp.body?.npcs || npcsResp.body || [];
        if (Array.isArray(npcs) && npcs.length > 0) {
          const npcId = npcs[0].id || npcs[0].npcId;
          if (npcId) {
            const questions = await request(`/api/sessions/${sessionId}/npcs/${npcId}/questions`);
            if (questions.res.status === 200) {
              const qs = questions.body?.items || questions.body?.questions || questions.body || [];
              if (Array.isArray(qs) && qs.length > 0) {
                const qId = qs[0].id || qs[0].questionId;
                if (qId) {
                  const askResp = await request(`/api/sessions/${sessionId}/npcs/${npcId}/ask`, {
                    method: 'POST',
                    body: JSON.stringify({ questionId: qId }),
                  });
                  if ([200, 201].includes(askResp.res.status)) testimonyCreated = true;
                }
              }
            }
          }
        }
      }

      // --- Create reasoning linking evidence ---
      const reasoning = await request(`/api/sessions/${sessionId}/reasoning`, {
        method: 'POST',
        body: JSON.stringify({ clueIds: [`sus1-${suffix}`, `sus2-${suffix}`], conclusion: 'suspect-A has strongest link' }),
      });
      expect([200, 201]).toContain(reasoning.res.status);
      const reasoningId = reasoning.body?.id || reasoning.body?.reasoningId;
      expect(reasoningId).toBeTruthy();

      // --- Get assessment and verify structure ---
      const assess1 = await request(`/api/sessions/${sessionId}/suspects/assessment`, { method: 'GET' });
      expect(assess1.res.status).toBe(200);
      const items1 = assess1.body?.items || assess1.body?.suspects || [];
      expect(Array.isArray(items1)).toBe(true);
      expect(items1.length, 'Expected at least one suspect assessment item').toBeGreaterThan(0);

      // Verify each suspect has motive AND opportunity AND score fields
      for (const suspect of items1) {
        const hasMotive = 'motive' in suspect || 'motivation' in suspect;
        const hasOpportunity = 'opportunity' in suspect || 'access' in suspect;
        const hasScore = 'score' in suspect || 'suspicion' in suspect || 'suspicionLevel' in suspect;
        expect(hasMotive, `Suspect ${getSuspectId(suspect)} should have motive field, got ${JSON.stringify(suspect)}`).toBe(true);
        expect(hasOpportunity, `Suspect ${getSuspectId(suspect)} should have opportunity field, got ${JSON.stringify(suspect)}`).toBe(true);
        expect(hasScore, `Suspect ${getSuspectId(suspect)} should have score field, got ${JSON.stringify(suspect)}`).toBe(true);
      }

      // Verify descending sort by score
      if (items1.length > 1) {
        const scores1 = items1.map((s) => getScore(s));
        for (let i = 1; i < scores1.length; i++) {
          expect(scores1[i - 1] >= scores1[i], `Expected descending sort: ${scores1}`).toBe(true);
        }
      }

      // --- Verify stable sort: multiple requests return same order ---
      const assess1b = await request(`/api/sessions/${sessionId}/suspects/assessment`, { method: 'GET' });
      expect(assess1b.res.status).toBe(200);
      const items1b = assess1b.body?.items || assess1b.body?.suspects || [];
      const ids1 = items1.map((s) => getSuspectId(s));
      const ids1b = items1b.map((s) => getSuspectId(s));
      expect(ids1b, 'Suspect order should be stable across multiple requests').toEqual(ids1);

      // --- Verify same-score stable sort ---
      // Find suspects with identical scores
      const scoreGroups = {};
      for (const s of items1) {
        const sc = getScore(s);
        if (!scoreGroups[sc]) scoreGroups[sc] = [];
        scoreGroups[sc].push(getSuspectId(s));
      }
      // If any group has >1 suspects at same score, verify order is consistent
      for (const [sc, group] of Object.entries(scoreGroups)) {
        if (group.length > 1) {
          const groupB = items1b.filter((s) => getScore(s) === Number(sc)).map((s) => getSuspectId(s));
          expect(groupB, `Suspects with same score ${sc} should maintain stable order`).toEqual(group);
        }
      }

      // Save first assessment state for comparison
      const firstSuspectBefore = items1[0];
      const scoreBefore = getScore(firstSuspectBefore);
      const motiveDescBefore = firstSuspectBefore.motive || firstSuspectBefore.motivation || '';
      const opportunityDescBefore = firstSuspectBefore.opportunity || firstSuspectBefore.access || '';

      // --- Delete reasoning to invalidate support ---
      const removeReasoning = await request(`/api/sessions/${sessionId}/reasoning/${reasoningId}`, { method: 'DELETE' });
      expect([200, 204]).toContain(removeReasoning.res.status);

      // --- Get updated assessment ---
      const assess2 = await request(`/api/sessions/${sessionId}/suspects/assessment`, { method: 'GET' });
      expect(assess2.res.status).toBe(200);
      const items2 = assess2.body?.items || assess2.body?.suspects || [];
      expect(Array.isArray(items2)).toBe(true);
      expect(items2.length, 'Suspect assessment should still exist after invalidation').toBeGreaterThan(0);

      // Find the same suspect after invalidation
      const firstSuspectAfter = items2.find(
        (s) => getSuspectId(s) === getSuspectId(firstSuspectBefore)
      ) || items2[0];
      const scoreAfter = getScore(firstSuspectAfter);
      const motiveDescAfter = firstSuspectAfter.motive || firstSuspectAfter.motivation || '';
      const opportunityDescAfter = firstSuspectAfter.opportunity || firstSuspectAfter.access || '';

      // The assessment should have changed — either score changed or description changed
      const scoreChanged = scoreAfter !== scoreBefore;
      const motiveChanged = motiveDescAfter !== motiveDescBefore;
      const opportunityChanged = opportunityDescAfter !== opportunityDescBefore;
      const explanationBefore = JSON.stringify(firstSuspectBefore);
      const explanationAfter = JSON.stringify(firstSuspectAfter);
      expect(
        scoreChanged || motiveChanged || opportunityChanged || explanationAfter !== explanationBefore,
        `Suspect assessment should update after support invalidation; before=${explanationBefore}, after=${explanationAfter}`
      ).toBe(true);

      // Verify the invalidated suspect's description no longer references the deleted reasoning as active support
      // (it should not still claim the old reasoning as current evidence)
      const afterStr = JSON.stringify(firstSuspectAfter).toLowerCase();
      if (afterStr.includes('strongest link')) {
        // If the conclusion text still appears, it should be marked as invalidated or removed
        const hasInvalidMark = afterStr.includes('invalid') || afterStr.includes('removed') || afterStr.includes('deleted') || afterStr.includes('失效');
        expect(hasInvalidMark, 'If old reasoning conclusion still referenced, it should be marked as invalidated').toBe(true);
      }
    } finally {
      await cleanup(cleanupPaths);
    }
  });
});

