import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function request(path, init = {}) {
  const res = await fetch(`${BASE_URL}${path}`, {
    headers: {
      'Content-Type': 'application/json',
      ...(init.headers || {}),
    },
    ...init,
  });
  let body = null;
  const text = await res.text();
  try {
    body = text ? JSON.parse(text) : null;
  } catch {
    body = text;
  }
  return { res, body };
}

async function createSession(suffix) {
  const attempts = [
    { path: '/api/cases', body: { title: `followup-${suffix}` } },
    { path: '/api/sessions', body: { name: `followup-${suffix}` } },
    { path: '/api/game/sessions', body: { name: `followup-${suffix}` } },
  ];
  for (const a of attempts) {
    try {
      const result = await request(a.path, { method: 'POST', body: JSON.stringify(a.body) });
      if ([200, 201].includes(result.res.status)) {
        const id = result.body?.id || result.body?.caseId || result.body?.sessionId;
        if (id) return { id, prefix: `${a.path}/${id}`, basePath: a.path };
      }
    } catch {}
  }
  throw new Error('Could not create session');
}

async function tryRequest(paths, options = {}) {
  for (const path of paths) {
    try {
      const result = await request(path, options);
      if ([200, 201].includes(result.res.status)) return { ...result, usedPath: path };
      if ([400, 403, 409, 422].includes(result.res.status)) return { ...result, usedPath: path };
    } catch {}
  }
  return request(paths[0], options);
}

function getNpcId(body) {
  // Try to extract available NPC ids from game state
  const npcs = body?.npcs || body?.characters || body?.people || [];
  if (Array.isArray(npcs) && npcs.length > 0) {
    return npcs[0]?.id || npcs[0]?.npcId;
  }
  return null;
}

describe('round12_followup_question_rules', () => {
  it('locks follow-up when conditions unmet, shows locked follow-ups in list with reason, unlocks when multi-conditions met, shares history, prevents duplicate reward, and records refusal', async () => {
    const suffix = Date.now();
    const session = await createSession(suffix);
    const { prefix } = session;

    try {
      // Use first available NPC or fallback to known IDs
      const npcId = 'npc_butler';
      const secondNpcId = 'npc_maid';

      // --- Step 1: Ask a normal question to establish dialogue history ---
      const normalAsk = await tryRequest([
        `${prefix}/interrogations`,
        `${prefix}/interrogations/${npcId}/ask`,
        `${prefix}/npc/${npcId}/ask`,
        `${prefix}/characters/${npcId}/ask`,
      ], {
        method: 'POST',
        body: JSON.stringify({ npcId, questionId: 'q_where_were_you', kind: 'normal' }),
      });
      expect([200, 201]).toContain(normalAsk.res.status);

      // --- Step 2: Get follow-up questions list - locked ones should be visible but disabled with reason ---
      const followupList = await tryRequest([
        `${prefix}/interrogations/${npcId}/followups`,
        `${prefix}/interrogations/${npcId}/questions?kind=followup`,
        `${prefix}/npc/${npcId}/followups`,
        `${prefix}/characters/${npcId}/questions?kind=followup`,
        `${prefix}/interrogations/${npcId}/questions`,
        `${prefix}/npc/${npcId}/questions`,
      ], { method: 'GET' });

      if (followupList.res.status === 200) {
        const questions = followupList.body?.questions || followupList.body?.items || followupList.body?.followups || followupList.body || [];
        if (Array.isArray(questions) && questions.length > 0) {
          // Find a locked follow-up
          const lockedFollowup = questions.find(q =>
            q.locked === true || q.available === false || q.enabled === false ||
            (q.kind === 'followup' || q.type === 'followup')
          );
          if (lockedFollowup) {
            // Verify it's visible but shows a reason for being locked
            const reason = lockedFollowup.reason || lockedFollowup.lockedReason || lockedFollowup.hint || '';
            expect(
              typeof reason === 'string' && reason.length > 0,
              `locked follow-up should display reason why it's unavailable, got ${JSON.stringify(lockedFollowup)}`
            ).toBe(true);
          }
        }
      }

      // --- Step 3: Attempt follow-up WITHOUT all conditions met (missing evidence + missing NPC conversation) ---
      const followupLocked = await tryRequest([
        `${prefix}/interrogations`,
        `${prefix}/interrogations/${npcId}/ask`,
        `${prefix}/npc/${npcId}/ask`,
      ], {
        method: 'POST',
        body: JSON.stringify({ npcId, questionId: 'fq_confront_alibi_gap', kind: 'followup' }),
      });

      // Should be rejected or returned as locked with a reason
      if ([400, 403, 409, 422].includes(followupLocked.res.status)) {
        const reason = followupLocked.body?.reason || followupLocked.body?.message || '';
        expect(reason.length, 'locked follow-up rejection should explain why').toBeGreaterThan(0);
      } else if ([200, 201].includes(followupLocked.res.status)) {
        const locked = followupLocked.body?.locked === true || followupLocked.body?.available === false || followupLocked.body?.enabled === false;
        const reason = followupLocked.body?.reason || followupLocked.body?.lockedReason || '';
        expect(locked, 'expected follow-up to be locked when conditions not met').toBe(true);
        expect(reason.length, 'locked follow-up should provide a reason').toBeGreaterThan(0);
      }

      // --- Step 4: Fulfill FIRST condition — collect required evidence ---
      const collectEvidence = await tryRequest([
        `${prefix}/evidences`,
        `${prefix}/evidence/collect`,
        `${prefix}/evidence`,
        `${prefix}/clues`,
      ], {
        method: 'POST',
        body: JSON.stringify({ id: 'clue_fake_alibi', title: 'Fake Alibi Document', name: 'Fake Alibi Document', category: 'document', areaId: 'study', objectId: 'obj_fake_alibi', evidenceId: 'clue_fake_alibi' }),
      });
      expect([200, 201]).toContain(collectEvidence.res.status);

      // --- Step 4b: Attempt follow-up with only ONE condition met (evidence but no second NPC chat) ---
      const followupPartial = await tryRequest([
        `${prefix}/interrogations`,
        `${prefix}/interrogations/${npcId}/ask`,
        `${prefix}/npc/${npcId}/ask`,
      ], {
        method: 'POST',
        body: JSON.stringify({ npcId, questionId: 'fq_confront_alibi_gap', kind: 'followup' }),
      });
      // May still be locked if multi-condition requires talking to another NPC
      const partialStillLocked = [400, 403, 409, 422].includes(followupPartial.res.status) ||
        (followupPartial.res.status === 200 && (followupPartial.body?.locked === true || followupPartial.body?.available === false));
      // This is acceptable either way - depends on game logic

      // --- Step 5: Fulfill SECOND condition — talk to another NPC about a related topic ---
      const talkSecondNpc = await tryRequest([
        `${prefix}/interrogations`,
        `${prefix}/interrogations/${secondNpcId}/ask`,
        `${prefix}/npc/${secondNpcId}/ask`,
        `${prefix}/characters/${secondNpcId}/ask`,
      ], {
        method: 'POST',
        body: JSON.stringify({ npcId: secondNpcId, questionId: 'q_alibi_topic', kind: 'normal' }),
      });
      // Don't fail the whole test if second NPC doesn't exist - but log it
      const secondNpcTalked = [200, 201].includes(talkSecondNpc.res.status);

      // --- Step 6: Now attempt follow-up again — both conditions should be met ---
      const followup = await tryRequest([
        `${prefix}/interrogations`,
        `${prefix}/interrogations/${npcId}/ask`,
        `${prefix}/npc/${npcId}/ask`,
      ], {
        method: 'POST',
        body: JSON.stringify({ npcId, questionId: 'fq_confront_alibi_gap', kind: 'followup' }),
      });
      expect([200, 201]).toContain(followup.res.status);
      expect(followup.body).toBeTruthy();

      // Verify it's recognized as a follow-up type
      const kindField = String(followup.body?.kind || followup.body?.type || followup.body?.questionType || '').toLowerCase();
      if (kindField) {
        expect(kindField).toMatch(/follow/i);
      }

      // Record whether reward was granted
      const rewardFirst = followup.body?.rewardGranted ?? followup.body?.reward ?? followup.body?.newClueAdded ?? null;

      // --- Step 7: Verify shared conversation history includes both normal and follow-up ---
      const history = await tryRequest([
        `${prefix}/interrogations/history?npcId=${npcId}`,
        `${prefix}/interrogations/${npcId}/history`,
        `${prefix}/npc/${npcId}/history`,
        `${prefix}/characters/${npcId}/history`,
      ], { method: 'GET' });
      expect(history.res.status).toBe(200);
      const historyItems = history.body?.items || history.body?.history || history.body?.dialogues || history.body || [];
      expect(Array.isArray(historyItems)).toBe(true);
      expect(historyItems.length, 'history should contain at least the normal question and the follow-up').toBeGreaterThanOrEqual(2);

      const questionIds = historyItems.map(x => x.questionId || x.id || x.question);
      // Both normal and follow-up should be in the same history stream
      const hasNormal = historyItems.some(x =>
        (x.questionId || x.id) === 'q_where_were_you' || (x.kind || x.type) === 'normal'
      );
      const hasFollowup = historyItems.some(x =>
        (x.questionId || x.id) === 'fq_confront_alibi_gap' || (x.kind || x.type) === 'followup'
      );
      expect(hasNormal || historyItems.length >= 2, 'normal question should be in shared history').toBe(true);
      expect(hasFollowup || historyItems.length >= 2, 'follow-up should be in shared history').toBe(true);

      // --- Step 8: Attempt same follow-up again — reward should NOT be granted twice ---
      const followupAgain = await tryRequest([
        `${prefix}/interrogations`,
        `${prefix}/interrogations/${npcId}/ask`,
        `${prefix}/npc/${npcId}/ask`,
      ], {
        method: 'POST',
        body: JSON.stringify({ npcId, questionId: 'fq_confront_alibi_gap', kind: 'followup' }),
      });
      expect([200, 201, 409, 400].includes(followupAgain.res.status)).toBe(true);
      if ([200, 201].includes(followupAgain.res.status)) {
        const rewardSecond = followupAgain.body?.rewardGranted ?? followupAgain.body?.reward ?? followupAgain.body?.newClueAdded ?? false;
        expect(rewardSecond, 'same follow-up should not grant reward again').toBeFalsy();
      }

      // --- Step 9: Check cross-effects — timeline should have a pending/unconfirmed event ---
      const timelineCheck = await tryRequest([
        `${prefix}/timeline`,
        `${prefix}/timelines`,
      ], { method: 'GET' });
      expect(timelineCheck.res.status).toBe(200);
      const tlItems = timelineCheck.body?.items || timelineCheck.body?.timeline || timelineCheck.body?.events || [];
      if (Array.isArray(tlItems) && tlItems.length > 0) {
        // Look for pending/unconfirmed events from follow-up
        const pendingEvents = tlItems.filter(e =>
          e.status === 'pending' || e.status === 'unconfirmed' || e.confirmed === false || e.pending === true
        );
        // At least note that this path was checked
        expect(Array.isArray(tlItems)).toBe(true);
      }

      // --- Step 10: Test refusal scenario — attempt a question the NPC refuses ---
      const refusalAttempt = await tryRequest([
        `${prefix}/interrogations`,
        `${prefix}/interrogations/${npcId}/ask`,
        `${prefix}/npc/${npcId}/ask`,
      ], {
        method: 'POST',
        body: JSON.stringify({ npcId, questionId: 'fq_refused_topic', kind: 'followup' }),
      });

      // Verify refusal is recorded with a clear reason
      const refusalBody = refusalAttempt.body || {};
      const isRefused = refusalBody.refused === true || refusalBody.status === 'refused' ||
        (typeof refusalBody.message === 'string' && refusalBody.message.toLowerCase().includes('refuse')) ||
        [400, 403, 409].includes(refusalAttempt.res.status);

      if (isRefused) {
        // Verify refusal has a specific reason (not just empty rejection)
        const reason = refusalBody.reason || refusalBody.message || refusalBody.lockedReason || '';
        expect(
          typeof reason === 'string' && reason.trim().length > 0,
          `refusal should have a clear explanation, got ${JSON.stringify(refusalBody)}`
        ).toBe(true);
      }

      // Verify history is preserved after refusal attempt
      const historyAfterRefusal = await tryRequest([
        `${prefix}/interrogations/history?npcId=${npcId}`,
        `${prefix}/interrogations/${npcId}/history`,
        `${prefix}/npc/${npcId}/history`,
      ], { method: 'GET' });
      expect(historyAfterRefusal.res.status).toBe(200);
      const histAfter = historyAfterRefusal.body?.items || historyAfterRefusal.body?.history || historyAfterRefusal.body?.dialogues || historyAfterRefusal.body || [];
      expect(Array.isArray(histAfter)).toBe(true);
      // History should still contain at least the earlier interactions
      expect(histAfter.length, 'history should be preserved after refusal').toBeGreaterThanOrEqual(2);

      // If refusal was recorded, it should appear in history
      if (isRefused) {
        const refusalInHistory = histAfter.some(h =>
          h.status === 'refused' || h.refused === true ||
          (h.questionId || h.id) === 'fq_refused_topic'
        );
        // Refusal should leave a record in dialogue history
        expect(
          refusalInHistory || histAfter.length >= 3,
          'refusal should leave a record in dialogue history'
        ).toBe(true);
      }

    } finally {
      await request(`${session.prefix}`, { method: 'DELETE' }).catch(() => {});
      await request(`${session.basePath}/${session.id}`, { method: 'DELETE' }).catch(() => {});
    }
  });
});

