describe('reasoning_conflict_state_updates_with_timeline_changes', () => {
  it('should show reasoning conflict when referenced clues are placed in conflicting timeline phases and clear it after removing the conflicting event', async () => {
    // Create session
    const { res: createRes, body: createBody } = await request('/sessions', {
      method: 'POST',
      body: JSON.stringify({ title: `verifier-timeline-${Date.now()}`, scenario: 'detective-adventure' }),
    });
    expect(createRes.status).toBe(201);
    const sessionId = createBody.sessionId || createBody.id;
    expect(sessionId).toBeTruthy();

    // Create two clues
    const clues = [];
    for (const name of ['Timeline Clue A', 'Timeline Clue B']) {
      const { res, body } = await request(`/sessions/${sessionId}/clues`, {
        method: 'POST',
        body: JSON.stringify({ name, summary: `${name} summary`, category: 'evidence' }),
      });
      expect([200, 201]).toContain(res.status);
      clues.push(body.clueId || body.id);
    }

    // Create reasoning that links both clues
    const { res: reasoningRes, body: reasoningBody } = await request(`/sessions/${sessionId}/reasonings`, {
      method: 'POST',
      body: JSON.stringify({ title: 'Conflict Reasoning', clueIds: clues }),
    });
    expect([200, 201]).toContain(reasoningRes.status);
    const reasoningId = reasoningBody.reasoningId || reasoningBody.id;
    expect(reasoningId).toBeTruthy();

    // Place clue A in 'before-incident' phase
    const { res: eventResA, body: eventBodyA } = await request(`/sessions/${sessionId}/timeline/events`, {
      method: 'POST',
      body: JSON.stringify({ clueId: clues[0], phase: 'before-incident', label: 'Clue A before incident' }),
    });
    expect([200, 201]).toContain(eventResA.status);
    const eventIdA = eventBodyA.eventId || eventBodyA.id;
    expect(eventIdA).toBeTruthy();

    // Place the SAME clue A in 'after-incident' phase – this creates a conflict
    // (same clue in two contradictory phases)
    const { res: eventResConflict, body: eventBodyConflict } = await request(`/sessions/${sessionId}/timeline/events`, {
      method: 'POST',
      body: JSON.stringify({ clueId: clues[0], phase: 'after-incident', label: 'Clue A after incident (contradictory)' }),
    });
    expect([200, 201]).toContain(eventResConflict.status);
    const eventIdConflict = eventBodyConflict.eventId || eventBodyConflict.id;
    expect(eventIdConflict).toBeTruthy();

    // Verify reasoning now shows conflict/contradiction
    const { res: reasoningGetRes1, body: reasoningGetBody1 } = await request(`/sessions/${sessionId}/reasonings/${reasoningId}`, { method: 'GET' });
    expect(reasoningGetRes1.status).toBe(200);
    expect(reasoningGetBody1).toBeTruthy();

    const hasConflict1 = reasoningGetBody1.hasConflict ?? reasoningGetBody1.conflicted ?? reasoningGetBody1.contradiction;
    expect(
      hasConflict1,
      `reasoning should indicate conflict after same clue placed in contradictory timeline phases, got ${JSON.stringify(reasoningGetBody1)}`
    ).toBe(true);

    // If there's a conflict message, verify it's informative
    const conflictMsg = reasoningGetBody1.conflictMessage || reasoningGetBody1.contradictionMessage || '';
    if (typeof conflictMsg === 'string' && conflictMsg.length > 0) {
      expect(conflictMsg.length).toBeGreaterThan(0);
    }

    // Remove the conflicting timeline event (the one in after-incident)
    const { res: deleteEventRes } = await request(`/sessions/${sessionId}/timeline/events/${eventIdConflict}`, {
      method: 'DELETE',
    });
    expect([200, 204]).toContain(deleteEventRes.status);

    // Verify reasoning conflict is now cleared
    const { res: reasoningGetRes2, body: reasoningGetBody2 } = await request(`/sessions/${sessionId}/reasonings/${reasoningId}`, { method: 'GET' });
    expect(reasoningGetRes2.status).toBe(200);

    const hasConflict2 = reasoningGetBody2.hasConflict ?? reasoningGetBody2.conflicted ?? reasoningGetBody2.contradiction;
    expect(
      hasConflict2,
      `reasoning conflict should clear after removing conflicting timeline event, got ${JSON.stringify(reasoningGetBody2)}`
    ).toBe(false);

    // Also test: place clue B in a conflicting way and verify conflict returns
    const { res: eventResBConflict1 } = await request(`/sessions/${sessionId}/timeline/events`, {
      method: 'POST',
      body: JSON.stringify({ clueId: clues[1], phase: 'before-incident', label: 'Clue B before' }),
    });
    expect([200, 201]).toContain(eventResBConflict1.status);

    const { res: eventResBConflict2, body: eventBodyBConflict2 } = await request(`/sessions/${sessionId}/timeline/events`, {
      method: 'POST',
      body: JSON.stringify({ clueId: clues[1], phase: 'after-incident', label: 'Clue B after (contradictory)' }),
    });
    expect([200, 201]).toContain(eventResBConflict2.status);
    const eventIdBConflict = eventBodyBConflict2.eventId || eventBodyBConflict2.id;

    // Verify conflict reappears
    const { res: reasoningGetRes3, body: reasoningGetBody3 } = await request(`/sessions/${sessionId}/reasonings/${reasoningId}`, { method: 'GET' });
    expect(reasoningGetRes3.status).toBe(200);
    const hasConflict3 = reasoningGetBody3.hasConflict ?? reasoningGetBody3.conflicted ?? reasoningGetBody3.contradiction;
    expect(
      hasConflict3,
      `reasoning should indicate conflict again after clue B placed in contradictory phases, got ${JSON.stringify(reasoningGetBody3)}`
    ).toBe(true);

    // Clean up conflicting event to restore clean state
    await request(`/sessions/${sessionId}/timeline/events/${eventIdBConflict}`, { method: 'DELETE' });

    await cleanup(`/sessions/${sessionId}`);
  });
});

