describe('reasoning_requires_two_to_three_unique_clues', () => {
  it('should enforce 2-3 unique clues, reject duplicate combinations, and show referenced clues in reasoning list', async () => {
    const { res: createRes, body: createBody } = await request('/sessions', {
      method: 'POST',
      body: JSON.stringify({ title: `verifier-reasoning-${Date.now()}`, scenario: 'detective-adventure' }),
    });
    expect(createRes.status).toBe(201);
    const sessionId = createBody.sessionId || createBody.id;
    expect(sessionId).toBeTruthy();

    const cluePayloads = [
      { name: 'Clue A', summary: 'first', category: 'evidence' },
      { name: 'Clue B', summary: 'second', category: 'testimony' },
      { name: 'Clue C', summary: 'third', category: 'note' },
      { name: 'Clue D', summary: 'fourth', category: 'evidence' },
    ];

    const clueIds = [];
    for (const payload of cluePayloads) {
      const { res, body } = await request(`/sessions/${sessionId}/clues`, {
        method: 'POST',
        body: JSON.stringify(payload),
      });
      expect([200, 201]).toContain(res.status);
      clueIds.push(body.clueId || body.id);
    }

    const { res: lessRes, body: lessBody } = await request(`/sessions/${sessionId}/reasonings`, {
      method: 'POST',
      body: JSON.stringify({ title: 'Too Few', clueIds: [clueIds[0]] }),
    });
    expect([400, 422]).toContain(lessRes.status);
    expect((lessBody.message || lessBody.reason || '').toLowerCase()).toContain('2');

    const { res: validRes, body: validBody } = await request(`/sessions/${sessionId}/reasonings`, {
      method: 'POST',
      body: JSON.stringify({ title: 'Valid Reasoning', clueIds: [clueIds[0], clueIds[1], clueIds[2]] }),
    });
    expect([200, 201]).toContain(validRes.status);
    const reasoningId = validBody.reasoningId || validBody.id;
    expect(reasoningId).toBeTruthy();
    expect((validBody.clueIds || []).length).toBeGreaterThanOrEqual(2);

    const { res: overRes, body: overBody } = await request(`/sessions/${sessionId}/reasonings`, {
      method: 'POST',
      body: JSON.stringify({ title: 'Too Many', clueIds: [clueIds[0], clueIds[1], clueIds[2], clueIds[3]] }),
    });
    expect([400, 422]).toContain(overRes.status);
    expect((overBody.message || overBody.reason || '').toLowerCase()).toContain('3');

    const { res: dupRes, body: dupBody } = await request(`/sessions/${sessionId}/reasonings`, {
      method: 'POST',
      body: JSON.stringify({ title: 'Duplicate Combo', clueIds: [clueIds[0], clueIds[1], clueIds[2]] }),
    });
    expect([400, 409]).toContain(dupRes.status);
    expect((dupBody.message || dupBody.reason || '').toLowerCase()).toMatch(/duplicate|already/);

    const { res: listRes, body: listBody } = await request(`/sessions/${sessionId}/reasonings`, { method: 'GET' });
    expect(listRes.status).toBe(200);
    const reasonings = listBody.items || listBody.reasonings || [];
    const saved = reasonings.find((r) => (r.reasoningId || r.id) === reasoningId);
    expect(saved, `expected saved reasoning ${reasoningId} in list`).toBeTruthy();
    const referenced = saved.clues || saved.clueIds || [];
    expect(referenced.length, 'saved reasoning should display referenced clues').toBeGreaterThanOrEqual(2);

    await cleanup(`/sessions/${sessionId}`);
  });
});

