function getId(obj) {
  if (!obj) return null;
  return obj.id || obj.caseId || obj.evidenceId || obj.reasoningId || obj.eventId || obj.saveId || null;
}

describe('round13_end_to_end_state_sync', () => {
  it('full end-to-end chain: evidence → inquiry → panel → reasoning → timeline → suspect assessment → report, with revocation sync and export/import restore', async () => {
    // Step 0: Create a case
    const created = await request('/api/cases', {
      method: 'POST',
      body: JSON.stringify({ title: `e2e-sync-${Date.now()}` }),
    });
    expect([200, 201]).toContain(created.res.status);
    const caseId = getId(created.body);
    expect(caseId).toBeTruthy();

    try {
      // Step 1: Collect evidence from crime scene
      const evidence1 = await request(`/api/cases/${caseId}/evidence`, {
        method: 'POST',
        body: JSON.stringify({ itemId: 'clue_watch', name: '停摆怀表', category: 'physical', description: '一块停在20:15的怀表' }),
      });
      expect([200, 201]).toContain(evidence1.res.status);
      const ev1Id = getId(evidence1.body) || 'clue_watch';

      // Step 2: NPC inquiry — question NPC and get testimony
      const askRes = await request(`/api/cases/${caseId}/dialogues`, {
        method: 'POST',
        body: JSON.stringify({ npcId: 'butler', questionId: 'q_timeline' }),
      });
      expect([200, 201]).toContain(askRes.res.status);
      expect(askRes.body).toBeTruthy();

      // Collect testimony as evidence
      const testimony = await request(`/api/cases/${caseId}/evidence`, {
        method: 'POST',
        body: JSON.stringify({ itemId: 'clue_testimony', name: '管家口供：听到争吵声', category: 'testimony', description: '管家声称在20:10左右听到激烈争吵' }),
      });
      expect([200, 201]).toContain(testimony.res.status);
      const testimonyId = getId(testimony.body) || 'clue_testimony';

      // Step 3: Verify both clues appear in investigation panel immediately
      const panelRes = await request(`/api/cases/${caseId}/evidence`, { method: 'GET' });
      expect(panelRes.res.status).toBe(200);
      const panelList = Array.isArray(panelRes.body) ? panelRes.body : (panelRes.body?.items || panelRes.body?.evidence || []);
      expect(panelList.length).toBeGreaterThanOrEqual(2);
      const panelIds = panelList.map(e => e.id || e.itemId);
      expect(panelIds).toContain(ev1Id);
      expect(panelIds).toContain(testimonyId);

      // Step 4: Create reasoning linking the two clues
      const reasoning = await request(`/api/cases/${caseId}/reasoning`, {
        method: 'POST',
        body: JSON.stringify({
          linkedEvidence: [ev1Id, testimonyId],
          conclusion: '怀表停止时间与管家听到争吵时间高度吻合，说明案发时刻可确定',
        }),
      });
      expect([200, 201]).toContain(reasoning.res.status);
      const reasoningId = getId(reasoning.body);
      expect(reasoningId).toBeTruthy();

      // Step 5: Add timeline events
      const timelineEvent1 = await request(`/api/cases/${caseId}/timeline`, {
        method: 'POST',
        body: JSON.stringify({
          label: '20:10 激烈争吵',
          phase: 'during',
          description: 'Loud quarrel heard by butler',
          linkedClues: [ev1Id, testimonyId],
        }),
      });
      expect([200, 201]).toContain(timelineEvent1.res.status);
      const timelineEventId = getId(timelineEvent1.body);
      expect(timelineEventId).toBeTruthy();

      // Step 6: Check suspect assessment IMMEDIATELY reflects new information
      const suspectsBefore = await request(`/api/cases/${caseId}/suspects`, { method: 'GET' });
      expect(suspectsBefore.res.status).toBe(200);
      const suspectListBefore = Array.isArray(suspectsBefore.body) ? suspectsBefore.body : (suspectsBefore.body?.items || suspectsBefore.body?.suspects || []);
      // Save snapshot for later comparison
      const suspectSnapshotBefore = JSON.parse(JSON.stringify(suspectListBefore));

      // Step 7: Create case report (draft) with key evidence
      const report = await request(`/api/cases/${caseId}/report`, {
        method: 'POST',
        body: JSON.stringify({
          suspectId: 'suspect_alpha',
          reasoning: '依据停电与怀表线索以及管家口供，嫌疑人在关键时段进入现场。',
          keyEvidence: [ev1Id, testimonyId],
          status: 'draft',
        }),
      });
      expect([200, 201]).toContain(report.res.status);
      expect(report.body).toBeTruthy();
      const reportReasoning = report.body.reasoning || report.body.logic || '';
      expect(reportReasoning).toContain('怀表');

      // Verify report key evidence before revocation
      const basisBefore = await request(`/api/cases/${caseId}/report`, { method: 'GET' });
      expect(basisBefore.res.status).toBe(200);
      const keyEvidenceBefore = basisBefore.body.keyEvidence || basisBefore.body.keyEvidences || basisBefore.body.evidence || [];
      expect(keyEvidenceBefore).toContain(ev1Id);

      // === Step 8: REVOKE — delete the reasoning ===
      const removeReasoning = await request(`/api/cases/${caseId}/reasoning/${reasoningId}`, { method: 'DELETE' });
      expect([200, 204]).toContain(removeReasoning.res.status);

      // Step 9: Verify report AFTER reasoning revocation — text preserved, invalidation indicated
      const reportAfterReasoningDel = await request(`/api/cases/${caseId}/report`, { method: 'GET' });
      expect(reportAfterReasoningDel.res.status).toBe(200);
      const afterBody = reportAfterReasoningDel.body;

      // Text should be preserved (not cleared)
      const afterReasoning = afterBody.reasoning || afterBody.logic || '';
      expect(afterReasoning).toContain('怀表');

      // Must have invalidation markers that identify what became invalid
      const invalidatedItems = afterBody.invalidatedReasonings
        || afterBody.invalidItems
        || afterBody.staleReasonings
        || afterBody.warnings
        || afterBody.invalidated;
      expect(invalidatedItems, `Report should contain invalidation markers after reasoning deletion, got: ${JSON.stringify(afterBody)}`).toBeTruthy();

      // The invalidation should reference the deleted reasoning
      const invalidStr = JSON.stringify(invalidatedItems);
      expect(
        invalidStr.includes(reasoningId) || invalidStr.includes('reasoning') || invalidStr.includes('invalidat') || invalidStr.includes('stale'),
        `Invalidation markers should reference the deleted reasoning or indicate staleness, got: ${invalidStr}`
      ).toBe(true);

      // Step 10: Verify suspect assessment changed after reasoning revocation
      const suspectsAfterReasoning = await request(`/api/cases/${caseId}/suspects`, { method: 'GET' });
      expect(suspectsAfterReasoning.res.status).toBe(200);
      const suspectListAfterReasoning = Array.isArray(suspectsAfterReasoning.body) ? suspectsAfterReasoning.body : (suspectsAfterReasoning.body?.items || suspectsAfterReasoning.body?.suspects || []);
      // Suspect data should have changed (not identical to before)
      const suspectSnapshotAfterReasoning = JSON.stringify(suspectListAfterReasoning);
      expect(
        suspectSnapshotAfterReasoning !== JSON.stringify(suspectSnapshotBefore) || suspectListAfterReasoning.length === 0,
        'Suspect assessment should change after reasoning revocation'
      ).toBe(true);

      // === Step 11: REVOKE — delete the timeline event ===
      const removeTimeline = await request(`/api/cases/${caseId}/timeline/${timelineEventId}`, { method: 'DELETE' });
      expect([200, 204]).toContain(removeTimeline.res.status);

      // Step 12: Verify report AFTER timeline event removal — text still preserved, new invalidation
      const reportAfterTimelineDel = await request(`/api/cases/${caseId}/report`, { method: 'GET' });
      expect(reportAfterTimelineDel.res.status).toBe(200);
      const afterTimelineBody = reportAfterTimelineDel.body;

      // Text still preserved
      const afterTimelineReasoning = afterTimelineBody.reasoning || afterTimelineBody.logic || '';
      expect(afterTimelineReasoning).toContain('怀表');

      // Step 13: Verify suspect assessment also changed after timeline removal
      const suspectsAfterTimeline = await request(`/api/cases/${caseId}/suspects`, { method: 'GET' });
      expect(suspectsAfterTimeline.res.status).toBe(200);
      const suspectListAfterTimeline = Array.isArray(suspectsAfterTimeline.body) ? suspectsAfterTimeline.body : (suspectsAfterTimeline.body?.items || suspectsAfterTimeline.body?.suspects || []);
      expect(suspectListAfterTimeline).toBeDefined();

      // === Step 14: Export / Import cycle to verify state restoration ===
      const exportRes = await request(`/api/cases/${caseId}/export`, { method: 'GET' });
      expect(exportRes.res.status).toBe(200);
      expect(exportRes.body).toBeTruthy();
      const exportData = exportRes.body;

      // Import
      const importRes = await request('/api/saves/import', {
        method: 'POST',
        body: JSON.stringify(exportData),
      });
      expect([200, 201]).toContain(importRes.res.status);
      const importedId = getId(importRes.body);
      expect(importedId).toBeTruthy();

      // Verify report state is restored in imported save (including text preservation)
      const restoredReport = await request(`/api/cases/${importedId}/report`, { method: 'GET' });
      expect(restoredReport.res.status).toBe(200);
      const restoredReasoning = restoredReport.body.reasoning || restoredReport.body.logic || '';
      expect(restoredReasoning).toContain('怀表');

      // Verify evidence is restored
      const restoredEvidence = await request(`/api/cases/${importedId}/evidence`, { method: 'GET' });
      expect(restoredEvidence.res.status).toBe(200);
      const restoredList = Array.isArray(restoredEvidence.body) ? restoredEvidence.body : (restoredEvidence.body?.items || restoredEvidence.body?.evidence || []);
      expect(restoredList.length).toBeGreaterThanOrEqual(2);

      // Cleanup imported case
      if (importedId !== caseId) {
        await request(`/api/cases/${importedId}`, { method: 'DELETE' }).catch(() => {});
      }
    } finally {
      await request(`/api/cases/${caseId}`, { method: 'DELETE' }).catch(() => {});
    }
  });
});

