import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function request(path, options = {}) {
  const res = await fetch(`${BASE_URL}${path}`, {
    headers: {
      'Content-Type': 'application/json',
      ...(options.headers || {}),
    },
    ...options,
  });

  const text = await res.text();
  let body;
  try {
    body = text ? JSON.parse(text) : null;
  } catch {
    body = text;
  }

  return { res, body };
}

function extractId(obj, ...keys) {
  if (!obj) return null;
  for (const k of keys) {
    if (obj[k]) return obj[k];
  }
  return null;
}

function extractList(body) {
  if (Array.isArray(body)) return body;
  if (!body) return [];
  for (const key of ['items', 'questions', 'history', 'messages', 'clues', 'evidences', 'characters', 'npcs']) {
    if (Array.isArray(body[key])) return body[key];
  }
  return [];
}

async function tryPaths(paths, options = {}) {
  for (const path of paths) {
    const result = await request(path, options);
    if ([200, 201].includes(result.res.status)) return { ...result, usedPath: path };
  }
  return { ...(await request(paths[0], options)), usedPath: paths[0] };
}

describe('round2_npc_dialogue_state_persistence', () => {
  it('should persist NPC dialogue history, asked state, evidence-unlocked question state, generated clue data across reloads, and handle boundaries', async () => {
    const runId = `vitest-round2-${Date.now()}-${Math.random().toString(36).slice(2)}`;

    // Create case
    let caseId, basePath;
    const createCase = await request('/api/cases', {
      method: 'POST',
      body: JSON.stringify({ title: `Round2 NPC ${runId}` }),
    });
    if ([200, 201].includes(createCase.res.status)) {
      caseId = extractId(createCase.body, 'id', 'caseId');
      basePath = `/api/cases/${caseId}`;
    }
    if (!caseId) {
      const createSession = await request('/api/sessions', {
        method: 'POST',
        body: JSON.stringify({ name: `Round2 Session ${runId}`, playerId: `player-${runId}` }),
      });
      expect([200, 201]).toContain(createSession.res.status);
      caseId = extractId(createSession.body, 'id', 'sessionId', 'caseId');
      basePath = `/api/sessions/${caseId}`;
    }
    expect(caseId).toBeTruthy();

    try {
      // Find or create NPC
      let npcId;
      const npcPathVariants = [`${basePath}/npcs`, `${basePath}/characters`];
      for (const p of npcPathVariants) {
        const listRes = await request(p, { method: 'GET' });
        if (listRes.res.status === 200) {
          const list = extractList(listRes.body);
          if (list.length > 0) {
            npcId = extractId(list[0], 'id', 'npcId', 'characterId');
            break;
          }
        }
      }
      if (!npcId) {
        const createNpc = await tryPaths(npcPathVariants, {
          method: 'POST',
          body: JSON.stringify({ npcKey: `maid-${runId}`, name: 'The Maid', role: 'suspect' }),
        });
        if ([200, 201].includes(createNpc.res.status)) {
          npcId = extractId(createNpc.body, 'id', 'npcId', 'characterId');
        }
      }
      expect(npcId, 'expected to have an NPC').toBeTruthy();

      // Create evidence to unlock questions
      const evPaths = [`${basePath}/evidences`, `${basePath}/evidence`];
      const createEvidence = await tryPaths(evPaths, {
        method: 'POST',
        body: JSON.stringify({ id: `broken-watch-${runId}`, title: 'Broken Watch', type: 'unlock-question', category: 'physical', sourceObjectId: `watch-${runId}` }),
      });
      expect([200, 201]).toContain(createEvidence.res.status);
      const evidenceId = extractId(createEvidence.body, 'id', 'evidenceId') || `broken-watch-${runId}`;

      // Get initial questions
      const qPaths = [
        `${basePath}/npcs/${npcId}/questions`,
        `${basePath}/characters/${npcId}/questions`,
      ];
      const questionsBefore = await tryPaths(qPaths, { method: 'GET' });
      expect(questionsBefore.res.status).toBe(200);
      const beforeList = extractList(questionsBefore.body);
      expect(beforeList.length).toBeGreaterThan(0);

      const initialUnlocked = beforeList.find(q => q.unlocked === true || q.locked === false);
      const lockedQuestion = beforeList.find(q => q.locked === true || q.unlocked === false);
      expect(initialUnlocked, 'expected at least one initially unlocked question').toBeTruthy();

      // Verify locked question has hint
      if (lockedQuestion) {
        const hint = lockedQuestion.hint || lockedQuestion.reason || lockedQuestion.lockReason || lockedQuestion.description;
        expect(hint, `expected locked question to have a hint/reason, got ${JSON.stringify(lockedQuestion)}`).toBeTruthy();
      }

      const askedQuestionId = extractId(initialUnlocked, 'id', 'questionId');
      const askPaths = [
        `${basePath}/npcs/${npcId}/ask`,
        `${basePath}/characters/${npcId}/ask`,
        `${basePath}/npcs/${npcId}/inquire`,
      ];

      // Ask the unlocked question
      const askInitial = await tryPaths(askPaths, {
        method: 'POST',
        body: JSON.stringify({ questionId: askedQuestionId }),
      });
      expect([200, 201]).toContain(askInitial.res.status);
      const answer1 = askInitial.body?.answer || askInitial.body?.reply || askInitial.body?.message;
      expect(answer1, 'expected ask response to include answer/reply/message').toBeTruthy();

      // Boundary: re-ask same question — should NOT create duplicate dialogue entries
      const reAsk = await tryPaths(askPaths, {
        method: 'POST',
        body: JSON.stringify({ questionId: askedQuestionId }),
      });
      // Should be handled gracefully (idempotent 200 or rejection 409/4xx)
      expect([200, 201, 400, 409, 422].includes(reAsk.res.status), `expected re-ask to be handled, got ${reAsk.res.status}`).toBe(true);

      // Boundary: try asking a locked question — should fail with reason
      if (lockedQuestion) {
        const lockedQId = extractId(lockedQuestion, 'id', 'questionId');
        const askLockedRes = await tryPaths(askPaths, {
          method: 'POST',
          body: JSON.stringify({ questionId: lockedQId }),
        });
        expect([400, 403, 422, 423].includes(askLockedRes.res.status), `expected asking locked question to fail, got ${askLockedRes.res.status}`).toBe(true);
        // Should explain WHY it's locked (insufficient clues, trust, etc.)
        const failReason = askLockedRes.body?.reason || askLockedRes.body?.message || askLockedRes.body?.error;
        expect(failReason, `expected rejection to include reason, got ${JSON.stringify(askLockedRes.body)}`).toBeTruthy();
      }

      // Unlock questions via evidence
      const unlockPaths = [
        `${basePath}/npcs/${npcId}/unlock-questions`,
        `${basePath}/characters/${npcId}/unlock-questions`,
        `${basePath}/npcs/${npcId}/unlock`,
      ];
      const unlockRes = await tryPaths(unlockPaths, {
        method: 'POST',
        body: JSON.stringify({ evidenceId }),
      });
      expect([200, 201]).toContain(unlockRes.res.status);

      // Find newly unlocked question
      const questionsAfterUnlock = await tryPaths(qPaths, { method: 'GET' });
      expect(questionsAfterUnlock.res.status).toBe(200);
      const afterUnlockList = extractList(questionsAfterUnlock.body);

      const unlockedQuestionId = (unlockRes.body?.unlockedQuestionIds || [])[0]
        || extractId(
          afterUnlockList.find(q => (q.unlocked === true || q.locked === false) && extractId(q, 'id', 'questionId') !== askedQuestionId),
          'id', 'questionId'
        );
      expect(unlockedQuestionId, 'expected at least one question to be unlocked by evidence').toBeTruthy();

      // Ask unlocked question
      const askUnlocked = await tryPaths(askPaths, {
        method: 'POST',
        body: JSON.stringify({ questionId: unlockedQuestionId }),
      });
      expect([200, 201]).toContain(askUnlocked.res.status);
      const answer2 = askUnlocked.body?.answer || askUnlocked.body?.reply || askUnlocked.body?.message;
      expect(answer2, 'expected unlocked question answer').toBeTruthy();

      // Check dialogue history before reload
      const historyPaths = [
        `${basePath}/npcs/${npcId}/dialogue-history`,
        `${basePath}/characters/${npcId}/dialogue-history`,
        `${basePath}/npcs/${npcId}/history`,
      ];
      const historyBefore = await tryPaths(historyPaths, { method: 'GET' });
      expect(historyBefore.res.status).toBe(200);
      const historyListBefore = extractList(historyBefore.body);
      expect(historyListBefore.length).toBeGreaterThanOrEqual(2);

      // Check clues — verify type distinction (testimony vs note) and content
      const cluePaths = [`${basePath}/clues`, `${basePath}/evidences`];
      const cluesBefore = await tryPaths(cluePaths, { method: 'GET' });
      expect(cluesBefore.res.status).toBe(200);
      const clueListBefore = extractList(cluesBefore.body);
      const generatedCluesBefore = clueListBefore.filter(clue => {
        const src = clue.npcId || clue.sourceNpcId || clue.source;
        const srcQ = clue.questionId || clue.sourceQuestionId;
        return src === npcId || srcQ === askedQuestionId || srcQ === unlockedQuestionId ||
          clue.category === 'testimony' || clue.type === 'testimony' || clue.type === 'note';
      });
      expect(generatedCluesBefore.length, 'expected questioning to generate testimony/note clues').toBeGreaterThan(0);

      // Verify clue has type and content fields
      for (const clue of generatedCluesBefore) {
        const clueType = clue.type || clue.category;
        expect(clueType, `expected clue to have a type/category field, got ${JSON.stringify(clue)}`).toBeTruthy();
        const hasContent = clue.title || clue.name || clue.summary || clue.description || clue.content;
        expect(hasContent, `expected clue to have content (title/name/summary), got ${JSON.stringify(clue)}`).toBeTruthy();
      }

      // === Simulate page reload ===
      await request(basePath, { method: 'GET' });

      // Questions persist
      const questionsAfterReload = await tryPaths(qPaths, { method: 'GET' });
      expect(questionsAfterReload.res.status).toBe(200);
      const afterReloadList = extractList(questionsAfterReload.body);

      // Asked questions remain marked
      for (const qId of [askedQuestionId, unlockedQuestionId]) {
        const record = afterReloadList.find(q => extractId(q, 'id', 'questionId') === qId);
        expect(record, `expected question ${qId} to exist after reload`).toBeTruthy();
        const isAsked = record.asked === true || record.hasAsked === true || record.status === 'asked';
        expect(isAsked, `expected question ${qId} to be marked as asked after reload, got ${JSON.stringify(record)}`).toBe(true);
      }

      // Evidence-unlocked question stays unlocked
      const unlockedRecord = afterReloadList.find(q => extractId(q, 'id', 'questionId') === unlockedQuestionId);
      expect(unlockedRecord).toBeTruthy();
      expect(unlockedRecord.locked === false || unlockedRecord.unlocked === true, 'expected unlocked question to remain unlocked after reload').toBe(true);

      // Locked question remains locked (if it wasn't the one we unlocked)
      if (lockedQuestion) {
        const lockedId = extractId(lockedQuestion, 'id', 'questionId');
        if (lockedId !== unlockedQuestionId) {
          const lockedRecord = afterReloadList.find(q => extractId(q, 'id', 'questionId') === lockedId);
          if (lockedRecord) {
            expect(lockedRecord.locked === true || lockedRecord.unlocked === false, 'expected locked question to remain locked').toBe(true);
          }
        }
      }

      // Dialogue history persists
      const historyAfter = await tryPaths(historyPaths, { method: 'GET' });
      expect(historyAfter.res.status).toBe(200);
      const historyListAfter = extractList(historyAfter.body);
      expect(historyListAfter.length).toBeGreaterThanOrEqual(2);

      // Clues persist
      const cluesAfter = await tryPaths(cluePaths, { method: 'GET' });
      expect(cluesAfter.res.status).toBe(200);
      const clueListAfter = extractList(cluesAfter.body);
      const generatedCluesAfter = clueListAfter.filter(clue => {
        const src = clue.npcId || clue.sourceNpcId || clue.source;
        const srcQ = clue.questionId || clue.sourceQuestionId;
        return src === npcId || srcQ === askedQuestionId || srcQ === unlockedQuestionId ||
          clue.category === 'testimony' || clue.type === 'testimony' || clue.type === 'note';
      });
      expect(generatedCluesAfter.length, 'expected clues to persist after reload').toBeGreaterThan(0);
    } finally {
      await request(basePath, { method: 'DELETE' }).catch(() => {});
    }
  });
});

import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function request(path, init = {}) {
  const res = await fetch(`${BASE_URL}${path}`, {
    headers: {
      'Content-Type': 'application/json',
      ...(init.headers || {}),
    },
    ...init,
  });
  let body = null;
  const text = await res.text();
  try {
    body = text ? JSON.parse(text) : null;
  } catch {
    body = text;
  }
  return { res, body };
}

async function tryRequest(paths, options = {}) {
  for (const path of paths) {
    try {
      const result = await request(path, options);
      if ([200, 201].includes(result.res.status)) return { ...result, usedPath: path };
      if ([400, 403, 409, 422].includes(result.res.status)) return { ...result, usedPath: path };
    } catch {}
  }
  return request(paths[0], options);
}

async function createCase(suffix) {
  const attempts = [
    { path: '/api/cases', body: { title: `chapter-test-${suffix}` } },
    { path: '/api/sessions', body: { name: `chapter-test-${suffix}` } },
    { path: '/api/game/cases', body: { title: `chapter-test-${suffix}` } },
  ];
  for (const a of attempts) {
    try {
      const result = await request(a.path, { method: 'POST', body: JSON.stringify(a.body) });
      if ([200, 201].includes(result.res.status)) {
        const id = result.body?.id || result.body?.caseId || result.body?.sessionId;
        if (id) return { id, prefix: `${a.path}/${id}`, basePath: a.path };
      }
    } catch {}
  }
  throw new Error('Could not create case');
}

function extractArray(body, ...keys) {
  for (const key of keys) {
    if (body && Array.isArray(body[key])) return body[key];
  }
  if (Array.isArray(body)) return body;
  return [];
}

function findChapter2(items) {
  return items.find(x =>
    x.id === 'chapter2' || x.id === 'ch2' ||
    x.chapter === 2 || x.chapterNumber === 2 ||
    x.number === 2 || x.index === 1
  );
}

function isChapterLocked(ch) {
  if (!ch) return true; // No chapter entry = locked
  return ch.unlocked === false || ch.locked === true || ch.status === 'locked' || ch.available === false;
}

function isChapterUnlocked(ch) {
  if (!ch) return false;
  return ch.unlocked === true || ch.locked === false || ch.status === 'unlocked' || ch.status === 'open' || ch.available === true;
}

describe('round20_chapter_unlock_and_compatibility', () => {
  it('keeps chapter 2 locked until chapter 1 is formally closed', async () => {
    const suffix = Date.now();
    const caseData = await createCase(suffix);
    const { prefix } = caseData;

    try {
      // --- Verify chapter 2 is locked initially ---
      const chaptersBefore = await tryRequest([
        `${prefix}/chapters`,
        `${prefix}/chapter`,
        `${prefix}/game/chapters`,
      ], { method: 'GET' });
      expect(chaptersBefore.res.status).toBe(200);
      const beforeItems = extractArray(chaptersBefore.body, 'items', 'chapters');
      expect(Array.isArray(beforeItems)).toBe(true);
      const ch2Before = findChapter2(beforeItems);
      // Chapter 2 must either not exist or be locked
      expect(
        !ch2Before || isChapterLocked(ch2Before),
        `Chapter 2 should be locked initially, got ${JSON.stringify(ch2Before)}`
