function findChapter2(items) {
  return items.find(x =>
    x.id === 'chapter2' || x.id === 'ch2' ||
    x.chapter === 2 || x.chapterNumber === 2 ||
    x.number === 2 || x.index === 1
  );
}

function isChapterLocked(ch) {
  if (!ch) return true;
  return ch.unlocked === false || ch.locked === true || ch.status === 'locked' || ch.available === false;
}

function isChapterUnlocked(ch) {
  if (!ch) return false;
  return ch.unlocked === true || ch.locked === false || ch.status === 'unlocked' || ch.status === 'open' || ch.available === true;
}

import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function request(path, options = {}) {
  const res = await fetch(`${BASE_URL}${path}`, {
    headers: {
      'Content-Type': 'application/json',
      ...(options.headers || {}),
    },
    ...options,
  });
  let body = null;
  const text = await res.text();
  try {
    body = text ? JSON.parse(text) : null;
  } catch {
    body = text;
  }
  return { res, body };
}

async function safeDelete(path) {
  try {
    await fetch(`${BASE_URL}${path}`, { method: 'DELETE' });
  } catch { /* ignore */ }
}

describe('round18_import_rules_unchanged', () => {
  it('importing a legacy save with only basic evidence and dialogues should auto-fill structure but NOT generate reasoning, timeline, or closure results; chapters should be auto-structured', async () => {
    const cleanupPaths = [];

    try {
      // --- Part 1: Import legacy save (only basic evidence + dialogues, no reasoning/timeline/closure) ---
      const legacySave = {
        version: 1,
        evidence: [
          { id: 'legacy-ev-1', name: 'Old Letter' },
