      expect(importResp.body).toBeTruthy();
      const importedId = importResp.body.id || importResp.body.saveId;
      expect(importedId).toBeTruthy();
      cleanupPaths.push(`/api/saves/${importedId}`);

      // Fetch the imported save and verify migration
      const getResp = await request(`/api/saves/${importedId}`, { method: 'GET' });
      expect(getResp.res.status).toBe(200);
      expect(getResp.body).toBeTruthy();
      const save = getResp.body.save || getResp.body;

      // Evidence should be preserved
      const evidence = save.evidence || save.caseData?.evidence || save.chapters?.[0]?.evidence || save.chapters?.chapter1?.evidence || [];
      expect(Array.isArray(evidence)).toBe(true);
      expect(evidence.length).toBeGreaterThanOrEqual(2);
      expect(evidence.some((e) => e.id === 'legacy-ev-1')).toBe(true);
      expect(evidence.some((e) => e.id === 'legacy-ev-2')).toBe(true);

      // Each evidence should have a category assigned (default category migration)
      for (const e of evidence) {
        const cat = e.category || e.group;
        expect(cat, `Evidence ${e.id} should have a category after migration`).toBeTruthy();
      }

      // Dialogues should be preserved
      const dialogues = save.dialogues || save.caseData?.dialogues || save.chapters?.[0]?.dialogues || save.chapters?.chapter1?.dialogues || [];
      expect(Array.isArray(dialogues)).toBe(true);
      expect(dialogues.length).toBeGreaterThanOrEqual(1);

      // Reasoning must NOT be auto-generated (should be undefined/null/empty array)
      const reasoning = save.reasoning || save.caseData?.reasoning || save.chapters?.[0]?.reasoning || save.chapters?.chapter1?.reasoning;
      if (reasoning !== undefined && reasoning !== null) {
        expect(Array.isArray(reasoning), 'Reasoning field should be an array if present').toBe(true);
        expect(reasoning.length, 'Legacy import must not auto-generate reasoning records').toBe(0);
      }
      // If undefined/null that's also acceptable — no reasoning generated

      // Timeline must NOT be auto-generated
      const timeline = save.timeline || save.caseData?.timeline || save.chapters?.[0]?.timeline || save.chapters?.chapter1?.timeline;
      if (timeline !== undefined && timeline !== null) {
        expect(Array.isArray(timeline), 'Timeline field should be an array if present').toBe(true);
        expect(timeline.length, 'Legacy import must not auto-generate timeline entries').toBe(0);
      }

      // Closure / case result must NOT be auto-generated
      const closure = save.closure || save.caseClosure || save.report || save.caseData?.closure || save.caseData?.report;
      if (closure !== undefined && closure !== null) {
        const closureStatus = closure.status || '';
        expect(closureStatus).not.toMatch(/final|closed|completed|submitted/i);
      }

      // Chapter structure should be auto-filled: chapter 1 unlocked, chapter 2 locked (Round 20 requirement)
      const chapters = save.chapters || save.caseData?.chapters;
      if (chapters) {
        if (Array.isArray(chapters)) {
          // At least chapter 1 should exist and be unlocked
          expect(chapters.length).toBeGreaterThanOrEqual(1);
          const ch1 = chapters.find((c) => c.chapterNumber === 1 || c.chapter === 1) || chapters[0];
          expect(ch1.unlocked === true || ch1.locked === false, 'Chapter 1 should be unlocked').toBe(true);
          // If chapter 2 exists, it should be locked
          const ch2 = chapters.find((c) => c.chapterNumber === 2 || c.chapter === 2);
          if (ch2) {
            expect(ch2.unlocked === false || ch2.locked === true, 'Chapter 2 should remain locked for legacy import').toBe(true);
          }
        } else if (typeof chapters === 'object') {
          // Object-based chapters
          if (chapters.chapter1) {
            expect(chapters.chapter1.unlocked === true || chapters.chapter1.locked === false, 'Chapter 1 should be unlocked').toBe(true);
          }
          if (chapters.chapter2) {
            expect(chapters.chapter2.unlocked === false || chapters.chapter2.locked === true, 'Chapter 2 should remain locked for legacy import').toBe(true);
          }
        }
      }
    } finally {
      for (const p of cleanupPaths) {
        await safeDelete(p);
      }
    }
  });

