      // Current log should still be there
      const curLog = stateAfter.investigationLog || stateAfter.log || [];
      if (Array.isArray(curLog)) {
        expect(curLog.length, 'Current investigation log must survive corrupted import attempt').toBeGreaterThanOrEqual(1);
      }

      // Pinned items should still be there
      const pinned = stateAfter.pinned || stateAfter.pinnedClues || stateAfter.highlights || [];
      if (Array.isArray(pinned)) {
        expect(pinned.length, 'Current pinned/highlighted marks must survive corrupted import attempt').toBeGreaterThanOrEqual(1);
      }

      // Also check if there's a global "current progress" endpoint and verify it's intact
      const globalProgress = await request('/api/saves/current', { method: 'GET' });
      if (globalProgress.res.status === 200 && globalProgress.body) {
        const globalState = globalProgress.body.save || globalProgress.body;
