      const inquiry = boardResp.body?.dialogues || boardResp.body?.inquiry || boardResp.body?.sections?.inquiry || allItems.filter(i => i.type === 'inquiry' || i.type === 'dialogue') || [];

      expect(Array.isArray(evidence), `expected unified evidence array, got ${JSON.stringify(evidence)}`).toBe(true);
      expect(evidence.some(e => e.id === `legacy-board-evi-${suffix}`), `expected old evidence 'Key' on board, got ${JSON.stringify(evidence)}`).toBe(true);

      // --- Verify each evidence item has a proper default category (not using || fallback) ---
      for (const item of evidence) {
        const cat = item.category || item.group;
        expect(cat, `Expected evidence item ${item.id} to have a category/group field assigned, got ${JSON.stringify(item)}`).toBeTruthy();
        expect(typeof cat).toBe('string');
        expect(cat.length).toBeGreaterThan(0);
      }

      // --- Verify each evidence item has name and summary ---
      for (const item of evidence) {
        const itemName = item.name || item.title;
        expect(itemName, `Expected evidence item ${item.id} to have name/title, got ${JSON.stringify(item)}`).toBeTruthy();
        const itemSummary = item.summary || item.description || item.excerpt;
        expect(itemSummary, `Expected evidence item ${item.id} to have summary/description, got ${JSON.stringify(item)}`).toBeTruthy();
      }

      // --- Verify inquiry/dialogue section ---
      expect(Array.isArray(inquiry), `expected inquiry/dialogue section array, got ${JSON.stringify(inquiry)}`).toBe(true);
      expect(
        inquiry.some(i => JSON.stringify(i).includes(`legacy-npc-${suffix}`) || JSON.stringify(i).includes('alibi')),
        `expected dialogue-derived info on board, got ${JSON.stringify(inquiry)}`
      ).toBe(true);

      // --- Test search functionality ---
      const searchResp = await request(`/api/saves/${saveId}/board?search=Key`, { method: 'GET' });
      expect(searchResp.res.status).toBe(200);
      const searchItems = searchResp.body?.items || searchResp.body?.evidence || searchResp.body?.results || [];
      const searchCount = searchResp.body?.count ?? searchResp.body?.total ?? searchItems.length;
      expect(searchItems.length).toBeGreaterThan(0);
      expect(searchItems.some(e => (e.name || e.title || '').includes('Key'))).toBe(true);
      expect(searchCount).toBeGreaterThan(0);

      // --- Test category filter ---
      const defaultCat = evidence[0].category || evidence[0].group;
      const filterResp = await request(`/api/saves/${saveId}/board?category=${encodeURIComponent(defaultCat)}`, { method: 'GET' });
      expect(filterResp.res.status).toBe(200);
      const filterItems = filterResp.body?.items || filterResp.body?.evidence || filterResp.body?.results || [];
      const filterCount = filterResp.body?.count ?? filterResp.body?.total ?? filterItems.length;
      expect(filterItems.length).toBeGreaterThan(0);
      expect(filterCount).toBeGreaterThan(0);

      // --- Test empty search result returns hint/message ---
      const emptySearchResp = await request(`/api/saves/${saveId}/board?search=xyznonexistent999`, { method: 'GET' });
      expect(emptySearchResp.res.status).toBe(200);
      const emptyItems = emptySearchResp.body?.items || emptySearchResp.body?.evidence || emptySearchResp.body?.results || [];
      expect(emptyItems.length).toBe(0);
      const hint = emptySearchResp.body?.message || emptySearchResp.body?.hint || emptySearchResp.body?.emptyMessage;
      expect(hint, `Expected a hint/message when no results match, got ${JSON.stringify(emptySearchResp.body)}`).toBeTruthy();
      expect(typeof hint).toBe('string');
      expect(hint.length).toBeGreaterThan(0);

      // --- Test very long search keyword does not crash ---
      const longKeyword = 'a'.repeat(2000);
      const longSearchResp = await request(`/api/saves/${saveId}/board?search=${encodeURIComponent(longKeyword)}`, { method: 'GET' });
      expect([200, 400, 422].includes(longSearchResp.res.status), `Long keyword search should not crash, got ${longSearchResp.res.status}`).toBe(true);

      // --- Verify raw save still has original evidence (not lost) ---
      const rawSaveResp = await request(`/api/saves/${saveId}`, { method: 'GET' });
      expect(rawSaveResp.res.status).toBe(200);
      const rawEvidence = rawSaveResp.body?.save?.evidence || rawSaveResp.body?.evidence || rawSaveResp.body?.data?.evidence || [];
      expect(rawEvidence.some(e => e.id === `legacy-board-evi-${suffix}`), `expected saved evidence not lost after board upgrade, got ${JSON.stringify(rawEvidence)}`).toBe(true);
    } finally {
      await cleanup(cleanupPaths);
    }
  });
});

