describe('round15_validation_without_regression', () => {
  it('rejects blank, too-long reasoning, duplicate evidence; preserves draft on rejection; search/filter still works with edge inputs', async () => {
    const created = await request('/api/cases', {
      method: 'POST',
      body: JSON.stringify({ title: `verifier-round15-${Date.now()}` }),
    });
    expect([200, 201]).toContain(created.res.status);
    const caseId = created.body?.id ?? created.body?.caseId;
    expect(caseId).toBeTruthy();

    try {
      // Create two pieces of evidence
      await request(`/api/cases/${caseId}/evidences`, {
        method: 'POST',
        body: JSON.stringify({ id: 'clue_note', title: '便签纸', category: 'document' }),
      });
      await request(`/api/cases/${caseId}/evidences`, {
        method: 'POST',
        body: JSON.stringify({ id: 'clue_knife', title: '短刀', category: 'weapon' }),
      });

      // --- Step 1: Save a valid draft report first ---
      const validDraft = await request(`/api/cases/${caseId}/report`, {
        method: 'POST',
        body: JSON.stringify({
          suspectId: 'suspect_alpha',
          reasoning: '嫌疑人留下了书面痕迹，并在案发现场丢失了短刀。',
          keyEvidence: ['clue_note'],
          status: 'draft',
        }),
      });
      expect([200, 201]).toContain(validDraft.res.status);

      // --- Step 2: Reject blank (whitespace-only) reasoning ---
      const invalidBlank = await request(`/api/cases/${caseId}/report`, {
        method: 'POST',
        body: JSON.stringify({
          suspectId: 'suspect_alpha',
          reasoning: '   ',
          keyEvidence: ['clue_note'],
          status: 'draft',
        }),
      });
      expect([400, 422]).toContain(invalidBlank.res.status);
      expect(invalidBlank.body).toBeTruthy();

      // --- Step 3: Reject overly long reasoning text ---
      const longText = 'A'.repeat(10000);
      const invalidLong = await request(`/api/cases/${caseId}/report`, {
        method: 'POST',
        body: JSON.stringify({
          suspectId: 'suspect_alpha',
          reasoning: longText,
          keyEvidence: ['clue_note'],
          status: 'draft',
        }),
      });
      expect([400, 422]).toContain(invalidLong.res.status);
      expect(invalidLong.body).toBeTruthy();

      // --- Step 4: Reject duplicate key evidence ---
      const invalidDuplicate = await request(`/api/cases/${caseId}/report`, {
        method: 'POST',
        body: JSON.stringify({
          suspectId: 'suspect_alpha',
          reasoning: '嫌疑人留下了书面痕迹。',
          keyEvidence: ['clue_note', 'clue_note'],
          status: 'draft',
        }),
      });
      expect([400, 422]).toContain(invalidDuplicate.res.status);
      expect(invalidDuplicate.body).toBeTruthy();

      // --- Step 5: Verify previously saved draft is still intact after rejections ---
      const draftCheck = await request(`/api/cases/${caseId}/report`, { method: 'GET' });
      expect(draftCheck.res.status).toBe(200);
      const draftBody = draftCheck.body?.report || draftCheck.body;
      expect(draftBody).toBeTruthy();
      expect(draftBody.suspectId || draftBody.suspect).toBeTruthy();
      // The reasoning from the valid draft should still be there
      const savedReasoning = draftBody.reasoning || draftBody.logic || '';
      expect(savedReasoning.length).toBeGreaterThan(0);
      expect(savedReasoning).not.toBe('   ');

      // --- Step 6: Normal short keyword search still works ---
      const search = await request(`/api/cases/${caseId}/evidences?keyword=短&category=weapon`);
      expect(search.res.status).toBe(200);
      const items = search.body?.items || search.body;
      expect(Array.isArray(items)).toBe(true);
      expect(items.length).toBeGreaterThan(0);
      expect(items.some((x) => x.id === 'clue_knife' || x.title === '短刀')).toBe(true);
      // All results should be of the filtered category
      for (const item of items) {
        if (item.category) {
          expect(item.category).toBe('weapon');
        }
      }

      // --- Step 7: Very long search string should not crash and not break subsequent search ---
      const longKeyword = '测'.repeat(5000);
      const longSearch = await request(`/api/cases/${caseId}/evidences?keyword=${encodeURIComponent(longKeyword)}`);
      expect([200, 400, 414]).toContain(longSearch.res.status);

      // --- Step 8: Special characters in search should not crash ---
      const specialSearch = await request(`/api/cases/${caseId}/evidences?keyword=${encodeURIComponent("'; DROP TABLE--")}`);
      expect([200, 400]).toContain(specialSearch.res.status);

      // --- Step 9: Verify normal search still works after edge-case searches ---
      const searchAfter = await request(`/api/cases/${caseId}/evidences?keyword=便签`);
      expect(searchAfter.res.status).toBe(200);
      const itemsAfter = searchAfter.body?.items || searchAfter.body;
      expect(Array.isArray(itemsAfter)).toBe(true);
      expect(itemsAfter.some((x) => x.id === 'clue_note' || x.title === '便签纸')).toBe(true);

    } finally {
      await request(`/api/cases/${caseId}`, { method: 'DELETE' }).catch(() => {});
    }
  });
});

