describe('case_report_validation_rejects_invalid_logic_and_evidence_selection', () => {
  let sessionId;
  let clueIds = [];

  beforeAll(async () => {
    // Create session
    const { res: createRes, body: createBody } = await request('/api/cases', {
      method: 'POST',
      body: JSON.stringify({ title: `verifier-report-${Date.now()}` }),
    });
    expect([200, 201]).toContain(createRes.status);
    sessionId = createBody.id || createBody.caseId || createBody.sessionId;
    expect(sessionId, `Expected session/case id, got ${JSON.stringify(createBody)}`).toBeTruthy();

    // Create 4 clues for testing
    clueIds = [];
    for (const name of ['Report Clue 1', 'Report Clue 2', 'Report Clue 3', 'Report Clue 4']) {
      const { res, body } = await request(`/api/cases/${sessionId}/evidences`, {
        method: 'POST',
        body: JSON.stringify({ name, title: name, summary: `${name} summary`, category: 'evidence' }),
      });
      expect([200, 201]).toContain(res.status);
      clueIds.push(body.id || body.clueId || body.evidenceId);
    }

    // Save a valid draft as baseline
    await request(`/api/cases/${sessionId}/report`, {
      method: 'POST',
      body: JSON.stringify({
        suspectId: 'alice',
        conclusion: 'Draft conclusion should persist',
        logic: 'Valid initial logic',
        reasoning: 'Valid initial logic',
        evidenceIds: [clueIds[0]],
        keyEvidence: [clueIds[0]],
        status: 'draft',
      }),
    });
  });

  afterAll(async () => {
    if (sessionId) {
      await cleanup(`/api/cases/${sessionId}`);
    }
  });

  it('should reject empty logic', async () => {
    const { res, body } = await request(`/api/cases/${sessionId}/report`, {
      method: 'POST',
      body: JSON.stringify({
        suspectId: 'alice',
        conclusion: 'Draft conclusion should persist',
        logic: '',
        reasoning: '',
        keyEvidence: [clueIds[0]],
        status: 'final',
      }),
    });
    expect([400, 422]).toContain(res.status);
    expect(body).toBeTruthy();
    const msg = (body.message || body.reason || body.error || JSON.stringify(body)).toLowerCase();
    expect(msg).toMatch(/logic|reasoning|作案|逻辑|empty|空/);
  });

  it('should reject whitespace-only logic', async () => {
    const { res, body } = await request(`/api/cases/${sessionId}/report`, {
      method: 'POST',
      body: JSON.stringify({
        suspectId: 'alice',
        conclusion: 'Draft conclusion should persist',
        logic: '   ',
        reasoning: '   ',
        keyEvidence: [clueIds[0]],
        status: 'final',
      }),
    });
    expect([400, 422]).toContain(res.status);
    expect(body).toBeTruthy();
    const msg = (body.message || body.reason || body.error || JSON.stringify(body)).toLowerCase();
    expect(msg).toMatch(/logic|reasoning|作案|逻辑|空|whitespace|blank|empty/);
  });

  it('should reject overlong logic text', async () => {
    const { res, body } = await request(`/api/cases/${sessionId}/report`, {
      method: 'POST',
      body: JSON.stringify({
        suspectId: 'alice',
        conclusion: 'Draft conclusion should persist',
        logic: 'x'.repeat(10001),
        reasoning: 'x'.repeat(10001),
        keyEvidence: [clueIds[0]],
        status: 'final',
      }),
    });
    expect([400, 422]).toContain(res.status);
    expect(body).toBeTruthy();
    const msg = (body.message || body.reason || body.error || JSON.stringify(body)).toLowerCase();
    expect(msg).toMatch(/long|length|limit|exceed|超|过长|上限|max/);
  });

  it('should reject when keyEvidence is empty (less than 1)', async () => {
    const { res, body } = await request(`/api/cases/${sessionId}/report`, {
      method: 'POST',
      body: JSON.stringify({
        suspectId: 'alice',
        conclusion: 'Draft conclusion should persist',
        logic: 'Valid logic here',
        reasoning: 'Valid logic here',
        evidenceIds: [clueIds[0]],
        keyEvidence: [],
        status: 'final',
      }),
    });
    expect([400, 422]).toContain(res.status);
    expect(body).toBeTruthy();
    const msg = (body.message || body.reason || body.error || JSON.stringify(body)).toLowerCase();
    expect(msg).toMatch(/evidence|依据|关键|key|least|少/);
  });

  it('should reject duplicate keyEvidence selections', async () => {
    const { res, body } = await request(`/api/cases/${sessionId}/report`, {
      method: 'POST',
      body: JSON.stringify({
        suspectId: 'alice',
        conclusion: 'Draft conclusion should persist',
        logic: 'Valid logic here',
        reasoning: 'Valid logic here',
        keyEvidence: [clueIds[0], clueIds[0]],
        status: 'final',
      }),
    });
    expect([400, 422]).toContain(res.status);
    expect(body).toBeTruthy();
    const msg = (body.message || body.reason || body.error || JSON.stringify(body)).toLowerCase();
    expect(msg).toMatch(/duplicate|重复|repeat|same/);
  });

  it('should reject more than 3 keyEvidence selections', async () => {
    const { res, body } = await request(`/api/cases/${sessionId}/report`, {
      method: 'POST',
      body: JSON.stringify({
        suspectId: 'alice',
        conclusion: 'Draft conclusion should persist',
        logic: 'Valid logic here',
        reasoning: 'Valid logic here',
        keyEvidence: clueIds.slice(0, 4),
        status: 'final',
      }),
    });
    expect([400, 422]).toContain(res.status);
    expect(body).toBeTruthy();
    const msg = (body.message || body.reason || body.error || JSON.stringify(body)).toLowerCase();
    expect(msg).toMatch(/3|three|exceed|超|上限|too many|max/);
  });

  it('should preserve previously saved draft fields after invalid submission attempts', async () => {
    // After all the failed submissions above, the draft should still be intact
    const draftCheck = await request(`/api/cases/${sessionId}/report`, { method: 'GET' });
    expect(draftCheck.res.status).toBe(200);
    expect(draftCheck.body, 'Expected draft body to exist').toBeTruthy();

    const draft = draftCheck.body.draft || draftCheck.body.report || draftCheck.body;
    // The baseline draft we saved should still have its fields preserved
    const hasSuspectId = draft.suspectId === 'alice';
    const hasConclusion = draft.conclusion === 'Draft conclusion should persist';
    const hasLogic = (draft.logic || draft.reasoning || '').includes('Valid initial logic');
    expect(
      hasSuspectId || hasConclusion || hasLogic,
      `Expected draft fields to be preserved after invalid submissions, got ${JSON.stringify(draft)}`
    ).toBe(true);
  });

  it('should also reject whitespace-only logic for draft saves', async () => {
    const { res, body } = await request(`/api/cases/${sessionId}/report`, {
      method: 'POST',
      body: JSON.stringify({
        suspectId: 'bob',
        logic: '   ',
        reasoning: '   ',
        keyEvidence: [clueIds[0]],
        status: 'draft',
      }),
    });

    // Draft saves may or may not enforce the same validation;
    // but final submission definitely should reject it
    if ([400, 422].includes(res.status)) {
      // Draft also rejects whitespace - good
      expect(body).toBeTruthy();
    } else {
      // At minimum, final submission must reject
      const finalRes = await request(`/api/cases/${sessionId}/report`, {
        method: 'POST',
        body: JSON.stringify({
          suspectId: 'bob',
          logic: '   ',
          reasoning: '   ',
          keyEvidence: [clueIds[0]],
          status: 'final',
        }),
      });
      expect([400, 422]).toContain(finalRes.res.status);
    }
  });
});

