describe('legacy_save_import_migrates_structure_without_generating_new_progress', () => {
  it('should import legacy save, migrate structure with default category, keep chapter 2 locked, and avoid generating new progress', async () => {
    const cleanupPaths = [];
    const legacySave = {
      version: 1,
      playerId: `test-player-${Date.now()}`,
      caseId: `case-${Date.now()}`,
      chapters: {
        chapter1: {
          unlocked: true,
          completed: false,
          evidence: [
            { id: 'legacy-evi-1', name: 'Bloody Note', obtainedAt: new Date().toISOString() },
            { id: 'legacy-evi-2', name: 'Broken Watch', obtainedAt: new Date().toISOString() }
          ],
          dialogues: [
            { npcId: 'npc-old-1', lineId: 'line-1', text: 'I saw someone run away.' }
          ]
        }
      }
    };

    try {
      // Import legacy save
      const importResp = await request('/api/saves/import', {
        method: 'POST',
        body: JSON.stringify(legacySave)
      });

      expect([200, 201]).toContain(importResp.res.status);
      expect(importResp.body).toBeTruthy();
      const saveId = importResp.body.id || importResp.body.saveId;
      expect(saveId, `Expected imported save to have an id, got ${JSON.stringify(importResp.body)}`).toBeTruthy();
      cleanupPaths.push(`/api/saves/${saveId}`);

      // Fetch the imported & migrated save
      const getResp = await request(`/api/saves/${saveId}`, { method: 'GET' });
      expect(getResp.res.status).toBe(200);
      expect(getResp.body).toBeTruthy();

      const save = getResp.body.save || getResp.body;

      // --- Evidence should be preserved with default category ---
      const evidence = save.evidence
        || save.caseData?.evidence
        || (Array.isArray(save.chapters) ? save.chapters[0]?.evidence : null)
        || save.chapters?.chapter1?.evidence;
      expect(evidence, 'Migrated save must contain evidence field').toBeTruthy();
      expect(Array.isArray(evidence)).toBe(true);
      expect(evidence.length).toBe(2);
      expect(evidence.some(e => e.id === 'legacy-evi-1')).toBe(true);
      expect(evidence.some(e => e.id === 'legacy-evi-2')).toBe(true);

      // All legacy evidence should have the SAME default category (proving auto-categorization)
      const categories = evidence.map(e => e.category || e.group);
      for (const cat of categories) {
        expect(cat, 'Each legacy evidence item must have a category assigned after migration').toBeTruthy();
        expect(typeof cat).toBe('string');
        expect(cat.length).toBeGreaterThan(0);
      }
      // All old evidence should fall into the same default category
      expect(categories[0]).toBe(categories[1]);

      // --- Dialogues should be preserved ---
      const dialogues = save.dialogues
        || save.caseData?.dialogues
        || (Array.isArray(save.chapters) ? save.chapters[0]?.dialogues : null)
        || save.chapters?.chapter1?.dialogues;
      expect(dialogues, 'Migrated save must contain dialogues field').toBeTruthy();
      expect(Array.isArray(dialogues)).toBe(true);
      expect(dialogues.length).toBe(1);
      expect(dialogues[0].npcId).toBe('npc-old-1');

      // --- Reasoning must NOT be auto-generated ---
      const reasoning = save.reasoning
        || save.caseData?.reasoning
        || (Array.isArray(save.chapters) ? save.chapters[0]?.reasoning : null)
        || save.chapters?.chapter1?.reasoning;
      if (reasoning !== undefined && reasoning !== null) {
        expect(Array.isArray(reasoning)).toBe(true);
        expect(reasoning.length, 'Legacy import must not auto-generate reasoning').toBe(0);
      }

      // --- Timeline must NOT be auto-generated ---
      const timeline = save.timeline
        || save.caseData?.timeline
        || (Array.isArray(save.chapters) ? save.chapters[0]?.timeline : null)
        || save.chapters?.chapter1?.timeline;
      if (timeline !== undefined && timeline !== null) {
        expect(Array.isArray(timeline)).toBe(true);
        expect(timeline.length, 'Legacy import must not auto-generate timeline entries').toBe(0);
      }

      // --- Suspect assessment must NOT be auto-generated ---
      const suspects = save.suspects
        || save.caseData?.suspects
        || save.suspectAssessment
        || (Array.isArray(save.chapters) ? save.chapters[0]?.suspects : null);
      if (suspects !== undefined && suspects !== null) {
        expect(Array.isArray(suspects)).toBe(true);
        expect(suspects.length, 'Legacy import must not auto-generate suspect assessments').toBe(0);
      }

      // --- Closure / case result must NOT be auto-generated ---
      const closure = save.closure || save.caseClosure || save.caseData?.closure || save.report;
      if (closure !== undefined && closure !== null) {
        const closureStatus = closure.status || '';
        // Must be absent, not_started, or empty — never final/closed/completed
        expect(closureStatus).not.toMatch(/final|closed|completed|submitted/i);
        // Explicitly check it's an initial state or empty
        if (closureStatus) {
          expect(closureStatus).toMatch(/^(not_started|draft|)$/i);
        }
      }

      // --- Chapter 2 must exist and be locked ---
      const chapter2 = save.chapters?.chapter2
        || (Array.isArray(save.chapters) ? save.chapters.find(c => c.chapterNumber === 2 || c.number === 2) : null)
        || save.progress?.chapter2;

      expect(chapter2, 'After importing a chapter-1-only legacy save, chapter 2 should be present in the response (in locked state)').toBeTruthy();
      const ch2Unlocked = chapter2.unlocked;
      const ch2Status = chapter2.status;
      const isLocked = ch2Unlocked === false || ch2Status === 'locked' || ch2Status === 'not_started';
      expect(isLocked, `Chapter 2 must be locked after legacy import, got unlocked=${ch2Unlocked}, status=${ch2Status}`).toBe(true);

      // --- Verify migrated data is actually usable by querying sub-endpoints ---
      // Evidence list should be queryable
      const evidenceList = await request(`/api/saves/${saveId}/details/evidence/legacy-evi-1`, { method: 'GET' });
      if (evidenceList.res.status === 200) {
        expect(evidenceList.body).toBeTruthy();
        expect(evidenceList.body.id).toBe('legacy-evi-1');
        const name = evidenceList.body.name || evidenceList.body.title;
        expect(name).toBe('Bloody Note');
      }

      // --- Pinned field should default to false for legacy evidence ---
      for (const e of evidence) {
        const pinned = e.pinned;
        if (pinned !== undefined) {
          expect(pinned, `Legacy evidence ${e.id} should default to not pinned`).toBe(false);
        }
      }
    } finally {
      await cleanup(cleanupPaths);
    }
  });
});

import { describe, it, expect, beforeAll, afterAll } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function request(path, options = {}) {
  const res = await fetch(`${BASE_URL}${path}`, {
    headers: {
      'Content-Type': 'application/json',
      ...(options.headers || {}),
    },
    ...options,
  });

  const text = await res.text();
  let body;
  try {
    body = text ? JSON.parse(text) : null;
  } catch {
    body = text;
  }

  return { res, body };
}

async function safeCleanup(paths) {
  for (const path of paths) {
    try {
      await fetch(`${BASE_URL}${path}`, { method: 'DELETE' });
    } catch {
      // ignore cleanup failures
    }
  }
}

