      ? boardPreview.body
      : boardPreview.body.items || boardPreview.body.evidence || [];

    expect(Array.isArray(boardItems), `expected evidence board to return array data, got ${JSON.stringify(boardPreview.body)}`).toBe(true);
    const boardRecord = boardItems.find((item) => (item.id || item.evidenceId) === evidenceId || (item.objectId || item.sourceObjectId) === objectId);
    expect(boardRecord, `expected collected evidence to appear in evidence board preview, got ${JSON.stringify(boardItems)}`).toBeTruthy();
