describe('round16_highlighted_clues_shared_state', () => {
  it('allows up to 6 highlighted clues, rejects over-limit with clear message, reflects in evidences/report/reasoning, supports unmark with sync, and handles old saves without highlights', async () => {
    const created = await request('/api/cases', {
      method: 'POST',
      body: JSON.stringify({ title: `verifier-round16-${Date.now()}` }),
    });
    expect([200, 201]).toContain(created.res.status);
    const caseId = created.body.id ?? created.body.caseId;
    expect(caseId).toBeTruthy();

    try {
      // Create 7 clues so we can test the limit properly
      const clueIds = Array.from({ length: 7 }, (_, i) => `clue_hl_${i + 1}`);
      for (const id of clueIds) {
        const createClue = await request(`/api/cases/${caseId}/evidences`, {
          method: 'POST',
          body: JSON.stringify({ id, title: `Evidence ${id}`, category: 'general' }),
        });
        expect([200, 201]).toContain(createClue.res.status);
      }

      // --- Highlight exactly 6 clues (the maximum) ---
      const sixClueIds = clueIds.slice(0, 6);
      const highlight = await request(`/api/cases/${caseId}/highlights`, {
        method: 'POST',
        body: JSON.stringify({ clueIds: sixClueIds }),
      });
      expect([200, 201]).toContain(highlight.res.status);
      expect(highlight.body).toBeTruthy();
      const highlighted = highlight.body.clueIds || highlight.body.items || highlight.body.highlights || [];
      expect(Array.isArray(highlighted)).toBe(true);
      expect(highlighted).toHaveLength(6);

      // --- Attempt to highlight 7 (over-limit) => should fail with explicit message ---
      const overLimit = await request(`/api/cases/${caseId}/highlights`, {
        method: 'POST',
        body: JSON.stringify({ clueIds: clueIds }), // all 7
      });
      expect([400, 422]).toContain(overLimit.res.status);
      const overLimitMsg = (overLimit.body?.message || overLimit.body?.error || JSON.stringify(overLimit.body || '')).toLowerCase();
      expect(overLimitMsg.length).toBeGreaterThan(0);
      // Error message should mention the limit (6, limit, maximum, 上限)
      const mentionsLimit = overLimitMsg.includes('6') || overLimitMsg.includes('limit') || overLimitMsg.includes('maximum') || overLimitMsg.includes('上限') || overLimitMsg.includes('max');
      expect(mentionsLimit, `Over-limit error message should mention the limit of 6, got: ${overLimitMsg}`).toBe(true);

      // --- Verify highlighted clues are visible in evidences endpoint (the unified investigation panel) ---
      const evidencesResp = await request(`/api/cases/${caseId}/evidences`);
      expect(evidencesResp.res.status).toBe(200);
      const evidences = evidencesResp.body?.items || evidencesResp.body?.evidences || evidencesResp.body || [];
      const highlightedEvidence = evidences.filter(
        (e) => e.highlighted === true || e.isHighlighted === true || e.important === true
      );
      expect(highlightedEvidence.length, 'Evidences endpoint should reflect 6 highlight marks').toBe(6);

      // --- Verify highlighted clues are visible in report context ---
      const reportState = await request(`/api/cases/${caseId}/report`);
      if (reportState.res.status === 200 && reportState.body) {
        const reportHighlights = reportState.body.highlightedClues || reportState.body.highlights || reportState.body.keyClues || [];
        if (Array.isArray(reportHighlights)) {
          expect(reportHighlights.length, 'Report should expose highlighted clues').toBeGreaterThanOrEqual(1);
        }
      }

      // --- Verify highlighted clues are visible in reasoning context ---
      const reasoningResp = await request(`/api/cases/${caseId}/reasoning`);
      if (reasoningResp.res.status === 200 && reasoningResp.body) {
        // The reasoning endpoint might expose available clues with highlight marks
        const reasoningClues = reasoningResp.body.availableClues || reasoningResp.body.clues || [];
        if (Array.isArray(reasoningClues) && reasoningClues.length > 0) {
          const highlightedInReasoning = reasoningClues.filter(
            (c) => c.highlighted === true || c.isHighlighted === true || c.important === true
          );
          expect(highlightedInReasoning.length, 'Reasoning context should show highlighted clues').toBeGreaterThanOrEqual(1);
        }
      }

      // --- Verify there is only one unified evidences/clues endpoint (no parallel data source) ---
      // The evidences endpoint we already checked should be the single source of truth
      // Attempting an alternative path should either not exist or return the same data
      const altResp = await request(`/api/cases/${caseId}/clues`);
      if (altResp.res.status === 200) {
        const altItems = altResp.body?.items || altResp.body?.clues || altResp.body || [];
        // If both endpoints exist, they should return the same data count
        expect(altItems.length, 'If /clues endpoint exists, it should mirror /evidences data').toBe(evidences.length);
      }
      // If 404, that's fine — only one endpoint exists

      // --- Unmark / remove highlight from one clue ---
      const clueToUnmark = sixClueIds[0];
      // Try explicit remove first
      let unmarkSuccess = false;
      const altRemove = await request(`/api/cases/${caseId}/highlights/${clueToUnmark}`, {
        method: 'DELETE',
      });
      if ([200, 204].includes(altRemove.res.status)) {
        unmarkSuccess = true;
      } else {
        // Try updating highlights with 5 clues
        const remainingHighlights = sixClueIds.slice(1);
        const unhighlight = await request(`/api/cases/${caseId}/highlights`, {
          method: 'POST',
          body: JSON.stringify({ clueIds: remainingHighlights }),
        });
        if ([200, 201].includes(unhighlight.res.status)) {
          unmarkSuccess = true;
        }
      }
      expect(unmarkSuccess, 'Should be able to unmark a highlighted clue').toBe(true);

      // Verify the unmarked clue is no longer highlighted in the highlights endpoint
      const highlightsAfterUnmark = await request(`/api/cases/${caseId}/highlights`);
      if (highlightsAfterUnmark.res.status === 200) {
        const currentHighlights = highlightsAfterUnmark.body?.clueIds || highlightsAfterUnmark.body?.items || highlightsAfterUnmark.body?.highlights || [];
        const stillHasUnmarked = currentHighlights.some(
          (item) => (typeof item === 'string' ? item : item.id || item.clueId) === clueToUnmark
        );
        expect(stillHasUnmarked, `Clue ${clueToUnmark} should no longer be highlighted after unmark`).toBe(false);
      }

      // Verify the unmarked clue is also no longer highlighted in the evidences endpoint (sync)
      const evidencesAfterUnmark = await request(`/api/cases/${caseId}/evidences`);
      expect(evidencesAfterUnmark.res.status).toBe(200);
      const evidencesListAfter = evidencesAfterUnmark.body?.items || evidencesAfterUnmark.body?.evidences || evidencesAfterUnmark.body || [];
      const unmarkedInEvidence = evidencesListAfter.find((e) => (e.id || e.clueId) === clueToUnmark);
      if (unmarkedInEvidence) {
        expect(
          unmarkedInEvidence.highlighted !== true && unmarkedInEvidence.isHighlighted !== true && unmarkedInEvidence.important !== true,
          `Clue ${clueToUnmark} should not be highlighted in evidences after unmark`
        ).toBe(true);
      }
      // Remaining highlighted should be 5
      const stillHighlighted = evidencesListAfter.filter(
        (e) => e.highlighted === true || e.isHighlighted === true || e.important === true
      );
      expect(stillHighlighted.length, 'After unmarking one, 5 should remain highlighted').toBe(5);

      // Verify report also reflects the change
      const reportAfterUnmark = await request(`/api/cases/${caseId}/report`);
      if (reportAfterUnmark.res.status === 200 && reportAfterUnmark.body) {
        const reportHlAfter = reportAfterUnmark.body.highlightedClues || reportAfterUnmark.body.highlights || reportAfterUnmark.body.keyClues || [];
        if (Array.isArray(reportHlAfter)) {
          const unmarkedInReport = reportHlAfter.some(
            (item) => (typeof item === 'string' ? item : item.id || item.clueId) === clueToUnmark
          );
          expect(unmarkedInReport, `Clue ${clueToUnmark} should not be in report highlights after unmark`).toBe(false);
        }
      }

      // --- Old save without highlights should import cleanly ---
      const oldSave = {
        title: `old-save-no-highlights-${Date.now()}`,
        version: 1,
        evidence: [
          { id: 'legacy_clue_1', title: 'Legacy evidence 1', category: 'general' },
          { id: 'legacy_clue_2', title: 'Legacy evidence 2', category: 'general' },
        ],
        // No highlights field at all
      };
      const importResp = await request(`/api/cases/import`, {
        method: 'POST',
        body: JSON.stringify(oldSave),
      });
      expect([200, 201]).toContain(importResp.res.status);
      const importedCaseId = importResp.body?.id ?? importResp.body?.caseId;
      expect(importedCaseId).toBeTruthy();

      try {
        // Verify imported case has no highlights by default
        const importedHighlights = await request(`/api/cases/${importedCaseId}/highlights`);
        if (importedHighlights.res.status === 200) {
          const importedHl = importedHighlights.body?.clueIds || importedHighlights.body?.items || importedHighlights.body?.highlights || [];
          expect(importedHl.length, 'Old save without highlights should default to no highlights').toBe(0);
        }

        // Verify the imported evidence is accessible and none are highlighted
        const importedEvidence = await request(`/api/cases/${importedCaseId}/evidences`);
        expect(importedEvidence.res.status).toBe(200);
        const importedEvidenceItems = importedEvidence.body?.items || importedEvidence.body?.evidences || importedEvidence.body || [];
        expect(importedEvidenceItems.length).toBeGreaterThanOrEqual(1);
        for (const e of importedEvidenceItems) {
          const isHl = e.highlighted === true || e.isHighlighted === true || e.important === true;
          expect(isHl, `Legacy evidence ${e.id} should not be highlighted by default`).toBe(false);
        }
      } finally {
        await safeDelete(`/api/cases/${importedCaseId}`);
      }
    } finally {
      await safeDelete(`/api/cases/${caseId}`);
    }
  });
});

import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function request(path, options = {}) {
  const res = await fetch(`${BASE_URL}${path}`, {
    headers: {
      'Content-Type': 'application/json',
      ...(options.headers || {}),
    },
    ...options,
  });
  const text = await res.text();
  let body = null;
  try {
    body = text ? JSON.parse(text) : null;
  } catch {
    body = text;
  }
  return { res, body };
}

async function cleanup(paths) {
  for (const path of paths) {
    try {
      await fetch(`${BASE_URL}${path}`, { method: 'DELETE' });
    } catch {}
  }
}

// Helper: try multiple endpoint patterns and return first success
async function tryEndpoints(paths, options = {}) {
  for (const path of paths) {
    try {
      const result = await request(path, options);
      if ([200, 201].includes(result.res.status)) return { ...result, usedPath: path };
    } catch {}
  }
  // Return last attempt
  return request(paths[paths.length - 1], options);
}

async function createSession(suffix) {
  const paths = [
    { path: '/api/sessions', body: { name: `timeline-${suffix}` } },
    { path: '/api/cases', body: { title: `timeline-${suffix}` } },
    { path: '/api/game/sessions', body: { name: `timeline-${suffix}` } },
  ];
  for (const p of paths) {
    try {
      const result = await request(p.path, {
        method: 'POST',
        body: JSON.stringify(p.body),
      });
      if ([200, 201].includes(result.res.status)) {
        const id = result.body?.id || result.body?.sessionId || result.body?.caseId;
        if (id) {
          const prefix = p.path.replace(/\/$/, '');
          return { id, prefix: `${prefix}/${id}`, cleanupPath: `${prefix}/${id}` };
        }
      }
    } catch {}
  }
  throw new Error('Could not create session/case via any known endpoint');
}

async function collectEvidence(prefix, evidenceId, name) {
  const paths = [
    { path: `${prefix}/evidence/collect`, body: { areaId: 'street', objectId: `obj-${evidenceId}`, evidenceId, name } },
    { path: `${prefix}/evidence`, body: { id: evidenceId, name, category: 'physical' } },
    { path: `${prefix}/evidences`, body: { id: evidenceId, title: name, category: 'physical' } },
    { path: `${prefix}/clues`, body: { id: evidenceId, name, type: 'evidence' } },
  ];
  for (const p of paths) {
    try {
      const result = await request(p.path, { method: 'POST', body: JSON.stringify(p.body) });
      if ([200, 201].includes(result.res.status)) return result;
    } catch {}
  }
  throw new Error(`Could not collect evidence ${evidenceId}`);
}

async function createReasoning(prefix, clueIds, conclusion) {
  const paths = [
    { path: `${prefix}/reasoning`, body: { clueIds, conclusion } },
    { path: `${prefix}/deductions`, body: { clueIds, conclusion } },
    { path: `${prefix}/reasoning/create`, body: { clueIds, conclusion } },
  ];
  for (const p of paths) {
    try {
      const result = await request(p.path, { method: 'POST', body: JSON.stringify(p.body) });
      if ([200, 201].includes(result.res.status)) return result;
    } catch {}
  }
  throw new Error('Could not create reasoning');
}

async function getTimeline(prefix) {
  const paths = [`${prefix}/timeline`, `${prefix}/timelines`];
  for (const p of paths) {
    try {
      const result = await request(p, { method: 'GET' });
      if (result.res.status === 200) return result;
    } catch {}
  }
  return request(`${prefix}/timeline`, { method: 'GET' });
}

async function addToTimeline(prefix, clueId, stage) {
  const paths = [
    { path: `${prefix}/timeline`, body: { clueId, stage } },
    { path: `${prefix}/timeline/events`, body: { clueId, stage } },
    { path: `${prefix}/timeline/add`, body: { clueId, stage } },
  ];
  for (const p of paths) {
    try {
      const result = await request(p.path, { method: 'POST', body: JSON.stringify(p.body) });
      if ([200, 201].includes(result.res.status)) return result;
    } catch {}
  }
  return request(`${prefix}/timeline`, { method: 'POST', body: JSON.stringify({ clueId, stage }) });
}

async function removeFromTimeline(prefix, clueId, stage) {
  const paths = [
    { path: `${prefix}/timeline`, method: 'DELETE', body: { clueId, stage } },
    { path: `${prefix}/timeline/events`, method: 'DELETE', body: { clueId, stage } },
    { path: `${prefix}/timeline/remove`, method: 'POST', body: { clueId, stage } },
  ];
  for (const p of paths) {
    try {
      const result = await request(p.path, { method: p.method, body: JSON.stringify(p.body) });
      if ([200, 204].includes(result.res.status)) return result;
    } catch {}
  }
  return request(`${prefix}/timeline`, { method: 'DELETE', body: JSON.stringify({ clueId, stage }) });
}

async function getReasoning(prefix, reasoningId) {
  const paths = [
    `${prefix}/reasoning/${reasoningId}`,
    `${prefix}/deductions/${reasoningId}`,
  ];
  for (const p of paths) {
    try {
      const result = await request(p, { method: 'GET' });
      if (result.res.status === 200) return result;
    } catch {}
  }
  return request(`${prefix}/reasoning/${reasoningId}`, { method: 'GET' });
}

function extractTimelineItems(body) {
  return body?.items || body?.timeline || body?.events || body?.stages?.flatMap(s => s.events || s.items || []) || [];
}

function hasConflictFlag(item) {
  if (!item) return false;
  if (item.conflicted === true || item.hasConflict === true || item.contradicted === true || item.timelineConflict === true) return true;
  const status = String(item.status || '').toLowerCase();
  if (status.includes('conflict') || status.includes('contradict')) return true;
  const warnings = item.warnings || item.conflicts || [];
  if (Array.isArray(warnings) && warnings.length > 0) return true;
  return false;
}

describe('round6_timeline_and_reasoning_conflict', () => {
  it('should show explicit guidance when timeline is empty', async () => {
    const suffix = Date.now();
    const cleanupPaths = [];

    try {
      const session = await createSession(suffix);
      cleanupPaths.push(session.cleanupPath);

      const emptyTimeline = await getTimeline(session.prefix);
      expect(emptyTimeline.res.status).toBe(200);
      const tlBody = emptyTimeline.body;
      const items = extractTimelineItems(tlBody);

      // Timeline should be empty
      expect(items.length).toBe(0);

      // Must have explicit guidance content, not just an empty list
      const guidanceText = tlBody?.guidance || tlBody?.emptyMessage || tlBody?.hint || tlBody?.message || '';
      const hasExplicitGuidance = typeof guidanceText === 'string' && guidanceText.trim().length > 0;
      const hasGuidanceFlag = tlBody?.showGuidance === true || tlBody?.isEmpty === true;
      expect(
        hasExplicitGuidance || hasGuidanceFlag,
        `expected empty timeline to contain explicit guidance text or flag, got ${JSON.stringify(tlBody)}`
      ).toBe(true);
    } finally {
      await cleanup(cleanupPaths);
    }
  });

  it('should prevent same-clue same-stage duplicates but allow cross-stage placement', async () => {
    const suffix = Date.now();
    const cleanupPaths = [];

    try {
      const session = await createSession(suffix);
      cleanupPaths.push(session.cleanupPath);

      const clueId = `dup-test-${suffix}`;
      await collectEvidence(session.prefix, clueId, 'Duplicate test evidence');

      // Add clue to 'before' stage
      const add1 = await addToTimeline(session.prefix, clueId, 'before');
      expect([200, 201]).toContain(add1.res.status);

      // Attempt same clue in same stage again - should be rejected or flagged
      const addDup = await addToTimeline(session.prefix, clueId, 'before');
      const dupRejected = [400, 409, 422].includes(addDup.res.status) ||
        (addDup.res.status === 200 && (addDup.body?.duplicate === true || addDup.body?.added === false || addDup.body?.alreadyExists === true));
      expect(dupRejected, `expected duplicate same-stage placement to be prevented, got status ${addDup.res.status} body ${JSON.stringify(addDup.body)}`).toBe(true);

      // Verify only one entry in 'before' for this clue
      const list = await getTimeline(session.prefix);
      expect(list.res.status).toBe(200);
      const allItems = extractTimelineItems(list.body);
      const beforeEntries = allItems.filter(i =>
        (i.stage === 'before' || i.phase === 'before') &&
        (i.clueId === clueId || i.id === clueId || i.evidenceId === clueId)
      );
      expect(beforeEntries.length, `expected clue to appear exactly once in same stage`).toBe(1);

      // Same clue CAN be added to a different stage (allowed per requirement)
      const addDiffStage = await addToTimeline(session.prefix, clueId, 'after');
      expect([200, 201]).toContain(addDiffStage.res.status);

      // Verify clue appears in both stages
      const list2 = await getTimeline(session.prefix);
      const allItems2 = extractTimelineItems(list2.body);
      const clueEntries = allItems2.filter(i =>
        i.clueId === clueId || i.id === clueId || i.evidenceId === clueId
      );
      expect(clueEntries.length).toBeGreaterThanOrEqual(2);
    } finally {
      await cleanup(cleanupPaths);
    }
  });

  it('should surface reasoning conflict when associated clues are in contradictory stages, and clear conflict when contradiction is resolved', async () => {
    const suffix = Date.now();
    const cleanupPaths = [];

    try {
      const session = await createSession(suffix);
      cleanupPaths.push(session.cleanupPath);

      const clueA = `conflict-a-${suffix}`;
      const clueB = `conflict-b-${suffix}`;

      await collectEvidence(session.prefix, clueA, 'Evidence A - alibi proof');
      await collectEvidence(session.prefix, clueB, 'Evidence B - presence proof');

      // Create reasoning linking both clues
      const reasoning = await createReasoning(session.prefix, [clueA, clueB], 'suspect was present during crime');
      expect([200, 201]).toContain(reasoning.res.status);
      const reasoningId = reasoning.body?.id || reasoning.body?.reasoningId;
      expect(reasoningId).toBeTruthy();

      // Place clue A in 'before' (suggesting something happened before the crime)
      const addA = await addToTimeline(session.prefix, clueA, 'before');
      expect([200, 201]).toContain(addA.res.status);

      // Place clue B in 'after' (suggesting contradictory timing for same reasoning)
      // Two clues used in the same reasoning placed in conflicting stages should trigger conflict
      const addB = await addToTimeline(session.prefix, clueB, 'after');
      expect([200, 201]).toContain(addB.res.status);

      // Check reasoning for conflict indication
      const reasoningCheck = await getReasoning(session.prefix, reasoningId);
      expect(reasoningCheck.res.status).toBe(200);
      const item = reasoningCheck.body?.reasoning || reasoningCheck.body;
      expect(
        hasConflictFlag(item),
        `expected reasoning to show conflict when its clues are in contradictory timeline stages, got ${JSON.stringify(item)}`
      ).toBe(true);

      // Remove clue B from 'after' to resolve contradiction
      const remove = await removeFromTimeline(session.prefix, clueB, 'after');
      expect([200, 204]).toContain(remove.res.status);

      // Now place clue B in same stage as clue A ('before') - no more contradiction
      const addBSameStage = await addToTimeline(session.prefix, clueB, 'before');
      expect([200, 201]).toContain(addBSameStage.res.status);

      // Conflict should be cleared
      const reasoningAfter = await getReasoning(session.prefix, reasoningId);
      expect(reasoningAfter.res.status).toBe(200);
      const itemAfter = reasoningAfter.body?.reasoning || reasoningAfter.body;
      expect(
        hasConflictFlag(itemAfter),
        `expected reasoning conflict to be cleared after resolving timeline contradiction, got ${JSON.stringify(itemAfter)}`
      ).toBe(false);
    } finally {
      await cleanup(cleanupPaths);
    }
  });

  it('should maintain clear ordering when a stage has many events', async () => {
    const suffix = Date.now();
    const cleanupPaths = [];

    try {
      const session = await createSession(suffix);
      cleanupPaths.push(session.cleanupPath);

      const clueIds = [];
      // Add 6+ events to one stage
      for (let i = 0; i < 6; i++) {
        const cid = `order-${i}-${suffix}`;
        clueIds.push(cid);
        await collectEvidence(session.prefix, cid, `Event ${i} evidence`);
        const add = await addToTimeline(session.prefix, cid, 'during');
        expect([200, 201]).toContain(add.res.status);
      }

      // Fetch timeline and verify ordering is stable
      const tl1 = await getTimeline(session.prefix);
      expect(tl1.res.status).toBe(200);
      const items1 = extractTimelineItems(tl1.body).filter(i =>
        i.stage === 'during' || i.phase === 'during'
      );
      expect(items1.length).toBeGreaterThanOrEqual(6);

      // Fetch again and verify same order
      const tl2 = await getTimeline(session.prefix);
      const items2 = extractTimelineItems(tl2.body).filter(i =>
        i.stage === 'during' || i.phase === 'during'
      );

      const ids1 = items1.map(i => i.clueId || i.id || i.evidenceId);
      const ids2 = items2.map(i => i.clueId || i.id || i.evidenceId);
      expect(ids1).toEqual(ids2);
    } finally {
      await cleanup(cleanupPaths);
    }
  });
});

import { describe, it, expect, beforeAll, afterAll } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function request(path, options = {}) {
  const res = await fetch(`${BASE_URL}${path}`, {
    headers: {
      'Content-Type': 'application/json',
      ...(options.headers || {}),
    },
    ...options,
  });

  const text = await res.text();
  let body;
  try {
    body = text ? JSON.parse(text) : null;
  } catch {
    body = text;
  }

  return { res, body };
}

async function safeCleanup(paths) {
  for (const path of paths) {
    try {
      await fetch(`${BASE_URL}${path}`, { method: 'DELETE' });
    } catch {
      // ignore cleanup failures
    }
  }
}

describe('session_state_persists_without_duplicate_evidence', () => {
  const runId = `vitest-evidence-${Date.now()}-${Math.random().toString(36).slice(2)}`;
  const sessionPayload = {
    name: `Evidence Session ${runId}`,
    playerId: `player-${runId}`,
    metadata: { scope: 'verifier', verifier_case_id: 'session_state_persists_without_duplicate_evidence' }
  };

  let sessionId;
  let objectId;
  let evidenceId;

  beforeAll(async () => {
    const createSession = await request('/api/sessions', {
      method: 'POST',
      body: JSON.stringify(sessionPayload),
    });

    expect(createSession.res.status, `expected POST /api/sessions to return 200 or 201, got ${createSession.res.status} with body ${JSON.stringify(createSession.body)}`).toContain(createSession.res.status);
    expect(createSession.body).toBeTruthy();
    sessionId = createSession.body.id || createSession.body.sessionId;
    expect(sessionId, `expected created session to include id/sessionId, got ${JSON.stringify(createSession.body)}`).toBeTruthy();

    const createSceneObject = await request(`/api/sessions/${sessionId}/scene-objects`, {
      method: 'POST',
      body: JSON.stringify({
        objectKey: `bloody-knife-${runId}`,
        title: 'Bloody Knife',
        location: 'kitchen',
        inspectable: true,
        collectible: true,
      }),
    });

    expect([200, 201], `expected POST /api/sessions/${sessionId}/scene-objects to return 200 or 201, got ${createSceneObject.res.status} with body ${JSON.stringify(createSceneObject.body)}`).toContain(createSceneObject.res.status);
    objectId = createSceneObject.body.id || createSceneObject.body.objectId;
    expect(objectId, `expected created scene object to include id/objectId, got ${JSON.stringify(createSceneObject.body)}`).toBeTruthy();
  });

  afterAll(async () => {
    await safeCleanup([
      evidenceId ? `/api/sessions/${sessionId}/evidence/${evidenceId}` : '',
      objectId ? `/api/sessions/${sessionId}/scene-objects/${objectId}` : '',
      sessionId ? `/api/sessions/${sessionId}` : '',
    ].filter(Boolean));
  });

  it('should persist inspected and collected evidence state without creating duplicate evidence entries', async () => {
    const inspectRes = await request(`/api/sessions/${sessionId}/scene-objects/${objectId}/inspect`, {
      method: 'POST',
      body: JSON.stringify({ viewedAt: new Date().toISOString() }),
    });

    expect([200, 201], `expected inspect endpoint to return 200 or 201, got ${inspectRes.res.status} with body ${JSON.stringify(inspectRes.body)}`).toContain(inspectRes.res.status);
    expect(inspectRes.body).toBeTruthy();
    expect(inspectRes.body.inspected ?? inspectRes.body.viewed ?? true, `expected inspect response to indicate inspected/viewed state, got ${JSON.stringify(inspectRes.body)}`).toBeTruthy();

    const collectFirst = await request(`/api/sessions/${sessionId}/scene-objects/${objectId}/collect`, {
      method: 'POST',
      body: JSON.stringify({ collectedAt: new Date().toISOString() }),
    });

    expect([200, 201], `expected first collect to return 200 or 201, got ${collectFirst.res.status} with body ${JSON.stringify(collectFirst.body)}`).toContain(collectFirst.res.status);
    expect(collectFirst.body).toBeTruthy();
    evidenceId = collectFirst.body.evidenceId || collectFirst.body.id;
    expect(evidenceId, `expected collect response to include evidenceId/id, got ${JSON.stringify(collectFirst.body)}`).toBeTruthy();
    expect(collectFirst.body.objectId || collectFirst.body.sourceObjectId, `expected collect response to reference source object, got ${JSON.stringify(collectFirst.body)}`).toBeTruthy();

    const collectAgain = await request(`/api/sessions/${sessionId}/scene-objects/${objectId}/collect`, {
      method: 'POST',
      body: JSON.stringify({ collectedAt: new Date().toISOString() }),
    });

    expect([200, 201, 409], `expected duplicate collect to return 200/201(idempotent) or 409(conflict), got ${collectAgain.res.status} with body ${JSON.stringify(collectAgain.body)}`).toContain(collectAgain.res.status);
    if (collectAgain.res.status !== 409) {
      const duplicateEvidenceId = collectAgain.body?.evidenceId || collectAgain.body?.id;
      expect(duplicateEvidenceId, `expected duplicate collect response to still reference evidence id, got ${JSON.stringify(collectAgain.body)}`).toBeTruthy();
      expect(duplicateEvidenceId).toBe(evidenceId);
    }

    const boardBeforeRefresh = await request(`/api/sessions/${sessionId}/evidence-board`, { method: 'GET' });
    expect(boardBeforeRefresh.res.status, `expected GET evidence board to return 200, got ${boardBeforeRefresh.res.status} with body ${JSON.stringify(boardBeforeRefresh.body)}`).toBe(200);
    expect(boardBeforeRefresh.body).toBeTruthy();

    const evidenceListBefore = Array.isArray(boardBeforeRefresh.body)
      ? boardBeforeRefresh.body
      : boardBeforeRefresh.body.items || boardBeforeRefresh.body.evidence || [];

    expect(Array.isArray(evidenceListBefore), `expected evidence board response to contain an array, got ${JSON.stringify(boardBeforeRefresh.body)}`).toBe(true);

    const matchingBefore = evidenceListBefore.filter((item) => {
      const itemEvidenceId = item.id || item.evidenceId;
      const itemObjectId = item.objectId || item.sourceObjectId;
      return itemEvidenceId === evidenceId || itemObjectId === objectId;
    });

    expect(matchingBefore.length, `expected exactly 1 evidence entry for collected object before refresh, got ${matchingBefore.length} from ${JSON.stringify(evidenceListBefore)}`).toBe(1);

    const sessionReload = await request(`/api/sessions/${sessionId}`, { method: 'GET' });
    expect(sessionReload.res.status, `expected GET /api/sessions/${sessionId} to return 200, got ${sessionReload.res.status} with body ${JSON.stringify(sessionReload.body)}`).toBe(200);
    expect(sessionReload.body).toBeTruthy();

    const objectState = await request(`/api/sessions/${sessionId}/scene-objects/${objectId}`, { method: 'GET' });
    expect(objectState.res.status, `expected GET scene object to return 200, got ${objectState.res.status} with body ${JSON.stringify(objectState.body)}`).toBe(200);
    expect(objectState.body).toBeTruthy();
    expect(objectState.body.inspected ?? objectState.body.viewed, `expected scene object to remain inspected/viewed after reload, got ${JSON.stringify(objectState.body)}`).toBeTruthy();
    expect(objectState.body.collected ?? objectState.body.isCollected ?? true, `expected scene object to remain collected after reload, got ${JSON.stringify(objectState.body)}`).toBeTruthy();

    const boardAfterRefresh = await request(`/api/sessions/${sessionId}/evidence-board`, { method: 'GET' });
    expect(boardAfterRefresh.res.status, `expected GET evidence board after refresh to return 200, got ${boardAfterRefresh.res.status} with body ${JSON.stringify(boardAfterRefresh.body)}`).toBe(200);
    expect(boardAfterRefresh.body).toBeTruthy();

    const evidenceListAfter = Array.isArray(boardAfterRefresh.body)
      ? boardAfterRefresh.body
      : boardAfterRefresh.body.items || boardAfterRefresh.body.evidence || [];

    expect(Array.isArray(evidenceListAfter), `expected refreshed evidence board response to contain an array, got ${JSON.stringify(boardAfterRefresh.body)}`).toBe(true);

    const matchingAfter = evidenceListAfter.filter((item) => {
      const itemEvidenceId = item.id || item.evidenceId;
      const itemObjectId = item.objectId || item.sourceObjectId;
      return itemEvidenceId === evidenceId || itemObjectId === objectId;
    });

    expect(matchingAfter.length, `expected exactly 1 evidence entry for collected object after refresh, got ${matchingAfter.length} from ${JSON.stringify(evidenceListAfter)}`).toBe(1);
    expect(matchingAfter[0]).toBeTruthy();
    expect(matchingAfter[0].id || matchingAfter[0].evidenceId, `expected persisted evidence entry to retain same evidence id after refresh, got ${JSON.stringify(matchingAfter[0])}`).toBe(evidenceId);
  });
});

