describe('suspect_ranking_is_stable_and_removes_stale_judgments', () => {
  it('should keep stable ranking order on refresh and remove stale judgments when supporting clue is deleted', async () => {
    // Create case
    const { res: createRes, body: createBody } = await request('/api/cases', {
      method: 'POST',
      body: JSON.stringify({ title: `verifier-suspects-${Date.now()}` }),
    });
    expect([200, 201]).toContain(createRes.status);
    const caseId = createBody.id || createBody.caseId;
    expect(caseId).toBeTruthy();

    try {
      // Create a clue that will contribute to suspect scoring
      const { res: clueRes, body: clueBody } = await request(`/api/cases/${caseId}/evidences`, {
        method: 'POST',
        body: JSON.stringify({ name: 'Shared Motive', title: 'Shared Motive', summary: 'A clue impacting suspect scoring', category: 'evidence' }),
      });
      expect([200, 201]).toContain(clueRes.status);
      const clueId = clueBody.id || clueBody.clueId || clueBody.evidenceId;
      expect(clueId).toBeTruthy();

      // Get the list of suspects available in the case (3-5 expected per Round 8)
      const { res: suspectsListRes, body: suspectsListBody } = await request(`/api/cases/${caseId}/suspects`, { method: 'GET' });
      expect(suspectsListRes.status).toBe(200);
      const allSuspects = suspectsListBody.items || suspectsListBody.suspects || suspectsListBody || [];
      expect(Array.isArray(allSuspects)).toBe(true);
      expect(allSuspects.length, 'should have 3-5 suspects per Round 8 requirement').toBeGreaterThanOrEqual(3);

      // Add same-score suspicions for at least 3 suspects so we can test tie-breaking
      const suspectIds = allSuspects.slice(0, 3).map(s => s.suspectId || s.id);
      for (const suspectId of suspectIds) {
        const { res } = await request(`/api/cases/${caseId}/suspicions`, {
          method: 'POST',
          body: JSON.stringify({ suspectId, clueId, score: 50, scoreDelta: 10, reason: 'same-score-support' }),
        });
        expect([200, 201]).toContain(res.status);
      }

      // First ranking query
      const { res: rankRes1, body: rankBody1 } = await request(`/api/cases/${caseId}/suspects`, { method: 'GET' });
      expect(rankRes1.status).toBe(200);
      const ranking1 = rankBody1.items || rankBody1.ranking || rankBody1.suspects || rankBody1 || [];
      expect(Array.isArray(ranking1)).toBe(true);
      expect(ranking1.length).toBeGreaterThanOrEqual(3);
      const order1 = ranking1.map((s) => s.suspectId || s.id);

      // Second ranking query – order should be identical (stable tie-breaking)
      const { res: rankRes2, body: rankBody2 } = await request(`/api/cases/${caseId}/suspects`, { method: 'GET' });
      expect(rankRes2.status).toBe(200);
      const ranking2 = rankBody2.items || rankBody2.ranking || rankBody2.suspects || rankBody2 || [];
      const order2 = ranking2.map((s) => s.suspectId || s.id);
      expect(order2, 'ranking order should remain stable across refreshes when scores tie').toEqual(order1);

      // Third ranking query – triple-check stability
      const { res: rankRes3, body: rankBody3 } = await request(`/api/cases/${caseId}/suspects`, { method: 'GET' });
      expect(rankRes3.status).toBe(200);
      const ranking3 = rankBody3.items || rankBody3.ranking || rankBody3.suspects || rankBody3 || [];
      const order3 = ranking3.map((s) => s.suspectId || s.id);
      expect(order3, 'ranking order should remain stable on third query').toEqual(order1);

      // Now delete/invalidate the shared clue
      const { res: invalidateRes } = await request(`/api/cases/${caseId}/evidences/${clueId}`, {
        method: 'DELETE',
      });
      expect([200, 204]).toContain(invalidateRes.status);

      // Fetch ranking again after clue invalidation
      const { res: rankRes4, body: rankBody4 } = await request(`/api/cases/${caseId}/suspects`, { method: 'GET' });
      expect(rankRes4.status).toBe(200);
      const ranking4 = rankBody4.items || rankBody4.ranking || rankBody4.suspects || rankBody4 || [];

      // Verify each suspect's stale judgment is removed AND score reflects the change
      for (const suspectId of suspectIds) {
        const suspect = ranking4.find((s) => (s.suspectId || s.id) === suspectId);
        expect(suspect, `suspect ${suspectId} should still appear in ranking after clue invalidation`).toBeTruthy();

        // Judgments / reasons should be cleared (stale judgment removed)
        const judgments = suspect.reasons || suspect.judgments || [];
        if (Array.isArray(judgments)) {
          const staleJudgment = judgments.find(j =>
            (j.clueId === clueId) ||
            String(j.reason || j.description || '').includes('same-score-support')
          );
          expect(staleJudgment, `stale judgment referencing deleted clue should be removed from ${suspectId}`).toBeFalsy();
        }

        // Suspicion score should have decreased or be reset
        const score = suspect.suspicion ?? suspect.score ?? suspect.suspicionValue;
        if (score !== undefined && score !== null) {
          expect(score, `suspicion score for ${suspectId} should drop or reset after supporting clue removed`).toBeLessThanOrEqual(50);
        }

        // Motive/opportunity overview should reflect insufficient info or be cleared
        const motive = suspect.motive ?? suspect.motiveDescription ?? '';
        const opportunity = suspect.opportunity ?? suspect.opportunityDescription ?? '';
        const hasInsufficientIndicator = (text) => {
          if (!text || typeof text !== 'string') return true;
          const lower = text.toLowerCase();
          return lower.includes('不足') || lower.includes('insufficient') || lower.includes('unknown') || lower.length === 0;
        };
        expect(
          hasInsufficientIndicator(motive) || hasInsufficientIndicator(opportunity),
          `suspect ${suspectId} motive/opportunity should reflect stale state, got motive="${motive}", opportunity="${opportunity}"`
        ).toBe(true);
      }
    } finally {
      await cleanup(`/api/cases/${caseId}`);
    }
  });

  it('should remove stale judgments when supporting reasoning/deduction is deleted', async () => {
    // Create case
    const { res: createRes, body: createBody } = await request('/api/cases', {
      method: 'POST',
      body: JSON.stringify({ title: `verifier-suspects-reasoning-${Date.now()}` }),
    });
    expect([200, 201]).toContain(createRes.status);
    const caseId = createBody.id || createBody.caseId;
    expect(caseId).toBeTruthy();

    try {
      // Create two clues
      const clueIds = [];
      for (const name of ['Reasoning Clue A', 'Reasoning Clue B']) {
        const { res, body } = await request(`/api/cases/${caseId}/evidences`, {
          method: 'POST',
          body: JSON.stringify({ name, title: name, summary: `${name} summary`, category: 'evidence' }),
        });
        expect([200, 201]).toContain(res.status);
        clueIds.push(body.id || body.clueId || body.evidenceId);
      }

      // Create a reasoning/deduction from those clues
      let deductionId = null;
      const dedRes = await request(`/api/cases/${caseId}/deductions`, {
        method: 'POST',
        body: JSON.stringify({ clueIds, conclusion: '推理用于嫌疑评估测试' }),
      });
      if ([200, 201].includes(dedRes.res.status)) {
        deductionId = dedRes.body.id || dedRes.body.deductionId;
      } else {
        // Try alternate path
        const dedAlt = await request(`/api/cases/${caseId}/reasoning`, {
          method: 'POST',
          body: JSON.stringify({ clueIds, conclusion: '推理用于嫌疑评估测试' }),
        });
        if ([200, 201].includes(dedAlt.res.status)) {
          deductionId = dedAlt.body.id || dedAlt.body.deductionId || dedAlt.body.reasoningId;
        }
      }

      // Get suspects
      const { res: suspListRes, body: suspListBody } = await request(`/api/cases/${caseId}/suspects`, { method: 'GET' });
      expect(suspListRes.status).toBe(200);
      const allSuspects = suspListBody.items || suspListBody.suspects || suspListBody || [];
      expect(Array.isArray(allSuspects)).toBe(true);

      if (allSuspects.length > 0 && deductionId) {
        const suspectId = allSuspects[0].suspectId || allSuspects[0].id;

        // Link the deduction to a suspect's suspicion
        await request(`/api/cases/${caseId}/suspicions`, {
          method: 'POST',
          body: JSON.stringify({ suspectId, deductionId, score: 70, reason: 'reasoning-based-support' }),
        });

        // Verify suspect has the judgment
        const beforeDel = await request(`/api/cases/${caseId}/suspects`, { method: 'GET' });
        expect(beforeDel.res.status).toBe(200);

        // Now delete the deduction
        let deleteSuccess = false;
        const delRes = await request(`/api/cases/${caseId}/deductions/${deductionId}`, { method: 'DELETE' });
        if ([200, 204].includes(delRes.res.status)) {
          deleteSuccess = true;
        } else {
          const delAlt = await request(`/api/cases/${caseId}/reasoning/${deductionId}`, { method: 'DELETE' });
          if ([200, 204].includes(delAlt.res.status)) {
            deleteSuccess = true;
          }
        }

        if (deleteSuccess) {
          // Check that suspect's stale reasoning-based judgment is cleared
          const afterDel = await request(`/api/cases/${caseId}/suspects`, { method: 'GET' });
          expect(afterDel.res.status).toBe(200);
          const updatedSuspects = afterDel.body.items || afterDel.body.ranking || afterDel.body.suspects || afterDel.body || [];
          const suspect = Array.isArray(updatedSuspects) ? updatedSuspects.find(s => (s.suspectId || s.id) === suspectId) : null;
          if (suspect) {
            const judgments = suspect.reasons || suspect.judgments || [];
            if (Array.isArray(judgments)) {
              const staleJudgment = judgments.find(j =>
                (j.deductionId === deductionId) ||
                String(j.reason || j.description || '').includes('reasoning-based-support')
              );
              expect(staleJudgment, `stale judgment referencing deleted reasoning should be removed from ${suspectId}`).toBeFalsy();
            }
          }
        }
      }
    } finally {
      await cleanup(`/api/cases/${caseId}`);
    }
  });
});

import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function request(path, options = {}) {
  const res = await fetch(`${BASE_URL}${path}`, {
    headers: {
      'Content-Type': 'application/json',
      ...(options.headers || {}),
    },
    ...options,
  });
  const text = await res.text();
  let body = null;
  try {
    body = text ? JSON.parse(text) : null;
  } catch {
    body = text;
  }
  return { res, body };
}

async function tryRequest(paths, options = {}) {
  for (const path of paths) {
    try {
      const result = await request(path, options);
      if ([200, 201].includes(result.res.status)) return { ...result, usedPath: path };
      if ([400, 403, 409, 422].includes(result.res.status)) return { ...result, usedPath: path };
    } catch {}
  }
  return request(paths[0], options);
}

async function createSession(suffix) {
  const attempts = [
    { path: '/api/sessions', body: { name: `baseline-${suffix}` } },
    { path: '/api/cases', body: { title: `baseline-${suffix}` } },
    { path: '/api/game/sessions', body: { name: `baseline-${suffix}` } },
  ];
  for (const a of attempts) {
    try {
      const result = await request(a.path, { method: 'POST', body: JSON.stringify(a.body) });
      if ([200, 201].includes(result.res.status)) {
        const id = result.body?.id || result.body?.sessionId || result.body?.caseId;
        if (id) return { id, prefix: `${a.path}/${id}`, basePath: a.path };
      }
    } catch {}
  }
  throw new Error('Could not create session');
}

async function collectEvidence(prefix, evidenceId, name) {
  return tryRequest([
    `${prefix}/evidence/collect`,
    `${prefix}/evidence`,
    `${prefix}/evidences`,
    `${prefix}/clues`,
  ], {
    method: 'POST',
    body: JSON.stringify({
      areaId: 'archive', objectId: `obj-${evidenceId}`, evidenceId, id: evidenceId, name, title: name, category: 'physical'
    }),
  });
}

function extractArray(body, ...keys) {
  for (const key of keys) {
    if (body && Array.isArray(body[key])) return body[key];
  }
  if (Array.isArray(body)) return body;
  return [];
}

