import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function request(path, init = {}) {
  const res = await fetch(`${BASE_URL}${path}`, {
    headers: {
      'Content-Type': 'application/json',
      ...(init.headers || {}),
    },
    ...init,
  });

  let body = null;
  const text = await res.text();
  try {
    body = text ? JSON.parse(text) : null;
  } catch {
    body = text;
  }

  return { res, body };
}

describe('round10_report_workflow_unified', () => {
  it('supports report draft save and final submit without draft triggering formal ending', async () => {
    const casePayload = {
      title: `verifier-round10-${Date.now()}`,
      mode: 'detective',
    };

    const created = await request('/api/cases', {
      method: 'POST',
      body: JSON.stringify(casePayload),
    });

    expect([200, 201]).toContain(created.res.status);
    expect(created.body).toBeTruthy();
    expect(created.body.id ?? created.body.caseId).toBeTruthy();
    const caseId = created.body.id ?? created.body.caseId;

    try {
      // --- Save a draft report ---
      const draftPayload = {
        suspectId: 'suspect_alpha',
        reasoning: '嫌疑人利用停电时段进入书房并伪造不在场证明。',
        keyEvidence: ['clue_fingerprint', 'clue_power_outage', 'clue_fake_alibi'],
        status: 'draft',
      };

      const draft = await request(`/api/cases/${caseId}/report`, {
        method: 'POST',
        body: JSON.stringify(draftPayload),
      });

      expect([200, 201]).toContain(draft.res.status);
      expect(draft.body).toBeTruthy();
      expect(draft.body.suspectId).toBe(draftPayload.suspectId);
      expect(draft.body.reasoning).toBe(draftPayload.reasoning);
      expect(Array.isArray(draft.body.keyEvidence)).toBe(true);
      expect(draft.body.keyEvidence).toHaveLength(3);
      expect(draft.body.keyEvidence).toEqual(draftPayload.keyEvidence);
      expect(String(draft.body.status || '')).toMatch(/draft/i);

      // --- Draft should NOT trigger formal ending ---
      const stateAfterDraft = await request(`/api/cases/${caseId}`);
      expect(stateAfterDraft.res.status).toBe(200);
      expect(stateAfterDraft.body).toBeTruthy();
      const endingStatus = stateAfterDraft.body.endingStatus ?? stateAfterDraft.body.caseStatus ?? stateAfterDraft.body.reportStatus;
      expect(String(endingStatus ?? '')).not.toMatch(/final|closed|completed|ended/i);

      // Also check that no ending/result object was generated
      const endingAfterDraft = await request(`/api/cases/${caseId}/ending`);
      if (endingAfterDraft.res.status === 200 && endingAfterDraft.body) {
        const endingResult = endingAfterDraft.body.result || endingAfterDraft.body.endingType || endingAfterDraft.body.type;
        // If endpoint exists, there should be no finalized result yet
        expect(endingResult).toBeFalsy();
      }
      // If endpoint returns 404, that also means no ending was generated, which is correct

      // --- Submit final report ---
      const finalPayload = {
        suspectId: 'suspect_alpha',
        reasoning: '嫌疑人利用停电制造监控盲区，随后进入书房实施作案，并通过伪造通话记录构建虚假时间线。',
        keyEvidence: ['clue_fingerprint', 'clue_power_outage', 'clue_fake_alibi'],
        status: 'final',
      };

      const submitted = await request(`/api/cases/${caseId}/report`, {
        method: 'POST',
        body: JSON.stringify(finalPayload),
      });

      expect([200, 201]).toContain(submitted.res.status);
      expect(submitted.body).toBeTruthy();
      expect(submitted.body.suspectId).toBe(finalPayload.suspectId);
      expect(submitted.body.reasoning).toBe(finalPayload.reasoning);
      expect(submitted.body.keyEvidence).toEqual(finalPayload.keyEvidence);
      expect(String(submitted.body.status || '')).toMatch(/final|submitted/i);

      // --- After final submission, an ending should be triggered ---
      const endingAfterFinal = await request(`/api/cases/${caseId}/ending`);
      if (endingAfterFinal.res.status === 200) {
        expect(endingAfterFinal.body).toBeTruthy();
        // Should have some ending type or result
        const resultField = endingAfterFinal.body.result || endingAfterFinal.body.endingType || endingAfterFinal.body.type || endingAfterFinal.body.ending;
        expect(resultField, 'Final report submission should trigger an ending result').toBeTruthy();
      }

      // --- Verify report can be retrieved ---
      const reportGet = await request(`/api/cases/${caseId}/report`);
      expect(reportGet.res.status).toBe(200);
      expect(reportGet.body.suspectId).toBe(finalPayload.suspectId);
      expect(reportGet.body.reasoning).toBe(finalPayload.reasoning);
      expect(reportGet.body.keyEvidence).toEqual(finalPayload.keyEvidence);
      expect(String(reportGet.body.status || '')).toMatch(/final|submitted/i);

      // --- Boundary: keyEvidence empty array should be rejected for final ---
      const emptyEvidenceFinal = await request(`/api/cases/${caseId}/report`, {
        method: 'POST',
        body: JSON.stringify({
          suspectId: 'suspect_alpha',
          reasoning: 'Some reasoning text.',
          keyEvidence: [],
          status: 'final',
        }),
      });
      expect(emptyEvidenceFinal.res.status).toBeGreaterThanOrEqual(400);
      expect(emptyEvidenceFinal.res.status).toBeLessThan(500);

      // --- Boundary: keyEvidence with more than 3 items should be rejected ---
      const tooManyEvidence = await request(`/api/cases/${caseId}/report`, {
        method: 'POST',
        body: JSON.stringify({
          suspectId: 'suspect_alpha',
          reasoning: 'Some reasoning text.',
          keyEvidence: ['clue_a', 'clue_b', 'clue_c', 'clue_d'],
          status: 'final',
        }),
      });
      expect(tooManyEvidence.res.status).toBeGreaterThanOrEqual(400);
      expect(tooManyEvidence.res.status).toBeLessThan(500);

      // --- Boundary: keyEvidence with 0 items for final should be rejected ---
      const zeroEvidenceFinal = await request(`/api/cases/${caseId}/report`, {
        method: 'POST',
        body: JSON.stringify({
          suspectId: 'suspect_alpha',
          reasoning: 'Reasoning.',
          keyEvidence: [],
          status: 'final',
        }),
      });
      expect(zeroEvidenceFinal.res.status).toBeGreaterThanOrEqual(400);

      // --- Verify old submission endpoint is gone or redirected ---
      const oldEndpoint = await request(`/api/cases/${caseId}/submit`, {
        method: 'POST',
        body: JSON.stringify({ suspectId: 'suspect_alpha', reasoning: 'test' }),
      });
      // Old endpoint should not work (404 or redirect)
      expect([301, 302, 404, 405].some(s => s === oldEndpoint.res.status) || oldEndpoint.res.status >= 400).toBe(true);

    } finally {
      await request(`/api/cases/${caseId}`, { method: 'DELETE' }).catch(() => {});
    }
  });
});

