describe('round17_investigation_log_persistence', () => {
  it('shows guidance when empty, records multiple action types in reverse chronological order, marks deleted entries, navigates, and persists through refresh and export/import', async () => {
    const created = await request('/api/cases', {
      method: 'POST',
      body: JSON.stringify({ title: `verifier-round17-${Date.now()}` }),
    });
    expect([200, 201]).toContain(created.res.status);
    const caseId = created.body.id ?? created.body.caseId;
    expect(caseId, `Expected caseId from creation, got ${JSON.stringify(created.body)}`).toBeTruthy();

    try {
      // --- Verify empty state has guidance text ---
      const emptyLogs = await request(`/api/cases/${caseId}/logs`);
      expect(emptyLogs.res.status).toBe(200);
      const emptyItems = emptyLogs.body.items || emptyLogs.body;
      const emptyMessage = emptyLogs.body.emptyMessage || emptyLogs.body.guidance || emptyLogs.body.hint || emptyLogs.body.message;
      if (Array.isArray(emptyItems) && emptyItems.length === 0) {
        expect(emptyMessage, `Expected guidance text when log is empty, got ${JSON.stringify(emptyLogs.body)}`).toBeTruthy();
        expect(typeof emptyMessage).toBe('string');
        expect(emptyMessage.length).toBeGreaterThan(0);
      }

      // --- Action 1: Create evidence to generate a log entry ---
      const evidence = await request(`/api/cases/${caseId}/evidences`, {
        method: 'POST',
        body: JSON.stringify({ id: 'clue_log_target', title: '日志目标线索', name: '日志目标线索', category: 'general', summary: '用于日志测试' }),
      });
      expect([200, 201]).toContain(evidence.res.status);
      const evidenceId = evidence.body.id || evidence.body.evidenceId || 'clue_log_target';

      // --- Action 2: Create a reasoning/deduction to generate another log entry type ---
      // First add a second clue so we can form a deduction
      const evidence2 = await request(`/api/cases/${caseId}/evidences`, {
        method: 'POST',
        body: JSON.stringify({ id: 'clue_log_2', title: '日志辅助线索', name: '日志辅助线索', category: 'general', summary: '辅助' }),
      });
