      const evidenceId2 = evidence2.body.id || evidence2.body.evidenceId || 'clue_log_2';

      const deduction = await request(`/api/cases/${caseId}/deductions`, {
        method: 'POST',
        body: JSON.stringify({ clueIds: [evidenceId, evidenceId2], conclusion: '测试推理记录' }),
      });
      // Accept success or try alternate path
      let deductionCreated = [200, 201].includes(deduction.res.status);
      if (!deductionCreated) {
        // Try alternate path
        const dedAlt = await request(`/api/cases/${caseId}/reasoning`, {
          method: 'POST',
          body: JSON.stringify({ clueIds: [evidenceId, evidenceId2], conclusion: '测试推理记录' }),
        });
