        for (let i = 0; i < items.length - 1; i++) {
          const currentTime = items[i].timestamp || items[i].createdAt || items[i].time || items[i].date;
          const nextTime = items[i + 1].timestamp || items[i + 1].createdAt || items[i + 1].time || items[i + 1].date;
          if (currentTime && nextTime) {
            expect(
              new Date(currentTime).getTime() >= new Date(nextTime).getTime(),
              `Log entries should be in reverse chronological order: ${currentTime} should be >= ${nextTime}`
            ).toBe(true);
          }
        }
        // Also check that the first item is the most recent action (report or deduction, not the first evidence)
        const firstLogDesc = String(items[0].label || items[0].description || items[0].action || '').toLowerCase();
        const lastLogDesc = String(items[items.length - 1].label || items[items.length - 1].description || items[items.length - 1].action || '').toLowerCase();
        // The first entry should NOT be about the earliest action if ordering is correct
        // This is a soft check since we can't always know exact description matching
      }

      // --- Verify persistence through "refresh" (re-GET) ---
      const refreshedLogs = await request(`/api/cases/${caseId}/logs`);
      expect(refreshedLogs.res.status).toBe(200);
      const refreshedItems = refreshedLogs.body.items || refreshedLogs.body;
      expect(Array.isArray(refreshedItems)).toBe(true);
      expect(refreshedItems.length).toBe(items.length);

      // --- Delete the evidence ---
      const deleted = await request(`/api/cases/${caseId}/evidences/${evidenceId}`, { method: 'DELETE' });
      if (![200, 204].includes(deleted.res.status)) {
        // Try alternate ID format
        await request(`/api/cases/${caseId}/evidences/clue_log_target`, { method: 'DELETE' });
      }

      // --- Verify log entry still exists but is marked as deleted/invalid ---
      const logsAfterDelete = await request(`/api/cases/${caseId}/logs`);
      expect(logsAfterDelete.res.status).toBe(200);
      const itemsAfterDelete = logsAfterDelete.body.items || logsAfterDelete.body;
      const persistedLog = itemsAfterDelete.find((x) =>
        String(x.targetId || x.entityId || x.refId || '').includes('clue_log_target') ||
        String(x.label || x.description || '').includes('日志目标线索')
      );
      expect(persistedLog, 'Log entry should persist after source content deletion').toBeTruthy();

      const logStatus = persistedLog.status || persistedLog.state || persistedLog.sourceStatus;
      expect(logStatus, `Expected persisted log to have a status field indicating deletion, got ${JSON.stringify(persistedLog)}`).toBeTruthy();
      expect(String(logStatus).toLowerCase()).toMatch(/deleted|invalid|missing|inactive|removed|expired|失效/i);

      // --- Export the case ---
      const exportResp = await request(`/api/cases/${caseId}/export`);
      expect(exportResp.res.status, `Expected export status 200, got ${exportResp.res.status}`).toBe(200);
      expect(exportResp.body && typeof exportResp.body === 'object').toBe(true);

      // --- Import the case into a new slot ---
      const importResp = await request('/api/cases/import', {
        method: 'POST',
        body: JSON.stringify(exportResp.body),
      });
      expect([200, 201]).toContain(importResp.res.status);
      const importedCaseId = importResp.body.id ?? importResp.body.caseId;
      expect(importedCaseId, `Expected imported caseId, got ${JSON.stringify(importResp.body)}`).toBeTruthy();

      try {
        // --- Verify logs are restored after import ---
        const importedLogs = await request(`/api/cases/${importedCaseId}/logs`);
        expect(importedLogs.res.status).toBe(200);
        const importedItems = importedLogs.body.items || importedLogs.body;
        expect(Array.isArray(importedItems)).toBe(true);
        expect(importedItems.length).toBeGreaterThan(0);

        const restoredLog = importedItems.find((x) =>
          String(x.targetId || x.entityId || x.refId || '').includes('clue_log_target') ||
          String(x.label || x.description || '').includes('日志目标线索')
        );
        expect(restoredLog, 'Log entry should be restored after import').toBeTruthy();

        const restoredStatus = restoredLog.status || restoredLog.state || restoredLog.sourceStatus;
        expect(restoredStatus, 'Restored log should still indicate deleted status').toBeTruthy();
        expect(String(restoredStatus).toLowerCase()).toMatch(/deleted|invalid|missing|inactive|removed|expired|失效/i);

        // Verify imported logs also maintain reverse chronological order
        if (importedItems.length >= 2) {
          const t0 = importedItems[0].timestamp || importedItems[0].createdAt || importedItems[0].time;
          const tLast = importedItems[importedItems.length - 1].timestamp || importedItems[importedItems.length - 1].createdAt || importedItems[importedItems.length - 1].time;
          if (t0 && tLast) {
            expect(
              new Date(t0).getTime() >= new Date(tLast).getTime(),
              'Imported logs should maintain reverse chronological order'
            ).toBe(true);
          }
        }
      } finally {
        await request(`/api/cases/${importedCaseId}`, { method: 'DELETE' }).catch(() => {});
      }
    } finally {
      await request(`/api/cases/${caseId}`, { method: 'DELETE' }).catch(() => {});
    }
  });
});

import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function request(method, path, body) {
  const res = await fetch(`${BASE_URL}${path}`, {
    method,
    headers: { 'Content-Type': 'application/json' },
    body: body === undefined ? undefined : JSON.stringify(body),
  });
  const text = await res.text();
  let json;
  try {
    json = text ? JSON.parse(text) : null;
  } catch {
    json = text;
  }
  return { res, body: json };
}

function pickId(payload) {
  return payload?.id ?? payload?.data?.id ?? payload?.dashboard?.id;
}

function pickList(payload) {
  if (Array.isArray(payload)) return payload;
  if (Array.isArray(payload?.items)) return payload.items;
  if (Array.isArray(payload?.data)) return payload.data;
  if (Array.isArray(payload?.data?.items)) return payload.data.items;
  return [];
}

function pickTotal(payload) {
  return payload?.total ?? payload?.count ?? payload?.data?.total ?? payload?.data?.count ?? null;
}

function pickName(payload) {
  return payload?.name ?? payload?.data?.name ?? payload?.dashboard?.name ?? null;
}

async function createDashboard(name, description) {
  const r = await request('POST', '/api/dashboards', { name, description });
  expect([200, 201]).toContain(r.res.status);
  const id = pickId(r.body);
  expect(id, `expected dashboard id from create response, got ${JSON.stringify(r.body)}`).toBeTruthy();
  return id;
}

async function safeDeleteDashboard(id) {
  if (!id) return;
  try {
    await fetch(`${BASE_URL}/api/dashboards/${id}`, { method: 'DELETE' });
  } catch {}
}

describe('round2_dashboard_list_management', () => {
  it('should support search, rename, copy, delete, and keep search result count consistent', async () => {
    const unique = `vt-mgmt-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
    const renamed = `${unique}-renamed`;
    let id1;
    let id2;
    let copiedId;

    try {
      id1 = await createDashboard(`${unique}-alpha`, 'alpha');
      id2 = await createDashboard(`${unique}-beta`, 'beta');

      // Search should find both
      const searchBefore = await request('GET', `/api/dashboards?search=${encodeURIComponent(unique)}`);
      expect(searchBefore.res.status).toBe(200);
      const beforeItems = pickList(searchBefore.body);
      expect(beforeItems.length).toBeGreaterThanOrEqual(2);
      expect(beforeItems.every(item => String(item.name).includes(unique))).toBe(true);

      // Rename
      const renameRes = await request('PATCH', `/api/dashboards/${id1}`, { name: renamed });
      expect([200, 204]).toContain(renameRes.res.status);

      const getRenamedList = await request('GET', `/api/dashboards?search=${encodeURIComponent(renamed)}`);
      expect(getRenamedList.res.status).toBe(200);
      const renamedItems = pickList(getRenamedList.body);
      expect(renamedItems.some(item => item.id === id1 || item.name === renamed)).toBe(true);

      // Copy and verify name differs from original
      const copyRes = await request('POST', `/api/dashboards/${id1}/copy`, {});
      expect([200, 201]).toContain(copyRes.res.status);
      copiedId = pickId(copyRes.body);
      expect(copiedId, `expected copied dashboard id, got ${JSON.stringify(copyRes.body)}`).toBeTruthy();

      // Verify copied dashboard name is different from the original
      const copiedName = pickName(copyRes.body);
      if (copiedName) {
        expect(copiedName).not.toBe(renamed);
      } else {
        // Fallback: fetch the copied dashboard detail to check name
        const copiedDetail = await request('GET', `/api/dashboards/${copiedId}`);
        expect(copiedDetail.res.status).toBe(200);
        const copiedDashboard = copiedDetail.body?.dashboard ?? copiedDetail.body?.data ?? copiedDetail.body;
        expect(copiedDashboard.name, `copied dashboard name should differ from original '${renamed}'`).not.toBe(renamed);
      }

      // Delete
      const deleteRes = await request('DELETE', `/api/dashboards/${id2}`);
      expect([200, 204]).toContain(deleteRes.res.status);
      const deletedId2 = id2;
      id2 = undefined;

      const searchDeleted = await request('GET', `/api/dashboards?search=${encodeURIComponent(`${unique}-beta`)}`);
      expect(searchDeleted.res.status).toBe(200);
      const deletedItems = pickList(searchDeleted.body);
      expect(deletedItems.find(item => item.id === deletedId2 || item.name === `${unique}-beta`)).toBeFalsy();

      // Verify search result count consistency
      const verifyCount = await request('GET', `/api/dashboards?search=${encodeURIComponent(unique)}`);
      expect(verifyCount.res.status).toBe(200);
      const verifyItems = pickList(verifyCount.body);
      const totalFromResponse = pickTotal(verifyCount.body);
      if (totalFromResponse !== null && totalFromResponse !== undefined) {
        expect(totalFromResponse, `expected total count to match items array length`).toBe(verifyItems.length);
      }
      // After rename+copy+delete: original renamed (id1) + copy of id1 = at least 2 items matching unique prefix
      expect(verifyItems.length).toBeGreaterThanOrEqual(2);

      // --- Empty search result: should return 200 with empty list, not an error ---
      const nonsenseKeyword = `no-match-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
      const emptySearch = await request('GET', `/api/dashboards?search=${encodeURIComponent(nonsenseKeyword)}`);
      expect(emptySearch.res.status).toBe(200);
      const emptyItems = pickList(emptySearch.body);
      expect(emptyItems.length).toBe(0);
    } finally {
      await safeDeleteDashboard(id1);
      await safeDeleteDashboard(id2);
      await safeDeleteDashboard(copiedId);
    }
  });
});

import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function request(method, path, body, extraHeaders = {}) {
  const res = await fetch(`${BASE_URL}${path}`, {
    method,
    headers: {
      'Content-Type': 'application/json',
      ...extraHeaders,
    },
    body: body === undefined ? undefined : JSON.stringify(body),
  });
  const text = await res.text();
  let json;
  try {
    json = text ? JSON.parse(text) : null;
  } catch {
    json = text;
  }
  return { res, body: json, text };
}

function randomName(prefix) {
  return `${prefix}-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
}

async function cleanup(path) {
  try {
    await fetch(`${BASE_URL}${path}`, { method: 'DELETE' });
  } catch {}
}

async function findWorkingEndpoint(candidates, method = 'OPTIONS') {
  for (const path of candidates) {
    try {
      const res = await fetch(`${BASE_URL}${path}`, { method });
      if (res.status !== 404) return path;
    } catch {}
  }
  for (const path of candidates) {
    try {
      const res = await fetch(`${BASE_URL}${path}`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({}),
      });
      if (res.status !== 404) return path;
    } catch {}
  }
  return candidates[0];
}

async function findDsApiPath() {
  for (const path of ['/api/datasources', '/api/data-sources']) {
    try {
      const res = await fetch(`${BASE_URL}${path}`, { method: 'GET' });
      if (res.status !== 404) return path;
    } catch {}
  }
  return '/api/datasources';
}

function extractSummaryField(body, ...fieldNames) {
  if (!body || typeof body !== 'object') return undefined;
  for (const f of fieldNames) {
    if (body[f] !== undefined) return body[f];
    if (body.summary && body.summary[f] !== undefined) return body.summary[f];
  }
  return undefined;
}

function getSummaryCount(body, category) {
  // Try direct fields, nested summary, results array
  const directMap = {
    succeeded: ['succeeded', 'success', 'successCount', 'created'],
    failed: ['failed', 'failure', 'failCount', 'errors', 'failedCount'],
    skipped: ['skipped', 'skipCount', 'skippedCount'],
    renamed: ['renamed', 'renamedCount'],
    overwritten: ['overwritten', 'overwrittenCount', 'overwrote'],
  };
  const fields = directMap[category] || [category];
  for (const f of fields) {
    if (body?.[f] !== undefined) {
      const v = body[f];
      if (typeof v === 'number') return v;
      if (Array.isArray(v)) return v.length;
    }
    if (body?.summary?.[f] !== undefined) {
      const v = body.summary[f];
      if (typeof v === 'number') return v;
      if (Array.isArray(v)) return v.length;
    }
  }
  // Try results array
  const results = body?.results ?? body?.items ?? [];
  if (Array.isArray(results) && results.length > 0) {
    const actionMap = {
      succeeded: ['created', 'success', 'imported', 'overwritten', 'renamed'],
      failed: ['failed', 'error'],
      skipped: ['skipped', 'skip'],
      renamed: ['renamed', 'rename'],
      overwritten: ['overwritten', 'overwrite'],
    };
    const actions = actionMap[category] || [category];
    return results.filter(r => actions.includes(r.action) || actions.includes(r.status) || actions.includes(r.result)).length;
  }
  return undefined;
}

describe('round15_import_conflict_resolution', () => {
  it('should support skip, overwrite and rename strategies for dashboards and datasources, with result summaries and partial failure resilience', async () => {
    const baseName = randomName('conflict-dashboard');
    const unrelatedName = randomName('unrelated-dashboard');
    const createdIds = [];
    const createdDsIds = [];

    const importPath = await findWorkingEndpoint(['/api/import', '/api/dashboards/import', '/api/imports']);
    const dsApiPath = await findDsApiPath();

    // Create existing dashboard
    const existing = await request('POST', '/api/dashboards', {
      name: baseName,
      layout: [{ i: 'base-chart', x: 0, y: 0, w: 4, h: 4 }],
