    const existingId = existing.body?.id;
    expect(existingId).toBeTruthy();
    createdIds.push(existingId);

    // Create an unrelated dashboard to verify overwrite doesn't remove it
    const unrelated = await request('POST', '/api/dashboards', {
      name: unrelatedName,
      layout: [{ i: 'unrelated-chart', x: 0, y: 0, w: 3, h: 3 }],
      charts: [{ id: 'unrelated-chart', type: 'pie', title: 'Unrelated', dataSource: { kind: 'builtin', dataset: 'demo_sales' } }],
