      expect([200, 201, 207], `skip strategy import failed: ${skipImport.res.status} ${skipImport.text}`).toContain(skipImport.res.status);
      expect(skipImport.body && typeof skipImport.body === 'object').toBeTruthy();

      // Verify skip response has clear skip indication and summary counts
