        const dsList = dsListRes.body?.items || dsListRes.body?.dataSources || dsListRes.body || [];
        if (Array.isArray(dsList)) {
          const renamedDsList = dsList.filter(ds => ds.id !== existingDsId && ds.name !== dsName && ds.name && ds.name.includes(dsName.substring(0, dsName.indexOf('-'))));
          for (const rds of renamedDsList) {
            if (!createdDsIds.includes(rds.id)) createdDsIds.push(rds.id);
            expect(rds.name).not.toBe(dsName);
            expect(rds.name.length).toBeGreaterThan(0);
          }
        }
      }

      // === PARTIAL FAILURE: one valid item + one clearly invalid item ===
      const goodName = randomName('partial-success');
      const partialArchive = {
        version: 'current',
        dashboards: [
          {
            name: goodName,
            layout: [{ i: 'ok-chart', x: 0, y: 0, w: 4, h: 4 }],
            charts: [{ id: 'ok-chart', type: 'line', title: 'OK', dataSource: { kind: 'builtin', dataset: 'demo_sales' } }],
            filters: [],
          },
          {
            name: '',
            layout: 'INVALID_NOT_AN_ARRAY',
            charts: 'NOT_VALID',
            filters: 12345,
          },
        ],
      };
      const partialImport = await request('POST', importPath, { ...partialArchive, conflict: 'rename', conflictStrategy: 'rename', strategy: 'rename' });
      // Accept 200, 201, 207 (partial success) - should NOT be a full rollback
      expect([200, 201, 207], `partial import unexpected status: ${partialImport.res.status} ${partialImport.text}`).toContain(partialImport.res.status);

      // Check partial import response has success/failure breakdown with counts
      const partialBody = partialImport.body;
      const partialSucceededCount = getSummaryCount(partialBody, 'succeeded');
      const partialFailedCount = getSummaryCount(partialBody, 'failed');
      const hasBreakdown = (
        (partialSucceededCount !== undefined && partialFailedCount !== undefined) ||
        partialBody?.results !== undefined ||
        partialBody?.summary !== undefined ||
        (partialBody?.succeeded !== undefined && partialBody?.failed !== undefined)
      );
      expect(hasBreakdown, `partial import response should contain success/failure breakdown: ${JSON.stringify(partialBody)}`).toBe(true);

      // Verify at least one succeeded and one failed
      if (partialSucceededCount !== undefined) {
        expect(partialSucceededCount, 'At least the valid dashboard should succeed').toBeGreaterThanOrEqual(1);
      }
      if (partialFailedCount !== undefined) {
        expect(partialFailedCount, 'The invalid dashboard should be counted as failed').toBeGreaterThanOrEqual(1);
      }

      // Check that the successful item was preserved (not rolled back)
      const partialResults = partialBody?.results ?? partialBody?.items ?? partialBody?.created ?? [];
      let goodItemId;
      if (Array.isArray(partialResults)) {
        const goodResult = partialResults.find(r => r.name === goodName || (r.name && r.name.includes('partial-success')));
        goodItemId = goodResult?.id;
      }
      goodItemId = goodItemId || partialBody?.created?.[0]?.id;

      if (goodItemId) {
        createdIds.push(goodItemId);
        const goodItemGet = await request('GET', `/api/dashboards/${goodItemId}`);
        expect(goodItemGet.res.status, 'successful item should be retrievable by ID after partial failure').toBe(200);
        const goodItemPayload = goodItemGet.body?.dashboard || goodItemGet.body;
        expect(goodItemPayload.name).toContain('partial-success');
      } else {
        // Fallback: search in list
        const listAfterPartial = await request('GET', '/api/dashboards');
        expect(listAfterPartial.res.status).toBe(200);
        const items = listAfterPartial.body?.items || listAfterPartial.body?.dashboards || listAfterPartial.body || [];
        const foundSuccess = items.find((d) => d.name === goodName || (d.name && d.name.includes('partial-success')));
        expect(foundSuccess, `successful item should remain imported even if another item fails. list=${JSON.stringify(items.map(d => d.name))}`).toBeTruthy();
        if (foundSuccess?.id) createdIds.push(foundSuccess.id);
      }
    } finally {
      for (const id of createdIds) await cleanup(`/api/dashboards/${id}`);
      for (const id of createdDsIds) await cleanup(`${dsApiPath}/${id}`);
    }
  });
});

import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function request(method, path, body, extraHeaders = {}) {
  const res = await fetch(`${BASE_URL}${path}`, {
    method,
    headers: {
      'Content-Type': 'application/json',
      ...extraHeaders,
    },
    body: body === undefined ? undefined : JSON.stringify(body),
  });
  const text = await res.text();
  let json;
  try {
    json = text ? JSON.parse(text) : null;
  } catch {
    json = text;
  }
  return { res, body: json, text };
}

function randomName(prefix) {
  return `${prefix}-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
}

async function cleanup(path) {
  try {
    await fetch(`${BASE_URL}${path}`, { method: 'DELETE' });
  } catch {}
}

function extractChartData(dashboardPayload, chartId) {
  const charts = dashboardPayload?.charts || [];
  const chart = charts.find(c => c.id === chartId);
  if (!chart) return null;
  // Return a deep copy of the chart's relevant fields
  return {
    id: chart.id,
    type: chart.type,
    title: chart.title,
    data: chart.data,
    series: chart.series,
    dataSource: chart.dataSource,
    bindings: chart.bindings,
    config: chart.config,
  };
}

describe('round19_demo_mode_deterministic', () => {
  it('should advance builtin demo charts deterministically for 5 steps, keep real-source charts unchanged, show step info, and reset to initial state when turned off', async () => {
    const dashboardName = randomName('demo-mode');
    let dashboardId;

    const create = await request('POST', '/api/dashboards', {
      name: dashboardName,
      layout: [
        { i: 'demo-chart', x: 0, y: 0, w: 6, h: 4 },
        { i: 'real-chart', x: 6, y: 0, w: 6, h: 4 },
      ],
      charts: [
        {
          id: 'demo-chart',
          type: 'line',
          title: 'Demo Builtin',
          dataSource: { kind: 'builtin', dataset: 'demo_sales' },
        },
        {
          id: 'real-chart',
          type: 'line',
          title: 'Real Remote',
          dataSource: { kind: 'remote', url: 'https://example.invalid/api/data' },
        },
      ],
      filters: [],
    });

    expect([200, 201]).toContain(create.res.status);
    dashboardId = create.body?.id;
    expect(dashboardId).toBeTruthy();

    try {
      // Capture initial state
      const initial = await request('GET', `/api/dashboards/${dashboardId}`);
      expect(initial.res.status).toBe(200);
      const initialPayload = initial.body?.dashboard || initial.body;
      const initialDemoChart = extractChartData(initialPayload, 'demo-chart');
      const initialRealChart = extractChartData(initialPayload, 'real-chart');
      const initialCharts = JSON.stringify(initialPayload.charts);
      const initialLayout = JSON.stringify(initialPayload.layout);
      const initialFilters = JSON.stringify(initialPayload.filters);

      // Enable demo mode
      const enableDemo = await request('POST', `/api/dashboards/${dashboardId}/demo-mode`, { enabled: true });
      expect([200, 201]).toContain(enableDemo.res.status);
      expect(enableDemo.body?.enabled ?? true).toBe(true);

      // First run: advance 5 steps and capture snapshots
      const stepSnapshots = [];
      const realChartSnapshots = [];
      for (let i = 1; i <= 5; i++) {
        const step = await request('POST', `/api/dashboards/${dashboardId}/demo-mode/step`, { step: i });
        expect([200, 201], `step ${i} failed with ${step.res.status}: ${step.text}`).toContain(step.res.status);
        const body = step.body || {};
        expect(body.currentStep ?? body.step, `demo mode should report current step for step ${i}: ${JSON.stringify(body)}`).toBe(i);
        stepSnapshots.push(JSON.stringify(body));

        // Verify real-chart is unchanged during each step by fetching dashboard details
        const midStepDashboard = await request('GET', `/api/dashboards/${dashboardId}`);
        expect(midStepDashboard.res.status).toBe(200);
        const midPayload = midStepDashboard.body?.dashboard || midStepDashboard.body;
        const currentRealChart = extractChartData(midPayload, 'real-chart');
        realChartSnapshots.push(JSON.stringify(currentRealChart));

        // Real chart should be identical to initial state
        expect(
          JSON.stringify(currentRealChart),
          `real-source chart should remain unchanged at step ${i}`
        ).toBe(JSON.stringify(initialRealChart));

        // Verify step info is visible on dashboard detail ("page" level)
        const demoState = midPayload.demoMode || midPayload.demo || midPayload.demoState || body;
        const currentStepVisible = demoState?.currentStep ?? demoState?.step ?? midPayload.currentStep ?? midPayload.step;
        expect(currentStepVisible, `dashboard detail should show current demo step at step ${i}`).toBe(i);
      }

      // All 5 steps should be distinct
      expect(stepSnapshots.length).toBe(5);
      expect(new Set(stepSnapshots).size, 'each deterministic step snapshot should be distinct across 5 steps').toBe(5);

      // Reset and run second round to verify determinism of ALL 5 steps
      const resetDemo = await request('POST', `/api/dashboards/${dashboardId}/demo-mode/reset`, {});
      expect([200, 201]).toContain(resetDemo.res.status);

      // Second run: advance 5 steps and compare with first run
      for (let i = 1; i <= 5; i++) {
        const stepAgain = await request('POST', `/api/dashboards/${dashboardId}/demo-mode/step`, { step: i });
        expect([200, 201]).toContain(stepAgain.res.status);
        expect(
          JSON.stringify(stepAgain.body || {}),
          `step ${i} after reset should be deterministic and identical to first run`
        ).toBe(stepSnapshots[i - 1]);
      }

      // Disable demo mode
      const disableDemo = await request('POST', `/api/dashboards/${dashboardId}/demo-mode`, { enabled: false });
      expect([200, 201]).toContain(disableDemo.res.status);
      expect(disableDemo.body?.enabled ?? false).toBe(false);

      // After disabling, verify key business fields return to initial state
      const afterDisable = await request('GET', `/api/dashboards/${dashboardId}`);
      expect(afterDisable.res.status).toBe(200);
      const afterDisablePayload = afterDisable.body?.dashboard || afterDisable.body;

      // Compare charts content (key business fields)
      const afterCharts = JSON.stringify(afterDisablePayload.charts);
      const afterLayout = JSON.stringify(afterDisablePayload.layout);
      const afterFilters = JSON.stringify(afterDisablePayload.filters);
      expect(afterCharts, 'after disabling demo mode, charts should return to initial state').toBe(initialCharts);
      expect(afterLayout, 'after disabling demo mode, layout should return to initial state').toBe(initialLayout);
      expect(afterFilters, 'after disabling demo mode, filters should return to initial state').toBe(initialFilters);

      // Specifically verify both charts are back
      const afterDemoChart = extractChartData(afterDisablePayload, 'demo-chart');
      const afterRealChart = extractChartData(afterDisablePayload, 'real-chart');
      expect(afterDemoChart, 'demo chart should exist after disabling demo mode').toBeTruthy();
      expect(afterRealChart, 'real chart should exist after disabling demo mode').toBeTruthy();
      expect(JSON.stringify(afterDemoChart), 'demo chart should be back to initial state').toBe(JSON.stringify(initialDemoChart));
      expect(JSON.stringify(afterRealChart), 'real chart should be unchanged').toBe(JSON.stringify(initialRealChart));
    } finally {
      if (dashboardId) await cleanup(`/api/dashboards/${dashboardId}`);
    }
  });
});

import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function request(method, path, body) {
  const res = await fetch(`${BASE_URL}${path}`, {
    method,
    headers: { 'Content-Type': 'application/json' },
    body: body === undefined ? undefined : JSON.stringify(body),
  });
  const text = await res.text();
  let json;
  try {
    json = text ? JSON.parse(text) : null;
  } catch {
    json = text;
  }
  return { res, body: json };
}

function pickId(payload) {
  return payload?.id ?? payload?.data?.id ?? payload?.dashboard?.id;
}

function pickList(payload) {
  if (Array.isArray(payload)) return payload;
  if (Array.isArray(payload?.items)) return payload.items;
  if (Array.isArray(payload?.data)) return payload.data;
  if (Array.isArray(payload?.data?.items)) return payload.data.items;
  return [];
}

function pickErrorMessage(payload) {
  if (!payload) return null;
  return payload?.message ?? payload?.error ?? payload?.errors ?? payload?.data?.message ?? null;
}

async function safeDeleteDashboard(id) {
  if (!id) return;
  try {
    await fetch(`${BASE_URL}/api/dashboards/${id}`, { method: 'DELETE' });
  } catch {}
}

describe('round1_dashboard_create_flow', () => {
  it('should create dashboard, validate list fields, and enforce name validation', async () => {
    const unique = `vt-dashboard-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
    const description = 'verifier dashboard create flow';
    let dashboardId;

    try {
      // --- Boundary: empty name ---
