      const items = pickList(list.body);
      expect(Array.isArray(items), `expected dashboard list array, got ${JSON.stringify(list.body)}`).toBe(true);

      const found = items.find(item => item.id === dashboardId || item.name === unique);
      expect(found, `expected dashboard ${unique} to exist in list, got ${JSON.stringify(items)}`).toBeTruthy();
