      expect(found.description).toBe(description);
      expect(found.updatedAt ?? found.updated_at, `expected updatedAt field on dashboard list item, got ${JSON.stringify(found)}`).toBeTruthy();
    } finally {
      await safeDeleteDashboard(dashboardId);
    }
  });
});

