          conflictText.includes('already') || conflictResult?.strategy || conflictResult?.conflictResolution;
        // At minimum the response should indicate how the conflict was handled
        expect(
          hasConflictInfo || conflictId !== importedCurrentId,
          `importing same-name archive should indicate conflict handling or create a distinct entry, got: ${conflictText.slice(0, 300)}`
        ).toBe(true);
      } else {
        // 4xx response for conflict is acceptable
        expect([400, 409, 422]).toContain(conflictImport.res.status);
        const conflictErrorBody = conflictImport.body;
        const hasConflictMsg = conflictErrorBody?.message || conflictErrorBody?.error;
        expect(hasConflictMsg, `conflict response should contain error message: ${JSON.stringify(conflictErrorBody)}`).toBeTruthy();
      }

      // --- Import legacy archive (missing filters and share settings) ---
      const legacyName = randomName('legacy-import');
      const legacyArchive = {
        version: '0.9',
        dashboard: {
          name: legacyName,
          description: 'A simple legacy dashboard',
          charts: [
            {
              id: 'legacy-chart-1',
              type: 'bar',
              title: 'Legacy Chart',
              dataSource: { kind: 'builtin', dataset: 'demo_sales' },
            },
          ],
        },
      };

      const importLegacy = await request('POST', '/api/import', legacyArchive);
      expect([200, 201], `legacy import failed with ${importLegacy.res.status}: ${importLegacy.text}`).toContain(importLegacy.res.status);
      const importedLegacyId = importLegacy.body?.dashboardId || importLegacy.body?.id || importLegacy.body?.dashboard?.id;
      expect(importedLegacyId, `legacy import id missing: ${JSON.stringify(importLegacy.body)}`).toBeTruthy();
      importedDashboardIds.push(importedLegacyId);

      const importedLegacyGet = await request('GET', `/api/dashboards/${importedLegacyId}`);
      expect(importedLegacyGet.res.status).toBe(200);
      const legacyPayload = importedLegacyGet.body?.dashboard || importedLegacyGet.body;
      expect(legacyPayload.name).toBe(legacyName);
      expect(Array.isArray(legacyPayload.charts)).toBe(true);

      // Filters should be defaulted to empty array
      expect(Array.isArray(legacyPayload.filters), `legacy import should default filters to array: ${JSON.stringify(importedLegacyGet.body)}`).toBe(true);

      // Visibility should default to 'private' (or equivalent default)
      const legacyVisibility = legacyPayload.visibility ?? legacyPayload.share?.mode ?? legacyPayload.shareMode;
      expect(
        legacyVisibility === 'private' || legacyVisibility === undefined || legacyVisibility === null,
        `legacy import should default visibility to 'private', got: ${JSON.stringify(legacyVisibility)}`
      ).toBe(true);

      // --- Full platform export including data sources ---
      let fullExport = await request('GET', '/api/export');
      if (fullExport.res.status !== 200) {
        fullExport = await request('GET', '/api/export/all');
      }
      if (fullExport.res.status !== 200) {
        fullExport = await request('GET', '/api/dashboards/export');
      }
      expect(fullExport.res.status, `full export should succeed: ${fullExport.text}`).toBe(200);
      const fullBody = fullExport.body;
      expect(fullBody && typeof fullBody === 'object', 'full export should return an object').toBeTruthy();

      // Should contain dashboards array
      const allDashboards = fullBody.dashboards ?? fullBody.data?.dashboards ?? (Array.isArray(fullBody) ? fullBody : null);
      expect(allDashboards, `full export should contain dashboards: ${JSON.stringify(fullBody).slice(0, 500)}`).toBeTruthy();
      if (Array.isArray(allDashboards)) {
        expect(allDashboards.length).toBeGreaterThan(0);
      }

      // Verify full export includes data sources summary
      const dataSources = fullBody.dataSources ?? fullBody.data?.dataSources ?? fullBody.datasources ?? fullBody.data?.datasources;
      expect(
        dataSources !== undefined,
        `full platform export should include dataSources summary, got keys: ${Object.keys(fullBody).join(', ')}`
      ).toBe(true);
    } finally {
      if (dashboardId) await cleanup(`/api/dashboards/${dashboardId}`);
      for (const id of importedDashboardIds) await cleanup(`/api/dashboards/${id}`);
    }
  });

  it('should reject invalid or incomplete import data with clear error messages', async () => {
    // --- Invalid JSON-like data ---
    const invalidImport = await request('POST', '/api/import', { garbage: true });
    expect([400, 422]).toContain(invalidImport.res.status);
    const invalidBody = invalidImport.body;
    const invalidErrorMsg = invalidBody?.message ?? invalidBody?.error;
    expect(
      invalidErrorMsg && typeof invalidErrorMsg === 'string' && invalidErrorMsg.length > 0,
      `invalid import should return a clear error message, got: ${JSON.stringify(invalidBody)}`
    ).toBe(true);

    // --- Incomplete: missing dashboard name ---
    const incompleteImport = await request('POST', '/api/import', {
      version: 'current',
      dashboard: {
        charts: [{ id: 'c1', type: 'bar', title: 'No name dashboard' }],
      },
    });
    if ([400, 422].includes(incompleteImport.res.status)) {
      // Missing name should produce a clear error
      const incompleteBody = incompleteImport.body;
      const incompleteErrorMsg = incompleteBody?.message ?? incompleteBody?.error;
      expect(
        incompleteErrorMsg && typeof incompleteErrorMsg === 'string' && incompleteErrorMsg.length > 0,
        `incomplete import error should have a clear message, got: ${JSON.stringify(incompleteBody)}`
      ).toBe(true);
    } else if ([200, 201].includes(incompleteImport.res.status)) {
      // If the system auto-fills a default name, verify it's present and reasonable
      const incompleteId = incompleteImport.body?.dashboardId || incompleteImport.body?.id || incompleteImport.body?.dashboard?.id;
      expect(incompleteId, 'if import succeeds with missing name, should return an id').toBeTruthy();
      const incompleteGet = await request('GET', `/api/dashboards/${incompleteId}`);
      expect(incompleteGet.res.status).toBe(200);
      const incompletePayload = incompleteGet.body?.dashboard || incompleteGet.body;
      expect(
        incompletePayload.name && typeof incompletePayload.name === 'string' && incompletePayload.name.length > 0,
        `dashboard imported without name should have a default name assigned, got: ${JSON.stringify(incompletePayload.name)}`
      ).toBe(true);
      // Cleanup
      await cleanup(`/api/dashboards/${incompleteId}`);
    } else {
      // Unexpected status
      expect.fail(`unexpected status ${incompleteImport.res.status} for incomplete import: ${incompleteImport.text}`);
    }
  });
});

import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function request(method, path, body) {
  const res = await fetch(`${BASE_URL}${path}`, {
    method,
    headers: { 'Content-Type': 'application/json' },
    body: body === undefined ? undefined : JSON.stringify(body),
  });
  const text = await res.text();
  let json;
  try {
    json = text ? JSON.parse(text) : null;
  } catch {
    json = text;
  }
  return { res, body: json };
}

function pickId(payload) {
  return payload?.id ?? payload?.data?.id ?? payload?.chart?.id ?? payload?.dashboard?.id;
}

function pickDashboard(payload) {
  return payload?.dashboard || payload?.data || payload;
}

function pickCharts(payload) {
  const d = pickDashboard(payload);
  if (Array.isArray(d?.charts)) return d.charts;
  return [];
}

function pickLayout(payload) {
  const d = pickDashboard(payload);
  return d?.layout || [];
}

async function safeDeleteDashboard(id) {
  if (!id) return;
  try {
    await fetch(`${BASE_URL}/api/dashboards/${id}`, { method: 'DELETE' });
  } catch {}
}

describe('round6_dashboard_layout_persistence', () => {
  it('should persist chart order and size after layout save and reload (simulated page refresh)', async () => {
    let dashboardId;
    try {
      const dashboard = await request('POST', '/api/dashboards', {
        name: `vt-layout-${Date.now()}`,
        description: 'layout persistence',
      });
      expect([200, 201]).toContain(dashboard.res.status);
      dashboardId = pickId(dashboard.body);
      expect(dashboardId).toBeTruthy();

      const ids = [];
      for (let i = 0; i < 3; i++) {
        const chart = await request('POST', `/api/dashboards/${dashboardId}/charts`, {
          title: `chart-${i}`,
          type: 'bar',
          data: [{ label: `L${i}`, value: i + 1 }],
        });
        expect([200, 201]).toContain(chart.res.status);
        ids.push(pickId(chart.body));
      }

      // Rearrange layout: chart[2] first (large), chart[0] second (medium), chart[1] third (full-width)
      const newLayout = [
        { chartId: ids[2], i: ids[2], x: 0, y: 0, w: 8, h: 4, order: 1, size: 'large' },
        { chartId: ids[0], i: ids[0], x: 8, y: 0, w: 4, h: 4, order: 2, size: 'medium' },
        { chartId: ids[1], i: ids[1], x: 0, y: 4, w: 12, h: 5, order: 3, size: 'large' },
      ];

      const saveLayout = await request('PUT', `/api/dashboards/${dashboardId}/layout`, { layout: newLayout });
      expect([200, 204]).toContain(saveLayout.res.status);

      // First read: verify layout was saved
      const detail1 = await request('GET', `/api/dashboards/${dashboardId}`);
      expect(detail1.res.status).toBe(200);
      verifyLayout(detail1.body, ids);

      // Second independent read (simulating page refresh): verify persistence
      const detail2 = await request('GET', `/api/dashboards/${dashboardId}`);
      expect(detail2.res.status).toBe(200);
      verifyLayout(detail2.body, ids);

      function verifyLayout(responseBody, chartIds) {
        const layout = pickLayout(responseBody);
        const charts = pickCharts(responseBody);

        // Verify from layout array if available
        if (Array.isArray(layout) && layout.length >= 3) {
          // Find layout items by chartId or i
          const findLayoutItem = (cid) => layout.find(l => l.chartId === cid || l.i === cid || l.id === cid);
          const first = findLayoutItem(chartIds[2]);
          const second = findLayoutItem(chartIds[0]);
          const third = findLayoutItem(chartIds[1]);

          if (first && second && third) {
            // Verify sizes
            expect(first.w ?? first.width, `first layout item width should be 8`).toBe(8);
            expect(first.h ?? first.height, `first layout item height should be 4`).toBe(4);
            expect(third.w ?? third.width, `third layout item width should be 12`).toBe(12);

            // Verify ordering: first should be at y=0,x=0; third at y=4
            const firstOrder = first.order ?? first.y ?? 0;
            const thirdOrder = third.order ?? third.y ?? 0;
            expect(thirdOrder).toBeGreaterThan(firstOrder);
          }
        }

        // Also verify from charts if they carry position/layout info
        if (charts.length >= 3) {
          const chartMap = new Map(charts.map(c => [c.id, c]));
          const c2 = chartMap.get(chartIds[2]);
          if (c2) {
            const pos = c2.layout ?? c2.position ?? c2;
            if (pos.w !== undefined || pos.width !== undefined) {
              expect(pos.w ?? pos.width).toBe(8);
              expect(pos.h ?? pos.height).toBe(4);
            }
          }
        }
      }
    } finally {
      await safeDeleteDashboard(dashboardId);
    }
  });

  it('should auto-fill gaps when a middle chart is deleted', async () => {
    let dashboardId;
    try {
      const dashboard = await request('POST', '/api/dashboards', {
        name: `vt-layout-delete-${Date.now()}`,
        description: 'delete middle chart test',
      });
      expect([200, 201]).toContain(dashboard.res.status);
      dashboardId = pickId(dashboard.body);
      expect(dashboardId).toBeTruthy();

      const ids = [];
      for (let i = 0; i < 3; i++) {
        const chart = await request('POST', `/api/dashboards/${dashboardId}/charts`, {
          title: `chart-del-${i}`,
          type: 'bar',
          data: [{ label: `L${i}`, value: i + 1 }],
        });
        expect([200, 201]).toContain(chart.res.status);
        ids.push(pickId(chart.body));
      }

      // Set initial layout in sequence
      const initialLayout = [
        { chartId: ids[0], i: ids[0], x: 0, y: 0, w: 6, h: 4, order: 1 },
        { chartId: ids[1], i: ids[1], x: 6, y: 0, w: 6, h: 4, order: 2 },
        { chartId: ids[2], i: ids[2], x: 0, y: 4, w: 6, h: 4, order: 3 },
      ];
      const saveLayout = await request('PUT', `/api/dashboards/${dashboardId}/layout`, { layout: initialLayout });
      expect([200, 204]).toContain(saveLayout.res.status);

      // Delete the middle chart
      const deleteMiddle = await request('DELETE', `/api/dashboards/${dashboardId}/charts/${ids[1]}`);
      expect([200, 204]).toContain(deleteMiddle.res.status);

      // Verify remaining charts are present and fill the gap
      const afterDelete = await request('GET', `/api/dashboards/${dashboardId}`);
      expect(afterDelete.res.status).toBe(200);
      const charts = pickCharts(afterDelete.body);
      const layout = pickLayout(afterDelete.body);

      // Should have 2 charts remaining
      const remaining = charts.length > 0 ? charts : layout;
      expect(remaining.length).toBe(2);

      // The deleted chart should not be present
      const hasDeleted = remaining.some(c => (c.id || c.chartId || c.i) === ids[1]);
      expect(hasDeleted, 'deleted middle chart should not be present').toBe(false);

      // The remaining charts should still be in order
      const hasFirst = remaining.some(c => (c.id || c.chartId || c.i) === ids[0]);
      const hasThird = remaining.some(c => (c.id || c.chartId || c.i) === ids[2]);
      expect(hasFirst, 'first chart should remain').toBe(true);
      expect(hasThird, 'third chart should remain and fill in').toBe(true);
    } finally {
      await safeDeleteDashboard(dashboardId);
    }
  });

  it('should not show weird empty placeholder when only one chart remains', async () => {
    let dashboardId;
    try {
      const dashboard = await request('POST', '/api/dashboards', {
        name: `vt-layout-single-${Date.now()}`,
        description: 'single chart test',
      });
      expect([200, 201]).toContain(dashboard.res.status);
      dashboardId = pickId(dashboard.body);
      expect(dashboardId).toBeTruthy();

      const ids = [];
      for (let i = 0; i < 2; i++) {
        const chart = await request('POST', `/api/dashboards/${dashboardId}/charts`, {
          title: `chart-single-${i}`,
          type: 'bar',
          data: [{ label: `L${i}`, value: i + 1 }],
        });
        expect([200, 201]).toContain(chart.res.status);
        ids.push(pickId(chart.body));
      }

      // Delete one chart, leaving only one
      const del = await request('DELETE', `/api/dashboards/${dashboardId}/charts/${ids[1]}`);
      expect([200, 204]).toContain(del.res.status);

      const afterDel = await request('GET', `/api/dashboards/${dashboardId}`);
      expect(afterDel.res.status).toBe(200);
      const charts = pickCharts(afterDel.body);
      const layout = pickLayout(afterDel.body);
      const items = charts.length > 0 ? charts : layout;

      // Should have exactly 1 item
      expect(items.length).toBe(1);

      // The layout/response should not contain empty placeholder items
      const responseStr = JSON.stringify(afterDel.body);
      const hasWeirdPlaceholder = /empty.?placeholder|blank.?space|no.?charts/i.test(responseStr);
      // If there is a single chart, the layout should be clean
      expect(items[0]).toBeTruthy();
      const itemId = items[0].id || items[0].chartId || items[0].i;
      expect(itemId).toBe(ids[0]);
    } finally {
      await safeDeleteDashboard(dashboardId);
    }
  });
});

import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function request(method, path, body, extraHeaders = {}) {
  const res = await fetch(`${BASE_URL}${path}`, {
    method,
    headers: {
      'Content-Type': 'application/json',
      ...extraHeaders,
    },
    body: body === undefined ? undefined : JSON.stringify(body),
  });
  const text = await res.text();
  let json;
  try {
    json = text ? JSON.parse(text) : null;
  } catch {
    json = text;
  }
  return { res, body: json, text };
}

function randomName(prefix) {
  return `${prefix}-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
}

async function cleanup(path) {
  try {
    await fetch(`${BASE_URL}${path}`, { method: 'DELETE' });
  } catch {}
}

async function findDsApiPath() {
  for (const path of ['/api/datasources', '/api/data-sources']) {
    try {
      const res = await fetch(`${BASE_URL}${path}`, { method: 'GET' });
      if (res.status !== 404) return path;
    } catch {}
  }
  return '/api/datasources';
}

async function ensureDataSourceError(dsApiPath, dsId) {
  // Try multiple approaches to make the data source status abnormal
  const approaches = [
    () => request('POST', `${dsApiPath}/${dsId}/test`, {}),
    () => request('POST', `${dsApiPath}/${dsId}/refresh`, {}),
    () => request('POST', `${dsApiPath}/${dsId}/connect`, {}),
    () => request('PATCH', `${dsApiPath}/${dsId}`, { status: 'error', connectionStatus: 'error' }),
    () => request('PUT', `${dsApiPath}/${dsId}/status`, { status: 'error' }),
  ];
  for (const approach of approaches) {
    try { await approach(); } catch {}
  }
}

function getDataSourceStatus(dsPayload) {
  return dsPayload?.status || dsPayload?.state || dsPayload?.connectionStatus || dsPayload?.connection?.status;
}

describe('round23_readonly_remote_source_guard', () => {
  it('should show unavailable placeholder in readonly share for abnormal remote/API sources, keep non-remote charts visible, and show problem info to editors', async () => {
    const dashboardName = randomName('remote-guard-dashboard');
    let dsApiPath;
    let remoteDataSourceId;
    let manualDataSourceId;
    let fileDataSourceId;
    let builtinDataSourceId;
    let dashboardId;
    let shareToken;

    dsApiPath = await findDsApiPath();

    // 1. Create a remote/API data source pointing to unreachable URL
    const remoteDsName = randomName('remote-guard-ds');
    const createRemoteSource = await request('POST', dsApiPath, {
      name: remoteDsName,
      type: 'api',
      sourceType: 'api',
      config: { url: 'https://example.invalid/unreachable-endpoint-that-does-not-exist', method: 'GET' },
    });
    expect([200, 201]).toContain(createRemoteSource.res.status);
    remoteDataSourceId = createRemoteSource.body?.id;
    expect(remoteDataSourceId).toBeTruthy();

    // Try to trigger a connection attempt to make status abnormal
    await ensureDataSourceError(dsApiPath, remoteDataSourceId);

    // 2. Create a manual data source (should remain visible in readonly)
    const createManualSource = await request('POST', dsApiPath, {
      name: randomName('manual-guard-ds'),
      type: 'manual',
      sourceType: 'manual',
      config: { data: [{ x: 1, y: 2 }] },
    });
    expect([200, 201]).toContain(createManualSource.res.status);
    manualDataSourceId = createManualSource.body?.id;
    expect(manualDataSourceId).toBeTruthy();

    // 3. Create a file-based data source
    const createFileSource = await request('POST', dsApiPath, {
      name: randomName('file-guard-ds'),
      type: 'file',
      sourceType: 'file',
      config: { filePath: '/data/sample.csv' },
    });
    expect([200, 201]).toContain(createFileSource.res.status);
    fileDataSourceId = createFileSource.body?.id;
    expect(fileDataSourceId).toBeTruthy();

    // 4. Create a builtin/example data source
    const createBuiltinSource = await request('POST', dsApiPath, {
      name: randomName('builtin-guard-ds'),
      type: 'builtin',
      sourceType: 'builtin',
      config: { preset: 'sample', dataset: 'demo_sales' },
    });
    expect([200, 201]).toContain(createBuiltinSource.res.status);
    builtinDataSourceId = createBuiltinSource.body?.id;
    expect(builtinDataSourceId).toBeTruthy();

    try {
      // 5. Create dashboard with all four chart types
      const createDashboard = await request('POST', '/api/dashboards', {
        name: dashboardName,
        layout: [
          { i: 'remote-chart', x: 0, y: 0, w: 6, h: 4 },
          { i: 'manual-chart', x: 6, y: 0, w: 6, h: 4 },
          { i: 'file-chart', x: 0, y: 4, w: 6, h: 4 },
          { i: 'builtin-chart', x: 6, y: 4, w: 6, h: 4 },
        ],
        charts: [
          {
            id: 'remote-chart',
            type: 'line',
            title: 'Guarded Remote',
            dataSourceId: remoteDataSourceId,
            dataSource: { kind: 'api', id: remoteDataSourceId },
            bindings: { x: 'time', y: 'value' },
          },
          {
            id: 'manual-chart',
            type: 'bar',
            title: 'Manual Entry Chart',
            dataSourceId: manualDataSourceId,
            dataSource: { kind: 'manual', id: manualDataSourceId },
            bindings: { x: 'x', y: 'y' },
          },
          {
            id: 'file-chart',
            type: 'pie',
            title: 'File Based Chart',
            dataSourceId: fileDataSourceId,
            dataSource: { kind: 'file', id: fileDataSourceId },
            bindings: { x: 'category', y: 'count' },
          },
          {
            id: 'builtin-chart',
            type: 'line',
            title: 'Builtin Example Chart',
            dataSourceId: builtinDataSourceId,
            dataSource: { kind: 'builtin', id: builtinDataSourceId, dataset: 'demo_sales' },
            bindings: { x: 'a', y: 'b' },
          },
        ],
        filters: [],
      });
      expect([200, 201]).toContain(createDashboard.res.status);
      dashboardId = createDashboard.body?.id;
      expect(dashboardId).toBeTruthy();

      // If charts need to be added separately
      if (!createDashboard.body?.charts || createDashboard.body?.charts?.length === 0) {
        const chartConfigs = [
          { id: 'remote-chart', type: 'line', title: 'Guarded Remote', dataSourceId: remoteDataSourceId },
          { id: 'manual-chart', type: 'bar', title: 'Manual Entry Chart', dataSourceId: manualDataSourceId },
          { id: 'file-chart', type: 'pie', title: 'File Based Chart', dataSourceId: fileDataSourceId },
          { id: 'builtin-chart', type: 'line', title: 'Builtin Example Chart', dataSourceId: builtinDataSourceId },
        ];
        for (const cc of chartConfigs) {
          await request('POST', `/api/dashboards/${dashboardId}/charts`, cc);
        }
      }

      // 6. Create a readonly share link
      const share = await request('POST', `/api/dashboards/${dashboardId}/share`, {
        mode: 'link_view',
        readonly: true,
      });
      expect([200, 201]).toContain(share.res.status);
      shareToken = share.body?.token || share.body?.shareToken || share.body?.id;
      expect(shareToken).toBeTruthy();

      // 7. Verify data source status is actually abnormal (prerequisite assertion)
      const dsDetail = await request('GET', `${dsApiPath}/${remoteDataSourceId}`);
      expect(dsDetail.res.status).toBe(200);
      const dsPayload = dsDetail.body?.dataSource || dsDetail.body;
      const dsStatus = getDataSourceStatus(dsPayload);
      const dsPayloadStr = JSON.stringify(dsPayload);
      const isAbnormal = ['error', 'abnormal', 'disconnected', 'failed', 'unreachable'].includes(dsStatus) ||
        /error|abnormal|disconnect|fail|unreachable/i.test(dsPayloadStr);
      expect(
        isAbnormal,
        `Prerequisite: Remote data source should be in abnormal/error state. Status: '${dsStatus}', payload: ${dsPayloadStr.substring(0, 500)}`
      ).toBe(true);

      // 8. Access via readonly share link
      const sharePath = `/api/share/${shareToken}`;
      const readonly = await request('GET', sharePath);
      expect(readonly.res.status).toBe(200);
      const readonlyPayload = readonly.body?.dashboard || readonly.body;

      const readonlyCharts = readonlyPayload?.charts || [];
      expect(Array.isArray(readonlyCharts), 'readonly response should contain charts array').toBe(true);

      // 9. Remote/API chart with error status should show unavailable placeholder
      const remoteChart = readonlyCharts.find(
        (c) => c.id === 'remote-chart' || c.title === 'Guarded Remote'
      );
      expect(remoteChart, 'remote chart entry should exist in readonly response').toBeTruthy();

      // Check for unavailable indicator on specific fields (not whole JSON string match)
      const remoteChartStatus = remoteChart.status || remoteChart.state;
      const remoteChartPlaceholder = remoteChart.placeholder || remoteChart.message || remoteChart.errorMessage;
      const isUnavailableByStatus = ['unavailable', 'error', 'data_unavailable'].includes(remoteChartStatus);
      const isUnavailableByPlaceholder = typeof remoteChartPlaceholder === 'string' &&
        /unavailable|not\s*available|数据不可用|data.*unavailable/i.test(remoteChartPlaceholder);
      const isUnavailableByError = typeof remoteChart.error === 'string' &&
        /unavailable|not\s*available|source.*error|数据不可用/i.test(remoteChart.error);
      expect(
        isUnavailableByStatus || isUnavailableByPlaceholder || isUnavailableByError,
        `Remote chart with abnormal data source should show unavailable placeholder via status/placeholder/error fields. ` +
        `status='${remoteChartStatus}', placeholder='${remoteChartPlaceholder}', error='${remoteChart.error}'`
      ).toBe(true);

      // The remote chart should NOT expose actual stale data content
      const remoteChartData = remoteChart.data || remoteChart.series;
      const hasNoStaleData = !remoteChartData || (Array.isArray(remoteChartData) && remoteChartData.length === 0) || remoteChartData === null;
      expect(
        hasNoStaleData,
        'Remote chart with abnormal source should not expose stale chart data in readonly view'
