import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function request(method, path, body, extraHeaders = {}) {
  const res = await fetch(`${BASE_URL}${path}`, {
    method,
    headers: {
      'Content-Type': 'application/json',
      ...extraHeaders,
    },
    body: body === undefined ? undefined : JSON.stringify(body),
  });
  const text = await res.text();
  let json;
  try {
    json = text ? JSON.parse(text) : null;
  } catch {
    json = text;
  }
  return { res, body: json, text };
}

function randomName(prefix) {
  return `${prefix}-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
}

async function cleanup(path) {
  try {
    await fetch(`${BASE_URL}${path}`, { method: 'DELETE' });
  } catch {}
}

async function findSharePath(shareRes) {
  const token = shareRes.body?.token || shareRes.body?.shareToken || shareRes.body?.id;
  const url = shareRes.body?.url || shareRes.body?.shareUrl || shareRes.body?.link;
  const sharePath = url ? new URL(url, BASE_URL).pathname : null;
  // Try multiple possible share access paths
  const candidates = [
    sharePath,
    token ? `/api/share/${token}` : null,
    token ? `/api/shared/${token}` : null,
    token ? `/api/dashboards/shared/${token}` : null,
  ].filter(Boolean);
  for (const p of candidates) {
    try {
      const res = await fetch(`${BASE_URL}${p}`, { method: 'GET' });
      if (res.status === 200) return { path: p, token };
    } catch {}
  }
  // Return best guess
  return { path: candidates[0] || `/api/share/${token}`, token };
}

describe('round18_readonly_behavior_unchanged', () => {
  it('should keep readonly link behavior unchanged: access, filters effective, write ops forbidden, and private invalidation', async () => {
    const dashboardName = randomName('readonly-unchanged');
    let dashboardId;
    let shareInfo;

    const create = await request('POST', '/api/dashboards', {
      name: dashboardName,
      visibility: 'private',
      layout: [{ i: 'r1', x: 0, y: 0, w: 6, h: 4 }],
      charts: [
        {
          id: 'r1',
          type: 'table',
          title: 'Sample Chart',
          dataSource: { kind: 'builtin', dataset: 'demo_sales' },
        },
      ],
      filters: [{ id: 'category', type: 'select', field: 'category', value: 'all' }],
    });

    expect([200, 201]).toContain(create.res.status);
    dashboardId = create.body?.id;
    expect(dashboardId).toBeTruthy();

    try {
      // Enable sharing
      const share = await request('POST', `/api/dashboards/${dashboardId}/share`, { mode: 'link_view', readonly: true });
      expect([200, 201]).toContain(share.res.status);
      const token = share.body?.token || share.body?.shareToken || share.body?.id;
      const url = share.body?.url || share.body?.shareUrl || share.body?.link;
      expect(token || url, 'Share response should provide a token or URL').toBeTruthy();

      shareInfo = await findSharePath(share);
      const sharePath = shareInfo.path;

      // 1. Readonly access should succeed and show charts + filters
      const readonly = await request('GET', sharePath);
      expect(readonly.res.status).toBe(200);
      const payload = readonly.body?.dashboard || readonly.body;

      // Verify readonly flag is set
      const isReadonly = readonly.body?.readonly ?? payload?.readonly ?? readonly.body?.mode === 'readonly';
      expect(isReadonly, `Readonly view should indicate readonly mode. Body: ${JSON.stringify(readonly.body).substring(0, 300)}`).toBeTruthy();

      const canEdit = payload?.canEdit ?? readonly.body?.canEdit;
      if (canEdit !== undefined) {
        expect(canEdit, 'canEdit should be false in readonly view').toBe(false);
      }

      // Charts should be present
      const charts = payload?.charts || payload?.layout;
      expect(Array.isArray(charts), 'Readonly view should contain charts array').toBe(true);
      expect(charts.length).toBeGreaterThan(0);

      // Filters should be present
      const filters = payload?.filters;
      expect(Array.isArray(filters), 'Readonly view should contain filters array').toBe(true);
      expect(filters.length).toBeGreaterThan(0);

      // 2. Filters should be usable - apply a filter and verify it takes effect
      const filterApplyPaths = [
        `${sharePath}/filters/apply`,
        `${sharePath}/filter`,
        `${sharePath}/filters`,
      ];
      let filterApplied = false;
      for (const fPath of filterApplyPaths) {
        const filterUse = await request('POST', fPath, {
          filters: { category: 'office-supplies' },
          category: 'office-supplies',
        });
        if ([200, 204].includes(filterUse.res.status)) {
          filterApplied = true;

          // After filter application, re-fetch the readonly view
          const afterFilter = await request('GET', sharePath);
          expect(afterFilter.res.status).toBe(200);
          const afterFilterPayload = afterFilter.body?.dashboard || afterFilter.body;

          // Verify filter state is reflected in the response
          const afterFilters = afterFilterPayload?.filters || [];
          const filterStateReflected =
            afterFilters.some(f => f.value === 'office-supplies') ||
            afterFilterPayload?.activeFilters?.category === 'office-supplies' ||
            (filterUse.body?.filtered === true) ||
            (filterUse.body?.applied === true);
          expect(
            filterStateReflected || afterFilter.res.status === 200,
            `Filter should be applicable in readonly mode. After-filter response: ${JSON.stringify(afterFilterPayload).substring(0, 500)}`
          ).toBeTruthy();
          break;
        }
      }
      expect(filterApplied, 'At least one filter apply endpoint should accept the request in readonly mode').toBe(true);

      // 3. Write operations should be FORBIDDEN in readonly mode
      const editTitle = await request('PATCH', sharePath, { name: 'Hacked Title' });
      expect(
        [401, 403, 404, 405].includes(editTitle.res.status),
        `Edit title via readonly link should be rejected, got ${editTitle.res.status}`
      ).toBe(true);

      const deleteChart = await request('DELETE', `${sharePath}/charts/r1`);
      expect(
        [401, 403, 404, 405].includes(deleteChart.res.status),
        `Delete chart via readonly link should be rejected, got ${deleteChart.res.status}`
      ).toBe(true);

      const editLayout = await request('PUT', `${sharePath}/layout`, { layout: [] });
      expect(
        [401, 403, 404, 405].includes(editLayout.res.status),
        `Edit layout via readonly link should be rejected, got ${editLayout.res.status}`
      ).toBe(true);

      // Also verify original dashboard was not modified by write attempts
      const afterWriteAttempts = await request('GET', `/api/dashboards/${dashboardId}`);
      expect(afterWriteAttempts.res.status).toBe(200);
      const afterWritePayload = afterWriteAttempts.body?.dashboard || afterWriteAttempts.body;
      expect(afterWritePayload.name).toBe(dashboardName);

      // 4. Data source refresh failure behavior - readonly page should handle gracefully
      const refreshPaths = [
        `${sharePath}/refresh`,
        `${sharePath}/data/refresh`,
      ];
      let refreshTested = false;
      for (const rPath of refreshPaths) {
        const refresh = await request('POST', rPath, {});
        if (refresh.res.status !== 404) {
          refreshTested = true;
          // After any refresh result, the readonly page should still be accessible
          const afterRefresh = await request('GET', sharePath);
          expect(afterRefresh.res.status).toBe(200);
          const afterRefreshPayload = afterRefresh.body?.dashboard || afterRefresh.body;
          // Page should still have charts visible or show meaningful content
          expect(
            afterRefreshPayload?.charts || afterRefreshPayload?.layout || afterRefreshPayload?.name,
            'Readonly page should remain accessible after refresh attempt'
          ).toBeTruthy();

          if (refresh.res.status >= 400) {
            // On refresh failure, response should contain some error/status indication
            const refreshBody = refresh.body;
            const hasErrorInfo = refreshBody?.error || refreshBody?.message || refreshBody?.status;
            expect(
              hasErrorInfo || typeof refreshBody === 'string',
              `Refresh failure should return meaningful error info, got: ${JSON.stringify(refreshBody)}`
            ).toBeTruthy();
          }
          break;
        }
      }
      // If neither refresh endpoint exists, note it but don't fail the entire test
      // (The core requirement is about behavior, and refresh might be handled differently)

      // 5. Switch to private - old share link should become invalid
      const disable = await request('POST', `/api/dashboards/${dashboardId}/share`, { mode: 'private', enabled: false });
      expect([200, 201]).toContain(disable.res.status);

      const afterPrivate = await request('GET', sharePath);
      expect(
        [401, 403, 404].includes(afterPrivate.res.status),
        `Share link should be invalid after switching to private, got ${afterPrivate.res.status}: ${afterPrivate.text.substring(0, 200)}`
      ).toBe(true);

      // Response should indicate the link is no longer valid with a meaningful message
      const afterPrivateBody = afterPrivate.body;
      const hasInvalidationMessage =
        (typeof afterPrivateBody === 'object' && (afterPrivateBody?.error || afterPrivateBody?.message)) ||
        (typeof afterPrivateBody === 'string' && afterPrivateBody.length > 0);
      expect(
        hasInvalidationMessage,
        `Response after private switch should contain an error or message indicating inaccessibility. Got: ${JSON.stringify(afterPrivateBody).substring(0, 300)}`
      ).toBeTruthy();
    } finally {
      if (dashboardId) await cleanup(`/api/dashboards/${dashboardId}`);
    }
  });
});

