function pickId(payload) {
  return payload?.id ?? payload?.data?.id ?? payload?.chart?.id ?? payload?.dashboard?.id ?? payload?.datasource?.id;
}

function pickChart(payload) {
  return payload?.chart ?? payload?.data ?? payload;
}

function pickDatasource(payload) {
  return payload?.datasource ?? payload?.data ?? payload;
}

async function safeDeleteDashboard(id) {
  if (!id) return;
  try {
    await fetch(`${BASE_URL}/api/dashboards/${id}`, { method: 'DELETE' });
  } catch {}
}

async function safeDeleteDatasource(id) {
  if (!id) return;
  try {
    await fetch(`${BASE_URL}/api/datasources/${id}`, { method: 'DELETE' });
  } catch {}
}

// Adaptive chart GET
async function getChart(dashboardId, chartId) {
  let r = await request('GET', `/api/dashboards/${dashboardId}/charts/${chartId}`);
  if (r.res.status === 200) return r;
  r = await request('GET', `/api/charts/${chartId}`);
  return r;
}

// Adaptive chart binding
async function bindChart(dashboardId, chartId, bindingPayload) {
  // Try multiple possible endpoints
  let r = await request('PUT', `/api/dashboards/${dashboardId}/charts/${chartId}/bindDatasource`, bindingPayload);
  if ([200, 204].includes(r.res.status)) return r;
  r = await request('PUT', `/api/dashboards/${dashboardId}/charts/${chartId}/binding`, bindingPayload);
  if ([200, 204].includes(r.res.status)) return r;
  r = await request('PUT', `/api/charts/${chartId}/binding`, bindingPayload);
  if ([200, 204].includes(r.res.status)) return r;
  r = await request('PATCH', `/api/dashboards/${dashboardId}/charts/${chartId}`, bindingPayload);
  if ([200, 204].includes(r.res.status)) return r;
  r = await request('PATCH', `/api/charts/${chartId}`, bindingPayload);
  return r;
}

describe('round9_chart_bind_datasource', () => {
  it('should bind chart to datasource with field mapping and preview should use datasource data instead of default sample data', async () => {
    let dashboardId;
    let chartId;
    let datasourceId;
    let datasource2Id;

    try {
      // Create datasource with 2 fields
      const ds = await request('POST', '/api/datasources', {
        name: `vt-bind-ds-${Date.now()}`,
        sourceType: 'manual',
        data: [
          { product: 'Phone', amount: 100 },
          { product: 'Laptop', amount: 200 },
        ],
      });
      expect([200, 201]).toContain(ds.res.status);
      datasourceId = pickId(ds.body);

      // Verify datasource fields
      const dsDetail = await request('GET', `/api/datasources/${datasourceId}`);
      expect(dsDetail.res.status).toBe(200);
      const detailBody = pickDatasource(dsDetail.body);
      const fields = detailBody.fields ?? detailBody.columns;
      expect(JSON.stringify(fields)).toContain('product');
      expect(JSON.stringify(fields)).toContain('amount');

      // Create dashboard and chart
      const dashboard = await request('POST', '/api/dashboards', {
        name: `vt-bind-dashboard-${Date.now()}`,
        description: 'bind datasource',
      });
      expect([200, 201]).toContain(dashboard.res.status);
      dashboardId = pickId(dashboard.body);

      const chart = await request('POST', `/api/dashboards/${dashboardId}/charts`, {
        title: 'bind-me',
        type: 'bar',
        data: [{ label: 'Default', value: 1 }],
      });
      expect([200, 201]).toContain(chart.res.status);
      chartId = pickId(chart.body);

      // --- Boundary: bar chart without value field should fail ---
      const noValueBind = await bindChart(dashboardId, chartId, {
        datasourceId,
        mapping: { xField: 'product' },
        dimensionFields: ['product'],
        valueFields: [],
      });
      expect([400, 422]).toContain(noValueBind.res.status);

      // --- Happy path: bind bar chart with valid mapping ---
      const bind = await bindChart(dashboardId, chartId, {
        datasourceId,
        mapping: { xField: 'product', yField: 'amount' },
        dimensionFields: ['product'],
        valueFields: ['amount'],
      });
      expect([200, 204]).toContain(bind.res.status);

      // Verify binding persisted and preview uses datasource data
      const after = await getChart(dashboardId, chartId);
      expect(after.res.status).toBe(200);
      const boundChart = pickChart(after.body);
      expect(boundChart.datasourceId ?? boundChart.datasource_id ?? boundChart.dataSourceId).toBe(datasourceId);
      expect(boundChart.mapping ?? boundChart.fieldMapping, `expected mapping after binding, got ${JSON.stringify(boundChart)}`).toBeTruthy();

      const preview = JSON.stringify(boundChart.previewData ?? boundChart.data ?? {});
      expect(preview).toContain('Phone');
      expect(preview).toContain('200');
      expect(preview).not.toContain('Default');

      // --- Boundary: pie chart should only accept exactly 1 dimension + 1 value ---
      // Create a pie chart
      const pieChart = await request('POST', `/api/dashboards/${dashboardId}/charts`, {
        title: 'pie-test',
        type: 'pie',
      });
      expect([200, 201]).toContain(pieChart.res.status);
      const pieChartId = pickId(pieChart.body);

      // Try binding pie chart with 2 dimension fields - should fail
      const pieBadBind = await bindChart(dashboardId, pieChartId, {
        datasourceId,
        mapping: { xField: 'product', yField: 'amount' },
        dimensionFields: ['product', 'amount'],
        valueFields: ['amount'],
      });
      expect([400, 422]).toContain(pieBadBind.res.status);

      // --- Boundary: switch datasource should clear old fields if they don't exist ---
      // Create a second datasource with different fields
      const ds2 = await request('POST', '/api/datasources', {
        name: `vt-bind-ds2-${Date.now()}`,
        sourceType: 'manual',
        data: [
          { region: 'East', revenue: 500 },
          { region: 'West', revenue: 300 },
        ],
      });
      expect([200, 201]).toContain(ds2.res.status);
      datasource2Id = pickId(ds2.body);

      // Switch the bar chart to datasource2 - old mapping fields (product/amount) don't exist
      const switchBind = await bindChart(dashboardId, chartId, {
        datasourceId: datasource2Id,
        mapping: { xField: 'product', yField: 'amount' },
        dimensionFields: ['product'],
        valueFields: ['amount'],
      });
      // The system should either reject or auto-clear the mapping
      if ([200, 204].includes(switchBind.res.status)) {
        // If accepted, the old fields should have been cleared
        const switchedChart = await getChart(dashboardId, chartId);
        const sc = pickChart(switchedChart.body);
        const newMapping = sc.mapping ?? sc.fieldMapping;
        // old fields should not remain intact if ds2 doesn't have them
        const mappingStr = JSON.stringify(newMapping ?? {});
        // If auto-cleared, we check the response or the chart state
        expect(sc.datasourceId ?? sc.datasource_id ?? sc.dataSourceId).toBe(datasource2Id);
      } else {
        // Rejected because old fields don't exist in new datasource - also valid
        expect([400, 422]).toContain(switchBind.res.status);
      }

    } finally {
      await safeDeleteDashboard(dashboardId);
      await safeDeleteDatasource(datasourceId);
      await safeDeleteDatasource(datasource2Id);
    }
  });
});

