describe('round8_datasource_preview_detail', () => {
  it('should return datasource detail and preview fields, support editing manual data, refresh preview for api type, and distinguish empty datasource from refresh failure', async () => {
    let dataId;
    let emptyId;
    let failedId;

    try {
      // --- Create a normal manual datasource with data ---
      const normal = await request('POST', '/api/datasources', {
        name: `vt-preview-normal-${Date.now()}`,
        sourceType: 'manual',
        data: [
          { city: 'Shanghai', sales: 10 },
          { city: 'Beijing', sales: 20 },
        ],
      });
      expect([200, 201]).toContain(normal.res.status);
      dataId = pickId(normal.body);

      // --- Create an empty manual datasource ---
      const empty = await request('POST', '/api/datasources', {
        name: `vt-preview-empty-${Date.now()}`,
        sourceType: 'manual',
        data: [],
      });
      expect([200, 201]).toContain(empty.res.status);
      emptyId = pickId(empty.body);

      // --- Verify normal datasource detail: fields, preview rows, total rows ---
      const detail = await request('GET', `/api/datasources/${dataId}`);
      expect(detail.res.status).toBe(200);
      const ds = pickDatasource(detail.body);
      expect(ds.name).toContain('vt-preview-normal-');
      expect(ds.fields ?? ds.columns, `expected fields/columns in datasource detail, got ${JSON.stringify(ds)}`).toBeTruthy();
      expect(ds.previewRows ?? ds.preview ?? ds.rows, `expected preview rows in datasource detail, got ${JSON.stringify(ds)}`).toBeTruthy();
      expect(ds.totalRows ?? ds.total, `expected total rows = 2, got ${JSON.stringify(ds)}`).toBe(2);

      // --- Verify empty datasource: totalRows=0, clearly not a failure ---
      const emptyDetail = await request('GET', `/api/datasources/${emptyId}`);
      expect(emptyDetail.res.status).toBe(200);
      const emptyDs = pickDatasource(emptyDetail.body);
      const emptyTotal = emptyDs.totalRows ?? emptyDs.total;
      expect(emptyTotal).toBe(0);
      // Empty datasource should NOT have a failure/error status
      const emptyStatus = emptyDs.status;
      if (emptyStatus) {
        expect(emptyStatus).not.toBe('refresh_failed');
        expect(emptyStatus).not.toBe('error');
      }

      // --- Manual datasource editing: update data and verify ---
      const updateRes = await request('PATCH', `/api/datasources/${dataId}`, {
        data: [
          { city: 'Shanghai', sales: 10 },
          { city: 'Beijing', sales: 20 },
          { city: 'Guangzhou', sales: 30 },
        ],
      });
      // Also try PUT if PATCH fails
      if (![200, 204].includes(updateRes.res.status)) {
        const putRes = await request('PUT', `/api/datasources/${dataId}`, {
          data: [
            { city: 'Shanghai', sales: 10 },
            { city: 'Beijing', sales: 20 },
            { city: 'Guangzhou', sales: 30 },
          ],
        });
        expect([200, 204]).toContain(putRes.res.status);
      } else {
        expect([200, 204]).toContain(updateRes.res.status);
      }

      const updatedDetail = await request('GET', `/api/datasources/${dataId}`);
      expect(updatedDetail.res.status).toBe(200);
      const updatedDs = pickDatasource(updatedDetail.body);
      const updatedTotal = updatedDs.totalRows ?? updatedDs.total;
      expect(updatedTotal).toBe(3);

      // --- Create api-type datasource to test refresh and failure distinction ---
      const failed = await request('POST', '/api/datasources', {
        name: `vt-preview-failed-${Date.now()}`,
        sourceType: 'api',
        url: 'https://non-existent.invalid/data.json',
      });
      expect([200, 201]).toContain(failed.res.status);
      failedId = pickId(failed.body);
      expect(failedId, `expected api datasource to be created, got ${JSON.stringify(failed.body)}`).toBeTruthy();

      // Try to refresh preview for the api datasource
      const refreshRes = await request('POST', `/api/datasources/${failedId}/refresh`, {});
      // Refresh may return various codes depending on implementation; we don't require success here
      // But the endpoint should exist and respond
      expect(refreshRes.res.status).toBeDefined();

      // Verify that the failed datasource detail shows a failure state distinct from empty
      const failedDetail = await request('GET', `/api/datasources/${failedId}`);
      expect(failedDetail.res.status).toBe(200);
      const failedDs = pickDatasource(failedDetail.body);

      // The failed datasource should have a status/error that distinguishes it from empty
      const failedStatus = failedDs.status;
      const failedError = failedDs.error ?? failedDs.lastError ?? failedDs.errorMessage;
      const hasFailureIndicator = failedStatus === 'refresh_failed' || failedStatus === 'error' || !!failedError;
      expect(hasFailureIndicator, `expected failed datasource to have distinct failure indicator vs empty datasource, got ${JSON.stringify(failedDs)}`).toBe(true);

      // Confirm that empty datasource and failed datasource have different status/messaging
      const emptyIndicator = emptyDs.status ?? 'ok';
      const failIndicator = failedDs.status ?? failedDs.error ?? failedDs.lastError;
      expect(String(failIndicator)).not.toBe(String(emptyIndicator));

    } finally {
      await safeDeleteDatasource(dataId);
      await safeDeleteDatasource(emptyId);
      await safeDeleteDatasource(failedId);
    }
  });
});

