import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function request(method, path, body) {
  const res = await fetch(`${BASE_URL}${path}`, {
    method,
    headers: { 'Content-Type': 'application/json' },
    body: body === undefined ? undefined : JSON.stringify(body),
  });
  const text = await res.text();
  let json;
  try {
    json = text ? JSON.parse(text) : null;
  } catch {
    json = text;
  }
  return { res, body: json, text };
}

function pickId(payload) {
  return payload?.id ?? payload?.data?.id ?? payload?.chart?.id ?? payload?.dashboard?.id;
}

function pickList(payload) {
  if (Array.isArray(payload)) return payload;
  if (Array.isArray(payload?.items)) return payload.items;
  if (Array.isArray(payload?.data)) return payload.data;
  if (Array.isArray(payload?.data?.items)) return payload.data.items;
  if (Array.isArray(payload?.types)) return payload.types;
  if (Array.isArray(payload?.chartTypes)) return payload.chartTypes;
  return [];
}

function pickTotal(payload) {
  return payload?.total ?? payload?.count ?? payload?.data?.total ?? payload?.data?.count ?? null;
}

function pickChart(payload) {
  return payload?.chart ?? payload?.data ?? payload;
}

async function safeDeleteDashboard(id) {
  if (!id) return;
  try {
    await fetch(`${BASE_URL}/api/dashboards/${id}`, { method: 'DELETE' });
  } catch {}
}

async function editChart(dashboardId, chartId, body) {
  let edit = await request('PATCH', `/api/dashboards/${dashboardId}/charts/${chartId}`, body);
  if ([200, 204].includes(edit.res.status)) return edit;
  edit = await request('PUT', `/api/dashboards/${dashboardId}/charts/${chartId}`, body);
  if ([200, 204].includes(edit.res.status)) return edit;
  edit = await request('PATCH', `/api/charts/${chartId}`, body);
  if ([200, 204].includes(edit.res.status)) return edit;
  edit = await request('PUT', `/api/charts/${chartId}`, body);
  return edit;
}

async function fetchChart(dashboardId, chartId) {
  let r = await request('GET', `/api/dashboards/${dashboardId}/charts/${chartId}`);
  if (r.res.status === 200) return r;
  r = await request('GET', `/api/charts/${chartId}`);
  return r;
}

