      // switching filters changes the visible count and content
      // ============================================================
      const libCategoryBasic = await request('GET', '/api/chart-library?category=basic');
      expect(libCategoryBasic.res.status).toBe(200);
      const basicItems = pickList(libCategoryBasic.body);
      const basicTotal = pickTotal(libCategoryBasic.body);
      expect(basicItems.length).toBeGreaterThan(0);
      // Filtered results should be a subset of all
      expect(basicItems.length).toBeLessThanOrEqual(allItems.length);
      // If total field present, it should match list length
      if (basicTotal !== null) {
        expect(basicTotal).toBe(basicItems.length);
      }

      // Second category filter to verify switching filters changes results
      const libCategoryAdvanced = await request('GET', '/api/chart-library?category=advanced');
      expect(libCategoryAdvanced.res.status).toBe(200);
