      ).toBe(true);

      // ============================================================
      // STEP 6: Old chart still exists and is editable after library
      // operations (verifies old charts are not lost or broken)
      // ============================================================
      const oldChartAfterLib = await fetchChart(dashboardId, chartId);
      expect(oldChartAfterLib.res.status).toBe(200);
      const oldChartAfterLibData = pickChart(oldChartAfterLib.body);
      expect(oldChartAfterLibData.title).toBe('legacy chart');
      expect(oldChartAfterLibData.type).toBe('bar');

      // Edit the old chart to verify it's still editable
      const edit = await editChart(dashboardId, chartId, {
        title: 'legacy chart updated',
        type: 'bar',
        data: [{ label: 'old', value: 2 }],
      });
      expect([200, 204]).toContain(edit.res.status);

      // Verify the update persisted
      const afterEdit = await fetchChart(dashboardId, chartId);
      expect(afterEdit.res.status).toBe(200);
      const afterEditChart = pickChart(afterEdit.body);
      expect(afterEditChart.title).toBe('legacy chart updated');
      expect(afterEditChart.type).toBe('bar');
      const editedData = afterEditChart.data ?? afterEditChart.previewData;
      expect(editedData).toBeTruthy();
      if (Array.isArray(editedData)) {
        expect(editedData.some(d => Number(d.value ?? d.amount ?? d.count) === 2)).toBe(true);
      }
    } finally {
      await safeDeleteDashboard(dashboardId);
    }
  });
});

import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function request(method, path, body) {
  const res = await fetch(`${BASE_URL}${path}`, {
    method,
    headers: { 'Content-Type': 'application/json' },
    body: body === undefined ? undefined : JSON.stringify(body),
  });
  const text = await res.text();
  let json;
  try {
    json = text ? JSON.parse(text) : null;
  } catch {
    json = text;
  }
  return { res, body: json };
}

function pickId(payload) {
  return payload?.id ?? payload?.data?.id ?? payload?.chart?.id ?? payload?.dashboard?.id;
}

function pickChart(payload) {
  return payload?.chart ?? payload?.data ?? payload;
}

async function safeDeleteDashboard(id) {
  if (!id) return;
  try {
    await fetch(`${BASE_URL}/api/dashboards/${id}`, { method: 'DELETE' });
  } catch {}
}

// Try multiple possible paths for getting a chart
async function getChart(dashboardId, chartId) {
  let r = await request('GET', `/api/dashboards/${dashboardId}/charts/${chartId}`);
  if (r.res.status === 200) return r;
  r = await request('GET', `/api/charts/${chartId}`);
  return r;
}

// Try multiple possible paths for patching a chart
async function patchChart(dashboardId, chartId, body) {
  let r = await request('PATCH', `/api/dashboards/${dashboardId}/charts/${chartId}`, body);
  if ([200, 204].includes(r.res.status)) return r;
  r = await request('PATCH', `/api/charts/${chartId}`, body);
  if ([200, 204].includes(r.res.status)) return r;
  r = await request('PUT', `/api/dashboards/${dashboardId}/charts/${chartId}`, body);
  if ([200, 204].includes(r.res.status)) return r;
  r = await request('PUT', `/api/charts/${chartId}`, body);
  return r;
}

describe('round5_chart_config_save', () => {
  it('should save chart config updates and keep original value unchanged when not saved', async () => {
    let dashboardId;
    let chartId;
    const initialData = [{ label: 'A', value: 1 }, { label: 'B', value: 2 }];
    const updatedData = [{ label: 'C', value: 30 }, { label: 'D', value: 40 }];

    try {
      const dashboard = await request('POST', '/api/dashboards', {
        name: `vt-chart-save-${Date.now()}`,
        description: 'chart config save',
      });
      expect([200, 201]).toContain(dashboard.res.status);
      dashboardId = pickId(dashboard.body);

      const chart = await request('POST', `/api/dashboards/${dashboardId}/charts`, {
        title: 'original-title',
        type: 'bar',
        data: initialData,
      });
      expect([200, 201]).toContain(chart.res.status);
      chartId = pickId(chart.body);

      // Verify initial state
      const before = await getChart(dashboardId, chartId);
      expect(before.res.status).toBe(200);
      const beforeChart = pickChart(before.body);
      expect(beforeChart.title).toBe('original-title');
      expect(beforeChart.type).toBe('bar');

      // "Cancel" scenario: simulate cancel by NOT calling any save/PATCH endpoint.
      // In a pure API context, cancel means the client discards local edits and never
      // sends a save request. We verify the server-side state is still the original.
      const cancelCandidateTitle = 'draft-not-saved';
      const notSavedCheck = await getChart(dashboardId, chartId);
      expect(notSavedCheck.res.status).toBe(200);
      const stillOriginal = pickChart(notSavedCheck.body);
      expect(stillOriginal.title).not.toBe(cancelCandidateTitle);
      expect(stillOriginal.title).toBe('original-title');
      expect(stillOriginal.type).toBe('bar');

      // --- Boundary: empty title should be rejected with meaningful error message ---
      const emptyTitleRes = await patchChart(dashboardId, chartId, {
        title: '',
        type: 'bar',
      });
      expect([400, 422]).toContain(emptyTitleRes.res.status);
      // Verify the failure response contains a meaningful error message
      const emptyTitleBody = emptyTitleRes.body;
      const emptyTitleErrorText = JSON.stringify(emptyTitleBody);
      const hasEmptyTitleError = emptyTitleBody?.message || emptyTitleBody?.error || emptyTitleBody?.errors;
      expect(hasEmptyTitleError, `expected error message for empty title, got: ${emptyTitleErrorText}`).toBeTruthy();

      // --- Boundary: over-long title (>50 chars) should be rejected with meaningful error message ---
      const longTitle = 'T'.repeat(51);
      const longTitleRes = await patchChart(dashboardId, chartId, {
        title: longTitle,
        type: 'bar',
      });
      expect([400, 422]).toContain(longTitleRes.res.status);
      const longTitleBody = longTitleRes.body;
      const longTitleErrorText = JSON.stringify(longTitleBody);
      const hasLongTitleError = longTitleBody?.message || longTitleBody?.error || longTitleBody?.errors;
      expect(hasLongTitleError, `expected error message for long title, got: ${longTitleErrorText}`).toBeTruthy();

      // Verify original chart is unaffected after failed updates
      const afterFailed = await getChart(dashboardId, chartId);
      expect(afterFailed.res.status).toBe(200);
      const afterFailedChart = pickChart(afterFailed.body);
      expect(afterFailedChart.title).toBe('original-title');
      expect(afterFailedChart.type).toBe('bar');

      // --- Boundary: title exactly at 50 chars should be accepted ---
      const exactTitle = 'X'.repeat(50);
      const exactTitleRes = await patchChart(dashboardId, chartId, {
        title: exactTitle,
        type: 'bar',
      });
      expect([200, 204]).toContain(exactTitleRes.res.status);
      // Restore original title for the next test step
      const restoreRes = await patchChart(dashboardId, chartId, {
        title: 'original-title',
        type: 'bar',
        data: initialData,
      });
      expect([200, 204]).toContain(restoreRes.res.status);

      // --- Happy path: save valid update (title, type, and sample data) ---
      const saveRes = await patchChart(dashboardId, chartId, {
        title: 'updated-title',
        type: 'line',
        data: updatedData,
      });
      expect([200, 204]).toContain(saveRes.res.status);

      const after = await getChart(dashboardId, chartId);
      expect(after.res.status).toBe(200);
      const afterChart = pickChart(after.body);
      expect(afterChart.title).toBe('updated-title');
      expect(afterChart.type).toBe('line');

      // Verify data/previewData is present and matches the updated data structurally
      const actualData = afterChart.data ?? afterChart.previewData;
      expect(actualData, `expected chart data or previewData after save, got ${JSON.stringify(afterChart)}`).toBeTruthy();
      expect(Array.isArray(actualData)).toBe(true);
      expect(actualData.length).toBe(updatedData.length);
      // Structural assertion: check elements match
      for (let i = 0; i < updatedData.length; i++) {
        const item = actualData[i];
        expect(item.label ?? item.name ?? item.category).toBe(updatedData[i].label);
        expect(Number(item.value ?? item.amount ?? item.count)).toBe(updatedData[i].value);
      }

      // Verify legend/legend info is present and reflects updated data if available
      const legend = afterChart.legend ?? afterChart.legendItems ?? afterChart.legends;
      if (legend) {
        const legendText = JSON.stringify(legend);
        expect(legendText).toContain('C');
        expect(legendText).toContain('D');
      }
    } finally {
      await safeDeleteDashboard(dashboardId);
    }
  });
});

import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function request(method, path, body, extraHeaders = {}) {
