describe('round21_end_to_end_persistence', () => {
  it('should persist data source, dashboard, multiple chart bindings, filters, layout, sharing and export/import without affecting old dashboards', async () => {
    const oldDashboardName = randomName('old-dashboard');
    const dsName = randomName('source');
    const dashboardName = randomName('e2e-dashboard');
    let oldDashboardId;
    let dataSourceId;
    let dashboardId;
    let importedDashboardId;
    let legacyImportedId;
    let shareToken;

    // Create old dashboard that should not be affected
    const oldDashboard = await request('POST', '/api/dashboards', {
      name: oldDashboardName,
