      // --- Step 2: Create dashboard with multiple charts, bindings, filters, layout ---
      const createDashboard = await request('POST', '/api/dashboards', {
        name: dashboardName,
        layout: [
          { i: 'chart-main', x: 1, y: 2, w: 8, h: 5 },
          { i: 'chart-secondary', x: 0, y: 0, w: 4, h: 3 },
