        charts: [
          {
            id: 'chart-main',
            type: 'bar',
            title: 'Main Chart',
            dataSourceId,
            bindings: { x: 'region', y: 'sales' },
          },
          {
            id: 'chart-secondary',
            type: 'line',
            title: 'Secondary Chart',
            dataSourceId,
            bindings: { x: 'month', y: 'revenue' },
          },
