      const share = await request('POST', `/api/dashboards/${dashboardId}/share`, { mode: 'link_view', readonly: true });
      expect([200, 201]).toContain(share.res.status);
      shareToken = share.body?.token || share.body?.shareToken || share.body?.id || share.body?.link;
      expect(shareToken, `share token missing: ${JSON.stringify(share.body)}`).toBeTruthy();

      // --- Step 4: Export ---
      const exported = await request('GET', `/api/dashboards/${dashboardId}/export`);
      expect(exported.res.status).toBe(200);
      const archive = exported.body?.dashboard ? exported.body : { version: exported.body?.version || 'current', dashboard: exported.body };
      expect(JSON.stringify(archive)).toContain(dashboardName);

      // --- Step 5: Simulate page refresh - re-fetch and verify ---
      const refreshLikeReload = await request('GET', `/api/dashboards/${dashboardId}`);
      expect(refreshLikeReload.res.status).toBe(200);
      const refreshed = refreshLikeReload.body?.dashboard || refreshLikeReload.body;
      expect(refreshed.name).toBe(dashboardName);
      expect(Array.isArray(refreshed.layout)).toBe(true);
      expect(refreshed.layout.length).toBeGreaterThanOrEqual(2);
      expect(refreshed.layout[0]?.w).toBe(8);
      expect(Array.isArray(refreshed.charts)).toBe(true);
      expect(refreshed.charts.length).toBeGreaterThanOrEqual(2);
      expect(refreshed.charts[0]?.bindings?.x).toBe('region');
