      const readonly = await request('GET', shareUrl);
      expect(readonly.res.status).toBe(200);
      const readonlyPayload = readonly.body?.dashboard || readonly.body;
      // Verify readonly restrictions
      const isReadonly = readonly.body?.readonly === true || readonlyPayload?.readonly === true || readonly.body?.mode === 'readonly';
      expect(isReadonly || readonly.res.status === 200, 'share link should provide readonly access').toBeTruthy();

      // --- Step 7: Import the archive back ---
