      const oldPayload = oldDashboardGet.body?.dashboard || oldDashboardGet.body;
      expect(oldPayload.name, 'old dashboard should remain unchanged and not be overwritten').toBe(oldDashboardName);
      expect(oldPayload.charts[0]?.title).toBe('Old');

      // --- Step 9: Verify original dashboard share token still works ---
      const shareAfterImport = await request('GET', shareUrl);
      expect(shareAfterImport.res.status, 'original share link should still work after import').toBe(200);

      // --- Step 10: Import a legacy archive and verify defaults are filled ---
      const legacyArchive = {
        version: '0.9',
        dashboard: {
          name: randomName('legacy-e2e'),
          description: 'Legacy simple dashboard',
          charts: [
            {
              id: 'legacy-chart-1',
              type: 'bar',
              title: 'Legacy Chart',
            },
          ],
        },
      };

      const legacyImport = await request('POST', '/api/import', { ...legacyArchive, conflict: 'rename' });
      expect([200, 201, 207], `legacy import failed: ${legacyImport.res.status} ${legacyImport.text}`).toContain(legacyImport.res.status);
      legacyImportedId = legacyImport.body?.dashboardId || legacyImport.body?.id || legacyImport.body?.dashboard?.id || legacyImport.body?.created?.[0]?.id;
      expect(legacyImportedId, `legacy imported id missing: ${JSON.stringify(legacyImport.body)}`).toBeTruthy();

      const legacyGet = await request('GET', `/api/dashboards/${legacyImportedId}`);
      expect(legacyGet.res.status).toBe(200);
      const legacyPayload = legacyGet.body?.dashboard || legacyGet.body;

      // Filters should be defaulted
      expect(Array.isArray(legacyPayload.filters), 'legacy import should default filters to empty array').toBe(true);

      // Visibility should be defaulted to private
      const legacyVisibility = legacyPayload.visibility ?? legacyPayload.share?.mode ?? legacyPayload.shareMode;
      expect(
        legacyVisibility === 'private' || legacyVisibility === undefined || legacyVisibility === null,
        `legacy import should default visibility to private, got: ${legacyVisibility}`
      ).toBe(true);

      // Charts should still be there
      expect(Array.isArray(legacyPayload.charts)).toBe(true);
      expect(legacyPayload.charts.length).toBeGreaterThan(0);
      expect(legacyPayload.charts[0]?.title).toBe('Legacy Chart');
    } finally {
      if (legacyImportedId) await cleanup(`/api/dashboards/${legacyImportedId}`);
      if (importedDashboardId) await cleanup(`/api/dashboards/${importedDashboardId}`);
      if (dashboardId) await cleanup(`/api/dashboards/${dashboardId}`);
      if (oldDashboardId) await cleanup(`/api/dashboards/${oldDashboardId}`);
      if (dataSourceId) {
        await cleanup(`/api/datasources/${dataSourceId}`);
        await cleanup(`/api/data-sources/${dataSourceId}`);
      }
    }
  });
});

