describe('history_versions_capped_at_twenty', () => {
  it('should retain only the most recent 20 history versions without affecting current content or comments', async () => {
    let documentId;
    try {
      const createDoc = await request('POST', '/documents', {
        title: `history-cap-${Date.now()}`,
        content: 'current-content-v0'
      });
      expect(createDoc.res.status, `expected create document 200/201, got ${createDoc.res.status}`).toBeOneOf([200, 201]);
      documentId = createDoc.body.id || createDoc.body.documentId;
      expect(documentId, `expected document id from ${JSON.stringify(createDoc.body)}`).toBeTruthy();

      const commentCreate = await request('POST', `/documents/${documentId}/comments`, {
        author: 'qa-user',
        content: 'comment should remain',
        anchorType: 'document'
      });
      expect(commentCreate.res.status, `expected create comment 200/201, got ${commentCreate.res.status}`).toBeOneOf([200, 201]);

      for (let i = 1; i <= 25; i++) {
        const update = await request('PUT', `/documents/${documentId}`, {
          title: `history-cap-${Date.now()}`,
          content: `current-content-v${i}`
        });
        expect(update.res.status, `expected update status 200/204 on iteration ${i}, got ${update.res.status}`).toBeOneOf([200, 204]);

        const saveVersion = await request('POST', `/documents/${documentId}/history`, {
          label: `save-${i}`,
          content: `snapshot-content-v${i}`
        });
        expect(saveVersion.res.status, `expected history save 200/201 on iteration ${i}, got ${saveVersion.res.status}`).toBeOneOf([200, 201]);
      }

      const historyRes = await request('GET', `/documents/${documentId}/history`);
      expect(historyRes.res.status, `expected history fetch 200, got ${historyRes.res.status}`).toBe(200);
      expect(Array.isArray(historyRes.body), `expected history array, got ${JSON.stringify(historyRes.body)}`).toBe(true);
      expect(historyRes.body.length, `expected only latest 20 versions retained, got ${historyRes.body.length}`).toBeLessThanOrEqual(20);
      expect(historyRes.body.length, `expected 20 versions after saving 25, got ${historyRes.body.length}`).toBe(20);

      const labels = historyRes.body.map(v => v.label || v.name || v.id);
      expect(labels.some(v => String(v).includes('save-1')), `expected oldest save-1 to be trimmed, labels=${JSON.stringify(labels)}`).toBe(false);
      expect(labels.some(v => String(v).includes('save-5')), `expected save-5 to be trimmed, labels=${JSON.stringify(labels)}`).toBe(false);
      expect(labels.some(v => String(v).includes('save-6')), `expected save-6 to remain, labels=${JSON.stringify(labels)}`).toBe(true);
      expect(labels.some(v => String(v).includes('save-25')), `expected newest save-25 to remain, labels=${JSON.stringify(labels)}`).toBe(true);

      const getDoc = await request('GET', `/documents/${documentId}`);
      expect(getDoc.res.status, `expected get document 200, got ${getDoc.res.status}`).toBe(200);
      expect(getDoc.body.content, `expected current content unaffected and equal current-content-v25, got ${getDoc.body.content}`).toBe('current-content-v25');

      const commentsRes = await request('GET', `/documents/${documentId}/comments`);
      expect(commentsRes.res.status, `expected comments fetch 200, got ${commentsRes.res.status}`).toBe(200);
      expect(Array.isArray(commentsRes.body), 'expected comments array').toBe(true);
      expect(commentsRes.body.length, `expected existing comments preserved, got ${commentsRes.body.length}`).toBe(1);
      expect(commentsRes.body[0].content, `expected preserved comment content, got ${commentsRes.body[0]?.content}`).toBe('comment should remain');
    } finally {
      await cleanupDocument(documentId);
    }
  });
});

