import { describe, it, expect, beforeAll, afterAll } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function safeJson(res) {
  const text = await res.text();
  try {
    return text ? JSON.parse(text) : null;
  } catch {
    return { raw: text };
  }
}

async function tryDelete(path) {
  try {
    await fetch(`${BASE_URL}${path}`, { method: 'DELETE' });
  } catch { /* ignore */ }
}

function extractArray(data) {
  if (Array.isArray(data)) return data;
  if (data && typeof data === 'object') {
    for (const key of ['items', 'comments', 'data', 'results', 'threads']) {
      if (Array.isArray(data[key])) return data[key];
    }
  }
  return [];
}

function extractId(body) {
  return body?.id || body?.document?.id || body?.data?.id || body?._id || body?.documentId || null;
}

function extractCommentId(body) {
  return body?.id || body?.comment?.id || body?.data?.id || body?._id || null;
}

async function createDocument(title, content) {
  const res = await fetch(`${BASE_URL}/api/documents`, {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify({ title, content, body: content })
  });
  expect([200, 201]).toContain(res.status);
  const body = await safeJson(res);
  const id = extractId(body);
  expect(id, `Should get document ID from creation of '${title}'`).toBeTruthy();
  return id;
}

async function addComment(docId, text) {
  const res = await fetch(`${BASE_URL}/api/documents/${docId}/comments`, {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify({ body: text, content: text, text: text })
  });
  expect([200, 201]).toContain(res.status);
  const body = await safeJson(res);
  const id = extractCommentId(body);
  expect(id, `Should get comment ID for '${text}'`).toBeTruthy();
  return id;
}

async function resolveComment(docId, commentId) {
  let res = await fetch(`${BASE_URL}/api/documents/${docId}/comments/${commentId}/resolve`, {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify({ resolved: true })
  }).catch(() => null);

  if (!res || res.status === 404) {
    res = await fetch(`${BASE_URL}/api/documents/${docId}/comments/${commentId}`, {
      method: 'PATCH',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify({ resolved: true })
    }).catch(() => null);
  }
  if (!res || res.status === 404) {
    res = await fetch(`${BASE_URL}/api/documents/${docId}/comments/${commentId}`, {
      method: 'PUT',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify({ resolved: true })
    }).catch(() => null);
  }
  expect(res, 'Resolve comment endpoint should be reachable').toBeTruthy();
  expect([200, 201, 204]).toContain(res.status);
}

async function unresolveComment(docId, commentId) {
  let res = await fetch(`${BASE_URL}/api/documents/${docId}/comments/${commentId}/reopen`, {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify({ resolved: false })
  }).catch(() => null);

  if (!res || res.status === 404) {
    res = await fetch(`${BASE_URL}/api/documents/${docId}/comments/${commentId}`, {
      method: 'PATCH',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify({ resolved: false })
    }).catch(() => null);
  }
  if (!res || res.status === 404) {
    res = await fetch(`${BASE_URL}/api/documents/${docId}/comments/${commentId}`, {
      method: 'PUT',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify({ resolved: false })
    }).catch(() => null);
  }
  expect(res, 'Unresolve/reopen comment endpoint should be reachable').toBeTruthy();
  expect([200, 201, 204]).toContain(res.status);
}

async function getComments(docId) {
  const res = await fetch(`${BASE_URL}/api/documents/${docId}/comments`);
  expect(res.status).toBe(200);
  const body = await safeJson(res);
  return extractArray(body);
}

