  for (const id of cleanupIds) {
    await tryDelete(`/api/documents/${id}`);
  }
});

describe('round4_comment_resolution_counts', () => {

  it('should create documents and comments, verify unresolved counts per document and independence', async () => {
    const suffix = `${Date.now()}-${Math.random().toString(36).slice(2, 7)}`;

    // Create two documents
    const doc1Id = await createDocument(`doc-a-${suffix}`, 'body a');
    const doc2Id = await createDocument(`doc-b-${suffix}`, 'body b');
    cleanupIds.push(doc1Id, doc2Id);

    // Add 2 comments to doc1, 1 comment to doc2
    const comment1Id = await addComment(doc1Id, 'open comment 1');
    const comment2Id = await addComment(doc1Id, 'will resolve');
    const comment3Id = await addComment(doc2Id, 'open comment 2');

    // Resolve comment2 in doc1
    await resolveComment(doc1Id, comment2Id);

    // Verify doc1 comments
    const arr1 = await getComments(doc1Id);
    expect(arr1.length, `Doc1 should have 2 comments, got ${arr1.length}`).toBe(2);

    const unresolved1 = arr1.filter(x => x?.resolved === false || (x?.resolved === undefined && x?.isResolved === undefined)).length;
    const resolved1 = arr1.filter(x => x?.resolved === true || x?.isResolved === true).length;
    expect(resolved1, 'Doc1 should have 1 resolved comment').toBe(1);
    expect(unresolved1, 'Doc1 should have 1 unresolved comment').toBeGreaterThanOrEqual(1);

    // Verify doc2 comments are independent and unaffected
    const arr2 = await getComments(doc2Id);
    expect(arr2.length, 'Doc2 should have 1 comment').toBe(1);
    const unresolved2 = arr2.filter(x => x?.resolved === false || (x?.resolved === undefined && x?.isResolved === undefined)).length;
    expect(unresolved2, 'Doc2 should have 1 unresolved comment').toBe(1);

    // Verify unresolved comments appear before resolved ones in the list
    if (arr1.length >= 2) {
      const firstResolved = arr1.findIndex(x => x?.resolved === true);
      const lastUnresolved = arr1.length - 1 - [...arr1].reverse().findIndex(x => x?.resolved === false || x?.resolved === undefined);
      if (firstResolved >= 0 && lastUnresolved >= 0) {
        expect(
          lastUnresolved < firstResolved || firstResolved === -1,
          'Resolved comments should appear after unresolved ones in the list'
        ).toBe(true);
      }
    }

    // Verify document detail includes unresolved count
    const docDetailRes = await fetch(`${BASE_URL}/api/documents/${doc1Id}`);
    if (docDetailRes.ok) {
      const detail = await safeJson(docDetailRes);
      const countValue = detail?.unresolvedCommentCount ??
        detail?.unresolved_comment_count ??
        detail?.unresolvedCount ??
        detail?.commentStats?.unresolved ??
        detail?.stats?.unresolvedComments;
      if (typeof countValue === 'number') {
        expect(countValue, 'Unresolved count on doc detail should be at least 1').toBeGreaterThanOrEqual(1);
      }
    }
  });

  it('should allow reopening a resolved comment and update counts', async () => {
    const suffix = `reopen-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`;

    const docId = await createDocument(`doc-reopen-${suffix}`, 'reopen test');
    cleanupIds.push(docId);

    const c1Id = await addComment(docId, 'comment to resolve and reopen');
    const c2Id = await addComment(docId, 'always open comment');

    // Resolve c1
    await resolveComment(docId, c1Id);

    // Verify c1 is resolved
    let comments = await getComments(docId);
    let resolvedComment = comments.find(c => c?.id === c1Id || c?._id === c1Id);
    if (resolvedComment) {
      expect(resolvedComment.resolved, 'Comment should be resolved').toBe(true);
    }

    // Reopen c1
    await unresolveComment(docId, c1Id);

    // Verify c1 is now unresolved
    comments = await getComments(docId);
    const reopenedComment = comments.find(c => c?.id === c1Id || c?._id === c1Id);
    if (reopenedComment) {
      expect(reopenedComment.resolved, 'Reopened comment should be unresolved (false)').toBe(false);
    }

