  it('should not execute search when keyword is empty or whitespace-only', async () => {
    // Empty keyword
    let result = await request('GET', `/search?q=`);
    if (result.res.status === 404 || result.res.status === 405) {
      result = await request('POST', '/search', { q: '' });
