import { describe, it, expect, afterAll } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function safeJson(res) {
  const text = await res.text();
  try {
    return text ? JSON.parse(text) : null;
  } catch {
    return { raw: text };
  }
}

async function request(method, path, body) {
  const opts = {
    method,
    headers: { 'Content-Type': 'application/json' },
  };
  if (body !== undefined) opts.body = JSON.stringify(body);
  const res = await fetch(`${BASE_URL}${path}`, opts);
  const json = await safeJson(res);
  return { res, body: json };
}

async function tryRequest(method, paths, body) {
  for (const path of paths) {
    try {
      const result = await request(method, path, body);
      if (result.res.status !== 404) return { ...result, path };
    } catch { /* try next */ }
  }
  return null;
}

const cleanupActions = [];

async function cleanup() {
  for (const action of cleanupActions) {
    try { await action(); } catch { /* ignore */ }
  }
}

afterAll(cleanup);

const importPaths = ['/api/import', '/imports', '/api/documents/import', '/api/workspaces/import'];
const docPaths = ['/api/documents', '/documents'];

function extractDocId(doc) {
  return doc?.id || doc?._id || doc?.documentId;
}

function extractImportedDocs(body) {
  return body?.documents ||
    body?.workspace?.documents ||
    body?.imported ||
    (Array.isArray(body) ? body : []);
}

