      // Create 23 history versions to exceed the 20-version cap
      for (let i = 1; i <= 23; i++) {
        const update = await request('PUT', `/documents/${docId}`, {
          title: `history-unchanged-${Date.now()}`,
          content: `live-content-${i}`
        });
        expect(update.res.status).toBeOneOf([200, 204]);
        const save = await request('POST', `/documents/${docId}/history`, {
          label: `checkpoint-${i}`,
          content: `snapshot-${i}`
        });
        expect(save.res.status).toBeOneOf([200, 201]);
      }

      // Verify history is capped at 20
      const history = await request('GET', `/documents/${docId}/history`);
      expect(history.res.status).toBe(200);
      expect(Array.isArray(history.body)).toBe(true);
      expect(history.body.length).toBeLessThanOrEqual(20);

      // Oldest versions should have been trimmed
      const allLabels = history.body.map(v => v.label || v.name || String(v.id));
      const allLabelsStr = allLabels.join(',');
      // checkpoint-1, 2, 3 should be gone (trimmed as oldest)
      expect(allLabelsStr).not.toContain('checkpoint-1,');
      expect(allLabelsStr).not.toContain('checkpoint-2,');
      expect(allLabelsStr).not.toContain('checkpoint-3,');
      // newest checkpoint should exist
      expect(history.body.some(v => {
        const l = v.label || v.name || String(v.id);
        return l.includes('checkpoint-23');
      })).toBe(true);

      // Verify preview does not change current content
      const target = history.body[0];
      const versionId = target.id || target.versionId;
      expect(versionId).toBeTruthy();

      const preview = await request('GET', `/documents/${docId}/history/${versionId}`);
      expect(preview.res.status).toBe(200);
      const previewContent = preview.body.content ?? preview.body.snapshotContent;
      expect(previewContent).toBeTruthy();

      // Current document content should remain live-content-23
      const currentDoc = await request('GET', `/documents/${docId}`);
      expect(currentDoc.res.status).toBe(200);
      expect(currentDoc.body.content).toBe('live-content-23');

      // Comments should be preserved
      const comments = await request('GET', `/documents/${docId}/comments`);
      expect(comments.res.status).toBe(200);
      const commentList = Array.isArray(comments.body) ? comments.body : (comments.body.comments || []);
      expect(commentList.length).toBeGreaterThanOrEqual(1);
      const ourComment = commentList.find(c => c.content === 'history must not affect me');
      expect(ourComment).toBeTruthy();
      expect(ourComment.resolved).toBe(false);
    } finally {
      await cleanupDocument(docId);
    }
  });

  it('should warn/block restore when there are unsaved modifications', async () => {
    let docId;
    try {
      // Create document and save a history version
      const createDoc = await request('POST', '/documents', {
        title: `restore-warn-${Date.now()}`,
        content: 'original-saved-content'
      });
      expect(createDoc.res.status).toBeOneOf([200, 201]);
      docId = createDoc.body.id || createDoc.body.documentId;
      expect(docId).toBeTruthy();

      // Save a history checkpoint
      const save1 = await request('POST', `/documents/${docId}/history`, {
        label: 'v1-checkpoint',
        content: 'original-saved-content'
      });
      expect(save1.res.status).toBeOneOf([200, 201]);

      // Update content to simulate unsaved modification
      const update = await request('PUT', `/documents/${docId}`, {
        content: 'unsaved-modification-in-progress'
      });
      expect(update.res.status).toBeOneOf([200, 204]);

      // Get the history version to restore
      const history = await request('GET', `/documents/${docId}/history`);
      expect(history.res.status).toBe(200);
      expect(history.body.length).toBeGreaterThanOrEqual(1);
      const versionId = history.body[0].id || history.body[0].versionId;
      expect(versionId).toBeTruthy();

      // Attempt to restore while there are unsaved changes
      // The API should either reject (409/conflict), require a force/confirm parameter,
      // or return a warning/prompt indicating unsaved changes exist
      const restoreAttempt = await request('POST', `/documents/${docId}/history/${versionId}/restore`, {
        force: false
      });

      const status = restoreAttempt.res.status;
      const bodyStr = JSON.stringify(restoreAttempt.body);

      const isBlocked = status === 409 || status === 400;
      const hasWarning = status === 200 && restoreAttempt.body && (
        restoreAttempt.body.confirmationRequired === true ||
        restoreAttempt.body.warning ||
        restoreAttempt.body.unsavedChanges === true ||
        restoreAttempt.body.requiresConfirmation === true
      );

      expect(
        isBlocked || hasWarning,
        `Expected restore to be blocked or warned about unsaved changes, got status=${status}, body=${bodyStr}`
      ).toBe(true);
    } finally {
      await cleanupDocument(docId);
    }
  });

  it('should only create a new history node after restored content is explicitly saved again', async () => {
    let docId;
    try {
      // Create document
      const createDoc = await request('POST', '/documents', {
        title: `restore-save-${Date.now()}`,
        content: 'content-v1'
      });
      expect(createDoc.res.status).toBeOneOf([200, 201]);
      docId = createDoc.body.id || createDoc.body.documentId;
      expect(docId).toBeTruthy();

      // Save two history checkpoints
      const save1 = await request('POST', `/documents/${docId}/history`, {
        label: 'v1',
        content: 'content-v1'
      });
      expect(save1.res.status).toBeOneOf([200, 201]);

      await request('PUT', `/documents/${docId}`, { content: 'content-v2' });
      const save2 = await request('POST', `/documents/${docId}/history`, {
        label: 'v2',
        content: 'content-v2'
      });
      expect(save2.res.status).toBeOneOf([200, 201]);

      // Get history count before restore
      const historyBefore = await request('GET', `/documents/${docId}/history`);
      expect(historyBefore.res.status).toBe(200);
      const countBefore = historyBefore.body.length;
      expect(countBefore).toBe(2);

      // Find v1 version
      const v1Entry = historyBefore.body.find(
        v => (v.label || v.name || '') === 'v1'
      );
      const versionId = v1Entry
        ? (v1Entry.id || v1Entry.versionId)
        : (historyBefore.body[historyBefore.body.length - 1].id || historyBefore.body[historyBefore.body.length - 1].versionId);

      expect(versionId).toBeTruthy();

      // Restore v1
      const restore = await request('POST', `/documents/${docId}/history/${versionId}/restore`, {
        force: true,
        confirm: true
      });
      expect(restore.res.status).toBeOneOf([200, 201, 204]);

      // After restore but BEFORE saving again, history count should NOT have increased
      const historyAfterRestore = await request('GET', `/documents/${docId}/history`);
      expect(historyAfterRestore.res.status).toBe(200);
      expect(
        historyAfterRestore.body.length,
        `History should not grow just from restoring (before save). Before=${countBefore}, after=${historyAfterRestore.body.length}`
      ).toBe(countBefore);

      // Now explicitly save, which should create a new history node
      const saveAfterRestore = await request('POST', `/documents/${docId}/history`, {
        label: 'v3-after-restore',
        content: 'content-v1'
      });
      expect(saveAfterRestore.res.status).toBeOneOf([200, 201]);

      const historyAfterSave = await request('GET', `/documents/${docId}/history`);
      expect(historyAfterSave.res.status).toBe(200);
      expect(
        historyAfterSave.body.length,
        `History should grow by 1 after explicit save. Before=${countBefore}, after=${historyAfterSave.body.length}`
      ).toBe(countBefore + 1);
    } finally {
      await cleanupDocument(docId);
    }
  });
});

import { describe, it, expect, beforeAll, afterAll } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function safeJson(res) {
  const text = await res.text();
  try {
    return text ? JSON.parse(text) : null;
  } catch {
    return { raw: text };
  }
}

async function request(method, path, body) {
  const opts = {
    method,
    headers: { 'Content-Type': 'application/json' },
  };
  if (body !== undefined) opts.body = JSON.stringify(body);
  const res = await fetch(`${BASE_URL}${path}`, opts);
  const json = await safeJson(res);
  return { res, body: json };
}

async function tryRequest(method, paths, body) {
  for (const path of paths) {
    try {
      const result = await request(method, path, body);
      if (result.res.status !== 404) return { ...result, path };
    } catch { /* try next */ }
  }
  return null;
}

const importPaths = ['/api/import', '/api/documents/import', '/api/workspaces/import', '/imports'];
const docPaths = ['/api/documents', '/documents'];

const cleanupIds = [];

async function cleanup() {
  for (const id of cleanupIds) {
    for (const base of docPaths) {
      try {
        await fetch(`${BASE_URL}${base}/${id}`, { method: 'DELETE' });
      } catch { /* ignore */ }
    }
  }
}

afterAll(cleanup);

function extractDocId(doc) {
  return doc?.id || doc?._id || doc?.documentId;
}

function extractImportedDocs(body) {
  return body?.documents ||
    body?.workspace?.documents ||
    body?.imported ||
    (Array.isArray(body) ? body : []);
}

describe('round15_share_permission_migration', () => {

  it('should map legacy "readonly" / "view_only" permission to "comment" on import while keeping other permissions unchanged', async () => {
    const uniqueSuffix = `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;

    const legacyPayload = {
      workspace: { name: 'default' },
      documents: [
        {
          title: `perm-readonly-${uniqueSuffix}`,
          content: 'Body for readonly doc',
          body: 'Body for readonly doc',
          sharing: {
            visibility: 'readonly',
            level: 'readonly',
            permission: 'readonly',
            users: [
              { userId: 'u-readonly', permission: 'readonly' },
              { userId: 'u-view', permission: 'view_only' }
            ]
          },
          comments: [],
          history: []
        },
        {
          title: `perm-private-${uniqueSuffix}`,
          content: 'Body for private doc',
          body: 'Body for private doc',
          sharing: {
            visibility: 'private',
            level: 'private',
            permission: 'private',
            users: []
          },
          comments: [],
          history: []
        },
        {
          title: `perm-editable-${uniqueSuffix}`,
          content: 'Body for editable doc',
          body: 'Body for editable doc',
          sharing: {
            visibility: 'editable',
            level: 'editable',
            permission: 'editable',
            users: [
              { userId: 'u-edit', permission: 'edit' },
              { userId: 'u-edit2', permission: 'editable' }
            ]
          },
          comments: [],
          history: []
        }
      ]
    };

    const importResult = await tryRequest('POST', importPaths, legacyPayload);
    expect(importResult, 'Import endpoint must be reachable to test permission migration').toBeTruthy();
    expect(
      [200, 201, 202].includes(importResult.res.status),
      `Import should succeed; got status ${importResult.res.status}, body: ${JSON.stringify(importResult.body)}`
    ).toBe(true);

    const importedDocs = extractImportedDocs(importResult.body);
    expect(Array.isArray(importedDocs) && importedDocs.length > 0,
      `Import response should contain an array of documents, got: ${JSON.stringify(importResult.body).substring(0, 500)}`
    ).toBe(true);

    for (const doc of importedDocs) {
      const id = extractDocId(doc);
      if (id) cleanupIds.push(id);
    }

    // === Verify readonly doc: permission should be mapped to comment ===
    const readonlyDoc = importedDocs.find(d => d.title?.includes('perm-readonly'));
    expect(readonlyDoc, 'Should find the readonly migration doc in import results').toBeTruthy();

    // Get sharing from import response or by querying the doc
    let readonlySharing = readonlyDoc.sharing || readonlyDoc.share || readonlyDoc.permissions;
    const readonlyDocId = extractDocId(readonlyDoc);
    if (!readonlySharing && readonlyDocId) {
      const sharingPaths = [
        `/api/documents/${readonlyDocId}/sharing`,
        `/api/documents/${readonlyDocId}`,
        `/documents/${readonlyDocId}/sharing`,
        `/documents/${readonlyDocId}`
      ];
      const docResult = await tryRequest('GET', sharingPaths);
      if (docResult && docResult.res.ok) {
        readonlySharing = docResult.body?.sharing || docResult.body?.share || docResult.body?.permissions || docResult.body;
      }
    }
    expect(readonlySharing, 'Should be able to retrieve sharing info for readonly doc').toBeTruthy();

    const readonlySharingStr = JSON.stringify(readonlySharing).toLowerCase();
    expect(
      !readonlySharingStr.includes('"readonly"') && !readonlySharingStr.includes('"view_only"'),
      `Legacy readonly/view_only permission should be migrated away, but found: ${readonlySharingStr}`
    ).toBe(true);
    expect(
      readonlySharingStr.includes('comment'),
      `Legacy readonly should map to comment-level, got: ${readonlySharingStr}`
    ).toBe(true);

    // Verify user-level permissions were also migrated
    const readonlyUsers = readonlySharing?.users || readonlyDoc.sharing?.users;
    if (Array.isArray(readonlyUsers) && readonlyUsers.length > 0) {
      for (const user of readonlyUsers) {
        const perm = (user.permission || user.role || '').toLowerCase();
        expect(
          perm !== 'readonly' && perm !== 'view_only',
          `User ${user.userId} should not have readonly/view_only, has: ${perm}`
        ).toBe(true);
        expect(
          perm.includes('comment'),
          `User ${user.userId} former readonly/view_only should map to comment, has: ${perm}`
        ).toBe(true);
      }
    }

    // === Verify private doc remains private ===
    const privateDoc = importedDocs.find(d => d.title?.includes('perm-private'));
    expect(privateDoc, 'Should find the private doc in import results').toBeTruthy();
    const privateSharing = privateDoc.sharing || privateDoc.share || privateDoc.permissions;
    if (privateSharing) {
      const privateSharingStr = JSON.stringify(privateSharing).toLowerCase();
      expect(
        privateSharingStr.includes('private'),
        `Private permission should remain private, got: ${privateSharingStr}`
      ).toBe(true);
    }

    // === Verify editable doc remains editable ===
    const editableDoc = importedDocs.find(d => d.title?.includes('perm-editable'));
    expect(editableDoc, 'Should find the editable doc in import results').toBeTruthy();
    const editableSharing = editableDoc.sharing || editableDoc.share || editableDoc.permissions;
    if (editableSharing) {
      const editableSharingStr = JSON.stringify(editableSharing).toLowerCase();
      expect(
        editableSharingStr.includes('edit'),
        `Editable permission should remain edit-level, got: ${editableSharingStr}`
      ).toBe(true);
      // Editable should NOT have been converted to comment
      const editableUsers = editableSharing?.users || editableDoc.sharing?.users;
      if (Array.isArray(editableUsers) && editableUsers.length > 0) {
        for (const user of editableUsers) {
          const perm = (user.permission || user.role || '').toLowerCase();
          expect(
            perm.includes('edit'),
            `User ${user.userId} should retain edit permission, has: ${perm}`
          ).toBe(true);
        }
      }
    }
  });

  it('should only expose three permission levels: private, comment, editable — setting readonly is rejected or auto-mapped', async () => {
    const createResult = await tryRequest('POST', docPaths, {
      title: `perm-check-${Date.now()}`,
      content: 'Test permission levels',
      body: 'Test permission levels'
    });
    expect(createResult, 'Should be able to create a document for permission level testing').toBeTruthy();
    expect(createResult.res.ok, `Document creation should succeed, got ${createResult.res.status}`).toBe(true);

    const docId = extractDocId(createResult.body);
    expect(docId, 'Should get a document ID after creation').toBeTruthy();
    cleanupIds.push(docId);

    const sharingPaths = [
      `/api/documents/${docId}/sharing`,
      `/documents/${docId}/sharing`,
      `/api/documents/${docId}/share`,
      `/documents/${docId}/share`
    ];

    // Try setting readonly — should be rejected or auto-mapped to comment
    const setReadonly = await tryRequest('PUT', sharingPaths, {
      visibility: 'readonly',
      level: 'readonly',
      permission: 'readonly'
    });

    if (setReadonly && setReadonly.res.status !== 404 && setReadonly.res.status !== 405) {
      if (setReadonly.res.ok) {
        // If accepted, it must have been auto-mapped — verify no 'readonly' stored
        const resultStr = JSON.stringify(setReadonly.body).toLowerCase();
        expect(
          !resultStr.includes('"readonly"'),
          `Setting readonly should be auto-mapped to comment, not stored as-is: ${resultStr}`
        ).toBe(true);
        expect(
          resultStr.includes('comment'),
          `Auto-mapped readonly should become comment: ${resultStr}`
        ).toBe(true);
      } else {
        // Rejected is acceptable
        expect(
          [400, 422].includes(setReadonly.res.status),
          `Readonly should be rejected with 400/422, got ${setReadonly.res.status}`
        ).toBe(true);
      }
    }

    // Verify valid levels work: private
    const setPrivate = await tryRequest('PUT', sharingPaths, {
      visibility: 'private',
      level: 'private'
    });
    if (setPrivate && setPrivate.res.status !== 404 && setPrivate.res.status !== 405) {
      expect(
        [200, 201, 204].includes(setPrivate.res.status),
        `Setting private should succeed, got ${setPrivate.res.status}`
      ).toBe(true);
    }

    // Verify valid levels work: comment
    const setComment = await tryRequest('PUT', sharingPaths, {
      visibility: 'comment',
      level: 'comment'
    });
    if (setComment && setComment.res.status !== 404 && setComment.res.status !== 405) {
      expect(
        [200, 201, 204].includes(setComment.res.status),
        `Setting comment should succeed, got ${setComment.res.status}`
      ).toBe(true);
    }

    // Verify valid levels work: editable
    const setEditable = await tryRequest('PUT', sharingPaths, {
      visibility: 'editable',
      level: 'editable'
    });
    if (setEditable && setEditable.res.status !== 404 && setEditable.res.status !== 405) {
      expect(
        [200, 201, 204].includes(setEditable.res.status),
        `Setting editable should succeed, got ${setEditable.res.status}`
      ).toBe(true);
    }
  });
});

import { describe, it, expect, beforeAll, afterAll } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function safeJson(res) {
  const text = await res.text();
  try {
    return text ? JSON.parse(text) : null;
  } catch {
    return { raw: text };
  }
}

async function tryDelete(path) {
  try {
    await fetch(`${BASE_URL}${path}`, { method: 'DELETE' });
  } catch {}
}

function extractId(body) {
  return body?.id || body?.workspace?.id || body?.data?.id || null;
}

function extractArray(data) {
  if (Array.isArray(data)) return data;
  if (data && typeof data === 'object') {
    for (const key of ['items', 'workspaces', 'documents', 'data', 'results', 'members', 'collaborators']) {
      if (Array.isArray(data[key])) return data[key];
    }
  }
  return [];
}

async function listDocsByWorkspace(workspaceId) {
  let res = await fetch(`${BASE_URL}/api/workspaces/${workspaceId}/documents`).catch(() => null);
  if (!res || res.status === 404) {
    res = await fetch(`${BASE_URL}/api/documents?workspaceId=${workspaceId}`).catch(() => null);
  }
  expect(res, 'Document list endpoint should be reachable').toBeTruthy();
  if (res && res.ok) {
    return extractArray(await safeJson(res));
  }
  return [];
}

describe('round16_workspace_migration_and_scope', () => {
