    expect(wsRes, 'GET /api/workspaces should be reachable').toBeTruthy();
    expect(wsRes.ok, `GET /api/workspaces should succeed, got ${wsRes?.status}`).toBe(true);

    const wsBody = await safeJson(wsRes);
    const workspaces = extractArray(wsBody);
    expect(workspaces.length, 'Should have at least one (default) workspace').toBeGreaterThanOrEqual(1);

    const defaultWs = workspaces.find(w =>
      w.isDefault === true || w.is_default === true ||
      (w.name && (w.name.toLowerCase().includes('default') || w.name.toLowerCase().includes('我的') || w.name.toLowerCase().includes('个人')))
    ) || workspaces[0];

    defaultWorkspaceId = defaultWs.id || defaultWs.workspaceId;
