  it('should isolate document lists by workspace', async () => {
    expect(defaultWorkspaceId).toBeTruthy();
    expect(secondWorkspaceId, 'Second workspace should be created').toBeTruthy();

    const uniqueDefault = `ws-default-${Date.now()}`;
    const uniqueSecond = `ws-second-${Date.now()}`;

