        title: uniqueDefault,
        content: 'default ws doc',
        body: 'default ws doc',
        workspaceId: defaultWorkspaceId
      })
    });
    expect([200, 201]).toContain(docRes1.status);
    const d1 = await safeJson(docRes1);
    const did1 = d1?.id || d1?.document?.id || d1?.data?.id;
    if (did1) cleanupDocIds.push(did1);

    // Create a document in second workspace
    const docRes2 = await fetch(`${BASE_URL}/api/documents`, {
