    // List documents for each workspace
    const defaultDocs = await listDocsByWorkspace(defaultWorkspaceId);
    const secondDocs = await listDocsByWorkspace(secondWorkspaceId);

    // Ensure documents are isolated - no overlap by id
    const defaultIds = new Set(defaultDocs.map(d => d.id));
    const secondIds = new Set(secondDocs.map(d => d.id));
