import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function request(method, path, body) {
  const res = await fetch(`${BASE_URL}${path}`, {
    method,
    headers: { 'Content-Type': 'application/json' },
    body: body === undefined ? undefined : JSON.stringify(body),
  });
  const text = await res.text();
  let json;
  try {
    json = text ? JSON.parse(text) : null;
  } catch (e) {
    json = text;
  }
  return { res, body: json };
}

async function cleanupDocument(documentId) {
  if (!documentId) return;
  try {
    await fetch(`${BASE_URL}/documents/${documentId}`, { method: 'DELETE' });
  } catch (e) { /* ignore */ }
}

function getSummaryValue(entry) {
  return entry.summary || entry.changes || entry.changeSummary ||
    entry.changeTypes || entry.changeType || entry.description;
}

function summaryContains(summaryVal, keyword) {
  if (!summaryVal) return false;
  const str = typeof summaryVal === 'string' ? summaryVal.toLowerCase() : JSON.stringify(summaryVal).toLowerCase();
  return str.includes(keyword.toLowerCase());
}

