import { describe, it, expect, afterAll } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function safeJson(res) {
  const text = await res.text();
  try {
    return text ? JSON.parse(text) : null;
  } catch {
    return { raw: text };
  }
}

async function tryDelete(path) {
  try {
    await fetch(`${BASE_URL}${path}`, { method: 'DELETE' });
  } catch {}
}

function extractId(body) {
  return body?.id || body?.document?.id || body?.data?.id || body?.workspace?.id || null;
}

function extractArray(data) {
  if (Array.isArray(data)) return data;
  if (data && typeof data === 'object') {
    for (const key of ['items', 'documents', 'data', 'results', 'comments', 'versions', 'history']) {
      if (Array.isArray(data[key])) return data[key];
    }
  }
  return [];
}

async function doExport(docId) {
  let exportRes = await fetch(`${BASE_URL}/api/documents/${docId}/export`).catch(() => null);
  if (!exportRes || exportRes.status === 404) {
    exportRes = await fetch(`${BASE_URL}/api/export`, {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify({ documentIds: [docId] })
    }).catch(() => null);
  }
  if (!exportRes || exportRes.status === 404) {
    exportRes = await fetch(`${BASE_URL}/api/workspaces/default/export`).catch(() => null);
  }
  expect(exportRes, 'At least one export endpoint must be reachable').toBeTruthy();
  expect(exportRes.ok, `Export should succeed, got status ${exportRes?.status}`).toBe(true);
  return exportRes;
}

async function doImport(data) {
  let importRes = await fetch(`${BASE_URL}/api/import`, {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify(data)
  }).catch(() => null);

  if (!importRes || importRes.status === 404) {
    importRes = await fetch(`${BASE_URL}/api/documents/import`, {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify(data)
    }).catch(() => null);
  }
  expect(importRes, 'At least one import endpoint must be reachable').toBeTruthy();
  return importRes;
}

