import { describe, it, expect, beforeAll, afterAll } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function safeJson(res) {
  const text = await res.text();
  try {
    return text ? JSON.parse(text) : null;
  } catch {
    return { raw: text };
  }
}

async function tryDelete(path) {
  try {
    await fetch(`${BASE_URL}${path}`, { method: 'DELETE' });
  } catch {}
}

function extractId(body) {
  return body?.id || body?.document?.id || body?.data?.id || null;
}

function extractArray(data) {
  if (Array.isArray(data)) return data;
  if (data && typeof data === 'object') {
    for (const key of ['items', 'versions', 'history', 'data', 'results']) {
      if (Array.isArray(data[key])) return data[key];
    }
  }
  return [];
}

async function createDocument(title, content) {
  const createRes = await fetch(`${BASE_URL}/api/documents`, {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify({ title, content, body: content })
  });
  expect(createRes, 'POST /api/documents should be reachable').toBeTruthy();
  expect([200, 201]).toContain(createRes.status);
  const createBody = await safeJson(createRes);
  const id = extractId(createBody);
  expect(id, `Missing document id: ${JSON.stringify(createBody)}`).toBeTruthy();
  return id;
}

async function saveDocument(docId, content, title) {
  let saveRes = await fetch(`${BASE_URL}/api/documents/${docId}/save`, {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify({ content, body: content, title })
  }).catch(() => null);

  if (!saveRes || saveRes.status === 404) {
    saveRes = await fetch(`${BASE_URL}/api/documents/${docId}`, {
      method: 'PUT',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify({ content, body: content, title })
    }).catch(() => null);
  }
  expect(saveRes, 'Save endpoint should be reachable').toBeTruthy();
  expect([200, 201, 204]).toContain(saveRes.status);
  return saveRes;
}

async function getVersions(docId) {
  let versionsRes = await fetch(`${BASE_URL}/api/documents/${docId}/versions`).catch(() => null);
  if (!versionsRes || versionsRes.status === 404) {
    versionsRes = await fetch(`${BASE_URL}/api/documents/${docId}/history`).catch(() => null);
  }
  expect(versionsRes, 'Version history endpoint should be reachable').toBeTruthy();
  expect(versionsRes.status).toBe(200);
  const versionsBody = await safeJson(versionsRes);
  return { body: versionsBody, versions: extractArray(versionsBody) };
}

function getVersionId(v) {
  return v.id || v.versionId || v.version_id;
}

describe('round5_version_history_save_and_limit', () => {
  const cleanupDocIds = [];

  afterAll(async () => {
    for (const id of cleanupDocIds) {
      await tryDelete(`/api/documents/${id}`);
    }
  });

  it('should generate a version on each save, limit to 20, and preview without overwriting current content', async () => {
    const docId = await createDocument(`history-limit-${Date.now()}`, 'initial content');
    cleanupDocIds.push(docId);

    // Save 22 times to exceed the 20-version limit
    for (let i = 1; i <= 22; i++) {
      await saveDocument(docId, `content v${i}`, `history-limit-${Date.now()}`);
    }

    // Fetch version history
    const { versions } = await getVersions(docId);

    // Verify at most 20 versions
    expect(versions.length, `Expected at most 20 versions, got ${versions.length}`).toBeLessThanOrEqual(20);
    expect(versions.length, 'Should have created some versions').toBeGreaterThan(0);

    // Verify versions have timestamp and content summary
    const v = versions[0];
    const hasTimestamp = v.createdAt || v.created_at || v.savedAt || v.saved_at || v.timestamp || v.date;
    expect(hasTimestamp, `Version should have a save timestamp. Version keys: ${Object.keys(v).join(', ')}`).toBeTruthy();

    const hasSummary = v.body || v.content || v.summary || v.contentSummary || v.content_summary || v.changes;
    expect(hasSummary !== undefined && hasSummary !== null, `Version should have content body or summary. Version keys: ${Object.keys(v).join(', ')}`).toBe(true);

    // Preview a version without overwriting current document
    expect(versions.length).toBeGreaterThanOrEqual(2);
    const previewVersionId = getVersionId(versions[versions.length - 1]);
    expect(previewVersionId, 'Version should have an id').toBeTruthy();

    // Get current document content first
    const currentDocRes = await fetch(`${BASE_URL}/api/documents/${docId}`);
    expect(currentDocRes.status).toBe(200);
    const currentDoc = await safeJson(currentDocRes);
    const currentContent = currentDoc?.content || currentDoc?.body || currentDoc?.document?.content || currentDoc?.document?.body;

    // Preview version (GET should NOT overwrite)
    let previewRes = await fetch(`${BASE_URL}/api/documents/${docId}/versions/${previewVersionId}`).catch(() => null);
    if (!previewRes || previewRes.status === 404) {
      previewRes = await fetch(`${BASE_URL}/api/documents/${docId}/history/${previewVersionId}`).catch(() => null);
    }
    expect(previewRes, 'Preview endpoint should be reachable').toBeTruthy();
    expect(previewRes.status).toBe(200);
    const previewBody = await safeJson(previewRes);
    expect(previewBody, 'Preview should return version data').toBeTruthy();

    // Verify current document was NOT modified by preview
    const afterPreviewRes = await fetch(`${BASE_URL}/api/documents/${docId}`);
    expect(afterPreviewRes.status).toBe(200);
    const afterPreview = await safeJson(afterPreviewRes);
    const afterContent = afterPreview?.content || afterPreview?.body || afterPreview?.document?.content || afterPreview?.document?.body;
    expect(afterContent, `Preview should not overwrite current content. Before: ${currentContent}, After: ${afterContent}`).toBe(currentContent);
  });

  it('should warn when restoring a version while current doc has unsaved modifications', async () => {
    // Self-contained: create own document and versions
    const docId = await createDocument(`unsaved-warn-${Date.now()}`, 'base content');
    cleanupDocIds.push(docId);

    // Save twice to create versions
    await saveDocument(docId, 'saved content v1', `unsaved-warn-${Date.now()}`);
    await saveDocument(docId, 'saved content v2', `unsaved-warn-${Date.now()}`);

    const { versions } = await getVersions(docId);
    expect(versions.length, 'Should have at least 2 versions').toBeGreaterThanOrEqual(2);

    const targetVersionId = getVersionId(versions[versions.length - 1]);
    expect(targetVersionId, 'Target version should have an id').toBeTruthy();

    // Attempt restore with unsaved changes flag
    let restoreRes = await fetch(`${BASE_URL}/api/documents/${docId}/versions/${targetVersionId}/restore`, {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify({ hasUnsavedChanges: true, unsaved: true })
    }).catch(() => null);

    if (!restoreRes || restoreRes.status === 404) {
      restoreRes = await fetch(`${BASE_URL}/api/documents/${docId}/restore`, {
        method: 'POST',
        headers: { 'content-type': 'application/json' },
        body: JSON.stringify({ versionId: targetVersionId, hasUnsavedChanges: true })
      }).catch(() => null);
    }

    expect(restoreRes, 'Restore endpoint should be reachable').toBeTruthy();

    // The API should either return a warning/confirmation-required response (e.g., 409)
    // or include a warning flag in the body indicating unsaved changes risk
    const restoreBody = await safeJson(restoreRes);

    const isWarningStatus = restoreRes.status === 409 || restoreRes.status === 428;
    const hasWarningField = restoreBody?.warning || restoreBody?.confirmRequired ||
      restoreBody?.requiresConfirmation || restoreBody?.confirm ||
      restoreBody?.unsavedWarning || restoreBody?.hasUnsavedChanges;
    const hasWarningMessage = typeof restoreBody?.message === 'string' &&
      (restoreBody.message.toLowerCase().includes('unsaved') ||
       restoreBody.message.toLowerCase().includes('confirm') ||
       restoreBody.message.toLowerCase().includes('warning') ||
       restoreBody.message.toLowerCase().includes('risk'));

    expect(
      isWarningStatus || hasWarningField || hasWarningMessage,
      `Restoring with unsaved changes should produce a warning or confirmation prompt. ` +
      `Status: ${restoreRes.status}, Body: ${JSON.stringify(restoreBody)}`
    ).toBe(true);
  });

  it('should update document content and history after successful restore, and re-save creates new history entry', async () => {
    // Self-contained: create own document and versions
    const docId = await createDocument(`restore-test-${Date.now()}`, 'initial for restore');
    cleanupDocIds.push(docId);

    // Save 3 versions with distinct content
    await saveDocument(docId, 'restore content v1', `restore-test`);
    await saveDocument(docId, 'restore content v2', `restore-test`);
    await saveDocument(docId, 'restore content v3', `restore-test`);

    const { versions } = await getVersions(docId);
    expect(versions.length, 'Should have at least 2 versions').toBeGreaterThanOrEqual(2);

    // Pick an older version to restore
    const oldVersion = versions[versions.length - 1];
    const targetVersionId = getVersionId(oldVersion);
    const oldContent = oldVersion.body || oldVersion.content || oldVersion.summary;
    expect(targetVersionId, 'Target version should have an id').toBeTruthy();

    const versionCountBefore = versions.length;

    // Restore the old version (without unsaved changes flag)
    let restoreRes = await fetch(`${BASE_URL}/api/documents/${docId}/versions/${targetVersionId}/restore`, {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify({ hasUnsavedChanges: false })
    }).catch(() => null);

    if (!restoreRes || restoreRes.status === 404) {
      restoreRes = await fetch(`${BASE_URL}/api/documents/${docId}/restore`, {
        method: 'POST',
        headers: { 'content-type': 'application/json' },
        body: JSON.stringify({ versionId: targetVersionId, hasUnsavedChanges: false })
      }).catch(() => null);
    }

    expect(restoreRes, 'Restore endpoint should be reachable').toBeTruthy();
    expect([200, 201, 204]).toContain(restoreRes.status);

    // Verify current document content was updated
    const docRes = await fetch(`${BASE_URL}/api/documents/${docId}`);
    expect(docRes.status).toBe(200);
    const doc = await safeJson(docRes);
    const currentContent = doc?.content || doc?.body || doc?.document?.content || doc?.document?.body;
    if (oldContent) {
      expect(currentContent, 'After restore, document content should match restored version').toBe(oldContent);
    }

    // Now save again after restore - this should create a NEW history entry
    await saveDocument(docId, currentContent || 'restored content saved again', 'restore-test');

    const { versions: versionsAfterSave } = await getVersions(docId);
    expect(
      versionsAfterSave.length,
      `After restore and re-save, history should have grown. Before restore: ${versionCountBefore}, After re-save: ${versionsAfterSave.length}`
    ).toBeGreaterThan(versionCountBefore);
  });

  it('should show empty state when document has no history', async () => {
    // Create a fresh document without explicitly saving
    const freshDocId = await createDocument(`no-history-${Date.now()}`, 'fresh');
    cleanupDocIds.push(freshDocId);

    let histRes = await fetch(`${BASE_URL}/api/documents/${freshDocId}/versions`).catch(() => null);
    if (!histRes || histRes.status === 404) {
      histRes = await fetch(`${BASE_URL}/api/documents/${freshDocId}/history`).catch(() => null);
    }

    expect(histRes, 'History endpoint should be reachable').toBeTruthy();
    expect(histRes.status).toBe(200);

    const histBody = await safeJson(histRes);
    const histArr = extractArray(histBody);
    // A brand new doc with no explicit saves should have 0 or at most 1 (initial) version
    expect(histArr.length, 'Fresh document should have minimal or no history').toBeLessThanOrEqual(1);

    // When history is empty, response should include an empty state message/indicator
    if (histArr.length === 0) {
      if (histBody && typeof histBody === 'object' && !Array.isArray(histBody)) {
        const emptyMsg = histBody.emptyMessage || histBody.message || histBody.emptyState || histBody.empty || histBody.description;
        expect(
          emptyMsg !== undefined && emptyMsg !== null,
          `When history is empty, response should include an empty state message. Got body keys: ${Object.keys(histBody).join(', ')}`
        ).toBe(true);
        if (typeof emptyMsg === 'string') {
          expect(emptyMsg.length, 'Empty state message should be non-empty').toBeGreaterThan(0);
        }
      } else if (Array.isArray(histBody)) {
        // If the response is just an empty array, that's acceptable as the empty state
        expect(histBody.length).toBe(0);
      }
    }
  });
});

import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function request(method, path, body) {
  const res = await fetch(`${BASE_URL}${path}`, {
    method,
    headers: { 'Content-Type': 'application/json' },
    body: body === undefined ? undefined : JSON.stringify(body),
  });
  const text = await res.text();
  let json;
  try {
    json = text ? JSON.parse(text) : null;
  } catch {
    json = text;
  }
  return { res, body: json };
}

async function cleanupDocument(documentId) {
  if (!documentId) return;
  try {
    await fetch(`${BASE_URL}/documents/${documentId}`, { method: 'DELETE' });
  } catch {}
}

describe('round9_comment_thread_resolution', () => {
  it('should support replies and resolve/reopen at thread level with linked unresolved count updates', async () => {
    let docId;
    try {
      const createDoc = await request('POST', '/documents', { title: `thread-${Date.now()}`, content: 'thread body' });
      expect(createDoc.res.status).toBeOneOf([200, 201]);
      docId = createDoc.body.id || createDoc.body.documentId;
      expect(docId).toBeTruthy();

      const createThread = await request('POST', `/documents/${docId}/comments`, {
        author: 'alice',
        content: 'root thread',
        anchorType: 'document',
        resolved: false
      });
      expect(createThread.res.status, `expected thread create 200/201, got ${createThread.res.status}`).toBeOneOf([200, 201]);
      const threadId = createThread.body.id || createThread.body.commentId;
      expect(threadId, `expected thread id, got ${JSON.stringify(createThread.body)}`).toBeTruthy();

      const addReply = await request('POST', `/documents/${docId}/comments/${threadId}/replies`, {
        author: 'bob',
        content: 'reply message'
      });
      expect(addReply.res.status, `expected reply create 200/201, got ${addReply.res.status}`).toBeOneOf([200, 201]);

      const commentsAfterReply = await request('GET', `/documents/${docId}/comments`);
      expect(commentsAfterReply.res.status).toBe(200);
      expect(commentsAfterReply.body.length, `expected 1 thread, got ${commentsAfterReply.body.length}`).toBe(1);
      expect(Array.isArray(commentsAfterReply.body[0].replies), 'expected replies array').toBe(true);
      expect(commentsAfterReply.body[0].replies.length, `expected 1 reply, got ${commentsAfterReply.body[0].replies.length}`).toBe(1);
      expect(commentsAfterReply.body[0].resolved, `expected thread unresolved before resolve action, got ${commentsAfterReply.body[0].resolved}`).toBe(false);

      const docBeforeResolve = await request('GET', `/documents/${docId}`);
      expect(docBeforeResolve.res.status).toBe(200);
      const unresolvedBefore = docBeforeResolve.body.unresolvedCommentCount ?? docBeforeResolve.body.commentCount ?? docBeforeResolve.body.commentsCount;
      expect(unresolvedBefore, `expected unresolved count 1 before resolve, got ${unresolvedBefore}`).toBe(1);

      const resolve = await request('PATCH', `/documents/${docId}/comments/${threadId}`, { resolved: true });
      expect(resolve.res.status, `expected resolve patch 200/204, got ${resolve.res.status}`).toBeOneOf([200, 204]);

      const afterResolve = await request('GET', `/documents/${docId}/comments`);
      expect(afterResolve.res.status).toBe(200);
      expect(afterResolve.body[0].resolved, `expected thread resolved after patch, got ${afterResolve.body[0].resolved}`).toBe(true);
      expect(afterResolve.body[0].replies.length, `expected reply retained after resolve, got ${afterResolve.body[0].replies.length}`).toBe(1);

      const docAfterResolve = await request('GET', `/documents/${docId}`);
      const unresolvedAfterResolve = docAfterResolve.body.unresolvedCommentCount ?? docAfterResolve.body.commentCount ?? docAfterResolve.body.commentsCount;
      expect(unresolvedAfterResolve ?? 0, `expected unresolved count 0 after resolve, got ${unresolvedAfterResolve}`).toBe(0);

      const reopen = await request('PATCH', `/documents/${docId}/comments/${threadId}`, { resolved: false });
      expect(reopen.res.status, `expected reopen patch 200/204, got ${reopen.res.status}`).toBeOneOf([200, 204]);

      const docAfterReopen = await request('GET', `/documents/${docId}`);
      const unresolvedAfterReopen = docAfterReopen.body.unresolvedCommentCount ?? docAfterReopen.body.commentCount ?? docAfterReopen.body.commentsCount;
      expect(unresolvedAfterReopen, `expected unresolved count restored to 1 after reopen, got ${unresolvedAfterReopen}`).toBe(1);
    } finally {
      await cleanupDocument(docId);
    }
  });
});

