      // First import should succeed
      const import1 = await request('POST', '/imports', exportData);
      expect(import1.res.status).toBeOneOf([200, 201]);

      // Count documents before second import
      const listBefore = await request('GET', '/documents');
      const countBefore = Array.isArray(listBefore.body) ? listBefore.body.length : 0;

      // Second import of the SAME data
      const import2 = await request('POST', '/imports', exportData);
      const status2 = import2.res.status;
      const body2 = import2.body;
      const body2Str = JSON.stringify(body2);

      const isConflict = status2 === 409;
      const hasConflictInfo = body2 && (
        body2.conflicts ||
        body2.duplicates ||
        body2.existingDocuments ||
        body2.requiresAction ||
        body2Str.toLowerCase().includes('overwrite') ||
        body2Str.toLowerCase().includes('duplicate') ||
        body2Str.toLowerCase().includes('already exists') ||
        body2Str.toLowerCase().includes('conflict') ||
        body2Str.toLowerCase().includes('same source')
      );

