import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function request(method, path, body) {
  const res = await fetch(`${BASE_URL}${path}`, {
    method,
    headers: { 'Content-Type': 'application/json' },
    body: body === undefined ? undefined : JSON.stringify(body),
  });
  let data = null;
  try {
    data = await res.json();
  } catch {
    data = null;
  }
  return { res, data };
}

async function safeCleanup(path) {
  try {
    await fetch(`${BASE_URL}${path}`, { method: 'DELETE' });
  } catch {}
}

describe('add_watchlist_max_20_no_duplicates', () => {
  it('should allow at most 20 watchlist symbols and reject duplicate additions', async () => {
    const created = [];
    try {
      for (let i = 1; i <= 20; i++) {
        const symbol = `TESTWL${String(i).padStart(2, '0')}`;
        const { res, data } = await request('POST', '/api/watchlist', { symbol });
        expect(res.status, `adding symbol ${symbol} should succeed`).toBeGreaterThanOrEqual(200);
        expect(res.status, `adding symbol ${symbol} should succeed`).toBeLessThan(300);
        expect(data, `response body for ${symbol} should be object`).toBeTruthy();
        expect(data.symbol ?? data.data?.symbol, `created watchlist item should echo symbol ${symbol}`).toBe(symbol);
        created.push(symbol);
      }

      const duplicateSymbol = created[0];
      const duplicate = await request('POST', '/api/watchlist', { symbol: duplicateSymbol });
      expect([400, 409, 422], `duplicate add should be rejected, got ${duplicate.res.status}`).toContain(duplicate.res.status);
      expect(JSON.stringify(duplicate.data || {})).toMatch(/duplicate|already|exists|已关注|重复/i);

      const overflowSymbol = 'TESTWL21';
      const overflow = await request('POST', '/api/watchlist', { symbol: overflowSymbol });
      expect([400, 409, 422], `adding 21st symbol should be rejected, got ${overflow.res.status}`).toContain(overflow.res.status);
      expect(JSON.stringify(overflow.data || {})).toMatch(/20|max|limit|上限|最多/i);

      const list = await request('GET', '/api/watchlist');
      expect(list.res.status).toBe(200);
      const items = Array.isArray(list.data) ? list.data : (Array.isArray(list.data?.items) ? list.data.items : []);
      expect(items.length, 'watchlist should contain exactly 20 items after duplicate and overflow rejections').toBe(20);
      const symbols = items.map(x => x.symbol);
      expect(new Set(symbols).size, 'watchlist symbols should remain unique').toBe(20);
    } finally {
      for (const symbol of created) {
        await safeCleanup(`/api/watchlist/${encodeURIComponent(symbol)}`);
      }
    }
  });
});

import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function request(method, path, body) {
  const res = await fetch(`${BASE_URL}${path}`, {
    method,
    headers: { 'Content-Type': 'application/json' },
    body: body === undefined ? undefined : JSON.stringify(body),
  });
  let data = null;
  try { data = await res.json(); } catch { data = null; }
  return { res, data };
}

async function cleanup(symbols) {
  for (const symbol of symbols) {
    try { await fetch(`${BASE_URL}/api/watchlist/${encodeURIComponent(symbol)}`, { method: 'DELETE' }); } catch {}
    try { await fetch(`${BASE_URL}/api/market/quotes/${encodeURIComponent(symbol)}`, { method: 'DELETE' }); } catch {}
  }
}

function extractItems(data) {
  return Array.isArray(data) ? data : (Array.isArray(data?.items) ? data.items : (Array.isArray(data?.data) ? data.data : []));
}

describe('sort_watchlist_by_change_stable_for_unavailable', () => {
  it('should keep insertion order by default, sort unavailable quotes last stably, and persist after refresh', async () => {
    // Use 4 symbols:
    // WLSORTA: +10% (currentPrice=110, previousClose=100)
    // WLSORTB: -5%  (currentPrice=95, previousClose=100)
    // WLSORTC: no current price → change not computable
    // WLSORTD: no current price AND no previousClose → change not computable
    const symbols = ['WLSORTA', 'WLSORTB', 'WLSORTC', 'WLSORTD'];
    await cleanup(symbols);

    try {
      // Setup quotes - make WLSORTC and WLSORTD clearly not computable
      const quoteFixtures = {
        WLSORTA: { currentPrice: 110, previousClose: 100 },   // +10%
        WLSORTB: { currentPrice: 95, previousClose: 100 },    // -5%
        WLSORTC: { currentPrice: null, previousClose: 100 },  // not computable (no current price)
        WLSORTD: { currentPrice: null, previousClose: null },  // not computable (no data at all)
      };

      for (const [symbol, quote] of Object.entries(quoteFixtures)) {
        const q = await request('POST', '/api/market/quotes', { symbol, ...quote });
        expect(q.res.status, `quote setup for ${symbol} should succeed`).toBeLessThan(300);
      }

      // Add to watchlist in order: A, B, C, D
      for (const symbol of symbols) {
        const add = await request('POST', '/api/watchlist', { symbol });
        expect(add.res.status, `watchlist add for ${symbol} should succeed`).toBeLessThan(300);
      }

      // 1. Default order should match insertion order
      const defaultList = await request('GET', '/api/watchlist');
      expect(defaultList.res.status).toBe(200);
      const defaultItems = extractItems(defaultList.data);
      const defaultSymbols = defaultItems.map(x => x.symbol);
      expect(defaultSymbols.slice(0, 4), 'default watchlist order should follow insertion order').toEqual(symbols);

      // 2. Sort by change (descending): computable ones first sorted by change desc, then not-computable ones in original relative order
      // Expected: WLSORTA(+10%) > WLSORTB(-5%), then WLSORTC, WLSORTD (original relative order preserved)
      const sorted = await request('GET', '/api/watchlist?sort=change');
      expect(sorted.res.status).toBe(200);
      const sortedItems = extractItems(sorted.data);
      const sortedSymbols = sortedItems.map(x => x.symbol);

      // Computable symbols should come first, sorted by change descending
      const computableSorted = sortedSymbols.filter(s => ['WLSORTA', 'WLSORTB'].includes(s));
      expect(computableSorted, 'computable changes should sort descending: A(+10%) before B(-5%)').toEqual(['WLSORTA', 'WLSORTB']);

      // Not-computable symbols should come after computable ones
      const notComputableSorted = sortedSymbols.filter(s => ['WLSORTC', 'WLSORTD'].includes(s));
      expect(notComputableSorted, 'not-computable symbols should be at the end').toEqual(['WLSORTC', 'WLSORTD']);

      // Verify not-computable symbols are indeed after computable ones
      const idxLastComputable = Math.max(sortedSymbols.indexOf('WLSORTA'), sortedSymbols.indexOf('WLSORTB'));
      const idxFirstNotComputable = Math.min(sortedSymbols.indexOf('WLSORTC'), sortedSymbols.indexOf('WLSORTD'));
      expect(idxFirstNotComputable, 'unavailable quotes should appear after available ones').toBeGreaterThan(idxLastComputable);

      // Verify relative order among not-computable is preserved (C was added before D)
      expect(sortedSymbols.indexOf('WLSORTC'), 'WLSORTC should come before WLSORTD among unavailable (original order)').toBeLessThan(sortedSymbols.indexOf('WLSORTD'));

      // 3. Switch back to default sort - should not mutate actual watchlist membership/order
      const refresh = await request('GET', '/api/watchlist?sort=default');
      expect(refresh.res.status).toBe(200);
      const refreshItems = extractItems(refresh.data);
      expect(refreshItems.map(x => x.symbol).slice(0, 4), 'switching sort should not mutate actual watchlist membership/order').toEqual(symbols);

      // 4. Simulate page refresh: verify persistence by making a fresh GET request
      // In an API-level test, a fresh GET is equivalent to page refresh since it reads from persistent storage
      // We add a small delay to ensure any async persistence has completed
      await new Promise(resolve => setTimeout(resolve, 200));
      const persisted = await request('GET', '/api/watchlist');
      expect(persisted.res.status).toBe(200);
      const persistedItems = extractItems(persisted.data);
      const persistedSymbols = persistedItems.map(x => x.symbol);
      // All 4 symbols should still be present after simulated refresh
      for (const symbol of symbols) {
        expect(persistedSymbols, `${symbol} should be persisted after refresh`).toContain(symbol);
      }
      expect(persistedSymbols.slice(0, 4), 'persisted order should match insertion order').toEqual(symbols);
    } finally {
      await cleanup(symbols);
    }
  });
});

import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

