async function findOrderEndpoint() {
  const candidates = ['/api/orders', '/api/order', '/api/trade/order', '/api/trading/orders'];
  for (const path of candidates) {
    try {
      const res = await fetch(`${BASE_URL}${path}`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ symbol: 'TEST', side: 'buy', price: 10, quantity: 100 }),
      });
      if (res.status !== 404) return path;
    } catch {}
  }
  return '/api/orders';
}

