describe('reject_orders_violating_business_constraints', () => {
  it('should reject insufficient funds buy with specific feedback', async () => {
    try {
      // Reset account with low cash
      await request('POST', '/api/account/reset', { cash: 1000 });
      // Setup a valid quote so current price is available
      await request('POST', '/api/market/quotes', { symbol: 'BIZBUY1', currentPrice: 50, previousClose: 48 });

      // Attempt buy: price=50, quantity=100, amount=5000 > cash=1000 → should be rejected
      const insufficient = await request('POST', '/api/orders', { symbol: 'BIZBUY1', side: 'buy', price: 50, quantity: 100 });
      expect([400, 409, 422], `insufficient funds buy should be rejected, got ${insufficient.res.status}`).toContain(insufficient.res.status);
      const text = JSON.stringify(insufficient.data || {});
      expect(text, `should mention insufficient funds/balance, got: ${text}`).toMatch(/insufficient|balance|资金|余额不足|余额/i);
    } finally {
      try { await request('POST', '/api/account/reset', {}); } catch {}
    }
  });

  it('should reject selling more than available position', async () => {
    const createdOrderIds = [];
    try {
      // Reset with enough cash
      await request('POST', '/api/account/reset', { cash: 1000000 });
      // Setup quote for BIZSELL1 so buy can be matched
      await request('POST', '/api/market/quotes', { symbol: 'BIZSELL1', currentPrice: 10, previousClose: 10 });

      // Buy 200 shares at price=10 (price >= currentPrice=10, should match immediately)
      const buy = await request('POST', '/api/orders', { symbol: 'BIZSELL1', side: 'buy', price: 10, quantity: 200 });
      expect([200, 201], `setup buy order should succeed, got ${buy.res.status}`).toContain(buy.res.status);
      const buyId = extractId(buy.data);
      if (buyId) createdOrderIds.push(buyId);

      // Wait a moment for order to settle
      await new Promise(resolve => setTimeout(resolve, 100));

      // Attempt to sell 300 shares (only 200 held) → should be rejected
      const oversell = await request('POST', '/api/orders', { symbol: 'BIZSELL1', side: 'sell', price: 10, quantity: 300 });
      expect([400, 409, 422], `oversell should be rejected, got ${oversell.res.status}`).toContain(oversell.res.status);
      const text = JSON.stringify(oversell.data || {});
      expect(text, `should mention position/available quantity exceeded, got: ${text}`).toMatch(/exceed|available|可卖|超限|持仓|position|数量/i);
    } finally {
      for (const id of createdOrderIds) {
        await safeDeleteOrder(id);
      }
      try { await request('POST', '/api/account/reset', {}); } catch {}
    }
  });

  it('should reject sell when no position exists', async () => {
    try {
      await request('POST', '/api/account/reset', { cash: 1000000 });
      // NOPOS01 has no position
      await request('POST', '/api/market/quotes', { symbol: 'NOPOS01', currentPrice: 10, previousClose: 10 });

      const noPosition = await request('POST', '/api/orders', { symbol: 'NOPOS01', side: 'sell', price: 10, quantity: 100 });
      expect([400, 409, 422], `sell without position should be rejected, got ${noPosition.res.status}`).toContain(noPosition.res.status);
      const text = JSON.stringify(noPosition.data || {});
      expect(text, `should mention no position, got: ${text}`).toMatch(/no position|持仓不足|无持仓|不可卖|position|持仓/i);
    } finally {
      try { await request('POST', '/api/account/reset', {}); } catch {}
    }
  });

  it('should handle unavailable current price when submitting an order', async () => {
    try {
      await request('POST', '/api/account/reset', { cash: 1000000 });
      // Set currentPrice to null → price unavailable
      await request('POST', '/api/market/quotes', { symbol: 'NOPRICE1', currentPrice: null, previousClose: 10 });

      const noPrice = await request('POST', '/api/orders', { symbol: 'NOPRICE1', side: 'buy', price: 10, quantity: 100 });

      // Two valid behaviors:
      // 1. System rejects the order outright (4xx) with a message about price unavailability
      // 2. System accepts the order (2xx) but it stays pending with a warning about price unavailability
      const text = JSON.stringify(noPrice.data || {});

      if (noPrice.res.status >= 400) {
        // Behavior 1: order rejected
        expect([400, 409, 422]).toContain(noPrice.res.status);
        expect(text, `rejection should mention price unavailable, got: ${text}`).toMatch(/price|不可用|unavailable|行情|当前价/i);
      } else {
        // Behavior 2: order accepted but pending, not matched
        expect([200, 201]).toContain(noPrice.res.status);
        // Verify the order is NOT filled (should be pending since current price is unavailable)
        const orderId = extractId(noPrice.data);
        if (orderId) {
          const orderDetail = await request('GET', `/api/orders/${encodeURIComponent(orderId)}`);
          if (orderDetail.res.status === 200) {
            const status = String(orderDetail.data?.status || orderDetail.data?.data?.status || '');
            expect(status, 'order should not be filled when current price is unavailable').not.toMatch(/filled|executed|成交|已成交/i);
          }
        }
        // The response or order should contain some indication about price unavailability
        // (this is a softer check since the order was accepted)
      }
    } finally {
      try { await request('POST', '/api/account/reset', {}); } catch {}
    }
  });
});

