describe('create_order_match_status_and_preserve_duplicates', () => {
  it('should set pending/filled/cancelled by matching rules and preserve duplicate orders as separate records', async () => {
    const createdIds = [];
    try {
      await request('POST', '/api/account/reset', { cash: 1000000 });
      await request('POST', '/api/market/quotes', { symbol: 'ORDM001', currentPrice: 10, previousClose: 9.8 });

      const filledBuy = await request('POST', '/api/orders', { symbol: 'ORDM001', side: 'buy', price: 10, quantity: 100 });
      expect([200, 201], 'buy order at >= current price should be accepted').toContain(filledBuy.res.status);
      const filledBuyId = filledBuy.data?.id || filledBuy.data?.orderId || filledBuy.data?.data?.id;
      createdIds.push(filledBuyId);
      expect(JSON.stringify(filledBuy.data || {})).toMatch(/filled|executed|成交|已成交/i);

      const pendingBuy = await request('POST', '/api/orders', { symbol: 'ORDM001', side: 'buy', price: 9.5, quantity: 100 });
      expect([200, 201], 'buy order below current price should be accepted as pending').toContain(pendingBuy.res.status);
      const pendingBuyId = pendingBuy.data?.id || pendingBuy.data?.orderId || pendingBuy.data?.data?.id;
      createdIds.push(pendingBuyId);
      expect(JSON.stringify(pendingBuy.data || {})).toMatch(/pending|open|未成交|待成交/i);

      const duplicatePending = await request('POST', '/api/orders', { symbol: 'ORDM001', side: 'buy', price: 9.5, quantity: 100 });
      expect([200, 201], 'duplicate order content should still create separate order').toContain(duplicatePending.res.status);
      const duplicatePendingId = duplicatePending.data?.id || duplicatePending.data?.orderId || duplicatePending.data?.data?.id;
      createdIds.push(duplicatePendingId);
      expect(duplicatePendingId, 'duplicate order should have its own distinct id').toBeTruthy();
      expect(duplicatePendingId).not.toBe(pendingBuyId);

      const cancelled = await request('POST', `/api/orders/${encodeURIComponent(duplicatePendingId)}/cancel`);
      expect([200, 204], 'pending order should be cancellable').toContain(cancelled.res.status);

      const sellFilled = await request('POST', '/api/orders', { symbol: 'ORDM001', side: 'sell', price: 9.8, quantity: 100 });
      expect([200, 201], 'sell order at <= current price should be accepted').toContain(sellFilled.res.status);
      const sellFilledId = sellFilled.data?.id || sellFilled.data?.orderId || sellFilled.data?.data?.id;
      createdIds.push(sellFilledId);
      expect(JSON.stringify(sellFilled.data || {})).toMatch(/filled|executed|成交|已成交/i);

      const list = await request('GET', '/api/orders?symbol=ORDM001');
      expect(list.res.status).toBe(200);
      const items = getItems(list.data);
      const ids = items.map(x => x.id || x.orderId);
      expect(ids).toContain(filledBuyId);
      expect(ids).toContain(pendingBuyId);
      expect(ids).toContain(duplicatePendingId);
      expect(ids).toContain(sellFilledId);

      const statuses = Object.fromEntries(items.map(x => [x.id || x.orderId, String(x.status || '')]));
      expect(statuses[filledBuyId], `filled buy ${filledBuyId} should be marked filled`).toMatch(/filled|executed|成交|已成交/i);
      expect(statuses[pendingBuyId], `pending buy ${pendingBuyId} should remain pending`).toMatch(/pending|open|未成交|待成交/i);
      expect(statuses[duplicatePendingId], `cancelled order ${duplicatePendingId} should be marked cancelled`).toMatch(/cancel|撤销/i);
      expect(statuses[sellFilledId], `filled sell ${sellFilledId} should be marked filled`).toMatch(/filled|executed|成交|已成交/i);
    } finally {
      for (const id of createdIds) {
        try { await fetch(`${BASE_URL}/api/orders/${encodeURIComponent(id)}`, { method: 'DELETE' }); } catch {}
      }
    }
  });
});

