import { describe, it, expect, beforeAll, afterAll } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function request(method, path, body) {
  const res = await fetch(`${BASE_URL}${path}`, {
    method,
    headers: { 'Content-Type': 'application/json' },
    body: body === undefined ? undefined : JSON.stringify(body),
  });
  let data = null;
  const text = await res.text();
  try { data = text ? JSON.parse(text) : null; } catch { data = text; }
  return { res, data };
}

function extractId(data) {
  if (!data) return null;
  return data.id || data.orderId || data.order_id || data.recordId ||
    data.data?.id || data.data?.orderId || data.data?.order_id || null;
}

function extractStatus(record) {
  if (!record) return '';
  return String(record.status || record.data?.status || record.orderStatus || '').toLowerCase();
}

function extractValidity(record) {
  if (!record) return '';
  return String(
    record.timeInForce || record.validity || record.validityType || record.orderValidity ||
    record.data?.timeInForce || record.data?.validity || ''
  ).toLowerCase();
}

async function resetAccount() {
  const paths = ['/api/account/reset', '/api/reset', '/api/test/reset'];
  for (const p of paths) {
    try {
      const r = await fetch(`${BASE_URL}${p}`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ cash: 2000000 }),
      });
      if (r.status < 300) return true;
    } catch {}
  }
  return false;
}

async function setQuote(symbol, currentPrice) {
  const paths = ['/api/market/quotes', '/api/quotes', '/api/market/price'];
  for (const p of paths) {
    try {
      const r = await fetch(`${BASE_URL}${p}`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ symbol, currentPrice, previousClose: currentPrice }),
      });
      if (r.status < 300) return true;
    } catch {}
  }
  return false;
}

async function findOrderEndpoint() {
  const candidates = ['/api/orders', '/api/order', '/api/trading/orders'];
  for (const path of candidates) {
    try {
      const r = await fetch(`${BASE_URL}${path}`, { method: 'GET' });
      if (r.status !== 404) return path;
    } catch {}
  }
  return '/api/orders';
}

async function triggerRecheck(symbol) {
  const paths = [
    ['/api/orders/recheck', 'POST', { symbol }],
    ['/api/market/advance', 'POST', { symbol }],
    [`/api/market/advance/${symbol}`, 'POST', {}],
    ['/api/orders/match', 'POST', { symbol }],
  ];
  for (const [p, m, b] of paths) {
    try {
      const r = await fetch(`${BASE_URL}${p}`, {
        method: m,
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(b),
      });
      if (r.status < 300) return true;
    } catch {}
  }
  return false;
}

async function cancelOrder(orderPath, id) {
  const cancelPaths = [
    [`${orderPath}/${encodeURIComponent(id)}/cancel`, 'POST'],
    [`${orderPath}/${encodeURIComponent(id)}/cancel`, 'PUT'],
    [`${orderPath}/cancel/${encodeURIComponent(id)}`, 'POST'],
  ];
  for (const [p, m] of cancelPaths) {
    try {
      const r = await fetch(`${BASE_URL}${p}`, {
        method: m,
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({}),
      });
      if (r.status < 300) return true;
    } catch {}
  }
  return false;
}

describe('preserve_order_validity_and_exclude_closed_from_matching', () => {
  let ORDER_PATH = '/api/orders';
  const createdIds = [];

  beforeAll(async () => {
    ORDER_PATH = await findOrderEndpoint();
    await resetAccount();
  });

  afterAll(async () => {
    await resetAccount();
  });

  it('should distinguish day/gtc validity types in order responses', async () => {
    await setQuote('VALID01', 10);

    // Place DAY order: buy at 9 (below current 10, won't match)
    const dayOrder = await request('POST', ORDER_PATH, {
      symbol: 'VALID01', side: 'buy', price: 9, quantity: 100, timeInForce: 'DAY',
    });
    expect(
      [200, 201].includes(dayOrder.res.status),
      `DAY order should be accepted, got ${dayOrder.res.status}: ${JSON.stringify(dayOrder.data)}`
    ).toBe(true);
    const dayId = extractId(dayOrder.data);
    expect(dayId, 'DAY order should return an id').toBeTruthy();
    createdIds.push(dayId);

    // Place GTC order: buy at 8.5 (below current 10, won't match)
    const gtcOrder = await request('POST', ORDER_PATH, {
      symbol: 'VALID01', side: 'buy', price: 8.5, quantity: 100, timeInForce: 'GTC',
    });
    expect(
      [200, 201].includes(gtcOrder.res.status),
      `GTC order should be accepted, got ${gtcOrder.res.status}: ${JSON.stringify(gtcOrder.data)}`
    ).toBe(true);
    const gtcId = extractId(gtcOrder.data);
    expect(gtcId, 'GTC order should return an id').toBeTruthy();
    createdIds.push(gtcId);

    // Verify the two orders have distinguishable validity types
    const dayValidity = extractValidity(dayOrder.data);
    const gtcValidity = extractValidity(gtcOrder.data);

    // At least verify DAY order text contains DAY-related keyword
    const dayText = JSON.stringify(dayOrder.data || {}).toLowerCase();
    expect(
      dayText.includes('day') || dayText.includes('当日'),
      `DAY order response should indicate DAY validity, got: ${dayText}`
    ).toBe(true);

    // GTC order text contains GTC-related keyword
    const gtcText = JSON.stringify(gtcOrder.data || {}).toLowerCase();
    expect(
      gtcText.includes('gtc') || gtcText.includes('长期') || gtcText.includes('good'),
      `GTC order response should indicate GTC/long-term validity, got: ${gtcText}`
    ).toBe(true);

    // They must be different
    if (dayValidity && gtcValidity) {
      expect(dayValidity, 'DAY and GTC validity must differ').not.toBe(gtcValidity);
    }
  });

  it('should persist pending orders after re-query (simulating refresh)', async () => {
    // Query orders to confirm they persist
    const list1 = await request('GET', `${ORDER_PATH}?symbol=VALID01`);
    expect(list1.res.status).toBe(200);
    const text1 = JSON.stringify(list1.data || {});
    for (const id of createdIds) {
      if (id) {
        expect(text1, `order ${id} should be visible`).toContain(String(id));
      }
    }

    // Wait and re-query (simulating page refresh)
    await new Promise(resolve => setTimeout(resolve, 300));
    const list2 = await request('GET', `${ORDER_PATH}?symbol=VALID01`);
    expect(list2.res.status).toBe(200);
    const text2 = JSON.stringify(list2.data || {});
    for (const id of createdIds) {
      if (id) {
        expect(text2, `order ${id} should persist after refresh`).toContain(String(id));
      }
    }
  });

  it('should not re-match cancelled orders when price changes', async () => {
    const gtcId = createdIds[1];
    expect(gtcId, 'GTC order id should exist from earlier test').toBeTruthy();

    // Cancel the GTC order
    const cancelled = await cancelOrder(ORDER_PATH, gtcId);
    expect(cancelled, 'cancel GTC should succeed').toBe(true);

    // Verify GTC is cancelled
    const gtcAfter = await request('GET', `${ORDER_PATH}/${encodeURIComponent(gtcId)}`);
    if (gtcAfter.res.status === 200) {
      const status = extractStatus(gtcAfter.data);
      expect(
        status.includes('cancel') || status.includes('撤'),
        `GTC order should be cancelled, got status: ${status}`
      ).toBe(true);
    }

    // Drop price to 8 so DAY order (price=9) should match (buy at 9 >= current 8)
    // But cancelled GTC (price=8.5) should NOT re-enter matching
    await setQuote('VALID01', 8);
    await triggerRecheck('VALID01');
    await new Promise(resolve => setTimeout(resolve, 300));

    // Verify DAY order (buy at 9) is now filled
    const dayId = createdIds[0];
    if (dayId) {
      const dayAfter = await request('GET', `${ORDER_PATH}/${encodeURIComponent(dayId)}`);
      expect(dayAfter.res.status).toBe(200);
      const dayStatus = extractStatus(dayAfter.data);
      expect(
        dayStatus.includes('fill') || dayStatus.includes('executed') || dayStatus.includes('成交'),
        `DAY order should be filled after price drop, got: ${dayStatus}`
      ).toBe(true);
    }

    // Verify cancelled GTC is still cancelled (not re-matched)
    if (gtcId) {
      const gtcFinal = await request('GET', `${ORDER_PATH}/${encodeURIComponent(gtcId)}`);
      expect(gtcFinal.res.status).toBe(200);
      const gtcStatus = extractStatus(gtcFinal.data);
      expect(
        gtcStatus.includes('cancel') || gtcStatus.includes('撤'),
        `cancelled order should remain cancelled, got: ${gtcStatus}`
      ).toBe(true);
      expect(
        !(gtcStatus.includes('fill') || gtcStatus.includes('成交')),
        `cancelled order must not become filled, got: ${gtcStatus}`
      ).toBe(true);
    }
  });

  it('should not re-match already filled orders on subsequent price changes', async () => {
    // The DAY order (buy at 9) is now filled from the previous test.
    // Change price again to something that would re-satisfy the condition
    await setQuote('VALID01', 7);
    await triggerRecheck('VALID01');
    await new Promise(resolve => setTimeout(resolve, 300));

    const dayId = createdIds[0];
    if (dayId) {
      const dayCheck = await request('GET', `${ORDER_PATH}/${encodeURIComponent(dayId)}`);
      expect(dayCheck.res.status).toBe(200);
      const status = extractStatus(dayCheck.data);
      // Should still be filled, not double-filled or changed
      expect(
        status.includes('fill') || status.includes('executed') || status.includes('成交'),
        `already filled order should remain filled, got: ${status}`
      ).toBe(true);
    }

    // Verify account was not double-debited by checking we can still query normally
    const accountPaths = ['/api/account', '/api/account/info', '/api/portfolio'];
    for (const p of accountPaths) {
      try {
        const r = await fetch(`${BASE_URL}${p}`);
        if (r.status === 200) {
          const acct = await r.json();
          // Account should still have positive balance (not double-debited)
          const cash = acct.availableCash ?? acct.available ?? acct.cash ?? acct.data?.availableCash;
          if (typeof cash === 'number') {
            expect(cash, 'account should not be double-debited').toBeGreaterThanOrEqual(0);
          }
          break;
        }
      } catch {}
    }
  });
});

