describe('recheck_pending_orders_on_price_update_without_double_fill', () => {
  it('should re-evaluate pending orders on price updates and never double fill the same order', async () => {
    const ids = [];
    try {
      await request('POST', '/api/account/reset', { cash: 1000000 });
      await request('POST', '/api/market/quotes', { symbol: 'RECHK01', currentPrice: 11, previousClose: 10.5 });

      const pending = await request('POST', '/api/orders', { symbol: 'RECHK01', side: 'buy', price: 10, quantity: 100 });
      expect([200, 201]).toContain(pending.res.status);
      const id = pending.data?.id || pending.data?.orderId || pending.data?.data?.id;
      ids.push(id);
      expect(JSON.stringify(pending.data || {})).toMatch(/pending|open|未成交|待成交/i);

      await request('POST', '/api/market/quotes', { symbol: 'RECHK01', currentPrice: null, previousClose: 10.5 });
      const noPriceCheck = await request('POST', '/api/orders/recheck', { symbol: 'RECHK01' });
      expect(noPriceCheck.res.status).toBeLessThan(300);
      const stillPending = await request('GET', `/api/orders/${encodeURIComponent(id)}`);
      expect(stillPending.res.status).toBe(200);
      expect(String(stillPending.data?.status || stillPending.data?.data?.status || ''), 'order should remain pending when current price is unavailable').toMatch(/pending|open|未成交|待成交/i);

      await request('POST', '/api/market/quotes', { symbol: 'RECHK01', currentPrice: 10, previousClose: 10.5 });
      const firstCheck = await request('POST', '/api/orders/recheck', { symbol: 'RECHK01' });
      expect(firstCheck.res.status).toBeLessThan(300);

      const filled = await request('GET', `/api/orders/${encodeURIComponent(id)}`);
      expect(filled.res.status).toBe(200);
      const statusAfterFirst = String(filled.data?.status || filled.data?.data?.status || '');
      expect(statusAfterFirst, 'order should be filled when price reaches buy limit').toMatch(/filled|executed|成交|已成交/i);
      const filledQuantity1 = filled.data?.filledQuantity ?? filled.data?.data?.filledQuantity ?? filled.data?.quantity ?? filled.data?.data?.quantity;
      expect(Number(filledQuantity1)).toBe(100);

      const secondCheck = await request('POST', '/api/orders/recheck', { symbol: 'RECHK01' });
      expect(secondCheck.res.status).toBeLessThan(300);
      const afterSecond = await request('GET', `/api/orders/${encodeURIComponent(id)}`);
      expect(afterSecond.res.status).toBe(200);
      const filledQuantity2 = afterSecond.data?.filledQuantity ?? afterSecond.data?.data?.filledQuantity ?? afterSecond.data?.quantity ?? afterSecond.data?.data?.quantity;
      expect(Number(filledQuantity2), 'filled quantity should not increase after already filled order is rechecked again').toBe(100);

      const trades = await request('GET', `/api/trades?orderId=${encodeURIComponent(id)}`);
      if (trades.res.status === 200) {
        const items = Array.isArray(trades.data) ? trades.data : (Array.isArray(trades.data?.items) ? trades.data.items : []);
        expect(items.length, 'same order should generate at most one fill/trade record').toBe(1);
      }
    } finally {
      for (const id of ids) {
        try { await fetch(`${BASE_URL}/api/orders/${encodeURIComponent(id)}`, { method: 'DELETE' }); } catch {}
      }
    }
  });
});

