describe('compute_analysis_metrics_with_unavailable_win_rate', () => {
  let ORDER_PATH = '/api/orders';
  let ANALYSIS_PATH = '/api/analysis';

  beforeAll(async () => {
    ORDER_PATH = await findOrderEndpoint();
    ANALYSIS_PATH = await findAnalysisEndpoint();
    await resetAccount();
  });

  afterAll(async () => {
    await resetAccount();
  });

  it('should compute metrics correctly with only buy trades and no completed sells', async () => {
    // Setup AN001 with valid quote
    await setQuote('AN001', 12, 11);
    // Buy AN001: price=12 >= currentPrice=12, should match immediately
    const buy1 = await request('POST', ORDER_PATH, { symbol: 'AN001', side: 'buy', price: 12, quantity: 100 });
    expect(
      [200, 201].includes(buy1.res.status),
      `buy AN001 should succeed, got ${buy1.res.status}: ${JSON.stringify(buy1.data)}`
    ).toBe(true);

    // Setup AN002 with valid quote so buy can match
    await setQuote('AN002', 20, 20);
    // Buy AN002
    const buy2 = await request('POST', ORDER_PATH, { symbol: 'AN002', side: 'buy', price: 20, quantity: 100 });
    expect(
      [200, 201].includes(buy2.res.status),
      `buy AN002 should succeed, got ${buy2.res.status}: ${JSON.stringify(buy2.data)}`
    ).toBe(true);

    // Wait for orders to settle
    await new Promise(resolve => setTimeout(resolve, 300));

    // Now remove AN002's current price to simulate partial quote unavailability
    await setQuote('AN002', null, 20);

    // Fetch analysis metrics
    const analysis = await request('GET', ANALYSIS_PATH);
    expect(analysis.res.status, 'analysis endpoint should respond 200').toBe(200);
    expect(analysis.data, 'analysis response should include data').toBeTruthy();

    const body = analysis.data;

    // 1. Realized PnL should be 0 (no sells completed)
    const realizedPnL = findField(body, 'realizedPnL', 'realizedProfitLoss', 'realized_pnl', 'realizedProfit');
    expect(realizedPnL, 'realized PnL field should exist').toBeDefined();
    expect(realizedPnL, 'realized PnL should be 0 with no completed sell').toBe(0);

    // 2. Trade count should be exactly 2 (two completed buy executions)
    const tradeCount = findField(body, 'tradeCount', 'filledOrderCount', 'dealCount', 'trade_count', 'transactionCount', 'filledCount');
    expect(tradeCount, 'trade count field should exist').toBeDefined();
    expect(tradeCount, 'trade count should be exactly 2').toBe(2);

    // 3. Position symbol count should be 2
    const positionCount = findField(body, 'positionSymbolCount', 'holdingSymbolCount', 'position_symbol_count', 'holdingCount', 'positionCount');
    expect(positionCount, 'position symbol count field should exist').toBeDefined();
    expect(positionCount, 'position symbol count should be 2').toBe(2);

    // 4. Win rate should be unavailable / not computable (no completed sells)
    const winRate = findField(body, 'winRate', 'win_rate', 'winRatio');
    const isUnavailable =
      winRate === null ||
      winRate === undefined ||
      Number.isNaN(winRate) ||
      winRate === 'N/A' ||
      winRate === '--' ||
      String(winRate).match(/N\/A|不可计算|unavailable|无法计算|-{1,2}/i);
    expect(
      isUnavailable,
      `win rate should be unavailable when no completed sells exist, got: ${JSON.stringify(winRate)}`
    ).toBeTruthy();
    // Specifically it should NOT be 0%
    if (typeof winRate === 'number') {
      // If it's returned as a number, it should be NaN or similar, not 0
      expect(Number.isNaN(winRate), 'win rate should not be 0% with no sells, should be NaN').toBe(true);
    }

    // 5. Unrealized/floating PnL should be computable for AN001 (cost=12, current=12 => 0)
    //    but AN002 has no current price => partial unavailability
    const floating = findField(body, 'unrealizedPnL', 'floatingPnL', 'unrealized_pnl', 'floating_pnl', 'floatingProfit');
    // The page should NOT error out entirely
    expect(analysis.res.status, 'should not return error despite partial unavailability').toBe(200);

    if (typeof floating === 'number') {
      // If system computes only from available quotes, AN001 floating = 0
      expect(floating, 'unrealized PnL from available quotes should be ~0 for AN001').toBeCloseTo(0, 0);
    } else {
      // System indicates partial unavailability
      const analysisText = JSON.stringify(body);
      expect(
        analysisText,
        'should indicate partial floating PnL unavailability'
      ).toMatch(/unavailable|不可计算|partial|部分|缺失|N\/A|无法/i);
    }
  });
});

