describe('summarize_per_symbol_sorted_by_total_return', () => {
  it('should summarize by symbol, exclude never-filled symbols, retain closed positions, and sort by total return desc', async () => {
    try {
      // Reset account to clean state
      await request('POST', '/api/account/reset', { cash: 1000000 });

      // SUMA: currentPrice=10, buy at price=10 (10 >= 10 => fills), then price goes to 12 => positive floating PnL
      await request('POST', '/api/market/quotes', { symbol: 'SUMA', currentPrice: 10, previousClose: 9 });
      await request('POST', '/api/orders', { symbol: 'SUMA', side: 'buy', price: 10, quantity: 100 });
      // Now update SUMA price to 12 so floating PnL is positive
      await request('POST', '/api/market/quotes', { symbol: 'SUMA', currentPrice: 12, previousClose: 10 });

      // SUMB: currentPrice=8, buy at price=10 (10 >= 8 => fills), price stays at 8 => negative floating PnL
      await request('POST', '/api/market/quotes', { symbol: 'SUMB', currentPrice: 8, previousClose: 9 });
      await request('POST', '/api/orders', { symbol: 'SUMB', side: 'buy', price: 10, quantity: 100 });

      // SUMC: currentPrice=10, buy at 10 (fills), then sell at 10 (10 <= 10 => fills) => closed position
      await request('POST', '/api/market/quotes', { symbol: 'SUMC', currentPrice: 10, previousClose: 10 });
      await request('POST', '/api/orders', { symbol: 'SUMC', side: 'buy', price: 10, quantity: 100 });
      await request('POST', '/api/orders', { symbol: 'SUMC', side: 'sell', price: 10, quantity: 100 });

      // SUMD: currentPrice=10, buy at price=9 (9 < 10 => does NOT fill) => never filled, only pending
      await request('POST', '/api/market/quotes', { symbol: 'SUMD', currentPrice: 10, previousClose: 10 });
      await request('POST', '/api/orders', { symbol: 'SUMD', side: 'buy', price: 9, quantity: 100 });

      // Fetch analysis symbol summary
      const analysis = await request('GET', '/api/analysis/symbols');
      expect(analysis.res.status).toBe(200);
      const list = items(analysis.data);
      expect(list.length, 'summary should contain filled-trade symbols only (SUMA, SUMB, SUMC)').toBeGreaterThanOrEqual(3);

      const bySymbol = Object.fromEntries(list.map(x => [x.symbol, x]));

      // SUMA should appear because its buy order was filled
      expect(bySymbol.SUMA, 'SUMA should appear because it has executed trades').toBeTruthy();
      // SUMB should appear because its buy order was filled
      expect(bySymbol.SUMB, 'SUMB should appear because it has executed trades').toBeTruthy();
      // SUMC should appear even though position is now closed
      expect(bySymbol.SUMC, 'SUMC should appear even though position is closed').toBeTruthy();
      // SUMD should NOT appear because its order was never filled
      expect(bySymbol.SUMD, 'SUMD should not appear because it was never filled').toBeFalsy();

      // Verify SUMA fields
      const sumaBuyQty = bySymbol.SUMA.buyQuantity ?? bySymbol.SUMA.totalBuyQuantity ?? bySymbol.SUMA.cumulativeBuyQuantity;
      expect(sumaBuyQty, 'SUMA cumulative buy qty should be 100').toBe(100);
      const sumaSellQty = bySymbol.SUMA.sellQuantity ?? bySymbol.SUMA.totalSellQuantity ?? bySymbol.SUMA.cumulativeSellQuantity ?? 0;
      expect(sumaSellQty, 'SUMA cumulative sell qty should be 0').toBe(0);
      const sumaRemaining = bySymbol.SUMA.positionQuantity ?? bySymbol.SUMA.remainingPosition ?? bySymbol.SUMA.currentPosition;
      expect(sumaRemaining, 'SUMA remaining position qty should be 100').toBe(100);
      const sumaTotalReturn = bySymbol.SUMA.totalReturn ?? bySymbol.SUMA.totalContribution ?? bySymbol.SUMA.totalPnl;
      expect(sumaTotalReturn, 'SUMA total return should be positive').toBeGreaterThan(0);

      // Verify SUMB fields - bought at 10, current price 8, so negative
      const sumbRemaining = bySymbol.SUMB.positionQuantity ?? bySymbol.SUMB.remainingPosition ?? bySymbol.SUMB.currentPosition;
      expect(sumbRemaining, 'SUMB remaining position should be 100').toBe(100);
      const sumbTotalReturn = bySymbol.SUMB.totalReturn ?? bySymbol.SUMB.totalContribution ?? bySymbol.SUMB.totalPnl;
      expect(sumbTotalReturn, 'SUMB total return should be negative').toBeLessThan(0);

      // Verify SUMC fields - closed position
      const sumcRemaining = bySymbol.SUMC.positionQuantity ?? bySymbol.SUMC.remainingPosition ?? bySymbol.SUMC.currentPosition;
      expect(sumcRemaining, 'closed position should have zero remaining qty').toBe(0);
      const sumcFloating = bySymbol.SUMC.unrealizedPnL ?? bySymbol.SUMC.floatingPnL ?? bySymbol.SUMC.unrealizedPnl ?? bySymbol.SUMC.floatingPnl;
      expect(
        sumcFloating === 0 || sumcFloating === null || sumcFloating === undefined || sumcFloating === 'N/A',
        `closed symbol floating pnl should be 0 or unavailable, got ${String(sumcFloating)}`
      ).toBe(true);

      // Verify default sort: total return descending
      const totalReturns = list.map(x => x.totalReturn ?? x.totalContribution ?? x.totalPnl ?? Number.NEGATIVE_INFINITY);
      const sorted = [...totalReturns].sort((a, b) => b - a);
      expect(totalReturns, 'symbol summary should be sorted by total return descending by default').toEqual(sorted);

      // Boundary: test ascending sort
      const analysisAsc = await request('GET', '/api/analysis/symbols?sort=asc');
      if (analysisAsc.res.status === 200) {
        const listAsc = items(analysisAsc.data);
        if (listAsc.length >= 2) {
          const totalReturnsAsc = listAsc.map(x => x.totalReturn ?? x.totalContribution ?? x.totalPnl ?? Number.NEGATIVE_INFINITY);
          const sortedAsc = [...totalReturnsAsc].sort((a, b) => a - b);
          expect(totalReturnsAsc, 'ascending sort should order by total return from low to high').toEqual(sortedAsc);
          // Result count should be the same regardless of sort order
          expect(listAsc.length, 'sort change should not affect result count').toBe(list.length);
        }
      }
    } finally {
      try { await request('POST', '/api/test/reset', {}); } catch {}
      try { await request('POST', '/api/account/reset', {}); } catch {}
    }
  });
});

