    expect([200, 201].includes(o2.res.status), `buy TRAB failed: ${o2.res.status}`).toBe(true);

    // Sell TRAA at 100 (fills: 100 <= 100) - creates realized trade
    const o3 = await request('POST', ORDER_PATH, { symbol: 'TRAA', side: 'sell', price: 100, quantity: 100 });
    expect([200, 201].includes(o3.res.status), `sell TRAA failed: ${o3.res.status}`).toBe(true);

    await new Promise(resolve => setTimeout(resolve, 300));
  });

  it('should return records for all time range containing our trades', async () => {
    const allResp = await request('GET', `${RECORDS_PATH}?range=all`);
    expect(allResp.res.status, 'all range should return 200').toBe(200);
    const allRecords = extractRecords(allResp.body);
    expect(Array.isArray(allRecords), 'all range should return array').toBe(true);
    expect(allRecords.length, 'all range should contain at least 3 orders').toBeGreaterThanOrEqual(3);
  });

  it('should return today records as subset of all and include recent trades', async () => {
    const todayResp = await request('GET', `${RECORDS_PATH}?range=today`);
    expect(todayResp.res.status, 'today range should return 200').toBe(200);
    const todayRecords = extractRecords(todayResp.body);
    expect(Array.isArray(todayRecords), 'today should return array').toBe(true);
    // Since we just created trades, today should have records
    expect(todayRecords.length, 'today should have recently created records').toBeGreaterThanOrEqual(1);

    const allResp = await request('GET', `${RECORDS_PATH}?range=all`);
    const allRecords = extractRecords(allResp.body);
    expect(todayRecords.length, 'today should be <= all').toBeLessThanOrEqual(allRecords.length);
  });

  it('should return 7d and 30d records as subsets of all', async () => {
    const allResp = await request('GET', `${RECORDS_PATH}?range=all`);
    const allRecords = extractRecords(allResp.body);

    const d7Resp = await request('GET', `${RECORDS_PATH}?range=7d`);
    expect(d7Resp.res.status).toBe(200);
    const d7Records = extractRecords(d7Resp.body);
    expect(Array.isArray(d7Records)).toBe(true);
    expect(d7Records.length, '7d <= all').toBeLessThanOrEqual(allRecords.length);

    const d30Resp = await request('GET', `${RECORDS_PATH}?range=30d`);
    expect(d30Resp.res.status).toBe(200);
    const d30Records = extractRecords(d30Resp.body);
    expect(Array.isArray(d30Records)).toBe(true);
    expect(d30Records.length, '30d <= all').toBeLessThanOrEqual(allRecords.length);

    // 7d should be <= 30d
    expect(d7Records.length, '7d <= 30d').toBeLessThanOrEqual(d30Records.length);
  });

  it('should update analysis metrics together with time range', async () => {
    const analysisAll = await request('GET', `${ANALYSIS_PATH}?range=all`);
    const analysisToday = await request('GET', `${ANALYSIS_PATH}?range=today`);

    if (analysisAll.res.status === 200 && analysisToday.res.status === 200) {
      const allBody = analysisAll.body;
      const todayBody = analysisToday.body;

      expect(allBody, 'analysis all should return data').toBeTruthy();
      expect(todayBody, 'analysis today should return data').toBeTruthy();

      // Verify trade count exists and is consistent
      const allTradeCount = findField(allBody, 'tradeCount', 'filledCount', 'dealCount', 'transactionCount', 'trade_count');
      const todayTradeCount = findField(todayBody, 'tradeCount', 'filledCount', 'dealCount', 'transactionCount', 'trade_count');

      if (allTradeCount !== undefined) {
        expect(typeof allTradeCount, 'all trade count should be number').toBe('number');
      }
      if (todayTradeCount !== undefined && allTradeCount !== undefined) {
        expect(todayTradeCount, 'today trade count <= all').toBeLessThanOrEqual(allTradeCount);
      }

      // Verify realized PnL exists
      const allRealized = findField(allBody, 'realizedPnL', 'realized_pnl', 'realizedProfitLoss', 'realizedProfit');
      if (allRealized !== undefined) {
        expect(typeof allRealized, 'realized PnL should be number').toBe('number');
      }
    }
  });

  it('should show empty/unavailable metrics when range has no trades', async () => {
    // All our trades are from today, so a range that excludes today should be empty
    // We can't easily create trades in the past via API, but we can verify the behavior
    // by checking that if a range returns 0 records, the analysis reflects that

    // Try creating a scenario: reset and query analysis with today range (no trades)
    // But that would destroy our test data. Instead, verify the contract:
    // After switching back to 'all', data should still be intact (not mutated)
    const allBefore = await request('GET', `${RECORDS_PATH}?range=all`);
    const allRecordsBefore = extractRecords(allBefore.body);

    // Switch through all ranges
    for (const range of ['today', '7d', '30d']) {
      await request('GET', `${RECORDS_PATH}?range=${range}`);
    }

    // Verify all records are unchanged (switching ranges doesn't mutate data)
    const allAfter = await request('GET', `${RECORDS_PATH}?range=all`);
    const allRecordsAfter = extractRecords(allAfter.body);
    expect(
      allRecordsAfter.length,
      'switching ranges should not mutate underlying records'
    ).toBe(allRecordsBefore.length);

    // Verify record content is the same (not just count)
    if (allRecordsBefore.length > 0 && allRecordsAfter.length > 0) {
      const getId = (r) => r.id || r.orderId || r.order_id || '';
      const idsBefore = allRecordsBefore.map(getId).sort();
      const idsAfter = allRecordsAfter.map(getId).sort();
      expect(idsAfter, 'record ids should be identical after range switches').toEqual(idsBefore);
    }
  });

  it('should not let analysis from one range leak into another range query', async () => {
    // Query analysis for all range first
    const analysisAll = await request('GET', `${ANALYSIS_PATH}?range=all`);
    if (analysisAll.res.status !== 200) return; // skip if endpoint not available

    const allRealized = findField(analysisAll.body, 'realizedPnL', 'realized_pnl', 'realizedProfitLoss');

    // Now query analysis for today
    const analysisToday = await request('GET', `${ANALYSIS_PATH}?range=today`);
    if (analysisToday.res.status !== 200) return;

    const todayRealized = findField(analysisToday.body, 'realizedPnL', 'realized_pnl', 'realizedProfitLoss');

    // Both should be defined (not leaking from each other implicitly)
    // The today value should reflect only today's data
    if (allRealized !== undefined && todayRealized !== undefined) {
      // Since all trades are from today, they should be equal in this case
      expect(todayRealized, 'today realized PnL should reflect today trades').toBe(allRealized);
    }

    // Query analysis again for all to verify it wasn't corrupted
    const analysisAllAgain = await request('GET', `${ANALYSIS_PATH}?range=all`);
    if (analysisAllAgain.res.status === 200) {
      const allRealizedAgain = findField(analysisAllAgain.body, 'realizedPnL', 'realized_pnl', 'realizedProfitLoss');
      if (allRealized !== undefined && allRealizedAgain !== undefined) {
        expect(allRealizedAgain, 'all analysis should not change after querying today').toBe(allRealized);
      }
    }
  });
});

import { describe, it, expect, beforeAll, afterAll } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function request(method, path, body) {
  const res = await fetch(`${BASE_URL}${path}`, {
    method,
    headers: { 'Content-Type': 'application/json' },
    body: body === undefined ? undefined : JSON.stringify(body),
  });
  const text = await res.text();
  let json;
  try { json = text ? JSON.parse(text) : null; } catch { json = text; }
  return { res, body: json };
}

function extractRecords(body) {
  if (!body) return [];
  if (Array.isArray(body)) return body;
  return body.records || body.items || body.orders || body.data || [];
}

function extractTotalCount(body) {
  if (!body) return undefined;
  return body.totalCount ?? body.total ?? body.count ?? body.resultCount ?? undefined;
}

async function resetAccount() {
  const paths = ['/api/account/reset', '/api/reset', '/api/test/reset'];
  for (const p of paths) {
    try {
      const r = await fetch(`${BASE_URL}${p}`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ cash: 1000000 }),
      });
      if (r.status < 300) return true;
    } catch {}
  }
  return false;
}

async function setQuote(symbol, price) {
  const paths = ['/api/market/quotes', '/api/quotes', '/api/market/price'];
  for (const p of paths) {
    try {
      const r = await fetch(`${BASE_URL}${p}`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ symbol, currentPrice: price, previousClose: price }),
      });
      if (r.status < 300) return true;
    } catch {}
  }
  return false;
}

async function findEndpoint(candidates, method = 'GET') {
  for (const path of candidates) {
    try {
      const r = await fetch(`${BASE_URL}${path}`, { method });
      if (r.status !== 404) return path;
    } catch {}
  }
  return candidates[0];
}

async function cancelOrder(orderPath, id) {
  const paths = [
    [`${orderPath}/${encodeURIComponent(id)}/cancel`, 'POST'],
    [`${orderPath}/${encodeURIComponent(id)}/cancel`, 'PUT'],
    [`${orderPath}/cancel/${encodeURIComponent(id)}`, 'POST'],
  ];
  for (const [p, m] of paths) {
    try {
      const r = await fetch(`${BASE_URL}${p}`, {
        method: m,
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({}),
      });
      if (r.status < 300) return true;
    } catch {}
  }
  return false;
}

function getId(data) {
  if (!data) return null;
  return data.id || data.orderId || data.order_id || data.recordId ||
    data.data?.id || data.data?.orderId || null;
}

function getDirection(rec) {
  return (rec.side || rec.direction || rec.orderSide || '').toLowerCase();
}

function getStatus(rec) {
  return (rec.status || rec.orderStatus || '').toLowerCase();
}

function getSymbol(rec) {
  return (rec.symbol || rec.symbolCode || rec.stockCode || '').toUpperCase();
}

describe('filter_records_by_symbol_direction_status_keyword', () => {
  let ORDER_PATH = '/api/orders';
  let RECORDS_PATH = '/api/orders';
  let pendingOrderId = null;

  beforeAll(async () => {
    ORDER_PATH = await findEndpoint(['/api/orders', '/api/order', '/api/trading/orders']);
    RECORDS_PATH = await findEndpoint(['/api/trading/records', '/api/records', '/api/orders']);
    await resetAccount();

    // Set up market data
    // FLTX: currentPrice=100
    await setQuote('FLTX', 100);
    // FLTY: currentPrice=200
    await setQuote('FLTY', 200);
    // FLTZ: currentPrice=300
    await setQuote('FLTZ', 300);

    // Order 1: FLTX BUY at 90 => PENDING (90 < 100 for buy)
    const o1 = await request('POST', ORDER_PATH, { symbol: 'FLTX', side: 'buy', price: 90, quantity: 100 });
    expect(o1.res.status, 'order 1 should succeed').toBeLessThan(300);
    pendingOrderId = getId(o1.body);

    // Order 2: FLTX BUY at 100 => FILLED (100 >= 100)
    const o2 = await request('POST', ORDER_PATH, { symbol: 'FLTX', side: 'buy', price: 100, quantity: 100 });
    expect(o2.res.status, 'order 2 should succeed').toBeLessThan(300);

    // Order 3: FLTY BUY at 200 => FILLED (200 >= 200) -- need position for sell
    await request('POST', ORDER_PATH, { symbol: 'FLTY', side: 'buy', price: 200, quantity: 100 });

    // Order 4: FLTY SELL at 250 => PENDING (250 > 200 for sell, needs price <= current)
    const o3 = await request('POST', ORDER_PATH, { symbol: 'FLTY', side: 'sell', price: 250, quantity: 100 });
    expect(o3.res.status, 'order 3 should succeed').toBeLessThan(300);

    // Order 5: FLTZ BUY at 300 => FILLED (300 >= 300)
    const o4 = await request('POST', ORDER_PATH, { symbol: 'FLTZ', side: 'buy', price: 300, quantity: 100 });
    expect(o4.res.status, 'order 4 should succeed').toBeLessThan(300);

    // Cancel the FLTX pending order to get CANCELED status
    if (pendingOrderId) {
      await cancelOrder(ORDER_PATH, pendingOrderId);
    }

    await new Promise(resolve => setTimeout(resolve, 300));
  });

  afterAll(async () => {
    await resetAccount();
  });

  it('should filter records by symbol only', async () => {
    const bySymbol = await request('GET', `${RECORDS_PATH}?symbol=FLTX`);
    expect(bySymbol.res.status, 'filter by symbol should return 200').toBe(200);
    const records = extractRecords(bySymbol.body);
    expect(Array.isArray(records), 'should return array').toBe(true);
    expect(records.length, 'FLTX should have at least 2 orders').toBeGreaterThanOrEqual(2);
    for (const rec of records) {
      expect(getSymbol(rec), 'all records should be FLTX').toBe('FLTX');
    }
  });

  it('should filter by combined conditions using intersection semantics', async () => {
    // First get single-condition results for comparison
    const byFLTX = await request('GET', `${RECORDS_PATH}?symbol=FLTX`);
    const fltxRecords = extractRecords(byFLTX.body);

    // Now combined: symbol=FLTX, side=buy (or direction=buy), status=filled
    // Try both 'side' and 'direction' parameter names
    let combined = await request('GET', `${RECORDS_PATH}?symbol=FLTX&side=buy&status=filled`);
    if (extractRecords(combined.body).length === 0) {
      combined = await request('GET', `${RECORDS_PATH}?symbol=FLTX&direction=buy&status=filled`);
    }
    if (extractRecords(combined.body).length === 0) {
      combined = await request('GET', `${RECORDS_PATH}?symbol=FLTX&side=buy&status=FILLED`);
    }
    expect(combined.res.status, 'combined filter should return 200').toBe(200);
    const combinedRecords = extractRecords(combined.body);
    expect(Array.isArray(combinedRecords), 'combined should return array').toBe(true);

    // Combined results should be a strict subset of single-condition results (intersection)
    expect(
      combinedRecords.length,
      'combined filter (intersection) should return fewer or equal records than single filter'
    ).toBeLessThanOrEqual(fltxRecords.length);

    // Should find exactly 1 record: FLTX buy at 100 that filled
    expect(combinedRecords.length, 'should find exactly 1 FLTX filled buy').toBe(1);

    for (const rec of combinedRecords) {
      expect(getSymbol(rec), 'should be FLTX').toBe('FLTX');
      const dir = getDirection(rec);
      expect(dir, 'direction should be buy').toBe('buy');
      const status = getStatus(rec);
      expect(
        status.includes('fill') || status.includes('executed') || status.includes('成交'),
        `status should be filled, got: ${status}`
      ).toBe(true);
    }
  });

  it('should filter by keyword matching symbol name', async () => {
    const byKeyword = await request('GET', `${RECORDS_PATH}?keyword=FLTX`);
    expect(byKeyword.res.status, 'keyword filter should return 200').toBe(200);
    const records = extractRecords(byKeyword.body);
    expect(Array.isArray(records), 'keyword filter should return array').toBe(true);
    expect(records.length, 'keyword FLTX should find records').toBeGreaterThanOrEqual(1);
    for (const rec of records) {
      const haystack = `${rec.symbolName || ''} ${rec.symbol || ''} ${rec.name || ''}`.toUpperCase();
      expect(haystack.includes('FLTX'), `keyword should match, got ${haystack}`).toBe(true);
    }
  });

  it('should return empty results with clear indicator for incompatible intersection', async () => {
    // FLTX has no filled sell orders
    let noMatch = await request('GET', `${RECORDS_PATH}?symbol=FLTX&side=sell&status=filled`);
    if (extractRecords(noMatch.body).length > 0) {
      noMatch = await request('GET', `${RECORDS_PATH}?symbol=FLTX&direction=sell&status=filled`);
    }
    expect(noMatch.res.status, 'no-match filter should return 200').toBe(200);
    const records = extractRecords(noMatch.body);
    expect(records.length, 'incompatible intersection should return empty').toBe(0);

    // Check for empty state indicator
    const totalCount = extractTotalCount(noMatch.body);
    if (totalCount !== undefined) {
      expect(totalCount, 'total count for empty result should be 0').toBe(0);
    }

    // Check for empty state message/indicator
    const bodyText = JSON.stringify(noMatch.body || {});
    const hasEmptyIndicator =
      records.length === 0 ||
      (totalCount !== undefined && totalCount === 0) ||
      /empty|暂无|没有|无记录|no.*record|no.*result|not.*found/i.test(bodyText);
    expect(hasEmptyIndicator, 'empty results should have clear indicator').toBe(true);
  });

  it('should restore all records when keyword is empty', async () => {
    const emptyKeyword = await request('GET', `${RECORDS_PATH}?keyword=`);
    expect(emptyKeyword.res.status, 'empty keyword should return 200').toBe(200);
    const emptyKwRecords = extractRecords(emptyKeyword.body);

    const allRecords = extractRecords((await request('GET', RECORDS_PATH)).body);
    expect(emptyKwRecords.length, 'empty keyword should restore all records').toBe(allRecords.length);
  });

  it('should restore all records when clearing all filters', async () => {
    // First apply multiple filters
    await request('GET', `${RECORDS_PATH}?symbol=FLTX&side=buy&status=filled&keyword=FLTX`);

    // Then clear all by querying with no params
    const cleared = await request('GET', RECORDS_PATH);
    expect(cleared.res.status).toBe(200);
    const clearedRecords = extractRecords(cleared.body);

    // Should include records from all symbols
    const symbols = new Set(clearedRecords.map(r => getSymbol(r)));
    expect(symbols.size, 'clearing all filters should show records from multiple symbols').toBeGreaterThanOrEqual(2);
  });

  it('should have consistent totalCount with returned records for filtered queries', async () => {
    const withFilter = await request('GET', `${RECORDS_PATH}?symbol=FLTX`);
    expect(withFilter.res.status).toBe(200);
    const recs = extractRecords(withFilter.body);
    const countVal = extractTotalCount(withFilter.body);
    if (countVal !== undefined) {
      expect(countVal, 'totalCount should match number of returned records').toBe(recs.length);
    }
  });

  it('should update results when filter conditions change sequentially', async () => {
    // Query with symbol=FLTX
    const r1 = await request('GET', `${RECORDS_PATH}?symbol=FLTX`);
    const fltxCount = extractRecords(r1.body).length;

    // Query with symbol=FLTY
    const r2 = await request('GET', `${RECORDS_PATH}?symbol=FLTY`);
    const fltyCount = extractRecords(r2.body).length;

    // Query with symbol=FLTZ
    const r3 = await request('GET', `${RECORDS_PATH}?symbol=FLTZ`);
    const fltzCount = extractRecords(r3.body).length;

    // All three should have data (we created orders for all)
    expect(fltxCount, 'FLTX should have records').toBeGreaterThanOrEqual(1);
    expect(fltyCount, 'FLTY should have records').toBeGreaterThanOrEqual(1);
    expect(fltzCount, 'FLTZ should have records').toBeGreaterThanOrEqual(1);

    // Each result should only contain its own symbol's records
    const r1Recs = extractRecords(r1.body);
    const r1Symbols = new Set(r1Recs.map(r => getSymbol(r)));
    expect(r1Symbols.size, 'FLTX filter should only show FLTX').toBe(1);
    expect(r1Symbols.has('FLTX')).toBe(true);
  });
});

import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function request(method, path, body) {
  const res = await fetch(`${BASE_URL}${path}`, {
    method,
    headers: { 'Content-Type': 'application/json' },
    body: body === undefined ? undefined : JSON.stringify(body),
  });
  const text = await res.text();
  let json;
  try { json = text ? JSON.parse(text) : null; } catch { json = text; }
  return { res, body: json };
}

function extractRecords(body) {
  if (!body) return [];
  return body.records || body.items || body.orders || body.data || (Array.isArray(body) ? body : []);
}

function getOrderId(body) {
  if (!body) return undefined;
  return body.id || body.orderId || body.recordId;
}

function getOrderStatus(body) {
  if (!body) return '';
  const s = body.status || '';
  return String(s).toUpperCase();
}

async function resetAccount() {
  // Try multiple reset endpoints to find the working one
  const candidates = [
    { method: 'POST', path: '/api/account/reset' },
    { method: 'POST', path: '/api/test/reset' },
    { method: 'POST', path: '/api/reset' },
  ];
  for (const c of candidates) {
    try {
      const r = await request(c.method, c.path, { cash: 1000000 });
      if (r.res.status < 400) return r;
    } catch {}
  }
  return null;
}

async function setupMarket(symbol, currentPrice) {
  const candidates = [
    '/api/market/quotes',
    '/api/market/setup',
    '/api/market',
  ];
  for (const path of candidates) {
    try {
      const r = await request('POST', path, { symbol, currentPrice, previousClose: currentPrice - 2 });
      if (r.res.status < 400) return r;
    } catch {}
  }
  return null;
}

async function placeOrder(payload) {
  const candidates = ['/api/orders', '/api/trading/orders', '/orders'];
  for (const path of candidates) {
    try {
      const r = await request('POST', path, payload);
      if (r.res.status < 500) return { path, ...r };
    } catch {}
  }
  return null;
}

async function cancelOrder(id) {
  const candidates = [
    `/api/orders/${id}/cancel`,
    `/api/trading/records/${id}/cancel`,
  ];
  for (const path of candidates) {
    try {
      const r = await request('POST', path, {});
      if (r.res.status < 500) return r;
    } catch {}
  }
  return null;
}

async function batchCancel(orderIds) {
  const candidates = [
    '/api/orders/batch-cancel',
    '/api/trading/batch-cancel',
  ];
  for (const path of candidates) {
    try {
      const r = await request('POST', path, { orderIds });
      if (r.res.status < 500) return { path, ...r };
    } catch {}
  }
  return null;
}

async function getOrder(id) {
  const candidates = [
    `/api/orders/${id}`,
    `/api/trading/records/${id}`,
    `/api/records/${id}`,
  ];
  for (const path of candidates) {
    try {
      const r = await request('GET', path);
      if (r.res.status === 200) return r.body;
    } catch {}
  }
