}

describe('batch_cancel_selected_pending_orders_atomically', () => {
  it('should batch cancel pending orders across symbols and reject invalid mixed selections atomically', async () => {
    // Reset account
    const resetResult = await resetAccount();
    expect(resetResult, 'reset endpoint should be available').toBeTruthy();
    expect(resetResult.res.status).toBeLessThan(400);

    // Set up market data: prices set so that certain orders won't fill
    await setupMarket('BTCA', 50);
    await setupMarket('BTCB', 60);
    await setupMarket('BTCC', 30);

    // Create pending orders (buy price < current price => won't fill)
    const pending1Resp = await placeOrder({ symbol: 'BTCA', side: 'buy', price: 40, quantity: 100 });
    expect(pending1Resp, 'pending order 1 endpoint should work').toBeTruthy();
    expect(pending1Resp.res.status, 'pending order 1 creation should succeed').toBeLessThan(300);
    const p1Id = getOrderId(pending1Resp.body);
    expect(p1Id, 'pending order 1 should have an ID').toBeTruthy();

    const pending2Resp = await placeOrder({ symbol: 'BTCB', side: 'buy', price: 45, quantity: 100 });
    expect(pending2Resp, 'pending order 2 endpoint should work').toBeTruthy();
    expect(pending2Resp.res.status, 'pending order 2 creation should succeed').toBeLessThan(300);
    const p2Id = getOrderId(pending2Resp.body);
    expect(p2Id, 'pending order 2 should have an ID').toBeTruthy();

    // Create a filled order (buy price >= current price => fills immediately)
    const filledResp = await placeOrder({ symbol: 'BTCC', side: 'buy', price: 30, quantity: 100 });
    expect(filledResp, 'filled order endpoint should work').toBeTruthy();
    expect(filledResp.res.status, 'filled order creation should succeed').toBeLessThan(300);
    const fId = getOrderId(filledResp.body);
    expect(fId, 'filled order should have an ID').toBeTruthy();

    // Create another pending order, then cancel it individually to get CANCELED status
    const canceledResp = await placeOrder({ symbol: 'BTCA', side: 'buy', price: 35, quantity: 100 });
    expect(canceledResp, 'order to cancel endpoint should work').toBeTruthy();
    expect(canceledResp.res.status, 'order to cancel creation should succeed').toBeLessThan(300);
    const cId = getOrderId(canceledResp.body);
    expect(cId, 'order to cancel should have an ID').toBeTruthy();
    const cancelResult = await cancelOrder(cId);
    expect(cancelResult, 'individual cancel should work').toBeTruthy();
    expect(cancelResult.res.status).toBeLessThan(300);

    // Get counts before batch cancel for verification
    const beforePending = await getOrders('?status=pending');
    const beforeCanceled = await getOrders('?status=canceled');
    const pendingCountBefore = beforePending ? extractRecords(beforePending.body).length : undefined;
    const canceledCountBefore = beforeCanceled ? extractRecords(beforeCanceled.body).length : undefined;

    // --- Test 1: Batch cancel two valid pending orders across different symbols ---
    const batchSuccess = await batchCancel([p1Id, p2Id]);
    expect(batchSuccess, 'batch cancel endpoint should be available').toBeTruthy();
    expect(batchSuccess.res.status, 'batch cancel of valid pending orders should succeed').toBeLessThan(300);

    // Verify the response indicates how many were canceled
    const canceledCount = batchSuccess.body?.canceledCount ?? batchSuccess.body?.count ?? batchSuccess.body?.canceled;
    expect(canceledCount, 'response should report the number of canceled orders').toBeDefined();
    expect(canceledCount, 'should report 2 canceled orders').toBe(2);

    // Verify orders are now CANCELED
    const p1After = await getOrder(p1Id);
    expect(p1After, 'should be able to retrieve order p1 after cancel').toBeTruthy();
    expect(getOrderStatus(p1After), `pending order ${p1Id} should become CANCELED`).toMatch(/CANCEL/);

    const p2After = await getOrder(p2Id);
    expect(p2After, 'should be able to retrieve order p2 after cancel').toBeTruthy();
    expect(getOrderStatus(p2After), `pending order ${p2Id} should become CANCELED`).toMatch(/CANCEL/);

    // Verify result counts updated: pending count decreased, canceled count increased
    if (pendingCountBefore !== undefined) {
      const afterPending = await getOrders('?status=pending');
      if (afterPending && afterPending.res.status === 200) {
        const pendingCountAfter = extractRecords(afterPending.body).length;
        expect(pendingCountAfter, 'pending count should decrease after batch cancel').toBeLessThan(pendingCountBefore);
      }
    }
    if (canceledCountBefore !== undefined) {
      const afterCanceled = await getOrders('?status=canceled');
      if (afterCanceled && afterCanceled.res.status === 200) {
        const canceledCountAfter = extractRecords(afterCanceled.body).length;
        expect(canceledCountAfter, 'canceled count should increase after batch cancel').toBeGreaterThan(canceledCountBefore);
      }
    }

    // --- Test 2: Empty selection should be rejected with clear reason ---
    const emptyBatch = await batchCancel([]);
    expect(emptyBatch, 'batch cancel endpoint should respond to empty selection').toBeTruthy();
    expect(emptyBatch.res.status, 'empty selection should be rejected with 4xx').toBeGreaterThanOrEqual(400);
    // Verify error response contains a reason message
    const emptyErrorBody = typeof emptyBatch.body === 'string' ? emptyBatch.body : JSON.stringify(emptyBatch.body || '');
    expect(emptyErrorBody.length, 'empty selection rejection should include an error message').toBeGreaterThan(0);

    // --- Test 3: Mixed selection with a FILLED order should be rejected atomically ---
    const pending3Resp = await placeOrder({ symbol: 'BTCA', side: 'buy', price: 38, quantity: 100 });
    expect(pending3Resp, 'pending order 3 should be created').toBeTruthy();
    expect(pending3Resp.res.status).toBeLessThan(300);
    const p3Id = getOrderId(pending3Resp.body);
    expect(p3Id, 'pending order 3 should have an ID').toBeTruthy();

    const mixedWithFilled = await batchCancel([p3Id, fId]);
    expect(mixedWithFilled, 'batch cancel with mixed statuses should respond').toBeTruthy();
    expect(
      mixedWithFilled.res.status,
      'batch cancel mixing pending with filled should be rejected'
    ).toBeGreaterThanOrEqual(400);
    // Verify error response explains the reason
    const mixedFilledError = typeof mixedWithFilled.body === 'string' ? mixedWithFilled.body : JSON.stringify(mixedWithFilled.body || '');
    expect(mixedFilledError.length, 'mixed status rejection should include a reason').toBeGreaterThan(0);

    // Verify atomicity: pending order should remain PENDING (not canceled)
    const p3After = await getOrder(p3Id);
    expect(p3After, 'should be able to retrieve order p3 after failed mixed cancel').toBeTruthy();
    const p3Status = getOrderStatus(p3After);
    expect(p3Status, 'atomic failure should keep pending order unchanged').toMatch(/PENDING|未成交/);

    // Filled order should remain FILLED
    const fAfter = await getOrder(fId);
    expect(fAfter, 'should be able to retrieve filled order after failed mixed cancel').toBeTruthy();
    const fStatus = getOrderStatus(fAfter);
    expect(fStatus, 'filled order should remain FILLED').toMatch(/FILL|已成交|EXECUTED|DONE/);

    // --- Test 4: Mixed selection with an already CANCELED order should also be rejected ---
    const mixedWithCanceled = await batchCancel([p3Id, cId]);
    expect(mixedWithCanceled, 'batch cancel with canceled order should respond').toBeTruthy();
    expect(
      mixedWithCanceled.res.status,
      'batch cancel mixing pending with already-canceled should be rejected'
    ).toBeGreaterThanOrEqual(400);
    // Verify error response explains the reason
    const mixedCanceledError = typeof mixedWithCanceled.body === 'string' ? mixedWithCanceled.body : JSON.stringify(mixedWithCanceled.body || '');
    expect(mixedCanceledError.length, 'mixed-with-canceled rejection should include a reason').toBeGreaterThan(0);

    // Verify p3 is still PENDING after failed mixed operation
    const p3AfterMixed = await getOrder(p3Id);
    expect(p3AfterMixed, 'should be able to retrieve order p3 after second failed mixed cancel').toBeTruthy();
    expect(
      getOrderStatus(p3AfterMixed),
      'pending order should remain PENDING after mixed cancel failure'
    ).toMatch(/PENDING|未成交/);

    // --- Test 5: After all operations, verify final record counts ---
    const finalCanceled = await getOrders('?status=canceled');
    if (finalCanceled && finalCanceled.res.status === 200) {
      const canceledRecords = extractRecords(finalCanceled.body);
      // We should have at least 3 canceled: p1, p2, and the individually canceled one (cId)
      expect(canceledRecords.length, 'should have at least 3 canceled orders total').toBeGreaterThanOrEqual(3);
    }

    // Clean up: cancel the remaining pending order p3 so state is clean
    await cancelOrder(p3Id);
  });
});

import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function request(method, path, body) {
  const res = await fetch(`${BASE_URL}${path}`, {
    method,
    headers: { 'Content-Type': 'application/json' },
    body: body === undefined ? undefined : JSON.stringify(body),
  });
  const text = await res.text();
  let json;
  try { json = text ? JSON.parse(text) : null; } catch { json = text; }
  return { res, body: json };
}

async function findWorkingEndpoint(method, candidates, body) {
  for (const path of candidates) {
    try {
      const result = await request(method, path, body);
      if (result.res.status < 500) return { path, ...result };
    } catch {}
  }
  return null;
}

function getPrice(body) {
  if (!body) return undefined;
  return body.currentPrice ?? body.price ?? body.latestPrice ?? body.last ?? body.data?.currentPrice ?? body.data?.price;
}

async function resetSystem() {
  const candidates = ['/api/account/reset', '/api/test/reset', '/api/reset'];
  for (const path of candidates) {
    try { await request('POST', path, {}); } catch {}
  }
}

async function setupMarketSequences(sequences) {
  // Try dedicated sequence setup endpoint first
  const seqResult = await findWorkingEndpoint('POST', [
    '/api/test/market-sequences',
    '/api/market/sequences',
    '/api/market/setup',
  ], { sequences });
  if (seqResult && seqResult.res.status < 400) return seqResult;

  // Fallback: set initial prices via quotes
  for (const [symbol, prices] of Object.entries(sequences)) {
    if (Array.isArray(prices) && prices.length > 0) {
      await findWorkingEndpoint('POST', [
        '/api/market/quotes',
        '/api/market',
      ], { symbol, currentPrice: prices[0], previousClose: prices[0] - 2, sequence: prices });
    }
  }
  return null;
}

async function advanceMarket(symbol) {
  return findWorkingEndpoint('POST', [
    '/api/market/advance',
    '/api/market/next',
  ], { symbol });
}

async function getMarketPrice(symbol) {
  return findWorkingEndpoint('GET', [
    `/api/market/${symbol}`,
    `/api/market/quotes/${symbol}`,
    `/api/market?symbol=${symbol}`,
  ]);
}

describe('advance_market_with_deterministic_independent_sequences', () => {
  it('should advance market with deterministic fixed sequences and independent progress per symbol', async () => {
    // Reset to clean state
    await resetSystem();

    // Set up deterministic price sequences for two symbols
    // AAA: initial 100, then 101, 103, 102, 105, 104, 108 (6 steps)
    // BBB: initial 50, then 49, 48, 50, 52, 51, 55 (6 steps)
    await setupMarketSequences({
      AAA: [100, 101, 103, 102, 105, 104, 108],
      BBB: [50, 49, 48, 50, 52, 51, 55],
    });

    // Verify initial price of AAA
    const initA = await getMarketPrice('AAA');
    expect(initA, 'should be able to get market data for AAA').toBeTruthy();
    expect(initA.res.status, 'AAA market data should return 200').toBe(200);
    const initAPrice = getPrice(initA.body);
    expect(initAPrice, 'AAA initial price should be defined').toBeDefined();
    expect(initAPrice, 'AAA should start at initial price 100').toBe(100);

    // Advance AAA through 6 steps and verify each price deterministically
    const expectedAAA = [101, 103, 102, 105, 104, 108];
    for (let i = 0; i < expectedAAA.length; i++) {
      const step = await advanceMarket('AAA');
      expect(step, `advance AAA step ${i + 1} should return a result`).toBeTruthy();
      expect(step.res.status, `advance AAA step ${i + 1} should succeed`).toBeLessThan(300);
      const stepPrice = getPrice(step.body);
      expect(stepPrice, `AAA step ${i + 1} price should be defined`).toBeDefined();
      expect(stepPrice, `AAA step ${i + 1} price should be ${expectedAAA[i]}`).toBe(expectedAAA[i]);
    }

    // Verify BBB has NOT been affected by AAA's advances (independence)
    const initB = await getMarketPrice('BBB');
    expect(initB, 'should be able to get market data for BBB').toBeTruthy();
    expect(initB.res.status, 'BBB market data should return 200').toBe(200);
    const initBPrice = getPrice(initB.body);
    expect(initBPrice, 'BBB price should be defined').toBeDefined();
    expect(initBPrice, 'BBB should remain at its initial price 50 before any advance').toBe(50);

    // Advance BBB independently one step
    const stepB1 = await advanceMarket('BBB');
    expect(stepB1, 'advance BBB should return a result').toBeTruthy();
    expect(stepB1.res.status, 'advance BBB should succeed').toBeLessThan(300);
    const stepB1Price = getPrice(stepB1.body);
    expect(stepB1Price, 'BBB first step price should be defined').toBeDefined();
    expect(stepB1Price, 'BBB first step should be 49').toBe(49);

    // Verify AAA progress was NOT reset by switching to BBB
    const aAfterSwitch = await getMarketPrice('AAA');
    expect(aAfterSwitch, 'should be able to get AAA after switching to BBB').toBeTruthy();
    expect(aAfterSwitch.res.status, 'AAA should still be accessible').toBe(200);
    const aPrice = getPrice(aAfterSwitch.body);
    expect(aPrice, 'AAA price should be defined after BBB advance').toBeDefined();
    expect(aPrice, 'switching to BBB should not reset AAA progress; AAA should be at 108').toBe(108);

    // Boundary: advancing a symbol without market data should be rejected
    const noData = await advanceMarket('NO_DATA_SYMBOL');
    expect(noData, 'advance of unknown symbol should return a result').toBeTruthy();
    expect(
      noData.res.status,
      'advancing a symbol without market sequence should return 4xx'
    ).toBeGreaterThanOrEqual(400);

    // Advance BBB through the remaining 5 steps to reach end
    const expectedBBBRemaining = [48, 50, 52, 51, 55];
    for (let i = 0; i < expectedBBBRemaining.length; i++) {
      const step = await advanceMarket('BBB');
      expect(step, `advance BBB step ${i + 2} should return a result`).toBeTruthy();
      expect(step.res.status, `advance BBB step ${i + 2} should succeed`).toBeLessThan(300);
      const sp = getPrice(step.body);
      expect(sp, `BBB step ${i + 2} price should be defined`).toBeDefined();
      expect(sp, `BBB step ${i + 2} should be ${expectedBBBRemaining[i]}`).toBe(expectedBBBRemaining[i]);
    }

    // Boundary: advance past the end of the sequence
    const pastEnd = await advanceMarket('BBB');
    expect(pastEnd, 'advance past end should return a result').toBeTruthy();
    // Should either stay at last price or return an indication that sequence is complete
    if (pastEnd.res.status < 300) {
      const pastEndPrice = getPrice(pastEnd.body);
      expect(pastEndPrice, 'past-end price should be defined').toBeDefined();
      expect(pastEndPrice, 'past end should stay at last value 55').toBe(55);
    }
    // It may also return a specific status code indicating end - that's acceptable too

    // Verify market summary data integrity after all advances
    const marketSummary = await getMarketPrice('AAA');
    expect(marketSummary, 'AAA market summary should be accessible').toBeTruthy();
    expect(marketSummary.res.status).toBe(200);
    const finalPrice = getPrice(marketSummary.body);
    expect(finalPrice, 'AAA current price should be defined after all advances').toBeDefined();
    expect(typeof finalPrice, 'price should be a number').toBe('number');
    expect(finalPrice, 'AAA should still be at 108').toBe(108);
  });
});

