}

async function getPositions() {
  return findEndpoint('GET', ['/api/positions', '/api/holdings']);
}

async function getRecords(params = '') {
  return findEndpoint('GET', [
    `/api/trading/records${params}`, `/api/records${params}`, `/api/orders${params}`
  ]);
}

async function placeOrder(payload) {
  return findEndpoint('POST', ['/api/orders', '/api/trading/orders'], payload);
}

async function advanceMarket(symbol) {
  return findEndpoint('POST', ['/api/market/advance', '/api/market/next'], { symbol });
}

function getField(body, ...keys) {
  for (const key of keys) {
    if (body?.[key] !== undefined) return body[key];
    if (body?.data?.[key] !== undefined) return body.data[key];
  }
  return undefined;
}

function extractList(body) {
  if (!body) return [];
  return body.records || body.items || body.orders || body.deals || body.data?.records || (Array.isArray(body) ? body : []);
}

function countByStatus(records, statusKeywords) {
  return records.filter(r => {
    const status = String(r.status || '').toLowerCase();
    return statusKeywords.some(kw => status.includes(kw));
  }).length;
}

describe('advance_market_recomputes_consistent_account_results', () => {
  afterAll(async () => {
    await resetSystem();
  });

  async function runScenario() {
    // Reset to known state
    await resetSystem();

    // Setup deterministic price sequence: AAA starts at 100, then 105, 110, 108, 115
    await setupMarketSequences({ AAA: [100, 105, 110, 108, 115] });

    // Place a buy order that should immediately match (price >= current price of 100)
    const buyOrder = await placeOrder({
      symbol: 'AAA', side: 'BUY', quantity: 100, price: 100
    });
    expect(buyOrder, 'should have a working order endpoint').toBeTruthy();
    expect(buyOrder.res.status, 'buy order should succeed').toBeLessThan(300);

    // Place a pending buy at 95 — won't match because 95 < 100 current price
    const pendingBuy = await placeOrder({
      symbol: 'AAA', side: 'BUY', quantity: 100, price: 95
    });
    expect(pendingBuy, 'pending buy order endpoint should work').toBeTruthy();

    // Place a sell limit at 110 — won't match yet (110 > 100, sell needs price <= current)
    const pendingSell = await placeOrder({
      symbol: 'AAA', side: 'SELL', quantity: 100, price: 110
    });
    expect(pendingSell, 'pending sell order endpoint should work').toBeTruthy();

    // Get state before advancing
    const beforeAccount = await getAccount();
    expect(beforeAccount, 'account endpoint should work').toBeTruthy();
    expect(beforeAccount.res.status).toBe(200);

    const beforeRecords = await getRecords();
    expect(beforeRecords, 'records endpoint should work').toBeTruthy();
    expect(beforeRecords.res.status).toBe(200);
    const filledBeforeAdv = countByStatus(extractList(beforeRecords.body), ['filled', '成交', 'executed', 'done']);

    // Advance market step 1: price goes 100 -> 105
    const adv1 = await advanceMarket('AAA');
    expect(adv1, 'advance endpoint should work').toBeTruthy();
    expect(adv1.res.status).toBeLessThan(300);

    // Advance market step 2: price goes 105 -> 110
    // At 110, the sell limit at 110 should trigger (sell price 110 <= current 110)
    const adv2 = await advanceMarket('AAA');
    expect(adv2, 'second advance should work').toBeTruthy();
    expect(adv2.res.status).toBeLessThan(300);

    // Get state after two advances
    const afterAccount = await getAccount();
    expect(afterAccount, 'account endpoint should work after advances').toBeTruthy();
    expect(afterAccount.res.status).toBe(200);

    const afterRecords = await getRecords();
    expect(afterRecords, 'records endpoint should work after advances').toBeTruthy();
    expect(afterRecords.res.status).toBe(200);
    const filledAfterAdv2 = countByStatus(extractList(afterRecords.body), ['filled', '成交', 'executed', 'done']);

    // The sell should have triggered, so filled count should increase
    expect(filledAfterAdv2, 'sell order should have filled after price reached 110').toBeGreaterThan(filledBeforeAdv);

    const positions = await getPositions();
    expect(positions, 'positions endpoint should work').toBeTruthy();
    expect(positions.res.status).toBe(200);

    // Advance step 3: price goes 110 -> 108
    const adv3 = await advanceMarket('AAA');
    expect(adv3, 'third advance should work').toBeTruthy();
    expect(adv3.res.status).toBeLessThan(300);

    // After third advance, the already-filled sell should NOT re-trigger
    const afterAdv3Records = await getRecords();
    expect(afterAdv3Records, 'records should be available after third advance').toBeTruthy();
    expect(afterAdv3Records.res.status).toBe(200);
    const filledAfterAdv3 = countByStatus(extractList(afterAdv3Records.body), ['filled', '成交', 'executed', 'done']);

    // No duplicate execution
    expect(filledAfterAdv3, 'no duplicate execution should occur on subsequent advances').toBe(filledAfterAdv2);

    const afterAdv3Account = await getAccount();
    expect(afterAdv3Account, 'account should be available after third advance').toBeTruthy();
    expect(afterAdv3Account.res.status).toBe(200);

    // Cash should not change between adv2 and adv3 (no new trades)
    const cashAfterAdv2 = getField(afterAccount.body, 'availableCash', 'cash', 'available');
    const cashAfterAdv3 = getField(afterAdv3Account.body, 'availableCash', 'cash', 'available');
    expect(cashAfterAdv2, 'cash after adv2 should be defined').toBeDefined();
    expect(cashAfterAdv3, 'cash after adv3 should be defined').toBeDefined();
    expect(cashAfterAdv3, 'cash should not change if no new trades execute').toBe(cashAfterAdv2);

    return {
      totalAssets: getField(afterAccount.body, 'totalAssets', 'currentAssets', 'total'),
      cash: cashAfterAdv2,
      filledCount: filledAfterAdv2,
    };
  }

  it('should produce consistent results for identical initial state and steps, and not double-execute', async () => {
    const first = await runScenario();
    const second = await runScenario();

    // Both runs must produce defined values
    expect(first.totalAssets, 'first run total assets should be defined').toBeDefined();
    expect(second.totalAssets, 'second run total assets should be defined').toBeDefined();
    expect(first.cash, 'first run cash should be defined').toBeDefined();
    expect(second.cash, 'second run cash should be defined').toBeDefined();

    // Both runs should produce identical results (deterministic)
    expect(second.totalAssets, 'total assets should be identical across runs').toBe(first.totalAssets);
    expect(second.cash, 'available cash should be identical across runs').toBe(first.cash);
    expect(second.filledCount, 'filled count should be identical across runs').toBe(first.filledCount);
  });

  it('should auto-refresh filtered results after market advance changes state', async () => {
    await resetSystem();

    // Setup: sequence goes up so sell limit can trigger
    await setupMarketSequences({ AAA: [100, 105, 110] });

    // Buy 100 shares at market (price 100 >= 100, immediate fill)
    const buyResult = await placeOrder({
      symbol: 'AAA', side: 'BUY', quantity: 100, price: 100
    });
    expect(buyResult, 'buy order should work').toBeTruthy();
    expect(buyResult.res.status).toBeLessThan(300);

    // Place sell limit at 108 — pending (108 > 100 current, so 108 <= 100 is false)
    const sellResult = await placeOrder({
      symbol: 'AAA', side: 'SELL', quantity: 100, price: 108
    });
    expect(sellResult, 'sell order should work').toBeTruthy();
    expect(sellResult.res.status).toBeLessThan(300);

    // Query records filtered by pending status before advancing
    const beforeAdvance = await getRecords('?status=pending');
    expect(beforeAdvance, 'pending records endpoint should work').toBeTruthy();
    expect(beforeAdvance.res.status, 'pending records query should return 200').toBe(200);
    const pendingBefore = extractList(beforeAdvance.body);
    expect(pendingBefore.length, 'should have at least 1 pending order before advance').toBeGreaterThanOrEqual(1);

    // Advance to 105 — sell at 108: 108 <= 105? No. Still pending.
    const a1 = await advanceMarket('AAA');
    expect(a1, 'first advance should work').toBeTruthy();
    expect(a1.res.status).toBeLessThan(300);

    // Advance to 110 — sell at 108: 108 <= 110? Yes. Should match.
    const a2 = await advanceMarket('AAA');
    expect(a2, 'second advance should work').toBeTruthy();
    expect(a2.res.status).toBeLessThan(300);

    // Query pending records after advance - should have fewer
    const afterAdvance = await getRecords('?status=pending');
    expect(afterAdvance, 'pending records should be queryable after advance').toBeTruthy();
    expect(afterAdvance.res.status, 'pending records should return 200 after advance').toBe(200);
    const pendingAfter = extractList(afterAdvance.body);
    expect(
      pendingAfter.length,
      'filtered pending list should auto-refresh after market advance triggers fill'
    ).toBeLessThan(pendingBefore.length);
  });
});

