  return body.prompts || body.items || body.risks || body.data?.prompts || body.data?.risks || (Array.isArray(body) ? body : []);
}

describe('compute_risk_prompts_for_funds_and_drawdown', () => {
  afterAll(async () => {
    await resetSystem();
  });

  it('should compute low-funds and drawdown risks in real time, update after events, and show normal state when no risk', async () => {
    // Reset with specific cash: 10100 so after buying 100 shares at 100 (=10000), only ~100 left
    await resetSystem(10100);

    // Setup: price sequence starts at 100, drops to 60, then 50, then recovers to 120
    await setupMarketSequences({ RISK: [100, 60, 50, 120] });

    // Buy 100 shares at 100 (immediately fills: price 100 >= current 100)
    const buyResult = await placeOrder({
      symbol: 'RISK', side: 'BUY', quantity: 100, price: 100
    });
    expect(buyResult, 'order endpoint should work').toBeTruthy();
    expect(buyResult.res.status, 'buy order should succeed').toBeLessThan(300);

    // Check risk: should have low funds warning (only ~100 left out of 10100)
    const risk1 = await getRiskPrompts();
    expect(risk1, 'risk prompts endpoint should work').toBeTruthy();
    expect(risk1.res.status, 'risk prompts should return 200').toBe(200);
    const prompts1 = extractPrompts(risk1.body);
    expect(Array.isArray(prompts1), 'risk prompts should be an array').toBe(true);
    const hasLowFunds1 = prompts1.some(p => {
      const s = JSON.stringify(p).toLowerCase();
      return s.includes('fund') || s.includes('资金') || s.includes('余额') || s.includes('cash') || s.includes('balance');
    });
    expect(hasLowFunds1, 'should contain low funds risk after near full allocation').toBe(true);

    // Advance market: price drops from 100 -> 60 (40% loss on 100 shares)
    const adv1 = await advanceMarket('RISK');
    expect(adv1, 'advance endpoint should work').toBeTruthy();
    expect(adv1.res.status, 'advance should succeed').toBeLessThan(300);

    // Check risk: should now also have drawdown/loss risk
    const risk2 = await getRiskPrompts();
    expect(risk2, 'risk prompts should work after price drop').toBeTruthy();
    expect(risk2.res.status).toBe(200);
    const prompts2 = extractPrompts(risk2.body);
    expect(Array.isArray(prompts2), 'prompts2 should be an array').toBe(true);

    // Verify drawdown risk exists and mentions the specific symbol
    const hasDrawdown = prompts2.some(p => {
      const s = JSON.stringify(p).toLowerCase();
      return s.includes('drawdown') || s.includes('loss') || s.includes('亏') || s.includes('浮亏');
    });
    expect(hasDrawdown, 'should contain drawdown/loss risk after market drops 40%').toBe(true);

    // Verify risk prompt mentions the specific symbol 'RISK'
    const mentionsSymbol = prompts2.some(p => {
      const s = JSON.stringify(p);
      return s.includes('RISK');
    });
    expect(mentionsSymbol, 'risk prompt should mention the specific symbol involved').toBe(true);

    // Verify multiple risks shown simultaneously
    expect(prompts2.length, 'should show multiple risk prompts when both low funds and drawdown apply').toBeGreaterThanOrEqual(2);

    // Verify there's an indication of total risk count or "more" indicator when multiple risks exist
    const bodyStr2 = JSON.stringify(risk2.body).toLowerCase();
    const hasCountOrMore = risk2.body?.total !== undefined ||
      risk2.body?.totalCount !== undefined ||
      risk2.body?.hasMore !== undefined ||
      bodyStr2.includes('more') || bodyStr2.includes('更多') ||
      prompts2.length >= 2;
    expect(hasCountOrMore, 'when multiple risks exist, should indicate count or show them all').toBe(true);

    // --- Test import archive triggers risk recalculation ---
    const exported = await exportArchive();
    expect(exported, 'export endpoint should work').toBeTruthy();
    expect(exported.res.status, 'export should succeed').toBeLessThan(300);
    expect(exported.body, 'export body should exist').toBeTruthy();

    // Reset to clean state
    await resetSystem();

    // After reset, risk should be normal/empty
    const riskAfterReset = await getRiskPrompts();
    expect(riskAfterReset, 'risk prompts should work after reset').toBeTruthy();
    expect(riskAfterReset.res.status, 'risk prompts should return 200 after reset').toBe(200);
    const promptsReset = extractPrompts(riskAfterReset.body);
    // When no risk: should show normal state, not disappear completely
    // Check for explicit normal/safe indicator or empty prompts array
    const resetBodyStr = JSON.stringify(riskAfterReset.body).toLowerCase();
    const isNormalState = promptsReset.length === 0 ||
      resetBodyStr.includes('normal') || resetBodyStr.includes('正常') || resetBodyStr.includes('safe');
    expect(isNormalState, 'when no risk, should show normal state (empty prompts or explicit normal indicator)').toBe(true);

    // Import the archived state back
    const imported = await importArchive(exported.body);
    expect(imported, 'import endpoint should work').toBeTruthy();
    expect(imported.res.status, 'import should succeed').toBeLessThan(300);

    // After import, risk should be recalculated and show the same risks as before
    const riskAfterImport = await getRiskPrompts();
    expect(riskAfterImport, 'risk prompts should work after import').toBeTruthy();
    expect(riskAfterImport.res.status, 'risk prompts should return 200 after import').toBe(200);
    const promptsImport = extractPrompts(riskAfterImport.body);
    expect(promptsImport.length, 'risk prompts should be recalculated after import with at least 1 risk').toBeGreaterThanOrEqual(1);

    // --- Test: sell all to close position, then verify RISK symbol no longer in risk prompts ---
    // Current price should still be at 60 after import (the advance happened before export)
    const sellResult = await placeOrder({
      symbol: 'RISK', side: 'SELL', quantity: 100, price: 60
    });
    expect(sellResult, 'sell order endpoint should work').toBeTruthy();
    expect(sellResult.res.status, 'sell order should succeed to close position').toBeLessThan(300);

    // After closing position, RISK should NOT appear in risk prompts
    const risk3 = await getRiskPrompts();
    expect(risk3, 'risk prompts should work after closing position').toBeTruthy();
    expect(risk3.res.status, 'risk prompts should return 200 after position close').toBe(200);
    const prompts3 = extractPrompts(risk3.body);
    const hasClosedSymbol = prompts3.some(p => {
      const s = JSON.stringify(p);
      return s.includes('RISK');
    });
    expect(hasClosedSymbol, 'closed/liquidated symbol should no longer appear in risk prompts').toBe(false);

    // Verify normal state is shown when no position risk remains
    const bodyStr3 = JSON.stringify(risk3.body).toLowerCase();
    const showsNormalOrEmpty = prompts3.length === 0 ||
      bodyStr3.includes('normal') || bodyStr3.includes('正常') || bodyStr3.includes('safe');
    expect(showsNormalOrEmpty, 'when no risk remains after closing positions, should display normal/safe state').toBe(true);
  });
});

import { describe, it, expect, afterAll } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function request(method, path, body) {
  const res = await fetch(`${BASE_URL}${path}`, {
    method,
    headers: { 'Content-Type': 'application/json' },
    body: body === undefined ? undefined : JSON.stringify(body),
  });
  const text = await res.text();
  let json;
  try { json = text ? JSON.parse(text) : null; } catch { json = text; }
  return { res, body: json };
}

async function findEndpoint(method, candidates, body) {
  for (const path of candidates) {
    try {
      const result = await request(method, path, body);
      if (result.res.status < 500) return { path, ...result };
    } catch {}
  }
  return null;
}

async function resetSystem(cash) {
  const candidates = ['/api/account/reset', '/api/test/reset', '/api/reset'];
  for (const path of candidates) {
    try {
      const r = await request('POST', path, cash !== undefined ? { cash } : {});
      if (r.res.status < 400) return r;
    } catch {}
  }
  return null;
}

async function setupMarketSequences(sequences) {
  const result = await findEndpoint('POST', [
    '/api/test/market-sequences',
    '/api/market/sequences',
    '/api/market/setup',
  ], { sequences });
  if (result && result.res.status < 400) return result;
  for (const [symbol, prices] of Object.entries(sequences)) {
    if (Array.isArray(prices) && prices.length > 0) {
      await findEndpoint('POST', ['/api/market/quotes', '/api/market'], {
        symbol, currentPrice: prices[0], previousClose: prices[0] - 2, sequence: prices
      });
    }
  }
  return null;
}

async function placeOrder(payload) {
  return findEndpoint('POST', ['/api/orders', '/api/trading/orders'], payload);
}

async function advanceMarket(symbol) {
  return findEndpoint('POST', ['/api/market/advance', '/api/market/next'], { symbol });
}

async function getAccount() {
  return findEndpoint('GET', ['/api/account/summary', '/api/account', '/api/state']);
}

async function getPositions() {
  return findEndpoint('GET', ['/api/positions', '/api/holdings']);
}

async function getOrders(params = '') {
  return findEndpoint('GET', [
    `/api/orders${params}`, `/api/trading/records${params}`, `/api/records${params}`
  ]);
}

async function getWatchlist() {
  return findEndpoint('GET', ['/api/watchlist', '/api/favorites']);
}

async function addToWatchlist(symbol) {
  return findEndpoint('POST', ['/api/watchlist', '/api/watchlist/add'], { symbol });
}

async function getMarketPrice(symbol) {
  return findEndpoint('GET', [
    `/api/market/${symbol}`,
    `/api/market/quotes/${symbol}`,
  ]);
}

async function getAnalysis() {
  return findEndpoint('GET', ['/api/analysis/summary', '/api/analysis']);
}

async function exportArchive() {
  return findEndpoint('POST', ['/api/archive/export', '/api/export']);
}

async function importArchive(data) {
  return findEndpoint('POST', ['/api/archive/import', '/api/import'], data);
}

function deepGet(obj, ...keys) {
  for (const key of keys) {
    if (obj?.[key] !== undefined) return obj[key];
    if (obj?.data?.[key] !== undefined) return obj.data[key];
  }
  return undefined;
}

function extractList(body) {
  if (!body) return [];
  return body.records || body.items || body.orders || body.data?.records || (Array.isArray(body) ? body : []);
}

function getPrice(body) {
  if (!body) return undefined;
  return body.currentPrice ?? body.price ?? body.latestPrice ?? body.last ?? body.data?.currentPrice;
}

describe('export_import_restore_full_state', () => {
  afterAll(async () => {
    await resetSystem();
  });

  it('should export and import archive to fully restore account, positions, orders, watchlist, market progress and analysis', async () => {
    // --- Step 1: Build up a rich state ---
    await resetSystem(100000);

    // Setup market sequences
    await setupMarketSequences({
      AAA: [10, 11, 12, 13],
      BBB: [20, 19, 21, 22]
    });

    // Add watchlist items
    const wlA = await addToWatchlist('AAA');
    expect(wlA, 'add AAA to watchlist should work').toBeTruthy();
    const wlB = await addToWatchlist('BBB');
    expect(wlB, 'add BBB to watchlist should work').toBeTruthy();

    // Place a buy order that matches immediately (price >= current)
    const buy1 = await placeOrder({ symbol: 'AAA', side: 'BUY', quantity: 100, price: 10 });
    expect(buy1, 'buy AAA order should work').toBeTruthy();
    expect(buy1.res.status, 'buy AAA should succeed').toBeLessThan(300);

    const buy2 = await placeOrder({ symbol: 'BBB', side: 'BUY', quantity: 100, price: 20 });
    expect(buy2, 'buy BBB order should work').toBeTruthy();
    expect(buy2.res.status, 'buy BBB should succeed').toBeLessThan(300);

    // Place a pending order (won't match: buy at 5 when current is 10)
    const pendingOrder = await placeOrder({ symbol: 'AAA', side: 'BUY', quantity: 100, price: 5 });
    expect(pendingOrder, 'pending order should be placed').toBeTruthy();

    // Advance market for both symbols one step each
    const advA = await advanceMarket('AAA');
    expect(advA, 'advance AAA should work').toBeTruthy();
    expect(advA.res.status).toBeLessThan(300);

    const advB = await advanceMarket('BBB');
    expect(advB, 'advance BBB should work').toBeTruthy();
    expect(advB.res.status).toBeLessThan(300);

    // --- Step 2: Capture full state before export ---
    const beforeAccount = await getAccount();
    expect(beforeAccount, 'account should be available before export').toBeTruthy();
    expect(beforeAccount.res.status).toBe(200);
    const beforeCash = deepGet(beforeAccount.body, 'availableCash', 'cash', 'available');
    expect(beforeCash, 'cash should be defined before export').toBeDefined();

    const beforePositions = await getPositions();
    expect(beforePositions, 'positions should be available before export').toBeTruthy();
    expect(beforePositions.res.status).toBe(200);
    const beforePosList = extractList(beforePositions.body);
    expect(beforePosList.length, 'should have positions before export').toBeGreaterThan(0);

    const beforeOrders = await getOrders();
    expect(beforeOrders, 'orders should be available before export').toBeTruthy();
    expect(beforeOrders.res.status).toBe(200);
    const beforeOrderList = extractList(beforeOrders.body);
    expect(beforeOrderList.length, 'should have order records before export').toBeGreaterThan(0);

    const beforeWatchlist = await getWatchlist();
    expect(beforeWatchlist, 'watchlist should be available before export').toBeTruthy();
    expect(beforeWatchlist.res.status).toBe(200);

    // Capture market progress: AAA should be at 11 after one advance
    const beforeMarketA = await getMarketPrice('AAA');
    expect(beforeMarketA, 'AAA market should be available').toBeTruthy();
    expect(beforeMarketA.res.status).toBe(200);
    const beforePriceA = getPrice(beforeMarketA.body);
    expect(beforePriceA, 'AAA price should be defined before export').toBeDefined();
    expect(beforePriceA, 'AAA should be at 11 after one advance').toBe(11);

    // Capture analysis data
    const beforeAnalysis = await getAnalysis();
    let beforeAnalysisBody = null;
    if (beforeAnalysis && beforeAnalysis.res.status === 200) {
      beforeAnalysisBody = beforeAnalysis.body;
    }

    // --- Step 3: Export ---
    const exported = await exportArchive();
    expect(exported, 'export endpoint should work').toBeTruthy();
    expect(exported.res.status, 'export should succeed').toBeLessThan(300);
    expect(exported.body, 'export body should exist').toBeTruthy();

    // --- Step 4: Mutate state (reset to different state) ---
    await resetSystem(1);

    // --- Step 5: Import the exported archive ---
    const imported = await importArchive(exported.body);
    expect(imported, 'import endpoint should work').toBeTruthy();
    expect(imported.res.status, 'import should succeed').toBeLessThan(300);

    // --- Step 6: Verify all state is restored ---

    // Account
    const afterAccount = await getAccount();
    expect(afterAccount, 'account should be available after import').toBeTruthy();
    expect(afterAccount.res.status).toBe(200);
    const afterCash = deepGet(afterAccount.body, 'availableCash', 'cash', 'available');
    expect(afterCash, 'cash should be defined after import').toBeDefined();
    expect(afterCash, 'cash should match pre-export value').toBe(beforeCash);

    // Positions
    const afterPositions = await getPositions();
    expect(afterPositions, 'positions should be available after import').toBeTruthy();
    expect(afterPositions.res.status).toBe(200);
    const afterPosList = extractList(afterPositions.body);
    expect(afterPosList.length, 'position count should match pre-export').toBe(beforePosList.length);

    // Orders/Records
    const afterOrders = await getOrders();
    expect(afterOrders, 'orders should be available after import').toBeTruthy();
    expect(afterOrders.res.status).toBe(200);
    const afterOrderList = extractList(afterOrders.body);
    expect(afterOrderList.length, 'order count should match pre-export').toBe(beforeOrderList.length);

    // Watchlist
    const afterWatchlist = await getWatchlist();
    expect(afterWatchlist, 'watchlist should be available after import').toBeTruthy();
    expect(afterWatchlist.res.status).toBe(200);

    // Market progress: verify AAA price is still at 11 (progress preserved)
    const afterMarketA = await getMarketPrice('AAA');
    expect(afterMarketA, 'AAA market should be available after import').toBeTruthy();
    expect(afterMarketA.res.status).toBe(200);
    const afterPriceA = getPrice(afterMarketA.body);
    expect(afterPriceA, 'AAA price should be defined after import').toBeDefined();
    expect(afterPriceA, 'AAA price should match pre-export (market progress preserved)').toBe(beforePriceA);

    // Verify market progress continues from where it was:
    // AAA was at step 1 (price 11), next advance should go to 12
    const advAfterImport = await advanceMarket('AAA');
    expect(advAfterImport, 'advance after import should work').toBeTruthy();
    expect(advAfterImport.res.status).toBeLessThan(300);
    const priceAfterAdvance = getPrice(advAfterImport.body);
    expect(priceAfterAdvance, 'price after advance should be defined').toBeDefined();
    expect(priceAfterAdvance, 'AAA should advance to 12 (continuing from imported progress)').toBe(12);

    // Analysis data
    if (beforeAnalysisBody) {
      const afterAnalysis = await getAnalysis();
      expect(afterAnalysis, 'analysis should be available after import').toBeTruthy();
      expect(afterAnalysis.res.status).toBe(200);
      expect(afterAnalysis.body, 'analysis data should be restored after import').toEqual(beforeAnalysisBody);
    }
  });
});

