describe('import_legacy_archive_with_defaults_and_reject_invalid', () => {
  it('should import legacy archive with defaults and reject invalid archive without overwriting current state', async () => {
    try {
      const baseline = await request('POST', '/api/test/reset-and-load', {
        account: { cash: 12345 },
        actions: []
      });
      expect([200, 201]).toContain(baseline.res.status);

      const beforeInvalid = await request('GET', '/api/state/full');
      expect(beforeInvalid.res.status).toBe(200);

      const legacy = {
        account: { cash: 10000, availableCash: 8000 },
        positions: [{ symbol: 'OLD', quantity: 10, averageCost: 50 }],
        trades: [{ symbol: 'OLD', side: 'BUY', quantity: 10, price: 50 }]
      };
      const importLegacy = await request('POST', '/api/archive/import', legacy);
      expect(importLegacy.res.status, `legacy import should succeed, got ${importLegacy.res.status}`).toBeLessThan(300);

      const afterLegacy = await request('GET', '/api/state/full');
      expect(afterLegacy.res.status).toBe(200);
      expect(afterLegacy.body.account, 'legacy import should restore account').toBeTruthy();
      expect(afterLegacy.body.positions, 'legacy import should restore positions').toBeTruthy();
      expect((afterLegacy.body.orders || []).length, 'missing orders should be defaulted to empty array').toBe(0);
      expect(afterLegacy.body.analysis || {}, 'missing analysis helpers should default to empty object or equivalent').toBeTruthy();

      const invalid = { account: 'wrong-type', positions: 'bad' };
      const invalidImport = await request('POST', '/api/archive/import', invalid);
      expect(invalidImport.res.status, `invalid archive should be rejected, got ${invalidImport.res.status}`).toBeGreaterThanOrEqual(400);

      const afterInvalid = await request('GET', '/api/state/full');
      expect(afterInvalid.res.status).toBe(200);
      expect(afterInvalid.body).toEqual(afterLegacy.body);

      const missingCritical = { positions: [] };
      const missingCriticalImport = await request('POST', '/api/archive/import', missingCritical);
      expect(missingCriticalImport.res.status, 'archive missing critical account info should be rejected').toBeGreaterThanOrEqual(400);
    } finally {
      try { await request('POST', '/api/test/reset'); } catch {}
    }
  });
});

