describe('update_fee_rates_affect_new_trades_only', () => {
  afterAll(async () => {
    await resetSystem();
  });

  it('should persist valid fee updates, reject invalid ones, and apply new rates only to new trades while keeping historical trades unchanged', async () => {
    await resetSystem();

    // Setup with known initial fee rates
    const initialCommission = 0.001;
    const initialStampDuty = 0.001;
    const seed = {
      account: { cash: 100000 },
      feeRates: { commission: initialCommission, stampDuty: initialStampDuty },
      marketSequences: { FEE: [10, 12, 15] },
      actions: []
    };
    const seedResult = await loadSeed(seed);
    if (seedResult) {
      expect(seedResult.res.status).toBeLessThan(300);
    }

    // Set initial fee rates explicitly
    const initialFeeSet = await setFees({ commission: initialCommission, stampDuty: initialStampDuty });
    expect(initialFeeSet, 'fee setting endpoint should work').toBeTruthy();
    expect(initialFeeSet.res.status).toBeLessThan(300);

    // First trade: buy 100 shares at 10 with initial fee rates
    const firstTrade = await placeOrder({
      symbol: 'FEE', side: 'BUY', quantity: 100, price: 10, type: 'MARKET'
    });
    expect(firstTrade, 'order endpoint should work').toBeTruthy();
    expect(firstTrade.res.status).toBeLessThan(300);

    // Record the first trade's fee for later comparison
    const recordsAfterFirst = await getRecords('?symbol=FEE');
    expect(recordsAfterFirst, 'records endpoint should work').toBeTruthy();
    expect(recordsAfterFirst.res.status).toBe(200);
    const listAfterFirst = extractList(recordsAfterFirst.body);
    expect(listAfterFirst.length, 'should have at least one record after first trade').toBeGreaterThanOrEqual(1);

    const firstBuyRecord = listAfterFirst.find(x => {
      const side = (x.side || x.direction || '').toUpperCase();
      return side === 'BUY';
    });
    expect(firstBuyRecord, 'should find first BUY trade record').toBeTruthy();
    const firstTradeFeeBeforeUpdate = getFeeValue(firstBuyRecord);

    // Expected fee for first trade: 100 * 10 * 0.001 = 1.0
    const expectedFirstFee = 100 * 10 * initialCommission;
    expect(firstTradeFeeBeforeUpdate, 'first trade fee should be a positive number').toBeGreaterThan(0);
    expect(firstTradeFeeBeforeUpdate, 'first trade fee should match initial commission rate').toBeCloseTo(expectedFirstFee, 2);

    // Get account state before fee update
    const accountBeforeUpdate = await getAccount();
    expect(accountBeforeUpdate, 'account endpoint should work').toBeTruthy();
    expect(accountBeforeUpdate.res.status).toBe(200);

    // --- Test invalid fee rates ---
    // Negative fee should be rejected
    const invalidNegative = await setFees({ commission: -0.1, stampDuty: 0.001 });
    expect(invalidNegative, 'negative fee request should get a response').toBeTruthy();
    expect(invalidNegative.res.status, 'negative fee should be rejected with 4xx').toBeGreaterThanOrEqual(400);

    // Unreasonably high fee should be rejected
    const invalidTooHigh = await setFees({ commission: 10, stampDuty: 10 });
    expect(invalidTooHigh, 'too high fee request should get a response').toBeTruthy();
    expect(invalidTooHigh.res.status, 'unreasonable fee should be rejected with 4xx').toBeGreaterThanOrEqual(400);

    // --- Update to new valid fee rates ---
    const newCommission = 0.002;
    const newStampDuty = 0.003;
    const updateResult = await setFees({ commission: newCommission, stampDuty: newStampDuty });
    expect(updateResult, 'valid fee update should succeed').toBeTruthy();
    expect(updateResult.res.status, 'valid fee update status should be success').toBeLessThan(300);

    // --- Verify fee rates persist (simulate refresh by re-reading) ---
    const currentFees = await getFees();
    expect(currentFees, 'fee GET endpoint should work').toBeTruthy();
    expect(currentFees.res.status).toBe(200);
    const feeBody = currentFees.body;
    const commission = feeBody.commission || feeBody.commissionRate || feeBody.data?.commission;
    const stampDuty = feeBody.stampDuty || feeBody.stampDutyRate || feeBody.data?.stampDuty;
    expect(commission, 'commission should persist after update').toBe(newCommission);
    expect(stampDuty, 'stamp duty should persist after update').toBe(newStampDuty);

    // --- Verify historical trade fee unchanged after fee update ---
    const recordsAfterUpdate = await getRecords('?symbol=FEE');
    expect(recordsAfterUpdate.res.status).toBe(200);
    const listAfterUpdate = extractList(recordsAfterUpdate.body);
    const firstBuyRecordAfterUpdate = listAfterUpdate.find(x => {
      const side = (x.side || x.direction || '').toUpperCase();
      return side === 'BUY';
    });
    expect(firstBuyRecordAfterUpdate, 'first BUY trade should still exist after fee update').toBeTruthy();
    const firstTradeFeeAfterUpdate = getFeeValue(firstBuyRecordAfterUpdate);
    expect(firstTradeFeeAfterUpdate, 'historical trade fee should NOT be recalculated after fee update').toBe(firstTradeFeeBeforeUpdate);

    // --- New buy trade with new fee rates to verify impact on position cost ---
    const secondBuy = await placeOrder({
      symbol: 'FEE', side: 'BUY', quantity: 100, price: 12, type: 'MARKET'
    });
    expect(secondBuy, 'second buy order should succeed').toBeTruthy();
    expect(secondBuy.res.status).toBeLessThan(300);

    // Verify position cost reflects new fee rate (cost should include commission)
    const positionsAfterSecondBuy = await getPositions();
    expect(positionsAfterSecondBuy, 'positions endpoint should work').toBeTruthy();
    expect(positionsAfterSecondBuy.res.status).toBe(200);
    const posList = positionsAfterSecondBuy.body?.positions || positionsAfterSecondBuy.body?.holdings ||
      positionsAfterSecondBuy.body?.data?.positions || (Array.isArray(positionsAfterSecondBuy.body) ? positionsAfterSecondBuy.body : []);
    const feePos = posList.find(p => (p.symbol || p.code) === 'FEE');
    expect(feePos, 'should have FEE position after second buy').toBeTruthy();
    const posCost = Number(feePos.costPrice || feePos.avgCost || feePos.averagePrice || feePos.averageCost || feePos.cost);
    expect(Number.isFinite(posCost), 'position cost should be a valid number').toBe(true);
    // With fees, the average cost should be higher than simple average of buy prices
    // First buy: 100 * 10 + fee(1.0) = 1001, Second buy: 100 * 12 + fee(100*12*0.002=2.4) = 1202.4
    // Weighted avg cost = (1001 + 1202.4) / 200 = 11.017 (approximately)
    // Without fees, simple avg would be (1000 + 1200) / 200 = 11.0
    // Cost should be >= 11.0 (fees make it slightly higher)
    expect(posCost, 'position cost should reflect fee inclusion (>= raw average)').toBeGreaterThanOrEqual(11.0);

    // --- Sell trade with new fee rates: sell 200 shares at 15 ---
    const sellTrade = await placeOrder({
      symbol: 'FEE', side: 'SELL', quantity: 200, price: 15, type: 'MARKET'
    });
    expect(sellTrade, 'sell order should succeed').toBeTruthy();
    expect(sellTrade.res.status).toBeLessThan(300);

    // Verify new sell trade has fee reflecting new rates
    const recordsAfterSell = await getRecords('?symbol=FEE');
    expect(recordsAfterSell.res.status).toBe(200);
    const listAfterSell = extractList(recordsAfterSell.body);
    const sellRecords = listAfterSell.filter(x => {
      const side = (x.side || x.direction || '').toUpperCase();
      return side === 'SELL';
    });
    expect(sellRecords.length, 'should find at least one SELL trade record').toBeGreaterThanOrEqual(1);
    const sellRecord = sellRecords[sellRecords.length - 1]; // latest sell
    const sellFee = getFeeValue(sellRecord);
    // Expected sell fee: commission = 200 * 15 * 0.002 = 6.0, stampDuty = 200 * 15 * 0.003 = 9.0, total = 15.0
    const expectedSellFee = 200 * 15 * newCommission + 200 * 15 * newStampDuty;
    expect(sellFee, 'new sell trade fee should be a positive number').toBeGreaterThan(0);
    expect(sellFee, 'new sell trade fee should reflect new fee rates').toBeCloseTo(expectedSellFee, 1);
    // New trade fee should differ from historical first trade fee
    expect(sellFee, 'new trade fee should differ from historical trade fee').not.toBe(firstTradeFeeBeforeUpdate);

    // --- Verify new fee affected available cash ---
    const accountAfterSell = await getAccount();
    expect(accountAfterSell.res.status).toBe(200);
    const cashAfterSell = extractCash(accountAfterSell.body);
    expect(Number.isFinite(cashAfterSell), 'available cash should be a valid number after sell').toBe(true);
    // Cash should reflect deduction of fees
    // Without any fees: 100000 - 1000 - 1200 + 3000 = 100800
    // With fees it should be less than 100800
    const cashWithoutFees = 100000 - (100 * 10) - (100 * 12) + (200 * 15);
    expect(cashAfterSell, 'cash should be less than no-fee scenario due to fee deductions').toBeLessThan(cashWithoutFees);
    expect(cashAfterSell, 'cash should still be positive').toBeGreaterThan(0);

    // --- Verify analysis shows cost-adjusted results ---
    const analysis = await getAnalysis();
    expect(analysis, 'analysis endpoint should work').toBeTruthy();
    expect(analysis.res.status).toBe(200);
    expect(analysis.body, 'analysis body should exist').toBeTruthy();

    // Check realized PnL reflects costs
    const realizedPnl = analysis.body.realizedPnl ?? analysis.body.realizedProfit ?? analysis.body.data?.realizedPnl ?? analysis.body.data?.realizedProfit;
    expect(realizedPnl !== undefined && realizedPnl !== null, 'realized PnL field should exist in analysis').toBe(true);
    // Raw profit from selling 200 @ 15 with avg cost ~11 = (15 - 11) * 200 = 800
    // After fees, realized PnL should be less than raw profit
    const rawProfit = (15 - 11) * 200;
    expect(Number(realizedPnl), 'realized PnL should be less than raw profit due to fee deduction').toBeLessThan(rawProfit);
    expect(Number(realizedPnl), 'realized PnL should still be positive').toBeGreaterThan(0);

    // Check if analysis indicates costs were deducted (look for cost-related fields)
    const totalCosts = analysis.body.totalCosts ?? analysis.body.totalFees ?? analysis.body.tradingCosts ?? analysis.body.data?.totalCosts ?? analysis.body.data?.totalFees;
    if (totalCosts !== undefined) {
      expect(Number(totalCosts), 'total trading costs should be positive if field exists').toBeGreaterThan(0);
    }
  });
});

