import { describe, it, expect, afterAll } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function request(method, path, body) {
  const res = await fetch(`${BASE_URL}${path}`, {
    method,
    headers: { 'Content-Type': 'application/json' },
    body: body === undefined ? undefined : JSON.stringify(body),
  });
  const text = await res.text();
  let json;
  try { json = text ? JSON.parse(text) : null; } catch { json = text; }
  return { res, body: json };
}

async function findEndpoint(method, candidates, body) {
  for (const path of candidates) {
    try {
      const result = await request(method, path, body);
      if (result.res.status < 500) return { path, ...result };
    } catch {}
  }
  return null;
}

async function resetSystem() {
  return findEndpoint('POST', ['/api/account/reset', '/api/test/reset', '/api/reset', '/reset'], { confirm: true });
}

async function loadSeed(seed) {
  return findEndpoint('POST', ['/api/test/reset-and-load', '/api/test/seed', '/api/seed'], seed);
}

async function placeOrder(payload) {
  return findEndpoint('POST', ['/api/orders', '/orders', '/api/trades/orders'], payload);
}

async function setFees(payload) {
  return findEndpoint('PUT', ['/api/settings/fees', '/api/fees', '/settings/fees', '/fees'], payload);
}

async function getFees() {
  return findEndpoint('GET', ['/api/settings/fees', '/api/fees', '/settings/fees', '/fees']);
}

async function addToWatchlist(symbol) {
  return findEndpoint('POST', ['/api/watchlist', '/api/watchlist/add', '/watchlist'], { symbol });
}

async function advanceMarket(symbol) {
  return findEndpoint('POST', ['/api/market/advance', '/api/market/next', '/market/advance'], { symbol });
}

async function getAccount() {
  return findEndpoint('GET', ['/api/account/summary', '/api/account', '/account']);
}

async function getPositions() {
  return findEndpoint('GET', ['/api/positions', '/api/holdings', '/positions']);
}

async function getRecords(params = '') {
  return findEndpoint('GET', [
    `/api/trading/records${params}`, `/api/records${params}`, `/api/orders${params}`, `/api/trades${params}`
  ]);
}

async function getWatchlist() {
  return findEndpoint('GET', ['/api/watchlist', '/watchlist']);
}

async function getAnalysis() {
  return findEndpoint('GET', ['/api/analysis/summary', '/api/analysis', '/analysis']);
}

async function importArchive(data) {
  return findEndpoint('POST', ['/api/archive/import', '/api/import', '/import', '/api/data/import'], data);
}

async function exportArchive() {
  return findEndpoint('GET', ['/api/archive/export', '/api/export', '/export', '/api/data/export']);
}

function extractCash(body) {
  if (!body) return NaN;
  return Number(
    body.availableCash ?? body.cash ?? body.available ?? body.availableFunds ??
    body.data?.availableCash ?? body.data?.cash ?? body.account?.availableCash ?? body.account?.cash ?? NaN
  );
}

function extractList(body) {
  if (!body) return [];
  return body.records || body.items || body.orders || body.deals || body.data?.records || (Array.isArray(body) ? body : []);
}

function extractPositionList(body) {
  if (!body) return [];
  if (Array.isArray(body)) return body;
  return body.positions || body.holdings || body.data?.positions || [];
}

function extractWatchlist(body) {
  if (!body) return [];
  if (Array.isArray(body)) return body;
  return body.watchlist || body.favorites || body.data?.watchlist || body.data?.favorites || body.items || [];
}

