        expect(cashAfterReset, 'cash should NOT be the archive value of 50000').not.toBe(50000);
      }
    }
    // If import endpoint doesn't exist, we at least verified the standard reset behavior above

    await resetSystem();
  });
});

import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function request(path, options = {}) {
  const res = await fetch(`${BASE_URL}${path}`, {
    headers: { 'Content-Type': 'application/json', ...(options.headers || {}) },
    ...options,
  });
  const text = await res.text();
  let body;
  try {
    body = text ? JSON.parse(text) : null;
  } catch {
    body = text;
  }
  return { res, body };
}

async function resetState() {
  for (const path of ['/api/account/reset', '/account/reset', '/api/reset', '/reset']) {
    try {
      const result = await request(path, { method: 'POST', body: JSON.stringify({ confirm: true }) });
      if (result.res.status < 500) return result;
    } catch {}
  }
}

async function getAccount() {
  for (const path of ['/api/account', '/account', '/api/account/summary', '/api/state', '/state']) {
    const result = await request(path).catch(() => null);
    if (result && result.res.status === 200) return result;
  }
  return null;
}

function extractCash(body) {
  return Number(
    body?.availableCash ??
    body?.cash ??
    body?.availableFunds ??
    body?.available ??
    body?.balance?.availableCash ??
    body?.data?.availableCash ??
    body?.data?.cash ??
    body?.account?.availableCash ??
    body?.account?.cash ??
    NaN
  );
}

function extractPositions(body) {
  if (Array.isArray(body?.positions)) return body.positions;
  return body?.positions || body?.holdings || body?.data?.positions || body?.account?.positions || [];
}

async function submitOrder(payload) {
  for (const path of ['/api/orders', '/orders', '/api/trades/orders', '/api/order']) {
    const result = await request(path, { method: 'POST', body: JSON.stringify(payload) }).catch(() => null);
    if (result && result.res.status < 500) return { path, ...result };
  }
  return null;
}

async function setPrice(symbol, price) {
  for (const path of ['/api/market/price', '/market/price', '/api/quotes', '/quotes']) {
    try {
      const r = await request(path, {
        method: 'POST',
        body: JSON.stringify({ symbol, latestPrice: price, currentPrice: price, market: 'SH' })
      });
      if (r.res.status < 500) return r;
    } catch {}
  }
  return null;
}

