import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function request(path, options = {}) {
  const res = await fetch(`${BASE_URL}${path}`, {
    headers: { 'Content-Type': 'application/json', ...(options.headers || {}) },
    ...options,
  });
  const text = await res.text();
  let body;
  try {
    body = text ? JSON.parse(text) : null;
  } catch {
    body = text;
  }
  return { res, body };
}

async function resetState() {
  for (const path of ['/api/account/reset', '/account/reset', '/api/reset', '/reset']) {
    try {
      const result = await request(path, { method: 'POST', body: JSON.stringify({ confirm: true }) });
      if (result.res.status < 500) return;
    } catch {}
  }
}

async function submitOrder(payload) {
  for (const path of ['/api/orders', '/orders', '/api/trades/orders', '/api/order']) {
    const result = await request(path, { method: 'POST', body: JSON.stringify(payload) }).catch(() => null);
    if (result && result.res.status < 500) return { path, ...result };
  }
  return null;
}

async function getOrders() {
  for (const path of ['/api/orders', '/orders', '/api/trades/orders', '/api/trading/records']) {
    const result = await request(path).catch(() => null);
    if (result && result.res.status === 200) return result;
  }
  return null;
}

function extractOrderList(body) {
  if (Array.isArray(body)) return body;
  return body?.orders || body?.entrusts || body?.records || body?.data?.orders || body?.data?.records || body?.data || [];
}

async function getAccount() {
  for (const path of ['/api/account', '/account', '/api/account/summary', '/api/state', '/state']) {
    const result = await request(path).catch(() => null);
    if (result && result.res.status === 200) return result;
  }
  return null;
}

function extractCash(body) {
  return Number(
    body?.availableCash ?? body?.cash ?? body?.available ?? body?.availableFunds ??
    body?.balance?.availableCash ?? body?.data?.availableCash ?? body?.data?.cash ??
    body?.account?.availableCash ?? body?.account?.cash ?? NaN
  );
}

function extractPositions(body) {
  if (Array.isArray(body?.positions)) return body.positions;
  return body?.positions || body?.holdings || body?.data?.positions || body?.account?.positions || [];
}

async function cancelOrder(orderId) {
  for (const path of [`/api/orders/${orderId}/cancel`, `/orders/${orderId}/cancel`, `/api/orders/${orderId}`, `/orders/${orderId}`]) {
    const method = /\/cancel$/.test(path) ? 'POST' : 'DELETE';
    const result = await request(path, { method }).catch(() => null);
    if (result && result.res.status < 500) return result;
  }
  return null;
}

async function setPrice(symbol, price) {
  for (const path of ['/api/market/price', '/market/price', '/api/quotes', '/quotes']) {
    try {
      const r = await request(path, {
        method: 'POST',
        body: JSON.stringify({ symbol, latestPrice: price, currentPrice: price, market: 'SH' })
      });
      if (r.res.status < 500) return r;
    } catch {}
  }
  return null;
}

async function clearPrice(symbol) {
  // Try to clear/remove price
  for (const path of ['/api/market/price', '/market/price', '/api/quotes', '/quotes']) {
    try {
      await request(path, {
        method: 'POST',
        body: JSON.stringify({ symbol, latestPrice: null, currentPrice: null, market: 'SH' })
      });
    } catch {}
  }
  for (const path of [`/api/market/price/${symbol}`, `/market/price/${symbol}`, `/api/quotes/${symbol}`]) {
    try { await request(path, { method: 'DELETE' }); } catch {}
  }
}

function getStatus(order) {
  return String(order.status || '').toLowerCase();
}

function isFilled(order) {
  return /filled|done|matched|成交|completed|executed/i.test(getStatus(order));
}

function isPending(order) {
  return /pending|open|委托|未成交|unfilled|waiting/i.test(getStatus(order));
}

function isCancelled(order) {
  return /cancel|撤/i.test(getStatus(order));
}

describe('round7_order_matching_and_cancel', () => {
  it('should fill buy order when price >= current price, keep pending when price < current price', async () => {
    await resetState();

    const symbol = 'TEST_R7_ORD_001';
    await setPrice(symbol, 10);

    // Get initial account state
    const initialAccount = await getAccount();
    expect(initialAccount, '应能查询初始账户').toBeTruthy();
    const initialCash = extractCash(initialAccount.body);

    // Order 1: price=10 >= currentPrice=10 → should fill
    const filledOrder = await submitOrder({
      symbol, market: 'SH', side: 'BUY', price: 10, quantity: 100, validity: 'DAY'
    });
