    expect([200, 201, 202].includes(filledOrder.res.status),
      `买单应成功提交，实际: ${filledOrder.res.status}`).toBe(true);

    // Order 2: price=9 < currentPrice=10 → should stay pending
    const pendingOrder1 = await submitOrder({
      symbol, market: 'SH', side: 'BUY', price: 9, quantity: 100, validity: 'DAY'
    });
    expect(pendingOrder1, '应能提交买单(price=9)').toBeTruthy();
    expect([200, 201, 202].includes(pendingOrder1.res.status),
      `买单应成功提交，实际: ${pendingOrder1.res.status}`).toBe(true);

    // Order 3: duplicate of order 2
    const pendingOrder2 = await submitOrder({
      symbol, market: 'SH', side: 'BUY', price: 9, quantity: 100, validity: 'DAY'
    });
    expect(pendingOrder2, '应能提交重复买单(price=9)').toBeTruthy();
    expect([200, 201, 202].includes(pendingOrder2.res.status),
      `重复买单应成功提交`).toBe(true);

    // Verify order list
    const listResult = await getOrders();
    expect(listResult, '应存在委托查询接口').toBeTruthy();
    const orders = extractOrderList(listResult.body);
    expect(Array.isArray(orders), `委托列表应为数组`).toBe(true);

    const targetOrders = orders.filter((o) => (o.symbol || o.code) === symbol);
    expect(targetOrders.length, `应至少有3笔订单，实际: ${targetOrders.length}`).toBeGreaterThanOrEqual(3);

    const filledOrders = targetOrders.filter(isFilled);
    const pendingOrders = targetOrders.filter(isPending);
    expect(filledOrders.length, `应有至少1笔已成交订单，实际: ${JSON.stringify(targetOrders.map(o => o.status))}`).toBeGreaterThanOrEqual(1);
    expect(pendingOrders.length, `应有至少2笔未成交订单，实际: ${JSON.stringify(targetOrders.map(o => o.status))}`).toBeGreaterThanOrEqual(2);

    // Verify filled order affected cash and position
    const afterAccount = await getAccount();
