  it('should reject or prevent order entry when current price is unavailable', async () => {
    await resetState();

    const symbol = 'TEST_R7_NOPRICE';
    // Do NOT set any price for this symbol
    await clearPrice(symbol);

    const orderResult = await submitOrder({
      symbol, market: 'SH', side: 'BUY', price: 10, quantity: 100, validity: 'DAY'
    });
    expect(orderResult, '应存在下单接口').toBeTruthy();

    // When current price is unavailable, the system should either:
    // 1. Reject the order with 4xx, OR
    // 2. Accept but keep it pending (not enter matching) with a warning
    if ([400, 422, 403].includes(orderResult.res.status)) {
      // Rejected — verify error message mentions price unavailable
      const errMsg = JSON.stringify(orderResult.body).toLowerCase();
      expect(errMsg).toMatch(/价格|price|不可用|unavailable|行情|market|quote/);
    } else if ([200, 201, 202].includes(orderResult.res.status)) {
