  it('should cancel pending order, update status, reject re-cancel, and reject cancel on filled order', async () => {
    await resetState();

    const symbol = 'TEST_R7_CANCEL';
    await setPrice(symbol, 10);

    // Get cash before any orders
    const accountBefore = await getAccount();
    expect(accountBefore, '应能查询账户').toBeTruthy();
    const cashBefore = extractCash(accountBefore.body);

    // Create a pending order (price < current for buy)
    const pendResult = await submitOrder({
      symbol, market: 'SH', side: 'BUY', price: 8, quantity: 100, validity: 'DAY'
    });
    expect(pendResult, '应能提交挂单').toBeTruthy();

    // Get cash after pending order (should be same since pending doesn't affect cash... or may freeze)
    const accountAfterPending = await getAccount();
    const cashAfterPending = extractCash(accountAfterPending.body);

    // Also create a filled order for later cancel rejection test
    const filledResult = await submitOrder({
      symbol, market: 'SH', side: 'BUY', price: 10, quantity: 100, validity: 'DAY'
    });
    expect(filledResult, '应能提交成交单').toBeTruthy();

    const listResult = await getOrders();
    const orders = extractOrderList(listResult.body);
    const pendingOrder = orders.find((o) => (o.symbol || o.code) === symbol && isPending(o));
    expect(pendingOrder, '应找到未成交委托').toBeTruthy();
    const filledOrder = orders.find((o) => (o.symbol || o.code) === symbol && isFilled(o));
    expect(filledOrder, '应找到已成交订单').toBeTruthy();

    const cancelId = pendingOrder.id || pendingOrder.orderId;
    expect(cancelId, '委托应包含 id').toBeTruthy();

    // Cancel the pending order
    const cancelResult = await cancelOrder(cancelId);
    expect(cancelResult, '应存在可用的撤单接口').toBeTruthy();
    expect([200, 204].includes(cancelResult.res.status),
      `撤单状态码异常: ${cancelResult.res.status}`).toBe(true);

    // Verify cancelled status
    const afterList = await getOrders();
    const afterOrders = extractOrderList(afterList.body);
    const cancelledOrder = afterOrders.find((o) => String(o.id || o.orderId) === String(cancelId));
    expect(cancelledOrder, '撤单后订单记录仍应保留').toBeTruthy();
    expect(isCancelled(cancelledOrder), `撤单后状态应为已撤销，实际: ${cancelledOrder.status}`).toBe(true);

    // Verify cancel did not affect cash/positions (pending orders shouldn't)
    const accountAfterCancel = await getAccount();
    const cashAfterCancel = extractCash(accountAfterCancel.body);
    // Cash should be same as after the pending order was placed (cancel just releases it)
    // At minimum, cash should not have decreased due to cancel
    expect(Number.isFinite(cashAfterCancel), 'cash after cancel should be valid').toBe(true);

    // Try to cancel the same order again — should be rejected
    const reCancelResult = await cancelOrder(cancelId);
    expect(reCancelResult, '重复撤单应返回结果').toBeTruthy();
    expect([400, 422, 409, 403].includes(reCancelResult.res.status),
      `已撤销委托不能再次撤销，实际状态码: ${reCancelResult.res.status}`).toBe(true);

    // Try to cancel the filled order — should also be rejected
    const filledId = filledOrder.id || filledOrder.orderId;
    expect(filledId, '已成交订单应有id').toBeTruthy();
    const cancelFilledResult = await cancelOrder(filledId);
    expect(cancelFilledResult, '对已成交订单撤单应返回结果').toBeTruthy();
    expect([400, 422, 409, 403].includes(cancelFilledResult.res.status),
      `已成交订单不能撤销，实际状态码: ${cancelFilledResult.res.status}`).toBe(true);

    await resetState();
  });

  it('should keep multiple identical orders as separate records', async () => {
    await resetState();

    const symbol = 'TEST_R7_DUP';
    await setPrice(symbol, 10);

    // Submit 3 identical pending orders
    for (let i = 0; i < 3; i++) {
      const result = await submitOrder({
        symbol, market: 'SH', side: 'BUY', price: 8, quantity: 100, validity: 'DAY'
      });
      expect(result, `第 ${i + 1} 笔重复订单应成功提交`).toBeTruthy();
      expect([200, 201, 202].includes(result.res.status)).toBe(true);
    }

    const listResult = await getOrders();
    const orders = extractOrderList(listResult.body);
    const targetOrders = orders.filter((o) => (o.symbol || o.code) === symbol);
    expect(targetOrders.length, `3笔相同内容订单应分别保留，实际: ${targetOrders.length}`).toBeGreaterThanOrEqual(3);

    // All should have unique ids
    const ids = targetOrders.map(o => String(o.id || o.orderId));
    const uniqueIds = new Set(ids);
    expect(uniqueIds.size, `每笔订单应有唯一ID，实际IDs: ${JSON.stringify(ids)}`).toBe(targetOrders.length);

    await resetState();
  });
});

import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function request(path, options = {}) {
  const res = await fetch(`${BASE_URL}${path}`, {
    headers: { 'Content-Type': 'application/json', ...(options.headers || {}) },
    ...options,
  });
  const text = await res.text();
  let body;
  try {
    body = text ? JSON.parse(text) : null;
  } catch {
    body = text;
  }
  return { res, body };
}

async function resetState() {
  for (const path of ['/api/account/reset', '/account/reset', '/api/reset', '/reset']) {
    try {
      const result = await request(path, { method: 'POST', body: JSON.stringify({}) });
      if (result.res.status < 500) return;
    } catch {}
  }
}

async function submitOrder(payload) {
  for (const path of ['/api/orders', '/orders', '/api/trades/orders', '/api/order']) {
    const result = await request(path, { method: 'POST', body: JSON.stringify(payload) }).catch(() => null);
    if (result && [200, 201, 202].includes(result.res.status)) return result;
  }
  return null;
}

async function setPrice(symbol, price) {
  for (const path of ['/api/market/price', '/market/price', '/api/quotes', '/quotes']) {
    try {
      const r = await request(path, {
        method: 'POST',
        body: JSON.stringify({ symbol, latestPrice: price, currentPrice: price, market: 'SH' })
      });
      if (r.res.status < 500) return r;
    } catch {}
  }
  return null;
}

async function getAnalysis() {
  for (const path of ['/api/analysis/overview', '/analysis/overview', '/api/analysis', '/analysis', '/api/analysis/summary']) {
    const result = await request(path).catch(() => null);
    if (result && result.res.status === 200) return result;
  }
  return null;
}

function extractOverview(body) {
  return body?.overview || body?.data || body;
}

describe('round10_analysis_overview_metrics', () => {
  it('should show win rate as uncalculable when no sell trades exist', async () => {
    await resetState();

