    const overviewBefore = extractOverview(analysisBefore.body);
    expect(overviewBefore && typeof overviewBefore === 'object', '分析概览应为对象').toBe(true);

    // Before sell, realized PnL should be 0 or absent
    const realizedBefore = Number(overviewBefore.realizedPnl ?? overviewBefore.totalRealizedPnl ?? overviewBefore.realized_pnl ?? 0);
    expect(realizedBefore, '卖出前累计已实现盈亏应为0').toBe(0);

    // Win rate before sell should still be uncalculable
    const winRateBefore = overviewBefore.winRate ?? overviewBefore.win_rate;
    const isUncalcBefore = winRateBefore === null || winRateBefore === undefined ||
      (typeof winRateBefore === 'string' && /不可|N\/A|--|-/i.test(winRateBefore)) ||
