    // --- Check analysis AFTER selling (verify 联动更新) ---
    const analysisAfter = await getAnalysis();
    expect(analysisAfter, '卖出后应存在分析概览接口').toBeTruthy();

    const overview = extractOverview(analysisAfter.body);
    expect(overview && typeof overview === 'object', '分析概览应为对象').toBe(true);

    // Realized PnL: sold 100 at 13, cost was 11 → realized ≈ (13-11)*100 = 200 (before trading costs)
    const realized = Number(overview.realizedPnl ?? overview.totalRealizedPnl ?? overview.realized_pnl);
    expect(Number.isFinite(realized), `累计已实现盈亏应为有效数字，实际: ${JSON.stringify(overview)}`).toBe(true);
    // Allow slight deviation for trading costs
    expect(realized).toBeGreaterThan(150);
    expect(realized).toBeLessThanOrEqual(200);

    // Unrealized PnL: still hold 100 shares at cost 11, current price 13 → (13-11)*100 = 200
    const floating = Number(overview.unrealizedPnl ?? overview.floatingPnl ?? overview.currentUnrealizedPnl ?? overview.unrealized_pnl);
    expect(Number.isFinite(floating), `浮动盈亏应为有效数字，实际: ${JSON.stringify(overview)}`).toBe(true);
    expect(floating).toBeGreaterThan(150);
