describe('round11_symbol_performance_summary', () => {
  it('should summarize symbols from executed trades only, keep closed symbols, not include pending-only symbols, and sort by total contribution desc', async () => {
    await resetState();

    const a = 'TEST_R11_A';
    const b = 'TEST_R11_B';
    const c = 'TEST_R11_C'; // will only have pending order, never filled

    await setPrice(a, 12);
    await setPrice(b, 20);
    await setPrice(c, 50);

    // Symbol A: buy 100 at 12 (fills since price=12, 12>=12), then sell 100 at 14 (need price >= 14 first)
    const buyA = await submitOrder({ symbol: a, market: 'SH', side: 'BUY', price: 12, quantity: 100, validity: 'DAY' });
    expect(buyA, '应能买入A').toBeTruthy();

    await setPrice(a, 14);
    const sellA = await submitOrder({ symbol: a, market: 'SH', side: 'SELL', price: 14, quantity: 100, validity: 'DAY' });
    expect(sellA, '应能卖出A').toBeTruthy();

    // Symbol B: buy 100 at 20 (current=20, fills)
    const buyB = await submitOrder({ symbol: b, market: 'SH', side: 'BUY', price: 20, quantity: 100, validity: 'DAY' });
    expect(buyB, '应能买入B').toBeTruthy();
    // B stays as holding, current price is 20, let's change to 18 for negative floating
    await setPrice(b, 18);

    // Symbol C: only a pending order that won't fill (buy at 30, current price 50, 30 < 50 → won't fill)
    const pendC = await submitOrder({ symbol: c, market: 'SH', side: 'BUY', price: 30, quantity: 100, validity: 'DAY' });
    expect(pendC, '应能提交C的挂单').toBeTruthy();

