    const rows = extractRows(summaryResult.body);
    expect(Array.isArray(rows), `品种汇总结果应为数组，实际: ${JSON.stringify(summaryResult.body)}`).toBe(true);

    // Symbol C should NOT appear (only pending, never filled)
    const rowC = rows.find((r) => (r.symbol || r.code) === c);
    expect(rowC, `从未成交的品种 ${c} 不应出现在汇总中，实际: ${JSON.stringify(rows.map(r => r.symbol || r.code))}`).toBeFalsy();

    // Symbol A should exist (closed position)
    const rowA = rows.find((r) => (r.symbol || r.code) === a);
    expect(rowA, `已清仓品种 ${a} 仍应保留在汇总中`).toBeTruthy();

    // Symbol B should exist (open position)
    const rowB = rows.find((r) => (r.symbol || r.code) === b);
    expect(rowB, `持仓品种 ${b} 应存在于汇总中`).toBeTruthy();

    // Verify key fields on rowA
    const buyQtyA = Number(rowA.totalBuyQuantity ?? rowA.buyQuantity ?? rowA.totalBuy ?? rowA.buy_quantity);
    expect(Number.isFinite(buyQtyA), `品种A应有累计买入数量字段`).toBe(true);
