    expect(sellQtyA, `品种A累计卖出数量应为 100`).toBe(100);

    const remainA = Number(rowA.remainingPosition ?? rowA.currentPosition ?? rowA.holdingQuantity ?? rowA.remaining ?? 0);
    expect(remainA, `品种A已清仓，剩余持仓应为 0`).toBe(0);

    const realizedA = Number(rowA.realizedPnl ?? rowA.realized_pnl ?? rowA.realizedProfit);
    expect(Number.isFinite(realizedA), `品种A应有已实现盈亏字段`).toBe(true);
    // Bought at 12, sold at 14, qty 100 → realized = 200
    expect(realizedA, `品种A已实现盈亏应为 200`).toBe(200);

    // Closed position floating pnl should be 0 or not available, not stale
    const floatingA = rowA.unrealizedPnl ?? rowA.floatingPnl ?? rowA.floating_pnl;
    const floatAVal = Number(floatingA);
    expect(
      floatingA === null || floatingA === undefined || floatAVal === 0 || floatingA === 'N/A' || floatingA === '--',
      `已清仓品种浮动盈亏不应沿用旧值，实际: ${JSON.stringify(floatingA)}`
    ).toBe(true);

    // Verify key fields on rowB
    const buyQtyB = Number(rowB.totalBuyQuantity ?? rowB.buyQuantity ?? rowB.totalBuy ?? rowB.buy_quantity);
    expect(buyQtyB, `品种B累计买入数量应为 100`).toBe(100);

    const remainB = Number(rowB.remainingPosition ?? rowB.currentPosition ?? rowB.holdingQuantity ?? rowB.remaining);
    expect(remainB, `品种B剩余持仓应为 100`).toBe(100);

    // Verify default sort: total contribution descending
    // A: realized 200, floating 0, total ~200
    // B: realized 0, floating (18-20)*100 = -200, total ~ -200
    const totalA = Number(rowA.totalPnl ?? rowA.totalContribution ?? rowA.totalProfit ?? rowA.total_pnl);
    const totalB = Number(rowB.totalPnl ?? rowB.totalContribution ?? rowB.totalProfit ?? rowB.total_pnl);
    expect(Number.isFinite(totalA) && Number.isFinite(totalB), '应有总收益贡献字段').toBe(true);

    // In the default descending list, A should appear before B
    const idxA = rows.findIndex((r) => (r.symbol || r.code) === a);
    const idxB = rows.findIndex((r) => (r.symbol || r.code) === b);
    expect(idxA, `品种A（收益更高）应排在品种B前面`).toBeLessThan(idxB);
    expect(totalA, `A的总收益应大于B，A=${totalA}, B=${totalB}`).toBeGreaterThan(totalB);

    await resetState();
  });
});

