describe('round13_order_validity_recheck', () => {
  it('should allow both DAY and GTC orders to fill when price is met during recheck, and distinguish validity types', async () => {
    await resetState();

    const symbol = 'TEST_R13_A';
    // Set initial price above the limit price so orders remain pending
    await setMarketPrice(symbol, 15);

    // Create a DAY order and a GTC order, both buying at 9
    const dayResult = await createOrder({ symbol, market: 'SH', side: 'BUY', price: 9, quantity: 100, validity: 'DAY' });
    expect(dayResult, 'Should create DAY order').toBeTruthy();
    const dayId = dayResult.body?.id || dayResult.body?.orderId;

    const gtcResult = await createOrder({ symbol, market: 'SH', side: 'BUY', price: 9, quantity: 100, validity: 'GTC' });
    expect(gtcResult, 'Should create GTC order').toBeTruthy();
    const gtcId = gtcResult.body?.id || gtcResult.body?.orderId;

    // Verify both are pending initially
    let orders = await getOrders();
    const dayBefore = orders.find(o => String(o.id || o.orderId) === String(dayId));
    const gtcBefore = orders.find(o => String(o.id || o.orderId) === String(gtcId));

    expect(dayBefore, 'DAY order should exist in order list').toBeTruthy();
    expect(gtcBefore, 'GTC order should exist in order list').toBeTruthy();

    // Verify validity types are distinguishable and non-empty
    const dayValBefore = String(dayBefore.validity || dayBefore.timeInForce || '').toUpperCase();
    const gtcValBefore = String(gtcBefore.validity || gtcBefore.timeInForce || '').toUpperCase();
    expect(dayValBefore.length).toBeGreaterThan(0);
    expect(gtcValBefore.length).toBeGreaterThan(0);
    expect(dayValBefore).toMatch(/DAY|当日/);
    expect(gtcValBefore).toMatch(/GTC|UNTIL|长期|永久/);
    expect(dayValBefore).not.toBe(gtcValBefore);

    // Now drop price to 9 so limit orders should fill
    await setMarketPrice(symbol, 9);

    // Trigger recheck (simulates page refresh or switching to this symbol)
    await triggerRecheck(symbol);

    // Both DAY and GTC orders should now be filled since price condition is met within the same day
    orders = await getOrders();
    const dayAfter = orders.find(o => String(o.id || o.orderId) === String(dayId));
    const gtcAfter = orders.find(o => String(o.id || o.orderId) === String(gtcId));

    expect(dayAfter, 'DAY order should still exist in list').toBeTruthy();
    expect(gtcAfter, 'GTC order should still exist in list').toBeTruthy();

    expect(String(gtcAfter.status).toLowerCase()).toMatch(/filled|done|matched|成交|success/);
    expect(String(dayAfter.status).toLowerCase()).toMatch(/filled|done|matched|成交|success/);

    // Verify validity identifiers are still distinguishable after fill
    const dayValidity = String(dayAfter.validity || dayAfter.timeInForce || '').toUpperCase();
    const gtcValidity = String(gtcAfter.validity || gtcAfter.timeInForce || '').toUpperCase();
    expect(dayValidity.length).toBeGreaterThan(0);
    expect(gtcValidity.length).toBeGreaterThan(0);
    expect(dayValidity).not.toBe(gtcValidity);

    await resetState();
  });

  it('should not re-process already filled or cancelled orders during recheck', async () => {
    await resetState();

    const symbol = 'TEST_R13_B';
    // Set price so buy order fills immediately (buy at 10, price is 10)
    await setMarketPrice(symbol, 10);

    const filledResult = await createOrder({ symbol, market: 'SH', side: 'BUY', price: 10, quantity: 100, validity: 'GTC' });
    expect(filledResult, 'Should create order to be filled').toBeTruthy();
    const filledId = filledResult.body?.id || filledResult.body?.orderId;

    // Trigger recheck to ensure the order fills if not already immediate
    await triggerRecheck(symbol);

    // Verify order is actually filled BEFORE proceeding
    let ordersBefore = await getOrders();
    const filledBefore = ordersBefore.find(o => String(o.id || o.orderId) === String(filledId));
    expect(filledBefore, 'Filled order should exist').toBeTruthy();
    expect(String(filledBefore.status).toLowerCase(), 'Order should be filled before recheck test').toMatch(/filled|done|matched|成交|success/);

    // Create an order that stays pending, then cancel it
    await setMarketPrice(symbol, 15);
    const cancelResult = await createOrder({ symbol, market: 'SH', side: 'BUY', price: 5, quantity: 100, validity: 'GTC' });
    expect(cancelResult, 'Should create order to be cancelled').toBeTruthy();
    const cancelId = cancelResult.body?.id || cancelResult.body?.orderId;

    // Cancel the second order
    await cancelOrder(cancelId);

    // Verify cancelled status BEFORE recheck
    ordersBefore = await getOrders();
    const cancelledBefore = ordersBefore.find(o => String(o.id || o.orderId) === String(cancelId));
    if (cancelledBefore) {
      expect(String(cancelledBefore.status).toLowerCase(), 'Order should be cancelled').toMatch(/cancel|撤/);
    }

    // Now set price to 5 which would match the cancelled order's price, then trigger recheck
    await setMarketPrice(symbol, 5);
    await triggerRecheck(symbol);

    // Verify states haven't changed for filled and cancelled orders
    let ordersAfter = await getOrders();
    const filledAfter = ordersAfter.find(o => String(o.id || o.orderId) === String(filledId));
    const cancelledAfter = ordersAfter.find(o => String(o.id || o.orderId) === String(cancelId));

    expect(filledAfter, 'Filled order should still exist').toBeTruthy();
    expect(String(filledAfter.status).toLowerCase()).toMatch(/filled|done|matched|成交|success/);

    if (cancelledAfter) {
      expect(String(cancelledAfter.status).toLowerCase()).toMatch(/cancel|撤/);
      // Cancelled order must NOT have become filled
      expect(String(cancelledAfter.status).toLowerCase()).not.toMatch(/filled|done|matched|成交|success/);
    }

    await resetState();
  });

  it('should preserve pending orders when price condition is not met after recheck (not just when price is unavailable)', async () => {
    await resetState();

    const symbol = 'TEST_R13_PRESERVE';
    // Set current price to 20, but buy order at 10 — condition not met
    await setMarketPrice(symbol, 20);

    const result = await createOrder({ symbol, market: 'SH', side: 'BUY', price: 10, quantity: 100, validity: 'GTC' });
    expect(result, 'Should create pending order').toBeTruthy();
    const orderId = result.body?.id || result.body?.orderId;

    // Trigger recheck — price is 20, buy limit is 10, should NOT fill
    await triggerRecheck(symbol);

    const orders = await getOrders();
    const order = orders.find(o => String(o.id || o.orderId) === String(orderId));
    expect(order, 'Pending order should still exist in list after recheck').toBeTruthy();
    expect(String(order.status).toLowerCase()).not.toMatch(/filled|done|matched|成交|success/);
    expect(String(order.status).toLowerCase()).toMatch(/pending|open|未成交|委托|waiting/);

    await resetState();
  });

  it('should keep pending orders unchanged when current price is unavailable', async () => {
    await resetState();

    const symbolNoPrice = 'TEST_R13_NOPRICE';
    // First set a price so we can create an order, then make it unavailable
    await setMarketPrice(symbolNoPrice, 20);

    const result = await createOrder({ symbol: symbolNoPrice, market: 'SH', side: 'BUY', price: 10, quantity: 100, validity: 'GTC' });
    expect(result, 'Should create order for price-unavailable test').toBeTruthy();
    const orderId = result.body?.id || result.body?.orderId;

    // Verify order is pending
    let orders = await getOrders();
    let order = orders.find(o => String(o.id || o.orderId) === String(orderId));
    expect(order, 'Order should exist before price removal').toBeTruthy();
    expect(String(order.status).toLowerCase()).toMatch(/pending|open|未成交|委托|waiting/);

    // Try to clear the price to simulate unavailable market data
    for (const path of ['/api/market/price', '/market/price', '/api/quotes', '/quotes']) {
      try {
        await request(path, {
          method: 'POST',
          body: JSON.stringify({ symbol: symbolNoPrice, latestPrice: null, currentPrice: null, market: 'SH' })
        });
      } catch {}
    }

    // Trigger recheck - should not error and should not fill the order
    await triggerRecheck(symbolNoPrice);

    orders = await getOrders();
    order = orders.find(o => String(o.id || o.orderId) === String(orderId));
    expect(order, 'Order should still exist after recheck with unavailable price').toBeTruthy();
    // Order should remain pending/open, not filled
    expect(String(order.status).toLowerCase()).not.toMatch(/filled|done|matched|成交|success/);
    expect(String(order.status).toLowerCase()).toMatch(/pending|open|未成交|委托|waiting/);

    await resetState();
  });
});

