describe('round17_fee_settings_apply_only_new_trades', () => {
  it('should apply buy commission only, sell commission + stamp duty, each trade calculated independently', async () => {
    await resetState();

    const symbol = 'TEST_R17_FEE_001';
    const commissionRate = 0.001;
    const stampDutyRate = 0.001;
    const price = 10;
    const quantity = 100;

    const setResult = await setFees({ commissionRate, stampDutyRate });
    expect(setResult, 'Fee settings API should exist and respond').toBeTruthy();
    expect([200, 201].includes(setResult.res.status), `Set fees status: ${setResult.res.status}`).toBe(true);

    // Set market price so orders fill immediately
    await setMarketPrice(symbol, price);

    // Place a BUY order
    const buyResult = await createOrder({ symbol, market: 'SH', side: 'BUY', price, quantity, validity: 'DAY' });
    expect(buyResult, 'Should create BUY order').toBeTruthy();

    // Place a SELL order at same price
    const sellResult = await createOrder({ symbol, market: 'SH', side: 'SELL', price, quantity, validity: 'DAY' });
    expect(sellResult, 'Should create SELL order').toBeTruthy();

    const trades = await getTrades();
    const filledTrades = trades.filter(t => (t.symbol || t.code) === symbol && isFilled(t));

    // Must have at least 2 filled trades (buy + sell)
    expect(filledTrades.length, `应有至少2笔成交记录，实际: ${filledTrades.length}`).toBeGreaterThanOrEqual(2);

    const buyTrades = filledTrades.filter(t => String(t.side || t.direction || '').toUpperCase().match(/BUY|买/));
    const sellTrades = filledTrades.filter(t => String(t.side || t.direction || '').toUpperCase().match(/SELL|卖/));

    expect(buyTrades.length, '应有买入成交记录').toBeGreaterThanOrEqual(1);
    expect(sellTrades.length, '应有卖出成交记录').toBeGreaterThanOrEqual(1);

    // Expected fees
    const expectedBuyFee = price * quantity * commissionRate; // buy: commission only = 1
    const expectedSellFee = price * quantity * (commissionRate + stampDutyRate); // sell: commission + stamp duty = 2

    // Verify buy trade fee (commission only, no stamp duty)
    const buyFee = getTradeFee(buyTrades[0]);
    expect(Number.isFinite(buyFee), `买入手续费应为有效数字，实际: ${buyFee}`).toBe(true);
    expect(Math.abs(buyFee - expectedBuyFee), `买入手续费应约为${expectedBuyFee}，实际: ${buyFee}`).toBeLessThan(0.01);

    // Verify sell trade fee (commission + stamp duty)
    const sellFee = getTradeFee(sellTrades[0]);
    expect(Number.isFinite(sellFee), `卖出手续费应为有效数字，实际: ${sellFee}`).toBe(true);
    expect(Math.abs(sellFee - expectedSellFee), `卖出手续费应约为${expectedSellFee}，实际: ${sellFee}`).toBeLessThan(0.01);

    // Sell fee should be greater than buy fee due to stamp duty
    expect(sellFee, '卖出手续费应大于买入手续费（因印花税）').toBeGreaterThan(buyFee);

    // Verify each trade has independent fee field (not merged)
    for (const t of filledTrades) {
      const fee = getTradeFee(t);
      expect(Number.isFinite(fee), `Each trade should have its own fee field: ${JSON.stringify(t)}`).toBe(true);
    }

    await resetState();
  });

  it('should not recalculate historical trade fees when fee settings change', async () => {
    await resetState();

    const symbol = 'TEST_R17_HIST';
    const oldFees = { commissionRate: 0.001, stampDutyRate: 0.001 };
    const newFees = { commissionRate: 0.003, stampDutyRate: 0.003 };

    await setFees(oldFees);
    await setMarketPrice(symbol, 10);

    // Create trades with old fees
    const buyOld = await createOrder({ symbol, market: 'SH', side: 'BUY', price: 10, quantity: 100, validity: 'DAY' });
    expect(buyOld, 'Should create old trade').toBeTruthy();

    const tradesBefore = await getTrades();
    const oldTrades = tradesBefore.filter(t => (t.symbol || t.code) === symbol && isFilled(t));
    expect(oldTrades.length, '应有旧费率下的成交记录').toBeGreaterThanOrEqual(1);

    const oldFeeValues = oldTrades.map(t => getTradeFee(t));
    expect(oldFeeValues.every(v => Number.isFinite(v)), '旧成交的手续费应为有效数字').toBe(true);

    // Change fees to higher values
    const setNew = await setFees(newFees);
    expect(setNew, 'Should update fee settings').toBeTruthy();

    // Create new trade with new fees
    const symbol2 = 'TEST_R17_NEW';
    await setMarketPrice(symbol2, 10);
    const buyNew = await createOrder({ symbol: symbol2, market: 'SH', side: 'BUY', price: 10, quantity: 100, validity: 'DAY' });
    expect(buyNew, 'Should create new trade with new fees').toBeTruthy();

    // Verify old trades unchanged
    const tradesAfter = await getTrades();
    const oldTradesAfter = tradesAfter.filter(t => (t.symbol || t.code) === symbol && isFilled(t));
    const oldFeeValuesAfter = oldTradesAfter.map(t => getTradeFee(t));

    expect(oldFeeValuesAfter.length, '旧成交记录数量不应改变').toBe(oldFeeValues.length);
    expect(oldFeeValuesAfter, '旧成交手续费不应被新费率重新计算').toEqual(oldFeeValues);

    // Verify new trades use new rates
    const newTrades = tradesAfter.filter(t => (t.symbol || t.code) === symbol2 && isFilled(t));
    expect(newTrades.length, '应有新费率下的成交记录').toBeGreaterThanOrEqual(1);

    const newFee = getTradeFee(newTrades[0]);
    expect(Number.isFinite(newFee), '新成交手续费应为有效数字').toBe(true);
    const expectedNewFee = 10 * 100 * newFees.commissionRate; // 3
    expect(Math.abs(newFee - expectedNewFee), `新成交手续费应约为${expectedNewFee}，实际: ${newFee}`).toBeLessThan(0.01);

    // New fee should be larger than old fee (3x rate)
    expect(newFee, '新费率下手续费应大于旧费率').toBeGreaterThan(oldFeeValues[0]);

    // Verify fee settings are persisted
    const feeGet = await getFees();
    if (feeGet) {
      const feeBody = feeGet.body?.feeSettings || feeGet.body?.data || feeGet.body;
      expect(Number(feeBody.commissionRate || feeBody.commission_rate), '佣金费率应为新值').toBe(newFees.commissionRate);
      expect(Number(feeBody.stampDutyRate || feeBody.stamp_duty_rate), '印花税费率应为新值').toBe(newFees.stampDutyRate);
    }

    await resetState();
  });

  it('should reject negative or unreasonably high fee rates', async () => {
    await resetState();

    // Negative fee rate
    const negResult = await setFees({ commissionRate: -0.001, stampDutyRate: 0.001 });
    expect(negResult, 'Setting negative fee should return a response').toBeTruthy();
    expect(
      [400, 422, 403].includes(negResult.res.status),
      `Negative commission rate should be rejected with 4xx, got status ${negResult.res.status}`
    ).toBe(true);

    // Unreasonably high fee rate
    const highResult = await setFees({ commissionRate: 0.5, stampDutyRate: 0.5 });
    expect(highResult, 'Setting high fee should return a response').toBeTruthy();
    expect(
      [400, 422, 403].includes(highResult.res.status),
      `Unreasonably high fee rate should be rejected with 4xx, got status ${highResult.res.status}`
    ).toBe(true);

    // Negative stamp duty
    const negStamp = await setFees({ commissionRate: 0.001, stampDutyRate: -0.01 });
    expect(negStamp, 'Setting negative stamp duty should return a response').toBeTruthy();
    expect(
      [400, 422, 403].includes(negStamp.res.status),
      `Negative stamp duty should be rejected with 4xx, got status ${negStamp.res.status}`
    ).toBe(true);

    await resetState();
  });

  it('should show cost-deducted returns in analysis page after trades with fees', async () => {
    await resetState();

    const symbol = 'TEST_R17_ANA_COST';
    const commissionRate = 0.001;
    const stampDutyRate = 0.001;

    await setFees({ commissionRate, stampDutyRate });
    await setMarketPrice(symbol, 10);

    // Buy 200 shares
    await createOrder({ symbol, market: 'SH', side: 'BUY', price: 10, quantity: 200, validity: 'DAY' });

    // Sell 100 shares at 12
    await setMarketPrice(symbol, 12);
    await createOrder({ symbol, market: 'SH', side: 'SELL', price: 12, quantity: 100, validity: 'DAY' });

    const analysis = await getAnalysis();
    expect(analysis, 'Analysis endpoint should be accessible').toBeTruthy();
    expect(analysis.body, 'Analysis should return structured data').toBeTruthy();

    const body = analysis.body?.overview || analysis.body?.data || analysis.body;

    // Check for realized PnL (should exist and account for costs)
    const realizedPnl = Number(body.realizedPnl ?? body.totalRealizedPnl ?? body.realized_pnl ?? body.netProfit ?? body.profit);
    expect(Number.isFinite(realizedPnl), `已实现盈亏应为有效数字，实际body: ${JSON.stringify(body)}`).toBe(true);

    // Without fees: (12-10)*100 = 200
    // With fees: buy cost = 10*200*0.001 = 2 (but only 100 shares' portion matters for realized)
    // sell cost = 12*100*(0.001+0.001) = 2.4
    // Realized PnL should be less than 200 due to trading costs
    expect(realizedPnl, '扣除成本后已实现盈亏应小于200（无费版）').toBeLessThan(200);
    expect(realizedPnl, '已实现盈亏应为正数').toBeGreaterThan(0);

    // Check that there is some cost/fee-related info present
    const totalFees = body.totalFees ?? body.totalCost ?? body.tradingCost ?? body.fees;
    const hasFeeInfo = totalFees !== undefined || realizedPnl < 200; // cost-deducted result is proof
    expect(hasFeeInfo, '分析页应体现成本已扣除的结果').toBe(true);

    await resetState();
  });
});

import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function request(path, options = {}) {
  const res = await fetch(`${BASE_URL}${path}`, {
    headers: { 'Content-Type': 'application/json', ...(options.headers || {}) },
    ...options,
  });
  const text = await res.text();
  let body;
  try {
    body = text ? JSON.parse(text) : null;
  } catch {
    body = text;
  }
  return { res, body };
}

