describe('round18_weighted_average_cost_basis', () => {
  it('should maintain weighted average cost across multiple buys and calculate realized PnL on partial sell', async () => {
    await resetState();

    const symbol = 'TEST_R18_WAC';
    const commissionRate = 0.001;
    const stampDutyRate = 0.001;

    // Set known fee rates
    await setFees({ commissionRate, stampDutyRate });

    // Buy 100 shares at 10
    await setMarketPrice(symbol, 10);
    const buy1 = await createOrder({ symbol, market: 'SH', side: 'BUY', price: 10, quantity: 100, validity: 'DAY' });
    expect(buy1, 'First buy order should succeed').toBeTruthy();

    // Buy 100 shares at 20
    await setMarketPrice(symbol, 20);
    const buy2 = await createOrder({ symbol, market: 'SH', side: 'BUY', price: 20, quantity: 100, validity: 'DAY' });
    expect(buy2, 'Second buy order should succeed').toBeTruthy();

    // Weighted average cost = (10*100 + 20*100) / 200 = 15 per share (excluding fees)
    // With fees: buy1 cost = 10*100*(1+0.001) = 1001, buy2 cost = 20*100*(1+0.001) = 2002
    // Avg cost per share ≈ (1001 + 2002) / 200 = 15.015

    // Check position shows weighted average cost
    let positions = await getPositions();
    let pos = positions.find(p => (p.symbol || p.code) === symbol);
    expect(pos, '应有持仓记录').toBeTruthy();

    const qty1 = getPositionField(pos, 'quantity', 'shares', 'amount');
    expect(qty1, '持仓数量应为200').toBe(200);

    const avgCost1 = getPositionField(pos, 'averageCost', 'avgCost', 'costBasis', 'avgPrice', 'cost_price');
    expect(Number.isFinite(avgCost1), `平均成本应为有效数字，实际pos: ${JSON.stringify(pos)}`).toBe(true);
    // Average cost should be around 15 (±small fee adjustment)
    expect(avgCost1).toBeGreaterThan(14);
    expect(avgCost1).toBeLessThan(16);

    // Now sell 100 shares at 25
    await setMarketPrice(symbol, 25);
    const sell1 = await createOrder({ symbol, market: 'SH', side: 'SELL', price: 25, quantity: 100, validity: 'DAY' });
    expect(sell1, 'Sell order should succeed').toBeTruthy();

    // Expected realized PnL ≈ (25 - 15.015) * 100 - sellCost
    // sellCost = 25*100*(0.001+0.001) = 5
    // Realized PnL ≈ 998.5 - 5 ≈ 993.5

    // Check remaining position
    positions = await getPositions();
    pos = positions.find(p => (p.symbol || p.code) === symbol);
    expect(pos, '卖出后应仍有持仓记录').toBeTruthy();

    const remainingQty = getPositionField(pos, 'quantity', 'shares', 'amount');
    expect(remainingQty, '剩余持仓数量应为100').toBe(100);

    // Average cost should remain ~15 (not change due to partial sell)
    const avgCost2 = getPositionField(pos, 'averageCost', 'avgCost', 'costBasis', 'avgPrice', 'cost_price');
    expect(Number.isFinite(avgCost2), '部分卖出后平均成本应仍为有效数字').toBe(true);
    expect(avgCost2).toBeGreaterThan(14);
    expect(avgCost2).toBeLessThan(16);
    // Average cost should not have changed significantly
    expect(Math.abs(avgCost2 - avgCost1), '部分卖出后平均成本不应显著变化').toBeLessThan(0.1);

    // Check realized PnL in trades or analysis
    const trades = await getTrades();
    const sellTrades = trades.filter(t =>
      (t.symbol || t.code) === symbol &&
      String(t.side || t.direction || '').toUpperCase().match(/SELL|卖/) &&
      String(t.status || '').toLowerCase().match(/filled|done|matched|成交|success/)
    );
    expect(sellTrades.length, '应有卖出成交记录').toBeGreaterThanOrEqual(1);

    const pnl = Number(sellTrades[0].realizedPnl ?? sellTrades[0].pnl ?? sellTrades[0].profit ?? sellTrades[0].realized_pnl);
    if (Number.isFinite(pnl)) {
      // PnL should be positive and approximately (25-15)*100 - costs ≈ 993
      expect(pnl, '已实现盈亏应为正数').toBeGreaterThan(0);
      expect(pnl, '已实现盈亏应接近预期值（约993）').toBeGreaterThan(900);
      expect(pnl, '已实现盈亏不应超过无费用上限').toBeLessThanOrEqual(1000);
    }

    await resetState();
  });

