async function queryWithTimeRange(basePaths, range) {
  for (const basePath of basePaths) {
    for (const paramName of ['range', 'timeRange', 'time_range', 'period', 'filter']) {
      const url = `${basePath}?${paramName}=${range}`;
      const result = await request(url).catch(() => null);
      if (result && result.res.status === 200) return result;
    }
    // Try with body POST
    const result = await request(basePath, { method: 'POST', body: JSON.stringify({ range, timeRange: range }) }).catch(() => null);
    if (result && result.res.status === 200) return result;
  }
  return null;
}

