  if (range) {
    return await queryWithTimeRange(paths, range);
  }
  for (const path of paths) {
    const result = await request(path).catch(() => null);
    if (result && result.res.status === 200) return result;
  }
  // Fallback: try analysis endpoint and extract breakdown
  const analysis = await getAnalysis(range);
  if (analysis) {
    const body = analysis.body;
    const breakdown = body?.bySymbol || body?.symbols || body?.breakdown || body?.symbolPerformance || body?.data?.bySymbol;
    if (breakdown) return { res: analysis.res, body: breakdown };
