function extractList(result) {
  if (!result || !result.body) return [];
  if (Array.isArray(result.body)) return result.body;
  return result.body.trades || result.body.orders || result.body.deals || result.body.entrusts || result.body.data?.trades || result.body.data?.orders || [];
}

