describe('round24_deterministic_market_stepper', () => {
  beforeEach(async () => {
    await resetState();
  });

  it('should serve the main application page', async () => {
    const res = await fetch(`${BASE_URL}/`);
    expect(res.status).toBe(200);
    const text = await res.text();
    expect(text.toLowerCase()).toContain('<html');
  });

  it('should have a deterministic price sequence with at least 5 steps for a known instrument', async () => {
    const symbols = await getAvailableSymbols();
    const testSymbol = typeof symbols[0] === 'string' ? symbols[0] : (symbols[0]?.symbol || symbols[0]?.code || '600000');

    // Get initial price
    const initialMarket = await getMarketInfo(testSymbol);
    const initialPrice = getCurrentPrice(initialMarket);

    // Advance market at least 5 times and collect prices
    const prices = [];
    if (initialPrice !== null) prices.push(Number(initialPrice));

    for (let i = 0; i < 6; i++) {
      const stepResult = await advanceMarket(testSymbol);
      // After advancing, get the new price
      const market = await getMarketInfo(testSymbol);
      const price = getCurrentPrice(market);
      if (price !== null) prices.push(Number(price));
      // Also check if stepResult itself returns the new price
      if (stepResult && stepResult.body) {
        const stepPrice = getCurrentPrice(stepResult.body);
        if (stepPrice !== null && prices[prices.length - 1] !== Number(stepPrice)) {
          prices.push(Number(stepPrice));
        }
      }
    }

    // We should have collected multiple price points
    expect(prices.length).toBeGreaterThanOrEqual(2);
    // Prices should be valid numbers
    prices.forEach(p => expect(Number.isFinite(p)).toBe(true));
  });

  it('should produce deterministic results - same sequence on repeated runs', async () => {
    const symbols = await getAvailableSymbols();
    const testSymbol = typeof symbols[0] === 'string' ? symbols[0] : (symbols[0]?.symbol || symbols[0]?.code || '600000');

    // Run 1: collect prices
    await resetState();
    const run1Prices = [];
    for (let i = 0; i < 5; i++) {
      await advanceMarket(testSymbol);
      const market = await getMarketInfo(testSymbol);
      const price = getCurrentPrice(market);
      if (price !== null) run1Prices.push(Number(price));
    }

    // Run 2: reset and collect prices again
    await resetState();
    const run2Prices = [];
    for (let i = 0; i < 5; i++) {
      await advanceMarket(testSymbol);
      const market = await getMarketInfo(testSymbol);
      const price = getCurrentPrice(market);
      if (price !== null) run2Prices.push(Number(price));
    }

    // Both runs should produce the same price sequence
    expect(run1Prices.length).toBe(run2Prices.length);
    for (let i = 0; i < run1Prices.length; i++) {
      expect(run2Prices[i]).toBe(run1Prices[i]);
    }
  });

  it('should maintain separate progress per instrument - switching does not reset other progress', async () => {
    const symbols = await getAvailableSymbols();
    if (symbols.length < 2) return; // need at least 2 symbols

    const symbolA = typeof symbols[0] === 'string' ? symbols[0] : (symbols[0]?.symbol || symbols[0]?.code || '600000');
    const symbolB = typeof symbols[1] === 'string' ? symbols[1] : (symbols[1]?.symbol || symbols[1]?.code || '600036');

    // Advance symbol A 3 times
    for (let i = 0; i < 3; i++) {
      await advanceMarket(symbolA);
    }
    const priceAAfter3 = getCurrentPrice(await getMarketInfo(symbolA));

    // Now switch to symbol B and advance it
    await advanceMarket(symbolB);
    await advanceMarket(symbolB);

    // Switch back to symbol A - its price should still be at step 3, not reset
    const priceAAfterSwitch = getCurrentPrice(await getMarketInfo(symbolA));

    if (priceAAfter3 !== null && priceAAfterSwitch !== null) {
      expect(Number(priceAAfterSwitch)).toBe(Number(priceAAfter3));
    }
  });

  it('should handle end of sequence - stays at last value or indicates ended', async () => {
    const symbols = await getAvailableSymbols();
    const testSymbol = typeof symbols[0] === 'string' ? symbols[0] : (symbols[0]?.symbol || symbols[0]?.code || '600000');

    // Advance many times to reach the end of the sequence
    let lastPrice = null;
    let previousPrice = null;
    let stoppedChanging = false;
    let endedMessage = false;

    for (let i = 0; i < 20; i++) {
      const stepResult = await advanceMarket(testSymbol);
      const market = await getMarketInfo(testSymbol);
      const price = getCurrentPrice(market);

      if (stepResult && stepResult.body) {
        const bodyStr = JSON.stringify(stepResult.body).toLowerCase();
        if (/结束|ended|end|last|完成|no more/.test(bodyStr)) {
          endedMessage = true;
        }
      }

      if (price !== null) {
        if (previousPrice !== null && Number(price) === Number(previousPrice) && Number(price) === Number(lastPrice)) {
          stoppedChanging = true;
        }
        previousPrice = lastPrice;
        lastPrice = price;
      }
    }

    // At end of sequence, should either stay at last value or show ended message
    expect(stoppedChanging || endedMessage || lastPrice !== null).toBe(true);
  });

  it('should update position floating P&L when market advances', async () => {
    const symbols = await getAvailableSymbols();
    const testSymbol = typeof symbols[0] === 'string' ? symbols[0] : (symbols[0]?.symbol || symbols[0]?.code || '600000');

    // Get initial price for this symbol
    const initialMarket = await getMarketInfo(testSymbol);
    const initialPrice = getCurrentPrice(initialMarket);
    if (!initialPrice) return; // skip if no initial price available

    // Create a buy order at current price to establish a position
    const orderResult = await createOrder({
      symbol: testSymbol,
      market: 'SH',
      side: 'BUY',
      type: 'MARKET',
      price: Number(initialPrice),
      quantity: 100
    });

    if (!orderResult) return; // skip if ordering not supported via API

    // Get positions before advancing
    const positionsBefore = await getPositions();
    const posBefore = positionsBefore.find(p => getSymbol(p) === testSymbol);

    // Advance market several steps
    for (let i = 0; i < 3; i++) {
      await advanceMarket(testSymbol);
    }

    const newMarket = await getMarketInfo(testSymbol);
    const newPrice = getCurrentPrice(newMarket);

    // Get positions after advancing
    const positionsAfter = await getPositions();
    const posAfter = positionsAfter.find(p => getSymbol(p) === testSymbol);

    // If price changed and we have a position, P&L should reflect the new price
    if (posAfter && newPrice && initialPrice && Number(newPrice) !== Number(initialPrice)) {
      const pnl = posAfter.floatingPnl || posAfter.unrealizedPnl || posAfter.pnl || posAfter.profit || posAfter.floatingProfit;
      // P&L should exist and be non-null
      expect(pnl !== undefined && pnl !== null).toBe(true);
    }
  });
});

