describe('round25_step_triggered_order_matching', () => {
  beforeEach(async () => {
    await resetState();
  });

  it('should fill a pending buy order when market step brings price down to limit', async () => {
    const testSymbol = '600000';

    // Get initial market price
    const initialMarket = await getMarketInfo(testSymbol);
    const initialPrice = getCurrentPrice(initialMarket);
    if (!initialPrice) return;

    // Create a buy limit order at a price below current market
    // We set the limit well below to ensure it starts as pending
    const limitPrice = Math.max(1, Number(initialPrice) * 0.5);
    const limitPriceRounded = Math.round(limitPrice * 100) / 100;

    const orderResult = await createOrder({
      symbol: testSymbol,
      market: 'SH',
      side: 'BUY',
      type: 'LIMIT',
      price: limitPriceRounded,
      quantity: 100
    });
    if (!orderResult) return;

    const orderId = orderResult.body?.id || orderResult.body?.orderId;

    // Initially the order should be pending
    let orders = await getOrders();
    let order = orders.find(o => String(o.id || o.orderId) === String(orderId));
    if (order) {
      expect(isPending(getStatus(order))).toBe(true);
    }

    // Advance the market multiple times - the deterministic sequence may bring the price to meet our limit
    for (let i = 0; i < 10; i++) {
      await advanceMarket(testSymbol);
    }

    // Check if the order has been filled
    orders = await getOrders();
    order = orders.find(o => String(o.id || o.orderId) === String(orderId));

    // The order may or may not have filled depending on the price sequence
    // At minimum, it should still be a valid order
    if (order) {
      const status = getStatus(order);
      expect(isPending(status) || isFilled(status)).toBe(true);
    }
  });

  it('should not fill the same order more than once across multiple market steps', async () => {
    const testSymbol = '600000';

    const initialMarket = await getMarketInfo(testSymbol);
    const initialPrice = getCurrentPrice(initialMarket);
    if (!initialPrice) return;

    // Create a buy order at market price (should fill immediately or on first matching step)
    const orderResult = await createOrder({
      symbol: testSymbol,
      market: 'SH',
      side: 'BUY',
      type: 'MARKET',
      price: Number(initialPrice),
      quantity: 100
    });
    if (!orderResult) return;

    // Record account state after the order
    await new Promise(r => setTimeout(r, 100));
    const accountAfterOrder = await getAccount();
    const balanceAfterOrder = getBalance(accountAfterOrder);
    const tradesAfterOrder = await getTrades();
    const tradeCountAfterOrder = tradesAfterOrder.filter(t => getSymbol(t) === testSymbol).length;

    // Advance market multiple times
    for (let i = 0; i < 5; i++) {
      await advanceMarket(testSymbol);
    }

    // The same order should NOT generate additional trades or fund changes
    const tradesAfterSteps = await getTrades();
    const tradeCountAfterSteps = tradesAfterSteps.filter(t => getSymbol(t) === testSymbol).length;

    // Trade count for this symbol should not have increased from the same order
    // (It could increase if there are OTHER new orders, but we only placed one)
    expect(tradeCountAfterSteps).toBe(tradeCountAfterOrder);
  });

