function extractCurvePoints(data) {
  if (!data) return [];
  if (Array.isArray(data)) return data;
  if (data.body) data = data.body;
  if (Array.isArray(data)) return data;
  if (data.curve && Array.isArray(data.curve)) return data.curve;
  if (data.equityCurve && Array.isArray(data.equityCurve)) return data.equityCurve;
  if (data.points && Array.isArray(data.points)) return data.points;
  if (data.chartData && Array.isArray(data.chartData)) return data.chartData;
  if (data.data) {
    if (Array.isArray(data.data)) return data.data;
    if (data.data.curve && Array.isArray(data.data.curve)) return data.data.curve;
    if (data.data.points && Array.isArray(data.data.points)) return data.data.points;
  }
  return [];
}

function isEmptyState(data) {
  if (!data) return true;
  const body = data.body || data;
  if (Array.isArray(body) && body.length === 0) return true;
  const points = extractCurvePoints(body);
  if (points.length === 0) return true;
  const str = JSON.stringify(body).toLowerCase();
  return /暂无|no.*data|empty|空|insufficient|不足|no.*record/.test(str);
}

