import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function request(path, options = {}) {
  const res = await fetch(`${BASE_URL}${path}`, {
    headers: { 'Content-Type': 'application/json', ...(options.headers || {}) },
    ...options,
  });
  const text = await res.text();
  let body;
  try {
    body = text ? JSON.parse(text) : null;
  } catch {
    body = text;
  }
  return { res, body };
}

async function createTrip() {
  const name = `trip-marker-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
  const payload = { name, title: name };
  const { res, body } = await request('/trips', { method: 'POST', body: JSON.stringify(payload) });
  expect([200, 201]).toContain(res.status);
  const tripId = body?.id ?? body?.data?.id ?? body?.tripId ?? body?.data?.tripId;
  expect(tripId, `expected trip id in response, got ${JSON.stringify(body)}`).toBeTruthy();
  return { tripId, body };
}

async function cleanup(path) {
  try {
    await fetch(`${BASE_URL}${path}`, { method: 'DELETE' });
  } catch {}
}

describe('validate_marker_fields_and_default_category', () => {
  it('should save valid marker fields, reject invalid coordinates, and default category to 其他 when not provided', async () => {
    const { tripId } = await createTrip();
    const createdMarkerIds = [];

    try {
      // --- Valid marker creation without category (should default to 其他) ---
      const validPayload = {
        name: '人民广场',
        note: '测试备注-可录入',
        latitude: 31.2304,
        longitude: 121.4737,
      };

      const validCreate = await request(`/trips/${tripId}/markers`, {
        method: 'POST',
        body: JSON.stringify(validPayload),
      });

      expect([200, 201]).toContain(validCreate.res.status);
      const marker = validCreate.body?.id ? validCreate.body : (validCreate.body?.data || {});
      const markerId = marker?.id ?? validCreate.body?.markerId ?? validCreate.body?.data?.markerId;
      createdMarkerIds.push(markerId);
      expect(markerId, `expected marker id in response, got ${JSON.stringify(validCreate.body)}`).toBeTruthy();
      expect(marker.name).toBe(validPayload.name);
      expect(marker.note).toBe(validPayload.note);
      expect(Number(marker.latitude)).toBe(validPayload.latitude);
      expect(Number(marker.longitude)).toBe(validPayload.longitude);
      // Default category should be '其他'
      expect(marker.category ?? marker.categoryName ?? marker.type).toBe('其他');

      // --- Verify via list endpoint ---
      const listRes = await request(`/trips/${tripId}/markers`, { method: 'GET' });
      expect(listRes.res.status).toBe(200);
      const markers = Array.isArray(listRes.body) ? listRes.body : (listRes.body?.data || listRes.body?.items || []);
      const found = markers.find((m) => String(m.id) === String(markerId));
      expect(found, `expected created marker ${markerId} in list response ${JSON.stringify(listRes.body)}`).toBeTruthy();
      expect(found.name).toBe(validPayload.name);
      expect(found.note).toBe(validPayload.note);
      expect(Number(found.latitude)).toBe(validPayload.latitude);
      expect(Number(found.longitude)).toBe(validPayload.longitude);
      expect(found.category ?? found.categoryName ?? found.type).toBe('其他');

      // --- Simulate "old marker" without category field ---
      // Creating a marker explicitly without any category-related field
      // to verify backward compatibility: old markers default to '其他'
      const oldStylePayload = {
        name: '旧标注测试',
        note: '模拟旧数据无分类',
        latitude: 30.5728,
        longitude: 104.0668,
        // No category, categoryName, or type field at all
      };
      const oldStyleCreate = await request(`/trips/${tripId}/markers`, {
        method: 'POST',
        body: JSON.stringify(oldStylePayload),
      });
      expect([200, 201]).toContain(oldStyleCreate.res.status);
      const oldMarker = oldStyleCreate.body?.id ? oldStyleCreate.body : (oldStyleCreate.body?.data || {});
      const oldMarkerId = oldMarker?.id ?? oldStyleCreate.body?.markerId ?? oldStyleCreate.body?.data?.markerId;
      createdMarkerIds.push(oldMarkerId);
      expect(oldMarkerId).toBeTruthy();
      // Old marker should also default to '其他'
      expect(oldMarker.category ?? oldMarker.categoryName ?? oldMarker.type).toBe('其他');

      // Verify old-style marker appears correctly in list with category '其他'
      const listRes2 = await request(`/trips/${tripId}/markers`, { method: 'GET' });
      expect(listRes2.res.status).toBe(200);
      const markers2 = Array.isArray(listRes2.body) ? listRes2.body : (listRes2.body?.data || listRes2.body?.items || []);
      const foundOld = markers2.find((m) => String(m.id) === String(oldMarkerId));
      expect(foundOld).toBeTruthy();
      expect(foundOld.category ?? foundOld.categoryName ?? foundOld.type).toBe('其他');

      // --- Invalid latitude > 90 ---
      const invalidLatHigh = await request(`/trips/${tripId}/markers`, {
        method: 'POST',
        body: JSON.stringify({
          name: '非法纬度-高',
          note: 'lat > 90',
          latitude: 90.1,
          longitude: 120,
        }),
      });
      expect([400, 422]).toContain(invalidLatHigh.res.status);
      expect(JSON.stringify(invalidLatHigh.body)).toMatch(/纬度|latitude|-90|90|invalid|range/i);

      // --- Invalid latitude < -90 ---
      const invalidLatLow = await request(`/trips/${tripId}/markers`, {
        method: 'POST',
        body: JSON.stringify({
          name: '非法纬度-低',
          note: 'lat < -90',
          latitude: -90.1,
          longitude: 120,
        }),
      });
      expect([400, 422]).toContain(invalidLatLow.res.status);
      expect(JSON.stringify(invalidLatLow.body)).toMatch(/纬度|latitude|-90|90|invalid|range/i);

      // --- Invalid longitude < -180 ---
      const invalidLngLow = await request(`/trips/${tripId}/markers`, {
        method: 'POST',
        body: JSON.stringify({
          name: '非法经度-低',
          note: 'lng < -180',
          latitude: 30,
          longitude: -180.1,
        }),
      });
      expect([400, 422]).toContain(invalidLngLow.res.status);
      expect(JSON.stringify(invalidLngLow.body)).toMatch(/经度|longitude|-180|180|invalid|range/i);

      // --- Invalid longitude > 180 ---
      const invalidLngHigh = await request(`/trips/${tripId}/markers`, {
        method: 'POST',
        body: JSON.stringify({
          name: '非法经度-高',
          note: 'lng > 180',
          latitude: 30,
          longitude: 180.1,
        }),
      });
      expect([400, 422]).toContain(invalidLngHigh.res.status);
      expect(JSON.stringify(invalidLngHigh.body)).toMatch(/经度|longitude|-180|180|invalid|range/i);
    } finally {
      for (const mid of createdMarkerIds) {
        if (mid) await cleanup(`/trips/${tripId}/markers/${mid}`);
      }
      await cleanup(`/trips/${tripId}`);
    }
  });
});

