function getDuration(route) {
  return route.estimatedDurationMinutes ?? route.durationMinutes ?? route.estimatedVisitMinutes ?? route.duration;
}

describe('generate_route_with_valid_stop_count', () => {
  it('should reject routes with fewer than 2 stops and create route with 2-10 stops including order, count and valid duration', async () => {
    const tripId = await createTrip();
    const markerIds = [];
    const routeIds = [];

    try {
      // Create 3 markers for basic tests
      const m1 = await createMarker(tripId, 1);
      const m2 = await createMarker(tripId, 2);
      const m3 = await createMarker(tripId, 3);
      markerIds.push(m1.markerId, m2.markerId, m3.markerId);

      // --- Reject fewer than 2 stops ---
      const tooFew = await request(`/trips/${tripId}/routes`, {
        method: 'POST',
        body: JSON.stringify({
          name: 'invalid-route',
          markerIds: [m1.markerId],
        }),
      });
      expect([400, 422]).toContain(tooFew.res.status);
      expect(JSON.stringify(tooFew.body)).toMatch(/2|至少|stop|marker|点/i);

      // --- Create valid route WITH explicit duration ---
      const createRoute = await request(`/trips/${tripId}/routes`, {
        method: 'POST',
        body: JSON.stringify({
          name: 'valid-route-with-duration',
          markerIds: [m1.markerId, m2.markerId, m3.markerId],
          estimatedDurationMinutes: 120,
        }),
      });
      expect([200, 201]).toContain(createRoute.res.status);
      const route = createRoute.body?.id ? createRoute.body : (createRoute.body?.data || {});
      const routeId = route?.id ?? createRoute.body?.routeId ?? createRoute.body?.data?.routeId;
      routeIds.push(routeId);
      expect(routeId, `expected route id in response, got ${JSON.stringify(createRoute.body)}`).toBeTruthy();

      const stops = route.stops ?? route.stopovers ?? route.markers ?? [];
      const stopCount = route.stopCount ?? route.totalStops ?? stops.length;
      expect(stopCount).toBe(3);
      expect(stops.length).toBe(3);
      const actualIds = stops.map((s) => String(s.markerId ?? s.id));
      expect(actualIds).toEqual([String(m1.markerId), String(m2.markerId), String(m3.markerId)]);
      // Duration should be the value we set
      expect(Number(getDuration(route))).toBe(120);

      // Verify via GET
      const getRoute = await request(`/trips/${tripId}/routes/${routeId}`, { method: 'GET' });
      expect(getRoute.res.status).toBe(200);
      const fetched = getRoute.body?.id ? getRoute.body : (getRoute.body?.data || {});
      const fetchedStops = fetched.stops ?? fetched.stopovers ?? fetched.markers ?? [];
      expect(fetchedStops.length).toBe(3);
      expect(fetched.stopCount ?? fetched.totalStops ?? fetchedStops.length).toBe(3);
      expect(Number(getDuration(fetched))).toBe(120);

      // --- Create route WITHOUT duration (old route scenario) -> should show '未设置' or null ---
      const createRouteNoDuration = await request(`/trips/${tripId}/routes`, {
        method: 'POST',
        body: JSON.stringify({
          name: 'route-no-duration',
          markerIds: [m1.markerId, m2.markerId],
          // No duration field
        }),
      });
      expect([200, 201]).toContain(createRouteNoDuration.res.status);
      const routeNoDur = createRouteNoDuration.body?.id ? createRouteNoDuration.body : (createRouteNoDuration.body?.data || {});
      const routeNoDurId = routeNoDur?.id ?? createRouteNoDuration.body?.routeId ?? createRouteNoDuration.body?.data?.routeId;
      routeIds.push(routeNoDurId);
      expect(routeNoDurId).toBeTruthy();

      // Verify old route without duration: should be null/undefined or display text '未设置'
      const getNoDur = await request(`/trips/${tripId}/routes/${routeNoDurId}`, { method: 'GET' });
      expect(getNoDur.res.status).toBe(200);
      const fetchedNoDur = getNoDur.body?.id ? getNoDur.body : (getNoDur.body?.data || {});
      const durValue = getDuration(fetchedNoDur);
      // Duration should be null, undefined, or the string '未设置'
      const isUnset = durValue === null || durValue === undefined || durValue === '未设置' || durValue === '';
      expect(isUnset, `expected duration to be unset for old route, got ${JSON.stringify(durValue)}`).toBe(true);

      // --- Reject duration = 0 (below min of 1) ---
      const durTooLow = await request(`/trips/${tripId}/routes`, {
        method: 'POST',
        body: JSON.stringify({
          name: 'route-dur-0',
          markerIds: [m1.markerId, m2.markerId],
          estimatedDurationMinutes: 0,
        }),
      });
      expect([400, 422]).toContain(durTooLow.res.status);
      expect(JSON.stringify(durTooLow.body)).toMatch(/1|1440|时长|duration|分钟|minute|range|invalid/i);

      // --- Reject duration = 1441 (above max of 1440) ---
      const durTooHigh = await request(`/trips/${tripId}/routes`, {
        method: 'POST',
        body: JSON.stringify({
          name: 'route-dur-1441',
          markerIds: [m1.markerId, m2.markerId],
          estimatedDurationMinutes: 1441,
        }),
      });
      expect([400, 422]).toContain(durTooHigh.res.status);
      expect(JSON.stringify(durTooHigh.body)).toMatch(/1|1440|时长|duration|分钟|minute|range|invalid/i);

      // --- Reject more than 10 stops ---
      // Create 8 more markers to have 11 total
      for (let i = 4; i <= 11; i++) {
        const m = await createMarker(tripId, i);
        markerIds.push(m.markerId);
      }
      const tooManyStops = await request(`/trips/${tripId}/routes`, {
        method: 'POST',
        body: JSON.stringify({
          name: 'route-11-stops',
          markerIds: markerIds.slice(0, 11),
          estimatedDurationMinutes: 60,
        }),
      });
      expect([400, 422]).toContain(tooManyStops.res.status);
      expect(JSON.stringify(tooManyStops.body)).toMatch(/10|最多|stop|marker|点|exceed|limit/i);
    } finally {
      for (const rid of routeIds) {
        if (rid) await cleanup(`/trips/${tripId}/routes/${rid}`);
      }
      for (const mid of markerIds) {
        if (mid) await cleanup(`/trips/${tripId}/markers/${mid}`);
      }
      await cleanup(`/trips/${tripId}`);
    }
  });
});

