      expect(favorite.name).toBe(directPayload.name);
      expect(favorite.city).toBe(directPayload.city);
      expect((favorite.tags || []).length).toBe(3);

      // --- Prefill from marker ---
      const prefillCreate = await request(`/trips/${tripId}/markers/${markerId}/favorite`, {
        method: 'POST',
        body: JSON.stringify({ tags: ['散步'] }),
      });
      expect([200, 201]).toContain(prefillCreate.res.status);
