      favoriteIds.push(prefavId);
      expect(prefavId).toBeTruthy();
      expect(prefav.name).toBe('外滩');
      // City should be prefilled from marker or trip destination
      expect(prefav.city).toBeTruthy();

      // --- Duplicate: try to favorite same marker again, expect rejection/warning ---
      const dupPrefill = await request(`/trips/${tripId}/markers/${markerId}/favorite`, {
        method: 'POST',
        body: JSON.stringify({ tags: ['重复测试'] }),
      });
      expect([400, 409, 422]).toContain(dupPrefill.res.status);
      expect(JSON.stringify(dupPrefill.body)).toMatch(/重复|已存在|duplicate|already|exist/i);

      // --- Too many tags (4 > 3 max) ---
      const tooManyTags = await request('/favorites', {
