      // --- Tag exactly 12 characters after trimming (boundary: should succeed) ---
      const exactTag = await request('/favorites', {
        method: 'POST',
        body: JSON.stringify({
          name: '标签刚好12',
          city: '上海',
          tags: ['  123456789012  '],
        }),
      });
      expect([200, 201]).toContain(exactTag.res.status);
      const exactFav = exactTag.body?.id ? exactTag.body : (exactTag.body?.data || {});
      const exactFavId = exactFav?.id ?? exactTag.body?.favoriteId ?? exactTag.body?.data?.favoriteId;
      favoriteIds.push(exactFavId);
      expect(exactFavId).toBeTruthy();
      // Verify the tag was saved and trimmed
      const savedTags = exactFav.tags || [];
      expect(savedTags.length).toBe(1);
      expect(savedTags[0].trim().length).toBeLessThanOrEqual(12);
    } finally {
      for (const fid of favoriteIds) {
        if (fid) await cleanup(`/favorites/${fid}`);
      }
      await cleanup(`/trips/${tripId}/markers/${markerId}`);
      await cleanup(`/trips/${tripId}`);
    }
  });
});

