describe('validate_journal_title_and_content_limits', () => {
  it('should allow journal with title length 1-60 and non-empty content with upper limit, and reject invalid inputs', async () => {
    const tripId = await createTrip();
    const journalIds = [];

    try {
      // --- Valid creation with normal title and content, including date ---
      const validPayload = {
        title: '今日日记',
        date: new Date().toISOString().slice(0, 10),
        content: '这是一次很棒的旅行记录。',
      };
      const create = await request(`/trips/${tripId}/journals`, {
        method: 'POST',
        body: JSON.stringify(validPayload),
      });
      expect([200, 201]).toContain(create.res.status);
      const journal = create.body?.id ? create.body : (create.body?.data || {});
      const journalId = journal?.id ?? create.body?.journalId ?? create.body?.data?.journalId;
      journalIds.push(journalId);
      expect(journalId).toBeTruthy();
      expect(journal.title).toBe(validPayload.title);
      expect(journal.content).toBe(validPayload.content);

      // --- Boundary: title exactly 1 character (minimum) ---
      const title1 = await request(`/trips/${tripId}/journals`, {
        method: 'POST',
        body: JSON.stringify({ title: 'A', date: '2024-01-01', content: '正文内容' }),
      });
      expect([200, 201]).toContain(title1.res.status);
      const j1 = title1.body?.id ? title1.body : (title1.body?.data || {});
      const j1Id = j1?.id ?? title1.body?.journalId ?? title1.body?.data?.journalId;
      journalIds.push(j1Id);
      expect(j1Id).toBeTruthy();
      expect(j1.title).toBe('A');

      // --- Boundary: title exactly 60 characters (maximum) ---
      const title60Str = 'B'.repeat(60);
      const title60 = await request(`/trips/${tripId}/journals`, {
        method: 'POST',
        body: JSON.stringify({ title: title60Str, date: '2024-01-02', content: '正文内容' }),
      });
      expect([200, 201]).toContain(title60.res.status);
      const j60 = title60.body?.id ? title60.body : (title60.body?.data || {});
      const j60Id = j60?.id ?? title60.body?.journalId ?? title60.body?.data?.journalId;
      journalIds.push(j60Id);
      expect(j60Id).toBeTruthy();
      expect(j60.title).toBe(title60Str);
      expect(j60.title.length).toBe(60);

      // --- Reject empty title ---
      const emptyTitle = await request(`/trips/${tripId}/journals`, {
        method: 'POST',
        body: JSON.stringify({ title: '', date: '2024-01-03', content: '正文' }),
      });
      expect([400, 422]).toContain(emptyTitle.res.status);
      expect(JSON.stringify(emptyTitle.body)).toMatch(/标题|title|1|不能为空|empty/i);

      // --- Reject title with 61 characters ---
      const tooLongTitle = await request(`/trips/${tripId}/journals`, {
        method: 'POST',
        body: JSON.stringify({ title: 'a'.repeat(61), date: '2024-01-04', content: '正文' }),
      });
      expect([400, 422]).toContain(tooLongTitle.res.status);
      expect(JSON.stringify(tooLongTitle.body)).toMatch(/60|标题|title|长度|length/i);

      // --- Reject empty content ---
      const emptyContent = await request(`/trips/${tripId}/journals`, {
        method: 'POST',
        body: JSON.stringify({ title: '标题', date: '2024-01-05', content: '' }),
      });
      expect([400, 422]).toContain(emptyContent.res.status);
      expect(JSON.stringify(emptyContent.body)).toMatch(/正文|content|不能为空|empty/i);

      // --- Reject excessively long content (upper limit) ---
      // Use a very large content string to test the upper bound
      const oversizedContent = 'X'.repeat(100000);
      const tooLongContent = await request(`/trips/${tripId}/journals`, {
        method: 'POST',
        body: JSON.stringify({ title: '超长正文', date: '2024-01-06', content: oversizedContent }),
      });
      expect([400, 413, 422]).toContain(tooLongContent.res.status);
      expect(JSON.stringify(tooLongContent.body)).toMatch(/正文|content|长度|上限|limit|too long|length|exceed/i);
    } finally {
      for (const jid of journalIds) {
        if (jid) await cleanup(`/trips/${tripId}/journals/${jid}`);
      }
      await cleanup(`/trips/${tripId}`);
    }
  });
});

