describe('maintain_journal_route_association_state', () => {
  it('should keep journal when linked to markers and one route, sync route summary after route changes, preserve content, and mark deleted route as invalid', async () => {
    const tripId = await createTrip();
    const markerIds = [];
    let routeId;
    let journalId;

    try {
      const m1 = await createMarker(tripId, 1);
      const m2 = await createMarker(tripId, 2);
      const m3 = await createMarker(tripId, 3);
      markerIds.push(m1, m2, m3);

      const routeCreate = await request(`/trips/${tripId}/routes`, {
        method: 'POST',
        body: JSON.stringify({ name: 'journal-linked-route', markerIds: [m1, m2] }),
      });
      expect([200, 201]).toContain(routeCreate.res.status);
      const route = routeCreate.body?.id ? routeCreate.body : (routeCreate.body?.data || {});
      routeId = route?.id ?? routeCreate.body?.routeId ?? routeCreate.body?.data?.routeId;
      expect(routeId).toBeTruthy();

      const content = '正文必须保持不变';
      const journalCreate = await request(`/trips/${tripId}/journals`, {
        method: 'POST',
        body: JSON.stringify({
          title: '关联路线日记',
          content,
          markerIds: [m1, m2, m3],
          routeId,
          date: '2025-01-01',
        }),
      });
      expect([200, 201]).toContain(journalCreate.res.status);
      const journal = journalCreate.body?.id ? journalCreate.body : (journalCreate.body?.data || {});
      journalId = journal?.id ?? journalCreate.body?.journalId ?? journalCreate.body?.data?.journalId;
      expect(journalId).toBeTruthy();
      expect((journal.markerIds ?? journal.markers?.map((m) => m.id) ?? []).length).toBeLessThanOrEqual(3);
      expect(journal.content).toBe(content);
      expect(JSON.stringify(journal.routeSummary ?? journal.route)).toMatch(/p-1|p-2/);

      const routeUpdate = await request(`/trips/${tripId}/routes/${routeId}`, {
        method: 'PUT',
        body: JSON.stringify({ name: 'journal-linked-route', markerIds: [m1, m3] }),
      });
      expect([200, 204]).toContain(routeUpdate.res.status);

      const journalAfterRouteUpdate = await request(`/trips/${tripId}/journals/${journalId}`, { method: 'GET' });
      expect(journalAfterRouteUpdate.res.status).toBe(200);
      const fetched = journalAfterRouteUpdate.body?.id ? journalAfterRouteUpdate.body : (journalAfterRouteUpdate.body?.data || {});
      expect(fetched.content).toBe(content);
      expect(JSON.stringify(fetched.routeSummary ?? fetched.route)).toMatch(/p-1|p-3/);
      expect(JSON.stringify(fetched.routeSummary ?? fetched.route)).not.toMatch(/p-2/);

      const routeDelete = await request(`/trips/${tripId}/routes/${routeId}`, { method: 'DELETE' });
      expect([200, 204]).toContain(routeDelete.res.status);
      routeId = undefined;

      const journalAfterRouteDelete = await request(`/trips/${tripId}/journals/${journalId}`, { method: 'GET' });
      expect(journalAfterRouteDelete.res.status).toBe(200);
      const afterDelete = journalAfterRouteDelete.body?.id ? journalAfterRouteDelete.body : (journalAfterRouteDelete.body?.data || {});
      expect(afterDelete.content).toBe(content);
      expect(JSON.stringify(afterDelete.routeStatus ?? afterDelete.route)).toMatch(/失效|invalid|deleted/i);
    } finally {
      if (routeId) await cleanup(`/trips/${tripId}/routes/${routeId}`);
      if (journalId) await cleanup(`/trips/${tripId}/journals/${journalId}`);
      for (const markerId of markerIds) {
        if (markerId) await cleanup(`/trips/${tripId}/markers/${markerId}`);
      }
      await cleanup(`/trips/${tripId}`);
    }
  });
});

