describe('preserve_journal_when_linked_marker_deleted', () => {
  it('should preserve journal content and mark deleted marker association as removed when a linked marker is deleted', async () => {
    const tripId = await createTrip();
    const markerId = await createMarker(tripId);
    let journalId;

    try {
      const content = '删除关联标注后，日记正文仍需完整保留';
      const title = '标注删除保留日记';
      const createJournal = await request(`/trips/${tripId}/journals`, {
        method: 'POST',
        body: JSON.stringify({
          title,
          date: new Date().toISOString().slice(0, 10),
          content,
          markerIds: [markerId],
        }),
      });
      expect([200, 201]).toContain(createJournal.res.status);
      const journal = createJournal.body?.id ? createJournal.body : (createJournal.body?.data || {});
      journalId = journal?.id ?? createJournal.body?.journalId ?? createJournal.body?.data?.journalId;
      expect(journalId).toBeTruthy();
      expect(journal.content).toBe(content);

      // Verify marker association exists before deletion
      const getBeforeDelete = await request(`/trips/${tripId}/journals/${journalId}`, { method: 'GET' });
      expect(getBeforeDelete.res.status).toBe(200);
      const beforeDelete = getBeforeDelete.body?.id ? getBeforeDelete.body : (getBeforeDelete.body?.data || {});
      const markersBefore = beforeDelete.markers ?? beforeDelete.markerIds ?? beforeDelete.linkedMarkers ?? beforeDelete.associatedMarkers ?? beforeDelete.locations ?? [];
      expect(markersBefore.length).toBeGreaterThanOrEqual(1);

      // Delete the linked marker
      const delMarker = await request(`/trips/${tripId}/markers/${markerId}`, { method: 'DELETE' });
      expect([200, 204]).toContain(delMarker.res.status);

      // Fetch journal after marker deletion
      const getJournal = await request(`/trips/${tripId}/journals/${journalId}`, { method: 'GET' });
      expect(getJournal.res.status).toBe(200);
      const fetched = getJournal.body?.id ? getJournal.body : (getJournal.body?.data || {});

      // Journal content must be fully preserved
      expect(fetched.title).toBe(title);
      expect(fetched.content).toBe(content);
      expect(fetched.content.length).toBe(content.length);

      // The deleted marker association should be marked as removed/invalid
      const markersAfter = fetched.markers ?? fetched.linkedMarkers ?? fetched.associatedMarkers ?? fetched.locations ?? [];
      const responseStr = JSON.stringify(fetched);

      // Check that the invalidated marker is indicated as removed
      // Could be via a status field on the marker association, a label, or presence of '已移除地点' text
      const hasRemovedIndicator =
        responseStr.includes('已移除地点') ||
        responseStr.includes('已移除') ||
        responseStr.includes('已删除') ||
        responseStr.includes('removed') ||
        responseStr.includes('deleted') ||
        (Array.isArray(markersAfter) && markersAfter.some((m) => {
          const status = m.status ?? m.state ?? '';
          const name = m.name ?? m.label ?? '';
          return (
            status === 'removed' ||
            status === 'deleted' ||
            status === 'invalid' ||
            name.includes('已移除') ||
            name.includes('已删除') ||
            m.removed === true ||
            m.deleted === true ||
            m.invalid === true
          );
        }));

      expect(
        hasRemovedIndicator,
        `Expected deleted marker association to be marked as '已移除地点' or similar removed indicator in journal response: ${responseStr}`
      ).toBe(true);
    } finally {
      if (journalId) await cleanup(`/trips/${tripId}/journals/${journalId}`);
      await cleanup(`/trips/${tripId}/markers/${markerId}`);
      await cleanup(`/trips/${tripId}`);
    }
  });
});

