import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function createTrip(payload) {
  const res = await fetch(`${BASE_URL}/api/trips`, {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify(payload)
  });
  expect([200, 201]).toContain(res.status);
  const body = await res.json();
  const id = body.id || body.tripId || body.data?.id;
  expect(id, `expected trip id in create response, got ${JSON.stringify(body)}`).toBeTruthy();
  return { id, body };
}

function extractItems(body) {
  const data = body.data || body.items || body.trips || body;
  return Array.isArray(data) ? data : data.items || data.results || [];
}

function extractTotal(body, items) {
  return body.total ?? body.totalCount ?? body.data?.total ?? body.data?.totalCount ?? body.meta?.total ?? items.length;
}

describe('filter_and_search_trips_with_combined_conditions', () => {
  it('should combine keyword search and status filter, trim search terms, support reset, show no-match feedback, and cover all status types', async () => {
    const now = Date.now();
    const createdIds = [];

    // "Kyoto Blossom" - future dates => not_started / upcoming
    // "Osaka Food" - past dates => completed / ended
    // "Kyoto Active" - spans current date => ongoing / in_progress
    const trips = [
      {
        name: `Kyoto Blossom ${now}`,
        destination: 'Kyoto',
        startDate: '2099-04-01',
        endDate: '2099-04-05'
      },
      {
        name: `Osaka Food ${now}`,
        destination: 'Osaka',
        startDate: '2000-04-01',
        endDate: '2000-04-05'
      },
      {
        name: `Kyoto Active ${now}`,
        destination: 'Kyoto',
        startDate: '2020-01-01',
        endDate: '2099-12-31'
      }
    ];

    try {
      for (const t of trips) {
        const created = await createTrip(t);
        createdIds.push(created.id);
      }

      // Helper: try multiple possible status enum values
      async function searchTrips(search, status) {
        const params = new URLSearchParams();
        if (search !== undefined) params.set('search', search);
        if (status !== undefined) params.set('status', status);
        const res = await fetch(`${BASE_URL}/api/trips?${params.toString()}`);
        expect(res.status).toBe(200);
        const body = await res.json();
        return { body, items: extractItems(body), total: extractTotal(body, extractItems(body)) };
      }

      // 1. Combined search + status filter: trimmed keyword "  Kyoto  " + upcoming/not_started
      // Try both possible status values
      let combinedResult;
      for (const statusVal of ['upcoming', 'not_started']) {
        const r = await searchTrips(`  Kyoto ${now}  `, statusVal);
        if (r.items.length > 0) {
          combinedResult = r;
          break;
        }
      }
      expect(combinedResult, 'expected at least one status value to match upcoming trips').toBeTruthy();
      expect(combinedResult.items.length, 'expected exactly 1 trip matching trimmed Kyoto search + upcoming').toBe(1);
      expect(combinedResult.items[0].name).toContain(`Kyoto Blossom ${now}`);
      expect(combinedResult.total).toBe(combinedResult.items.length);

      // 2. Filter by ongoing/in_progress status - should return "Kyoto Active"
      let ongoingResult;
      for (const statusVal of ['ongoing', 'in_progress']) {
        const r = await searchTrips(undefined, statusVal);
        const matchingItems = r.items.filter(i => (i.name || '').includes(String(now)));
        if (matchingItems.length > 0) {
          ongoingResult = { ...r, matchingItems };
          break;
        }
      }
      expect(ongoingResult, 'expected at least one status value to match ongoing trips').toBeTruthy();
      const ongoingNames = ongoingResult.matchingItems.map(i => i.name);
      expect(ongoingNames.some(n => n.includes(`Kyoto Active ${now}`))).toBe(true);

      // 3. Filter by completed/ended status - should return "Osaka Food"
      let completedResult;
      for (const statusVal of ['completed', 'ended']) {
        const r = await searchTrips(undefined, statusVal);
        const matchingItems = r.items.filter(i => (i.name || '').includes(String(now)));
        if (matchingItems.length > 0) {
          completedResult = { ...r, matchingItems };
          break;
        }
      }
      expect(completedResult, 'expected at least one status value to match completed trips').toBeTruthy();
      const completedNames = completedResult.matchingItems.map(i => i.name);
      expect(completedNames.some(n => n.includes(`Osaka Food ${now}`))).toBe(true);

      // 4. Empty search returns all created trips
      const emptySearch = await searchTrips('');
      const names = emptySearch.items.map(x => x.name || '');
      expect(names.some(n => n.includes(`Kyoto Blossom ${now}`))).toBe(true);
      expect(names.some(n => n.includes(`Osaka Food ${now}`))).toBe(true);
      expect(names.some(n => n.includes(`Kyoto Active ${now}`))).toBe(true);

      // 5. No matching results - should return empty with feedback
      let noneResult;
      for (const statusVal of ['completed', 'ended']) {
        const r = await searchTrips(`NoSuchTrip-${now}`, statusVal);
        if (r.items.length === 0) {
          noneResult = r;
          break;
        }
      }
      if (!noneResult) {
        noneResult = await searchTrips(`NoSuchTrip-${now}`);
      }
      expect(noneResult.items.length).toBe(0);
      expect(noneResult.total).toBe(0);
      // Verify there is some kind of no-match feedback
      const emptyMessage = noneResult.body.message || noneResult.body.emptyMessage
        || noneResult.body.data?.message || noneResult.body.data?.emptyMessage
        || noneResult.body.meta?.message;
      // API should provide a message when no results found
      if (emptyMessage) {
        expect(typeof emptyMessage).toBe('string');
        expect(emptyMessage.length).toBeGreaterThan(0);
      }
      // At minimum, the empty items array confirms no results

      // 6. Reset filter - clear search and status, should return all
      const resetResult = await searchTrips('', '');
      const resetNames = resetResult.items.map(x => x.name || '');
      expect(resetNames.some(n => n.includes(`Kyoto Blossom ${now}`))).toBe(true);
      expect(resetNames.some(n => n.includes(`Osaka Food ${now}`))).toBe(true);
      expect(resetNames.some(n => n.includes(`Kyoto Active ${now}`))).toBe(true);

      // 7. Persist search/filter state across refresh (if supported by API)
      // Set a filter state
      const setFilterRes = await fetch(`${BASE_URL}/api/trips/filter-state`, {
        method: 'POST',
        headers: { 'content-type': 'application/json' },
        body: JSON.stringify({ search: `Kyoto ${now}`, status: 'upcoming' })
      }).catch(() => null);

      if (setFilterRes && [200, 201].includes(setFilterRes.status)) {
        // Read back without query params to simulate page refresh
        const refreshRes = await fetch(`${BASE_URL}/api/trips`);
        expect(refreshRes.status).toBe(200);
        const refreshBody = await refreshRes.json();
        const refreshItems = extractItems(refreshBody);
        // If filter state is persisted server-side, the default request should return filtered results
        const refreshNames2 = refreshItems.map(x => x.name || '');
        const hasOnlyMatchingItems = refreshItems.length >= 1 &&
          refreshItems.length < resetResult.items.length;
        if (hasOnlyMatchingItems) {
          expect(refreshNames2.some(n => n.includes(`Kyoto Blossom ${now}`))).toBe(true);
        }
        // Clean up filter state
        await fetch(`${BASE_URL}/api/trips/filter-state`, {
          method: 'POST',
          headers: { 'content-type': 'application/json' },
          body: JSON.stringify({ search: '', status: '' })
        }).catch(() => {});
      }
      // Note: If filter persistence is a frontend-only feature (localStorage/URL params),
      // it cannot be fully validated via API tests. The search + filter correctness
      // has been validated above.
    } finally {
      for (const id of createdIds) {
        await fetch(`${BASE_URL}/api/trips/${id}`, { method: 'DELETE' }).catch(() => {});
      }
    }
  });
});

