import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

function extractItems(body) {
  const data = body.data || body.items || body.favorites || body;
  return Array.isArray(data) ? data : data.items || data.results || [];
}

function extractTotal(body, items) {
  return body.total ?? body.totalCount ?? body.count ?? body.data?.total ?? body.data?.totalCount ?? body.meta?.total ?? items.length;
}

