import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

describe('persist_local_changes_across_tabs', () => {
  it('should persist latest object state and reject or flag stale writes for trips', async () => {
    const suffix = Date.now();
    let tripId;

    try {
      const createRes = await fetch(`${BASE_URL}/api/trips`, {
        method: 'POST',
        headers: { 'content-type': 'application/json' },
        body: JSON.stringify({
          name: `Tab Sync Trip ${suffix}`,
          destination: 'Nanjing',
          startDate: '2099-10-01',
          endDate: '2099-10-03',
          coverDescription: 'initial'
        })
      });
      expect([200, 201]).toContain(createRes.status);
      const createBody = await createRes.json();
      tripId = createBody.id || createBody.tripId || createBody.data?.id;
      expect(tripId).toBeTruthy();

      // Tab1 reads the trip
      const tab1ReadRes = await fetch(`${BASE_URL}/api/trips/${tripId}`);
      expect(tab1ReadRes.status).toBe(200);
      const tab1Body = await tab1ReadRes.json();
      const tab1Trip = tab1Body.data || tab1Body;
      const initialRevision = tab1Trip.revision || tab1Trip.version || tab1Trip.updatedAt;

      // Tab2 updates the trip
      const tab2UpdateRes = await fetch(`${BASE_URL}/api/trips/${tripId}`, {
        method: 'PATCH',
        headers: { 'content-type': 'application/json' },
        body: JSON.stringify({ coverDescription: 'edited in tab2' })
      });
      expect([200, 204]).toContain(tab2UpdateRes.status);

      // Tab1 reads again - should see the latest data from tab2
      const freshReadRes = await fetch(`${BASE_URL}/api/trips/${tripId}`);
      expect(freshReadRes.status).toBe(200);
      const freshReadBody = await freshReadRes.json();
      const freshTrip = freshReadBody.data || freshReadBody;
      expect(freshTrip.coverDescription).toBe('edited in tab2');

      // Verify revision/version changed
      const freshRevision = freshTrip.revision || freshTrip.version || freshTrip.updatedAt;
      if (initialRevision && freshRevision) {
        expect(String(freshRevision)).not.toBe(String(initialRevision));
      }

      // Tab1 attempts stale write using old revision
      if (initialRevision) {
        const staleOverwriteRes = await fetch(`${BASE_URL}/api/trips/${tripId}`, {
          method: 'PATCH',
          headers: {
            'content-type': 'application/json',
            'if-match': String(initialRevision)
          },
          body: JSON.stringify({ coverDescription: 'stale write from tab1' })
        });

        if ([409, 412].includes(staleOverwriteRes.status)) {
          // Server correctly rejected stale write
          const staleBody = await staleOverwriteRes.json().catch(() => ({}));
          expect(/conflict|stale|version|revision|updated|changed/i.test(JSON.stringify(staleBody))).toBe(true);
        } else if (staleOverwriteRes.status === 200) {
          // Server accepted the write - verify it at least provides conflict info
          // or the final state should be the stale write (last-write-wins but not silent)
          const staleBody = await staleOverwriteRes.json().catch(() => ({}));
          const hasConflictInfo = staleBody.conflict || staleBody.warning || staleBody.previousValue || staleBody.merged;
          if (!hasConflictInfo) {
            // Last-write-wins scenario: verify the final state is consistent
            const verifyRes = await fetch(`${BASE_URL}/api/trips/${tripId}`);
            const verifyBody = await verifyRes.json();
            const verifyTrip = verifyBody.data || verifyBody;
            // The value should be one of the two writes, not corrupted
            expect(['edited in tab2', 'stale write from tab1']).toContain(verifyTrip.coverDescription);
          }
        }
      }

      // Verify list is consistent with detail
      const listRes = await fetch(`${BASE_URL}/api/trips`);
      expect(listRes.status).toBe(200);
      const listBody = await listRes.json();
      const listData = listBody.data || listBody.items || listBody.trips || listBody;
      const listItems = Array.isArray(listData) ? listData : listData.items || [];
      const tripInList = listItems.find(t => (t.id || t.tripId) === tripId);
      expect(tripInList, 'expected trip to appear in list').toBeTruthy();
    } finally {
      if (tripId) await fetch(`${BASE_URL}/api/trips/${tripId}`, { method: 'DELETE' }).catch(() => {});
      if (tripId) await fetch(`${BASE_URL}/api/recycle-bin/purge`, {
        method: 'POST',
        headers: { 'content-type': 'application/json' },
        body: JSON.stringify({ entityType: 'trip', entityId: tripId })
      }).catch(() => {});
    }
  });

