      tripId = pickId(importedTrip) || importBody?.data?.createdIds?.[0] || importBody?.createdIds?.[0];
      if (!tripId && importBody?.data?.id) tripId = importBody.data.id;
      if (!tripId && importBody?.id) tripId = importBody.id;
      expect(tripId, `expected imported trip id from import response, got ${JSON.stringify(importBody)}`).toBeTruthy();

      // --- 2. Verify legacy marker defaults to '其他' (strong assertions) ---
