      expect(markersRes.res.status, 'markers endpoint should return 200').toBe(200);
      const markers = markersRes.body?.markers || markersRes.body?.data || markersRes.body;
      expect(Array.isArray(markers), 'markers should be an array').toBe(true);
      expect(markers.length, 'should have at least 2 markers').toBeGreaterThanOrEqual(2);

