      // --- 3. Create a share link via data-center ---
      let shareCreateRes = await request('POST', '/api/data-center/share', { tripId });
      if (![200, 201].includes(shareCreateRes.res.status)) {
        shareCreateRes = await request('POST', `/api/trips/${tripId}/share`, {});
      }
      expect([200, 201]).toContain(shareCreateRes.res.status);
      const shareCreateBody = shareCreateRes.body;
      shareToken = shareCreateBody?.token || shareCreateBody?.shareToken || shareCreateBody?.data?.token || shareCreateBody?.shareId || shareCreateBody?.data?.shareId || shareCreateBody?.id || shareCreateBody?.data?.id;
      expect(shareToken, `expected share token, got ${JSON.stringify(shareCreateBody)}`).toBeTruthy();

      // --- 4. Soft-delete the trip ---
      const softDeleteRes = await request('DELETE', `/api/trips/${tripId}`);
      expect([200, 202, 204]).toContain(softDeleteRes.res.status);

      // --- 5. Verify default export excludes recycle-bin content (strong assertion) ---
      let exportRes = await request('GET', '/api/data-center/export');
      if (exportRes.res.status !== 200) {
        exportRes = await request('GET', '/api/export');
      }
      expect(exportRes.res.status, 'export endpoint should return 200').toBe(200);
      const exportBody = exportRes.body;
      const exportedTrips = exportBody?.trips || exportBody?.data?.trips || [];
      const foundDeletedTrip = exportedTrips.find(t => {
        const tName = t.name || t.title || '';
        return tName.includes(`Imported Trip ${suffix}`);
      });
      expect(foundDeletedTrip, 'default export should NOT include soft-deleted trip in recycle bin').toBeFalsy();

      // --- 6. Restore trip from recycle bin ---
      let restoreRes = await request('POST', '/api/data-center/restore', { entityType: 'trip', entityId: tripId });
      if (![200, 201].includes(restoreRes.res.status)) {
        restoreRes = await request('POST', '/api/recycle-bin/restore', { entityType: 'trip', entityId: tripId });
      }
      expect([200, 201]).toContain(restoreRes.res.status);

      // --- 7. Verify share page is accessible after restore ---
