      const sharedName = sharedTrip.name || sharedTrip.title || '';
      expect(sharedName.includes(`Imported Trip ${suffix}`), `expected shared trip name to include imported trip name, got ${sharedName}`).toBe(true);

      // --- 8. Verify write through share link is forbidden (core read-only assertion) ---
      const forbiddenWriteRes = await request('PATCH', `/api/shared/${shareToken}`, { name: 'attempt write through share link' });
      expect([403, 405]).toContain(forbiddenWriteRes.res.status);

      // Also try PUT as another write method
      const forbiddenPutRes = await request('PUT', `/api/shared/${shareToken}`, { name: 'attempt put' });
      expect([403, 405]).toContain(forbiddenPutRes.res.status);

      // --- 9. Verify duplicate favorite rejection (same name + same city) ---
      const favPayload = {
        name: `FavSpot ${suffix}`,
        city: 'Kunming',
        tags: ['test']
      };
      const fav1Res = await request('POST', '/api/favorites', favPayload);
      expect([200, 201]).toContain(fav1Res.res.status);
      fav1Id = pickId(fav1Res.body?.favorite || fav1Res.body?.data || fav1Res.body, ['id', '_id', 'favoriteId']);

      const fav2Res = await request('POST', '/api/favorites', favPayload);
      // Duplicate should be rejected or warned
      expect([400, 409, 422]).toContain(fav2Res.res.status);

    } finally {
      // Cleanup favorite
      if (fav1Id) await fetch(`${BASE_URL}/api/favorites/${fav1Id}`, { method: 'DELETE' }).catch(() => {});
      if (tripId) {
        await fetch(`${BASE_URL}/api/trips/${tripId}`, { method: 'DELETE' }).catch(() => {});
        await fetch(`${BASE_URL}/api/recycle-bin/purge`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ entityType: 'trip', entityId: tripId })
        }).catch(() => {});
        await fetch(`${BASE_URL}/api/data-center/purge`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ entityType: 'trip', entityId: tripId })
        }).catch(() => {});
      }
    }
  });
});

