      // --- 10. Verify the invalid import did not corrupt existing data ---
      const verifyAfterBadImport = await request('GET', `/api/trips/${tripId}`);
      expect(verifyAfterBadImport.res.status).toBe(200);

    } finally {
      for (const id of importedTripIds) {
        await cleanup([`/api/trips/${id}`]);
        // Also try to purge from recycle bin
        await request('POST', '/api/recycle-bin/purge', { entityType: 'trip', entityId: id }).catch(() => {});
      }
    }
  });
