      const favorites = Array.isArray(listFavorites.data) ? listFavorites.data : (listFavorites.data.items || listFavorites.data.favorites || []);
      expect(Array.isArray(favorites), `expected favorites array, got ${JSON.stringify(listFavorites.data)}`).toBe(true);
      const matched = favorites.filter((item) => (item.recipeId || item.id) === recipeId);
      expect(matched.length, `expected exactly 1 favorite entry for recipe ${recipeId}, got ${matched.length}`).toBe(1);

      const duplicateFavorite = await request('POST', '/api/favorites', { recipeId });
      expect([200, 201, 400, 409, 422]).toContain(duplicateFavorite.res.status);
      if ([200, 201].includes(duplicateFavorite.res.status)) {
        const listFavoritesAgain = await request('GET', '/api/favorites');
        expect(listFavoritesAgain.res.status).toBe(200);
        const favoritesAgain = Array.isArray(listFavoritesAgain.data) ? listFavoritesAgain.data : (listFavoritesAgain.data.items || listFavoritesAgain.data.favorites || []);
        const matchedAgain = favoritesAgain.filter((item) => (item.recipeId || item.id) === recipeId);
        expect(matchedAgain.length, `duplicate favorite should not create additional record for recipe ${recipeId}, got ${matchedAgain.length}`).toBe(1);
