describe('round4_nutrition_item_copy_and_goals', () => {
  it('should copy an item independently and save goals with correct difference values', async () => {
    const calc = await request('POST', '/api/nutrition/calculators', { name: `copy-goals-${Date.now()}` });
    expect(calc.res.status).toBeOneOf([200, 201]);
    const calculatorId = calc.data.id || calc.data.calculatorId;
    expect(calculatorId).toBeTruthy();

    try {
      const baseItem = { name: 'Oats', caloriesPer100g: 389, proteinPer100g: 16.9, fatPer100g: 6.9, carbsPer100g: 66.3, weight: 100 };
      const add = await request('POST', `/api/nutrition/calculators/${calculatorId}/items`, baseItem);
      expect(add.res.status).toBeOneOf([200, 201]);
      const originalId = add.data.id || add.data.itemId;
      expect(originalId).toBeTruthy();

      const copy = await request('POST', `/api/nutrition/calculators/${calculatorId}/items/${originalId}/copy`);
      expect(copy.res.status, `expected copy item 201/200, got ${copy.res.status} with body ${JSON.stringify(copy.data)}`).toBeOneOf([200, 201]);
      const copiedId = copy.data.id || copy.data.itemId;
      expect(copiedId, `expected copied item id, got ${JSON.stringify(copy.data)}`).toBeTruthy();
      expect(copiedId).not.toBe(originalId);

      const updateCopied = await request('PATCH', `/api/nutrition/calculators/${calculatorId}/items/${copiedId}`, { weight: 50, name: 'Oats Copy' });
      expect(updateCopied.res.status).toBe(200);

      const calcState = await request('GET', `/api/nutrition/calculators/${calculatorId}`);
      expect(calcState.res.status).toBe(200);
      const items = calcState.data.items || calcState.data.ingredients || [];
      expect(Array.isArray(items)).toBe(true);
      const original = items.find((i) => (i.id || i.itemId) === originalId);
      const copied = items.find((i) => (i.id || i.itemId) === copiedId);
      expect(original, `expected original item ${originalId} to exist`).toBeTruthy();
      expect(copied, `expected copied item ${copiedId} to exist`).toBeTruthy();
      expect(num(original.weight)).toBe(100);
      expect(num(copied.weight)).toBe(50);
      expect(copied.name).toBe('Oats Copy');

      // Verify each item has a calorie percentage field
      for (const item of items) {
        const pct = item.caloriePercentage ?? item.caloriesPercentage ?? item.caloriePercent ?? item.percentage;
        expect(pct, `expected item ${item.id || item.itemId} to have a calorie percentage field, got item: ${JSON.stringify(item)}`).toBeDefined();
        expect(num(pct)).toBeGreaterThanOrEqual(0);
        expect(num(pct)).toBeLessThanOrEqual(100);
      }
      // The two items together should sum to ~100%
      const totalPct = items.reduce((sum, item) => {
        const pct = item.caloriePercentage ?? item.caloriesPercentage ?? item.caloriePercent ?? item.percentage;
        return sum + num(pct);
      }, 0);
      expect(totalPct).toBeCloseTo(100, 0);

      const goalsPayload = { calories: 700, protein: 30, fat: 20, carbs: 120 };
      const saveGoals = await request('PUT', `/api/nutrition/calculators/${calculatorId}/goals`, goalsPayload);
      expect(saveGoals.res.status, `expected save goals 200, got ${saveGoals.res.status} with body ${JSON.stringify(saveGoals.data)}`).toBe(200);

      const goalsView = await request('GET', `/api/nutrition/calculators/${calculatorId}/goals`);
      expect(goalsView.res.status).toBe(200);
      const payload = goalsView.data.goals ? goalsView.data : { goals: goalsView.data.goals || goalsPayload, difference: goalsView.data.difference || goalsView.data.delta || {} };
      const goals = payload.goals || goalsView.data.goals || goalsPayload;
      const diff = payload.difference || payload.delta || goalsView.data.difference || goalsView.data.delta || {};
      expect(num(goals.calories)).toBe(700);
      expect(num(goals.protein)).toBe(30);
      expect(num(goals.fat)).toBe(20);
      expect(num(goals.carbs)).toBe(120);
      // Oats 100g = 389 cal, 16.9 protein, 6.9 fat, 66.3 carbs
      // Oats Copy 50g = 194.5 cal, 8.45 protein, 3.45 fat, 33.15 carbs
      // Total = 583.5 cal, 25.35 protein, 10.35 fat, 99.45 carbs
      // Diff = goal - total: 116.5, 4.65, 9.65, 20.55
      expect(num(diff.calories)).toBeCloseTo(116.5, 0);
      expect(num(diff.protein)).toBeCloseTo(4.65, 0);
      expect(num(diff.fat)).toBeCloseTo(9.65, 0);
      expect(num(diff.carbs)).toBeCloseTo(20.55, 0);
    } finally {
      await tryDelete(`/api/nutrition/calculators/${calculatorId}`);
    }
  });

  it('should reject negative goal values', async () => {
    const calc = await request('POST', '/api/nutrition/calculators', { name: `neg-goal-${Date.now()}` });
    expect(calc.res.status).toBeOneOf([200, 201]);
    const calculatorId = calc.data.id || calc.data.calculatorId;
    expect(calculatorId).toBeTruthy();

    try {
      const negGoals = await request('PUT', `/api/nutrition/calculators/${calculatorId}/goals`, { calories: -100, protein: 30, fat: 20, carbs: 120 });
      expect(negGoals.res.status, `expected negative goal to be rejected with 4xx, got ${negGoals.res.status}`).toBeGreaterThanOrEqual(400);
      expect(negGoals.res.status).toBeLessThan(500);

      const negProtein = await request('PUT', `/api/nutrition/calculators/${calculatorId}/goals`, { calories: 2000, protein: -50, fat: 60, carbs: 200 });
      expect(negProtein.res.status, `expected negative protein goal to be rejected with 4xx`).toBeGreaterThanOrEqual(400);
      expect(negProtein.res.status).toBeLessThan(500);
    } finally {
      await tryDelete(`/api/nutrition/calculators/${calculatorId}`);
    }
  });

  it('should reject absurdly high goal values', async () => {
    const calc = await request('POST', '/api/nutrition/calculators', { name: `high-goal-${Date.now()}` });
    expect(calc.res.status).toBeOneOf([200, 201]);
    const calculatorId = calc.data.id || calc.data.calculatorId;
    expect(calculatorId).toBeTruthy();

    try {
      const absurdGoals = await request('PUT', `/api/nutrition/calculators/${calculatorId}/goals`, { calories: 99999999, protein: 99999999, fat: 99999999, carbs: 99999999 });
      expect(absurdGoals.res.status, `expected absurdly high goal to be rejected with 4xx, got ${absurdGoals.res.status}`).toBeGreaterThanOrEqual(400);
      expect(absurdGoals.res.status).toBeLessThan(500);
    } finally {
      await tryDelete(`/api/nutrition/calculators/${calculatorId}`);
    }
  });
});

