describe('round5_weekly_meal_plan_persistence', () => {
  it('should persist one-week breakfast/lunch/dinner data, block duplicate additions, and update totals after deletion', async () => {
    const unique = `week-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`;
    const recipes = [];

    const recipeDefs = [
      { title: `Breakfast ${unique}`, calories: 300 },
      { title: `Lunch ${unique}`, calories: 600 },
      { title: `Dinner ${unique}`, calories: 800 }
    ];

    try {
      for (const def of recipeDefs) {
        const r = await request('POST', '/api/recipes', {
          title: def.title,
          description: 'weekly meal plan verifier recipe',
          calories: def.calories,
          ingredients: [{ name: 'Ingredient', amount: 1, unit: 'serving' }],
          steps: ['cook']
        });
        expect(r.res.status).toBeOneOf([200, 201]);
        recipes.push({ id: r.data.id || r.data.recipeId, calories: def.calories, title: def.title });
      }

      const weekId = 'current';
      const monday = 'monday';
      const breakfast = recipes[0];
      const lunch = recipes[1];
      const dinner = recipes[2];

      const addBreakfast = await request('POST', `/api/meal-plans/${weekId}/days/${monday}/meals/breakfast`, { recipeId: breakfast.id });
      expect(addBreakfast.res.status).toBeOneOf([200, 201]);
      const addLunch = await request('POST', `/api/meal-plans/${weekId}/days/${monday}/meals/lunch`, { recipeId: lunch.id });
      expect(addLunch.res.status).toBeOneOf([200, 201]);
      const addDinner = await request('POST', `/api/meal-plans/${weekId}/days/${monday}/meals/dinner`, { recipeId: dinner.id });
      expect(addDinner.res.status).toBeOneOf([200, 201]);

      // Attempt duplicate addition - same recipe in same meal slot
      const duplicateBreakfast = await request('POST', `/api/meal-plans/${weekId}/days/${monday}/meals/breakfast`, { recipeId: breakfast.id });
      if (duplicateBreakfast.res.status >= 400) {
        // Server rejected the duplicate - verify it gives a meaningful message
        const errBody = typeof duplicateBreakfast.data === 'string' ? duplicateBreakfast.data : JSON.stringify(duplicateBreakfast.data);
        expect(errBody.toLowerCase()).toMatch(/duplicate|already|exist|repeat|重复|已存在/);
      } else {
        // Server returned 2xx - verify the meal slot still has only one instance of the recipe
        const checkView = await request('GET', `/api/meal-plans/${weekId}`);
        expect(checkView.res.status).toBe(200);
        const checkDays = checkView.data.days || checkView.data.week || checkView.data;
        const checkMonday = checkDays[monday] || (Array.isArray(checkDays) ? checkDays.find((d) => d.day === monday) : null);
        const breakfastCheck = checkMonday.breakfast || checkMonday.meals?.breakfast || [];
        const breakfastRecipeIds = breakfastCheck.map((item) => item.recipeId || item.id);
        const duplicateCount = breakfastRecipeIds.filter((id) => String(id) === String(breakfast.id)).length;
        expect(duplicateCount, 'same recipe should not appear twice in the same meal slot').toBe(1);
      }

      const weekView1 = await request('GET', `/api/meal-plans/${weekId}`);
      expect(weekView1.res.status, `expected meal plan fetch 200, got ${weekView1.res.status} with body ${JSON.stringify(weekView1.data)}`).toBe(200);
      const days1 = weekView1.data.days || weekView1.data.week || weekView1.data;
      expect(days1).toBeTruthy();
      const mondayData = days1[monday] || (Array.isArray(days1) ? days1.find((d) => d.day === monday) : null);
      expect(mondayData, `expected monday data in week view, got ${JSON.stringify(days1)}`).toBeTruthy();
      const breakfastItems = mondayData.breakfast || mondayData.meals?.breakfast || [];
      const lunchItems = mondayData.lunch || mondayData.meals?.lunch || [];
      const dinnerItems = mondayData.dinner || mondayData.meals?.dinner || [];
      expect(breakfastItems.length).toBe(1);
      expect(lunchItems.length).toBe(1);
      expect(dinnerItems.length).toBe(1);
      const total1 = weekView1.data.totalCalories || weekView1.data.summary?.calories || mondayData.totalCalories || 0;
      expect(Number(total1)).toBeGreaterThanOrEqual(1700);

      // Second GET to verify persistence
      const weekView2 = await request('GET', `/api/meal-plans/${weekId}`);
      expect(weekView2.res.status).toBe(200);
      const days2 = weekView2.data.days || weekView2.data.week || weekView2.data;
      const mondayData2 = days2[monday] || (Array.isArray(days2) ? days2.find((d) => d.day === monday) : null);
      expect(mondayData2).toBeTruthy();
      expect((mondayData2.breakfast || mondayData2.meals?.breakfast || []).length).toBe(1);
      expect((mondayData2.lunch || mondayData2.meals?.lunch || []).length).toBe(1);
