    const unique = `copy-day-${Date.now()}-${Math.random().toString(36).slice(2, 6)}`;
    const recipeCreates = await Promise.all([
      request('POST', '/api/recipes', { title: `B-${unique}`, calories: 250, ingredients: [{ name: 'a', amount: 1, unit: 'x' }], steps: ['x'] }),
