      request('POST', '/api/recipes', { title: `D-${unique}`, calories: 700, ingredients: [{ name: 'c', amount: 1, unit: 'x' }], steps: ['x'] }),
      request('POST', '/api/recipes', { title: `Conflict-${unique}`, calories: 300, ingredients: [{ name: 'd', amount: 1, unit: 'x' }], steps: ['x'] })
    ]);
    recipeCreates.forEach((r) => expect(r.res.status).toBeOneOf([200, 201]));
    const [b, l, d, conflict] = recipeCreates.map((r) => ({ id: r.data.id || r.data.recipeId }));
    const weekId = `week-${unique}`;

    try {
      await request('POST', `/api/meal-plans/${weekId}/days/monday/meals/breakfast`, { recipeId: b.id });
      await request('POST', `/api/meal-plans/${weekId}/days/monday/meals/lunch`, { recipeId: l.id });
      await request('POST', `/api/meal-plans/${weekId}/days/monday/meals/dinner`, { recipeId: d.id });
      await request('POST', `/api/meal-plans/${weekId}/days/tuesday/meals/breakfast`, { recipeId: conflict.id });

      const monday = await request('GET', `/api/meal-plans/${weekId}/days/monday`);
      expect(monday.res.status).toBe(200);
      const meals = monday.data.meals || monday.data;
      expect((meals.breakfast || []).length).toBe(1);
      expect((meals.lunch || []).length).toBe(1);
      expect((meals.dinner || []).length).toBe(1);
      const summary = monday.data.summary || monday.data.totals || monday.data;
      expect(Number(summary.calories || summary.totalCalories || 0)).toBeGreaterThanOrEqual(1450);

      const conflictCopy = await request('POST', `/api/meal-plans/${weekId}/days/monday/copy`, { targetDay: 'tuesday' });
      expect([200, 201, 400, 409, 422]).toContain(conflictCopy.res.status);
      if ([400, 409, 422].includes(conflictCopy.res.status)) {
        const msg = typeof conflictCopy.data === 'string' ? conflictCopy.data : JSON.stringify(conflictCopy.data);
        expect(msg.toLowerCase(), `expected conflict message, got ${msg}`).toMatch(/conflict|duplicate|already|冲突/);
      }

      const successCopy = await request('POST', `/api/meal-plans/${weekId}/days/monday/copy`, { targetDay: 'wednesday' });
      expect(successCopy.res.status, `expected successful day copy, got ${successCopy.res.status} with body ${JSON.stringify(successCopy.data)}`).toBeOneOf([200, 201]);

      const wednesday = await request('GET', `/api/meal-plans/${weekId}/days/wednesday`);
      expect(wednesday.res.status).toBe(200);
      const wMeals = wednesday.data.meals || wednesday.data;
      expect((wMeals.breakfast || []).length).toBe(1);
      expect((wMeals.lunch || []).length).toBe(1);
      expect((wMeals.dinner || []).length).toBe(1);

      const week = await request('GET', `/api/meal-plans/${weekId}`);
