describe('round7_shopping_list_generation_and_progress', () => {
  it('should generate aggregated shopping list from weekly meal plan, toggle purchased state, update progress, and guide when empty', async () => {
    const unique = `shop-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`;
    const weekId = 'current';

    const recipe1 = await request('POST', '/api/recipes', {
      title: `Recipe1 ${unique}`,
      ingredients: [
        { name: 'Tomato', amount: 2, unit: 'pcs' },
        { name: 'Egg', amount: 3, unit: 'pcs' }
      ],
      steps: ['cook']
    });
    const recipe2 = await request('POST', '/api/recipes', {
      title: `Recipe2 ${unique}`,
      ingredients: [
        { name: 'Tomato', amount: 1, unit: 'pcs' },
        { name: 'Milk', amount: 500, unit: 'ml' }
      ],
      steps: ['cook']
    });
    // Recipe with incompatible units for merging
    const recipe3 = await request('POST', '/api/recipes', {
      title: `Recipe3 ${unique}`,
      ingredients: [
        { name: 'Tomato', amount: 200, unit: 'g' }
      ],
      steps: ['cook']
    });
    expect(recipe1.res.status).toBeOneOf([200, 201]);
    expect(recipe2.res.status).toBeOneOf([200, 201]);
    expect(recipe3.res.status).toBeOneOf([200, 201]);
    const recipe1Id = recipe1.data.id || recipe1.data.recipeId;
    const recipe2Id = recipe2.data.id || recipe2.data.recipeId;
    const recipe3Id = recipe3.data.id || recipe3.data.recipeId;

    try {
      // === Ensure meal plan is empty first ===
      // Try to clear any existing meal plan entries for the days we'll use
      try { await request('DELETE', `/api/meal-plans/${weekId}/days/monday/meals/lunch`); } catch {}
      try { await request('DELETE', `/api/meal-plans/${weekId}/days/tuesday/meals/dinner`); } catch {}
      try { await request('DELETE', `/api/meal-plans/${weekId}/days/wednesday/meals/lunch`); } catch {}
      // Also try clearing the whole week
      try { await request('DELETE', `/api/meal-plans/${weekId}`); } catch {}

      // === Empty meal plan → shopping list should show guidance ===
      const emptyList = await request('GET', `/api/shopping-lists/${weekId}`);
      // Whether 200 with empty items or 404, the response should contain guidance
      if (emptyList.res.status === 200) {
        const items = emptyList.data.items || emptyList.data.ingredients || [];
        // After clearing, items should be empty
        expect(items.length, 'After clearing meal plan, shopping list should be empty').toBe(0);
        const emptyMsg = typeof emptyList.data === 'string' ? emptyList.data : JSON.stringify(emptyList.data);
        expect(emptyMsg.toLowerCase()).toMatch(/empty|no meal|guide|添加|餐单|安排|plan|提示|先/);
      } else if (emptyList.res.status === 404) {
        const errMsg = typeof emptyList.data === 'string' ? emptyList.data : JSON.stringify(emptyList.data);
        expect(errMsg.toLowerCase()).toMatch(/empty|no meal|guide|添加|餐单|安排|plan|提示|先/);
      } else {
        // Accept 200 or 404 only for empty state
        expect([200, 404]).toContain(emptyList.res.status);
      }

      // Add recipes to meal plan
      await request('POST', `/api/meal-plans/${weekId}/days/monday/meals/lunch`, { recipeId: recipe1Id });
      await request('POST', `/api/meal-plans/${weekId}/days/tuesday/meals/dinner`, { recipeId: recipe2Id });
      await request('POST', `/api/meal-plans/${weekId}/days/wednesday/meals/lunch`, { recipeId: recipe3Id });

      const generated = await request('POST', `/api/shopping-lists/${weekId}/generate`);
      expect(generated.res.status, `expected shopping list generate 200/201, got ${generated.res.status} with body ${JSON.stringify(generated.data)}`).toBeOneOf([200, 201]);

      const list = await request('GET', `/api/shopping-lists/${weekId}`);
      expect(list.res.status).toBe(200);
      const items = list.data.items || list.data.ingredients || [];
      expect(Array.isArray(items)).toBe(true);
      const egg = items.find((i) => (i.name || '').toLowerCase() === 'egg');
      const milk = items.find((i) => (i.name || '').toLowerCase() === 'milk');
      expect(egg, 'Egg item should exist in shopping list').toBeTruthy();
      expect(milk, 'Milk item should exist in shopping list').toBeTruthy();
      expect(Number(egg.amount || egg.quantity)).toBe(3);
      expect(Number(milk.amount || milk.quantity)).toBe(500);

      // Tomato appears with different units (pcs and g) - check merge or visible note
      const tomatoItems = items.filter((i) => (i.name || '').toLowerCase() === 'tomato');
      expect(tomatoItems.length).toBeGreaterThanOrEqual(1);
      if (tomatoItems.length === 1) {
        // Merged into one - must have a note/warning about unit mismatch
        const tomatoStr = JSON.stringify(tomatoItems[0]).toLowerCase();
        const hasNote = tomatoItems[0].note || tomatoItems[0].warning || tomatoItems[0].message || tomatoItems[0].remarks;
        const hasNoteInStr = tomatoStr.match(/note|warning|mismatch|说明|提示|无法合并|不同单位|unit/);
        expect(hasNote || hasNoteInStr, `When merging tomato with incompatible units (pcs and g), a visible note/warning should exist. Got: ${tomatoStr}`).toBeTruthy();
      } else {
        // Multiple entries kept separate due to incompatible units - also acceptable
        // Verify pcs tomatoes are merged correctly: recipe1(2 pcs) + recipe2(1 pcs) = 3 pcs
        const tomatoPcs = tomatoItems.find((i) => (i.unit || '').toLowerCase() === 'pcs');
        const tomatoG = tomatoItems.find((i) => (i.unit || '').toLowerCase() === 'g');
        if (tomatoPcs) {
          expect(Number(tomatoPcs.amount || tomatoPcs.quantity), 'Tomato pcs should be merged: 2+1=3').toBe(3);
        }
        if (tomatoG) {
          expect(Number(tomatoG.amount || tomatoG.quantity), 'Tomato g should be 200').toBe(200);
        }
        expect(tomatoItems.length).toBeGreaterThanOrEqual(2);
      }

      // === Record progress BEFORE toggle ===
      const progressBefore = list.data.progress || list.data.summary || {};
      const purchasedBefore = Number(progressBefore.purchasedCount || progressBefore.completed || 0);

      // Toggle purchased state
      const targetId = egg.id || egg.itemId;
      expect(targetId).toBeTruthy();
      const toggle = await request('PATCH', `/api/shopping-lists/${weekId}/items/${targetId}`, { purchased: true });
      expect(toggle.res.status).toBe(200);

      const listAfter = await request('GET', `/api/shopping-lists/${weekId}`);
      expect(listAfter.res.status).toBe(200);
      const itemsAfter = listAfter.data.items || listAfter.data.ingredients || [];
      const eggAfter = itemsAfter.find((i) => (i.id || i.itemId) === targetId);
      expect(Boolean(eggAfter.purchased)).toBe(true);

      // Verify progress AFTER toggle - purchasedCount should have increased by 1
      const progressAfter = listAfter.data.progress || listAfter.data.summary || {};
      const purchasedAfter = Number(progressAfter.purchasedCount || progressAfter.completed || 0);
      expect(purchasedAfter, 'purchasedCount should increase by 1 after toggling item to purchased').toBe(purchasedBefore + 1);
      expect(Number(progressAfter.totalCount || progressAfter.total || itemsAfter.length)).toBeGreaterThanOrEqual(3);

      // Toggle back to unpurchased and verify progress reverts
      const toggleBack = await request('PATCH', `/api/shopping-lists/${weekId}/items/${targetId}`, { purchased: false });
      expect(toggleBack.res.status).toBe(200);

      const listAfterRevert = await request('GET', `/api/shopping-lists/${weekId}`);
      expect(listAfterRevert.res.status).toBe(200);
      const eggReverted = (listAfterRevert.data.items || listAfterRevert.data.ingredients || []).find((i) => (i.id || i.itemId) === targetId);
      expect(Boolean(eggReverted.purchased), 'Egg should be back to unpurchased').toBe(false);
      const progressReverted = listAfterRevert.data.progress || listAfterRevert.data.summary || {};
      const purchasedReverted = Number(progressReverted.purchasedCount || progressReverted.completed || 0);
      expect(purchasedReverted, 'purchasedCount should revert after toggling back to unpurchased').toBe(purchasedBefore);

      // === Delete a shopping list item and verify undo/restore entry ===
      const milkItem = itemsAfter.find((i) => (i.name || '').toLowerCase() === 'milk');
      const milkId = milkItem.id || milkItem.itemId;
      const deleteRes = await request('DELETE', `/api/shopping-lists/${weekId}/items/${milkId}`);
      expect([200, 204]).toContain(deleteRes.res.status);

      // Check for undo/restore capability
      const afterDelete = await request('GET', `/api/shopping-lists/${weekId}`);
      expect(afterDelete.res.status).toBe(200);
      const afterDeleteData = afterDelete.data;
      // The response or a separate endpoint should provide an undo/restore mechanism
      const hasUndo = afterDeleteData.undo || afterDeleteData.undoAvailable || afterDeleteData.canUndo || afterDeleteData.lastDeleted;
      // Also try a dedicated undo endpoint
      const undoRes = await request('POST', `/api/shopping-lists/${weekId}/items/${milkId}/restore`);
      const undoAvailable = hasUndo || (undoRes.res.status >= 200 && undoRes.res.status < 300);
      expect(undoAvailable, 'should have a restore/undo mechanism after deleting a shopping list item').toBe(true);

    } finally {
      // Cleanup meal plan entries
      try { await request('DELETE', `/api/meal-plans/${weekId}/days/monday/meals/lunch/${recipe1Id}`); } catch {}
      try { await request('DELETE', `/api/meal-plans/${weekId}/days/tuesday/meals/dinner/${recipe2Id}`); } catch {}
      try { await request('DELETE', `/api/meal-plans/${weekId}/days/wednesday/meals/lunch/${recipe3Id}`); } catch {}
      try { await request('DELETE', `/api/meal-plans/${weekId}/days/monday/meals/lunch`); } catch {}
      try { await request('DELETE', `/api/meal-plans/${weekId}/days/tuesday/meals/dinner`); } catch {}
      try { await request('DELETE', `/api/meal-plans/${weekId}/days/wednesday/meals/lunch`); } catch {}
      await tryDelete(`/api/recipes/${recipe1Id}`);
      await tryDelete(`/api/recipes/${recipe2Id}`);
      await tryDelete(`/api/recipes/${recipe3Id}`);
    }
  });
});

