      expect((await request('POST', `/api/meal-plans/${currentWeekId}/days/monday/meals/breakfast`, { recipeId })).res.status).toBeOneOf([200, 201]);
      expect((await request('POST', `/api/meal-plans/${nextWeekId}/days/tuesday/meals/dinner`, { recipeId })).res.status).toBeOneOf([200, 201]);
