      expect((await request('PATCH', `/api/shopping-lists/${currentWeekId}/items/${itemId}`, { purchased: true })).res.status).toBe(200);

      const calc = await request('POST', '/api/nutrition/calculators', { name: `backup-calc-${unique}` });
      expect(calc.res.status).toBeOneOf([200, 201]);
      const calculatorId = calc.data.id || calc.data.calculatorId;
      expect(calculatorId).toBeTruthy();
      expect((await request('PUT', `/api/nutrition/calculators/${calculatorId}/goals`, { calories: 1800, protein: 100, fat: 60, carbs: 200 })).res.status).toBe(200);

      // Export
      const exported = await request('GET', '/api/backup/export');
      expect(exported.res.status, `expected backup export 200, got ${exported.res.status} with body ${JSON.stringify(exported.data)}`).toBe(200);
      expect(exported.data).toBeTruthy();
      const backupPayload = exported.data.backup || exported.data;
      const backupText = JSON.stringify(backupPayload);
      expect(backupText).toMatch(/favorites|meal|shopping|goal/i);

      // Verify export contains identifiable metadata (version, exportDate, etc.)
      const meta = backupPayload;
      const hasVersion = meta.version !== undefined || meta.formatVersion !== undefined || meta.schemaVersion !== undefined;
      const hasDate = meta.exportDate !== undefined || meta.exportedAt !== undefined || meta.timestamp !== undefined || meta.createdAt !== undefined;
      expect(hasVersion || hasDate, `expected export to contain identifiable meta info (version or date), got keys: ${Object.keys(meta).join(', ')}`).toBe(true);

      // Clear data to simulate fresh state
      await request('DELETE', `/api/favorites/${recipeId}`);
      await request('DELETE', `/api/meal-plans/${currentWeekId}/days/monday/meals/breakfast/${recipeId}`);
      await request('DELETE', `/api/meal-plans/${nextWeekId}/days/tuesday/meals/dinner/${recipeId}`);

      // Import
      const imported = await request('POST', '/api/backup/import', backupPayload);
      expect(imported.res.status, `expected backup import success 200/201, got ${imported.res.status} with body ${JSON.stringify(imported.data)}`).toBeOneOf([200, 201]);

      // Verify favorites restored
