      expect([400, 409, 422]).toContain(invalidImport.res.status);

      // Verify favorites preserved after failed import
      const stateAfterFailedImport = await request('GET', '/api/favorites');
      expect(stateAfterFailedImport.res.status).toBe(200);
      const favoritesAfterFailed = Array.isArray(stateAfterFailedImport.data) ? stateAfterFailedImport.data : (stateAfterFailedImport.data.items || stateAfterFailedImport.data.favorites || []);
      expect(favoritesAfterFailed.some((i) => String(i.recipeId || i.id) === String(recipeId)), 'favorites should remain after failed import').toBe(true);

      // Verify current week meal plan preserved after failed import
      const currentPlanAfterFail = await request('GET', `/api/meal-plans/${currentWeekId}`);
      expect(currentPlanAfterFail.res.status).toBe(200);
      expect(JSON.stringify(currentPlanAfterFail.data)).toContain(String(recipeId));

      // Verify next week meal plan preserved after failed import
      const nextPlanAfterFail = await request('GET', `/api/meal-plans/${nextWeekId}`);
      expect(nextPlanAfterFail.res.status).toBe(200);
      expect(JSON.stringify(nextPlanAfterFail.data)).toContain(String(recipeId));

      // Verify shopping list purchased state preserved after failed import
      const shoppingAfterFail = await request('GET', `/api/shopping-lists/${currentWeekId}`);
      expect(shoppingAfterFail.res.status).toBe(200);
      const itemsAfterFail = shoppingAfterFail.data.items || shoppingAfterFail.data.ingredients || [];
      expect(itemsAfterFail.some((i) => Boolean(i.purchased)), 'purchased state should remain after failed import').toBe(true);

      // Verify nutrition goals preserved after failed import
      const goalsAfterFail = await request('GET', `/api/nutrition/calculators/${calculatorId}/goals`);
      expect(goalsAfterFail.res.status).toBe(200);
      const goalsDataAfterFail = goalsAfterFail.data.goals || goalsAfterFail.data;
      expect(Number(goalsDataAfterFail.calories)).toBe(1800);

      // === Failed import: oversized payload ===
      const oversizedImport = await request('POST', '/api/backup/import', { data: 'X'.repeat(2 * 1024 * 1024) });
      expect([400, 413, 422]).toContain(oversizedImport.res.status);
      const oversizedMsg = JSON.stringify(oversizedImport.data).toLowerCase();
      expect(oversizedMsg, 'oversized import should mention size-related error').toMatch(/large|size|too big|payload|exceed|过大/);

      // === Failed import: incomplete/corrupt content ===
      const incompleteImport = await request('POST', '/api/backup/import', { version: 2, mealPlans: [{}] });
      expect([400, 422]).toContain(incompleteImport.res.status);
      const incompleteMsg = JSON.stringify(incompleteImport.data).toLowerCase();
      expect(incompleteMsg, 'incomplete import should indicate invalid/incomplete/corrupt').toMatch(/invalid|incomplete|corrupt|missing|残缺/);

      // === Failed import: unsupported version ===
      const unsupportedImport = await request('POST', '/api/backup/import', { version: 9999, mealPlans: [], settings: {} });
      expect([400, 422]).toContain(unsupportedImport.res.status);
      const unsupportedMsg = JSON.stringify(unsupportedImport.data).toLowerCase();
      expect(unsupportedMsg, 'unsupported version import should indicate version issue').toMatch(/version|unsupported|不支持/);

      // Verify all three errors produce distinct messages
      expect(oversizedMsg).not.toBe(incompleteMsg);
      expect(oversizedMsg).not.toBe(unsupportedMsg);
      expect(incompleteMsg).not.toBe(unsupportedMsg);

      // === Legacy (old format, single-week) backup import ===
      // Old format has no 'current'/'next' keys — flat structure without week period concept
      const legacyBackup = {
        favorites: [{ recipeId }],
        mealPlans: {
          sunday: { dinner: [{ recipeId }] }
        },
        version: 1
      };
      const legacyImport = await request('POST', '/api/backup/import', legacyBackup);
      expect(legacyImport.res.status).toBeOneOf([200, 201]);

      // Verify legacy data landed in current week
      const currentAfterLegacy = await request('GET', `/api/meal-plans/${currentWeekId}`);
      expect(currentAfterLegacy.res.status).toBe(200);
      const currentLegacyDays = currentAfterLegacy.data.days || currentAfterLegacy.data.week || currentAfterLegacy.data;
      const sundayData = currentLegacyDays.sunday || currentLegacyDays['sunday'] || (Array.isArray(currentLegacyDays) ? currentLegacyDays.find((d) => d.day === 'sunday') : null);
      expect(sundayData, 'sunday should exist in current week after legacy import').toBeTruthy();
      const sundayDinner = sundayData.dinner || sundayData.meals?.dinner || [];
      const dinnerArr = Array.isArray(sundayDinner) ? sundayDinner : [sundayDinner];
      const hasSundayDinnerRecipe = dinnerArr.some((item) => String(item.recipeId || item.id) === String(recipeId));
      expect(hasSundayDinnerRecipe, `legacy import should place sunday dinner recipe in current week, got: ${JSON.stringify(sundayDinner)}`).toBe(true);

      // Verify next week is NOT polluted by legacy import
      const nextAfterLegacy = await request('GET', `/api/meal-plans/${nextWeekId}`);
      if (nextAfterLegacy.res.status === 200) {
        const nextLegacyDays = nextAfterLegacy.data.days || nextAfterLegacy.data.week || nextAfterLegacy.data;
        const nextSunday = nextLegacyDays.sunday || nextLegacyDays['sunday'] || (Array.isArray(nextLegacyDays) ? nextLegacyDays.find((d) => d.day === 'sunday') : null);
        if (nextSunday) {
          const nextSundayDinner = nextSunday.dinner || nextSunday.meals?.dinner || [];
          const nextDinnerArr = Array.isArray(nextSundayDinner) ? nextSundayDinner : [nextSundayDinner].filter(Boolean);
          // Legacy import data for sunday dinner should NOT appear in next week
          const hasLegacyInNextSunday = nextDinnerArr.some((item) => String(item.recipeId || item.id) === String(recipeId));
          expect(hasLegacyInNextSunday, 'legacy import should NOT place data in next week').toBe(false);
        }
        // else next week sunday doesn't exist at all — that's fine, it means next week is empty
      } else {
        // 404 or empty next week is acceptable — means next week is empty
        expect([200, 404]).toContain(nextAfterLegacy.res.status);
      }
    } finally {
      await tryDelete(`/api/favorites/${recipeId}`);
      try { await request('DELETE', `/api/meal-plans/current/days/monday/meals/breakfast/${recipeId}`); } catch {}
      try { await request('DELETE', `/api/meal-plans/next/days/tuesday/meals/dinner/${recipeId}`); } catch {}
      try { await request('DELETE', `/api/meal-plans/current/days/sunday/meals/dinner/${recipeId}`); } catch {}
      try { await request('DELETE', `/api/meal-plans/current/days/monday/meals/breakfast`); } catch {}
      try { await request('DELETE', `/api/meal-plans/next/days/tuesday/meals/dinner`); } catch {}
      try { await request('DELETE', `/api/meal-plans/current/days/sunday/meals/dinner`); } catch {}
      await tryDelete(`/api/recipes/${recipeId}`);
    }
  });
});

