    });
    expect(recipe.res.status).toBeOneOf([200, 201]);
    const recipeId = recipe.data.id || recipe.data.recipeId;

    try {
      // === Test 1: Deleting meal should not cancel favorite ===
      expect((await request('POST', '/api/favorites', { recipeId })).res.status).toBeOneOf([200, 201]);
      expect((await request('POST', `/api/meal-plans/${weekId}/days/monday/meals/breakfast`, { recipeId })).res.status).toBeOneOf([200, 201]);
      expect((await request('DELETE', `/api/meal-plans/${weekId}/days/monday/meals/breakfast/${recipeId}`)).res.status).toBeOneOf([200, 204]);

      const favList = await request('GET', '/api/favorites');
