        // All items should belong to some group - check for a default/other group
        const allGroupItems = groups.flatMap((g) => g.items || []);
        expect(allGroupItems.length).toBeGreaterThanOrEqual(items.length);
      }

      // === Test 3: Distinguish "no data" vs "filter results empty" ===

