      const emptySearch = await request('GET', '/api/recipes/search?q=no-such-keyword-verifier-xyzzy');
      expect(emptySearch.res.status).toBe(200);
      const searchItems = Array.isArray(emptySearch.data) ? emptySearch.data : (emptySearch.data.items || emptySearch.data.results || []);
      expect(searchItems.length).toBe(0);

      // The empty search response should indicate it's a filter/search result being empty
