      const sundayDinner = sundayData.dinner || sundayData.meals?.dinner || [];
      const dinnerArr = Array.isArray(sundayDinner) ? sundayDinner : [sundayDinner].filter(Boolean);
      expect(dinnerArr.some((item) => String(item.recipeId || item.id) === String(recipeId)), 'legacy data should be in current week sunday dinner').toBe(true);

      // Verify next week remains empty (not polluted by legacy import)
