        const nextDays = nextPlan.data.days || nextPlan.data.week || nextPlan.data;
        const nextSunday = nextDays.sunday || nextDays['sunday'] || (Array.isArray(nextDays) ? nextDays.find((d) => d.day === 'sunday') : null);
        if (nextSunday) {
