describe('round19_unified_add_to_plan_rules', () => {
  it('should enforce the same duplicate-add rule from different entry points (favorites vs detail) and avoid double accumulation', async () => {
    const uid = `vt-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
    const recipePayload = {
      title: `Unified Plan Recipe ${uid}`,
      servings: 2,
      ingredients: [
        { name: `Chicken Breast ${uid}`, quantity: 200, unit: 'g' },
        { name: `Broccoli ${uid}`, quantity: 150, unit: 'g' }
      ],
      nutrition: { calories: 420, protein: 35, carbs: 18, fat: 14 }
    };

    let recipeId;
    let planId;

    try {
      // Create a recipe
      const createRecipe = await http('POST', '/api/recipes', recipePayload);
      expect([200, 201]).toContain(createRecipe.res.status);
      expect(createRecipe.body && typeof createRecipe.body).toBe('object');
      recipeId = createRecipe.body.id || createRecipe.body.recipeId;
      expect(recipeId, `recipe id should exist in response: ${JSON.stringify(createRecipe.body)}`).toBeTruthy();
      expect(createRecipe.body.title || createRecipe.body.name).toBe(recipePayload.title);

      // Add to favorites so we can simulate adding from favorites entry
      const favRes = await http('POST', '/api/favorites', { recipeId });
      expect([200, 201]).toContain(favRes.res.status);

      const addPayload = {
        week: '2025-W30',
        day: 'tuesday',
        mealType: 'lunch',
        recipeId
      };

      // First add: simulate adding from favorites page (source: 'favorites')
      const firstAdd = await http('POST', '/api/meal-plans', {
        ...addPayload,
        source: 'favorites'
      });
      expect([200, 201]).toContain(firstAdd.res.status);
      expect(firstAdd.body && typeof firstAdd.body).toBe('object');
      planId = firstAdd.body.id || firstAdd.body.planId;
      expect(planId, `plan id should exist in response: ${JSON.stringify(firstAdd.body)}`).toBeTruthy();
      expect(firstAdd.body.recipeId || firstAdd.body.recipe?.id).toBe(recipeId);

      // Capture the success message/response from first add for later comparison
      const firstAddResponseText = JSON.stringify(firstAdd.body).toLowerCase();

      // Second add: simulate adding from detail page (source: 'detail') to the SAME slot
      const duplicateFromDetail = await http('POST', '/api/meal-plans', {
        ...addPayload,
        source: 'detail'
      });
      expect([200, 409]).toContain(duplicateFromDetail.res.status);
      expect(duplicateFromDetail.body, 'duplicate add should return a response body').toBeTruthy();

      const duplicateDetailMessage = JSON.stringify(duplicateFromDetail.body).toLowerCase();
      expect(
        duplicateDetailMessage,
        `duplicate add from detail page should mention duplicate/exists/already, actual: ${JSON.stringify(duplicateFromDetail.body)}`
      ).toMatch(/duplicate|exists|already/);

      // Third add: simulate adding from search page (source: 'search') to the SAME slot
      const duplicateFromSearch = await http('POST', '/api/meal-plans', {
        ...addPayload,
        source: 'search'
      });
      expect([200, 409]).toContain(duplicateFromSearch.res.status);
      expect(duplicateFromSearch.body, 'duplicate add from search should return a response body').toBeTruthy();

      const duplicateSearchMessage = JSON.stringify(duplicateFromSearch.body).toLowerCase();
      expect(
        duplicateSearchMessage,
        `duplicate add from search page should mention duplicate/exists/already, actual: ${JSON.stringify(duplicateFromSearch.body)}`
      ).toMatch(/duplicate|exists|already/);

      // Verify conflict prompt consistency: both duplicate responses should have the same status code and similar message
      expect(
        duplicateFromDetail.res.status,
        'conflict status code should be consistent across different entry points'
      ).toBe(duplicateFromSearch.res.status);

      // Verify only one plan entry exists (no double creation)
      const listPlan = await http('GET', `/api/meal-plans?week=${encodeURIComponent(addPayload.week)}`);
      expect(listPlan.res.status).toBe(200);
      const planItems = Array.isArray(listPlan.body)
        ? listPlan.body
        : Array.isArray(listPlan.body?.items)
          ? listPlan.body.items
          : Array.isArray(listPlan.body?.data)
            ? listPlan.body.data
            : [];

      const matches = planItems.filter((item) => {
        const itemRecipeId = item.recipeId || item.recipe?.id;
        const itemDay = item.day || item.slot?.day;
        const itemMealType = item.mealType || item.slot?.mealType;
        return itemRecipeId === recipeId && itemDay === addPayload.day && itemMealType === addPayload.mealType;
      });

      expect(matches.length, `duplicate adds from different entry points should not create more than one plan entry, found ${matches.length}`).toBe(1);

      // Verify shopping list is not double-accumulated
      const shopping = await http('GET', `/api/shopping-list?week=${encodeURIComponent(addPayload.week)}`);
      expect(shopping.res.status).toBe(200);
      expect(shopping.body, 'shopping list response body should exist').toBeTruthy();
      const shoppingItems = Array.isArray(shopping.body)
        ? shopping.body
        : Array.isArray(shopping.body?.items)
          ? shopping.body.items
          : Array.isArray(shopping.body?.data)
            ? shopping.body.data
            : [];

      const chickenItem = shoppingItems.find((item) => String(item.name || item.ingredient || '').includes(uid));
      expect(chickenItem, `shopping list should contain created ingredient marker ${uid}`).toBeTruthy();
      const qty = Number(chickenItem.quantity || chickenItem.amount || chickenItem.totalQuantity);
      expect(Number.isNaN(qty)).toBe(false);
      expect(qty, `duplicate adds should not double shopping list quantity; expected ${recipePayload.ingredients[0].quantity}, actual ${qty}`).toBe(recipePayload.ingredients[0].quantity);

      // Verify summary is not double-accumulated
      const summary = await http('GET', `/api/meal-plans/summary?week=${encodeURIComponent(addPayload.week)}`);
      expect(summary.res.status).toBe(200);
      expect(summary.body, 'summary response body should exist').toBeTruthy();
      const calories = Number(summary.body.calories || summary.body.totalCalories || summary.body.nutrition?.calories);
      expect(Number.isNaN(calories)).toBe(false);
      expect(calories, `duplicate adds should not double total calories; expected ${recipePayload.nutrition.calories}, actual ${calories}`).toBe(recipePayload.nutrition.calories);
    } finally {
      if (planId) await safeDelete(`/api/meal-plans/${planId}`);
      if (recipeId) {
        await safeDelete(`/api/favorites/${recipeId}`);
        await safeDelete(`/api/recipes/${recipeId}`);
      }
    }
  });
});

import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function http(method, path, body, extraHeaders = {}) {
  const res = await fetch(`${BASE_URL}${path}`, {
    method,
    headers: {
      'Content-Type': 'application/json',
      ...extraHeaders,
    },
    body: body === undefined ? undefined : JSON.stringify(body),
  });

  const text = await res.text();
  let json;
  try {
    json = text ? JSON.parse(text) : null;
  } catch {
    json = text;
  }
  return { res, body: json, text };
}

async function safeDelete(path) {
  try {
    await fetch(`${BASE_URL}${path}`, { method: 'DELETE' });
  } catch {
    // ignore cleanup failures
  }
}

describe('round20_week_share_import_export', () => {
  it('should export a selected week and import only that week with replace/append conflict rules preserved', async () => {
    const uid = `vt-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
    const sourceWeek = '2025-W31';
    const otherWeek = '2025-W32';
    const targetWeek = '2025-W40';

    let recipeAId;
    let recipeBId;
    let recipeCId;
    const createdPlanIds = [];

    try {
      const recipeA = await http('POST', '/api/recipes', {
        title: `Exported Recipe A ${uid}`,
        servings: 1,
        ingredients: [{ name: `Rice ${uid}`, quantity: 100, unit: 'g' }],
        nutrition: { calories: 300, protein: 6, carbs: 60, fat: 2 }
      });
      expect([200, 201]).toContain(recipeA.res.status);
      recipeAId = recipeA.body.id || recipeA.body.recipeId;
      expect(recipeAId).toBeTruthy();

      const recipeB = await http('POST', '/api/recipes', {
        title: `Exported Recipe B ${uid}`,
        servings: 1,
        ingredients: [{ name: `Beans ${uid}`, quantity: 120, unit: 'g' }],
        nutrition: { calories: 260, protein: 14, carbs: 35, fat: 4 }
      });
      expect([200, 201]).toContain(recipeB.res.status);
      recipeBId = recipeB.body.id || recipeB.body.recipeId;
      expect(recipeBId).toBeTruthy();

      const recipeC = await http('POST', '/api/recipes', {
        title: `Existing Target Recipe ${uid}`,
        servings: 1,
        ingredients: [{ name: `Egg ${uid}`, quantity: 2, unit: 'pcs' }],
        nutrition: { calories: 180, protein: 12, carbs: 2, fat: 12 }
      });
      expect([200, 201]).toContain(recipeC.res.status);
      recipeCId = recipeC.body.id || recipeC.body.recipeId;
      expect(recipeCId).toBeTruthy();

      const p1 = await http('POST', '/api/meal-plans', { week: sourceWeek, day: 'monday', mealType: 'breakfast', recipeId: recipeAId });
      expect([200, 201]).toContain(p1.res.status);
      createdPlanIds.push(p1.body.id || p1.body.planId);

      const p2 = await http('POST', '/api/meal-plans', { week: sourceWeek, day: 'tuesday', mealType: 'dinner', recipeId: recipeBId });
      expect([200, 201]).toContain(p2.res.status);
      createdPlanIds.push(p2.body.id || p2.body.planId);

      const pOther = await http('POST', '/api/meal-plans', { week: otherWeek, day: 'wednesday', mealType: 'lunch', recipeId: recipeAId });
      expect([200, 201]).toContain(pOther.res.status);
      createdPlanIds.push(pOther.body.id || pOther.body.planId);

      const exportRes = await http('POST', '/api/shares/export', { week: sourceWeek });
      expect(exportRes.res.status).toBe(200);
      expect(exportRes.body, 'export response should exist').toBeTruthy();
      const exportPayload = exportRes.body.shareData || exportRes.body.data || exportRes.body;
      expect(exportPayload, `export payload should exist, actual: ${JSON.stringify(exportRes.body)}`).toBeTruthy();
      const exportText = JSON.stringify(exportPayload);
      expect(exportText).toContain(sourceWeek);
      expect(exportText).not.toContain(otherWeek);
      expect(exportText).toContain(String(recipeAId));
      expect(exportText).toContain(String(recipeBId));

      const targetExisting = await http('POST', '/api/meal-plans', { week: targetWeek, day: 'monday', mealType: 'breakfast', recipeId: recipeCId });
      expect([200, 201]).toContain(targetExisting.res.status);
      createdPlanIds.push(targetExisting.body.id || targetExisting.body.planId);

      const importReplace = await http('POST', '/api/shares/import', {
        week: targetWeek,
        mode: 'replace',
        data: exportPayload
      });
      expect([200, 201]).toContain(importReplace.res.status);
      expect(importReplace.body, 'replace import response body should exist').toBeTruthy();
      expect(JSON.stringify(importReplace.body).toLowerCase()).toMatch(/replace|import|success/);

      const targetAfterReplace = await http('GET', `/api/meal-plans?week=${encodeURIComponent(targetWeek)}`);
      expect(targetAfterReplace.res.status).toBe(200);
      const replaceItems = Array.isArray(targetAfterReplace.body)
        ? targetAfterReplace.body
        : Array.isArray(targetAfterReplace.body.items)
          ? targetAfterReplace.body.items
          : targetAfterReplace.body.data;
      expect(Array.isArray(replaceItems)).toBe(true);
      expect(replaceItems.length, `replace import should restore exactly exported week items; actual items: ${JSON.stringify(replaceItems)}`).toBe(2);
      expect(replaceItems.some((i) => (i.recipeId || i.recipe?.id) === recipeAId)).toBe(true);
      expect(replaceItems.some((i) => (i.recipeId || i.recipe?.id) === recipeBId)).toBe(true);
      expect(replaceItems.some((i) => (i.recipeId || i.recipe?.id) === recipeCId)).toBe(false);

      const shoppingAfterReplace = await http('GET', `/api/shopping-list?week=${encodeURIComponent(targetWeek)}`);
      expect(shoppingAfterReplace.res.status).toBe(200);
      const shoppingText = JSON.stringify(shoppingAfterReplace.body);
      expect(shoppingText).toContain(uid);
      expect(shoppingText).toContain('Rice');
      expect(shoppingText).toContain('Beans');

      const restoreConflict = await http('POST', '/api/meal-plans', { week: targetWeek, day: 'monday', mealType: 'breakfast', recipeId: recipeCId });
      expect([200, 201, 409]).toContain(restoreConflict.res.status);
      if ([200, 201].includes(restoreConflict.res.status)) {
        createdPlanIds.push(restoreConflict.body.id || restoreConflict.body.planId);
      }

      const importAppend = await http('POST', '/api/shares/import', {
        week: targetWeek,
        mode: 'append',
        data: exportPayload
      });
      expect([200, 201]).toContain(importAppend.res.status);
      expect(importAppend.body, 'append import response body should exist').toBeTruthy();
      const appendText = JSON.stringify(importAppend.body).toLowerCase();
      expect(appendText, `append import should describe conflict/kept/or appended result, actual: ${JSON.stringify(importAppend.body)}`).toMatch(/append|conflict|kept|skipped|imported/);

      const targetAfterAppend = await http('GET', `/api/meal-plans?week=${encodeURIComponent(targetWeek)}`);
      expect(targetAfterAppend.res.status).toBe(200);
      const appendItems = Array.isArray(targetAfterAppend.body)
        ? targetAfterAppend.body
        : Array.isArray(targetAfterAppend.body.items)
          ? targetAfterAppend.body.items
          : targetAfterAppend.body.data;
      expect(Array.isArray(appendItems)).toBe(true);

      const mondayBreakfast = appendItems.filter((i) => (i.day || i.slot?.day) === 'monday' && (i.mealType || i.slot?.mealType) === 'breakfast');
      expect(mondayBreakfast.length, `append import should preserve original conflict item and avoid overwriting existing content; actual: ${JSON.stringify(mondayBreakfast)}`).toBe(1);
      expect((mondayBreakfast[0].recipeId || mondayBreakfast[0].recipe?.id)).toBe(recipeCId);

      const importedTuesdayDinner = appendItems.find((i) => (i.day || i.slot?.day) === 'tuesday' && (i.mealType || i.slot?.mealType) === 'dinner');
      expect(importedTuesdayDinner, `append import should fill empty target slot for tuesday dinner; actual items: ${JSON.stringify(appendItems)}`).toBeTruthy();
      expect(importedTuesdayDinner.recipeId || importedTuesdayDinner.recipe?.id).toBe(recipeBId);
    } finally {
      for (const id of createdPlanIds.filter(Boolean)) {
        await safeDelete(`/api/meal-plans/${id}`);
      }
      if (recipeAId) await safeDelete(`/api/recipes/${recipeAId}`);
      if (recipeBId) await safeDelete(`/api/recipes/${recipeBId}`);
      if (recipeCId) await safeDelete(`/api/recipes/${recipeCId}`);
    }
  });
});

