describe('round21_end_to_end_behavior_unchanged', () => {
  it('should preserve cross-feature invariants: week isolation, deleting plan does not remove favorite, archive restores settings, and share excludes favorites/recent searches', async () => {
    const uid = `vt-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
    const weekA = '2025-W33';
    const weekB = '2025-W34';
    let recipeId;
    let planAId;
    let planBId;
    let favoriteId;

    try {
      const createRecipe = await http('POST', '/api/recipes', {
        title: `Invariant Recipe ${uid}`,
        servings: 2,
        ingredients: [{ name: `Tomato ${uid}`, quantity: 2, unit: 'pcs' }],
        nutrition: { calories: 220, protein: 8, carbs: 20, fat: 10 }
      });
      expect([200, 201]).toContain(createRecipe.res.status);
      recipeId = createRecipe.body.id || createRecipe.body.recipeId;
      expect(recipeId).toBeTruthy();

      const fav = await http('POST', '/api/favorites', { recipeId });
      expect([200, 201]).toContain(fav.res.status);
      favoriteId = fav.body.id || fav.body.favoriteId || recipeId;
      expect(fav.body.recipeId || fav.body.recipe?.id || recipeId).toBe(recipeId);

      const recentSearch = await http('POST', '/api/search/history', { keyword: `keto-${uid}` });
      expect([200, 201, 204]).toContain(recentSearch.res.status);

      const pA = await http('POST', '/api/meal-plans', { week: weekA, day: 'friday', mealType: 'dinner', recipeId });
      expect([200, 201]).toContain(pA.res.status);
      planAId = pA.body.id || pA.body.planId;
      expect(planAId).toBeTruthy();

      const pB = await http('POST', '/api/meal-plans', { week: weekB, day: 'friday', mealType: 'dinner', recipeId });
      expect([200, 201]).toContain(pB.res.status);
      planBId = pB.body.id || pB.body.planId;
      expect(planBId).toBeTruthy();

      const deleteWeekAPlan = await fetch(`${BASE_URL}/api/meal-plans/${planAId}`, { method: 'DELETE' });
      expect([200, 204]).toContain(deleteWeekAPlan.status);

      const favoritesAfterDelete = await http('GET', '/api/favorites');
      expect(favoritesAfterDelete.res.status).toBe(200);
      const favoriteItems = Array.isArray(favoritesAfterDelete.body)
        ? favoritesAfterDelete.body
        : Array.isArray(favoritesAfterDelete.body.items)
          ? favoritesAfterDelete.body.items
          : favoritesAfterDelete.body.data;
      expect(Array.isArray(favoriteItems)).toBe(true);
      expect(
        favoriteItems.some((item) => (item.recipeId || item.recipe?.id) === recipeId),
        `deleting meal plan must not remove favorite for recipe ${recipeId}; actual favorites: ${JSON.stringify(favoriteItems)}`
      ).toBe(true);

      const weekBPlans = await http('GET', `/api/meal-plans?week=${encodeURIComponent(weekB)}`);
      expect(weekBPlans.res.status).toBe(200);
      const weekBItems = Array.isArray(weekBPlans.body)
        ? weekBPlans.body
        : Array.isArray(weekBPlans.body.items)
          ? weekBPlans.body.items
          : weekBPlans.body.data;
      expect(Array.isArray(weekBItems)).toBe(true);
      expect(
        weekBItems.some((item) => (item.id || item.planId) === planBId || (item.recipeId || item.recipe?.id) === recipeId),
        `week ${weekB} should remain isolated and retain its plan after deleting week ${weekA}; actual: ${JSON.stringify(weekBItems)}`
      ).toBe(true);

      const setSettings = await http('PUT', '/api/settings', {
        units: 'metric',
        calorieTarget: 1850,
        theme: 'dark',
        planningCycles: 2
      });
      expect([200, 204]).toContain(setSettings.res.status);

      const exportArchive = await http('POST', '/api/archive/export', {});
      expect(exportArchive.res.status).toBe(200);
      const archivePayload = exportArchive.body.archive || exportArchive.body.data || exportArchive.body;
      expect(archivePayload, `archive export should return payload, actual: ${JSON.stringify(exportArchive.body)}`).toBeTruthy();

      const mutateSettings = await http('PUT', '/api/settings', {
        units: 'imperial',
        calorieTarget: 2400,
        theme: 'light',
        planningCycles: 1
      });
      expect([200, 204]).toContain(mutateSettings.res.status);

      const importArchive = await http('POST', '/api/archive/import', { data: archivePayload });
      expect([200, 201]).toContain(importArchive.res.status);
      expect(importArchive.body, 'archive import should return body').toBeTruthy();

      const restoredSettings = await http('GET', '/api/settings');
      expect(restoredSettings.res.status).toBe(200);
      expect(restoredSettings.body.units, `restored units should be metric, actual: ${JSON.stringify(restoredSettings.body)}`).toBe('metric');
      expect(restoredSettings.body.calorieTarget, `restored calorieTarget should be 1850, actual: ${JSON.stringify(restoredSettings.body)}`).toBe(1850);
      expect(restoredSettings.body.theme, `restored theme should be dark, actual: ${JSON.stringify(restoredSettings.body)}`).toBe('dark');

      const shareExport = await http('POST', '/api/shares/export', { week: weekB });
      expect(shareExport.res.status).toBe(200);
      const sharePayload = shareExport.body.shareData || shareExport.body.data || shareExport.body;
      const shareText = JSON.stringify(sharePayload);
      expect(shareText).toContain(weekB);
      expect(shareText).not.toContain('favorites');
      expect(shareText).not.toContain('recentSearch');
      expect(shareText).not.toContain(`keto-${uid}`);
    } finally {
      if (planBId) await safeDelete(`/api/meal-plans/${planBId}`);
      if (favoriteId) await safeDelete(`/api/favorites/${favoriteId}`);
      if (recipeId) await safeDelete(`/api/recipes/${recipeId}`);
    }
  });
});

