describe('round22_import_errors_and_regression_guard', () => {
  it('should return distinct import errors, keep current data/state on failure, handle long text, and preserve regression-sensitive behaviors', async () => {
    const uid = `vt-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
    const currentWeekId = 'current';
    const nextWeekId = 'next';
    let recipeId;
    let longRecipeId;

    try {
      // Create a recipe for regression tests
      const recipe = await http('POST', '/api/recipes', {
        title: `Regression Guard Recipe ${uid}`,
        servings: 1,
        ingredients: [{ name: `Oats ${uid}`, quantity: 80, unit: 'g', amount: 80 }],
        steps: ['cook'],
        nutrition: { calories: 280, protein: 10, carbs: 45, fat: 5 }
      });
      expect([200, 201]).toContain(recipe.res.status);
      recipeId = recipe.body.id || recipe.body.recipeId;
      expect(recipeId).toBeTruthy();

      // Create a recipe with super long title to test long text handling
      const longTitle = `Long Recipe ${'A'.repeat(500)} ${uid}`;
      const longRecipe = await http('POST', '/api/recipes', {
        title: longTitle,
        servings: 1,
        ingredients: [{ name: `Ingredient ${'B'.repeat(300)} ${uid}`, quantity: 50, unit: 'g', amount: 50 }],
        steps: ['cook'],
        nutrition: { calories: 100, protein: 5, carbs: 10, fat: 2 }
      });
      expect([200, 201]).toContain(longRecipe.res.status);
      longRecipeId = longRecipe.body.id || longRecipe.body.recipeId;
      expect(longRecipeId).toBeTruthy();
      // Verify long text is stored and returned without truncation
      const fetchLongRecipe = await http('GET', `/api/recipes/${longRecipeId}`);
      expect(fetchLongRecipe.res.status).toBe(200);
      const returnedTitle = fetchLongRecipe.body.title || fetchLongRecipe.body.name;
      expect(returnedTitle, 'Long title should be stored and returned fully').toContain('A'.repeat(100));

      // Set up meal plans in two different week periods
      const p1 = await http('POST', `/api/meal-plans/${currentWeekId}/days/sunday/meals/breakfast`, { recipeId });
      expect([200, 201]).toContain(p1.res.status);

      const p2 = await http('POST', `/api/meal-plans/${nextWeekId}/days/saturday/meals/lunch`, { recipeId });
      expect([200, 201]).toContain(p2.res.status);

      // Capture baselines
      const baselineCurrentPlan = await http('GET', `/api/meal-plans/${currentWeekId}`);
      expect(baselineCurrentPlan.res.status).toBe(200);
      expect(JSON.stringify(baselineCurrentPlan.body)).toContain(String(recipeId));

      const baselineNextPlan = await http('GET', `/api/meal-plans/${nextWeekId}`);
      expect(baselineNextPlan.res.status).toBe(200);
      expect(JSON.stringify(baselineNextPlan.body)).toContain(String(recipeId));

      // --- Error scenario 1: Oversized import ---
      const oversizedImport = await http('POST', '/api/backup/import', {
        data: 'X'.repeat(2 * 1024 * 1024)
      });
      expect([400, 413]).toContain(oversizedImport.res.status);
      const oversizedMsg = JSON.stringify(oversizedImport.body).toLowerCase();
      expect(oversizedMsg, `oversized import should indicate size-related error, actual: ${oversizedMsg}`).toMatch(/large|size|too big|payload|exceed|过大/);

      // --- Error scenario 2: Incomplete/corrupt content ---
      const incompleteImport = await http('POST', '/api/backup/import', {
        version: 2, mealPlans: [{}]
      });
      expect([400, 422]).toContain(incompleteImport.res.status);
      const incompleteMsg = JSON.stringify(incompleteImport.body).toLowerCase();
      expect(incompleteMsg, `incomplete import should indicate invalid/incomplete/corrupt format, actual: ${incompleteMsg}`).toMatch(/invalid|incomplete|corrupt|missing|残缺/);

      // --- Error scenario 3: Unsupported version ---
      const unsupportedVersionImport = await http('POST', '/api/backup/import', {
        version: 9999, mealPlans: [], settings: {}
      });
      expect([400, 422]).toContain(unsupportedVersionImport.res.status);
      const unsupportedMsg = JSON.stringify(unsupportedVersionImport.body).toLowerCase();
      expect(unsupportedMsg, `unsupported version import should indicate version issue, actual: ${unsupportedMsg}`).toMatch(/version|unsupported|不支持/);

      // --- Cross-assert: all three error messages are DISTINCT ---
      expect(oversizedMsg).not.toBe(incompleteMsg);
      expect(oversizedMsg).not.toBe(unsupportedMsg);
      expect(incompleteMsg).not.toBe(unsupportedMsg);

      // --- Verify data preservation after import failures ---
      // Current week meal plan preserved
      const currentAfterFailures = await http('GET', `/api/meal-plans/${currentWeekId}`);
      expect(currentAfterFailures.res.status).toBe(200);
      expect(JSON.stringify(currentAfterFailures.body), 'failed imports must not mutate existing current week meal plan data').toContain(String(recipeId));

      // Next week meal plan preserved
      const nextAfterFailures = await http('GET', `/api/meal-plans/${nextWeekId}`);
      expect(nextAfterFailures.res.status).toBe(200);
      expect(JSON.stringify(nextAfterFailures.body), 'failed imports must not mutate existing next week meal plan data').toContain(String(recipeId));

      // --- Regression: old archive compatibility ---
      // Old format: flat mealPlans without current/next period concept
      const legacyCompatibleImport = await http('POST', '/api/backup/import', {
        version: 1,
        settings: { units: 'metric' },
        mealPlans: {
          wednesday: { lunch: [{ recipeId }] }
        }
      });
      expect([200, 201]).toContain(legacyCompatibleImport.res.status);

      // Verify legacy data was actually imported into current week
      const currentAfterLegacy = await http('GET', `/api/meal-plans/${currentWeekId}`);
      expect(currentAfterLegacy.res.status).toBe(200);
      const currentData = currentAfterLegacy.body;
      const currentDays = currentData.days || currentData.week || currentData;
      const wednesdayData = currentDays.wednesday || currentDays['wednesday'] || (Array.isArray(currentDays) ? currentDays.find((d) => d.day === 'wednesday') : null);
      expect(wednesdayData, 'wednesday should exist in current week after legacy import').toBeTruthy();
      const wedLunch = wednesdayData.lunch || wednesdayData.meals?.lunch || [];
      const wedLunchArr = Array.isArray(wedLunch) ? wedLunch : [wedLunch].filter(Boolean);
      expect(wedLunchArr.some((item) => String(item.recipeId || item.id) === String(recipeId)),
        `legacy import should place wednesday lunch recipe in current week, got: ${JSON.stringify(wedLunch)}`).toBe(true);

      // --- Regression: unified duplicate-add rule still enforced ---
      // Try to add the same recipe to the same slot again
      const duplicatePlanAttempt = await http('POST', `/api/meal-plans/${currentWeekId}/days/sunday/meals/breakfast`, { recipeId });
      // Should be rejected (409) or at least acknowledged (200 with conflict info)
      if (duplicatePlanAttempt.res.status === 409) {
        const dupMsg = JSON.stringify(duplicatePlanAttempt.body).toLowerCase();
        expect(dupMsg).toMatch(/duplicate|already|exists|conflict|重复|已存在/);
      } else {
        // If 200, the system may have silently handled it, but at minimum check data wasn't double-added
        expect([200, 409]).toContain(duplicatePlanAttempt.res.status);
      }

      // --- Regression: dual-week isolation ---
      // Verify current and next week data are independent
      const isolatedCurrent = await http('GET', `/api/meal-plans/${currentWeekId}`);
      expect(isolatedCurrent.res.status).toBe(200);
      const isolatedNext = await http('GET', `/api/meal-plans/${nextWeekId}`);
      expect(isolatedNext.res.status).toBe(200);
      // Both should have recipeId but in different day/meal slots
      expect(JSON.stringify(isolatedCurrent.body)).toContain(String(recipeId));
      expect(JSON.stringify(isolatedNext.body)).toContain(String(recipeId));

      // === Extreme empty state: fresh user with no data should get step-by-step guidance ===
      // We test the dashboard/overview endpoint for guidance indicators
      const dashboardRes = await http('GET', '/api/dashboard');
      if (dashboardRes.res.status === 200) {
        // If the dashboard endpoint exists, check for guidance fields
        const dashText = JSON.stringify(dashboardRes.body).toLowerCase();
        // The dashboard response should have guidance/onboarding fields when sections have no data
        const hasGuidanceField = dashboardRes.body.guidance || dashboardRes.body.onboarding || dashboardRes.body.steps || dashText.match(/guide|引导|开始|step|onboard/);
        // This is a soft check since our test user has data; just verify the endpoint exists and responds
        expect(dashboardRes.body).toBeTruthy();
      }
      // Also try the home/overview endpoint
      const homeRes = await http('GET', '/api/overview');
      if (homeRes.res.status === 200) {
        expect(homeRes.body).toBeTruthy();
      }

    } finally {
      // Cleanup meal plan entries
      try { await http('DELETE', `/api/meal-plans/${currentWeekId}/days/sunday/meals/breakfast/${recipeId}`); } catch {}
      try { await http('DELETE', `/api/meal-plans/${nextWeekId}/days/saturday/meals/lunch/${recipeId}`); } catch {}
      try { await http('DELETE', `/api/meal-plans/${currentWeekId}/days/wednesday/meals/lunch/${recipeId}`); } catch {}
      try { await http('DELETE', `/api/meal-plans/${currentWeekId}/days/sunday/meals/breakfast`); } catch {}
      try { await http('DELETE', `/api/meal-plans/${nextWeekId}/days/saturday/meals/lunch`); } catch {}
      try { await http('DELETE', `/api/meal-plans/${currentWeekId}/days/wednesday/meals/lunch`); } catch {}
      if (longRecipeId) await safeDelete(`/api/recipes/${longRecipeId}`);
      if (recipeId) await safeDelete(`/api/recipes/${recipeId}`);
    }
  });
});

import { describe, it, expect, beforeAll, afterAll } from 'vitest';
import { chromium, Browser, Page } from 'playwright';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

describe('invalid_project_name_rejected', () => {
  let browser: Browser;
  let page: Page;

  beforeAll(async () => {
    browser = await chromium.launch();
  });

  afterAll(async () => {
    await browser?.close();
  });

  async function openFreshPage(): Promise<Page> {
    const ctx = await browser.newContext();
    const p = await ctx.newPage();
    await p.goto(BASE_URL, { waitUntil: 'networkidle' });
    return p;
  }

  async function findCreateProjectTrigger(p: Page) {
    // Try common selectors/text for a "new project" or "create project" button
    const selectors = [
      'button:has-text("新建")',
      'button:has-text("新建项目")',
      'button:has-text("创建项目")',
      'button:has-text("Create")',
      'button:has-text("New")',
      'button:has-text("New Project")',
      '[data-testid="create-project"]',
      '[data-testid="new-project"]',
      'button:has-text("新增项目")',
      'a:has-text("新建")',
      'a:has-text("新建项目")',
      ':text("新建"):visible',
      ':text("创建"):visible',
    ];
    for (const sel of selectors) {
      try {
        const el = p.locator(sel).first();
        if (await el.isVisible({ timeout: 1000 })) {
          return el;
        }
      } catch { /* continue */ }
    }
    return null;
  }

  async function findProjectNameInput(p: Page) {
    const selectors = [
      'input[placeholder*="项目名"]',
      'input[placeholder*="project"]',
      'input[placeholder*="Project"]',
      'input[placeholder*="名称"]',
      '[data-testid="project-name-input"]',
      'input[type="text"]',
      'dialog input',
      '.modal input',
    ];
    for (const sel of selectors) {
      try {
        const el = p.locator(sel).first();
        if (await el.isVisible({ timeout: 1000 })) {
          return el;
        }
      } catch { /* continue */ }
    }
    return null;
  }

  async function findConfirmButton(p: Page) {
    const selectors = [
      'button:has-text("确定")',
      'button:has-text("确认")',
      'button:has-text("OK")',
      'button:has-text("Create")',
      'button:has-text("创建")',
      'button:has-text("Submit")',
      'button:has-text("保存")',
      'button[type="submit"]',
    ];
    for (const sel of selectors) {
      try {
        const el = p.locator(sel).first();
        if (await el.isVisible({ timeout: 1000 })) {
          return el;
        }
      } catch { /* continue */ }
    }
    return null;
  }

  async function getVisibleErrorText(p: Page): Promise<string> {
    // Look for error/warning messages
    const errorSelectors = [
      '.error', '.error-message', '.err-msg',
      '[class*="error"]', '[class*="Error"]',
      '[class*="warning"]', '[class*="Warning"]',
      '[role="alert"]',
      '.ant-form-item-explain-error',
      '.validation-error',
      '.invalid-feedback',
      ':text("不合法")',
      ':text("不能为空")',
      ':text("超过")',
      ':text("too long")',
      ':text("invalid")',
      ':text("required")',
    ];
    for (const sel of errorSelectors) {
      try {
        const el = p.locator(sel).first();
        if (await el.isVisible({ timeout: 500 })) {
          return await el.textContent() || '';
        }
      } catch { /* continue */ }
    }
    return '';
  }

  async function attemptCreateProject(p: Page, name: string): Promise<{ errorVisible: boolean; errorText: string }> {
    const trigger = await findCreateProjectTrigger(p);
    if (trigger) {
      await trigger.click();
      await p.waitForTimeout(500);
    }

    const input = await findProjectNameInput(p);
    if (input) {
      await input.fill(name);
      await p.waitForTimeout(200);
    }

    const confirm = await findConfirmButton(p);
    if (confirm) {
      // Check if button is disabled
      const disabled = await confirm.isDisabled();
      if (disabled) {
        const errorText = await getVisibleErrorText(p);
        return { errorVisible: true, errorText: errorText || 'button-disabled' };
      }
      await confirm.click();
      await p.waitForTimeout(500);
    } else if (input) {
      await input.press('Enter');
      await p.waitForTimeout(500);
    }

    const errorText = await getVisibleErrorText(p);
    return { errorVisible: errorText.length > 0, errorText };
  }

  it('should load the application successfully', async () => {
    page = await openFreshPage();
    const title = await page.title();
    expect(title).toBeTruthy();
    const rootEl = page.locator('#root, #app, [id*="root"], [id*="app"]').first();
    await expect(rootEl).toBeAttached();
    await page.close();
  });

  it('should reject empty project name', async () => {
    page = await openFreshPage();
    const bodyTextBefore = await page.locator('body').textContent();

    const result = await attemptCreateProject(page, '');

    // Either an error is shown, or the project was not created
    // We check that the UI indicates rejection
    const bodyTextAfter = await page.locator('body').textContent();
    const hasError = result.errorVisible;
    // Alternatively, project name area should not show an empty-named project as valid
    const noNewProjectCreated = !bodyTextAfter?.includes('Untitled') || bodyTextBefore === bodyTextAfter;

    expect(hasError || noNewProjectCreated).toBe(true);
    await page.close();
  });

  it('should reject all-whitespace project name', async () => {
    page = await openFreshPage();

    const result = await attemptCreateProject(page, '     ');

    const bodyText = await page.locator('body').textContent();
    const hasError = result.errorVisible;
    // A purely whitespace name should not appear as a valid project name in the header
    const noWhitespaceProject = !bodyText?.includes('     ');

    expect(hasError || noWhitespaceProject).toBe(true);
    await page.close();
  });

  it('should reject project name exceeding 40 characters', async () => {
    page = await openFreshPage();
    const longName = 'A'.repeat(41);

    const result = await attemptCreateProject(page, longName);

    const bodyText = await page.locator('body').textContent();
    const hasError = result.errorVisible;
    // The 41-char name should not appear as the current project name
    const noLongProject = !bodyText?.includes(longName);

    expect(hasError || noLongProject).toBe(true);
    await page.close();
  });

  it('should accept a valid project name within 40 characters', async () => {
    page = await openFreshPage();
    const validName = 'TestProject_' + Date.now().toString().slice(-6);

    await attemptCreateProject(page, validName);

    // The valid project name should appear somewhere in the page (e.g., header)
    const bodyText = await page.locator('body').textContent();
    expect(bodyText).toContain(validName);
    await page.close();
  });
});

import { describe, it, expect, beforeAll, afterAll } from 'vitest';
import { chromium, Browser, Page, BrowserContext } from 'playwright';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

describe('project_state_persist_after_refresh', () => {
  let browser: Browser;

  beforeAll(async () => {
    browser = await chromium.launch();
  });

  afterAll(async () => {
    await browser?.close();
  });

  async function findAndClickElement(p: Page, textPatterns: string[]): Promise<boolean> {
    for (const pattern of textPatterns) {
      try {
        const el = p.locator(`text=${pattern}`).first();
        if (await el.isVisible({ timeout: 1000 })) {
          await el.click();
          await p.waitForTimeout(500);
          return true;
        }
      } catch { /* continue */ }
    }
    // Try button variants
    for (const pattern of textPatterns) {
      try {
        const el = p.locator(`button:has-text("${pattern}")`).first();
        if (await el.isVisible({ timeout: 500 })) {
          await el.click();
          await p.waitForTimeout(500);
          return true;
        }
      } catch { /* continue */ }
    }
    return false;
  }

  async function findProjectNameInput(p: Page) {
    const selectors = [
      'input[placeholder*="项目"]', 'input[placeholder*="project"]',
      'input[placeholder*="Project"]', 'input[placeholder*="名称"]',
      '[data-testid="project-name-input"]', 'dialog input', '.modal input',
      'input[type="text"]',
    ];
    for (const sel of selectors) {
      try {
        const el = p.locator(sel).first();
        if (await el.isVisible({ timeout: 800 })) return el;
      } catch { /* continue */ }
    }
    return null;
  }

  async function clickConfirm(p: Page) {
    const patterns = ['确定', '确认', 'OK', 'Create', '创建', 'Submit', '保存'];
    for (const pat of patterns) {
      try {
        const btn = p.locator(`button:has-text("${pat}")`).first();
        if (await btn.isVisible({ timeout: 500 })) {
          await btn.click();
          await p.waitForTimeout(500);
          return;
        }
      } catch { /* continue */ }
    }
    // try pressing Enter on the input
    const input = await findProjectNameInput(p);
    if (input) await input.press('Enter');
  }

  it('should persist a newly created blank project after page refresh', async () => {
    const ctx = await browser.newContext();
    const page = await ctx.newPage();
    await page.goto(BASE_URL, { waitUntil: 'networkidle' });

    const projectName = 'PersistTest_' + Date.now().toString().slice(-6);

    // Try to create a new project
    await findAndClickElement(page, ['新建', '新建项目', '创建项目', 'New', 'Create', 'New Project']);
    await page.waitForTimeout(500);

    const input = await findProjectNameInput(page);
    if (input) {
      await input.fill(projectName);
      await page.waitForTimeout(200);
    }
    await clickConfirm(page);
    await page.waitForTimeout(500);

    // Verify project name is visible before refresh
    let bodyText = await page.locator('body').textContent();
    const projectCreated = bodyText?.includes(projectName);

    // Refresh the page
    await page.reload({ waitUntil: 'networkidle' });
    await page.waitForTimeout(1000);

    // After refresh, the project state should be preserved
    bodyText = await page.locator('body').textContent();

    if (projectCreated) {
      // If we successfully created a named project, it should persist
      expect(bodyText).toContain(projectName);
    } else {
      // Even if we couldn't find the create flow, the app should at least
      // maintain some consistent state across refresh
      expect(bodyText!.length).toBeGreaterThan(0);
    }

    await page.close();
    await ctx.close();
  });

  it('should persist sample project state after refresh', async () => {
    const ctx = await browser.newContext();
    const page = await ctx.newPage();
    await page.goto(BASE_URL, { waitUntil: 'networkidle' });

    // Switch to sample/example project
    const clicked = await findAndClickElement(page, [
      '示例项目', '示例', 'Sample', 'Example', 'Demo',
      'sample project', 'example project', '加载示例',
    ]);

    await page.waitForTimeout(800);

    // Capture state after switching to sample project
    const bodyTextBefore = await page.locator('body').textContent() || '';

    // Refresh the page
    await page.reload({ waitUntil: 'networkidle' });
    await page.waitForTimeout(1000);

    const bodyTextAfter = await page.locator('body').textContent() || '';

    if (clicked) {
      // The page should still show sample/example project content after refresh
      // At minimum, it should not revert to empty/initial state if sample was loaded
      // Check that some meaningful content survived the refresh
      expect(bodyTextAfter.length).toBeGreaterThan(50);

      // If the sample project had identifiable content, it should still be there
      // Look for sample-related text in both snapshots
      const sampleIndicators = ['示例', 'Sample', 'Example', 'Demo', 'User', 'Order', 'Product'];
      const hadSampleBefore = sampleIndicators.some(ind => bodyTextBefore.includes(ind));
      const hasSampleAfter = sampleIndicators.some(ind => bodyTextAfter.includes(ind));

      if (hadSampleBefore) {
        expect(hasSampleAfter).toBe(true);
      }
    } else {
      // If sample button not found, at least verify app loads consistently
      expect(bodyTextAfter.length).toBeGreaterThan(0);
    }

    await page.close();
    await ctx.close();
  });

  it('should not revert to initial skeleton state after refresh when project was active', async () => {
    const ctx = await browser.newContext();
    const page = await ctx.newPage();
    await page.goto(BASE_URL, { waitUntil: 'networkidle' });

    // Get initial state
    const initialBody = await page.locator('body').textContent() || '';

    // Perform some action to change state (try creating project or loading sample)
    const projName = 'RefreshCheck_' + Date.now().toString().slice(-5);
    await findAndClickElement(page, ['新建', '新建项目', 'New', 'Create']);
    await page.waitForTimeout(300);
    const input = await findProjectNameInput(page);
    if (input) {
      await input.fill(projName);
      await page.waitForTimeout(200);
    }
    await clickConfirm(page);
    await page.waitForTimeout(500);

    const afterActionBody = await page.locator('body').textContent() || '';
    const stateChanged = afterActionBody !== initialBody || afterActionBody.includes(projName);

    // Refresh
    await page.reload({ waitUntil: 'networkidle' });
    await page.waitForTimeout(1000);

    const afterRefreshBody = await page.locator('body').textContent() || '';

    if (stateChanged) {
      // After refresh, should not revert to the exact initial skeleton
      // The current project state should be maintained
      if (afterActionBody.includes(projName)) {
        expect(afterRefreshBody).toContain(projName);
      }
    }

    // App should always load something meaningful
    expect(afterRefreshBody.length).toBeGreaterThan(0);

    await page.close();
    await ctx.close();
  });
});

import { describe, it, expect, beforeAll, afterAll, beforeEach } from 'vitest';
import { chromium, Browser, Page, BrowserContext } from 'playwright';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

describe('entity_crud_and_name_constraints', () => {
  let browser: Browser;
  let context: BrowserContext;
  let page: Page;

  beforeAll(async () => {
    browser = await chromium.launch();
  });

  afterAll(async () => {
    await browser?.close();
  });

  beforeEach(async () => {
    context = await browser.newContext();
    page = await context.newPage();
    await page.goto(BASE_URL, { waitUntil: 'networkidle' });
    await page.waitForTimeout(500);
  });

  async function findAndClick(p: Page, patterns: string[]): Promise<boolean> {
    for (const pattern of patterns) {
      try {
        // Try button first
        let el = p.locator(`button:has-text("${pattern}")`).first();
        if (await el.isVisible({ timeout: 800 })) {
          await el.click();
          await p.waitForTimeout(400);
          return true;
        }
      } catch { /* continue */ }
      try {
        let el = p.locator(`text=${pattern}`).first();
        if (await el.isVisible({ timeout: 500 })) {
          await el.click();
          await p.waitForTimeout(400);
          return true;
        }
      } catch { /* continue */ }
      try {
        let el = p.locator(`a:has-text("${pattern}")`).first();
        if (await el.isVisible({ timeout: 500 })) {
          await el.click();
          await p.waitForTimeout(400);
          return true;
        }
      } catch { /* continue */ }
    }
    return false;
  }

  async function findInput(p: Page, hints: string[] = []): Promise<any> {
    const selectors = [
      ...hints.map(h => `input[placeholder*="${h}"]`),
      '[data-testid*="entity"] input',
      'dialog input', '.modal input',
      'input[type="text"]',
    ];
    for (const sel of selectors) {
      try {
        const el = p.locator(sel).first();
        if (await el.isVisible({ timeout: 800 })) return el;
      } catch { /* continue */ }
    }
    return null;
  }

  async function confirmAction(p: Page) {
    const patterns = ['确定', '确认', 'OK', 'Create', '创建', 'Submit', '保存', 'Add', '添加'];
    for (const pat of patterns) {
      try {
        const btn = p.locator(`button:has-text("${pat}")`).first();
        if (await btn.isVisible({ timeout: 500 })) {
          await btn.click();
          await p.waitForTimeout(400);
          return true;
        }
      } catch { /* continue */ }
    }
    return false;
  }

  async function getBodyText(p: Page): Promise<string> {
    return await p.locator('body').textContent() || '';
  }

  async function hasVisibleError(p: Page): Promise<boolean> {
    const errorSelectors = [
      '[class*="error"]', '[class*="Error"]',
      '[role="alert"]', '.ant-form-item-explain-error',
      '.validation-error', '.invalid-feedback',
      '[class*="warning"]', '[class*="Warning"]',
      '[class*="danger"]',
    ];
    for (const sel of errorSelectors) {
      try {
        const el = p.locator(sel).first();
        if (await el.isVisible({ timeout: 500 })) return true;
      } catch { /* continue */ }
    }
    // Also check for common error text patterns
    const body = await getBodyText(p);
    const errorPhrases = ['不能为空', '已存在', '重复', '超过', '不合法', 'invalid', 'already exist', 'too long', 'required', 'duplicate'];
    return errorPhrases.some(phrase => body.toLowerCase().includes(phrase.toLowerCase()));
  }

  async function createEntity(p: Page, name: string): Promise<boolean> {
    await findAndClick(p, ['新增实体', '添加实体', '新建实体', 'Add Entity', 'New Entity', 'Create Entity', '新增', 'Add']);
    await p.waitForTimeout(300);

    const input = await findInput(p, ['实体', 'entity', 'Entity', '名称', 'name']);
    if (input) {
      await input.fill(name);
      await p.waitForTimeout(200);
    }

    const confirmed = await confirmAction(p);
    if (!confirmed && input) {
      await input.press('Enter');
      await p.waitForTimeout(400);
    }
