import { describe, it, expect, beforeAll, afterAll, beforeEach } from 'vitest';
import { chromium, Browser, Page, BrowserContext } from 'playwright';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

describe('field_crud_type_and_name_validation', () => {
  let browser: Browser;
  let context: BrowserContext;
  let page: Page;

  beforeAll(async () => {
    browser = await chromium.launch();
  });

  afterAll(async () => {
    await browser?.close();
  });

  beforeEach(async () => {
    context = await browser.newContext();
    page = await context.newPage();
    await page.goto(BASE_URL, { waitUntil: 'networkidle' });
    await page.waitForTimeout(500);
  });

  async function findAndClick(p: Page, patterns: string[]): Promise<boolean> {
    for (const pattern of patterns) {
      try {
        let el = p.locator(`button:has-text("${pattern}")`).first();
        if (await el.isVisible({ timeout: 800 })) {
          await el.click();
          await p.waitForTimeout(400);
          return true;
        }
      } catch { /* continue */ }
      try {
        let el = p.locator(`text=${pattern}`).first();
        if (await el.isVisible({ timeout: 500 })) {
          await el.click();
          await p.waitForTimeout(400);
          return true;
        }
      } catch { /* continue */ }
    }
    return false;
  }

  async function findInput(p: Page, hints: string[] = []): Promise<any> {
    const selectors = [
      ...hints.map(h => `input[placeholder*="${h}"]`),
      'dialog input', '.modal input',
      'input[type="text"]',
    ];
    for (const sel of selectors) {
      try {
        const el = p.locator(sel).first();
        if (await el.isVisible({ timeout: 800 })) return el;
      } catch { /* continue */ }
    }
    return null;
  }

  async function confirmAction(p: Page): Promise<boolean> {
    const patterns = ['确定', '确认', 'OK', 'Create', '创建', 'Submit', '保存', 'Add', '添加'];
    for (const pat of patterns) {
      try {
        const btn = p.locator(`button:has-text("${pat}")`).first();
        if (await btn.isVisible({ timeout: 500 })) {
          await btn.click();
          await p.waitForTimeout(400);
          return true;
        }
      } catch { /* continue */ }
    }
    return false;
  }

  async function getBodyText(p: Page): Promise<string> {
    return await p.locator('body').textContent() || '';
  }

  async function hasVisibleError(p: Page): Promise<boolean> {
    const errorSelectors = [
      '[class*="error"]', '[class*="Error"]',
      '[role="alert"]', '.validation-error', '.invalid-feedback',
      '[class*="warning"]',
    ];
    for (const sel of errorSelectors) {
      try {
        const el = p.locator(sel).first();
        if (await el.isVisible({ timeout: 500 })) return true;
      } catch { /* continue */ }
    }
    const body = await getBodyText(p);
    const errorPhrases = ['不能为空', '已存在', '重复', '超过', '不合法', 'invalid', 'already exist', 'too long', 'required', 'duplicate', '请选择', '类型'];
    return errorPhrases.some(phrase => body.toLowerCase().includes(phrase.toLowerCase()));
  }

  async function createEntity(p: Page, name: string): Promise<boolean> {
    await findAndClick(p, ['新增实体', '添加实体', '新建实体', 'Add Entity', 'New Entity', 'Create Entity', '新增', 'Add']);
    await p.waitForTimeout(300);
    const input = await findInput(p, ['实体', 'entity', 'Entity', '名称', 'name']);
    if (input) {
      await input.fill(name);
      await p.waitForTimeout(200);
    }
    const confirmed = await confirmAction(p);
    if (!confirmed && input) {
      await input.press('Enter');
      await p.waitForTimeout(400);
    }
    await p.waitForTimeout(300);
    const body = await getBodyText(p);
    return body.includes(name.trim());
  }

  async function selectEntity(p: Page, name: string): Promise<boolean> {
    return await findAndClick(p, [name]);
  }

  async function addField(p: Page, fieldName: string, fieldType?: string): Promise<boolean> {
    await findAndClick(p, ['新增字段', '添加字段', '新建字段', 'Add Field', 'New Field', 'Add', '添加', '新增']);
    await p.waitForTimeout(300);

    // Fill field name
    const nameInput = await findInput(p, ['字段', 'field', 'Field', '名称', 'name', '列名', 'column']);
    if (nameInput) {
      await nameInput.fill(fieldName);
      await p.waitForTimeout(200);
    }

    // Set field type if provided
    if (fieldType) {
      // Try select dropdown
      const selectSelectors = [
        'select', '[class*="select"]', '[data-testid*="type"]',
        'select[name*="type"]',
      ];
      for (const sel of selectSelectors) {
        try {
          const selectEl = p.locator(sel).first();
          if (await selectEl.isVisible({ timeout: 500 })) {
            await selectEl.selectOption({ label: fieldType });
            await p.waitForTimeout(200);
            break;
          }
        } catch {
          try {
            // Try clicking the select and then clicking the option
            const selectEl = p.locator(sel).first();
            if (await selectEl.isVisible({ timeout: 300 })) {
              await selectEl.click();
              await p.waitForTimeout(300);
              await findAndClick(p, [fieldType]);
              break;
            }
          } catch { /* continue */ }
        }
      }
    }

    await confirmAction(p);
    await p.waitForTimeout(300);

    const body = await getBodyText(p);
    return body.includes(fieldName.trim());
  }

  it('should load the application successfully', async () => {
    const body = await getBodyText(page);
    expect(body.length).toBeGreaterThan(0);
    await page.close();
    await context.close();
  });

  it('should create an entity and add a field with type', async () => {
    const entityName = 'FieldTest_' + Date.now().toString().slice(-5);
    await createEntity(page, entityName);
    await selectEntity(page, entityName);
    await page.waitForTimeout(300);

    const fieldName = 'test_field';
    // Try common type names
    const added = await addField(page, fieldName, 'INT');
    if (!added) {
      // Try alternative type names
      await addField(page, fieldName, 'INTEGER');
    }

    const body = await getBodyText(page);
    // Field should appear in the right panel or entity card
    expect(body).toContain(fieldName);
    await page.close();
    await context.close();
  });

  it('should reject empty field name', async () => {
    const entityName = 'EmptyFieldTest_' + Date.now().toString().slice(-5);
    await createEntity(page, entityName);
    await selectEntity(page, entityName);
    await page.waitForTimeout(300);

    // Try adding a field with empty name
    await findAndClick(page, ['新增字段', '添加字段', 'Add Field', 'New Field', 'Add', '新增', '添加']);
    await page.waitForTimeout(300);

    const nameInput = await findInput(page, ['字段', 'field', 'Field', '名称', 'name']);
    if (nameInput) {
      await nameInput.fill('');
      await page.waitForTimeout(200);
    }

    await confirmAction(page);
    await page.waitForTimeout(400);

    const error = await hasVisibleError(page);
    expect(error).toBe(true);
    await page.close();
    await context.close();
  });

  it('should reject field name exceeding 30 characters', async () => {
    const entityName = 'LongFieldTest_' + Date.now().toString().slice(-5);
    await createEntity(page, entityName);
    await selectEntity(page, entityName);
    await page.waitForTimeout(300);

    const longFieldName = 'F'.repeat(31);
    await findAndClick(page, ['新增字段', '添加字段', 'Add Field', 'New Field', 'Add', '新增', '添加']);
    await page.waitForTimeout(300);

    const nameInput = await findInput(page, ['字段', 'field', 'Field', '名称', 'name']);
    if (nameInput) {
      await nameInput.fill(longFieldName);
      await page.waitForTimeout(200);
    }

    await confirmAction(page);
    await page.waitForTimeout(400);

    const error = await hasVisibleError(page);
    const body = await getBodyText(page);
    const rejected = error || !body.includes(longFieldName);
    expect(rejected).toBe(true);
    await page.close();
    await context.close();
  });

  it('should reject duplicate field name within same entity', async () => {
    const entityName = 'DupFieldTest_' + Date.now().toString().slice(-5);
    await createEntity(page, entityName);
    await selectEntity(page, entityName);
    await page.waitForTimeout(300);

    const fieldName = 'dup_field';
    await addField(page, fieldName, 'INT');
    await page.waitForTimeout(300);

    // Try adding another field with the same name
    await findAndClick(page, ['新增字段', '添加字段', 'Add Field', 'New Field', 'Add', '新增', '添加']);
    await page.waitForTimeout(300);

    const nameInput = await findInput(page, ['字段', 'field', 'Field', '名称', 'name']);
    if (nameInput) {
      await nameInput.fill(fieldName);
      await page.waitForTimeout(200);
    }

    await confirmAction(page);
    await page.waitForTimeout(400);

    const error = await hasVisibleError(page);
    expect(error).toBe(true);
    await page.close();
    await context.close();
  });

  it('should not allow saving a field without selecting a type', async () => {
    const entityName = 'NoTypeTest_' + Date.now().toString().slice(-5);
    await createEntity(page, entityName);
    await selectEntity(page, entityName);
    await page.waitForTimeout(300);

    await findAndClick(page, ['新增字段', '添加字段', 'Add Field', 'New Field', 'Add', '新增', '添加']);
    await page.waitForTimeout(300);

    const nameInput = await findInput(page, ['字段', 'field', 'Field', '名称', 'name']);
    if (nameInput) {
      await nameInput.fill('no_type_field');
      await page.waitForTimeout(200);
    }

    // Don't select a type, try to save
    await confirmAction(page);
    await page.waitForTimeout(400);

    const error = await hasVisibleError(page);
    // Either we get an error or the field is not created without a type
    const body = await getBodyText(page);
    const fieldNotSaved = !body.includes('no_type_field') || error;
    expect(fieldNotSaved).toBe(true);
    await page.close();
    await context.close();
  });

  it('should show empty state when entity has no fields', async () => {
    const entityName = 'NoFields_' + Date.now().toString().slice(-5);
    await createEntity(page, entityName);
    await selectEntity(page, entityName);
    await page.waitForTimeout(500);

    const body = await getBodyText(page);
    // Should see some indication of no fields / empty state
    const emptyIndicators = ['没有字段', '还没有字段', 'no field', 'No field', 'empty', '暂无', '无字段', 'Add a field', '添加字段'];
    const hasEmptyState = emptyIndicators.some(ind => body.toLowerCase().includes(ind.toLowerCase()));
    expect(hasEmptyState).toBe(true);
    await page.close();
    await context.close();
