  it('should switch right panel content when switching between entities', async () => {
    const entity1 = 'SwitchA_' + Date.now().toString().slice(-5);
    const entity2 = 'SwitchB_' + Date.now().toString().slice(-5);
    const field1 = 'field_in_a';
    const field2 = 'field_in_b';

    // Create two entities with different fields
    await createEntity(page, entity1);
    await selectEntity(page, entity1);
    await page.waitForTimeout(300);
    await addField(page, field1, 'INT');
    await page.waitForTimeout(300);

    await createEntity(page, entity2);
    await selectEntity(page, entity2);
    await page.waitForTimeout(300);
    await addField(page, field2, 'VARCHAR');
    await page.waitForTimeout(300);

    // Switch to entity1
    await selectEntity(page, entity1);
