    // Find and click delete for the field
    // The delete button might be near the field name
    const fieldEl = page.locator(`text=${fieldName}`).first();
    try {
      if (await fieldEl.isVisible({ timeout: 500 })) {
        await fieldEl.click();
        await page.waitForTimeout(300);
      }
    } catch { /* continue */ }

    await findAndClick(page, ['删除字段', '删除', 'Delete', 'Remove']);
