  async function toggleCheckbox(p: Page, labelPatterns: string[]): Promise<boolean> {
    for (const label of labelPatterns) {
      try {
        // Try label-based checkbox
        const checkbox = p.locator(`label:has-text("${label}") input[type="checkbox"]`).first();
        if (await checkbox.isVisible({ timeout: 500 })) {
          await checkbox.click();
          await p.waitForTimeout(300);
          return true;
        }
      } catch { /* continue */ }
      try {
        // Try clicking the label/switch directly
        const el = p.locator(`text=${label}`).first();
        if (await el.isVisible({ timeout: 500 })) {
          await el.click();
          await p.waitForTimeout(300);
          return true;
        }
      } catch { /* continue */ }
      try {
        // Try checkbox near text
        const el = p.locator(`input[type="checkbox"]`).first();
        if (await el.isVisible({ timeout: 300 })) {
          // Check if this is the right one by nearby text
          const parent = el.locator('..');
          const parentText = await parent.textContent() || '';
          if (labelPatterns.some(lp => parentText.includes(lp))) {
            await el.click();
            await p.waitForTimeout(300);
            return true;
          }
        }
      } catch { /* continue */ }
    }
    // Also try switch components
    for (const label of labelPatterns) {
      try {
        const switchEl = p.locator(`[class*="switch"]:near(:text("${label}"))`).first();
        if (await switchEl.isVisible({ timeout: 500 })) {
          await switchEl.click();
          await p.waitForTimeout(300);
          return true;
        }
      } catch { /* continue */ }
    }
    return false;
  }

  async function selectField(p: Page, fieldName: string): Promise<boolean> {
    return await findAndClick(p, [fieldName]);
  }

  async function setDefaultValue(p: Page, value: string): Promise<boolean> {
    const selectors = [
      'input[placeholder*="默认"]', 'input[placeholder*="default"]',
      'input[placeholder*="Default"]', '[data-testid*="default"]',
    ];
    for (const sel of selectors) {
      try {
        const el = p.locator(sel).first();
        if (await el.isVisible({ timeout: 500 })) {
          await el.fill(value);
          await p.waitForTimeout(200);
          return true;
        }
      } catch { /* continue */ }
    }
    return false;
  }

