import { describe, it, expect, beforeAll, afterAll } from 'vitest';
import puppeteer from 'puppeteer';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

describe('relation_creation_constraints_and_cascade_delete', () => {
  let browser;
  let page;

  beforeAll(async () => {
    browser = await puppeteer.launch({ headless: 'new', args: ['--no-sandbox', '--disable-setuid-sandbox'] });
    page = await browser.newPage();
    await page.goto(BASE_URL, { waitUntil: 'networkidle0', timeout: 30000 });
    await page.waitForSelector('body', { timeout: 10000 });
    // Small wait for React to render
    await new Promise(r => setTimeout(r, 2000));
  });

  afterAll(async () => {
    if (browser) await browser.close();
  });

  it('should serve the application page successfully', async () => {
    const res = await fetch(BASE_URL);
    expect(res.status).toBe(200);
    const html = await res.text();
    expect(html).toBeTruthy();
  });

  async function clickButtonByText(pg, text) {
    const btns = await pg.$$('button');
    for (const btn of btns) {
      const t = await pg.evaluate(el => el.textContent.trim(), btn);
      if (t.includes(text)) { await btn.click(); return true; }
    }
    // Also try links, divs, spans with click behavior
    const els = await pg.$$('[role="button"], a, [onClick], [data-action]');
    for (const el of els) {
      const t = await pg.evaluate(e => e.textContent.trim(), el);
      if (t.includes(text)) { await el.click(); return true; }
    }
    return false;
  }

  async function getVisibleText(pg) {
    return pg.evaluate(() => document.body.innerText);
  }

  async function createNewProject(pg) {
    const text = await getVisibleText(pg);
    // Try to create or use a blank project
    const clicked = await clickButtonByText(pg, '新建') || await clickButtonByText(pg, '新建项目') || await clickButtonByText(pg, 'New') || await clickButtonByText(pg, 'Create');
    if (clicked) {
      await new Promise(r => setTimeout(r, 500));
      // Fill project name if prompted
      const inputs = await pg.$$('input');
      for (const inp of inputs) {
        const placeholder = await pg.evaluate(el => el.placeholder || '', inp);
        if (placeholder.includes('项目') || placeholder.includes('name') || placeholder.includes('Name') || placeholder.includes('名')) {
          await inp.click({ clickCount: 3 });
          await inp.type('TestProject');
          break;
        }
      }
      await clickButtonByText(pg, '确定') || await clickButtonByText(pg, '确认') || await clickButtonByText(pg, 'OK') || await clickButtonByText(pg, 'Confirm') || await clickButtonByText(pg, '创建');
      await new Promise(r => setTimeout(r, 500));
    }
  }

  async function addEntity(pg, name) {
    const clicked = await clickButtonByText(pg, '新增实体') || await clickButtonByText(pg, '添加实体') || await clickButtonByText(pg, 'Add Entity') || await clickButtonByText(pg, '新建实体') || await clickButtonByText(pg, '+');
    await new Promise(r => setTimeout(r, 500));
    // Fill entity name
    const inputs = await pg.$$('input');
    for (const inp of inputs) {
      const val = await pg.evaluate(el => el.value, inp);
      const placeholder = await pg.evaluate(el => el.placeholder || '', inp);
      if (placeholder.includes('实体') || placeholder.includes('entity') || placeholder.includes('Entity') || placeholder.includes('名') || val === '' || val.includes('实体') || val.includes('Entity')) {
        await inp.click({ clickCount: 3 });
        await inp.type(name);
        break;
      }
    }
    await clickButtonByText(pg, '确定') || await clickButtonByText(pg, '确认') || await clickButtonByText(pg, 'OK') || await clickButtonByText(pg, 'Confirm') || await clickButtonByText(pg, '保存') || await clickButtonByText(pg, 'Save');
    await new Promise(r => setTimeout(r, 500));
  }

  async function findAndCountRelations(pg) {
    const text = await getVisibleText(pg);
    // Look for relation count in the UI
    const match = text.match(/(\d+)\s*[个条]?\s*(关系|relation)/i) || text.match(/(关系|relation)[^\d]*(\d+)/i);
    if (match) {
      return parseInt(match[1]) || parseInt(match[2]) || 0;
    }
    return -1; // unknown
  }

  it('should allow creating entities and creating relations between them', async () => {
    await createNewProject(page);
    await addEntity(page, 'EntityA');
    await addEntity(page, 'EntityB');
    await addEntity(page, 'EntityC');
    await new Promise(r => setTimeout(r, 1000));

    const text = await getVisibleText(page);
    // Verify entities exist in the page
    expect(text).toMatch(/EntityA/i);
    expect(text).toMatch(/EntityB/i);
    expect(text).toMatch(/EntityC/i);

    // Try to create a relation between EntityA and EntityB
    const addedRelation = await clickButtonByText(page, '添加关系') || await clickButtonByText(page, '新增关系') || await clickButtonByText(page, '创建关系') || await clickButtonByText(page, 'Add Relation') || await clickButtonByText(page, 'New Relation') || await clickButtonByText(page, 'Create Relation');
    await new Promise(r => setTimeout(r, 500));

    if (addedRelation) {
      // Select source and target entities from dropdowns/selects
      const selects = await page.$$('select');
      if (selects.length >= 2) {
        await selects[0].select('EntityA');
        await new Promise(r => setTimeout(r, 200));
        await selects[1].select('EntityB');
        await new Promise(r => setTimeout(r, 200));
      } else {
