        const allTexts = await page.$$eval('[class*="option"], [class*="item"], [role="option"], li', els => els.map(e => e.textContent.trim()));
        // Try to click EntityA then EntityB
      }

      // Select relation type - one-to-many
      const typeSelects = await page.$$('select');
      for (const sel of typeSelects) {
        const options = await page.evaluate(el => Array.from(el.options).map(o => o.value + '|' + o.text), sel);
        const hasType = options.some(o => o.includes('one') || o.includes('many') || o.includes('一对'));
        if (hasType) {
          const typeOption = options.find(o => o.includes('one-to-many') || o.includes('oneToMany') || o.includes('1:N') || o.includes('一对多'));
          if (typeOption) {
            await sel.select(typeOption.split('|')[0]);
          }
          break;
        }
      }

      await clickButtonByText(page, '确定') || await clickButtonByText(page, '确认') || await clickButtonByText(page, 'OK') || await clickButtonByText(page, '保存') || await clickButtonByText(page, 'Save') || await clickButtonByText(page, '创建') || await clickButtonByText(page, 'Create');
      await new Promise(r => setTimeout(r, 500));
    }

    const textAfter = await getVisibleText(page);
    // The page should show at least some relationship information or the relation count should be > 0
    const hasRelation = textAfter.includes('关系') || textAfter.includes('relation') || textAfter.includes('Relation');
    expect(hasRelation).toBe(true);
  });

  it('should prevent self-connections (same entity to itself)', async () => {
    // Try to create a relation from EntityA to EntityA
    const addedRelation = await clickButtonByText(page, '添加关系') || await clickButtonByText(page, '新增关系') || await clickButtonByText(page, '创建关系') || await clickButtonByText(page, 'Add Relation') || await clickButtonByText(page, 'New Relation');
    await new Promise(r => setTimeout(r, 500));

    if (addedRelation) {
      const selects = await page.$$('select');
      if (selects.length >= 2) {
        // Try selecting same entity for both source and target
        try {
          await selects[0].select('EntityA');
          await new Promise(r => setTimeout(r, 200));
          await selects[1].select('EntityA');
          await new Promise(r => setTimeout(r, 200));
        } catch (e) {
          // If EntityA is not available in target, that's also valid prevention
        }
      }

      await clickButtonByText(page, '确定') || await clickButtonByText(page, '确认') || await clickButtonByText(page, 'OK') || await clickButtonByText(page, '保存') || await clickButtonByText(page, 'Save') || await clickButtonByText(page, '创建');
      await new Promise(r => setTimeout(r, 500));
    }

    const text = await getVisibleText(page);
    // Should show error/warning about self-connection, or the self-relation should not be created
    const hasSelfError = text.includes('不允许') || text.includes('自连接') || text.includes('self') || text.includes('相同') || text.includes('cannot') || text.includes('same entity') || text.includes('不能');
    // Or alternatively, count relations should not have increased for self-connection
    // The application should either show an error or prevent the selection
    // We check that the UI communicates the restriction
    const bodyText = text.toLowerCase();
    const selfRelationPrevented = hasSelfError || bodyText.includes('invalid') || bodyText.includes('error') || bodyText.includes('禁止');
    expect(selfRelationPrevented).toBe(true);
  });

  it('should prevent duplicate relations in the same direction between same entities', async () => {
    // First ensure we have a relation between EntityA and EntityB from previous test
    // Try to create the same relation again
    const addedRelation = await clickButtonByText(page, '添加关系') || await clickButtonByText(page, '新增关系') || await clickButtonByText(page, '创建关系') || await clickButtonByText(page, 'Add Relation') || await clickButtonByText(page, 'New Relation');
    await new Promise(r => setTimeout(r, 500));

    if (addedRelation) {
      const selects = await page.$$('select');
      if (selects.length >= 2) {
        try {
          await selects[0].select('EntityA');
          await new Promise(r => setTimeout(r, 200));
          await selects[1].select('EntityB');
          await new Promise(r => setTimeout(r, 200));
