      text.includes('100%') || text.includes('适应') || text.includes('fit');
    expect(hasZoomControls).toBe(true);
  });

  it('should maintain consistent state across multiple reloads', async () => {
    // First reload
    await page.reload({ waitUntil: 'networkidle0', timeout: 30000 });
    await new Promise(r => setTimeout(r, 2000));
    const text1 = await getText(page);

    // Second reload
    await page.reload({ waitUntil: 'networkidle0', timeout: 30000 });
    await new Promise(r => setTimeout(r, 2000));
    const text2 = await getText(page);

    // Entities should be present after both reloads
