import { describe, it, expect, beforeAll, afterAll } from 'vitest';
import puppeteer from 'puppeteer';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

describe('generate_sql_and_problem_list_from_model', () => {
  let browser;
  let page;

  beforeAll(async () => {
    browser = await puppeteer.launch({ headless: 'new', args: ['--no-sandbox', '--disable-setuid-sandbox'] });
    page = await browser.newPage();
    await page.goto(BASE_URL, { waitUntil: 'networkidle0', timeout: 30000 });
    await new Promise(r => setTimeout(r, 2000));
  });

  afterAll(async () => {
    if (browser) await browser.close();
  });

  async function clickByText(pg, text) {
    const btns = await pg.$$('button, [role="button"], a, [class*="tab"], [role="tab"]');
    for (const btn of btns) {
      const t = await pg.evaluate(el => el.textContent.trim(), btn);
      if (t.includes(text)) { await btn.click(); return true; }
    }
    return false;
  }

  async function getText(pg) {
    return pg.evaluate(() => document.body.innerText);
  }

  async function setupProject(pg) {
    await clickByText(pg, '新建') || await clickByText(pg, 'New') || await clickByText(pg, '创建');
    await new Promise(r => setTimeout(r, 500));
    const inputs = await pg.$$('input');
    for (const inp of inputs) {
      const ph = await pg.evaluate(el => el.placeholder || '', inp);
      if (ph.includes('项目') || ph.includes('name') || ph.includes('名')) {
        await inp.click({ clickCount: 3 });
        await inp.type('SQLGenTest');
        break;
      }
    }
    await clickByText(pg, '确定') || await clickByText(pg, '确认') || await clickByText(pg, 'OK') || await clickByText(pg, '创建');
    await new Promise(r => setTimeout(r, 500));
  }

  async function addEntity(pg, name) {
    await clickByText(pg, '新增实体') || await clickByText(pg, '添加实体') || await clickByText(pg, 'Add Entity') || await clickByText(pg, '新建实体') || await clickByText(pg, '+');
    await new Promise(r => setTimeout(r, 500));
    const inputs = await pg.$$('input');
    for (const inp of inputs) {
      const val = await pg.evaluate(el => el.value, inp);
      const ph = await pg.evaluate(el => el.placeholder || '', inp);
      if (ph.includes('实体') || ph.includes('entity') || ph.includes('名') || val === '' || val.includes('实体')) {
        await inp.click({ clickCount: 3 });
        await inp.type(name);
        break;
      }
    }
    await clickByText(pg, '确定') || await clickByText(pg, '确认') || await clickByText(pg, 'OK') || await clickByText(pg, '保存') || await clickByText(pg, '创建');
    await new Promise(r => setTimeout(r, 500));
  }

  async function selectEntity(pg, name) {
    const items = await pg.$$('[class*="entity"], [class*="item"], [class*="list"] > *, li');
    for (const item of items) {
      const t = await pg.evaluate(el => el.textContent.trim(), item);
      if (t.includes(name)) {
        await item.click();
        await new Promise(r => setTimeout(r, 500));
        return true;
      }
    }
    return false;
  }

  async function addField(pg, fieldName, fieldType, isPK, isNotNull, isUnique, defaultVal) {
    await clickByText(pg, '新增字段') || await clickByText(pg, '添加字段') || await clickByText(pg, 'Add Field') || await clickByText(pg, '+');
    await new Promise(r => setTimeout(r, 500));

    const inputs = await pg.$$('input:not([type="checkbox"])');
    for (const inp of inputs) {
      const ph = await pg.evaluate(el => el.placeholder || '', inp);
      const val = await pg.evaluate(el => el.value, inp);
      if (ph.includes('字段') || ph.includes('field') || ph.includes('名') || val === '' || val.includes('字段') || val.includes('field')) {
        await inp.click({ clickCount: 3 });
        await inp.type(fieldName);
        break;
      }
    }

    // Select type
    if (fieldType) {
      const selects = await pg.$$('select');
      for (const sel of selects) {
        const options = await pg.evaluate(el => Array.from(el.options).map(o => o.value.toLowerCase() + '|' + o.text.toLowerCase()), sel);
        const hasTypeOptions = options.some(o => o.includes('int') || o.includes('varchar') || o.includes('text') || o.includes('number') || o.includes('date'));
        if (hasTypeOptions) {
          const typeOpt = options.find(o => o.includes(fieldType.toLowerCase()));
          if (typeOpt) {
            await sel.select(typeOpt.split('|')[0] === typeOpt.split('|')[1] ? typeOpt.split('|')[0] : await pg.evaluate((el, ft) => {
              const opts = Array.from(el.options);
              const match = opts.find(o => o.value.toLowerCase().includes(ft) || o.text.toLowerCase().includes(ft));
              return match ? match.value : '';
            }, sel, fieldType.toLowerCase()));
          }
          break;
        }
      }
    }

    // Set constraints via checkboxes
    const checkboxes = await pg.$$('input[type="checkbox"]');
    for (const cb of checkboxes) {
      const label = await pg.evaluate(el => {
        const parent = el.closest('label') || el.parentElement;
        return parent ? parent.textContent.trim() : '';
      }, cb);
      if (isPK && (label.includes('主键') || label.includes('primary') || label.includes('PK'))) {
        const checked = await pg.evaluate(el => el.checked, cb);
        if (!checked) await cb.click();
      }
      if (isNotNull && (label.includes('非空') || label.includes('not null') || label.includes('NOT NULL') || label.includes('必填'))) {
        const checked = await pg.evaluate(el => el.checked, cb);
        if (!checked) await cb.click();
      }
      if (isUnique && (label.includes('唯一') || label.includes('unique') || label.includes('UNIQUE'))) {
        const checked = await pg.evaluate(el => el.checked, cb);
        if (!checked) await cb.click();
      }
    }

    // Set default value
    if (defaultVal) {
      const allInputs = await pg.$$('input:not([type="checkbox"])');
      for (const inp of allInputs) {
        const ph = await pg.evaluate(el => el.placeholder || '', inp);
        const name = await pg.evaluate(el => el.name || '', inp);
        if (ph.includes('默认') || ph.includes('default') || name.includes('default')) {
          await inp.click({ clickCount: 3 });
          await inp.type(defaultVal);
          break;
        }
      }
    }

    await clickByText(pg, '保存') || await clickByText(pg, 'Save') || await clickByText(pg, '确定');
    await new Promise(r => setTimeout(r, 500));
  }

  async function switchToSQLTab(pg) {
    await clickByText(pg, 'SQL') || await clickByText(pg, 'SQL预览') || await clickByText(pg, 'SQL Preview') || await clickByText(pg, 'DDL') || await clickByText(pg, '生成SQL');
    await new Promise(r => setTimeout(r, 500));
  }

  it('should serve the application page successfully', async () => {
    const res = await fetch(BASE_URL);
    expect(res.status).toBe(200);
  });

  it('should generate SQL with CREATE TABLE, PRIMARY KEY, NOT NULL, UNIQUE, and DEFAULT', async () => {
    await setupProject(page);
    await addEntity(page, 'users');
    await selectEntity(page, 'users');
    await addField(page, 'id', 'int', true, true, false, null);
    await addField(page, 'username', 'varchar', false, true, true, null);
    await addField(page, 'status', 'varchar', false, false, false, 'active');
    await new Promise(r => setTimeout(r, 500));

    await switchToSQLTab(page);
    const text = await getText(page);
    const textLower = text.toLowerCase();

    // Should contain CREATE TABLE
    const hasCreateTable = textLower.includes('create table') || textLower.includes('create  table');
    expect(hasCreateTable).toBe(true);

    // Should reference the entity name
    expect(textLower).toMatch(/users/);

    // Should contain PRIMARY KEY
    const hasPK = textLower.includes('primary key');
    expect(hasPK).toBe(true);

    // Should contain NOT NULL
    const hasNotNull = textLower.includes('not null');
    expect(hasNotNull).toBe(true);

    // Should contain UNIQUE
    const hasUnique = textLower.includes('unique');
    expect(hasUnique).toBe(true);

    // Should contain DEFAULT
    const hasDefault = textLower.includes('default');
    expect(hasDefault).toBe(true);
  });

  it('should output foreign key information for clearly mapped relations', async () => {
    await addEntity(page, 'orders');
    await selectEntity(page, 'orders');
    await addField(page, 'order_id', 'int', true, true, false, null);
    await addField(page, 'user_id', 'int', false, true, false, null);
    await new Promise(r => setTimeout(r, 500));

    // Create a one-to-many relation from users to orders
    await clickByText(page, '添加关系') || await clickByText(page, '新增关系') || await clickByText(page, '创建关系') || await clickByText(page, 'Add Relation') || await clickByText(page, 'New Relation');
    await new Promise(r => setTimeout(r, 500));
    const selects = await page.$$('select');
    if (selects.length >= 2) {
      try {
        await selects[0].select('users');
        await new Promise(r => setTimeout(r, 200));
        await selects[1].select('orders');
        await new Promise(r => setTimeout(r, 200));
      } catch (e) { /* fallback */ }
    }
    await clickByText(page, '确定') || await clickByText(page, '确认') || await clickByText(page, 'OK') || await clickByText(page, '保存') || await clickByText(page, '创建');
    await new Promise(r => setTimeout(r, 500));

    await switchToSQLTab(page);
    const text = await getText(page);
    const textLower = text.toLowerCase();

    // Should contain FOREIGN KEY or REFERENCES, or a comment about the relation
    const hasForeignKey = textLower.includes('foreign key') || textLower.includes('references') || textLower.includes('--') || textLower.includes('/*');
    expect(hasForeignKey).toBe(true);
  });

  it('should show problem list for incomplete models without crashing', async () => {
    // Add an entity without any fields to create an incomplete model
    await addEntity(page, 'empty_table');
    await new Promise(r => setTimeout(r, 500));

    await switchToSQLTab(page);
    const text = await getText(page);
    const textLower = text.toLowerCase();

    // Should show problems/warnings for the incomplete entity
    const hasProblem = textLower.includes('问题') || textLower.includes('warning') || textLower.includes('error') || textLower.includes('problem') || textLower.includes('issue') || textLower.includes('缺') || textLower.includes('不完整') || textLower.includes('incomplete') || textLower.includes('missing');
    expect(hasProblem).toBe(true);

    // SQL should not crash - should still contain the valid parts (users table SQL)
    expect(textLower).toMatch(/create table/);
  });

  it('should synchronize SQL and problem list when model changes', async () => {
    // Get current SQL content
    await switchToSQLTab(page);
    const textBefore = await getText(page);

    // Add a field to empty_table to fix the issue
    await selectEntity(page, 'empty_table');
    await addField(page, 'col1', 'int', false, false, false, null);
