    const hasSQLSection = text.includes('SQL') || text.includes('DDL') || text.includes('预览') || text.includes('Preview');
    expect(hasSQLSection).toBe(true);
  });
});

import { describe, it, expect, beforeAll } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

/**
