          try {
            const bundleRes = await fetch(`${BASE_URL}${src}`);
            if (bundleRes.ok) {
              bundleContent += await bundleRes.text();
            }
          } catch { /* skip unreachable bundles */ }
        }
      }
    }

    // The application should contain references to SQL type handling
    // These are the common types required by Round 9
    const appContent = (text + bundleContent).toLowerCase();

    // Verify the app contains type-related keywords indicating SQL type mapping support
