          try {
            const bundleRes = await fetch(`${BASE_URL}${src}`);
            if (bundleRes.ok) {
              bundleContent += await bundleRes.text();
            }
          } catch { /* skip */ }
        }
      }
    }

    const appContent = (text + bundleContent).toLowerCase();

    // The app should contain length validation logic
    const hasLengthValidation = appContent.includes('length') &&
      (appContent.includes('valid') || appContent.includes('required') || appContent.includes('positive') || appContent.includes('integer'));
    expect(hasLengthValidation, 'Application should contain length validation logic for SQL types').toBe(true);
  });

  it('should have SQL preview and issues/problem list UI components', async () => {
    const { res, text } = await fetchPage('/');
    expect(res.status).toBe(200);

    const scriptMatches = text.match(/src=["']([^"']+\.js[^"']*)["']/gi) || [];
    let bundleContent = '';

    for (const match of scriptMatches) {
      const srcMatch = match.match(/src=["']([^"']+)["']/);
      if (srcMatch && srcMatch[1]) {
        let src = srcMatch[1];
        if (src.startsWith('/')) {
          try {
            const bundleRes = await fetch(`${BASE_URL}${src}`);
            if (bundleRes.ok) {
              bundleContent += await bundleRes.text();
            }
          } catch { /* skip */ }
        }
      }
    }

    const appContent = (text + bundleContent).toLowerCase();

    // SQL preview feature should exist
    const hasSqlPreview = appContent.includes('sql') &&
      (appContent.includes('preview') || appContent.includes('generate') || appContent.includes('create table'));
    expect(hasSqlPreview, 'Application should contain SQL preview functionality').toBe(true);

    // Issues/problem list feature should exist
    const hasIssuesList = appContent.includes('issue') ||
      appContent.includes('problem') ||
      appContent.includes('warning') ||
      appContent.includes('error');
    expect(hasIssuesList, 'Application should contain issues/problems list functionality').toBe(true);

    // Multiple SQL types should be recognized (Round 9: numeric, text, datetime)
