describe('switch_sql_dialect_affects_preview_not_model', () => {
  it('should change preview and validation by dialect without mutating model data', async () => {
    const projectName = `vt-dialect-${Date.now()}`;
    // Include a field that has dialect-specific behavior:
    // - 'boolean' type: MySQL uses TINYINT(1), PostgreSQL uses BOOLEAN
    // - 'json' type: may differ in support
    // - auto_increment / SERIAL difference
    // Also include a field with a problematic config to ensure issues list is non-empty
    const payload = {
      name: projectName,
      sqlDialect: 'mysql',
      entities: [
        {
          name: 'orders',
          fields: [
            { name: 'id', type: 'integer', primaryKey: true, nullable: false },
            { name: 'code', type: 'varchar', length: 32, nullable: false },
            { name: 'is_active', type: 'boolean', nullable: true, defaultValue: 'true' },
            { name: 'payload', type: 'json', nullable: true },
            { name: 'bad_field', type: 'varchar', nullable: true }
            // bad_field has no length - should produce an issue
          ]
        }
      ]
    };

    let projectId;
    try {
      const create = await request('/api/projects', { method: 'POST', body: JSON.stringify(payload) });
      expect([200, 201]).toContain(create.res.status);
      projectId = create.body.id || create.body.projectId || create.body.data?.id;
      expect(projectId).toBeTruthy();

      // Capture model state before dialect switching
      const before = await request(`/api/projects/${projectId}`);
      expect(before.res.status).toBe(200);
      const beforeBody = before.body.data || before.body;
      expect(beforeBody.name).toBe(projectName);
      const beforeEntities = JSON.stringify(beforeBody.entities || beforeBody);
      expect(beforeEntities).toContain('orders');
      expect(beforeEntities).toContain('payload');
      expect(beforeEntities).toContain('is_active');

      // Get MySQL preview
      const mysqlPreview = await request(`/api/projects/${projectId}/sql/preview?dialect=mysql`);
      expect(mysqlPreview.res.status).toBe(200);
      const mysqlSql = mysqlPreview.body.sql || mysqlPreview.body.preview || mysqlPreview.body.data?.sql || '';
      const mysqlIssues = mysqlPreview.body.issues || mysqlPreview.body.problems || [];
      expect(typeof mysqlSql).toBe('string');
      expect(mysqlSql, 'mysql preview should not be empty').not.toBe('');
      expect(Array.isArray(mysqlIssues)).toBe(true);

      // Get PostgreSQL preview
      const pgPreview = await request(`/api/projects/${projectId}/sql/preview?dialect=postgres`);
      expect(pgPreview.res.status).toBe(200);
      const pgSql = pgPreview.body.sql || pgPreview.body.preview || pgPreview.body.data?.sql || '';
      const pgIssues = pgPreview.body.issues || pgPreview.body.problems || [];
      expect(typeof pgSql).toBe('string');
      expect(pgSql, 'postgres preview should not be empty').not.toBe('');
      expect(Array.isArray(pgIssues)).toBe(true);

      // SQL outputs should differ between dialects (boolean, auto_increment vs serial, identifier quoting, etc.)
      expect(mysqlSql).not.toBe(pgSql);

      // Issues list should not be cleared by switching dialect
      // bad_field (varchar without length) should produce issues in both dialects
      expect(mysqlIssues.length, 'mysql issues should not be empty due to bad_field').toBeGreaterThan(0);
      expect(pgIssues.length, 'postgres issues should not be empty due to bad_field').toBeGreaterThan(0);

      // Check for dialect-specific differences in issues or SQL
      // At minimum, the SQL should show dialect-specific syntax differences
      const mysqlSqlLower = mysqlSql.toLowerCase();
      const pgSqlLower = pgSql.toLowerCase();
      // MySQL and PostgreSQL should produce visibly different output for boolean/autoincrement/quoting
      const hasDifference =
        (mysqlSqlLower.includes('tinyint') && !pgSqlLower.includes('tinyint')) ||
        (pgSqlLower.includes('boolean') && !mysqlSqlLower.includes('boolean')) ||
        (mysqlSqlLower.includes('auto_increment') && !pgSqlLower.includes('auto_increment')) ||
        (pgSqlLower.includes('serial') && !mysqlSqlLower.includes('serial')) ||
        (mysqlSqlLower.includes('`') && pgSqlLower.includes('"')) ||
        mysqlSqlLower !== pgSqlLower;
      expect(hasDifference, 'different dialects should produce visibly different SQL').toBe(true);

      // Check dialect-specific issue differences if applicable
      // json type may be valid in one dialect but not another, or produce different warnings
      const mysqlIssueText = JSON.stringify(mysqlIssues).toLowerCase();
      const pgIssueText = JSON.stringify(pgIssues).toLowerCase();
      // Both should have issues (at minimum for bad_field), but content may differ
      // We just verify neither was cleared
      expect(mysqlIssueText.length).toBeGreaterThan(2); // not just '[]'
      expect(pgIssueText.length).toBeGreaterThan(2);

      // Verify model data was NOT mutated by switching dialects
      const after = await request(`/api/projects/${projectId}`);
      expect(after.res.status).toBe(200);
      const afterBody = after.body.data || after.body;
      expect(afterBody.name).toBe(projectName);
      const afterEntities = JSON.stringify(afterBody.entities || afterBody);
      expect(afterEntities).toContain('orders');
      expect(afterEntities).toContain('payload');
      expect(afterEntities).toContain('is_active');
      expect(afterEntities).toContain('code');
      expect(afterEntities).toContain('bad_field');
    } finally {
      await safeDeleteProject(projectId);
    }
  });
});

