async function safeDeleteProject(id) {
  if (!id) return;
  try {
    await fetch(`${BASE_URL}/api/projects/${id}`, { method: 'DELETE' });
  } catch {}
}

describe('execute_supported_select_queries_with_expected_counts', () => {
  it('should execute supported single-table SELECT/WHERE/LIMIT and reject unsupported SQL', async () => {
    const rowCount = 12;
    const payload = {
      name: `vt-exec-${Date.now()}`,
      sqlDialect: 'mysql',
      entities: [
        {
          name: 'products',
          mock: { rows: rowCount },
          fields: [
            { name: 'id', type: 'integer', primaryKey: true, mockRule: { type: 'increment', start: 1, step: 1 } },
            { name: 'category', type: 'varchar', length: 10, mockRule: { type: 'sequence', values: ['A', 'B'] } }
          ]
        }
      ]
    };

    let projectId;
    try {
      const create = await request('/api/projects', { method: 'POST', body: JSON.stringify(payload) });
      expect([200, 201]).toContain(create.res.status);
      projectId = create.body.id || create.body.projectId || create.body.data?.id;
      expect(projectId).toBeTruthy();

      const gen = await request(`/api/projects/${projectId}/mock-data/generate`, { method: 'POST', body: JSON.stringify({ entity: 'products', rows: rowCount }) });
      expect([200, 201]).toContain(gen.res.status);

      const q1 = await request(`/api/projects/${projectId}/sql/execute`, { method: 'POST', body: JSON.stringify({ query: 'SELECT * FROM products' }) });
      expect(q1.res.status).toBe(200);
      const rows1 = q1.body.rows || q1.body.data?.rows || q1.body.result || [];
      const count1 = q1.body.count || q1.body.total || rows1.length;
      expect(Array.isArray(rows1)).toBe(true);
      expect(count1).toBe(rowCount);
      expect(rows1.length).toBe(rowCount);

      const q2 = await request(`/api/projects/${projectId}/sql/execute`, { method: 'POST', body: JSON.stringify({ query: "SELECT * FROM products WHERE category = 'A'" }) });
      expect(q2.res.status).toBe(200);
      const rows2 = q2.body.rows || q2.body.data?.rows || [];
      expect(Array.isArray(rows2)).toBe(true);
      expect(rows2.length).toBeGreaterThan(0);
      for (const row of rows2) expect(String(row.category)).toBe('A');

      const q3 = await request(`/api/projects/${projectId}/sql/execute`, { method: 'POST', body: JSON.stringify({ query: 'SELECT * FROM products LIMIT 5' }) });
      expect(q3.res.status).toBe(200);
      const rows3 = q3.body.rows || q3.body.data?.rows || [];
      expect(rows3.length).toBe(5);

      const unsupportedQueries = [
        'SELECT * FROM products p JOIN products p2 ON p.id = p2.id',
        'UPDATE products SET category = \"X\"',
        'DELETE FROM products',
        'SELECT * FROM (SELECT * FROM products) t',
        'SELECT category, COUNT(*) FROM products GROUP BY category HAVING COUNT(*) > 1'
      ];

      for (const query of unsupportedQueries) {
        const res = await request(`/api/projects/${projectId}/sql/execute`, { method: 'POST', body: JSON.stringify({ query }) });
        expect([400, 422]).toContain(res.res.status);
        const text = JSON.stringify(res.body || res.text).toLowerCase();
        expect(text.includes('support') || text.includes('unsupported') || text.includes('only select')).toBe(true);
      }
    } finally {
      await safeDeleteProject(projectId);
    }
  });
});

