describe('generate_mock_data_with_rules_and_validation', () => {
  it('should generate mock rows for valid rules and reject invalid generator configs', async () => {
    const rows = 10;
    const payload = {
      name: `vt-mock-rules-${Date.now()}`,
      entities: [
        {
          name: 'samples',
          fields: [
            { name: 'id', type: 'integer', primaryKey: true, nullable: false, mockRule: { type: 'increment', start: 1, step: 1 } },
            { name: 'title', type: 'varchar', length: 30, nullable: false, mockRule: { type: 'randomText', minLength: 5, maxLength: 8 } },
            { name: 'created_at', type: 'datetime', nullable: false, mockRule: { type: 'datetime' } },
            { name: 'enabled', type: 'boolean', nullable: false, mockRule: { type: 'boolean' } },
            { name: 'status', type: 'varchar', length: 10, nullable: false, mockRule: { type: 'sequence', values: ['NEW', 'OLD'] } },
            { name: 'kind', type: 'varchar', length: 10, nullable: false, mockRule: { type: 'sample', options: ['A', 'B', 'C'] } }
          ]
        }
      ]
    };

    let projectId;
    let invalidProjectId;
    try {
      const create = await request('/api/projects', { method: 'POST', body: JSON.stringify(payload) });
      expect([200, 201]).toContain(create.res.status);
      projectId = create.body.id || create.body.projectId || create.body.data?.id;
      expect(projectId).toBeTruthy();

      const gen = await request(`/api/projects/${projectId}/mock-data/generate`, { method: 'POST', body: JSON.stringify({ entity: 'samples', rows }) });
      expect([200, 201]).toContain(gen.res.status);
      const generated = gen.body.rows || gen.body.data?.rows || gen.body.result || [];
      expect(Array.isArray(generated)).toBe(true);
      expect(generated.length).toBe(rows);

      const ids = new Set(generated.map(r => r.id));
      expect(ids.size).toBe(rows);
      for (const row of generated) {
        expect(row.id).toBeTypeOf('number');
        expect(row.title).toBeTruthy();
        expect(row.created_at || row.createdAt).toBeTruthy();
        expect(typeof row.enabled).toBe('boolean');
        expect(['NEW', 'OLD']).toContain(row.status);
        expect(['A', 'B', 'C']).toContain(row.kind);
      }

      const invalidPayload = {
        name: `vt-mock-invalid-${Date.now()}`,
        entities: [
          {
            name: 'bad_samples',
            fields: [
              { name: 'id', type: 'integer', primaryKey: true, mockRule: { type: 'increment', start: 1, step: 0 } },
              { name: 'kind', type: 'varchar', length: 10, mockRule: { type: 'sample', options: [] } },
              { name: 'status', type: 'varchar', length: 10, mockRule: { type: 'sequence', values: [] } }
            ]
          }
        ]
      };
      const invalidCreate = await request('/api/projects', { method: 'POST', body: JSON.stringify(invalidPayload) });
      expect([200, 201]).toContain(invalidCreate.res.status);
      invalidProjectId = invalidCreate.body.id || invalidCreate.body.projectId || invalidCreate.body.data?.id;
      expect(invalidProjectId).toBeTruthy();

      const invalidGen = await request(`/api/projects/${invalidProjectId}/mock-data/generate`, { method: 'POST', body: JSON.stringify({ entity: 'bad_samples', rows: 5 }) });
      expect([400, 422]).toContain(invalidGen.res.status);
      const invalidText = JSON.stringify(invalidGen.body || invalidGen.text).toLowerCase();
      expect(invalidText.includes('step') || invalidText.includes('options') || invalidText.includes('sequence')).toBe(true);

      const tooMany = await request(`/api/projects/${projectId}/mock-data/generate`, { method: 'POST', body: JSON.stringify({ entity: 'samples', rows: 1001 }) });
      expect([400, 422]).toContain(tooMany.res.status);
      const tooManyText = JSON.stringify(tooMany.body || tooMany.text).toLowerCase();
      expect(tooManyText.includes('1000') || tooManyText.includes('limit') || tooManyText.includes('rows')).toBe(true);
    } finally {
      await safeDeleteProject(projectId);
      await safeDeleteProject(invalidProjectId);
    }
  });
});

import { describe, it, expect, beforeAll } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

/**
 * This is a frontend-only React application. Mock data generation with
 * relationship awareness runs client-side. Since there are no backend API
 * endpoints, we validate that the app contains the relationship-aware
 * mock data generation logic.
 */

async function fetchPage(path = '/') {
  const res = await fetch(`${BASE_URL}${path}`);
  const text = await res.text();
  return { res, text };
}

async function getAppBundle(): Promise<string> {
  const { text } = await fetchPage('/');
  const scriptMatches = text.match(/src=["']([^"']+\.js[^"']*)["']/gi) || [];
  let bundleContent = text;

  for (const match of scriptMatches) {
    const srcMatch = match.match(/src=["']([^"']+)["']/);
    if (srcMatch && srcMatch[1]) {
      let src = srcMatch[1];
      if (src.startsWith('/')) {
        try {
          const bundleRes = await fetch(`${BASE_URL}${src}`);
          if (bundleRes.ok) {
            bundleContent += await bundleRes.text();
          }
        } catch { /* skip */ }
      }
    }
  }
  return bundleContent;
}

describe('mock_data_respects_relationship_constraints', () => {
  let appContent = '';
  let appContentLower = '';

  beforeAll(async () => {
    appContent = await getAppBundle();
    appContentLower = appContent.toLowerCase();
  });

  it('should serve the application successfully', async () => {
    const { res, text } = await fetchPage('/');
    expect(res.status).toBe(200);
    expect(res.headers.get('content-type')).toMatch(/text\/html/i);
    expect(text).toContain('<div id="root"');
  });

  it('should contain mock data generation functionality', () => {
    const hasMockData = (appContentLower.includes('mock') || appContentLower.includes('simulate') || appContentLower.includes('generat')) &&
      (appContentLower.includes('data') || appContentLower.includes('row'));
    expect(hasMockData, 'Application should contain mock data generation functionality').toBe(true);
  });

  it('should support relationship types: one-to-one, one-to-many, many-to-many', () => {
    const hasOneToMany = appContentLower.includes('one-to-many') || appContentLower.includes('onetomany') || appContentLower.includes('1:n') || appContentLower.includes('one_to_many');
    const hasOneToOne = appContentLower.includes('one-to-one') || appContentLower.includes('onetoone') || appContentLower.includes('1:1') || appContentLower.includes('one_to_one');
    const hasManyToMany = appContentLower.includes('many-to-many') || appContentLower.includes('manytomany') || appContentLower.includes('m:n') || appContentLower.includes('many_to_many');

    expect(hasOneToMany, 'Application should support one-to-many relationships').toBe(true);
    expect(hasOneToOne, 'Application should support one-to-one relationships').toBe(true);
    expect(hasManyToMany, 'Application should support many-to-many relationships').toBe(true);
  });

  it('should enforce foreign key constraints in one-to-many mock data generation', () => {
    // Round 17: "一对多关系，生成子表数据时要能参考父表已有模拟数据，至少让外键列落到父表主键范围内"
    const hasFkConstraint = (appContentLower.includes('foreign') || appContentLower.includes('fk') || appContentLower.includes('parent')) &&
      (appContentLower.includes('key') || appContentLower.includes('reference') || appContentLower.includes('range'));
    const hasParentReference = appContentLower.includes('parent') &&
      (appContentLower.includes('data') || appContentLower.includes('primary') || appContentLower.includes('id'));
    expect(
      hasFkConstraint || hasParentReference,
      'Mock data generation should enforce foreign key constraints for one-to-many relationships'
    ).toBe(true);
  });

  it('should handle parent table without data: guide or auto-generate', () => {
    // Round 17: "如果父表还没有数据，要给出引导或允许先自动生成父表"
    const hasParentGuidance = appContentLower.includes('parent') &&
      (appContentLower.includes('auto') || appContentLower.includes('generat') ||
       appContentLower.includes('first') || appContentLower.includes('guid') ||
       appContentLower.includes('no data') || appContentLower.includes('require'));
    expect(
      hasParentGuidance,
      'Application should guide user or auto-generate parent data when parent has no mock data'
    ).toBe(true);
  });

  it('should prevent duplicate associations in one-to-one relationship data', () => {
    // Round 17: "一对一关系，不要生成出明显冲突的大量重复关联"
    const hasOneToOneConstraint = (appContentLower.includes('one-to-one') || appContentLower.includes('1:1') || appContentLower.includes('one_to_one')) &&
      (appContentLower.includes('unique') || appContentLower.includes('duplicate') || appContentLower.includes('conflict') || appContentLower.includes('repeat'));
    const hasUniqueEnforcement = appContentLower.includes('unique') &&
      (appContentLower.includes('foreign') || appContentLower.includes('parent') || appContentLower.includes('relation'));
    expect(
      hasOneToOneConstraint || hasUniqueEnforcement,
      'One-to-one relationship data should not have duplicate associations'
    ).toBe(true);
  });

  it('should explicitly handle many-to-many relationships, not silently ignore', () => {
    // Round 17: "多对多先不用做到很深，但至少要说明当前如何处理，不要默默忽略"
    const hasManyToManyHandling = (appContentLower.includes('many-to-many') || appContentLower.includes('many_to_many') || appContentLower.includes('m:n')) &&
      (appContentLower.includes('junction') || appContentLower.includes('pivot') ||
       appContentLower.includes('not support') || appContentLower.includes('skip') ||
       appContentLower.includes('handle') || appContentLower.includes('process') ||
       appContentLower.includes('ignore') || appContentLower.includes('note'));
    expect(
      hasManyToManyHandling,
      'Application should explicitly handle or explain many-to-many relationship data generation'
    ).toBe(true);
  });

  it('should surface relationship risk warnings in problem list after data generation', () => {
    // Round 17: "问题列表也要同步反映潜在风险，比如引用列可能不唯一、父表缺主键之类"
    const hasRiskWarnings = (appContentLower.includes('issue') || appContentLower.includes('problem') || appContentLower.includes('warning') || appContentLower.includes('risk')) &&
      (appContentLower.includes('unique') || appContentLower.includes('primary') || appContentLower.includes('key') ||
       appContentLower.includes('reference') || appContentLower.includes('foreign'));
    expect(
      hasRiskWarnings,
      'Problem list should surface relationship risk warnings (non-unique references, missing primary keys)'
    ).toBe(true);
  });

  it('should enforce primary key uniqueness in generated mock data', () => {
    // Round 16: "主键字段必须尽量保证唯一"
    const hasPkUniqueness = appContentLower.includes('primary') &&
      (appContentLower.includes('unique') || appContentLower.includes('increment') || appContentLower.includes('distinct'));
    expect(
      hasPkUniqueness,
      'Mock data generation should enforce primary key uniqueness'
    ).toBe(true);
  });

  it('should enforce non-null constraint in generated mock data', () => {
    // Round 16: "被标记为非空的字段不能生成空值"
    const hasNonNullEnforcement = (appContentLower.includes('non-null') || appContentLower.includes('not null') || appContentLower.includes('nullable') || appContentLower.includes('required')) &&
      (appContentLower.includes('generat') || appContentLower.includes('mock') || appContentLower.includes('data'));
    expect(
      hasNonNullEnforcement,
      'Mock data generation should enforce non-null constraints'
    ).toBe(true);
  });

  it('should validate row count limits (1 to 1000)', () => {
    // Round 16: "生成行数，范围限制在 1 到 1000"
    const hasRowLimit = appContentLower.includes('1000') ||
      (appContentLower.includes('row') && (appContentLower.includes('limit') || appContentLower.includes('max') || appContentLower.includes('range')));
    expect(
      hasRowLimit,
      'Mock data generation should validate row count within 1-1000 range'
    ).toBe(true);
  });
});

