  it('should produce deterministic mock data so WHERE and LIMIT results are stably verifiable', async () => {
    const rows = 12;
    const payload = {
      name: `vt-predict-${Date.now()}`,
      entities: [
        {
          name: 'events',
          fields: [
            { name: 'id', type: 'integer', primaryKey: true, mockRule: { type: 'increment', start: 1, step: 1 } },
            { name: 'tag', type: 'varchar', length: 10, mockRule: { type: 'sequence', values: ['A', 'B', 'C'] } }
          ]
        }
      ]
    };

    let projectId;
    try {
      const create = await request('/api/projects', { method: 'POST', body: JSON.stringify(payload) });
      expect([200, 201]).toContain(create.res.status);
      projectId = create.body.id || create.body.projectId || create.body.data?.id;
      expect(projectId).toBeTruthy();

      const gen = await request(`/api/projects/${projectId}/mock-data/generate`, { method: 'POST', body: JSON.stringify({ entity: 'events', rows }) });
      expect([200, 201]).toContain(gen.res.status);
      const generated = gen.body.rows || gen.body.data?.rows || [];
      expect(generated.length).toBe(rows);

      const qA = await request(`/api/projects/${projectId}/sql/execute`, { method: 'POST', body: JSON.stringify({ query: "SELECT * FROM events WHERE tag = 'A'" }) });
      expect(qA.res.status).toBe(200);
      const rowsA = qA.body.rows || qA.body.data?.rows || [];
      expect(rowsA.length).toBe(4);
      for (const row of rowsA) expect(row.tag).toBe('A');

      const qBLimit = await request(`/api/projects/${projectId}/sql/execute`, { method: 'POST', body: JSON.stringify({ query: "SELECT * FROM events WHERE tag = 'B' LIMIT 2" }) });
