describe('table_sort_filter_and_pagination_results_correct', () => {
  it('should support pagination, sorting by type, filtering, totalPages, empty filter result, and preserve original query/count through view changes', async () => {
    const suffix = `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
    const entityName = `records_${suffix.replace(/[^a-zA-Z0-9_]/g, '_')}`;
    const payload = {
      name: `vt-table-view-${suffix}`,
      entities: [
        {
          name: entityName,
          fields: [
            { name: 'id', type: 'integer', primaryKey: true, mockRule: { type: 'increment', start: 1, step: 1 } },
            { name: 'label', type: 'varchar', length: 10, mockRule: { type: 'sequence', values: ['c', 'a', 'b'] } },
            { name: 'created_at', type: 'datetime', mockRule: { type: 'datetime' } }
          ]
        }
      ]
    };

    let projectId;
    try {
      const create = await request('/api/projects', { method: 'POST', body: JSON.stringify(payload) });
      expect([200, 201]).toContain(create.res.status);
      projectId = create.body?.id || create.body?.projectId || create.body?.data?.id;
      expect(projectId).toBeTruthy();

      // Generate 9 rows of mock data
      const gen = await request(`/api/projects/${projectId}/mock-data/generate`, {
        method: 'POST',
        body: JSON.stringify({ entity: entityName, rows: 9 })
      });
      expect([200, 201]).toContain(gen.res.status);

      // === Step 1: Execute original query to get baseline total ===
      const originalQuery = `SELECT * FROM ${entityName}`;
      const baseExec = await request(`/api/projects/${projectId}/sql/execute`, {
        method: 'POST',
        body: JSON.stringify({ query: originalQuery })
      });
      expect(baseExec.res.status).toBe(200);
      const baseRows = baseExec.body?.rows || baseExec.body?.data?.rows || [];
      const baseTotal = baseExec.body?.total || baseExec.body?.count || baseExec.body?.data?.total || baseRows.length;
      expect(baseTotal).toBe(9);

      // === Step 2: Paginate with page=1, pageSize=3, sort by id desc ===
      const page1 = await request(`/api/projects/${projectId}/sql/execute`, {
        method: 'POST',
        body: JSON.stringify({
          query: originalQuery,
          view: { page: 1, pageSize: 3, sort: [{ field: 'id', order: 'desc' }] }
        })
      });
      expect(page1.res.status).toBe(200);
      const rows1 = page1.body?.rows || page1.body?.data?.rows || [];
      const total1 = page1.body?.total || page1.body?.count || page1.body?.data?.total || 0;
      expect(rows1.length).toBe(3);
      // Original total must NOT change due to front-end pagination
      expect(total1).toBe(9);
      // First row with desc sort should be id=9
      expect(rows1[0]?.id).toBe(9);
      // Verify totalPages: 9 rows / pageSize 3 = 3 pages
      const totalPages1 = page1.body?.totalPages || page1.body?.data?.totalPages || Math.ceil(total1 / 3);
      expect(totalPages1).toBe(3);
      // Original query text should be preserved - must exist
      const returnedQuery1 = page1.body?.query || page1.body?.data?.query;
      expect(returnedQuery1).toBeTruthy();
      expect(returnedQuery1).toContain('SELECT');
      expect(returnedQuery1).toContain(entityName);

      // === Step 3: Change pageSize to 5, verify totalPages updates ===
      const page2 = await request(`/api/projects/${projectId}/sql/execute`, {
        method: 'POST',
        body: JSON.stringify({
          query: originalQuery,
          view: { page: 2, pageSize: 5, sort: [{ field: 'id', order: 'desc' }] }
        })
      });
      expect(page2.res.status).toBe(200);
      const rows2 = page2.body?.rows || page2.body?.data?.rows || [];
      const total2 = page2.body?.total || page2.body?.count || page2.body?.data?.total || 0;
      expect(rows2.length).toBe(4);
      expect(total2).toBe(9);
      // Verify totalPages: 9 rows / pageSize 5 = 2 pages
      const totalPages2 = page2.body?.totalPages || page2.body?.data?.totalPages || Math.ceil(total2 / 5);
      expect(totalPages2).toBe(2);

      // === Step 4: Filter by label='a' ===
      const filtered = await request(`/api/projects/${projectId}/sql/execute`, {
        method: 'POST',
        body: JSON.stringify({
          query: originalQuery,
          view: { page: 1, pageSize: 10, filters: [{ field: 'label', op: 'eq', value: 'a' }], sort: [{ field: 'label', order: 'asc' }] }
        })
      });
      expect(filtered.res.status).toBe(200);
      const filteredRows = filtered.body?.rows || filtered.body?.data?.rows || [];
      expect(filteredRows.length).toBeGreaterThan(0);
      for (const row of filteredRows) {
        expect(row.label).toBe('a');
      }
      // Query text should still be preserved
      const filteredQuery = filtered.body?.query || filtered.body?.data?.query;
