        dialect: 'mysql',
      });
      expect([200, 201], `create project status expected 200/201, got ${createProject.res.status}`).toContain(createProject.res.status);
      expect(createProject.data && typeof createProject.data === 'object', 'create project response body should be an object').toBeTruthy();
      projectId = createProject.data.id || createProject.data.projectId;
      expect(projectId, `project id should exist in response, got ${JSON.stringify(createProject.data)}`).toBeTruthy();

      const createEntity = await request('POST', `/api/projects/${projectId}/entities`, {
        name: `users_${suffix.replace(/[^a-zA-Z0-9_]/g, '_')}`,
        fields: [
