      const exportWithoutData = await request('POST', `/api/projects/${projectId}/entities/${entityId}/mock-data/export`, {
        format: 'table-text',
        scope: 'all',
      });
      expect(
        [400, 404, 409, 422],
        `export without mock data should be rejected, got status ${exportWithoutData.res.status} and body ${JSON.stringify(exportWithoutData.data)}`
      ).toContain(exportWithoutData.res.status);

      const seedMockData = await request('POST', `/api/projects/${projectId}/entities/${entityId}/mock-data/generate`, {
