          { id: 2, name: 'Bob', status: 'inactive' },
          { id: 3, name: 'Carol', status: 'active' },
          { id: 4, name: 'David', status: 'inactive' },
          { id: 5, name: 'Eve', status: 'active' },
          { id: 6, name: 'Frank', status: 'inactive' },
          { id: 7, name: 'Grace', status: 'active' },
          { id: 8, name: 'Heidi', status: 'inactive' },
          { id: 9, name: 'Ivan', status: 'active' },
          { id: 10, name: 'Judy', status: 'inactive' },
          { id: 11, name: 'Mallory', status: 'active' },
          { id: 12, name: 'Niaj', status: 'inactive' },
        ],
      });
      expect([200, 201], `generate mock data status expected 200/201, got ${seedMockData.res.status}`).toContain(seedMockData.res.status);

      const exportFiltered = await request('POST', `/api/projects/${projectId}/entities/${entityId}/mock-data/export`, {
        format: 'table-text',
        scope: 'filtered',
        filter: { status: 'active' },
        pagination: { page: 1, pageSize: 2 },
      });
      expect([200, 201], `filtered export status expected 200/201, got ${exportFiltered.res.status}`).toContain(exportFiltered.res.status);
      const filteredText = typeof exportFiltered.data === 'string' ? exportFiltered.data : exportFiltered.text;
      expect(filteredText, 'filtered export text should not be empty').toBeTruthy();
      expect(filteredText.includes('id') && filteredText.includes('name') && filteredText.includes('status'), `filtered export should include header row, got: ${filteredText}`).toBe(true);
      expect(filteredText.includes('Alice') || filteredText.includes('Carol') || filteredText.includes('Eve'), `filtered export should include active rows, got: ${filteredText}`).toBe(true);
      expect(filteredText.includes('Bob') || filteredText.includes('David') || filteredText.includes('Frank'), `filtered export should not include inactive rows, got: ${filteredText}`).toBe(false);

      const exportAll = await request('POST', `/api/projects/${projectId}/entities/${entityId}/mock-data/export`, {
        format: 'table-text',
        scope: 'all',
        filter: { status: 'active' },
        pagination: { page: 1, pageSize: 2 },
      });
      expect([200, 201], `full export status expected 200/201, got ${exportAll.res.status}`).toContain(exportAll.res.status);
      const allText = typeof exportAll.data === 'string' ? exportAll.data : exportAll.text;
      expect(allText, 'full export text should not be empty').toBeTruthy();
      expect(allText.includes('id') && allText.includes('name') && allText.includes('status'), `full export should include header row, got: ${allText}`).toBe(true);
      expect(allText.includes('Alice') && allText.includes('Bob') && allText.includes('Mallory') && allText.includes('Niaj'), `full export should include rows across the full dataset rather than only current filtered page, got: ${allText}`).toBe(true);
    } finally {
      if (projectId) await safeDeleteProject(projectId);
    }
  });
});

