function sleep(ms) { return new Promise(r => setTimeout(r, ms)); }

describe('snapshot_save_limit_and_restore_full_state', () => {
  it('should validate snapshot name rules, enforce max 20 snapshots, restore full state including mock data and SQL preview, and coexist with undo/redo and export/import', async () => {
    const suffix = `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
    const entityName = `orders_${suffix.replace(/[^a-zA-Z0-9_]/g, '_')}`;
    let projectId;

    try {
      // Create project
      const createProject = await request('POST', '/api/projects', { name: `snapshot-${suffix}`, dialect: 'mysql' });
      expect([200, 201]).toContain(createProject.res.status);
      projectId = createProject.data?.id || createProject.data?.projectId;
      expect(projectId).toBeTruthy();

      // === Snapshot name validation ===
      const invalidEmpty = await request('POST', `/api/projects/${projectId}/snapshots`, { name: '' });
      expect([400, 422]).toContain(invalidEmpty.res.status);

      const invalidLong = await request('POST', `/api/projects/${projectId}/snapshots`, { name: 'x'.repeat(51) });
      expect([400, 422]).toContain(invalidLong.res.status);

      // Exactly 50 chars should be valid
      const valid50 = await request('POST', `/api/projects/${projectId}/snapshots`, { name: 'a'.repeat(50) });
      expect([200, 201]).toContain(valid50.res.status);

      // === Save empty project snapshot ===
      const emptySnapshot = await request('POST', `/api/projects/${projectId}/snapshots`, { name: 'blank version' });
      expect([200, 201]).toContain(emptySnapshot.res.status);
      expect(emptySnapshot.data).toBeTruthy();
      const emptySnapName = emptySnapshot.data?.name || emptySnapshot.data?.data?.name;
      expect(emptySnapName).toBe('blank version');

      // Verify empty snapshot is identifiable as blank in list
      const listAfterEmpty = await request('GET', `/api/projects/${projectId}/snapshots`);
      expect(listAfterEmpty.res.status).toBe(200);
      const snapList = Array.isArray(listAfterEmpty.data) ? listAfterEmpty.data : (listAfterEmpty.data?.items || listAfterEmpty.data?.snapshots || []);
      const blankSnap = snapList.find(s => s.name === 'blank version');
      expect(blankSnap).toBeTruthy();
      // Should have a clear indication it's empty (entityCount === 0 or empty === true)
      const isEmptyIdentifiable = blankSnap.empty === true || blankSnap.isEmpty === true || blankSnap.entityCount === 0;
      expect(isEmptyIdentifiable, `Empty project snapshot should be identifiable as blank. Got: ${JSON.stringify(blankSnap)}`).toBe(true);

      // === Set up project state for meaningful snapshot ===
      const createTheme = await request('POST', `/api/projects/${projectId}/theme-views`, { name: `ThemeA_${suffix}` });
      expect([200, 201]).toContain(createTheme.res.status);
      const themeId = createTheme.data?.id || createTheme.data?.themeViewId;
      expect(themeId).toBeTruthy();

      const createEntity = await request('POST', `/api/projects/${projectId}/entities`, {
        name: entityName,
        x: 100, y: 200,
        fields: [
          { name: 'id', type: 'int', primaryKey: true },
          { name: 'amount', type: 'decimal', length: 10 },
        ],
      });
      expect([200, 201]).toContain(createEntity.res.status);
      const entityId = createEntity.data?.id || createEntity.data?.entityId;
      expect(entityId).toBeTruthy();

      const updateLayout = await request('PUT', `/api/projects/${projectId}/theme-views/${themeId}/layout`, {
        positions: [{ entityId, x: 333, y: 444 }],
      });
      expect([200, 204]).toContain(updateLayout.res.status);

      // === Generate mock data before snapshot ===
      const genMock = await request('POST', `/api/projects/${projectId}/mock-data/generate`, {
        entity: entityName,
        rows: 5,
        fields: {
          id: { generator: 'increment', start: 1, step: 1 },
          amount: { generator: 'increment', start: 100, step: 10 },
        },
      });
      expect([200, 201]).toContain(genMock.res.status);

      // Verify mock data was generated
      const getMockBefore = await request('GET', `/api/projects/${projectId}/mock-data?entity=${entityName}`);
      expect(getMockBefore.res.status).toBe(200);
      const mockRowsBefore = getMockBefore.data?.rows || getMockBefore.data?.data?.rows || [];
      expect(mockRowsBefore.length).toBe(5);

      const queryText = `SELECT * FROM ${entityName} LIMIT 1`;
      const setQuery = await request('PUT', `/api/projects/${projectId}/query`, { text: queryText });
      expect([200, 204]).toContain(setQuery.res.status);

      const setDialect = await request('PUT', `/api/projects/${projectId}/dialect`, { dialect: 'postgres' });
      expect([200, 204]).toContain(setDialect.res.status);

      // === Capture SQL preview before snapshot ===
      const sqlPreviewBefore = await request('GET', `/api/projects/${projectId}/sql-preview`);
      expect(sqlPreviewBefore.res.status).toBe(200);
      const sqlTextBefore = typeof sqlPreviewBefore.data === 'string' ? sqlPreviewBefore.data : (sqlPreviewBefore.data?.sql || sqlPreviewBefore.data?.content || JSON.stringify(sqlPreviewBefore.data));
      expect(sqlTextBefore).toContain(entityName);

      // Save meaningful snapshot
      const save1 = await request('POST', `/api/projects/${projectId}/snapshots`, { name: 'release' });
      expect([200, 201]).toContain(save1.res.status);
      const snap1Id = save1.data?.id || save1.data?.snapshotId;
      expect(snap1Id).toBeTruthy();

      // === Duplicate name with different timestamp ===
      await sleep(50);
      const save2 = await request('POST', `/api/projects/${projectId}/snapshots`, { name: 'release' });
      expect([200, 201]).toContain(save2.res.status);
      const snap2Id = save2.data?.id || save2.data?.snapshotId;
      expect(snap2Id).toBeTruthy();
      expect(String(snap2Id)).not.toBe(String(snap1Id));

      // Verify duplicate snapshots have different timestamps
      const listForDupes = await request('GET', `/api/projects/${projectId}/snapshots`);
      expect(listForDupes.res.status).toBe(200);
      const allSnaps = Array.isArray(listForDupes.data) ? listForDupes.data : (listForDupes.data?.items || listForDupes.data?.snapshots || []);
      const releaseSnaps = allSnaps.filter(s => s.name === 'release');
      expect(releaseSnaps.length).toBeGreaterThanOrEqual(2);
      if (releaseSnaps.length >= 2) {
        const time1 = releaseSnaps[0].createdAt || releaseSnaps[0].savedAt || releaseSnaps[0].timestamp;
        const time2 = releaseSnaps[1].createdAt || releaseSnaps[1].savedAt || releaseSnaps[1].timestamp;
        expect(time1).toBeTruthy();
        expect(time2).toBeTruthy();
        if (time1 && time2) {
          expect(time1).not.toBe(time2);
        }
      }

      // === Fill up to 20 snapshots, then test limit ===
      const remaining = 20 - allSnaps.length;
      for (let i = 0; i < remaining; i++) {
        const s = await request('POST', `/api/projects/${projectId}/snapshots`, { name: `fill-${i}` });
        expect([200, 201]).toContain(s.res.status);
      }

      // 21st snapshot should fail
      const overLimit = await request('POST', `/api/projects/${projectId}/snapshots`, { name: 'snap-over-limit' });
      expect([400, 409, 422]).toContain(overLimit.res.status);
      const overLimitText = JSON.stringify(overLimit.data).toLowerCase();
      expect(
        overLimitText.includes('limit') || overLimitText.includes('max') || overLimitText.includes('clean') || overLimitText.includes('full') || overLimitText.includes('20') || overLimitText.includes('exceed'),
        `Over-limit response should mention limit/cleanup. Got: ${overLimitText}`
      ).toBe(true);

      // === Modify state, then restore snapshot ===
      await request('PUT', `/api/projects/${projectId}/dialect`, { dialect: 'mysql' });
      await request('PUT', `/api/projects/${projectId}/query`, { text: 'SELECT 1' });
      await request('PUT', `/api/projects/${projectId}/theme-views/${themeId}/layout`, {
        positions: [{ entityId, x: 1, y: 2 }],
      });
      // Delete mock data or modify it
      const genMock2 = await request('POST', `/api/projects/${projectId}/mock-data/generate`, {
        entity: entityName,
        rows: 2,
      });
      // Don't require success - just modify state

      const restore = await request('POST', `/api/projects/${projectId}/snapshots/${snap1Id}/restore`);
      expect([200, 204]).toContain(restore.res.status);

      // === Verify restored state ===
      const getProject = await request('GET', `/api/projects/${projectId}`);
      expect(getProject.res.status).toBe(200);
      expect(getProject.data).toBeTruthy();

      // Dialect should be restored to postgres
      const restoredDialect = getProject.data?.dialect || getProject.data?.data?.dialect;
      expect(restoredDialect).toBe('postgres');

      // Query text should be restored
      const restoredQuery = getProject.data?.query || getProject.data?.queryText || getProject.data?.data?.query;
      expect(restoredQuery).toBeTruthy();
      expect(restoredQuery).toContain(entityName);
      expect(restoredQuery).toContain('LIMIT 1');

      // Entity should still exist
      const entities = getProject.data?.entities || getProject.data?.data?.entities || [];
      const entityExists = Array.isArray(entities) ? entities.some(e => e.name === entityName || e.name?.includes('orders_')) : JSON.stringify(getProject.data).includes(entityName);
      expect(entityExists).toBe(true);

      // Theme view layout should be restored
      const getLayout = await request('GET', `/api/projects/${projectId}/theme-views/${themeId}/layout`);
      expect(getLayout.res.status).toBe(200);
      const positions = getLayout.data?.positions || getLayout.data?.data?.positions || [];
      expect(positions.length).toBeGreaterThan(0);
      const pos = positions.find(p => String(p.entityId) === String(entityId));
      expect(pos).toBeTruthy();
      expect(pos.x).toBe(333);
      expect(pos.y).toBe(444);

      // === Verify mock data restored ===
      const getMockAfter = await request('GET', `/api/projects/${projectId}/mock-data?entity=${entityName}`);
      expect(getMockAfter.res.status).toBe(200);
      const mockRowsAfter = getMockAfter.data?.rows || getMockAfter.data?.data?.rows || [];
      expect(mockRowsAfter.length).toBe(5);

      // === Verify SQL preview restored ===
      const sqlPreviewAfter = await request('GET', `/api/projects/${projectId}/sql-preview`);
      expect(sqlPreviewAfter.res.status).toBe(200);
      const sqlTextAfter = typeof sqlPreviewAfter.data === 'string' ? sqlPreviewAfter.data : (sqlPreviewAfter.data?.sql || sqlPreviewAfter.data?.content || JSON.stringify(sqlPreviewAfter.data));
      expect(sqlTextAfter).toContain(entityName);

      // === Verify snapshot doesn't break undo/redo ===
      const tempEntityName = `temp_entity_${suffix.replace(/[^a-zA-Z0-9_]/g, '_')}`;
      const editAfterRestore = await request('POST', `/api/projects/${projectId}/entities`, {
        name: tempEntityName,
        fields: [{ name: 'tid', type: 'int', primaryKey: true }],
      });
      expect([200, 201]).toContain(editAfterRestore.res.status);

      // Undo should work and actually remove the temp entity
      const undoRes = await request('POST', `/api/projects/${projectId}/undo`);
      expect([200, 204]).toContain(undoRes.res.status);

      // Verify undo effect: temp entity should be gone
      const afterUndo = await request('GET', `/api/projects/${projectId}`);
      expect(afterUndo.res.status).toBe(200);
