describe('theme_view_crud_constraints_and_project_scope_behavior', () => {
  it('should support theme view CRUD with constraints and keep SQL/mock/query scoped to full project model', async () => {
    const suffix = `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
    const entityName1 = `customers_${suffix.replace(/[^a-zA-Z0-9_]/g, '_')}`;
    const entityName2 = `orders_${suffix.replace(/[^a-zA-Z0-9_]/g, '_')}`;
    let projectId;

    try {
      // Create project
      const createProject = await request('POST', '/api/projects', { name: `theme-${suffix}`, dialect: 'mysql' });
      expect([200, 201]).toContain(createProject.res.status);
      projectId = createProject.data?.id || createProject.data?.projectId;
      expect(projectId).toBeTruthy();

      // === Name validation: empty ===
      const invalidEmpty = await request('POST', `/api/projects/${projectId}/theme-views`, { name: '' });
      expect([400, 422]).toContain(invalidEmpty.res.status);

      // === Name validation: pure spaces ===
      const invalidSpaces = await request('POST', `/api/projects/${projectId}/theme-views`, { name: '   ' });
      expect([400, 422]).toContain(invalidSpaces.res.status);

      // === Name validation: too long (>30 chars per Round 21) ===
      const invalidLong = await request('POST', `/api/projects/${projectId}/theme-views`, { name: 'a'.repeat(31) });
      expect([400, 422]).toContain(invalidLong.res.status);

      // Exactly 30 chars should be valid
      const valid30 = await request('POST', `/api/projects/${projectId}/theme-views`, { name: 'b'.repeat(30) });
      expect([200, 201]).toContain(valid30.res.status);
      const valid30Id = valid30.data?.id || valid30.data?.themeViewId;

      // === Create theme view A ===
      const themeAName = `DomainA_${suffix}`;
      const createA = await request('POST', `/api/projects/${projectId}/theme-views`, { name: themeAName });
      expect([200, 201]).toContain(createA.res.status);
      const aId = createA.data?.id || createA.data?.themeViewId;
      expect(aId).toBeTruthy();
      // Verify returned name
      const aName = createA.data?.name || createA.data?.data?.name;
      expect(aName).toBe(themeAName);

      // === Duplicate name rejected ===
      const duplicate = await request('POST', `/api/projects/${projectId}/theme-views`, { name: themeAName });
      expect([400, 409, 422]).toContain(duplicate.res.status);

      // === Create theme view B ===
      const themeBName = `DomainB_${suffix}`;
      const createB = await request('POST', `/api/projects/${projectId}/theme-views`, { name: themeBName });
      expect([200, 201]).toContain(createB.res.status);
      const bId = createB.data?.id || createB.data?.themeViewId;
      expect(bId).toBeTruthy();

      // === Rename B and verify ===
      const newBName = `DomainB2_${suffix}`;
      const renameB = await request('PUT', `/api/projects/${projectId}/theme-views/${bId}`, { name: newBName });
      expect([200, 204]).toContain(renameB.res.status);

      // Verify rename took effect
      const getB = await request('GET', `/api/projects/${projectId}/theme-views/${bId}`);
      expect(getB.res.status).toBe(200);
      const bNameAfter = getB.data?.name || getB.data?.data?.name;
      expect(bNameAfter).toBe(newBName);

      // === Rename to existing name should be rejected ===
      const renameConflict = await request('PUT', `/api/projects/${projectId}/theme-views/${bId}`, { name: themeAName });
      expect([400, 409, 422]).toContain(renameConflict.res.status);

      // === Create entities (project-scoped) ===
      const createEntity1 = await request('POST', `/api/projects/${projectId}/entities`, {
        name: entityName1,
        fields: [
          { name: 'id', type: 'int', primaryKey: true },
          { name: 'name', type: 'varchar', length: 50 },
        ],
      });
      expect([200, 201]).toContain(createEntity1.res.status);
      const entity1Id = createEntity1.data?.id || createEntity1.data?.entityId;
      expect(entity1Id).toBeTruthy();

      const createEntity2 = await request('POST', `/api/projects/${projectId}/entities`, {
        name: entityName2,
        fields: [
          { name: 'id', type: 'int', primaryKey: true },
          { name: 'customer_id', type: 'int' },
        ],
      });
      expect([200, 201]).toContain(createEntity2.res.status);
      const entity2Id = createEntity2.data?.id || createEntity2.data?.entityId;
      expect(entity2Id).toBeTruthy();

      // Generate mock data for entity2
      let genMock = await request('POST', `/api/projects/${projectId}/mock-data/generate`, {
        entity: entityName2,
        rows: 5,
      });
      if (![200, 201].includes(genMock.res.status)) {
        genMock = await request('POST', `/api/projects/${projectId}/entities/${entity2Id}/mock-data/generate`, {
          rows: 5,
        });
      }
      expect([200, 201]).toContain(genMock.res.status);

      const queryText = `SELECT * FROM ${entityName2} LIMIT 2`;
      const setQuery = await request('PUT', `/api/projects/${projectId}/query`, { text: queryText });
      expect([200, 204]).toContain(setQuery.res.status);

      // === Get SQL preview BEFORE switching theme view ===
      const sqlPreviewBefore = await request('GET', `/api/projects/${projectId}/sql-preview`);
      expect(sqlPreviewBefore.res.status).toBe(200);
      const sqlTextBefore = typeof sqlPreviewBefore.data === 'string' ? sqlPreviewBefore.data : (sqlPreviewBefore.data?.sql || sqlPreviewBefore.data?.content || JSON.stringify(sqlPreviewBefore.data));
      // SQL preview must include BOTH entities (whole project, not just one theme view)
      expect(sqlTextBefore).toContain(entityName1.substring(0, 10));
      expect(sqlTextBefore).toContain(entityName2.substring(0, 10));

      // === Switch to theme view B ===
      const switchTheme = await request('PUT', `/api/projects/${projectId}/theme-views/current`, { themeViewId: bId });
      expect([200, 204]).toContain(switchTheme.res.status);

      // === Get SQL preview AFTER switching - should be identical (project-scoped) ===
      const sqlPreviewAfter = await request('GET', `/api/projects/${projectId}/sql-preview`);
      expect(sqlPreviewAfter.res.status).toBe(200);
      const sqlTextAfter = typeof sqlPreviewAfter.data === 'string' ? sqlPreviewAfter.data : (sqlPreviewAfter.data?.sql || sqlPreviewAfter.data?.content || JSON.stringify(sqlPreviewAfter.data));
      expect(sqlTextAfter).toContain(entityName1.substring(0, 10));
      expect(sqlTextAfter).toContain(entityName2.substring(0, 10));

      // === Verify mock data is still accessible after switching theme view ===
      let mockDataAfterSwitch = await request('GET', `/api/projects/${projectId}/mock-data?entity=${entityName2}`);
      if (mockDataAfterSwitch.res.status !== 200) {
        mockDataAfterSwitch = await request('POST', `/api/projects/${projectId}/mock-data`, {
          entity: entityName2,
          view: { page: 1, pageSize: 10 }
        });
      }
      expect(mockDataAfterSwitch.res.status).toBe(200);
      const mockRowsAfterSwitch = mockDataAfterSwitch.data?.rows || mockDataAfterSwitch.data?.data?.rows || [];
      expect(mockRowsAfterSwitch.length).toBe(5);

      // === Query execution should work with project-scoped model and verify result content ===
      let queryExec = await request('POST', `/api/projects/${projectId}/sql/execute`, { query: queryText });
      if (queryExec.res.status !== 200) {
        queryExec = await request('POST', `/api/projects/${projectId}/query/execute`, { text: queryText });
      }
      expect(queryExec.res.status).toBe(200);
      const queryRows = queryExec.data?.rows || queryExec.data?.data?.rows || [];
      // LIMIT 2 should return at most 2 rows
      expect(queryRows.length).toBeLessThanOrEqual(2);
      // Verify columns match entity2's fields
      if (queryRows.length > 0) {
        const firstRow = queryRows[0];
        expect(firstRow).toHaveProperty('id');
        expect(firstRow).toHaveProperty('customer_id');
      }

      // === Delete theme views and test "at least 1" constraint ===
      const listAll = await request('GET', `/api/projects/${projectId}/theme-views`);
      expect(listAll.res.status).toBe(200);
      const allViews = Array.isArray(listAll.data) ? listAll.data : (listAll.data?.items || listAll.data?.themeViews || []);
      const allViewIds = allViews.map(v => v.id || v.themeViewId);

      // Delete all but one
      for (let i = 0; i < allViewIds.length - 1; i++) {
        const delRes = await request('DELETE', `/api/projects/${projectId}/theme-views/${allViewIds[i]}`);
        expect([200, 204]).toContain(delRes.res.status);
      }

      // Try to delete the last remaining one - should be rejected
      const lastId = allViewIds[allViewIds.length - 1];
      const deleteLast = await request('DELETE', `/api/projects/${projectId}/theme-views/${lastId}`);
      expect([400, 409, 422]).toContain(deleteLast.res.status);

      // Verify at least one still exists
      const listFinal = await request('GET', `/api/projects/${projectId}/theme-views`);
      expect(listFinal.res.status).toBe(200);
      const finalViews = Array.isArray(listFinal.data) ? listFinal.data : (listFinal.data?.items || listFinal.data?.themeViews || []);
      expect(finalViews.length).toBeGreaterThanOrEqual(1);

    } finally {
      if (projectId) await safeDeleteProject(projectId);
    }
  });
});

