describe('cross_flow_state_persist_through_export_refresh_import', () => {
  it('should preserve model, theme layouts, fixed-sequence mock data, query, and dialect through full roundtrip', async () => {
    const suffix = `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
    const entityName = `products_${suffix.replace(/[^a-zA-Z0-9_]/g, '_')}`;
    let projectId;
    let importedProjectId;
    let legacyId;

    try {
      // === Create project with postgres dialect ===
      const createProject = await request('POST', '/api/projects', { name: `cross-flow-${suffix}`, dialect: 'postgres' });
      expect([200, 201]).toContain(createProject.res.status);
      projectId = createProject.data?.id || createProject.data?.projectId;
      expect(projectId).toBeTruthy();

      // === Create two theme views ===
      const theme1 = await request('POST', `/api/projects/${projectId}/theme-views`, { name: `Model_${suffix}` });
      expect([200, 201]).toContain(theme1.res.status);
      const theme1Id = theme1.data?.id || theme1.data?.themeViewId;
      expect(theme1Id).toBeTruthy();

      const theme2 = await request('POST', `/api/projects/${projectId}/theme-views`, { name: `Layout_${suffix}` });
      expect([200, 201]).toContain(theme2.res.status);
      const theme2Id = theme2.data?.id || theme2.data?.themeViewId;
      expect(theme2Id).toBeTruthy();

      // === Create entity with fields ===
      const entity = await request('POST', `/api/projects/${projectId}/entities`, {
        name: entityName,
        fields: [
          { name: 'id', type: 'int', primaryKey: true },
          { name: 'label', type: 'varchar', length: 50 },
        ],
      });
      expect([200, 201]).toContain(entity.res.status);
      const entityId = entity.data?.id || entity.data?.entityId;
      expect(entityId).toBeTruthy();

      // === Set fixed-sequence mock data rules ===
      const setRule = await request('PUT', `/api/projects/${projectId}/entities/${entityId}/mock-data/rules`, {
        count: 6,
        fields: {
          id: { generator: 'increment', start: 1, step: 1 },
          label: { generator: 'sequence', values: ['Alpha', 'Beta', 'Gamma'] }
        },
      });
      expect([200, 204]).toContain(setRule.res.status);

      // === Generate mock data using fixed sequence ===
      const genData = await request('POST', `/api/projects/${projectId}/entities/${entityId}/mock-data/generate`, {
        rows: 6,
        fields: {
          id: { generator: 'increment', start: 1, step: 1 },
          label: { generator: 'sequence', values: ['Alpha', 'Beta', 'Gamma'] }
        },
      });
      expect([200, 201]).toContain(genData.res.status);

      // Verify generated data
      const getMockBefore = await request('GET', `/api/projects/${projectId}/mock-data?entity=${entityName}`);
      expect(getMockBefore.res.status).toBe(200);
      const mockRowsBefore = getMockBefore.data?.rows || getMockBefore.data?.data?.rows || [];
      expect(mockRowsBefore.length).toBe(6);
      // Verify fixed sequence cycle: Alpha, Beta, Gamma, Alpha, Beta, Gamma
      const expectedLabels = ['Alpha', 'Beta', 'Gamma', 'Alpha', 'Beta', 'Gamma'];
      for (let i = 0; i < mockRowsBefore.length; i++) {
        expect(mockRowsBefore[i].label).toBe(expectedLabels[i]);
      }

      // === Set theme view 2 layout ===
      const layout2 = await request('PUT', `/api/projects/${projectId}/theme-views/${theme2Id}/layout`, {
        positions: [{ entityId, x: 700, y: 800 }],
      });
      expect([200, 204]).toContain(layout2.res.status);

      // === Set query text ===
      const queryText = `SELECT * FROM ${entityName} LIMIT 2`;
      const setQuery = await request('PUT', `/api/projects/${projectId}/query`, { text: queryText });
      expect([200, 204]).toContain(setQuery.res.status);

      // === Save snapshot ===
      const saveSnapshot = await request('POST', `/api/projects/${projectId}/snapshots`, { name: 'stable-state' });
      expect([200, 201]).toContain(saveSnapshot.res.status);

      // === Simulate "refresh" by re-fetching project and verifying state ===
      const refreshCheck = await request('GET', `/api/projects/${projectId}`);
      expect(refreshCheck.res.status).toBe(200);
      const refreshData = refreshCheck.data;
      const refreshDialect = refreshData?.dialect || refreshData?.data?.dialect;
      expect(refreshDialect).toBe('postgres');
      const refreshEntities = refreshData?.entities || refreshData?.data?.entities || [];
      const entityFound = Array.isArray(refreshEntities)
        ? refreshEntities.some(e => (e.name || '').includes('products_'))
        : JSON.stringify(refreshData).includes(entityName);
      expect(entityFound).toBe(true);

      // === Export project ===
      const exportProject = await request('GET', `/api/projects/${projectId}/export`);
      expect(exportProject.res.status).toBe(200);
      expect(exportProject.text).toBeTruthy();
      expect(exportProject.text).toContain(entityName.substring(0, 10));
      expect(exportProject.text.toLowerCase()).toContain('postgres');
      const exportedPayload = exportProject.data;

      // === Import project ===
      const importProject = await request('POST', '/api/projects/import', { payload: exportedPayload || exportProject.text });
      expect([200, 201]).toContain(importProject.res.status);
      importedProjectId = importProject.data?.id || importProject.data?.projectId;
      expect(importedProjectId).toBeTruthy();

      // === Verify imported project state ===
