      expect(impDialect).toBe('postgres');

      // Entity exists
      const impEntities = importedProject.data?.entities || importedProject.data?.data?.entities || [];
      const impEntityFound = Array.isArray(impEntities)
        ? impEntities.some(e => (e.name || '').includes('products_'))
        : JSON.stringify(importedProject.data).includes(entityName);
      expect(impEntityFound).toBe(true);

      // Query text - must be present
      const impQuery = importedProject.data?.query || importedProject.data?.queryText || importedProject.data?.data?.query;
      expect(impQuery).toBeTruthy();
      expect(impQuery).toContain(entityName.substring(0, 10));

      // Theme views exist - must verify
      const impThemes = await request('GET', `/api/projects/${importedProjectId}/theme-views`);
      expect(impThemes.res.status).toBe(200);
      const impThemeList = Array.isArray(impThemes.data) ? impThemes.data : (impThemes.data?.items || impThemes.data?.themeViews || []);
      expect(impThemeList.length).toBeGreaterThanOrEqual(2);

      // === Verify theme view 2 layout restored ===
      // Find the imported theme view corresponding to Layout_*
      const impTheme2 = impThemeList.find(t => (t.name || '').includes('Layout_'));
      if (impTheme2) {
        const impTheme2Id = impTheme2.id || impTheme2.themeViewId;
        const impLayout = await request('GET', `/api/projects/${importedProjectId}/theme-views/${impTheme2Id}/layout`);
        expect(impLayout.res.status).toBe(200);
        const impPositions = impLayout.data?.positions || impLayout.data?.data?.positions || [];
        expect(impPositions.length).toBeGreaterThan(0);
        const impPos = impPositions[0];
        expect(impPos.x).toBe(700);
        expect(impPos.y).toBe(800);
      }

      // === Verify mock data rules restored ===
      // Find imported entity id
      const impEntityObj = Array.isArray(impEntities)
        ? impEntities.find(e => (e.name || '').includes('products_'))
        : null;
      const impEntityId = impEntityObj?.id || impEntityObj?.entityId;
      if (impEntityId) {
        const impRules = await request('GET', `/api/projects/${importedProjectId}/entities/${impEntityId}/mock-data/rules`);
        if (impRules.res.status === 200) {
          const rulesStr = JSON.stringify(impRules.data);
          expect(rulesStr).toContain('sequence');
          expect(rulesStr).toContain('Alpha');
          expect(rulesStr).toContain('Beta');
          expect(rulesStr).toContain('Gamma');
        }
      }

      // === Verify generated data restored (6 rows, correct sequence) ===
      const impMockData = await request('GET', `/api/projects/${importedProjectId}/mock-data?entity=${entityName}`);
      expect(impMockData.res.status).toBe(200);
      const impMockRows = impMockData.data?.rows || impMockData.data?.data?.rows || [];
      expect(impMockRows.length).toBe(6);
      // Verify fixed sequence values
      for (let i = 0; i < impMockRows.length; i++) {
        expect(impMockRows[i].label).toBe(expectedLabels[i]);
      }

      // === Verify snapshot was preserved ===
      const impSnapshots = await request('GET', `/api/projects/${importedProjectId}/snapshots`);
      if (impSnapshots.res.status === 200) {
        const impSnapList = Array.isArray(impSnapshots.data) ? impSnapshots.data : (impSnapshots.data?.items || impSnapshots.data?.snapshots || []);
        const stableSnap = impSnapList.find(s => s.name === 'stable-state');
        if (stableSnap) {
          expect(stableSnap.name).toBe('stable-state');
        }
      }

      // Query execution should work on imported project
      let impExec = await request('POST', `/api/projects/${importedProjectId}/sql/execute`, { query: queryText });
      if (impExec.res.status !== 200) {
        impExec = await request('POST', `/api/projects/${importedProjectId}/query/execute`, { text: queryText });
      }
      expect(impExec.res.status).toBe(200);

      // === Test importing legacy/old format without theme views or mock rules ===
      const legacyPayload = {
        name: `legacy-${suffix}`,
        dialect: 'mysql',
        entities: [
          {
            name: 'legacy_table',
            fields: [
              { name: 'id', type: 'int', primaryKey: true },
              { name: 'value', type: 'varchar' }
            ]
          }
        ]
        // Deliberately missing: themeViews, mockDataRules, query, relationships
      };

      const legacyImport = await request('POST', '/api/projects/import', { payload: legacyPayload });
      expect([200, 201]).toContain(legacyImport.res.status);
      legacyId = legacyImport.data?.id || legacyImport.data?.projectId;
      expect(legacyId).toBeTruthy();

      // Legacy import should auto-create default theme view
      const legacyThemes = await request('GET', `/api/projects/${legacyId}/theme-views`);
      expect(legacyThemes.res.status).toBe(200);
      const legacyThemeList = Array.isArray(legacyThemes.data) ? legacyThemes.data : (legacyThemes.data?.items || legacyThemes.data?.themeViews || []);
      expect(legacyThemeList.length).toBeGreaterThanOrEqual(1);

      // Legacy project should be editable
      const legacyGet = await request('GET', `/api/projects/${legacyId}`);
      expect(legacyGet.res.status).toBe(200);
      const legacyEntities = legacyGet.data?.entities || legacyGet.data?.data?.entities || [];
      const legacyEntityExists = Array.isArray(legacyEntities)
        ? legacyEntities.some(e => e.name === 'legacy_table')
        : JSON.stringify(legacyGet.data).includes('legacy_table');
      expect(legacyEntityExists).toBe(true);

    } finally {
      if (projectId) await safeDeleteProject(projectId);
      if (importedProjectId) await safeDeleteProject(importedProjectId);
      if (legacyId) await safeDeleteProject(legacyId);
    }
  });
});

