describe('round10_sql_dialect_switch_preserves_model', () => {
  it('should regenerate SQL for switched dialect without mutating model data, preserve issues list, show dialect-specific differences and validation', async () => {
    const suffix = `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
    const entityName = `items_${suffix.replace(/[^a-zA-Z0-9_]/g, '_')}`;
    let projectId;

    try {
      // Create project with mysql dialect
      const createProject = await request('POST', '/api/projects', { name: `dialect-${suffix}`, dialect: 'mysql' });
      expect([200, 201]).toContain(createProject.res.status);
      projectId = createProject.data?.id || createProject.data?.projectId;
      expect(projectId).toBeTruthy();

      // Create entity with fields that behave differently across dialects:
      // - autoIncrement: MySQL uses AUTO_INCREMENT, Postgres uses SERIAL/GENERATED
      // - boolean default: MySQL may use TINYINT(1), Postgres uses BOOLEAN
      // - Also add a field that may be invalid in one dialect to test differential validation
      const createEntity = await request('POST', `/api/projects/${projectId}/entities`, {
        name: entityName,
        fields: [
          { name: 'id', type: 'int', primaryKey: true, autoIncrement: true },
          { name: 'title', type: 'varchar', length: 100 },
          { name: 'is_active', type: 'boolean', defaultValue: true },
          { name: 'notes', type: 'text' },
        ],
      });
      expect([200, 201]).toContain(createEntity.res.status);

      // Create a field configuration that might be problematic:
      // e.g., a field missing required length for varchar to ensure issues list is non-empty
      const entityId = createEntity.data?.id || createEntity.data?.entityId;
      expect(entityId).toBeTruthy();

      // Add a field without length that requires it - to ensure issues are generated
      const addField = await request('POST', `/api/projects/${projectId}/entities/${entityId}/fields`, {
        name: 'code',
        type: 'varchar',
        // Deliberately omit length to create an issue
      });
      // This may or may not succeed depending on validation - continue regardless

      // Capture full model data before dialect switch
      const beforeProject = await request('GET', `/api/projects/${projectId}`);
      expect(beforeProject.res.status).toBe(200);
      const beforeEntities = beforeProject.data?.entities || beforeProject.data?.schema?.entities || beforeProject.data?.model?.entities || beforeProject.data?.data?.entities;
      const beforeModelStr = JSON.stringify(beforeEntities);

      // Get MySQL SQL preview
      const mysqlSql = await request('GET', `/api/projects/${projectId}/sql-preview`);
      expect(mysqlSql.res.status).toBe(200);
      const mysqlText = typeof mysqlSql.data === 'string' ? mysqlSql.data : (mysqlSql.data?.sql || mysqlSql.data?.content || JSON.stringify(mysqlSql.data));
      expect(mysqlText).toBeTruthy();
      expect(mysqlText).toContain(entityName);

      // Get issues/problems list before switching dialect
      const issuesBefore = await request('GET', `/api/projects/${projectId}/issues`);
      const issuesBeforeStatus = issuesBefore.res.status;
      let issuesBeforeCount = 0;
      if (issuesBeforeStatus === 200) {
        const issuesArr = Array.isArray(issuesBefore.data) ? issuesBefore.data : (issuesBefore.data?.issues || issuesBefore.data?.data?.issues || []);
        issuesBeforeCount = issuesArr.length;
      }

      // Switch dialect to postgres
      const switchDialect = await request('PUT', `/api/projects/${projectId}/dialect`, { dialect: 'postgres' });
      expect([200, 204]).toContain(switchDialect.res.status);

      // Verify model data is NOT mutated after dialect switch
      const afterProject = await request('GET', `/api/projects/${projectId}`);
      expect(afterProject.res.status).toBe(200);
      const afterEntities = afterProject.data?.entities || afterProject.data?.schema?.entities || afterProject.data?.model?.entities || afterProject.data?.data?.entities;
      const afterModelStr = JSON.stringify(afterEntities);

      // Direct comparison: model data should be identical
      expect(afterModelStr).toBe(beforeModelStr);

      // Additional structural verification
      expect(afterModelStr).toContain(entityName);
      expect(afterModelStr).toContain('title');
      expect(afterModelStr).toContain('is_active');
      if (Array.isArray(beforeEntities) && Array.isArray(afterEntities)) {
        expect(afterEntities.length).toBe(beforeEntities.length);
        for (const beforeEntity of beforeEntities) {
          const afterEntity = afterEntities.find(e => (e.name || e.id) === (beforeEntity.name || beforeEntity.id));
          expect(afterEntity).toBeTruthy();
          const bFields = beforeEntity.fields || [];
          const aFields = afterEntity.fields || [];
          expect(aFields.length).toBe(bFields.length);
          for (const bf of bFields) {
            const af = aFields.find(f => f.name === bf.name);
            expect(af).toBeTruthy();
            expect(af.type).toBe(bf.type);
            if (bf.primaryKey !== undefined) expect(af.primaryKey).toBe(bf.primaryKey);
            if (bf.autoIncrement !== undefined) expect(af.autoIncrement).toBe(bf.autoIncrement);
            if (bf.defaultValue !== undefined) expect(af.defaultValue).toBe(bf.defaultValue);
            if (bf.length !== undefined) expect(af.length).toBe(bf.length);
          }
        }
      }

      // Verify issues list is NOT cleared after dialect switch
      const issuesAfter = await request('GET', `/api/projects/${projectId}/issues`);
      expect(issuesAfter.res.status).toBe(200);
      const issuesAfterArr = Array.isArray(issuesAfter.data) ? issuesAfter.data : (issuesAfter.data?.issues || issuesAfter.data?.data?.issues || []);
      // Issues should still exist (not cleared) - count should be >= what was there before
      expect(issuesAfterArr.length).toBeGreaterThanOrEqual(issuesBeforeCount);

      // Get PostgreSQL SQL preview
      const postgresSql = await request('GET', `/api/projects/${projectId}/sql-preview`);
      expect(postgresSql.res.status).toBe(200);
      const pgText = typeof postgresSql.data === 'string' ? postgresSql.data : (postgresSql.data?.sql || postgresSql.data?.content || JSON.stringify(postgresSql.data));
      expect(pgText).toBeTruthy();
      expect(pgText).toContain(entityName);

      // Assert visible difference between MySQL and PostgreSQL SQL output
      expect(pgText).not.toBe(mysqlText);

      // Verify copy SQL returns current dialect version
      // Try dedicated copy endpoint, fallback to sql-preview
      let copySql = await request('POST', `/api/projects/${projectId}/sql/copy`);
      if (![200, 201].includes(copySql.res.status)) {
        copySql = await request('GET', `/api/projects/${projectId}/sql-preview`);
      }
      expect(copySql.res.status).toBe(200);
      const copyText = typeof copySql.data === 'string' ? copySql.data : (copySql.data?.sql || copySql.data?.content || JSON.stringify(copySql.data));
      expect(copyText).toContain(entityName);
      // Current SQL should match postgres dialect output (not mysql)
      expect(copyText).toBe(pgText);

      // === Test dialect-specific validation differences ===
      // Switch back to MySQL and check if issues change (dialect-specific validation)
      const switchBack = await request('PUT', `/api/projects/${projectId}/dialect`, { dialect: 'mysql' });
      expect([200, 204]).toContain(switchBack.res.status);

      const issuesMysql = await request('GET', `/api/projects/${projectId}/issues`);
      expect(issuesMysql.res.status).toBe(200);
      const issuesMysqlArr = Array.isArray(issuesMysql.data) ? issuesMysql.data : (issuesMysql.data?.issues || issuesMysql.data?.data?.issues || []);

      // Switch to postgres again
      const switchAgain = await request('PUT', `/api/projects/${projectId}/dialect`, { dialect: 'postgres' });
      expect([200, 204]).toContain(switchAgain.res.status);

      const issuesPg = await request('GET', `/api/projects/${projectId}/issues`);
      expect(issuesPg.res.status).toBe(200);
      const issuesPgArr = Array.isArray(issuesPg.data) ? issuesPg.data : (issuesPg.data?.issues || issuesPg.data?.data?.issues || []);

      // The issues lists should exist - if there are dialect-specific differences, they should be reflected
      // At minimum, issues endpoint should work after multiple dialect switches
      expect(issuesPgArr).toBeDefined();
      expect(issuesMysqlArr).toBeDefined();

      // Verify model is STILL not mutated after multiple switches
      const finalProject = await request('GET', `/api/projects/${projectId}`);
      expect(finalProject.res.status).toBe(200);
      const finalEntities = finalProject.data?.entities || finalProject.data?.schema?.entities || finalProject.data?.model?.entities || finalProject.data?.data?.entities;
      const finalModelStr = JSON.stringify(finalEntities);
      expect(finalModelStr).toBe(beforeModelStr);

    } finally {
      if (projectId) await safeDeleteProject(projectId);
    }
  });
});

