describe('round11_project_export_complete_and_stable', () => {
  it('should export project with complete core content and keep consecutive exports stable when unchanged', async () => {
    const suffix = `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
    const usersName = `users_${suffix.replace(/[^a-zA-Z0-9_]/g, '_')}`;
    const postsName = `posts_${suffix.replace(/[^a-zA-Z0-9_]/g, '_')}`;
    let projectId;

    try {
      const createProject = await request('POST', '/api/projects', { name: `export-project-${suffix}`, dialect: 'mysql' });
      expect([200, 201]).toContain(createProject.res.status);
      projectId = createProject.data?.id || createProject.data?.projectId;
      expect(projectId).toBeTruthy();

      const entityA = await request('POST', `/api/projects/${projectId}/entities`, {
        name: usersName,
        x: 10,
        y: 20,
        fields: [
          { name: 'id', type: 'int', primaryKey: true },
          { name: 'email', type: 'varchar', length: 255, unique: true },
        ],
      });
      const entityB = await request('POST', `/api/projects/${projectId}/entities`, {
        name: postsName,
        x: 300,
        y: 400,
        fields: [
          { name: 'id', type: 'int', primaryKey: true },
          { name: 'user_id', type: 'int' },
        ],
      });
      expect([200, 201]).toContain(entityA.res.status);
      expect([200, 201]).toContain(entityB.res.status);
      const userId = entityA.data?.id || entityA.data?.entityId;
      const postId = entityB.data?.id || entityB.data?.entityId;

      const relation = await request('POST', `/api/projects/${projectId}/relations`, {
        fromEntityId: postId,
        fromField: 'user_id',
        toEntityId: userId,
        toField: 'id',
        type: 'many-to-one',
      });
      expect([200, 201]).toContain(relation.res.status);

      // First export
      const export1 = await request('GET', `/api/projects/${projectId}/export`);
      expect(export1.res.status).toBe(200);
      expect(export1.text).toBeTruthy();

      // Parse exported data as JSON for structured assertions
      let exportData1;
      try {
        exportData1 = typeof export1.data === 'object' ? export1.data : JSON.parse(export1.text);
      } catch {
        exportData1 = null;
      }
      expect(exportData1).toBeTruthy();

      // Verify project name
      expect(export1.text).toContain(`export-project-${suffix}`);

      // Verify entities
      expect(export1.text).toContain(usersName);
      expect(export1.text).toContain(postsName);

      // Verify fields
      expect(export1.text).toContain('email');
      expect(export1.text).toContain('user_id');

      // Verify dialect
      expect(export1.text.toLowerCase()).toContain('mysql');

      const exportStr = JSON.stringify(exportData1);

      // Check constraints: verify both primaryKey and unique constraints exist
      // The id field should have primaryKey and email should have unique
      expect(
        exportStr.includes('primaryKey') || exportStr.includes('primary_key') || exportStr.includes('"primaryKey":true') || exportStr.includes('"primary_key":true')
      ).toBe(true);
      expect(
        exportStr.includes('unique') || exportStr.includes('Unique') || exportStr.includes('"unique":true')
      ).toBe(true);

      // Check relations exist in export
      const rels = exportData1.relations || exportData1.schema?.relations || exportData1.model?.relations;
      if (Array.isArray(rels)) {
        expect(rels.length).toBeGreaterThanOrEqual(1);
        const rel = rels[0];
        expect(rel).toBeTruthy();
        const relStr = JSON.stringify(rel);
        expect(relStr.includes('user_id') || relStr.includes(String(postId)) || relStr.includes(String(userId))).toBe(true);
      } else {
        // Fallback text check: at minimum relations must be mentioned
        expect(exportStr.includes('many-to-one') || exportStr.includes('relation') || exportStr.includes('user_id')).toBe(true);
      }

      // Check canvas positions - must be verifiable, not conditionally skipped
      // At least one approach must confirm positions are present
      let positionsVerified = false;

      const entities = exportData1.entities || exportData1.schema?.entities || exportData1.model?.entities;
      if (Array.isArray(entities)) {
        const usersEntity = entities.find(e => e.name === usersName);
        const postsEntity = entities.find(e => e.name === postsName);
        if (usersEntity && usersEntity.x !== undefined) {
          expect(usersEntity.x).toBe(10);
          expect(usersEntity.y).toBe(20);
          positionsVerified = true;
        }
        if (postsEntity && postsEntity.x !== undefined) {
          expect(postsEntity.x).toBe(300);
          expect(postsEntity.y).toBe(400);
          positionsVerified = true;
        }
      }

      // Also check if positions appear in views/canvas/themeViews
      const views = exportData1.views || exportData1.themeViews || exportData1.canvas;
      if (views && typeof views === 'object' && !positionsVerified) {
        const viewStr = JSON.stringify(views);
        if (viewStr.includes('10') && viewStr.includes('20')) {
          positionsVerified = true;
        }
      }

      // Ensure positions were found somewhere in the export
      expect(positionsVerified).toBe(true);

      // Second export: verify stability
      const export2 = await request('GET', `/api/projects/${projectId}/export`);
      expect(export2.res.status).toBe(200);
      expect(export2.text).toBeTruthy();
      expect(export2.text).toBe(export1.text);
    } finally {
      if (projectId) await safeDeleteProject(projectId);
    }
  });

