      const hasWarning = exportStr.toLowerCase().includes('warn') ||
        exportStr.toLowerCase().includes('issue') ||
        exportStr.toLowerCase().includes('problem') ||
        exportStr.toLowerCase().includes('error') ||
        exportStr.toLowerCase().includes('remind') ||
        exportStr.toLowerCase().includes('notice') ||
        (typeof exportResult.data === 'object' && (exportResult.data.warnings || exportResult.data.issues || exportResult.data.errors));

      // The export MUST include a warning about model issues
