      // The export should still contain the project data regardless
      expect(exportStr).toContain(`export-warn-${suffix}`);
    } finally {
      if (projectId) await safeDeleteProject(projectId);
    }
  });

  it('should export an empty project and clearly indicate it is empty, not corrupted', async () => {
    const suffix = `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
    let projectId;

    try {
      const createProject = await request('POST', '/api/projects', { name: `empty-export-${suffix}`, dialect: 'mysql' });
      expect([200, 201]).toContain(createProject.res.status);
      projectId = createProject.data?.id || createProject.data?.projectId;
      expect(projectId).toBeTruthy();

      // Export empty project
      const exportResult = await request('GET', `/api/projects/${projectId}/export`);
      expect(exportResult.res.status).toBe(200);
      expect(exportResult.text).toBeTruthy();

      // Should contain project name to show it's valid
      expect(exportResult.text).toContain(`empty-export-${suffix}`);

      // Should be parseable (not corrupted)
      let parsed;
      try {
        parsed = typeof exportResult.data === 'object' ? exportResult.data : JSON.parse(exportResult.text);
      } catch {
        parsed = null;
      }
      expect(parsed).toBeTruthy();

      // Should indicate emptiness (empty entities array or similar)
      const entitiesField = parsed?.entities || parsed?.schema?.entities || parsed?.model?.entities;
      if (Array.isArray(entitiesField)) {
        expect(entitiesField.length).toBe(0);
      }

      // Verify dialect is present even for empty project
      const parsedStr = JSON.stringify(parsed).toLowerCase();
      expect(parsedStr).toContain('mysql');
    } finally {
