    });
    const corruptedStatus = corruptedRes.status;
    expect(corruptedStatus).toBeGreaterThanOrEqual(400);
    const corruptedText = await corruptedRes.text();
    expect(corruptedText).toBeTruthy();

    // --- 2. Structurally incomplete file import ---
    const incompleteRes = await request('POST', '/api/projects/import', { someRandomField: 'abc' });
    const incompleteStatus = incompleteRes.res.status;
    expect(incompleteStatus).toBeGreaterThanOrEqual(400);
    const incompleteText = typeof incompleteRes.data === 'string' ? incompleteRes.data : JSON.stringify(incompleteRes.data);
    expect(incompleteText).toBeTruthy();

    // --- 3. Severe name conflicts ---
    const conflictPayload = {
      name: 'conflict-test-project',
      entities: [
        { name: 'dup_entity', fields: [{ name: 'id', type: 'int', primaryKey: true }] },
        { name: 'dup_entity', fields: [{ name: 'id', type: 'int', primaryKey: true }] },
        { name: 'dup_entity', fields: [{ name: 'id', type: 'int', primaryKey: true }] },
      ],
      relations: [],
      dialect: 'mysql'
    };
    const conflictRes = await request('POST', '/api/projects/import', conflictPayload);
    const conflictStatus = conflictRes.res.status;
    const conflictText = typeof conflictRes.data === 'string' ? conflictRes.data : JSON.stringify(conflictRes.data);
    expect(conflictText).toBeTruthy();

    // Clean up if conflict import created a project
    if (conflictRes.res.status >= 200 && conflictRes.res.status < 300) {
      const conflictProjectId = conflictRes.data?.id || conflictRes.data?.projectId;
      if (conflictProjectId) await safeDeleteProject(conflictProjectId);
    }

    // --- Verify the three error types are DISTINCT ---
    // At minimum, either the status codes differ OR the error messages/types differ
    const corruptedMsg = corruptedText.toLowerCase();
    const incompleteMsg = incompleteText.toLowerCase();
    const conflictMsg = conflictText.toLowerCase();

    const allSameStatus = (corruptedStatus === incompleteStatus && incompleteStatus === conflictStatus);
    const allSameMessage = (corruptedMsg === incompleteMsg && incompleteMsg === conflictMsg);

    // They should NOT all be identical (different errors should produce different responses)
    expect(allSameStatus && allSameMessage).toBe(false);
  });

