        // Should have visible confirmation/overwrite indication
        const hasOverwriteInfo = importStr.toLowerCase().includes('overwrite') ||
          importStr.toLowerCase().includes('confirm') ||
          importStr.toLowerCase().includes('replace') ||
          importStr.toLowerCase().includes('warn') ||
          importStr.toLowerCase().includes('cover') ||
          (typeof importRes.data === 'object' && (
            importRes.data.overwritten !== undefined ||
            importRes.data.confirmation !== undefined ||
            importRes.data.warning !== undefined ||
            importRes.data.replaced !== undefined
          ));
        expect(hasOverwriteInfo).toBe(true);
      } else {
