        // The response should indicate that confirmation is needed
        const needsConfirm = importStr.toLowerCase().includes('confirm') ||
          importStr.toLowerCase().includes('overwrite') ||
          importStr.toLowerCase().includes('existing');
        expect(needsConfirm).toBe(true);
      }
    } finally {
