const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function request(method, path, body) {
  const res = await fetch(`${BASE_URL}${path}`, {
    method,
    headers: { 'Content-Type': 'application/json' },
    body: body === undefined ? undefined : JSON.stringify(body),
  });
  const text = await res.text();
  let data;
  try { data = text ? JSON.parse(text) : null; } catch { data = text; }
  return { res, data, text };
}

async function safeDeleteProject(projectId) {
  try { await fetch(`${BASE_URL}/api/projects/${projectId}`, { method: 'DELETE' }); } catch {}
}

function getViews(project) {
  return project?.themeViews || project?.views || [];
}

function getEntities(project) {
  return project?.entities || project?.schema?.entities || project?.model?.entities || [];
}

function getRelations(project) {
  return project?.relations || project?.schema?.relations || project?.model?.relations || [];
}

describe('round21_multi_view_project_migration', () => {
  it('should migrate a legacy single-view project into a default theme view preserving layout and entities', async () => {
    const projectName = `legacy-single-view-${Date.now()}`;
    let projectId;

    const legacyProjectPayload = {
      name: projectName,
      dialect: 'postgres',
      entities: [
        {
          id: 'entity_users',
          name: 'users',
          fields: [
            { id: 'f_id', name: 'id', type: 'int', primaryKey: true },
            { id: 'f_name', name: 'name', type: 'varchar' },
          ],
          x: 100,
          y: 120,
        },
        {
          id: 'entity_orders',
          name: 'orders',
          fields: [
            { id: 'f_order_id', name: 'id', type: 'int', primaryKey: true },
            { id: 'f_user_id', name: 'user_id', type: 'int' },
          ],
          x: 360,
          y: 120,
        },
      ],
      relations: [
        {
          id: 'rel_user_orders',
          name: 'users_orders',
          fromEntityId: 'entity_users',
          toEntityId: 'entity_orders',
          fromField: 'id',
          toField: 'user_id',
          type: 'one-to-many',
        },
      ],
      // No views/themeViews - legacy single-view format
    };

    try {
      // Import legacy project
      const importRes = await request('POST', '/api/projects/import', legacyProjectPayload);
      expect([200, 201]).toContain(importRes.res.status);
      projectId = importRes.data?.id || importRes.data?.projectId;
      expect(projectId).toBeTruthy();

      // Fetch project and verify migration
      const getProject = await request('GET', `/api/projects/${projectId}`);
      expect(getProject.res.status).toBe(200);
      const project = getProject.data;
      expect(project).toBeTruthy();

      // Verify theme views exist (migrated from legacy single view)
      const views = getViews(project);
      expect(Array.isArray(views)).toBe(true);
      expect(views.length).toBeGreaterThanOrEqual(1);

      const firstView = views[0];
      expect(firstView).toBeTruthy();
      expect(typeof firstView).toBe('object');

      // Verify the default theme view contains all original entities
      const viewEntityIds = firstView.entityIds || firstView.visibleEntityIds || [];
      const viewStr = JSON.stringify(firstView);
      // The first view should reference all entities from the legacy project
      const hasAllEntities = (viewEntityIds.length >= 2) ||
        (viewStr.includes('users') && viewStr.includes('orders')) ||
        (viewStr.includes('entity_users') && viewStr.includes('entity_orders'));
      expect(hasAllEntities).toBe(true);

      // Verify canvas layout positions were migrated to the default view
      const layoutNodes = firstView.layout?.nodes || firstView.nodes || firstView.canvas?.nodes;
      if (Array.isArray(layoutNodes)) {
        // Should have position data from original entities
        expect(layoutNodes.length).toBeGreaterThanOrEqual(2);
        const userNode = layoutNodes.find(n => n.entityId === 'entity_users' || n.id === 'entity_users');
        if (userNode) {
          expect(userNode.x).toBe(100);
          expect(userNode.y).toBe(120);
        }
      } else {
        // Positions might be on entities themselves
        const entities = getEntities(project);
        const usersEntity = entities.find(e => e.name === 'users');
        if (usersEntity && usersEntity.x !== undefined) {
          expect(usersEntity.x).toBe(100);
          expect(usersEntity.y).toBe(120);
        }
      }

      // Verify whole-project entities preserved
      const entities = getEntities(project);
      expect(Array.isArray(entities)).toBe(true);
      expect(entities.length).toBeGreaterThanOrEqual(2);
      const entityNames = entities.map(e => e.name);
      expect(entityNames).toContain('users');
      expect(entityNames).toContain('orders');

      // Verify whole-project relations preserved
      const relations = getRelations(project);
      expect(Array.isArray(relations)).toBe(true);
      expect(relations.length).toBeGreaterThanOrEqual(1);

      // Verify SQL generation is based on entire project model (not just one view)
      const sqlPreview = await request('GET', `/api/projects/${projectId}/sql-preview`);
      expect(sqlPreview.res.status).toBe(200);
      const sqlText = typeof sqlPreview.data === 'string' ? sqlPreview.data : (sqlPreview.data?.sql || sqlPreview.data?.content || JSON.stringify(sqlPreview.data));
      expect(sqlText).toContain('users');
      expect(sqlText).toContain('orders');
    } finally {
      if (projectId) await safeDeleteProject(projectId);
    }
  });

  it('should support creating multiple theme views with independent entity subsets and layouts', async () => {
    const suffix = `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
    let projectId;

    try {
      const createProject = await request('POST', '/api/projects', {
        name: `multi-view-${suffix}`,
        dialect: 'mysql'
      });
      expect([200, 201]).toContain(createProject.res.status);
      projectId = createProject.data?.id || createProject.data?.projectId;
      expect(projectId).toBeTruthy();

      // Create entities
      const entity1 = await request('POST', `/api/projects/${projectId}/entities`, {
        name: 'customers',
        x: 10,
        y: 10,
        fields: [{ name: 'id', type: 'int', primaryKey: true }]
      });
      expect([200, 201]).toContain(entity1.res.status);
      const entity1Id = entity1.data?.id || entity1.data?.entityId;
      expect(entity1Id).toBeTruthy();

      const entity2 = await request('POST', `/api/projects/${projectId}/entities`, {
        name: 'products',
        x: 200,
        y: 200,
        fields: [{ name: 'id', type: 'int', primaryKey: true }]
      });
      expect([200, 201]).toContain(entity2.res.status);
      const entity2Id = entity2.data?.id || entity2.data?.entityId;
      expect(entity2Id).toBeTruthy();

      // Get the project to find the default theme view
      const proj = await request('GET', `/api/projects/${projectId}`);
      expect(proj.res.status).toBe(200);
      const views = getViews(proj.data);
      expect(Array.isArray(views)).toBe(true);
      expect(views.length).toBeGreaterThanOrEqual(1);

      const defaultViewId = views[0].id || views[0].viewId;
      expect(defaultViewId).toBeTruthy();

      // Try to add a second view
      let addViewRes = await request('POST', `/api/projects/${projectId}/views`, {
        name: 'Products View'
      });
      if (addViewRes.res.status >= 400) {
        addViewRes = await request('POST', `/api/projects/${projectId}/theme-views`, {
          name: 'Products View'
        });
      }
      expect([200, 201]).toContain(addViewRes.res.status);
      const secondViewId = addViewRes.data?.id || addViewRes.data?.viewId;
      expect(secondViewId).toBeTruthy();

      // SQL should still cover entire project model regardless of active view
      const sqlPreview = await request('GET', `/api/projects/${projectId}/sql-preview`);
      expect(sqlPreview.res.status).toBe(200);
      const sqlText = typeof sqlPreview.data === 'string' ? sqlPreview.data : (sqlPreview.data?.sql || sqlPreview.data?.content || JSON.stringify(sqlPreview.data));
      expect(sqlText).toContain('customers');
      expect(sqlText).toContain('products');

      // Verify the two views are distinguishable
      const view1Detail = await request('GET', `/api/projects/${projectId}/views/${defaultViewId}`);
      const view2Detail = await request('GET', `/api/projects/${projectId}/views/${secondViewId}`);

      if (view1Detail.res.status === 200 && view2Detail.res.status === 200) {
        const v1Str = JSON.stringify(view1Detail.data);
        const v2Str = JSON.stringify(view2Detail.data);
        expect(v1Str).not.toBe(v2Str);
      }
    } finally {
      if (projectId) await safeDeleteProject(projectId);
    }
  });

  it('should enforce theme view name constraints: 1-30 chars, unique within project', async () => {
    const suffix = `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
    let projectId;

    try {
      const createProject = await request('POST', '/api/projects', {
        name: `view-constraints-${suffix}`,
        dialect: 'mysql'
      });
      expect([200, 201]).toContain(createProject.res.status);
      projectId = createProject.data?.id || createProject.data?.projectId;
      expect(projectId).toBeTruthy();

      const viewEndpoint = `/api/projects/${projectId}/views`;
      const altEndpoint = `/api/projects/${projectId}/theme-views`;

      async function createView(name) {
        let res = await request('POST', viewEndpoint, { name });
        if (res.res.status >= 400 && res.res.status !== 422 && res.res.status !== 409) {
          res = await request('POST', altEndpoint, { name });
        }
        return res;
      }

      // Empty name should be rejected
      const emptyNameRes = await createView('');
      expect(emptyNameRes.res.status).toBeGreaterThanOrEqual(400);

      // Name exceeding 30 characters should be rejected
      const longName = 'A'.repeat(31);
      const longNameRes = await createView(longName);
      expect(longNameRes.res.status).toBeGreaterThanOrEqual(400);

      // Exactly 30 characters should be accepted
      const exact30 = 'B'.repeat(30);
      const exact30Res = await createView(exact30);
      expect([200, 201]).toContain(exact30Res.res.status);

      // Exactly 1 character should be accepted
      const singleCharRes = await createView('Z');
      expect([200, 201]).toContain(singleCharRes.res.status);

      // Duplicate name within same project should be rejected
      const dupRes = await createView('Z');
      expect(dupRes.res.status).toBeGreaterThanOrEqual(400);
    } finally {
      if (projectId) await safeDeleteProject(projectId);
    }
  });

  it('should prevent deleting the last remaining theme view', async () => {
    const suffix = `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
    let projectId;

    try {
      const createProject = await request('POST', '/api/projects', {
        name: `view-delete-${suffix}`,
        dialect: 'mysql'
      });
      expect([200, 201]).toContain(createProject.res.status);
      projectId = createProject.data?.id || createProject.data?.projectId;
      expect(projectId).toBeTruthy();

      // Get the default view
      const proj = await request('GET', `/api/projects/${projectId}`);
      expect(proj.res.status).toBe(200);
      const views = getViews(proj.data);
      expect(Array.isArray(views)).toBe(true);
      expect(views.length).toBeGreaterThanOrEqual(1);

      const defaultViewId = views[0].id || views[0].viewId;
      expect(defaultViewId).toBeTruthy();

      // Attempt to delete the last remaining view - should be rejected
      let deleteRes = await request('DELETE', `/api/projects/${projectId}/views/${defaultViewId}`);
      if (deleteRes.res.status === 404) {
        deleteRes = await request('DELETE', `/api/projects/${projectId}/theme-views/${defaultViewId}`);
      }
      expect(deleteRes.res.status).toBeGreaterThanOrEqual(400);

      // Verify the view still exists
      const projAfter = await request('GET', `/api/projects/${projectId}`);
      expect(projAfter.res.status).toBe(200);
      const viewsAfter = getViews(projAfter.data);
      expect(viewsAfter.length).toBeGreaterThanOrEqual(1);
    } finally {
      if (projectId) await safeDeleteProject(projectId);
    }
  });

  it('should base SQL and query debugging on entire project model, not just current view', async () => {
    const suffix = `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
    let projectId;

    try {
      const createProject = await request('POST', '/api/projects', {
        name: `sql-full-model-${suffix}`,
        dialect: 'mysql'
      });
      expect([200, 201]).toContain(createProject.res.status);
      projectId = createProject.data?.id || createProject.data?.projectId;
      expect(projectId).toBeTruthy();

      // Create two entities
      const e1 = await request('POST', `/api/projects/${projectId}/entities`, {
        name: 'table_alpha',
        fields: [{ name: 'id', type: 'int', primaryKey: true }]
      });
      expect([200, 201]).toContain(e1.res.status);

      const e2 = await request('POST', `/api/projects/${projectId}/entities`, {
        name: 'table_beta',
        fields: [{ name: 'id', type: 'int', primaryKey: true }]
      });
      expect([200, 201]).toContain(e2.res.status);

      // SQL preview should include both entities
      const sqlPreview = await request('GET', `/api/projects/${projectId}/sql-preview`);
      expect(sqlPreview.res.status).toBe(200);
      const sqlText = typeof sqlPreview.data === 'string' ? sqlPreview.data : (sqlPreview.data?.sql || sqlPreview.data?.content || JSON.stringify(sqlPreview.data));
      expect(sqlText).toContain('table_alpha');
      expect(sqlText).toContain('table_beta');

      // Query debugging should be able to reference both tables
      const queryText = 'SELECT * FROM table_alpha';
      const setQuery = await request('PUT', `/api/projects/${projectId}/query`, { text: queryText });
      expect([200, 204]).toContain(setQuery.res.status);

      // Execute or debug the query
      const debugRes = await request('POST', `/api/projects/${projectId}/query/execute`, { text: queryText });
      // Even if execution fails (no real DB), the endpoint should accept queries referencing any project entity
      expect(debugRes.res.status).toBeLessThan(500);
    } finally {
      if (projectId) await safeDeleteProject(projectId);
    }
  });
});

import { describe, it, expect } from 'vitest';

