describe('round22_theme_view_unification', () => {
  it('should expose unified theme views and switching views does not alter underlying model, SQL, mock data or debug results', async () => {
    const suffix = Date.now();
    const payload = {
      name: `theme-view-unification-${suffix}`,
      dialect: 'mysql',
      entities: [
        {
          id: 'account',
          name: 'account',
          fields: [
            { id: 'account_id', name: 'id', type: 'int', primaryKey: true },
            { id: 'account_name', name: 'name', type: 'varchar' },
          ],
        },
        {
          id: 'invoice',
          name: 'invoice',
          fields: [
            { id: 'invoice_id', name: 'id', type: 'int', primaryKey: true },
            { id: 'invoice_account_id', name: 'account_id', type: 'int' },
          ],
        },
      ],
      relations: [
        {
          id: 'rel_account_invoice',
          name: 'account_invoice',
          fromEntityId: 'account',
          toEntityId: 'invoice',
          fromField: 'id',
          toField: 'account_id',
        },
      ],
      themeViews: [
        {
          id: 'tv_all',
          name: 'All',
          entityIds: ['account', 'invoice'],
          layout: {
            nodes: [
              { entityId: 'account', x: 60, y: 80 },
              { entityId: 'invoice', x: 320, y: 80 },
            ],
          },
        },
        {
          id: 'tv_account_only',
          name: 'AccountOnly',
          entityIds: ['account'],
          layout: {
            nodes: [{ entityId: 'account', x: 180, y: 140 }],
          },
        },
      ],
      queryText: 'SELECT * FROM account;',
    };

    let projectId;
    try {
      // Step 1: Import project with theme views
      let createRes = await request('POST', '/api/projects/import', payload);
      if (createRes.res.status >= 400) {
        createRes = await request('POST', '/api/projects', payload);
      }
      expect([200, 201]).toContain(createRes.res.status);
      projectId = getProjectId(createRes.data);
      expect(projectId).toBeTruthy();

      // Step 2: Get project state before switching
      const getBefore = await request('GET', `/api/projects/${projectId}`);
      expect(getBefore.res.status).toBe(200);
      const projectBefore = getBefore.data;

      const entitiesBefore = getEntities(projectBefore);
      const relationsBefore = getRelations(projectBefore);
      const dialectBefore = getDialect(projectBefore);
      const themeViewsBefore = getThemeViews(projectBefore);

      expect(Array.isArray(themeViewsBefore)).toBe(true);
      expect(themeViewsBefore.length).toBeGreaterThanOrEqual(2);
      expect(Array.isArray(entitiesBefore)).toBe(true);
      expect(entitiesBefore.length).toBeGreaterThanOrEqual(2);
      expect(relationsBefore.length).toBeGreaterThanOrEqual(1);
      expect(dialectBefore).toBeTruthy();

      // Verify the two theme views exist and have correct entity subsets
      const tvAll = themeViewsBefore.find(v => v.name === 'All' || (v.id || v.viewId) === 'tv_all');
      const tvAccount = themeViewsBefore.find(v => v.name === 'AccountOnly' || (v.id || v.viewId) === 'tv_account_only');
      expect(tvAll).toBeTruthy();
      expect(tvAccount).toBeTruthy();

      const tvAllIds = tvAll.entityIds || tvAll.visibleEntityIds || [];
      const tvAccountIds = tvAccount.entityIds || tvAccount.visibleEntityIds || [];
      expect(tvAllIds.length).toBeGreaterThanOrEqual(2);
      expect(tvAccountIds.length).toBeGreaterThanOrEqual(1);
      // AccountOnly should NOT contain invoice
      expect(tvAccountIds).not.toEqual(expect.arrayContaining(['invoice']));

      // Get SQL before switching
      const sqlBefore = await request('GET', `/api/projects/${projectId}/sql-preview`);
      expect(sqlBefore.res.status).toBe(200);
      const sqlTextBefore = typeof sqlBefore.data === 'string' ? sqlBefore.data : (sqlBefore.data?.sql || sqlBefore.data?.content || JSON.stringify(sqlBefore.data));

      // Step 3: Switch active theme view
      const switchViewId = tvAccount.id || tvAccount.viewId || 'tv_account_only';
      const switchPayload = { activeThemeViewId: switchViewId };
      let switchRes = await request('PATCH', `/api/projects/${projectId}`, switchPayload);
      if (switchRes.res.status >= 400) {
        switchRes = await request('PUT', `/api/projects/${projectId}`, { ...payload, activeThemeViewId: switchViewId });
      }
      expect(switchRes.res.status).toBeLessThan(400);

      // Step 4: Get project state after switching
      const getAfter = await request('GET', `/api/projects/${projectId}`);
      expect(getAfter.res.status).toBe(200);
      const projectAfter = getAfter.data;

      // Step 5: Verify underlying model NOT changed after switching
      const entitiesAfter = getEntities(projectAfter);
      const relationsAfter = getRelations(projectAfter);
      const dialectAfter = getDialect(projectAfter);

      expect(entitiesAfter.map(e => e.id || e.name).sort())
        .toEqual(entitiesBefore.map(e => e.id || e.name).sort());
      expect(relationsAfter.length).toBe(relationsBefore.length);
      expect(dialectAfter).toBe(dialectBefore);

      // Mock data rules should be unchanged (must exist and match)
      const rulesBefore = projectBefore.mockDataRules || projectBefore.mock?.rules || projectBefore.dataMockRules;
      const rulesAfter = projectAfter.mockDataRules || projectAfter.mock?.rules || projectAfter.dataMockRules;
      if (rulesBefore) {
        expect(rulesAfter).toBeTruthy();
        expect(JSON.stringify(rulesAfter)).toBe(JSON.stringify(rulesBefore));
      }

      // Query text should be unchanged
      const queryBefore = projectBefore.queryText || projectBefore.query?.text || projectBefore.debug?.queryText;
      const queryAfter = projectAfter.queryText || projectAfter.query?.text || projectAfter.debug?.queryText;
      expect(queryBefore).toBeTruthy();
      expect(queryAfter).toBe(queryBefore);

      // SQL output should be unchanged (based on whole model, not view)
      const sqlAfter = await request('GET', `/api/projects/${projectId}/sql-preview`);
      expect(sqlAfter.res.status).toBe(200);
      const sqlTextAfter = typeof sqlAfter.data === 'string' ? sqlAfter.data : (sqlAfter.data?.sql || sqlAfter.data?.content || JSON.stringify(sqlAfter.data));
      // SQL should still contain both entities
      expect(sqlTextAfter).toContain('account');
      expect(sqlTextAfter).toContain('invoice');

      // Step 6: Verify old field names (diagramViews, diagrams, pages) are NOT present
      expect(projectAfter).not.toHaveProperty('diagramViews');
      expect(projectAfter).not.toHaveProperty('diagrams');
      // 'pages' should not be used as the theme view field
      expect(projectAfter.pages).toBeFalsy();
    } finally {
      if (projectId) await safeDeleteProject(projectId);
    }
  });

  it('should treat old project default diagram as first theme view on import with all entities included', async () => {
    const legacyPayload = {
      name: `legacy-upgrade-${Date.now()}`,
      dialect: 'mysql',
      entities: [
        {
          id: 'user',
          name: 'user',
          fields: [
            { id: 'user_id', name: 'id', type: 'int', primaryKey: true },
          ],
          x: 50,
          y: 60,
        },
      ],
      relations: [],
      // No themeViews - simulating old format
    };

    let projectId;
    try {
      // Import via the import endpoint
      let importRes = await request('POST', '/api/projects/import', legacyPayload);
      if (importRes.res.status >= 400) {
        importRes = await request('POST', '/api/projects', legacyPayload);
      }
      expect([200, 201]).toContain(importRes.res.status);
      projectId = getProjectId(importRes.data);
      expect(projectId).toBeTruthy();

      const getRes = await request('GET', `/api/projects/${projectId}`);
      expect(getRes.res.status).toBe(200);
      const project = getRes.data;

      // The system should auto-create at least one theme view from the old default diagram
      const themeViews = getThemeViews(project);
      expect(Array.isArray(themeViews)).toBe(true);
      expect(themeViews.length).toBeGreaterThanOrEqual(1);

      // The auto-created theme view should contain the old project's entity
      const firstView = themeViews[0];
      expect(firstView).toBeTruthy();

      const viewEntityIds = firstView.entityIds || firstView.visibleEntityIds || [];
      const viewStr = JSON.stringify(firstView);
      const containsUser = viewEntityIds.includes('user') ||
        viewStr.includes('user');
      expect(containsUser).toBe(true);

      // Verify the view is identifiable as the first/default theme view
      expect(firstView.name || firstView.id || firstView.viewId).toBeTruthy();

      // Verify old naming conventions are not used
      expect(project).not.toHaveProperty('diagramViews');
      expect(project).not.toHaveProperty('diagrams');
    } finally {
      if (projectId) await safeDeleteProject(projectId);
    }
  });
});

