import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function request(path, options = {}) {
  const res = await fetch(`${BASE_URL}${path}`, {
    headers: {
      'Content-Type': 'application/json',
      ...(options.headers || {}),
    },
    ...options,
  });
  const text = await res.text();
  let body = null;
  try {
    body = text ? JSON.parse(text) : null;
  } catch {
    body = text;
  }
  return { res, body };
}

async function deleteProject(projectId) {
  try {
    await request(`/api/projects/${projectId}`, { method: 'DELETE' });
  } catch {
    // ignore cleanup failures
  }
}

function getProjectId(body) {
  return body?.id || body?.projectId || body?.data?.id;
}

function getGeneratedData(project) {
  return project?.generatedData || project?.mockData || project?.generated?.data;
}

function getMockDataRules(project) {
  return project?.mockDataRules || project?.mock?.rules || project?.dataMockRules;
}

