import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function request(path, options = {}) {
  const res = await fetch(`${BASE_URL}${path}`, {
    headers: {
      'Content-Type': 'application/json',
      ...(options.headers || {}),
    },
    ...options,
  });
  const text = await res.text();
  let body = null;
  try {
    body = text ? JSON.parse(text) : null;
  } catch {
    body = text;
  }
  return { res, body };
}

async function deleteProject(projectId) {
  try {
    await request(`/api/projects/${projectId}`, { method: 'DELETE' });
  } catch {
    // ignore cleanup failures
  }
}

function getProjectId(body) {
  return body?.id || body?.projectId || body?.data?.id;
}

function getEntities(project) {
  return project?.schema?.entities || project?.model?.entities || project?.entities || [];
}

function getRelations(project) {
  return project?.schema?.relations || project?.model?.relations || project?.relations || [];
}

function getThemeViews(project) {
  return project?.themeViews || project?.views || [];
}

function getDialect(project) {
  return project?.dialect || project?.sqlDialect || project?.settings?.dialect;
}

function getQueryText(project) {
  return project?.queryText || project?.query?.text || project?.debug?.queryText;
}

function getMockDataRules(project) {
  return project?.mockDataRules || project?.mock?.rules || project?.dataMockRules;
}

function getGeneratedData(project) {
  return project?.generatedData || project?.mockData || project?.generated?.data;
}

function getSnapshots(project) {
  return project?.snapshots || (project?.snapshot ? [project.snapshot] : []) || (project?.latestSnapshot ? [project.latestSnapshot] : []);
}

