import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function req(path, options = {}) {
  const res = await fetch(`${BASE_URL}${path}`, {
    headers: {
      'Content-Type': 'application/json',
      ...(options.headers || {}),
    },
    ...options,
  });
  const text = await res.text();
  let body = null;
  try {
    body = text ? JSON.parse(text) : null;
  } catch {
    body = text;
  }
  return { res, body };
}

function extractSchemes(body) {
  if (Array.isArray(body)) return body;
  if (body && Array.isArray(body.data)) return body.data;
  if (body && Array.isArray(body.schemes)) return body.schemes;
  if (body && Array.isArray(body.items)) return body.items;
  if (body && Array.isArray(body.list)) return body.list;
  return [];
}

function extractId(body) {
  return body?.id ?? body?.data?.id ?? body?.schemeId ?? body?.data?.schemeId;
}

describe('round11_saved_filter_presets', () => {
  const cleanupIds = [];
  let schemePath = null;

  async function discoverPath() {
    const paths = ['/api/filter-schemes', '/api/schemes', '/api/saved-schemes'];
    for (const p of paths) {
      const probe = await req(p);
      if (probe.res.status !== 404) return p;
    }
    return null;
  }

  async function cleanup() {
    if (!schemePath) return;
    for (const id of cleanupIds) {
      try {
        await req(`${schemePath}/${id}`, { method: 'DELETE' });
      } catch {}
    }
    cleanupIds.length = 0;
  }

  it('should create, list, and delete filter schemes with name validation, and handle same-name rules per Round 21', async () => {
    schemePath = await discoverPath();
    if (!schemePath) {
      expect(true).toBe(true);
      return;
    }

    try {
      const listBefore = await req(schemePath);
      expect(listBefore.res.status).toBe(200);

      // --- Boundary: empty name (pure spaces) should be rejected ---
      const emptyName = await req(schemePath, {
        method: 'POST',
        body: JSON.stringify({ name: '   ', filters: { city: 'Test' } }),
      });
      expect([400, 409, 422]).toContain(emptyName.res.status);

      // --- Boundary: name longer than 20 characters should be rejected ---
      const longName = 'A'.repeat(21);
      const tooLong = await req(schemePath, {
        method: 'POST',
        body: JSON.stringify({ name: longName, filters: { city: 'Test' } }),
      });
      expect([400, 409, 422]).toContain(tooLong.res.status);

      // --- Create a valid scheme ---
      const name = `r11-${Date.now()}`.slice(0, 20);
      const filtersA = { city: 'Beijing', minPrice: 100, maxPrice: 300 };

      const created = await req(schemePath, {
        method: 'POST',
        body: JSON.stringify({ name, filters: filtersA }),
      });
      expect([200, 201]).toContain(created.res.status);
      const idA = extractId(created.body);
      expect(idA, `Expected created scheme id in response, got ${JSON.stringify(created.body)}`).toBeTruthy();
      cleanupIds.push(idA);

      // --- Per Round 21: same name + same filters (exact duplicate) should be rejected ---
      const exactDup = await req(schemePath, {
        method: 'POST',
        body: JSON.stringify({ name, filters: filtersA }),
      });
      expect([400, 409, 422]).toContain(exactDup.res.status);

      // --- Per Round 21: same name + different filters should be ALLOWED ---
      const filtersB = { city: 'Shenzhen', minPrice: 200 };
      const sameNameDiffFilters = await req(schemePath, {
        method: 'POST',
        body: JSON.stringify({ name, filters: filtersB }),
      });
      expect([200, 201]).toContain(sameNameDiffFilters.res.status);
      const idB = extractId(sameNameDiffFilters.body);
      expect(idB).toBeTruthy();
      cleanupIds.push(idB);

      // --- Verify both appear in the list ---
      const listed = await req(schemePath);
      expect(listed.res.status).toBe(200);
      const items = extractSchemes(listed.body);
      const matched = items.filter((item) => item?.name === name);
      expect(matched.length).toBeGreaterThanOrEqual(2);

      // --- Verify duplicate rejection did NOT affect existing filters ---
      // Get the first scheme and check its filters are intact
      const getFirst = await req(`${schemePath}/${idA}`);
      if (getFirst.res.ok && getFirst.body) {
        const f = getFirst.body?.filters ?? getFirst.body?.data?.filters ?? getFirst.body?.conditions;
        if (f) {
          expect(f.city ?? f.keyword).toBe(filtersA.city);
        }
      }

      // --- Delete scheme A and verify B still exists ---
      const deleted = await req(`${schemePath}/${idA}`, { method: 'DELETE' });
      expect([200, 204]).toContain(deleted.res.status);
      cleanupIds.splice(cleanupIds.indexOf(idA), 1);

      const afterDel = await req(schemePath);
      const afterItems = extractSchemes(afterDel.body);
      const stillExists = afterItems.some((s) => (s.id ?? s.schemeId) === idB);
      expect(stillExists, 'Deleting one scheme must not remove the other same-name scheme').toBe(true);

    } finally {
      await cleanup();
    }
  });
});

import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function request(path, options = {}) {
  const res = await fetch(`${BASE_URL}${path}`, {
    headers: {
      'Content-Type': 'application/json',
      ...(options.headers || {}),
    },
    ...options,
  });

  const contentType = res.headers.get('content-type') || '';
  let body = null;
  if (contentType.includes('application/json')) {
    body = await res.json();
  } else {
    body = await res.text();
  }

  return { res, body };
}

function isObject(value) {
  return value !== null && typeof value === 'object' && !Array.isArray(value);
}

function findIdDeep(value) {
  if (!isObject(value)) return undefined;
  if (typeof value.id === 'string' || typeof value.id === 'number') return value.id;
  for (const key of Object.keys(value)) {
    const nested = value[key];
    if (isObject(nested)) {
      const found = findIdDeep(nested);
      if (found !== undefined) return found;
    }
  }
  return undefined;
}

function findArrayDeep(value) {
  if (Array.isArray(value)) return value;
  if (!isObject(value)) return undefined;
  for (const key of Object.keys(value)) {
    const nested = value[key];
    const found = findArrayDeep(nested);
    if (found) return found;
  }
  return undefined;
}

function getPresetName(item) {
  if (!isObject(item)) return undefined;
  return item.name ?? item.title ?? item.presetName ?? item.label;
}

function getPresetFilters(item) {
  if (!isObject(item)) return undefined;
  return item.filters ?? item.conditions ?? item.criteria ?? item.query ?? item.payload;
}

function stableStringify(value) {
  if (Array.isArray(value)) {
    return `[${value.map(stableStringify).join(',')}]`;
  }
  if (value && typeof value === 'object') {
    return `{${Object.keys(value)
      .sort()
      .map((key) => `${JSON.stringify(key)}:${stableStringify(value[key])}`)
      .join(',')}}`;
  }
  return JSON.stringify(value);
}

async function createPreset(payload) {
  const candidates = ['/api/presets', '/presets', '/api/filter-presets', '/filter-presets'];
  let last;
  for (const path of candidates) {
    const result = await request(path, {
      method: 'POST',
      body: JSON.stringify(payload),
    });
    if (result.res.status !== 404) {
      return { path, ...result };
    }
    last = { path, ...result };
  }
  throw new Error(`No preset creation endpoint found. Last response status: ${last?.res?.status}`);
}

async function listPresets() {
  const candidates = ['/api/presets', '/presets', '/api/filter-presets', '/filter-presets'];
  let last;
  for (const path of candidates) {
    const result = await request(path, { method: 'GET' });
    if (result.res.status !== 404) {
      return { path, ...result };
    }
    last = { path, ...result };
  }
  throw new Error(`No preset list endpoint found. Last response status: ${last?.res?.status}`);
}

async function getPresetById(basePath, id) {
  return request(`${basePath}/${id}`, { method: 'GET' });
}

async function deletePreset(basePath, id) {
  return request(`${basePath}/${id}`, { method: 'DELETE' });
}

