      const listedPreset2 = sameNameItems.find((item) => String(findIdDeep(item)) === String(preset2Id));

      expect(!!listedPreset1, `Expected list to contain first preset id ${preset1Id}, got same-name items ${JSON.stringify(sameNameItems)}`).toBe(true);
      expect(!!listedPreset2, `Expected list to contain second preset id ${preset2Id}, got same-name items ${JSON.stringify(sameNameItems)}`).toBe(true);

      const listedFilters1 = getPresetFilters(listedPreset1);
      const listedFilters2 = getPresetFilters(listedPreset2);
