      ).toBe(true);
      expect(
        getPresetName(get1.body) === uniqueName || getPresetName(get1.body?.data) === uniqueName,
        `Expected fetched first preset name to be '${uniqueName}', got body ${JSON.stringify(get1.body)}`,
      ).toBe(true);
      expect(
