      ).toBe(true);

      const deleteFirst = await deletePreset(basePath, preset1Id);
      expect(
        [200, 204].includes(deleteFirst.res.status),
        `Expected deleting first preset id ${preset1Id} to succeed with 200/204, got ${deleteFirst.res.status} and body ${JSON.stringify(deleteFirst.body)}`,
      ).toBe(true);

      const afterDeleteFirstGet1 = await getPresetById(basePath, preset1Id);
      expect(
        [404, 410].includes(afterDeleteFirstGet1.res.status),
        `Expected deleted first preset id ${preset1Id} to be unavailable with 404/410, got ${afterDeleteFirstGet1.res.status} and body ${JSON.stringify(afterDeleteFirstGet1.body)}`,
      ).toBe(true);

      const afterDeleteFirstGet2 = await getPresetById(basePath, preset2Id);
