        `Expected second preset filters to remain unchanged after deleting first preset. Expected ${stableStringify(filtersB)}, got ${stableStringify(getPresetFilters(afterDeleteFirstGet2.body) ?? getPresetFilters(afterDeleteFirstGet2.body?.data))}`,
      ).toBe(true);

      createdIds.splice(createdIds.indexOf(preset1Id), 1);
    } finally {
      for (const id of createdIds) {
        try {
          await deletePreset(basePath, id);
        } catch {
          // ignore cleanup failures
        }
      }
    }
  });
});

import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function request(method, path, body) {
  const res = await fetch(`${BASE_URL}${path}`, {
    method,
    headers: { 'Content-Type': 'application/json' },
    body: body === undefined ? undefined : JSON.stringify(body),
  });
  const text = await res.text();
  let json;
  try {
    json = text ? JSON.parse(text) : null;
  } catch {
    json = { raw: text };
  }
  return { res, body: json };
}

// Try multiple possible search endpoints and methods
async function searchProperties(payload) {
  const candidates = [
    { method: 'POST', path: '/api/properties/search' },
    { method: 'POST', path: '/api/search' },
    { method: 'GET', path: '/api/properties' },
    { method: 'POST', path: '/api/property/search' },
  ];
  for (const c of candidates) {
    const result = await request(c.method, c.path, c.method === 'GET' ? undefined : payload);
    if (result.res.status !== 404) {
      return { ...result, endpoint: c };
    }
  }
  return { res: { status: 404 }, body: null, endpoint: candidates[0] };
}

