    expect(reducedCount).toBeGreaterThanOrEqual(fullCount);

    // Verify applied filters echo reflects the removal if available
    const appliedReduced = extractAppliedFilters(reducedBody);
    if (appliedReduced && appliedReduced.layouts) {
      expect(appliedReduced.layouts).not.toContain('3室');
      expect(appliedReduced.layouts).toHaveLength(2);
    }

    // Clear all conditions
    const clearAllPayload = { filters: { layouts: [], orientations: [], tags: [] } };
    const { res: clearRes, body: clearBody } = await searchProperties(clearAllPayload);
    expect(clearRes.status).toBe(200);
    const clearCount = extractCount(clearBody);
    expect(typeof clearCount).toBe('number');
    expect(clearCount).toBeGreaterThanOrEqual(reducedCount);

    // Verify filters are cleared in response if echoed
    const appliedClear = extractAppliedFilters(clearBody);
    if (appliedClear) {
      const layouts = appliedClear.layouts || [];
      const orientations = appliedClear.orientations || [];
      const tags = appliedClear.tags || [];
      expect(layouts).toHaveLength(0);
      expect(orientations).toHaveLength(0);
      expect(tags).toHaveLength(0);
    }
  });
});

