// Try multiple candidate endpoints for persisting filter/UI state
async function saveState(payload) {
  const candidates = [
    '/api/filter-state',
    '/api/user/preferences',
    '/api/settings/filter-state',
    '/api/user-state',
    '/api/state',
    '/api/preferences',
  ];
  for (const path of candidates) {
    const result = await request('POST', path, payload);
    if (result.res.status !== 404) {
      return { ...result, endpoint: path };
    }
  }
  return { res: { status: 404 }, body: null, endpoint: candidates[0] };
}

async function getState(endpoint, sessionId) {
  // Try query param and path-based approaches
  let result = await request('GET', `${endpoint}?sessionId=${encodeURIComponent(sessionId)}`);
  if (result.res.status === 404) {
    result = await request('GET', `${endpoint}/${encodeURIComponent(sessionId)}`);
  }
  return result;
}

async function deleteState(endpoint, sessionId) {
  await request('DELETE', `${endpoint}?sessionId=${encodeURIComponent(sessionId)}`).catch(() => undefined);
  await request('DELETE', `${endpoint}/${encodeURIComponent(sessionId)}`).catch(() => undefined);
}

