// Try multiple possible endpoints for compare operations
async function addToCompare(payload) {
  const candidates = [
    { method: 'POST', path: '/api/compare/items' },
    { method: 'POST', path: '/api/compare' },
    { method: 'POST', path: '/api/comparison/items' },
    { method: 'POST', path: '/api/compare/add' },
  ];
  for (const c of candidates) {
    const result = await request(c.method, c.path, payload);
    if (result.res.status !== 404) {
      return { ...result, endpoint: c.path };
    }
  }
  return { res: { status: 404 }, body: null, endpoint: candidates[0].path };
}

async function getCompareList(compareId, endpoint) {
  const candidates = endpoint
    ? [endpoint]
    : ['/api/compare/items', '/api/compare', '/api/comparison/items'];
  for (const path of candidates) {
    const result = await request('GET', `${path}?compareId=${encodeURIComponent(compareId)}`);
    if (result.res.status !== 404) {
      return { ...result, endpoint: path };
    }
  }
  return { res: { status: 404 }, body: null, endpoint: candidates[0] };
}

async function removeFromCompare(compareId, propertyId, endpoint) {
  // Try DELETE with body, then with query params
  let result = await request('DELETE', endpoint, { compareId, propertyId });
  if (result.res.status === 404 || result.res.status === 405) {
    result = await request('DELETE', `${endpoint}?compareId=${encodeURIComponent(compareId)}&propertyId=${encodeURIComponent(propertyId)}`);
  }
  return result;
}

function extractItems(body) {
  return body?.items || body?.data || body?.list || body?.properties || [];
}

describe('compare_list_limit_and_minimum_count_rules', () => {
  it('should allow adding up to 4 items from different entry points and verify each', async () => {
    const compareId = `cmp-add4-${Date.now()}`;
    const propertyIds = [
      `p-${Date.now()}-1`,
      `p-${Date.now()}-2`,
      `p-${Date.now()}-3`,
      `p-${Date.now()}-4`,
    ];
    const entryPoints = ['search', 'favorite', 'detail', 'search'];
    let endpoint = '';

    try {
      for (let i = 0; i < 4; i++) {
        const add = await addToCompare({
          compareId,
          propertyId: propertyIds[i],
          entryPoint: entryPoints[i],
        });
        expect(
          [200, 201].includes(add.res.status),
          `Adding item ${i + 1} from '${entryPoints[i]}' should succeed, got ${add.res.status}`
        ).toBe(true);
        if (!endpoint) endpoint = add.endpoint;
      }

      // Verify all 4 items are present and match expected IDs
