import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function request(method, path, body) {
  const res = await fetch(`${BASE_URL}${path}`, {
    method,
    headers: { 'Content-Type': 'application/json' },
    body: body === undefined ? undefined : JSON.stringify(body),
  });
  const text = await res.text();
  let json;
  try {
    json = text ? JSON.parse(text) : null;
  } catch {
    json = { raw: text };
  }
  return { res, body: json };
}

// Try multiple possible endpoints for compare analysis
async function postCompareAnalysis(payload) {
  const candidates = [
    '/api/compare/analysis',
    '/api/compare',
    '/api/comparison/analysis',
    '/api/compare/analyze',
  ];
  for (const path of candidates) {
    const result = await request('POST', path, payload);
    if (result.res.status !== 404) {
      return { ...result, endpoint: path };
    }
  }
  return { res: { status: 404 }, body: null, endpoint: candidates[0] };
}

async function getCompareAnalysis(endpoint, compareId, diffOnly) {
  const qs = `compareId=${encodeURIComponent(compareId)}${diffOnly ? '&diffOnly=true' : ''}`;
  return request('GET', `${endpoint}?${qs}`);
}

describe('compare_analysis_diff_and_tie_results_correct', () => {
  it('should return correct diff-only fields, handle ties with all tied objects, and handle missing values', async () => {
    const compareId = `cmp-analysis-${Date.now()}`;
    const properties = [
      {
        propertyId: `a-${Date.now()}-1`,
        totalPrice: 200,
        unitPrice: 2.5,
        area: 80,
        layout: '2室1厅',
        publishedAt: '2024-01-03T00:00:00.000Z',
        orientation: '南',
        decoration: '精装',
      },
      {
        propertyId: `a-${Date.now()}-2`,
        totalPrice: 200,
        unitPrice: 2.0,
        area: 80,
        layout: '2室1厅',
        publishedAt: '2024-01-03T00:00:00.000Z',
        orientation: '南',
        decoration: '精装',
      },
      {
        propertyId: `a-${Date.now()}-3`,
        totalPrice: 250,
        unitPrice: null,
        area: 90,
        layout: '3室2厅',
        publishedAt: '2024-01-05T00:00:00.000Z',
        orientation: '南',
        decoration: null,
      },
    ];

    // Expected analysis:
    // totalPrice: [200, 200, 250] - DIFF (250 differs)
    // unitPrice:  [2.5, 2.0, null] - DIFF (different values + null)
    // area:       [80, 80, 90] - DIFF
    // layout:     ['2室1厅', '2室1厅', '3室2厅'] - DIFF
    // publishedAt:[same, same, different] - DIFF
    // orientation:['南', '南', '南'] - SAME, should NOT be in diff
    // decoration: ['精装', '精装', null] - DIFF (null differs)

    let endpoint = '';

    try {
      // Setup compare analysis
      const setup = await postCompareAnalysis({
        compareId,
        properties,
        diffOnly: false,
      });

      expect(
        [200, 201].includes(setup.res.status),
        `POST setup should succeed, got ${setup.res.status}: ${JSON.stringify(setup.body)}`
      ).toBe(true);
      endpoint = setup.endpoint;

      // Verify setup response confirms data was accepted
      expect(setup.body).toBeTruthy();
      const setupData = setup.body?.data || setup.body;
      // If the setup echoes back properties count or ID, verify it
      if (setupData?.properties) {
        expect(Array.isArray(setupData.properties) ? setupData.properties.length : 0).toBeGreaterThanOrEqual(2);
      }

      // Fetch full analysis first (no diff filter)
      const fullAnalysis = await getCompareAnalysis(endpoint, compareId, false);
      expect(fullAnalysis.res.status).toBe(200);
      const fullBody = fullAnalysis.body?.data || fullAnalysis.body;
      expect(fullBody).toBeTruthy();

      // Fetch diff-only analysis
      const diffAnalysis = await getCompareAnalysis(endpoint, compareId, true);
      expect(diffAnalysis.res.status).toBe(200);
      const body = diffAnalysis.body?.data || diffAnalysis.body;
      expect(body).toBeTruthy();

      // Validate diff items
      const diffItems = body.diffItems || body.differences || body.items || body.fields || body.rows || [];
      expect(Array.isArray(diffItems)).toBe(true);
      const diffFields = diffItems.map((i) => String(i.field || i.key || i.name || i.label || ''));

      // orientation is SAME for all ('南'), should NOT be in diff
      const hasOrientation = diffFields.some((f) => /orientation|朝向/i.test(f));
      expect(hasOrientation, 'orientation is identical across all, should NOT appear in diff-only').toBe(false);

      // These fields differ and should appear
      const hasTotalPrice = diffFields.some((f) => /totalPrice|total_price|总价/i.test(f));
      const hasUnitPrice = diffFields.some((f) => /unitPrice|unit_price|单价/i.test(f));
      const hasArea = diffFields.some((f) => /area|面积/i.test(f));
      const hasLayout = diffFields.some((f) => /layout|户型/i.test(f));
      const hasPublishedAt = diffFields.some((f) => /publish|发布/i.test(f));
      const hasDecoration = diffFields.some((f) => /decoration|装修/i.test(f));

      expect(hasTotalPrice, 'totalPrice differs and should be in diff-only').toBe(true);
      expect(hasArea, 'area differs and should be in diff-only').toBe(true);
      expect(hasUnitPrice, 'unitPrice (including null) differs and should be in diff-only').toBe(true);
      expect(hasDecoration, 'decoration with null should be treated as a difference').toBe(true);

      // Diff-only should have fewer fields than full analysis
      const fullItems = fullBody.diffItems || fullBody.differences || fullBody.items || fullBody.fields || fullBody.rows || [];
      if (Array.isArray(fullItems) && fullItems.length > 0) {
        expect(diffItems.length).toBeLessThanOrEqual(fullItems.length);
      }

      // Validate conclusions / summary
      const conclusions = body.conclusions || body.summary || fullBody.conclusions || fullBody.summary || {};

      // Lowest total price: properties[0] and properties[1] tie at 200
      const lowestTotal = conclusions.lowestTotalPrice || conclusions.minTotalPrice || conclusions.lowest_total_price || conclusions['总价最低'];
      if (lowestTotal) {
        const lowestTotalIds = lowestTotal.propertyIds || lowestTotal.ids || lowestTotal.items || [];
        expect(lowestTotalIds).toEqual(
          expect.arrayContaining([properties[0].propertyId, properties[1].propertyId])
        );
        // Tie: should include exactly 2
        expect(lowestTotalIds.length).toBe(2);
        // Should NOT include properties[2] (which has 250)
        expect(lowestTotalIds).not.toContain(properties[2].propertyId);
      }

      // Lowest unit price: properties[1] at 2.0 wins; null should NOT win
      const lowestUnit = conclusions.lowestUnitPrice || conclusions.minUnitPrice || conclusions.lowest_unit_price || conclusions['单价最低'];
      if (lowestUnit) {
        const lowestUnitIds = lowestUnit.propertyIds || lowestUnit.ids || lowestUnit.items || [];
        expect(lowestUnitIds).toContain(properties[1].propertyId);
        // Null unitPrice should not be treated as lowest
        expect(lowestUnitIds).not.toContain(properties[2].propertyId);
      }

      // Largest area: properties[2] at 90
      const largestArea = conclusions.largestArea || conclusions.maxArea || conclusions.largest_area || conclusions['面积最大'];
      if (largestArea) {
        const largestAreaIds = largestArea.propertyIds || largestArea.ids || largestArea.items || [];
        expect(largestAreaIds).toContain(properties[2].propertyId);
      }

      // Latest published: properties[2] at 2024-01-05
      const latestPublished = conclusions.latestPublished || conclusions.newestPublished || conclusions.latest_published || conclusions['最新发布'];
      if (latestPublished) {
        const latestIds = latestPublished.propertyIds || latestPublished.ids || latestPublished.items || [];
        expect(latestIds).toContain(properties[2].propertyId);
      }

      // At least some conclusions should exist
      const hasAnyConclusion = lowestTotal || lowestUnit || largestArea || latestPublished;
      expect(hasAnyConclusion, 'At least one conclusion/summary should be present').toBeTruthy();

    } finally {
      await request('DELETE', endpoint || '/api/compare/analysis', { compareId }).catch(() => undefined);
    }
  });

  it('should handle all-null field correctly: not include it as a diff if all are null', async () => {
    const compareId = `cmp-allnull-${Date.now()}`;
    const properties = [
      {
        propertyId: `n-${Date.now()}-1`,
        totalPrice: 300,
        unitPrice: 3.0,
        area: 100,
        layout: '3室1厅',
        publishedAt: '2024-02-01T00:00:00.000Z',
        orientation: null,
        decoration: null,
      },
      {
        propertyId: `n-${Date.now()}-2`,
        totalPrice: 350,
        unitPrice: 3.5,
        area: 100,
        layout: '3室1厅',
        publishedAt: '2024-02-01T00:00:00.000Z',
        orientation: null,
        decoration: null,
      },
    ];

    // orientation: [null, null] - all same (null) -> NOT a diff
    // decoration:  [null, null] - all same (null) -> NOT a diff
    // area:        [100, 100] - same -> NOT a diff
    // totalPrice:  [300, 350] - DIFF
    // unitPrice:   [3.0, 3.5] - DIFF

    let endpoint = '';

    try {
      const setup = await postCompareAnalysis({
        compareId,
        properties,
        diffOnly: false,
      });

      if (setup.res.status === 404) {
        // Skip if endpoint not available
        return;
      }

      expect([200, 201]).toContain(setup.res.status);
      endpoint = setup.endpoint;

      const diffAnalysis = await getCompareAnalysis(endpoint, compareId, true);
      expect(diffAnalysis.res.status).toBe(200);
      const body = diffAnalysis.body?.data || diffAnalysis.body;

      const diffItems = body?.diffItems || body?.differences || body?.items || body?.fields || body?.rows || [];
      expect(Array.isArray(diffItems)).toBe(true);
      const diffFields = diffItems.map((i) => String(i.field || i.key || i.name || i.label || ''));

      // All-null fields should NOT be in diff
      const hasOrientation = diffFields.some((f) => /orientation|朝向/i.test(f));
      const hasDecoration = diffFields.some((f) => /decoration|装修/i.test(f));
      expect(hasOrientation, 'all-null orientation should not appear in diff').toBe(false);
      expect(hasDecoration, 'all-null decoration should not appear in diff').toBe(false);

      // Same-value area should NOT be in diff
      const hasArea = diffFields.some((f) => /area|面积/i.test(f));
      expect(hasArea, 'identical area should not appear in diff').toBe(false);

      // Different totalPrice should be in diff
      const hasTotalPrice = diffFields.some((f) => /totalPrice|total_price|总价/i.test(f));
      expect(hasTotalPrice, 'different totalPrice should appear in diff').toBe(true);

    } finally {
      await request('DELETE', endpoint || '/api/compare/analysis', { compareId }).catch(() => undefined);
    }
  });
});

