import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function request(method, path, body, headers = {}) {
  const res = await fetch(`${BASE_URL}${path}`, {
    method,
    headers: {
      ...(body !== undefined ? { 'Content-Type': 'application/json' } : {}),
      ...headers,
    },
    body: body !== undefined ? JSON.stringify(body) : undefined,
  });

  const text = await res.text();
  let json;
  try {
    json = text ? JSON.parse(text) : null;
  } catch {
    json = text;
  }
  return { res, body: json, text };
}

async function safeDelete(path) {
  try {
    await fetch(`${BASE_URL}${path}`, { method: 'DELETE' });
  } catch {
    // ignore cleanup failure
  }
}

function normalizeTrendPayload(body) {
  const series = body?.series || body?.data || body?.trend || body?.priceTrend || body?.items || [];
  return Array.isArray(series) ? series : [];
}

function getPointValue(point) {
  if (point == null) return undefined;
  if (typeof point === 'number') return point;
  if (typeof point.value === 'number') return point.value;
  if (typeof point.price === 'number') return point.price;
  if (typeof point.amount === 'number') return point.amount;
  return undefined;
}

function isGap(point) {
  if (point == null) return true;
  const v = getPointValue(point);
  if (v === null || v === undefined) return true;
  if (typeof point === 'object' && (point.gap === true || point.missing === true || point.noData === true)) return true;
  return false;
}

describe('demo_listing_trend_fixed_sequence_persisted', () => {
  it('should keep fixed demo trend sequence across ranges and refresh while normal listings remain independently generated', async () => {
    const createdIds = [];

    const demoPayload = {
      title: `Verifier Demo Listing ${Date.now()}`,
      city: 'Shanghai',
      district: 'Pudong',
      price: 5000000,
      isDemo: true,
      trendPreset: {
        startPrice: 10000,
        monthlyChanges: [100, -50, 200, 0, -100, 150],
      },
    };

    const normalPayload = {
      title: `Verifier Normal Listing ${Date.now()}`,
      city: 'Shanghai',
      district: 'Minhang',
      price: 4200000,
      isDemo: false,
