    try {
      // Create demo listing
      const createDemo = await request('POST', '/api/listings', demoPayload);
      expect([200, 201]).toContain(createDemo.res.status);
      expect(createDemo.body && typeof createDemo.body).toBe('object');
      const demoId = createDemo.body.id || createDemo.body.listingId || createDemo.body.data?.id;
      expect(demoId, `expected created demo listing id, got ${JSON.stringify(createDemo.body)}`).toBeTruthy();
      createdIds.push(demoId);

      // Create normal listing
      const createNormal = await request('POST', '/api/listings', normalPayload);
      expect([200, 201]).toContain(createNormal.res.status);
      const normalId = createNormal.body.id || createNormal.body.listingId || createNormal.body.data?.id;
      expect(normalId, `expected created normal listing id, got ${JSON.stringify(createNormal.body)}`).toBeTruthy();
      createdIds.push(normalId);

      // Expected sequence: startPrice=10000, changes=[100,-50,200,0,-100,150]
      // Could include startPrice as first point or not; we handle both
      const expectedWithStart = [10000, 10100, 10050, 10250, 10250, 10150, 10300];
      const expectedWithoutStart = [10100, 10050, 10250, 10250, 10150, 10300];

      // === First 6m request ===
      const trend6a = await request('GET', `/api/listings/${demoId}/price-trend?range=6m`);
      expect(trend6a.res.status).toBe(200);
      const series6a = normalizeTrendPayload(trend6a.body);
      expect(series6a.length).toBeGreaterThan(0);
      const actual6a = series6a.map(getPointValue);

      // Determine which format the API uses (with or without start price)
      let expected6;
      if (series6a.length === 7) {
        expected6 = expectedWithStart;
      } else {
        expect(series6a.length).toBe(6);
        expected6 = expectedWithoutStart;
      }
      expect(actual6a).toEqual(expected6);

      // === 1 year range ===
      const trend1y = await request('GET', `/api/listings/${demoId}/price-trend?range=1y`);
      expect(trend1y.res.status).toBe(200);
      const series1y = normalizeTrendPayload(trend1y.body);
      expect(series1y.length).toBe(12);
      const values1y = series1y.map(getPointValue);
      // First N points should match the known sequence
      expect(values1y.slice(0, expected6.length)).toEqual(expected6);
      // Remaining points should be gaps (null/undefined/marked missing)
      const remaining1y = series1y.slice(expected6.length);
      for (let i = 0; i < remaining1y.length; i++) {
        expect(isGap(remaining1y[i]), `Expected gap at index ${expected6.length + i} in 1y range, got ${JSON.stringify(remaining1y[i])}`).toBe(true);
      }

      // === 2 year range ===
      const trend2y = await request('GET', `/api/listings/${demoId}/price-trend?range=2y`);
      expect(trend2y.res.status).toBe(200);
      const series2y = normalizeTrendPayload(trend2y.body);
      expect(series2y.length).toBe(24);
      const values2y = series2y.map(getPointValue);
      expect(values2y.slice(0, expected6.length)).toEqual(expected6);
      const remaining2y = series2y.slice(expected6.length);
      for (let i = 0; i < remaining2y.length; i++) {
        expect(isGap(remaining2y[i]), `Expected gap at index ${expected6.length + i} in 2y range, got ${JSON.stringify(remaining2y[i])}`).toBe(true);
      }

      // === Simulate refresh: second 6m request with cache-busting header ===
      const trend6b = await request('GET', `/api/listings/${demoId}/price-trend?range=6m`, undefined, {
