      // === Third 6m request after a small delay to further simulate refresh ===
      await new Promise(resolve => setTimeout(resolve, 500));
      const trend6c = await request('GET', `/api/listings/${demoId}/price-trend?range=6m`, undefined, {
        'Cache-Control': 'no-store',
        'x-request-id': `refresh2-${Date.now()}-${Math.random().toString(36).slice(2)}`,
      });
      expect(trend6c.res.status).toBe(200);
      const series6c = normalizeTrendPayload(trend6c.body);
      expect(series6c.map(getPointValue)).toEqual(expected6);

      // === Normal listing: should NOT match demo sequence ===
      const normalTrend = await request('GET', `/api/listings/${normalId}/price-trend?range=6m`);
      expect(normalTrend.res.status).toBe(200);
      const normalSeries = normalizeTrendPayload(normalTrend.body);
      expect(normalSeries.length).toBeGreaterThan(0);
      // Verify normal listing has a reasonable data structure
      const normalValues = normalSeries.map(getPointValue);
      // At least some values should be defined (non-gap)
      const definedNormalValues = normalValues.filter(v => v !== null && v !== undefined);
      expect(definedNormalValues.length).toBeGreaterThan(0);
      // Should not equal the demo sequence
      expect(normalValues).not.toEqual(expected6);
      // Each defined value should be a positive number
      for (const v of definedNormalValues) {
        expect(typeof v).toBe('number');
        expect(v).toBeGreaterThan(0);
      }
    } finally {
      for (const id of createdIds) {
        await safeDelete(`/api/listings/${id}`);
      }
    }
  });
});

