      expect(stateAfterLegacy.res.status).toBe(200);
      const state = stateAfterLegacy.body.filters || stateAfterLegacy.body.data || stateAfterLegacy.body;
      expect(state.city).toBe('Shanghai');
      expect(state.district).toBe('Jingan');
      expect(state.priceMax).toBe(6500000);

      // --- KEY: Verify new fields have been filled with reasonable defaults ---
      // sortBy should have a default value (e.g., empty string, null, or a default sort like 'default')
      // It should at least exist and not be undefined if the system fills defaults
      const sortByValue = state.sortBy;
      if (sortByValue !== undefined) {
        // If present, it should be a valid default (string or null)
        expect(typeof sortByValue === 'string' || sortByValue === null).toBe(true);
