import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function request(method, path, body, headers = {}) {
  const res = await fetch(`${BASE_URL}${path}`, {
    method,
    headers: {
      ...(body !== undefined ? { 'Content-Type': 'application/json' } : {}),
      ...headers,
    },
    body: body !== undefined ? JSON.stringify(body) : undefined,
  });
  const text = await res.text();
  let json;
  try {
    json = text ? JSON.parse(text) : null;
  } catch {
    json = text;
  }
  return { res, body: json, text };
}

async function safeDelete(path, headers = {}) {
  try {
    await fetch(`${BASE_URL}${path}`, { method: 'DELETE', headers });
  } catch {
    // ignore cleanup failure
  }
}

describe('cross_page_state_persist_and_restore_correctly', () => {
  it('should persist state across search/favorites/compare/detail contexts and keep detail readable after removing from compare', async () => {
    const sessionId = `cross-page-${Date.now()}-${Math.random().toString(36).slice(2)}`;
    const headers = { 'x-test-session-id': sessionId };
    const createdListingIds = [];
    const createdSchemeIds = [];

    try {
      // --- Setup: Create listings ---
      const createA = await request('POST', '/api/listings', {
        title: `Cross Page A ${Date.now()}`,
        city: 'Shanghai',
        district: 'Pudong',
        price: 5300000,
      });
      expect([200, 201]).toContain(createA.res.status);
      const listingA = createA.body.id || createA.body.listingId || createA.body.data?.id;
      expect(listingA).toBeTruthy();
      createdListingIds.push(listingA);

      const createB = await request('POST', '/api/listings', {
        title: `Cross Page B ${Date.now()}`,
        city: 'Shanghai',
        district: 'Minhang',
        price: 6300000,
      });
      expect([200, 201]).toContain(createB.res.status);
      const listingB = createB.body.id || createB.body.listingId || createB.body.data?.id;
      expect(listingB).toBeTruthy();
      createdListingIds.push(listingB);

      // --- Setup: Set filter state ---
      const setState = await request('PUT', '/api/user/filter-state', {
        city: 'Shanghai',
        priceMin: 3000000,
        priceMax: 7000000,
        rooms: [2, 3],
      }, headers);
      expect([200, 201]).toContain(setState.res.status);

      // --- Setup: Save filter scheme ---
      const saveScheme = await request('POST', '/api/filter-schemes', {
        name: '跨页方案',
        filters: { city: 'Shanghai', priceMin: 3000000, priceMax: 7000000, rooms: [2, 3] },
      }, headers);
      expect([200, 201]).toContain(saveScheme.res.status);
      const schemeId = saveScheme.body.id || saveScheme.body.schemeId || saveScheme.body.data?.id;
      expect(schemeId).toBeTruthy();
      createdSchemeIds.push(schemeId);

      // --- Setup: Add favorite and compare ---
      const addFav = await request('POST', '/api/favorites', { listingId: listingA }, headers);
      expect([200, 201]).toContain(addFav.res.status);

      const addCmpA = await request('POST', '/api/compare', { listingId: listingA }, headers);
      expect([200, 201]).toContain(addCmpA.res.status);
      const addCmpB = await request('POST', '/api/compare', { listingId: listingB }, headers);
      expect([200, 201]).toContain(addCmpB.res.status);

      // === Simulate "refresh" by using a new session-like header to prove persistence ===
      // Use a different request id to avoid caching, simulating a fresh page load
      const refreshHeaders = {
        ...headers,
        'Cache-Control': 'no-cache',
        'x-request-id': `refresh-${Date.now()}-${Math.random().toString(36).slice(2)}`,
      };

      // --- Verify filter state persisted after "refresh" ---
      const searchPageReload = await request('GET', '/api/user/filter-state', undefined, refreshHeaders);
      expect(searchPageReload.res.status).toBe(200);
      const searchState = searchPageReload.body.filters || searchPageReload.body.data || searchPageReload.body;
      expect(searchState.city).toBe('Shanghai');
      expect(searchState.priceMin).toBe(3000000);
      expect(searchState.priceMax).toBe(7000000);

      // --- Verify favorites persisted ---
      const favoritesPage = await request('GET', '/api/favorites', undefined, refreshHeaders);
      expect(favoritesPage.res.status).toBe(200);
      const favoriteItems = favoritesPage.body.items || favoritesPage.body.data || favoritesPage.body;
      const favoriteIds = Array.isArray(favoriteItems) ? favoriteItems.map(v => v.listingId || v.id) : [];
      expect(favoriteIds).toContain(listingA);

      // --- Verify compare list persisted ---
      const comparePage = await request('GET', '/api/compare', undefined, refreshHeaders);
      expect(comparePage.res.status).toBe(200);
      const compareItems = comparePage.body.items || comparePage.body.data || comparePage.body;
      const compareIds = Array.isArray(compareItems) ? compareItems.map(v => v.listingId || v.id) : [];
      expect(compareIds).toContain(listingA);
      expect(compareIds).toContain(listingB);

      // --- Verify schemes persisted ---
      const schemesPage = await request('GET', '/api/filter-schemes', undefined, refreshHeaders);
      expect(schemesPage.res.status).toBe(200);
      const schemes = schemesPage.body.items || schemesPage.body.data || schemesPage.body;
      expect(Array.isArray(schemes)).toBe(true);
      expect(schemes.some(v => v.name === '跨页方案')).toBe(true);

      // --- Verify detail page shows listing with correct states before removal ---
      const detailBeforeRemove = await request('GET', `/api/listings/${listingA}`, undefined, headers);
      expect(detailBeforeRemove.res.status).toBe(200);
      const detailDataBefore = detailBeforeRemove.body.data || detailBeforeRemove.body;
      expect(detailDataBefore.id || detailDataBefore.listingId).toBe(listingA);

      // --- Verify search results show listingA as favorited ---
      const searchResults = await request('GET', '/api/listings?city=Shanghai&priceMin=3000000&priceMax=7000000', undefined, headers);
      if (searchResults.res.status === 200) {
        const resultItems = searchResults.body.items || searchResults.body.data || searchResults.body;
        if (Array.isArray(resultItems)) {
          const listingAInResults = resultItems.find(v => (v.id || v.listingId) === listingA);
          if (listingAInResults) {
            // Check favorite status in search results
            const isFav = listingAInResults.isFavorite ?? listingAInResults.favorited ?? listingAInResults.meta?.isFavorite;
            if (isFav !== undefined) {
              expect(isFav).toBe(true);
            }
            // Check compare status in search results
            const inCmp = listingAInResults.inCompare ?? listingAInResults.isCompared ?? listingAInResults.meta?.inCompare;
            if (inCmp !== undefined) {
              expect(inCmp).toBe(true);
            }
          }
        }
      }

      // --- Remove listingA from compare ---
      const removeCompare = await request('DELETE', `/api/compare/${listingA}`, undefined, headers);
      expect([200, 204]).toContain(removeCompare.res.status);

      // --- Verify detail page still accessible after removal from compare ---
      const detailAfterRemove = await request('GET', `/api/listings/${listingA}`, undefined, headers);
      expect(detailAfterRemove.res.status).toBe(200);
      const detailDataAfter = detailAfterRemove.body.data || detailAfterRemove.body;
      expect(detailDataAfter.id || detailDataAfter.listingId).toBe(listingA);

      // --- Verify compare list no longer contains listingA ---
      const comparePageAfter = await request('GET', '/api/compare', undefined, headers);
      expect(comparePageAfter.res.status).toBe(200);
      const compareItemsAfter = comparePageAfter.body.items || comparePageAfter.body.data || comparePageAfter.body;
      const compareIdsAfter = Array.isArray(compareItemsAfter) ? compareItemsAfter.map(v => v.listingId || v.id) : [];
      expect(compareIdsAfter).not.toContain(listingA);
      expect(compareIdsAfter).toContain(listingB);

      // --- Strongly assert compare status on detail page is "not in compare" ---
      const inCompareAfter = detailDataAfter.inCompare ?? detailDataAfter.isCompared ?? detailDataAfter.meta?.inCompare ?? detailDataAfter.meta?.isCompared;
      // The field should exist and be false, OR the compare list check above already proves it
      if (inCompareAfter !== undefined) {
        expect(inCompareAfter, 'Detail page should show listing as NOT in compare after removal').toBe(false);
      }
      // If the detail endpoint doesn't return inCompare, we've already verified via the compare list endpoint above

      // --- Strongly assert favorite status remains true on detail page ---
      const isFavoriteAfter = detailDataAfter.isFavorite ?? detailDataAfter.favorited ?? detailDataAfter.meta?.isFavorite ?? detailDataAfter.meta?.favorited;
      if (isFavoriteAfter !== undefined) {
        expect(isFavoriteAfter, 'Detail page should still show listing as favorited').toBe(true);
      }

      // --- Verify favorited status is also reflected in favorites list (listingA should still be there) ---
      const favsAfterCompareRemove = await request('GET', '/api/favorites', undefined, headers);
      expect(favsAfterCompareRemove.res.status).toBe(200);
      const favsItemsAfter = favsAfterCompareRemove.body.items || favsAfterCompareRemove.body.data || favsAfterCompareRemove.body;
      const favIdsAfter = Array.isArray(favsItemsAfter) ? favsItemsAfter.map(v => v.listingId || v.id) : [];
      expect(favIdsAfter, 'Removing from compare should not affect favorites').toContain(listingA);

    } finally {
      // Cleanup
      for (const id of createdSchemeIds) {
        await safeDelete(`/api/filter-schemes/${id}`, headers);
      }
      // Clean up favorites
      try {
        for (const id of createdListingIds) {
          await safeDelete(`/api/favorites/${id}`, headers);
        }
      } catch { /* ignore */ }
      // Clean up remaining compare items
      try {
        for (const id of createdListingIds) {
          await safeDelete(`/api/compare/${id}`, headers);
        }
      } catch { /* ignore */ }
      for (const id of createdListingIds) {
        await safeDelete(`/api/listings/${id}`);
      }
    }
  });
});

import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function request(method: string, path: string, body?: any) {
  const res = await fetch(`${BASE_URL}${path}`, {
    method,
    headers: { 'Content-Type': 'application/json' },
    body: body === undefined ? undefined : JSON.stringify(body),
  });
  let data: any = null;
  const text = await res.text();
  try { data = text ? JSON.parse(text) : null; } catch { data = text; }
  return { res, body: data };
}

async function tryDeleteProject(projectId: string | number | undefined) {
  if (!projectId) return;
  try { await request('DELETE', `/api/projects/${projectId}`); } catch {}
}

describe('align_and_distribute_updates_positions_without_reordering', () => {
  it('should update positions for all alignment/distribution types, enforce min-count constraints, preserve layer order, stay in canvas bounds, and produce stable results', async () => {
    const suffix = `${Date.now()}_${Math.random().toString(36).slice(2, 8)}`;
    let projectId: string | number | undefined;

    try {
      // Create project
      const proj = await request('POST', '/api/projects', { name: `verifier-align-${suffix}` });
      expect(proj.res.status).toBeGreaterThanOrEqual(200);
      expect(proj.res.status).toBeLessThan(300);
      projectId = proj.body?.id;
      expect(projectId).toBeTruthy();

      // Create page
      const page = await request('POST', `/api/projects/${projectId}/pages`, { name: `Page-${suffix}` });
      expect(page.res.status).toBeGreaterThanOrEqual(200);
      expect(page.res.status).toBeLessThan(300);
      const pageId = page.body?.id;
      expect(pageId).toBeTruthy();

      // Get canvas size for boundary checks (default or from page)
      const pageInfo = await request('GET', `/api/projects/${projectId}/pages/${pageId}`);
      const canvasWidth = pageInfo.body?.width || pageInfo.body?.canvasWidth || 1024;
      const canvasHeight = pageInfo.body?.height || pageInfo.body?.canvasHeight || 768;

      // Create 3 components with different sizes for thorough testing
      const c1 = await request('POST', `/api/projects/${projectId}/pages/${pageId}/components`, {
        name: 'A', type: 'text', x: 120, y: 80, width: 100, height: 40, text: 'A',
      });
      expect(c1.res.status).toBeGreaterThanOrEqual(200);
      expect(c1.res.status).toBeLessThan(300);
      const c1Id = c1.body?.id;
      expect(c1Id).toBeTruthy();

      const c2 = await request('POST', `/api/projects/${projectId}/pages/${pageId}/components`, {
        name: 'B', type: 'text', x: 260, y: 140, width: 120, height: 50, text: 'B',
      });
      expect(c2.res.status).toBeGreaterThanOrEqual(200);
      expect(c2.res.status).toBeLessThan(300);
      const c2Id = c2.body?.id;
      expect(c2Id).toBeTruthy();

      const c3 = await request('POST', `/api/projects/${projectId}/pages/${pageId}/components`, {
        name: 'C', type: 'text', x: 420, y: 260, width: 80, height: 30, text: 'C',
      });
      expect(c3.res.status).toBeGreaterThanOrEqual(200);
      expect(c3.res.status).toBeLessThan(300);
      const c3Id = c3.body?.id;
      expect(c3Id).toBeTruthy();

      const allIds = [c1Id, c2Id, c3Id];

      // Get initial layer order
      const beforePage = await request('GET', `/api/projects/${projectId}/pages/${pageId}`);
      expect(beforePage.res.status).toBeGreaterThanOrEqual(200);
      expect(beforePage.res.status).toBeLessThan(300);
      const beforeOrder = (beforePage.body?.components || []).map((c: any) => c.id);
      expect(beforeOrder).toEqual(expect.arrayContaining(allIds));

      // Helper to reset positions
      async function resetPositions() {
        await request('PUT', `/api/projects/${projectId}/pages/${pageId}/components/${c1Id}`, { x: 120, y: 80, width: 100, height: 40 });
        await request('PUT', `/api/projects/${projectId}/pages/${pageId}/components/${c2Id}`, { x: 260, y: 140, width: 120, height: 50 });
        await request('PUT', `/api/projects/${projectId}/pages/${pageId}/components/${c3Id}`, { x: 420, y: 260, width: 80, height: 30 });
      }

      // Helper to get components after operation
      async function getComponents() {
        const r = await request('GET', `/api/projects/${projectId}/pages/${pageId}`);
        expect(r.res.status).toBeGreaterThanOrEqual(200);
        expect(r.res.status).toBeLessThan(300);
        return r.body?.components || [];
      }

      // Helper to verify layer order unchanged
      function verifyOrder(comps: any[], label: string) {
        const order = comps.map((c: any) => c.id);
        expect(order, `layer order should be unchanged after ${label}`).toEqual(beforeOrder);
      }

      // Helper to verify all components are within canvas visible range
      function verifyInBounds(comps: any[], label: string) {
        for (const c of comps) {
          if (allIds.includes(c.id)) {
            expect(c.x, `${label}: component ${c.name} x should be >= 0`).toBeGreaterThanOrEqual(0);
            expect(c.y, `${label}: component ${c.name} y should be >= 0`).toBeGreaterThanOrEqual(0);
            expect(c.x + (c.width || 0), `${label}: component ${c.name} right edge should be within canvas`).toBeLessThanOrEqual(canvasWidth + 100); // allow small tolerance
            expect(c.y + (c.height || 0), `${label}: component ${c.name} bottom edge should be within canvas`).toBeLessThanOrEqual(canvasHeight + 100);
          }
        }
      }

      // Try both possible align endpoint patterns
      async function tryAlign(action: string, componentIds: any[]) {
        // Try POST /align endpoint
        let r = await request('POST', `/api/projects/${projectId}/pages/${pageId}/align`, {
          action,
          componentIds,
        });
        if (r.res.status === 404) {
          // Try alternative endpoint
          r = await request('POST', `/api/projects/${projectId}/pages/${pageId}/components/align`, {
            action,
            componentIds,
          });
        }
        return r;
      }

      // --- Boundary: single component alignment should be rejected ---
      const singleAlignRes = await tryAlign('left', [c1Id]);
      expect(
        singleAlignRes.res.status >= 400,
        `alignment with single component should be rejected, got status ${singleAlignRes.res.status}`,
      ).toBe(true);

      // --- Boundary: distribute with only 2 components should be rejected ---
      const twoDistribute = await tryAlign('horizontal-distribute', [c1Id, c2Id]);
      expect(
        twoDistribute.res.status >= 400,
        `horizontal-distribute with only 2 components should be rejected, got status ${twoDistribute.res.status}`,
      ).toBe(true);

      const twoVertDistribute = await tryAlign('vertical-distribute', [c1Id, c2Id]);
      expect(
        twoVertDistribute.res.status >= 400,
        `vertical-distribute with only 2 components should be rejected, got status ${twoVertDistribute.res.status}`,
      ).toBe(true);

      // --- Left align with 3 components ---
      await resetPositions();
      const leftAlign = await tryAlign('left', allIds);
      expect(leftAlign.res.status).toBeGreaterThanOrEqual(200);
      expect(leftAlign.res.status).toBeLessThan(300);

      let comps = await getComponents();
      let ca = comps.find((c: any) => c.id === c1Id);
      let cb = comps.find((c: any) => c.id === c2Id);
      let cc = comps.find((c: any) => c.id === c3Id);
      expect(ca).toBeTruthy(); expect(cb).toBeTruthy(); expect(cc).toBeTruthy();
      // After left-align, all x values should be the minimum x
      const minX = Math.min(120, 260, 420); // original positions
      expect(ca!.x, 'left-align: A.x').toBe(minX);
      expect(cb!.x, 'left-align: B.x').toBe(minX);
      expect(cc!.x, 'left-align: C.x').toBe(minX);
      verifyOrder(comps, 'left-align');
      verifyInBounds(comps, 'left-align');

      // --- Right align ---
      await resetPositions();
      const rightAlign = await tryAlign('right', allIds);
      expect(rightAlign.res.status).toBeGreaterThanOrEqual(200);
      expect(rightAlign.res.status).toBeLessThan(300);

      comps = await getComponents();
      ca = comps.find((c: any) => c.id === c1Id);
      cb = comps.find((c: any) => c.id === c2Id);
      cc = comps.find((c: any) => c.id === c3Id);
      // After right-align, all right edges (x + width) should be the same
      const maxRight = Math.max(120 + 100, 260 + 120, 420 + 80); // 500
      expect(ca!.x + (ca!.width || 100), 'right-align: A right edge').toBe(maxRight);
      expect(cb!.x + (cb!.width || 120), 'right-align: B right edge').toBe(maxRight);
      expect(cc!.x + (cc!.width || 80), 'right-align: C right edge').toBe(maxRight);
      verifyOrder(comps, 'right-align');
      verifyInBounds(comps, 'right-align');

      // --- Top align ---
      await resetPositions();
      const topAlign = await tryAlign('top', allIds);
      expect(topAlign.res.status).toBeGreaterThanOrEqual(200);
      expect(topAlign.res.status).toBeLessThan(300);

      comps = await getComponents();
      ca = comps.find((c: any) => c.id === c1Id);
      cb = comps.find((c: any) => c.id === c2Id);
      cc = comps.find((c: any) => c.id === c3Id);
      const minY = Math.min(80, 140, 260);
      expect(ca!.y, 'top-align: A.y').toBe(minY);
      expect(cb!.y, 'top-align: B.y').toBe(minY);
      expect(cc!.y, 'top-align: C.y').toBe(minY);
      verifyOrder(comps, 'top-align');

      // --- Bottom align ---
      await resetPositions();
      const bottomAlign = await tryAlign('bottom', allIds);
      expect(bottomAlign.res.status).toBeGreaterThanOrEqual(200);
