      const vCenterB = cb!.y + (cb!.height || 50) / 2;
      const vCenterC = cc!.y + (cc!.height || 30) / 2;
      expect(Math.abs(vCenterA - vCenterB), 'vertical-center: A and B centers should match').toBeLessThanOrEqual(1);
      expect(Math.abs(vCenterB - vCenterC), 'vertical-center: B and C centers should match').toBeLessThanOrEqual(1);
      verifyOrder(comps, 'vertical-center');

      // --- Horizontal distribute with 3 components ---
      await resetPositions();
      const hDistribute = await tryAlign('horizontal-distribute', allIds);
      expect(hDistribute.res.status).toBeGreaterThanOrEqual(200);
      expect(hDistribute.res.status).toBeLessThan(300);

