      expect(ca!.x).toBeGreaterThanOrEqual(0);
      expect(cb!.x).toBeGreaterThanOrEqual(0);
      expect(cc!.x).toBeGreaterThanOrEqual(0);

      // Sort by x and check edge-to-edge gaps are equal (considering width)
      const hSorted = [
        { x: ca!.x, w: ca!.width || 100 },
        { x: cb!.x, w: cb!.width || 120 },
        { x: cc!.x, w: cc!.width || 80 },
      ].sort((a, b) => a.x - b.x);
      const hGap1 = hSorted[1].x - (hSorted[0].x + hSorted[0].w);
      const hGap2 = hSorted[2].x - (hSorted[1].x + hSorted[1].w);
      expect(Math.abs(hGap1 - hGap2), `distributed horizontal gaps should be equal (considering width), got gap1=${hGap1}, gap2=${hGap2}`).toBeLessThanOrEqual(1);

      verifyOrder(comps, 'horizontal-distribute');
      verifyInBounds(comps, 'horizontal-distribute');

