      expect(cb2!.x, 'stable: B.x should be same on repeated distribute').toBe(cb!.x);
      expect(cc2!.x, 'stable: C.x should be same on repeated distribute').toBe(cc!.x);

      // --- Vertical distribute ---
      await resetPositions();
      const vDistribute = await tryAlign('vertical-distribute', allIds);
      expect(vDistribute.res.status).toBeGreaterThanOrEqual(200);
      expect(vDistribute.res.status).toBeLessThan(300);

      comps = await getComponents();
      ca = comps.find((c: any) => c.id === c1Id);
      cb = comps.find((c: any) => c.id === c2Id);
      cc = comps.find((c: any) => c.id === c3Id);

      // Sort by y and check edge-to-edge gaps are equal (considering height)
      const vSorted = [
        { y: ca!.y, h: ca!.height || 40 },
        { y: cb!.y, h: cb!.height || 50 },
        { y: cc!.y, h: cc!.height || 30 },
      ].sort((a, b) => a.y - b.y);
      const vGap1 = vSorted[1].y - (vSorted[0].y + vSorted[0].h);
      const vGap2 = vSorted[2].y - (vSorted[1].y + vSorted[1].h);
      expect(Math.abs(vGap1 - vGap2), `distributed vertical gaps should be equal (considering height), got gap1=${vGap1}, gap2=${vGap2}`).toBeLessThanOrEqual(1);

      verifyOrder(comps, 'vertical-distribute');
      verifyInBounds(comps, 'vertical-distribute');

      // --- Boundary: components near canvas edge, alignment should keep them visible ---
      await request('PUT', `/api/projects/${projectId}/pages/${pageId}/components/${c1Id}`, { x: canvasWidth - 20, y: canvasHeight - 10, width: 100, height: 40 });
      await request('PUT', `/api/projects/${projectId}/pages/${pageId}/components/${c2Id}`, { x: 10, y: 10, width: 120, height: 50 });
      await request('PUT', `/api/projects/${projectId}/pages/${pageId}/components/${c3Id}`, { x: canvasWidth - 50, y: canvasHeight - 20, width: 80, height: 30 });

      const edgeAlign = await tryAlign('right', allIds);
      if (edgeAlign.res.status >= 200 && edgeAlign.res.status < 300) {
        comps = await getComponents();
        for (const c of comps) {
          if (allIds.includes(c.id)) {
            // Component should still be at least partially visible
            expect(c.x, `edge test: ${c.name} x should be >= 0`).toBeGreaterThanOrEqual(0);
            expect(c.y, `edge test: ${c.name} y should be >= 0`).toBeGreaterThanOrEqual(0);
          }
        }
      }
    } finally {
      await tryDeleteProject(projectId);
    }
  });
});

