describe('round29_search_text_replace_with_undo', () => {
  it('should count impacted pages/components for text replace, replace only text content, handle boundary cases, handle deleted components, and undo in one step', async () => {
    const suffix = `${Date.now()}_${Math.random().toString(36).slice(2, 8)}`;
    let projectId: string | number | undefined;

    try {
      // --- Setup project with two pages and components ---
      const proj = await request('POST', '/api/projects', { name: `proj_round29_${suffix}` });
      expect(proj.res.status).toBeGreaterThanOrEqual(200);
      expect(proj.res.status).toBeLessThan(300);
      projectId = proj.body?.id ?? proj.body?.projectId;
      expect(projectId).toBeTruthy();

      const page1 = await request('POST', `/api/projects/${projectId}/pages`, { name: `Page1_${suffix}` });
      const page2 = await request('POST', `/api/projects/${projectId}/pages`, { name: `Page2_${suffix}` });
      expect(page1.res.status).toBeGreaterThanOrEqual(200);
      expect(page1.res.status).toBeLessThan(300);
      expect(page2.res.status).toBeGreaterThanOrEqual(200);
      expect(page2.res.status).toBeLessThan(300);
      const page1Id = page1.body?.id ?? page1.body?.pageId;
      const page2Id = page2.body?.id ?? page2.body?.pageId;
      expect(page1Id).toBeTruthy();
      expect(page2Id).toBeTruthy();

      // Component on page 1 with "target" in text, component name should NOT be changed
      const c1 = await request('POST', `/api/projects/${projectId}/pages/${page1Id}/components`, {
        type: 'text',
        name: 'ButtonNameShouldStay',
        text: 'foo target foo',
        x: 0,
        y: 0,
        width: 100,
        height: 20,
      });
      // Component on page 2 with "target" in text
      const c2 = await request('POST', `/api/projects/${projectId}/pages/${page2Id}/components`, {
        type: 'text',
        name: 'LibraryNameShouldStay',
        text: 'target only',
        x: 0,
        y: 30,
        width: 100,
        height: 20,
      });
      // Component on page 2 that will be deleted before replace execution
      const c3 = await request('POST', `/api/projects/${projectId}/pages/${page2Id}/components`, {
        type: 'text',
        name: 'WillBeDeleted',
        text: 'target to delete',
        x: 0,
        y: 60,
        width: 100,
        height: 20,
      });
      expect(c1.res.status).toBeGreaterThanOrEqual(200);
      expect(c1.res.status).toBeLessThan(300);
      expect(c2.res.status).toBeGreaterThanOrEqual(200);
      expect(c2.res.status).toBeLessThan(300);
      expect(c3.res.status).toBeGreaterThanOrEqual(200);
      expect(c3.res.status).toBeLessThan(300);
      const c1Id = c1.body?.id;
      const c2Id = c2.body?.id;
      const c3Id = c3.body?.id;
      expect(c1Id).toBeTruthy();
      expect(c2Id).toBeTruthy();
      expect(c3Id).toBeTruthy();

      // --- Determine search/replace endpoints ---
      // Try preview
      let previewPath = `/api/projects/${projectId}/search-replace/preview`;
      let executePath = `/api/projects/${projectId}/search-replace/execute`;
      let undoPath = `/api/projects/${projectId}/undo`;

      let preview = await request('POST', previewPath, {
        search: 'target',
        replace: 'updated',
      });
      if (preview.res.status === 404) {
        previewPath = `/api/projects/${projectId}/search/replace-preview`;
        preview = await request('POST', previewPath, {
          search: 'target',
          replace: 'updated',
        });
      }
      if (preview.res.status === 404) {
        previewPath = `/api/projects/${projectId}/replace/preview`;
        preview = await request('POST', previewPath, {
          search: 'target',
          replace: 'updated',
        });
      }
      expect(preview.res.status).toBeGreaterThanOrEqual(200);
      expect(preview.res.status).toBeLessThan(300);

      // Preview should report affected pages and components count
      const matchedPages = preview.body?.matchedPages ?? preview.body?.affectedPages ?? preview.body?.pageCount;
      const matchedComponents = preview.body?.matchedComponents ?? preview.body?.affectedComponents ?? preview.body?.componentCount ?? preview.body?.matchCount;
      expect(matchedPages).toBeDefined();
      expect(matchedComponents).toBeDefined();
      // We have 3 components with "target" across 2 pages
      expect(matchedPages).toBe(2);
      expect(matchedComponents).toBe(3);

      // --- Boundary test 1: Empty replacement string ---
      const emptyReplace = await request('POST', previewPath.replace('preview', 'execute').replace('replace-preview', 'replace'), {
        search: 'target',
        replace: '',
      });
      // Empty replace should either be rejected (400/422) or handled specifically
      // If accepted, we just verify it doesn't crash
      if (emptyReplace.res.status >= 400) {
        expect([400, 422]).toContain(emptyReplace.res.status);
      }
      // If it was executed, we need to undo it
      if (emptyReplace.res.status >= 200 && emptyReplace.res.status < 300) {
        await request('POST', undoPath);
      }

      // --- Boundary test 2: Super long replacement string ---
      const longString = 'x'.repeat(10000);
      const longReplace = await request('POST', previewPath.replace('preview', 'execute').replace('replace-preview', 'replace'), {
        search: 'target',
        replace: longString,
      });
      if (longReplace.res.status >= 400) {
        expect([400, 422]).toContain(longReplace.res.status);
      }
      if (longReplace.res.status >= 200 && longReplace.res.status < 300) {
        await request('POST', undoPath);
      }

      // --- Boundary test 3: Replace with same text (search === replace) ---
      const sameReplace = await request('POST', previewPath, {
        search: 'target',
        replace: 'target',
      });
      // Should handle gracefully - either reject, report 0 effective changes, or allow
      expect(sameReplace.res.status).toBeGreaterThanOrEqual(200);
      expect(sameReplace.res.status).toBeLessThan(500);

      // --- Step: Delete c3 before executing replace (simulating deleted-before-confirm) ---
      const delC3 = await request('DELETE', `/api/projects/${projectId}/pages/${page2Id}/components/${c3Id}`);
      expect([200, 204]).toContain(delC3.res.status);

      // --- Execute the actual replace (target -> updated) ---
      // Now only 2 components should be affected (c3 was deleted)
      if (executePath.includes('search-replace')) {
        // keep as is
      } else {
        executePath = previewPath.replace('preview', 'execute').replace('replace-preview', 'replace');
      }
      const replace = await request('POST', executePath, {
        search: 'target',
        replace: 'updated',
      });
      expect(replace.res.status).toBeGreaterThanOrEqual(200);
      expect(replace.res.status).toBeLessThan(300);

      // Verify replace reports statistics (including skipped count for deleted component)
      const replacedCount = replace.body?.matchedComponents ?? replace.body?.replacedCount ?? replace.body?.affectedComponents;
      if (replacedCount !== undefined) {
        expect(replacedCount).toBe(2); // c3 was deleted, so only 2 should be affected
      }
      const skippedCount = replace.body?.skippedCount ?? replace.body?.skipped;
      // skippedCount may or may not be present; if it is, it should reflect the deleted component
      if (skippedCount !== undefined) {
        expect(skippedCount).toBeGreaterThanOrEqual(0);
      }

      // --- Verify replacement results ---
      const c1After = await request('GET', `/api/projects/${projectId}/pages/${page1Id}/components/${c1Id}`);
      const c2After = await request('GET', `/api/projects/${projectId}/pages/${page2Id}/components/${c2Id}`);
      expect(c1After.res.status).toBeGreaterThanOrEqual(200);
      expect(c1After.res.status).toBeLessThan(300);
      expect(c2After.res.status).toBeGreaterThanOrEqual(200);
      expect(c2After.res.status).toBeLessThan(300);

      // Text content should be replaced
      expect(c1After.body?.text).toBe('foo updated foo');
      expect(c2After.body?.text).toBe('updated only');

      // Component names must NOT be changed (non-text fields)
      expect(
        c1After.body?.name,
        `replace should not modify component name, got ${c1After.body?.name}`,
      ).toBe('ButtonNameShouldStay');
      expect(
        c2After.body?.name,
        `replace should not modify component name, got ${c2After.body?.name}`,
      ).toBe('LibraryNameShouldStay');

      // --- Undo the batch replace in one step ---
      const undo = await request('POST', undoPath);
      expect(undo.res.status).toBeGreaterThanOrEqual(200);
      expect(undo.res.status).toBeLessThan(300);

      // Verify undo restored original text
      const c1Undo = await request('GET', `/api/projects/${projectId}/pages/${page1Id}/components/${c1Id}`);
      const c2Undo = await request('GET', `/api/projects/${projectId}/pages/${page2Id}/components/${c2Id}`);
      expect(c1Undo.res.status).toBeGreaterThanOrEqual(200);
      expect(c1Undo.res.status).toBeLessThan(300);
      expect(c2Undo.res.status).toBeGreaterThanOrEqual(200);
      expect(c2Undo.res.status).toBeLessThan(300);

      expect(
        c1Undo.body?.text,
        `undo should restore original text, got ${c1Undo.body?.text}`,
      ).toBe('foo target foo');
      expect(
        c2Undo.body?.text,
        `undo should restore original text, got ${c2Undo.body?.text}`,
      ).toBe('target only');

      // Component names should still be intact after undo
      expect(c1Undo.body?.name).toBe('ButtonNameShouldStay');
      expect(c2Undo.body?.name).toBe('LibraryNameShouldStay');
    } finally {
      await cleanupProject(projectId);
    }
  });
});

