describe('round20_project_import_export_and_legacy_compat', () => {
  it('should export/import project, support legacy snapshot defaults, and keep current data intact on failed import', async () => {
    const suffix = `${Date.now()}_${Math.random().toString(36).slice(2, 8)}`;
    let projectId: string | number | undefined;

    try {
      const created = await request('POST', '/api/projects', { name: `proj_round20_${suffix}` });
      expect(created.res.status).toBeGreaterThanOrEqual(200);
      expect(created.res.status).toBeLessThan(300);
      projectId = created.body?.id;
      expect(projectId).toBeTruthy();

      const page = await request('POST', `/api/projects/${projectId}/pages`, { name: `Page_${suffix}` });
      expect(page.res.status).toBeGreaterThanOrEqual(200);
      expect(page.res.status).toBeLessThan(300);
      const pageId = page.body?.id;
      expect(pageId).toBeTruthy();

      const comp = await request('POST', `/api/projects/${projectId}/pages/${pageId}/components`, {
        type: 'text', name: `Text_${suffix}`, text: 'export_me', x: 1, y: 2, width: 100, height: 20,
      });
      expect(comp.res.status).toBeGreaterThanOrEqual(200);
      expect(comp.res.status).toBeLessThan(300);
      expect(comp.body?.text).toBe('export_me');

      const exported = await request('GET', `/api/projects/${projectId}/export`);
      expect(exported.res.status).toBeGreaterThanOrEqual(200);
      expect(exported.res.status).toBeLessThan(300);
      expect(exported.body, `exported project snapshot should exist, got ${JSON.stringify(exported.body)}`).toBeTruthy();
      expect(Array.isArray(exported.body?.pages), `exported snapshot should include pages, got ${JSON.stringify(exported.body)}`).toBe(true);
      expect(exported.body.pages.length).toBeGreaterThan(0);

      const replaceImport = await request('POST', `/api/projects/${projectId}/import`, {
        mode: 'replace',
        snapshot: exported.body,
      });
      expect(replaceImport.res.status).toBeGreaterThanOrEqual(200);
      expect(replaceImport.res.status).toBeLessThan(300);
      expect(replaceImport.body?.projectId ?? projectId).toBe(projectId);

      const afterImport = await request('GET', `/api/projects/${projectId}`);
      expect(afterImport.res.status).toBeGreaterThanOrEqual(200);
      expect(afterImport.res.status).toBeLessThan(300);
      expect(Array.isArray(afterImport.body?.pages)).toBe(true);
      expect(afterImport.body.pages.some((p: any) => p.name === `Page_${suffix}`), `imported project should restore page name Page_${suffix}, got ${JSON.stringify(afterImport.body)}`).toBe(true);

      const legacySnapshot = {
        version: 1,
        name: `legacy_${suffix}`,
        pages: [
          {
            name: `LegacyPage_${suffix}`,
            components: [
              { type: 'text', text: 'legacy_text', x: 5, y: 6, width: 90, height: 18 },
            ],
          },
        ],
      };

      const legacyImport = await request('POST', `/api/projects/${projectId}/import`, {
        mode: 'append',
        snapshot: legacySnapshot,
      });
      expect(legacyImport.res.status).toBeGreaterThanOrEqual(200);
      expect(legacyImport.res.status).toBeLessThan(300);

      const afterLegacy = await request('GET', `/api/projects/${projectId}`);
      expect(afterLegacy.res.status).toBeGreaterThanOrEqual(200);
      expect(afterLegacy.res.status).toBeLessThan(300);
      const legacyPage = afterLegacy.body?.pages?.find((p: any) => String(p.name).includes(`LegacyPage_${suffix}`));
      expect(legacyPage, `legacy page should be imported, got ${JSON.stringify(afterLegacy.body)}`).toBeTruthy();
      if (legacyPage) {
        expect(legacyPage.id, `legacy-imported page should receive default/generated id, got ${JSON.stringify(legacyPage)}`).toBeTruthy();
      }

      const invalidImport = await request('POST', `/api/projects/${projectId}/import`, {
        mode: 'append',
        snapshot: 'not_a_valid_snapshot',
      });
      expect(
        [400, 409, 422].includes(invalidImport.res.status),
        `invalid import should be rejected with 400/409/422, got ${invalidImport.res.status}`,
      ).toBe(true);

      const afterInvalid = await request('GET', `/api/projects/${projectId}`);
      expect(afterInvalid.res.status).toBeGreaterThanOrEqual(200);
      expect(afterInvalid.res.status).toBeLessThan(300);
      expect(
        afterInvalid.body?.pages?.some((p: any) => p.name === `Page_${suffix}`),
        `failed import should not destroy current project data, got ${JSON.stringify(afterInvalid.body)}`,
      ).toBe(true);
      expect(
        afterInvalid.body?.pages?.some((p: any) => String(p.name).includes(`LegacyPage_${suffix}`)),
        `failed import should not remove previously imported legacy page, got ${JSON.stringify(afterInvalid.body)}`,
      ).toBe(true);
    } finally {
      await cleanupProject(projectId);
    }
  });
});

