        name: `SourceText_${suffix}`,
        text: 'v1',
        x: 10,
        y: 20,
        width: 100,
        height: 24,
      });
      expect(createComponent.res.status).toBeGreaterThanOrEqual(200);
      expect(createComponent.res.status).toBeLessThan(300);
      const sourceComponentId = createComponent.body?.id;
      expect(sourceComponentId).toBeTruthy();
      expect(createComponent.body?.text).toBe('v1');

      // --- Save component to library ---
      const saveLibraryItem = await request('POST', `/api/projects/${projectId}/library`, {
        name: `LibItem_${suffix}`,
        sourceComponentIds: [sourceComponentId],
      });
      if (saveLibraryItem.res.status === 404) {
        // Try alternative path
        const saveLibAlt = await request('POST', `/api/projects/${projectId}/library-items`, {
          name: `LibItem_${suffix}`,
          sourceComponentIds: [sourceComponentId],
        });
        expect(saveLibAlt.res.status).toBeGreaterThanOrEqual(200);
        expect(saveLibAlt.res.status).toBeLessThan(300);
      }
      const libPath = saveLibraryItem.res.status < 300 ? 'library' : 'library-items';
      const libResp = saveLibraryItem.res.status < 300 ? saveLibraryItem : await request('POST', `/api/projects/${projectId}/library-items`, {
        name: `LibItem_${suffix}`,
        sourceComponentIds: [sourceComponentId],
      });
      expect(libResp.res.status).toBeGreaterThanOrEqual(200);
      expect(libResp.res.status).toBeLessThan(300);
      const libraryItemId = libResp.body?.id ?? libResp.body?.libraryItemId;
      expect(libraryItemId).toBeTruthy();
      expect(libResp.body?.name).toBe(`LibItem_${suffix}`);

      // --- Instantiate from library (instance 1) ---
      // Try multiple possible paths for instantiation
      let instantiate1 = await request('POST', `/api/projects/${projectId}/pages/${pageId}/components`, {
        libraryItemId,
        x: 100,
        y: 100,
      });
      if (instantiate1.res.status >= 400) {
        instantiate1 = await request('POST', `/api/projects/${projectId}/pages/${pageId}/instances`, {
          libraryItemId,
          x: 100,
          y: 100,
        });
      }
      expect(instantiate1.res.status).toBeGreaterThanOrEqual(200);
      expect(instantiate1.res.status).toBeLessThan(300);
      const instance1Id = instantiate1.body?.id ?? instantiate1.body?.componentId ?? instantiate1.body?.instanceId;
      expect(instance1Id).toBeTruthy();

      // Verify source library reference is visible
      const instance1Source = instantiate1.body?.libraryItemId ?? instantiate1.body?.libraryId ?? instantiate1.body?.sourceLibraryItemId;
      expect(
        instance1Source,
        `instance should record source library item id, got ${JSON.stringify(instantiate1.body)}`,
      ).toBeTruthy();

      // --- Detach instance 1 from library ---
      // Try several possible detach paths
      let detach = await request('POST', `/api/projects/${projectId}/pages/${pageId}/components/${instance1Id}/detach`);
      if (detach.res.status >= 400) {
        detach = await request('POST', `/api/projects/${projectId}/instances/${instance1Id}/detach`);
      }
      if (detach.res.status >= 400) {
        detach = await request('PATCH', `/api/projects/${projectId}/pages/${pageId}/components/${instance1Id}`, {
          libraryItemId: null,
          detach: true,
        });
      }
      expect(detach.res.status).toBeGreaterThanOrEqual(200);
      expect(detach.res.status).toBeLessThan(300);
      const detachedLibRef = detach.body?.libraryItemId ?? detach.body?.sourceLibraryItemId ?? null;
      expect(
        detachedLibRef,
        `detached instance should no longer reference library item, got ${JSON.stringify(detach.body)}`,
      ).toBeNull();

      // --- Create instance 2 (still linked to library, text = v1) ---
      let instantiate2 = await request('POST', `/api/projects/${projectId}/pages/${pageId}/components`, {
        libraryItemId,
        x: 200,
        y: 200,
      });
      if (instantiate2.res.status >= 400) {
        instantiate2 = await request('POST', `/api/projects/${projectId}/pages/${pageId}/instances`, {
          libraryItemId,
          x: 200,
          y: 200,
        });
      }
      expect(instantiate2.res.status).toBeGreaterThanOrEqual(200);
      expect(instantiate2.res.status).toBeLessThan(300);
      const instance2Id = instantiate2.body?.id ?? instantiate2.body?.componentId ?? instantiate2.body?.instanceId;
      expect(instance2Id).toBeTruthy();

      // --- Modify instance 2 text to v2, then use "update library from instance" ---
      // First update instance 2's text to v2
      const patchInst2 = await request('PATCH', `/api/projects/${projectId}/pages/${pageId}/components/${instance2Id}`, {
        text: 'v2',
      });
      expect(patchInst2.res.status).toBeGreaterThanOrEqual(200);
      expect(patchInst2.res.status).toBeLessThan(300);

      // Now trigger "update library item from current instance"
      let updateFromInstance = await request('POST', `/api/projects/${projectId}/pages/${pageId}/components/${instance2Id}/update-library`);
      if (updateFromInstance.res.status >= 400) {
        updateFromInstance = await request('POST', `/api/projects/${projectId}/instances/${instance2Id}/update-library`);
      }
      if (updateFromInstance.res.status >= 400) {
        updateFromInstance = await request('POST', `/api/projects/${projectId}/pages/${pageId}/components/${instance2Id}/push-to-library`);
      }
      if (updateFromInstance.res.status >= 400) {
        // Fallback: directly PUT library item template (less ideal but still tests the flow)
        updateFromInstance = await request('PUT', `/api/projects/${projectId}/${libPath}/${libraryItemId}`, {
          name: `LibItem_${suffix}`,
          template: {
            components: [
              {
                type: 'text',
                name: `SourceText_${suffix}`,
                text: 'v2',
                x: 10,
                y: 20,
                width: 100,
                height: 24,
              },
            ],
          },
        });
      }
      expect(updateFromInstance.res.status).toBeGreaterThanOrEqual(200);
      expect(updateFromInstance.res.status).toBeLessThan(300);

      // --- Instantiate instance 3 (should get v2 from updated library) ---
      let instantiate3 = await request('POST', `/api/projects/${projectId}/pages/${pageId}/components`, {
        libraryItemId,
        x: 300,
        y: 300,
      });
      if (instantiate3.res.status >= 400) {
        instantiate3 = await request('POST', `/api/projects/${projectId}/pages/${pageId}/instances`, {
          libraryItemId,
          x: 300,
          y: 300,
        });
      }
      expect(instantiate3.res.status).toBeGreaterThanOrEqual(200);
      expect(instantiate3.res.status).toBeLessThan(300);
      const instance3Id = instantiate3.body?.id ?? instantiate3.body?.componentId ?? instantiate3.body?.instanceId;
      expect(instance3Id).toBeTruthy();

      // --- Verify instance 1 (detached) still has v1 ---
      let getInstance1 = await request('GET', `/api/projects/${projectId}/pages/${pageId}/components/${instance1Id}`);
      if (getInstance1.res.status >= 400) {
        getInstance1 = await request('GET', `/api/projects/${projectId}/instances/${instance1Id}`);
      }
      expect(getInstance1.res.status).toBeGreaterThanOrEqual(200);
      expect(getInstance1.res.status).toBeLessThan(300);
      expect(getInstance1.body?.id ?? getInstance1.body?.componentId).toBeTruthy();
      const inst1LibRef = getInstance1.body?.libraryItemId ?? getInstance1.body?.sourceLibraryItemId ?? null;
      expect(inst1LibRef).toBeNull();
      // Assert text - check both direct text and nested components structure
      const inst1Text = getInstance1.body?.text ?? getInstance1.body?.components?.[0]?.text;
      expect(inst1Text).toBeDefined();
      expect(
        inst1Text,
        `old detached instance text should remain v1 after library update, got ${inst1Text}`,
      ).toBe('v1');

      // --- Verify instance 3 (new from updated library) has v2 ---
      let getInstance3 = await request('GET', `/api/projects/${projectId}/pages/${pageId}/components/${instance3Id}`);
      if (getInstance3.res.status >= 400) {
        getInstance3 = await request('GET', `/api/projects/${projectId}/instances/${instance3Id}`);
      }
      expect(getInstance3.res.status).toBeGreaterThanOrEqual(200);
      expect(getInstance3.res.status).toBeLessThan(300);
      const inst3Text = getInstance3.body?.text ?? getInstance3.body?.components?.[0]?.text;
      expect(inst3Text).toBeDefined();
      expect(
        inst3Text,
        `new instance from updated library should have text v2, got ${inst3Text}`,
      ).toBe('v2');

      // --- Verify instance 2 (old linked instance) was NOT retroactively changed ---
      // Instance 2 was updated locally to v2 already but this verifies "update library from instance"
      // does not go back and change already-placed instances other than itself
      let getInstance2 = await request('GET', `/api/projects/${projectId}/pages/${pageId}/components/${instance2Id}`);
      if (getInstance2.res.status >= 400) {
        getInstance2 = await request('GET', `/api/projects/${projectId}/instances/${instance2Id}`);
      }
      expect(getInstance2.res.status).toBeGreaterThanOrEqual(200);
      expect(getInstance2.res.status).toBeLessThan(300);
      const inst2Text = getInstance2.body?.text ?? getInstance2.body?.components?.[0]?.text;
      expect(inst2Text).toBeDefined();
      // Instance 2 was manually set to v2, so it should be v2, but the key point is
      // if someone else had an old instance with v1, it stays v1 (tested via instance 1)
      expect(inst2Text).toBe('v2');

      // --- Delete library item ---
      let deleteLibrary = await request('DELETE', `/api/projects/${projectId}/${libPath}/${libraryItemId}`);
      if (deleteLibrary.res.status >= 400) {
        deleteLibrary = await request('DELETE', `/api/projects/${projectId}/library-items/${libraryItemId}`);
      }
      expect([200, 204]).toContain(deleteLibrary.res.status);

      // --- Verify instance 1 (detached, library deleted) degrades gracefully ---
      let getInst1AfterDel = await request('GET', `/api/projects/${projectId}/pages/${pageId}/components/${instance1Id}`);
      if (getInst1AfterDel.res.status >= 400) {
        getInst1AfterDel = await request('GET', `/api/projects/${projectId}/instances/${instance1Id}`);
      }
      expect(getInst1AfterDel.res.status).toBeGreaterThanOrEqual(200);
      expect(getInst1AfterDel.res.status).toBeLessThan(300);
      expect(getInst1AfterDel.body?.id ?? getInst1AfterDel.body?.componentId).toBeTruthy();

      // --- Verify instance 2 (still linked to now-deleted library item) degrades gracefully ---
      let getInst2AfterDel = await request('GET', `/api/projects/${projectId}/pages/${pageId}/components/${instance2Id}`);
      if (getInst2AfterDel.res.status >= 400) {
        getInst2AfterDel = await request('GET', `/api/projects/${projectId}/instances/${instance2Id}`);
      }
      // Must NOT error - should degrade gracefully
      expect(getInst2AfterDel.res.status).toBeGreaterThanOrEqual(200);
      expect(getInst2AfterDel.res.status).toBeLessThan(300);
      expect(getInst2AfterDel.body?.id ?? getInst2AfterDel.body?.componentId).toBeTruthy();
      // The text should still be present (degraded display, not error)
      const inst2TextAfterDel = getInst2AfterDel.body?.text ?? getInst2AfterDel.body?.components?.[0]?.text;
      expect(inst2TextAfterDel).toBeDefined();

      // --- Verify instance 3 (linked to now-deleted library item) also degrades gracefully ---
      let getInst3AfterDel = await request('GET', `/api/projects/${projectId}/pages/${pageId}/components/${instance3Id}`);
      if (getInst3AfterDel.res.status >= 400) {
        getInst3AfterDel = await request('GET', `/api/projects/${projectId}/instances/${instance3Id}`);
      }
      expect(getInst3AfterDel.res.status).toBeGreaterThanOrEqual(200);
      expect(getInst3AfterDel.res.status).toBeLessThan(300);
      expect(getInst3AfterDel.body?.id ?? getInst3AfterDel.body?.componentId).toBeTruthy();
      const inst3TextAfterDel = getInst3AfterDel.body?.text ?? getInst3AfterDel.body?.components?.[0]?.text;
      expect(inst3TextAfterDel).toBeDefined();
    } finally {
      await cleanupProject(projectId);
    }
  });
});

import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function request(path, options = {}) {
  const res = await fetch(`${BASE_URL}${path}`, {
    headers: { 'Content-Type': 'application/json', ...(options.headers || {}) },
    ...options,
  });
  let body = null;
  const text = await res.text();
  try { body = text ? JSON.parse(text) : null; } catch { body = text; }
  return { res, body };
}

async function createProject() {
  const { res, body } = await request('/api/projects', { method: 'POST', body: JSON.stringify({ name: `search-${Date.now()}` }) });
  expect(res.status).toBe(201);
  return body;
}
async function createPage(projectId, name) {
  const { res, body } = await request(`/api/projects/${projectId}/pages`, { method: 'POST', body: JSON.stringify({ name }) });
  expect(res.status).toBe(201);
  return body;
}
async function createComponent(projectId, pageId, payload) {
  const { res, body } = await request(`/api/projects/${projectId}/pages/${pageId}/components`, { method: 'POST', body: JSON.stringify(payload) });
  expect(res.status).toBe(201);
  return body;
}
async function tryDeleteProject(projectId) { try { await request(`/api/projects/${projectId}`, { method: 'DELETE' }); } catch {} }

describe('project_search_filters_results_and_ignores_deleted_targets', () => {
  it('should filter search results and stop returning deleted targets', async () => {
    const project = await createProject();
    try {
      const page = await createPage(project.id, 'SearchTargetPage');
      const cmp = await createComponent(project.id, page.id, { name: 'SearchTargetComponent', type: 'text', x: 1, y: 2, width: 80, height: 20, text: 'UniqueSearchTextValue' });

      const emptySearch = await request(`/api/projects/${project.id}/search?q=`);
      expect([200, 204, 400]).toContain(emptySearch.res.status);
      if (emptySearch.res.status === 200) {
        const items = emptySearch.body.items || emptySearch.body.results || [];
        expect(items.length, 'empty query should not show misleading broad results').toBe(0);
      }

      const shortSearch = await request(`/api/projects/${project.id}/search?q=a`);
      expect([200, 204, 400]).toContain(shortSearch.res.status);

      const search = await request(`/api/projects/${project.id}/search?q=UniqueSearchTextValue`);
      expect(search.res.status).toBe(200);
      const results = search.body.items || search.body.results || [];
      expect(results.length, 'search should return at least one precise hit').toBeGreaterThan(0);
      const hit = results.find((r) => [r.pageId, r.componentId, r.id].includes(cmp.id) || (r.text || '').includes('UniqueSearchTextValue'));
      expect(hit, `search results should include created component/text. results=${JSON.stringify(results)}`).toBeTruthy();

      const del = await request(`/api/projects/${project.id}/pages/${page.id}/components/${cmp.id}`, { method: 'DELETE' });
      expect([200, 204]).toContain(del.res.status);

      const searchAfterDelete = await request(`/api/projects/${project.id}/search?q=UniqueSearchTextValue`);
      expect(searchAfterDelete.res.status).toBe(200);
      const resultsAfterDelete = searchAfterDelete.body.items || searchAfterDelete.body.results || [];
      const stale = resultsAfterDelete.find((r) => [r.pageId, r.componentId, r.id].includes(cmp.id) || (r.text || '').includes('UniqueSearchTextValue'));
      expect(stale, `deleted target should not continue to appear in search results. results=${JSON.stringify(resultsAfterDelete)}`).toBeFalsy();
    } finally {
      await tryDeleteProject(project.id);
    }
  });
});

import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function request(method: string, path: string, body?: any) {
  const res = await fetch(`${BASE_URL}${path}`, {
    method,
    headers: { 'Content-Type': 'application/json' },
    body: body === undefined ? undefined : JSON.stringify(body),
  });
  const text = await res.text();
  let data = null;
  try { data = text ? JSON.parse(text) : null; } catch { data = text; }
  return { res, data };
}

async function cleanupProject(projectId: string | number | undefined) {
  if (!projectId) return;
  try { await request('DELETE', `/api/projects/${projectId}`); } catch {}
}

/**
 * Try multiple API paths for canvas settings since contract is not defined.
 * Returns the result of the first successful (non-404) attempt.
 */
async function setCanvas(projectId: string | number, pageId: string | number, payload: any) {
  let result = await request('PATCH', `/api/projects/${projectId}/pages/${pageId}/canvas`, payload);
  if (result.res.status === 404) {
    result = await request('PATCH', `/api/projects/${projectId}/pages/${pageId}`, { canvas: payload });
  }
  if (result.res.status === 404) {
    result = await request('PUT', `/api/projects/${projectId}/pages/${pageId}/canvas`, payload);
  }
  return result;
}

function extractCanvas(pageData: any) {
  return pageData?.canvas ?? pageData?.canvasSettings ?? pageData;
}

describe('page_canvas_settings_are_isolated_and_validated', () => {
  it('should keep canvas settings isolated per page, reject invalid sizes, support presets, and swap dimensions on orientation change', async () => {
    const suffix = `${Date.now()}_${Math.random().toString(36).slice(2, 8)}`;
    let projectId: string | number | undefined;

    try {
      // Create project
      const proj = await request('POST', '/api/projects', { name: `proj_canvas_${suffix}` });
      expect(proj.res.status).toBeGreaterThanOrEqual(200);
      expect(proj.res.status).toBeLessThan(300);
      projectId = proj.data?.id ?? proj.data?.projectId;
      expect(projectId).toBeTruthy();

      // Create two pages
      const p1 = await request('POST', `/api/projects/${projectId}/pages`, { name: `Canvas1_${suffix}` });
      const p2 = await request('POST', `/api/projects/${projectId}/pages`, { name: `Canvas2_${suffix}` });
      expect(p1.res.status).toBeGreaterThanOrEqual(200);
      expect(p1.res.status).toBeLessThan(300);
      expect(p2.res.status).toBeGreaterThanOrEqual(200);
      expect(p2.res.status).toBeLessThan(300);
      const page1Id = p1.data?.id ?? p1.data?.pageId;
      const page2Id = p2.data?.id ?? p2.data?.pageId;
      expect(page1Id).toBeTruthy();
      expect(page2Id).toBeTruthy();

      // ====== Verify empty page (no components) returns canvas size info ======
      const emptyRead = await request('GET', `/api/projects/${projectId}/pages/${page1Id}`);
      expect(emptyRead.res.status).toBe(200);
      const emptyCanvas = extractCanvas(emptyRead.data);
      // Canvas info should be available even with no components
      const emptyWidth = emptyCanvas?.width ?? emptyCanvas?.canvasWidth;
      const emptyHeight = emptyCanvas?.height ?? emptyCanvas?.canvasHeight;
      expect(emptyWidth, 'empty page should have canvas width info').toBeDefined();
      expect(emptyHeight, 'empty page should have canvas height info').toBeDefined();

      // ====== Set canvas for page 1 (landscape) ======
      const setPage1 = await setCanvas(projectId!, page1Id, {
        width: 800, height: 600, orientation: 'landscape',
      });
      expect(setPage1.res.status).toBeGreaterThanOrEqual(200);
      expect(setPage1.res.status).toBeLessThan(300);

      // ====== Set canvas for page 2 (portrait) ======
      const setPage2 = await setCanvas(projectId!, page2Id, {
        width: 375, height: 812, orientation: 'portrait',
      });
      expect(setPage2.res.status).toBeGreaterThanOrEqual(200);
      expect(setPage2.res.status).toBeLessThan(300);

      // ====== Test invalid canvas values (both width and height) ======
      const invalidPayloads = [
        { width: 0, height: 600, orientation: 'landscape', reason: 'zero width' },
        { width: -1, height: 600, orientation: 'landscape', reason: 'negative width' },
        { width: 100.5, height: 600, orientation: 'landscape', reason: 'non-integer width' },
        { width: 100000, height: 100000, orientation: 'portrait', reason: 'excessively large' },
        { width: 'abc' as any, height: 600, orientation: 'landscape', reason: 'non-number string width' },
        { width: null as any, height: 600, orientation: 'landscape', reason: 'null width' },
        { width: 1, height: 1, orientation: 'landscape', reason: 'too small positive integer (1x1)' },
        { width: 5, height: 5, orientation: 'portrait', reason: 'too small positive integer (5x5)' },
        { width: 600, height: 0, orientation: 'landscape', reason: 'zero height' },
        { width: 600, height: -10, orientation: 'landscape', reason: 'negative height' },
        { width: 600, height: 99.9, orientation: 'landscape', reason: 'non-integer height' },
        { width: 600, height: null as any, orientation: 'landscape', reason: 'null height' },
      ];

      for (const invalid of invalidPayloads) {
        const bad = await setCanvas(projectId!, page1Id, invalid);
        expect(
          [400, 422].includes(bad.res.status),
          `Expected invalid canvas payload (${invalid.reason}) to be rejected, got status ${bad.res.status}`,
        ).toBe(true);
      }

      // ====== Read back and verify isolation ======
      const read1 = await request('GET', `/api/projects/${projectId}/pages/${page1Id}`);
      const read2 = await request('GET', `/api/projects/${projectId}/pages/${page2Id}`);
      expect(read1.res.status).toBe(200);
      expect(read2.res.status).toBe(200);

      const canvas1 = extractCanvas(read1.data);
      const canvas2 = extractCanvas(read2.data);

      // Page 1 should still be 800x600 landscape (invalid payloads should not have changed it)
      const c1w = canvas1?.width ?? canvas1?.canvasWidth;
      const c1h = canvas1?.height ?? canvas1?.canvasHeight;
      expect(c1w, 'page 1 width should be 800').toBe(800);
      expect(c1h, 'page 1 height should be 600').toBe(600);
      const c1Orient = canvas1?.orientation ?? canvas1?.canvasOrientation;
      expect(c1Orient, 'page 1 orientation should be landscape').toBe('landscape');

      // Page 2 should be 375x812 portrait
      const c2w = canvas2?.width ?? canvas2?.canvasWidth;
      const c2h = canvas2?.height ?? canvas2?.canvasHeight;
      expect(c2w, 'page 2 width should be 375').toBe(375);
      expect(c2h, 'page 2 height should be 812').toBe(812);
      const c2Orient = canvas2?.orientation ?? canvas2?.canvasOrientation;
      expect(c2Orient, 'page 2 orientation should be portrait').toBe('portrait');

      // ====== Test orientation switch swaps width/height ======
      // Switch page 1 from landscape (800x600) to portrait -> should become 600x800
      const switchOrientation = await setCanvas(projectId!, page1Id, {
        orientation: 'portrait',
      });
      // If switching only orientation doesn't work, try with explicit swapped dimensions
      if (switchOrientation.res.status >= 400) {
        const switchWithDims = await setCanvas(projectId!, page1Id, {
          width: 600, height: 800, orientation: 'portrait',
        });
        expect(switchWithDims.res.status).toBeGreaterThanOrEqual(200);
        expect(switchWithDims.res.status).toBeLessThan(300);
      } else {
        expect(switchOrientation.res.status).toBeGreaterThanOrEqual(200);
        expect(switchOrientation.res.status).toBeLessThan(300);
      }

      const readAfterSwitch = await request('GET', `/api/projects/${projectId}/pages/${page1Id}`);
      expect(readAfterSwitch.res.status).toBe(200);
      const canvasAfter = extractCanvas(readAfterSwitch.data);
      const afterW = canvasAfter?.width ?? canvasAfter?.canvasWidth;
      const afterH = canvasAfter?.height ?? canvasAfter?.canvasHeight;
      // After switching to portrait, the shorter dimension should be width
      expect(afterW, 'after switching to portrait, width should be 600').toBe(600);
      expect(afterH, 'after switching to portrait, height should be 800').toBe(800);

      // ====== Test preset sizes ======
      let presetResp = await request('GET', `/api/projects/${projectId}/canvas-presets`);
      if (presetResp.res.status === 404) {
        presetResp = await request('GET', `/api/canvas-presets`);
      }
      if (presetResp.res.status >= 200 && presetResp.res.status < 300) {
        const presets = Array.isArray(presetResp.data) ? presetResp.data : (presetResp.data?.presets ?? []);
        expect(presets.length, 'should have at least a few common presets').toBeGreaterThan(0);
        const firstPreset = presets[0];
        expect(firstPreset?.width, 'preset should have width').toBeDefined();
        expect(firstPreset?.height, 'preset should have height').toBeDefined();

        // Apply a preset to page 2 and verify
        const applyPreset = await setCanvas(projectId!, page2Id, {
          width: firstPreset.width,
          height: firstPreset.height,
          orientation: firstPreset.orientation ?? 'portrait',
          preset: firstPreset.name ?? firstPreset.id,
        });
        expect(applyPreset.res.status).toBeGreaterThanOrEqual(200);
        expect(applyPreset.res.status).toBeLessThan(300);

        const readPreset = await request('GET', `/api/projects/${projectId}/pages/${page2Id}`);
        expect(readPreset.res.status).toBe(200);
        const presetCanvas = extractCanvas(readPreset.data);
        expect(presetCanvas?.width ?? presetCanvas?.canvasWidth, 'preset width should be applied').toBe(firstPreset.width);
        expect(presetCanvas?.height ?? presetCanvas?.canvasHeight, 'preset height should be applied').toBe(firstPreset.height);
      }

    } finally {
      await cleanupProject(projectId);
    }
  });
});

import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function request(method: string, path: string, body?: any) {
  const res = await fetch(`${BASE_URL}${path}`, {
    method,
    headers: { 'Content-Type': 'application/json' },
    body: body === undefined ? undefined : JSON.stringify(body),
  });
  const text = await res.text();
  let data: any = null;
  try { data = text ? JSON.parse(text) : null; } catch { data = text; }
  return { res, data };
}

async function tryEndpoints(method: string, paths: string[], body?: any) {
  for (const path of paths) {
    const resp = await request(method, path, body);
    if (resp.res.status !== 404) return { ...resp, usedPath: path };
  }
  const resp = await request(method, paths[paths.length - 1], body);
  return { ...resp, usedPath: paths[paths.length - 1] };
}

async function tryDelete(path: string) {
  try { await request('DELETE', path); } catch {}
}

