describe('project_import_export_validates_and_restores_data', () => {
  it('should export/import valid data, default export name, reject invalid data without mutating current project', async () => {
    const suffix = `${Date.now()}_${Math.random().toString(36).slice(2, 8)}`;
    const project = await createProject(`import-export-${suffix}`);
    try {
      const page = await createPage(project.id, `Export Page ${suffix}`);
      await createComponent(project.id, page.id, { name: 'Title', type: 'text', x: 10, y: 20, width: 200, height: 40, text: 'Hello export' });
      await createComponent(project.id, page.id, { name: 'Btn1', type: 'button', x: 10, y: 80, width: 100, height: 30, text: 'Click me' });

      // ====== Export ======
      let exported = await request(`/api/projects/${project.id}/export`);
      if (exported.res.status >= 400) {
        exported = await request(`/api/projects/${project.id}/export`, { method: 'POST', body: JSON.stringify({}) });
      }
      expect(exported.res.status).toBeGreaterThanOrEqual(200);
      expect(exported.res.status).toBeLessThan(300);
      expect(exported.body, 'export response should contain data').toBeTruthy();

      const exportData = exported.body?.data ?? exported.body?.project ?? exported.body?.content ?? exported.body;
      expect(exportData, 'export response should include project data payload').toBeTruthy();

      // ====== Verify default export name is generated ======
      const exportName = exported.body?.name ?? exported.body?.fileName ?? exported.body?.filename;
      // The name should be present and non-empty when user doesn't provide one
      expect(
        exportName,
        `when export name is omitted, backend should generate a non-empty default name, got: ${JSON.stringify({ name: exported.body?.name, fileName: exported.body?.fileName, filename: exported.body?.filename })}`,
      ).toBeTruthy();
      expect(typeof exportName === 'string' && exportName.trim().length > 0, 'default export name should be a non-empty string').toBe(true);

      // ====== Check Content-Disposition if present (file download) ======
      const contentDisposition = exported.res.headers.get('content-disposition');
      // If content-disposition is set, verify it has a filename
      if (contentDisposition) {
        expect(contentDisposition.toLowerCase()).toContain('filename');
      }

      // ====== Snapshot project state before invalid import ======
      const snapshotBeforeInvalid = await getProject(project.id);
      const pagesBefore = snapshotBeforeInvalid?.pages ?? [];
      const pageCountBefore = pagesBefore.length;
      const compCountBefore = pagesBefore.flatMap((p: any) => p.components ?? []).length;

      // ====== Reject invalid/unsupported import data ======
      const invalidImport = await request(`/api/projects/${project.id}/import`, {
        method: 'POST',
        body: JSON.stringify({ data: { version: 999999, broken: true } }),
      });
      expect(
        [400, 409, 422].includes(invalidImport.res.status),
        `invalid or unsupported import should be rejected, got ${invalidImport.res.status}`,
      ).toBe(true);
      // Verify error message is present
      const invalidErrorMsg = invalidImport.body?.message ?? invalidImport.body?.error ?? invalidImport.body?.reason;
      expect(invalidErrorMsg, 'rejected import should include an error message/reason').toBeTruthy();

      // Verify project is unchanged after failed import (pages AND components)
      const snapshotAfterInvalid = await getProject(project.id);
      expect(snapshotAfterInvalid, 'project should remain readable after failed import').toBeTruthy();
      const pagesAfterInvalid = snapshotAfterInvalid?.pages ?? [];
      expect(pagesAfterInvalid.length, 'failed import must not destroy existing pages').toBe(pageCountBefore);
      const compCountAfterInvalid = pagesAfterInvalid.flatMap((p: any) => p.components ?? []).length;
      expect(compCountAfterInvalid, 'failed import must not destroy existing components').toBe(compCountBefore);

      // ====== Reject non-tool file (plain text / garbage) ======
      const garbageImport = await request(`/api/projects/${project.id}/import`, {
        method: 'POST',
        body: JSON.stringify({ data: 'this is not a valid project file' }),
      });
      expect(
        [400, 409, 422].includes(garbageImport.res.status),
        `non-tool file should be rejected, got ${garbageImport.res.status}`,
      ).toBe(true);
      const garbageErrorMsg = garbageImport.body?.message ?? garbageImport.body?.error ?? garbageImport.body?.reason;
      expect(garbageErrorMsg, 'non-tool file rejection should include an error message').toBeTruthy();

      // Verify project still intact after garbage import
      const snapshotAfterGarbage = await getProject(project.id);
      const pagesAfterGarbage = snapshotAfterGarbage?.pages ?? [];
      expect(pagesAfterGarbage.length, 'garbage import must not destroy existing pages').toBe(pageCountBefore);

      // ====== Import old/legacy format with missing fields ======
      const legacySnapshot = {
        pages: [
          {
            name: `Legacy Page ${suffix}`,
            components: [
              { name: 'OldButton', type: 'button', x: 5, y: 5, width: 80, height: 30 }
              // Missing: visible, locked, text, libraryItemId etc.
            ]
          }
        ]
        // Missing: libraryItems, version, grid settings etc.
      };
      const legacyImport = await request(`/api/projects/${project.id}/import`, {
        method: 'POST',
        body: JSON.stringify({ data: legacySnapshot, mode: 'replace' }),
      });
      expect(legacyImport.res.status).toBeGreaterThanOrEqual(200);
      expect(legacyImport.res.status).toBeLessThan(300);

      const restoredLegacy = await getProject(project.id);
      const restoredPages = restoredLegacy?.pages ?? [];
      expect(restoredPages.length, 'legacy import should create at least one page').toBeGreaterThan(0);

      // Check that missing fields got defaults
      const restoredComps = restoredPages.flatMap((p: any) => p.components ?? []);
      expect(restoredComps.length, 'legacy import should restore at least one component').toBeGreaterThan(0);
      const comp = restoredComps[0];
      // Visible should default to true
      const compVisible = comp.visible ?? comp.isVisible;
      expect(compVisible, 'missing visible field should default to true').toBe(true);
      // Locked should default to false
      const compLocked = comp.locked ?? comp.isLocked;
      expect(compLocked, 'missing locked field should default to false').toBe(false);

      // ====== Valid re-import with original exported data ======
      const importBack = await request(`/api/projects/${project.id}/import`, {
        method: 'POST',
        body: JSON.stringify({ data: exportData, mode: 'replace' }),
      });
      expect(importBack.res.status).toBeGreaterThanOrEqual(200);
      expect(importBack.res.status).toBeLessThan(300);

      const restored = await getProject(project.id);
      const finalPages = restored?.pages ?? [];
      expect(finalPages.length, 'restored project should contain at least one page').toBeGreaterThan(0);
      const restoredTexts = finalPages.flatMap((p: any) => (p.components ?? []).map((c: any) => c.text)).filter(Boolean);
      expect(restoredTexts, 'restored project should include previously exported text content').toContain('Hello export');
      expect(restoredTexts, 'restored project should include button text').toContain('Click me');
    } finally {
      await tryDeleteProject(project.id);
    }
  });
});

