describe('composite_instance_preserves_structure_and_cascades_delete', () => {
  it('should preserve internal structure/state for composite library instances and cascade delete children', async () => {
    const suffix = `${Date.now()}_${Math.random().toString(36).slice(2, 8)}`;
    let projectId: string | number | undefined;

    try {
      // Create project
      const proj = await request('POST', '/api/projects', { name: `composite_${suffix}` });
