      expect(projectId).toBeTruthy();

      // Create page
      const page = await request('POST', `/api/projects/${projectId}/pages`, { name: `CompositePage_${suffix}` });
      expect(page.res.status).toBeGreaterThanOrEqual(200);
      expect(page.res.status).toBeLessThan(300);
      const pageId = page.data?.id ?? page.data?.pageId;
      expect(pageId).toBeTruthy();

      // Create two source components with different visible/locked states
      const a = await request('POST', `/api/projects/${projectId}/pages/${pageId}/components`, {
        name: `CompA_${suffix}`, type: 'button', x: 10, y: 20, width: 50, height: 50, visible: true, locked: false,
      });
      expect(a.res.status).toBeGreaterThanOrEqual(200);
      expect(a.res.status).toBeLessThan(300);
      const aId = a.data?.id ?? a.data?.componentId;
      expect(aId).toBeTruthy();

      const b = await request('POST', `/api/projects/${projectId}/pages/${pageId}/components`, {
        name: `CompB_${suffix}`, type: 'text', x: 80, y: 20, width: 50, height: 50, visible: false, locked: true,
      });
      expect(b.res.status).toBeGreaterThanOrEqual(200);
      expect(b.res.status).toBeLessThan(300);
      const bId = b.data?.id ?? b.data?.componentId;
      expect(bId).toBeTruthy();

      // Record relative positions: A at (10,20), B at (80,20) => B offset from A is (70, 0)
      const relativeOffsetX = 80 - 10; // 70
      const relativeOffsetY = 20 - 20; // 0

      // Save as composite library item
      const composite = await request('POST', `/api/projects/${projectId}/library-items`, {
        name: `Composite_${suffix}`,
        sourceComponentIds: [aId, bId],
        composite: true,
      });
      expect(composite.res.status).toBeGreaterThanOrEqual(200);
      expect(composite.res.status).toBeLessThan(300);
      const libraryItemId = composite.data?.id ?? composite.data?.libraryItemId;
      expect(libraryItemId).toBeTruthy();

      // Place composite instance onto the page at a new position
      const placeX = 200;
      const placeY = 200;
      const place = await request('POST', `/api/projects/${projectId}/pages/${pageId}/components`, {
        libraryItemId, x: placeX, y: placeY, type: 'library-instance',
      });
      expect(place.res.status).toBeGreaterThanOrEqual(200);
      expect(place.res.status).toBeLessThan(300);
      const compositeInstanceId = place.data?.id ?? place.data?.componentId ?? place.data?.groupId;
      expect(compositeInstanceId).toBeTruthy();

      // Get page state to inspect placed components
      const state = await request('GET', `/api/projects/${projectId}/pages/${pageId}`);
      expect(state.res.status).toBeGreaterThanOrEqual(200);
      expect(state.res.status).toBeLessThan(300);
      const components = state.data?.components ?? [];

      // Find children of the composite instance
      // Support both flat structure (parentId/groupId) and nested structure (children/components property)
      const compositeEntity = components.find((c: any) => (c.id ?? c.componentId) === compositeInstanceId);
      const innerChildren = compositeEntity?.children ?? compositeEntity?.components ?? [];
      const flatChildren = components.filter((c: any) =>
        c.parentId === compositeInstanceId || c.groupId === compositeInstanceId
      );
      const allChildren = innerChildren.length > 0 ? innerChildren : flatChildren;

      expect(
        allChildren.length,
        `Expected composite instance to contain at least 2 internal elements, got ${allChildren.length}. Full components: ${JSON.stringify(components.slice(0, 10))}`,
      ).toBeGreaterThanOrEqual(2);

      // Find child A and child B by name pattern
      const childA = allChildren.find((c: any) => c.name?.includes('CompA') || c.type === 'button');
      const childB = allChildren.find((c: any) => c.name?.includes('CompB') || (c.type === 'text' && c !== childA));

      expect(childA, 'child A should exist in composite instance').toBeTruthy();
      expect(childB, 'child B should exist in composite instance').toBeTruthy();

      // Check visible/locked values - must not be skipped
      const aVisible = childA.visible ?? childA.isVisible;
      const aLocked = childA.locked ?? childA.isLocked;
      const bVisible = childB.visible ?? childB.isVisible;
      const bLocked = childB.locked ?? childB.isLocked;

      expect(aVisible, 'child A should be visible').toBe(true);
      expect(aLocked, 'child A should not be locked').toBe(false);
      expect(bVisible, 'child B should be hidden').toBe(false);
      expect(bLocked, 'child B should be locked').toBe(true);

      // Verify relative positions are preserved - MUST not be skipped
      const childAx = childA.x ?? childA.posX;
      const childAy = childA.y ?? childA.posY;
      const childBx = childB.x ?? childB.posX;
      const childBy = childB.y ?? childB.posY;
      expect(childAx, 'child A should have an x position').toBeDefined();
      expect(childBx, 'child B should have an x position').toBeDefined();
      expect(childAy, 'child A should have a y position').toBeDefined();
      expect(childBy, 'child B should have a y position').toBeDefined();

      const actualRelX = childBx - childAx;
      const actualRelY = childBy - childAy;
      expect(
        actualRelX,
        `relative X offset between A and B should be preserved (expected ${relativeOffsetX}, got ${actualRelX})`,
      ).toBe(relativeOffsetX);
      expect(
        actualRelY,
        `relative Y offset between A and B should be preserved (expected ${relativeOffsetY}, got ${actualRelY})`,
      ).toBe(relativeOffsetY);

      // Verify layer order is preserved: B was added after A, so B should be on top or appear later
      const childAIndex = allChildren.findIndex((c: any) => c === childA);
      const childBIndex = allChildren.findIndex((c: any) => c === childB);
      if (childA.zIndex !== undefined && childB.zIndex !== undefined) {
        expect(childB.zIndex, 'B should have same or higher zIndex than A').toBeGreaterThanOrEqual(childA.zIndex);
      } else {
        // Fall back to list order as proxy for layer order
        expect(childBIndex, 'B should appear at same or later position than A in children list (layer order)').toBeGreaterThanOrEqual(childAIndex);
      }

      // Verify original source components (aId, bId) still exist independently
      const sourceA = components.find((c: any) => (c.id ?? c.componentId) === aId);
      const sourceB = components.find((c: any) => (c.id ?? c.componentId) === bId);
      expect(sourceA, 'original source component A should still exist independently on the page').toBeTruthy();
      expect(sourceB, 'original source component B should still exist independently on the page').toBeTruthy();

      // Record total component count before cascade delete
      const countBefore = components.length;

      // Delete the composite instance
      const deleteComposite = await request('DELETE', `/api/projects/${projectId}/pages/${pageId}/components/${compositeInstanceId}`);
      expect(deleteComposite.res.status).toBeGreaterThanOrEqual(200);
      expect(deleteComposite.res.status).toBeLessThan(300);

      // Verify cascade delete: composite and its children should all be gone
      const afterDelete = await request('GET', `/api/projects/${projectId}/pages/${pageId}`);
      expect(afterDelete.res.status).toBeGreaterThanOrEqual(200);
      expect(afterDelete.res.status).toBeLessThan(300);
      const remaining = afterDelete.data?.components ?? [];

      // Composite root should be deleted
      expect(
        remaining.some((c: any) => (c.id ?? c.componentId) === compositeInstanceId),
        'composite root should be deleted',
      ).toBe(false);

      // Children should also be cascade-deleted
      expect(
        remaining.some((c: any) => c.parentId === compositeInstanceId || c.groupId === compositeInstanceId),
        'composite children should be cascade-deleted',
      ).toBe(false);

      // Also check no nested children remain
      for (const comp of remaining) {
        const nested = comp.children ?? comp.components ?? [];
        // If a remaining component has children, none should reference the deleted composite
        for (const child of nested) {
          expect(
            (child.parentId ?? child.groupId) !== compositeInstanceId,
            'no nested child should reference deleted composite',
          ).toBe(true);
        }
      }

      // Verify original source components still exist (they are independent, not part of the composite instance)
      const sourceAAfter = remaining.find((c: any) => (c.id ?? c.componentId) === aId);
      const sourceBAfter = remaining.find((c: any) => (c.id ?? c.componentId) === bId);
      expect(sourceAAfter, 'original source component A should NOT be cascade-deleted (it is independent)').toBeTruthy();
      expect(sourceBAfter, 'original source component B should NOT be cascade-deleted (it is independent)').toBeTruthy();

    } finally {
      await tryDeleteProject(projectId);
    }
  });
});

import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function request(path, options = {}) {
  const res = await fetch(`${BASE_URL}${path}`, {
    headers: { 'Content-Type': 'application/json', ...(options.headers || {}) },
    ...options,
  });
  let body = null;
  const text = await res.text();
  try { body = text ? JSON.parse(text) : null; } catch { body = text; }
  return { res, body };
}

async function createProject(name) {
  const projectName = name || `roundtrip-${Date.now()}`;
  const { res, body } = await request('/api/projects', { method: 'POST', body: JSON.stringify({ name: projectName }) });
  expect(res.status).toBe(201);
  return body;
}
async function createPage(projectId, name) {
  const { res, body } = await request(`/api/projects/${projectId}/pages`, { method: 'POST', body: JSON.stringify({ name }) });
  expect(res.status).toBe(201);
  return body;
}
async function createComponent(projectId, pageId, payload) {
  const { res, body } = await request(`/api/projects/${projectId}/pages/${pageId}/components`, { method: 'POST', body: JSON.stringify(payload) });
  expect(res.status).toBe(201);
  return body;
}
async function getProject(projectId) {
  const { res, body } = await request(`/api/projects/${projectId}`);
  expect(res.status).toBe(200);
  return body;
}
async function getPage(projectId, pageId) {
  const { res, body } = await request(`/api/projects/${projectId}/pages/${pageId}`);
  expect(res.status).toBe(200);
  return body;
}
async function tryDeleteProject(projectId) { try { await request(`/api/projects/${projectId}`, { method: 'DELETE' }); } catch {} }

describe('end_to_end_project_roundtrip_preserves_instance_and_library_relations', () => {
  it('should preserve library and instance relations across export/import while keeping modified text isolated', async () => {
    const project = await createProject();
    try {
      // Step 1: Create a page and put a component on it
      const page1 = await createPage(project.id, 'Base Page');
      const source = await createComponent(project.id, page1.id, {
        name: 'Button', type: 'text', x: 10, y: 10, width: 120, height: 40, text: 'Original CTA',
      });

      // Step 2: Save as library item
      const createLibrary = await request(`/api/projects/${project.id}/library-items`, {
        method: 'POST',
        body: JSON.stringify({ name: 'ButtonLib', sourceComponentId: source.id, pageId: page1.id }),
      });
      expect([200, 201]).toContain(createLibrary.res.status);
      const lib = createLibrary.body;
      expect(lib.id, 'created library item id should exist').toBeTruthy();

      // Step 3: Duplicate page (components come along)
      const clonePage = await request(`/api/projects/${project.id}/pages/${page1.id}/duplicate`, { method: 'POST' });
      expect([200, 201]).toContain(clonePage.res.status);
      const page2 = clonePage.body;
      expect(page2.id).toBeTruthy();

      // Step 4: Find the component that was copied along with the page
      const page2State = await getPage(project.id, page2.id);
      const copiedComponents = page2State.components || [];
      expect(copiedComponents.length, 'Duplicated page should contain copied components').toBeGreaterThanOrEqual(1);
      const copiedInstance = copiedComponents[0];
      expect(copiedInstance.id).toBeTruthy();
      expect(copiedInstance.text, 'Copied component should inherit original text').toBe('Original CTA');

      // Step 5: Modify the copied instance's text
      const modifyInstance = await request(`/api/projects/${project.id}/pages/${page2.id}/components/${copiedInstance.id}`, {
        method: 'PATCH',
        body: JSON.stringify({ text: 'Changed CTA only here' }),
      });
      expect([200, 204]).toContain(modifyInstance.res.status);

      // Step 6: Export
      const exported = await request(`/api/projects/${project.id}/export`, { method: 'POST', body: JSON.stringify({}) });
      expect([200, 201]).toContain(exported.res.status);
      const data = exported.body.data || exported.body.project || exported.body.content || exported.body;
      expect(data).toBeTruthy();

      // Step 7: Create new project and import (simulates refresh + import)
      const importedProject = await createProject(`roundtrip-imported-${Date.now()}`);
      try {
        const importRes = await request(`/api/projects/${importedProject.id}/import`, {
          method: 'POST',
          body: JSON.stringify({ data, mode: 'replace' }),
        });
        expect([200, 201]).toContain(importRes.res.status);

        // Step 8: Search for the modified text
        const search = await request(`/api/projects/${importedProject.id}/search?q=${encodeURIComponent('Changed CTA only here')}`);
        expect(search.res.status).toBe(200);
        const results = search.body.items || search.body.results || [];
        expect(results.length, 'imported project should allow finding modified instance text').toBeGreaterThan(0);
        // Verify search result contains the expected text
        const matchingResult = results.find((r) =>
          (r.text || r.matchedText || r.content || '').includes('Changed CTA only here')
        );
        expect(matchingResult, 'search result should contain the modified text').toBeTruthy();

        // Step 9: Verify project state
        const importedState = await getProject(importedProject.id);
        const pages = importedState.pages || [];
        expect(pages.length, 'imported project should contain both base and duplicated pages').toBeGreaterThanOrEqual(2);

        const allComponents = pages.flatMap((p) => p.components || []);
        const modifiedMatches = allComponents.filter((c) => c.text === 'Changed CTA only here');
        const originalMatches = allComponents.filter((c) => c.text === 'Original CTA');
        expect(modifiedMatches.length, 'only modified instance should contain changed text').toBeGreaterThanOrEqual(1);
        expect(originalMatches.length, 'original page instance should retain original text').toBeGreaterThanOrEqual(1);

        // Step 10: Verify library item template was not modified
        const importedLibs = importedState.libraryItems || importedState.library || [];
        expect(importedLibs.length, 'library items should survive roundtrip').toBeGreaterThanOrEqual(1);
        const importedLib = importedLibs.find((l) => l.name === 'ButtonLib');
        if (importedLib) {
          // If the library item exposes template text, verify it
          if (importedLib.text !== undefined || importedLib.template?.text !== undefined) {
            const libText = importedLib.text ?? importedLib.template?.text;
            expect(libText, 'Library item template should retain original text, not the modified instance text').toBe('Original CTA');
          }
        }

        // Step 11: Verify instance-library relation survived
        const instanceWithRelation = allComponents.find((c) => c.libraryItemId || c.sourceLibraryItemId);
        expect(instanceWithRelation, 'instance-library relation should survive roundtrip').toBeTruthy();
      } finally {
        await tryDeleteProject(importedProject.id);
      }
    } finally {
      await tryDeleteProject(project.id);
    }
  });
});

