describe('round18_behavior_unchanged_baseline', () => {
  it('should keep page-scoped undo/redo, preserve instances after library deletion, and not change real size/position on zoom', async () => {
    const suffix = `${Date.now()}_${Math.random().toString(36).slice(2, 8)}`;
    let projectId: string | number | undefined;

    try {
      // Create project
      const p = await request('POST', '/api/projects', { name: `proj_round18_${suffix}` });
