      const page2 = await request('POST', `/api/projects/${projectId}/pages`, { name: `Page2_${suffix}` });
      expect(page1.res.status).toBeGreaterThanOrEqual(200);
      expect(page1.res.status).toBeLessThan(300);
      expect(page2.res.status).toBeGreaterThanOrEqual(200);
      expect(page2.res.status).toBeLessThan(300);
      const page1Id = page1.body?.id;
      const page2Id = page2.body?.id;
