        type: 'rect', name: `Rect_${suffix}`, x: 10, y: 20, width: 100, height: 60,
      });
      const c2 = await request('POST', `/api/projects/${projectId}/pages/${page2Id}/components`, {
        type: 'text', name: `Text_${suffix}`, text: 'hello', x: 30, y: 40, width: 80, height: 20,
      });
      expect(c1.res.status).toBeGreaterThanOrEqual(200);
      expect(c1.res.status).toBeLessThan(300);
      expect(c2.res.status).toBeGreaterThanOrEqual(200);
      expect(c2.res.status).toBeLessThan(300);
      const c1Id = c1.body?.id;
      const c2Id = c2.body?.id;
      expect(c1Id).toBeTruthy();
      expect(c2Id).toBeTruthy();

      // Delete component on page1
      const delOnPage1 = await request('DELETE', `/api/projects/${projectId}/pages/${page1Id}/components/${c1Id}`);
      expect([200, 204]).toContain(delOnPage1.res.status);

      // Undo on page1 — try both possible endpoint styles
      let undoPage1 = await request('POST', `/api/projects/${projectId}/pages/${page1Id}/undo`);
      if (undoPage1.res.status >= 400) {
        undoPage1 = await request('POST', `/api/projects/${projectId}/pages/${page1Id}/history/undo`);
      }
      expect(undoPage1.res.status).toBeGreaterThanOrEqual(200);
      expect(undoPage1.res.status).toBeLessThan(300);

      // Verify page1 undo restored component, page2 unchanged
      const page1State = await request('GET', `/api/projects/${projectId}/pages/${page1Id}`);
      const page2State = await request('GET', `/api/projects/${projectId}/pages/${page2Id}`);
      expect(page1State.res.status).toBeGreaterThanOrEqual(200);
      expect(page1State.res.status).toBeLessThan(300);
      expect(page2State.res.status).toBeGreaterThanOrEqual(200);
      expect(page2State.res.status).toBeLessThan(300);

      const page1Components = page1State.body?.components || [];
      expect(
        Array.isArray(page1Components) && page1Components.some((x: any) => x.id === c1Id),
        `page1 undo should restore deleted component ${c1Id}, got ${JSON.stringify(page1State.body)}`,
      ).toBe(true);

      const page2Components = page2State.body?.components || [];
      expect(
        Array.isArray(page2Components) && page2Components.some((x: any) => x.id === c2Id),
        `page2 should remain unchanged by page1 undo, got ${JSON.stringify(page2State.body)}`,
      ).toBe(true);

      // Create library item from c2
      const lib = await request('POST', `/api/projects/${projectId}/library-items`, {
        name: `Lib_${suffix}`,
        sourceComponentIds: [c2Id],
      });
      expect(lib.res.status).toBeGreaterThanOrEqual(200);
      expect(lib.res.status).toBeLessThan(300);
      const libraryItemId = lib.body?.id;
      expect(libraryItemId).toBeTruthy();

      // Place instance from library item onto page2
      const inst = await request('POST', `/api/projects/${projectId}/pages/${page2Id}/components`, {
        libraryItemId,
        x: 120,
        y: 140,
      });
      expect(inst.res.status).toBeGreaterThanOrEqual(200);
      expect(inst.res.status).toBeLessThan(300);
      const instanceId = inst.body?.id;
      expect(instanceId).toBeTruthy();

      // Delete library item
      const delLib = await request('DELETE', `/api/projects/${projectId}/library-items/${libraryItemId}`);
      expect([200, 204]).toContain(delLib.res.status);

      // Verify instance still exists on page2 by fetching the page
      const page2AfterLibDel = await request('GET', `/api/projects/${projectId}/pages/${page2Id}`);
      expect(page2AfterLibDel.res.status).toBeGreaterThanOrEqual(200);
      expect(page2AfterLibDel.res.status).toBeLessThan(300);
      const page2CompsAfterDel = page2AfterLibDel.body?.components || [];
      const instanceInPage = page2CompsAfterDel.find((c: any) => c.id === instanceId);
      expect(
        instanceInPage,
        `Instance ${instanceId} should still exist on page2 after library item deletion, got components: ${JSON.stringify(page2CompsAfterDel)}`,
      ).toBeTruthy();

      // Also try fetching instance directly at page-scoped path
      const getInst = await request('GET', `/api/projects/${projectId}/pages/${page2Id}/components/${instanceId}`);
      if (getInst.res.status >= 200 && getInst.res.status < 300) {
        expect(getInst.body?.id).toBe(instanceId);
      }

      // Zoom: get component before zoom
      const beforeZoom = await request('GET', `/api/projects/${projectId}/pages/${page2Id}/components/${c2Id}`);
      expect(beforeZoom.res.status).toBeGreaterThanOrEqual(200);
      expect(beforeZoom.res.status).toBeLessThan(300);
      const before = {
        x: beforeZoom.body?.x,
        y: beforeZoom.body?.y,
        width: beforeZoom.body?.width,
        height: beforeZoom.body?.height,
      };

      // Set zoom — try PUT first, then POST as fallback
      let zoom = await request('PUT', `/api/projects/${projectId}/pages/${page2Id}/viewport`, { zoom: 2 });
      if (zoom.res.status >= 400) {
        zoom = await request('POST', `/api/projects/${projectId}/pages/${page2Id}/viewport`, { zoom: 2 });
      }
      expect(zoom.res.status).toBeGreaterThanOrEqual(200);
      expect(zoom.res.status).toBeLessThan(300);

      // Verify component real size/position unchanged after zoom
      const afterZoom = await request('GET', `/api/projects/${projectId}/pages/${page2Id}/components/${c2Id}`);
      expect(afterZoom.res.status).toBeGreaterThanOrEqual(200);
      expect(afterZoom.res.status).toBeLessThan(300);
      expect(afterZoom.body?.x, `x should not change after zoom, before=${before.x}, after=${afterZoom.body?.x}`).toBe(before.x);
      expect(afterZoom.body?.y, `y should not change after zoom, before=${before.y}, after=${afterZoom.body?.y}`).toBe(before.y);
      expect(afterZoom.body?.width, `width should not change after zoom, before=${before.width}, after=${afterZoom.body?.width}`).toBe(before.width);
      expect(afterZoom.body?.height, `height should not change after zoom, before=${before.height}, after=${afterZoom.body?.height}`).toBe(before.height);
    } finally {
      await cleanupProject(projectId);
    }
  });
});

import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function request(method: string, path: string, body?: any) {
  const res = await fetch(`${BASE_URL}${path}`, {
    method,
    headers: { 'Content-Type': 'application/json' },
    body: body === undefined ? undefined : JSON.stringify(body),
  });
  const text = await res.text();
  let data: any = null;
  try { data = text ? JSON.parse(text) : null; } catch { data = text; }
  return { res, data };
}

async function tryEndpoints(method: string, paths: string[], body?: any) {
  for (const path of paths) {
    const resp = await request(method, path, body);
    if (resp.res.status !== 404) return resp;
  }
  return request(method, paths[paths.length - 1], body);
}

describe('library_instance_update_affects_only_future_instances', () => {
  it('should update library definition for future instances only, support detach, and degrade gracefully when source library item is missing', async () => {
    const suffix = `${Date.now()}_${Math.random().toString(36).slice(2, 8)}`;
    // Create project
    const ws = await request('POST', '/api/projects', { name: `verifier-library-update-${suffix}` });
    expect([200, 201]).toContain(ws.res.status);
    const projectId = ws.data?.id || ws.data?.projectId;
    expect(projectId).toBeTruthy();

    try {
      // Create a page
      const page = await request('POST', `/api/projects/${projectId}/pages`, { name: 'Update Host' });
      expect([200, 201]).toContain(page.res.status);
      const pageId = page.data?.id || page.data?.pageId;
      expect(pageId).toBeTruthy();

      // Create source component
      const source = await request('POST', `/api/projects/${projectId}/pages/${pageId}/components`, {
        name: 'Badge', type: 'text', text: 'old', x: 0, y: 0, width: 80, height: 30,
      });
      expect([200, 201]).toContain(source.res.status);
      const sourceId = source.data?.id || source.data?.componentId;
      expect(sourceId).toBeTruthy();

      // Save as library item
      const item = await tryEndpoints('POST', [
        `/api/projects/${projectId}/library-items`,
        `/api/projects/${projectId}/library`,
      ], { name: `BadgeLib_${suffix}`, sourceComponentId: sourceId, sourceComponentIds: [sourceId], pageId });
      expect([200, 201]).toContain(item.res.status);
      const libraryItemId = item.data?.id || item.data?.libraryItemId;
      expect(libraryItemId).toBeTruthy();

      // --- Instance 0: place BEFORE update (untouched, should keep 'old' content) ---
      const inst0 = await request('POST', `/api/projects/${projectId}/pages/${pageId}/components`, {
        type: 'library-instance', libraryItemId, x: 5, y: 5,
      });
      expect([200, 201]).toContain(inst0.res.status);
      const inst0Id = inst0.data?.id || inst0.data?.componentId;
      expect(inst0Id).toBeTruthy();

      // --- Instance 1: place from library, then edit locally ---
      const inst1 = await request('POST', `/api/projects/${projectId}/pages/${pageId}/components`, {
        type: 'library-instance', libraryItemId, x: 10, y: 10,
      });
      expect([200, 201]).toContain(inst1.res.status);
      const inst1Id = inst1.data?.id || inst1.data?.componentId;
      expect(inst1Id).toBeTruthy();

      // Verify all instance IDs are distinct
      expect(inst0Id).not.toBe(inst1Id);
      expect(inst0Id).not.toBe(sourceId);
      expect(inst1Id).not.toBe(sourceId);

      // Edit instance 1 locally
      const localEdit = await request('PATCH', `/api/projects/${projectId}/pages/${pageId}/components/${inst1Id}`, { text: 'custom-old' });
      expect([200, 204]).toContain(localEdit.res.status);

      // Verify editing inst1 did not change inst0
      const stateBeforeUpdate = await request('GET', `/api/projects/${projectId}/pages/${pageId}`);
      expect(stateBeforeUpdate.res.status).toBe(200);
      const compsBeforeUpdate = stateBeforeUpdate.data?.components || [];
      const inst0BeforeUpdate = compsBeforeUpdate.find((c: any) => c.id === inst0Id);
      expect(inst0BeforeUpdate).toBeTruthy();
      expect(inst0BeforeUpdate.text).toBe('old');

      // Update library item from instance 1
      const updateLibrary = await tryEndpoints('POST', [
        `/api/projects/${projectId}/library-items/${libraryItemId}/update-from-instance`,
        `/api/projects/${projectId}/library/${libraryItemId}/update-from-instance`,
      ], { componentId: inst1Id, pageId });
      expect([200, 204]).toContain(updateLibrary.res.status);

      // --- Verify: inst0 (existed before update, never edited) still has 'old' ---
      const stateAfterUpdate = await request('GET', `/api/projects/${projectId}/pages/${pageId}`);
      expect(stateAfterUpdate.res.status).toBe(200);
      const compsAfterUpdate = stateAfterUpdate.data?.components || [];
      const c0 = compsAfterUpdate.find((c: any) => c.id === inst0Id);
      expect(c0).toBeTruthy();
      expect(c0.text, `Expected old untouched instance to keep original content 'old', got '${c0.text}'`).toBe('old');

      // --- Verify: inst1 keeps its locally edited content ---
      const c1 = compsAfterUpdate.find((c: any) => c.id === inst1Id);
      expect(c1).toBeTruthy();
      expect(c1.text, `Expected edited instance to keep its content 'custom-old', got '${c1.text}'`).toBe('custom-old');

      // --- Instance 2: place from library AFTER update ---
      const inst2 = await request('POST', `/api/projects/${projectId}/pages/${pageId}/components`, {
        type: 'library-instance', libraryItemId, x: 20, y: 20,
      });
      expect([200, 201]).toContain(inst2.res.status);
      const inst2Id = inst2.data?.id || inst2.data?.componentId;
      expect(inst2Id).toBeTruthy();
      expect(inst2Id).not.toBe(inst0Id);
      expect(inst2Id).not.toBe(inst1Id);

      // Verify inst2 gets the updated library content
      const stateAfterInst2 = await request('GET', `/api/projects/${projectId}/pages/${pageId}`);
      expect(stateAfterInst2.res.status).toBe(200);
      const c2 = (stateAfterInst2.data?.components || []).find((c: any) => c.id === inst2Id);
      expect(c2).toBeTruthy();
      expect(c2.text, `Expected future instance to use updated library content 'custom-old', got '${c2.text}'`).toBe('custom-old');

      // --- Instance 3: for degradation test ---
      const inst3 = await request('POST', `/api/projects/${projectId}/pages/${pageId}/components`, {
        type: 'library-instance', libraryItemId, x: 30, y: 30,
      });
      expect([200, 201]).toContain(inst3.res.status);
      const inst3Id = inst3.data?.id || inst3.data?.componentId;
      expect(inst3Id).toBeTruthy();

      // --- Detach inst2 and verify it becomes a plain component ---
      const detach = await tryEndpoints('POST', [
        `/api/projects/${projectId}/pages/${pageId}/components/${inst2Id}/detach-from-library`,
        `/api/projects/${projectId}/pages/${pageId}/components/${inst2Id}/detach`,
      ], {});
      expect([200, 204]).toContain(detach.res.status);

      // Verify detached instance no longer references library item
      const detachedState = await request('GET', `/api/projects/${projectId}/pages/${pageId}`);
      expect(detachedState.res.status).toBe(200);
      const detachedComp = (detachedState.data?.components || []).find((c: any) => c.id === inst2Id);
      expect(detachedComp).toBeTruthy();
      const detachedLibRef = detachedComp.libraryItemId ?? detachedComp.sourceLibraryItemId;
      expect(detachedLibRef == null || detachedLibRef === '', 'After detach, component should no longer reference a library item').toBe(true);
      // Detached component should still have its text content
      expect(detachedComp.text).toBe('custom-old');

      // --- Degradation: delete the library item, then check inst3 (still linked) ---
      const deleteLibrary = await tryEndpoints('DELETE', [
        `/api/projects/${projectId}/library-items/${libraryItemId}`,
        `/api/projects/${projectId}/library/${libraryItemId}`,
      ]);
      expect([200, 204]).toContain(deleteLibrary.res.status);

      // inst3 was never detached; its source library item is now gone
      const degradedState = await request('GET', `/api/projects/${projectId}/pages/${pageId}`);
      expect(degradedState.res.status).toBe(200);
      const degradedComp = (degradedState.data?.components || []).find((c: any) => c.id === inst3Id);
      expect(degradedComp, 'Instance whose source library was deleted should still exist on the canvas').toBeTruthy();
      // The component should still have displayable content
      expect(
        degradedComp.text != null || degradedComp.name != null,
        'Degraded instance should still have displayable content'
      ).toBe(true);
      // Verify degradation indicator: the library item reference should point to a non-existent item
      // or there should be a degraded flag
      const degradedLibRef = degradedComp.libraryItemId ?? degradedComp.sourceLibraryItemId;
      if (degradedComp.degraded !== undefined) {
        expect(degradedComp.degraded, 'Instance with missing source library should be marked as degraded').toBe(true);
      } else if (degradedLibRef) {
        // The reference exists but the library item is gone - this is the expected degradation
        // Verify attempting to resolve the library item fails
        const resolveLib = await tryEndpoints('GET', [
          `/api/projects/${projectId}/library-items/${degradedLibRef}`,
          `/api/projects/${projectId}/library/${degradedLibRef}`,
        ]);
        expect(resolveLib.res.status).toBeGreaterThanOrEqual(400);
      }
    } finally {
      await request('DELETE', `/api/projects/${projectId}`).catch(() => {});
    }
  });
});

import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function request(method: string, path: string, body?: any) {
  const res = await fetch(`${BASE_URL}${path}`, {
    method,
    headers: { 'Content-Type': 'application/json' },
    body: body === undefined ? undefined : JSON.stringify(body),
  });
  let data: any = null;
  const text = await res.text();
  try { data = text ? JSON.parse(text) : null; } catch { data = text; }
  return { res, body: data };
}

async function tryDeleteProject(projectId: string | number | undefined) {
  if (!projectId) return;
  try { await request('DELETE', `/api/projects/${projectId}`); } catch {}
}

function findExportData(body: any): any {
  if (!body) return null;
  return body.data || body.project || body.content || body;
}

function getErrorMessage(body: any): string {
  if (!body) return '';
  if (typeof body === 'string') return body;
  return body.message || body.error || body.reason || body.detail || '';
}

describe('reimport_supports_replace_or_append_without_data_loss', () => {
  it('should support append with conflict resolution, replace with full reset, require mode selection, reject invalid files, and preserve data on failed import', async () => {
    const suffix = `${Date.now()}_${Math.random().toString(36).slice(2, 8)}`;
    let projectId: string | number | undefined;

    try {
      // Create project
      const proj = await request('POST', '/api/projects', { name: `reimport-${suffix}` });
      expect(proj.res.status).toBeGreaterThanOrEqual(200);
      expect(proj.res.status).toBeLessThan(300);
      projectId = proj.body?.id;
      expect(projectId).toBeTruthy();

      // Create page with component
      const p1 = await request('POST', `/api/projects/${projectId}/pages`, { name: 'DuplicateName' });
      expect(p1.res.status).toBeGreaterThanOrEqual(200);
      expect(p1.res.status).toBeLessThan(300);
      const p1Id = p1.body?.id;
      expect(p1Id).toBeTruthy();

      const comp = await request('POST', `/api/projects/${projectId}/pages/${p1Id}/components`, {
        name: 'Card', type: 'text', x: 10, y: 10, width: 100, height: 40, text: 'Seed text',
      });
      expect(comp.res.status).toBeGreaterThanOrEqual(200);
      expect(comp.res.status).toBeLessThan(300);
      const compId = comp.body?.id;
      expect(compId).toBeTruthy();

      // Create library item
      const lib = await request('POST', `/api/projects/${projectId}/library-items`, {
        name: 'MyLib',
        sourceComponentIds: [compId],
      });
      expect(lib.res.status).toBeGreaterThanOrEqual(200);
      expect(lib.res.status).toBeLessThan(300);

      // Export project
      let exported = await request('GET', `/api/projects/${projectId}/export`);
      if (exported.res.status >= 400) {
        exported = await request('POST', `/api/projects/${projectId}/export`, { name: 'roundtrip' });
      }
      expect(exported.res.status).toBeGreaterThanOrEqual(200);
      expect(exported.res.status).toBeLessThan(300);
      const exportedData = findExportData(exported.body);
      expect(exportedData).toBeTruthy();

      // ---- Test: Import without mode should require user to choose ----
      const noModeRes = await request('POST', `/api/projects/${projectId}/import`, {
        data: exportedData,
        snapshot: exportedData,
      });
      // System should either reject (requiring mode selection) or prompt for choice
      // Accept 400, 409, 422 as "needs user decision", or 200 if mode defaults but still acceptable
      if (noModeRes.res.status >= 400) {
        expect([400, 409, 422].includes(noModeRes.res.status) || noModeRes.res.status >= 400).toBe(true);
        const msg = getErrorMessage(noModeRes.body);
        expect(msg.length, 'import without mode should return an explanatory message').toBeGreaterThan(0);
      }
      // If the system accepted it (some implementations may default), we proceed

      // ---- Append import ----
      const appendRes = await request('POST', `/api/projects/${projectId}/import`, {
        data: exportedData,
        snapshot: exportedData,
        mode: 'append',
      });
      expect(appendRes.res.status).toBeGreaterThanOrEqual(200);
      expect(appendRes.res.status).toBeLessThan(300);

      // Verify after append: pages with conflict resolution
      const afterAppend = await request('GET', `/api/projects/${projectId}`);
      expect(afterAppend.res.status).toBeGreaterThanOrEqual(200);
      expect(afterAppend.res.status).toBeLessThan(300);

      const appendedPages = afterAppend.body?.pages || [];
      const dupPages = appendedPages.filter((p: any) => String(p.name).startsWith('DuplicateName'));
      expect(dupPages.length, `append should produce at least 2 pages starting with DuplicateName, got ${JSON.stringify(appendedPages.map((p: any) => p.name))}`).toBeGreaterThanOrEqual(2);
      const uniquePageNames = new Set(dupPages.map((p: any) => p.name));
      expect(uniquePageNames.size, 'page names should be unique after append conflict resolution').toBe(dupPages.length);

      // Verify component name conflict resolution: collect all component names across pages
      const allComponentNames: string[] = [];
      for (const pg of appendedPages) {
        const pageDetail = await request('GET', `/api/projects/${projectId}/pages/${pg.id}`);
        if (pageDetail.res.status >= 200 && pageDetail.res.status < 300) {
          const comps = pageDetail.body?.components || [];
          comps.forEach((c: any) => { if (c.name) allComponentNames.push(c.name); });
        }
      }
      // After append, there should be at least 2 components with Card-related names
      const cardNames = allComponentNames.filter((n) => n.startsWith('Card'));
      expect(cardNames.length, `append should produce at least 2 Card-related components, got ${JSON.stringify(cardNames)}`).toBeGreaterThanOrEqual(2);
      const uniqueCardNames = new Set(cardNames);
      expect(uniqueCardNames.size, `component names should be deduplicated on append, got ${JSON.stringify(cardNames)}`).toBe(cardNames.length);

      // Verify library item name conflict resolution (hard assertion)
      const libItems = await request('GET', `/api/projects/${projectId}/library-items`);
      expect(libItems.res.status).toBeGreaterThanOrEqual(200);
      expect(libItems.res.status).toBeLessThan(300);
      const libs = Array.isArray(libItems.body) ? libItems.body : (libItems.body?.items || libItems.body?.libraryItems || []);
      const myLibNames = libs.filter((l: any) => String(l.name).startsWith('MyLib')).map((l: any) => l.name);
      expect(myLibNames.length, `append should produce at least 2 MyLib-related library items, got ${JSON.stringify(myLibNames)}`).toBeGreaterThanOrEqual(2);
      const uniqueLibNames = new Set(myLibNames);
      expect(uniqueLibNames.size, `library item names should be deduplicated on append, got ${JSON.stringify(myLibNames)}`).toBe(myLibNames.length);

      // ---- Replace import ----
      const replaceRes = await request('POST', `/api/projects/${projectId}/import`, {
        data: exportedData,
        snapshot: exportedData,
        mode: 'replace',
      });
      expect(replaceRes.res.status).toBeGreaterThanOrEqual(200);
      expect(replaceRes.res.status).toBeLessThan(300);

      // Verify after replace: should be back to original state (1 page named DuplicateName)
      const afterReplace = await request('GET', `/api/projects/${projectId}`);
      expect(afterReplace.res.status).toBeGreaterThanOrEqual(200);
      expect(afterReplace.res.status).toBeLessThan(300);
      const replacedPages = afterReplace.body?.pages || [];
      expect(replacedPages.length, `replace should restore to original page count (1), got ${replacedPages.length}`).toBe(1);
      expect(replacedPages[0]?.name, 'replace should restore original page name').toBe('DuplicateName');

      // Verify replaced page has the original component
      const replacedPageId = replacedPages[0]?.id;
      if (replacedPageId) {
        const replacedPageDetail = await request('GET', `/api/projects/${projectId}/pages/${replacedPageId}`);
        if (replacedPageDetail.res.status >= 200 && replacedPageDetail.res.status < 300) {
          const replacedComps = replacedPageDetail.body?.components || [];
          const cardComp = replacedComps.find((c: any) => c.name === 'Card');
          expect(cardComp, 'replace should restore component named Card').toBeTruthy();
          expect(cardComp?.text, 'replace should restore component text').toBe('Seed text');
        }
      }

      // ---- Failed import: malformed data ----
      const failImport = await request('POST', `/api/projects/${projectId}/import`, {
        data: { malformed: true, pages: 'not-array' },
        snapshot: { malformed: true, pages: 'not-array' },
        mode: 'append',
      });
      expect(failImport.res.status).toBeGreaterThanOrEqual(400);
      expect(failImport.res.status).toBeLessThan(500);
      const failMsg = getErrorMessage(failImport.body);
      expect(failMsg.length, 'failed import should return an understandable error message').toBeGreaterThan(0);

      // ---- Failed import: non-tool file (completely unrelated JSON) ----
      const nonToolImport = await request('POST', `/api/projects/${projectId}/import`, {
        data: { foo: 'bar', unrelated: [1, 2, 3] },
        snapshot: { foo: 'bar', unrelated: [1, 2, 3] },
        mode: 'append',
      });
      expect(nonToolImport.res.status).toBeGreaterThanOrEqual(400);
      expect(nonToolImport.res.status).toBeLessThan(500);
      const nonToolMsg = getErrorMessage(nonToolImport.body);
      expect(nonToolMsg.length, 'non-tool file import should return an understandable error reason').toBeGreaterThan(0);

      // ---- Failed import: invalid/out-of-range version ----
      const badVersionImport = await request('POST', `/api/projects/${projectId}/import`, {
        data: { version: 99999, pages: [] },
        snapshot: { version: 99999, pages: [] },
        mode: 'append',
      });
      expect(badVersionImport.res.status).toBeGreaterThanOrEqual(400);
      expect(badVersionImport.res.status).toBeLessThan(500);
      const badVersionMsg = getErrorMessage(badVersionImport.body);
      expect(badVersionMsg.length, 'out-of-range version import should return an understandable error reason').toBeGreaterThan(0);

      // ---- Verify data not damaged after all failed imports ----
      const afterFail = await request('GET', `/api/projects/${projectId}`);
      expect(afterFail.res.status).toBeGreaterThanOrEqual(200);
      expect(afterFail.res.status).toBeLessThan(300);
      const failPages = afterFail.body?.pages || [];
      expect(failPages.length, 'failed import must not change page count').toBe(replacedPages.length);
      expect(failPages.map((p: any) => p.name), 'failed import must preserve page names').toEqual(replacedPages.map((p: any) => p.name));
    } finally {
      await tryDeleteProject(projectId);
    }
  });
});

