describe('component_library_crud_and_instance_survival', () => {
  it('should support library CRUD validations and keep placed instances alive after library item deletion', async () => {
    const ws = await request('POST', '/api/workspaces', { workspaceKey: `verifier-library-crud-${Date.now()}`, initializeDefaultCanvas: true });
    expect([200, 201, 404, 405]).toContain(ws.res.status);
    if (ws.res.status === 404 || ws.res.status === 405) {
      throw new Error('Backend API contract is missing for component library CRUD.');
    }

    const workspaceId = ws.data?.id || ws.data?.workspaceId;
    const page = await request('POST', `/api/workspaces/${workspaceId}/pages`, { name: 'Library Host' });
    expect([200, 201]).toContain(page.res.status);
    const pageId = page.data?.id || page.data?.pageId;

    const comp = await request('POST', `/api/workspaces/${workspaceId}/pages/${pageId}/components`, {
      name: 'Card', type: 'text', text: 'Card body', x: 10, y: 10,
    });
    expect([200, 201]).toContain(comp.res.status);
    const componentId = comp.data?.id || comp.data?.componentId;

    const blankName = await request('POST', `/api/workspaces/${workspaceId}/library/items`, { name: '   ', sourceComponentId: componentId });
    expect([400, 422]).toContain(blankName.res.status);

    const longName = await request('POST', `/api/workspaces/${workspaceId}/library/items`, { name: 'x'.repeat(300), sourceComponentId: componentId });
    expect([400, 422]).toContain(longName.res.status);

    const createItem = await request('POST', `/api/workspaces/${workspaceId}/library/items`, { name: 'MyCard', sourceComponentId: componentId });
    expect([200, 201]).toContain(createItem.res.status);
    const libraryItemId = createItem.data?.id || createItem.data?.libraryItemId;
    expect(libraryItemId).toBeTruthy();

    const dupName = await request('POST', `/api/workspaces/${workspaceId}/library/items`, { name: 'MyCard', sourceComponentId: componentId });
    expect([400, 409, 422]).toContain(dupName.res.status);

    const placeInstance = await request('POST', `/api/workspaces/${workspaceId}/pages/${pageId}/components/from-library`, {
      libraryItemId,
      x: 100,
      y: 100,
    });
    expect([200, 201]).toContain(placeInstance.res.status);
    const instanceId = placeInstance.data?.id || placeInstance.data?.componentId;

    const renameItem = await request('PATCH', `/api/workspaces/${workspaceId}/library/items/${libraryItemId}`, { name: 'MyCardRenamed' });
    expect([200, 204]).toContain(renameItem.res.status);

    const list = await request('GET', `/api/workspaces/${workspaceId}/library/items`);
    expect(list.res.status).toBe(200);
    expect((list.data || []).some((i) => i.id === libraryItemId && i.name === 'MyCardRenamed')).toBe(true);

    const deleteItem = await request('DELETE', `/api/workspaces/${workspaceId}/library/items/${libraryItemId}`);
    expect([200, 204]).toContain(deleteItem.res.status);

    const pageState = await request('GET', `/api/workspaces/${workspaceId}/pages/${pageId}`);
    expect(pageState.res.status).toBe(200);
    const instance = (pageState.data?.components || []).find((c) => c.id === instanceId);
    expect(instance, `Expected placed library instance to survive after library deletion, got ${JSON.stringify(pageState.data)}`).toBeTruthy();
    expect(instance?.text).toBe('Card body');

    await request('DELETE', `/api/workspaces/${workspaceId}`).catch(() => {});
  });
});

