      ).toBe(false);

      // Illegal file — should be rejected with reason
      const illegal = await request('POST', `/api/projects/${projectId}/import`, {
        mode: 'append',
        snapshot: { bad: true },
        data: { bad: true },
      });
      expect([400, 409, 422], `illegal snapshot should be rejected, got ${illegal.res.status}`).toContain(illegal.res.status);
      // Verify error reason is provided
      const illegalMsg = illegal.body?.message || illegal.body?.reason || illegal.body?.error;
      expect(illegalMsg, `rejected import should provide an error message, got body: ${JSON.stringify(illegal.body)}`).toBeTruthy();

      // Future version — should be rejected with reason
      const future = await request('POST', `/api/projects/${projectId}/import`, {
        mode: 'append',
        snapshot: { version: 999999, name: 'future', pages: [] },
        data: { version: 999999, name: 'future', pages: [] },
      });
      expect([400, 409, 422], `future version should be rejected, got ${future.res.status}`).toContain(future.res.status);
      const futureMsg = future.body?.message || future.body?.reason || future.body?.error;
      expect(futureMsg, `rejected future version import should provide an error message`).toBeTruthy();

      // Verify current project unaffected by failed imports
      const finalState = await request('GET', `/api/projects/${projectId}`);
      expect(finalState.res.status).toBeGreaterThanOrEqual(200);
      expect(finalState.res.status).toBeLessThan(300);
      expect(
        finalState.body?.pages?.some((p: any) => p.name === `OnlyPage_${suffix}`),
        `rejected imports must not damage current project`,
      ).toBe(true);

      // Test: import without mode should be rejected or require explicit choice
      const noMode = await request('POST', `/api/projects/${projectId}/import`, {
        snapshot: snapshotData,
        data: snapshotData,
      });
      // Either rejected (400/422) or the server defaults but doesn't silently overwrite
      if (noMode.res.status >= 200 && noMode.res.status < 300) {
        // If server accepts without mode, at least the existing data should still be intact
        const afterNoMode = await request('GET', `/api/projects/${projectId}`);
        expect(
          afterNoMode.body?.pages?.some((p: any) => p.name === `OnlyPage_${suffix}`),
          'import without explicit mode should not silently destroy existing data',
        ).toBe(true);
      }
      // If rejected, that's also acceptable (server requires explicit mode)
    } finally {
      await cleanupProject(projectId);
    }
  });
});

