describe('duplicate_page_copies_content_and_view_state', () => {
  it('should duplicate page with independent content, unique name, canvas settings, layer order, and view state', async () => {
    const suffix = `${Date.now()}_${Math.random().toString(36).slice(2, 8)}`;
    let projectId: string | number | undefined;

    try {
      // Create project
      const proj = await request('POST', '/api/projects', { name: `proj_dup_${suffix}` });
      expect(proj.res.status).toBeGreaterThanOrEqual(200);
      expect(proj.res.status).toBeLessThan(300);
      projectId = proj.data?.id ?? proj.data?.projectId;
      expect(projectId).toBeTruthy();

      // Create original page
      const originalPage = await request('POST', `/api/projects/${projectId}/pages`, { name: 'Original' });
      expect(originalPage.res.status).toBeGreaterThanOrEqual(200);
      expect(originalPage.res.status).toBeLessThan(300);
      const originalPageId = originalPage.data?.id ?? originalPage.data?.pageId;
      expect(originalPageId).toBeTruthy();

      // Add two components with layer ordering
      const c1 = await request('POST', `/api/projects/${projectId}/pages/${originalPageId}/components`, {
        name: 'Top',
        type: 'text',
        text: 'TopText',
        x: 10,
        y: 10,
        width: 20,
        height: 20,
        zIndex: 2,
      });
      const c2 = await request('POST', `/api/projects/${projectId}/pages/${originalPageId}/components`, {
        name: 'Bottom',
        type: 'text',
        text: 'BottomText',
        x: 20,
        y: 20,
        width: 20,
        height: 20,
        zIndex: 1,
      });
      expect(c1.res.status).toBeGreaterThanOrEqual(200);
      expect(c1.res.status).toBeLessThan(300);
      expect(c2.res.status).toBeGreaterThanOrEqual(200);
      expect(c2.res.status).toBeLessThan(300);

      // Set canvas settings
      let setCanvas = await request('PATCH', `/api/projects/${projectId}/pages/${originalPageId}/canvas`, {
        width: 1024,
        height: 768,
        orientation: 'landscape',
      });
      if (setCanvas.res.status === 404) {
        setCanvas = await request('PATCH', `/api/projects/${projectId}/pages/${originalPageId}`, {
          canvas: { width: 1024, height: 768, orientation: 'landscape' },
        });
      }
      // Canvas setting might be optional, continue regardless

      // Set view state (zoom, pan, grid)
      let setView = await request('PATCH', `/api/projects/${projectId}/pages/${originalPageId}/view`, {
        zoom: 1.5,
        panX: 120,
        panY: 80,
        gridEnabled: true,
        gridSize: 8,
      });
      if (setView.res.status === 404) {
        setView = await request('PATCH', `/api/projects/${projectId}/pages/${originalPageId}`, {
          view: { zoom: 1.5, panX: 120, panY: 80 },
          grid: { enabled: true, size: 8 },
        });
      }
      // View setting might be optional, continue regardless

      // Duplicate the page
      let duplicate = await request('POST', `/api/projects/${projectId}/pages/${originalPageId}/duplicate`);
      if (duplicate.res.status === 404) {
        duplicate = await request('POST', `/api/projects/${projectId}/pages/${originalPageId}/copy`);
      }
      if (duplicate.res.status === 404) {
        duplicate = await request('POST', `/api/projects/${projectId}/duplicate-page`, {
          pageId: originalPageId,
        });
      }
      expect(duplicate.res.status).toBeGreaterThanOrEqual(200);
      expect(duplicate.res.status).toBeLessThan(300);
      const duplicatePageId = duplicate.data?.id ?? duplicate.data?.pageId;
      expect(duplicatePageId).toBeTruthy();

      // Verify name is different from original
      const dupName = duplicate.data?.name ?? '';
      expect(dupName.trim()).not.toBe('Original');
      expect(dupName.trim().length).toBeGreaterThan(0);

      // Read both pages
      const originalState = await request('GET', `/api/projects/${projectId}/pages/${originalPageId}`);
      const duplicateState = await request('GET', `/api/projects/${projectId}/pages/${duplicatePageId}`);
      expect(originalState.res.status).toBe(200);
      expect(duplicateState.res.status).toBe(200);

      // Verify components are copied
      const origComponents = originalState.data?.components ?? [];
      const dupComponents = duplicateState.data?.components ?? [];
      expect(dupComponents.length).toBe(origComponents.length);
      expect(dupComponents.length).toBe(2);

      // Verify component names are preserved
      const origNames = origComponents.map((c: any) => c.name).sort();
      const dupNames = dupComponents.map((c: any) => c.name).sort();
      expect(dupNames).toEqual(origNames);

      // Verify components have different IDs (independent copies)
      const origIds = origComponents.map((c: any) => c.id).sort();
      const dupIds = dupComponents.map((c: any) => c.id).sort();
      expect(dupIds).not.toEqual(origIds);

      // Verify layer order is preserved (by checking relative ordering)
      const origOrder = origComponents.map((c: any) => c.name);
      const dupOrder = dupComponents.map((c: any) => c.name);
      expect(dupOrder).toEqual(origOrder);

      // Verify canvas settings if available
      const origCanvas = originalState.data?.canvas ?? originalState.data?.canvasSettings;
      const dupCanvas = duplicateState.data?.canvas ?? duplicateState.data?.canvasSettings;
      if (origCanvas && dupCanvas) {
        expect(dupCanvas.width ?? dupCanvas.canvasWidth).toBe(origCanvas.width ?? origCanvas.canvasWidth);
        expect(dupCanvas.height ?? dupCanvas.canvasHeight).toBe(origCanvas.height ?? origCanvas.canvasHeight);
      }

      // Verify view/grid state if available
      const origView = originalState.data?.view;
      const dupView = duplicateState.data?.view;
      if (origView && dupView) {
        expect(origView).toBeDefined();
        expect(dupView).toBeDefined();
        if (origView.zoom !== undefined) {
          expect(dupView.zoom).toBe(origView.zoom);
        }
        if (origView.panX !== undefined) {
          expect(dupView.panX).toBe(origView.panX);
        }
        if (origView.panY !== undefined) {
          expect(dupView.panY).toBe(origView.panY);
        }
      }

      const origGrid = originalState.data?.grid ?? originalState.data?.gridSettings;
      const dupGrid = duplicateState.data?.grid ?? duplicateState.data?.gridSettings;
      if (origGrid && dupGrid) {
        expect(dupGrid.enabled ?? dupGrid.gridEnabled).toBe(origGrid.enabled ?? origGrid.gridEnabled);
        expect(dupGrid.size ?? dupGrid.gridSize).toBe(origGrid.size ?? origGrid.gridSize);
      }

      // --- Verify independence: edit duplicate and check original is unchanged ---
      const dupComp0Id = dupComponents[0].id;
      const editDup = await request('PATCH', `/api/projects/${projectId}/pages/${duplicatePageId}/components/${dupComp0Id}`, {
        name: 'Edited in duplicate',
      });
      expect(editDup.res.status).toBeGreaterThanOrEqual(200);
      expect(editDup.res.status).toBeLessThan(300);

      const originalAfter = await request('GET', `/api/projects/${projectId}/pages/${originalPageId}`);
      expect(originalAfter.res.status).toBe(200);
      const origCompsAfter = originalAfter.data?.components ?? [];
      expect(origCompsAfter.some((c: any) => c.name === 'Edited in duplicate')).toBe(false);

      // --- Verify empty page duplication ---
      const emptyPage = await request('POST', `/api/projects/${projectId}/pages`, { name: `EmptyPage_${suffix}` });
      expect(emptyPage.res.status).toBeGreaterThanOrEqual(200);
      expect(emptyPage.res.status).toBeLessThan(300);
      const emptyPageId = emptyPage.data?.id ?? emptyPage.data?.pageId;
      expect(emptyPageId).toBeTruthy();

      let emptyDup = await request('POST', `/api/projects/${projectId}/pages/${emptyPageId}/duplicate`);
      if (emptyDup.res.status === 404) {
        emptyDup = await request('POST', `/api/projects/${projectId}/pages/${emptyPageId}/copy`);
      }
      if (emptyDup.res.status === 404) {
        emptyDup = await request('POST', `/api/projects/${projectId}/duplicate-page`, {
          pageId: emptyPageId,
        });
      }
      expect(emptyDup.res.status).toBeGreaterThanOrEqual(200);
      expect(emptyDup.res.status).toBeLessThan(300);
      const emptyDupId = emptyDup.data?.id ?? emptyDup.data?.pageId;
      expect(emptyDupId).toBeTruthy();

      const emptyDupState = await request('GET', `/api/projects/${projectId}/pages/${emptyDupId}`);
      expect(emptyDupState.res.status).toBe(200);
      expect((emptyDupState.data?.components ?? []).length).toBe(0);

      // Verify the empty duplicated page is editable (truly independent)
      const addToEmptyDup = await request('POST', `/api/projects/${projectId}/pages/${emptyDupId}/components`, {
        name: `NewComp_${suffix}`,
        type: 'text',
        text: 'test',
        x: 0,
        y: 0,
        width: 50,
        height: 20,
      });
      expect(addToEmptyDup.res.status).toBeGreaterThanOrEqual(200);
      expect(addToEmptyDup.res.status).toBeLessThan(300);

    } finally {
      await cleanupProject(projectId);
    }
  });
});

