describe('page_view_state_persists_per_page_without_mutating_layout', () => {
  it('should persist view state per page while keeping component geometry unchanged', async () => {
    const project = await createProject();
    try {
      const page1 = await createPage(project.id, 'ViewPage1');
      const page2 = await createPage(project.id, 'ViewPage2');
      const cmp1 = await createComponent(project.id, page1.id);
      await createComponent(project.id, page2.id);

      // Record original component geometry
      const before = await getPage(project.id, page1.id);
      const beforeCmp = (before?.components ?? []).find((c: any) => (c.id ?? c.componentId) === cmp1.id);
      expect(beforeCmp, 'component should exist on page1').toBeTruthy();
      const original = { x: beforeCmp.x, y: beforeCmp.y, width: beforeCmp.width, height: beforeCmp.height };

      // Set zoom/view state on page 1
      const setView1 = await request(`/api/projects/${project.id}/pages/${page1.id}/view-state`, {
        method: 'PUT',
        body: JSON.stringify({ zoom: 1.5, panX: 120, panY: 80 }),
      });
      expect(setView1.res.status).toBeGreaterThanOrEqual(200);
      expect(setView1.res.status).toBeLessThan(300);

      // Set different zoom/view state on page 2
      const setView2 = await request(`/api/projects/${project.id}/pages/${page2.id}/view-state`, {
        method: 'PUT',
        body: JSON.stringify({ zoom: 0.75, panX: -40, panY: 30 }),
      });
      expect(setView2.res.status).toBeGreaterThanOrEqual(200);
      expect(setView2.res.status).toBeLessThan(300);

      // Simulate switching to page 2 then back to page 1 by reading page 2 first
      const switchToPage2 = await getPage(project.id, page2.id);
      expect(switchToPage2).toBeTruthy();

      // Now switch back to page 1 and verify its view state persisted
      const afterPage1 = await getPage(project.id, page1.id);
      const afterPage2 = await getPage(project.id, page2.id);

      // Assert view state field exists on page 1
      const vs1 = afterPage1?.viewState ?? afterPage1?.view ?? afterPage1?.viewSettings;
      expect(vs1, `page1 should have persisted view state, got page data keys: ${Object.keys(afterPage1 ?? {})}`).toBeTruthy();
      expect(vs1).toMatchObject({ zoom: 1.5, panX: 120, panY: 80 });

      // Assert view state field exists on page 2 independently
      const vs2 = afterPage2?.viewState ?? afterPage2?.view ?? afterPage2?.viewSettings;
      expect(vs2, `page2 should have its own persisted view state, got page data keys: ${Object.keys(afterPage2 ?? {})}`).toBeTruthy();
      expect(vs2).toMatchObject({ zoom: 0.75, panX: -40, panY: 30 });

      // Verify that zoom did NOT change component real geometry
      const afterCmp = (afterPage1?.components ?? []).find((c: any) => (c.id ?? c.componentId) === cmp1.id);
      expect(afterCmp, 'component should still exist after view state change').toBeTruthy();
      expect(
        { x: afterCmp.x, y: afterCmp.y, width: afterCmp.width, height: afterCmp.height },
        'zoom/view state must not mutate real layout geometry',
      ).toEqual(original);

      // Additional: set zoom to extreme values and verify geometry still unchanged
      const setExtremeZoom = await request(`/api/projects/${project.id}/pages/${page1.id}/view-state`, {
        method: 'PUT',
        body: JSON.stringify({ zoom: 3.0, panX: 500, panY: 500 }),
      });
      if (setExtremeZoom.res.status >= 200 && setExtremeZoom.res.status < 300) {
        const afterExtreme = await getPage(project.id, page1.id);
        const extremeCmp = (afterExtreme?.components ?? []).find((c: any) => (c.id ?? c.componentId) === cmp1.id);
        expect(extremeCmp, 'component should exist after extreme zoom').toBeTruthy();
        expect(
          { x: extremeCmp.x, y: extremeCmp.y, width: extremeCmp.width, height: extremeCmp.height },
          'extreme zoom must not mutate real layout geometry',
        ).toEqual(original);
      }
    } finally {
      await tryDeleteProject(project.id);
    }
  });
});

