describe('project_summary_counts_update_after_operations', () => {
  it('should update summary counters after create, lock, hide, delete, library, edit, import/export operations and show guidance when empty', async () => {
    const project = await createProject();
    try {
      // ---- Verify empty project summary (guidance / zero counts) ----
      const initialSummary = await request(`/api/projects/${project.id}/summary`);
      expect(initialSummary.res.status).toBe(200);
      const s0 = initialSummary.body;

      const initialPageCount = getSummaryField(s0, 'pageCount', 'pages');
      expect(initialPageCount !== undefined, 'summary should include page count field').toBe(true);
      const initialComponentCount = getSummaryField(s0, 'componentCount', 'components');
      expect(initialComponentCount !== undefined, 'summary should include component count field').toBe(true);
      expect(initialComponentCount).toBe(0);
      const initialLibraryCount = getSummaryField(s0, 'libraryItemCount', 'libraryItems');
      expect(initialLibraryCount !== undefined, 'summary should include library item count field').toBe(true);
      expect(initialLibraryCount).toBe(0);
      const initialLockedCount = getSummaryField(s0, 'lockedCount', 'lockedItems');
      expect(initialLockedCount !== undefined, 'summary should include locked items count field').toBe(true);
      expect(initialLockedCount).toBe(0);
      const initialHiddenCount = getSummaryField(s0, 'hiddenCount', 'hiddenItems');
      expect(initialHiddenCount !== undefined, 'summary should include hidden items count field').toBe(true);
      expect(initialHiddenCount).toBe(0);

      // Check for guidance/empty state message
