      const c1 = await createComponent(project.id, page.id, { name: 'VisibleOne', type: 'button', x: 1, y: 1, width: 10, height: 10, text: 'btn' });
      const c2 = await createComponent(project.id, page.id, { name: 'HiddenLocked', type: 'text', x: 2, y: 2, width: 10, height: 10, text: 'x' });

      // ---- Lock and hide c2 ----
      const lockRes = await request(`/api/projects/${project.id}/pages/${page.id}/components/${c2.id}`, {
        method: 'PATCH',
        body: JSON.stringify({ locked: true, hidden: true }),
      });
      expect(lockRes.res.status).toBeGreaterThanOrEqual(200);
      expect(lockRes.res.status).toBeLessThan(300);

      // ---- Create a library item ----
      const createLib = await request(`/api/projects/${project.id}/library-items`, {
        method: 'POST',
        body: JSON.stringify({ name: 'SummaryLib', sourceComponentIds: [c1.id], pageId: page.id }),
