      });
      expect(renameRes.res.status).toBeGreaterThanOrEqual(200);
      expect(renameRes.res.status).toBeLessThan(300);

      const summaryAfterEdit = await request(`/api/projects/${project.id}/summary`);
      expect(summaryAfterEdit.res.status).toBe(200);
      // Component count should stay the same after rename
      const componentCountAfterEdit = getSummaryField(summaryAfterEdit.body, 'componentCount', 'components');
      expect(componentCountAfterEdit, 'component count should stay the same after edit').toBe(componentCount);

      // ---- Delete a component and verify count decreases ----
      const deleteRes = await request(`/api/projects/${project.id}/pages/${page.id}/components/${c1.id}`, { method: 'DELETE' });
      expect(deleteRes.res.status).toBeGreaterThanOrEqual(200);
      expect(deleteRes.res.status).toBeLessThan(300);

      const summaryAfterDelete = await request(`/api/projects/${project.id}/summary`);
      expect(summaryAfterDelete.res.status).toBe(200);
      const sd = summaryAfterDelete.body;
      const componentCountAfter = getSummaryField(sd, 'componentCount', 'components');
