      // ---- Import and verify import summary updates ----
      if (exportRes.body) {
        const exportedData = exportRes.body?.data || exportRes.body?.project || exportRes.body?.content || exportRes.body;
        const importRes = await request(`/api/projects/${project.id}/import`, {
          method: 'POST',
          body: JSON.stringify({ data: exportedData, mode: 'replace' }),
        });
        expect(importRes.res.status).toBeGreaterThanOrEqual(200);
        expect(importRes.res.status).toBeLessThan(300);

        const summaryAfterImport = await request(`/api/projects/${project.id}/summary`);
        expect(summaryAfterImport.res.status).toBe(200);
        const si = summaryAfterImport.body;
        const importSummary = getSummaryField(si, 'lastImportSummary', 'lastImport', 'lastOperationSummary');
        expect(importSummary, 'summary should include recent import result summary after import').toBeTruthy();
        if (typeof importSummary === 'object') {
          const hasInfo = importSummary.timestamp || importSummary.time || importSummary.pages !== undefined || importSummary.components !== undefined || Object.keys(importSummary).length > 0;
          expect(hasInfo, 'import summary should contain meaningful data').toBe(true);
        } else if (typeof importSummary === 'string') {
          expect((importSummary as string).length, 'import summary string should be non-empty').toBeGreaterThan(0);
        }
      }
    } finally {
      await tryDeleteProject(project.id);
    }
  });
});

