      expect([400, 403, 409].includes(moveAttempt.res.status) || moveAttempt.body?.x === 10, `locked component move should be blocked, got status=${moveAttempt.res.status}, body=${JSON.stringify(moveAttempt.body)}`).toBe(true);

      const deleteAttempt = await request('DELETE', `/api/projects/${projectId}/pages/${pageId}/components/${compId}`);
