import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function request(method: string, path: string, body?: any) {
  const res = await fetch(`${BASE_URL}${path}`, {
    method,
    headers: { 'Content-Type': 'application/json' },
    body: body === undefined ? undefined : JSON.stringify(body),
  });
  const text = await res.text();
  let data: any = null;
  try { data = text ? JSON.parse(text) : null; } catch { data = text; }
  return { res, data };
}

async function tryEndpoints(method: string, paths: string[], body?: any) {
  for (const path of paths) {
    const resp = await request(method, path, body);
    if (resp.res.status !== 404) return { ...resp, usedPath: path };
  }
  const resp = await request(method, paths[paths.length - 1], body);
  return { ...resp, usedPath: paths[paths.length - 1] };
}

describe('batch_layer_operations_skip_locked_and_limit_selection', () => {
  it('should reject selecting more than 10, skip locked layers during batch ops, support batch hide/show, and restore empty state after deletions', async () => {
    const suffix = `${Date.now()}_${Math.random().toString(36).slice(2, 8)}`;
    // Create project
    const ws = await request('POST', '/api/projects', { name: `verifier-batch-layers-${suffix}` });
    expect([200, 201]).toContain(ws.res.status);
    const projectId = ws.data?.id || ws.data?.projectId;
    expect(projectId).toBeTruthy();

    try {
      // Create page
      const page = await request('POST', `/api/projects/${projectId}/pages`, { name: 'Layer Page' });
      expect([200, 201]).toContain(page.res.status);
      const pageId = page.data?.id || page.data?.pageId;
      expect(pageId).toBeTruthy();

      // Create 11 components
      const ids: string[] = [];
      for (let i = 0; i < 11; i++) {
        const created = await request('POST', `/api/projects/${projectId}/pages/${pageId}/components`, {
          name: `Rect ${i + 1}`,
          type: 'button',
          x: i * 10,
          y: i * 10,
          width: 50,
          height: 50,
        });
        expect([200, 201]).toContain(created.res.status);
        ids.push(created.data?.id || created.data?.componentId);
      }

      // Lock two components and record their original positions
      const lockARes = await request('PATCH', `/api/projects/${projectId}/pages/${pageId}/components/${ids[2]}`, { locked: true });
      expect([200, 204]).toContain(lockARes.res.status);
      const lockBRes = await request('PATCH', `/api/projects/${projectId}/pages/${pageId}/components/${ids[7]}`, { locked: true });
      expect([200, 204]).toContain(lockBRes.res.status);

      // Record original positions of locked components before move
      const stateBeforeMove = await request('GET', `/api/projects/${projectId}/pages/${pageId}`);
      expect(stateBeforeMove.res.status).toBe(200);
      const compsBefore = stateBeforeMove.data?.components || [];
      const lockedA_before = compsBefore.find((c: any) => c.id === ids[2]);
      const lockedB_before = compsBefore.find((c: any) => c.id === ids[7]);
      const unlockedFirst_before = compsBefore.find((c: any) => c.id === ids[0]);
      expect(lockedA_before).toBeTruthy();
      expect(lockedB_before).toBeTruthy();
      expect(unlockedFirst_before).toBeTruthy();

      // --- Test: selecting more than 10 should be rejected with clear message ---
      const selectTooMany = await tryEndpoints('POST', [
        `/api/projects/${projectId}/pages/${pageId}/selection`,
        `/api/projects/${projectId}/pages/${pageId}/select`,
      ], { componentIds: ids });
      expect(selectTooMany.res.status).toBeGreaterThanOrEqual(400);
      expect(selectTooMany.res.status).toBeLessThan(500);
      // Verify error message is present
      const tooManyMsg = selectTooMany.data?.message ?? selectTooMany.data?.error ?? selectTooMany.data?.reason;
      expect(tooManyMsg, 'Selecting >10 should return a clear error message').toBeTruthy();

      // --- Test: selecting exactly 10 should succeed ---
      const selectedTen = ids.slice(0, 10);
      const selectOk = await tryEndpoints('POST', [
        `/api/projects/${projectId}/pages/${pageId}/selection`,
        `/api/projects/${projectId}/pages/${pageId}/select`,
      ], { componentIds: selectedTen });
      expect([200, 204]).toContain(selectOk.res.status);

      // --- Test: batch move should skip locked components ---
      const moveBatch = await tryEndpoints('POST', [
        `/api/projects/${projectId}/pages/${pageId}/components/batch-move`,
        `/api/projects/${projectId}/pages/${pageId}/batch/move`,
      ], {
        componentIds: selectedTen,
        dx: 100,
        dy: 50,
      });
      expect([200, 204]).toContain(moveBatch.res.status);

      // Verify batch-move response contains skip feedback (must have it, not optional)
      if (moveBatch.data && typeof moveBatch.data === 'object') {
        const skipped = moveBatch.data.skippedCount ?? moveBatch.data.skippedIds?.length ?? moveBatch.data.skipped;
        expect(skipped, 'batch-move should report skipped locked items').toBeTruthy();
        expect(Number(skipped)).toBeGreaterThanOrEqual(1);
      }

      const stateAfterMove = await request('GET', `/api/projects/${projectId}/pages/${pageId}`);
      expect(stateAfterMove.res.status).toBe(200);
      const componentsAfterMove = stateAfterMove.data?.components || [];

      const movedUnlocked = componentsAfterMove.find((c: any) => c.id === ids[0]);
      const stayedLockedA = componentsAfterMove.find((c: any) => c.id === ids[2]);
      const stayedLockedB = componentsAfterMove.find((c: any) => c.id === ids[7]);
      expect(movedUnlocked).toBeTruthy();
      expect(stayedLockedA).toBeTruthy();
      expect(stayedLockedB).toBeTruthy();
      expect(movedUnlocked.x, `Unlocked component should have moved`).toBe(unlockedFirst_before.x + 100);
      expect(movedUnlocked.y, `Unlocked component should have moved`).toBe(unlockedFirst_before.y + 50);
      expect(stayedLockedA.x, `Locked component A should NOT have moved`).toBe(lockedA_before.x);
      expect(stayedLockedA.y, `Locked component A should NOT have moved`).toBe(lockedA_before.y);
      expect(stayedLockedB.x, `Locked component B should NOT have moved`).toBe(lockedB_before.x);
      expect(stayedLockedB.y, `Locked component B should NOT have moved`).toBe(lockedB_before.y);

      // --- Test: batch hide (including a locked component) ---
      const batchHideIds = [ids[0], ids[1], ids[2]]; // ids[2] is locked
      const batchHide = await tryEndpoints('POST', [
        `/api/projects/${projectId}/pages/${pageId}/components/batch-hide`,
        `/api/projects/${projectId}/pages/${pageId}/batch/hide`,
      ], {
        componentIds: batchHideIds,
      });
      expect([200, 204]).toContain(batchHide.res.status);

      const stateAfterHide = await request('GET', `/api/projects/${projectId}/pages/${pageId}`);
      expect(stateAfterHide.res.status).toBe(200);
      const compsAfterHide = stateAfterHide.data?.components || [];

      // Verify unlocked components are hidden
      const hiddenUnlocked0 = compsAfterHide.find((c: any) => c.id === ids[0]);
      const hiddenUnlocked1 = compsAfterHide.find((c: any) => c.id === ids[1]);
      expect(hiddenUnlocked0).toBeTruthy();
      expect(hiddenUnlocked1).toBeTruthy();
      const isHidden0 = hiddenUnlocked0.hidden === true || hiddenUnlocked0.visible === false;
      const isHidden1 = hiddenUnlocked1.hidden === true || hiddenUnlocked1.visible === false;
      expect(isHidden0, 'Unlocked component 0 should be hidden after batch hide').toBe(true);
      expect(isHidden1, 'Unlocked component 1 should be hidden after batch hide').toBe(true);

      // Check locked component's hidden state (batch hide may or may not affect locked items for hide/show)
      const lockedAfterHide = compsAfterHide.find((c: any) => c.id === ids[2]);
      expect(lockedAfterHide).toBeTruthy();

      // --- Test: batch show ---
      const batchShow = await tryEndpoints('POST', [
        `/api/projects/${projectId}/pages/${pageId}/components/batch-show`,
        `/api/projects/${projectId}/pages/${pageId}/batch/show`,
      ], {
        componentIds: batchHideIds,
      });
      expect([200, 204]).toContain(batchShow.res.status);

      const stateAfterShow = await request('GET', `/api/projects/${projectId}/pages/${pageId}`);
      expect(stateAfterShow.res.status).toBe(200);
      const compsAfterShow = stateAfterShow.data?.components || [];
      const shownUnlocked = compsAfterShow.find((c: any) => c.id === ids[0]);
      expect(shownUnlocked).toBeTruthy();
      const isVisible = shownUnlocked.hidden === false || shownUnlocked.hidden === undefined || shownUnlocked.visible === true;
      expect(isVisible, 'Unlocked component should be visible after batch show').toBe(true);

      // --- Test: batch delete should skip locked components and report feedback ---
      const deleteBatch = await tryEndpoints('POST', [
        `/api/projects/${projectId}/pages/${pageId}/components/batch-delete`,
        `/api/projects/${projectId}/pages/${pageId}/batch/delete`,
      ], {
        componentIds: ids,
      });
      expect([200, 204]).toContain(deleteBatch.res.status);

      // Verify batch-delete response contains skip feedback (must have it)
      if (deleteBatch.data && typeof deleteBatch.data === 'object') {
        const skippedDel = deleteBatch.data.skippedCount ?? deleteBatch.data.skippedIds?.length ?? deleteBatch.data.skipped;
        expect(skippedDel, 'batch-delete should report skipped locked items').toBeTruthy();
        expect(Number(skippedDel)).toBeGreaterThanOrEqual(1);
      }

      const stateAfterDelete = await request('GET', `/api/projects/${projectId}/pages/${pageId}`);
      expect(stateAfterDelete.res.status).toBe(200);
      const remaining = stateAfterDelete.data?.components || [];
      expect(remaining.some((c: any) => c.id === ids[2]), 'Locked component ids[2] should survive batch delete').toBe(true);
      expect(remaining.some((c: any) => c.id === ids[7]), 'Locked component ids[7] should survive batch delete').toBe(true);
      // Only the 2 locked components should remain
      expect(remaining.length).toBe(2);

      // --- Test: unlock and delete remaining, then verify empty state ---
      for (const id of [ids[2], ids[7]]) {
        await request('PATCH', `/api/projects/${projectId}/pages/${pageId}/components/${id}`, { locked: false });
        await request('DELETE', `/api/projects/${projectId}/pages/${pageId}/components/${id}`);
      }

      const finalState = await request('GET', `/api/projects/${projectId}/pages/${pageId}`);
      expect(finalState.res.status).toBe(200);
      const finalComps = finalState.data?.components || [];
      expect(finalComps.length, 'Expected no components left after cleaning up locked items').toBe(0);
      // Verify empty state indicator if available
      const emptyIndicator = finalState.data?.emptyState ?? finalState.data?.isEmpty ?? finalState.data?.layerEmptyMessage;
      if (emptyIndicator !== undefined) {
        expect(emptyIndicator).toBeTruthy();
      }
    } finally {
      await request('DELETE', `/api/projects/${projectId}`).catch(() => {});
    }
  });
});

import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function request(path, options = {}) {
  const res = await fetch(`${BASE_URL}${path}`, {
    headers: { 'Content-Type': 'application/json', ...(options.headers || {}) },
    ...options,
  });
  let body = null;
  const text = await res.text();
  try { body = text ? JSON.parse(text) : null; } catch { body = text; }
  return { res, body };
}

async function createProject() {
  const { res, body } = await request('/api/projects', { method: 'POST', body: JSON.stringify({ name: `undo-redo-${Date.now()}` }) });
  expect(res.status).toBe(201);
  return body;
}
async function createPage(projectId, name) {
  const { res, body } = await request(`/api/projects/${projectId}/pages`, { method: 'POST', body: JSON.stringify({ name }) });
  expect(res.status).toBe(201);
  return body;
}
async function createComponent(projectId, pageId, payload) {
  const { res, body } = await request(`/api/projects/${projectId}/pages/${pageId}/components`, { method: 'POST', body: JSON.stringify(payload) });
  expect(res.status).toBe(201);
  return body;
}
async function getPage(projectId, pageId) {
  const { res, body } = await request(`/api/projects/${projectId}/pages/${pageId}`);
  expect(res.status).toBe(200);
  return body;
}
async function undo(projectId, pageId) {
  return await request(`/api/projects/${projectId}/pages/${pageId}/history/undo`, { method: 'POST' });
}
async function redo(projectId, pageId) {
  return await request(`/api/projects/${projectId}/pages/${pageId}/history/redo`, { method: 'POST' });
}
async function tryDeleteProject(projectId) { try { await request(`/api/projects/${projectId}`, { method: 'DELETE' }); } catch {} }

describe('round9_per_canvas_undo_redo_history', () => {
  it('should keep undo/redo history isolated per canvas, cover multiple operation types, clear redo chain after new change, and respect history limit', async () => {
    const project = await createProject();
    try {
      const page1 = await createPage(project.id, 'Canvas A');
      const page2 = await createPage(project.id, 'Canvas B');

      // ====== 1. Undo new component creation ======
      const cmp = await createComponent(project.id, page1.id, {
        name: 'UndoMe', type: 'text', x: 10, y: 10, width: 100, height: 20, text: 'before',
      });

      // Undo the creation
      const undoCreate = await undo(project.id, page1.id);
      expect([200, 204]).toContain(undoCreate.res.status);

      let page1State = await getPage(project.id, page1.id);
      let comps = page1State.components || [];
      const cmpAfterUndoCreate = comps.find((c) => c.id === cmp.id);
      expect(cmpAfterUndoCreate, 'Component should be gone after undoing creation').toBeFalsy();

      // Redo the creation
      const redoCreate = await redo(project.id, page1.id);
      expect([200, 204]).toContain(redoCreate.res.status);

      page1State = await getPage(project.id, page1.id);
      comps = page1State.components || [];
      const cmpAfterRedoCreate = comps.find((c) => c.id === cmp.id);
      expect(cmpAfterRedoCreate, 'Component should reappear after redoing creation').toBeTruthy();

      // ====== 2. Undo move (position change) ======
      const move = await request(`/api/projects/${project.id}/pages/${page1.id}/components/${cmp.id}`, {
        method: 'PATCH',
        body: JSON.stringify({ x: 99, y: 88 }),
      });
      expect([200, 204]).toContain(move.res.status);

      const undoMove = await undo(project.id, page1.id);
      expect([200, 204]).toContain(undoMove.res.status);

      page1State = await getPage(project.id, page1.id);
      const cmpAfterUndoMove = (page1State.components || []).find((c) => c.id === cmp.id);
      expect(cmpAfterUndoMove).toBeTruthy();
      expect(cmpAfterUndoMove.x, 'undo move should revert x from 99').not.toBe(99);

      // Redo the move
      const redoMove = await redo(project.id, page1.id);
      expect([200, 204]).toContain(redoMove.res.status);
      page1State = await getPage(project.id, page1.id);
      const cmpAfterRedoMove = (page1State.components || []).find((c) => c.id === cmp.id);
      expect(cmpAfterRedoMove.x, 'redo move should reapply x=99').toBe(99);

      // ====== 3. Undo text modification ======
      const textEdit = await request(`/api/projects/${project.id}/pages/${page1.id}/components/${cmp.id}`, {
        method: 'PATCH',
        body: JSON.stringify({ text: 'modified-text' }),
      });
      expect([200, 204]).toContain(textEdit.res.status);

      const undoText = await undo(project.id, page1.id);
      expect([200, 204]).toContain(undoText.res.status);

      page1State = await getPage(project.id, page1.id);
      const cmpAfterUndoText = (page1State.components || []).find((c) => c.id === cmp.id);
      expect(cmpAfterUndoText.text, 'undo text should revert from modified-text').not.toBe('modified-text');

      // Redo text
      const redoText = await redo(project.id, page1.id);
      expect([200, 204]).toContain(redoText.res.status);

      // ====== 4. Undo rename ======
      const rename = await request(`/api/projects/${project.id}/pages/${page1.id}/components/${cmp.id}`, {
        method: 'PATCH',
        body: JSON.stringify({ name: 'RenamedComp' }),
      });
      expect([200, 204]).toContain(rename.res.status);

      const undoRename = await undo(project.id, page1.id);
      expect([200, 204]).toContain(undoRename.res.status);

      page1State = await getPage(project.id, page1.id);
      const cmpAfterUndoRename = (page1State.components || []).find((c) => c.id === cmp.id);
      expect(cmpAfterUndoRename.name, 'undo rename should revert from RenamedComp').not.toBe('RenamedComp');

      // Redo rename and keep it
      await redo(project.id, page1.id);

      // ====== 5. Undo visibility toggle (hide/show) ======
      const hide = await request(`/api/projects/${project.id}/pages/${page1.id}/components/${cmp.id}`, {
        method: 'PATCH',
        body: JSON.stringify({ hidden: true }),
      });
      expect([200, 204]).toContain(hide.res.status);

      const undoHide = await undo(project.id, page1.id);
      expect([200, 204]).toContain(undoHide.res.status);

      page1State = await getPage(project.id, page1.id);
      const cmpAfterUndoHide = (page1State.components || []).find((c) => c.id === cmp.id);
      const isVisible = cmpAfterUndoHide.hidden === false || cmpAfterUndoHide.hidden === undefined;
      expect(isVisible, 'undo hide should restore component visibility').toBe(true);

      // Redo hide and keep it
      await redo(project.id, page1.id);
      // Unhide for subsequent tests
      await request(`/api/projects/${project.id}/pages/${page1.id}/components/${cmp.id}`, {
        method: 'PATCH',
        body: JSON.stringify({ hidden: false }),
      });

      // ====== 6. Undo layer order change ======
      const cmp2 = await createComponent(project.id, page1.id, {
        name: 'LayerTest', type: 'button', x: 50, y: 50, width: 80, height: 30, text: 'btn',
      });

      const reorder = await request(`/api/projects/${project.id}/pages/${page1.id}/components/${cmp2.id}/reorder`, {
        method: 'POST',
        body: JSON.stringify({ direction: 'up' }),
      });
      // reorder might use PATCH or POST depending on API; accept common codes
      expect([200, 204]).toContain(reorder.res.status);

      const undoReorder = await undo(project.id, page1.id);
      expect([200, 204]).toContain(undoReorder.res.status);
      // We just verify the undo didn't fail; layer order verification is implicit

      // ====== 7. Undo delete ======
      const deleteCmp2 = await request(`/api/projects/${project.id}/pages/${page1.id}/components/${cmp2.id}`, {
        method: 'DELETE',
      });
      expect([200, 204]).toContain(deleteCmp2.res.status);

      const undoDelete = await undo(project.id, page1.id);
      expect([200, 204]).toContain(undoDelete.res.status);

      page1State = await getPage(project.id, page1.id);
      const cmp2AfterUndoDelete = (page1State.components || []).find((c) => c.id === cmp2.id);
      expect(cmp2AfterUndoDelete, 'undo delete should restore the deleted component').toBeTruthy();

      // ====== 8. Cross-canvas isolation ======
      const page2State = await getPage(project.id, page2.id);
      expect((page2State.components || []).length, 'page2 should be unaffected by page1 undo/redo operations').toBe(0);

      // ====== 9. Undo then new change clears redo chain ======
      const undoAgain = await undo(project.id, page1.id);
      expect([200, 204]).toContain(undoAgain.res.status);

      // Make a new change which should clear the redo chain
      const newChange = await request(`/api/projects/${project.id}/pages/${page1.id}/components/${cmp.id}`, {
        method: 'PATCH',
        body: JSON.stringify({ text: 'after-new-change' }),
      });
      expect([200, 204]).toContain(newChange.res.status);

      // Redo should now be unavailable or have no effect
      const redoAfterNewChange = await redo(project.id, page1.id);
      expect([400, 409, 422, 204, 200]).toContain(redoAfterNewChange.res.status);

      const finalPage1 = await getPage(project.id, page1.id);
      const finalCmp = (finalPage1.components || []).find((c) => c.id === cmp.id);
      expect(finalCmp.text, 'new change after undo should persist and redo chain should be cleared').toBe('after-new-change');

      // ====== 10. History limit: excessive operations should drop oldest ======
      // Perform many operations to exceed likely history limit (e.g., 50+)
      for (let i = 0; i < 55; i++) {
        const patchRes = await request(`/api/projects/${project.id}/pages/${page1.id}/components/${cmp.id}`, {
          method: 'PATCH',
          body: JSON.stringify({ x: 200 + i }),
        });
        expect([200, 204]).toContain(patchRes.res.status);
      }

      // Try to undo all the way back - at some point, oldest operations should be gone
      let undoCount = 0;
      for (let i = 0; i < 60; i++) {
        const u = await undo(project.id, page1.id);
        if ([400, 409, 422].includes(u.res.status)) {
          break; // no more history
        }
        undoCount++;
      }
      // undoCount should be less than total operations (55 + prior ones), proving limit exists
      // At minimum, recent operations should be undoable
      expect(undoCount, 'should be able to undo at least some recent operations').toBeGreaterThan(0);
    } finally {
      await tryDeleteProject(project.id);
    }
  });
});

