describe('default_canvas_initialization_persists', () => {
  it('should persist default-canvas initialization state after refresh/reload', async () => {
    const projectName = `verifier-default-canvas-${Date.now()}-${Math.random().toString(36).slice(2)}`;
    let projectId;

    try {
      // Create a project which should auto-initialize with a default canvas/page
      const createRes = await request('POST', '/api/projects', { name: projectName });
      expect([200, 201]).toContain(createRes.res.status);
      projectId = createRes.data?.id || createRes.data?.projectId;
      expect(projectId, `Expected project id in response, got: ${JSON.stringify(createRes.data)}`).toBeTruthy();

      // First read: verify default canvas/page exists
      const firstRead = await request('GET', `/api/projects/${projectId}`);
      expect(firstRead.res.status).toBe(200);

      const pages1 = firstRead.data?.pages || firstRead.data?.canvases || [];
      expect(Array.isArray(pages1), 'project should contain a pages/canvases array').toBe(true);
      expect(pages1.length, 'Expected at least one default canvas/page after creation').toBeGreaterThanOrEqual(1);

      const defaultPage = pages1[0];
      expect(defaultPage.id, 'default page should have an id').toBeTruthy();
      expect(defaultPage.name || defaultPage.title, 'default page should have a name').toBeTruthy();

      // Second read (simulating page refresh): verify same state persists
      const secondRead = await request('GET', `/api/projects/${projectId}`);
      expect(secondRead.res.status).toBe(200);

      const pages2 = secondRead.data?.pages || secondRead.data?.canvases || [];
      expect(pages2.length, 'Expected default canvas to persist after refresh').toBeGreaterThanOrEqual(1);
      expect(pages2[0]?.id, 'default page id should be the same after refresh').toBe(defaultPage.id);

      // ---- Boundary: verify pages endpoint also shows the default page ----
      const pagesEndpoint = await request('GET', `/api/projects/${projectId}/pages`);
      if (pagesEndpoint.res.status === 200) {
        const pagesList = Array.isArray(pagesEndpoint.data) ? pagesEndpoint.data : (pagesEndpoint.data?.pages || []);
        expect(pagesList.length, 'pages list endpoint should also show default page').toBeGreaterThanOrEqual(1);
      }

      // ---- Boundary: delete the default page, then verify deletion attempt ----
      // Per requirement: at least 1 page must remain, so deleting the last one should fail
      const deleteLast = await request('DELETE', `/api/projects/${projectId}/pages/${defaultPage.id}`);
      // If only one page exists, deletion should be rejected
      if (pages1.length === 1) {
        expect(
          deleteLast.res.status >= 400 && deleteLast.res.status < 500,
          `deleting the last remaining page should be rejected, got status ${deleteLast.res.status}`
        ).toBe(true);

        // After failed deletion, page should still exist
        const afterFailedDelete = await request('GET', `/api/projects/${projectId}`);
        expect(afterFailedDelete.res.status).toBe(200);
        const pagesAfter = afterFailedDelete.data?.pages || afterFailedDelete.data?.canvases || [];
        expect(pagesAfter.length).toBeGreaterThanOrEqual(1);
      }

    } finally {
      if (projectId) {
        await request('DELETE', `/api/projects/${projectId}`).catch(() => {});
      }
    }
  });
});

import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function request(method: string, path: string, body?: any) {
  const res = await fetch(`${BASE_URL}${path}`, {
    method,
    headers: { 'Content-Type': 'application/json' },
    body: body === undefined ? undefined : JSON.stringify(body),
  });
  const text = await res.text();
  let data: any = null;
  try { data = text ? JSON.parse(text) : null; } catch { data = text; }
  return { res, data };
}

async function tryEndpoints(method: string, paths: string[], body?: any) {
  for (const path of paths) {
    const resp = await request(method, path, body);
    if (resp.res.status !== 404) return { ...resp, usedPath: path };
  }
  const resp = await request(method, paths[paths.length - 1], body);
  return { ...resp, usedPath: paths[paths.length - 1] };
}

