describe('bulk_text_replace_reports_counts_and_skips_deleted_matches', () => {
  it('should preview and replace text matches, skipping deleted components, not touching non-text fields, handle edge cases, and support undo', async () => {
    const suffix = `${Date.now()}_${Math.random().toString(36).slice(2, 8)}`;
    const project = await request('POST', '/api/projects', { name: `bulk-replace-${suffix}` });
    expect([200, 201]).toContain(project.res.status);
    const projectId = project.data?.id ?? project.data?.projectId;
    expect(projectId).toBeTruthy();

    try {
      const page1 = await request('POST', `/api/projects/${projectId}/pages`, { name: 'P1' });
      expect([200, 201]).toContain(page1.res.status);
      const page1Id = page1.data?.id ?? page1.data?.pageId;

      const page2 = await request('POST', `/api/projects/${projectId}/pages`, { name: 'P2' });
      expect([200, 201]).toContain(page2.res.status);
      const page2Id = page2.data?.id ?? page2.data?.pageId;

      const c1 = await request('POST', `/api/projects/${projectId}/pages/${page1Id}/components`, {
        name: 'NameShouldStay', type: 'text', x: 0, y: 0, width: 100, height: 20, text: 'foo target text',
      });
      expect([200, 201]).toContain(c1.res.status);
      const c1Id = c1.data?.id ?? c1.data?.componentId;

      const c2 = await request('POST', `/api/projects/${projectId}/pages/${page2Id}/components`, {
        name: 'AnotherNameShouldStay', type: 'text', x: 0, y: 0, width: 100, height: 20, text: 'foo target text 2',
      });
      expect([200, 201]).toContain(c2.res.status);
      const c2Id = c2.data?.id ?? c2.data?.componentId;

      // Create a library item with name containing 'foo' to verify it's not modified
      const libItem = await tryEndpoints('POST', [
        `/api/projects/${projectId}/library-items`,
        `/api/projects/${projectId}/library`,
      ], {
        name: `foo_lib_${suffix}`,
        sourceComponentId: c1Id,
        sourceComponentIds: [c1Id],
        pageId: page1Id,
      });
      expect([200, 201]).toContain(libItem.res.status);
      const libItemId = libItem.data?.id ?? libItem.data?.libraryItemId;

      // --- Preview: should report affected counts ---
      const preview = await tryEndpoints('POST', [
        `/api/projects/${projectId}/search-replace/preview`,
        `/api/projects/${projectId}/search/replace-preview`,
        `/api/projects/${projectId}/replace/preview`,
      ], { search: 'foo', replace: 'bar' });
      expect(preview.res.status).toBe(200);
      expect(preview.data).toBeTruthy();
      const previewMatchCount = preview.data?.matchCount ?? preview.data?.componentsAffected ?? preview.data?.totalMatches ?? preview.data?.count;
      expect(previewMatchCount, 'preview should report affected match/component count >= 2').toBeGreaterThanOrEqual(2);
      const previewPageCount = preview.data?.pageCount ?? preview.data?.pagesAffected ?? preview.data?.totalPages ?? preview.data?.pages;
      expect(previewPageCount, 'preview should report affected page count >= 2').toBeGreaterThanOrEqual(2);

      // --- Delete c2 before executing replace ---
      const del = await request('DELETE', `/api/projects/${projectId}/pages/${page2Id}/components/${c2Id}`);
      expect([200, 204]).toContain(del.res.status);

      // Determine the replace execute path based on preview path
      const replaceBasePath = (preview as any).usedPath?.replace('/preview', '/execute') 
        ?? `/api/projects/${projectId}/search-replace/execute`;

      // --- Execute replace: should skip deleted c2 ---
      const replace = await tryEndpoints('POST', [
        replaceBasePath,
        `/api/projects/${projectId}/search-replace/execute`,
        `/api/projects/${projectId}/search/replace`,
        `/api/projects/${projectId}/replace/execute`,
      ], { search: 'foo', replace: 'bar' });
      expect([200, 201]).toContain(replace.res.status);
      expect(replace.data).toBeTruthy();
      const replacedCount = replace.data?.replacedCount ?? replace.data?.updatedCount ?? replace.data?.replaced;
      expect(replacedCount, 'replace should report at least one updated item').toBeGreaterThanOrEqual(1);
      const skippedCount = replace.data?.skippedCount ?? replace.data?.deletedSkippedCount ?? replace.data?.skipped;
      expect(skippedCount, 'replace should report at least 1 skipped due to deleted component').toBeGreaterThanOrEqual(1);

      // --- Verify text was replaced and non-text fields untouched ---
      const pageAfter = await request('GET', `/api/projects/${projectId}/pages/${page1Id}`);
      expect(pageAfter.res.status).toBe(200);
      const updated = (pageAfter.data?.components || []).find((c: any) => c.id === c1Id);
      expect(updated).toBeTruthy();
      expect(updated.text, `text field should contain 'bar' after replace`).toContain('bar');
      expect(updated.text, `text field should not contain 'foo' after replace`).not.toContain('foo');
      expect(updated.name, 'bulk text replace should not mutate component name field').toBe('NameShouldStay');

      // --- Verify library item name was NOT modified ---
      if (libItemId) {
        const libAfter = await tryEndpoints('GET', [
          `/api/projects/${projectId}/library-items/${libItemId}`,
          `/api/projects/${projectId}/library/${libItemId}`,
        ]);
        if (libAfter.res.status >= 200 && libAfter.res.status < 300) {
          const libName = libAfter.data?.name ?? libAfter.data?.title;
          expect(libName, 'Library item name containing foo should NOT be modified by text replace').toContain('foo');
        } else {
          // If individual lib item GET not supported, check via project listing
          const projAfter = await request('GET', `/api/projects/${projectId}`);
          if (projAfter.res.status >= 200 && projAfter.res.status < 300) {
            const libItems = projAfter.data?.libraryItems ?? projAfter.data?.library ?? [];
            const foundLib = libItems.find((l: any) => (l.id ?? l.libraryItemId) === libItemId);
            if (foundLib) {
              expect(foundLib.name, 'Library item name should not be modified by text replace').toContain('foo');
            }
          }
        }
      }

      // --- Test undo of replace ---
      const undo = await tryEndpoints('POST', [
        `/api/projects/${projectId}/undo`,
        `/api/projects/${projectId}/pages/${page1Id}/undo`,
        `/api/projects/${projectId}/search-replace/undo`,
      ]);
      if (undo.res.status >= 200 && undo.res.status < 300) {
        const pageAfterUndo = await request('GET', `/api/projects/${projectId}/pages/${page1Id}`);
        expect(pageAfterUndo.res.status).toBe(200);
        const undoneComp = (pageAfterUndo.data?.components || []).find((c: any) => c.id === c1Id);
        if (undoneComp) {
          expect(undoneComp.text, 'After undo, text should revert to contain foo').toContain('foo');
          expect(undoneComp.text, 'After undo, text should not contain bar').not.toContain('bar');
        }
      }

      // --- Boundary: same text replace ---
      const sameReplace = await tryEndpoints('POST', [
        replaceBasePath,
        `/api/projects/${projectId}/search-replace/execute`,
      ], { search: 'bar', replace: 'bar' });
      // Should either be rejected (4xx) or accepted as a no-op (200 with indication)
      if (sameReplace.res.status >= 400) {
        expect(sameReplace.res.status).toBeLessThan(500);
        const errorMsg = sameReplace.data?.message ?? sameReplace.data?.error;
        expect(errorMsg, 'Same-text replace rejection should include an error description').toBeTruthy();
      } else {
        // If 200, verify it indicates nothing was changed or it's treated as no-op
        expect(sameReplace.res.status).toBeGreaterThanOrEqual(200);
        expect(sameReplace.res.status).toBeLessThan(300);
      }

      // --- Boundary: empty replacement string ---
      const emptyReplace = await tryEndpoints('POST', [
        replaceBasePath,
        `/api/projects/${projectId}/search-replace/execute`,
      ], { search: 'bar', replace: '' });
      // Should either be rejected or handled
      if (emptyReplace.res.status >= 400) {
        expect(emptyReplace.res.status).toBeLessThan(500);
        const errMsg = emptyReplace.data?.message ?? emptyReplace.data?.error;
        expect(errMsg, 'Empty replace rejection should include error description').toBeTruthy();
      } else {
        expect(emptyReplace.res.status).toBeGreaterThanOrEqual(200);
        expect(emptyReplace.res.status).toBeLessThan(300);
      }

      // --- Boundary: overly long replacement string ---
      const longReplacement = 'x'.repeat(10000);
      const longReplace = await tryEndpoints('POST', [
        replaceBasePath,
        `/api/projects/${projectId}/search-replace/execute`,
      ], { search: 'target text', replace: longReplacement });
      if (longReplace.res.status >= 400) {
        expect(longReplace.res.status).toBeLessThan(500);
        const errMsg = longReplace.data?.message ?? longReplace.data?.error;
        expect(errMsg, 'Overly long replace rejection should include error description').toBeTruthy();
      } else {
        expect(longReplace.res.status).toBeGreaterThanOrEqual(200);
        expect(longReplace.res.status).toBeLessThan(300);
      }
    } finally {
      await tryDeleteProject(projectId);
    }
  });
});

