      const restoredAfterDel = comps.find((c: any) => (c.id ?? c.componentId) === comp1Id);
      expect(restoredAfterDel, 'delete undo should restore the component').toBeTruthy();

      // ====== Test 8: Page isolation - switching pages preserves independent history ======
