      const p2CompAfterUndo = p2Comps.find((c: any) => (c.id ?? c.componentId) === p2CompId);
      expect(p2CompAfterUndo, 'page 2 component should exist after undo').toBeTruthy();
      expect(p2CompAfterUndo?.text, 'page 2 text should revert to original').toBe('page2text');

      // Now go back to page 1 and verify its history is still intact
      // Page 1 should still have the component (we undid delete earlier)
      comps = await getPageComponents(projectId!, page1Id);
      const p1CompStillThere = comps.find((c: any) => (c.id ?? c.componentId) === comp1Id);
      expect(p1CompStillThere, 'page 1 component should still exist after switching to page 2 and back').toBeTruthy();

      // Page 1 undo should still be possible (its history was not affected by page 2 operations)
      // We can undo the delete-undo redo (which was a delete) on page1, but let's do a fresh modification
      const editP1Again = await request('PATCH', `/api/projects/${projectId}/pages/${page1Id}/components/${comp1Id}`, { text: 'p1_after_switch' });
      expect(editP1Again.res.status).toBeGreaterThanOrEqual(200);
      expect(editP1Again.res.status).toBeLessThan(300);

      const undoP1AfterSwitch = await request('POST', `/api/projects/${projectId}/pages/${page1Id}/undo`);
      expect(undoP1AfterSwitch.res.status).toBeGreaterThanOrEqual(200);
      expect(undoP1AfterSwitch.res.status).toBeLessThan(300);

      comps = await getPageComponents(projectId!, page1Id);
      const p1CompAfterSwitch = comps.find((c: any) => (c.id ?? c.componentId) === comp1Id);
      expect(p1CompAfterSwitch?.text, 'page 1 history should be independent; undo should work after switching back').not.toBe('p1_after_switch');

      // ====== Test 9: Undo then new edit clears redo chain ======
      // Make a new edit after undo
      const newBranch = await request('PATCH', `/api/projects/${projectId}/pages/${page1Id}/components/${comp1Id}`, { text: 'branch-edit' });
      expect(newBranch.res.status).toBeGreaterThanOrEqual(200);
      expect(newBranch.res.status).toBeLessThan(300);

      // Redo should fail or be no-op since redo chain was cleared
      const redoShouldFail = await request('POST', `/api/projects/${projectId}/pages/${page1Id}/redo`);
      expect([200, 204, 400, 409, 422]).toContain(redoShouldFail.res.status);

      comps = await getPageComponents(projectId!, page1Id);
      const finalComp = comps.find((c: any) => (c.id ?? c.componentId) === comp1Id);
      expect(finalComp?.text).toBe('branch-edit');

      // ====== Test 10: History bounding ======
      // Perform many edits
      for (let i = 0; i < 25; i++) {
        const edit = await request('PATCH', `/api/projects/${projectId}/pages/${page1Id}/components/${comp1Id}`, { text: `v-${i}` });
        expect(edit.res.status).toBeGreaterThanOrEqual(200);
        expect(edit.res.status).toBeLessThan(300);
      }

      // Undo until exhausted
      let undoCount = 0;
      const maxUndoAttempts = 100;
      while (undoCount < maxUndoAttempts) {
        const u = await request('POST', `/api/projects/${projectId}/pages/${page1Id}/undo`);
        if (u.res.status >= 400 || u.res.status === 204) break;
        if (u.data?.empty || u.data?.nothingToUndo) break;
        undoCount++;
      }
      // History should be bounded
      expect(undoCount, 'history should be bounded and not allow infinite undos').toBeLessThan(maxUndoAttempts);
      expect(undoCount, 'should have been able to undo at least a few steps').toBeGreaterThan(0);

      // After exhausting undo, verify final state is the earliest reachable point (not necessarily initial state)
      comps = await getPageComponents(projectId!, page1Id);
      const bottomComp = comps.find((c: any) => (c.id ?? c.componentId) === comp1Id);
      // The component might or might not exist depending on how far back history goes
      // But if it exists, its text should be one of the history states, not undefined
      if (bottomComp) {
        expect(bottomComp.text, 'at history bottom, text should be a valid historical value').toBeDefined();
      }

    } finally {
      await tryDeleteProject(projectId);
    }
  });
});

import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function request(method, path, body) {
  const res = await fetch(`${BASE_URL}${path}`, {
    method,
    headers: { 'Content-Type': 'application/json' },
    body: body === undefined ? undefined : JSON.stringify(body),
  });
  const text = await res.text();
  let data = null;
  try { data = text ? JSON.parse(text) : null; } catch { data = text; }
  return { res, data };
}

describe('page_list_and_active_page_persist_after_refresh', () => {
  it('should persist page list and active page and enforce page-name/page-count validations', async () => {
    const workspaceKey = `verifier-pages-${Date.now()}-${Math.random().toString(36).slice(2)}`;
    const createWs = await request('POST', '/api/workspaces', { workspaceKey, initializeDefaultCanvas: true });

    expect([200, 201, 404, 405]).toContain(createWs.res.status);
    if (createWs.res.status === 404 || createWs.res.status === 405) {
      throw new Error('Backend API contract is missing for page management persistence. Expected workspace/page CRUD endpoints.');
    }

    const workspaceId = createWs.data?.id || createWs.data?.workspaceId;
    expect(workspaceId).toBeTruthy();

    const before = await request('GET', `/api/workspaces/${workspaceId}`);
    expect(before.res.status).toBe(200);
    const defaultPage = before.data?.activePage || before.data?.pages?.[0];
    expect(defaultPage, `Expected a default page, got ${JSON.stringify(before.data)}`).toBeTruthy();

    const p1 = await request('POST', `/api/workspaces/${workspaceId}/pages`, { name: 'Page A' });
    expect([200, 201]).toContain(p1.res.status);
    const pageAId = p1.data?.id || p1.data?.pageId;
    expect(pageAId).toBeTruthy();

    const p2 = await request('POST', `/api/workspaces/${workspaceId}/pages`, { name: 'Page A' });
    expect([200, 201]).toContain(p2.res.status);
    const pageBId = p2.data?.id || p2.data?.pageId;
    expect(pageBId).toBeTruthy();
    expect((p2.data?.name || '').trim(), 'Expected duplicate page name to be auto-disambiguated').not.toBe('Page A');

    const renameBlank = await request('PATCH', `/api/workspaces/${workspaceId}/pages/${pageAId}`, { name: '   ' });
    expect([400, 422]).toContain(renameBlank.res.status);

    const renameTooLong = await request('PATCH', `/api/workspaces/${workspaceId}/pages/${pageAId}`, { name: 'x'.repeat(300) });
    expect([400, 422]).toContain(renameTooLong.res.status);

    const renameOk = await request('PATCH', `/api/workspaces/${workspaceId}/pages/${pageAId}`, { name: 'Renamed A' });
    expect([200, 204]).toContain(renameOk.res.status);

    const activate = await request('POST', `/api/workspaces/${workspaceId}/pages/${pageBId}/activate`);
    expect([200, 204]).toContain(activate.res.status);

    const deleteOne = await request('DELETE', `/api/workspaces/${workspaceId}/pages/${pageAId}`);
    expect([200, 204]).toContain(deleteOne.res.status);

    const state1 = await request('GET', `/api/workspaces/${workspaceId}`);
    expect(state1.res.status).toBe(200);
    expect(Array.isArray(state1.data?.pages), `Expected pages array, got ${JSON.stringify(state1.data)}`).toBe(true);
    expect(state1.data.pages.length).toBeGreaterThanOrEqual(1);

    const remainingPageIds = state1.data.pages.map((p) => p.id);
    expect(remainingPageIds).toContain(pageBId);

    const activePageId = state1.data?.activePageId || state1.data?.activePage?.id;
    expect(activePageId, `Expected active page id after operations, got ${JSON.stringify(state1.data)}`).toBe(pageBId);

    while ((state1.data?.pages?.length || 0) > 1) {
      const deletable = state1.data.pages.find((p) => p.id !== activePageId);
      if (!deletable) break;
      await request('DELETE', `/api/workspaces/${workspaceId}/pages/${deletable.id}`);
      const next = await request('GET', `/api/workspaces/${workspaceId}`);
      state1.data = next.data;
    }

    const lastPageId = state1.data.pages[0].id;
    const deleteLast = await request('DELETE', `/api/workspaces/${workspaceId}/pages/${lastPageId}`);
    expect([400, 409, 422]).toContain(deleteLast.res.status);

    const afterRefresh = await request('GET', `/api/workspaces/${workspaceId}`);
    expect(afterRefresh.res.status).toBe(200);
    expect(Array.isArray(afterRefresh.data?.pages)).toBe(true);
    expect(afterRefresh.data.pages.length).toBe(state1.data.pages.length);
    expect(afterRefresh.data.pages.map((p) => p.id)).toEqual(state1.data.pages.map((p) => p.id));
    expect(afterRefresh.data.pages.map((p) => p.name)).toEqual(state1.data.pages.map((p) => p.name));
    expect(afterRefresh.data?.activePageId || afterRefresh.data?.activePage?.id).toBe(state1.data?.activePageId || state1.data?.activePage?.id);

    await request('DELETE', `/api/workspaces/${workspaceId}`).catch(() => {});
  });
});

import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function request(method: string, path: string, body?: any) {
  const res = await fetch(`${BASE_URL}${path}`, {
    method,
    headers: { 'Content-Type': 'application/json' },
    body: body === undefined ? undefined : JSON.stringify(body),
  });
  const text = await res.text();
  let json: any = null;
  try { json = text ? JSON.parse(text) : null; } catch { json = text; }
  return { res, body: json };
}

async function cleanupProject(projectId: string | number | undefined) {
  if (!projectId) return;
  try { await request('DELETE', `/api/projects/${projectId}`); } catch {}
}

// Helper to find a working endpoint by trying multiple paths
async function tryEndpoints(method: string, paths: string[], body?: any) {
  for (const path of paths) {
    const resp = await request(method, path, body);
    if (resp.res.status < 404) return { ...resp, usedPath: path };
    if (resp.res.status !== 404) return { ...resp, usedPath: path };
  }
  // Return last attempt
  const resp = await request(method, paths[paths.length - 1], body);
  return { ...resp, usedPath: paths[paths.length - 1] };
}

