      expect(createComp2.res.status).toBeGreaterThanOrEqual(200);
      expect(createComp2.res.status).toBeLessThan(300);
      const comp2Id = createComp2.body?.id ?? createComp2.body?.componentId;
      expect(comp2Id).toBeTruthy();

      // Verify second component properties
      const readComp2 = await request('GET', `/api/projects/${projectId}/pages/${pageId}`);
      if (readComp2.res.status >= 200 && readComp2.res.status < 300) {
        const c2 = (readComp2.body?.components || []).find((c: any) => (c.id ?? c.componentId) === comp2Id);
        if (c2) {
          if (c2.text !== undefined) expect(c2.text).toBe('Click me');
          if (c2.x !== undefined) expect(c2.x).toBe(200);
        }
      }

      // Save both components as a composite library item
      const saveCompositeLib = await tryEndpoints('POST', [
        `/api/projects/${projectId}/library`,
        `/api/projects/${projectId}/library-items`,
      ], {
        name: `CompositeLib_${suffix}`,
        sourceComponentIds: [createdCompId, comp2Id],
        pageId,
      });
      expect(saveCompositeLib.res.status).toBeGreaterThanOrEqual(200);
      expect(saveCompositeLib.res.status).toBeLessThan(300);
      const compositeLibId = saveCompositeLib.body?.id ?? saveCompositeLib.body?.libraryItemId;
      expect(compositeLibId).toBeTruthy();

      // Add composite library item instance via unified resource entry
      const addCompositeInstance = await tryEndpoints('POST', [
        `/api/projects/${projectId}/pages/${pageId}/components`,
        `/api/projects/${projectId}/pages/${pageId}/resources/create`,
        `/api/projects/${projectId}/pages/${pageId}/instances`,
      ], {
        type: 'library-instance',
        libraryItemId: compositeLibId,
        x: 100,
        y: 100,
        source: 'resource-panel',
      });
      expect(addCompositeInstance.res.status).toBeGreaterThanOrEqual(200);
      expect(addCompositeInstance.res.status).toBeLessThan(300);

      // --- Step 5: Verify legacy direct creation entries are disabled ---
      // Test that requests without resource-panel source or through legacy-specific paths are rejected
      const legacyPaths = [
        `/api/projects/${projectId}/pages/${pageId}/components/direct-create`,
        `/api/projects/${projectId}/pages/${pageId}/canvas/add-component`,
        `/api/projects/${projectId}/pages/${pageId}/quick-add`,
      ];
      for (const legacyPath of legacyPaths) {
        const legacyResp = await request('POST', legacyPath, {
          type: 'text',
          name: 'legacy_should_fail',
          text: 'fail',
          x: 0,
          y: 0,
          width: 50,
          height: 20,
        });
        expect(
          legacyResp.res.status >= 400,
          `Legacy path ${legacyPath} should be unavailable, got status=${legacyResp.res.status}`,
        ).toBe(true);
      }

      // Also test that if there is a source-based gating, requests without proper source are rejected
      const noSourceResp = await request('POST', `/api/projects/${projectId}/pages/${pageId}/components`, {
        type: 'text',
        name: 'no_source_test',
        text: 'test',
        x: 0,
        y: 0,
        width: 50,
        height: 20,
        source: 'canvas-direct',
      });
      // If the server enforces source=resource-panel, this should be rejected
      // If source is not enforced, the component endpoint IS the unified entry and this is acceptable
      // We just record this for awareness - the key verification is that legacy paths fail

      // --- Step 6: Export, then import and verify editability ---
      let exported = await request('GET', `/api/projects/${projectId}/export`);
      if (exported.res.status === 404) {
        exported = await request('POST', `/api/projects/${projectId}/export`);
      }
      expect(exported.res.status).toBeGreaterThanOrEqual(200);
      expect(exported.res.status).toBeLessThan(300);
      expect(exported.body).toBeTruthy();

      // Import as replace
      let importResp = await tryEndpoints('POST', [
        `/api/projects/${projectId}/import`,
        `/api/projects/import`,
      ], {
        mode: 'replace',
        snapshot: exported.body,
        data: exported.body,
        projectId,
      });
      expect(importResp.res.status).toBeGreaterThanOrEqual(200);
      expect(importResp.res.status).toBeLessThan(300);

      // Read back project after import
      const afterImport = await request('GET', `/api/projects/${projectId}`);
      expect(afterImport.res.status).toBeGreaterThanOrEqual(200);
      expect(afterImport.res.status).toBeLessThan(300);

      // Find the page in the imported project
      const pages = afterImport.body?.pages ?? [];
      const importedPage = pages.find((p: any) => String(p.name ?? p.title ?? '').includes(`Page_${suffix}`));
      const importedPageId = importedPage?.id ?? importedPage?.pageId ?? pageId;

      // Verify existing components can still be read (FIX: use .body not .data)
      const readImportedPage = await request('GET', `/api/projects/${projectId}/pages/${importedPageId}`);
      expect(readImportedPage.res.status).toBeGreaterThanOrEqual(200);
      expect(readImportedPage.res.status).toBeLessThan(300);
      const importedComps = readImportedPage.body?.components ?? [];
      expect(importedComps.length).toBeGreaterThan(0);

      // Verify imported components can be edited (property modification)
      if (importedComps.length > 0) {
        const firstComp = importedComps[0];
        const compId = firstComp.id ?? firstComp.componentId;
        const editResp = await request('PATCH', `/api/projects/${projectId}/pages/${importedPageId}/components/${compId}`, {
          text: 'edited_after_import',
        });
        expect(editResp.res.status).toBeGreaterThanOrEqual(200);
        expect(editResp.res.status).toBeLessThan(300);

        // Verify the edit took effect
        const readEdited = await request('GET', `/api/projects/${projectId}/pages/${importedPageId}`);
        if (readEdited.res.status >= 200 && readEdited.res.status < 300) {
          const editedComp = (readEdited.body?.components ?? []).find((c: any) => (c.id ?? c.componentId) === compId);
          if (editedComp) {
            expect(editedComp.text).toBe('edited_after_import');
          }
        }
      }

      // Verify new components can still be added via resource entry after import
      const postImportCreate = await request('POST', `/api/projects/${projectId}/pages/${importedPageId}/components`, {
        type: 'button',
        name: `PostImportBtn_${suffix}`,
        text: 'new',
        x: 300,
        y: 300,
        width: 60,
        height: 25,
        source: 'resource-panel',
      });
      expect(postImportCreate.res.status).toBeGreaterThanOrEqual(200);
      expect(postImportCreate.res.status).toBeLessThan(300);

      // Verify new component properties
      const postImportCompId = postImportCreate.body?.id ?? postImportCreate.body?.componentId;
      expect(postImportCompId).toBeTruthy();
      const readPostImport = await request('GET', `/api/projects/${projectId}/pages/${importedPageId}`);
      if (readPostImport.res.status >= 200 && readPostImport.res.status < 300) {
        const newComp = (readPostImport.body?.components ?? []).find((c: any) => (c.id ?? c.componentId) === postImportCompId);
        if (newComp) {
          expect(newComp.text).toBe('new');
          expect(newComp.x).toBe(300);
          expect(newComp.y).toBe(300);
        }
      }

    } finally {
      await cleanupProject(projectId);
    }
  });
});

import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function request(path, options = {}) {
  const res = await fetch(`${BASE_URL}${path}`, {
    headers: { 'Content-Type': 'application/json', ...(options.headers || {}) },
    ...options,
  });
  let body = null;
  const text = await res.text();
  try { body = text ? JSON.parse(text) : null; } catch { body = text; }
  return { res, body };
}

async function createProject() {
  const { res, body } = await request('/api/projects', { method: 'POST', body: JSON.stringify({ name: `library-delete-${Date.now()}` }) });
  expect(res.status).toBe(201);
  return body;
}
async function createPage(projectId, name) {
  const { res, body } = await request(`/api/projects/${projectId}/pages`, { method: 'POST', body: JSON.stringify({ name }) });
  expect(res.status).toBe(201);
  return body;
}
async function createComponent(projectId, pageId, payload) {
  const { res, body } = await request(`/api/projects/${projectId}/pages/${pageId}/components`, { method: 'POST', body: JSON.stringify(payload) });
  expect(res.status).toBe(201);
  return body;
}
async function getPage(projectId, pageId) {
  const { res, body } = await request(`/api/projects/${projectId}/pages/${pageId}`);
  expect(res.status).toBe(200);
  return body;
}
async function tryDeleteProject(projectId) { try { await request(`/api/projects/${projectId}`, { method: 'DELETE' }); } catch {} }

describe('round12_library_delete_keeps_existing_instances', () => {
  it('should keep existing canvas instances readable after library item deletion, and validate rename with name rules', async () => {
    const project = await createProject();
    try {
      const page = await createPage(project.id, 'Library page');
      const source = await createComponent(project.id, page.id, { name: 'SourceComp', type: 'text', x: 10, y: 10, width: 100, height: 20, text: 'Shared text' });

      // Create library item using sourceComponentIds (array) per round24 update supporting single and multi
      const createLibrary = await request(`/api/projects/${project.id}/library-items`, {
        method: 'POST',
        body: JSON.stringify({ name: 'LibItem1', sourceComponentIds: [source.id], pageId: page.id }),
      });
      expect([200, 201]).toContain(createLibrary.res.status);
      const lib = createLibrary.body;
      expect(lib.id).toBeTruthy();

      // Verify library item has type information for preview
      expect(lib.type || lib.componentType || lib.sourceType, 'library item should expose type info for preview').toBeTruthy();

      // ---- Rename: valid rename ----
      const renameLibrary = await request(`/api/projects/${project.id}/library-items/${lib.id}`, {
        method: 'PATCH',
        body: JSON.stringify({ name: 'LibItemRenamed' }),
      });
      expect([200, 204]).toContain(renameLibrary.res.status);

      // Verify rename reflected in library list
      const listAfterRename = await request(`/api/projects/${project.id}/library-items`);
      expect(listAfterRename.res.status).toBe(200);
      const libs = Array.isArray(listAfterRename.body) ? listAfterRename.body : (listAfterRename.body?.items || listAfterRename.body?.libraryItems || []);
      const renamedLib = libs.find((l) => l.id === lib.id);
      expect(renamedLib, 'renamed library item should appear in list').toBeTruthy();
      expect(renamedLib.name).toBe('LibItemRenamed');

      // ---- Rename boundary: empty/whitespace name should be rejected ----
      const renameEmpty = await request(`/api/projects/${project.id}/library-items/${lib.id}`, {
        method: 'PATCH',
        body: JSON.stringify({ name: '' }),
      });
      expect(renameEmpty.res.status).toBeGreaterThanOrEqual(400);
      expect(renameEmpty.res.status).toBeLessThan(500);

      const renameWhitespace = await request(`/api/projects/${project.id}/library-items/${lib.id}`, {
        method: 'PATCH',
        body: JSON.stringify({ name: '   ' }),
      });
      expect(renameWhitespace.res.status).toBeGreaterThanOrEqual(400);
      expect(renameWhitespace.res.status).toBeLessThan(500);

      // ---- Rename boundary: overly long name should be rejected ----
      const longName = 'A'.repeat(500);
      const renameLong = await request(`/api/projects/${project.id}/library-items/${lib.id}`, {
        method: 'PATCH',
        body: JSON.stringify({ name: longName }),
      });
      expect(renameLong.res.status).toBeGreaterThanOrEqual(400);
      expect(renameLong.res.status).toBeLessThan(500);

      // ---- Rename boundary: duplicate name should be rejected ----
      // Create a second library item
      const source2 = await createComponent(project.id, page.id, { name: 'SourceComp2', type: 'button', x: 50, y: 50, width: 80, height: 30, text: 'Click' });
      const createLib2 = await request(`/api/projects/${project.id}/library-items`, {
        method: 'POST',
        body: JSON.stringify({ name: 'LibItem2', sourceComponentIds: [source2.id], pageId: page.id }),
      });
      expect([200, 201]).toContain(createLib2.res.status);
      const lib2 = createLib2.body;

      // Try renaming lib2 to the same name as lib (LibItemRenamed)
      const renameDuplicate = await request(`/api/projects/${project.id}/library-items/${lib2.id}`, {
        method: 'PATCH',
        body: JSON.stringify({ name: 'LibItemRenamed' }),
      });
      expect(renameDuplicate.res.status).toBeGreaterThanOrEqual(400);
      expect(renameDuplicate.res.status).toBeLessThan(500);

      // ---- Create instance from library item ----
      const instanceRes = await request(`/api/projects/${project.id}/pages/${page.id}/components`, {
        method: 'POST',
        body: JSON.stringify({ name: 'Instance1', type: 'library-instance', libraryItemId: lib.id, x: 20, y: 30 }),
      });
      expect([200, 201]).toContain(instanceRes.res.status);
      const instance = instanceRes.body;
      expect(instance.id).toBeTruthy();

      // ---- Delete library item ----
      const deleteLibrary = await request(`/api/projects/${project.id}/library-items/${lib.id}`, { method: 'DELETE' });
      expect([200, 204]).toContain(deleteLibrary.res.status);

      // ---- Verify existing instance still exists and is readable ----
      const pageAfter = await getPage(project.id, page.id);
      const components = pageAfter.components || pageAfter.layers || [];
      const persistedInstance = components.find((c) => c.id === instance.id);
      expect(persistedInstance, 'existing instance should remain on canvas after library item deletion').toBeTruthy();
      expect(persistedInstance.text || persistedInstance.content || persistedInstance.name, 'existing instance should still be readable/displayable after library deletion').toBeTruthy();

      // ---- Verify deleted library item no longer in list ----
      const listAfterDelete = await request(`/api/projects/${project.id}/library-items`);
      expect(listAfterDelete.res.status).toBe(200);
      const libsAfterDelete = Array.isArray(listAfterDelete.body) ? listAfterDelete.body : (listAfterDelete.body?.items || listAfterDelete.body?.libraryItems || []);
      const deletedLib = libsAfterDelete.find((l) => l.id === lib.id);
      expect(deletedLib, 'deleted library item should no longer appear in resource list').toBeFalsy();
    } finally {
      await tryDeleteProject(project.id);
    }
  });
});

import { describe, it, expect, beforeAll, afterAll } from 'vitest';
import { chromium, Browser, BrowserContext, Page } from 'playwright';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

describe('multitab_local_sync_preserves_active_input', () => {
  let browser: Browser;
  let context1: BrowserContext;
  let context2: BrowserContext;
  let page1: Page;
  let page2: Page;

  beforeAll(async () => {
    browser = await chromium.launch({ headless: true });
    // Use two separate contexts that share the same origin storage
    // to simulate two tabs. For localStorage/BroadcastChannel sync,
    // we need same-origin contexts.
    context1 = await browser.newContext();
    context2 = await browser.newContext();
    page1 = await context1.newPage();
    page2 = await context2.newPage();
    await page1.goto(BASE_URL, { waitUntil: 'networkidle', timeout: 30000 });
    await page2.goto(BASE_URL, { waitUntil: 'networkidle', timeout: 30000 });
  }, 60000);

  afterAll(async () => {
    await context1?.close();
    await context2?.close();
    await browser?.close();
  });

  it('should serve the application in both tabs', async () => {
    const title1 = await page1.title();
    const title2 = await page2.title();
    expect(title1).toBeTruthy();
    expect(title2).toBeTruthy();
    // Both tabs should have rendered the app shell
    const app1 = await page1.$('#app, [data-app], .app, main, [class*="canvas"], [class*="workspace"]');
    const app2 = await page2.$('#app, [data-app], .app, main, [class*="canvas"], [class*="workspace"]');
    expect(app1 || (await page1.content()).length > 100).toBeTruthy();
    expect(app2 || (await page2.content()).length > 100).toBeTruthy();
  }, 15000);

  it('should sync page creation from tab1 to tab2 via local mechanism', async () => {
    // Find and click the new page / new canvas button in tab1
    const newPageBtn = await page1.$(
      'button:has-text("新建"), button:has-text("新增"), button:has-text("添加页面"), ' +
      'button:has-text("New"), button:has-text("+"), [class*="add-page"], [class*="new-page"], ' +
      '[data-action="add-page"], [title*="新建"], [aria-label*="新建"]'
    );
    if (newPageBtn) {
      await newPageBtn.click();
      await page1.waitForTimeout(1000);
    }

    // Get page list from tab1
    const pages1 = await page1.evaluate(() => {
      const stored = localStorage.getItem('pages') ||
                     localStorage.getItem('project') ||
                     localStorage.getItem('canvases') ||
                     localStorage.getItem('designPages') ||
                     localStorage.getItem('app-state') ||
                     localStorage.getItem('prototype-tool');
      return stored;
    });

    // Trigger sync in tab2 - simulate storage event or BroadcastChannel
    // by dispatching a storage event or waiting for auto-sync
    await page2.evaluate((storedData) => {
      // Simulate receiving a storage event (as if another tab wrote)
      if (storedData) {
        // Try to trigger the app's sync mechanism
        window.dispatchEvent(new StorageEvent('storage', {
          key: null,
          newValue: null,
          storageArea: localStorage
        }));
      }
    }, pages1);

    // Wait for potential sync (up to 10 seconds as per requirement)
    await page2.waitForTimeout(3000);

    // Reload tab2 to pick up localStorage changes (fallback sync)
    // since BroadcastChannel doesn't work across browser contexts
    await page2.reload({ waitUntil: 'networkidle', timeout: 15000 });
    await page2.waitForTimeout(2000);

    // Verify tab2 can see the same data
    const pages2 = await page2.evaluate(() => {
      const keys = Object.keys(localStorage);
      return { keys, count: keys.length };
    });

    // At minimum, localStorage should have project data
    expect(pages2.count).toBeGreaterThanOrEqual(0);
    // The app should still be functional after reload
    const content2 = await page2.content();
    expect(content2.length).toBeGreaterThan(100);
  }, 30000);

  it('should not clear active input when external sync occurs', async () => {
    // Find any text input in tab2 and start typing
    const inputSelector = 'input[type="text"], input:not([type]), textarea, [contenteditable="true"]';
    const input = await page2.$(inputSelector);

    if (input) {
      await input.click();
      const testText = 'user-is-typing-now';
      await input.fill(testText);

      // Now simulate an external sync event while user is typing
      await page2.evaluate(() => {
        // Simulate storage event from another tab
        const event = new StorageEvent('storage', {
          key: 'project',
          newValue: JSON.stringify({ _syncTest: true, timestamp: Date.now() }),
          oldValue: null,
          storageArea: localStorage,
          url: window.location.href
        });
        window.dispatchEvent(event);

        // Also try BroadcastChannel
        try {
          const bc = new BroadcastChannel('app-sync');
          bc.postMessage({ type: 'external-update', data: { _syncTest: true } });
          bc.close();
        } catch (e) { /* BroadcastChannel may not be the channel name used */ }
      });

      await page2.waitForTimeout(1000);

      // Verify the input still has the user's text
      const currentValue = await input.inputValue().catch(() => input.textContent());
      // The user's uncommitted input should be preserved
      if (currentValue !== null && currentValue !== undefined) {
        expect(currentValue).toContain(testText);
      }
    } else {
      // If no input is visible, verify the page is at least stable
      const content = await page2.content();
      expect(content.length).toBeGreaterThan(100);
    }
  }, 15000);

  it('should handle sync failure gracefully without losing local data', async () => {
    // Store something locally in tab1
    await page1.evaluate(() => {
      localStorage.setItem('_test_local_modification', JSON.stringify({
        modified: true,
        timestamp: Date.now()
      }));
    });

    // Simulate a sync failure scenario
    const errorMessages = await page1.evaluate(() => {
      const errors: string[] = [];
      // Override console.error temporarily to catch sync failure messages
      const origError = console.error;
      console.error = (...args: any[]) => {
        errors.push(args.map(String).join(' '));
        origError.apply(console, args);
      };

      // Simulate a corrupted sync message
      try {
        const bc = new BroadcastChannel('app-sync');
        bc.postMessage({ type: 'sync-update', data: null, corrupted: true });
        bc.close();
      } catch (e) { /* channel may not exist */ }

      window.dispatchEvent(new StorageEvent('storage', {
        key: 'project',
        newValue: 'INVALID_JSON{{{',
        oldValue: null,
        storageArea: localStorage,
        url: window.location.href
      }));

      console.error = origError;
      return errors;
    });

    await page1.waitForTimeout(1000);

    // Verify local data is preserved despite sync issues
    const localData = await page1.evaluate(() => {
      return localStorage.getItem('_test_local_modification');
    });
    expect(localData).toBeTruthy();
    const parsed = JSON.parse(localData!);
    expect(parsed.modified).toBe(true);

    // Clean up
    await page1.evaluate(() => {
      localStorage.removeItem('_test_local_modification');
    });
  }, 15000);

  it('should provide observable conflict handling for concurrent modifications', async () => {
    // Both tabs modify localStorage almost simultaneously
    const [result1, result2] = await Promise.all([
      page1.evaluate(() => {
        const data = { source: 'tab1', value: 'tab1-edit', timestamp: Date.now() };
        localStorage.setItem('_conflict_test', JSON.stringify(data));
        return data;
      }),
      page2.evaluate(() => {
        const data = { source: 'tab2', value: 'tab2-edit', timestamp: Date.now() };
        localStorage.setItem('_conflict_test', JSON.stringify(data));
        return data;
      })
    ]);

    await page1.waitForTimeout(1000);

    // One of the writes should win (last-write-wins is acceptable)
    const finalValue = await page1.evaluate(() => {
      return localStorage.getItem('_conflict_test');
    });
    expect(finalValue).toBeTruthy();
    const parsed = JSON.parse(finalValue!);
    // The result should be from one of the two tabs, not corrupted
    expect(['tab1', 'tab2']).toContain(parsed.source);
    expect(['tab1-edit', 'tab2-edit']).toContain(parsed.value);

    // Clean up
    await page1.evaluate(() => {
      localStorage.removeItem('_conflict_test');
    });
    await page2.evaluate(() => {
      localStorage.removeItem('_conflict_test');
    });
  }, 15000);
});

import { describe, it, expect, beforeAll, afterAll } from 'vitest';
