import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

function uid(prefix = 'test') {
  return `${prefix}-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
}

async function api(method, path, body) {
  const res = await fetch(`${BASE_URL}${path}`, {
    method,
    headers: { 'Content-Type': 'application/json' },
    body: body === undefined ? undefined : JSON.stringify(body),
  });
  const text = await res.text();
  let json;
  try { json = text ? JSON.parse(text) : null; } catch { json = text; }
  return { res, body: json, text };
}

async function tryApi(method, paths, body) {
  for (const path of paths) {
    const result = await api(method, path, body);
    if (result.res.status !== 404) return result;
  }
  return api(method, paths[0], body);
}

function getId(obj) {
  return obj?.id || obj?.data?.id;
}

async function cleanup(path) {
  try { await api('DELETE', path); } catch {}
}

function sitemapContains(body, needle) {
  const text = typeof body === 'string' ? body : JSON.stringify(body);
  const encoded = encodeURIComponent(needle);
  const slugified = needle.toLowerCase().replace(/\s+/g, '-');
  return text.includes(needle) || text.includes(encoded) || text.includes(slugified);
}

describe('sitemap_updates_after_category_tag_rename', () => {
  it('should update sitemap and public links after category/tag rename and remove empty category/tag pages from sitemap', async () => {
    const suffix = uid('sitemap');
    const oldCatName = `CatOld-${suffix}`;
    const newCatName = `CatNew-${suffix}`;
    const oldTagName = `TagOld-${suffix}`;
    const newTagName = `TagNew-${suffix}`;
    let categoryId, tagId, articleId, draftArticleId, incompletePubId;

    try {
      // Create category
      const catRes = await api('POST', '/api/categories', { name: oldCatName });
      expect(catRes.res.status).toBeGreaterThanOrEqual(200);
      expect(catRes.res.status).toBeLessThan(300);
      categoryId = getId(catRes.body);

      // Create tag
      const tagRes = await api('POST', '/api/tags', { name: oldTagName });
      expect(tagRes.res.status).toBeGreaterThanOrEqual(200);
      expect(tagRes.res.status).toBeLessThan(300);
      tagId = getId(tagRes.body);

      // Create a fully qualified published article
      const artRes = await api('POST', '/api/articles', {
        title: `Article ${suffix}`,
        content: 'body content here for sitemap test',
        summary: 'a summary',
        status: 'published',
        publishTime: '2024-04-01T10:00:00.000Z',
        publishedAt: '2024-04-01T10:00:00.000Z',
        primaryCategoryId: categoryId,
        categoryIds: [categoryId],
        tags: [oldTagName],
        tagIds: tagId ? [tagId] : undefined,
      });
      expect(artRes.res.status).toBeGreaterThanOrEqual(200);
      expect(artRes.res.status).toBeLessThan(300);
      articleId = getId(artRes.body);

      // --- Boundary: article missing publishTime should NOT appear in sitemap (public condition) ---
      const incompleteRes = await api('POST', '/api/articles', {
        title: `Incomplete ${suffix}`,
        content: 'has content',
        status: 'published',
        // No publishTime!
        primaryCategoryId: categoryId,
        categoryIds: [categoryId],
      });
      if ([200, 201].includes(incompleteRes.res.status)) {
        incompletePubId = getId(incompleteRes.body);
      }

      // === Verify sitemap contains old category and tag ===
      const beforeSitemap = await tryApi('GET', [
        '/api/seo/sitemap-preview',
        '/api/sitemap-preview',
        '/api/sitemap',
      ]);
      expect(beforeSitemap.res.status, 'sitemap fetch failed').toBe(200);
      expect(sitemapContains(beforeSitemap.body, oldCatName),
        `expected old category '${oldCatName}' in sitemap before rename`).toBe(true);
      expect(sitemapContains(beforeSitemap.body, oldTagName),
        `expected old tag '${oldTagName}' in sitemap before rename`).toBe(true);

      // Check public links preview
      const linksRes = await tryApi('GET', [
        '/api/seo/public-link-preview',
        '/api/seo/public-links',
        '/api/seo/links',
      ]);
      expect(linksRes.res.status, `public links preview fetch failed`).toBe(200);
      expect(sitemapContains(linksRes.body, oldCatName),
        'expected old category in public links before rename').toBe(true);

      // === Rename category ===
      let renameCatRes = await api('PUT', `/api/categories/${categoryId}`, { name: newCatName });
      if (renameCatRes.res.status >= 400) {
        renameCatRes = await api('PATCH', `/api/categories/${categoryId}`, { name: newCatName });
      }
      expect(renameCatRes.res.status).toBeGreaterThanOrEqual(200);
      expect(renameCatRes.res.status).toBeLessThan(300);

      // === Rename tag ===
      let renameTagRes = await api('PUT', `/api/tags/${tagId}`, { name: newTagName });
      if (renameTagRes.res.status >= 400) {
        renameTagRes = await api('PATCH', `/api/tags/${tagId}`, { name: newTagName });
      }
      expect(renameTagRes.res.status).toBeGreaterThanOrEqual(200);
      expect(renameTagRes.res.status).toBeLessThan(300);

      // === Verify sitemap reflects renamed category and tag ===
      const afterRenameSitemap = await tryApi('GET', [
        '/api/seo/sitemap-preview',
        '/api/sitemap-preview',
        '/api/sitemap',
      ]);
      expect(afterRenameSitemap.res.status).toBe(200);
      expect(sitemapContains(afterRenameSitemap.body, newCatName),
        `expected renamed category '${newCatName}' in sitemap`).toBe(true);
      expect(sitemapContains(afterRenameSitemap.body, newTagName),
        `expected renamed tag '${newTagName}' in sitemap`).toBe(true);
      // Old names should be gone
      expect(sitemapContains(afterRenameSitemap.body, oldCatName),
        `old category name should disappear from sitemap after rename`).toBe(false);
      expect(sitemapContains(afterRenameSitemap.body, oldTagName),
        `old tag name should disappear from sitemap after rename`).toBe(false);

      // Verify public links also updated
      const linksAfterRes = await tryApi('GET', [
        '/api/seo/public-link-preview',
        '/api/seo/public-links',
        '/api/seo/links',
      ]);
      expect(linksAfterRes.res.status).toBe(200);
      expect(sitemapContains(linksAfterRes.body, newCatName),
        'expected renamed category in public links').toBe(true);
      expect(sitemapContains(linksAfterRes.body, oldCatName),
        'old category name should not appear in public links after rename').toBe(false);

      // === Move article to trash (soft delete) so category/tag have no public articles ===
      let trashed = false;
      const trashEndpoints = [
        { method: 'POST', path: `/api/articles/${articleId}/trash` },
        { method: 'PUT', path: `/api/articles/${articleId}/trash` },
        { method: 'PATCH', path: `/api/articles/${articleId}`, body: { status: 'trashed' } },
        { method: 'PATCH', path: `/api/articles/${articleId}`, body: { isInTrash: true } },
        { method: 'DELETE', path: `/api/articles/${articleId}` },
      ];
      for (const ep of trashEndpoints) {
        const r = await api(ep.method, ep.path, ep.body);
        if (r.res.status >= 200 && r.res.status < 300) { trashed = true; break; }
      }
      expect(trashed, 'should be able to soft-delete the article').toBe(true);

      // === Verify empty category/tag pages are removed from sitemap ===
      const afterRemovalSitemap = await tryApi('GET', [
        '/api/seo/sitemap-preview',
        '/api/sitemap-preview',
        '/api/sitemap',
      ]);
      expect(afterRemovalSitemap.res.status).toBe(200);
      expect(sitemapContains(afterRemovalSitemap.body, newCatName),
        `empty category page '${newCatName}' should not remain in sitemap`).toBe(false);
      expect(sitemapContains(afterRemovalSitemap.body, newTagName),
        `empty tag page '${newTagName}' should not remain in sitemap`).toBe(false);

      // === Additional boundary: draft article should not make category/tag appear in sitemap ===
      const draftRes = await api('POST', '/api/articles', {
        title: `Draft-sitemap ${suffix}`,
        content: 'body',
        status: 'draft',
        primaryCategoryId: categoryId,
        categoryIds: [categoryId],
        tags: [newTagName],
        tagIds: tagId ? [tagId] : undefined,
      });
      if ([200, 201].includes(draftRes.res.status)) {
        draftArticleId = getId(draftRes.body);
      }

      const afterDraftSitemap = await tryApi('GET', [
        '/api/seo/sitemap-preview',
        '/api/sitemap-preview',
        '/api/sitemap',
      ]);
      expect(afterDraftSitemap.res.status).toBe(200);
      expect(sitemapContains(afterDraftSitemap.body, newCatName),
        'category with only draft article should not be in sitemap').toBe(false);
      expect(sitemapContains(afterDraftSitemap.body, newTagName),
        'tag with only draft article should not be in sitemap').toBe(false);

    } finally {
      if (articleId) {
        await cleanup(`/api/articles/${articleId}/permanent`);
        await cleanup(`/api/articles/${articleId}`);
      }
      if (draftArticleId) await cleanup(`/api/articles/${draftArticleId}`);
      if (incompletePubId) await cleanup(`/api/articles/${incompletePubId}`);
      if (tagId) await cleanup(`/api/tags/${tagId}`);
      if (categoryId) await cleanup(`/api/categories/${categoryId}`);
    }
  });
});

import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

function uid(prefix = 'test') {
  return `${prefix}-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
}

async function api(path, options = {}) {
  const res = await fetch(`${BASE_URL}${path}`, {
    headers: { 'Content-Type': 'application/json', ...(options.headers || {}) },
    ...options,
  });
  const text = await res.text();
  let body;
  try { body = text ? JSON.parse(text) : null; } catch { body = text; }
  return { res, body };
}

function unwrap(body) {
  return body?.data ?? body;
}

function getId(a) {
  const v = unwrap(a);
  return v?.id;
}

function getItems(body) {
  const data = unwrap(body);
  if (Array.isArray(data)) return data;
  return data?.items || data?.articles || data?.data || [];
}

function getCategoryId(category) {
  return unwrap(category)?.id;
}

async function createCategory(name) {
  const { res, body } = await api('/api/categories', {
    method: 'POST',
    body: JSON.stringify({ name }),
  });
  expect(res.status, `create category failed: ${JSON.stringify(body)}`).toBeGreaterThanOrEqual(200);
  expect(res.status).toBeLessThan(300);
  const id = getCategoryId(body);
  expect(id, `created category should have id: ${JSON.stringify(body)}`).toBeTruthy();
  return body;
}

async function createArticle(payload) {
  const { res, body } = await api('/api/articles', { method: 'POST', body: JSON.stringify(payload) });
  expect(res.status, `create article failed: ${JSON.stringify(body)}`).toBeGreaterThanOrEqual(200);
  expect(res.status).toBeLessThan(300);
  const article = unwrap(body);
  expect(article?.id, `created article should have id: ${JSON.stringify(body)}`).toBeTruthy();
  expect(article?.title, `created article should have title: ${JSON.stringify(body)}`).toBe(payload.title);
  expect(article?.status, `created article should have status: ${JSON.stringify(body)}`).toBe(payload.status);
  return body;
}

async function cleanupArticle(id) {
  try {
    if (!id) return;
    await api(`/api/articles/${id}`, { method: 'DELETE' });
    await api(`/api/articles/${id}/permanent`, { method: 'DELETE' });
    await api(`/api/articles/${id}?permanent=true`, { method: 'DELETE' });
  } catch {}
}

async function cleanupCategory(id) { try { if (id) await api(`/api/categories/${id}`, { method: 'DELETE' }); } catch {} }

async function moveToTrash(id) {
  const r1 = await api(`/api/articles/${id}/trash`, { method: 'POST' });
  if (r1.res.status >= 200 && r1.res.status < 300) return r1;
  const r2 = await api(`/api/articles/${id}`, {
    method: 'PATCH',
    body: JSON.stringify({ isInTrash: true }),
  });
  expect(r2.res.status, `move to trash failed for ${id}: ${JSON.stringify(r2.body)}`).toBeGreaterThanOrEqual(200);
  expect(r2.res.status).toBeLessThan(300);
  return r2;
}

async function restoreFromTrash(id) {
  const r1 = await api(`/api/articles/${id}/restore`, { method: 'POST' });
  if (r1.res.status >= 200 && r1.res.status < 300) return r1;
  const r2 = await api(`/api/articles/${id}`, {
    method: 'PATCH',
    body: JSON.stringify({ isInTrash: false }),
  });
  expect(r2.res.status, `restore failed for ${id}: ${JSON.stringify(r2.body)}`).toBeGreaterThanOrEqual(200);
  expect(r2.res.status).toBeLessThan(300);
  return r2;
}

async function permanentDelete(id) {
  const r1 = await api(`/api/articles/${id}/permanent`, { method: 'DELETE' });
  if (r1.res.status >= 200 && r1.res.status < 300) return r1;
  const r2 = await api(`/api/articles/${id}?permanent=true`, { method: 'DELETE' });
  expect(r2.res.status, `permanent delete failed for ${id}: ${JSON.stringify(r2.body)}`).toBeGreaterThanOrEqual(200);
  expect(r2.res.status).toBeLessThan(300);
  return r2;
}

async function getTrashList(search = '') {
  const q = search ? `?search=${encodeURIComponent(search)}` : '';
  const r1 = await api(`/api/articles/trash${q}`);
  if (r1.res.status === 200) return r1;
  const r2 = await api(`/api/articles?inTrash=true${search ? `&search=${encodeURIComponent(search)}` : ''}`);
  expect(r2.res.status, `trash list failed: ${JSON.stringify(r2.body)}`).toBe(200);
  return r2;
}

describe('trash_contains_only_soft_deleted_articles', () => {
  it('should show only soft deleted articles in trash, support title search/restore/permanent delete, and prevent permanently deleted article from remaining reachable in detail and adjacent navigation', async () => {
    const suffix = uid('trash');
    let categoryId;
    let softDeletedId, activePublishedId, activeDraftId, activeArchivedId, neighborBeforeId, neighborAfterId;

    try {
      const category = await createCategory(`Trash Cat ${suffix}`);
      categoryId = getCategoryId(category);

      const basePublished = {
        content: 'body content for trash test',
        summary: 'summary',
        status: 'published',
        publishedAt: '2024-06-01T10:00:00.000Z',
        primaryCategoryId: categoryId,
        categoryId: categoryId,
        editorMode: 'markdown',
      };

      const neighborBefore = await createArticle({
        title: `Neighbor before ${suffix}`,
        ...basePublished,
        publishedAt: '2024-06-01T09:00:00.000Z',
      });
      neighborBeforeId = getId(neighborBefore);

      const softDeleted = await createArticle({
        title: `Trash target ${suffix}`,
        ...basePublished,
        publishedAt: '2024-06-01T10:00:00.000Z',
      });
      softDeletedId = getId(softDeleted);

      const neighborAfter = await createArticle({
        title: `Neighbor after ${suffix}`,
        ...basePublished,
        publishedAt: '2024-06-01T11:00:00.000Z',
      });
      neighborAfterId = getId(neighborAfter);

      const activePublished = await createArticle({
        title: `Active published ${suffix}`,
        ...basePublished,
        publishedAt: '2024-06-02T10:00:00.000Z',
      });
      activePublishedId = getId(activePublished);

      const activeDraft = await createArticle({
        title: `Active draft ${suffix}`,
        content: 'draft body',
        summary: 'draft summary',
        status: 'draft',
        primaryCategoryId: categoryId,
        categoryId: categoryId,
        editorMode: 'markdown',
      });
      activeDraftId = getId(activeDraft);

      const activeArchived = await createArticle({
        title: `Active archived ${suffix}`,
        content: 'archived body',
        summary: 'archived summary',
        status: 'archived',
        publishedAt: '2024-06-01T10:00:00.000Z',
        primaryCategoryId: categoryId,
        categoryId: categoryId,
        editorMode: 'markdown',
      });
      activeArchivedId = getId(activeArchived);

      await moveToTrash(softDeletedId);

      const fullTrashList = await getTrashList();
      expect(fullTrashList.res.status).toBe(200);
      const fullTrashItems = getItems(fullTrashList.body);
      expect(Array.isArray(fullTrashItems), `trash list items should be array: ${JSON.stringify(fullTrashList.body)}`).toBe(true);
      const fullTrashIds = fullTrashItems.map(x => x.id);
      expect(fullTrashIds, 'soft deleted article should appear in full trash list').toContain(softDeletedId);
      expect(fullTrashIds, 'active published article must not appear in full trash list').not.toContain(activePublishedId);
      expect(fullTrashIds, 'active draft article must not appear in full trash list').not.toContain(activeDraftId);
      expect(fullTrashIds, 'active archived article must not appear in full trash list').not.toContain(activeArchivedId);
      expect(fullTrashIds, 'other active published neighbor must not appear in full trash list').not.toContain(neighborBeforeId);
      expect(fullTrashIds, 'other active published neighbor must not appear in full trash list').not.toContain(neighborAfterId);

      const trashList = await getTrashList(`Trash target ${suffix}`);
      expect(trashList.res.status).toBe(200);
      const trashItems = getItems(trashList.body);
      expect(Array.isArray(trashItems), `trash list items should be array: ${JSON.stringify(trashList.body)}`).toBe(true);
      expect(trashItems.some((x) => x.id === softDeletedId), `soft deleted article should appear in trash: ${JSON.stringify(trashItems)}`).toBe(true);
      expect(trashItems.some((x) => x.id === activePublishedId), 'active published article must not appear in trash search result').toBe(false);
      expect(trashItems.some((x) => x.id === activeDraftId), 'active draft article must not appear in trash search result').toBe(false);
      expect(trashItems.some((x) => x.id === activeArchivedId), 'active archived article must not appear in trash search result').toBe(false);
      const searched = trashItems.find((x) => x.id === softDeletedId);
      expect(String(searched?.title || ''), 'trash search should match title').toContain(`Trash target ${suffix}`);

      await restoreFromTrash(softDeletedId);

      const trashAfterRestore = await getTrashList(suffix);
      expect(trashAfterRestore.res.status).toBe(200);
      const itemsAfterRestore = getItems(trashAfterRestore.body);
      expect(itemsAfterRestore.some((x) => x.id === softDeletedId), `restored article should disappear from trash: ${JSON.stringify(itemsAfterRestore)}`).toBe(false);

      const restoredDetail = await api(`/api/articles/${softDeletedId}`);
      expect(restoredDetail.res.status).toBe(200);
      const restoredArticle = unwrap(restoredDetail.body);
      expect(restoredArticle.status, `restored article should retain original status: ${JSON.stringify(restoredArticle)}`).toBe('published');
      expect(restoredArticle.title).toBe(`Trash target ${suffix}`);

      await moveToTrash(softDeletedId);
      const permanent = await permanentDelete(softDeletedId);
      expect(permanent.res.status).toBeGreaterThanOrEqual(200);
      expect(permanent.res.status).toBeLessThan(300);

      const detail = await api(`/api/articles/${softDeletedId}`);
      expect([404, 410]).toContain(detail.res.status);

      const trashAfterPermanent = await getTrashList(`Trash target ${suffix}`);
      expect(trashAfterPermanent.res.status).toBe(200);
      const itemsAfterPermanent = getItems(trashAfterPermanent.body);
      const ourTrashItems = itemsAfterPermanent.filter((x) => String(x.title || '').includes(suffix));
      expect(ourTrashItems.length, `no test articles should remain in trash after permanent deletion: ${JSON.stringify(itemsAfterPermanent)}`).toBe(0);

      const adjacentFromBefore = await api(`/api/articles/${neighborBeforeId}/adjacent`);
      if (adjacentFromBefore.res.status === 200) {
        const adjacentText = JSON.stringify(adjacentFromBefore.body);
        expect(adjacentText.includes(String(softDeletedId)), 'adjacent navigation from previous article must not point to permanently deleted article').toBe(false);
      } else {
        expect([404, 405]).toContain(adjacentFromBefore.res.status);
      }

      const adjacentFromAfter = await api(`/api/articles/${neighborAfterId}/adjacent`);
      if (adjacentFromAfter.res.status === 200) {
        const adjacentText = JSON.stringify(adjacentFromAfter.body);
        expect(adjacentText.includes(String(softDeletedId)), 'adjacent navigation from next article must not point to permanently deleted article').toBe(false);
      } else {
        expect([404, 405]).toContain(adjacentFromAfter.res.status);
      }

      softDeletedId = null;
    } finally {
      if (softDeletedId) await cleanupArticle(softDeletedId);
      if (activePublishedId) await cleanupArticle(activePublishedId);
      if (activeDraftId) await cleanupArticle(activeDraftId);
      if (activeArchivedId) await cleanupArticle(activeArchivedId);
      if (neighborBeforeId) await cleanupArticle(neighborBeforeId);
      if (neighborAfterId) await cleanupArticle(neighborAfterId);
      if (categoryId) await cleanupCategory(categoryId);
    }
  });
});

import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function request(path, options = {}) {
  return fetch(`${BASE_URL}${path}`, {
    headers: {
      'Content-Type': 'application/json',
      ...(options.headers || {}),
    },
    ...options,
  });
}

async function safeJson(res) {
  const text = await res.text();
  try {
    return text ? JSON.parse(text) : null;
  } catch {
    return { raw: text };
  }
}

async function cleanupArticle(id) {
  if (!id) return;
  try {
    await request(`/api/articles/${id}`, { method: 'DELETE' });
  } catch {}
  try {
    await request(`/api/articles/${id}?permanent=true&confirm=true`, { method: 'DELETE' });
  } catch {}
}

async function cleanupCategory(id) {
  if (!id) return;
  try {
    await request(`/api/categories/${id}`, { method: 'DELETE' });
  } catch {}
}

async function cleanupTag(id) {
  if (!id) return;
  try {
    await request(`/api/tags/${id}`, { method: 'DELETE' });
  } catch {}
}

async function ensureCategory(name) {
  const res = await request('/api/categories', {
    method: 'POST',
    body: JSON.stringify({ name }),
  });
  expect([200, 201]).toContain(res.status);
  const body = await safeJson(res);
  return body;
}

async function ensureTag(name) {
  const res = await request('/api/tags', {
    method: 'POST',
    body: JSON.stringify({ name }),
  });
  expect([200, 201]).toContain(res.status);
  const body = await safeJson(res);
  return body;
}

function extractId(obj) {
  if (!obj) return undefined;
  return obj.id || obj.data?.id;
}

function unwrap(body) {
  return body?.data ?? body;
}

function listItems(body) {
  const source = unwrap(body);
  return source?.items || source?.articles || source?.data || (Array.isArray(source) ? source : []);
}

function tagNames(tags) {
  return (tags || []).map(tag => (typeof tag === 'string' ? tag : tag.name));
}

async function deleteAllCategories() {
  try {
    const res = await request('/api/categories');
    if (res.status === 200) {
      const body = await safeJson(res);
      const items = unwrap(body);
      const cats = Array.isArray(items) ? items : (items?.items || items?.categories || []);
      for (const cat of cats) {
        const cid = cat.id || cat.data?.id;
        if (cid) {
          try { await request(`/api/categories/${cid}`, { method: 'DELETE' }); } catch {}
        }
      }
    }
  } catch {}
}

