import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function request(method, path, body) {
  const res = await fetch(`${BASE_URL}${path}`, {
    method,
    headers: { 'Content-Type': 'application/json' },
    body: body !== undefined ? JSON.stringify(body) : undefined,
  });
  const text = await res.text();
  let json;
  try {
    json = text ? JSON.parse(text) : null;
  } catch {
    json = text;
  }
  return { res, body: json };
}

function getArticle(body) {
  return body?.article || body?.data || body;
}

function getId(body) {
  return body?.id || body?.data?.id || body?.categoryId || body?.tagId;
}

describe('delete_tag_removes_article_relations', () => {
  it('should block deleting an in-use category (with usage count) and remove deleted tag from related articles', async () => {
    const suffix = `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
    let categoryId;
    let tagId;
    let articleId1;
    let articleId2;

    try {
      // Create a category
      const category = await request('POST', '/api/categories', { name: `used-category-${suffix}` });
      expect([200, 201].includes(category.res.status), `expected category create success, got ${category.res.status} ${JSON.stringify(category.body)}`).toBe(true);
      categoryId = getId(category.body);
      expect(categoryId, `expected category id, got ${JSON.stringify(category.body)}`).toBeTruthy();

      // Create a tag
      const tag = await request('POST', '/api/tags', { name: `used-tag-${suffix}` });
      expect([200, 201].includes(tag.res.status), `expected tag create success, got ${tag.res.status} ${JSON.stringify(tag.body)}`).toBe(true);
      tagId = getId(tag.body);
      expect(tagId, `expected tag id, got ${JSON.stringify(tag.body)}`).toBeTruthy();

      // Create first article using both category and tag
      const article1 = await request('POST', '/api/articles', {
        title: `article-with-relations-1-${suffix}`,
        content: 'content for article 1',
        status: 'draft',
        primaryCategoryId: categoryId,
        categoryIds: [categoryId],
        tagIds: [tagId],
      });
      expect([200, 201].includes(article1.res.status), `expected article1 create success, got ${article1.res.status} ${JSON.stringify(article1.body)}`).toBe(true);
      articleId1 = getId(article1.body);
      expect(articleId1, `expected article1 id, got ${JSON.stringify(article1.body)}`).toBeTruthy();

      // Create second article also using the same tag (to test multi-article tag removal)
      const article2 = await request('POST', '/api/articles', {
        title: `article-with-relations-2-${suffix}`,
        content: 'content for article 2',
        status: 'draft',
        primaryCategoryId: categoryId,
        categoryIds: [categoryId],
        tagIds: [tagId],
      });
      expect([200, 201].includes(article2.res.status), `expected article2 create success, got ${article2.res.status} ${JSON.stringify(article2.body)}`).toBe(true);
      articleId2 = getId(article2.body);
      expect(articleId2, `expected article2 id, got ${JSON.stringify(article2.body)}`).toBeTruthy();

      // Attempt to delete the in-use category - should be blocked
      const deleteCategory = await request('DELETE', `/api/categories/${categoryId}`);
      expect(
        [400, 409, 422].includes(deleteCategory.res.status),
        `expected deleting in-use category to be blocked, got ${deleteCategory.res.status} ${JSON.stringify(deleteCategory.body)}`
      ).toBe(true);

      // Verify the block response includes usage/article count info
      const blockBody = deleteCategory.body;
      const blockText = JSON.stringify(blockBody || {}).toLowerCase();
      const hasUsageInfo =
        blockText.includes('2') || // 2 articles using it
        blockText.includes('article') ||
        blockText.includes('count') ||
        blockText.includes('use') ||
        blockText.includes('reference') ||
        (typeof blockBody === 'object' && (blockBody.count !== undefined || blockBody.articleCount !== undefined || blockBody.usageCount !== undefined || blockBody.references !== undefined));
      expect(hasUsageInfo, `expected blocked response to mention usage count or article references, got ${JSON.stringify(blockBody)}`).toBe(true);

      // Delete the in-use tag - should succeed
      const deleteTag = await request('DELETE', `/api/tags/${tagId}`);
      expect([200, 204].includes(deleteTag.res.status), `expected deleting in-use tag to succeed, got ${deleteTag.res.status} ${JSON.stringify(deleteTag.body)}`).toBe(true);

      // Verify tag is removed from FIRST article
      const getArticle1 = await request('GET', `/api/articles/${articleId1}`);
      expect(getArticle1.res.status).toBe(200);
      const article1Data = getArticle(getArticle1.body);
      const article1Tags = article1Data?.tags || article1Data?.tagIds || [];
      const normalizedTagIds1 = Array.isArray(article1Tags)
        ? article1Tags.map((t) => (typeof t === 'object' ? t.id : t))
        : [];
      expect(
        normalizedTagIds1.includes(tagId),
        `expected deleted tag ${tagId} to be removed from article1, got ${JSON.stringify(article1Tags)}`
      ).toBe(false);

      // Verify tag is removed from SECOND article as well
      const getArticle2 = await request('GET', `/api/articles/${articleId2}`);
      expect(getArticle2.res.status).toBe(200);
      const article2Data = getArticle(getArticle2.body);
      const article2Tags = article2Data?.tags || article2Data?.tagIds || [];
      const normalizedTagIds2 = Array.isArray(article2Tags)
        ? article2Tags.map((t) => (typeof t === 'object' ? t.id : t))
        : [];
      expect(
        normalizedTagIds2.includes(tagId),
        `expected deleted tag ${tagId} to be removed from article2, got ${JSON.stringify(article2Tags)}`
      ).toBe(false);
    } finally {
      try { if (articleId1) await request('DELETE', `/api/articles/${articleId1}`); } catch {}
      try { if (articleId2) await request('DELETE', `/api/articles/${articleId2}`); } catch {}
      try { if (tagId) await request('DELETE', `/api/tags/${tagId}`); } catch {}
      try { if (categoryId) await request('DELETE', `/api/categories/${categoryId}`); } catch {}
    }
  });
});

import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function request(method, path, body) {
  const res = await fetch(`${BASE_URL}${path}`, {
    method,
    headers: { 'Content-Type': 'application/json' },
    body: body === undefined ? undefined : JSON.stringify(body),
  });
  const text = await res.text();
  let json = null;
  try { json = text ? JSON.parse(text) : null; } catch { json = text; }
  return { res, body: json, text };
}

async function tryDelete(path) {
  try { await fetch(`${BASE_URL}${path}`, { method: 'DELETE' }); } catch {}
}

function pick(obj, keys) {
  for (const key of keys) {
    if (obj && obj[key] !== undefined) return obj[key];
  }
}

function asArray(v) {
  return Array.isArray(v) ? v : Array.isArray(v?.items) ? v.items : Array.isArray(v?.data) ? v.data : [];
}

describe('round11_publish_time_and_rss_order', () => {
  it('should save metadata, block publish without publishTime, and order RSS by publishTime desc then updatedAt desc', async () => {
    const unique = `rss-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
    const createdIds = [];

    try {
      // Test: block publishing without publishTime via direct POST
      const blocked = await request('POST', '/api/articles', {
        title: `No Publish Time ${unique}`,
        content: 'content',
        authorName: `Author ${unique}`,
        coverImageUrl: `https://img.example.com/${unique}.jpg`,
        status: 'published',
      });
      expect([400, 422]).toContain(blocked.res.status);
      const blockedMsg = JSON.stringify(blocked.body || blocked.text).toLowerCase();
      expect(blockedMsg, `expected error about publishTime, got ${blockedMsg}`).toMatch(/publish.*time|publishtime|publish_time/i);

      // Test: block publishing without publishTime via PATCH from draft
      const draftForBlock = await request('POST', '/api/articles', {
        title: `Draft Block Test ${unique}`,
        content: 'content',
        status: 'draft',
      });
      expect([200, 201]).toContain(draftForBlock.res.status);
      const draftBlockId = pick(draftForBlock.body, ['id', 'articleId']) || draftForBlock.body?.data?.id;
      expect(draftBlockId).toBeTruthy();
      createdIds.push(draftBlockId);

      const patchPublishNoTime = await request('PATCH', `/api/articles/${draftBlockId}`, {
        status: 'published',
      });
      expect([400, 422]).toContain(patchPublishNoTime.res.status);
      const patchBlockMsg = JSON.stringify(patchPublishNoTime.body || patchPublishNoTime.text).toLowerCase();
      expect(patchBlockMsg, `expected error about publishTime when PATCH to published, got ${patchBlockMsg}`).toMatch(/publish.*time|publishtime|publish_time/i);

      // Test: authorName can be left empty
      const noAuthor = await request('POST', '/api/articles', {
        title: `No Author ${unique}`,
        content: 'content without author',
        status: 'draft',
      });
      expect([200, 201]).toContain(noAuthor.res.status);
      const noAuthorId = pick(noAuthor.body, ['id', 'articleId']) || noAuthor.body?.data?.id;
      expect(noAuthorId).toBeTruthy();
      createdIds.push(noAuthorId);

      // Test: invalid cover image URL should warn but not block
      const invalidCover = await request('POST', '/api/articles', {
        title: `Invalid Cover ${unique}`,
        content: 'content',
        coverImageUrl: 'not-a-url',
        status: 'draft',
      });
      // Should either succeed with a warning or return a validation error specifically about cover image
      // The requirement says "提示，但不能让整个页面卡住" - so it should not block creation entirely
      // Accept either: success (201) with possible warning, or a 4xx that specifically mentions cover/image
      if (invalidCover.res.status >= 400) {
        const errMsg = JSON.stringify(invalidCover.body || invalidCover.text).toLowerCase();
        expect(errMsg, 'if rejected, error should be about cover image format').toMatch(/cover|image|url|format/i);
      } else {
        expect([200, 201]).toContain(invalidCover.res.status);
        const invalidCoverId = pick(invalidCover.body, ['id', 'articleId']) || invalidCover.body?.data?.id;
        if (invalidCoverId) createdIds.push(invalidCoverId);
      }

      // Create published articles for RSS ordering test
      const t1 = '2024-01-01T10:00:00.000Z';
      const t2 = '2024-01-02T10:00:00.000Z';

      const a1 = await request('POST', '/api/articles', {
        title: `RSS Older ${unique}`,
        content: 'older',
        authorName: `Author ${unique}`,
        coverImageUrl: `https://img.example.com/${unique}-1.jpg`,
        publishTime: t1,
        status: 'published',
      });
      expect([200, 201]).toContain(a1.res.status);
