      const targets = items.filter((x) => String(x.title || '').includes(unique));
      expect(targets.length, `expected at least 3 rss items for unique marker ${unique}, got ${JSON.stringify(items)}`).toBeGreaterThanOrEqual(3);

      const titles = targets.map((x) => x.title);
