import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function request(method, path, body) {
  const res = await fetch(`${BASE_URL}${path}`, {
    method,
    headers: { 'Content-Type': 'application/json' },
    body: body !== undefined ? JSON.stringify(body) : undefined,
  });
  const text = await res.text();
  let json;
  try {
    json = text ? JSON.parse(text) : null;
  } catch {
    json = text;
  }
  return { res, body: json };
}

async function tryRequest(method, paths, body) {
  for (const path of paths) {
    const result = await request(method, path, body);
    if (result.res.status !== 404) return result;
  }
  return request(method, paths[0], body);
}

const CONFIG_PATHS = ['/api/rss/config', '/api/subscription/config'];

function extractConfig(body) {
  return body?.config || body?.data || body || {};
}

function readValue(obj, keys) {
  for (const key of keys) {
    if (obj && obj[key] !== undefined) return obj[key];
  }
  return undefined;
}

function findFieldError(body, fieldNames) {
  const text = JSON.stringify(body || {}).toLowerCase();
  return fieldNames.some(name => text.includes(String(name).toLowerCase()));
}

function asArray(v) {
  return Array.isArray(v) ? v : Array.isArray(v?.items) ? v.items : Array.isArray(v?.data) ? v.data : [];
}

describe('subscription_config_validation_by_mode', () => {
  it('should validate required title and site url, reject invalid url format, enforce free/extended max limits, preserve over-limit input as invalid after mode switch, and not render preview with invalid limit', async () => {
    const suffix = `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;

    const makePayload = (overrides = {}) => ({
      mode: 'free',
      title: `My Feed ${suffix}`,
      description: `Feed description ${suffix}`,
      siteUrl: 'https://example.com',
      feedUrl: 'https://example.com/feed',
      limit: 10,
      articleCount: 10,
      ...overrides,
    });

    // --- Title required ---
    const missingTitle = await tryRequest('PUT', CONFIG_PATHS, makePayload({ title: '   ' }));
    expect([400, 422].includes(missingTitle.res.status), `expected required title validation error, got ${missingTitle.res.status} ${JSON.stringify(missingTitle.body)}`).toBe(true);
    expect(findFieldError(missingTitle.body, ['title', '频道标题', '标题']), 'expected title-related error in response body').toBe(true);

    // --- Site URL required ---
    const missingSiteUrl = await tryRequest('PUT', CONFIG_PATHS, makePayload({ siteUrl: '' }));
    expect([400, 422].includes(missingSiteUrl.res.status), `expected required site url validation error, got ${missingSiteUrl.res.status} ${JSON.stringify(missingSiteUrl.body)}`).toBe(true);
    expect(findFieldError(missingSiteUrl.body, ['siteUrl', 'site_url', 'siteAddress', '站点地址', 'url']), 'expected site url-related error in response body').toBe(true);

    // --- Invalid site URL format ---
    const invalidSiteUrl = await tryRequest('PUT', CONFIG_PATHS, makePayload({ siteUrl: 'not-a-url' }));
    expect([400, 422].includes(invalidSiteUrl.res.status), `expected invalid site url format rejection, got ${invalidSiteUrl.res.status} ${JSON.stringify(invalidSiteUrl.body)}`).toBe(true);
    expect(findFieldError(invalidSiteUrl.body, ['siteUrl', 'site_url', 'url', '地址', 'format', '格式']), 'expected invalid url field error').toBe(true);

    // --- Limit below minimum (0 and negative) ---
    const limitZero = await tryRequest('PUT', CONFIG_PATHS, makePayload({ mode: 'free', limit: 0, articleCount: 0 }));
    expect([400, 422].includes(limitZero.res.status), `expected limit=0 rejection, got ${limitZero.res.status} ${JSON.stringify(limitZero.body)}`).toBe(true);

    const limitNegative = await tryRequest('PUT', CONFIG_PATHS, makePayload({ mode: 'free', limit: -1, articleCount: -1 }));
    expect([400, 422].includes(limitNegative.res.status), `expected limit=-1 rejection, got ${limitNegative.res.status} ${JSON.stringify(limitNegative.body)}`).toBe(true);

    // --- Free mode: limit=1 (lower boundary) should succeed ---
    const free1 = await tryRequest('PUT', CONFIG_PATHS, makePayload({ mode: 'free', limit: 1, articleCount: 1 }));
    expect([200, 201].includes(free1.res.status), `expected free mode limit=1 to succeed, got ${free1.res.status} ${JSON.stringify(free1.body)}`).toBe(true);

    // --- Free mode: max 20 valid ---
    const free20 = await tryRequest('PUT', CONFIG_PATHS, makePayload({ mode: 'free', limit: 20, articleCount: 20 }));
    expect([200, 201].includes(free20.res.status), `expected free mode with max 20 to succeed, got ${free20.res.status} ${JSON.stringify(free20.body)}`).toBe(true);
    const free20Config = extractConfig(free20.body);
    const free20Mode = readValue(free20Config, ['mode']);
    expect(free20Mode).toBe('free');
    const free20Limit = readValue(free20Config, ['limit', 'articleCount', 'outputCount', 'count']);
    expect(free20Limit).toBe(20);

    // --- Free mode: 21 should be rejected ---
    const free21 = await tryRequest('PUT', CONFIG_PATHS, makePayload({ mode: 'free', limit: 21, articleCount: 21 }));
    expect([400, 422].includes(free21.res.status), `expected free mode 21 rejection, got ${free21.res.status} ${JSON.stringify(free21.body)}`).toBe(true);

    // --- Extended mode: max 100 valid ---
    const extended100 = await tryRequest('PUT', CONFIG_PATHS, makePayload({ mode: 'extended', limit: 100, articleCount: 100 }));
    expect([200, 201].includes(extended100.res.status), `expected extended mode max 100 success, got ${extended100.res.status} ${JSON.stringify(extended100.body)}`).toBe(true);
    const ext100Config = extractConfig(extended100.body);
    expect(readValue(ext100Config, ['mode'])).toBe('extended');
    const ext100Limit = readValue(ext100Config, ['limit', 'articleCount', 'outputCount', 'count']);
    expect(ext100Limit).toBe(100);

    // --- Extended mode: 101 should be rejected ---
    const extended101 = await tryRequest('PUT', CONFIG_PATHS, makePayload({ mode: 'extended', limit: 101, articleCount: 101 }));
    expect([400, 422].includes(extended101.res.status), `expected extended mode 101 rejection, got ${extended101.res.status} ${JSON.stringify(extended101.body)}`).toBe(true);

    // --- Verify previous valid config was NOT corrupted by failed saves ---
    const readAfterFails = await tryRequest('GET', CONFIG_PATHS);
    expect(readAfterFails.res.status).toBe(200);
    const currentConfig = extractConfig(readAfterFails.body);
    // The last successful save was extended mode with limit=100
    const currentLimit = readValue(currentConfig, ['limit', 'articleCount', 'outputCount', 'count']);
    expect(currentLimit, 'last successful config should be preserved after failed saves').toBe(100);
    expect(readValue(currentConfig, ['mode'])).toBe('extended');

    // --- Switch from extended (valid 50) to free mode — limit 50 exceeds free max 20 ---
    // First save a valid extended config with limit=50
    const ext50 = await tryRequest('PUT', CONFIG_PATHS, makePayload({ mode: 'extended', limit: 50, articleCount: 50 }));
    expect([200, 201].includes(ext50.res.status), `expected extended mode 50 success, got ${ext50.res.status}`).toBe(true);

    // Now switch to free mode — keep limit=50 which exceeds free max of 20
    const switchToFree = await tryRequest('PUT', CONFIG_PATHS, makePayload({ mode: 'free', limit: 50, articleCount: 50 }));

    // The API may handle this in different ways:
    // A) Reject with 400/422 and include the preserved input + invalid marker
    // B) Accept but mark the limit as invalid in the response
    if ([400, 422].includes(switchToFree.res.status)) {
      // Approach A: rejected - verify error mentions limit
      expect(findFieldError(switchToFree.body, ['limit', 'articleCount', 'outputCount', 'max', 'count', '数量', 'invalid']),
        'expected over-limit error indication').toBe(true);

      // Verify the previous valid config is still intact
      const readAfterSwitch = await tryRequest('GET', CONFIG_PATHS);
      expect(readAfterSwitch.res.status).toBe(200);
      const configAfterSwitch = extractConfig(readAfterSwitch.body);
      const limitAfterSwitch = readValue(configAfterSwitch, ['limit', 'articleCount', 'outputCount', 'count']);
      // Should still be the last valid save (extended, 50)
      expect(limitAfterSwitch).toBe(50);
    } else if ([200, 201].includes(switchToFree.res.status)) {
      // Approach B: accepted but marked as invalid
      const switchConfig = extractConfig(switchToFree.body);
      const switchLimit = readValue(switchConfig, ['limit', 'articleCount', 'outputCount', 'count']);
      // Input should be preserved
      expect(switchLimit, 'over-limit input should be preserved').toBe(50);
      // Should have an invalid marker
      const invalidFlag = readValue(switchConfig, ['invalid', 'isInvalid', 'limitInvalid', 'outputCountInvalid']) ??
        readValue(switchToFree.body, ['invalid', 'isInvalid', 'limitInvalid', 'outputCountInvalid']);
      if (invalidFlag !== undefined) {
        expect(!!invalidFlag, 'limit should be marked as invalid after mode switch').toBe(true);
      }
    }

    // --- Verify preview does NOT render with invalid limit ---
    // Create some published articles to have preview data
    const catRes = await request('POST', '/api/categories', { name: `PreviewCat ${suffix}` });
    const catId = catRes.body?.id || catRes.body?.data?.id || catRes.body?.categoryId;
    const createdArticleIds = [];

    try {
      // Create a few published articles
      for (let i = 0; i < 3; i++) {
        const art = await request('POST', '/api/articles', {
          title: `Preview Art ${i} ${suffix}`,
          content: `Content for preview article ${i}`,
          status: 'published',
          publishedAt: `2024-06-0${i + 1}T10:00:00.000Z`,
          publishTime: `2024-06-0${i + 1}T10:00:00.000Z`,
          primaryCategoryId: catId,
          categoryIds: catId ? [catId] : undefined,
        });
        if ([200, 201].includes(art.res.status)) {
          const artId = art.body?.id || art.body?.data?.id;
          if (artId) createdArticleIds.push(artId);
        }
      }

      // Save a valid free mode config with limit=3
      await tryRequest('PUT', CONFIG_PATHS, makePayload({ mode: 'free', limit: 3, articleCount: 3 }));

      // Get preview - should work with valid limit
      const previewValid = await tryRequest('GET', ['/api/rss/preview', '/api/subscription/preview']);
      expect(previewValid.res.status).toBe(200);
      const previewValidBody = previewValid.body?.data || previewValid.body;
      const previewValidItems = asArray(previewValidBody?.included || previewValidBody?.items || previewValidBody?.articles || previewValidBody);
      // Should have at most 3 items (our limit)
      expect(previewValidItems.length).toBeLessThanOrEqual(3);

      // Now save extended with limit=50, then try switching to free (where 50 is invalid)
      await tryRequest('PUT', CONFIG_PATHS, makePayload({ mode: 'extended', limit: 50, articleCount: 50 }));
      // Attempt the switch
      await tryRequest('PUT', CONFIG_PATHS, makePayload({ mode: 'free', limit: 50, articleCount: 50 }));

      // Get preview again
      const previewAfter = await tryRequest('GET', ['/api/rss/preview', '/api/subscription/preview']);
      expect(previewAfter.res.status).toBe(200);
      const previewAfterBody = previewAfter.body?.data || previewAfter.body;
      const previewAfterItems = asArray(previewAfterBody?.included || previewAfterBody?.items || previewAfterBody?.articles || previewAfterBody);
      // Preview should NOT use the invalid limit of 50 in free mode (max 20)
      // It should use either the last valid config or cap at the mode max
      expect(previewAfterItems.length).toBeLessThanOrEqual(20);

    } finally {
      for (const id of createdArticleIds) {
        await tryRequest('DELETE', [`/api/articles/${id}`]);
        await tryRequest('DELETE', [`/api/articles/${id}/permanent`, `/api/articles/${id}?permanent=true`]);
      }
      if (catId) {
        try { await fetch(`${BASE_URL}/api/categories/${catId}`, { method: 'DELETE' }); } catch {}
      }
    }
  });
});

import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function request(method, path, body) {
  const res = await fetch(`${BASE_URL}${path}`, {
    method,
    headers: { 'Content-Type': 'application/json' },
    body: body === undefined ? undefined : JSON.stringify(body),
  });
  const text = await res.text();
  let data = null;
  try {
    data = text ? JSON.parse(text) : null;
  } catch {
    data = text;
  }
  return { res, data };
}

async function safeDelete(path) {
  try {
    await fetch(`${BASE_URL}${path}`, { method: 'DELETE' });
  } catch {
    // ignore
  }
}

function unwrap(data) {
  return data?.data ?? data;
}

function asList(data) {
  const d = unwrap(data);
  return Array.isArray(d) ? d : d?.items || d?.versions || d?.data || [];
}

function getUpdatedAt(item) {
  const d = unwrap(item);
  return d?.updatedAt || d?.updated_at || d?.modifiedAt || d?.lastUpdatedAt || d?.lastModifiedAt;
}

function getTitle(item) {
  return item?.title || item?.postTitle || item?.snapshotTitle || item?.versionTitle;
}

async function ensureCategory(name) {
  const { res, data } = await request('POST', '/api/categories', { name });
  expect([200, 201]).toContain(res.status);
  const body = unwrap(data);
  return body?.id;
}

describe('round26_version_restore_adds_new_record', () => {
  it('should create a new current version when restoring earliest titled version A instead of overwriting history', async () => {
    const unique = `r26-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
    let articleId;
    let catId;

    try {
      // Create a category for the article
      catId = await ensureCategory(`VerCat ${unique}`);

      // Create the article
      const { res: createRes, data: createData } = await request('POST', '/api/articles', {
        title: `Seed ${unique}`,
        summary: 'version restore behavior test',
        content: 'seed content',
        status: 'draft',
        primaryCategoryId: catId,
        categoryIds: [catId],
      });
      expect([200, 201]).toContain(createRes.status);
      const created = unwrap(createData);
      articleId = created?.id;
      expect(articleId, `expected created article id, got ${JSON.stringify(createData)}`).toBeTruthy();

      // Save version A by updating article title to A
      const saveA = await request('PUT', `/api/articles/${articleId}`, {
        title: 'A',
        content: 'content-A',
        summary: 'version A',
        primaryCategoryId: catId,
        categoryIds: [catId],
      });
      expect(saveA.res.status, `expected save A success, got ${saveA.res.status}`).toBeGreaterThanOrEqual(200);
      expect(saveA.res.status).toBeLessThan(300);

      // Save version B
      const saveB = await request('PUT', `/api/articles/${articleId}`, {
        title: 'B',
        content: 'content-B',
        summary: 'version B',
        primaryCategoryId: catId,
        categoryIds: [catId],
      });
      expect(saveB.res.status).toBeGreaterThanOrEqual(200);
      expect(saveB.res.status).toBeLessThan(300);

      // Save version C
      const saveC = await request('PUT', `/api/articles/${articleId}`, {
        title: 'C',
        content: 'content-C',
        summary: 'version C',
        primaryCategoryId: catId,
        categoryIds: [catId],
      });
      expect(saveC.res.status).toBeGreaterThanOrEqual(200);
      expect(saveC.res.status).toBeLessThan(300);

      // Get version list before restore
      const beforeList = await request('GET', `/api/articles/${articleId}/versions`);
      expect(beforeList.res.status, `expected versions list, got ${beforeList.res.status}`).toBe(200);
      const beforeVersions = asList(beforeList.data);
      expect(beforeVersions.length, `expected at least 3 versions, got ${beforeVersions.length}`).toBeGreaterThanOrEqual(3);

      // Find the earliest version with title A
      const earliestA = beforeVersions.find((v) => getTitle(v) === 'A' || v.label === 'manual-save-A' || v.summary === 'version A');
      expect(earliestA, `expected to find version A in ${JSON.stringify(beforeVersions.map(v => getTitle(v)))}`).toBeTruthy();
      expect(earliestA?.id, `expected version A to have id`).toBeTruthy();

      // Record detail before restore
      const beforeDetail = await request('GET', `/api/articles/${articleId}`);
      expect(beforeDetail.res.status).toBe(200);
      const beforeUpdatedAt = getUpdatedAt(beforeDetail.data);
      expect(beforeUpdatedAt, `expected updatedAt before restore`).toBeTruthy();

      // Wait a bit to ensure time difference
      await new Promise((r) => setTimeout(r, 50));

      // Restore version A
      const restoreRes = await request('POST', `/api/articles/${articleId}/versions/${earliestA.id}/restore`, {});
      if (restoreRes.res.status === 404 || restoreRes.res.status === 405) {
        // Try alternative restore endpoint
        const altRestore = await request('POST', `/api/articles/${articleId}/restore`, { versionId: earliestA.id });
        expect(altRestore.res.status, `expected restore to succeed`).toBeGreaterThanOrEqual(200);
        expect(altRestore.res.status).toBeLessThan(300);
      } else {
        expect(restoreRes.res.status, `expected restore to succeed, got ${restoreRes.res.status}`).toBeGreaterThanOrEqual(200);
        expect(restoreRes.res.status).toBeLessThan(300);
      }

      // Verify version list after restore: count should be beforeVersions.length + 1
      const afterList = await request('GET', `/api/articles/${articleId}/versions`);
      expect(afterList.res.status).toBe(200);
      const afterVersions = asList(afterList.data);

      expect(afterVersions.length, `expected version count to increase by 1 after restore. before=${beforeVersions.length}, after=${afterVersions.length}`).toBe(beforeVersions.length + 1);

      // B and C versions should still exist
      const hasB = afterVersions.some((v) => getTitle(v) === 'B' || v.summary === 'version B');
      const hasC = afterVersions.some((v) => getTitle(v) === 'C' || v.summary === 'version C');
      expect(hasB, `expected original B version to remain after restore`).toBe(true);
      expect(hasC, `expected original C version to remain after restore`).toBe(true);

      // There should be a new version record (the restore-generated one) not in the old list
      const beforeIds = new Set(beforeVersions.map((v) => v?.id).filter(Boolean));
      const newVersions = afterVersions.filter((v) => v?.id && !beforeIds.has(v.id));
      expect(newVersions.length, `expected exactly one newly added version record after restore`).toBe(1);

      // Current article title should be A
      const detailAfter = await request('GET', `/api/articles/${articleId}`);
      expect(detailAfter.res.status).toBe(200);
      const restoredArticle = unwrap(detailAfter.data);
      expect(restoredArticle?.title, `expected restored title to be A, got ${restoredArticle?.title}`).toBe('A');

      // Updated time should be newer than before
      const afterUpdatedAt = getUpdatedAt(detailAfter.data);
      expect(afterUpdatedAt, `expected updatedAt after restore`).toBeTruthy();
      expect(new Date(afterUpdatedAt).getTime(), `expected updatedAt to be strictly after before. before=${beforeUpdatedAt}, after=${afterUpdatedAt}`).toBeGreaterThan(new Date(beforeUpdatedAt).getTime());

      // Check the article list (overview) shows the updated time
      const overviewAfter = await request('GET', '/api/articles');
      expect(overviewAfter.res.status).toBe(200);
      const overviewItems = asList(overviewAfter.data);
      const overviewArticle = overviewItems.find((p) => p?.id === articleId);
      expect(overviewArticle, `expected restored article in articles list`).toBeTruthy();
      const overviewUpdatedAt = getUpdatedAt(overviewArticle);
      expect(overviewUpdatedAt, `expected overview updatedAt field`).toBeTruthy();
      expect(new Date(overviewUpdatedAt).getTime(), `expected overview updatedAt to reflect restore time`).toBeGreaterThanOrEqual(new Date(afterUpdatedAt).getTime());
    } finally {
      if (articleId) {
        await safeDelete(`/api/articles/${articleId}?permanent=true&confirm=true`);
        await safeDelete(`/api/articles/${articleId}`);
      }
      if (catId) await safeDelete(`/api/categories/${catId}`);
    }
  });
});

import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function request(path, options = {}) {
  return fetch(`${BASE_URL}${path}`, {
    headers: {
      'Content-Type': 'application/json',
      ...(options.headers || {}),
    },
    ...options,
  });
}

async function safeJson(res) {
  const text = await res.text();
  try {
    return text ? JSON.parse(text) : null;
  } catch {
    return { raw: text };
  }
}

async function cleanupArticle(id) {
  if (!id) return;
  try {
    await request(`/api/articles/${id}`, { method: 'DELETE' });
  } catch {}
}

describe('round1_article_draft_creation', () => {
  it('should reject empty title and empty content', async () => {
    const invalidRes = await request('/api/articles', {
      method: 'POST',
      body: JSON.stringify({
        title: '',
        summary: 'summary',
        content: '',
        status: 'draft',
      }),
    });
    expect([400, 422]).toContain(invalidRes.status);
    const invalidBody = await safeJson(invalidRes);
    expect(invalidBody).toBeTruthy();
    const hasErrorInfo = invalidBody.message || invalidBody.error || invalidBody.errors || invalidBody.reason;
