import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function request(method, path, body) {
  const res = await fetch(`${BASE_URL}${path}`, {
    method,
    headers: { 'Content-Type': 'application/json' },
    body: body === undefined ? undefined : JSON.stringify(body),
  });
  const text = await res.text();
  let json = null;
  try { json = text ? JSON.parse(text) : null; } catch { json = text; }
  return { res, body: json, text };
}

async function tryPermanentDelete(id) {
  if (!id) return;
  try { await request('DELETE', `/api/articles/${id}?permanent=true&confirm=true`); } catch {}
  try { await request('DELETE', `/api/articles/${id}?permanent=true`); } catch {}
  try { await request('DELETE', `/api/articles/${id}`); } catch {}
}

function pick(obj, keys) {
  for (const key of keys) if (obj && obj[key] !== undefined) return obj[key];
}
function asArray(v) {
  if (Array.isArray(v)) return v;
  if (v?.items && Array.isArray(v.items)) return v.items;
  if (v?.articles && Array.isArray(v.articles)) return v.articles;
  if (v?.data && Array.isArray(v.data)) return v.data;
  return [];
}

function extractArticleId(obj) {
  if (!obj) return undefined;
  return obj.id || obj.articleId || obj.data?.id;
}

async function getStats() {
  const stats = await request('GET', '/api/articles/stats');
  expect(stats.res.status).toBe(200);
  const body = stats.body?.data || stats.body;
  expect(body).toBeTruthy();
  return {
    total: Number(body?.total ?? body?.all ?? 0),
    draft: Number(body?.draft ?? body?.draftCount ?? 0),
    published: Number(body?.published ?? body?.publishedCount ?? 0),
    archived: Number(body?.archived ?? body?.archivedCount ?? 0),
    recycle: Number(body?.deleted ?? body?.recycleBin ?? body?.recycleCount ?? 0),
  };
}

async function listByQuery(query) {
  const res = await request('GET', `/api/articles${query}`);
  expect(res.res.status).toBe(200);
  return asArray(res.body);
}

function expectSelectionFeedback(result, expectedSelected) {
  expect(result).toBeTruthy();
  const selectedCount = pick(result, ['selectedCount', 'selected', 'requestedCount', 'selectionCount']);
  expect(selectedCount, `expected selected/selection count in bulk result: ${JSON.stringify(result)}`).not.toBeUndefined();
  expect(Number(selectedCount)).toBe(expectedSelected);
}

function expectMixedFeedback(result, rawText, expectedSelected, invalidId) {
  expect(result).toBeTruthy();
  expectSelectionFeedback(result, expectedSelected);
  const invalidCount = pick(result, ['invalidCount', 'skippedCount', 'skipped', 'failedCount']);
  const details = pick(result, ['warnings', 'details', 'results', 'items', 'invalidItems', 'skippedItems']);
  const normalized = `${JSON.stringify(result)} ${String(rawText || '')}`.toLowerCase();
  expect(
    invalidCount !== undefined || details !== undefined || /already|archived|draft|deleted|recycle|skip|invalid|cannot/.test(normalized)
  ).toBe(true);
  if (invalidCount !== undefined) {
    expect(Number(invalidCount)).toBeGreaterThanOrEqual(1);
  }
  if (invalidId !== undefined) {
    expect(normalized.includes(String(invalidId).toLowerCase()) || /already|archived|draft|deleted|recycle|skip|invalid|cannot/.test(normalized)).toBe(true);
  }
}

describe('round13_bulk_actions_soft_delete', () => {
  it('should bulk archive articles and refresh archived status, counts, and filtered results', async () => {
    const unique = `bulk-arch-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
    const ids = [];

    try {
      for (let i = 1; i <= 2; i++) {
        const created = await request('POST', '/api/articles', {
          title: `BulkArch ${i} ${unique}`,
          content: `content ${i}`,
          status: 'published',
          publishedAt: new Date().toISOString(),
          publishTime: new Date().toISOString(),
        });
        expect([200, 201]).toContain(created.res.status);
        const id = extractArticleId(created.body);
        expect(id).toBeTruthy();
        ids.push(id);
      }

      const beforePublishedFiltered = await listByQuery(`?status=published&keyword=${encodeURIComponent(unique)}`);
      const beforeArchivedFiltered = await listByQuery(`?status=archived&keyword=${encodeURIComponent(unique)}`);
      expect(beforePublishedFiltered.map(x => x.id || x.articleId)).toEqual(expect.arrayContaining(ids));
      expect(beforeArchivedFiltered.map(x => x.id || x.articleId)).not.toEqual(expect.arrayContaining(ids));

      const statsBefore = await getStats();

      const archive = await request('POST', '/api/articles/bulk', {
        action: 'archive',
        ids,
      });
      expect([200, 204]).toContain(archive.res.status);

      const archiveResult = archive.body?.data || archive.body;
      expectSelectionFeedback(archiveResult, 2);
      const affectedCount = pick(archiveResult, ['affectedCount', 'affected', 'count', 'processed', 'success']);
      if (affectedCount !== undefined) expect(Number(affectedCount)).toBe(2);

      for (const id of ids) {
        const detail = await request('GET', `/api/articles/${id}`);
        expect(detail.res.status).toBe(200);
        const article = detail.body?.data || detail.body;
        expect(article).toBeTruthy();
        expect(article.id || article.articleId).toBe(id);
        expect(article.status).toBe('archived');
      }

      const publishedFilteredAfter = await listByQuery(`?status=published&keyword=${encodeURIComponent(unique)}`);
      const archivedFilteredAfter = await listByQuery(`?status=archived&keyword=${encodeURIComponent(unique)}`);
      const publishedIdsAfter = publishedFilteredAfter.map(x => x.id || x.articleId);
      const archivedIdsAfter = archivedFilteredAfter.map(x => x.id || x.articleId);
      expect(publishedIdsAfter.some(id => ids.includes(id))).toBe(false);
      expect(archivedIdsAfter).toEqual(expect.arrayContaining(ids));

      const statsAfter = await getStats();
      expect(statsAfter.archived - statsBefore.archived).toBe(2);
      expect(statsAfter.published - statsBefore.published).toBe(-2);
    } finally {
      for (const id of ids) await tryPermanentDelete(id);
    }
  });

