describe('article_list_category_order_correct', () => {
  it('should return article categories with primary category first and additional categories after it', async () => {
    const suffix = Date.now();
    const categoryIds = [];
    let articleId;

    try {
      for (const name of [`primary-${suffix}`, `secondary-${suffix}`]) {
        const c = await request('POST', '/categories', { name });
        expect([200, 201].includes(c.res.status), `expected category create success, got ${c.res.status} ${JSON.stringify(c.body)}`).toBe(true);
        categoryIds.push(c.body.id);
      }

      const article = await request('POST', '/articles', {
        title: `category-order-${suffix}`,
        content: 'content',
        status: 'draft',
        categories: [
          { id: categoryIds[1], isPrimary: false },
          { id: categoryIds[0], isPrimary: true },
        ],
      });
      expect([200, 201].includes(article.res.status), `expected article create success, got ${article.res.status} ${JSON.stringify(article.body)}`).toBe(true);
      articleId = article.body?.id;
      expect(articleId, `expected article id, got ${JSON.stringify(article.body)}`).toBeTruthy();

      const list = await request('GET', '/articles');
      expect(list.res.status, `expected article list success, got ${list.res.status} ${JSON.stringify(list.body)}`).toBe(200);

      const items = Array.isArray(list.body) ? list.body : list.body?.items || list.body?.data || [];
      const found = items.find((item) => item.id === articleId);
      expect(found, `expected created article ${articleId} to appear in list, got ${JSON.stringify(items)}`).toBeTruthy();

      const categories = found.categories || [];
      expect(Array.isArray(categories), `expected categories array in list item, got ${JSON.stringify(found)}`).toBe(true);
      expect(categories.length >= 2, `expected at least 2 categories in list item, got ${JSON.stringify(found)}`).toBe(true);

      const normalized = categories.map((c) => ({ id: c.id ?? c.categoryId ?? c, isPrimary: !!c.isPrimary }));
      expect(normalized[0].id, `expected primary category first in list item, got ${JSON.stringify(categories)}`).toBe(categoryIds[0]);
      expect(normalized[0].isPrimary, `expected first category to be marked primary, got ${JSON.stringify(categories)}`).toBe(true);
      expect(normalized[1].id, `expected secondary category after primary, got ${JSON.stringify(categories)}`).toBe(categoryIds[1]);
    } finally {
      try { if (articleId) await request('DELETE', `/articles/${articleId}`); } catch {}
      for (const id of categoryIds) {
        try { await request('DELETE', `/categories/${id}`); } catch {}
      }
    }
  });
});

