import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function request(method, path, body) {
  const res = await fetch(`${BASE_URL}${path}`, {
    method,
    headers: { 'Content-Type': 'application/json' },
    body: body === undefined ? undefined : JSON.stringify(body),
  });
  const text = await res.text();
  let json = null;
  try { json = text ? JSON.parse(text) : null; } catch { json = text; }
  return { res, body: json, text };
}

async function tryRequest(method, path, body) {
  let r = await request(method, path, body);
  if (r.res.status === 404 && !path.startsWith('/api/')) {
    r = await request(method, `/api${path}`, body);
  } else if (r.res.status === 404 && path.startsWith('/api/')) {
    r = await request(method, path.replace(/^\/api/, ''), body);
  }
  return r;
}

async function tryDelete(path) {
  try { await fetch(`${BASE_URL}${path}`, { method: 'DELETE' }); } catch {}
  try { await fetch(`${BASE_URL}/api${path.replace(/^\/api/, '')}`, { method: 'DELETE' }); } catch {}
}

function unwrap(body) {
  return body?.data ?? body;
}

function pick(obj, keys) {
  const d = unwrap(obj);
  for (const key of keys) {
    if (d && d[key] !== undefined) return d[key];
  }
  return undefined;
}

function asArray(v) {
  const d = unwrap(v);
  return Array.isArray(d) ? d : Array.isArray(d?.items) ? d.items : Array.isArray(d?.data) ? d.data : Array.isArray(d?.articles) ? d.articles : [];
}

describe('round12_dual_category_migration', () => {
  it('should enforce max 2 categories with 1 primary, migrate legacy single category, and handle edge cases', async () => {
    const unique = `cat-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
    const categoryIds = [];
    const articleIds = [];

    try {
      // Create 3 categories
      const c1 = await tryRequest('POST', '/api/categories', { name: `Primary ${unique}` });
      expect(c1.res.status).toBeGreaterThanOrEqual(200);
      expect(c1.res.status).toBeLessThan(300);
      const c2 = await tryRequest('POST', '/api/categories', { name: `Secondary ${unique}` });
      expect(c2.res.status).toBeGreaterThanOrEqual(200);
      expect(c2.res.status).toBeLessThan(300);
      const c3 = await tryRequest('POST', '/api/categories', { name: `Third ${unique}` });
      expect(c3.res.status).toBeGreaterThanOrEqual(200);
      expect(c3.res.status).toBeLessThan(300);

      const id1 = pick(c1.body, ['id', 'categoryId']);
      const id2 = pick(c2.body, ['id', 'categoryId']);
      const id3 = pick(c3.body, ['id', 'categoryId']);
      expect(id1, 'category 1 should have an id').toBeTruthy();
      expect(id2, 'category 2 should have an id').toBeTruthy();
      expect(id3, 'category 3 should have an id').toBeTruthy();
      categoryIds.push(id1, id2, id3);

      // Legacy single-category article: should auto-migrate as primary
      const legacy = await tryRequest('POST', '/api/articles', {
        title: `Legacy Single Category ${unique}`,
        content: 'legacy content body',
        categoryId: id1,
        primaryCategoryId: id1,
        status: 'draft',
        editorMode: 'markdown',
      });
      expect(legacy.res.status).toBeGreaterThanOrEqual(200);
      expect(legacy.res.status).toBeLessThan(300);
      const legacyArticleId = pick(legacy.body, ['id', 'articleId']);
      expect(legacyArticleId, 'legacy article should return an id').toBeTruthy();
      articleIds.push(legacyArticleId);

      // Read back and verify primary category is set
      const readLegacy = await tryRequest('GET', `/api/articles/${legacyArticleId}`);
      expect(readLegacy.res.status).toBe(200);
      const article = unwrap(readLegacy.body);

      const primaryCategoryId = (
        article?.primaryCategoryId ||
        article?.primaryCategory?.id ||
        (Array.isArray(article?.categories) && article.categories.find(c => c.isPrimary || c.primary)?.id)
      );
      expect(primaryCategoryId, `Legacy single category should be mapped as primary. Article: ${JSON.stringify(article)}`).toBeTruthy();

      // Try to assign more than 2 categories => should be rejected
      const tooMany = await tryRequest('PATCH', `/api/articles/${legacyArticleId}`, {
        primaryCategoryId: id1,
        categoryIds: [id1, id2, id3],
        categories: [{ id: id1, isPrimary: true }, { id: id2 }, { id: id3 }],
      });
      // If PATCH 404, try PUT
      let tooManyResult = tooMany;
      if (tooMany.res.status === 404) {
        tooManyResult = await tryRequest('PUT', `/api/articles/${legacyArticleId}`, {
          title: `Legacy Single Category ${unique}`,
          content: 'legacy content body',
          primaryCategoryId: id1,
          categoryIds: [id1, id2, id3],
          status: 'draft',
          editorMode: 'markdown',
        });
      }
      expect([400, 422]).toContain(tooManyResult.res.status);

      // Try to set categories without a primary => should be rejected
      const noPrimary = await tryRequest('PATCH', `/api/articles/${legacyArticleId}`, {
        categoryIds: [id1, id2],
        primaryCategoryId: null,
        categories: [{ id: id1 }, { id: id2 }],
      });
      let noPrimaryResult = noPrimary;
      if (noPrimary.res.status === 404) {
        noPrimaryResult = await tryRequest('PUT', `/api/articles/${legacyArticleId}`, {
          title: `Legacy Single Category ${unique}`,
          content: 'legacy content body',
          categoryIds: [id1, id2],
          primaryCategoryId: null,
          status: 'draft',
          editorMode: 'markdown',
        });
      }
      expect([400, 422]).toContain(noPrimaryResult.res.status);

      // Valid update: primary + secondary (2 categories)
      const valid = await tryRequest('PATCH', `/api/articles/${legacyArticleId}`, {
        primaryCategoryId: id1,
        categoryIds: [id1, id2],
        categories: [{ id: id1, isPrimary: true }, { id: id2, isPrimary: false }],
      });
      let validResult = valid;
      if (valid.res.status === 404) {
        validResult = await tryRequest('PUT', `/api/articles/${legacyArticleId}`, {
          title: `Legacy Single Category ${unique}`,
          content: 'legacy content body',
          primaryCategoryId: id1,
          categoryIds: [id1, id2],
          status: 'draft',
          editorMode: 'markdown',
        });
      }
      expect(validResult.res.status).toBeGreaterThanOrEqual(200);
      expect(validResult.res.status).toBeLessThan(300);

      // Verify the update
      const readUpdated = await tryRequest('GET', `/api/articles/${legacyArticleId}`);
      expect(readUpdated.res.status).toBe(200);
      const updated = unwrap(readUpdated.body);

      const updatedCategories = updated.categoryIds || (Array.isArray(updated.categories) ? updated.categories.map(c => c.id) : []);
      expect(updatedCategories.length, `Should have at most 2 categories. Got: ${JSON.stringify(updated)}`).toBeLessThanOrEqual(2);

      const updatedPrimary = (
        updated.primaryCategoryId ||
        updated.primaryCategory?.id ||
        (Array.isArray(updated.categories) && updated.categories.find(c => c.isPrimary || c.primary)?.id)
      );
      expect(updatedPrimary, `Primary category should be retained. Got: ${JSON.stringify(updated)}`).toBeTruthy();

      // Edge case: try to remove primary while keeping secondary
      const removePrimary = await tryRequest('PATCH', `/api/articles/${legacyArticleId}`, {
        primaryCategoryId: null,
        categoryIds: [id2],
        categories: [{ id: id2 }],
      });
      let removePrimaryResult = removePrimary;
      if (removePrimary.res.status === 404) {
        removePrimaryResult = await tryRequest('PUT', `/api/articles/${legacyArticleId}`, {
          title: `Legacy Single Category ${unique}`,
          content: 'legacy content body',
          primaryCategoryId: null,
          categoryIds: [id2],
          status: 'draft',
          editorMode: 'markdown',
        });
      }
      expect([400, 422]).toContain(removePrimaryResult.res.status);

      // Verify article list shows category info
      let listRes = await tryRequest('GET', `/api/articles?search=${encodeURIComponent(unique)}`);
      if (listRes.res.status === 404) {
        listRes = await tryRequest('GET', '/api/articles');
      }
      expect(listRes.res.status).toBe(200);
      const listItems = asArray(listRes.body);
      const listArticle = listItems.find(x => String(x.title || '').includes(`Legacy Single Category ${unique}`));
      expect(listArticle, 'Article should appear in list').toBeTruthy();

      // List should expose category info
      const listHasCats = (
        listArticle.categories ||
        listArticle.categoryIds ||
        listArticle.primaryCategoryId ||
        listArticle.primaryCategory
      );
      expect(listHasCats, `List item should include category info. Got: ${JSON.stringify(listArticle)}`).toBeTruthy();
    } finally {
      for (const id of articleIds) {
        await tryDelete(`/api/articles/${id}`);
        try { await fetch(`${BASE_URL}/api/articles/${id}/permanent`, { method: 'DELETE' }); } catch {}
      }
      for (const id of categoryIds) {
        await tryDelete(`/api/categories/${id}`);
      }
    }
  });
});

import { describe, it, expect, afterAll } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function request(path, options = {}) {
  const res = await fetch(`${BASE_URL}${path}`, {
    headers: {
      'Content-Type': 'application/json',
      ...(options.headers || {}),
    },
    ...options,
  });
  return res;
}

async function tryRequest(path, options = {}) {
  let res = await request(path, options);
  if (res.status === 404 && !path.startsWith('/api/')) {
    res = await request(`/api${path}`, options);
  } else if (res.status === 404 && path.startsWith('/api/')) {
    res = await request(path.replace(/^\/api/, ''), options);
  }
  return res;
}

async function safeJson(res) {
  const text = await res.text();
  try {
    return text ? JSON.parse(text) : null;
  } catch {
    return { raw: text };
  }
}

function unwrap(body) {
  return body?.data ?? body;
}

async function cleanupArticle(id) {
  if (!id) return;
  try { await request(`/api/articles/${id}`, { method: 'DELETE' }); } catch {}
  try { await request(`/api/articles/${id}/permanent`, { method: 'DELETE' }); } catch {}
}

async function ensureCategory(name) {
  let res = await tryRequest('/api/categories', {
    method: 'POST',
    body: JSON.stringify({ name }),
  });
  expect(res.status).toBeGreaterThanOrEqual(200);
  expect(res.status).toBeLessThan(300);
  const body = await safeJson(res);
  return unwrap(body);
}

function extractItems(body, ...keys) {
  const d = unwrap(body);
  for (const key of keys) {
    if (d && Array.isArray(d[key])) return d[key];
  }
  if (Array.isArray(d)) return d;
  return [];
}

function getCounts(body) {
  const d = unwrap(body);
  return d?.counts || d?.statusCounts || d?.statistics || d?.stats || body?.counts || body?.statusCounts || {};
}

