        title: `Status Flow ${unique}`,
        summary: 'summary',
        content: 'published body',
        status: 'archived',
        publishedAt: new Date().toISOString(),
        primaryCategoryId: catData?.id,
        editorMode: 'markdown',
      }),
    });
    expect(archiveRes.status).toBeGreaterThanOrEqual(200);
    expect(archiveRes.status).toBeLessThan(300);

    const getRes = await tryRequest(`/api/articles/${articleId}`);
    expect(getRes.status).toBe(200);
    const article = unwrap(await safeJson(getRes));
    expect(article.status).toBe('archived');
  });

  it('should reject direct content editing on archived article', async () => {
    const getBefore = await tryRequest(`/api/articles/${articleId}`);
    expect(getBefore.status).toBe(200);
    const before = unwrap(await safeJson(getBefore));
    const contentBefore = before.content || before.body;

    const editArchivedRes = await tryRequest(`/api/articles/${articleId}`, {
      method: 'PUT',
      body: JSON.stringify({
        title: `Status Flow ${unique}`,
        summary: 'summary',
        content: 'trying to edit archived body directly - CHANGED',
        status: 'archived',
        editorMode: 'markdown',
      }),
    });

    if ([400, 403, 422].includes(editArchivedRes.status)) {
      // Good: editing archived is explicitly rejected
      expect([400, 403, 422]).toContain(editArchivedRes.status);
    } else {
      // If API accepts the PUT, content should NOT have been changed
      const getAfter = await tryRequest(`/api/articles/${articleId}`);
      expect(getAfter.status).toBe(200);
      const after = unwrap(await safeJson(getAfter));
      const contentAfter = after.content || after.body;
      expect(contentAfter, 'archived article content should not be modified').toBe(contentBefore);
    }
  });

  it('should allow restoring archived article to draft', async () => {
    const restoreRes = await tryRequest(`/api/articles/${articleId}`, {
      method: 'PUT',
      body: JSON.stringify({
        title: `Status Flow ${unique}`,
        summary: 'summary',
        content: 'published body',
        status: 'draft',
        editorMode: 'markdown',
      }),
    });
    expect(restoreRes.status).toBeGreaterThanOrEqual(200);
    expect(restoreRes.status).toBeLessThan(300);

    const getRes = await tryRequest(`/api/articles/${articleId}`);
    expect(getRes.status).toBe(200);
    const article = unwrap(await safeJson(getRes));
    expect(article.status).toBe('draft');
  });

  it('should filter articles by status and return status counts that update on status change', async () => {
    // Set article to published for filtering test
    await tryRequest(`/api/articles/${articleId}`, {
      method: 'PUT',
      body: JSON.stringify({
        title: `Status Flow ${unique}`,
        summary: 'summary',
        content: 'published body',
        status: 'published',
        publishedAt: new Date().toISOString(),
        primaryCategoryId: catData?.id,
        editorMode: 'markdown',
      }),
    });

    // Get published list
    const publishedListRes = await tryRequest(`/api/articles?status=published`);
    expect(publishedListRes.status).toBe(200);
    const publishedListBody = await safeJson(publishedListRes);
    const publishedItems = extractItems(publishedListBody, 'items', 'articles', 'data');
    expect(Array.isArray(publishedItems)).toBe(true);
    const foundInPublished = publishedItems.find(item => (unwrap(item)?.id || item.id) === articleId);
    expect(foundInPublished, 'published article should appear in published filter').toBeTruthy();

    // Verify status counts are returned
    const countsBefore = getCounts(publishedListBody);
    // Status counts should be present
    expect(
      Object.keys(countsBefore).length > 0 || publishedListBody?.totalCount !== undefined || publishedListBody?.total !== undefined,
      `Response should include status counts or total. Got: ${JSON.stringify(publishedListBody)}`
    ).toBe(true);

    // Now archive the article
    await tryRequest(`/api/articles/${articleId}`, {
      method: 'PUT',
      body: JSON.stringify({
        title: `Status Flow ${unique}`,
        summary: 'summary',
        content: 'published body',
        status: 'archived',
        publishedAt: new Date().toISOString(),
        primaryCategoryId: catData?.id,
        editorMode: 'markdown',
      }),
    });

    // Verify it appears in archived filter
    const archivedListRes = await tryRequest('/api/articles?status=archived');
    expect(archivedListRes.status).toBe(200);
    const archivedListBody = await safeJson(archivedListRes);
    const archivedItems = extractItems(archivedListBody, 'items', 'articles', 'data');
    expect(Array.isArray(archivedItems)).toBe(true);
    const foundInArchived = archivedItems.find(item => (unwrap(item)?.id || item.id) === articleId);
    expect(foundInArchived, 'archived article should appear in archived filter').toBeTruthy();

    // Verify counts updated
    const countsAfter = getCounts(archivedListBody);
    if (Object.keys(countsAfter).length > 0) {
      expect(countsAfter.archived, 'archived count should be at least 1').toBeGreaterThanOrEqual(1);
    }

    // Check article no longer in published filter
    const publishedAfterRes = await tryRequest('/api/articles?status=published');
    expect(publishedAfterRes.status).toBe(200);
    const publishedAfterBody = await safeJson(publishedAfterRes);
    const publishedAfterItems = extractItems(publishedAfterBody, 'items', 'articles', 'data');
    const notFoundInPublished = publishedAfterItems.find(item => (unwrap(item)?.id || item.id) === articleId);
    expect(notFoundInPublished, 'archived article should NOT appear in published filter').toBeFalsy();

    // Check draft filter does not return this archived article
    const draftListRes = await tryRequest('/api/articles?status=draft');
    expect(draftListRes.status).toBe(200);
    const draftListBody = await safeJson(draftListRes);
    const draftItems = extractItems(draftListBody, 'items', 'articles', 'data');
    const notFoundInDraft = draftItems.find(item => (unwrap(item)?.id || item.id) === articleId);
    expect(notFoundInDraft, 'archived article should not appear in draft filter').toBeFalsy();
  });

  it('should show empty result when filtering by status with no matching results', async () => {
    // Article is currently archived (from previous test)
    // Query for published with our unique marker - should be empty
    const emptyStatusRes = await tryRequest(`/api/articles?status=published&search=${encodeURIComponent(unique)}`);
    expect(emptyStatusRes.status).toBe(200);
    const emptyBody = await safeJson(emptyStatusRes);
    const emptyItems = extractItems(emptyBody, 'items', 'articles', 'data');
    expect(Array.isArray(emptyItems)).toBe(true);
    const matchingItems = emptyItems.filter(item => (unwrap(item)?.id || item.id) === articleId);
    expect(matchingItems.length, 'filtered result should be empty for non-matching status').toBe(0);
  });
});

import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

function uid(prefix = 'test') {
  return `${prefix}-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
}

async function api(path, options = {}) {
  const res = await fetch(`${BASE_URL}${path}`, {
    headers: { 'Content-Type': 'application/json', ...(options.headers || {}) },
    ...options,
  });
  const text = await res.text();
  let body;
  try { body = text ? JSON.parse(text) : null; } catch { body = text; }
  return { res, body, text };
}

function unwrap(body) {
  return body?.data ?? body;
}

function extractItems(body, ...keys) {
  const source = unwrap(body);
  for (const key of keys) {
    if (source && Array.isArray(source[key])) return source[key];
  }
  if (Array.isArray(source)) return source;
  return [];
}

async function cleanupArticle(id) {
  if (!id) return;
  try { await api(`/api/articles/${id}`, { method: 'DELETE' }); } catch {}
  try { await api(`/api/articles/${id}?permanent=true&confirm=true`, { method: 'DELETE' }); } catch {}
  try { await api(`/api/articles/${id}/permanent`, { method: 'DELETE', body: JSON.stringify({ confirm: true }) }); } catch {}
}

async function cleanup(path) { try { await api(path, { method: 'DELETE' }); } catch {} }

async function tryApi(path, options = {}) {
  let r = await api(path, options);
  if (r.res.status === 404 && !path.startsWith('/api/')) {
    r = await api(`/api${path}`, options);
  } else if (r.res.status === 404 && path.startsWith('/api/')) {
    r = await api(path.replace(/^\/api/, ''), options);
  }
  return r;
}

async function importArchive(archive) {
  let r = await api('/api/import', { method: 'POST', body: JSON.stringify(archive) });
  if (r.res.status === 404) {
    r = await api('/api/import', { method: 'POST', body: JSON.stringify({ archive }) });
  }
  if (r.res.status === 404) {
    r = await api('/import', { method: 'POST', body: JSON.stringify(archive) });
  }
  return r;
}

async function getSubscriptionPreview() {
  let r = await api('/api/subscription/preview');
  if (r.res.status === 404) r = await api('/api/rss/preview');
  if (r.res.status === 404) r = await api('/api/feed/preview');
  return r;
}

async function getSeoPreview() {
  let r = await api('/api/seo/preview');
  if (r.res.status === 404) r = await api('/api/seo/articles');
  return r;
}

describe('legacy_archive_import_migrates_to_current_schema', () => {
  it('should import legacy archive, map single category to primary, fill defaults, and exclude incomplete articles from public previews', async () => {
    const unique = uid('legacy');
    const importedIds = [];

    try {
      // Build a legacy archive with old-format data:
      // - No versions field (old archives didn't have version history)
      // - No publicLinkRules field (old archives didn't have public link rules)
      // - Single category field instead of primaryCategoryId/categoryIds
      const legacyArchive = {
        version: 'legacy-v1',
        articles: [
          {
            title: `Legacy Published NoCat ${unique}`,
            summary: 'legacy summary 1',
            content: 'legacy body 1',
            status: 'published',
            // No category, no publishedAt, no primaryCategory => incomplete for public
            // No versions field
            // No publicLinkRules
          },
          {
            title: `Legacy Draft ${unique}`,
            summary: 'legacy summary 2',
            content: 'legacy body 2',
            status: 'draft',
            category: `Old Single Category ${unique}`,
            // Old-style single category field
            // No versions field
            // No publicLinkRules
          },
        ],
        categories: [
          { name: `Old Single Category ${unique}` },
        ],
        // No publicLinkRules config in legacy archive
        // No versionHistory in legacy archive
      };

      const importRes = await importArchive(legacyArchive);
      expect([200, 201, 207]).toContain(importRes.res.status);
      expect(importRes.body).toBeTruthy();

      const importBody = unwrap(importRes.body) || importRes.body;

      // Verify import result summary exists with recognizable structure
      const hasSummaryInfo = (
        importBody.imported !== undefined ||
        importBody.success !== undefined ||
        importBody.failed !== undefined ||
        importBody.skipped !== undefined ||
        importBody.summary !== undefined ||
        importBody.results !== undefined ||
        importBody.message !== undefined
      );
      expect(hasSummaryInfo, `Import response should contain summary info, got: ${JSON.stringify(importBody)}`).toBe(true);

      // Verify import success counts: both articles should have been imported successfully
      const successCount = importBody.imported ?? importBody.success ??
        importBody.summary?.imported ?? importBody.summary?.success ??
        importBody.results?.success ?? importBody.results?.imported;
      const failCount = importBody.failed ?? importBody.summary?.failed ?? importBody.results?.failed ?? 0;
      if (successCount !== undefined) {
        expect(successCount, 'Both legacy articles should be successfully imported').toBeGreaterThanOrEqual(2);
      }
      expect(failCount, 'No articles should fail to import from a valid legacy archive').toBe(0);

      // Search for imported articles
      let searchRes = await tryApi(`/api/articles?search=${encodeURIComponent(unique)}`);
      if (searchRes.res.status === 404) {
        searchRes = await tryApi(`/api/articles?keyword=${encodeURIComponent(unique)}`);
      }
      expect(searchRes.res.status).toBe(200);
      const searchItems = extractItems(searchRes.body, 'items', 'articles', 'data');

      const importedPublished = searchItems.find(a => String(a.title || '').includes(`Legacy Published NoCat ${unique}`));
      const importedDraft = searchItems.find(a => String(a.title || '').includes(`Legacy Draft ${unique}`));

      expect(importedPublished, `Published article should exist after import, search results: ${JSON.stringify(searchItems.map(i => i.title))}`).toBeTruthy();
      expect(importedDraft, `Draft article should exist after import, search results: ${JSON.stringify(searchItems.map(i => i.title))}`).toBeTruthy();

      if (importedPublished?.id) importedIds.push(importedPublished.id);
      if (importedDraft?.id) importedIds.push(importedDraft.id);

      // Verify statuses preserved
      expect(importedPublished.status).toBe('published');
      expect(importedDraft.status).toBe('draft');

      // Verify draft article with legacy single category got mapped to primary
      const draftDetail = await tryApi(`/api/articles/${importedDraft.id}`);
      expect(draftDetail.res.status).toBe(200);
      const dd = unwrap(draftDetail.body) || draftDetail.body;

      // Legacy single category should become primaryCategory
      const hasPrimaryCategory = (
        dd.primaryCategoryId ||
        dd.primaryCategory ||
        (Array.isArray(dd.categories) && dd.categories.some(c => c.isPrimary || c.primary))
      );
      expect(hasPrimaryCategory, `Legacy single category should be mapped to primary category. Article detail: ${JSON.stringify(dd)}`).toBeTruthy();

      // Verify default fields were filled in
      const hasEditorMode = dd.editorMode !== undefined || dd.editor_mode !== undefined || dd.editMode !== undefined;
      expect(hasEditorMode, `Default editorMode should be filled for legacy article. Detail: ${JSON.stringify(dd)}`).toBe(true);

      // Verify the category name matches
      if (Array.isArray(dd.categories) && dd.categories.length > 0) {
        const catName = dd.categories[0].name || dd.categories[0].title || '';
        expect(catName).toContain(`Old Single Category ${unique}`);
      }

      // Verify SEO default fields are filled (fallback rule: use article title/summary/tags)
      const draftSeo = dd.seo || {};
      const seoTitle = draftSeo.title || draftSeo.seoTitle;
      const seoDescription = draftSeo.description || draftSeo.seoDescription;
      // If SEO fields exist, they should have been defaulted from article fields
      if (seoTitle !== undefined || seoDescription !== undefined) {
        // SEO title defaults to article title if not set
        if (seoTitle) {
          expect(String(seoTitle)).toContain(`Legacy Draft ${unique}`);
        }
      }

      // Published article has no category and likely no publishedAt => incomplete for public
      const pubDetail = await tryApi(`/api/articles/${importedPublished.id}`);
      expect(pubDetail.res.status).toBe(200);
      const pd = unwrap(pubDetail.body) || pubDetail.body;
      // Should also have default editorMode filled
