      expect(pubHasEditorMode, `Default editorMode should be filled for legacy published article. Detail: ${JSON.stringify(pd)}`).toBe(true);

      // Verify RSS/subscription preview excludes incomplete articles
      const rssPreviewRes = await getSubscriptionPreview();
      expect(rssPreviewRes.res.status, `RSS/subscription preview endpoint should be available. Tried multiple paths.`).toBe(200);
      const rssItems = extractItems(rssPreviewRes.body, 'items', 'articles', 'data');
      const rssTitles = rssItems.map(i => i.title || '');
      // Draft should never be in RSS
      expect(rssTitles).not.toContain(`Legacy Draft ${unique}`);
      // Published without category/publishedAt should be excluded
      const pubInRss = rssTitles.some(t => t.includes(`Legacy Published NoCat ${unique}`));
      expect(pubInRss, 'Incomplete published article should not appear in RSS preview').toBe(false);

      // Check excluded count if available
      const rssBody = unwrap(rssPreviewRes.body) || rssPreviewRes.body;
      const rssExcludedCount = rssBody?.excludedCount ?? rssBody?.summary?.excludedCount ?? rssBody?.excluded;
      if (typeof rssExcludedCount === 'number') {
        expect(rssExcludedCount).toBeGreaterThanOrEqual(1);
      }

      // Verify SEO preview also excludes incomplete articles
      const seoPreviewRes = await getSeoPreview();
      expect(seoPreviewRes.res.status, `SEO preview endpoint should be available. Tried multiple paths.`).toBe(200);
      const seoItems = extractItems(seoPreviewRes.body, 'items', 'articles', 'data');
      const seoTitles = seoItems.map(i => i.title || '');
      expect(seoTitles).not.toContain(`Legacy Draft ${unique}`);
      const pubInSeo = seoTitles.some(t => t.includes(`Legacy Published NoCat ${unique}`));
      expect(pubInSeo, 'Incomplete published article should not appear in SEO preview').toBe(false);

      const seoBody = unwrap(seoPreviewRes.body) || seoPreviewRes.body;
      const seoExcludedCount = seoBody?.excludedCount ?? seoBody?.summary?.excludedCount ?? seoBody?.excluded;
      if (typeof seoExcludedCount === 'number') {
        expect(seoExcludedCount).toBeGreaterThanOrEqual(1);
      }

      // Version history should be accessible (even if empty for legacy)
      const draftVersions = await tryApi(`/api/articles/${importedDraft.id}/versions`);
      // Legacy articles have no version history but import should still succeed
      expect([200, 404]).toContain(draftVersions.res.status);
      if (draftVersions.res.status === 200) {
        const versionItems = extractItems(draftVersions.body, 'versions', 'items', 'data');
        expect(Array.isArray(versionItems)).toBe(true);
        // Legacy import should not have generated spurious version records
      }

      // Verify public link preview handles legacy articles correctly
      const pubLinkPreview = await tryApi(`/api/articles/${importedPublished.id}/public-link`);
      if (pubLinkPreview.res.status === 200) {
        const linkData = unwrap(pubLinkPreview.body) || pubLinkPreview.body;
        // Incomplete published article should not have a valid public link
        const isAvailable = linkData?.available ?? linkData?.isPublic ?? linkData?.accessible;
        if (isAvailable !== undefined) {
          expect(isAvailable, 'Incomplete published article should not be publicly accessible').toBe(false);
        }
      }
    } finally {
      for (const id of importedIds) {
        await cleanupArticle(id);
      }
      try {
        let searchRes = await tryApi(`/api/articles?search=${encodeURIComponent(unique)}`);
        if (searchRes.res.status === 404) {
          searchRes = await tryApi(`/api/articles?keyword=${encodeURIComponent(unique)}`);
        }
        const items = extractItems(searchRes.body, 'items', 'articles', 'data');
        for (const item of items) await cleanupArticle(item.id);
      } catch {}
      try {
        let catRes = await tryApi(`/api/categories?search=${encodeURIComponent(unique)}`);
        if (catRes.res.status === 404) {
          catRes = await tryApi(`/api/categories?keyword=${encodeURIComponent(unique)}`);
        }
        const cats = extractItems(catRes.body, 'items', 'categories', 'data');
        for (const c of cats) await cleanup(`/api/categories/${c.id}`);
      } catch {}
    }
  });
});

import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function request(method, path, body) {
  const res = await fetch(`${BASE_URL}${path}`, {
    method,
    headers: body !== undefined ? { 'Content-Type': 'application/json' } : undefined,
    body: body !== undefined ? JSON.stringify(body) : undefined,
  });
  const text = await res.text();
  let json;
  try {
    json = text ? JSON.parse(text) : null;
  } catch {
    json = text;
  }
  return { res, body: json };
}

function asArray(body) {
  if (Array.isArray(body)) return body;
  if (Array.isArray(body?.items)) return body.items;
  if (Array.isArray(body?.data)) return body.data;
  if (Array.isArray(body?.articles)) return body.articles;
  return [];
}

function getId(body) {
  return body?.id || body?.data?.id;
}

async function safeDelete(path) {
  try {
    await fetch(`${BASE_URL}${path}`, { method: 'DELETE' });
  } catch {}
}

describe('article_filters_apply_combined_criteria', () => {
  it('should apply combined keyword/category/tag/status filters, match keyword in content, require all selected tags, and treat whitespace keyword as no keyword filter', async () => {
    const suffix = `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
    const categoryIds = [];
    const tagIds = [];
    const articleIds = [];

    try {
      // Create two categories
      for (const name of [`filter-cat-a-${suffix}`, `filter-cat-b-${suffix}`]) {
        const c = await request('POST', '/api/categories', { name });
        expect([200, 201].includes(c.res.status), `expected category create success, got ${c.res.status} ${JSON.stringify(c.body)}`).toBe(true);
        categoryIds.push(getId(c.body));
      }

      // Create three tags
      for (const name of [`filter-tag-a-${suffix}`, `filter-tag-b-${suffix}`, `filter-tag-c-${suffix}`]) {
        const t = await request('POST', '/api/tags', { name });
        expect([200, 201].includes(t.res.status), `expected tag create success, got ${t.res.status} ${JSON.stringify(t.body)}`).toBe(true);
        tagIds.push(getId(t.body));
      }

      const uniqueKeyword = `kwbody${suffix}`;

      // article1: keyword in both summary and content, has both selected tags (tag0+tag1), category[0], published
      const article1 = await request('POST', '/api/articles', {
        title: `UniqueTitle-${suffix}`,
        summary: `contains ${uniqueKeyword} summary`,
        content: `body with visible ${uniqueKeyword} and beta`,
        status: 'published',
        publishedAt: new Date().toISOString(),
        primaryCategoryId: categoryIds[0],
        categoryIds: [categoryIds[0]],
        tagIds: [tagIds[0], tagIds[1]],
      });
      expect([200, 201].includes(article1.res.status), `expected article1 create success, got ${article1.res.status}`).toBe(true);
      articleIds.push(getId(article1.body));

      // article2: no keyword, draft, category[0], tag0 only
      const article2 = await request('POST', '/api/articles', {
        title: `OtherTitle-${suffix}`,
        summary: 'different summary',
        content: 'body with beta only',
        status: 'draft',
        primaryCategoryId: categoryIds[0],
        categoryIds: [categoryIds[0]],
        tagIds: [tagIds[0]],
      });
      expect([200, 201].includes(article2.res.status), `expected article2 create success, got ${article2.res.status}`).toBe(true);
      articleIds.push(getId(article2.body));

      // article3: keyword in summary, WRONG category (category[1]), published, all 3 tags
      const article3 = await request('POST', '/api/articles', {
        title: `ThirdTitle-${suffix}`,
        summary: `${uniqueKeyword} elsewhere`,
        content: 'gamma',
        status: 'published',
        publishedAt: new Date().toISOString(),
        primaryCategoryId: categoryIds[1],
        categoryIds: [categoryIds[1]],
        tagIds: [tagIds[0], tagIds[1], tagIds[2]],
      });
      expect([200, 201].includes(article3.res.status), `expected article3 create success, got ${article3.res.status}`).toBe(true);
      articleIds.push(getId(article3.body));

      // article4: keyword ONLY in content, published, category[0], both tags (tag0+tag1)
      const contentOnlyKeyword = `bodyonly${suffix}`;
      const article4 = await request('POST', '/api/articles', {
        title: `NoKwTitle-${suffix}`,
        summary: 'plain summary without it',
        content: `visible body contains ${contentOnlyKeyword} term`,
        status: 'published',
        publishedAt: new Date().toISOString(),
        primaryCategoryId: categoryIds[0],
        categoryIds: [categoryIds[0]],
        tagIds: [tagIds[0], tagIds[1]],
      });
      expect([200, 201].includes(article4.res.status), `expected article4 create success, got ${article4.res.status}`).toBe(true);
      articleIds.push(getId(article4.body));

      // article5: keyword in title, published, category[0], only ONE tag (tag0) - missing tag1
      const article5 = await request('POST', '/api/articles', {
        title: `SingleTagTitle-${uniqueKeyword}-${suffix}`,
        summary: 'single tag summary',
        content: 'arbitrary content',
        status: 'published',
        publishedAt: new Date().toISOString(),
        primaryCategoryId: categoryIds[0],
        categoryIds: [categoryIds[0]],
        tagIds: [tagIds[0]],
      });
      expect([200, 201].includes(article5.res.status), `expected article5 create success, got ${article5.res.status}`).toBe(true);
      articleIds.push(getId(article5.body));

      // Combined filter: search=uniqueKeyword, categoryId=category[0], tagIds=tag0+tag1 (AND), status=published
      const filtered = await request(
        'GET',
        `/api/articles?search=${encodeURIComponent(uniqueKeyword)}&categoryId=${encodeURIComponent(categoryIds[0])}&tagIds=${encodeURIComponent(tagIds[0])},${encodeURIComponent(tagIds[1])}&status=published`
      );
      expect(filtered.res.status, `expected filtered list success, got ${filtered.res.status}`).toBe(200);
      const filteredIds = asArray(filtered.body).map(item => item.id);
      // article1: matches keyword + category + both tags + published -> included
      expect(filteredIds.includes(articleIds[0]), `expected article1 in combined filter result`).toBe(true);
      // article2: draft -> excluded
      expect(filteredIds.includes(articleIds[1]), `expected article2 excluded (draft)`).toBe(false);
      // article3: wrong category -> excluded
      expect(filteredIds.includes(articleIds[2]), `expected article3 excluded (wrong category)`).toBe(false);
      // article5: missing tag1 (AND semantics) -> excluded
      expect(filteredIds.includes(articleIds[4]), `expected article5 excluded (missing tag, AND semantics)`).toBe(false);

      // Verify keyword matches content visible text (Round 27 full-text search)
      const contentOnlySearch = await request(
        'GET',
        `/api/articles?search=${encodeURIComponent(contentOnlyKeyword)}&status=published`
      );
      expect(contentOnlySearch.res.status).toBe(200);
      const contentOnlyIds = asArray(contentOnlySearch.body).map(item => item.id);
      expect(contentOnlyIds.includes(articleIds[3]), `expected keyword search to match content visible text (article4)`).toBe(true);

      // Verify tag AND semantics: category[0] + tag0+tag1 + published -> only article1 and article4
      const andTagFilter = await request(
        'GET',
        `/api/articles?categoryId=${encodeURIComponent(categoryIds[0])}&tagIds=${encodeURIComponent(tagIds[0])},${encodeURIComponent(tagIds[1])}&status=published`
      );
      expect(andTagFilter.res.status).toBe(200);
      const andTagIds = asArray(andTagFilter.body).map(item => item.id);
      expect(andTagIds.includes(articleIds[0]), 'article1 has both selected tags').toBe(true);
      expect(andTagIds.includes(articleIds[3]), 'article4 has both selected tags').toBe(true);
      expect(andTagIds.includes(articleIds[4]), 'article5 has only one tag, excluded under AND semantics').toBe(false);

      // Whitespace keyword should be treated as no keyword filter
      const whitespaceKeyword = await request(
        'GET',
        `/api/articles?search=${encodeURIComponent('   ')}&categoryId=${encodeURIComponent(categoryIds[0])}&status=draft`
      );
      expect(whitespaceKeyword.res.status).toBe(200);
      const whitespaceIds = asArray(whitespaceKeyword.body).map(item => item.id);
      // article2 is draft in category[0] -> should appear when whitespace = no keyword
      expect(whitespaceIds.includes(articleIds[1]), `expected whitespace keyword to behave as no keyword filter`).toBe(true);
      // article1 is published -> should NOT appear when status=draft
      expect(whitespaceIds.includes(articleIds[0]), `expected status filter to exclude published articles`).toBe(false);

      // Pure whitespace search without other filters returns all
      const pureWhitespace = await request('GET', `/api/articles?search=${encodeURIComponent('   ')}`);
      expect(pureWhitespace.res.status).toBe(200);
      const pureWsItems = asArray(pureWhitespace.body);
      // Should return at least all 5 created articles (like no search)
      for (const id of articleIds) {
        expect(pureWsItems.some(p => p.id === id), `pure whitespace search should include article ${id}`).toBe(true);
      }
    } finally {
      for (const id of articleIds) {
        if (id) await safeDelete(`/api/articles/${id}`);
      }
      for (const id of tagIds) {
        if (id) await safeDelete(`/api/tags/${id}`);
      }
      for (const id of categoryIds) {
        if (id) await safeDelete(`/api/categories/${id}`);
      }
    }
  });
});

import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

function uid(prefix = 'test') {
  return `${prefix}-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
}

function slugify(v) {
  return String(v).toLowerCase().trim().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');
}

async function api(path, options = {}) {
  const res = await fetch(`${BASE_URL}${path}`, {
    headers: { 'Content-Type': 'application/json', ...(options.headers || {}) },
    ...options,
  });
  const text = await res.text();
  let body;
  try { body = text ? JSON.parse(text) : null; } catch { body = text; }
  return { res, body, text };
}

function unwrap(body) {
  return body?.data ?? body;
}

function extractItems(body, ...keys) {
  const source = unwrap(body);
  for (const key of keys) {
    if (source && Array.isArray(source[key])) return source[key];
  }
  if (Array.isArray(source)) return source;
  return [];
}

async function cleanup(path) { try { await api(path, { method: 'DELETE' }); } catch {} }

async function exportArchive() {
  return api('/api/export', { method: 'POST' });
}

async function importArchive(archive) {
  return api('/api/import', { method: 'POST', body: JSON.stringify({ archive }) });
}

async function getSubscriptionPreview() {
  return api('/api/subscription/preview');
}

async function getRssConfig() {
  return api('/api/subscription/config');
}

async function putRssConfig(payload) {
  return api('/api/subscription/config', { method: 'PUT', body: JSON.stringify(payload) });
}

async function getSeoConfig() {
  return api('/api/seo/config');
}

async function putSeoConfig(payload) {
  return api('/api/seo/config', { method: 'PUT', body: JSON.stringify(payload) });
}

async function getSeoPreview() {
  return api('/api/seo/preview');
}

function rssSnapshot(body) {
  const source = unwrap(body) || body?.config || {};
  return {
    title: source.title,
    description: source.description,
    siteUrl: source.siteUrl,
    feedUrl: source.feedUrl,
    articleCount: source.articleCount,
  };
}

function seoSnapshot(body) {
  const source = unwrap(body) || body?.config || {};
  return {
    siteTitle: source.siteTitle,
    siteDescription: source.siteDescription,
    defaultKeywords: source.defaultKeywords,
    siteCoverUrl: source.siteCoverUrl,
  };
}

