import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

function uid(prefix = 'test') {
  return `${prefix}-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
}

async function api(path, options = {}) {
  const res = await fetch(`${BASE_URL}${path}`, {
    headers: { 'Content-Type': 'application/json', ...(options.headers || {}) },
    ...options,
  });
  const text = await res.text();
  let body;
  try { body = text ? JSON.parse(text) : null; } catch { body = text; }
  return { res, body, text };
}

async function createCategory(name) {
  const { res, body } = await api('/api/categories', { method: 'POST', body: JSON.stringify({ name, slug: name.toLowerCase().replace(/[^a-z0-9]+/g, '-') }) });
  expect(res.status).toBeGreaterThanOrEqual(200);
  expect(res.status).toBeLessThan(300);
  return body;
}

async function createArticle(payload) {
  const { res, body } = await api('/api/articles', { method: 'POST', body: JSON.stringify(payload) });
  expect(res.status).toBeGreaterThanOrEqual(200);
  expect(res.status).toBeLessThan(300);
  return body;
}

async function cleanup(path) { try { await api(path, { method: 'DELETE' }); } catch {} }

async function trashArticle(id) {
  // Try PATCH first
  let result = await api(`/api/articles/${id}`, { method: 'PATCH', body: JSON.stringify({ isInTrash: true }) });
  if (result.res.status >= 200 && result.res.status < 300) return result;
  // Fallback: try DELETE (soft delete)
  result = await api(`/api/articles/${id}/trash`, { method: 'POST' });
  if (result.res.status >= 200 && result.res.status < 300) return result;
  // Fallback: try PATCH with different field name
  result = await api(`/api/articles/${id}`, { method: 'PATCH', body: JSON.stringify({ inRecycleBin: true, deleted: true }) });
  return result;
}

async function restoreArticle(id) {
  // Try POST restore endpoint
  let result = await api(`/api/articles/${id}/restore`, { method: 'POST' });
  if (result.res.status >= 200 && result.res.status < 300) return result;
  // Fallback: try PATCH
  result = await api(`/api/articles/${id}`, { method: 'PATCH', body: JSON.stringify({ isInTrash: false, inRecycleBin: false, deleted: false }) });
  return result;
}

function extractItems(body, ...keys) {
  for (const key of keys) {
    if (body && Array.isArray(body[key])) return body[key];
  }
  if (Array.isArray(body)) return body;
  return [];
}

function findArticleInList(items, articleId, titleFragment) {
  return items.some((x) => x.id === articleId || (titleFragment && String(x.title || '').includes(titleFragment)));
}

describe('trash_move_isolates_and_restore_reappears', () => {
  it('should disappear from normal list/subscription/seo/sitemap/stats after trash move and reappear after restore if still public', async () => {
    const suffix = uid('trash-isolate');
    let category, article;

    try {
      category = await createCategory(`Cat ${suffix}`);
      article = await createArticle({
        title: `Public article ${suffix}`,
        content: 'body content for testing',
        summary: 'summary for testing',
        status: 'published',
        publishedAt: '2024-07-01T10:00:00.000Z',
        categoryId: category.id,
        primaryCategoryId: category.id,
        primaryCategory: { id: category.id, name: `Cat ${suffix}` },
        visibility: 'public',
        isInTrash: false,
      });

      // --- Baseline: article appears everywhere ---
      const baselineList = await api(`/api/articles?search=${encodeURIComponent(suffix)}`);
      expect(baselineList.res.status).toBe(200);
      const baselineItems = extractItems(baselineList.body, 'items', 'articles', 'data');
      expect(findArticleInList(baselineItems, article.id, suffix)).toBe(true);

      const baselineSub = await api('/api/subscription/preview');
      const baselineSubItems = extractItems(baselineSub.body, 'items', 'articles', 'data');

      const baselineSeo = await api('/api/seo/preview');
      const baselineSeoItems = extractItems(baselineSeo.body, 'items', 'articles', 'data');

      const baselineMap = await api('/api/sitemap');

      const baselineStats = await api('/api/stats');
      expect(baselineStats.res.status).toBe(200);
      // Validate stats has meaningful structure
      expect(baselineStats.body).toBeTruthy();
      const statsBody1 = baselineStats.body;
      const publishedCount1 = statsBody1.publishedCount ?? statsBody1.published ?? statsBody1.publishedArticles ?? 0;
      const trashCount1 = statsBody1.trashCount ?? statsBody1.recycleBinCount ?? statsBody1.recycled ?? statsBody1.trashedCount ?? 0;

      // --- Move to trash ---
      const moveResult = await trashArticle(article.id);
      expect(moveResult.res.status).toBeGreaterThanOrEqual(200);
      expect(moveResult.res.status).toBeLessThan(300);

      // Article should NOT appear in normal list
      const normalList = await api(`/api/articles?search=${encodeURIComponent(suffix)}`);
      const normalItems = extractItems(normalList.body, 'items', 'articles', 'data');
      expect(findArticleInList(normalItems, article.id, suffix),
        `trashed article should be hidden from normal list: ${JSON.stringify(normalList.body)}`
      ).toBe(false);

      // Article should NOT appear in subscription preview
      const sub = await api('/api/subscription/preview');
      const subItems = extractItems(sub.body, 'items', 'articles', 'data');
      expect(findArticleInList(subItems, article.id, `Public article ${suffix}`),
        `trashed article should be hidden from subscription preview`
      ).toBe(false);

      // Article should NOT appear in SEO preview
      const seo = await api('/api/seo/preview');
      const seoItems = extractItems(seo.body, 'items', 'articles', 'data');
      expect(findArticleInList(seoItems, article.id, `Public article ${suffix}`),
        `trashed article should be hidden from seo preview`
      ).toBe(false);

      // Article should NOT appear in sitemap
      const map = await api('/api/sitemap');
      const mapStr = typeof map.body === 'string' ? map.body : JSON.stringify(map.body);
      expect(mapStr.includes(suffix),
        `trashed article should be removed from sitemap`
      ).toBe(false);

      // Stats should reflect the change with concrete numeric assertions
      const statsAfterTrash = await api('/api/stats');
      expect(statsAfterTrash.res.status).toBe(200);
      const statsBody2 = statsAfterTrash.body;
      expect(statsBody2).toBeTruthy();
      const trashCount2 = statsBody2.trashCount ?? statsBody2.recycleBinCount ?? statsBody2.recycled ?? statsBody2.trashedCount ?? 0;
      expect(trashCount2).toBeGreaterThan(trashCount1);

      // --- Restore from trash ---
      const restoreResult = await restoreArticle(article.id);
      expect(restoreResult.res.status).toBeGreaterThanOrEqual(200);
      expect(restoreResult.res.status).toBeLessThan(300);

      // Article should reappear in normal list
      const restoredList = await api(`/api/articles?search=${encodeURIComponent(suffix)}`);
      const restoredItems = extractItems(restoredList.body, 'items', 'articles', 'data');
      expect(findArticleInList(restoredItems, article.id, suffix),
        `restored article should reappear in normal list: ${JSON.stringify(restoredList.body)}`
      ).toBe(true);

      // Article should reappear in subscription preview
      const restoredSub = await api('/api/subscription/preview');
      const restoredSubItems = extractItems(restoredSub.body, 'items', 'articles', 'data');
      expect(findArticleInList(restoredSubItems, article.id, `Public article ${suffix}`),
        `restored article should reappear in subscription preview`
      ).toBe(true);

      // Article should reappear in SEO preview
      const restoredSeo = await api('/api/seo/preview');
      const restoredSeoItems = extractItems(restoredSeo.body, 'items', 'articles', 'data');
      expect(findArticleInList(restoredSeoItems, article.id, `Public article ${suffix}`),
        `restored article should reappear in seo preview`
      ).toBe(true);

      // Article should reappear in sitemap
      const restoredMap = await api('/api/sitemap');
      const restoredMapStr = typeof restoredMap.body === 'string' ? restoredMap.body : JSON.stringify(restoredMap.body);
      expect(restoredMapStr.includes(suffix),
        `restored article should reappear in sitemap`
      ).toBe(true);

      // Stats should reflect restore
      const statsAfterRestore = await api('/api/stats');
      const statsBody3 = statsAfterRestore.body;
      const trashCount3 = statsBody3.trashCount ?? statsBody3.recycleBinCount ?? statsBody3.recycled ?? statsBody3.trashedCount ?? 0;
      expect(trashCount3).toBeLessThan(trashCount2);
    } finally {
      await cleanup(article?.id ? `/api/articles/${article.id}` : '');
      await cleanup(category?.id ? `/api/categories/${category.id}` : '');
    }
  });

  it('should NOT reappear in subscription/seo/sitemap after restore if article does not meet public conditions', async () => {
    const suffix = uid('trash-nopub');
    let article;

    try {
      // Create an article that is published but missing primary category and publishedAt
      // so it does NOT satisfy public conditions
      article = await createArticle({
        title: `Incomplete article ${suffix}`,
        content: 'body content',
        status: 'published',
        // No publishedAt
        // No categoryId / primaryCategoryId
        isInTrash: false,
      });

      // Move to trash
      const moveResult = await trashArticle(article.id);
      expect(moveResult.res.status).toBeGreaterThanOrEqual(200);
      expect(moveResult.res.status).toBeLessThan(300);

      // Restore
      const restoreResult = await restoreArticle(article.id);
      expect(restoreResult.res.status).toBeGreaterThanOrEqual(200);
      expect(restoreResult.res.status).toBeLessThan(300);

      // Should appear in normal list (restored)
      const restoredList = await api(`/api/articles?search=${encodeURIComponent(suffix)}`);
      const restoredItems = extractItems(restoredList.body, 'items', 'articles', 'data');
      expect(findArticleInList(restoredItems, article.id, suffix),
        `restored article should appear in normal list even if not public-eligible`
      ).toBe(true);

      // Should NOT appear in subscription preview (missing public conditions)
      const sub = await api('/api/subscription/preview');
      const subItems = extractItems(sub.body, 'items', 'articles', 'data');
      expect(findArticleInList(subItems, article.id, `Incomplete article ${suffix}`),
        `restored article missing public conditions should NOT appear in subscription preview`
      ).toBe(false);

      // Should NOT appear in SEO preview
      const seo = await api('/api/seo/preview');
      const seoItems = extractItems(seo.body, 'items', 'articles', 'data');
      expect(findArticleInList(seoItems, article.id, `Incomplete article ${suffix}`),
        `restored article missing public conditions should NOT appear in seo preview`
      ).toBe(false);

      // Should NOT appear in sitemap
      const map = await api('/api/sitemap');
      const mapStr = typeof map.body === 'string' ? map.body : JSON.stringify(map.body);
      expect(mapStr.includes(suffix),
        `restored article missing public conditions should NOT appear in sitemap`
      ).toBe(false);
    } finally {
      await cleanup(article?.id ? `/api/articles/${article.id}` : '');
    }
  });
});

import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function request(method, path, body) {
  const res = await fetch(`${BASE_URL}${path}`, {
    method,
    headers: { 'Content-Type': 'application/json' },
    body: body === undefined ? undefined : JSON.stringify(body),
  });
  const text = await res.text();
  let data = null;
  try {
    data = text ? JSON.parse(text) : null;
  } catch {
    data = text;
  }
  return { res, data };
}

async function tryRequest(method, path, body) {
  let r = await request(method, path, body);
  if (r.res.status === 404 && !path.startsWith('/api/')) {
    r = await request(method, `/api${path}`, body);
  } else if (r.res.status === 404 && path.startsWith('/api/')) {
    r = await request(method, path.replace(/^\/api/, ''), body);
  }
  return r;
}

async function safeDelete(path) {
  try { await fetch(`${BASE_URL}${path}`, { method: 'DELETE' }); } catch {}
  try { await fetch(`${BASE_URL}/api${path}`, { method: 'DELETE' }); } catch {}
}

function unwrap(data) {
  return data?.data ?? data;
}

function textOf(value) {
  return typeof value === 'string' ? value : JSON.stringify(value || {});
}

function getField(data, ...names) {
  const d = unwrap(data);
  for (const name of names) {
    if (d && d[name] != null) return d[name];
  }
  return undefined;
}

async function createCategory(name) {
  let r = await tryRequest('POST', '/api/categories', { name });
  if (r.res.status >= 200 && r.res.status < 300) {
    return unwrap(r.data)?.id || r.data?.id;
  }
  return null;
}

async function createArticle(payload) {
  let r = await tryRequest('POST', '/api/articles', payload);
  if (r.res.status >= 200 && r.res.status < 300) {
    return unwrap(r.data) || r.data;
  }
  return null;
}

// Resolve the correct share preview path for an article
const SHARE_PREVIEW_PATHS = [
  (id) => `/api/articles/${id}/seo/share-preview`,
  (id) => `/api/articles/${id}/share-preview`,
  (id) => `/api/seo/articles/${id}/share-preview`,
];

let resolvedSharePreviewPathFn = null;

async function getArticleSharePreview(id) {
  if (resolvedSharePreviewPathFn) {
    return tryRequest('GET', resolvedSharePreviewPathFn(id));
  }
  for (const pathFn of SHARE_PREVIEW_PATHS) {
    const r = await tryRequest('GET', pathFn(id));
    if (r.res.status !== 404) {
      resolvedSharePreviewPathFn = pathFn;
      return r;
    }
  }
  // fallback
  resolvedSharePreviewPathFn = SHARE_PREVIEW_PATHS[0];
  return tryRequest('GET', resolvedSharePreviewPathFn(id));
}

