        const longDetail = await tryRequest('GET', `/api/articles/${longPost.id}`);
        expect(longDetail.res.status).toBe(200);
        const ld = unwrap(longDetail.data);
        const storedSeo = ld?.seo || {};
        const storedTitle = storedSeo.title || storedSeo.socialTitle || storedSeo.ogTitle || '';
        const storedDesc = storedSeo.description || storedSeo.socialDescription || storedSeo.ogDescription || '';
        if (storedTitle) {
          expect(storedTitle, 'original SEO title should be stored without truncation').toBe(longTitle);
        }
        if (storedDesc) {
          expect(storedDesc, 'original SEO description should be stored without truncation').toBe(longDescription);
        }
      }

      // --- Verify non-public articles are blocked from share preview ---
      const blockedArticles = [
        { id: draft?.id, label: 'draft' },
        { id: archived?.id, label: 'archived' },
        { id: trashed?.id, label: 'trashed' },
      ];

      for (const blocked of blockedArticles) {
        if (!blocked.id) continue;
        const blockedPreview = await getArticleSharePreview(blocked.id);

        const payloadText = JSON.stringify(blockedPreview.data || {});
        // Should either return error status or flag as unavailable in body
        const isBlocked = (
          blockedPreview.res.status === 403 ||
          blockedPreview.res.status === 404 ||
          blockedPreview.res.status === 409 ||
          blockedPreview.res.status === 422 ||
          (unwrap(blockedPreview.data))?.available === false ||
          (unwrap(blockedPreview.data))?.isPublic === false ||
          (unwrap(blockedPreview.data))?.excluded === true ||
          (unwrap(blockedPreview.data))?.shareable === false ||
          ((unwrap(blockedPreview.data))?.reason && blockedPreview.res.status === 200)
        );
        expect(isBlocked, `${blocked.label} article should not generate a formal share preview. Status: ${blockedPreview.res.status}, body: ${payloadText}`).toBe(true);

        // Should explain why preview is unavailable
        if (blockedPreview.res.status !== 404) {
          const hasExplanation = /reason|message|error|draft|archived|archive|trash|recycle|deleted|not.?public|unavailable|blocked|cannot/i.test(payloadText);
          expect(hasExplanation, `${blocked.label} blocked preview should explain reason. Got: ${payloadText}`).toBe(true);
        }
      }
    } finally {
      for (const id of ids) {
        await safeDelete(`/api/articles/${id}`);
        try { await request('DELETE', `/api/articles/${id}?permanent=true&confirm=true`); } catch {}
        try { await request('DELETE', `/api/articles/${id}/permanent`); } catch {}
      }
      for (const id of catIds) {
        await safeDelete(`/api/categories/${id}`);
      }
    }
  });
});

