function extractId(body) {
  return body?.id || body?.articleId || body?.data?.id;
}

function asArray(v) {
  return Array.isArray(v) ? v : Array.isArray(v?.items) ? v.items : Array.isArray(v?.data) ? v.data : [];
}

function findReasonCounts(body) {
  return body?.reasonCounts || body?.reasons || body?.summary || body?.excludedReasonCounts || body?.counts || body?.exclusionReasons || body?.excludedReasons || body?.excluded;
}

function extractExcludedCount(body) {
  const rc = findReasonCounts(body);
  if (rc && typeof rc === 'object' && !Array.isArray(rc)) {
    const vals = Object.values(rc).filter(v => typeof v === 'number');
    if (vals.length > 0) return vals.reduce((s, n) => s + n, 0);
  }
  return body?.excludedCount || body?.excluded_count || body?.totalExcluded || 0;
}

describe('round17_public_preview_eligibility', () => {
  it('should include only eligible published articles in RSS and SEO public preview, exclude draft and incomplete articles, provide exclusion reason counts, and update after fixing articles', async () => {
    const unique = `elig-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
    const categoryIds = [];
    const articleIds = [];

    try {
      // Create a category
      const category = await request('POST', '/api/categories', { name: `EligCat ${unique}` });
      expect([200, 201]).toContain(category.res.status);
      const categoryId = extractId(category.body);
      categoryIds.push(categoryId);
      expect(categoryId).toBeTruthy();

      // 1. Create a fully eligible published article
      const eligible = await request('POST', '/api/articles', {
        title: `Eligible ${unique}`,
        content: 'This is valid body content',
        status: 'published',
        publishTime: '2024-04-01T10:00:00.000Z',
        publishedAt: '2024-04-01T10:00:00.000Z',
        primaryCategoryId: categoryId,
        categoryIds: [categoryId],
      });
      expect([200, 201]).toContain(eligible.res.status);
      const eligibleId = extractId(eligible.body);
      articleIds.push(eligibleId);
      expect(eligibleId).toBeTruthy();

      // 2. Create a DRAFT article with all fields complete — should NOT be in public preview
      const draftComplete = await request('POST', '/api/articles', {
        title: `Draft Complete ${unique}`,
        content: 'This draft has everything but is not published',
        status: 'draft',
        publishTime: '2024-04-01T10:30:00.000Z',
        publishedAt: '2024-04-01T10:30:00.000Z',
        primaryCategoryId: categoryId,
        categoryIds: [categoryId],
      });
      expect([200, 201]).toContain(draftComplete.res.status);
      const draftCompleteId = extractId(draftComplete.body);
      articleIds.push(draftCompleteId);

      // 3. Published article then clear content (missing body)
      const missingBodyArt = await request('POST', '/api/articles', {
        title: `Missing Body ${unique}`,
        content: 'temporary body',
        status: 'published',
        publishTime: '2024-04-01T11:00:00.000Z',
        publishedAt: '2024-04-01T11:00:00.000Z',
        primaryCategoryId: categoryId,
        categoryIds: [categoryId],
      });
      expect([200, 201]).toContain(missingBodyArt.res.status);
      const missingBodyId = extractId(missingBodyArt.body);
      articleIds.push(missingBodyId);
      const clearBodyRes = await request('PATCH', `/api/articles/${missingBodyId}`, { content: '' });
      // Check if the PATCH succeeded
      const clearBodySucceeded = [200, 204].includes(clearBodyRes.res.status);

      // 4. Published article then clear publish time
      const missingTimeArt = await request('POST', '/api/articles', {
        title: `Missing PublishTime ${unique}`,
        content: 'valid body content',
        status: 'published',
        publishTime: '2024-04-01T12:00:00.000Z',
        publishedAt: '2024-04-01T12:00:00.000Z',
        primaryCategoryId: categoryId,
        categoryIds: [categoryId],
      });
      expect([200, 201]).toContain(missingTimeArt.res.status);
      const missingTimeId = extractId(missingTimeArt.body);
      articleIds.push(missingTimeId);
      const clearTimeRes = await request('PATCH', `/api/articles/${missingTimeId}`, { publishTime: null, publishedAt: null });
      const clearTimeSucceeded = [200, 204].includes(clearTimeRes.res.status);

      // 5. Published article then remove primary category
      const missingCatArt = await request('POST', '/api/articles', {
        title: `Missing Category ${unique}`,
        content: 'valid body content',
        status: 'published',
        publishTime: '2024-04-01T13:00:00.000Z',
        publishedAt: '2024-04-01T13:00:00.000Z',
        primaryCategoryId: categoryId,
        categoryIds: [categoryId],
      });
      expect([200, 201]).toContain(missingCatArt.res.status);
      const missingCatId = extractId(missingCatArt.body);
      articleIds.push(missingCatId);
      const clearCatRes = await request('PATCH', `/api/articles/${missingCatId}`, { primaryCategoryId: null, categoryIds: [] });
      const clearCatSucceeded = [200, 204].includes(clearCatRes.res.status);

      // 6. Published article then clear title
      const missingTitleArt = await request('POST', '/api/articles', {
        title: `Missing Title ${unique}`,
        content: 'valid body content',
        status: 'published',
        publishTime: '2024-04-01T14:00:00.000Z',
        publishedAt: '2024-04-01T14:00:00.000Z',
        primaryCategoryId: categoryId,
        categoryIds: [categoryId],
      });
      expect([200, 201]).toContain(missingTitleArt.res.status);
      const missingTitleId = extractId(missingTitleArt.body);
      articleIds.push(missingTitleId);
      const clearTitleRes = await request('PATCH', `/api/articles/${missingTitleId}`, { title: '' });
      const clearTitleSucceeded = [200, 204].includes(clearTitleRes.res.status);

      // 7. Eligible article moved to recycle bin
      const recycledArt = await request('POST', '/api/articles', {
        title: `Recycled Eligible ${unique}`,
        content: 'valid body content',
        status: 'published',
        publishTime: '2024-04-01T15:00:00.000Z',
        publishedAt: '2024-04-01T15:00:00.000Z',
        primaryCategoryId: categoryId,
        categoryIds: [categoryId],
      });
      expect([200, 201]).toContain(recycledArt.res.status);
      const recycledId = extractId(recycledArt.body);
      articleIds.push(recycledId);
      const softDelete = await request('DELETE', `/api/articles/${recycledId}`);
      expect([200, 204]).toContain(softDelete.res.status);

      // --- Verify RSS preview ---
      const rss = await tryRequest('GET', ['/api/rss/preview', '/api/subscription/preview']);
      expect(rss.res.status).toBe(200);
      const rssBody = rss.body?.data || rss.body;
      const rssIncluded = asArray(rssBody?.included || rssBody?.items || rssBody?.articles || rssBody);
      const rssTitles = rssIncluded.map(x => x.title);

      // Eligible article must be in preview
      expect(rssTitles, 'eligible article should be in RSS preview').toContain(`Eligible ${unique}`);
      // Draft article must NOT be in preview (even though fields are complete)
      expect(rssTitles, 'draft article should not be in RSS preview').not.toContain(`Draft Complete ${unique}`);
      // Recycled article must NOT be in preview
      expect(rssTitles, 'recycled article should not be in RSS preview').not.toContain(`Recycled Eligible ${unique}`);
      // Incomplete articles should not be in preview
      if (clearBodySucceeded) expect(rssTitles).not.toContain(`Missing Body ${unique}`);
      if (clearCatSucceeded) expect(rssTitles).not.toContain(`Missing Category ${unique}`);
      if (clearTitleSucceeded) expect(rssTitles).not.toContain('');

      // Verify reason counts exist in RSS
      const rssReasonCounts = findReasonCounts(rssBody);
      expect(rssReasonCounts, `expected exclusion reason summary in RSS preview, got keys: ${JSON.stringify(Object.keys(rssBody || {}))}`).toBeTruthy();
      // Check that specific reason keys exist with non-zero values
      if (rssReasonCounts && typeof rssReasonCounts === 'object' && !Array.isArray(rssReasonCounts)) {
        const totalExcluded = Object.values(rssReasonCounts).reduce((s, v) => s + (typeof v === 'number' ? v : 0), 0);
        expect(totalExcluded, 'total excluded count should be > 0').toBeGreaterThan(0);
      }

      // --- Verify SEO public preview ---
      const seoPublic = await tryRequest('GET', ['/api/seo/public-preview', '/api/seo/preview']);
      expect(seoPublic.res.status).toBe(200);
      const seoBody = seoPublic.body?.data || seoPublic.body;
      const seoIncluded = asArray(seoBody?.included || seoBody?.items || seoBody?.articles || seoBody);
      const seoIncludedIds = seoIncluded.map(x => x.id || x.articleId);
      const seoIncludedTitles = seoIncluded.map(x => x.title);

      // Eligible must be present
      const eligibleInSeo = seoIncludedIds.includes(eligibleId) || seoIncludedTitles.includes(`Eligible ${unique}`);
      expect(eligibleInSeo, 'eligible article should be in SEO preview').toBe(true);

      // Draft must NOT be present
      const draftInSeo = seoIncludedIds.includes(draftCompleteId) || seoIncludedTitles.includes(`Draft Complete ${unique}`);
      expect(draftInSeo, 'draft article should not be in SEO preview').toBe(false);

      // Recycled must NOT be present
      const recycledInSeo = seoIncludedIds.includes(recycledId) || seoIncludedTitles.includes(`Recycled Eligible ${unique}`);
      expect(recycledInSeo, 'recycled article should not be in SEO preview').toBe(false);

      // Incomplete should not be present
      if (clearCatSucceeded) {
        const missingCatInSeo = seoIncludedIds.includes(missingCatId) || seoIncludedTitles.includes(`Missing Category ${unique}`);
        expect(missingCatInSeo, 'article missing category should not be in SEO preview').toBe(false);
      }

      // Verify SEO reason counts
      const seoReasonCounts = findReasonCounts(seoBody);
      expect(seoReasonCounts, `expected exclusion reason summary in SEO preview, got keys: ${JSON.stringify(Object.keys(seoBody || {}))}`).toBeTruthy();

      // Record initial excluded count
      const initialExcludedCount = extractExcludedCount(seoBody);

      // --- Fix one article (restore primary category) and verify counts update ---
      if (clearCatSucceeded) {
        const fixCat = await request('PATCH', `/api/articles/${missingCatId}`, {
          primaryCategoryId: categoryId,
          categoryIds: [categoryId],
        });
        expect([200, 201, 204]).toContain(fixCat.res.status);

        // Re-check RSS preview
        const rss2 = await tryRequest('GET', ['/api/rss/preview', '/api/subscription/preview']);
        expect(rss2.res.status).toBe(200);
        const rss2Body = rss2.body?.data || rss2.body;
        const rss2Included = asArray(rss2Body?.included || rss2Body?.items || rss2Body?.articles || rss2Body);
        const rss2Titles = rss2Included.map(x => x.title);
        // The fixed article should now appear
        expect(rss2Titles, 'fixed article should now appear in RSS preview').toContain(`Missing Category ${unique}`);

        // Re-check SEO preview - excluded count should have decreased
        const seo2 = await tryRequest('GET', ['/api/seo/public-preview', '/api/seo/preview']);
        expect(seo2.res.status).toBe(200);
        const seo2Body = seo2.body?.data || seo2.body;
        const seo2ExcludedCount = extractExcludedCount(seo2Body);
        expect(seo2ExcludedCount, 'excluded count should decrease after fixing article').toBeLessThan(initialExcludedCount);

        // The fixed article should now be in SEO included list
        const seo2Included = asArray(seo2Body?.included || seo2Body?.items || seo2Body?.articles || seo2Body);
        const seo2Ids = seo2Included.map(x => x.id || x.articleId);
        const seo2Titles = seo2Included.map(x => x.title);
        const fixedInSeo = seo2Ids.includes(missingCatId) || seo2Titles.includes(`Missing Category ${unique}`);
        expect(fixedInSeo, 'fixed article should now appear in SEO preview').toBe(true);
      }

    } finally {
      for (const id of articleIds) {
        if (id) {
          await tryDelete(`/api/articles/${id}?permanent=true&confirm=true`);
          await tryDelete(`/api/articles/${id}?permanent=true`);
          await tryDelete(`/api/articles/${id}`);
        }
      }
      for (const id of categoryIds) {
        if (id) await tryDelete(`/api/categories/${id}`);
      }
    }
  });
});

import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

function uid(prefix = 'test') {
  return `${prefix}-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
}

async function api(path, options = {}) {
  const res = await fetch(`${BASE_URL}${path}`, {
    headers: { 'Content-Type': 'application/json', ...(options.headers || {}) },
    ...options,
  });
  const text = await res.text();
  let body;
  try { body = text ? JSON.parse(text) : null; } catch { body = text; }
  return { res, body };
}

async function createArticle(payload) {
  const { res, body } = await api('/api/articles', { method: 'POST', body: JSON.stringify(payload) });
  expect(res.status).toBeGreaterThanOrEqual(200);
  expect(res.status).toBeLessThan(300);
  return body;
}

async function saveArticle(id, payload) {
  // Try PUT first, then PATCH, then POST /save as fallback
  let result = await api(`/api/articles/${id}`, { method: 'PUT', body: JSON.stringify(payload) });
  if (result.res.status >= 200 && result.res.status < 300) return result;
  result = await api(`/api/articles/${id}`, { method: 'PATCH', body: JSON.stringify(payload) });
  if (result.res.status >= 200 && result.res.status < 300) return result;
  result = await api(`/api/articles/${id}/save`, { method: 'POST', body: JSON.stringify(payload) });
  expect(result.res.status, `save article failed with all methods: ${JSON.stringify(result.body)}`).toBeGreaterThanOrEqual(200);
  expect(result.res.status).toBeLessThan(300);
  return result;
}

async function cleanupArticle(id) {
  if (!id) return;
  try { await api(`/api/articles/${id}`, { method: 'DELETE' }); } catch {}
}

function extractVersions(body) {
  if (body && Array.isArray(body.items)) return body.items;
  if (body && Array.isArray(body.versions)) return body.versions;
  if (body && Array.isArray(body.data)) return body.data;
  if (Array.isArray(body)) return body;
  return [];
}

describe('restore_old_version_creates_new_current_version', () => {
  it('should restore earliest version as current, keep intermediate versions, and append one new version entry', async () => {
    const suffix = uid('restore-version');
    let article;

    try {
      // Create article with title A (first manual save)
      article = await createArticle({ title: `A ${suffix}`, content: 'A body', status: 'draft' });
      expect(article.id, 'article should have an id').toBeTruthy();

      // Record time before saves for later comparison
      const timeBeforeB = new Date().toISOString();

      // Save B (second manual save)
      const saveB = await saveArticle(article.id, { title: `B ${suffix}`, content: 'B body', status: 'draft' });

      // Save C (third manual save)
      const saveC = await saveArticle(article.id, { title: `C ${suffix}`, content: 'C body', status: 'draft' });

      // Fetch version history before restore
      const before = await api(`/api/articles/${article.id}/versions`);
      expect(before.res.status, `versions endpoint should return 200, got ${before.res.status}`).toBe(200);
      const beforeVersions = extractVersions(before.body);
      const target = beforeVersions.filter((v) => String(v.title || '').includes(suffix));
      expect(target.length, `expected at least 3 versions (A/B/C) before restore, got ${target.length}: ${JSON.stringify(beforeVersions)}`).toBeGreaterThanOrEqual(3);
      const beforeCount = target.length;

      // Find version A
      const versionA = target.find((v) => v.title === `A ${suffix}`);
      expect(versionA, `expected to find version A in history: ${JSON.stringify(target)}`).toBeTruthy();
      expect(versionA.id, 'version A should have an id').toBeTruthy();

      // Record time just before restore
      const timeBeforeRestore = new Date();

      // Restore version A
      const restore = await api(`/api/articles/${article.id}/versions/${versionA.id}/restore`, { method: 'POST' });
      expect(restore.res.status, `restore version A failed: ${JSON.stringify(restore.body)}`).toBeGreaterThanOrEqual(200);
      expect(restore.res.status).toBeLessThan(300);

      // Verify current article title is now A
      const detail = await api(`/api/articles/${article.id}`);
      expect(detail.res.status).toBe(200);
      expect(detail.body.title, `current title should become A after restore, got ${JSON.stringify(detail.body.title)}`).toBe(`A ${suffix}`);

      // Verify updatedAt is the restore time, not the old version time
      const updatedAt = detail.body.updatedAt || detail.body.updated_at || detail.body.lastModified;
      expect(updatedAt, `article should have an updatedAt field after restore: ${JSON.stringify(detail.body)}`).toBeTruthy();
      const updatedDate = new Date(updatedAt);
      expect(updatedDate.getTime(), `updatedAt (${updatedAt}) should be >= restore time (${timeBeforeRestore.toISOString()})`)
        .toBeGreaterThanOrEqual(timeBeforeRestore.getTime() - 5000); // small tolerance

      // Verify version history after restore
      const after = await api(`/api/articles/${article.id}/versions`);
      expect(after.res.status).toBe(200);
      const afterVersions = extractVersions(after.body);
      const afterTarget = afterVersions.filter((v) => String(v.title || '').includes(suffix));

      // Version count should increase by exactly 1
      expect(afterTarget.length, `version count should increase by 1 after restore: before=${beforeCount}, after=${afterTarget.length}`).toBe(beforeCount + 1);

      // B and C should still exist
      expect(afterTarget.some((v) => v.title === `B ${suffix}`), `version B should remain after restore: ${JSON.stringify(afterTarget)}`).toBe(true);
      expect(afterTarget.some((v) => v.title === `C ${suffix}`), `version C should remain after restore: ${JSON.stringify(afterTarget)}`).toBe(true);

      // There should be at least 2 entries with title A (original + restore-generated)
      const countA = afterTarget.filter((v) => v.title === `A ${suffix}`).length;
      expect(countA, `expected original A and restored-generated new current version (at least 2 A entries), got ${countA}: ${JSON.stringify(afterTarget)}`).toBeGreaterThanOrEqual(2);
    } finally {
      await cleanupArticle(article?.id);
    }
  });
});

