        status: 'draft',
        primaryCategoryId: categoryId,
        categoryIds: [categoryId],
        tagIds: [tagId1, tagId2],
      });
      expect([200, 201]).toContain(otherArticleRes.res.status);
      otherArticleId = getId(otherArticleRes.body);
