        if (item && typeof item === 'object' && 'status' in item) {
          expect(item.status, 'each result should respect draft status filter').toBe('draft');
        }
      }

      // Step 2: Simulate filter persistence after "page refresh"
      // Save the current filter state, then attempt to retrieve persisted filters
      // Try saving filter state explicitly if the API supports it
      const saveFilterRes = await request('POST', '/api/articles/filters', {
        keyword: keyword,
        status: 'draft',
        categoryId: String(categoryId),
        tagIds: [tagId1, tagId2],
      });
      // Also try PUT
      let savedFilters = null;
      if (saveFilterRes.res.status >= 200 && saveFilterRes.res.status < 300) {
        // Filters saved, now simulate refresh by retrieving persisted filters
        const getFilterRes = await request('GET', '/api/articles/filters');
        if (getFilterRes.res.status === 200) {
          savedFilters = getFilterRes.body?.data ?? getFilterRes.body;
        }
      } else {
