          keyword: keyword,
          status: 'draft',
          categoryId: String(categoryId),
          tagIds: [tagId1, tagId2],
        });
        if (putFilterRes.res.status >= 200 && putFilterRes.res.status < 300) {
          const getFilterRes = await request('GET', '/api/articles/filters');
          if (getFilterRes.res.status === 200) {
            savedFilters = getFilterRes.body?.data ?? getFilterRes.body;
          }
        }
      }

      // If the API supports persisted filters, verify them
      if (savedFilters) {
        const persistedKeyword = savedFilters.keyword || savedFilters.search || savedFilters.q;
        const persistedStatus = savedFilters.status;
        const persistedCategoryId = savedFilters.categoryId || savedFilters.category;
