      expect(clearedIds, 'other article should also match remaining filters after keyword cleared').toContain(String(otherArticleId));

      // Verify count is updated
      const clearedTotalCount = getTotalCount(clearedResult.body);
      if (clearedTotalCount !== undefined) {
        expect(clearedTotalCount).toBeGreaterThanOrEqual(2);
      }

      // Verify status filter still applied
      for (const item of clearedItems) {
        if (item && typeof item === 'object' && 'status' in item) {
