      keywordOnlyParams.set('keyword', keyword);
      const keywordOnlyResult = await request('GET', `/api/articles?${keywordOnlyParams.toString()}`);
      expect(keywordOnlyResult.res.status).toBe(200);
      const keywordItems = getItems(keywordOnlyResult.body);
      const keywordIds = keywordItems.map(i => String(getId(i) || i.id));
      expect(keywordIds).toContain(String(articleId));

      // Step 5: Verify empty/whitespace keyword treated as no keyword
      const whitespaceParams = new URLSearchParams();
      whitespaceParams.set('keyword', '   ');
      whitespaceParams.set('status', 'draft');
