      const whitespaceResult = await request('GET', `/api/articles?${whitespaceParams.toString()}`);
      expect(whitespaceResult.res.status).toBe(200);
      const whitespaceItems = getItems(whitespaceResult.body);
      const whitespaceIds = whitespaceItems.map(i => String(getId(i) || i.id));
      // With whitespace keyword (treated as no keyword), both articles should appear
      expect(whitespaceIds).toContain(String(articleId));
      expect(whitespaceIds).toContain(String(otherArticleId));

    } finally {
      await cleanupArticle(articleId);
      await cleanupArticle(otherArticleId);
      await cleanupTag(tagId2);
      await cleanupTag(tagId1);
      await cleanupCategory(categoryId);
      // Clean up any persisted filter state
      try { await request('DELETE', '/api/articles/filters'); } catch {}
    }
  });
});

