import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

function uid(prefix = 'test') {
  return `${prefix}-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
}

async function api(path, options = {}) {
  const res = await fetch(`${BASE_URL}${path}`, {
    headers: { 'Content-Type': 'application/json', ...(options.headers || {}) },
    ...options,
  });
  const text = await res.text();
  let body;
  try { body = text ? JSON.parse(text) : null; } catch { body = text; }
  return { res, body };
}

async function createArticle(payload) {
  const { res, body } = await api('/api/articles', {
    method: 'POST',
    body: JSON.stringify(payload),
  });
  expect([200, 201]).toContain(res.status);
  return body;
}

async function updateArticle(id, payload) {
  let result = await api(`/api/articles/${id}`, { method: 'PUT', body: JSON.stringify(payload) });
  if (result.res.status >= 200 && result.res.status < 300) return result;
  result = await api(`/api/articles/${id}`, { method: 'PATCH', body: JSON.stringify(payload) });
  expect(result.res.status, `update article failed: ${JSON.stringify(result.body)}`).toBeGreaterThanOrEqual(200);
  expect(result.res.status).toBeLessThan(300);
  return result;
}

async function getMetrics() {
  const endpoints = [
    '/api/dashboard/metrics',
    '/api/dashboard',
    '/api/stats',
    '/api/metrics',
    '/api/articles/stats',
  ];
  for (const ep of endpoints) {
    const result = await api(ep);
    if (result.res.status === 200) return result.body;
  }
  // Force fail if none work
  const last = await api('/api/dashboard/metrics');
  expect(last.res.status, 'no dashboard/stats/metrics endpoint returned 200').toBe(200);
  return last.body;
}

async function trashArticle(id) {
  const endpoints = [
    { path: `/api/articles/${id}/trash`, method: 'POST', body: undefined },
    { path: `/api/articles/${id}/recycle`, method: 'POST', body: undefined },
    { path: `/api/articles/${id}`, method: 'PATCH', body: JSON.stringify({ isInTrash: true }) },
    { path: `/api/articles/${id}`, method: 'PATCH', body: JSON.stringify({ status: 'trashed' }) },
    { path: `/api/articles/${id}`, method: 'PUT', body: JSON.stringify({ isInTrash: true }) },
  ];
  for (const ep of endpoints) {
    const result = await api(ep.path, { method: ep.method, ...(ep.body ? { body: ep.body } : {}) });
    if (result.res.status >= 200 && result.res.status < 300) return result;
  }
  const fallback = await api(`/api/articles/${id}/trash`, { method: 'POST' });
  expect(fallback.res.status, `trashing article failed`).toBeGreaterThanOrEqual(200);
  expect(fallback.res.status).toBeLessThan(300);
  return fallback;
}

async function cleanupArticle(id) {
  if (!id) return;
  try { await api(`/api/articles/${id}`, { method: 'DELETE' }); } catch {}
  try { await api(`/api/articles/${id}/permanent`, { method: 'DELETE' }); } catch {}
}

async function cleanupCategory(id) {
  if (!id) return;
  try { await api(`/api/categories/${id}`, { method: 'DELETE' }); } catch {}
}

function getMetricValue(metrics, ...fields) {
  for (const field of fields) {
    const val = metrics[field];
    if (val !== undefined && val !== null) return Number(val);
  }
  if (metrics.stats) {
    for (const field of fields) {
      const val = metrics.stats[field];
      if (val !== undefined && val !== null) return Number(val);
    }
  }
  if (metrics.counts) {
    for (const field of fields) {
      const val = metrics.counts[field];
      if (val !== undefined && val !== null) return Number(val);
    }
  }
  return undefined;
}

function requireMetricValue(metrics, label, ...fields) {
  const val = getMetricValue(metrics, ...fields);
  expect(val, `metric '${label}' must exist in response: ${JSON.stringify(metrics)}`).not.toBeUndefined();
  return val;
}

describe('dashboard_metrics_update_with_article_changes', () => {
  it('should return valid zero-state metrics with all required fields when no articles exist or as baseline', async () => {
    const metrics = await getMetrics();
    expect(metrics, 'metrics response should be truthy').toBeTruthy();

    // All 6 required metric fields must exist and be >= 0
    const total = requireMetricValue(metrics, 'totalArticles', 'totalArticles', 'total', 'articleCount');
    expect(total).toBeGreaterThanOrEqual(0);

    const drafts = requireMetricValue(metrics, 'draftCount', 'draftCount', 'drafts');
    expect(drafts).toBeGreaterThanOrEqual(0);

    const published = requireMetricValue(metrics, 'publishedCount', 'publishedCount', 'published');
    expect(published).toBeGreaterThanOrEqual(0);

    const trash = requireMetricValue(metrics, 'trashCount', 'trashCount', 'recycleBinCount', 'recycled', 'trashedCount');
    expect(trash).toBeGreaterThanOrEqual(0);

    const eligible = requireMetricValue(metrics, 'eligibleCount', 'rssEligibleCount', 'subscriptionEligibleCount', 'previewEligibleCount', 'eligibleCount');
    expect(eligible).toBeGreaterThanOrEqual(0);

    const excluded = requireMetricValue(metrics, 'excludedCount', 'excludedPublishedCount', 'nonPublicPublishedCount', 'excludedCount');
    expect(excluded).toBeGreaterThanOrEqual(0);
  });

  it('should update metrics when recycle flag, publish status, publishedAt, and primary category change', async () => {
    const unique = uid('metrics');
    const ids = [];
    let categoryId;

    try {
      // Get baseline metrics
      const metricsBaseline = await getMetrics();
      const baseTotal = requireMetricValue(metricsBaseline, 'total', 'totalArticles', 'total', 'articleCount');
      const baseDrafts = requireMetricValue(metricsBaseline, 'drafts', 'draftCount', 'drafts');
      const basePublished = requireMetricValue(metricsBaseline, 'published', 'publishedCount', 'published');
      const baseTrash = requireMetricValue(metricsBaseline, 'trash', 'trashCount', 'recycleBinCount', 'recycled', 'trashedCount');

      // Create a draft article
      const draft = await createArticle({
        title: `Draft ${unique}`,
        summary: 'draft summary',
        content: 'draft body',
        status: 'draft',
        editorMode: 'markdown',
      });
      ids.push(draft.id);

      // Verify metrics after creating draft - drafts MUST increase
      const metricsAfterDraft = await getMetrics();
      const draftsAfterCreate = requireMetricValue(metricsAfterDraft, 'drafts', 'draftCount', 'drafts');
      expect(draftsAfterCreate, 'draft count should increase after creating draft').toBeGreaterThan(baseDrafts);

      const totalAfterCreate = requireMetricValue(metricsAfterDraft, 'total', 'totalArticles', 'total', 'articleCount');
      expect(totalAfterCreate, 'total count should increase after creating article').toBeGreaterThan(baseTotal);

      // --- Step 1: Change draft to published ---
      await updateArticle(draft.id, { status: 'published', publishedAt: new Date().toISOString() });

      const metricsAfterPublish = await getMetrics();
      const draftsAfterPublish = requireMetricValue(metricsAfterPublish, 'drafts', 'draftCount', 'drafts');
      const publishedAfterPublish = requireMetricValue(metricsAfterPublish, 'published', 'publishedCount', 'published');

      expect(draftsAfterPublish, 'draft count should decrease after publishing').toBeLessThan(draftsAfterCreate);
      expect(publishedAfterPublish, 'published count should increase after publishing').toBeGreaterThan(basePublished);

      // --- Step 2: Move to recycle bin ---
      const trashResult = await trashArticle(draft.id);
      expect(trashResult.res.status, `trashing article failed: ${JSON.stringify(trashResult.body)}`).toBeGreaterThanOrEqual(200);
      expect(trashResult.res.status).toBeLessThan(300);

      const metricsAfterTrash = await getMetrics();
      const trashAfterTrash = requireMetricValue(metricsAfterTrash, 'trash', 'trashCount', 'recycleBinCount', 'recycled', 'trashedCount');
      expect(trashAfterTrash, 'recycle bin count should increase after trashing').toBeGreaterThan(baseTrash);

      // --- Step 3: Create another article and test publishedAt + primary category affecting eligible count ---
      const publishedIncomplete = await createArticle({
        title: `PubIncomplete ${unique}`,
        summary: 'summary',
        content: 'body content',
        status: 'published',
        // Missing publishedAt and primary category -> not public-eligible
      });
      ids.push(publishedIncomplete.id);

      const metricsBeforeFix = await getMetrics();
      const excludedBeforeFix = requireMetricValue(metricsBeforeFix, 'excluded', 'excludedPublishedCount', 'nonPublicPublishedCount', 'excludedCount');
      const eligibleBeforeFix = requireMetricValue(metricsBeforeFix, 'eligible', 'rssEligibleCount', 'subscriptionEligibleCount', 'previewEligibleCount', 'eligibleCount');

      // Fill publishedAt
      await updateArticle(publishedIncomplete.id, {
        publishedAt: new Date().toISOString(),
      });

      // Add primary category - MUST succeed
      const catRes = await api('/api/categories', {
        method: 'POST',
        body: JSON.stringify({ name: `MetricsCat ${unique}`, slug: `metricscat-${unique}` }),
      });
      expect(catRes.res.status, 'category creation must succeed for primary category test').toBeGreaterThanOrEqual(200);
      expect(catRes.res.status).toBeLessThan(300);
      categoryId = catRes.body?.id;
      expect(categoryId, 'created category must have an id').toBeTruthy();

      await updateArticle(publishedIncomplete.id, {
        categoryId: categoryId,
        primaryCategoryId: categoryId,
      });

      const metricsAfterFix = await getMetrics();
      const eligibleAfterFix = requireMetricValue(metricsAfterFix, 'eligible', 'rssEligibleCount', 'subscriptionEligibleCount', 'previewEligibleCount', 'eligibleCount');
      const excludedAfterFix = requireMetricValue(metricsAfterFix, 'excluded', 'excludedPublishedCount', 'nonPublicPublishedCount', 'excludedCount');

      // After filling both publishedAt and primaryCategory, eligible count should increase
      expect(eligibleAfterFix, 'eligible count should increase after fixing public conditions').toBeGreaterThanOrEqual(eligibleBeforeFix);
      expect(excludedAfterFix, 'excluded count should decrease after fixing public conditions').toBeLessThanOrEqual(excludedBeforeFix);

      // --- Cross-validate with article list ---
      const articleListRes = await api('/api/articles?status=published');
      expect(articleListRes.res.status).toBe(200);
      const listBody = articleListRes.body;
      const listItems = listBody.items || listBody.articles || listBody.data || listBody;
      if (Array.isArray(listItems)) {
        const publishedInList = listItems.filter(a => !a.isInTrash && a.status === 'published');
        const publishedMetric = requireMetricValue(metricsAfterFix, 'published', 'publishedCount', 'published');
        // The published count in metrics should be consistent with what the list shows
        // (note: the trashed article may or may not appear in published filter depending on implementation)
      }

    } finally {
      for (const id of ids) {
        await cleanupArticle(id);
      }
      await cleanupCategory(categoryId);
    }
  });
});

import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

function uid(prefix = 'test') {
  return `${prefix}-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
}

async function api(path, options = {}) {
  const res = await fetch(`${BASE_URL}${path}`, {
    headers: { 'Content-Type': 'application/json', ...(options.headers || {}) },
    ...options,
  });
  const text = await res.text();
  let body;
  try {
    body = text ? JSON.parse(text) : null;
  } catch {
    body = text;
  }
  return { res, body };
}

function getId(obj) {
  return obj?.id || obj?.data?.id;
}

function getItems(body) {
  if (Array.isArray(body)) return body;
  return body?.items || body?.articles || body?.data || [];
}

async function tryApi(path, options = {}) {
  let r = await api(`/api${path}`, options);
  if (r.res.status === 404) {
    r = await api(path, options);
  }
  return r;
}

async function tryCreate(path, payload) {
  return tryApi(path, { method: 'POST', body: JSON.stringify(payload) });
}

async function cleanupArticle(id) {
  if (!id) return;
  try { await api(`/api/articles/${id}/permanent`, { method: 'DELETE' }); } catch {}
  try { await api(`/articles/${id}/permanent`, { method: 'DELETE' }); } catch {}
  try { await api(`/api/articles/${id}`, { method: 'DELETE' }); } catch {}
  try { await api(`/articles/${id}`, { method: 'DELETE' }); } catch {}
}

async function cleanupCategory(id) {
  if (!id) return;
  try { await api(`/api/categories/${id}`, { method: 'DELETE' }); } catch {}
  try { await api(`/categories/${id}`, { method: 'DELETE' }); } catch {}
}

