      createdCategoryIds.push(categoryId);

      const t1 = '2024-01-02T10:00:00.000Z';
      const t2 = '2024-01-03T10:00:00.000Z';

      // Helper to create an article
      async function createArticle(payload) {
        const r = await tryCreate('/articles', payload);
        if ([200, 201].includes(r.res.status)) {
          createdArticleIds.push(getId(r.body));
        }
        return r;
      }

      // Helper to create a valid published article
      async function createPublishedArticle(title, content, publishedAt, extraFields = {}) {
        const payload = {
          title,
          content,
          status: 'published',
          publishedAt,
          primaryCategoryId: categoryId,
          categories: [{ id: categoryId, isPrimary: true }],
          ...extraFields,
        };
        const r = await createArticle(payload);
        expect(r.res.status, `create article '${title}' failed: ${JSON.stringify(r.body)}`).toBeGreaterThanOrEqual(200);
        expect(r.res.status).toBeLessThan(300);
        return r;
      }

      // Article 1: valid, older publish time
      const a1 = await createPublishedArticle(`Visible older ${suffix}`, 'body older', t1);

      // Article 2: valid, newer publish time, created first among t2 articles
      const a2 = await createPublishedArticle(`Visible newer first-created ${suffix}`, 'body newer first', t2);

      // Small delay to ensure different updatedAt
      await new Promise(r => setTimeout(r, 100));

      // Article 3: valid, same newer publish time but created later (later updatedAt)
      const a3 = await createPublishedArticle(`Visible newer later-created ${suffix}`, 'body newer later', t2);

      // === Articles that should be EXCLUDED ===

      // Draft article (not published)
      await createArticle({
        title: `Draft ${suffix}`,
        content: 'body',
        status: 'draft',
        primaryCategoryId: categoryId,
        categories: [{ id: categoryId, isPrimary: true }],
      });

      // Archived article
      await createArticle({
        title: `Archived ${suffix}`,
        content: 'body',
        status: 'archived',
        publishedAt: t2,
        primaryCategoryId: categoryId,
        categories: [{ id: categoryId, isPrimary: true }],
      });

      // Article missing publishedAt (server may reject, which itself proves validation)
      const noPubTimeRes = await createArticle({
        title: `No publishedAt ${suffix}`,
        content: 'body',
        status: 'published',
        primaryCategoryId: categoryId,
        categories: [{ id: categoryId, isPrimary: true }],
        // deliberately omit publishedAt
      });

      // Article missing primary category
      const noCatRes = await createArticle({
        title: `No category ${suffix}`,
        content: 'body',
        status: 'published',
        publishedAt: t2,
        // deliberately omit category
      });

      // Article with content cleared after creation (test empty content exclusion)
      const clearContentRes = await createPublishedArticle(
        `ClearContent ${suffix}`, 'temporary body', t2
      );
      const clearContentId = getId(clearContentRes.body);
      if (clearContentId) {
        // Try to clear content
        await tryApi(`/articles/${clearContentId}`, {
          method: 'PATCH',
          body: JSON.stringify({ content: '' }),
        });
        await tryApi(`/articles/${clearContentId}`, {
          method: 'PUT',
          body: JSON.stringify({
            content: '',
            title: `ClearContent ${suffix}`,
            status: 'published',
            publishedAt: t2,
            primaryCategoryId: categoryId,
          }),
        });
      }

      // Create a published article then move to trash
      const trashArticle = await createPublishedArticle(`Trash ${suffix}`, 'body', t2);
      const trashId = getId(trashArticle.body);
      if (trashId) {
        const trashEndpoints = [
          { path: `/articles/${trashId}/trash`, method: 'POST' },
          { path: `/articles/${trashId}/trash`, method: 'PUT' },
          { path: `/articles/${trashId}`, method: 'PATCH', body: { isInTrash: true } },
          { path: `/articles/${trashId}`, method: 'PATCH', body: { status: 'trashed' } },
          { path: `/articles/${trashId}`, method: 'DELETE' },
        ];
        for (const ep of trashEndpoints) {
          const r = await tryApi(ep.path, {
            method: ep.method,
            ...(ep.body ? { body: JSON.stringify(ep.body) } : {}),
          });
          if (r.res.status >= 200 && r.res.status < 300) break;
        }
      }

      // Configure RSS output count to be large enough
      const rssConfigs = [
        { channelTitle: 'Test Blog', siteUrl: 'http://example.com', feedUrl: 'http://example.com/rss', articleCount: 50 },
        { title: 'Test Blog', siteUrl: 'http://example.com', feedUrl: 'http://example.com/rss', maxArticles: 50 },
      ];
      for (const payload of rssConfigs) {
        let r = await tryApi('/subscription/config', { method: 'PUT', body: JSON.stringify(payload) });
        if (r.res.status >= 200 && r.res.status < 300) break;
        r = await tryApi('/rss/config', { method: 'PUT', body: JSON.stringify(payload) });
        if (r.res.status >= 200 && r.res.status < 300) break;
      }

      // Fetch subscription preview
      let previewRes = await tryApi('/subscription/preview');
      if (previewRes.res.status === 404) {
        previewRes = await tryApi('/rss/preview');
      }
      expect(previewRes.res.status, `preview response: ${JSON.stringify(previewRes.body)}`).toBe(200);
      expect(previewRes.body).toBeTruthy();

      const items = getItems(previewRes.body);
      expect(Array.isArray(items), 'expected items array in preview response').toBe(true);

      // Filter to only our test articles
      const visible = items.filter((item) => String(item.title || '').includes(suffix));
      const visibleTitles = visible.map((item) => item.title);

      // Excluded articles should NOT appear in preview
      const excludedPrefixes = ['Draft', 'Archived', 'Trash', 'No publishedAt', 'No category', 'ClearContent'];
      for (const prefix of excludedPrefixes) {
        for (const title of visibleTitles) {
          expect(title, `preview should not contain '${prefix}' article`).not.toContain(prefix);
        }
      }

      // Valid articles should appear
      expect(visibleTitles, `expected 'Visible older ${suffix}' in preview`).toContain(`Visible older ${suffix}`);
      expect(visibleTitles, `expected 'Visible newer first-created ${suffix}' in preview`).toContain(`Visible newer first-created ${suffix}`);
      expect(visibleTitles, `expected 'Visible newer later-created ${suffix}' in preview`).toContain(`Visible newer later-created ${suffix}`);

      // Verify sorting: publishedAt desc, then updatedAt desc for same publishedAt
      // Expected order: a3 (t2, later updatedAt), a2 (t2, earlier updatedAt), a1 (t1)
      expect(visible.length).toBeGreaterThanOrEqual(3);

      // Find the indices of our three valid articles in the preview
      const a3Title = `Visible newer later-created ${suffix}`;
      const a2Title = `Visible newer first-created ${suffix}`;
      const a1Title = `Visible older ${suffix}`;

      const idxA3 = visible.findIndex(i => i.title === a3Title);
      const idxA2 = visible.findIndex(i => i.title === a2Title);
      const idxA1 = visible.findIndex(i => i.title === a1Title);

      expect(idxA3, 'a3 (latest updated, newer published) should be found').toBeGreaterThanOrEqual(0);
      expect(idxA2, 'a2 (earlier updated, newer published) should be found').toBeGreaterThanOrEqual(0);
      expect(idxA1, 'a1 (older published) should be found').toBeGreaterThanOrEqual(0);

      // a3 should come before a2 (same publishedAt, a3 has later updatedAt)
      expect(idxA3, 'a3 should appear before a2 (later updatedAt with same publishedAt)').toBeLessThan(idxA2);
      // a2 should come before a1 (a2 has newer publishedAt)
      expect(idxA2, 'a2 should appear before a1 (newer publishedAt)').toBeLessThan(idxA1);

      // Each visible item should be published with required fields
      for (const item of visible) {
        expect(item.status, 'preview item should be published').toBe('published');
        expect(item.title?.length, 'preview item should have non-empty title').toBeGreaterThan(0);
      }

      // === Verify excluded summary/counts ===
      // Round 17 requires the preview to report excluded article counts by reason
      const previewBody = previewRes.body;
      const summary = previewBody?.excludedSummary || previewBody?.excludedCounts || previewBody?.excluded || previewBody?.summary;

      expect(summary, 'response should include an excluded summary/counts object').toBeTruthy();
      expect(typeof summary, 'excluded summary should be an object').toBe('object');

      // Calculate total excluded count
      const totalExcluded = Object.values(summary).reduce(
        (acc, v) => acc + (typeof v === 'number' ? v : 0), 0
      );
      // We created at least: draft, archived, trash, and possibly noPubTime, noCat, clearContent
      expect(totalExcluded, 'expected excluded count > 0 since we created non-qualifying articles').toBeGreaterThan(0);

      // Check that specific exclusion reason keys exist
      // At minimum, we should see reasons for the articles we created
      const summaryKeys = Object.keys(summary).map(k => k.toLowerCase());
      const summaryStr = JSON.stringify(summary).toLowerCase();
      // We expect some combination of keys indicating exclusion reasons
      const hasReasonKeys = summaryStr.includes('title') ||
        summaryStr.includes('content') ||
        summaryStr.includes('publish') ||
        summaryStr.includes('category') ||
        summaryStr.includes('missing') ||
        summaryStr.includes('empty') ||
        summaryKeys.length > 0;
      expect(hasReasonKeys, 'excluded summary should contain identifiable reason categories').toBe(true);

    } finally {
      for (const id of createdArticleIds.reverse()) await cleanupArticle(id);
      for (const id of createdCategoryIds.reverse()) await cleanupCategory(id);
    }
  });
});

import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function request(method, path, body) {
  const res = await fetch(`${BASE_URL}${path}`, {
    method,
    headers: { 'Content-Type': 'application/json' },
    body: body !== undefined ? JSON.stringify(body) : undefined,
  });
  const text = await res.text();
  let json;
  try {
    json = text ? JSON.parse(text) : null;
  } catch {
    json = text;
  }
  return { res, body: json };
}

function getId(body) {
  return body?.id ?? body?.data?.id ?? body?.categoryId ?? body?.tagId;
}

describe('category_tag_name_validation_enforced', () => {
  it('should validate category/tag required names, exact length boundaries, duplicate names, tag rename duplicate rejection, deletion, and reference constraints', async () => {
    const suffix = `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
    let categoryId;
    let category2Id;
    let tagId;
    let tag2Id;
    let articleId;

    try {
      // --- Category: empty name rejected ---
      const emptyCategory = await request('POST', '/api/categories', { name: '   ' });
      expect([400, 422].includes(emptyCategory.res.status), `expected empty category name rejection, got ${emptyCategory.res.status} ${JSON.stringify(emptyCategory.body)}`).toBe(true);
      expect(emptyCategory.body, 'expected category validation error body').toBeTruthy();

      // --- Category: 40 chars accepted (boundary) ---
      const category40 = `c${'a'.repeat(39)}`;
      const validBoundaryCategory = await request('POST', '/api/categories', { name: category40 });
      expect([200, 201].includes(validBoundaryCategory.res.status), `expected 40-char category name accepted, got ${validBoundaryCategory.res.status} ${JSON.stringify(validBoundaryCategory.body)}`).toBe(true);
      categoryId = getId(validBoundaryCategory.body);
      expect(categoryId, `expected created boundary category id, got ${JSON.stringify(validBoundaryCategory.body)}`).toBeTruthy();

      // --- Category: 41 chars rejected (boundary) ---
      const category41 = `c${'b'.repeat(40)}`;
      const overBoundaryCategory = await request('POST', '/api/categories', { name: category41 });
      expect([400, 422].includes(overBoundaryCategory.res.status), `expected 41-char category name rejection, got ${overBoundaryCategory.res.status} ${JSON.stringify(overBoundaryCategory.body)}`).toBe(true);

      // --- Category: duplicate name rejected ---
      const duplicateCategory = await request('POST', '/api/categories', { name: category40 });
      expect([400, 409, 422].includes(duplicateCategory.res.status), `expected duplicate category rejection, got ${duplicateCategory.res.status} ${JSON.stringify(duplicateCategory.body)}`).toBe(true);

      // --- Category: create second for rename test ---
      const createCategory2 = await request('POST', '/api/categories', { name: `category-other-${suffix}` });
      expect([200, 201].includes(createCategory2.res.status), `expected second category create success, got ${createCategory2.res.status} ${JSON.stringify(createCategory2.body)}`).toBe(true);
      category2Id = getId(createCategory2.body);
      expect(category2Id).toBeTruthy();

      // --- Category: rename to duplicate rejected ---
      const renameCategoryToDuplicate = await request('PATCH', `/api/categories/${category2Id}`, { name: category40 });
      expect([400, 409, 422].includes(renameCategoryToDuplicate.res.status), `expected duplicate category rename rejection, got ${renameCategoryToDuplicate.res.status} ${JSON.stringify(renameCategoryToDuplicate.body)}`).toBe(true);
      expect(renameCategoryToDuplicate.body, 'expected duplicate category rename error body').toBeTruthy();

      // --- Tag: empty name rejected ---
      const emptyTag = await request('POST', '/api/tags', { name: ' ' });
      expect([400, 422].includes(emptyTag.res.status), `expected empty tag name rejection, got ${emptyTag.res.status} ${JSON.stringify(emptyTag.body)}`).toBe(true);

      // --- Tag: 20 chars accepted (boundary) ---
      const tag20 = 't'.repeat(20);
      const validBoundaryTag = await request('POST', '/api/tags', { name: tag20 });
      expect([200, 201].includes(validBoundaryTag.res.status), `expected 20-char tag name accepted, got ${validBoundaryTag.res.status} ${JSON.stringify(validBoundaryTag.body)}`).toBe(true);
      tagId = getId(validBoundaryTag.body);
      expect(tagId).toBeTruthy();

      // --- Tag: 21 chars rejected (boundary) ---
      const tag21 = 'u'.repeat(21);
      const overBoundaryTag = await request('POST', '/api/tags', { name: tag21 });
      expect([400, 422].includes(overBoundaryTag.res.status), `expected 21-char tag name rejection, got ${overBoundaryTag.res.status} ${JSON.stringify(overBoundaryTag.body)}`).toBe(true);

      // --- Tag: case-insensitive duplicate rejected ---
      const createTag2 = await request('POST', '/api/tags', { name: `TagCase-${suffix}` });
      expect([200, 201].includes(createTag2.res.status), `expected second tag create success, got ${createTag2.res.status} ${JSON.stringify(createTag2.body)}`).toBe(true);
      tag2Id = getId(createTag2.body);
      expect(tag2Id).toBeTruthy();

      const duplicateTagDifferentCase = await request('POST', '/api/tags', { name: `tagcase-${suffix}` });
      expect([400, 409, 422].includes(duplicateTagDifferentCase.res.status), `expected case-insensitive tag duplicate rejection, got ${duplicateTagDifferentCase.res.status} ${JSON.stringify(duplicateTagDifferentCase.body)}`).toBe(true);

      // --- Tag: rename to case-insensitive duplicate rejected ---
      const renameTagToDuplicateDifferentCase = await request('PATCH', `/api/tags/${tagId}`, { name: `tagcase-${suffix}` });
      expect([400, 409, 422].includes(renameTagToDuplicateDifferentCase.res.status), `expected tag rename to duplicate name rejection, got ${renameTagToDuplicateDifferentCase.res.status} ${JSON.stringify(renameTagToDuplicateDifferentCase.body)}`).toBe(true);

      // --- Category with article reference: deletion should be blocked ---
      const articleRes = await request('POST', '/api/articles', {
        title: `RefArticle ${suffix}`,
        content: 'Content for reference test',
        status: 'draft',
        primaryCategoryId: categoryId,
        categoryIds: [categoryId],
        tagIds: [tag2Id],
      });
      expect([200, 201]).toContain(articleRes.res.status);
      articleId = getId(articleRes.body);
      expect(articleId).toBeTruthy();

      // Try to delete category that is used by an article - should be blocked
      const deleteCategoryInUse = await request('DELETE', `/api/categories/${categoryId}`);
      expect([400, 409, 422].includes(deleteCategoryInUse.res.status), `expected category-in-use deletion to be blocked, got ${deleteCategoryInUse.res.status} ${JSON.stringify(deleteCategoryInUse.body)}`).toBe(true);
      // Response should indicate how many articles reference it
      const deleteBody = deleteCategoryInUse.body;
      expect(deleteBody, 'expected error body with reference info').toBeTruthy();

      // --- Tag deletion with article reference: allowed, tag removed from article ---
      const deleteTag2 = await request('DELETE', `/api/tags/${tag2Id}`);
      expect([200, 204].includes(deleteTag2.res.status), `expected tag delete success even when used, got ${deleteTag2.res.status} ${JSON.stringify(deleteTag2.body)}`).toBe(true);
      const deletedTag2Id = tag2Id;
      tag2Id = undefined;

      // Verify deleted tag is gone
      const deletedTagFetch = await request('GET', `/api/tags/${deletedTag2Id}`);
      expect([404, 410].includes(deletedTagFetch.res.status), `expected deleted tag to be inaccessible, got ${deletedTagFetch.res.status}`).toBe(true);

      // Verify the tag was removed from the article
      const articleAfterTagDelete = await request('GET', `/api/articles/${articleId}`);
      expect(articleAfterTagDelete.res.status).toBe(200);
      const articleData = articleAfterTagDelete.body?.data || articleAfterTagDelete.body;
      const articleTags = articleData?.tags || articleData?.tagIds || [];
      const tagIdStrings = articleTags.map(t => String(typeof t === 'object' ? (t.id || t.tagId) : t));
      expect(tagIdStrings).not.toContain(String(deletedTag2Id));

      // --- Delete unreferenced category (category2 has no articles) ---
      const deleteCategory2 = await request('DELETE', `/api/categories/${category2Id}`);
      expect([200, 204].includes(deleteCategory2.res.status), `expected unreferenced category delete success, got ${deleteCategory2.res.status} ${JSON.stringify(deleteCategory2.body)}`).toBe(true);
      category2Id = undefined;

      const deletedCat2Fetch = await request('GET', `/api/categories/${getId(createCategory2.body)}`);
      expect([404, 410].includes(deletedCat2Fetch.res.status), `expected deleted category to be inaccessible, got ${deletedCat2Fetch.res.status}`).toBe(true);

    } finally {
      // Cleanup
      if (articleId) {
        try { await request('DELETE', `/api/articles/${articleId}?permanent=true&confirm=true`); } catch {}
        try { await request('DELETE', `/api/articles/${articleId}?permanent=true`); } catch {}
        try { await request('DELETE', `/api/articles/${articleId}`); } catch {}
      }
      try { if (tag2Id) await request('DELETE', `/api/tags/${tag2Id}`); } catch {}
      try { if (tagId) await request('DELETE', `/api/tags/${tagId}`); } catch {}
      try { if (category2Id) await request('DELETE', `/api/categories/${category2Id}`); } catch {}
      try { if (categoryId) await request('DELETE', `/api/categories/${categoryId}`); } catch {}
    }
  });
});

import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function request(method, path, body) {
  const res = await fetch(`${BASE_URL}${path}`, {
    method,
    headers: { 'Content-Type': 'application/json' },
    body: body === undefined ? undefined : JSON.stringify(body),
  });
  const text = await res.text();
  let json = null;
  try { json = text ? JSON.parse(text) : null; } catch { json = text; }
  return { res, body: json, text };
}

async function tryRequest(method, paths, body) {
  for (const path of paths) {
    const result = await request(method, path, body);
    if (result.res.status !== 404) return result;
  }
  return request(method, paths[0], body);
}

async function tryDelete(path) {
  try { await fetch(`${BASE_URL}${path}`, { method: 'DELETE' }); } catch {}
}

function getId(body) {
  return body?.id || body?.data?.id || body?.categoryId || body?.tagId;
}

function asArray(v) {
  if (Array.isArray(v)) return v;
  if (Array.isArray(v?.items)) return v.items;
  if (Array.isArray(v?.data)) return v.data;
  if (Array.isArray(v?.articles)) return v.articles;
  if (Array.isArray(v?.categories)) return v.categories;
  if (Array.isArray(v?.tags)) return v.tags;
  return [];
}

function getConfig(body) {
  return body?.data || body?.config || body;
}

describe('round15_import_export_compatibility', () => {
  it('should export and import articles/categories/tags/rss/seo, reject invalid archives, support partial failure summary, and map legacy single-category archive to primary category', async () => {
    const unique = `impex-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
    const categoryIds = [];
    const tagIds = [];
    const articleIds = [];

    try {
      // Create a category
      const category = await request('POST', '/api/categories', { name: `ImportCat ${unique}` });
      expect([200, 201]).toContain(category.res.status);
      const categoryId = getId(category.body);
      expect(categoryId).toBeTruthy();
      categoryIds.push(categoryId);

      // Create a tag
      const tag = await request('POST', '/api/tags', { name: `ImportTag ${unique}` });
      expect([200, 201]).toContain(tag.res.status);
      const tagId = getId(tag.body);
      expect(tagId).toBeTruthy();
      tagIds.push(tagId);

      // Save SEO config
      const seo = await tryRequest('PUT', ['/api/seo/config', '/api/seo'], {
        siteTitle: `Imported Site ${unique}`,
        siteDescription: `Imported Desc ${unique}`,
      });
      expect([200, 201]).toContain(seo.res.status);

      // Save RSS/subscription config
      const rss = await tryRequest('PUT', ['/api/rss/config', '/api/subscription/config'], {
        title: `RSS ${unique}`,
        description: `RSS Desc ${unique}`,
        siteUrl: 'https://example.com',
        feedUrl: 'https://example.com/rss',
        articleCount: 10,
        limit: 10,
      });
      expect([200, 201]).toContain(rss.res.status);

      // Create an article
      const article = await request('POST', '/api/articles', {
        title: `ImportExport Article ${unique}`,
        content: 'content for export',
        primaryCategoryId: categoryId,
        categoryIds: [categoryId],
        tagIds: [tagId],
        status: 'published',
        publishedAt: '2024-03-01T10:00:00.000Z',
        publishTime: '2024-03-01T10:00:00.000Z',
      });
      expect([200, 201]).toContain(article.res.status);
      const articleId = getId(article.body);
      expect(articleId).toBeTruthy();
      articleIds.push(articleId);

      // ========== Export all data ==========
      let exportRes = await tryRequest('POST', ['/api/export', '/api/archives/export'], {});
      if (exportRes.res.status === 404 || exportRes.res.status === 405) {
        exportRes = await tryRequest('GET', ['/api/export', '/api/archives/export'], undefined);
      }
      expect([200]).toContain(exportRes.res.status);
      const archive = exportRes.body?.data || exportRes.body;
      expect(typeof archive).toBe('object');

      // Structural assertions on the exported archive
      const archiveArticles = archive.articles || archive.posts || [];
      const archiveCategories = archive.categories || [];
      const archiveTags = archive.tags || [];
      expect(Array.isArray(archiveArticles), 'exported archive should contain articles array').toBe(true);
      expect(archiveArticles.length).toBeGreaterThanOrEqual(1);
      expect(Array.isArray(archiveCategories), 'exported archive should contain categories array').toBe(true);
      expect(archiveCategories.length).toBeGreaterThanOrEqual(1);
      expect(Array.isArray(archiveTags), 'exported archive should contain tags array').toBe(true);
      expect(archiveTags.length).toBeGreaterThanOrEqual(1);

      // Verify specific data exists in the export
      const archiveStr = JSON.stringify(archive);
      expect(archiveStr).toContain(`ImportExport Article ${unique}`);
      expect(archiveStr).toContain(`ImportCat ${unique}`);
      expect(archiveStr).toContain(`ImportTag ${unique}`);

      // Verify SEO and RSS config present in archive
      const hasSeoConfig = archive.seoConfig || archive.seo || archive.seoSettings;
      const hasRssConfig = archive.rssConfig || archive.rss || archive.subscriptionConfig || archive.subscription;
      expect(hasSeoConfig || archiveStr.includes(`Imported Site ${unique}`), 'archive should include SEO config').toBeTruthy();
      expect(hasRssConfig || archiveStr.includes(`RSS ${unique}`), 'archive should include RSS config').toBeTruthy();

      // ========== Delete the created data to simulate "restore" scenario ==========
      await tryDelete(`/api/articles/${articleId}`);
      // Try permanent delete too
      await tryDelete(`/api/articles/${articleId}/permanent`);
      await tryDelete(`/api/articles/${articleId}?permanent=true`);
      await tryDelete(`/api/tags/${tagId}`);
      await tryDelete(`/api/categories/${categoryId}`);
      // Clear tracking since we deleted them
      articleIds.length = 0;
      tagIds.length = 0;
      categoryIds.length = 0;

      // Verify the article is gone
      const listAfterDelete = await request('GET', '/api/articles');
      const itemsAfterDelete = asArray(listAfterDelete.body);
      const stillExists = itemsAfterDelete.find(x => x.title === `ImportExport Article ${unique}`);
      // It might still be in recycle bin, that's ok - we just need to verify import restores

      // ========== Import the exported archive to restore ==========
      const importRes = await tryRequest('POST', ['/api/import', '/api/archives/import'], archive);
      expect([200, 201]).toContain(importRes.res.status);

      // Verify articles restored
      const listAfterImport = await request('GET', '/api/articles');
      expect(listAfterImport.res.status).toBe(200);
      const itemsAfterImport = asArray(listAfterImport.body);
      const restoredArticle = itemsAfterImport.find(x => x.title === `ImportExport Article ${unique}`);
      expect(restoredArticle, `expected article restored after import, got titles: ${JSON.stringify(itemsAfterImport.map(i => i.title))}`).toBeTruthy();
      if (restoredArticle?.id) articleIds.push(restoredArticle.id);

      // Verify categories restored
      const catList = await request('GET', '/api/categories');
      expect(catList.res.status).toBe(200);
      const cats = asArray(catList.body);
