import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function request(method, path, body) {
  const res = await fetch(`${BASE_URL}${path}`, {
    method,
    headers: { 'Content-Type': 'application/json' },
    body: body === undefined ? undefined : JSON.stringify(body),
  });
  const text = await res.text();
  let data = null;
  try {
    data = text ? JSON.parse(text) : null;
  } catch (e) {
    data = text;
  }
  return { res, data, text };
}

async function safeDelete(path) {
  try {
    await fetch(`${BASE_URL}${path}`, { method: 'DELETE' });
  } catch (e) {
    // ignore
  }
}

function unwrap(data) {
  return data?.data || data;
}

function extractId(data) {
  const body = unwrap(data);
  return body?.id || body?.articleId;
}

// Try multiple candidate paths for dashboard
const DASHBOARD_PATHS = [
  '/api/articles/dashboard',
  '/api/dashboard',
  '/api/stats',
  '/api/articles/stats',
];

let resolvedDashboardPath = null;

async function getDashboard() {
  if (resolvedDashboardPath) {
    return request('GET', resolvedDashboardPath);
  }
  for (const path of DASHBOARD_PATHS) {
    const r = await request('GET', path);
    if (r.res.status === 200) {
      resolvedDashboardPath = path;
      return r;
    }
  }
  // fallback to first path
  resolvedDashboardPath = DASHBOARD_PATHS[0];
  return request('GET', resolvedDashboardPath);
}

// Flexibly extract metric values from various possible field names
function readMetric(body, candidates) {
  for (const key of candidates) {
    if (body && body[key] !== undefined && body[key] !== null) return Number(body[key]);
  }
  return undefined;
}

function metricsOf(data) {
  const body = unwrap(data);
  expect(body).toBeTruthy();

  const total = readMetric(body, ['total', 'totalArticles', 'totalCount', 'article_count', 'articlesTotal']);
  const draft = readMetric(body, ['draft', 'draftCount', 'drafts', 'draft_count']);
  const published = readMetric(body, ['published', 'publishedCount', 'publishedArticles', 'published_count']);
  const recycle = readMetric(body, ['recycle', 'recycleCount', 'recycleBin', 'recycle_count', 'recycled', 'trashed', 'trashedCount', 'deleted', 'deletedCount']);
  const subscribable = readMetric(body, ['subscribable', 'subscribableCount', 'eligibleForSubscription', 'rssEligible', 'rss_eligible', 'feedEligible']);
  const excludedPublic = readMetric(body, ['excludedPublic', 'excludedPublicCount', 'publicExcluded', 'excluded', 'excludedCount', 'excluded_public']);

  expect(total, `expected total metric in dashboard response, got keys: ${Object.keys(body).join(', ')}`).not.toBeUndefined();
  expect(draft, `expected draft metric in dashboard response, got keys: ${Object.keys(body).join(', ')}`).not.toBeUndefined();
  expect(published, `expected published metric in dashboard response, got keys: ${Object.keys(body).join(', ')}`).not.toBeUndefined();
  expect(recycle, `expected recycle metric in dashboard response, got keys: ${Object.keys(body).join(', ')}`).not.toBeUndefined();
  expect(subscribable, `expected subscribable metric in dashboard response, got keys: ${Object.keys(body).join(', ')}`).not.toBeUndefined();
  expect(excludedPublic, `expected excludedPublic metric in dashboard response, got keys: ${Object.keys(body).join(', ')}`).not.toBeUndefined();

  return {
    total,
    draft,
    published,
    recycle,
    subscribable,
    excludedPublic,
    raw: body,
  };
}

async function tryRestore(id) {
  let r = await request('POST', `/api/articles/${id}/restore`);
  if (r.res.status === 404 || r.res.status === 405) {
    r = await request('PATCH', `/api/articles/${id}/restore`);
  }
  if (r.res.status === 404 || r.res.status === 405) {
    r = await request('PATCH', `/api/articles/${id}`, { deleted: false });
  }
  return r;
}

async function trySoftDelete(id) {
  let r = await request('DELETE', `/api/articles/${id}`);
  if (r.res.status === 404 || r.res.status === 405) {
    r = await request('POST', `/api/articles/${id}/trash`);
  }
  return r;
}

describe('round30_dashboard_metrics_consistent', () => {
  it('should expose complete zero-state metrics payload with numeric fields', async () => {
    const { res, data } = await getDashboard();
    expect(res.status).toBe(200);
    const m = metricsOf(data);

    expect(typeof m.total).toBe('number');
    expect(typeof m.draft).toBe('number');
    expect(typeof m.published).toBe('number');
    expect(typeof m.recycle).toBe('number');
    expect(typeof m.subscribable).toBe('number');
    expect(typeof m.excludedPublic).toBe('number');

    expect(m.total).toBeGreaterThanOrEqual(0);
    expect(m.draft).toBeGreaterThanOrEqual(0);
    expect(m.published).toBeGreaterThanOrEqual(0);
    expect(m.recycle).toBeGreaterThanOrEqual(0);
    expect(m.subscribable).toBeGreaterThanOrEqual(0);
    expect(m.excludedPublic).toBeGreaterThanOrEqual(0);

    // Zero-state: if total is 0, all sub-counts must also be 0
    if (m.total === 0) {
      expect(m.draft).toBe(0);
      expect(m.published).toBe(0);
      expect(m.recycle).toBe(0);
      expect(m.subscribable).toBe(0);
      expect(m.excludedPublic).toBe(0);
    }
  });

  it('should keep dashboard statistics consistent and react immediately to status, recycle, restore, publish time and primary category changes', async () => {
    const unique = `r30-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
    const ids = [];
    let catId = null;

    try {
      const baseline = await getDashboard();
      expect(baseline.res.status).toBe(200);
      const base = metricsOf(baseline.data);

      const catRes = await request('POST', '/api/categories', { name: `DashCat-${unique}` });
      expect([200, 201]).toContain(catRes.res.status);
      catId = extractId(catRes.data);
      expect(catId).toBeTruthy();

      // Create a draft article
      const draft = await request('POST', '/api/articles', {
        title: `Draft ${unique}`,
        content: 'draft content',
        status: 'draft',
        primaryCategoryId: catId,
        categoryIds: [catId],
      });
      expect([200, 201]).toContain(draft.res.status);
      const draftId = extractId(draft.data);
      ids.push(draftId);

      // Create a fully eligible published article
      const publishedEligible = await request('POST', '/api/articles', {
        title: `Published eligible ${unique}`,
        content: 'eligible content',
        status: 'published',
        publishedAt: new Date(Date.now() - 60000).toISOString(),
        publishTime: new Date(Date.now() - 60000).toISOString(),
        primaryCategoryId: catId,
        categoryIds: [catId],
      });
      expect([200, 201]).toContain(publishedEligible.res.status);
      const publishedEligibleId = extractId(publishedEligible.data);
      ids.push(publishedEligibleId);

      // Create a published article missing publish time => excluded from public
      const publishedExcluded = await request('POST', '/api/articles', {
        title: `Published excluded ${unique}`,
        content: 'excluded content',
        status: 'published',
        publishedAt: new Date(Date.now() - 60000).toISOString(),
        publishTime: new Date(Date.now() - 60000).toISOString(),
        primaryCategoryId: catId,
        categoryIds: [catId],
      });
      expect([200, 201]).toContain(publishedExcluded.res.status);
      const publishedExcludedId = extractId(publishedExcluded.data);
      ids.push(publishedExcludedId);
      // Remove publish time to make it excluded from public preview
      await request('PATCH', `/api/articles/${publishedExcludedId}`, {
        publishedAt: null,
        publishTime: null,
      });

      // Create article then move to recycle bin
      const recycleTarget = await request('POST', '/api/articles', {
        title: `Recycled ${unique}`,
        content: 'recycle content',
        status: 'draft',
        primaryCategoryId: catId,
        categoryIds: [catId],
      });
      expect([200, 201]).toContain(recycleTarget.res.status);
      const recycleTargetId = extractId(recycleTarget.data);
      ids.push(recycleTargetId);

      const moveRecycle = await trySoftDelete(recycleTargetId);
      expect([200, 204]).toContain(moveRecycle.res.status);

      // Check dashboard after creates
      const afterCreate = await getDashboard();
      expect(afterCreate.res.status).toBe(200);
      const m1 = metricsOf(afterCreate.data);

      expect(m1.total - base.total).toBe(4);
      expect(m1.draft - base.draft).toBe(1);
      expect(m1.published - base.published).toBe(2);
      expect(m1.recycle - base.recycle).toBe(1);
      expect(m1.subscribable - base.subscribable).toBe(1);
      expect(m1.excludedPublic - base.excludedPublic).toBe(1);

      // === Restore from recycle bin and verify metrics react ===
      const restoreRes = await tryRestore(recycleTargetId);
      expect([200, 204]).toContain(restoreRes.res.status);

      const afterRestore = await getDashboard();
      expect(afterRestore.res.status).toBe(200);
      const mRestore = metricsOf(afterRestore.data);

      // Recycle count should decrease by 1
      expect(mRestore.recycle).toBe(m1.recycle - 1);
      // Draft count should increase by 1 (restored to original draft state)
      expect(mRestore.draft).toBe(m1.draft + 1);
      // Total stays the same (recycle counts in total)
      expect(mRestore.total).toBe(m1.total);

      // Move it back to recycle for cleanup consistency
      const reRecycle = await trySoftDelete(recycleTargetId);
      expect([200, 204]).toContain(reRecycle.res.status);

      // === Promote draft to published with full eligibility ===
      const draftToPublished = await request('PATCH', `/api/articles/${draftId}`, {
        status: 'published',
        publishedAt: new Date(Date.now() - 60000).toISOString(),
        publishTime: new Date(Date.now() - 60000).toISOString(),
      });
      expect([200, 201, 204]).toContain(draftToPublished.res.status);

      // Fix the excluded article by adding publish time back
      const fixExcluded = await request('PATCH', `/api/articles/${publishedExcludedId}`, {
        publishedAt: new Date(Date.now() - 60000).toISOString(),
        publishTime: new Date(Date.now() - 60000).toISOString(),
      });
      expect([200, 201, 204]).toContain(fixExcluded.res.status);

      const afterUpdate = await getDashboard();
      expect(afterUpdate.res.status).toBe(200);
      const m2 = metricsOf(afterUpdate.data);

      // Re-read baseline after restore cycle: draft was promoted, excluded was fixed, recycle target back in recycle
      // draft count: m1.draft+1 (after restore) - 1 (promoted) = m1.draft
      // but we re-recycled, so draft goes back: m1.draft+1-1 = m1.draft, then re-recycled so m1.draft-1
      // Actually let's just compare from the m1 snapshot before restore:
      // After re-recycle, we're back to m1 state for recycle/draft.
      // Then promoted draft->published: draft -1, published +1
      // Fixed excluded: subscribable +1, excludedPublic -1
      expect(m2.draft).toBe(m1.draft - 1);
      expect(m2.published).toBe(m1.published + 1);
      expect(m2.recycle).toBe(m1.recycle);
      expect(m2.subscribable).toBe(m1.subscribable + 2);
      expect(m2.excludedPublic).toBe(m1.excludedPublic - 1);

      // === published -> draft (reverse status change) ===
      const publishedToDraft = await request('PATCH', `/api/articles/${draftId}`, {
        status: 'draft',
      });
      expect([200, 201, 204]).toContain(publishedToDraft.res.status);

      const afterReverse = await getDashboard();
      expect(afterReverse.res.status).toBe(200);
      const m3 = metricsOf(afterReverse.data);

      expect(m3.draft).toBe(m2.draft + 1);
      expect(m3.published).toBe(m2.published - 1);
      // subscribable should decrease (was eligible, now draft)
      expect(m3.subscribable).toBe(m2.subscribable - 1);

      // === Remove primary category from an eligible published article ===
      const removePrimaryCategory = await request('PATCH', `/api/articles/${publishedEligibleId}`, {
        primaryCategoryId: null,
        categoryIds: [],
      });
      expect([200, 201, 204]).toContain(removePrimaryCategory.res.status);

      const afterCategoryChange = await getDashboard();
      expect(afterCategoryChange.res.status).toBe(200);
      const m4 = metricsOf(afterCategoryChange.data);

      expect(m4.total).toBe(m3.total);
      expect(m4.published).toBe(m3.published);
      expect(m4.recycle).toBe(m3.recycle);
      expect(m4.subscribable).toBe(m3.subscribable - 1);
      expect(m4.excludedPublic).toBe(m3.excludedPublic + 1);
    } finally {
      for (const id of ids) {
        await safeDelete(`/api/articles/${id}?permanent=true&confirm=true`);
        await safeDelete(`/api/articles/${id}?permanent=true`);
        await safeDelete(`/api/articles/${id}`);
      }
      if (catId) {
        await safeDelete(`/api/categories/${catId}`);
      }
    }
  });
});

