import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function request(method, path, body) {
  const res = await fetch(`${BASE_URL}${path}`, {
    method,
    headers: { 'Content-Type': 'application/json' },
    body: body !== undefined ? JSON.stringify(body) : undefined,
  });
  const text = await res.text();
  let json;
  try {
    json = text ? JSON.parse(text) : null;
  } catch {
    json = text;
  }
  return { res, body: json };
}

async function safeDeleteArticle(id) {
  try {
    await request('DELETE', `/articles/${id}`);
  } catch {}
}

async function safeDeleteCategory(id) {
  try {
    await request('DELETE', `/categories/${id}`);
  } catch {}
}

describe('article_status_transitions_enforced', () => {
  let articleId;
  let categoryId;

  async function createCategoryAndDraft() {
    const categoryName = `cat-status-${Date.now()}`;
    const { res: catRes, body: catBody } = await request('POST', '/categories', { name: categoryName });
    expect([200, 201].includes(catRes.status), `expected category create success, got ${catRes.status} ${JSON.stringify(catBody)}`).toBe(true);
    categoryId = catBody?.id;
    expect(categoryId, `expected category id in response, got ${JSON.stringify(catBody)}`).toBeTruthy();

    const { res: draftRes, body: draftBody } = await request('POST', '/articles', {
      title: `status-article-${Date.now()}`,
      content: 'draft body',
      summary: 'draft summary',
      status: 'draft',
      categories: [{ id: categoryId, isPrimary: true }],
    });
    expect([200, 201].includes(draftRes.status), `expected article draft create success, got ${draftRes.status} ${JSON.stringify(draftBody)}`).toBe(true);
    articleId = draftBody?.id;
    expect(articleId, `expected article id in response, got ${JSON.stringify(draftBody)}`).toBeTruthy();
    expect(draftBody?.status, `expected initial status draft, got ${JSON.stringify(draftBody)}`).toBe('draft');
  }

  it('should reject publish when publishedAt is missing', async () => {
    await createCategoryAndDraft();
    try {
      const invalidPublish = await request('PATCH', `/articles/${articleId}`, {
        status: 'published',
        publishedAt: null,
      });
      expect(
        [400, 422].includes(invalidPublish.res.status),
        `expected publish without publishedAt to be rejected, got ${invalidPublish.res.status} ${JSON.stringify(invalidPublish.body)}`
      ).toBe(true);
    } finally {
      if (articleId) await safeDeleteArticle(articleId);
      if (categoryId) await safeDeleteCategory(categoryId);
      articleId = undefined;
      categoryId = undefined;
    }
  });

  it('should reject publish when title is empty', async () => {
    await createCategoryAndDraft();
    try {
      const invalidPublish = await request('PATCH', `/articles/${articleId}`, {
        title: '',
        status: 'published',
        publishedAt: new Date().toISOString(),
        categories: [{ id: categoryId, isPrimary: true }],
      });
      expect(
        [400, 422].includes(invalidPublish.res.status),
        `expected publish with empty title to be rejected, got ${invalidPublish.res.status} ${JSON.stringify(invalidPublish.body)}`
      ).toBe(true);
    } finally {
      if (articleId) await safeDeleteArticle(articleId);
      if (categoryId) await safeDeleteCategory(categoryId);
      articleId = undefined;
      categoryId = undefined;
    }
  });

  it('should reject publish when content is empty', async () => {
    await createCategoryAndDraft();
    try {
      const invalidPublish = await request('PATCH', `/articles/${articleId}`, {
        content: '',
        status: 'published',
        publishedAt: new Date().toISOString(),
        categories: [{ id: categoryId, isPrimary: true }],
      });
      expect(
        [400, 422].includes(invalidPublish.res.status),
        `expected publish with empty content to be rejected, got ${invalidPublish.res.status} ${JSON.stringify(invalidPublish.body)}`
      ).toBe(true);
    } finally {
      if (articleId) await safeDeleteArticle(articleId);
      if (categoryId) await safeDeleteCategory(categoryId);
      articleId = undefined;
      categoryId = undefined;
    }
  });

  it('should reject publish when primary category is missing', async () => {
    await createCategoryAndDraft();
    try {
      const invalidPublish = await request('PATCH', `/articles/${articleId}`, {
        status: 'published',
        publishedAt: new Date().toISOString(),
        categories: [],
      });
      expect(
        [400, 422].includes(invalidPublish.res.status),
        `expected publish without primary category to be rejected, got ${invalidPublish.res.status} ${JSON.stringify(invalidPublish.body)}`
      ).toBe(true);
    } finally {
      if (articleId) await safeDeleteArticle(articleId);
      if (categoryId) await safeDeleteCategory(categoryId);
      articleId = undefined;
      categoryId = undefined;
    }
  });

  it('should allow valid publish and full status transition cycle', async () => {
    await createCategoryAndDraft();
    try {
      // Valid publish
      const validPublish = await request('PATCH', `/articles/${articleId}`, {
        title: `status-article-${Date.now()}-published`,
        content: 'publishable content',
        status: 'published',
        publishedAt: new Date().toISOString(),
        categories: [{ id: categoryId, isPrimary: true }],
      });
      expect([200, 201].includes(validPublish.res.status), `expected valid publish success, got ${validPublish.res.status} ${JSON.stringify(validPublish.body)}`).toBe(true);
      expect(validPublish.body?.status, `expected status published, got ${JSON.stringify(validPublish.body)}`).toBe('published');

      // Revert to draft
      const backToDraft = await request('PATCH', `/articles/${articleId}`, { status: 'draft' });
      expect([200, 201].includes(backToDraft.res.status), `expected revert to draft success, got ${backToDraft.res.status} ${JSON.stringify(backToDraft.body)}`).toBe(true);
      expect(backToDraft.body?.status, `expected reverted status draft, got ${JSON.stringify(backToDraft.body)}`).toBe('draft');

      // Archive
      const archiveRes = await request('PATCH', `/articles/${articleId}`, { status: 'archived' });
      expect([200, 201].includes(archiveRes.res.status), `expected archive success, got ${archiveRes.res.status} ${JSON.stringify(archiveRes.body)}`).toBe(true);
      expect(archiveRes.body?.status, `expected archived status, got ${JSON.stringify(archiveRes.body)}`).toBe('archived');

      // Restore from archive to draft
      const restoreRes = await request('PATCH', `/articles/${articleId}`, { status: 'draft' });
      expect([200, 201].includes(restoreRes.res.status), `expected restore from archive success, got ${restoreRes.res.status} ${JSON.stringify(restoreRes.body)}`).toBe(true);
      expect(restoreRes.body?.status, `expected restored status draft, got ${JSON.stringify(restoreRes.body)}`).toBe('draft');
    } finally {
      if (articleId) await safeDeleteArticle(articleId);
      if (categoryId) await safeDeleteCategory(categoryId);
      articleId = undefined;
      categoryId = undefined;
    }
  });

  it('should reject editing content of an archived article without restoring first', async () => {
    await createCategoryAndDraft();
    try {
      // Archive the article
      const archiveRes = await request('PATCH', `/articles/${articleId}`, { status: 'archived' });
      expect([200, 201].includes(archiveRes.res.status), `expected archive success, got ${archiveRes.res.status} ${JSON.stringify(archiveRes.body)}`).toBe(true);
      expect(archiveRes.body?.status).toBe('archived');

      // Try to edit content while archived (without changing status)
      const editWhileArchived = await request('PATCH', `/articles/${articleId}`, {
        content: 'trying to edit archived content',
      });
      expect(
        [400, 403, 422].includes(editWhileArchived.res.status),
        `expected editing archived article content to be rejected, got ${editWhileArchived.res.status} ${JSON.stringify(editWhileArchived.body)}`
      ).toBe(true);
    } finally {
      if (articleId) await safeDeleteArticle(articleId);
      if (categoryId) await safeDeleteCategory(categoryId);
      articleId = undefined;
      categoryId = undefined;
    }
  });
});

import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function request(method, path, body) {
  const res = await fetch(`${BASE_URL}${path}`, {
    method,
    headers: { 'Content-Type': 'application/json' },
    body: body === undefined ? undefined : JSON.stringify(body),
  });
  const text = await res.text();
  let json = null;
  try { json = text ? JSON.parse(text) : null; } catch { json = text; }
  return { res, body: json, text };
}

async function tryDelete(path) {
  try { await fetch(`${BASE_URL}${path}`, { method: 'DELETE' }); } catch {}
}

function pick(obj, keys) {
  for (const key of keys) if (obj && obj[key] !== undefined) return obj[key];
}
function asArray(v) {
  if (Array.isArray(v)) return v;
  if (v?.items && Array.isArray(v.items)) return v.items;
  if (v?.articles && Array.isArray(v.articles)) return v.articles;
  if (v?.data && Array.isArray(v.data)) return v.data;
  return [];
}

function extractId(obj) {
  if (!obj) return undefined;
  return obj.id || obj.categoryId || obj.articleId || obj.data?.id;
}

