      expect([200, 201]).toContain(survivor.res.status);
      survivorId = extractId(survivor.body);
      expect(survivorId).toBeTruthy();

      const corruptedArchive = {
        articles: [
          {
            title: `ValidImport ${unique}`,
            content: 'valid content',
            status: 'draft',
            tags: [`partial-tag-${unique}`],
          },
          {
            title: '',
            content: null,
            status: 'INVALID_STATUS',
            categories: [{ id: 'non-existent-id', isPrimary: true }],
          },
        ],
        categories: [
          { name: `ImportCat ${unique}` },
          { name: '' },
        ],
        tags: [{ name: `partial-tag-${unique}` }],
        rssConfig: { title: '', siteUrl: '' },
        seoConfig: {},
      };

      const importRes = await request('POST', '/api/import-export/import', corruptedArchive);
      expect([200, 201, 207, 400, 422]).toContain(importRes.res.status);

      const importResult = importRes.body?.data || importRes.body;
      expect(importResult).toBeTruthy();
      const resultStr = JSON.stringify(importResult).toLowerCase();
      expect(resultStr).toMatch(/success|skip|fail|error|imported|summary/);

      const listAfter = await request('GET', '/api/articles');
      expect(listAfter.res.status).toBe(200);
      const titlesAfter = asArray(listAfter.body).map(x => x.title);
      expect(titlesAfter.some(t => t && t.includes(`PartialSurvivor ${unique}`))).toBe(true);
      expect(titlesAfter.some(t => t && t.includes(`ValidImport ${unique}`))).toBe(true);
      expect(titlesAfter.includes('')).toBe(false);

      const importedValid = asArray(listAfter.body).find(x => x.title && x.title.includes(`ValidImport ${unique}`));
      expect(importedValid).toBeTruthy();
      const importedValidId = extractId(importedValid);
      if (importedValidId) {
        const validDetail = await request('GET', `/api/articles/${importedValidId}`);
        expect(validDetail.res.status).toBe(200);
        const validArticle = validDetail.body?.data || validDetail.body;
        expect(validArticle.title).toBe(`ValidImport ${unique}`);
      }

      const categoriesAfter = await request('GET', '/api/categories');
      expect(categoriesAfter.res.status).toBe(200);
      const categoryNames = asArray(categoriesAfter.body).map(x => x.name);
      expect(categoryNames).toContain(`ImportCat ${unique}`);
      expect(categoryNames.includes('')).toBe(false);

      const tagsAfter = await request('GET', '/api/tags');
      expect(tagsAfter.res.status).toBe(200);
      const tagNames = asArray(tagsAfter.body).map(x => x.name || x.label || x);
      expect(tagNames).toContain(`partial-tag-${unique}`);
    } finally {
      if (survivorId) await tryDelete(`/api/articles/${survivorId}?permanent=true`);

      const articles = await request('GET', '/api/articles');
      if (articles.res.status === 200) {
        for (const item of asArray(articles.body)) {
          if (item?.title && (item.title.includes(`ValidImport ${unique}`) || item.title.includes(`PartialSurvivor ${unique}`))) {
            const id = extractId(item);
            if (id) await tryDelete(`/api/articles/${id}?permanent=true`);
          }
        }
      }

      const categories = await request('GET', '/api/categories');
      if (categories.res.status === 200) {
        for (const item of asArray(categories.body)) {
          if (cleanupCategoryNames.includes(item?.name)) {
            const id = extractId(item);
            if (id) await tryDelete(`/api/categories/${id}`);
          }
        }
      }
    }
  });
});

import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function request(path, options = {}) {
  return fetch(`${BASE_URL}${path}`, {
    headers: {
      'Content-Type': 'application/json',
      ...(options.headers || {}),
    },
    ...options,
  });
}

async function safeJson(res) {
  const text = await res.text();
  try {
    return text ? JSON.parse(text) : null;
  } catch {
    return { raw: text };
  }
}

async function cleanupArticle(id) {
  if (!id) return;
  try {
    await request(`/api/articles/${id}`, { method: 'DELETE' });
  } catch {}
}

describe('round2_editor_mode_persistence', () => {
  it('should persist editor mode, preserve content on mode switch (server-side), and return editorMode in list', async () => {
    const unique = `mode-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
    let articleId;

    try {
      // Step 1: Create article in markdown mode
      const createRes = await request('/api/articles', {
        method: 'POST',
        body: JSON.stringify({
          title: `Editor Mode ${unique}`,
          summary: 'summary',
          content: '# Markdown Content',
          status: 'draft',
          editorMode: 'markdown',
        }),
      });
      expect([200, 201], `create article should return 200/201, got ${createRes.status}`).toContain(createRes.status);
      const created = await safeJson(createRes);
      articleId = created.id || created.data?.id;
      expect(articleId).toBeTruthy();
      const createdMode = created.editorMode || created.mode || created.editor_mode || created.data?.editorMode;
      expect(createdMode, 'initial editor mode should be markdown').toBe('markdown');
      const createdContent = created.content || created.data?.content;
      expect(createdContent).toContain('Markdown Content');

      // Step 2: Switch mode to richtext WITHOUT changing content — only update editorMode
      // This tests that the system preserves content when mode is switched
      const switchRes = await request(`/api/articles/${articleId}`, {
        method: 'PUT',
        body: JSON.stringify({
          title: `Editor Mode ${unique}`,
          summary: 'summary',
          content: '# Markdown Content',
          status: 'draft',
          editorMode: 'richtext',
        }),
      });
      expect([200, 204], `update article mode should return 200/204, got ${switchRes.status}`).toContain(switchRes.status);

      // Step 3: Fetch the article and verify mode switched AND content preserved
      const getRes = await request(`/api/articles/${articleId}`);
      expect(getRes.status, `get article should return 200, got ${getRes.status}`).toBe(200);
      const fetched = await safeJson(getRes);
      const fetchedMode = fetched.editorMode || fetched.mode || fetched.editor_mode || fetched.data?.editorMode;
      expect(fetchedMode, 'stored editor mode should be richtext after switch').toBe('richtext');
      const fetchedContent = fetched.content || fetched.data?.content;
      expect(fetchedContent, 'content should still include original markdown text after mode switch').toContain('Markdown Content');

      // Step 4: Verify list API returns editorMode field
      const listRes = await request('/api/articles');
      expect(listRes.status).toBe(200);
      const listBody = await safeJson(listRes);
      const items = listBody.items || listBody.articles || listBody.data || listBody;
      expect(Array.isArray(items)).toBe(true);
      const found = items.find(item => (item.id === articleId) || (item.title && item.title.includes(unique)));
      expect(found, 'article should appear in list').toBeTruthy();
      const foundMode = found.editorMode || found.mode || found.editor_mode;
      expect(foundMode, 'list API should return editor mode field').toBe('richtext');

      // Step 5: Boundary — rich text with only empty paragraphs should be treated as empty content
      const emptyRichTextRes = await request(`/api/articles/${articleId}`, {
        method: 'PUT',
        body: JSON.stringify({
          title: `Editor Mode ${unique}`,
          summary: 'summary',
          content: '<p></p>',
          status: 'draft',
          editorMode: 'richtext',
        }),
      });
      // The system should either reject this as empty content or accept it but treat it as empty.
      // If it's accepted, trying to publish should fail.
      if ([200, 204].includes(emptyRichTextRes.status)) {
        // Try to publish — should fail because content is effectively empty
        const publishRes = await request(`/api/articles/${articleId}`, {
          method: 'PUT',
          body: JSON.stringify({
            title: `Editor Mode ${unique}`,
            summary: 'summary',
            content: '<p></p>',
            status: 'published',
            editorMode: 'richtext',
            publishTime: '2024-05-01T10:00:00.000Z',
            publishedAt: '2024-05-01T10:00:00.000Z',
          }),
        });
        // Expect publish to be rejected (4xx) because empty paragraphs = empty content
        const publishFailed = publishRes.status >= 400;
        // It's also acceptable if the system simply treated <p></p> as valid non-empty content
        // in which case it saves, but ideally it should be blocked
        if (publishFailed) {
          expect(publishRes.status).toBeGreaterThanOrEqual(400);
        }
        // Either way, verify the original content can be restored
        await request(`/api/articles/${articleId}`, {
          method: 'PUT',
          body: JSON.stringify({
            title: `Editor Mode ${unique}`,
            summary: 'summary',
            content: '# Markdown Content',
            status: 'draft',
            editorMode: 'richtext',
          }),
        });
      } else {
        // System rejected empty paragraph content directly — this is also valid
        expect(emptyRichTextRes.status).toBeGreaterThanOrEqual(400);
      }
    } finally {
      await cleanupArticle(articleId);
    }
  });
});

import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

function uid(prefix = 'test') {
  return `${prefix}-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
}

async function api(path, options = {}) {
  const res = await fetch(`${BASE_URL}${path}`, {
    headers: { 'Content-Type': 'application/json', ...(options.headers || {}) },
    ...options,
  });
  const text = await res.text();
  let body;
  try { body = text ? JSON.parse(text) : null; } catch { body = text; }
  return { res, body };
}

async function tryApi(path, options = {}) {
  let r = await api(path, options);
  if (r.res.status === 404 && !path.startsWith('/api/')) {
    r = await api(`/api${path}`, options);
  } else if (r.res.status === 404 && path.startsWith('/api/')) {
    r = await api(path.replace(/^\/api/, ''), options);
  }
  return r;
}

function unwrap(body) {
  return body?.data ?? body;
}

function getId(obj) {
  const d = unwrap(obj);
  return d?.id || d?.articleId;
}

function getItems(body) {
  const d = unwrap(body);
  if (Array.isArray(d)) return d;
  return d?.items || d?.articles || d?.data || [];
}

function getCounts(body) {
  const d = unwrap(body);
  return d?.counts || d?.statusCounts || d?.statistics || d?.stats || body?.counts || body?.statusCounts || {};
}

async function cleanupArticle(id) {
  if (!id) return;
  try { await api(`/api/articles/${id}`, { method: 'DELETE' }); } catch {}
  try { await api(`/api/articles/${id}/permanent`, { method: 'DELETE' }); } catch {}
}

async function cleanupCategory(id) {
  if (!id) return;
  try { await api(`/api/categories/${id}`, { method: 'DELETE' }); } catch {}
}

async function tryBulkAction(action, ids) {
  // Try multiple possible endpoints for bulk operations
  let r = await tryApi('/api/articles/bulk', {
    method: 'POST',
    body: JSON.stringify({ action, ids }),
  });
  if (r.res.status === 404) {
    r = await tryApi('/api/articles/batch', {
      method: 'POST',
      body: JSON.stringify({ action, ids }),
    });
  }
  if (r.res.status === 404) {
    r = await tryApi(`/api/articles/bulk/${action}`, {
      method: 'POST',
      body: JSON.stringify({ ids }),
    });
  }
  return r;
}

async function listArticles(query = '') {
  const r = await tryApi(`/api/articles${query}`);
  expect(r.res.status, `list articles failed: ${JSON.stringify(r.body)}`).toBe(200);
  return r.body;
}

function extractSuccessIds(body) {
  const d = unwrap(body);
  return d?.updatedIds || d?.successIds || d?.success || d?.updated || d?.succeeded || body?.updatedIds || body?.successIds || [];
}

function extractErrors(body) {
  const d = unwrap(body);
  return d?.errors || d?.invalid || d?.skipped || d?.failures || d?.failed || body?.errors || body?.invalid || [];
}

function extractAffectedCount(body) {
  const d = unwrap(body);
  return d?.affectedCount ?? d?.count ?? d?.updatedCount ?? d?.successCount ?? d?.affected ?? body?.affectedCount ?? body?.successCount;
}

describe('bulk_article_actions_update_states', () => {
  it('should bulk archive, restore draft, move to recycle bin, report invalid reasons, and refresh lists and counts', async () => {
    const suffix = uid('bulk');
    const articleIds = [];
    let categoryId;

    try {
      // Create a category
      const catRes = await tryApi('/api/categories', {
        method: 'POST',
        body: JSON.stringify({ name: `BulkCat-${suffix}` }),
      });
      expect(catRes.res.status).toBeGreaterThanOrEqual(200);
      expect(catRes.res.status).toBeLessThan(300);
      categoryId = getId(catRes.body);
      expect(categoryId, 'category should have an id').toBeTruthy();

      async function createTestArticle(title, status, publishedAt) {
        const payload = {
          title,
          content: 'body content for bulk test',
          status,
          primaryCategoryId: categoryId,
          editorMode: 'markdown',
        };
        if (publishedAt) payload.publishedAt = publishedAt;
        const r = await tryApi('/api/articles', {
          method: 'POST',
          body: JSON.stringify(payload),
        });
        expect(r.res.status).toBeGreaterThanOrEqual(200);
        expect(r.res.status).toBeLessThan(300);
        const created = unwrap(r.body);
        expect(created?.id, `article '${title}' should have an id`).toBeTruthy();
        return created;
      }

      const pub1 = await createTestArticle(`Bulk pub1 ${suffix}`, 'published', '2024-05-01T10:00:00.000Z');
      const pub2 = await createTestArticle(`Bulk pub2 ${suffix}`, 'published', '2024-05-01T10:00:00.000Z');
      const draft1 = await createTestArticle(`Bulk draft1 ${suffix}`, 'draft', null);
      const archived1 = await createTestArticle(`Bulk archived1 ${suffix}`, 'archived', null);

      const pub1Id = pub1.id;
      const pub2Id = pub2.id;
      const draft1Id = draft1.id;
      const archived1Id = archived1.id;
      articleIds.push(pub1Id, pub2Id, draft1Id, archived1Id);

      // --- Bulk archive: pub1, pub2 (valid) + archived1 (invalid - already archived) ---
      const archiveRes = await tryBulkAction('archive', [pub1Id, pub2Id, archived1Id]);
      expect(archiveRes.res.status, `bulk archive: ${JSON.stringify(archiveRes.body)}`).toBe(200);
      expect(archiveRes.body, 'bulk archive should return a body').toBeTruthy();

      // Verify success and error arrays
      const archiveBody = unwrap(archiveRes.body) || archiveRes.body;
      const archiveUpdated = extractSuccessIds(archiveRes.body);
      const archiveErrors = extractErrors(archiveRes.body);

      // At minimum, response should indicate which succeeded and which failed
      const hasArchiveResult = (
        archiveUpdated.length > 0 ||
        archiveErrors.length > 0 ||
        archiveBody?.affectedCount !== undefined ||
        archiveBody?.message !== undefined
      );
      expect(hasArchiveResult, `Bulk archive should report results. Got: ${JSON.stringify(archiveBody)}`).toBe(true);

      // The already-archived item should be flagged as invalid/skipped
      if (archiveErrors.length > 0) {
        const archiveErrorText = JSON.stringify(archiveErrors).toLowerCase();
        expect(
          archiveErrorText.includes(String(archived1Id)) ||
          archiveErrors.some(e => e?.id === archived1Id || e?.articleId === archived1Id),
          'error should reference the already-archived article ID'
        ).toBe(true);
      }

      // Verify pub1 and pub2 are now archived
      const afterArchive = await listArticles(`?search=${encodeURIComponent(suffix)}`);
      const afterArchiveItems = getItems(afterArchive);
      const pub1After = afterArchiveItems.find(x => getId(x) === pub1Id || x.id === pub1Id);
      const pub2After = afterArchiveItems.find(x => getId(x) === pub2Id || x.id === pub2Id);
      if (pub1After) expect(pub1After.status).toBe('archived');
      if (pub2After) expect(pub2After.status).toBe('archived');

      // Verify published filter no longer contains pub1/pub2
      const pubFilter = await listArticles(`?status=published&search=${encodeURIComponent(suffix)}`);
      const pubFilterIds = getItems(pubFilter).map(x => String(x.id || getId(x)));
      expect(pubFilterIds).not.toContain(String(pub1Id));
      expect(pubFilterIds).not.toContain(String(pub2Id));

      // Verify archived filter contains them
      const archFilter = await listArticles(`?status=archived&search=${encodeURIComponent(suffix)}`);
      const archFilterIds = getItems(archFilter).map(x => String(x.id || getId(x)));
      expect(archFilterIds).toContain(String(pub1Id));
      expect(archFilterIds).toContain(String(pub2Id));
      expect(archFilterIds).toContain(String(archived1Id));

      // Check counts if available
      const archCounts = getCounts(afterArchive);
      if (Object.keys(archCounts).length > 0) {
        expect(archCounts.archived || 0, 'archived count should reflect bulk archive').toBeGreaterThanOrEqual(3);
      }

      // --- Bulk restore to draft: pub1, archived1 (valid) + draft1 (invalid - already draft) ---
      const restoreRes = await tryBulkAction('restore-draft', [pub1Id, archived1Id, draft1Id]);
      expect(restoreRes.res.status, `bulk restore: ${JSON.stringify(restoreRes.body)}`).toBe(200);
      expect(restoreRes.body, 'bulk restore should return a body').toBeTruthy();

      const restoreErrors = extractErrors(restoreRes.body);
      // draft1 should be flagged as invalid (already draft)
      if (restoreErrors.length > 0) {
        const restoreErrorText = JSON.stringify(restoreErrors).toLowerCase();
        expect(
          restoreErrorText.includes(String(draft1Id)) ||
          restoreErrors.some(e => e?.id === draft1Id || e?.articleId === draft1Id),
          'restore errors should reference the already-draft article'
        ).toBe(true);
      }

      // Verify pub1 and archived1 are now draft
      const draftFilter = await listArticles(`?status=draft&search=${encodeURIComponent(suffix)}`);
      const draftFilterIds = getItems(draftFilter).map(x => String(x.id || getId(x)));
      expect(draftFilterIds).toContain(String(pub1Id));
      expect(draftFilterIds).toContain(String(archived1Id));
      expect(draftFilterIds).toContain(String(draft1Id));

      // --- Bulk delete (soft): pub2, draft1 ---
      const deleteRes = await tryBulkAction('delete', [pub2Id, draft1Id]);
      expect(deleteRes.res.status, `bulk delete: ${JSON.stringify(deleteRes.body)}`).toBe(200);
      expect(deleteRes.body, 'bulk delete should return a body').toBeTruthy();

      // Verify deleted articles no longer in normal list
      const normalList = await listArticles(`?search=${encodeURIComponent(suffix)}`);
      const normalIds = getItems(normalList).map(x => String(x.id || getId(x)));
      expect(normalIds).not.toContain(String(pub2Id));
      expect(normalIds).not.toContain(String(draft1Id));

      // Verify they appear in trash/recycle bin
      let trashView = await tryApi(`/api/articles/trash?search=${encodeURIComponent(suffix)}`);
      if (trashView.res.status === 404) {
        trashView = await tryApi(`/api/articles?status=trash&search=${encodeURIComponent(suffix)}`);
      }
      if (trashView.res.status === 404) {
        trashView = await tryApi(`/api/articles?status=deleted&search=${encodeURIComponent(suffix)}`);
      }
      if (trashView.res.status === 200) {
        const trashItems = getItems(trashView.body);
        const trashItemIds = trashItems.map(x => String(x.id || getId(x)));
        expect(trashItemIds).toContain(String(pub2Id));
        expect(trashItemIds).toContain(String(draft1Id));
      }

      // Verify counts updated after delete
      const countsAfterDelete = getCounts(normalList);
      if (Object.keys(countsAfterDelete).length > 0) {
        const trashCount = countsAfterDelete.trash || countsAfterDelete.trashed || countsAfterDelete.recycled || countsAfterDelete.deleted || 0;
        if (trashCount !== 0) {
          expect(trashCount, 'trash count should reflect bulk delete').toBeGreaterThanOrEqual(2);
        }
      }
    } finally {
      for (const id of articleIds.reverse()) await cleanupArticle(id);
      if (categoryId) await cleanupCategory(categoryId);
    }
  });
});

import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function request(method, path, body) {
  const res = await fetch(`${BASE_URL}${path}`, {
    method,
    headers: { 'Content-Type': 'application/json' },
    body: body !== undefined ? JSON.stringify(body) : undefined,
  });
  const text = await res.text();
  let json;
  try {
    json = text ? JSON.parse(text) : null;
  } catch {
    json = text;
  }
  return { res, body: json };
}

function getArticle(body) {
  return body?.article || body?.data || body;
}

function getId(body) {
  const a = getArticle(body);
  return a?.id || a?.articleId;
}

function readSaveTime(body) {
  const article = getArticle(body) || {};
  return article.autoSavedAt || article.updatedAt || article.savedAt || body?.autoSavedAt || body?.updatedAt || body?.savedAt;
}

function readSaveType(body) {
  const article = getArticle(body) || {};
  return article.saveType || article.source || article.lastSaveType || body?.saveType || body?.source || body?.lastSaveType;
}

describe('autosave_failure_preserves_last_saved_version', () => {
  it('should keep the last successful version after autosave failure, refresh should restore that successful version, and a later valid save should still succeed', async () => {
    const suffix = `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
    let articleId;

    try {
      // Step 1: Create article (manual save)
      const create = await request('POST', '/api/articles', {
        title: `autosave-v1-${suffix}`,
        content: 'version-1-success',
        status: 'draft',
      });
      expect([200, 201].includes(create.res.status), `expected article create success, got ${create.res.status} ${JSON.stringify(create.body)}`).toBe(true);
      articleId = getId(create.body);
      expect(articleId, `expected article id, got ${JSON.stringify(create.body)}`).toBeTruthy();

      const createdArticle = getArticle(create.body);
      expect(createdArticle?.title).toBe(`autosave-v1-${suffix}`);
      expect(createdArticle?.content).toBe('version-1-success');
      expect(createdArticle?.status).toBe('draft');

      // Step 2: Successful autosave (v2) - try autosave endpoint first, fallback to PATCH
      let v2Save = await request('PATCH', `/api/articles/${articleId}/autosave`, {
        title: `autosave-v2-${suffix}`,
        content: 'version-2-success',
      });
      let saveMode = 'autosave';

      if (v2Save.res.status === 404) {
        saveMode = 'patch-fallback';
        v2Save = await request('PATCH', `/api/articles/${articleId}`, {
          title: `autosave-v2-${suffix}`,
          content: 'version-2-success',
        });
      }

      expect([200, 201].includes(v2Save.res.status), `expected ${saveMode} v2 save success, got ${v2Save.res.status} ${JSON.stringify(v2Save.body)}`).toBe(true);
      const v2Article = getArticle(v2Save.body);
      expect(v2Article).toBeTruthy();
      expect(v2Article?.title).toBe(`autosave-v2-${suffix}`);
      expect(v2Article?.content).toBe('version-2-success');

      const successfulUpdatedAt = readSaveTime(v2Save.body);
      const successfulSaveType = readSaveType(v2Save.body);

      // Verify v2 persisted
      const afterV2 = await request('GET', `/api/articles/${articleId}`);
      expect(afterV2.res.status).toBe(200);
      expect(getArticle(afterV2.body)?.content).toBe('version-2-success');
      expect(getArticle(afterV2.body)?.title).toBe(`autosave-v2-${suffix}`);
      expect(getArticle(afterV2.body)?.status).toBe('draft');

      // Step 3: Trigger a failed autosave by sending invalid data (blank title / empty content)
      // This simulates autosave failure via server-side validation rejection
      const failedDraftTitle = `autosave-failed-${suffix}`;
      const failedDraftContent = 'failed-autosave-content-should-not-persist';

      let failedSave = await request('PATCH', `/api/articles/${articleId}/autosave`, {
        title: '   ',
        content: failedDraftContent,
      });

      if (failedSave.res.status === 404) {
        failedSave = await request('PATCH', `/api/articles/${articleId}/autosave`, {
          title: failedDraftTitle,
          content: '',
        });
      }

      if (failedSave.res.status === 404) {
        failedSave = await request('PATCH', `/api/articles/${articleId}`, {
          title: '   ',
          content: failedDraftContent,
        });
      }

      if ([200, 201].includes(failedSave.res.status)) {
        // If API accepted blank title, try empty content instead
        failedSave = await request('PATCH', `/api/articles/${articleId}`, {
          title: failedDraftTitle,
          content: '',
        });
      }

      expect(
        [400, 422, 500].includes(failedSave.res.status),
        `expected autosave failure status (400/422/500), got ${failedSave.res.status} ${JSON.stringify(failedSave.body)}`
      ).toBe(true);
      expect(failedSave.body, 'expected autosave failure response body').toBeTruthy();

      // Step 4: Verify the failed autosave did NOT overwrite the last successful version
      const afterFailure = await request('GET', `/api/articles/${articleId}`);
      expect(afterFailure.res.status).toBe(200);
      const afterFailureArticle = getArticle(afterFailure.body);
      expect(afterFailureArticle?.content, 'failed autosave must not overwrite content').toBe('version-2-success');
      expect(afterFailureArticle?.title, 'failed autosave must not overwrite title').toBe(`autosave-v2-${suffix}`);
      expect(afterFailureArticle?.status, 'failed autosave must not corrupt status').toBe('draft');

      // Ensure failed content is nowhere in the persisted data
      const persistedText = JSON.stringify(afterFailure.body);
      expect(persistedText.includes(failedDraftContent), 'failed autosave content must not be persisted').toBe(false);
      // Content should remain v2, not roll back to v1
      expect(afterFailureArticle?.content).not.toBe('version-1-success');

      // Verify timestamp didn't change due to failed save
      const afterFailureUpdatedAt = readSaveTime(afterFailure.body);
      if (successfulUpdatedAt && afterFailureUpdatedAt) {
        expect(afterFailureUpdatedAt, 'failed autosave should not update the last successful save timestamp').toBe(successfulUpdatedAt);
      }

      // Verify save type metadata didn't change
      const afterFailureSaveType = readSaveType(afterFailure.body);
      if (successfulSaveType && afterFailureSaveType) {
        expect(afterFailureSaveType, 'failed autosave should not change persisted save source metadata').toBe(successfulSaveType);
      }

      // Step 5: Simulate page refresh - GET should return last successful version
      const refreshRead = await request('GET', `/api/articles/${articleId}`);
      expect(refreshRead.res.status).toBe(200);
      const refreshArticle = getArticle(refreshRead.body);
      expect(refreshArticle?.title, 'refresh should restore last successful title').toBe(`autosave-v2-${suffix}`);
      expect(refreshArticle?.content, 'refresh should restore last successful content').toBe('version-2-success');
      expect(JSON.stringify(refreshRead.body).includes(failedDraftContent), 'refresh must not contain failed temporary content').toBe(false);

      // Step 6: Verify user can still save successfully after a failed autosave
      let recoverySave = await request('PATCH', `/api/articles/${articleId}/autosave`, {
        title: `autosave-v3-${suffix}`,
        content: 'version-3-success-after-failure',
      });
      if (recoverySave.res.status === 404) {
        recoverySave = await request('PATCH', `/api/articles/${articleId}`, {
          title: `autosave-v3-${suffix}`,
          content: 'version-3-success-after-failure',
        });
      }

      expect([200, 201].includes(recoverySave.res.status), `expected save after failure to succeed, got ${recoverySave.res.status}`).toBe(true);
      const recoveryArticle = getArticle(recoverySave.body);
      expect(recoveryArticle?.title).toBe(`autosave-v3-${suffix}`);
      expect(recoveryArticle?.content).toBe('version-3-success-after-failure');

      // Step 7: Verify manual save vs autosave distinction if saveType field exists
      // Do a manual save and check if saveType differs from autosave
      const manualSave = await request('PUT', `/api/articles/${articleId}`, {
        title: `manual-v4-${suffix}`,
        content: 'version-4-manual',
        status: 'draft',
      });
      if ([200, 201].includes(manualSave.res.status)) {
        const manualSaveType = readSaveType(manualSave.body);
        const autoSaveType = readSaveType(recoverySave.body);
        // If both have saveType, they should differ to distinguish manual from auto
        if (manualSaveType && autoSaveType) {
          expect(manualSaveType, 'manual save and autosave should have different saveType').not.toBe(autoSaveType);
        }
      }

      // Final verification
      const afterRecovery = await request('GET', `/api/articles/${articleId}`);
      expect(afterRecovery.res.status).toBe(200);
      const finalArticle = getArticle(afterRecovery.body);
      // Should be either v4 (manual) or v3 (auto recovery) depending on whether PUT worked
      expect(finalArticle?.content).toBeTruthy();
      expect(JSON.stringify(afterRecovery.body).includes(failedDraftContent), 'failed temporary content should never appear after later success').toBe(false);
    } finally {
      if (articleId) {
        try { await request('DELETE', `/api/articles/${articleId}`); } catch {}
        try { await request('DELETE', `/api/articles/${articleId}/permanent`); } catch {}
      }
    }
  });
});

import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function request(method, path, body) {
  const res = await fetch(`${BASE_URL}${path}`, {
    method,
    headers: { 'Content-Type': 'application/json' },
    body: body === undefined ? undefined : JSON.stringify(body),
  });
  const text = await res.text();
  let json = null;
  try { json = text ? JSON.parse(text) : null; } catch { json = text; }
  return { res, body: json, text };
}

async function tryDelete(path) {
  try { await fetch(`${BASE_URL}${path}`, { method: 'DELETE' }); } catch {}
}

function pick(obj, keys) {
  for (const key of keys) if (obj && obj[key] !== undefined) return obj[key];
}
function asArray(v) {
  if (Array.isArray(v)) return v;
  const d = v?.data ?? v;
  if (Array.isArray(d)) return d;
  if (Array.isArray(d?.items)) return d.items;
  if (Array.isArray(d?.articles)) return d.articles;
  return [];
}
function unwrap(v) {
  return v?.data ?? v;
}

async function ensureCategory(name) {
  const r = await request('POST', '/api/categories', { name });
  expect([200, 201]).toContain(r.res.status);
  const body = unwrap(r.body);
  const id = body?.id;
  expect(id).toBeTruthy();
  return id;
}

async function trySoftDelete(id) {
  let del = await request('DELETE', `/api/articles/${id}`);
  if (del.res.status === 404 || del.res.status === 405) {
    del = await request('POST', `/api/articles/${id}/trash`);
  }
  if (del.res.status === 404 || del.res.status === 405) {
    del = await request('PATCH', `/api/articles/${id}`, { status: 'deleted', deleted: true });
  }
  return del;
}

async function tryRestore(id) {
  let restore = await request('POST', `/api/articles/${id}/restore`);
  if (restore.res.status === 404 || restore.res.status === 405) {
    restore = await request('PATCH', `/api/articles/${id}/restore`);
  }
  if (restore.res.status === 404 || restore.res.status === 405) {
    restore = await request('PATCH', `/api/articles/${id}`, { deleted: false });
  }
  return restore;
}

async function tryPermanentDelete(id, withConfirm) {
  const confirmBody = withConfirm ? { confirm: true } : undefined;
  let r = await request('DELETE', `/api/articles/${id}/permanent`, confirmBody);
  if (r.res.status === 404 || r.res.status === 405) {
    const qs = withConfirm ? '?permanent=true&confirm=true' : '?permanent=true';
    r = await request('DELETE', `/api/articles/${id}${qs}`);
  }
  if (r.res.status === 404 || r.res.status === 405) {
    r = await request('POST', `/api/articles/${id}/permanent-delete`, confirmBody);
  }
  if (r.res.status === 404 || r.res.status === 405) {
    r = await request('DELETE', `/api/articles/${id}`, { permanent: true, ...(withConfirm ? { confirm: true } : {}) });
  }
  return r;
}

let resolvedRecyclePath = null;
async function getRecycleBin(extraParams = '') {
  const RECYCLE_PATHS = [
    '/api/articles?view=recycle',
    '/api/articles?status=deleted',
    '/api/articles/trash',
    '/api/articles/recycle',
  ];
  if (resolvedRecyclePath) {
    const sep = resolvedRecyclePath.includes('?') ? '&' : '?';
    return request('GET', `${resolvedRecyclePath}${extraParams ? sep + extraParams : ''}`);
  }
  for (const path of RECYCLE_PATHS) {
    const sep = path.includes('?') ? '&' : '?';
    const r = await request('GET', `${path}${extraParams ? sep + extraParams : ''}`);
    if (r.res.status === 200 && asArray(r.body).length >= 0) {
      // Check if this endpoint actually returns recycled items by verifying status 200
      resolvedRecyclePath = path;
      return r;
    }
  }
  resolvedRecyclePath = RECYCLE_PATHS[0];
  const sep = resolvedRecyclePath.includes('?') ? '&' : '?';
  return request('GET', `${resolvedRecyclePath}${extraParams ? sep + extraParams : ''}`);
}

let resolvedRssPath = null;
async function getRssPreview() {
  const RSS_PATHS = ['/api/rss/preview', '/api/rss', '/api/subscriptions/preview', '/api/subscription/preview', '/api/feed/preview'];
  if (resolvedRssPath) {
    return request('GET', resolvedRssPath);
  }
  for (const path of RSS_PATHS) {
    const r = await request('GET', path);
    if (r.res.status === 200) {
      resolvedRssPath = path;
      return r;
    }
  }
  resolvedRssPath = RSS_PATHS[0];
  return request('GET', resolvedRssPath);
}

let resolvedSeoPath = null;
async function getSeoPreview() {
  const SEO_PATHS = ['/api/seo/preview', '/api/seo/articles'];
  if (resolvedSeoPath) {
    return request('GET', resolvedSeoPath);
  }
  for (const path of SEO_PATHS) {
    const r = await request('GET', path);
    if (r.res.status === 200) {
      resolvedSeoPath = path;
      return r;
    }
  }
  resolvedSeoPath = SEO_PATHS[0];
  return request('GET', resolvedSeoPath);
}

describe('round14_recycle_bin_isolation', () => {
  it('should isolate recycle bin items, support title search/restore/permanent delete with adjacent navigation check, and exclude recycled content from list, RSS and SEO stats', async () => {
    const unique = `recycle-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
    let keepId;
    let purgeId;
    let neighborId;
    let catId;

    try {
      // Create a category so the published article satisfies public conditions
      catId = await ensureCategory(`RecycleCat ${unique}`);

      // Create a neighbor article for adjacent navigation testing
      const neighbor = await request('POST', '/api/articles', {
        title: `Neighbor ${unique}`,
        content: 'neighbor content body',
        status: 'published',
        publishedAt: '2024-02-01T08:00:00.000Z',
        publishTime: '2024-02-01T08:00:00.000Z',
        primaryCategoryId: catId,
        categoryIds: [catId],
      });
      expect([200, 201]).toContain(neighbor.res.status);
      neighborId = pick(unwrap(neighbor.body), ['id', 'articleId']);
      expect(neighborId).toBeTruthy();

      // Create a published article with all required fields for public eligibility
      const keep = await request('POST', '/api/articles', {
        title: `Recycle Keep ${unique}`,
        content: 'keep content body',
        status: 'published',
        publishedAt: '2024-02-01T10:00:00.000Z',
        publishTime: '2024-02-01T10:00:00.000Z',
        primaryCategoryId: catId,
        categoryIds: [catId],
      });
      const purge = await request('POST', '/api/articles', {
        title: `Recycle Purge ${unique}`,
        content: 'purge content body',
        status: 'draft',
        primaryCategoryId: catId,
        categoryIds: [catId],
      });
      expect([200, 201]).toContain(keep.res.status);
      expect([200, 201]).toContain(purge.res.status);
      keepId = pick(unwrap(keep.body), ['id', 'articleId']);
      purgeId = pick(unwrap(purge.body), ['id', 'articleId']);
      expect(keepId).toBeTruthy();
      expect(purgeId).toBeTruthy();

      // Record state before delete
      const beforeDeleteDetail = await request('GET', `/api/articles/${keepId}`);
      expect(beforeDeleteDetail.res.status).toBe(200);
      const beforeDeleteArticle = unwrap(beforeDeleteDetail.body);
      const beforeStatus = beforeDeleteArticle.status;
      const beforePublishedAt = beforeDeleteArticle.publishedAt ?? beforeDeleteArticle.publishTime;
      const beforeTitle = beforeDeleteArticle.title;
      const beforeCategoryId = beforeDeleteArticle.primaryCategoryId ?? beforeDeleteArticle.categoryId;
      expect(beforeStatus).toBe('published');
      expect(beforeTitle).toBe(`Recycle Keep ${unique}`);
      expect(beforePublishedAt).toBeTruthy();

      // Check RSS preview before delete
      const rssBefore = await getRssPreview();
      expect(rssBefore.res.status, 'RSS preview endpoint should be available').toBe(200);
      const rssBeforeTitles = asArray(rssBefore.body).map((x) => x.title);
      expect(rssBeforeTitles).toContain(`Recycle Keep ${unique}`);

      // Check SEO preview before delete
      const seoBefore = await getSeoPreview();
      expect(seoBefore.res.status, 'SEO preview endpoint should be available').toBe(200);

      // Soft-delete both articles
      const del1 = await trySoftDelete(keepId);
      expect([200, 204]).toContain(del1.res.status);

      const del2 = await trySoftDelete(purgeId);
      expect([200, 204]).toContain(del2.res.status);

      // Check recycle bin view
      const recycle = await getRecycleBin(`keyword=${encodeURIComponent(unique)}`);
      expect(recycle.res.status).toBe(200);
      const recycleItems = asArray(recycle.body);
      const recycleTitles = recycleItems.map((x) => x.title);
      expect(recycleTitles).toContain(`Recycle Keep ${unique}`);
      expect(recycleTitles).toContain(`Recycle Purge ${unique}`);

      // Recycle bin title search - search only for Purge
      const recycleSearch = await getRecycleBin(`keyword=${encodeURIComponent(`Purge ${unique}`)}`);
      if (recycleSearch.res.status === 200) {
        const recycleSearchItems = asArray(recycleSearch.body);
        const recycleSearchTitles = recycleSearchItems.map(x => x.title);
        expect(recycleSearchTitles).toContain(`Recycle Purge ${unique}`);
        expect(recycleSearchTitles).not.toContain(`Recycle Keep ${unique}`);
      }

      // Normal list should NOT contain soft-deleted articles
      const normal = await request('GET', `/api/articles?keyword=${encodeURIComponent(unique)}`);
      expect(normal.res.status).toBe(200);
      const normalTitles = asArray(normal.body).map((x) => x.title);
      expect(normalTitles.includes(`Recycle Keep ${unique}`)).toBe(false);
      expect(normalTitles.includes(`Recycle Purge ${unique}`)).toBe(false);
      // Neighbor should still be visible in normal list
      expect(normalTitles.includes(`Neighbor ${unique}`)).toBe(true);

      // RSS preview should NOT contain soft-deleted articles
      const rssAfterDelete = await getRssPreview();
      expect(rssAfterDelete.res.status).toBe(200);
      const rssDeletedTitles = asArray(rssAfterDelete.body).map((x) => x.title);
      expect(rssDeletedTitles.includes(`Recycle Keep ${unique}`)).toBe(false);
      expect(rssDeletedTitles.includes(`Recycle Purge ${unique}`)).toBe(false);

      // SEO preview should NOT contain soft-deleted articles
      const seoAfterDelete = await getSeoPreview();
      expect(seoAfterDelete.res.status).toBe(200);
      const seoDeletedTitles = asArray(seoAfterDelete.body).map((x) => x.title);
      expect(seoDeletedTitles.includes(`Recycle Keep ${unique}`)).toBe(false);
      expect(seoDeletedTitles.includes(`Recycle Purge ${unique}`)).toBe(false);

      // Restore keepId
      const restore = await tryRestore(keepId);
      expect([200, 204]).toContain(restore.res.status);

      // Restored article should have its original status, title, and publish time
      const restored = await request('GET', `/api/articles/${keepId}`);
      expect(restored.res.status).toBe(200);
      const restoredArticle = unwrap(restored.body);
      expect(restoredArticle.status).toBe(beforeStatus);
      expect(restoredArticle.title).toBe(beforeTitle);
      const restoredPublishedAt = restoredArticle.publishedAt ?? restoredArticle.publishTime;
      expect(restoredPublishedAt, 'publishedAt should be restored').toBeTruthy();
      // Verify category is restored
      const restoredCategoryId = restoredArticle.primaryCategoryId ?? restoredArticle.categoryId;
      if (beforeCategoryId) {
        expect(String(restoredCategoryId)).toBe(String(beforeCategoryId));
      }

      // RSS preview should contain the restored article again
      const rssAfterRestore = await getRssPreview();
      expect(rssAfterRestore.res.status).toBe(200);
      const rssRestoredTitles = asArray(rssAfterRestore.body).map((x) => x.title);
      expect(rssRestoredTitles.includes(`Recycle Keep ${unique}`)).toBe(true);
      expect(rssRestoredTitles.includes(`Recycle Purge ${unique}`)).toBe(false);

      // === Permanent delete purgeId ===
      // First try without confirmation - should be rejected or require confirmation
      const noConfirmPermanent = await tryPermanentDelete(purgeId, false);
      if ([400, 409, 422].includes(noConfirmPermanent.res.status)) {
        // Good - requires confirmation
        const noConfirmRaw = JSON.stringify(noConfirmPermanent.body || noConfirmPermanent.text).toLowerCase();
        expect(noConfirmRaw).toMatch(/confirm|permanent|second|twice|verification/);
      }

      // Now permanent delete with confirmation
      const permanent = await tryPermanentDelete(purgeId, true);
      expect([200, 204]).toContain(permanent.res.status);

      // Detail should not be accessible
      const detailAfterDelete = await request('GET', `/api/articles/${purgeId}`);
      expect([404, 410]).toContain(detailAfterDelete.res.status);

      // Edit/Update should not be accessible
      const editSaveAfterDelete = await request('PUT', `/api/articles/${purgeId}`, {
        title: `should-not-update-${unique}`,
        content: 'nope',
      });
      expect([404, 405, 409, 410]).toContain(editSaveAfterDelete.res.status);

      // Adjacent navigation (prev/next) from neighbor should NOT reference the permanently deleted article
      const neighborDetail = await request('GET', `/api/articles/${neighborId}`);
      expect(neighborDetail.res.status).toBe(200);
      const neighborData = unwrap(neighborDetail.body);
      const nextId = neighborData?.nextArticleId ?? neighborData?.next?.id ?? neighborData?.nextId;
      const prevId = neighborData?.prevArticleId ?? neighborData?.prev?.id ?? neighborData?.prevId;
      if (nextId) {
        expect(String(nextId), 'next article should not be the permanently deleted article').not.toBe(String(purgeId));
      }
      if (prevId) {
        expect(String(prevId), 'prev article should not be the permanently deleted article').not.toBe(String(purgeId));
      }

      // Recycle bin should not contain permanently deleted article
      const recycleAfterPurge = await getRecycleBin(`keyword=${encodeURIComponent(unique)}`);
      expect(recycleAfterPurge.res.status).toBe(200);
      const recycleAfterPurgeItems = asArray(recycleAfterPurge.body);
      const recycleAfterPurgeTitles = recycleAfterPurgeItems.map(x => x.title);
      expect(recycleAfterPurgeTitles).not.toContain(`Recycle Purge ${unique}`);

      purgeId = undefined;
    } finally {
      if (keepId) {
        await tryDelete(`/api/articles/${keepId}?permanent=true&confirm=true`);
        await tryDelete(`/api/articles/${keepId}/permanent`);
        await tryDelete(`/api/articles/${keepId}`);
      }
      if (purgeId) {
        await tryDelete(`/api/articles/${purgeId}?permanent=true&confirm=true`);
        await tryDelete(`/api/articles/${purgeId}/permanent`);
        await tryDelete(`/api/articles/${purgeId}`);
      }
      if (neighborId) {
        await tryDelete(`/api/articles/${neighborId}?permanent=true&confirm=true`);
        await tryDelete(`/api/articles/${neighborId}/permanent`);
        await tryDelete(`/api/articles/${neighborId}`);
      }
      if (catId) await tryDelete(`/api/categories/${catId}`);
    }
  });

  it('should return an empty recycle view with explicit empty-state indication after recycled items are cleared', async () => {
    const unique = `recycle-empty-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
    let articleId;
    let catId;

    try {
      catId = await ensureCategory(`RecycleEmptyCat ${unique}`);

      const created = await request('POST', '/api/articles', {
        title: `Recycle Empty ${unique}`,
        content: 'to delete',
        status: 'draft',
        primaryCategoryId: catId,
        categoryIds: [catId],
      });
      expect([200, 201]).toContain(created.res.status);
      articleId = pick(unwrap(created.body), ['id', 'articleId']);
      expect(articleId).toBeTruthy();

      // Soft delete
      const softDelete = await trySoftDelete(articleId);
      expect([200, 204]).toContain(softDelete.res.status);

      // Permanent delete with confirmation
      const permanent = await tryPermanentDelete(articleId, true);
      expect([200, 204]).toContain(permanent.res.status);
      articleId = undefined;

      // Verify recycle bin is empty for this search
      const recycle = await getRecycleBin(`keyword=${encodeURIComponent(unique)}`);
      expect(recycle.res.status).toBe(200);
      const items = asArray(recycle.body);
      expect(items.length).toBe(0);

      // Check for empty state indication in response
      const responseBody = unwrap(recycle.body) || recycle.body;
      const responseText = JSON.stringify(responseBody || '');
      // The response should either have an explicit empty state field or the empty array itself serves as the signal
      const hasEmptyStateInfo = (
        items.length === 0 ||
        responseBody?.emptyState !== undefined ||
        responseBody?.message !== undefined ||
        responseBody?.empty === true ||
        (typeof responseBody?.total === 'number' && responseBody.total === 0)
      );
      expect(hasEmptyStateInfo, `Empty recycle bin should provide clear empty state, got: ${responseText}`).toBe(true);
    } finally {
      if (articleId) {
        await tryDelete(`/api/articles/${articleId}?permanent=true&confirm=true`);
        await tryDelete(`/api/articles/${articleId}`);
      }
      if (catId) await tryDelete(`/api/categories/${catId}`);
    }
  });
});

import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

function uid(prefix = 'media') {
  return `${prefix}-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
}

async function request(path, options = {}) {
  return fetch(`${BASE_URL}${path}`, {
    headers: {
      'Content-Type': 'application/json',
      ...(options.headers || {}),
    },
    ...options,
  });
}

async function safeJson(res) {
  const text = await res.text();
  try {
    return text ? JSON.parse(text) : null;
  } catch {
    return { raw: text };
  }
}

function unwrap(body) {
  return body?.data ?? body;
}

async function cleanupArticle(id) {
  if (!id) return;
  try { await request(`/api/articles/${id}`, { method: 'DELETE' }); } catch {}
  try { await request(`/api/articles/${id}/permanent`, { method: 'DELETE' }); } catch {}
}

async function cleanupCategory(id) {
  if (!id) return;
  try { await request(`/api/categories/${id}`, { method: 'DELETE' }); } catch {}
}

describe('media_link_validity_does_not_block_publish', () => {
  it('should allow publishing when title/body/publishedAt/primaryCategory are valid even if body contains invalid external media links', async () => {
    const unique = uid();
    let categoryId;
    let articleId;

    try {
      const categoryRes = await request('/api/categories', {
        method: 'POST',
        body: JSON.stringify({ name: `Category ${unique}` }),
      });
      expect([200, 201]).toContain(categoryRes.status);
      const categoryBody = unwrap(await safeJson(categoryRes));
      expect(categoryBody?.id).toBeTruthy();
      categoryId = categoryBody.id;

      const content = [
        'This article contains invalid external media links but valid visible text.',
        '![broken-image](https://invalid.example.invalid/not-found.png)',
        '<video src="https://invalid.example.invalid/video.mp4"></video>'
      ].join('\n\n');

      const draftRes = await request('/api/articles', {
        method: 'POST',
        body: JSON.stringify({
          title: `Publish With Invalid Media ${unique}`,
          summary: 'summary',
          content,
          status: 'draft',
          editorMode: 'markdown',
          primaryCategoryId: categoryId,
        }),
      });
      expect([200, 201]).toContain(draftRes.status);
      const draftBody = unwrap(await safeJson(draftRes));
      expect(draftBody?.id).toBeTruthy();
      articleId = draftBody.id;
      expect(draftBody.title).toBe(`Publish With Invalid Media ${unique}`);
      expect(draftBody.content || draftBody.body).toContain('invalid.example.invalid');
      expect(draftBody.editorMode).toBe('markdown');

      const publishedAt = new Date().toISOString();
      const publishPayload = {
        title: `Publish With Invalid Media ${unique}`,
        summary: 'summary',
        content,
        status: 'published',
        publishedAt,
        primaryCategoryId: categoryId,
        editorMode: 'markdown'
      };

      expect(publishPayload.title.trim().length).toBeGreaterThan(0);
      expect(String(publishPayload.content).trim().length).toBeGreaterThan(0);
      expect(publishPayload.publishedAt).toBeTruthy();
      expect(publishPayload.primaryCategoryId).toBe(categoryId);

      const publishRes = await request(`/api/articles/${articleId}`, {
        method: 'PUT',
        body: JSON.stringify(publishPayload),
      });

      expect([200, 204]).toContain(publishRes.status);
      const body = publishRes.status === 204 ? null : unwrap(await safeJson(publishRes));
      if (body) {
        expect(body.id).toBe(articleId);
        expect(body.status).toBe('published');
        expect(body.publishedAt).toBeTruthy();
        expect(body.primaryCategoryId).toBe(categoryId);
        expect(body.content || body.body).toContain('https://invalid.example.invalid/not-found.png');
        expect(body.content || body.body).toContain('https://invalid.example.invalid/video.mp4');
        const message = JSON.stringify(body).toLowerCase();
        expect(message.includes('media invalid') || message.includes('image invalid') || message.includes('video invalid')).toBe(false);
      }

      const getRes = await request(`/api/articles/${articleId}`);
      expect(getRes.status).toBe(200);
      const fetched = unwrap(await safeJson(getRes));
      expect(fetched.id).toBe(articleId);
      expect(fetched.title).toBe(`Publish With Invalid Media ${unique}`);
      expect(fetched.status).toBe('published');
      expect(fetched.publishedAt).toBeTruthy();
      expect(fetched.primaryCategoryId).toBe(categoryId);
      expect(fetched.content || fetched.body).toContain('https://invalid.example.invalid/not-found.png');
      expect(fetched.content || fetched.body).toContain('https://invalid.example.invalid/video.mp4');
    } finally {
      await cleanupArticle(articleId);
      await cleanupCategory(categoryId);
    }
  });
});

import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

function uid(prefix = 'test') {
  return `${prefix}-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
}

function slugify(v) {
  return String(v).toLowerCase().trim().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');
}

async function api(path, options = {}) {
  const res = await fetch(`${BASE_URL}${path}`, {
    headers: { 'Content-Type': 'application/json', ...(options.headers || {}) },
    ...options,
  });
  const text = await res.text();
  let body;
  try { body = text ? JSON.parse(text) : null; } catch { body = text; }
  return { res, body };
}

async function cleanup(path) { try { await api(path, { method: 'DELETE' }); } catch {} }

function extractItems(body, ...keys) {
  for (const key of keys) {
    if (body && Array.isArray(body[key])) return body[key];
  }
  if (Array.isArray(body)) return body;
  return [];
}

async function tryImport(archive) {
  let result = await api('/api/import', { method: 'POST', body: JSON.stringify(archive) });
  if (result.res.status >= 200 && result.res.status < 300) return result;
  result = await api('/api/import', { method: 'POST', body: JSON.stringify({ archive }) });
  if (result.res.status >= 200 && result.res.status < 300) return result;
  result = await api('/api/restore', { method: 'POST', body: JSON.stringify(archive) });
  return result;
}

describe('partial_import_reports_success_skip_failure', () => {
  it('should classify import results into success/skip/failure, persist successful parts, and not create dirty data for failures', async () => {
    const suffix = uid('partial-import');

    try {
      // Pre-create a category so import of the same name triggers a skip/duplicate
      const existingCatRes = await api('/api/categories', {
        method: 'POST',
        body: JSON.stringify({ name: `Existing ${suffix}`, slug: slugify(`existing-${suffix}`) }),
      });
      expect(existingCatRes.res.status).toBeGreaterThanOrEqual(200);
      expect(existingCatRes.res.status).toBeLessThan(300);

      const archive = {
        categories: [
          { name: `Imported OK ${suffix}`, slug: slugify(`ok-${suffix}`) },
          { name: `Existing ${suffix}`, slug: slugify(`existing-${suffix}`) }, // duplicate -> should be skipped
          { badField: true } // corrupt -> should fail
        ],
        articles: [
          { title: `Imported article ${suffix}`, content: 'body', status: 'draft' },
          { title: '', content: '', status: 'published' } // invalid -> should fail
        ],
        tags: [
          { name: `Imported Tag ${suffix}`, slug: slugify(`imported-tag-${suffix}`) },
        ],
        corruptedPart: '###not-valid-structure###'
      };

      const importRes = await tryImport(archive);
      expect([200, 201, 207]).toContain(importRes.res.status);

      const responseBody = importRes.body;
      expect(responseBody, `expected import response body, got null`).toBeTruthy();

      // Extract the report - try various known structures
      const report = responseBody.results || responseBody.report || responseBody.summary || responseBody;

      // Verify that the report actually contains classification fields
      // At least one of these field groups must exist and be non-empty to prove classification
      const successList = report.success || report.imported || report.succeeded || [];
      const skippedList = report.skipped || report.skip || report.duplicates || [];
      const failedList = report.failed || report.errors || report.failures || [];

      // The report must actually contain at least one real classification field (not just empty fallbacks)
      const hasSuccessField = (report.success || report.imported || report.succeeded) !== undefined;
      const hasSkipField = (report.skipped || report.skip || report.duplicates) !== undefined;
      const hasFailField = (report.failed || report.errors || report.failures) !== undefined;
      const hasCountFields = report.successCount !== undefined || report.failedCount !== undefined || report.skippedCount !== undefined;

      expect(
        hasSuccessField || hasSkipField || hasFailField || hasCountFields,
        `report must contain at least one classification field (success/skipped/failed): ${JSON.stringify(report)}`
      ).toBe(true);

      // Verify successful items exist
      if (hasSuccessField) {
        expect(successList.length, `expected at least one successful import item: ${JSON.stringify(report)}`).toBeGreaterThanOrEqual(1);
      }

      // Verify skipped items exist (the duplicate category)
      if (hasSkipField) {
        expect(skippedList.length, `expected at least one skipped item (duplicate category): ${JSON.stringify(report)}`).toBeGreaterThanOrEqual(1);
        // Check that the skipped list references the existing/duplicate category
        const skippedNames = skippedList.map(s => s.name || s.title || s.identifier || JSON.stringify(s));
        const hasDuplicateSkip = skippedNames.some(n => String(n).includes('Existing') || String(n).includes(suffix));
        if (skippedList.length > 0) {
          // Soft check: if skipped entries have identifiable names, one should reference our duplicate
          expect(hasDuplicateSkip || skippedList.length >= 1, `skipped list should reference the duplicate category`).toBe(true);
        }
      }

      // Verify failed items exist
      if (hasFailField) {
        expect(failedList.length, `expected at least one failed item: ${JSON.stringify(report)}`).toBeGreaterThanOrEqual(1);
      }

      // === Verify successfully imported category is queryable ===
      const categories = await api(`/api/categories?search=${encodeURIComponent(suffix)}`);
      expect(categories.res.status).toBe(200);
      const categoryItems = extractItems(categories.body, 'items', 'categories', 'data');
      expect(categoryItems.some((x) => x.name === `Imported OK ${suffix}`), `successfully imported category should be queryable: ${JSON.stringify(categoryItems)}`).toBe(true);

      // Verify duplicate category was NOT duplicated
      const existingCount = categoryItems.filter((x) => x.name === `Existing ${suffix}`).length;
      expect(existingCount, `duplicate category should not be duplicated: ${JSON.stringify(categoryItems)}`).toBe(1);

      // === Verify successfully imported article is queryable ===
      const articles = await api(`/api/articles?search=${encodeURIComponent(suffix)}`);
      expect(articles.res.status).toBe(200);
      const articleItems = extractItems(articles.body, 'items', 'articles', 'data');
      expect(articleItems.some((x) => x.title === `Imported article ${suffix}`), `successfully imported article should be queryable: ${JSON.stringify(articleItems)}`).toBe(true);

      // === Verify failed entries did NOT create dirty data ===
      // The corrupt article (empty title, empty content) should not exist
      const allArticles = await api('/api/articles');
      const allArticleItems = extractItems(allArticles.body, 'items', 'articles', 'data');
      const dirtyArticles = allArticleItems.filter((x) =>
        (x.title === '' || x.title === null) && (x.content === '' || x.content === null)
      );
      expect(dirtyArticles.length, `failed import entries should NOT create dirty data (found articles with empty title+content): ${JSON.stringify(dirtyArticles)}`).toBe(0);

      // The corrupt category (badField only, no name) should not exist as a category without a name
      const allCategories = await api('/api/categories');
      const allCatItems = extractItems(allCategories.body, 'items', 'categories', 'data');
      const dirtyCats = allCatItems.filter((x) => !x.name || x.name === '');
      expect(dirtyCats.length, `failed import entries should NOT create dirty category data: ${JSON.stringify(dirtyCats)}`).toBe(0);

    } finally {
      try {
        const articles = await api(`/api/articles?search=${encodeURIComponent(suffix)}`);
        for (const item of extractItems(articles.body, 'items', 'articles', 'data')) await cleanup(`/api/articles/${item.id}`);
      } catch {}
      try {
        const categories = await api(`/api/categories?search=${encodeURIComponent(suffix)}`);
        for (const item of extractItems(categories.body, 'items', 'categories', 'data')) await cleanup(`/api/categories/${item.id}`);
      } catch {}
      try {
        const tags = await api(`/api/tags?search=${encodeURIComponent(suffix)}`);
        for (const item of extractItems(tags.body, 'items', 'tags', 'data')) await cleanup(`/api/tags/${item.id}`);
      } catch {}
    }
  });
});

import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function request(path, options = {}) {
  return fetch(`${BASE_URL}${path}`, {
    headers: {
      'Content-Type': 'application/json',
      ...(options.headers || {}),
    },
    ...options,
  });
}

async function safeJson(res) {
  const text = await res.text();
  try {
    return text ? JSON.parse(text) : null;
  } catch {
    return { raw: text };
  }
}

async function cleanupArticle(id) {
  if (!id) return;
  try {
    await request(`/api/articles/${id}`, { method: 'DELETE' });
  } catch {}
}

async function cleanupCategory(id) {
  if (!id) return;
  try {
    await request(`/api/categories/${id}`, { method: 'DELETE' });
  } catch {}
}

async function ensureCategory(name) {
  const res = await request('/api/categories', {
    method: 'POST',
    body: JSON.stringify({ name }),
  });
  return safeJson(res);
}

function extractId(obj) {
  if (!obj) return undefined;
  return obj.id || obj.categoryId || obj.data?.id;
}

function extractArticleId(obj) {
  if (!obj) return undefined;
  return obj.id || obj.articleId || obj.data?.id;
}

function asArray(v) {
  if (Array.isArray(v)) return v;
  if (v?.items && Array.isArray(v.items)) return v.items;
  if (v?.articles && Array.isArray(v.articles)) return v.articles;
  if (v?.data && Array.isArray(v.data)) return v.data;
  return [];
}

