import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

function uid(prefix = 'test') {
  return `${prefix}-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
}

async function api(path, options = {}) {
  const res = await fetch(`${BASE_URL}${path}`, {
    headers: { 'Content-Type': 'application/json', ...(options.headers || {}) },
    ...options,
  });
  const text = await res.text();
  let body;
  try { body = text ? JSON.parse(text) : null; } catch { body = text; }
  return { res, body };
}

async function createArticle(payload) {
  const { res, body } = await api('/api/articles', { method: 'POST', body: JSON.stringify(payload) });
  expect(res.status).toBeGreaterThanOrEqual(200);
  expect(res.status).toBeLessThan(300);
  return body;
}

async function cleanupArticle(id) { try { if (id) await api(`/api/articles/${id}`, { method: 'DELETE' }); } catch {} }

// Try multiple save approaches and return the first successful one
async function manualSave(articleId, payload) {
  // Try PUT /api/articles/:id (common REST update)
  let result = await api(`/api/articles/${articleId}`, {
    method: 'PUT',
    body: JSON.stringify(payload),
  });
  if (result.res.status >= 200 && result.res.status < 300) return result;

  // Try PATCH /api/articles/:id
  result = await api(`/api/articles/${articleId}`, {
    method: 'PATCH',
    body: JSON.stringify(payload),
  });
  if (result.res.status >= 200 && result.res.status < 300) return result;

  // Try POST /api/articles/:id/save
  result = await api(`/api/articles/${articleId}/save`, {
    method: 'POST',
    body: JSON.stringify(payload),
  });
  return result;
}

function extractVersions(body) {
  if (Array.isArray(body)) return body;
  return body?.items || body?.versions || body?.data || [];
}

async function trashArticle(id) {
  let result = await api(`/api/articles/${id}`, { method: 'PATCH', body: JSON.stringify({ isInTrash: true }) });
  if (result.res.status >= 200 && result.res.status < 300) return result;
  result = await api(`/api/articles/${id}/trash`, { method: 'POST' });
  return result;
}

describe('version_history_records_manual_saves', () => {
  it('should record each manual save with time/title/status, forbid new version in trash, and still allow viewing old versions', async () => {
    const suffix = uid('versions');
    let article;

    try {
      // Create article – this may or may not create a version record
      article = await createArticle({ title: `Version 1 ${suffix}`, content: 'body1', status: 'draft' });

      // Perform explicit manual save #1 to ensure at least one version exists
      const save1 = await manualSave(article.id, { title: `Version 1 ${suffix}`, content: 'body1 updated', status: 'draft' });
      expect(save1.res.status, `manual save #1 failed: ${JSON.stringify(save1.body)}`).toBeGreaterThanOrEqual(200);
      expect(save1.res.status).toBeLessThan(300);

      // Manual save #2
      const save2 = await manualSave(article.id, { title: `Version 2 ${suffix}`, content: 'body2', status: 'draft' });
      expect(save2.res.status, `manual save #2 failed: ${JSON.stringify(save2.body)}`).toBeGreaterThanOrEqual(200);
      expect(save2.res.status).toBeLessThan(300);

      // Manual save #3
      const save3 = await manualSave(article.id, { title: `Version 3 ${suffix}`, content: 'body3', status: 'draft' });
      expect(save3.res.status, `manual save #3 failed: ${JSON.stringify(save3.body)}`).toBeGreaterThanOrEqual(200);
      expect(save3.res.status).toBeLessThan(300);

      // Fetch version history
      const history = await api(`/api/articles/${article.id}/versions`);
      expect(history.res.status, `version history fetch failed: ${JSON.stringify(history.body)}`).toBe(200);
      const versions = extractVersions(history.body);
      expect(versions.length, `expected at least 3 versions after 3 manual saves, got ${versions.length}: ${JSON.stringify(versions)}`).toBeGreaterThanOrEqual(3);

      // Validate that versions contain title, status, and save time
      const targetVersions = versions.filter((v) => String(v.title || '').includes(suffix));
      expect(targetVersions.length, `expected version entries with our titles, got ${JSON.stringify(versions)}`).toBeGreaterThanOrEqual(3);
      for (const version of targetVersions) {
        expect(version.title, `version should record title: ${JSON.stringify(version)}`).toBeTruthy();
        expect(version.status, `version should record status: ${JSON.stringify(version)}`).toBeTruthy();
        const hasTime = !!(version.savedAt || version.createdAt || version.timestamp || version.updatedAt || version.date);
        expect(hasTime, `version should record save time: ${JSON.stringify(version)}`).toBe(true);
      }

      // --- Move article to trash ---
      const trash = await trashArticle(article.id);
      expect(trash.res.status).toBeGreaterThanOrEqual(200);
      expect(trash.res.status).toBeLessThan(300);

      // Attempting to save a trashed article should be rejected
      const blockedSave = await manualSave(article.id, { title: `Blocked ${suffix}`, content: 'blocked', status: 'draft' });
      expect([400, 403, 409, 422]).toContain(blockedSave.res.status);

      // But version history should still be viewable for trashed article
      const historyAfterTrash = await api(`/api/articles/${article.id}/versions`);
      expect(historyAfterTrash.res.status, `version history should still be viewable for trashed article`).toBe(200);
      const versionsAfterTrash = extractVersions(historyAfterTrash.body);
      // Count should not have increased since the blocked save should not create a version
      expect(versionsAfterTrash.length).toBeGreaterThanOrEqual(versions.length);
      // No new version with "Blocked" title should exist
      expect(versionsAfterTrash.some(v => String(v.title || '').includes('Blocked')),
        'blocked save should not create a new version'
      ).toBe(false);

      // Verify we can view an individual old version detail
      const firstVersion = versionsAfterTrash[0];
      expect(firstVersion, 'should have at least one version to view detail').toBeTruthy();
      if (firstVersion && firstVersion.id) {
        const versionDetail = await api(`/api/articles/${article.id}/versions/${firstVersion.id}`);
        expect(versionDetail.res.status, `should be able to view old version detail`).toBe(200);
        const detailBody = versionDetail.body;
        // Verify detail contains title, status, and time
        const detailTitle = detailBody.title || detailBody.version?.title;
        expect(detailTitle, `version detail should contain title: ${JSON.stringify(detailBody)}`).toBeTruthy();
        const detailStatus = detailBody.status || detailBody.version?.status;
        expect(detailStatus, `version detail should contain status: ${JSON.stringify(detailBody)}`).toBeTruthy();
        const detailTime = detailBody.savedAt || detailBody.createdAt || detailBody.timestamp || detailBody.updatedAt || detailBody.version?.savedAt || detailBody.version?.createdAt;
        expect(detailTime, `version detail should contain save time: ${JSON.stringify(detailBody)}`).toBeTruthy();
      }
    } finally {
      await cleanupArticle(article?.id);
    }
  });
});

