describe('article_category_tag_limits_enforced', () => {
  it('enforces max 2 categories, requires a primary category, allows max 5 tags, and preserves single legacy category as primary', async () => {
    const suffix = `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
    const createdCategoryIds = [];
    const createdTagIds = [];
    const createdArticleIds = [];

    try {
      const c1 = await createCategory(`Cat A ${suffix}`);
      const c2 = await createCategory(`Cat B ${suffix}`);
      const c3 = await createCategory(`Cat C ${suffix}`);
      createdCategoryIds.push(c1.id, c2.id, c3.id);

      const tags = [];
      for (let i = 1; i <= 6; i++) {
        const tag = await createTag(`Tag ${i} ${suffix}`);
        tags.push(tag);
        createdTagIds.push(tag.id);
      }

      const validPayload = {
        title: `Article ${suffix}`,
        content: `# Hello ${suffix}\n\nBody content`,
        status: 'draft',
        primaryCategoryId: c1.id,
        categoryIds: [c1.id, c2.id],
        tagIds: tags.slice(0, 5).map(t => t.id),
      };

      const validCreate = await createArticle(validPayload);
      expect([200, 201]).toContain(validCreate.res.status);
      expect(validCreate.body).toBeTruthy();
      expect(validCreate.body.id, `article create response should include id, got ${JSON.stringify(validCreate.body)}`).toBeTruthy();
      const articleId = validCreate.body.id;
      createdArticleIds.push(articleId);

      const fetched = await getArticle(articleId);
      expect(fetched.res.status).toBe(200);
      expect(fetched.body).toBeTruthy();
      expect(fetched.body.title).toBe(validPayload.title);
      expect(fetched.body.primaryCategoryId).toBe(c1.id);
      expect(Array.isArray(fetched.body.categoryIds), `expected categoryIds array, got ${JSON.stringify(fetched.body)}`).toBe(true);
      expect(fetched.body.categoryIds).toEqual([c1.id, c2.id]);
      expect(Array.isArray(fetched.body.tagIds), `expected tagIds array, got ${JSON.stringify(fetched.body)}`).toBe(true);
      expect(fetched.body.tagIds.length).toBe(5);

      const tooManyCategories = await updateArticle(articleId, {
        ...validPayload,
        primaryCategoryId: c1.id,
        categoryIds: [c1.id, c2.id, c3.id],
      });
      expect([400, 409, 422]).toContain(tooManyCategories.res.status);
      expect(tooManyCategories.body, `expected validation error body for too many categories`).toBeTruthy();

      const tooManyTags = await updateArticle(articleId, {
        ...validPayload,
        primaryCategoryId: c1.id,
        categoryIds: [c1.id, c2.id],
        tagIds: tags.map(t => t.id),
      });
      expect([400, 409, 422]).toContain(tooManyTags.res.status);
      expect(tooManyTags.body, `expected validation error body for too many tags`).toBeTruthy();

      const removePrimaryButKeepSecondary = await updateArticle(articleId, {
        ...validPayload,
        primaryCategoryId: null,
        categoryIds: [c2.id],
      });
      expect([400, 409, 422]).toContain(removePrimaryButKeepSecondary.res.status);
      expect(removePrimaryButKeepSecondary.body, `expected validation error body when primary category missing`).toBeTruthy();

      const legacySingleCategory = await createArticle({
        title: `Legacy article ${suffix}`,
        content: `Legacy body ${suffix}`,
        status: 'draft',
        categoryIds: [c3.id],
        tagIds: [],
      });

      if ([200, 201].includes(legacySingleCategory.res.status)) {
        expect(legacySingleCategory.body).toBeTruthy();
        expect(legacySingleCategory.body.id).toBeTruthy();
        createdArticleIds.push(legacySingleCategory.body.id);

        const legacyFetched = await getArticle(legacySingleCategory.body.id);
        expect(legacyFetched.res.status).toBe(200);
        expect(legacyFetched.body).toBeTruthy();
        expect(Array.isArray(legacyFetched.body.categoryIds)).toBe(true);
        expect(legacyFetched.body.categoryIds).toContain(c3.id);
        expect(
          legacyFetched.body.primaryCategoryId,
          `single-category legacy article should preserve that category as primary; body=${JSON.stringify(legacyFetched.body)}`
        ).toBe(c3.id);
      } else {
        expect([400, 409, 422]).toContain(legacySingleCategory.res.status);
        expect(legacySingleCategory.body).toBeTruthy();
      }
    } finally {
      for (const articleId of createdArticleIds) {
        await safeDelete(`/api/articles/${articleId}`);
      }
      for (const tagId of createdTagIds) {
        await safeDelete(`/api/tags/${tagId}`);
      }
      for (const categoryId of createdCategoryIds) {
        await safeDelete(`/api/categories/${categoryId}`);
      }
    }
  });
});

