function extractIds(body) {
  if (Array.isArray(body)) return body.map(x => x?.id).filter(Boolean);
  if (Array.isArray(body?.items)) return body.items.map(x => x?.id).filter(Boolean);
  if (Array.isArray(body?.articles)) return body.articles.map(x => x?.id).filter(Boolean);
  if (Array.isArray(body?.data)) return body.data.map(x => x?.id).filter(Boolean);
  return [];
}

function extractArticle(body, id) {
  const list = Array.isArray(body)
    ? body
    : Array.isArray(body?.items)
      ? body.items
      : Array.isArray(body?.articles)
        ? body.articles
        : Array.isArray(body?.data)
          ? body.data
          : [];
  return list.find(x => x?.id === id);
}

describe('seo_preview_uses_subscription_public_rules', () => {
  it('includes only publicly eligible articles in both SEO preview and subscription feed, and excludes article when primary category is removed/invalid', async () => {
    const suffix = `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
    const categoryIds = [];
    const articleIds = [];

    try {
      const primary = await createCategory(`Public Primary ${suffix}`);
      const secondary = await createCategory(`Public Secondary ${suffix}`);
      categoryIds.push(primary.id, secondary.id);

      const publishedAt = new Date().toISOString();

      const eligible = await createArticle({
        title: `Eligible ${suffix}`,
        content: `Eligible content ${suffix}`,
        status: 'published',
        publishedAt,
        primaryCategoryId: primary.id,
        categoryIds: [primary.id, secondary.id],
      });
      expect([200, 201]).toContain(eligible.res.status);
      expect(eligible.body?.id).toBeTruthy();
      articleIds.push(eligible.body.id);

      const draft = await createArticle({
        title: `Draft ${suffix}`,
        content: `Draft content ${suffix}`,
        status: 'draft',
        primaryCategoryId: primary.id,
        categoryIds: [primary.id],
      });
      expect([200, 201]).toContain(draft.res.status);
      expect(draft.body?.id).toBeTruthy();
      articleIds.push(draft.body.id);

      const missingPrimary = await createArticle({
        title: `Missing primary ${suffix}`,
        content: `Body ${suffix}`,
        status: 'published',
        publishedAt,
        categoryIds: [secondary.id],
      });
      if ([200, 201].includes(missingPrimary.res.status) && missingPrimary.body?.id) {
        articleIds.push(missingPrimary.body.id);
      } else {
        expect([400, 409, 422]).toContain(missingPrimary.res.status);
      }

      const seo1 = await getSeoPreview();
      const sub1 = await getSubscriptionFeed();
      expect(seo1.res.status).toBe(200);
      expect(sub1.res.status).toBe(200);

      const seoIds1 = extractIds(seo1.body);
      const subIds1 = extractIds(sub1.body);

      expect(seoIds1, `eligible article should appear in SEO preview; got ${JSON.stringify(seo1.body)}`).toContain(eligible.body.id);
      expect(subIds1, `eligible article should appear in subscription feed; got ${JSON.stringify(sub1.body)}`).toContain(eligible.body.id);
      expect(seoIds1).not.toContain(draft.body.id);
      expect(subIds1).not.toContain(draft.body.id);
      if (missingPrimary.body?.id) {
        expect(seoIds1).not.toContain(missingPrimary.body.id);
        expect(subIds1).not.toContain(missingPrimary.body.id);
      }

      const seoArticle = extractArticle(seo1.body, eligible.body.id);
      const subArticle = extractArticle(sub1.body, eligible.body.id);
      if (seoArticle) {
        expect(seoArticle.title).toBe(`Eligible ${suffix}`);
        if (seoArticle.primaryCategoryId !== undefined) {
          expect(seoArticle.primaryCategoryId).toBe(primary.id);
        }
      }
      if (subArticle) {
        expect(subArticle.title).toBe(`Eligible ${suffix}`);
        if (subArticle.primaryCategoryId !== undefined) {
          expect(subArticle.primaryCategoryId).toBe(primary.id);
        }
      }

      const removeSecondaryOnly = await updateArticle(eligible.body.id, {
        title: `Eligible ${suffix}`,
        content: `Eligible content ${suffix}`,
        status: 'published',
        publishedAt,
        primaryCategoryId: primary.id,
        categoryIds: [primary.id],
      });
      expect([200, 204]).toContain(removeSecondaryOnly.res.status);

      const seo2 = await getSeoPreview();
      const sub2 = await getSubscriptionFeed();
      expect(seo2.res.status).toBe(200);
      expect(sub2.res.status).toBe(200);
      expect(extractIds(seo2.body)).toContain(eligible.body.id);
      expect(extractIds(sub2.body)).toContain(eligible.body.id);

      const invalidatePrimary = await updateArticle(eligible.body.id, {
        title: `Eligible ${suffix}`,
        content: `Eligible content ${suffix}`,
        status: 'published',
        publishedAt,
        primaryCategoryId: null,
        categoryIds: [secondary.id],
      });

      if ([200, 204].includes(invalidatePrimary.res.status)) {
        const seo3 = await getSeoPreview();
        const sub3 = await getSubscriptionFeed();
        expect(seo3.res.status).toBe(200);
        expect(sub3.res.status).toBe(200);
        expect(extractIds(seo3.body)).not.toContain(eligible.body.id);
        expect(extractIds(sub3.body)).not.toContain(eligible.body.id);
      } else {
        expect([400, 409, 422]).toContain(invalidatePrimary.res.status);
        const seo3 = await getSeoPreview();
        const sub3 = await getSubscriptionFeed();
        expect(seo3.res.status).toBe(200);
        expect(sub3.res.status).toBe(200);
        expect(extractIds(seo3.body)).toContain(eligible.body.id);
        expect(extractIds(sub3.body)).toContain(eligible.body.id);
      }
    } finally {
      for (const articleId of articleIds) {
        await safeDelete(`/api/articles/${articleId}`);
      }
      for (const categoryId of categoryIds) {
        await safeDelete(`/api/categories/${categoryId}`);
      }
    }
  });
});

