describe('global_operations_are_idempotent_and_accurate', () => {
  it('treats repeated publish/trash/delete operations idempotently and returns accurate results without duplicating versions or deletions', async () => {
    const suffix = `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
    const createdCategoryIds = [];
    const createdArticleIds = [];

    try {
      // --- Setup: create category and article ---
      const category = await createCategory(`Ops Category ${suffix}`);
      createdCategoryIds.push(category.id);

      const create = await createArticle({
        title: `Ops Article ${suffix}`,
        content: `Initial content ${suffix}`,
        status: 'draft',
        primaryCategoryId: category.id,
        categoryIds: [category.id],
      });
      expect([200, 201]).toContain(create.res.status);
      expect(create.body?.id).toBeTruthy();
      const articleId = create.body.id;
      createdArticleIds.push(articleId);

      // Verify draft status
      const draftRead = await getArticle(articleId);
      expect(draftRead.res.status).toBe(200);
      expect(draftRead.body?.status).toBe('draft');

      // --- Publish ---
      const publishedAt = new Date().toISOString();
      const pub1 = await tryPublish(articleId, publishedAt);
      expect([200, 201, 204]).toContain(pub1.res.status);

      const afterPublish1 = await getArticle(articleId);
      expect(afterPublish1.res.status).toBe(200);
      expect(afterPublish1.body?.status).toBe('published');

      // Check versions before repeated publish
      const versionsBefore = await api(`/api/articles/${articleId}/versions`);
      const countBefore = versionsBefore.res.status === 200 ? versionsCount(versionsBefore.body) : null;

      // --- Repeated publish (idempotency) ---
      const pub2 = await tryPublish(articleId, publishedAt);
      // Should succeed idempotently or return conflict, not error out
      expect([200, 201, 204, 409]).toContain(pub2.res.status);

      const afterPublish2 = await getArticle(articleId);
      expect(afterPublish2.res.status).toBe(200);
      // Status must still be published, not changed to something else
      expect(afterPublish2.body?.status).toBe('published');

      // Repeated publish should NOT create duplicate versions - strict idempotency check
      if (countBefore !== null) {
        const versionsAfterPub = await api(`/api/articles/${articleId}/versions`);
        if (versionsAfterPub.res.status === 200) {
          const countAfterPub = versionsCount(versionsAfterPub.body);
          // True idempotency: repeated publish should not add new versions
          expect(
            countAfterPub,
            `repeated publish must not create duplicate versions; before=${countBefore}, after=${countAfterPub}`
          ).toBe(countBefore);
        }
      }

      // --- Trash ---
      const trash1 = await tryTrash(articleId);
      expect([200, 201, 204]).toContain(trash1.res.status);

      const trashedRead = await getArticle(articleId);
      expect(trashedRead.res.status).toBe(200);
      const trashedStatus = trashedRead.body?.status;
      expect(
        ['trashed', 'recycle_bin', 'deleted', 'recycled'].includes(trashedStatus),
        `expected trashed status but got ${trashedStatus}`
      ).toBe(true);

      // --- Repeated trash (idempotency) ---
      const trash2 = await tryTrash(articleId);
      expect([200, 201, 204, 409]).toContain(trash2.res.status);

      // After repeated trash, status must still be trashed, not changed
      const trashedRead2 = await getArticle(articleId);
      expect(trashedRead2.res.status).toBe(200);
      expect(
        ['trashed', 'recycle_bin', 'deleted', 'recycled'].includes(trashedRead2.body?.status),
        `status should remain trashed after repeated trash, got ${trashedRead2.body?.status}`
      ).toBe(true);

      // --- Verify article is excluded from RSS preview after trashing ---
      const rssEndpoints = findRssEndpoint();
      for (const ep of rssEndpoints) {
        const rssPreview = await api(`${ep}/preview`);
        if (rssPreview.res.status === 200 && rssPreview.body) {
          const previewArticles = rssPreview.body?.articles || rssPreview.body?.items || (Array.isArray(rssPreview.body) ? rssPreview.body : []);
          const found = previewArticles.find(a => a.id === articleId || a.title?.includes(suffix));
          expect(found, 'Trashed article must not appear in RSS preview').toBeFalsy();
          break;
        }
      }

      // --- Permanent delete ---
      const del1 = await tryPermanentDelete(articleId);
      expect([200, 204]).toContain(del1.res.status);

      const afterDelete = await getArticle(articleId);
      expect([404, 410]).toContain(afterDelete.res.status);

      // --- Repeated permanent delete (idempotency) ---
      const del2 = await tryPermanentDelete(articleId);
      expect([200, 204, 404, 410]).toContain(del2.res.status);

      // Verify article is truly gone
      const afterDelete2 = await getArticle(articleId);
      expect([404, 410]).toContain(afterDelete2.res.status);

    } finally {
      for (const articleId of createdArticleIds) {
        await safeDelete(`/api/articles/${articleId}/permanent`);
        await safeDelete(`/api/articles/${articleId}`);
      }
      for (const categoryId of createdCategoryIds) {
        await safeDelete(`/api/categories/${categoryId}`);
      }
    }
  });

  it('returns distinguishable error types: validation errors (400/422) vs conflicts (409) with different response structures', async () => {
    const suffix = `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
    const createdCategoryIds = [];
    const createdArticleIds = [];

    try {
      // --- Validation error: empty title and content ---
      const invalidCreate = await createArticle({
        title: '',
        content: '',
        status: 'published',
        categoryIds: [],
      });
      // Validation errors should use 400 or 422
      expect([400, 422]).toContain(invalidCreate.res.status);
      expect(invalidCreate.body).toBeTruthy();
      const validationErrorBody = typeof invalidCreate.body === 'string' ? invalidCreate.body : JSON.stringify(invalidCreate.body);
      // Must contain error details
      expect(
        invalidCreate.body?.error || invalidCreate.body?.message || invalidCreate.body?.errors || validationErrorBody.toLowerCase().includes('required') || validationErrorBody.toLowerCase().includes('valid') || validationErrorBody.toLowerCase().includes('title'),
        `Validation error response should contain error details: ${validationErrorBody}`
      ).toBeTruthy();
      const validationStatusCode = invalidCreate.res.status;

      // --- Validation error: title only spaces ---
      const spaceTitleCreate = await createArticle({
        title: '   ',
        content: 'some content',
        status: 'draft',
      });
      expect([400, 422]).toContain(spaceTitleCreate.res.status);
      expect(spaceTitleCreate.body).toBeTruthy();

      // --- Validation error: publishing without publishedAt ---
      const category = await createCategory(`ErrCat ${suffix}`);
      createdCategoryIds.push(category.id);

      const draftRes = await createArticle({
        title: `ErrArticle ${suffix}`,
        content: `Content ${suffix}`,
        status: 'draft',
        primaryCategoryId: category.id,
        categoryIds: [category.id],
      });
      expect([200, 201]).toContain(draftRes.res.status);
      const draftId = draftRes.body?.id;
      expect(draftId).toBeTruthy();
      createdArticleIds.push(draftId);

      // Try to publish without publishedAt - should fail with validation error
      const pubNoDate = await tryPublish(draftId, undefined);
      if ([400, 422].includes(pubNoDate.res.status)) {
        // Validation failure for missing publishedAt
        const pubErrBody = typeof pubNoDate.body === 'string' ? pubNoDate.body : JSON.stringify(pubNoDate.body);
        const hasPublishErr = (
          pubErrBody.toLowerCase().includes('time') ||
          pubErrBody.toLowerCase().includes('date') ||
          pubErrBody.toLowerCase().includes('required') ||
          pubErrBody.toLowerCase().includes('publish') ||
          pubNoDate.body?.error ||
          pubNoDate.body?.message
        );
        expect(hasPublishErr, `Publish validation error should explain reason: ${pubErrBody}`).toBeTruthy();
        // Validation errors use 400/422
        expect([400, 422]).toContain(pubNoDate.res.status);
      }
      // If it succeeded (some APIs auto-fill publishedAt), that's acceptable too

      // --- Conflict scenario: duplicate category name ---
      const dupCat = await api('/api/categories', {
        method: 'POST',
        body: JSON.stringify({ name: `ErrCat ${suffix}`, slug: `errcat-${suffix}-dup` }),
      });
      // Conflict should specifically return 409, distinguishable from validation 400/422
      if ([409].includes(dupCat.res.status)) {
        // This is the expected conflict response
        const dupBody = typeof dupCat.body === 'string' ? dupCat.body : JSON.stringify(dupCat.body);
        const hasConflictInfo = (
          dupBody.toLowerCase().includes('duplicate') ||
          dupBody.toLowerCase().includes('conflict') ||
          dupBody.toLowerCase().includes('exists') ||
          dupBody.toLowerCase().includes('already') ||
          dupCat.body?.error ||
          dupCat.body?.message
        );
        expect(hasConflictInfo, `Conflict error should explain reason: ${dupBody}`).toBeTruthy();
        // Confirm conflict status code is different from validation status code
        expect(dupCat.res.status).toBe(409);
        // Validation errors used 400 or 422, conflict uses 409 - they must be distinguishable
        expect(dupCat.res.status).not.toBe(validationStatusCode);
      } else if ([400, 422].includes(dupCat.res.status)) {
        // If API uses 400/422 for conflicts too, at least the response body type/message should differ
        const dupBody = typeof dupCat.body === 'string' ? dupCat.body : JSON.stringify(dupCat.body);
        const hasConflictKeyword = (
          dupBody.toLowerCase().includes('duplicate') ||
          dupBody.toLowerCase().includes('exists') ||
          dupBody.toLowerCase().includes('already') ||
          dupBody.toLowerCase().includes('conflict')
        );
        expect(hasConflictKeyword, `Conflict error should use different wording from validation error: ${dupBody}`).toBeTruthy();
      } else if ([200, 201].includes(dupCat.res.status)) {
        // If the API allowed duplicate, clean up
        if (dupCat.body?.id) createdCategoryIds.push(dupCat.body.id);
      }

    } finally {
      for (const articleId of createdArticleIds) {
        await safeDelete(`/api/articles/${articleId}/permanent`);
        await safeDelete(`/api/articles/${articleId}`);
      }
      for (const categoryId of createdCategoryIds) {
