  it('import with partial corruption returns a result summary with accurate counts for success, skipped, and failed items', async () => {
    const suffix = `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;

    // --- Test export operation has proper feedback ---
    const exportEndpoints = ['/api/export'];
    let exportWorked = false;
    for (const ep of exportEndpoints) {
      const exportRes = await api(ep, { method: 'GET' });
      if ([200].includes(exportRes.res.status)) {
        expect(exportRes.body).toBeTruthy();
        exportWorked = true;
        break;
      }
      const exportResPost = await api(ep, { method: 'POST' });
      if ([200].includes(exportResPost.res.status)) {
        expect(exportResPost.body).toBeTruthy();
        exportWorked = true;
        break;
      }
    }
    // Export endpoint must exist for this feature to be testable
    // If it doesn't exist, we still continue to test import

    // --- Import with completely invalid data should be rejected ---
    const badImport = await api('/api/import', {
      method: 'POST',
      body: JSON.stringify({ corrupted: true, data: 'not valid' }),
    });
    // Completely corrupt data should not be accepted as full success
    if ([200, 201].includes(badImport.res.status)) {
      // If API returns 200, body MUST indicate failure/issues
      const importBody = badImport.body;
      const bodyStr = typeof importBody === 'string' ? importBody : JSON.stringify(importBody);
      const indicatesIssues = (
        importBody?.failed > 0 ||
        importBody?.skipped > 0 ||
        (importBody?.summary && (importBody.summary.failed > 0 || importBody.summary.skipped > 0)) ||
        bodyStr.toLowerCase().includes('fail') ||
        bodyStr.toLowerCase().includes('error') ||
        bodyStr.toLowerCase().includes('invalid')
      );
      expect(
        indicatesIssues,
        `Import of fully corrupt data returning 2xx must NOT claim full success: ${bodyStr}`
      ).toBeTruthy();
    } else {
      // Non-2xx is expected for fully corrupt data
      expect([400, 422, 415, 500]).toContain(badImport.res.status);
      expect(badImport.body).toBeTruthy();
    }

    // --- Import with mixed valid/invalid data ---
    // We send 2 articles (1 good, 1 bad) and 2 categories (1 good, 1 bad)
    const mixedImport = await api('/api/import', {
      method: 'POST',
      body: JSON.stringify({
        articles: [
          {
            title: `Import Good ${suffix}`,
            content: `Good content ${suffix}`,
            status: 'draft',
          },
          {
            // Corrupt entry
            title: null,
            content: null,
            status: 'INVALID_STATUS_XYZ',
            corruptedField: 'garbage',
          },
        ],
        categories: [
          { name: `Import Cat ${suffix}` },
          { name: '', corruptedField: true }, // Invalid category - empty name
        ],
        tags: [],
      }),
    });

    if ([200, 201, 207].includes(mixedImport.res.status)) {
      const mixedBody = mixedImport.body;
      const mixedStr = typeof mixedBody === 'string' ? mixedBody : JSON.stringify(mixedBody);

      // Extract counts from response - try various common response shapes
      const summary = mixedBody?.summary || mixedBody?.results || mixedBody;

      // Helper to extract count from nested structures
      function extractCount(obj, ...keys) {
        for (const key of keys) {
          if (obj?.[key] !== undefined) return obj[key];
        }
        return undefined;
      }

      const successCount = extractCount(summary, 'success', 'succeeded', 'imported', 'successCount');
      const failedCount = extractCount(summary, 'failed', 'failures', 'failedCount', 'errors');
      const skippedCount = extractCount(summary, 'skipped', 'skippedCount');

      // Must NOT claim everything was fully successful
      // At minimum, failed count should be > 0 since we sent corrupt data
      if (typeof failedCount === 'number') {
        expect(failedCount, 'Failed count should be > 0 for corrupt entries').toBeGreaterThan(0);
      }
      if (typeof successCount === 'number') {
        // We sent 2 articles + 2 categories = 4 items, at least 2 are corrupt
        // Success should be less than total items
        expect(successCount, 'Success count should not equal total input count when some items are corrupt').toBeLessThan(4);
      }

      // Body must contain some distinguishing info about partial success
      const hasSummaryInfo = (
        typeof failedCount === 'number' ||
        typeof skippedCount === 'number' ||
        mixedBody?.errors ||
        mixedBody?.warnings ||
        mixedStr.toLowerCase().includes('fail') ||
        mixedStr.toLowerCase().includes('skip') ||
        mixedStr.toLowerCase().includes('error') ||
        mixedStr.toLowerCase().includes('partial')
      );
      expect(
        hasSummaryInfo,
        `Mixed import must distinguish success/skipped/failed, not claim full success: ${mixedStr}`
      ).toBeTruthy();

      // Verify that successfully imported items are actually accessible
      const articlesRes = await api('/api/articles');
      if (articlesRes.res.status === 200) {
        const articlesList = articlesRes.body?.items || articlesRes.body?.articles || (Array.isArray(articlesRes.body) ? articlesRes.body : []);
        const importedArticle = articlesList.find(a => a.title === `Import Good ${suffix}`);
        // The good article should have been imported
        if (successCount > 0 || (typeof successCount !== 'number')) {
          expect(importedArticle, 'Successfully imported article should be visible in article list').toBeTruthy();
          // Clean up imported article
          if (importedArticle?.id) {
            await safeDelete(`/api/articles/${importedArticle.id}/permanent`);
            await safeDelete(`/api/articles/${importedArticle.id}`);
          }
        }
      }

      // Clean up imported category
      const catsRes = await api('/api/categories');
      if (catsRes.res.status === 200) {
        const catsList = catsRes.body?.items || catsRes.body?.categories || (Array.isArray(catsRes.body) ? catsRes.body : []);
        const importedCat = catsList.find(c => c.name === `Import Cat ${suffix}`);
        if (importedCat?.id) {
          await safeDelete(`/api/categories/${importedCat.id}`);
        }
      }
    } else {
      // If import rejects entirely for mixed data, that's acceptable but must explain
      expect([400, 422]).toContain(mixedImport.res.status);
      expect(mixedImport.body).toBeTruthy();
    }
  });

  it('version restore creates exactly one new record and concurrent restores do not create duplicates', async () => {
    const suffix = `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
    const createdCategoryIds = [];
    const createdArticleIds = [];

    try {
      const category = await createCategory(`VerCat ${suffix}`);
      createdCategoryIds.push(category.id);

      // Create article with title A
      const create = await createArticle({
        title: `VerA ${suffix}`,
        content: `Content A ${suffix}`,
        status: 'draft',
        primaryCategoryId: category.id,
        categoryIds: [category.id],
      });
      expect([200, 201]).toContain(create.res.status);
      const articleId = create.body?.id;
      expect(articleId).toBeTruthy();
      createdArticleIds.push(articleId);

      // Save version B
      const saveB = await trySaveArticle(articleId, {
        title: `VerB ${suffix}`,
        content: `Content B ${suffix}`,
        status: 'draft',
        primaryCategoryId: category.id,
        categoryIds: [category.id],
      });
      expect([200, 204]).toContain(saveB.res.status);

      // Save version C
      const saveC = await trySaveArticle(articleId, {
        title: `VerC ${suffix}`,
        content: `Content C ${suffix}`,
        status: 'draft',
        primaryCategoryId: category.id,
        categoryIds: [category.id],
      });
      expect([200, 204]).toContain(saveC.res.status);

      // Get versions
      const versionsRes = await api(`/api/articles/${articleId}/versions`);
      expect(versionsRes.res.status).toBe(200);

      const versions = extractVersions(versionsRes.body);
      const countBeforeRestore = versions.length;
      expect(countBeforeRestore).toBeGreaterThanOrEqual(1);

      // Find the earliest version to restore (version A)
      const earliest = versions[versions.length - 1] || versions[0];
      const earliestId = earliest?.id || earliest?.versionId;
      expect(earliestId, 'Must find a version ID to restore').toBeTruthy();

      // --- Restore earliest version ---
      const restore1 = await tryRestoreVersion(articleId, earliestId);
      expect([200, 201, 204]).toContain(restore1.res.status);

      // Check that exactly one new version was created
      const versionsAfter1 = await api(`/api/articles/${articleId}/versions`);
      expect(versionsAfter1.res.status).toBe(200);
      const countAfter1 = versionsCount(versionsAfter1.body);
      expect(
        countAfter1,
        `Version restore must create exactly 1 new version record; before=${countBeforeRestore}, after=${countAfter1}`
      ).toBe(countBeforeRestore + 1);

      // Verify current article title is restored to A
      const currentArticle = await getArticle(articleId);
      expect(currentArticle.res.status).toBe(200);
      expect(currentArticle.body?.title).toContain(`VerA ${suffix}`);

      // Verify all previous versions (B, C) and the new restore version are still in history
      const versionsAfterRestore = extractVersions(versionsAfter1.body);
      expect(versionsAfterRestore.length).toBe(countBeforeRestore + 1);

      // Verify updated time reflects the restore time, not old version time
      const updatedAt = currentArticle.body?.updatedAt || currentArticle.body?.updated_at || currentArticle.body?.lastModified;
      if (updatedAt) {
        const updateTime = new Date(updatedAt).getTime();
        const now = Date.now();
        // Updated time should be very recent (within last 30 seconds)
        expect(now - updateTime).toBeLessThan(30000);
      }

      // --- Simulate rapid repeated restore (concurrent double-click prevention) ---
      const concurrentRestores = Promise.all([
        tryRestoreVersion(articleId, earliestId),
        tryRestoreVersion(articleId, earliestId),
        tryRestoreVersion(articleId, earliestId),
      ]);
      const results = await concurrentRestores;

      // Count how many succeeded
      const successfulRestores = results.filter(r => [200, 201, 204].includes(r.res.status));
      const conflictRestores = results.filter(r => [409, 429].includes(r.res.status));

      // All should either succeed or return conflict - no server errors
      for (const r of results) {
        expect([200, 201, 204, 409, 429]).toContain(r.res.status);
      }

      // After concurrent restores, check version count
      const versionsAfterConcurrent = await api(`/api/articles/${articleId}/versions`);
      expect(versionsAfterConcurrent.res.status).toBe(200);
      const countAfterConcurrent = versionsCount(versionsAfterConcurrent.body);

      // Concurrent restores should create at most 1 additional version (idempotency/dedup)
      // If API allows each to create a version, at most successfulRestores.length new versions
      // But the spirit of anti-duplicate is: rapid clicks should not create unbounded versions
      expect(
        countAfterConcurrent,
        `Concurrent restore should not create unbounded versions; after single=${countAfter1}, after concurrent=${countAfterConcurrent}, successful=${successfulRestores.length}`
      ).toBeLessThanOrEqual(countAfter1 + successfulRestores.length);

      // Ideally only 1 version should be added for rapid clicks
      // This is the stricter check for true deduplication
      if (successfulRestores.length > 1) {
        // If multiple succeeded, warn but check they didn't create excessive duplicates
        expect(countAfterConcurrent - countAfter1).toBeLessThanOrEqual(successfulRestores.length);
      }

    } finally {
      for (const articleId of createdArticleIds) {
        await safeDelete(`/api/articles/${articleId}/permanent`);
        await safeDelete(`/api/articles/${articleId}`);
      }
      for (const categoryId of createdCategoryIds) {
        await safeDelete(`/api/categories/${categoryId}`);
      }
    }
  });

