import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function api(path, options = {}) {
  const res = await fetch(`${BASE_URL}${path}`, {
    headers: {
      'Content-Type': 'application/json',
      ...(options.headers || {}),
    },
    ...options,
  });

  const text = await res.text();
  let body = null;
  try {
    body = text ? JSON.parse(text) : null;
  } catch {
    body = text;
  }

  return { res, body };
}

async function createCategory(name) {
  const { res, body } = await api('/api/categories', {
    method: 'POST',
    body: JSON.stringify({ name, slug: name.toLowerCase().replace(/[^a-z0-9]+/g, '-') }),
  });
  expect([200, 201]).toContain(res.status);
  expect(body?.id).toBeTruthy();
  return body;
}

async function createArticle(payload) {
  return api('/api/articles', { method: 'POST', body: JSON.stringify(payload) });
}

async function updateArticle(id, payload) {
  return api(`/api/articles/${id}`, { method: 'PUT', body: JSON.stringify(payload) });
}

async function getArticle(id) {
  return api(`/api/articles/${id}`);
}

async function safeDelete(path) {
  try {
    await api(path, { method: 'DELETE' });
  } catch {
    // ignore cleanup errors
  }
}

async function getSeoPreview() {
  return api('/api/seo/preview');
}

async function getSubscriptionFeed() {
  return api('/api/subscription/articles');
}

async function getSitemapPreview() {
  return api('/api/sitemap/preview');
}

function listFromBody(body) {
  if (Array.isArray(body)) return body;
  if (Array.isArray(body?.items)) return body.items;
  if (Array.isArray(body?.articles)) return body.articles;
  if (Array.isArray(body?.data)) return body.data;
  if (Array.isArray(body?.urls)) return body.urls;
  return [];
}

function containsId(body, id) {
  return listFromBody(body).some(item => item?.id === id || item?.articleId === id);
}

describe('round33_primary_category_priority_and_public_exclusion', () => {
  it('keeps primary category first in detail/public data and excludes article from public previews when primary category is removed or invalid', async () => {
    const suffix = `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
    const categoryIds = [];
    const articleIds = [];

    try {
      const primary = await createCategory(`Primary ${suffix}`);
      const secondary = await createCategory(`Secondary ${suffix}`);
      categoryIds.push(primary.id, secondary.id);

      const create = await createArticle({
        title: `Priority article ${suffix}`,
        content: `Public body ${suffix}`,
        status: 'published',
        publishedAt: new Date().toISOString(),
        primaryCategoryId: primary.id,
        categoryIds: [primary.id, secondary.id],
      });
      expect([200, 201]).toContain(create.res.status);
      expect(create.body?.id).toBeTruthy();
      const articleId = create.body.id;
      articleIds.push(articleId);

      const detail = await getArticle(articleId);
      expect(detail.res.status).toBe(200);
      expect(detail.body?.primaryCategoryId).toBe(primary.id);
      expect(Array.isArray(detail.body?.categoryIds), `expected categoryIds array in detail, got ${JSON.stringify(detail.body)}`).toBe(true);
      expect(detail.body.categoryIds[0], `primary category should be first in detail categoryIds, got ${JSON.stringify(detail.body.categoryIds)}`).toBe(primary.id);
      expect(detail.body.categoryIds[1]).toBe(secondary.id);

      const seo1 = await getSeoPreview();
      const sub1 = await getSubscriptionFeed();
      const site1 = await getSitemapPreview();
      expect(seo1.res.status).toBe(200);
      expect(sub1.res.status).toBe(200);
      expect(site1.res.status).toBe(200);
      expect(containsId(seo1.body, articleId), `article should appear in SEO preview; got ${JSON.stringify(seo1.body)}`).toBe(true);
      expect(containsId(sub1.body, articleId), `article should appear in subscription feed; got ${JSON.stringify(sub1.body)}`).toBe(true);
      expect(containsId(site1.body, articleId), `article should appear in sitemap preview; got ${JSON.stringify(site1.body)}`).toBe(true);

      const removeSecondary = await updateArticle(articleId, {
        title: `Priority article ${suffix}`,
        content: `Public body ${suffix}`,
        status: 'published',
        publishedAt: detail.body?.publishedAt || new Date().toISOString(),
        primaryCategoryId: primary.id,
        categoryIds: [primary.id],
      });
      expect([200, 204]).toContain(removeSecondary.res.status);

      const detail2 = await getArticle(articleId);
      expect(detail2.res.status).toBe(200);
      expect(detail2.body?.primaryCategoryId).toBe(primary.id);
      expect(detail2.body?.categoryIds).toEqual([primary.id]);

      const seo2 = await getSeoPreview();
      const sub2 = await getSubscriptionFeed();
      const site2 = await getSitemapPreview();
      expect(containsId(seo2.body, articleId)).toBe(true);
      expect(containsId(sub2.body, articleId)).toBe(true);
      expect(containsId(site2.body, articleId)).toBe(true);

      const removePrimary = await updateArticle(articleId, {
        title: `Priority article ${suffix}`,
        content: `Public body ${suffix}`,
        status: 'published',
        publishedAt: detail2.body?.publishedAt || new Date().toISOString(),
        primaryCategoryId: null,
        categoryIds: [],
      });

      if ([200, 204].includes(removePrimary.res.status)) {
        const detail3 = await getArticle(articleId);
        if (detail3.res.status === 200) {
          expect(detail3.body?.primaryCategoryId ?? null).toBe(null);
        }

        const seo3 = await getSeoPreview();
        const sub3 = await getSubscriptionFeed();
        const site3 = await getSitemapPreview();
        expect(seo3.res.status).toBe(200);
        expect(sub3.res.status).toBe(200);
        expect(site3.res.status).toBe(200);
        expect(containsId(seo3.body, articleId)).toBe(false);
        expect(containsId(sub3.body, articleId)).toBe(false);
        expect(containsId(site3.body, articleId)).toBe(false);
      } else {
        expect([400, 409, 422]).toContain(removePrimary.res.status);
        const seo3 = await getSeoPreview();
        const sub3 = await getSubscriptionFeed();
        const site3 = await getSitemapPreview();
        expect(containsId(seo3.body, articleId)).toBe(true);
        expect(containsId(sub3.body, articleId)).toBe(true);
        expect(containsId(site3.body, articleId)).toBe(true);
      }
    } finally {
      for (const articleId of articleIds) {
        await safeDelete(`/api/articles/${articleId}`);
      }
      for (const categoryId of categoryIds) {
        await safeDelete(`/api/categories/${categoryId}`);
      }
    }
  });
});

