describe('delete_node_cascades_related_data', () => {
  it('should cascade-delete related connections, comments, and presentation steps, update stats, and reject illegal deletion of protected root node', async () => {
    let boardId;
    let rootId;
    let childId;
    let leafId;
    let commentId;
    let stepId;

    try {
      const { res: boardRes, body: boardBody } = await request('/boards', {
        method: 'POST',
        body: JSON.stringify({ name: 'Delete Cascade Board', type: 'mindmap' }),
      });
      expect(boardRes.status, `board creation should succeed`).toBe(201);
      boardId = boardBody.id;

      const root = await request(`/boards/${boardId}/nodes`, { method: 'POST', body: JSON.stringify({ title: 'Root', type: 'root' }) });
      const child = await request(`/boards/${boardId}/nodes`, { method: 'POST', body: JSON.stringify({ title: 'Child', type: 'topic' }) });
      const leaf = await request(`/boards/${boardId}/nodes`, { method: 'POST', body: JSON.stringify({ title: 'Leaf', type: 'topic' }) });
      expect([200, 201]).toContain(root.res.status);
      expect([200, 201]).toContain(child.res.status);
      expect([200, 201]).toContain(leaf.res.status);
      rootId = root.body.id;
      childId = child.body.id;
      leafId = leaf.body.id;

      const conn1 = await request(`/boards/${boardId}/connections`, { method: 'POST', body: JSON.stringify({ fromNodeId: rootId, toNodeId: childId }) });
      const conn2 = await request(`/boards/${boardId}/connections`, { method: 'POST', body: JSON.stringify({ fromNodeId: childId, toNodeId: leafId }) });
      expect([200, 201]).toContain(conn1.res.status);
      expect([200, 201]).toContain(conn2.res.status);

      const comment = await request(`/boards/${boardId}/nodes/${childId}/comments`, {
        method: 'POST',
        body: JSON.stringify({ content: 'Comment on child' }),
      });
      expect([200, 201]).toContain(comment.res.status);
      commentId = comment.body.id;

      const step = await request(`/boards/${boardId}/presentation/steps`, {
        method: 'POST',
        body: JSON.stringify({ nodeId: childId, title: 'Step for child' }),
      });
      expect([200, 201]).toContain(step.res.status);
      stepId = step.body.id;

      const { res: beforeStatsRes, body: beforeStatsBody } = await request(`/boards/${boardId}/stats`);
      expect(beforeStatsRes.status, `stats fetch before delete should succeed`).toBe(200);
      expect(typeof beforeStatsBody.nodeCount, `stats should include nodeCount`).toBe('number');
      expect(typeof beforeStatsBody.connectionCount, `stats should include connectionCount`).toBe('number');

      const { res: deleteChildRes, body: deleteChildBody } = await request(`/boards/${boardId}/nodes/${childId}`, { method: 'DELETE' });
      expect([200, 204], `deleting child node should succeed, got ${deleteChildRes.status} with body ${JSON.stringify(deleteChildBody)}`).toContain(deleteChildRes.status);
      childId = undefined;

      const { res: getDeletedNodeRes } = await request(`/boards/${boardId}/nodes/${comment.body?.nodeId || 'unknown'}`);
      expect([404, 410], `deleted child node should no longer be retrievable, got ${getDeletedNodeRes.status}`).toContain(getDeletedNodeRes.status);

      const { res: connsRes, body: connsBody } = await request(`/boards/${boardId}/connections`);
      expect(connsRes.status, `connections list after delete should succeed`).toBe(200);
      expect(Array.isArray(connsBody), `connections list should be array`).toBe(true);
      expect(connsBody.some((c) => c.fromNodeId === rootId || c.toNodeId === rootId ? (c.fromNodeId === rootId && c.toNodeId === child.body.id) || (c.fromNodeId === child.body.id && c.toNodeId === leafId) : false), `connections related to deleted child should be removed`).toBe(false);

      const { res: commentsRes, body: commentsBody } = await request(`/boards/${boardId}/comments`);
      expect(commentsRes.status, `comments list should succeed`).toBe(200);
      expect(Array.isArray(commentsBody), `comments list should be array`).toBe(true);
      expect(commentsBody.some((c) => c.id === commentId), `comment attached to deleted node should be removed`).toBe(false);

      const { res: stepsRes, body: stepsBody } = await request(`/boards/${boardId}/presentation/steps`);
      expect(stepsRes.status, `presentation steps list should succeed`).toBe(200);
      expect(Array.isArray(stepsBody), `presentation steps should be array`).toBe(true);
      expect(stepsBody.some((s) => s.id === stepId), `presentation step attached to deleted node should be removed`).toBe(false);

      const { res: afterStatsRes, body: afterStatsBody } = await request(`/boards/${boardId}/stats`);
      expect(afterStatsRes.status, `stats fetch after delete should succeed`).toBe(200);
      expect(afterStatsBody.nodeCount, `node count should decrease after deleting child node`).toBeLessThan(beforeStatsBody.nodeCount);
      expect(afterStatsBody.connectionCount, `connection count should decrease after deleting related node`).toBeLessThan(beforeStatsBody.connectionCount);

      const { res: deleteRootRes, body: deleteRootBody } = await request(`/boards/${boardId}/nodes/${rootId}`, { method: 'DELETE' });
      expect([400, 409, 422], `protected root node deletion should be rejected to avoid illegal board state, got ${deleteRootRes.status} with body ${JSON.stringify(deleteRootBody)}`).toContain(deleteRootRes.status);
    } finally {
      await safeDeleteBoard(boardId);
    }
  });
});

import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function request(method: string, path: string, body?: any) {
  const res = await fetch(`${BASE_URL}${path}`, {
    method,
    headers: { 'Content-Type': 'application/json' },
    body: body === undefined ? undefined : JSON.stringify(body),
  });
  const text = await res.text();
  let json: any = null;
  try { json = text ? JSON.parse(text) : null; } catch { json = text; }
  return { res, body: json };
}

async function tryPaths(method: string, paths: string[], payload?: any) {
  for (const path of paths) {
    const out = await request(method, path, payload);
    if (out.res.status !== 404 && out.res.status !== 405) return { ...out, usedPath: path };
  }
  throw new Error(`No working endpoint found among: ${paths.join(', ')}`);
}

async function createBoard(title: string, template = 'mindmap') {
  const out = await tryPaths('POST', ['/api/boards', '/boards'], { title, template });
  expect([200, 201]).toContain(out.res.status);
  const id = out.body?.id || out.body?.data?.id || out.body?.boardId;
  expect(id).toBeTruthy();
  const basePath = out.usedPath;
  return { id, basePath };
}

async function createNode(basePath: string, boardId: string, payload: any) {
  const out = await tryPaths('POST', [`${basePath}/${boardId}/nodes`, '/api/nodes', '/nodes'],
    payload.boardId ? payload : { boardId, ...payload });
  expect([200, 201]).toContain(out.res.status);
  const id = out.body?.id || out.body?.data?.id;
  expect(id).toBeTruthy();
  return id;
}

async function createConnection(basePath: string, boardId: string, fromId: string, toId: string) {
  return tryPaths('POST', [`${basePath}/${boardId}/connections`, '/api/connections', '/connections'],
    { boardId, fromId, toId });
}

async function addComment(basePath: string, boardId: string, nodeId: string, content: string, parentId?: string) {
  const payload: any = { content, text: content, boardId, nodeId };
  if (parentId) payload.parentId = parentId;
  return tryPaths('POST', [`${basePath}/${boardId}/nodes/${nodeId}/comments`, `/api/boards/${boardId}/comments`, '/api/comments'],
    payload);
}

async function markCommentResolved(basePath: string, boardId: string, commentId: string, resolved: boolean) {
  for (const path of [
    `${basePath}/${boardId}/comments/${commentId}`,
    `/api/comments/${commentId}`,
    `/api/boards/${boardId}/comments/${commentId}`
  ]) {
    for (const field of [{ resolved }, { status: resolved ? 'resolved' : 'unresolved' }]) {
      const out = await request('PATCH', path, field);
      if (out.res.status !== 404 && out.res.status !== 405) return out;
    }
  }
  return null;
}

async function addTag(basePath: string, boardId: string, nodeId: string, tag: string) {
  for (const path of [
    `${basePath}/${boardId}/nodes/${nodeId}/tags`,
    `/api/nodes/${nodeId}/tags`,
  ]) {
    const out = await request('POST', path, { tag, name: tag, boardId });
    if (out.res.status !== 404 && out.res.status !== 405) return out;
  }
  for (const path of [
    `${basePath}/${boardId}/nodes/${nodeId}`,
    `/api/nodes/${nodeId}`,
  ]) {
    const out = await request('PATCH', path, { tags: [tag] });
    if (out.res.status !== 404 && out.res.status !== 405) return out;
  }
  return null;
}

async function addStep(basePath: string, boardId: string, nodeId: string) {
  return tryPaths('POST', [
    `${basePath}/${boardId}/presentation/steps`,
    `/api/boards/${boardId}/presentation/steps`,
    '/api/presentation/steps'
  ], { nodeId, boardId });
}

async function updateView(basePath: string, boardId: string, view: any) {
  for (const path of [`${basePath}/${boardId}`, `/api/boards/${boardId}`]) {
    const out = await request('PATCH', path, { viewState: view, view });
    if (out.res.status !== 404 && out.res.status !== 405) return out;
  }
  return null;
}

async function exportBoard(basePath: string, boardId: string) {
  const out = await tryPaths('GET', [`${basePath}/${boardId}/export`, `/api/boards/${boardId}/export`]);
  expect(out.res.ok).toBe(true);
  return out.body;
}

async function importBoard(payload: any) {
  return tryPaths('POST', ['/api/boards/import', '/boards/import'], payload);
}

async function getBoard(boardId: string) {
  return tryPaths('GET', [`/api/boards/${boardId}`, `/boards/${boardId}`]);
}

async function getNodes(basePath: string, boardId: string) {
  const out = await tryPaths('GET', [`${basePath}/${boardId}/nodes`, `/api/boards/${boardId}/nodes`]);
  const nodes = Array.isArray(out.body) ? out.body : (out.body?.nodes || out.body?.data?.nodes || out.body?.data || []);
  return nodes;
}

async function getConnections(basePath: string, boardId: string) {
  try {
    const out = await tryPaths('GET', [`${basePath}/${boardId}/connections`, `/api/boards/${boardId}/connections`]);
    const conns = Array.isArray(out.body) ? out.body : (out.body?.connections || out.body?.edges || out.body?.data || []);
    return conns;
  } catch {
    return [];
  }
}

async function getComments(basePath: string, boardId: string, nodeId: string) {
  const out = await tryPaths('GET', [
    `${basePath}/${boardId}/nodes/${nodeId}/comments`,
    `/api/boards/${boardId}/nodes/${nodeId}/comments`
  ]);
  const comments = Array.isArray(out.body) ? out.body : (out.body?.comments || out.body?.items || out.body?.data || []);
  return comments;
}

async function getSteps(basePath: string, boardId: string) {
  const out = await tryPaths('GET', [
    `${basePath}/${boardId}/presentation/steps`,
    `/api/boards/${boardId}/presentation/steps`
  ]);
  const steps = Array.isArray(out.body) ? out.body : (out.body?.steps || out.body?.data || []);
  return steps;
}

async function tryDeleteBoard(boardId: string) {
  if (!boardId) return;
  try { await request('DELETE', `/api/boards/${boardId}`); } catch {}
  try { await request('DELETE', `/boards/${boardId}`); } catch {}
}

describe('export_import_restores_full_board_state', () => {
  it('should export and import full board state including nodes, connections, comments with resolved status, tags, presentation steps, and view state', async () => {
    const board = await createBoard(`export-full-${Date.now()}`, 'mindmap');
    let importedId: string | undefined;
    try {
      // Create nodes
      const n1 = await createNode(board.basePath, board.id, { title: 'Root Node', text: 'Root Node' });
      const n2 = await createNode(board.basePath, board.id, { title: 'Child Node', text: 'Child Node' });

      // Create connection
      const conn = await createConnection(board.basePath, board.id, n1, n2);
      expect([200, 201]).toContain(conn.res.status);

      // Add tags
      await addTag(board.basePath, board.id, n1, 'TagA');
      await addTag(board.basePath, board.id, n1, 'TagB');
      await addTag(board.basePath, board.id, n2, 'TagB');

      // Add comment + reply
      const c1 = await addComment(board.basePath, board.id, n1, 'Top comment');
      expect([200, 201]).toContain(c1.res.status);
      const c1Id = c1.body?.id || c1.body?.data?.id || c1.body?.commentId;
      expect(c1Id, 'comment id should be returned').toBeTruthy();

      // Mark the comment as unresolved explicitly (should already be default)
      await markCommentResolved(board.basePath, board.id, c1Id, false);

      // Add reply
      const reply = await addComment(board.basePath, board.id, n1, 'Reply comment', c1Id);
      expect([200, 201]).toContain(reply.res.status);

      // Add presentation step
      const step = await addStep(board.basePath, board.id, n1);
      expect([200, 201]).toContain(step.res.status);

      // Set view state
      await updateView(board.basePath, board.id, { zoom: 1.5, x: 100, y: 200, center: { x: 100, y: 200 } });

      // Verify pre-export state
      const preExportComments = await getComments(board.basePath, board.id, n1);
      expect(preExportComments.length).toBeGreaterThanOrEqual(1);

      const preExportSteps = await getSteps(board.basePath, board.id);
      expect(preExportSteps.length).toBeGreaterThanOrEqual(1);

      // Export
      const exported = await exportBoard(board.basePath, board.id);
      expect(exported).toBeTruthy();
      expect(typeof exported).toBe('object');

      // Import
      const importRes = await importBoard(exported);
      expect([200, 201]).toContain(importRes.res.status);
      importedId = importRes.body?.id || importRes.body?.boardId || importRes.body?.data?.id;
      expect(importedId).toBeTruthy();

      // Verify the imported board
      const importedBoard = await getBoard(importedId as string);
      expect(importedBoard.res.status).toBe(200);
      const ib = importedBoard.body;

      // Verify template
      const template = ib.template || ib.type || ib.mode;
      expect(template).toBe('mindmap');

      // Verify nodes
      const importedNodes = await getNodes(board.basePath, importedId as string).catch(() => {
        return ib.nodes || ib.data?.nodes || [];
      });
      expect(importedNodes.length).toBeGreaterThanOrEqual(2);
      const titles = importedNodes.map((n: any) => n.title || n.label || n.text);
      expect(titles).toContain('Root Node');
      expect(titles).toContain('Child Node');

      // Verify connections
      const importedConns = await getConnections(board.basePath, importedId as string).catch(() => {
        return ib.edges || ib.connections || ib.links || ib.data?.edges || [];
      });
      expect(importedConns.length).toBeGreaterThanOrEqual(1);

      // Verify tags are present on nodes with specific values
      const rootNode = importedNodes.find((n: any) => (n.title || n.label || n.text) === 'Root Node');
      expect(rootNode, 'Root Node should exist in imported board').toBeTruthy();
      expect(rootNode.tags, 'Root Node should have tags after import').toBeTruthy();
      expect(Array.isArray(rootNode.tags)).toBe(true);
      expect(rootNode.tags.length).toBeGreaterThanOrEqual(1);
      // Verify specific tag values (case-insensitive check)
      const rootTagsLower = rootNode.tags.map((t: string) => t.toLowerCase());
      expect(rootTagsLower).toContain('taga');
      expect(rootTagsLower).toContain('tagb');

      const childNode = importedNodes.find((n: any) => (n.title || n.label || n.text) === 'Child Node');
      expect(childNode, 'Child Node should exist in imported board').toBeTruthy();
      if (childNode.tags) {
        const childTagsLower = childNode.tags.map((t: string) => t.toLowerCase());
        expect(childTagsLower).toContain('tagb');
      }

      // Verify view state is restored
      const viewState = ib.viewState || ib.view || ib.data?.view || ib.data?.viewState;
      expect(viewState, 'view state should be restored after import').toBeTruthy();
      const zoom = viewState.zoom || viewState.scale;
      expect(zoom).toBeTruthy();
      expect(zoom).toBeCloseTo(1.5, 1);

      // Verify comments with resolved status via API
