      const importedComments = await getComments(board.basePath, importedId as string, importedRootId).catch(() => []);
      expect(importedComments.length).toBeGreaterThanOrEqual(1);

      // Find the top-level comment
      const topComment = importedComments.find((c: any) => (c.text || c.content) === 'Top comment');
      expect(topComment, 'Top comment should be restored').toBeTruthy();
      // Verify resolved status is preserved (should be false/unresolved)
      expect(typeof topComment.resolved).toBe('boolean');
      expect(topComment.resolved, 'unresolved comment should remain unresolved after import').toBe(false);

      // Verify reply exists
      const hasReply = importedComments.some((c: any) => (c.text || c.content) === 'Reply comment')
        || (topComment.replies && topComment.replies.some((r: any) => (r.text || r.content) === 'Reply comment'));
      expect(hasReply, 'Reply comment should be restored after import').toBe(true);

      // Verify presentation steps via API
      const importedSteps = await getSteps(board.basePath, importedId as string).catch(() => []);
      expect(importedSteps.length).toBeGreaterThanOrEqual(1);
      // Verify the step references a node
      const stepNodeId = importedSteps[0].nodeId || importedSteps[0].node;
      expect(stepNodeId).toBeTruthy();
    } finally {
      await tryDeleteBoard(board.id);
      if (importedId) await tryDeleteBoard(importedId);
    }
