      // Test that when a comment fails to submit, the server returns an error status
      // and the error response does not consume/discard the input text
      const failComment = await request(`/api/boards/${boardId}/nodes/nonexistent-node-id/comments`, {
        method: 'POST',
        body: JSON.stringify({ text: 'Should fail', content: 'Should fail' }),
      });
