      expect([400, 404, 409, 422, 500]).toContain(failComment.res.status);
      // The response should indicate an error, allowing the client to retain the input and retry
      if (failComment.body && typeof failComment.body === 'object') {
        const hasErrorInfo = failComment.body.error || failComment.body.message || failComment.body.reason;
        expect(hasErrorInfo).toBeTruthy();
      }

      // --- Delete node: cascade delete comments ---
      const deleteNode = await request(`/api/boards/${boardId}/nodes/${nodeId}`, { method: 'DELETE' });
      expect([200, 204]).toContain(deleteNode.res.status);

      const commentsAfterDelete = await request(`/api/boards/${boardId}/nodes/${nodeId}/comments`);
      if (commentsAfterDelete.res.status === 200) {
        const remaining = commentsAfterDelete.body.comments || commentsAfterDelete.body.items || commentsAfterDelete.body;
        expect(Array.isArray(remaining)).toBe(true);
        expect(remaining.length, 'comments should be cascade deleted after node deletion').toBe(0);
      } else {
        expect([404, 410]).toContain(commentsAfterDelete.res.status);
      }
    } finally {
      await safeDeleteBoard(boardId);
    }
