    let boardId;
    let nodeId;

    try {
      const { res: boardRes, body: boardBody } = await request('/boards', {
        method: 'POST',
        body: JSON.stringify({ name: 'Node Title Validation Board', type: 'mindmap' }),
      });
      expect(boardRes.status, `board creation should succeed, got ${boardRes.status} with body ${JSON.stringify(boardBody)}`).toBe(201);
      boardId = boardBody.id;

      const { res: createNodeRes, body: createNodeBody } = await request(`/boards/${boardId}/nodes`, {
        method: 'POST',
        body: JSON.stringify({ title: 'Original Title', type: 'topic' }),
      });
      expect([200, 201], `node creation should succeed, got ${createNodeRes.status} with body ${JSON.stringify(createNodeBody)}`).toContain(createNodeRes.status);
      expect(createNodeBody.title, `initial node title should match`).toBe('Original Title');
      nodeId = createNodeBody.id;

      const { res: invalidBlankRes, body: invalidBlankBody } = await request(`/boards/${boardId}/nodes/${nodeId}`, {
        method: 'PATCH',
        body: JSON.stringify({ title: '    ' }),
      });
      expect([400, 422], `blank title should be rejected, got ${invalidBlankRes.status} with body ${JSON.stringify(invalidBlankBody)}`).toContain(invalidBlankRes.status);

      const { res: afterBlankGetRes, body: afterBlankGetBody } = await request(`/boards/${boardId}/nodes/${nodeId}`);
      expect(afterBlankGetRes.status, `node should still be fetchable after invalid blank update`).toBe(200);
      expect(afterBlankGetBody.title, `node title should remain unchanged after blank rejection`).toBe('Original Title');

      const tooLongTitle = 'x'.repeat(51);
      const { res: invalidLongRes, body: invalidLongBody } = await request(`/boards/${boardId}/nodes/${nodeId}`, {
        method: 'PATCH',
        body: JSON.stringify({ title: tooLongTitle }),
      });
      expect([400, 422], `title longer than 50 chars should be rejected, got ${invalidLongRes.status} with body ${JSON.stringify(invalidLongBody)}`).toContain(invalidLongRes.status);

      const { res: afterLongGetRes, body: afterLongGetBody } = await request(`/boards/${boardId}/nodes/${nodeId}`);
      expect(afterLongGetRes.status, `node should still be fetchable after invalid long update`).toBe(200);
      expect(afterLongGetBody.title, `node title should remain unchanged after long-title rejection`).toBe('Original Title');

      const validTitle = '   Valid Updated Title   ';
      const { res: validUpdateRes, body: validUpdateBody } = await request(`/boards/${boardId}/nodes/${nodeId}`, {
        method: 'PATCH',
        body: JSON.stringify({ title: validTitle }),
      });
      expect([200, 204], `valid title update should succeed, got ${validUpdateRes.status} with body ${JSON.stringify(validUpdateBody)}`).toContain(validUpdateRes.status);

      const { res: finalGetRes, body: finalGetBody } = await request(`/boards/${boardId}/nodes/${nodeId}`);
      expect(finalGetRes.status, `node fetch after valid update should succeed`).toBe(200);
      expect(typeof finalGetBody.title, `updated node should contain title`).toBe('string');
      expect(finalGetBody.title.trim(), `updated title trimmed value should match expected logical title`).toBe('Valid Updated Title');
      expect(finalGetBody.title.trim().length, `updated title trimmed length should be <= 50`).toBeLessThanOrEqual(50);
      expect(finalGetBody.title.trim().length, `updated title trimmed length should be >= 1`).toBeGreaterThanOrEqual(1);
    } finally {
      await safeDeleteBoard(boardId);
    }
  });
});

