import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function request(method: string, path: string, body?: any) {
  const res = await fetch(`${BASE_URL}${path}`, {
    method,
    headers: { 'Content-Type': 'application/json' },
    body: body === undefined ? undefined : JSON.stringify(body),
  });
  const text = await res.text();
  let json: any = null;
  try { json = text ? JSON.parse(text) : null; } catch { json = text; }
  return { res, body: json };
}

async function createBoard(name: string) {
  for (const c of [
    { path: '/api/boards', body: { title: name } },
    { path: '/boards', body: { title: name } },
  ]) {
    const { res, body } = await request('POST', c.path, c.body);
    if (res.ok && (body?.id || body?.data?.id)) return { id: body.id || body.data.id, base: c.path.includes('/api/') ? '/api/boards' : '/boards' };
  }
  throw new Error('Unable to create board');
}

async function createNode(base: string, boardId: string) {
  for (const path of [`${base}/${boardId}/nodes`, '/api/nodes', '/nodes']) {
    const payload = path.includes(`/${boardId}/`) ? { title: 'tag-node' } : { boardId, title: 'tag-node' };
    const { res, body } = await request('POST', path, payload);
    if (res.ok && (body?.id || body?.data?.id)) return body.id || body.data.id;
  }
  throw new Error('Unable to create node');
}

async function updateNodeTags(base: string, boardId: string, nodeId: string, tags: string[]) {
  const candidates = [
    { method: 'PUT', path: `${base}/${boardId}/nodes/${nodeId}/tags`, body: { tags } },
    { method: 'PATCH', path: `${base}/${boardId}/nodes/${nodeId}`, body: { tags } },
    { method: 'PATCH', path: '/api/nodes/' + nodeId, body: { boardId, tags } },
    { method: 'PATCH', path: '/nodes/' + nodeId, body: { boardId, tags } },
  ];
  for (const c of candidates) {
    const out = await request(c.method, c.path, c.body);
    if (out.res.status !== 404) return out;
  }
  throw new Error('Unable to find node tag update endpoint');
}

async function getNode(base: string, boardId: string, nodeId: string) {
  for (const path of [`${base}/${boardId}/nodes/${nodeId}`, '/api/nodes/' + nodeId, '/nodes/' + nodeId]) {
    const out = await request('GET', path);
    if (out.res.ok) return out.body;
  }
  throw new Error('Unable to read node');
}

async function tryDeleteBoard(base: string, boardId: string) { try { await request('DELETE', `${base}/${boardId}`); } catch {} }

describe('node_tags_validation_and_deduplication', () => {
  it('should validate tag count/name limits and deduplicate case-insensitively after trimming', async () => {
    const board = await createBoard(`tags-${Date.now()}`);
    try {
      const nodeId = await createNode(board.base, board.id);

      const invalidBlank = await updateNodeTags(board.base, board.id, nodeId, ['   ']);
      expect([400, 422]).toContain(invalidBlank.res.status);
      expect(JSON.stringify(invalidBlank.body).toLowerCase()).toMatch(/blank|empty|invalid|tag/);

      const invalidLong = await updateNodeTags(board.base, board.id, nodeId, ['x'.repeat(21)]);
      expect([400, 422]).toContain(invalidLong.res.status);
      expect(JSON.stringify(invalidLong.body).toLowerCase()).toMatch(/20|max|length|tag/);

      const dedup = await updateNodeTags(board.base, board.id, nodeId, ['  Alpha ', 'alpha', 'BETA', 'beta ']);
      expect([200, 201]).toContain(dedup.res.status);
      const node = await getNode(board.base, board.id, nodeId);
      const tags = node.tags || node.data?.tags || [];
