  try { json = text ? JSON.parse(text) : null; } catch { json = text; }
  return { res, body: json };
}

async function createBoard(name: string) {
  for (const c of [
    { path: '/api/boards', body: { title: name, template: 'mindmap' } },
    { path: '/boards', body: { title: name, template: 'mindmap' } },
  ]) {
    const { res, body } = await request('POST', c.path, c.body);
    if (res.ok && (body?.id || body?.data?.id)) {
      return { id: body.id || body.data.id, base: c.path.includes('/api/') ? '/api/boards' : '/boards' };
    }
  }
  throw new Error('Unable to create board');
}

async function createNode(base: string, boardId: string, title: string) {
  for (const path of [`${base}/${boardId}/nodes`, '/api/nodes', '/nodes']) {
    const payload = path.includes(`/${boardId}/`) ? { title } : { boardId, title };
    const { res, body } = await request('POST', path, payload);
    if (res.ok && (body?.id || body?.data?.id)) return body.id || body.data.id;
  }
  throw new Error('Unable to create node');
}

async function addTagsToNode(base: string, boardId: string, nodeId: string, tags: string[]) {
  // Try dedicated tags endpoint first
  const tagRes = await request('POST', `${base}/${boardId}/nodes/${nodeId}/tags`, { tags });
  if ([200, 201].includes(tagRes.res.status)) return;

  // Try adding tags one by one
  for (const tag of tags) {
    const singleRes = await request('POST', `${base}/${boardId}/nodes/${nodeId}/tags`, { tag });
    if ([200, 201].includes(singleRes.res.status)) continue;

    // Fallback: patch node with tags
    const patchRes = await request('PATCH', `${base}/${boardId}/nodes/${nodeId}`, { tags });
    if (patchRes.res.ok) return;
    break;
  }
}

async function filterNodes(base: string, boardId: string, tags: string[], q?: string) {
  const params = new URLSearchParams();
  params.set('boardId', boardId);
  params.set('tags', tags.join(','));
  if (q) params.set('q', q);
  const candidates = [
    `${base}/${boardId}/nodes/filter?tags=${encodeURIComponent(tags.join(','))}${q ? `&q=${encodeURIComponent(q)}` : ''}`,
    `${base}/${boardId}/nodes?tags=${encodeURIComponent(tags.join(','))}${q ? `&q=${encodeURIComponent(q)}` : ''}`,
    `/api/nodes?${params.toString()}`,
    `/nodes?${params.toString()}`,
  ];
  for (const path of candidates) {
    const out = await request('GET', path);
    if (out.res.ok) return out;
  }
  throw new Error('Unable to filter nodes');
}

async function tryDeleteBoard(base: string, boardId: string) {
  try {
    await request('DELETE', `${base}/${boardId}`, { confirm: true });
  } catch {}
  try {
    await request('DELETE', `/api/boards/${boardId}`, { confirm: true });
  } catch {}
}

function extractItems(filtered: any): any[] {
  if (Array.isArray(filtered)) return filtered;
  if (Array.isArray(filtered?.items)) return filtered.items;
  if (Array.isArray(filtered?.data)) return filtered.data;
  if (Array.isArray(filtered?.nodes)) return filtered.nodes;
  return [];
}

function extractCount(filtered: any, items: any[]): number {
  if (typeof filtered?.count === 'number') return filtered.count;
  if (typeof filtered?.total === 'number') return filtered.total;
  return items.length;
}

describe('filter_by_tags_matches_all_selected', () => {
  it('should filter by all selected tags (AND logic), return correct count, and apply search within filtered scope', async () => {
    const board = await createBoard(`filter-tags-${Date.now()}`);
    try {
      // Create nodes first, then add tags separately
      const nodeAlphaBeta = await createNode(board.base, board.id, 'Alpha Beta Match');
      await addTagsToNode(board.base, board.id, nodeAlphaBeta, ['alpha', 'beta']);

      const nodeAlphaOnly = await createNode(board.base, board.id, 'Alpha only');
      await addTagsToNode(board.base, board.id, nodeAlphaOnly, ['alpha']);

      const nodeBetaOnly = await createNode(board.base, board.id, 'Beta only');
      await addTagsToNode(board.base, board.id, nodeBetaOnly, ['beta']);

      const nodeGammaAlphaBeta = await createNode(board.base, board.id, 'Gamma Alpha Beta');
      await addTagsToNode(board.base, board.id, nodeGammaAlphaBeta, ['alpha', 'beta', 'gamma']);

      // Also create a node with no matching tags for extra coverage
      const nodeNoTags = await createNode(board.base, board.id, 'No Tags Node');

      // Filter with tags alpha AND beta -> should match only nodes having BOTH
      const filteredOut = await filterNodes(board.base, board.id, ['alpha', 'beta']);
      const filtered = filteredOut.body;
      const items = extractItems(filtered);
      expect(Array.isArray(items), `Expected filtered items array, got ${JSON.stringify(filtered)}`).toBe(true);

      const titles = items.map((n: any) => n.title || n.name || n.label);
      expect(titles).toEqual(expect.arrayContaining(['Alpha Beta Match', 'Gamma Alpha Beta']));
      // Nodes with only one of the two tags should NOT appear (AND logic)
      expect(titles).not.toContain('Alpha only');
      expect(titles).not.toContain('Beta only');
      expect(titles).not.toContain('No Tags Node');

      // Verify count
      const count = extractCount(filtered, items);
      expect(count).toBe(2);

      // Search within filtered scope: only 'Gamma Alpha Beta' matches 'Gamma' among filtered results
      const searchedOut = await filterNodes(board.base, board.id, ['alpha', 'beta'], 'Gamma');
      const searched = searchedOut.body;
      const searchedItems = extractItems(searched);
      expect(searchedItems.length).toBe(1);
      expect(searchedItems[0].title || searchedItems[0].name || searchedItems[0].label).toBe('Gamma Alpha Beta');

      // Verify that 'Alpha only' (which has 'alpha' but not 'beta') does NOT appear
      // when searching for 'Alpha' within the [alpha, beta] filter
      const searchAlphaOut = await filterNodes(board.base, board.id, ['alpha', 'beta'], 'Alpha');
      const searchAlphaItems = extractItems(searchAlphaOut.body);
      const searchAlphaTitles = searchAlphaItems.map((n: any) => n.title || n.name || n.label);
      // 'Alpha only' has only tag 'alpha', not 'beta', so it should be excluded by AND filter
      expect(searchAlphaTitles).not.toContain('Alpha only');
      // But 'Alpha Beta Match' has both tags and contains 'Alpha' in title
      expect(searchAlphaTitles).toContain('Alpha Beta Match');
    } finally {
      await tryDeleteBoard(board.base, board.id);
    }
  });

  it('should return empty results when no nodes match the filter tags', async () => {
    const board = await createBoard(`filter-empty-${Date.now()}`);
    try {
      const nodeId = await createNode(board.base, board.id, 'Some Node');
      await addTagsToNode(board.base, board.id, nodeId, ['alpha']);

      // Filter by a tag that no node has
      const filteredOut = await filterNodes(board.base, board.id, ['nonexistent_tag_xyz']);
      const filtered = filteredOut.body;
      const items = extractItems(filtered);
      expect(Array.isArray(items)).toBe(true);
      expect(items.length).toBe(0);

      // Count should be 0
      const count = extractCount(filtered, items);
      expect(count).toBe(0);

      // Verify the response does not include nodes that don't match
      // (the 'Some Node' with tag 'alpha' should NOT appear when filtering by 'nonexistent_tag_xyz')
      const hasSomeNode = items.some((n: any) => (n.title || n.name || n.label) === 'Some Node');
      expect(hasSomeNode).toBe(false);
    } finally {
      await tryDeleteBoard(board.base, board.id);
    }
  });

  it('should handle single tag filter correctly', async () => {
    const board = await createBoard(`filter-single-${Date.now()}`);
    try {
      const nodeA = await createNode(board.base, board.id, 'Has Alpha');
      await addTagsToNode(board.base, board.id, nodeA, ['alpha']);

      const nodeB = await createNode(board.base, board.id, 'Has Beta');
      await addTagsToNode(board.base, board.id, nodeB, ['beta']);

      // Filter with single tag 'alpha'
      const filteredOut = await filterNodes(board.base, board.id, ['alpha']);
      const items = extractItems(filteredOut.body);
      expect(items.length).toBeGreaterThanOrEqual(1);

      const titles = items.map((n: any) => n.title || n.name || n.label);
      expect(titles).toContain('Has Alpha');
      expect(titles).not.toContain('Has Beta');
    } finally {
      await tryDeleteBoard(board.base, board.id);
    }
  });
});

import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function request(path: string, options: any = {}) {
  const res = await fetch(`${BASE_URL}${path}`, {
    headers: { 'Content-Type': 'application/json', ...(options.headers || {}) },
    ...options,
  });
  const text = await res.text();
  let json: any;
  try {
    json = text ? JSON.parse(text) : null;
  } catch {
    json = text;
  }
  return { res, body: json, text };
}

async function tryPaths(method: string, paths: string[], payload?: any) {
  for (const path of paths) {
    const out = await request(path, {
      method,
      ...(payload !== undefined ? { body: JSON.stringify(payload) } : {}),
    });
    if (out.res.status !== 404 && out.res.status !== 405) return { ...out, usedPath: path };
  }
  throw new Error(`No working endpoint among: ${paths.join(', ')}`);
}

async function safeDeleteBoard(boardId: string) {
  if (!boardId) return;
  try { await fetch(`${BASE_URL}/api/boards/${boardId}`, { method: 'DELETE' }); } catch {}
  try { await fetch(`${BASE_URL}/boards/${boardId}`, { method: 'DELETE' }); } catch {}
}

async function createBoard(title: string, template: string) {
  const out = await tryPaths('POST', ['/api/boards', '/boards'], { title, template });
  expect([200, 201]).toContain(out.res.status);
  const id = out.body?.id || out.body?.data?.id || out.body?.boardId;
  expect(id).toBeTruthy();
  return { id, basePath: out.usedPath!.replace(/\/$/, '') };
}

async function getBoard(boardId: string) {
  return tryPaths('GET', [`/api/boards/${boardId}`, `/boards/${boardId}`]);
}

async function getNodes(boardId: string) {
  const out = await tryPaths('GET', [`/api/boards/${boardId}/nodes`, `/boards/${boardId}/nodes`]);
  const nodes = Array.isArray(out.body) ? out.body : (out.body?.nodes || out.body?.data?.nodes || out.body?.data || []);
  return nodes;
}

async function createNode(boardId: string, payload: any) {
  return tryPaths('POST', [`/api/boards/${boardId}/nodes`, `/boards/${boardId}/nodes`], payload);
}

async function importBoard(payload: any) {
  return tryPaths('POST', ['/api/boards/import', '/boards/import'], payload);
}

describe('round3_template_rules_and_legacy_migration', () => {
