      const root = nodes.find((n: any) => n.id === 'root-1');
      expect(root, 'expected protected root to remain after failed delete').toBeTruthy();
      expect(root.label || root.title || root.text).toBe('Renamed Root Node');

      const childNode = nodes.find((n: any) => n.id === childId || (n.label || n.title || n.text) === 'New Related Child');
      expect(childNode, 'expected newly added related node to exist').toBeTruthy();

      const linked = edges.some((e: any) => {
        const source = e.source || e.from || e.fromId || e.fromNodeId;
        const target = e.target || e.to || e.toId || e.toNodeId;
        return (source === 'root-1' && target === (childNode?.id || childId));
      });
