import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function request(method: string, path: string, body?: any) {
  const res = await fetch(`${BASE_URL}${path}`, {
    method,
    headers: { 'Content-Type': 'application/json' },
    body: body === undefined ? undefined : JSON.stringify(body),
  });
  const text = await res.text();
  let json: any = null;
  try { json = text ? JSON.parse(text) : null; } catch { json = text; }
  return { res, body: json };
}

async function createBoard(title: string, template = 'mindmap') {
  for (const c of [{ path: '/api/boards', body: { title, template } }, { path: '/boards', body: { title, template } }]) {
    const out = await request('POST', c.path, c.body);
    if (out.res.ok && (out.body?.id || out.body?.data?.id)) return { id: out.body.id || out.body.data.id, base: c.path.includes('/api/') ? '/api/boards' : '/boards', title };
  }
  throw new Error('Unable to create board');
}

async function createNode(base: string, boardId: string, payload: any) {
  for (const path of [`${base}/${boardId}/nodes`, '/api/nodes', '/nodes']) {
    const body = path.includes(`/${boardId}/`) ? payload : { boardId, ...payload };
    const out = await request('POST', path, body);
    if (out.res.ok && (out.body?.id || out.body?.data?.id)) return out.body.id || out.body.data.id;
  }
  throw new Error('Unable to create node');
}

async function updateNode(base: string, boardId: string, nodeId: string, payload: any) {
  for (const path of [`${base}/${boardId}/nodes/${nodeId}`, `/api/boards/${boardId}/nodes/${nodeId}`, `/api/nodes/${nodeId}`]) {
    const out = await request('PATCH', path, payload);
    if (out.res.ok || out.res.status === 204) return out;
  }
  for (const path of [`${base}/${boardId}/nodes/${nodeId}`, `/api/boards/${boardId}/nodes/${nodeId}`]) {
    const out = await request('PUT', path, payload);
    if (out.res.ok || out.res.status === 204) return out;
  }
  throw new Error('Unable to update node');
}

async function addComment(base: string, boardId: string, nodeId: string, content: string) {
  for (const c of [{ path: `${base}/${boardId}/nodes/${nodeId}/comments`, body: { content, text: content } }, { path: '/api/comments', body: { boardId, nodeId, content, text: content } }]) {
    const out = await request('POST', c.path, c.body);
    if (out.res.status !== 404) return out;
  }
  throw new Error('Unable to add comment');
}

async function addStep(base: string, boardId: string, nodeId: string) {
  for (const c of [{ path: `${base}/${boardId}/presentation/steps`, body: { nodeId } }, { path: '/api/presentation/steps', body: { boardId, nodeId } }]) {
    const out = await request('POST', c.path, c.body);
    if (out.res.status !== 404) return out;
  }
  throw new Error('Unable to add step');
}

async function copyBoard(base: string, boardId: string) {
  for (const c of [{ path: `${base}/${boardId}/copy`, body: {} }, { path: '/api/boards/' + boardId + '/copy', body: {} }]) {
    const out = await request('POST', c.path, c.body);
    if (out.res.status !== 404) return out;
  }
  throw new Error('Unable to copy board');
}

async function exportBoard(base: string, boardId: string) {
  for (const path of [`${base}/${boardId}/export`, '/api/boards/' + boardId + '/export']) {
    const out = await request('GET', path);
    if (out.res.ok) return out.body;
  }
  throw new Error('Unable to export board');
}

async function importBoard(payload: any) {
  for (const path of ['/api/boards/import', '/boards/import']) {
    const out = await request('POST', path, payload);
    if (out.res.status !== 404) return out;
  }
  throw new Error('Unable to import board');
}

async function getBoard(base: string, boardId: string) {
  for (const path of [`${base}/${boardId}`, '/api/boards/' + boardId]) {
    const out = await request('GET', path);
    if (out.res.ok) return out.body;
  }
  throw new Error('Unable to read board');
}

async function getNodes(base: string, boardId: string) {
  for (const path of [`${base}/${boardId}/nodes`, '/api/boards/' + boardId + '/nodes']) {
    const out = await request('GET', path);
    if (out.res.ok) {
      return Array.isArray(out.body) ? out.body : (out.body?.nodes || out.body?.items || out.body?.data || []);
    }
  }
  return [];
}

async function getComments(base: string, boardId: string, nodeId: string) {
  for (const path of [`${base}/${boardId}/nodes/${nodeId}/comments`, `/api/boards/${boardId}/nodes/${nodeId}/comments`]) {
    const out = await request('GET', path);
    if (out.res.ok) {
      return Array.isArray(out.body) ? out.body : (out.body?.comments || out.body?.items || out.body?.data || []);
    }
  }
  return [];
}

async function listBoards() {
  for (const path of ['/api/boards', '/boards']) {
    const out = await request('GET', path);
    if (out.res.ok) return Array.isArray(out.body) ? out.body : out.body.items || out.body.data || out.body.boards || [];
  }
  throw new Error('Unable to list boards');
}

async function tryDeleteBoard(base: string, boardId: string, confirm = true) {
  // Try with confirm parameter for second confirmation
  try { await request('DELETE', `${base}/${boardId}`, confirm ? { confirm: true } : undefined); } catch {}
  try { await request('DELETE', `/api/boards/${boardId}`, confirm ? { confirm: true } : undefined); } catch {}
}

describe('multi_board_isolation_after_copy_export_import', () => {
  it('should keep boards isolated after edit/copy/export/import, verify copy name differs, and keep summary consistent with detail', async () => {
    const boardATitle = `board-A-${Date.now()}`;
    const boardA = await createBoard(boardATitle, 'mindmap');
    const boardB = await createBoard(`board-B-${Date.now()}`, 'fishbone');
    let copyId: string | undefined;
    let importedId: string | undefined;
    try {
      // Create node in board A with tag
      const aNode = await createNode(boardA.base, boardA.id, { title: 'A node', text: 'A node', tags: ['red'] });
      // Add comment to board A node
      const commentRes = await addComment(boardA.base, boardA.id, aNode, 'A comment');
      expect([200, 201]).toContain(commentRes.res.status);
      // Add presentation step to board A
      const stepRes = await addStep(boardA.base, boardA.id, aNode);
      expect([200, 201]).toContain(stepRes.res.status);

      // Modify the node title before copying
      await updateNode(boardA.base, boardA.id, aNode, { title: 'A node edited', text: 'A node edited' });

      // Create node in board B
      await createNode(boardB.base, boardB.id, { title: 'B node', text: 'B node', tags: ['blue'] });

      // Copy board A
      const copy = await copyBoard(boardA.base, boardA.id);
      expect([200, 201]).toContain(copy.res.status);
      copyId = copy.body?.id || copy.body?.boardId || copy.body?.data?.id;
      expect(copyId).toBeTruthy();

      // Verify copy name differs from original
      const copyDetail = await getBoard(boardA.base, copyId as string);
      const copyName = copyDetail.title || copyDetail.name;
      expect(copyName, 'copy name should exist').toBeTruthy();
      expect(copyName, 'copy name should differ from original').not.toBe(boardATitle);

      // Verify copy has the edited content
      const copyText = JSON.stringify(copyDetail);
      expect(copyText).toContain('A node edited');

      // Find nodes in the copy
      const copyNodes = await getNodes(boardA.base, copyId as string);

      // Modify the copy to verify isolation from original
      if (copyNodes.length > 0) {
        const copyNodeId = copyNodes[0].id;
        try {
          await updateNode(boardA.base, copyId as string, copyNodeId, { title: 'Copy modified title', text: 'Copy modified title' });
        } catch { /* best effort */ }
      }

      // Verify original board A still has the original edited title, not the copy modification
      const boardAAfterCopyMod = await getBoard(boardA.base, boardA.id);
      const aAfterText = JSON.stringify(boardAAfterCopyMod);
      expect(aAfterText).toContain('A node edited');
      expect(aAfterText).not.toContain('Copy modified title');

      // Export board A
      const exported = await exportBoard(boardA.base, boardA.id);

      // Import as new board
      const imported = await importBoard(exported);
      expect([200, 201]).toContain(imported.res.status);
      importedId = imported.body?.id || imported.body?.boardId || imported.body?.data?.id;
      expect(importedId).toBeTruthy();

      // Verify imported board is also isolated: modify it and check original doesn't change
      const importedNodes = await getNodes(boardA.base, importedId as string);
      if (importedNodes.length > 0) {
        try {
          await updateNode(boardA.base, importedId as string, importedNodes[0].id, { title: 'Imported modified', text: 'Imported modified' });
        } catch { /* best effort */ }
      }

      // Re-check original board A is unaffected
      const boardAAfterImportMod = await getBoard(boardA.base, boardA.id);
      const aFinalText = JSON.stringify(boardAAfterImportMod);
      expect(aFinalText).toContain('A node edited');
      expect(aFinalText).not.toContain('Imported modified');

      // Delete the copy (with confirmation)
      await tryDeleteBoard(boardA.base, copyId as string, true);

      // Verify copy is gone
      const listAfterDelete = await listBoards();
      const copyInList = listAfterDelete.find((b: any) => b.id === copyId);
      expect(copyInList, 'deleted copy should not appear in list').toBeFalsy();

      // Set copyId to undefined since it's been cleaned up
      const deletedCopyId = copyId;
      copyId = undefined;

      // Get details of all remaining boards
      const boardADetail = await getBoard(boardA.base, boardA.id);
      const boardBDetail = await getBoard(boardB.base, boardB.id);
      const importedDetail = await getBoard(boardA.base, importedId as string).catch(async () => getBoard('/api/boards', importedId as string));
      const list = await listBoards();

      // Board A has its content
      const aDetailText = JSON.stringify(boardADetail);
      expect(aDetailText).toContain('A node edited');

      // Board B has its own content and not A's
      const bDetailText = JSON.stringify(boardBDetail);
      expect(bDetailText).toContain('B node');
      expect(bDetailText).not.toContain('A node');

      // --- Verify structured data: tags, comment counts, presentation steps ---

      // Check tags on board A nodes
      const aNodes = await getNodes(boardA.base, boardA.id);
      const aNodeWithTags = aNodes.find((n: any) => n.tags && n.tags.length > 0);
      expect(aNodeWithTags, 'board A should have a node with tags').toBeTruthy();
      expect(aNodeWithTags.tags).toContain('red');

      // Check comment count on board A node
      const aComments = await getComments(boardA.base, boardA.id, aNode);
      expect(aComments.length).toBeGreaterThanOrEqual(1);

      // Verify unresolved status tracking
      const unresolvedComments = aComments.filter((c: any) => c.resolved === false || c.status === 'unresolved');
      // At least the comment we added should be unresolved by default
      expect(unresolvedComments.length).toBeGreaterThanOrEqual(1);

      // --- Verify list summaries exist and match detail ---
      const summaryA = list.find((b: any) => b.id === boardA.id);
      const summaryB = list.find((b: any) => b.id === boardB.id);
      const summaryI = list.find((b: any) => b.id === importedId);
      expect(summaryA, 'Expected board A in board list').toBeTruthy();
      expect(summaryB, 'Expected board B in board list').toBeTruthy();
      expect(summaryI, 'Expected imported board in board list').toBeTruthy();

      // Template consistency between summary and detail
      const summaryATemplate = summaryA.template || summaryA.type;
      const detailATemplate = boardADetail.template || boardADetail.type;
      expect(summaryATemplate, 'board A summary should have template').toBeTruthy();
      expect(detailATemplate, 'board A detail should have template').toBeTruthy();
      expect(String(summaryATemplate).toLowerCase()).toBe(String(detailATemplate).toLowerCase());
      expect(String(summaryATemplate).toLowerCase()).toContain('mindmap');

      const summaryBTemplate = summaryB.template || summaryB.type;
      expect(String(summaryBTemplate || '').toLowerCase()).toContain('fishbone');

      // Comment count consistency between summary and detail for board A
      const summaryAComments = summaryA.commentCount ?? summaryA.commentsCount;
      if (summaryAComments !== undefined) {
        expect(summaryAComments).toBeGreaterThanOrEqual(1);
      }

      // Imported board summary template should match detail
      const summaryITemplate = summaryI.template || summaryI.type;
      const detailITemplate = (importedDetail as any).template || (importedDetail as any).type;
      if (summaryITemplate && detailITemplate) {
        expect(String(summaryITemplate).toLowerCase()).toBe(String(detailITemplate).toLowerCase());
      }

      // Verify imported board has original board's content
      const iDetailText = JSON.stringify(importedDetail);
      expect(iDetailText).toContain('A node edited');

    } finally {
      await tryDeleteBoard(boardA.base, boardA.id);
      await tryDeleteBoard(boardB.base, boardB.id);
      if (copyId) {
        await tryDeleteBoard('/api/boards', copyId);
        await tryDeleteBoard('/boards', copyId);
      }
      if (importedId) {
        await tryDeleteBoard('/api/boards', importedId);
        await tryDeleteBoard('/boards', importedId);
      }
    }
  });
});

import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function http(path, options = {}) {
  const res = await fetch(`${BASE_URL}${path}`, {
    headers: {
      'Content-Type': 'application/json',
      ...(options.headers || {}),
    },
    ...options,
  });
  const contentType = res.headers.get('content-type') || '';
  const body = contentType.includes('application/json') ? await res.json() : await res.text();
  return { res, body };
}

async function safeCleanup(boardId) {
  if (!boardId) return;
  try {
    await fetch(`${BASE_URL}/api/boards/${boardId}`, { method: 'DELETE' });
  } catch {}
}

describe('round17_comment_reply_and_resolution_rules', () => {
  it('should enforce comment reply depth (max 2 layers), resolution state, activity tracking, viewer restrictions, and cascade delete', async () => {
    let boardId;
    let nodeId;
    try {
      // --- Setup: create board and node ---
      const boardCreate = await http('/api/boards', {
        method: 'POST',
        body: JSON.stringify({
          title: `vitest-round17-${Date.now()}`,
          template: 'mindmap',
        }),
      });
      expect(boardCreate.res.status, `create board status should be 201, got ${boardCreate.res.status}`).toBe(201);
      expect(boardCreate.body).toBeTruthy();
      expect(boardCreate.body.id, `created board should contain id`).toBeTruthy();
      boardId = boardCreate.body.id;

      const nodeCreate = await http(`/api/boards/${boardId}/nodes`, {
        method: 'POST',
        body: JSON.stringify({
          text: 'comment target node',
          x: 120,
          y: 80,
        }),
      });
      expect(nodeCreate.res.status, `create node status should be 201, got ${nodeCreate.res.status}`).toBe(201);
      expect(nodeCreate.body.id, `created node should contain id`).toBeTruthy();
      nodeId = nodeCreate.body.id;

      // --- Create root comment (layer 1) ---
      const comment1 = await http(`/api/boards/${boardId}/nodes/${nodeId}/comments`, {
        method: 'POST',
        body: JSON.stringify({ text: 'root comment' }),
      });
      expect(comment1.res.status, `create root comment should return 201, got ${comment1.res.status}`).toBe(201);
      expect(comment1.body.text || comment1.body.content).toBe('root comment');
      expect(comment1.body.resolved, 'new root comment should default to unresolved').toBe(false);
      expect(comment1.body.id).toBeTruthy();
      const rootCommentId = comment1.body.id;

      // --- Create reply to root (layer 2) — should succeed ---
      const reply1 = await http(`/api/boards/${boardId}/comments/${rootCommentId}/replies`, {
        method: 'POST',
        body: JSON.stringify({ text: 'level 1 reply' }),
      });
      expect(reply1.res.status, `create level-2 reply should return 201, got ${reply1.res.status}`).toBe(201);
      expect(reply1.body.text || reply1.body.content).toBe('level 1 reply');
      expect(reply1.body.id).toBeTruthy();
      const reply1Id = reply1.body.id;

      // --- Attempt reply to reply (layer 3) — should be REJECTED (max 2 layers) ---
      const reply2 = await http(`/api/boards/${boardId}/comments/${reply1Id}/replies`, {
        method: 'POST',
        body: JSON.stringify({ text: 'level 2 reply should fail' }),
      });
      expect(
        [400, 403, 409, 422].includes(reply2.res.status),
        `creating a 3rd layer reply should be rejected (max 2 layers), got ${reply2.res.status} with body ${JSON.stringify(reply2.body)}`
      ).toBe(true);

      // --- Verify summary: totalCount vs unresolvedCount ---
      const summaryBefore = await http(`/api/boards/${boardId}/comments/summary`);
      expect(summaryBefore.res.status, `get comments summary should return 200, got ${summaryBefore.res.status}`).toBe(200);
      expect(typeof summaryBefore.body.totalCount, `summary should contain totalCount, got ${JSON.stringify(summaryBefore.body)}`).toBe('number');
      expect(typeof summaryBefore.body.unresolvedCount, `summary should contain unresolvedCount, got ${JSON.stringify(summaryBefore.body)}`).toBe('number');
      expect(summaryBefore.body.totalCount).toBeGreaterThanOrEqual(1);
      expect(summaryBefore.body.unresolvedCount).toBeGreaterThanOrEqual(1);

      // --- Resolve root comment ---
      const resolveRoot = await http(`/api/boards/${boardId}/comments/${rootCommentId}`, {
        method: 'PATCH',
        body: JSON.stringify({ resolved: true }),
      });
      expect(resolveRoot.res.status, `resolve comment should return 200, got ${resolveRoot.res.status}`).toBe(200);
      expect(resolveRoot.body.id).toBe(rootCommentId);
      expect(resolveRoot.body.resolved).toBe(true);

      // --- Verify unresolved count decreased after resolution ---
      const summaryAfterResolve = await http(`/api/boards/${boardId}/comments/summary`);
      expect(summaryAfterResolve.res.status).toBe(200);
      expect(summaryAfterResolve.body.unresolvedCount, 'unresolved count should decrease after resolving').toBeLessThan(summaryBefore.body.unresolvedCount);
      // totalCount should remain the same (resolving doesn't delete)
      expect(summaryAfterResolve.body.totalCount).toBe(summaryBefore.body.totalCount);

      // --- Verify resolved comment is collapsed by default ---
      const commentsList = await http(`/api/boards/${boardId}/nodes/${nodeId}/comments`);
      expect(commentsList.res.status, `list comments should return 200`).toBe(200);
      const commentItems = commentsList.body.comments || commentsList.body;
      expect(Array.isArray(commentItems)).toBe(true);
      const rootComment = commentItems.find((c) => c.id === rootCommentId);
      expect(rootComment, `root comment ${rootCommentId} should exist in list`).toBeTruthy();
      expect(rootComment.resolved).toBe(true);
      expect(
        rootComment.collapsed === true || rootComment.defaultCollapsed === true || rootComment.isCollapsed === true,
        `resolved comment should be folded by default, got ${JSON.stringify(rootComment)}`
      ).toBe(true);

      // --- Verify activities include comment creation, reply, and resolve ---
      const activities = await http(`/api/boards/${boardId}/activities`);
      expect(activities.res.status, `activities endpoint should return 200`).toBe(200);
      const activityItems = activities.body.items || activities.body.activities || activities.body;
      expect(Array.isArray(activityItems), `activities should be an array`).toBe(true);
      const activityStr = JSON.stringify(activityItems).toLowerCase();
      expect(
        activityStr.includes('comment') || activityStr.includes('评论'),
        `activities should contain comment-related entries`
      ).toBe(true);
      expect(
        activityStr.includes('reply') || activityStr.includes('回复') || activityStr.includes('replied'),
        `activities should contain reply-related entries`
      ).toBe(true);
      expect(
        activityStr.includes('resolve') || activityStr.includes('已解决') || activityStr.includes('resolved'),
        `activities should contain resolve status change entries`
      ).toBe(true);

      // --- Viewer cannot create new comment ---
      const viewerCreate = await http(`/api/boards/${boardId}/nodes/${nodeId}/comments`, {
        method: 'POST',
        headers: { 'x-user-role': 'viewer' },
        body: JSON.stringify({ text: 'viewer should not comment' }),
      });
      expect(
        [401, 403].includes(viewerCreate.res.status),
        `viewer should not be allowed to create comments, got ${viewerCreate.res.status}`
      ).toBe(true);

      // --- Viewer cannot reply to existing comment ---
      const viewerReply = await http(`/api/boards/${boardId}/comments/${rootCommentId}/replies`, {
        method: 'POST',
        headers: { 'x-user-role': 'viewer' },
        body: JSON.stringify({ text: 'viewer should not reply' }),
      });
      expect(
        [401, 403].includes(viewerReply.res.status),
        `viewer should not be allowed to reply to comments, got ${viewerReply.res.status}`
      ).toBe(true);

      // --- Delete node: cascade deletes all comments and replies ---
      const deleteNode = await http(`/api/boards/${boardId}/nodes/${nodeId}`, { method: 'DELETE' });
      expect([200, 204]).toContain(deleteNode.res.status);

      const commentsAfterDelete = await http(`/api/boards/${boardId}/nodes/${nodeId}/comments`);
      if (commentsAfterDelete.res.status === 200) {
        const remaining = commentsAfterDelete.body.comments || commentsAfterDelete.body;
        expect(Array.isArray(remaining)).toBe(true);
        expect(remaining.length, 'comments should be cascade deleted after node deletion').toBe(0);
      } else {
        expect([404, 410]).toContain(commentsAfterDelete.res.status);
      }

      // --- Verify summary after cascade delete ---
      const summaryAfterDelete = await http(`/api/boards/${boardId}/comments/summary`);
      if (summaryAfterDelete.res.status === 200) {
        expect(summaryAfterDelete.body.totalCount).toBe(0);
        expect(summaryAfterDelete.body.unresolvedCount).toBe(0);
      }
    } finally {
      await safeCleanup(boardId);
    }
  });
});

import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function http(path: string, options: any = {}) {
  const res = await fetch(`${BASE_URL}${path}`, {
    headers: {
      'Content-Type': 'application/json',
      ...(options.headers || {}),
    },
    ...options,
  });
  const contentType = res.headers.get('content-type') || '';
  let body: any;
  try {
    body = contentType.includes('application/json') ? await res.json() : await res.text();
  } catch {
    body = null;
  }
  return { res, body };
}

async function tryPaths(paths: string[], options: any = {}) {
  for (const path of paths) {
    const out = await http(path, options);
    if (out.res.status !== 404) return { ...out, path };
  }
  return null;
}

async function safeCleanup(boardId: string | undefined) {
  if (!boardId) return;
  try { await fetch(`${BASE_URL}/api/boards/${boardId}`, { method: 'DELETE' }); } catch {}
  try { await fetch(`${BASE_URL}/boards/${boardId}`, { method: 'DELETE' }); } catch {}
}

