// Determine how viewer role is conveyed
const VIEWER_ROLE_HEADERS = [
  { 'x-user-role': 'viewer' },
  { 'X-User-Role': 'viewer' },
  { 'x-role': 'viewer' },
];

async function tryAsViewer(path: string, method: string, body?: any) {
  for (const roleHeader of VIEWER_ROLE_HEADERS) {
    const out = await http(path, {
      method,
      headers: roleHeader,
      body: body ? JSON.stringify(body) : undefined,
    });
    if ([401, 403].includes(out.res.status)) {
      return { blocked: true, status: out.res.status, body: out.body };
    }
  }
  // Also try query param
  const separator = path.includes('?') ? '&' : '?';
  const out = await http(`${path}${separator}role=viewer`, {
    method,
    body: body ? JSON.stringify(body) : undefined,
  });
  if ([401, 403].includes(out.res.status)) {
    return { blocked: true, status: out.res.status, body: out.body };
  }
  return { blocked: false, status: out.res.status, body: out.body };
}

describe('round26_refactor_baseline_unchanged', () => {
  it('should keep baseline editing, viewer restrictions, legacy import, and presentation behavior unchanged after refactor', async () => {
    let boardId: string | undefined;
    let legacyBoardId: string | undefined;
    try {
      // Create a mindmap board
      const board = await createBoard(`vitest-round26-${Date.now()}`, 'mindmap');
      boardId = board.id;

      // --- Verify legacy edit routes are not directly accessible ---
      const legacyPaths = [
        `/boards/${boardId}/edit`,
        `/api/boards/${boardId}/edit`,
      ];
      for (const legacyPath of legacyPaths) {
        const legacyRes = await http(legacyPath, { method: 'GET' });
        // Should be redirected, forbidden, or not found
        expect(
          [301, 302, 307, 308, 403, 404].includes(legacyRes.res.status),
          `legacy edit route ${legacyPath} should not remain directly editable, got ${legacyRes.res.status}`
        ).toBe(true);
      }

      // Create nodes for testing
      const node = await createNode(boardId, { title: 'editable node' });
      expect(node.id, 'should create a node successfully').toBeTruthy();
      const nodeId = node.id!;

      // --- Viewer cannot create nodes ---
      for (const path of [`/api/boards/${boardId}/nodes`, `/boards/${boardId}/nodes`]) {
        const viewerCreate = await tryAsViewer(path, 'POST', { title: 'viewer node' });
        if (viewerCreate.blocked) {
          expect([401, 403]).toContain(viewerCreate.status);
          break;
        }
      }

      // --- Viewer cannot modify a node (single node PATCH/PUT) ---
      let viewerModifyBlocked = false;
      for (const path of [`/api/boards/${boardId}/nodes/${nodeId}`, `/boards/${boardId}/nodes/${nodeId}`]) {
        const viewerModify = await tryAsViewer(path, 'PATCH', { title: 'viewer modified' });
        if (viewerModify.blocked) {
          viewerModifyBlocked = true;
          break;
        }
        const viewerModifyPut = await tryAsViewer(path, 'PUT', { title: 'viewer modified' });
        if (viewerModifyPut.blocked) {
          viewerModifyBlocked = true;
          break;
        }
      }
      expect(viewerModifyBlocked, 'viewer should not be able to modify nodes').toBe(true);

      // --- Viewer cannot create comments ---
      let viewerCommentBlocked = false;
      for (const path of [`/api/boards/${boardId}/nodes/${nodeId}/comments`, `/boards/${boardId}/nodes/${nodeId}/comments`]) {
        const viewerComment = await tryAsViewer(path, 'POST', { content: 'viewer cannot comment' });
        if (viewerComment.blocked) {
          viewerCommentBlocked = true;
          break;
        }
      }
      expect(viewerCommentBlocked, 'viewer should not be able to create comments').toBe(true);

      // --- Viewer cannot perform batch edit ---
      let viewerBatchBlocked = false;
      for (const path of [`/api/boards/${boardId}/nodes/batch`, `/boards/${boardId}/nodes/batch`]) {
        const viewerBatch = await tryAsViewer(path, 'PATCH', { ids: [nodeId], changes: { title: 'mutated' } });
        if (viewerBatch.blocked) {
          viewerBatchBlocked = true;
          break;
        }
      }
      expect(viewerBatchBlocked, 'viewer should not be able to perform batch edit').toBe(true);

      // --- Presentation boundary behavior with multiple steps ---
      const node2 = await createNode(boardId, { title: 'step 2' });
      expect(node2.id).toBeTruthy();
      const node3 = await createNode(boardId, { title: 'step 3' });
      expect(node3.id).toBeTruthy();

      // Add 3 presentation steps
      await addPresentationStep(boardId, nodeId);
      await addPresentationStep(boardId, node2.id!);
      await addPresentationStep(boardId, node3.id!);

      // Start presentation
      const play = await startPresentation(boardId);
      expect(
        [200, 201].includes(play.res.status),
        `non-empty playlist should be playable, got ${play.res.status}`
      ).toBe(true);

      // Navigate next twice to reach step 3 (last step)
      const next1 = await presentationNext(boardId);
      expect([200, 204].includes(next1.res.status), `next step 1->2 should succeed, got ${next1.res.status}`).toBe(true);

      const next2 = await presentationNext(boardId);
      expect([200, 204].includes(next2.res.status), `next step 2->3 should succeed, got ${next2.res.status}`).toBe(true);

      // One more next should NOT go beyond the last step - must have clear end indication
      const next3 = await presentationNext(boardId);
      // Either returns an error status OR 200 with an explicit end flag
      if ([200, 204].includes(next3.res.status)) {
        // If 200, body MUST indicate we're at the end
        expect(next3.body, 'response body should exist when returning 200 at end').toBeTruthy();
        if (typeof next3.body === 'object' && next3.body !== null) {
          const atEnd = next3.body.atEnd || next3.body.isEnd || next3.body.isLast || next3.body.ended;
          const stepIndex = next3.body.step ?? next3.body.currentStep ?? next3.body.index;
          // At least one of these signals should indicate end
          const hasEndSignal = atEnd === true || (typeof stepIndex === 'number' && stepIndex >= 2);
          expect(
            hasEndSignal,
            `at end of presentation, response must indicate end state, got body: ${JSON.stringify(next3.body)}`
          ).toBe(true);
        }
      } else {
        // Error status is also acceptable as end-of-presentation feedback
        expect(
          [409, 422].includes(next3.res.status),
          `beyond last step should return end indicator, got ${next3.res.status}`
        ).toBe(true);
      }

      // --- Legacy import: old file should fall into default template and remain editable ---
      const legacyPayload = {
        title: 'legacy-after-refactor',
        nodes: [{ id: 'ln1', title: 'Legacy node' }],
        edges: [],
      };
      let importLegacy;
      try {
        importLegacy = await http('/api/boards/import', {
          method: 'POST',
          body: JSON.stringify(legacyPayload),
        });
        if (importLegacy.res.status === 404) throw new Error('try next');
      } catch {
        importLegacy = await http('/boards/import', {
          method: 'POST',
          body: JSON.stringify(legacyPayload),
        });
      }
      expect([200, 201].includes(importLegacy.res.status), `legacy import should succeed, got ${importLegacy.res.status}`).toBe(true);
      legacyBoardId = importLegacy.body?.id || importLegacy.body?.data?.id;
      expect(legacyBoardId, 'imported board should have an id').toBeTruthy();

      // Verify imported board has a default template assigned
      let importedBoard: any;
      for (const path of [`/api/boards/${legacyBoardId}`, `/boards/${legacyBoardId}`]) {
        const out = await http(path);
        if (out.res.ok) { importedBoard = out.body?.data || out.body; break; }
      }
      expect(importedBoard, 'should be able to read imported board').toBeTruthy();
      const assignedTemplate = importedBoard.template || importedBoard.type;
      expect(typeof assignedTemplate, 'imported board should have a template/type assigned').toBe('string');
      expect(assignedTemplate.trim().length, 'assigned template should not be blank').toBeGreaterThan(0);

      // The default template should be a known template type
      const knownTemplates = ['mindmap', 'flowchart', 'fishbone', 'default'];
      expect(
        knownTemplates.includes(assignedTemplate.toLowerCase()),
        `imported legacy board should fall into a default template (one of ${knownTemplates.join(', ')}), got '${assignedTemplate}'`
      ).toBe(true);

      // Verify we can still add nodes (board is editable)
      const editableNode = await createNode(legacyBoardId as string, { title: 'Still editable' });
      expect(editableNode.id, 'should be able to create node on imported legacy board').toBeTruthy();

    } finally {
      await safeCleanup(boardId);
      await safeCleanup(legacyBoardId);
    }
  });
});

import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function request(method: string, path: string, body?: any) {
  const res = await fetch(`${BASE_URL}${path}`, {
    method,
    headers: { 'Content-Type': 'application/json' },
    body: body === undefined ? undefined : JSON.stringify(body),
  });
  const text = await res.text();
  let json: any = null;
  try { json = text ? JSON.parse(text) : null; } catch { json = text; }
  return { res, body: json };
}

async function createBoard(name: string) {
  for (const c of [
    { path: '/api/boards', body: { title: name } },
    { path: '/boards', body: { title: name } },
    { path: '/api/boards', body: { name } },
    { path: '/boards', body: { name } },
  ]) {
    const { res, body } = await request('POST', c.path, c.body);
    if (res.ok && body && (body.id || body.boardId || body.data?.id)) {
      return { id: body.id || body.boardId || body.data.id, base: c.path.includes('/api/') ? '/api/boards' : '/boards' };
    }
  }
  throw new Error('Unable to create board');
}

async function createNode(base: string, boardId: string) {
  for (const path of [`${base}/${boardId}/nodes`, '/api/nodes', '/nodes']) {
    const body = path.includes(`/${boardId}/`) ? { title: 'node-for-comment' } : { boardId, title: 'node-for-comment' };
    const { res, body: json } = await request('POST', path, body);
    if (res.ok && json && (json.id || json.nodeId || json.data?.id)) return json.id || json.nodeId || json.data.id;
  }
  throw new Error('Unable to create node');
}

async function addComment(base: string, boardId: string, nodeId: string, content: string) {
  const candidates = [
    { path: `${base}/${boardId}/nodes/${nodeId}/comments`, body: { content } },
    { path: '/api/comments', body: { boardId, nodeId, content } },
    { path: '/comments', body: { boardId, nodeId, content } },
  ];
  for (const c of candidates) {
    const out = await request('POST', c.path, c.body);
    if (out.res.status !== 404) return out;
  }
  throw new Error('Unable to find comment create endpoint');
}

