}

describe('comment_input_validation_limits', () => {
  it('should reject blank-after-trim comments, accept <=200 chars, and reject >200 chars', async () => {
    const board = await createBoard(`comment-limits-${Date.now()}`);
    try {
      const nodeId = await createNode(board.base, board.id);

      const blank = await addComment(board.base, board.id, nodeId, '   \n  \t  ');
      expect([400, 422]).toContain(blank.res.status);
      expect(blank.body).toBeTruthy();
      expect(JSON.stringify(blank.body).toLowerCase()).toMatch(/empty|blank|required|invalid|content/);

      const validContent = 'a'.repeat(200);
      const valid = await addComment(board.base, board.id, nodeId, validContent);
      expect([200, 201]).toContain(valid.res.status);
      expect(valid.body).toBeTruthy();
      const returnedContent = valid.body.content || valid.body.data?.content || valid.body.comment?.content;
      expect(returnedContent, `Expected created comment content to equal 200-char input, got ${JSON.stringify(valid.body)}`).toBe(validContent);

      const tooLongContent = 'b'.repeat(201);
      const tooLong = await addComment(board.base, board.id, nodeId, tooLongContent);
      expect([400, 413, 422]).toContain(tooLong.res.status);
      expect(tooLong.body).toBeTruthy();
      expect(JSON.stringify(tooLong.body).toLowerCase()).toMatch(/200|max|length|too long|invalid/);
    } finally {
      await tryDeleteBoard(board.base, board.id);
