import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function request(method: string, path: string, body?: any) {
  const res = await fetch(`${BASE_URL}${path}`, {
    method,
    headers: { 'Content-Type': 'application/json' },
    body: body === undefined ? undefined : JSON.stringify(body),
  });
  const text = await res.text();
  let json: any = null;
  try {
    json = text ? JSON.parse(text) : null;
  } catch {
    json = text;
  }
  return { res, body: json };
}

async function createBoard(name: string, template: string = 'flowchart') {
  const candidates = [
    { path: '/api/boards', body: { title: name, template } },
    { path: '/boards', body: { title: name, template } },
    { path: '/api/boards', body: { name, template } },
    { path: '/boards', body: { name, template } },
  ];
  for (const c of candidates) {
    const { res, body } = await request('POST', c.path, c.body);
    if (res.ok && body && (body.id || body.boardId || body.data?.id)) {
      const id = body.id || body.boardId || body.data?.id;
      const pathBase = c.path.includes('/api/') ? '/api/boards' : '/boards';
      return { id, pathBase };
    }
  }
  throw new Error('Unable to create board');
}

async function createNode(boardBase: string, boardId: string, payload: Record<string, any>) {
  const candidates = [
    `${boardBase}/${boardId}/nodes`,
    `/api/boards/${boardId}/nodes`,
    `/boards/${boardId}/nodes`,
  ];
  for (const path of candidates) {
    const { res, body: json } = await request('POST', path, payload);
    if (res.ok && json && (json.id || json.nodeId || json.data?.id)) {
      return json.id || json.nodeId || json.data?.id;
    }
  }
  throw new Error('Unable to create node');
}

async function listNodes(boardBase: string, boardId: string) {
  const candidates = [
    `${boardBase}/${boardId}/nodes`,
    `/api/boards/${boardId}/nodes`,
    `/boards/${boardId}/nodes`,
  ];
  for (const path of candidates) {
    const { res, body } = await request('GET', path);
    if (res.ok) {
      if (Array.isArray(body)) return body;
      if (Array.isArray(body?.items)) return body.items;
      if (Array.isArray(body?.data)) return body.data;
      if (Array.isArray(body?.nodes)) return body.nodes;
    }
  }
  throw new Error('Unable to list nodes');
}

async function tryDeleteBoard(boardBase: string, boardId: string) {
  try {
    await request('DELETE', `${boardBase}/${boardId}`);
  } catch {}
}

async function tryBulkDelete(boardBase: string, boardId: string, nodeIds: string[]) {
  const candidates = [
    { path: `${boardBase}/${boardId}/nodes/bulk-delete`, body: { nodeIds } },
    { path: `${boardBase}/${boardId}/nodes/bulk_delete`, body: { nodeIds } },
    { path: `${boardBase}/${boardId}/nodes/batch-delete`, body: { nodeIds } },
    { path: `${boardBase}/${boardId}/nodes/batch`, body: { action: 'delete', nodeIds } },
    { path: `${boardBase}/${boardId}/bulk/delete`, body: { nodeIds } },
    { path: `/api/boards/${boardId}/nodes/bulk-delete`, body: { nodeIds } },
    { path: `/api/boards/${boardId}/nodes/batch-delete`, body: { nodeIds } },
    { path: `/api/boards/${boardId}/nodes/batch`, body: { action: 'delete', nodeIds } },
  ];
  for (const c of candidates) {
    // Try POST
    const { res, body } = await request('POST', c.path, c.body);
    if (res.status !== 404) {
      return { status: res.status, body };
    }
    // Also try DELETE method
    const { res: res2, body: body2 } = await request('DELETE', c.path, c.body);
    if (res2.status !== 404) {
      return { status: res2.status, body: body2 };
    }
  }
  return null;
}

describe('bulk_delete_multi_select_atomic_result', () => {
  it('should return an explicit non-silent result when bulk deleting mixed normal/protected nodes', async () => {
    const board = await createBoard(`bulk-del-${Date.now()}`, 'flowchart');
    try {
      // Create a start node (protected by flow rules: max 1 start)
      const startNodeId = await createNode(board.pathBase, board.id, { title: 'Start', type: 'start' });
      // Create an end node (protected: flowchart must have at least 1 end)
      const endNodeId = await createNode(board.pathBase, board.id, { title: 'End', type: 'end' });
      // Create normal step nodes (not protected)
      const normalNodeId1 = await createNode(board.pathBase, board.id, { title: 'Normal Step 1', type: 'step' });
      const normalNodeId2 = await createNode(board.pathBase, board.id, { title: 'Normal Step 2', type: 'step' });

      // Verify initial node count
      const nodesBefore = await listNodes(board.pathBase, board.id);
      const initialCount = nodesBefore.length;
      expect(initialCount).toBeGreaterThanOrEqual(4);

      // Attempt bulk delete mixing protected (start, end) and normal nodes
      const result = await tryBulkDelete(board.pathBase, board.id, [normalNodeId1, startNodeId, endNodeId]);

      expect(result, 'Expected a bulk-delete endpoint to exist').not.toBeNull();

      // The response should be explicit
      expect([200, 207, 400, 409, 422]).toContain(result!.status);
      expect(result!.body).toBeTruthy();
      expect(typeof result!.body).toBe('object');

      // Check for structured result fields that explain what happened
      const responseBody = result!.body;
      const hasExplicitResult =
        responseBody.failed !== undefined ||
        responseBody.errors !== undefined ||
        responseBody.results !== undefined ||
        responseBody.protected !== undefined ||
        responseBody.skipped !== undefined ||
        responseBody.deleted !== undefined ||
        responseBody.message !== undefined ||
        responseBody.error !== undefined;
      expect(
        hasExplicitResult,
        `Bulk-delete response should have explicit result fields explaining which nodes failed/succeeded, got: ${JSON.stringify(responseBody)}`,
      ).toBe(true);

      // Check if response specifically mentions protected nodes or reasons
      const bodyStr = JSON.stringify(responseBody).toLowerCase();
      const mentionsProtection =
        bodyStr.includes('protect') || bodyStr.includes('start') || bodyStr.includes('end') ||
        bodyStr.includes('cannot') || bodyStr.includes('不能') || bodyStr.includes('受保护') ||
        bodyStr.includes('skip') || bodyStr.includes('fail') || bodyStr.includes('error') ||
        bodyStr.includes('reject') || bodyStr.includes('denied');
      expect(
        mentionsProtection,
        `Response should explain why some nodes could not be deleted: ${JSON.stringify(responseBody)}`
      ).toBe(true);

      // Verify no silent partial deletion: protected nodes must still exist
      const nodesAfter = await listNodes(board.pathBase, board.id);
      const remainingIds = new Set(nodesAfter.map((n: any) => n.id));

      // Protected nodes (start, end) should NOT have been silently deleted
      const startSurvived = remainingIds.has(startNodeId);
      const endSurvived = remainingIds.has(endNodeId);

      expect(
        startSurvived && endSurvived,
        `Protected nodes (start/end) should not be silently deleted. Start survived: ${startSurvived}, End survived: ${endSurvived}`,
      ).toBe(true);

      // Check what happened to the normal node:
      // If the API allows partial success (207), the normal node may have been deleted
      // If the API rejects entirely (400/409/422), all nodes remain
      if ([400, 409, 422].includes(result!.status)) {
        // Entire operation rejected: all nodes should remain
        expect(remainingIds.has(normalNodeId1), 'normal node should remain if entire operation was rejected').toBe(true);
        expect(nodesAfter.length, 'node count should be unchanged after full rejection').toBe(initialCount);
      } else if (result!.status === 200 || result!.status === 207) {
        // Partial success: normal node may be deleted but protected ones survive
        // Node count should reflect the partial deletion
        expect(nodesAfter.length, 'node count should be updated after partial deletion').toBeLessThanOrEqual(initialCount);
      }
    } finally {
      await tryDeleteBoard(board.pathBase, board.id);
    }
  });

  it('should reject bulk selection of more than 50 nodes', async () => {
    const board = await createBoard(`bulk-limit-${Date.now()}`, 'mindmap');
    try {
      // Create 51 real nodes to exceed the 50-node selection limit
      const nodeIds: string[] = [];
      for (let i = 0; i < 51; i++) {
        const id = await createNode(board.pathBase, board.id, { title: `Bulk Node ${i}` });
        nodeIds.push(id);
      }

      expect(nodeIds.length, 'should have created 51 nodes').toBe(51);

      // Attempt bulk delete with all 51 node IDs
      const result = await tryBulkDelete(board.pathBase, board.id, nodeIds);

      expect(result, 'Expected a bulk-delete endpoint to exist').not.toBeNull();

      // Should reject with a client error status
      expect(
        [400, 409, 422].includes(result!.status),
        `Bulk delete of 51 nodes should be rejected due to 50-node limit, got status ${result!.status}`,
      ).toBe(true);

      // Response should mention the limit
      const bodyStr = JSON.stringify(result!.body).toLowerCase();
      expect(
        bodyStr.includes('50') || bodyStr.includes('limit') || bodyStr.includes('max') ||
        bodyStr.includes('exceed') || bodyStr.includes('too many') || bodyStr.includes('超') || bodyStr.includes('上限'),
        `Rejection response should mention the 50-node limit, got: ${JSON.stringify(result!.body)}`
      ).toBe(true);

      // All nodes should still exist (operation was rejected entirely)
      const nodesAfter = await listNodes(board.pathBase, board.id);
      expect(nodesAfter.length, 'all nodes should remain since operation was rejected').toBeGreaterThanOrEqual(51);

      // Verify at least the first and last nodes are still there
      const remainingIds = new Set(nodesAfter.map((n: any) => n.id));
      expect(remainingIds.has(nodeIds[0]), 'first node should still exist').toBe(true);
      expect(remainingIds.has(nodeIds[50]), 'last node should still exist').toBe(true);
    } finally {
      await tryDeleteBoard(board.pathBase, board.id);
    }
  });
});

import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function request(path: string, options: any = {}) {
  const res = await fetch(`${BASE_URL}${path}`, {
    headers: { 'Content-Type': 'application/json', ...(options.headers || {}) },
    ...options,
  });
  const text = await res.text();
  let json: any;
  try { json = text ? JSON.parse(text) : null; } catch { json = text; }
  return { res, body: json, text };
}

function extractId(body: any): string {
  return body?.id || body?.boardId || body?.data?.id || '';
}

function extractNodeId(body: any): string {
  return body?.id || body?.nodeId || body?.data?.id || '';
}

async function safeDeleteBoard(boardId: string | undefined) {
  if (!boardId) return;
  try { await fetch(`${BASE_URL}/api/boards/${boardId}`, { method: 'DELETE' }); } catch {}
  try { await fetch(`${BASE_URL}/boards/${boardId}`, { method: 'DELETE' }); } catch {}
}

async function tryRequest(paths: string[], options: any = {}): Promise<{ res: Response; body: any; path: string } | null> {
  for (const path of paths) {
    const res = await fetch(`${BASE_URL}${path}`, {
      headers: { 'Content-Type': 'application/json', ...(options.headers || {}) },
      ...options,
    });
    const text = await res.text();
    let json: any;
    try { json = text ? JSON.parse(text) : null; } catch { json = text; }
    if (res.status !== 404) {
      return { res, body: json, path };
    }
  }
  return null;
}

async function requireTryRequest(paths: string[], options: any = {}, label: string = 'endpoint'): Promise<{ res: Response; body: any; path: string }> {
  const result = await tryRequest(paths, options);
  expect(result, `Expected ${label} to exist (tried: ${paths.join(', ')})`).toBeTruthy();
  return result!;
}

