import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function request(method: string, path: string, body?: any) {
  const res = await fetch(`${BASE_URL}${path}`, {
    method,
    headers: { 'Content-Type': 'application/json' },
    body: body === undefined ? undefined : JSON.stringify(body),
  });
  const text = await res.text();
  let json: any = null;
  try { json = text ? JSON.parse(text) : null; } catch { json = text; }
  return { res, body: json };
}

async function createBoard(name: string) {
  for (const c of [{ path: '/api/boards', body: { title: name } }, { path: '/boards', body: { title: name } }]) {
    const { res, body } = await request('POST', c.path, c.body);
    if (res.ok && (body?.id || body?.data?.id)) return { id: body.id || body.data.id, base: c.path.includes('/api/') ? '/api/boards' : '/boards' };
  }
  throw new Error('Unable to create board');
}

async function createNode(base: string, boardId: string, title: string) {
  for (const path of [`${base}/${boardId}/nodes`, '/api/nodes', '/nodes']) {
    const payload = path.includes(`/${boardId}/`) ? { title } : { boardId, title };
    const { res, body } = await request('POST', path, payload);
    if (res.ok && (body?.id || body?.data?.id)) return body.id || body.data.id;
  }
  throw new Error('Unable to create node');
}

async function addStep(base: string, boardId: string, nodeId: string) {
  const candidates = [
    { path: `${base}/${boardId}/presentation/steps`, body: { nodeId } },
    { path: `${base}/${boardId}/presentation`, body: { nodeId } },
    { path: '/api/presentation/steps', body: { boardId, nodeId } },
  ];
  for (const c of candidates) {
    const out = await request('POST', c.path, c.body);
    if (out.res.status !== 404) return out;
  }
  throw new Error('Unable to add presentation step');
}

async function getSteps(base: string, boardId: string) {
  for (const path of [`${base}/${boardId}/presentation/steps`, `${base}/${boardId}/presentation`, `/api/presentation/steps?boardId=${boardId}`]) {
    const out = await request('GET', path);
    if (out.res.ok) return out.body;
  }
  throw new Error('Unable to get presentation steps');
}

async function deleteNode(base: string, boardId: string, nodeId: string) {
  for (const path of [`${base}/${boardId}/nodes/${nodeId}`, `/api/nodes/${nodeId}`, `/nodes/${nodeId}`]) {
    const out = await request('DELETE', path);
    if (out.res.status !== 404) return out;
  }
  throw new Error('Unable to delete node');
}

async function startPresentation(base: string, boardId: string) {
  for (const path of [`${base}/${boardId}/presentation/start`, '/api/presentation/start']) {
    const body = path === '/api/presentation/start' ? { boardId } : undefined;
    const out = await request('POST', path, body);
    if (out.res.status !== 404) return out;
  }
  throw new Error('Unable to start presentation');
}

async function tryDeleteBoard(base: string, boardId: string) { try { await request('DELETE', `${base}/${boardId}`); } catch {} }

describe('presentation_steps_deduplicate_and_cascade_remove', () => {
  it('should prevent duplicate steps, remove step when node is deleted, and reject starting presentation when step list is empty', async () => {
    const board = await createBoard(`presentation-${Date.now()}`);
    try {
      const nodeId = await createNode(board.base, board.id, 'slide-node');

      const first = await addStep(board.base, board.id, nodeId);
      expect([200, 201]).toContain(first.res.status);

      const second = await addStep(board.base, board.id, nodeId);
      expect([200, 201, 400, 409, 422]).toContain(second.res.status);
      const steps1 = await getSteps(board.base, board.id);
      const list1 = Array.isArray(steps1) ? steps1 : steps1.items || steps1.data || steps1.steps || [];
      const occurrences = list1.filter((s: any) => (s.nodeId || s.node?.id) === nodeId).length;
      expect(occurrences, `Expected duplicate presentation step to be prevented, got ${JSON.stringify(list1)}`).toBe(1);

      const del = await deleteNode(board.base, board.id, nodeId);
      expect([200, 204]).toContain(del.res.status);

      const steps2 = await getSteps(board.base, board.id);
      const list2 = Array.isArray(steps2) ? steps2 : steps2.items || steps2.data || steps2.steps || [];
      const stillExists = list2.some((s: any) => (s.nodeId || s.node?.id) === nodeId);
      expect(stillExists, `Expected presentation step to be removed after node deletion, got ${JSON.stringify(list2)}`).toBe(false);

      const started = await startPresentation(board.base, board.id);
      expect([400, 409, 422]).toContain(started.res.status);
      expect(JSON.stringify(started.body).toLowerCase()).toMatch(/empty|step|presentation|cannot|start/);
    } finally {
      await tryDeleteBoard(board.base, board.id);
    }
  });
});

import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function request(path: string, options: any = {}) {
  const res = await fetch(`${BASE_URL}${path}`, {
    headers: { 'Content-Type': 'application/json', ...(options.headers || {}) },
    ...options,
  });
  const text = await res.text();
  let json: any;
  try { json = text ? JSON.parse(text) : null; } catch { json = text; }
  return { res, body: json, text };
}

async function tryPaths(method: string, paths: string[], payload?: any) {
  for (const path of paths) {
    const out = await request(path, {
      method,
      ...(payload !== undefined ? { body: JSON.stringify(payload) } : {}),
    });
    if (out.res.status !== 404 && out.res.status !== 405) return { ...out, usedPath: path };
  }
  throw new Error(`No working endpoint among: ${paths.join(', ')}`);
}

async function safeDeleteBoard(boardId: string) {
  if (!boardId) return;
  try { await fetch(`${BASE_URL}/api/boards/${boardId}`, { method: 'DELETE' }); } catch {}
  try { await fetch(`${BASE_URL}/boards/${boardId}`, { method: 'DELETE' }); } catch {}
}

async function createBoard(title: string, template: string) {
  const out = await tryPaths('POST', ['/api/boards', '/boards'], { title, template });
  expect([200, 201]).toContain(out.res.status);
  const id = out.body?.id || out.body?.data?.id || out.body?.boardId;
  expect(id).toBeTruthy();
  return { id, basePath: out.usedPath! };
}

async function createNode(boardId: string, payload: any) {
  const out = await tryPaths('POST', [`/api/boards/${boardId}/nodes`, `/boards/${boardId}/nodes`],
    { boardId, ...payload });
  expect([200, 201]).toContain(out.res.status);
  const id = out.body?.id || out.body?.data?.id;
  expect(id).toBeTruthy();
  return id;
}

async function createConnection(boardId: string, fromId: string, toId: string) {
  return tryPaths('POST', [`/api/boards/${boardId}/connections`, `/boards/${boardId}/connections`],
    { boardId, fromId, toId, fromNodeId: fromId, toNodeId: toId });
}

async function getBoard(boardId: string) {
  return tryPaths('GET', [`/api/boards/${boardId}`, `/boards/${boardId}`]);
}

async function getNodes(boardId: string) {
  const out = await tryPaths('GET', [`/api/boards/${boardId}/nodes`, `/boards/${boardId}/nodes`]);
  return Array.isArray(out.body) ? out.body : (out.body?.nodes || out.body?.data?.nodes || out.body?.data || []);
}

async function exportBoard(boardId: string) {
  const out = await tryPaths('GET', [`/api/boards/${boardId}/export`, `/boards/${boardId}/export`]);
  expect(out.res.ok).toBe(true);
  return out.body;
}

async function importBoard(payload: any) {
  return tryPaths('POST', ['/api/boards/import', '/boards/import'], payload);
}

async function updateView(boardId: string, view: any) {
  for (const path of [`/api/boards/${boardId}`, `/boards/${boardId}`]) {
    const out = await request(path, {
      method: 'PATCH',
      body: JSON.stringify({ viewState: view, view }),
    });
    if (out.res.status !== 404 && out.res.status !== 405) return out;
  }
  return null;
}

describe('round8_import_export_and_invalid_file_protection', () => {
