      // Import
      const imported = await importBoard(exported);
      expect([200, 201]).toContain(imported.res.status);
      importedBoardId = imported.body?.id || imported.body?.boardId || imported.body?.data?.id;
      expect(importedBoardId).toBeTruthy();

      // Verify imported board
      const importedBoard = await getBoard(importedBoardId!);
      expect(importedBoard.res.status).toBe(200);
      const ib = importedBoard.body;

      // Template
      const template = ib.template || ib.type || ib.mode;
      expect(template).toBe('fishbone');

      // Nodes
      const importedNodes = await getNodes(importedBoardId!).catch(() =>
        ib.nodes || ib.data?.nodes || []
      );
      expect(importedNodes.length).toBeGreaterThanOrEqual(2);
      const titles = importedNodes.map((n: any) => n.title || n.label || n.text);
      expect(titles).toContain('Problem');
      expect(titles).toContain('Cause A');

      // Connections
      const edges = ib.edges || ib.connections || ib.links || ib.data?.edges || [];
      expect(edges.length).toBeGreaterThanOrEqual(1);

      // View state
      const view = ib.viewState || ib.view || ib.data?.view;
      if (view) {
        expect(view.x).toBe(100);
        expect(view.y).toBe(50);
        expect(view.zoom).toBe(0.9);
      }
    } finally {
      if (boardId) await safeDeleteBoard(boardId);
      if (importedBoardId) await safeDeleteBoard(importedBoardId);
    }
  });

  it('should reject invalid/corrupted files via global import without affecting existing boards', async () => {
    let existingBoardId: string | undefined;
    try {
