      const existing = await createBoard(`existing-${Date.now()}`, 'mindmap');
      existingBoardId = existing.id;
      await createNode(existingBoardId, { title: 'Existing Node' });

      // Snapshot the existing board before invalid import attempts
      const beforeInvalid = await getBoard(existingBoardId);
      expect(beforeInvalid.res.status).toBe(200);
      const beforeTemplate = beforeInvalid.body.template || beforeInvalid.body.type;
      const beforeNodes = await getNodes(existingBoardId);
      const beforeNodeCount = beforeNodes.length;
      const beforeTitles = beforeNodes.map((n: any) => n.title || n.label || n.text).sort();

      // Test 1: completely invalid object
      const invalid1 = await importBoard({ invalid: true, broken: '{not-json-shape' });
      expect([400, 422]).toContain(invalid1.res.status);
      // Verify error message exists
      const errMsg1 = invalid1.body?.message || invalid1.body?.error || invalid1.text;
      expect(typeof errMsg1).toBe('string');
