      // Test 2: valid JSON but missing required fields (not a board)
      const invalid2 = await importBoard({ name: 'Not a board', randomField: 42 });
      expect([400, 422]).toContain(invalid2.res.status);

      // Test 3: empty object
      const invalid3 = await importBoard({});
      expect([400, 422]).toContain(invalid3.res.status);

      // Verify existing board is NOT affected
      const afterInvalid = await getBoard(existingBoardId);
      expect(afterInvalid.res.status).toBe(200);
      const afterTemplate = afterInvalid.body.template || afterInvalid.body.type;
      expect(afterTemplate).toBe(beforeTemplate);

      const afterNodes = await getNodes(existingBoardId);
      expect(afterNodes.length).toBe(beforeNodeCount);
      const afterTitles = afterNodes.map((n: any) => n.title || n.label || n.text).sort();
      expect(afterTitles).toEqual(beforeTitles);
    } finally {
      if (existingBoardId) await safeDeleteBoard(existingBoardId);
    }
  });

  it('should accept legacy simple data via import and assign it to a valid template', async () => {
    let legacyImportedId: string | undefined;
    try {
      const legacyImport = await importBoard({
        title: `legacy-simple-${Date.now()}`,
        nodes: [
          { id: 'a', title: 'A', label: 'A' },
          { id: 'b', title: 'B', label: 'B' }
        ],
        edges: [
