      expect(tmpl, 'legacy import should fall into a default template').toBeTruthy();

      // Nodes should be preserved
      const nodes = await getNodes(legacyImportedId!).catch(() =>
        legacyFetched.body.nodes || legacyFetched.body.data?.nodes || []
      );
      const labels = nodes.map((n: any) => n.label || n.title || n.text);
      expect(labels).toContain('A');
      expect(labels).toContain('B');

      // Connection should be preserved
