import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function request(method: string, path: string, body?: any) {
  const res = await fetch(`${BASE_URL}${path}`, {
    method,
    headers: { 'Content-Type': 'application/json' },
    body: body === undefined ? undefined : JSON.stringify(body),
  });
  const text = await res.text();
  let json: any = null;
  try { json = text ? JSON.parse(text) : null; } catch { json = text; }
  return { res, body: json };
}

async function createBoard(title: string) {
  for (const c of [{ path: '/api/boards', body: { title } }, { path: '/boards', body: { title } }]) {
    const out = await request('POST', c.path, c.body);
    if (out.res.ok && (out.body?.id || out.body?.data?.id)) return { id: out.body.id || out.body.data.id, base: c.path.includes('/api/') ? '/api/boards' : '/boards' };
  }
  throw new Error('Unable to create board');
}

async function createNode(base: string, boardId: string, payload: any) {
  for (const path of [`${base}/${boardId}/nodes`, '/api/nodes', '/nodes']) {
    const body = path.includes(`/${boardId}/`) ? payload : { boardId, ...payload };
    const out = await request('POST', path, body);
    if (out.res.ok && (out.body?.id || out.body?.data?.id)) return { id: out.body.id || out.body.data.id, res: out.res, body: out.body };
  }
  throw new Error('Unable to create node');
}

async function updateNode(base: string, boardId: string, nodeId: string, patch: any) {
  for (const c of [
    { path: `${base}/${boardId}/nodes/${nodeId}`, body: patch },
    { path: '/api/nodes/' + nodeId, body: { boardId, ...patch } },
    { path: '/nodes/' + nodeId, body: { boardId, ...patch } },
  ]) {
    const out = await request('PATCH', c.path, c.body);
    if (out.res.status !== 404) return out;
  }
  throw new Error('Unable to update node');
}

async function getNode(base: string, boardId: string, nodeId: string) {
  for (const path of [`${base}/${boardId}/nodes/${nodeId}`, '/api/nodes/' + nodeId, '/nodes/' + nodeId]) {
    const out = await request('GET', path);
    if (out.res.ok) return out.body;
  }
  throw new Error('Unable to read node');
}

async function tryDeleteBoard(base: string, boardId: string) { try { await request('DELETE', `${base}/${boardId}`); } catch {} }

describe('round1_node_creation_and_persistence', () => {
  it('should create a node, update to a legal title, and persist after re-fetch', async () => {
    const board = await createBoard(`round1-${Date.now()}`);
    try {
      const node = await createNode(board.base, board.id, { title: 'Initial title', x: 50, y: 60 });
      const nodeId = node.id;
      expect(nodeId).toBeTruthy();

      // Update to legal title
      const patch = await updateNode(board.base, board.id, nodeId, { title: 'Updated legal title' });
      expect([200, 201]).toContain(patch.res.status);
      const patchTitle = patch.body?.title || patch.body?.data?.title;
      expect(patchTitle).toBe('Updated legal title');

      // Re-fetch: verify title persists
      const firstRead = await getNode(board.base, board.id, nodeId);
      expect(firstRead.title || firstRead.data?.title).toBe('Updated legal title');

      // Simulate "refresh" with second read: verify persistence
      const secondRead = await getNode(board.base, board.id, nodeId);
      expect(secondRead.title || secondRead.data?.title).toBe('Updated legal title');
      expect(secondRead.id || secondRead.data?.id).toBe(nodeId);

      // Verify position is also persisted
      const posX = secondRead.x ?? secondRead.data?.x;
      const posY = secondRead.y ?? secondRead.data?.y;
      if (posX !== undefined) {
        expect(posX).toBe(50);
        expect(posY).toBe(60);
      }
    } finally {
      await tryDeleteBoard(board.base, board.id);
    }
  });

  it('should reject empty or whitespace-only titles', async () => {
    const board = await createBoard(`round1-boundary-${Date.now()}`);
    try {
      const node = await createNode(board.base, board.id, { title: 'Valid title' });
      const nodeId = node.id;
      expect(nodeId).toBeTruthy();

      // Try to update with empty string
      const emptyPatch = await updateNode(board.base, board.id, nodeId, { title: '' });
      expect([400, 409, 422]).toContain(emptyPatch.res.status);

      // Try to update with whitespace-only string
      const whitespacePatch = await updateNode(board.base, board.id, nodeId, { title: '   ' });
      expect([400, 409, 422]).toContain(whitespacePatch.res.status);

      // Verify title is still the last valid value
      const afterReject = await getNode(board.base, board.id, nodeId);
      expect(afterReject.title || afterReject.data?.title).toBe('Valid title');
    } finally {
      await tryDeleteBoard(board.base, board.id);
    }
  });

  it('should reject titles exceeding 50 characters', async () => {
    const board = await createBoard(`round1-maxlen-${Date.now()}`);
    try {
      const node = await createNode(board.base, board.id, { title: 'Short title' });
      const nodeId = node.id;

      const longTitle = 'A'.repeat(51);
      const longPatch = await updateNode(board.base, board.id, nodeId, { title: longTitle });
      expect([400, 409, 422]).toContain(longPatch.res.status);

      // Verify title is still the last valid value
      const afterReject = await getNode(board.base, board.id, nodeId);
      expect(afterReject.title || afterReject.data?.title).toBe('Short title');

      // 50 chars should be accepted
      const exactTitle = 'B'.repeat(50);
      const exactPatch = await updateNode(board.base, board.id, nodeId, { title: exactTitle });
      expect([200, 201]).toContain(exactPatch.res.status);

      const afterExact = await getNode(board.base, board.id, nodeId);
      expect(afterExact.title || afterExact.data?.title).toBe(exactTitle);
    } finally {
      await tryDeleteBoard(board.base, board.id);
    }
  });

  it('should support single-select: only one node selected at a time', async () => {
    const board = await createBoard(`round1-select-${Date.now()}`);
    try {
      const node1 = await createNode(board.base, board.id, { title: 'Node A' });
      const node2 = await createNode(board.base, board.id, { title: 'Node B' });

      // Select node1
      const sel1 = await updateNode(board.base, board.id, node1.id, { selected: true });
      if ([200, 201].includes(sel1.res.status)) {
        // Select node2
        const sel2 = await updateNode(board.base, board.id, node2.id, { selected: true });
        expect([200, 201]).toContain(sel2.res.status);

        // Verify node1 is no longer selected
        const read1 = await getNode(board.base, board.id, node1.id);
        const selected1 = read1.selected ?? read1.data?.selected;
        expect(selected1).toBeFalsy();

        // Verify node2 is selected
        const read2 = await getNode(board.base, board.id, node2.id);
        const selected2 = read2.selected ?? read2.data?.selected;
        expect(selected2).toBe(true);
      }
      // If selection API doesn't work via PATCH selected, the test gracefully skips
    } finally {
      await tryDeleteBoard(board.base, board.id);
    }
  });
});

import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function request(path: string, options: any = {}) {
