    headers: { 'Content-Type': 'application/json', ...(options.headers || {}) },
    ...options,
  });
  let body: any = null;
  const text = await res.text();
  try {
    body = text ? JSON.parse(text) : null;
  } catch {
    body = text;
  }
  return { res, body };
}

async function safeDeleteBoard(id: string | undefined) {
  if (!id) return;
  try { await fetch(`${BASE_URL}/api/boards/${id}`, { method: 'DELETE' }); } catch {}
  try { await fetch(`${BASE_URL}/boards/${id}`, { method: 'DELETE' }); } catch {}
}

async function createBoard(title: string, template: string) {
  for (const c of [
    { path: '/api/boards', body: { title, template } },
    { path: '/boards', body: { title, template } },
  ]) {
    const out = await request(c.path, { method: 'POST', body: JSON.stringify(c.body) });
    if (out.res.ok && (out.body?.id || out.body?.data?.id)) {
      return {
        id: out.body.id || out.body.data.id,
        base: c.path,
      };
    }
  }
  throw new Error('Unable to create board');
}

async function createNode(base: string, boardId: string, payload: any) {
  for (const path of [`${base}/${boardId}/nodes`, `/api/boards/${boardId}/nodes`, `/boards/${boardId}/nodes`]) {
    const out = await request(path, { method: 'POST', body: JSON.stringify(payload) });
