}

// Known valid fishbone types
const FISHBONE_VALID_TYPES = ['problem', 'reason', 'cause', 'main', 'primary', 'secondary', 'category', 'sub-reason', 'bone', 'spine', 'effect'];

describe('fishbone_reason_depth_and_migration_defaults', () => {
  it('should enforce max 3-level fishbone reason depth and assign reasonable default type to migrated legacy nodes', async () => {
    let boardId: string | undefined;
    let legacyBoardId: string | undefined;

    try {
      // Create a fishbone board
      const board = await createBoard('Fishbone Depth Board', 'fishbone');
      boardId = board.id;

      // First, create the problem/main topic node (root of fishbone)
      let rootResult = await createNode(board.base, boardId, { title: 'Main Problem', type: 'problem' });
      if (!rootResult) {
        rootResult = await createNode(board.base, boardId, { title: 'Main Problem', type: 'main' });
      }
      if (!rootResult) {
        rootResult = await createNode(board.base, boardId, { title: 'Main Problem' });
      }
      expect(rootResult, 'Should be able to create root fishbone node').toBeTruthy();
      const rootId = rootResult!.id;

      // Level 1: primary reason / category under root
      const l1 = await createNode(board.base, boardId, { title: 'Level 1 Reason', type: 'reason', parentId: rootId });
      expect(l1, 'level 1 reason creation should succeed').toBeTruthy();
      const level1Id = l1!.id;

      // Level 2: sub-reason under level 1
      const l2 = await createNode(board.base, boardId, { title: 'Level 2 Reason', type: 'reason', parentId: level1Id });
      expect(l2, 'level 2 reason creation should succeed').toBeTruthy();
      const level2Id = l2!.id;

      // Level 3: deeper reason under level 2
      const l3 = await createNode(board.base, boardId, { title: 'Level 3 Reason', type: 'reason', parentId: level2Id });
      expect(l3, 'level 3 reason creation should succeed').toBeTruthy();
      const level3Id = l3!.id;

      // Verify the board now has all 4 nodes (root + 3 levels) with correct hierarchy
      const boardData = await getBoard(boardId);
      const nodes = boardData.nodes || boardData.data?.nodes || [];
      expect(Array.isArray(nodes), 'board should have a nodes array').toBe(true);
      expect(nodes.length, 'board should have at least 4 nodes (root + 3 levels)').toBeGreaterThanOrEqual(4);

      // Verify the created nodes exist in the board
      const nodeIds = nodes.map((n: any) => n.id);
      expect(nodeIds, 'root node should exist in board').toContain(rootId);
      expect(nodeIds, 'level 1 node should exist in board').toContain(level1Id);
      expect(nodeIds, 'level 2 node should exist in board').toContain(level2Id);
      expect(nodeIds, 'level 3 node should exist in board').toContain(level3Id);

      // Verify parent-child relationships where possible
      const l1Node = nodes.find((n: any) => n.id === level1Id);
      if (l1Node && (l1Node.parentId || l1Node.parent)) {
        expect(l1Node.parentId || l1Node.parent, 'level 1 parent should be root').toBe(rootId);
      }
      const l2Node = nodes.find((n: any) => n.id === level2Id);
      if (l2Node && (l2Node.parentId || l2Node.parent)) {
        expect(l2Node.parentId || l2Node.parent, 'level 2 parent should be level 1').toBe(level1Id);
      }
      const l3Node = nodes.find((n: any) => n.id === level3Id);
      if (l3Node && (l3Node.parentId || l3Node.parent)) {
        expect(l3Node.parentId || l3Node.parent, 'level 3 parent should be level 2').toBe(level2Id);
      }

      // Level 4: should be REJECTED because max depth is 3 levels of reasons
      const l4Result = await createNodeExpectFail(board.base, boardId, { title: 'Level 4 Too Deep', type: 'reason', parentId: level3Id });
      expect(
        [400, 409, 422, 403].includes(l4Result.res.status),
        `level 4 reason should be rejected because max depth is 3, got ${l4Result.res.status} with body ${JSON.stringify(l4Result.body)}`
      ).toBe(true);

      // Verify the rejection response contains an explanatory message
      const errorText = JSON.stringify(l4Result.body).toLowerCase();
      expect(
        errorText.includes('depth') || errorText.includes('level') || errorText.includes('layer') ||
        errorText.includes('limit') || errorText.includes('max') || errorText.includes('exceed') ||
        errorText.includes('层') || errorText.includes('超') || errorText.includes('不能'),
        `rejection response should explain the depth/level limit, got: ${JSON.stringify(l4Result.body)}`
      ).toBe(true);

      // Verify the board still has exactly 4 nodes (L4 was not created)
      const boardAfterReject = await getBoard(boardId);
      const nodesAfterReject = boardAfterReject.nodes || boardAfterReject.data?.nodes || [];
      expect(nodesAfterReject.length, 'rejected L4 should not have been added').toBe(nodes.length);

      // Test independent branch: create another L1 under root with its own depth
      const l1b = await createNode(board.base, boardId, { title: 'Branch B L1', type: 'reason', parentId: rootId });
      expect(l1b, 'second branch level 1 should succeed').toBeTruthy();
      const l1bId = l1b!.id;

      const l2b = await createNode(board.base, boardId, { title: 'Branch B L2', type: 'reason', parentId: l1bId });
      expect(l2b, 'second branch level 2 should succeed').toBeTruthy();

      const l3b = await createNode(board.base, boardId, { title: 'Branch B L3', type: 'reason', parentId: l2b!.id });
      expect(l3b, 'second branch level 3 should succeed').toBeTruthy();

      // L4 on second branch should also be rejected
      const l4bResult = await createNodeExpectFail(board.base, boardId, { title: 'Branch B L4 Too Deep', type: 'reason', parentId: l3b!.id });
      expect(
        [400, 409, 422, 403].includes(l4bResult.res.status),
        `level 4 on second branch should also be rejected, got ${l4bResult.res.status}`
      ).toBe(true);

      // --- Legacy node migration via import ---
      const legacyPayload = {
        title: 'Legacy Fishbone Import',
        template: 'fishbone',
        nodes: [
          { id: 'legacy-1', title: 'Legacy Node A' },
          { id: 'legacy-2', title: 'Legacy Node B' },
        ],
        edges: [],
      };
      const importResult = await importBoard(legacyPayload);
      expect(
        [200, 201].includes(importResult.res.status),
        `legacy import should succeed, got ${importResult.res.status} with body ${JSON.stringify(importResult.body)}`
      ).toBe(true);
      legacyBoardId = importResult.body?.id || importResult.body?.boardId || importResult.body?.data?.id;
      expect(legacyBoardId, 'imported board should have an id').toBeTruthy();

      // Read the imported board and check migrated nodes have default types
      const importedBoard = await getBoard(legacyBoardId as string);
      const importedNodes = importedBoard.nodes || importedBoard.data?.nodes || [];

      expect(Array.isArray(importedNodes), 'imported board should have a nodes array').toBe(true);
      expect(importedNodes.length, 'imported board should contain migrated nodes').toBeGreaterThanOrEqual(2);

      for (const node of importedNodes) {
        const nodeType = (node.type || node.nodeType || '').toLowerCase().trim();
        expect(
          nodeType.length > 0,
          `migrated node "${node.title || node.id}" should have a non-empty default type, got type=${JSON.stringify(node.type || node.nodeType)}`
        ).toBe(true);

        // Verify the assigned type is a reasonable fishbone type
        const isValidFishboneType = FISHBONE_VALID_TYPES.some(validType => nodeType.includes(validType));
        expect(
          isValidFishboneType,
          `migrated node "${node.title || node.id}" type "${nodeType}" should be a valid fishbone type (one of: ${FISHBONE_VALID_TYPES.join(', ')})`
        ).toBe(true);
      }

    } finally {
      await safeDeleteBoard(boardId);
      await safeDeleteBoard(legacyBoardId);
    }
  });
});

