    const out = await request(c.path, { method: 'POST', body: JSON.stringify(c.body) });
    if (out.res.ok && (out.body?.id || out.body?.data?.id)) {
      return { id: out.body.id || out.body.data.id, base: c.path.replace(/\/$/, '') };
    }
  }
  throw new Error('Unable to create board');
}

async function getBoard(boardId: string) {
  for (const path of [`/api/boards/${boardId}`, `/boards/${boardId}`]) {
    const out = await request(path);
    if (out.res.ok) return out;
  }
  throw new Error('Unable to read board');
}

async function renameBoard(boardId: string, payload: any) {
  for (const path of [`/api/boards/${boardId}`, `/boards/${boardId}`]) {
    const out = await request(path, { method: 'PATCH', body: JSON.stringify(payload) });
    if (out.res.status !== 404) return out;
  }
  // Try PUT as fallback
  for (const path of [`/api/boards/${boardId}`, `/boards/${boardId}`]) {
    const out = await request(path, { method: 'PUT', body: JSON.stringify(payload) });
    if (out.res.status !== 404) return out;
  }
  throw new Error('Unable to rename board');
}

async function copyBoard(boardId: string) {
  for (const path of [`/api/boards/${boardId}/copy`, `/boards/${boardId}/copy`]) {
    const out = await request(path, { method: 'POST' });
    if (out.res.status !== 404) return out;
  }
  throw new Error('Unable to copy board');
}

async function createNode(boardId: string, payload: any) {
  for (const path of [`/api/boards/${boardId}/nodes`, `/boards/${boardId}/nodes`]) {
    const out = await request(path, { method: 'POST', body: JSON.stringify(payload) });
    if (out.res.ok && (out.body?.id || out.body?.data?.id)) return out;
  }
  throw new Error('Unable to create node');
}

async function getNodes(boardId: string) {
  for (const path of [`/api/boards/${boardId}/nodes`, `/boards/${boardId}/nodes`]) {
    const out = await request(path);
    if (out.res.ok) {
      const nodes = Array.isArray(out.body) ? out.body : (out.body?.items || out.body?.data || out.body?.nodes || []);
      return nodes;
    }
  }
  return [];
}

describe('rename_copy_delete_board_constraints', () => {
  it('should validate rename length/trim rules, copy board with distinguishable name and same content, then delete successfully', async () => {
    let boardId: string | undefined;
    let copyId: string | undefined;

    try {
      // Create board using 'title' and 'template' fields
      const board = await createBoard('Original Board', 'mindmap');
      boardId = board.id;

      // Add a node so we can verify content is copied
      const nodePayload = { title: 'Seed Node' };
      const nodeResult = await createNode(boardId, nodePayload);
      expect([200, 201]).toContain(nodeResult.res.status);

      // --- Boundary: rename with only whitespace should be rejected ---
      const invalidRename = await renameBoard(boardId, { title: '    ' });
      expect(
        [400, 422].includes(invalidRename.res.status),
        `rename with only whitespace should be rejected, got ${invalidRename.res.status}`
      ).toBe(true);

      // --- Boundary: rename with >40 characters should be rejected ---
      const longName = 'A'.repeat(41);
      const tooLongRename = await renameBoard(boardId, { title: longName });
      expect(
        [400, 422].includes(tooLongRename.res.status),
        `rename with ${longName.length} chars should be rejected (max 40), got ${tooLongRename.res.status}`
      ).toBe(true);

      // --- Boundary: rename with exactly 40 characters should succeed ---
      const maxName = 'B'.repeat(40);
      const exactMaxRename = await renameBoard(boardId, { title: maxName });
      expect(
        [200, 204].includes(exactMaxRename.res.status),
        `rename with exactly 40 chars should succeed, got ${exactMaxRename.res.status}`
      ).toBe(true);

      // --- Valid rename with leading/trailing whitespace ---
      const validRenamePayload = { title: '   Renamed Board   ' };
      const renameResult = await renameBoard(boardId, validRenamePayload);
      expect(
        [200, 204].includes(renameResult.res.status),
        `valid rename should succeed, got ${renameResult.res.status}`
      ).toBe(true);

      // Verify the stored name is trimmed
      const renamedBoard = await getBoard(boardId);
      expect(renamedBoard.res.status).toBe(200);
      const storedTitle = renamedBoard.body.title || renamedBoard.body.name;
      expect(typeof storedTitle).toBe('string');
      expect(storedTitle.trim()).toBe('Renamed Board');
      expect(storedTitle.trim().length).toBeGreaterThanOrEqual(1);
      expect(storedTitle.trim().length).toBeLessThanOrEqual(40);

      // --- Copy the board ---
      const copyResult = await copyBoard(boardId);
      expect(
        [200, 201].includes(copyResult.res.status),
        `copy board should succeed, got ${copyResult.res.status}`
      ).toBe(true);
      copyId = copyResult.body?.id || copyResult.body?.data?.id;
      expect(copyId).toBeTruthy();
      expect(copyId).not.toBe(boardId);

      // Verify copy has a distinguishable name
      const copiedBoard = await getBoard(copyId as string);
      expect(copiedBoard.res.status).toBe(200);
      const copyTitle = copiedBoard.body.title || copiedBoard.body.name;
      expect(typeof copyTitle).toBe('string');
      expect(copyTitle).not.toBe(storedTitle.trim());

      // Verify copy has the same content (nodes)
      const originalNodes = await getNodes(boardId);
      const copyNodes = await getNodes(copyId as string);
      expect(copyNodes.length, 'copied board should have the same number of nodes').toBe(originalNodes.length);
      expect(
        copyNodes.some((n: any) => n.title === 'Seed Node'),
        `copied board should contain 'Seed Node'`
      ).toBe(true);

      // --- Delete the copy (with confirm if needed) ---
      let deleteResult: any;
      // Try with confirm parameter
      for (const path of [`/api/boards/${copyId}`, `/boards/${copyId}`]) {
        deleteResult = await request(path, {
          method: 'DELETE',
          body: JSON.stringify({ confirm: true }),
        });
        if ([200, 204].includes(deleteResult.res.status)) break;
        // Try without body
        deleteResult = await request(path, { method: 'DELETE' });
        if ([200, 204].includes(deleteResult.res.status)) break;
      }
      expect(
        [200, 204].includes(deleteResult.res.status),
        `delete board should succeed, got ${deleteResult.res.status}`
      ).toBe(true);

      // Verify deleted board is gone
      let deletedCheck: any;
      for (const path of [`/api/boards/${copyId}`, `/boards/${copyId}`]) {
        deletedCheck = await request(path);
        if ([404, 410].includes(deletedCheck.res.status)) break;
      }
      expect(
        [404, 410].includes(deletedCheck.res.status),
        `deleted board should return 404 or 410, got ${deletedCheck.res.status}`
      ).toBe(true);
      copyId = undefined;

    } finally {
      await safeDeleteBoard(copyId);
      await safeDeleteBoard(boardId);
    }
  });
});

import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function request(path: string, options: any = {}) {
  const res = await fetch(`${BASE_URL}${path}`, {
    headers: { 'Content-Type': 'application/json', ...(options.headers || {}) },
    ...options,
  });
  const text = await res.text();
  let json: any;
  try { json = text ? JSON.parse(text) : null; } catch { json = text; }
  return { res, body: json, text };
}

async function safeDeleteBoard(boardId: string) {
  if (!boardId) return;
  try { await fetch(`${BASE_URL}/api/boards/${boardId}`, { method: 'DELETE' }); } catch {}
}

describe('round9_undo_redo_local_history', () => {
  it('should undo/redo local edits in stable order, invalidate future branch after new edit, and maintain consistent state after simulated refresh', async () => {
    let boardId: string | undefined;
    try {
      const userId = `undo-user-${Date.now()}`;
      const otherUserId = `other-user-${Date.now()}`;

      const created = await request('/api/boards', {
        method: 'POST',
        headers: { 'X-User-Id': userId },
        body: JSON.stringify({
          title: `undo-redo-${Date.now()}`,
          template: 'mindmap',
          data: { nodes: [{ id: 'root-1', label: 'Root', type: 'root' }], edges: [] },
        }),
      });
      expect([200, 201]).toContain(created.res.status);
      boardId = created.body.id || created.body.boardId;
      expect(boardId).toBeTruthy();

      // Step 1: Add a child node (operation 1)
      const addChild = await request(`/api/boards/${boardId}/nodes/root-1/children`, {
        method: 'POST',
        headers: { 'X-User-Id': userId },
        body: JSON.stringify({ label: 'Child 1' }),
      });
      expect([200, 201]).toContain(addChild.res.status);
      const childId = addChild.body.id || addChild.body.nodeId;
      expect(childId).toBeTruthy();

      // Step 2: Rename child (operation 2)
      const rename = await request(`/api/boards/${boardId}/nodes/${childId}`, {
        method: 'PATCH',
        headers: { 'X-User-Id': userId },
        body: JSON.stringify({ label: 'Child 1 Renamed' }),
      });
      expect([200, 204]).toContain(rename.res.status);

      // Step 3: Undo rename — child should revert to 'Child 1'
      const undo1 = await request(`/api/boards/${boardId}/history/undo`, {
        method: 'POST',
        headers: { 'X-User-Id': userId },
      });
      expect([200, 201]).toContain(undo1.res.status);

      let current = await request(`/api/boards/${boardId}`, { headers: { 'X-User-Id': userId } });
      expect(current.res.status).toBe(200);
      let nodes = current.body.nodes || current.body.data?.nodes || [];
      let child = nodes.find((n: any) => n.id === childId);
      expect(child).toBeTruthy();
      expect(child.label || child.title || child.text).toBe('Child 1');

      // Step 4: Undo add child — child should be gone
      const undo2 = await request(`/api/boards/${boardId}/history/undo`, {
        method: 'POST',
        headers: { 'X-User-Id': userId },
      });
      expect([200, 201]).toContain(undo2.res.status);

      current = await request(`/api/boards/${boardId}`, { headers: { 'X-User-Id': userId } });
      expect(current.res.status).toBe(200);
      nodes = current.body.nodes || current.body.data?.nodes || [];
      child = nodes.find((n: any) => n.id === childId);
      expect(child, 'expected child to be removed after second undo').toBeFalsy();

      // Step 5: Redo — child should come back with 'Child 1'
      const redo1 = await request(`/api/boards/${boardId}/history/redo`, {
        method: 'POST',
        headers: { 'X-User-Id': userId },
      });
      expect([200, 201]).toContain(redo1.res.status);

      current = await request(`/api/boards/${boardId}`, { headers: { 'X-User-Id': userId } });
      nodes = current.body.nodes || current.body.data?.nodes || [];
      child = nodes.find((n: any) => n.id === childId);
      expect(child).toBeTruthy();
      expect(child.label || child.title || child.text).toBe('Child 1');

      // Step 6: New edit invalidates future redo branch
      const newEdit = await request(`/api/boards/${boardId}/nodes/${childId}`, {
        method: 'PATCH',
        headers: { 'X-User-Id': userId },
        body: JSON.stringify({ label: 'Child 1 New Branch' }),
      });
      expect([200, 204]).toContain(newEdit.res.status);

      // Redo should now fail or be a no-op since future branch is invalidated
      const redoShouldFail = await request(`/api/boards/${boardId}/history/redo`, {
        method: 'POST',
        headers: { 'X-User-Id': userId },
      });
      // Accept either an error status or a 200 with indication that nothing was redone
      if (redoShouldFail.res.status >= 200 && redoShouldFail.res.status < 300) {
        // If the server returns 200, the content should still be 'Child 1 New Branch' (no redo happened)
        const afterRedoAttempt = await request(`/api/boards/${boardId}`, { headers: { 'X-User-Id': userId } });
        const n = (afterRedoAttempt.body.nodes || afterRedoAttempt.body.data?.nodes || []).find((x: any) => x.id === childId);
        expect(n).toBeTruthy();
        expect(n.label || n.title || n.text).toBe('Child 1 New Branch');
      } else {
        expect([400, 409, 422]).toContain(redoShouldFail.res.status);
      }

      // Step 7: Verify final state content
      const finalState = await request(`/api/boards/${boardId}`, { headers: { 'X-User-Id': userId } });
      expect(finalState.res.status).toBe(200);
      const finalNodes = finalState.body.nodes || finalState.body.data?.nodes || [];
      const finalChild = finalNodes.find((n: any) => n.id === childId);
      expect(finalChild).toBeTruthy();
      expect(finalChild.label || finalChild.title || finalChild.text).toBe('Child 1 New Branch');

      // Step 8: Simulate other user's edit — should not be affected by our undo
      const otherUserEdit = await request(`/api/boards/${boardId}/nodes/root-1`, {
        method: 'PATCH',
        headers: { 'X-User-Id': otherUserId },
        body: JSON.stringify({ label: 'Root Updated By Other' }),
      });
      if ([200, 204].includes(otherUserEdit.res.status)) {
        // Now undo as our user — it should NOT revert the other user's change
        const undoOurs = await request(`/api/boards/${boardId}/history/undo`, {
          method: 'POST',
          headers: { 'X-User-Id': userId },
        });
        if ([200, 201].includes(undoOurs.res.status)) {
          const afterUndoOurs = await request(`/api/boards/${boardId}`, { headers: { 'X-User-Id': userId } });
          const rootNode = (afterUndoOurs.body.nodes || afterUndoOurs.body.data?.nodes || []).find((n: any) => n.id === 'root-1');
          if (rootNode) {
            // Other user's edit should still be present
            expect(rootNode.label || rootNode.title || rootNode.text).toBe('Root Updated By Other');
          }
        }
      }

      // Step 9: Simulate refresh — re-GET the board and history meta to verify state consistency
      const refreshedBoard = await request(`/api/boards/${boardId}`, { headers: { 'X-User-Id': userId } });
      expect(refreshedBoard.res.status).toBe(200);
      const refreshedNodes = refreshedBoard.body.nodes || refreshedBoard.body.data?.nodes || [];
      // The board should have content (at least root node)
      expect(refreshedNodes.length).toBeGreaterThanOrEqual(1);

      // Check history meta after refresh — button states should not conflict with content
      const historyMeta = await request(`/api/boards/${boardId}/history`, { headers: { 'X-User-Id': userId } });
      if (historyMeta.res.status === 200 && historyMeta.body && typeof historyMeta.body === 'object') {
        // If canUndo/canRedo are exposed, they should be consistent
        if ('canRedo' in historyMeta.body) {
          // We can't redo since we branched
          expect(historyMeta.body.canRedo).toBe(false);
        }
        // canUndo may or may not be true depending on remaining history
        if ('canUndo' in historyMeta.body) {
          expect(typeof historyMeta.body.canUndo).toBe('boolean');
        }
      }
    } finally {
      if (boardId) await safeDeleteBoard(boardId);
    }
  });
});

import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function request(method: string, path: string, body?: any, contentType?: string) {
  const headers: Record<string, string> = {};
  if (contentType) {
    headers['Content-Type'] = contentType;
  } else if (body !== undefined) {
    headers['Content-Type'] = 'application/json';
  }
  const res = await fetch(`${BASE_URL}${path}`, {
    method,
    headers,
    body: body === undefined ? undefined : (typeof body === 'string' ? body : JSON.stringify(body)),
  });
  const text = await res.text();
  let json: any = null;
  try { json = text ? JSON.parse(text) : null; } catch { json = text; }
  return { res, body: json, text };
}

async function createBoard(title: string) {
  for (const c of [{ path: '/api/boards', body: { title } }, { path: '/boards', body: { title } }]) {
    const out = await request('POST', c.path, c.body);
    if (out.res.ok && (out.body?.id || out.body?.data?.id)) return { id: out.body.id || out.body.data.id, base: c.path.includes('/api/') ? '/api/boards' : '/boards' };
  }
  throw new Error('Unable to create board');
}

async function createNode(base: string, boardId: string, title: string) {
  for (const path of [`${base}/${boardId}/nodes`, '/api/nodes', '/nodes']) {
    const payload = path.includes(`/${boardId}/`) ? { title } : { boardId, title };
    const out = await request('POST', path, payload);
    if (out.res.ok && (out.body?.id || out.body?.data?.id)) return out.body.id || out.body.data.id;
  }
  throw new Error('Unable to create node');
}

async function getBoard(base: string, boardId: string) {
  for (const path of [`${base}/${boardId}`, '/api/boards/' + boardId, '/boards/' + boardId]) {
    const out = await request('GET', path);
    if (out.res.ok) return out.body;
  }
  throw new Error('Unable to read board');
}

async function listBoards() {
  for (const path of ['/api/boards', '/boards']) {
    const out = await request('GET', path);
    if (out.res.ok) return out.body;
  }
  return null;
}

async function importBoard(payload: any, contentType?: string) {
  for (const path of ['/api/boards/import', '/boards/import', '/api/import']) {
    const out = await request('POST', path, payload, contentType);
    if (out.res.status !== 404) return out;
  }
  throw new Error('Unable to reach import endpoint');
}

async function tryDeleteBoard(boardId: string) {
  if (!boardId) return;
  try { await request('DELETE', `/api/boards/${boardId}`); } catch {}
  try { await request('DELETE', `/boards/${boardId}`); } catch {}
}

describe('import_invalid_and_legacy_data_handling', () => {
  it('should reject invalid JSON object import without overwriting any existing board data', async () => {
    const board = await createBoard(`import-guard-${Date.now()}`);
    try {
      const nodeId = await createNode(board.base, board.id, 'Existing node before invalid import');
      expect(nodeId).toBeTruthy();

      const before = await getBoard(board.base, board.id);
      const beforeText = JSON.stringify(before);
      expect(beforeText).toContain('Existing node before invalid import');

      // Capture board list before invalid import to verify no silent side effects
      const boardsBefore = await listBoards();
      const boardsBeforeCount = Array.isArray(boardsBefore)
        ? boardsBefore.length
        : (boardsBefore?.items || boardsBefore?.data || []).length;

      // --- Import invalid data (random JSON, not a valid export) ---
      const invalid = await importBoard({ definitely: 'not-a-valid-export-format', broken: true });
      expect([400, 415, 422]).toContain(invalid.res.status);
      const invalidMsg = JSON.stringify(invalid.body).toLowerCase();
      expect(invalidMsg).toMatch(/invalid|unsupported|format|import|error|fail/);

      // Existing board content must be intact
      const after = await getBoard(board.base, board.id);
      const afterText = JSON.stringify(after);
      expect(afterText, 'Invalid import should not overwrite existing board content').toContain('Existing node before invalid import');

      // No extra boards should have been created by invalid import
      const boardsAfter = await listBoards();
      const boardsAfterCount = Array.isArray(boardsAfter)
        ? boardsAfter.length
        : (boardsAfter?.items || boardsAfter?.data || []).length;
      expect(boardsAfterCount).toBe(boardsBeforeCount);
    } finally {
      await tryDeleteBoard(board.id);
    }
  });

  it('should reject corrupted/non-JSON import data', async () => {
    // Send a non-JSON string as import payload
    const corrupted = await importBoard('<<<this is not json at all>>>', 'text/plain');
    expect([400, 415, 422]).toContain(corrupted.res.status);
    const corruptedMsg = JSON.stringify(corrupted.body ?? corrupted.text).toLowerCase();
    expect(corruptedMsg).toMatch(/invalid|unsupported|format|json|parse|error|fail/);
  });

  it('should reject partially valid but structurally broken import data', async () => {
    // Has some valid-looking fields but is missing critical structure
    const partial = await importBoard({
      version: '999.0',
      nodes: 'not-an-array',
      edges: null
    });
    expect([400, 415, 422]).toContain(partial.res.status);
  });

  it('should accept legacy minimal data, assign a default template, and remain editable', async () => {
    let legacyImportedId: string | undefined;
    try {
      const legacyPayload = {
        version: '0.1',
        nodes: [
          { id: 'legacy-1', title: 'Legacy A' },
          { id: 'legacy-2', title: 'Legacy B' }
        ],
        connections: [
          { fromId: 'legacy-1', toId: 'legacy-2' }
        ]
      };
      const legacy = await importBoard(legacyPayload);
      expect([200, 201]).toContain(legacy.res.status);
      legacyImportedId = legacy.body?.id || legacy.body?.boardId || legacy.body?.data?.id;
      expect(legacyImportedId).toBeTruthy();

      // Read back the imported board
      let imported: any;
      try {
        imported = await getBoard('/api/boards', legacyImportedId as string);
      } catch {
        imported = await getBoard('/boards', legacyImportedId as string);
      }
      const importedText = JSON.stringify(imported);

      // Verify legacy nodes are present
      expect(importedText).toContain('Legacy A');
      expect(importedText).toContain('Legacy B');

      // Verify a default template was assigned
      expect(importedText.toLowerCase()).toMatch(/template|mindmap|flowchart|fishbone/);

      // --- Verify the imported board is still editable ---
      // Try creating a new node on the imported board
      let newNodeCreated = false;
      for (const path of [
        `/api/boards/${legacyImportedId}/nodes`,
        `/boards/${legacyImportedId}/nodes`,
        '/api/nodes'
      ]) {
        const payload = path.includes(`/${legacyImportedId}/`)
          ? { title: 'NewNodeAfterImport' }
          : { boardId: legacyImportedId, title: 'NewNodeAfterImport' };
        const addRes = await request('POST', path, payload);
        if (addRes.res.ok && (addRes.body?.id || addRes.body?.data?.id)) {
          newNodeCreated = true;
          break;
        }
      }
      expect(newNodeCreated, 'Should be able to create a new node on the imported legacy board').toBe(true);

      // Verify the new node is persisted
      let afterEdit: any;
      try {
        afterEdit = await getBoard('/api/boards', legacyImportedId as string);
      } catch {
        afterEdit = await getBoard('/boards', legacyImportedId as string);
      }
      const afterEditText = JSON.stringify(afterEdit);
      expect(afterEditText).toContain('NewNodeAfterImport');
    } finally {
      if (legacyImportedId) await tryDeleteBoard(legacyImportedId);
    }
  });
});

import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function http(path, options = {}) {
