describe('round7_local_edit_lock_simulation_and_recent_activity', () => {
  it('should keep recent activities in reverse order with max 10, expose node lock, block locked-node edits by others, and keep locks independent across nodes', async () => {
    let boardId;
    try {
      // --- Setup: create board ---
      const created = await request('/api/boards', {
        method: 'POST',
        body: JSON.stringify({
          title: `lock-activity-${Date.now()}`,
          template: 'mindmap',
        })
      });
      expect([200, 201]).toContain(created.res.status);
      boardId = created.body.id || created.body.boardId;
      expect(boardId).toBeTruthy();

      // --- Create two nodes ---
      const node1Create = await request(`/api/boards/${boardId}/nodes`, {
        method: 'POST',
        body: JSON.stringify({ text: 'Node Alpha', x: 0, y: 0 }),
      });
      expect([200, 201]).toContain(node1Create.res.status);
      const node1Id = node1Create.body.id;
      expect(node1Id).toBeTruthy();

      const node2Create = await request(`/api/boards/${boardId}/nodes`, {
        method: 'POST',
        body: JSON.stringify({ text: 'Node Beta', x: 100, y: 0 }),
      });
      expect([200, 201]).toContain(node2Create.res.status);
      const node2Id = node2Create.body.id;
      expect(node2Id).toBeTruthy();

      // --- Generate 12 activities to test max-10 cap ---
      for (let i = 0; i < 12; i++) {
        await request(`/api/boards/${boardId}/nodes/${node1Id}`, {
          method: 'PATCH',
          body: JSON.stringify({ text: `activity-${i}` }),
        });
      }

      // --- Lock node1 by Tester A ---
      const lock = await request(`/api/boards/${boardId}/nodes/${node1Id}/lock`, {
        method: 'PUT',
        body: JSON.stringify({ locked: true, by: 'Tester A' })
      });
      expect([200, 201]).toContain(lock.res.status);

      // --- Verify lock is visible in node detail ---
      const detail = await request(`/api/boards/${boardId}/nodes/${node1Id}`);
      expect(detail.res.status).toBe(200);
      const lockInfo = detail.body.lock || detail.body.editLock || detail.body.occupancy;
      expect(lockInfo, `expected lock info in node detail, got ${JSON.stringify(detail.body)}`).toBeTruthy();
      expect(lockInfo.locked ?? lockInfo.isLocked).toBe(true);

      // --- Verify lock persists on immediate re-fetch (short-term persistence) ---
      const detailAgain = await request(`/api/boards/${boardId}/nodes/${node1Id}`);
      expect(detailAgain.res.status).toBe(200);
      const lockAgain = detailAgain.body.lock || detailAgain.body.editLock || detailAgain.body.occupancy;
      expect(lockAgain).toBeTruthy();
      expect(lockAgain.locked ?? lockAgain.isLocked).toBe(true);

      // --- Another user tries to edit locked node1 → should be rejected ---
      const conflictEdit = await request(`/api/boards/${boardId}/nodes/${node1Id}`, {
        method: 'PATCH',
        headers: { 'X-User-Id': 'other-user', 'X-User-Name': 'Tester B' },
        body: JSON.stringify({ text: 'Conflict attempt' }),
      });
      expect(
        [403, 409, 423].includes(conflictEdit.res.status),
        `editing a locked node by another user should be rejected, got ${conflictEdit.res.status}`
      ).toBe(true);

      // --- Lock node2 by Tester B: should succeed independently ---
      const lock2 = await request(`/api/boards/${boardId}/nodes/${node2Id}/lock`, {
        method: 'PUT',
        headers: { 'X-User-Id': 'other-user' },
        body: JSON.stringify({ locked: true, by: 'Tester B' })
      });
      expect([200, 201]).toContain(lock2.res.status);

      // Verify node2 lock
      const detail2 = await request(`/api/boards/${boardId}/nodes/${node2Id}`);
      expect(detail2.res.status).toBe(200);
      const lockInfo2 = detail2.body.lock || detail2.body.editLock || detail2.body.occupancy;
      expect(lockInfo2).toBeTruthy();
      expect(lockInfo2.locked ?? lockInfo2.isLocked).toBe(true);

      // Verify node1 lock is still intact (independent)
      const detail1Recheck = await request(`/api/boards/${boardId}/nodes/${node1Id}`);
      const lockRecheck = detail1Recheck.body.lock || detail1Recheck.body.editLock || detail1Recheck.body.occupancy;
      expect(lockRecheck).toBeTruthy();
      expect(lockRecheck.locked ?? lockRecheck.isLocked).toBe(true);

      // --- Verify recent activities: max 10, reverse chronological ---
      const activities = await request(`/api/boards/${boardId}/activities`);
      expect(activities.res.status).toBe(200);
      const items = activities.body.items || activities.body.activities || activities.body;
      expect(Array.isArray(items)).toBe(true);
      expect(items.length).toBeLessThanOrEqual(10);
      expect(items.length).toBeGreaterThan(0);

      // The oldest simulated activities (activity-0, activity-1) should have been pushed out
      const allMessages = JSON.stringify(items);
      // activity-11 (last generated) should be present in recent items
      expect(
        allMessages.includes('activity-11'),
        `most recent activity (activity-11) should be in the list`
      ).toBe(true);
    } finally {
      await safeDeleteBoard(boardId);
    }
  });
});

import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function request(method: string, path: string, body?: any) {
  const res = await fetch(`${BASE_URL}${path}`, {
    method,
    headers: { 'Content-Type': 'application/json' },
    body: body === undefined ? undefined : JSON.stringify(body),
  });
  const text = await res.text();
  let json: any = null;
  try { json = text ? JSON.parse(text) : null; } catch { json = text; }
  return { res, body: json };
}

async function createBoard(title: string, template = 'mindmap') {
  for (const c of [
    { path: '/api/boards', body: { title, template } },
    { path: '/boards', body: { title, template } },
  ]) {
    const out = await request('POST', c.path, c.body);
    if (out.res.ok && (out.body?.id || out.body?.data?.id)) {
      return {
        id: out.body.id || out.body.data.id,
        base: c.path.includes('/api/') ? '/api/boards' : '/boards',
      };
    }
  }
  throw new Error('Unable to create board');
}

async function createNode(base: string, boardId: string, title: string) {
  for (const path of [`${base}/${boardId}/nodes`, '/api/nodes', '/nodes']) {
    const payload = path.includes(`/${boardId}/`) ? { title } : { boardId, title };
    const out = await request('POST', path, payload);
    if (out.res.ok && (out.body?.id || out.body?.data?.id)) return out.body.id || out.body.data.id;
  }
  throw new Error('Unable to create node');
}

async function createConnection(base: string, boardId: string, fromId: string, toId: string) {
  // Try both field name conventions: fromId/toId and fromNodeId/toNodeId
  for (const path of [`${base}/${boardId}/connections`, '/api/connections', '/connections']) {
    for (const payload of [
      path.includes(`/${boardId}/`) ? { fromId, toId } : { boardId, fromId, toId },
      path.includes(`/${boardId}/`) ? { fromNodeId: fromId, toNodeId: toId } : { boardId, fromNodeId: fromId, toNodeId: toId },
      path.includes(`/${boardId}/`) ? { source: fromId, target: toId } : { boardId, source: fromId, target: toId },
    ]) {
      const out = await request('POST', path, payload);
      if (out.res.status !== 404) return out;
    }
  }
  throw new Error('Unable to create connection');
}

async function listConnections(base: string, boardId: string) {
  for (const path of [
    `${base}/${boardId}/connections`,
    `/api/connections?boardId=${boardId}`,
    `/connections?boardId=${boardId}`,
  ]) {
    const out = await request('GET', path);
    if (out.res.ok) return Array.isArray(out.body) ? out.body : out.body.items || out.body.data || [];
  }
  throw new Error('Unable to list connections');
}

async function getNodeDetail(base: string, boardId: string, nodeId: string) {
  for (const path of [
    `${base}/${boardId}/nodes/${nodeId}`,
    `/api/nodes/${nodeId}`,
    `/nodes/${nodeId}`,
  ]) {
    const out = await request('GET', path);
    if (out.res.ok && out.body) return out.body;
  }
  return null;
}

async function getBoardDetail(base: string, boardId: string) {
  const out = await request('GET', `${base}/${boardId}`);
  if (out.res.ok) return out.body;
  return null;
}

async function deleteNode(base: string, boardId: string, nodeId: string) {
  for (const path of [
    `${base}/${boardId}/nodes/${nodeId}`,
    '/api/nodes/' + nodeId,
    '/nodes/' + nodeId,
  ]) {
    const out = await request('DELETE', path);
    if (out.res.status !== 404) return out;
  }
  throw new Error('Unable to delete node');
}

async function tryDeleteBoard(base: string, boardId: string) {
  try { await request('DELETE', `${base}/${boardId}`); } catch {}
}

function extractUpstreamDownstream(detail: any) {
  // Try common field naming patterns for upstream/downstream counts
  const upstream = detail?.upstreamCount ?? detail?.upstream ?? detail?.incomingCount ?? detail?.incoming ?? detail?.parentCount ?? detail?.parents?.length ?? null;
  const downstream = detail?.downstreamCount ?? detail?.downstream ?? detail?.outgoingCount ?? detail?.outgoing ?? detail?.childCount ?? detail?.children?.length ?? null;
  return { upstream, downstream };
}

describe('round2_connection_rules_and_cascade_delete', () => {
  it('should reject self-connections and duplicates, reject cycles in hierarchy templates, and cascade-delete related connections with count updates', async () => {
    const board = await createBoard(`round2-${Date.now()}`, 'mindmap');
    try {
      const a = await createNode(board.base, board.id, 'A');
      const b = await createNode(board.base, board.id, 'B');
      const c = await createNode(board.base, board.id, 'C');

      // 1. Self-connection should be rejected
      const self = await createConnection(board.base, board.id, a, a);
      expect([400, 409, 422]).toContain(self.res.status);
      expect(JSON.stringify(self.body).toLowerCase()).toMatch(/self|same|cycle|invalid|cannot/);

      // 2. Valid connection A→B
      const ab1 = await createConnection(board.base, board.id, a, b);
      expect([200, 201]).toContain(ab1.res.status);

      // 3. Duplicate connection A→B should be rejected
      const ab2 = await createConnection(board.base, board.id, a, b);
      expect([400, 409, 422]).toContain(ab2.res.status);
      expect(JSON.stringify(ab2.body).toLowerCase()).toMatch(/duplicate|exists|already|invalid/);

      // 4. Valid connection B→C
      const bc = await createConnection(board.base, board.id, b, c);
      expect([200, 201]).toContain(bc.res.status);

      // 5. Cycle C→A should be rejected (mindmap is hierarchical)
      const ca = await createConnection(board.base, board.id, c, a);
      expect([400, 409, 422]).toContain(ca.res.status);
      expect(JSON.stringify(ca.body).toLowerCase()).toMatch(/cycle|loop|invalid|circular/);

      // 6. Verify connections exist before delete
      const beforeDelete = await listConnections(board.base, board.id);
      expect(beforeDelete.length).toBeGreaterThanOrEqual(2);

      // 7. Check upstream/downstream counts for node A and C before deleting B
      const detailABefore = await getNodeDetail(board.base, board.id, a);
      const detailCBefore = await getNodeDetail(board.base, board.id, c);
      // Also try board-level detail for node info
      const boardDetail = await getBoardDetail(board.base, board.id);

      // 8. Delete node B — all connections involving B should be cascade-deleted
      const del = await deleteNode(board.base, board.id, b);
      expect([200, 204]).toContain(del.res.status);

      // 9. Verify connections involving B are removed
      const afterDelete = await listConnections(board.base, board.id);
      const remainingRefB = afterDelete.filter((x: any) => {
        const from = x.fromId || x.fromNodeId || x.source;
        const to = x.toId || x.toNodeId || x.target;
        return [from, to].includes(b);
      });
      expect(remainingRefB.length, `Expected all connections related to deleted node ${b} to be removed`).toBe(0);

      // 10. Verify upstream/downstream counts are updated for remaining nodes
      const detailAAfter = await getNodeDetail(board.base, board.id, a);
      const detailCAfter = await getNodeDetail(board.base, board.id, c);

      if (detailAAfter) {
        const countsA = extractUpstreamDownstream(detailAAfter);
        // After deleting B, A should have 0 downstream (A→B was the only outgoing edge)
        if (countsA.downstream !== null) {
          expect(countsA.downstream, 'Node A downstream count should be 0 after B is deleted').toBe(0);
        }
      }

      if (detailCAfter) {
        const countsC = extractUpstreamDownstream(detailCAfter);
        // After deleting B, C should have 0 upstream (B→C was the only incoming edge)
        if (countsC.upstream !== null) {
          expect(countsC.upstream, 'Node C upstream count should be 0 after B is deleted').toBe(0);
        }
      }

      // If node detail endpoint doesn't expose counts, check via board-level detail
      if (boardDetail && boardDetail.nodes) {
        const boardAfter = await getBoardDetail(board.base, board.id);
        if (boardAfter && boardAfter.nodes) {
          const nodeAInBoard = boardAfter.nodes.find((n: any) => n.id === a);
          const nodeCInBoard = boardAfter.nodes.find((n: any) => n.id === c);
          if (nodeAInBoard) {
            const ca2 = extractUpstreamDownstream(nodeAInBoard);
            if (ca2.downstream !== null) {
              expect(ca2.downstream, 'Node A downstream count from board detail should be 0').toBe(0);
            }
          }
          if (nodeCInBoard) {
            const cc2 = extractUpstreamDownstream(nodeCInBoard);
            if (cc2.upstream !== null) {
              expect(cc2.upstream, 'Node C upstream count from board detail should be 0').toBe(0);
            }
          }
        }
      }
    } finally {
      await tryDeleteBoard(board.base, board.id);
    }
  });
});

import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function request(path: string, options: any = {}) {
  const res = await fetch(`${BASE_URL}${path}`, {
    headers: { 'Content-Type': 'application/json', ...(options.headers || {}) },
    ...options,
  });
  let body: any = null;
  const text = await res.text();
  try {
    body = text ? JSON.parse(text) : null;
  } catch {
    body = text;
  }
  return { res, body };
}

function extractId(body: any): string {
  return body?.id || body?.boardId || body?.data?.id || '';
}

function extractNodeId(body: any): string {
  return body?.id || body?.nodeId || body?.data?.id || '';
}

function extractNodes(body: any): any[] {
  if (Array.isArray(body)) return body;
  if (Array.isArray(body?.nodes)) return body.nodes;
  if (Array.isArray(body?.items)) return body.items;
  if (Array.isArray(body?.data)) return body.data;
  return [];
}

function extractConnections(body: any): any[] {
  if (Array.isArray(body)) return body;
  if (Array.isArray(body?.connections)) return body.connections;
  if (Array.isArray(body?.edges)) return body.edges;
  if (Array.isArray(body?.items)) return body.items;
  if (Array.isArray(body?.data)) return body.data;
  return [];
}

async function safeDeleteBoard(id: string | undefined) {
  if (!id) return;
  try {
    await fetch(`${BASE_URL}/api/boards/${id}`, {
      method: 'DELETE',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ confirm: true }),
    });
  } catch {}
}

describe('board_state_persists_after_refresh', () => {
  it('should persist template, title, nodes, connections, view position, and overview viewport across repeated fetches', async () => {
    let boardId: string | undefined;
    let node1: string | undefined;
    let node2: string | undefined;

    try {
      // Create board with consistent field naming — use 'title' and 'template'
      const { res: createRes, body: createBody } = await request('/api/boards', {
        method: 'POST',
        body: JSON.stringify({ title: 'Persistent Board', template: 'flowchart' }),
      });
      expect([200, 201]).toContain(createRes.status);
      boardId = extractId(createBody);
      expect(boardId).toBeTruthy();

      // Create start node
      const n1 = await request(`/api/boards/${boardId}/nodes`, {
        method: 'POST',
        body: JSON.stringify({ title: 'Start', type: 'start', x: 100, y: 120 }),
      });
      expect([200, 201]).toContain(n1.res.status);
      node1 = extractNodeId(n1.body);
      expect(node1).toBeTruthy();

      // Create end node
      const n2 = await request(`/api/boards/${boardId}/nodes`, {
        method: 'POST',
        body: JSON.stringify({ title: 'End', type: 'end', x: 320, y: 120 }),
      });
      expect([200, 201]).toContain(n2.res.status);
      node2 = extractNodeId(n2.body);
      expect(node2).toBeTruthy();

      // Create connection between nodes
      const connPaths = [
        `/api/boards/${boardId}/connections`,
        `/api/boards/${boardId}/edges`,
      ];
      let connCreated = false;
      for (const connPath of connPaths) {
        const conn = await request(connPath, {
          method: 'POST',
          body: JSON.stringify({ fromNodeId: node1, toNodeId: node2, source: node1, target: node2 }),
        });
        if ([200, 201].includes(conn.res.status)) {
          connCreated = true;
          break;
        }
      }
      expect(connCreated, 'Should be able to create a connection').toBe(true);

      // Update board title and set viewport
      const titleUpdate = await request(`/api/boards/${boardId}`, {
        method: 'PATCH',
        body: JSON.stringify({
          title: 'Persistent Board Renamed',
          viewport: { x: 500, y: 300, zoom: 1.5 },
        }),
      });
      expect([200, 204]).toContain(titleUpdate.res.status);

      // Also try setting viewport via dedicated endpoint
      await request(`/api/boards/${boardId}/viewport`, {
        method: 'PUT',
        body: JSON.stringify({ x: 500, y: 300, zoom: 1.5 }),
      });

      // ---- Simulate refresh: re-fetch board ----
      const { res: firstGetRes, body: firstGetBody } = await request(`/api/boards/${boardId}`);
      expect(firstGetRes.status).toBe(200);

      // Verify title persists (check both 'title' and 'name' fields)
      const persistedTitle = firstGetBody.title || firstGetBody.name;
      expect(persistedTitle, 'Board title should persist after update').toBe('Persistent Board Renamed');

      // Verify template persists
      expect(firstGetBody.template, 'Board template should persist').toBe('flowchart');

      // Verify viewport persists
      const view = firstGetBody.viewport || firstGetBody.view;
      if (view) {
        expect(view.x, 'Viewport x should persist').toBe(500);
        expect(view.y, 'Viewport y should persist').toBe(300);
        expect(view.zoom, 'Viewport zoom should persist').toBe(1.5);
      }

      // Verify nodes persist
      const { res: nodesRes, body: nodesBody } = await request(`/api/boards/${boardId}/nodes`);
      expect(nodesRes.status).toBe(200);
      const nodeList = extractNodes(nodesBody);
      expect(nodeList.length, 'Board should have at least 2 nodes after refresh').toBeGreaterThanOrEqual(2);

      const startNode = nodeList.find((n: any) => n.id === node1);
      const endNode = nodeList.find((n: any) => n.id === node2);
      expect(startNode, 'Start node should persist after refresh').toBeTruthy();
      expect(endNode, 'End node should persist after refresh').toBeTruthy();
      expect(startNode.title || startNode.label || startNode.text).toBe('Start');
      expect(endNode.title || endNode.label || endNode.text).toBe('End');

      // Verify connections persist
      const connGetPaths = [
        `/api/boards/${boardId}/connections`,
        `/api/boards/${boardId}/edges`,
      ];
      for (const connPath of connGetPaths) {
        const { res: connsRes, body: connsBody } = await request(connPath);
        if (connsRes.status === 200) {
          const connections = extractConnections(connsBody);
          expect(connections.length, 'Board should retain connections after refresh').toBeGreaterThanOrEqual(1);
          break;
        }
      }

      // ---- Second fetch to verify stability ----
      const { res: secondGetRes, body: secondGetBody } = await request(`/api/boards/${boardId}`);
      expect(secondGetRes.status).toBe(200);
      const secondTitle = secondGetBody.title || secondGetBody.name;
      expect(secondTitle, 'Title should remain stable across repeated fetches').toBe(persistedTitle);
      expect(secondGetBody.template, 'Template should remain stable across repeated fetches').toBe('flowchart');

      const secondView = secondGetBody.viewport || secondGetBody.view;
      if (view && secondView) {
        expect(secondView, 'Viewport should remain stable across repeated fetches').toEqual(view);
      }
    } finally {
      await safeDeleteBoard(boardId);
    }
  });
});

