describe('round19_tags_filter_and_io_compatibility', () => {
  it('should support tag limits, boundary validations, multi-tag filtering, zero-match scenario, and preserve tags during import/export including old files', async () => {
    let boardId: string | undefined;
    let importedBoardId: string | undefined;
    let oldImportedBoardId: string | undefined;
    try {
      // Create a board
      const createBoard = await http('/api/boards', {
        method: 'POST',
        body: JSON.stringify({ title: `vitest-round19-${Date.now()}`, template: 'flowchart' }),
      });
      expect([200, 201]).toContain(createBoard.res.status);
      boardId = createBoard.body.id || createBoard.body.boardId;
      expect(boardId).toBeTruthy();

      // Create nodes with tags
      const createNodeA = await http(`/api/boards/${boardId}/nodes`, {
        method: 'POST',
        body: JSON.stringify({ title: 'Node A', label: 'Node A', text: 'Node A', x: 10, y: 10, tags: ['alpha', 'beta'] }),
      });
      const createNodeB = await http(`/api/boards/${boardId}/nodes`, {
        method: 'POST',
        body: JSON.stringify({ title: 'Node B', label: 'Node B', text: 'Node B', x: 20, y: 20, tags: ['alpha', 'gamma'] }),
      });
      const createNodeC = await http(`/api/boards/${boardId}/nodes`, {
        method: 'POST',
        body: JSON.stringify({ title: 'Node C', label: 'Node C', text: 'Node C', x: 30, y: 30, tags: ['beta', 'gamma'] }),
      });

      expect([200, 201]).toContain(createNodeA.res.status);
      expect([200, 201]).toContain(createNodeB.res.status);
      expect([200, 201]).toContain(createNodeC.res.status);

      const nodeAId = createNodeA.body.id || createNodeA.body.nodeId;
      expect(nodeAId).toBeTruthy();

      // Verify tags are returned
      const aTags = createNodeA.body.tags;
      if (aTags) {
        expect(aTags).toEqual(expect.arrayContaining(['alpha', 'beta']));
      }

      // === Boundary: >5 tags should be rejected ===
      const createOverLimit = await http(`/api/boards/${boardId}/nodes`, {
        method: 'POST',
        body: JSON.stringify({
          title: 'Over limit tags', label: 'Over limit tags', text: 'Over limit tags',
          x: 40, y: 40,
          tags: ['t1', 't2', 't3', 't4', 't5', 't6'],
        }),
      });
      expect([400, 409, 422], `creating node with >5 tags should fail, got ${createOverLimit.res.status}`).toContain(createOverLimit.res.status);

      // === Boundary: Empty/whitespace-only tag name should be rejected ===
      const createEmptyTag = await http(`/api/boards/${boardId}/nodes`, {
        method: 'POST',
        body: JSON.stringify({
          title: 'Empty tag node', label: 'Empty tag node', text: 'Empty tag node',
          x: 50, y: 50,
          tags: ['   '],
        }),
      });
      expect([400, 409, 422], `creating node with whitespace-only tag should fail, got ${createEmptyTag.res.status}`).toContain(createEmptyTag.res.status);

      // === Boundary: Tag longer than 20 characters should be rejected ===
      const longTag = 'a'.repeat(21);
      const createLongTag = await http(`/api/boards/${boardId}/nodes`, {
        method: 'POST',
        body: JSON.stringify({
          title: 'Long tag node', label: 'Long tag node', text: 'Long tag node',
          x: 60, y: 60,
          tags: [longTag],
        }),
      });
      expect([400, 409, 422], `creating node with >20 char tag should fail, got ${createLongTag.res.status}`).toContain(createLongTag.res.status);

      // === Boundary: Case-insensitive duplicate tags should be rejected/deduplicated ===
      const createDupCaseTag = await http(`/api/boards/${boardId}/nodes`, {
        method: 'POST',
        body: JSON.stringify({
          title: 'Dup case tag', label: 'Dup case tag', text: 'Dup case tag',
          x: 70, y: 70,
          tags: ['Alpha', 'ALPHA'],
        }),
      });
      if ([200, 201].includes(createDupCaseTag.res.status)) {
        // If accepted, tags should be deduplicated (only one variant)
        const dupTags = createDupCaseTag.body.tags || [];
        const normalized = dupTags.map((t: string) => t.toLowerCase());
        const uniqueNormalized = [...new Set(normalized)];
        expect(uniqueNormalized.length, 'case-insensitive duplicate tags should be deduplicated').toBe(1);
        // Cleanup
        const dupNodeId = createDupCaseTag.body.id || createDupCaseTag.body.nodeId;
        if (dupNodeId) {
          await http(`/api/boards/${boardId}/nodes/${dupNodeId}`, { method: 'DELETE' });
        }
      } else {
        // Rejection is also acceptable
        expect([400, 409, 422]).toContain(createDupCaseTag.res.status);
      }

      // === Filter: alpha+beta (AND) should match only Node A ===
      const filteredAlphaBeta = await http(`/api/boards/${boardId}/nodes?tags=alpha,beta`);
      expect(filteredAlphaBeta.res.status).toBe(200);
      const alphaBetaNodes = Array.isArray(filteredAlphaBeta.body)
        ? filteredAlphaBeta.body
        : (filteredAlphaBeta.body.nodes || filteredAlphaBeta.body.items || filteredAlphaBeta.body.data || []);
      expect(Array.isArray(alphaBetaNodes)).toBe(true);
      expect(alphaBetaNodes.length, `alpha+beta AND filter should match exactly one node`).toBe(1);
      const matchedTitle = alphaBetaNodes[0].title || alphaBetaNodes[0].label || alphaBetaNodes[0].text;
      expect(matchedTitle).toBe('Node A');

      // === Filter: gamma should match Node B and Node C ===
      const filteredGamma = await http(`/api/boards/${boardId}/nodes?tags=gamma`);
      expect(filteredGamma.res.status).toBe(200);
      const gammaNodes = Array.isArray(filteredGamma.body)
        ? filteredGamma.body
        : (filteredGamma.body.nodes || filteredGamma.body.items || filteredGamma.body.data || []);
      expect(Array.isArray(gammaNodes)).toBe(true);
      expect(gammaNodes.length).toBe(2);

      // === Zero-match filter: nonexistent tag should return empty array, not error ===
      const filteredNone = await http(`/api/boards/${boardId}/nodes?tags=nonexistent_tag_xyz`);
      expect(filteredNone.res.status).toBe(200);
      const noneNodes = Array.isArray(filteredNone.body)
        ? filteredNone.body
        : (filteredNone.body.nodes || filteredNone.body.items || filteredNone.body.data || []);
      expect(Array.isArray(noneNodes)).toBe(true);
      expect(noneNodes.length, 'zero-match filter should return empty result').toBe(0);

      // === Filter summary / result count ===
      const countRes = await http(`/api/boards/${boardId}/filters/summary?tags=alpha,beta`);
      if (countRes.res.status === 200 && countRes.body && typeof countRes.body === 'object') {
        const resultCount = countRes.body.resultCount ?? countRes.body.count ?? countRes.body.total;
        if (resultCount !== undefined) {
          expect(resultCount).toBe(1);
        }
      }

      // === Search within filter ===
      const searchWithinFilter = await http(`/api/boards/${boardId}/search?q=Node&tags=alpha,beta`);
      if (searchWithinFilter.res.status === 200) {
        const searchResults = Array.isArray(searchWithinFilter.body)
          ? searchWithinFilter.body
          : (searchWithinFilter.body.results || searchWithinFilter.body.nodes || searchWithinFilter.body.items || searchWithinFilter.body.data || []);
        expect(Array.isArray(searchResults)).toBe(true);
        expect(searchResults.length).toBe(1);
        const searchTitle = searchResults[0].title || searchResults[0].label || searchResults[0].text;
        expect(searchTitle).toBe('Node A');
      }

      // === Export and verify tags are included ===
      const exportRes = await http(`/api/boards/${boardId}/export`);
      expect(exportRes.res.status).toBe(200);
      expect(exportRes.body).toBeTruthy();
      const exportedNodes = exportRes.body.nodes || exportRes.body.data?.nodes || [];
      expect(Array.isArray(exportedNodes)).toBe(true);
      const exportedA = exportedNodes.find((n: any) => (n.title || n.label || n.text) === 'Node A');
      expect(exportedA, 'exported data should contain Node A').toBeTruthy();
      if (exportedA?.tags) {
        expect(exportedA.tags).toEqual(expect.arrayContaining(['alpha', 'beta']));
      }

      // === Import exported data and verify tags preserved ===
      const importRes = await http('/api/boards/import', {
        method: 'POST',
        body: JSON.stringify(exportRes.body),
      });
      expect([200, 201], `import exported board should succeed`).toContain(importRes.res.status);
      importedBoardId = importRes.body.id || importRes.body.boardId;
      expect(importedBoardId).toBeTruthy();

      const importedNodes = await http(`/api/boards/${importedBoardId}/nodes?tags=alpha,beta`);
      expect(importedNodes.res.status).toBe(200);
      const importedNodeList = Array.isArray(importedNodes.body)
        ? importedNodes.body
        : (importedNodes.body.nodes || importedNodes.body.items || importedNodes.body.data || []);
      expect(importedNodeList.length).toBe(1);
      const importedTitle = importedNodeList[0].title || importedNodeList[0].label || importedNodeList[0].text;
      expect(importedTitle).toBe('Node A');

      // === Import legacy data without tags — should succeed and give empty tags array ===
      const legacyPayload = {
        title: 'legacy-without-tags',
        template: 'mindmap',
        nodes: [
          { id: 'legacy-node-1', title: 'Legacy node', label: 'Legacy node', text: 'Legacy node', x: 1, y: 2 },
        ],
        edges: [],
      };
      const importLegacy = await http('/api/boards/import', {
        method: 'POST',
        body: JSON.stringify(legacyPayload),
      });
      expect([200, 201], `legacy import should succeed`).toContain(importLegacy.res.status);
      oldImportedBoardId = importLegacy.body.id || importLegacy.body.boardId;
      expect(oldImportedBoardId).toBeTruthy();

      const legacyNodes = await http(`/api/boards/${oldImportedBoardId}/nodes`);
      expect(legacyNodes.res.status).toBe(200);
      const legacyNodeList = Array.isArray(legacyNodes.body)
        ? legacyNodes.body
        : (legacyNodes.body.nodes || legacyNodes.body.items || legacyNodes.body.data || []);
      expect(legacyNodeList.length).toBeGreaterThanOrEqual(1);
      const legacyNode = legacyNodeList.find((n: any) => (n.title || n.label || n.text) === 'Legacy node');
      expect(legacyNode, 'legacy node should exist after import').toBeTruthy();
      if (legacyNode) {
        // Tags should default to empty array
        const legTags = legacyNode.tags;
        if (legTags !== undefined) {
          expect(Array.isArray(legTags), `legacy imported node should get default tags array`).toBe(true);
          expect(legTags.length).toBe(0);
        }
      }
    } finally {
      await safeCleanup(boardId!);
      await safeCleanup(importedBoardId!);
      await safeCleanup(oldImportedBoardId!);
    }
  });
});

import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function request(path, options = {}) {
  const res = await fetch(`${BASE_URL}${path}`, {
    headers: { 'Content-Type': 'application/json', ...(options.headers || {}) },
    ...options,
  });
  let body = null;
  const text = await res.text();
  try {
    body = text ? JSON.parse(text) : null;
  } catch {
    body = text;
  }
  return { res, body };
}

async function safeDeleteBoard(id) {
  if (!id) return;
  try {
    await fetch(`${BASE_URL}/boards/${id}`, { method: 'DELETE' });
  } catch {}
}

