import { describe, it, expect, afterAll } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function http(path: string, options: any = {}) {
  const res = await fetch(`${BASE_URL}${path}`, {
    headers: {
      'Content-Type': 'application/json',
      ...(options.headers || {}),
    },
    ...options,
  });
  const contentType = res.headers.get('content-type') || '';
  let body: any;
  if (contentType.includes('application/json')) {
    body = await res.json();
  } else {
    const text = await res.text();
    try { body = text ? JSON.parse(text) : null; } catch { body = text; }
  }
  return { res, body };
}

function extractId(body: any): string {
  return body?.id || body?.boardId || body?.data?.id || '';
}

function extractNodeId(body: any): string {
  return body?.id || body?.nodeId || body?.data?.id || '';
}

function extractBoards(body: any): any[] {
  if (Array.isArray(body)) return body;
  if (Array.isArray(body?.boards)) return body.boards;
  if (Array.isArray(body?.items)) return body.items;
  if (Array.isArray(body?.data)) return body.data;
  return [];
}

function extractNodes(body: any): any[] {
  if (Array.isArray(body)) return body;
  if (Array.isArray(body?.nodes)) return body.nodes;
  if (Array.isArray(body?.items)) return body.items;
  if (Array.isArray(body?.data)) return body.data;
  return [];
}

function extractSteps(body: any): any[] {
  if (Array.isArray(body)) return body;
  if (Array.isArray(body?.steps)) return body.steps;
  if (Array.isArray(body?.items)) return body.items;
  if (Array.isArray(body?.data)) return body.data;
  return [];
}

async function safeCleanup(boardId: string | undefined) {
  if (!boardId) return;
  try {
    await fetch(`${BASE_URL}/api/boards/${boardId}`, {
      method: 'DELETE',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ confirm: true }),
    });
  } catch {}
}

function getBoardTimestamp(board: any): string | number | undefined {
  return board?.updatedAt || board?.lastModifiedAt || board?.modifiedAt;
}

function getCollaboratorCount(board: any): number | undefined {
  return board?.collaboratorCount ?? board?.collaborators ?? board?.participantCount ?? board?.participants;
}

describe('round27_board_list_and_board_state_persistence', () => {
  const cleanupIds: string[] = [];

  afterAll(async () => {
    for (const id of cleanupIds) {
      await safeCleanup(id);
    }
  });

  it('should create boards, manage them from list view, and verify list summary updates after edits', async () => {
    // --- Create board A ---
    const titleA = `vitest-r27-A-${Date.now()}`;
    const createA = await http('/api/boards', {
      method: 'POST',
      body: JSON.stringify({ title: titleA, template: 'mindmap' }),
    });
    expect([200, 201]).toContain(createA.res.status);
    const boardA = extractId(createA.body);
    expect(boardA).toBeTruthy();
    cleanupIds.push(boardA);

    // --- Create board B ---
    const titleB = `vitest-r27-B-${Date.now()}`;
    const createB = await http('/api/boards', {
      method: 'POST',
      body: JSON.stringify({ title: titleB, template: 'flowchart' }),
    });
    expect([200, 201]).toContain(createB.res.status);
    const boardB = extractId(createB.body);
    expect(boardB).toBeTruthy();
    cleanupIds.push(boardB);

    // --- Rename board A ---
    const renameA = await http(`/api/boards/${boardA}`, {
      method: 'PATCH',
      body: JSON.stringify({ title: 'Board A Renamed' }),
    });
    expect([200, 204]).toContain(renameA.res.status);

    // --- List boards and verify basic summary ---
    const listRes = await http('/api/boards');
    expect(listRes.res.status).toBe(200);
    const boards = extractBoards(listRes.body);
    expect(boards.length).toBeGreaterThanOrEqual(2);

    const boardASummary = boards.find((b: any) => b.id === boardA);
    expect(boardASummary, 'Board A should appear in list').toBeTruthy();
    expect(boardASummary.title || boardASummary.name).toBe('Board A Renamed');
    expect(boardASummary.template).toBe('mindmap');

    // Verify modification timestamp exists
    const tsBeforeEdit = getBoardTimestamp(boardASummary);
    expect(tsBeforeEdit, 'Board list item should include modified timestamp').toBeTruthy();

    // Verify collaborator count field exists and is reasonable
    const collabCount = getCollaboratorCount(boardASummary);
    if (collabCount !== undefined) {
      expect(typeof collabCount).toBe('number');
      expect(collabCount).toBeGreaterThanOrEqual(0);
    }

    // --- Validate invalid titles ---
    // Empty title
    const emptyTitle = await http('/api/boards', {
      method: 'POST',
      body: JSON.stringify({ title: '', template: 'mindmap' }),
    });
    expect(
      [400, 409, 422].includes(emptyTitle.res.status),
      `Empty title should be rejected, got ${emptyTitle.res.status}`,
    ).toBe(true);

    // Whitespace-only title
    const whitespaceTitle = await http('/api/boards', {
      method: 'POST',
      body: JSON.stringify({ title: '   ', template: 'mindmap' }),
    });
    expect(
      [400, 409, 422].includes(whitespaceTitle.res.status),
      `Whitespace-only title should be rejected, got ${whitespaceTitle.res.status}`,
    ).toBe(true);

    // Title exceeding 40 characters
    const longTitle = 'A'.repeat(41);
    const longTitleRes = await http('/api/boards', {
      method: 'POST',
      body: JSON.stringify({ title: longTitle, template: 'mindmap' }),
    });
    expect(
      [400, 409, 422].includes(longTitleRes.res.status),
      `Title > 40 chars should be rejected, got ${longTitleRes.res.status}`,
    ).toBe(true);

    // Rename to empty should also be rejected
    const renameEmpty = await http(`/api/boards/${boardA}`, {
      method: 'PATCH',
      body: JSON.stringify({ title: '' }),
    });
    expect(
      [400, 409, 422].includes(renameEmpty.res.status),
      `Rename to empty title should be rejected, got ${renameEmpty.res.status}`,
    ).toBe(true);

    // --- Copy board A ---
    const copyRes = await http(`/api/boards/${boardA}/copy`, { method: 'POST' });
    expect([200, 201]).toContain(copyRes.res.status);
    const copiedBoard = extractId(copyRes.body);
    expect(copiedBoard).toBeTruthy();
    expect(copiedBoard).not.toBe(boardA);
    cleanupIds.push(copiedBoard);

    // Verify the copied board has a distinguished name
    const copiedDetail = await http(`/api/boards/${copiedBoard}`);
    expect(copiedDetail.res.status).toBe(200);
    const copiedTitle = copiedDetail.body.title || copiedDetail.body.name || '';
    expect(copiedTitle).toBeTruthy();
    expect(
      copiedTitle !== 'Board A Renamed',
      `Copied board title should differ from original. Original: 'Board A Renamed', Copy: '${copiedTitle}'`,
    ).toBe(true);

    // --- Delete board B with confirmation ---
    const deleteNoConfirm = await http(`/api/boards/${boardB}`, { method: 'DELETE' });
    if ([400, 409, 422].includes(deleteNoConfirm.res.status)) {
      const deleteWithConfirm = await http(`/api/boards/${boardB}`, {
        method: 'DELETE',
        body: JSON.stringify({ confirm: true }),
      });
      expect([200, 204]).toContain(deleteWithConfirm.res.status);
    } else {
      expect([200, 204]).toContain(deleteNoConfirm.res.status);
    }

    // Verify boardB is gone from list
    const listAfterDel = await http('/api/boards');
    expect(listAfterDel.res.status).toBe(200);
    const boardsAfterDel = extractBoards(listAfterDel.body);
    expect(
      boardsAfterDel.find((b: any) => b.id === boardB),
      'Deleted board should not remain in list',
    ).toBeFalsy();
    // Remove boardB from cleanup since already deleted
    const bIdx = cleanupIds.indexOf(boardB);
    if (bIdx >= 0) cleanupIds.splice(bIdx, 1);

    // --- Persist state on board A: add node with tags ---
    // Small delay to ensure timestamp difference
    await new Promise(r => setTimeout(r, 100));

    const nodeRes = await http(`/api/boards/${boardA}/nodes`, {
      method: 'POST',
      body: JSON.stringify({ title: 'Persistent Node', x: 100, y: 100 }),
    });
    expect([200, 201]).toContain(nodeRes.res.status);
    const nodeId = extractNodeId(nodeRes.body);
    expect(nodeId).toBeTruthy();

    // Add tags to node (try dedicated tag endpoint, then fallback to node PATCH with tags)
    const tagRes = await http(`/api/boards/${boardA}/nodes/${nodeId}/tags`, {
      method: 'POST',
      body: JSON.stringify({ tags: ['keep', 'boardA'] }),
