import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function request(path: string, options: any = {}) {
  const res = await fetch(`${BASE_URL}${path}`, {
    headers: { 'Content-Type': 'application/json', ...(options.headers || {}) },
    ...options,
  });
  let body = null;
  const text = await res.text();
  try {
    body = text ? JSON.parse(text) : null;
  } catch {
    body = text;
  }
  return { res, body };
}

async function tryPaths(method: string, paths: string[], payload?: any) {
  for (const path of paths) {
    const out = await request(path, {
      method,
      ...(payload !== undefined ? { body: JSON.stringify(payload) } : {}),
    });
    if (out.res.status !== 404 && out.res.status !== 405) return { ...out, usedPath: path };
  }
  throw new Error(`No working endpoint among: ${paths.join(', ')}`);
}

async function safeDeleteBoard(id: string) {
  if (!id) return;
  try { await fetch(`${BASE_URL}/api/boards/${id}`, { method: 'DELETE' }); } catch {}
  try { await fetch(`${BASE_URL}/boards/${id}`, { method: 'DELETE' }); } catch {}
}

async function createBoard(title: string, template: string) {
  const out = await tryPaths('POST', ['/api/boards', '/boards'], { title, template });
  expect([200, 201]).toContain(out.res.status);
  const id = out.body?.id || out.body?.data?.id || out.body?.boardId;
  expect(id).toBeTruthy();
  return id;
}

async function createNode(boardId: string, title: string, type?: string) {
  const payload: any = { title, boardId };
  if (type) payload.type = type;
  const out = await tryPaths('POST', [`/api/boards/${boardId}/nodes`, `/boards/${boardId}/nodes`], payload);
  expect([200, 201]).toContain(out.res.status);
  const id = out.body?.id || out.body?.data?.id;
  expect(id).toBeTruthy();
  return id;
}

async function createConnection(boardId: string, fromId: string, toId: string) {
  // Try multiple field name combinations
  const payload = { fromId, toId, fromNodeId: fromId, toNodeId: toId, source: fromId, target: toId, boardId };
  return tryPaths('POST', [`/api/boards/${boardId}/connections`, `/boards/${boardId}/connections`], payload);
}

async function getConnections(boardId: string) {
  const out = await tryPaths('GET', [`/api/boards/${boardId}/connections`, `/boards/${boardId}/connections`]);
  const conns = Array.isArray(out.body) ? out.body : (out.body?.connections || out.body?.edges || out.body?.data || []);
  return conns;
}

describe('create_connection_rejects_self_duplicate_cycle', () => {
  it('should reject self-connections, duplicate connections, and cycles in mindmap boards', async () => {
    let boardId: string | undefined;

    try {
      boardId = await createBoard(`conn-mindmap-${Date.now()}`, 'mindmap');

      const nodeA = await createNode(boardId, 'Node A');
      const nodeB = await createNode(boardId, 'Node B');
      const nodeC = await createNode(boardId, 'Node C');

      // Self-connection should be rejected
      const selfConn = await createConnection(boardId, nodeA, nodeA);
      expect([400, 409, 422]).toContain(selfConn.res.status);

      // First A->B connection should succeed
      const connAB = await createConnection(boardId, nodeA, nodeB);
      expect([200, 201]).toContain(connAB.res.status);

      // Duplicate A->B connection should be rejected
      const dupAB = await createConnection(boardId, nodeA, nodeB);
      expect([400, 409, 422]).toContain(dupAB.res.status);

      // B->C connection should succeed
      const connBC = await createConnection(boardId, nodeB, nodeC);
      expect([200, 201]).toContain(connBC.res.status);

      // C->A cycle should be rejected in mindmap
      const cycleCA = await createConnection(boardId, nodeC, nodeA);
      expect([400, 409, 422]).toContain(cycleCA.res.status);

      // Verify persisted connections
      const conns = await getConnections(boardId);
      expect(Array.isArray(conns)).toBe(true);

      // Should have exactly 2 valid connections (A->B and B->C)
      expect(conns.length).toBe(2);

      // Self and cycle connections should not exist
      const hasself = conns.some((c: any) => {
        const from = c.fromId || c.fromNodeId || c.source;
        const to = c.toId || c.toNodeId || c.target;
        return from === nodeA && to === nodeA;
      });
      expect(hasself, 'self-connection should not be persisted').toBe(false);

      const hasCycle = conns.some((c: any) => {
        const from = c.fromId || c.fromNodeId || c.source;
        const to = c.toId || c.toNodeId || c.target;
        return from === nodeC && to === nodeA;
      });
      expect(hasCycle, 'cycle connection should not be persisted').toBe(false);
    } finally {
      if (boardId) await safeDeleteBoard(boardId);
    }
  });

  it('should reject cycles in fishbone boards as well', async () => {
    let boardId: string | undefined;

    try {
      boardId = await createBoard(`conn-fishbone-${Date.now()}`, 'fishbone');

      const nodeA = await createNode(boardId, 'Cause A');
      const nodeB = await createNode(boardId, 'Cause B');
      const nodeC = await createNode(boardId, 'Cause C');

      // Self-connection rejected
      const selfConn = await createConnection(boardId, nodeA, nodeA);
      expect([400, 409, 422]).toContain(selfConn.res.status);

      // Build chain A->B->C
      const connAB = await createConnection(boardId, nodeA, nodeB);
      expect([200, 201]).toContain(connAB.res.status);

      const connBC = await createConnection(boardId, nodeB, nodeC);
      expect([200, 201]).toContain(connBC.res.status);

      // C->A cycle should be rejected in fishbone
      const cycleCA = await createConnection(boardId, nodeC, nodeA);
      expect([400, 409, 422]).toContain(cycleCA.res.status);

      // Duplicate A->B should be rejected
      const dupAB = await createConnection(boardId, nodeA, nodeB);
      expect([400, 409, 422]).toContain(dupAB.res.status);

      // Verify only valid connections persisted
      const conns = await getConnections(boardId);
      expect(conns.length).toBe(2);
    } finally {
      if (boardId) await safeDeleteBoard(boardId);
    }
  });
});

