describe('round13_batch_operations_with_protection', () => {
  it('should support batch move/highlight, expose rich selection summary, reject protected-node batch delete with details, preserve titles after highlight, and update linked areas', async () => {
    let boardId;
    try {
      // Create a mindmap board with root + 2 child nodes
      const created = await request('/api/boards', {
        method: 'POST',
        body: JSON.stringify({
          title: `batch-ops-${Date.now()}`,
