            ],
            edges: [
              { source: 'root', target: 'n1' },
              { source: 'root', target: 'n2' }
            ]
          }
        })
      });
      expect([200, 201]).toContain(created.res.status);
      boardId = created.body.id || created.body.boardId;
      expect(boardId).toBeTruthy();

      // --- Multi-select all 3 nodes ---
      const select = await request(`/api/boards/${boardId}/selection`, {
        method: 'PUT',
        body: JSON.stringify({ nodeIds: ['root', 'n1', 'n2'] })
      });
      expect([200, 201]).toContain(select.res.status);

      // --- Verify selection summary includes count, mixed types, available actions ---
      const summary = await request(`/api/boards/${boardId}/selection`);
      expect(summary.res.status).toBe(200);
      const selBody = summary.body;
      const selCount = selBody.count ?? (selBody.nodeIds || []).length;
      expect(selCount).toBe(3);
      // Check mixed types indication
      const hasMixedTypes = selBody.mixedTypes ?? selBody.hasMixedTypes ?? selBody.containsDifferentTypes;
      expect(hasMixedTypes).toBeDefined();
      // Check available actions listing
      const availableActions = selBody.availableActions ?? selBody.actions ?? selBody.available;
      expect(availableActions).toBeDefined();

      // --- Batch move ---
      const move = await request(`/api/boards/${boardId}/batch/move`, {
        method: 'POST',
        body: JSON.stringify({ nodeIds: ['n1', 'n2'], dx: 30, dy: 40 })
      });
      expect([200, 201]).toContain(move.res.status);

      // --- Batch highlight ---
      const highlight = await request(`/api/boards/${boardId}/batch/highlight`, {
        method: 'POST',
        body: JSON.stringify({ nodeIds: ['n1', 'n2'], highlighted: true })
      });
      expect([200, 201]).toContain(highlight.res.status);

      // --- Verify move, highlight, AND that titles are preserved ---
      const fetched = await request(`/api/boards/${boardId}`);
      expect(fetched.res.status).toBe(200);
      const nodes = fetched.body.nodes || fetched.body.data?.nodes || [];
      const n1 = nodes.find(n => n.id === 'n1');
      const n2 = nodes.find(n => n.id === 'n2');
      expect(n1).toBeTruthy();
      expect(n2).toBeTruthy();
      // Positions updated
      expect((n1.x ?? n1.position?.x)).toBeGreaterThanOrEqual(40);
      expect((n2.y ?? n2.position?.y)).toBeGreaterThanOrEqual(60);
      // Highlighted
      expect(n1.highlighted ?? n1.style?.highlighted).toBe(true);
      expect(n2.highlighted ?? n2.style?.highlighted).toBe(true);
      // Titles preserved after highlight (must not be affected)
      const n1Title = n1.label ?? n1.title ?? n1.name;
      const n2Title = n2.label ?? n2.title ?? n2.name;
      expect(n1Title).toBe('ChildA');
      expect(n2Title).toBe('ChildB');

      // --- Verify linked areas update: node count ---
      const boardState = fetched.body;
      const nodeCount = boardState.nodeCount ?? (boardState.nodes || boardState.data?.nodes || []).length;
      expect(nodeCount).toBe(3);

      // --- Verify linked areas update: recent activity ---
      const activityRes = await request(`/api/boards/${boardId}/activities`);
      if (activityRes.res.ok) {
        const activities = activityRes.body.items || activityRes.body.activities || activityRes.body;
        if (Array.isArray(activities) && activities.length > 0) {
          const activityText = JSON.stringify(activities).toLowerCase();
          expect(activityText).toMatch(/highlight|batch|move/);
        }
      }

      // --- Undo highlight (should be undoable) ---
      const undoHighlight = await request(`/api/boards/${boardId}/history/undo`, { method: 'POST' });
      expect([200, 201]).toContain(undoHighlight.res.status);
      const afterUndo = await request(`/api/boards/${boardId}`);
      expect(afterUndo.res.status).toBe(200);
      const nodesAfterUndo = afterUndo.body.nodes || afterUndo.body.data?.nodes || [];
      const n1AfterUndo = nodesAfterUndo.find(n => n.id === 'n1');
      expect(n1AfterUndo.highlighted ?? n1AfterUndo.style?.highlighted ?? false).toBe(false);
      // Title still intact after undo
      expect(n1AfterUndo.label ?? n1AfterUndo.title ?? n1AfterUndo.name).toBe('ChildA');

      // --- Batch delete including protected root node: must be clearly rejected ---
      const batchDeleteProtected = await request(`/api/boards/${boardId}/batch/delete`, {
        method: 'POST',
        body: JSON.stringify({ nodeIds: ['root', 'n1', 'n2'] })
      });
      expect([400, 409, 422]).toContain(batchDeleteProtected.res.status);
      const deleteMsg = JSON.stringify(batchDeleteProtected.body).toLowerCase();
      expect(typeof deleteMsg).toBe('string');
      // Must mention which node(s) are protected and why
      expect(deleteMsg).toMatch(/root|protected|cannot|delete/);

      // All nodes must still exist after rejected batch delete
      const afterDeleteAttempt = await request(`/api/boards/${boardId}`);
      expect(afterDeleteAttempt.res.status).toBe(200);
      const idsAfter = (afterDeleteAttempt.body.nodes || afterDeleteAttempt.body.data?.nodes || []).map(n => n.id);
      expect(idsAfter).toEqual(expect.arrayContaining(['root', 'n1', 'n2']));
    } finally {
      await safeDeleteBoard(boardId);
    }
  });

  it('should reject selecting more than 50 nodes', async () => {
    let boardId;
    try {
      // Build a board with 51 child nodes + root = 52 nodes
      const nodesList = [{ id: 'root', label: 'Root', type: 'root', x: 0, y: 0 }];
      const edgesList = [];
      for (let i = 1; i <= 51; i++) {
        const nodeId = `n${i}`;
        nodesList.push({ id: nodeId, label: `Node ${i}`, type: 'child', x: i * 5, y: i * 5 });
        edgesList.push({ source: 'root', target: nodeId });
      }

      const created = await request('/api/boards', {
        method: 'POST',
        body: JSON.stringify({
          title: `batch-limit-${Date.now()}`,
          template: 'mindmap',
          data: { nodes: nodesList, edges: edgesList }
        })
      });
      expect([200, 201]).toContain(created.res.status);
      boardId = created.body.id || created.body.boardId;
      expect(boardId).toBeTruthy();

      // Try to select all 52 nodes (exceeds 50 limit)
      const allIds = nodesList.map(n => n.id);
      expect(allIds.length).toBeGreaterThan(50);

      const selectOver = await request(`/api/boards/${boardId}/selection`, {
        method: 'PUT',
        body: JSON.stringify({ nodeIds: allIds })
      });

      // Should either reject with 4xx or truncate to 50
      if (selectOver.res.ok) {
        // If accepted, verify it was truncated to at most 50
        const checkSel = await request(`/api/boards/${boardId}/selection`);
        expect(checkSel.res.status).toBe(200);
        const cnt = checkSel.body.count ?? (checkSel.body.nodeIds || []).length;
        expect(cnt).toBeLessThanOrEqual(50);
      } else {
        expect([400, 409, 422]).toContain(selectOver.res.status);
        const msg = JSON.stringify(selectOver.body).toLowerCase();
        expect(msg).toMatch(/50|limit|maximum|exceed|too many/);
      }
    } finally {
      await safeDeleteBoard(boardId);
    }
  });
});

