describe('flowchart_node_type_constraints_enforced', () => {
  it('should support basic flowchart node types, reject second start node, reject deleting sole end node, and persist branch labels for decision nodes', async () => {
    let boardId: string | undefined;

    try {
      // Create a flowchart board using consistent field names (title, template)
      const { res: createBoardRes, body: createBoardBody } = await request('/api/boards', {
        method: 'POST',
        body: JSON.stringify({ title: 'Flowchart Constraint Board', template: 'flowchart' }),
      });
      expect([200, 201]).toContain(createBoardRes.status);
      boardId = createBoardBody.id || createBoardBody.boardId;
      expect(boardId).toBeTruthy();

      // Create start node
      const { res: startRes, body: startBody } = await request(`/api/boards/${boardId}/nodes`, {
        method: 'POST',
        body: JSON.stringify({ title: 'Start', label: 'Start', type: 'start' }),
      });
      expect([200, 201], `start node creation should succeed, got ${startRes.status}`).toContain(startRes.status);
      const startType = startBody.type || startBody.nodeType;
      expect(startType, `start node type should be 'start'`).toBe('start');
      const startId = startBody.id || startBody.nodeId;
      expect(startId).toBeTruthy();

      // Create step node
      const { res: stepRes, body: stepBody } = await request(`/api/boards/${boardId}/nodes`, {
        method: 'POST',
        body: JSON.stringify({ title: 'Step 1', label: 'Step 1', type: 'step' }),
      });
      expect([200, 201], `step node creation should succeed, got ${stepRes.status}`).toContain(stepRes.status);
      const stepType = stepBody.type || stepBody.nodeType;
      expect(stepType, `step node type should be 'step'`).toBe('step');
      const stepId = stepBody.id || stepBody.nodeId;
      expect(stepId).toBeTruthy();

      // Create decision node
      const { res: decisionRes, body: decisionBody } = await request(`/api/boards/${boardId}/nodes`, {
        method: 'POST',
        body: JSON.stringify({ title: 'Approve?', label: 'Approve?', type: 'decision' }),
      });
      expect([200, 201], `decision node creation should succeed, got ${decisionRes.status}`).toContain(decisionRes.status);
      const decisionType = decisionBody.type || decisionBody.nodeType;
      expect(decisionType, `decision node type should be 'decision'`).toBe('decision');
      const decisionId = decisionBody.id || decisionBody.nodeId;
      expect(decisionId).toBeTruthy();

      // Create end node
      const { res: endRes, body: endBody } = await request(`/api/boards/${boardId}/nodes`, {
        method: 'POST',
        body: JSON.stringify({ title: 'End', label: 'End', type: 'end' }),
      });
      expect([200, 201], `end node creation should succeed, got ${endRes.status}`).toContain(endRes.status);
      const endType = endBody.type || endBody.nodeType;
      expect(endType, `end node type should be 'end'`).toBe('end');
      const endId = endBody.id || endBody.nodeId;
      expect(endId).toBeTruthy();

      // Reject second start node (max 1)
      const { res: secondStartRes, body: secondStartBody } = await request(`/api/boards/${boardId}/nodes`, {
        method: 'POST',
        body: JSON.stringify({ title: 'Another Start', label: 'Another Start', type: 'start' }),
      });
      expect(
        [400, 409, 422],
        `creating a second start node should be rejected, got ${secondStartRes.status} with body ${JSON.stringify(secondStartBody)}`
      ).toContain(secondStartRes.status);
      const secondStartMsg = secondStartBody?.message || secondStartBody?.error || JSON.stringify(secondStartBody);
      expect(secondStartMsg.length).toBeGreaterThan(0);

      // Create connections: start -> step -> decision -> end (with branch label on decision->end)
      const { res: conn1Res } = await request(`/api/boards/${boardId}/connections`, {
        method: 'POST',
        body: JSON.stringify({ fromId: startId, toId: stepId, fromNodeId: startId, toNodeId: stepId, source: startId, target: stepId }),
      });
      expect([200, 201], `connection start->step should succeed`).toContain(conn1Res.status);

      const { res: conn2Res } = await request(`/api/boards/${boardId}/connections`, {
        method: 'POST',
        body: JSON.stringify({ fromId: stepId, toId: decisionId, fromNodeId: stepId, toNodeId: decisionId, source: stepId, target: decisionId }),
      });
      expect([200, 201], `connection step->decision should succeed`).toContain(conn2Res.status);

      // Decision -> End with branch label 'Yes'
      const { res: conn3Res, body: conn3Body } = await request(`/api/boards/${boardId}/connections`, {
        method: 'POST',
        body: JSON.stringify({
          fromId: decisionId, toId: endId,
          fromNodeId: decisionId, toNodeId: endId,
          source: decisionId, target: endId,
          label: 'Yes',
        }),
      });
      expect([200, 201], `decision connection with branch label should succeed`).toContain(conn3Res.status);
      // Verify label is returned
      if (conn3Body && typeof conn3Body === 'object') {
        const returnedLabel = conn3Body.label || conn3Body.branchLabel;
        if (returnedLabel !== undefined) {
          expect(returnedLabel).toBe('Yes');
        }
      }

      // Verify branch label persists in connections list
      const { res: getConnsRes, body: getConnsBody } = await request(`/api/boards/${boardId}/connections`);
      expect(getConnsRes.status).toBe(200);
      const connsList = Array.isArray(getConnsBody) ? getConnsBody : (getConnsBody?.items || getConnsBody?.data || []);
      expect(Array.isArray(connsList)).toBe(true);
      const decisionConn = connsList.find((c: any) => {
        const from = c.fromId || c.fromNodeId || c.source;
        const to = c.toId || c.toNodeId || c.target;
        return from === decisionId && to === endId;
      });
      expect(decisionConn, 'decision->end connection should exist in list').toBeTruthy();
      if (decisionConn) {
        const persistedLabel = decisionConn.label || decisionConn.branchLabel;
        if (persistedLabel !== undefined) {
          expect(persistedLabel, 'decision branch label should persist').toBe('Yes');
        }
      }

      // Attempt to delete the sole end node — should be REJECTED to prevent zero-end illegal state
      const { res: deleteEndRes, body: deleteEndBody } = await request(`/api/boards/${boardId}/nodes/${endId}`, {
        method: 'DELETE',
      });
      expect(
        [400, 409, 422],
        `deleting the only end node should be rejected to prevent zero-end state, got ${deleteEndRes.status} with body ${JSON.stringify(deleteEndBody)}`
      ).toContain(deleteEndRes.status);

      // Verify the end node still exists
      const verifyBoard = await request(`/api/boards/${boardId}`);
      expect(verifyBoard.res.status).toBe(200);
      const finalNodes = verifyBoard.body.nodes || verifyBoard.body.data?.nodes || [];
      const endStillExists = finalNodes.find((n: any) => n.id === endId);
      expect(endStillExists, 'end node should still exist after rejected deletion').toBeTruthy();
    } finally {
      if (boardId) await safeDeleteBoard(boardId);
    }
  });
});

import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function request(path, options = {}) {
  const res = await fetch(`${BASE_URL}${path}`, {
    headers: { 'Content-Type': 'application/json', ...(options.headers || {}) },
    ...options,
  });
  let body = null;
  const text = await res.text();
  try {
    body = text ? JSON.parse(text) : null;
  } catch {
    body = text;
  }
  return { res, body };
}

// Try multiple possible API paths for the user/me endpoint
async function getMe() {
  for (const path of ['/api/me', '/api/collaboration/me', '/api/participants/me', '/me']) {
    try {
      const result = await request(path);
      if (result.res.ok) return { ...result, path };
    } catch {}
  }
  throw new Error('Unable to find working GET /me endpoint');
}

async function patchMe(payload, basePath) {
  // Try PATCH first, then PUT
  for (const method of ['PATCH', 'PUT']) {
    try {
      const result = await request(basePath, {
        method,
        body: JSON.stringify(payload),
      });
      if (result.res.status !== 404 && result.res.status !== 405) return result;
    } catch {}
  }
  throw new Error(`Unable to update via ${basePath}`);
}

describe('update_display_name_validates_and_persists', () => {
  it('should reject invalid display names and persist a valid trimmed display name across repeated reads', async () => {
    // Discover the working endpoint
    const meResult = await getMe();
    const mePath = meResult.path;
    expect(meResult.res.status, `GET ${mePath} should succeed`).toBe(200);
    const displayNameField = meResult.body.displayName !== undefined ? 'displayName' : (meResult.body.display_name !== undefined ? 'display_name' : (meResult.body.name !== undefined ? 'name' : 'displayName'));
    expect(typeof meResult.body[displayNameField], `existing user should have ${displayNameField} field`).toBe('string');

    // Test: empty string should be rejected
    const emptyPayload = { [displayNameField]: '' };
    const { res: invalidEmptyRes } = await patchMe(emptyPayload, mePath);
    expect([400, 422]).toContain(invalidEmptyRes.status);

    // Test: blank (whitespace only) should be rejected
    const blankPayload = { [displayNameField]: '   ' };
    const { res: invalidBlankRes } = await patchMe(blankPayload, mePath);
    expect([400, 422]).toContain(invalidBlankRes.status);

    // Test: too long (21 chars) should be rejected
    const tooLong = 'x'.repeat(21);
    const tooLongPayload = { [displayNameField]: tooLong };
    const { res: invalidLongRes } = await patchMe(tooLongPayload, mePath);
    expect([400, 422]).toContain(invalidLongRes.status);

    // Test: exactly 1 character (boundary) should be accepted
    const singleCharPayload = { [displayNameField]: 'A' };
    const { res: singleCharRes } = await patchMe(singleCharPayload, mePath);
    expect([200, 204]).toContain(singleCharRes.status);

    // Verify the 1-char name was saved
    const afterSingle = await getMe();
    expect(afterSingle.body[displayNameField].trim()).toBe('A');

    // Test: exactly 20 characters (boundary) should be accepted
    const exactly20 = 'B'.repeat(20);
    const exactly20Payload = { [displayNameField]: exactly20 };
    const { res: exactly20Res } = await patchMe(exactly20Payload, mePath);
    expect([200, 204]).toContain(exactly20Res.status);

    // Verify the 20-char name was saved
    const after20 = await getMe();
    expect(after20.body[displayNameField].trim()).toBe(exactly20);
    expect(after20.body[displayNameField].trim().length).toBe(20);

    // Test: valid name with surrounding whitespace should be trimmed and accepted
    const validNameRaw = '   QA Tester   ';
    const validPayload = { [displayNameField]: validNameRaw };
    const { res: validPatchRes } = await patchMe(validPayload, mePath);
    expect([200, 204]).toContain(validPatchRes.status);

    // Verify persisted (first read)
    const meAfter = await getMe();
    expect(meAfter.res.status).toBe(200);
    expect(meAfter.body[displayNameField].trim()).toBe('QA Tester');
    expect(meAfter.body[displayNameField].trim().length).toBeGreaterThanOrEqual(1);
    expect(meAfter.body[displayNameField].trim().length).toBeLessThanOrEqual(20);

    // Simulate refresh: wait briefly then read again to ensure persistence beyond in-memory cache
    await new Promise(resolve => setTimeout(resolve, 200));
    const meRefresh = await getMe();
    expect(meRefresh.res.status).toBe(200);
    expect(meRefresh.body[displayNameField].trim()).toBe('QA Tester');
  });
});

import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function request(path: string, options: any = {}) {
  const res = await fetch(`${BASE_URL}${path}`, {
    headers: { 'Content-Type': 'application/json', ...(options.headers || {}) },
    ...options,
  });
  const text = await res.text();
  let json: any;
  try { json = text ? JSON.parse(text) : null; } catch { json = text; }
  return { res, body: json, text };
}

async function safeDeleteBoard(boardId: string | undefined) {
  if (!boardId) return;
  try { await fetch(`${BASE_URL}/api/boards/${boardId}`, { method: 'DELETE' }); } catch {}
}

function extractId(body: any): string {
  return body?.id || body?.boardId || body?.data?.id || '';
}

function extractNodeId(body: any): string {
  return body?.id || body?.nodeId || body?.data?.id || '';
}

function extractNodes(body: any): any[] {
  if (Array.isArray(body)) return body;
  if (Array.isArray(body?.nodes)) return body.nodes;
  if (Array.isArray(body?.items)) return body.items;
  if (Array.isArray(body?.data)) return body.data;
  return [];
}

