      }

      // Attempt to change root fishbone node to flowchart type 'end' — should be rejected
      const invalidType = await request(`/api/boards/${boardId}/nodes/${rootNodeId}`, {
        method: 'PATCH',
        body: JSON.stringify({ type: 'end' }),
      });
      expect(
        [400, 409, 422].includes(invalidType.res.status),
        `Changing fishbone root to flowchart type should be rejected, got ${invalidType.res.status}`,
      ).toBe(true);

      // Build 3 levels of cause nodes to test depth limit
      // Level 1 cause
      const l1Res = await request(`/api/boards/${boardId}/nodes`, {
        method: 'POST',
        body: JSON.stringify({ title: 'Cause L1', parentId: rootNodeId, type: 'cause' }),
      });
      expect([200, 201]).toContain(l1Res.res.status);
      const l1Id = extractNodeId(l1Res.body);

      // Level 2 cause
      const l2Res = await request(`/api/boards/${boardId}/nodes`, {
        method: 'POST',
        body: JSON.stringify({ title: 'Cause L2', parentId: l1Id, type: 'cause' }),
      });
      expect([200, 201]).toContain(l2Res.res.status);
      const l2Id = extractNodeId(l2Res.body);

      // Level 3 cause
      const l3Res = await request(`/api/boards/${boardId}/nodes`, {
        method: 'POST',
        body: JSON.stringify({ title: 'Cause L3', parentId: l2Id, type: 'cause' }),
      });
      expect([200, 201]).toContain(l3Res.res.status);
      const l3Id = extractNodeId(l3Res.body);

      // Level 4 cause — should be rejected (max 3 layers)
      const l4Res = await request(`/api/boards/${boardId}/nodes`, {
        method: 'POST',
        body: JSON.stringify({ title: 'Cause L4', parentId: l3Id, type: 'cause' }),
      });
      expect(
        [400, 409, 422].includes(l4Res.res.status),
        `Creating 4th level cause in fishbone should be rejected, got ${l4Res.res.status}`,
      ).toBe(true);
    } finally {
      await safeDeleteBoard(boardId);
    }
  });
});

import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function http(path, options = {}) {
  const res = await fetch(`${BASE_URL}${path}`, {
    headers: {
      'Content-Type': 'application/json',
      ...(options.headers || {}),
    },
    ...options,
  });
  const contentType = res.headers.get('content-type') || '';
  const body = contentType.includes('application/json') ? await res.json() : await res.text();
  return { res, body };
}

async function safeCleanup(boardId) {
  if (!boardId) return;
  try {
    await fetch(`${BASE_URL}/api/boards/${boardId}`, { method: 'DELETE' });
