import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function api(path, options = {}) {
  const res = await fetch(`${BASE_URL}${path}`, {
    headers: {
      'Content-Type': 'application/json',
      ...(options.headers || {}),
    },
    ...options,
  });

  const contentType = res.headers.get('content-type') || '';
  let body = null;
  if (contentType.includes('application/json')) {
    body = await res.json();
  } else {
    body = await res.text();
  }

  return { res, body };
}

function randomName(prefix) {
  return `${prefix}-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
}

function extractId(entity) {
  return entity?.id ?? entity?._id ?? entity?.boardId ?? entity?.nodeId ?? entity?.commentId;
}

function asData(body) {
  return body?.data ?? body;
}

function getArrayByCandidates(body, candidates) {
  if (Array.isArray(body)) return body;
  for (const key of candidates) {
    if (Array.isArray(body?.[key])) return body[key];
  }
  return null;
}

async function createBoard(payload) {
  const { res, body } = await api('/api/boards', {
    method: 'POST',
