  expect(res.status, `create board status should be 201, got ${res.status} with body ${JSON.stringify(body)}`).toBe(201);
  const board = asData(body);
  const boardId = extractId(board);
  expect(boardId, `created board should contain id, got ${JSON.stringify(body)}`).toBeTruthy();
  return board;
}

async function deleteBoard(boardId) {
  try {
    await api(`/api/boards/${boardId}`, { method: 'DELETE' });
  } catch {
    // ignore cleanup errors
  }
}

describe('recent_activities_order_and_limit', () => {
  it('should keep recent activities updated by key local operations, ordered desc by time, and limited to 10 items', async () => {
    const createdBoardIds = [];

    try {
      const board = await createBoard({
        title: randomName('activities-board'),
        type: 'mindmap',
      });
      const boardId = extractId(board);
      createdBoardIds.push(boardId);

      const createdNodeIds = [];
      const createdCommentIds = [];
      const operationDescriptions = []; // track operations in order

      // 1. Create 6 nodes (operations 1-6)
      for (let i = 0; i < 6; i++) {
        const marker = randomName(`node-${i}`);
        const { res, body } = await api(`/api/boards/${boardId}/nodes`, {
          method: 'POST',
          body: JSON.stringify({
            title: marker,
            type: 'topic',
          }),
        });

        expect(res.status, `create node #${i} should succeed, got ${res.status} with body ${JSON.stringify(body)}`).toBeGreaterThanOrEqual(200);
        expect(res.status, `create node #${i} should be < 300, got ${res.status}`).toBeLessThan(300);

        const node = asData(body);
        const nodeId = extractId(node);
        expect(nodeId, `created node #${i} should contain id, got ${JSON.stringify(body)}`).toBeTruthy();
        expect(node?.title ?? node?.name, `created node #${i} should echo title, got ${JSON.stringify(body)}`).toBe(marker);

        createdNodeIds.push(nodeId);
        operationDescriptions.push({ type: 'create_node', marker });
      }

      // 2. Rename a node title (operation 7) - this is 'change title' per the requirement
      const renamedNodeTitle = randomName('renamed-node');
      {
        const targetNodeId = createdNodeIds[0];
        const { res, body } = await api(`/api/boards/${boardId}/nodes/${targetNodeId}`, {
          method: 'PATCH',
          body: JSON.stringify({ title: renamedNodeTitle }),
        });

        expect(res.status, `rename node title should succeed, got ${res.status} with body ${JSON.stringify(body)}`).toBeGreaterThanOrEqual(200);
        expect(res.status, `rename node title should be < 300, got ${res.status}`).toBeLessThan(300);

        const updated = asData(body);
        expect(updated?.title ?? updated?.name, `renamed node should have title ${renamedNodeTitle}, got ${JSON.stringify(body)}`).toBe(renamedNodeTitle);
        operationDescriptions.push({ type: 'rename_node', marker: renamedNodeTitle });
      }

      // 3. Add comment (operation 8)
      const commentText = randomName('comment');
      let commentId;
      {
        const targetNodeId = createdNodeIds[0];
        const { res, body } = await api(`/api/boards/${boardId}/comments`, {
          method: 'POST',
          body: JSON.stringify({
            targetId: targetNodeId,
            nodeId: targetNodeId,
            content: commentText,
          }),
        });

        expect(res.status, `add comment should succeed, got ${res.status} with body ${JSON.stringify(body)}`).toBeGreaterThanOrEqual(200);
        expect(res.status, `add comment should be < 300, got ${res.status}`).toBeLessThan(300);

        const comment = asData(body);
        commentId = extractId(comment);
        expect(commentId, `created comment should contain id, got ${JSON.stringify(body)}`).toBeTruthy();
        expect(comment?.content ?? comment?.text, `created comment should have content ${commentText}, got ${JSON.stringify(body)}`).toBe(commentText);
        createdCommentIds.push(commentId);
        operationDescriptions.push({ type: 'add_comment', marker: commentText });
      }

      // 4. Resolve comment (operation 9)
      {
        const { res, body } = await api(`/api/boards/${boardId}/comments/${commentId}`, {
          method: 'PATCH',
          body: JSON.stringify({ resolved: true }),
        });

        expect(res.status, `resolve comment should succeed, got ${res.status} with body ${JSON.stringify(body)}`).toBeGreaterThanOrEqual(200);
        expect(res.status, `resolve comment should be < 300, got ${res.status}`).toBeLessThan(300);

        const updated = asData(body);
        expect(updated?.resolved, `resolved comment should have resolved=true, got ${JSON.stringify(body)}`).toBe(true);
        operationDescriptions.push({ type: 'resolve_comment', marker: 'resolved' });
      }

      // 5. Delete one node (operation 10)
      const deletedNodeId = createdNodeIds[5];
      {
        const { res, body } = await api(`/api/boards/${boardId}/nodes/${deletedNodeId}`, {
          method: 'DELETE',
        });

        expect([200, 204], `delete node should return 200 or 204, got ${res.status}`).toContain(res.status);
        operationDescriptions.push({ type: 'delete_node', marker: String(deletedNodeId) });
      }

      // 6. Create one more node (operation 11) to exceed the 10 limit
      const extraNodeTitle = randomName('extra-node');
      {
        const { res, body } = await api(`/api/boards/${boardId}/nodes`, {
          method: 'POST',
          body: JSON.stringify({
            title: extraNodeTitle,
            type: 'topic',
          }),
        });

        expect(res.status, `create extra node should succeed, got ${res.status} with body ${JSON.stringify(body)}`).toBeGreaterThanOrEqual(200);
        expect(res.status, `create extra node should be < 300, got ${res.status}`).toBeLessThan(300);

        const node = asData(body);
        const nodeId = extractId(node);
        expect(nodeId, `extra node should contain id, got ${JSON.stringify(body)}`).toBeTruthy();
        createdNodeIds.push(nodeId);
        operationDescriptions.push({ type: 'create_node', marker: extraNodeTitle });
      }

      // We now have 11 operations total. The oldest (first create_node) should be evicted.

      // Fetch recent activities
      const { res, body } = await api(`/api/boards/${boardId}/activities?limit=20`, {
        method: 'GET',
      });

      expect(res.status, `get recent activities should return 200, got ${res.status} with body ${JSON.stringify(body)}`).toBe(200);

      const activities = getArrayByCandidates(asData(body), ['activities', 'items', 'list', 'data']) || getArrayByCandidates(body, ['activities', 'items', 'list', 'data']);
      expect(Array.isArray(activities), `recent activities should be an array, got ${JSON.stringify(body)}`).toBe(true);
      expect(activities.length, `recent activities should keep at most 10 items, got ${activities.length}`).toBeLessThanOrEqual(10);
      expect(activities.length, `recent activities should contain exactly 10 items (we made 11 ops), got ${activities.length}`).toBe(10);

      // Verify descending time order
      for (let i = 0; i < activities.length - 1; i++) {
        const currentRaw = activities[i]?.createdAt ?? activities[i]?.updatedAt ?? activities[i]?.time ?? activities[i]?.timestamp;
        const nextRaw = activities[i + 1]?.createdAt ?? activities[i + 1]?.updatedAt ?? activities[i + 1]?.time ?? activities[i + 1]?.timestamp;
        expect(currentRaw, `activity[${i}] should contain a time field, got ${JSON.stringify(activities[i])}`).toBeTruthy();
        expect(nextRaw, `activity[${i + 1}] should contain a time field, got ${JSON.stringify(activities[i + 1])}`).toBeTruthy();

        const current = new Date(currentRaw).getTime();
        const next = new Date(nextRaw).getTime();
        expect(Number.isNaN(current), `activity[${i}] time should be parseable date, got ${currentRaw}`).toBe(false);
        expect(Number.isNaN(next), `activity[${i + 1}] time should be parseable date, got ${nextRaw}`).toBe(false);
        expect(current, `activities should be in reverse chronological order: activity[${i}] time ${currentRaw} should be >= activity[${i + 1}] time ${nextRaw}`).toBeGreaterThanOrEqual(next);
      }

      // Verify activity types are present for different operation kinds
      const activityTypes = activities.map(a => a?.type ?? a?.action ?? a?.activityType ?? a?.kind ?? '').map(t => String(t).toLowerCase());
      const activitySerialized = JSON.stringify(activities).toLowerCase();

      // Check that different operation types appear in activities
      // We expect at least: create_node, rename/update node title, add_comment, resolve_comment, delete_node
      const hasCreateNode = activityTypes.some(t => t.includes('create') || t.includes('add') || t.includes('node')) || activitySerialized.includes('create') || activitySerialized.includes('add_node');
      const hasRenameOrUpdate = activityTypes.some(t => t.includes('rename') || t.includes('update') || t.includes('edit') || t.includes('modify') || t.includes('title')) || activitySerialized.includes('rename') || activitySerialized.includes('update') || activitySerialized.includes(renamedNodeTitle.toLowerCase());
      const hasComment = activityTypes.some(t => t.includes('comment')) || activitySerialized.includes('comment');
      const hasDelete = activityTypes.some(t => t.includes('delete') || t.includes('remove')) || activitySerialized.includes('delete') || activitySerialized.includes('remove');
      const hasResolve = activityTypes.some(t => t.includes('resolve')) || activitySerialized.includes('resolve');

      // At least some of these operation types should be distinguishable
      expect(hasCreateNode || hasRenameOrUpdate || hasComment || hasDelete || hasResolve, `activities should contain recognizable operation types, got types: ${JSON.stringify(activityTypes)}`).toBe(true);

      // Verify the latest operation (extra node creation) is present
      const serialized = JSON.stringify(activities);
      expect(
        serialized.includes(extraNodeTitle) || activityTypes.some(t => t.includes('create')),
        `most recent activity should relate to the extra node creation (${extraNodeTitle}), got ${serialized}`
      ).toBe(true);

      // Verify the renamed node title appears in activities (rename operation)
      expect(
        serialized.includes(renamedNodeTitle),
        `activities should include the renamed node title marker: ${renamedNodeTitle}. Actual activities: ${serialized}`
      ).toBe(true);

      // Verify comment text appears in activities
      expect(
        serialized.includes(commentText),
        `activities should include the comment marker: ${commentText}. Actual activities: ${serialized}`
      ).toBe(true);

      // The very first node creation (operationDescriptions[0]) should have been evicted
      const firstNodeMarker = operationDescriptions[0].marker;
      expect(
        serialized.includes(firstNodeMarker),
        `oldest activity marker should have been evicted when count exceeds 10: ${firstNodeMarker}. Actual activities: ${serialized}`
      ).toBe(false);
    } finally {
      for (const boardId of createdBoardIds) {
        await deleteBoard(boardId);
      }
    }
  });
});

