  it('should complete multi-board e2e regression flow without cross-board mutation and keep summaries/details consistent', async () => {
    const cleanupBoardIds = [];

    try {
      const mindmapTitle = randomName('mindmap-source');
      const flowchartTitle = randomName('flowchart-source');

      const mindmap = await createBoard({ title: mindmapTitle, type: 'mindmap' });
      const flowchart = await createBoard({ title: flowchartTitle, type: 'flowchart' });
      const mindmapId = extractId(mindmap);
      const flowchartId = extractId(flowchart);
      cleanupBoardIds.push(mindmapId, flowchartId);

      // ===== Validate illegal inputs are rejected =====
      // Empty title should be rejected
      const emptyTitleRes = await api('/api/boards', {
        method: 'POST',
        body: JSON.stringify({ title: '', type: 'mindmap' }),
      });
      expect(emptyTitleRes.res.status, `creating board with empty title should be rejected (4xx), got ${emptyTitleRes.res.status}`).toBeGreaterThanOrEqual(400);
      expect(emptyTitleRes.res.status).toBeLessThan(500);

