        body: JSON.stringify({ title: randomName('invalid'), type: 'invalid_type_xyz' }),
      });
      expect(invalidTypeRes.res.status, `creating board with invalid type should be rejected (4xx), got ${invalidTypeRes.res.status}`).toBeGreaterThanOrEqual(400);
