      expect(fakeNodeRes.res.status).toBeLessThan(500);

      // ===== Edit mindmap board: add nodes =====
      const rootTitle = randomName('root-topic');
      const childTitle = randomName('child-topic');

      const rootNodeRes = await api(`/api/boards/${mindmapId}/nodes`, {
        method: 'POST',
        body: JSON.stringify({ title: rootTitle, type: 'topic' }),
      });
