      expect(rootNodeId).toBeTruthy();
      expect(rootNode?.title ?? rootNode?.name).toBe(rootTitle);

      const childNodeRes = await api(`/api/boards/${mindmapId}/nodes`, {
        method: 'POST',
        body: JSON.stringify({ title: childTitle, type: 'topic', parentId: rootNodeId }),
      });
      expect(childNodeRes.res.status).toBeGreaterThanOrEqual(200);
      expect(childNodeRes.res.status).toBeLessThan(300);
      const childNode = asData(childNodeRes.body);
      const childNodeId = extractId(childNode);
      expect(childNodeId).toBeTruthy();

      // ===== Add tags to mindmap nodes =====
      const tagName1 = randomName('tag1');
      const tagName2 = randomName('tag2');
      const tagRes1 = await api(`/api/boards/${mindmapId}/nodes/${rootNodeId}/tags`, {
        method: 'POST',
        body: JSON.stringify({ name: tagName1 }),
      });
      expect(tagRes1.res.status, `add tag to root node should succeed, got ${tagRes1.res.status}`).toBeGreaterThanOrEqual(200);
      expect(tagRes1.res.status).toBeLessThan(300);

      const tagRes2 = await api(`/api/boards/${mindmapId}/nodes/${childNodeId}/tags`, {
        method: 'POST',
        body: JSON.stringify({ name: tagName2 }),
      });
      expect(tagRes2.res.status, `add tag to child node should succeed, got ${tagRes2.res.status}`).toBeGreaterThanOrEqual(200);
      expect(tagRes2.res.status).toBeLessThan(300);

      // ===== Add comment to mindmap node =====
      const commentText = randomName('mm-comment');
      const commentRes = await api(`/api/boards/${mindmapId}/comments`, {
        method: 'POST',
        body: JSON.stringify({
          targetId: rootNodeId,
          nodeId: rootNodeId,
          content: commentText,
        }),
      });
      expect(commentRes.res.status, `add comment should succeed, got ${commentRes.res.status}`).toBeGreaterThanOrEqual(200);
      expect(commentRes.res.status).toBeLessThan(300);
      const comment = asData(commentRes.body);
      const commentId = extractId(comment);
      expect(commentId).toBeTruthy();
      expect(comment?.content ?? comment?.text).toBe(commentText);

      // ===== Add presentation steps to mindmap =====
      const presStep1Res = await api(`/api/boards/${mindmapId}/presentation/steps`, {
        method: 'POST',
        body: JSON.stringify({ nodeId: rootNodeId }),
      });
      expect(presStep1Res.res.status, `add presentation step 1 should succeed, got ${presStep1Res.res.status}`).toBeGreaterThanOrEqual(200);
      expect(presStep1Res.res.status).toBeLessThan(300);

      const presStep2Res = await api(`/api/boards/${mindmapId}/presentation/steps`, {
        method: 'POST',
        body: JSON.stringify({ nodeId: childNodeId }),
      });
      expect(presStep2Res.res.status, `add presentation step 2 should succeed, got ${presStep2Res.res.status}`).toBeGreaterThanOrEqual(200);
      expect(presStep2Res.res.status).toBeLessThan(300);

      // ===== Keep flowchart legal structure =====
      const startLabel = randomName('start');
      const processLabel = randomName('process');
      const endLabel = randomName('end');

      const flowStartRes = await api(`/api/boards/${flowchartId}/nodes`, {
        method: 'POST',
        body: JSON.stringify({ title: startLabel, type: 'start' }),
      });
      expect(flowStartRes.res.status).toBeGreaterThanOrEqual(200);
      expect(flowStartRes.res.status).toBeLessThan(300);
      const flowStart = asData(flowStartRes.body);
      const flowStartId = extractId(flowStart);
      expect(flowStartId).toBeTruthy();

      const flowProcessRes = await api(`/api/boards/${flowchartId}/nodes`, {
        method: 'POST',
        body: JSON.stringify({ title: processLabel, type: 'process' }),
      });
      expect(flowProcessRes.res.status).toBeGreaterThanOrEqual(200);
      expect(flowProcessRes.res.status).toBeLessThan(300);
      const flowProcess = asData(flowProcessRes.body);
      const flowProcessId = extractId(flowProcess);
      expect(flowProcessId).toBeTruthy();

      const flowEndRes = await api(`/api/boards/${flowchartId}/nodes`, {
        method: 'POST',
        body: JSON.stringify({ title: endLabel, type: 'end' }),
      });
      expect(flowEndRes.res.status).toBeGreaterThanOrEqual(200);
      expect(flowEndRes.res.status).toBeLessThan(300);
      const flowEnd = asData(flowEndRes.body);
      const flowEndId = extractId(flowEnd);
      expect(flowEndId).toBeTruthy();

      const edge1Res = await api(`/api/boards/${flowchartId}/edges`, {
        method: 'POST',
        body: JSON.stringify({ from: flowStartId, to: flowProcessId }),
      });
      expect(edge1Res.res.status).toBeGreaterThanOrEqual(200);
      expect(edge1Res.res.status).toBeLessThan(300);

      const edge2Res = await api(`/api/boards/${flowchartId}/edges`, {
        method: 'POST',
        body: JSON.stringify({ from: flowProcessId, to: flowEndId }),
      });
      expect(edge2Res.res.status).toBeGreaterThanOrEqual(200);
      expect(edge2Res.res.status).toBeLessThan(300);

      // ===== Verify flowchart constraint: second start node should be rejected =====
      const secondStartRes = await api(`/api/boards/${flowchartId}/nodes`, {
        method: 'POST',
        body: JSON.stringify({ title: randomName('start2'), type: 'start' }),
      });
      expect(
        secondStartRes.res.status,
        `creating a second start node should be rejected (4xx), got ${secondStartRes.res.status}`
      ).toBeGreaterThanOrEqual(400);
      expect(secondStartRes.res.status).toBeLessThan(500);

      // ===== Before copying, verify source board appears in list (matching user flow) =====
      const preListRes = await api('/api/boards', { method: 'GET' });
      expect(preListRes.res.status).toBe(200);
      const preBoards = getArrayByCandidates(asData(preListRes.body), ['boards', 'items', 'list', 'data']) || getArrayByCandidates(preListRes.body, ['boards', 'items', 'list', 'data']) || [];
      const preListedSource = preBoards.find((b) => extractId(b) === mindmapId);
      expect(preListedSource, `source board should appear in list before copying`).toBeTruthy();

      // ===== Copy mindmap board =====
      const copyTitle = randomName('mindmap-copy');
      const copyRes = await api(`/api/boards/${mindmapId}/copy`, {
        method: 'POST',
        body: JSON.stringify({ title: copyTitle }),
      });
      expect(copyRes.res.status, `copy board should succeed, got ${copyRes.res.status}`).toBeGreaterThanOrEqual(200);
      expect(copyRes.res.status).toBeLessThan(300);
      const copiedBoard = asData(copyRes.body);
      const copiedBoardId = extractId(copiedBoard);
      expect(copiedBoardId).toBeTruthy();
      expect(copiedBoardId).not.toBe(mindmapId);
      cleanupBoardIds.push(copiedBoardId);

      // Verify copied board has nodes
      const copiedDetailResBefore = await api(`/api/boards/${copiedBoardId}`, { method: 'GET' });
      expect(copiedDetailResBefore.res.status).toBe(200);
      const copiedDetailBefore = asData(copiedDetailResBefore.body);
      const copiedNodesBefore = getArrayByCandidates(copiedDetailBefore, ['nodes', 'items']) || [];
      expect(copiedNodesBefore.length, `copied board should contain copied nodes`).toBeGreaterThanOrEqual(2);

      const copiedChild = copiedNodesBefore.find((n) => (n.title ?? n.name) === childTitle);
      expect(copiedChild, `copied board should contain child node with title ${childTitle}`).toBeTruthy();
      const copiedChildId = extractId(copiedChild);
      expect(copiedChildId).toBeTruthy();

      // Modify copy
      const modifiedCopyChildTitle = randomName('copy-child-updated');
      const updateCopyNodeRes = await api(`/api/boards/${copiedBoardId}/nodes/${copiedChildId}`, {
        method: 'PATCH',
        body: JSON.stringify({ title: modifiedCopyChildTitle }),
      });
      expect(updateCopyNodeRes.res.status).toBeGreaterThanOrEqual(200);
      expect(updateCopyNodeRes.res.status).toBeLessThan(300);
      const updatedCopiedNode = asData(updateCopyNodeRes.body);
      expect(updatedCopiedNode?.title ?? updatedCopiedNode?.name).toBe(modifiedCopyChildTitle);

      // ===== Verify source board not mutated =====
      const sourceDetailRes = await api(`/api/boards/${mindmapId}`, { method: 'GET' });
      expect(sourceDetailRes.res.status).toBe(200);
      const sourceDetail = asData(sourceDetailRes.body);
      const sourceNodes = getArrayByCandidates(sourceDetail, ['nodes', 'items']) || [];
      const originalSourceChild = sourceNodes.find((n) => (n.title ?? n.name) === childTitle);
      expect(originalSourceChild, `source board should still contain original child title ${childTitle}`).toBeTruthy();
      const leakedChange = sourceNodes.find((n) => (n.title ?? n.name) === modifiedCopyChildTitle);
      expect(leakedChange, `source board should not contain copied-board-only title ${modifiedCopyChildTitle}`).toBeFalsy();

      // ===== Export copied board =====
      const exportRes = await api(`/api/boards/${copiedBoardId}/export`, { method: 'GET' });
      expect(exportRes.res.status, `export copied board should succeed, got ${exportRes.res.status}`).toBeGreaterThanOrEqual(200);
      expect(exportRes.res.status).toBeLessThan(300);
      const exported = asData(exportRes.body);
      expect(exported, `exported payload should exist`).toBeTruthy();

      // ===== Delete copied board =====
      const deleteCopyRes = await api(`/api/boards/${copiedBoardId}`, { method: 'DELETE' });
      expect([200, 204]).toContain(deleteCopyRes.res.status);
      // Remove from cleanup since it's already deleted
      const copiedIdx = cleanupBoardIds.indexOf(copiedBoardId);
      if (copiedIdx >= 0) cleanupBoardIds.splice(copiedIdx, 1);

      // ===== Import as new board =====
      const importedTitle = randomName('imported-board');
      const importRes = await api('/api/boards/import', {
        method: 'POST',
        body: JSON.stringify({ title: importedTitle, data: exported }),
      });
      expect(importRes.res.status, `import board should succeed, got ${importRes.res.status}`).toBeGreaterThanOrEqual(200);
      expect(importRes.res.status).toBeLessThan(300);
      const importedBoard = asData(importRes.body);
      const importedBoardId = extractId(importedBoard);
      expect(importedBoardId).toBeTruthy();
      expect(importedBoardId).not.toBe(mindmapId);
      expect(importedBoardId).not.toBe(copiedBoardId);
      cleanupBoardIds.push(importedBoardId);

      // ===== Verify imported board content (nodes, tags, comments, presentation) =====
      const importedDetailRes = await api(`/api/boards/${importedBoardId}`, { method: 'GET' });
      expect(importedDetailRes.res.status).toBe(200);
      const importedDetail = asData(importedDetailRes.body);
      const importedNodes = getArrayByCandidates(importedDetail, ['nodes', 'items']) || [];
      expect(importedNodes.length, `imported board should contain nodes from export/import`).toBeGreaterThanOrEqual(2);
      const importedChangedNode = importedNodes.find((n) => (n.title ?? n.name) === modifiedCopyChildTitle);
      expect(importedChangedNode, `imported board should preserve modified copied content ${modifiedCopyChildTitle}`).toBeTruthy();

      // Verify tags survived import — assert 200 instead of silently skipping
      const importedRootNode = importedNodes.find((n) => (n.title ?? n.name) === rootTitle);
      expect(importedRootNode, `imported board should contain root node with title ${rootTitle}`).toBeTruthy();
      const importedRootId = extractId(importedRootNode);
      expect(importedRootId).toBeTruthy();
      const importedTagsRes = await api(`/api/boards/${importedBoardId}/nodes/${importedRootId}/tags`, { method: 'GET' });
      expect(importedTagsRes.res.status, `fetching tags from imported board should return 200, got ${importedTagsRes.res.status}`).toBe(200);
      const importedTags = getArrayByCandidates(asData(importedTagsRes.body), ['tags', 'items', 'data']) || [];
      const serializedTags = JSON.stringify(importedTags);
      expect(serializedTags.includes(tagName1), `imported board should preserve tag ${tagName1}, found tags: ${serializedTags}`).toBe(true);

      // Verify comments survived import — assert 200 instead of silently skipping
      const importedCommentsRes = await api(`/api/boards/${importedBoardId}/comments`, { method: 'GET' });
      expect(importedCommentsRes.res.status, `fetching comments from imported board should return 200, got ${importedCommentsRes.res.status}`).toBe(200);
      const importedComments = getArrayByCandidates(asData(importedCommentsRes.body), ['comments', 'items', 'data']) || [];
      const commentsSerialized = JSON.stringify(importedComments);
      expect(commentsSerialized.includes(commentText), `imported board should preserve comment content ${commentText}, found: ${commentsSerialized}`).toBe(true);

      // Verify presentation steps survived import — assert 200 instead of silently skipping
      const importedPresRes = await api(`/api/boards/${importedBoardId}/presentation`, { method: 'GET' });
      expect(importedPresRes.res.status, `fetching presentation from imported board should return 200, got ${importedPresRes.res.status}`).toBe(200);
      const importedPres = asData(importedPresRes.body);
      const importedSlides = getArrayByCandidates(importedPres, ['slides', 'items', 'steps']) || [];
      expect(importedSlides.length, `imported board should preserve at least 2 presentation steps`).toBeGreaterThanOrEqual(2);

      // ===== Board list summary consistency =====
      const listRes = await api('/api/boards', { method: 'GET' });
      expect(listRes.res.status).toBe(200);
      const boards = getArrayByCandidates(asData(listRes.body), ['boards', 'items', 'list', 'data']) || getArrayByCandidates(listRes.body, ['boards', 'items', 'list', 'data']) || [];
      expect(Array.isArray(boards)).toBe(true);

      const listedSource = boards.find((b) => extractId(b) === mindmapId);
      const listedFlow = boards.find((b) => extractId(b) === flowchartId);
      const listedImported = boards.find((b) => extractId(b) === importedBoardId);
      expect(listedSource, `board list should include source board ${mindmapId}`).toBeTruthy();
      expect(listedFlow, `board list should include flowchart board ${flowchartId}`).toBeTruthy();
      expect(listedImported, `board list should include imported board ${importedBoardId}`).toBeTruthy();

      // Verify title consistency between list and detail
      expect(listedSource.title ?? listedSource.name).toBe(sourceDetail.title ?? sourceDetail.name);
      expect(listedImported.title ?? listedImported.name).toBe(importedDetail.title ?? importedDetail.name);

      // Verify template type consistency between list and detail
      const sourceType = sourceDetail?.type ?? sourceDetail?.template ?? sourceDetail?.templateType;
      const listedSourceType = listedSource?.type ?? listedSource?.template ?? listedSource?.templateType;
      if (sourceType && listedSourceType) {
        expect(listedSourceType, `list summary type should match detail type for source board`).toBe(sourceType);
      }
      const importedType = importedDetail?.type ?? importedDetail?.template ?? importedDetail?.templateType;
      const listedImportedType = listedImported?.type ?? listedImported?.template ?? listedImported?.templateType;
      if (importedType && listedImportedType) {
        expect(listedImportedType, `list summary type should match detail type for imported board`).toBe(importedType);
      }

      // Verify updatedAt consistency
      const sourceUpdatedAt = sourceDetail?.updatedAt ?? sourceDetail?.modifiedAt;
      const listedSourceUpdatedAt = listedSource?.updatedAt ?? listedSource?.modifiedAt;
      if (sourceUpdatedAt && listedSourceUpdatedAt) {
        expect(listedSourceUpdatedAt, `list summary updatedAt should match detail for source board`).toBe(sourceUpdatedAt);
      }

      // Distinguish source vs imported board
      expect(sourceDetail.title ?? sourceDetail.name).not.toBe(importedDetail.title ?? importedDetail.name);

      // ===== Viewer permission restriction should not regress =====
      // Viewer can read
      const viewerListRes = await api('/api/boards', {
        method: 'GET',
        headers: { 'x-role': 'viewer' },
      });
      expect(viewerListRes.res.status, `viewer should be able to read board list`).toBe(200);

      // Viewer cannot modify board (fixed: expect(actual).toSatisfy or use correct argument order)
      const viewerWriteRes = await api(`/api/boards/${mindmapId}`, {
        method: 'PATCH',
        headers: { 'x-role': 'viewer' },
        body: JSON.stringify({ title: randomName('viewer-should-not-edit') }),
      });
      expect(
        viewerWriteRes.res.status,
        `viewer should not be allowed to modify board, got ${viewerWriteRes.res.status}`
      ).toSatisfy((s) => s === 401 || s === 403);

      // Viewer cannot create node
      const viewerCreateNodeRes = await api(`/api/boards/${mindmapId}/nodes`, {
        method: 'POST',
        headers: { 'x-role': 'viewer' },
        body: JSON.stringify({ title: randomName('viewer-node'), type: 'topic' }),
      });
      expect(
        viewerCreateNodeRes.res.status,
        `viewer should not be allowed to create nodes, got ${viewerCreateNodeRes.res.status}`
      ).toSatisfy((s) => s === 401 || s === 403);

      // Viewer cannot delete node
      const viewerDeleteNodeRes = await api(`/api/boards/${mindmapId}/nodes/${rootNodeId}`, {
        method: 'DELETE',
        headers: { 'x-role': 'viewer' },
      });
      expect(
        viewerDeleteNodeRes.res.status,
        `viewer should not be allowed to delete nodes, got ${viewerDeleteNodeRes.res.status}`
      ).toSatisfy((s) => s === 401 || s === 403);

      // Viewer cannot add comment
      const viewerCommentRes = await api(`/api/boards/${mindmapId}/comments`, {
        method: 'POST',
        headers: { 'x-role': 'viewer' },
        body: JSON.stringify({ targetId: rootNodeId, nodeId: rootNodeId, content: 'viewer comment' }),
      });
      expect(
        viewerCommentRes.res.status,
        `viewer should not be allowed to add comments, got ${viewerCommentRes.res.status}`
      ).toSatisfy((s) => s === 401 || s === 403);

      // ===== Presentation boundary rule should not regress =====
      const presentationRes = await api(`/api/boards/${mindmapId}/presentation`, { method: 'GET' });
      expect(presentationRes.res.status, `presentation endpoint should return 200, got ${presentationRes.res.status}`).toBe(200);
      const presentation = asData(presentationRes.body);
      const slides = getArrayByCandidates(presentation, ['slides', 'items', 'steps']) || [];
      expect(Array.isArray(slides), `presentation should expose slides/items/steps array`).toBe(true);
      expect(slides.length, `presentation should have at least 2 steps`).toBeGreaterThanOrEqual(2);

      expect(slides[0]).toBeTruthy();
      expect(slides[slides.length - 1]).toBeTruthy();

      // Navigate to the end of the presentation
      for (let i = 0; i < slides.length - 1; i++) {
        const navRes = await api(`/api/boards/${mindmapId}/presentation/next`, {
          method: 'POST',
        });
        expect(navRes.res.status, `presentation next step ${i + 1} should succeed`).toBeGreaterThanOrEqual(200);
        expect(navRes.res.status).toBeLessThan(300);
      }

      // Try going past the last step — should either return 4xx or indicate atEnd / not advance
      const beyondRes = await api(`/api/boards/${mindmapId}/presentation/next`, {
        method: 'POST',
      });
      if (beyondRes.res.status >= 400 && beyondRes.res.status < 500) {
        // Server explicitly rejects going past the end — that's fine
        expect(beyondRes.res.status).toBeGreaterThanOrEqual(400);
      } else {
        // Server returns 2xx — must indicate at-end or not advance
        expect(beyondRes.res.status).toBeGreaterThanOrEqual(200);
        expect(beyondRes.res.status).toBeLessThan(300);
        const beyondData = asData(beyondRes.body);
        const beyondStep = beyondData?.currentStep ?? beyondData?.step ?? beyondData?.index;
        const atEnd = beyondData?.atEnd ?? beyondData?.isEnd ?? beyondData?.isLast ?? beyondData?.ended;
        // At least one of these indicators must be present
        const hasStepIndicator = beyondStep !== undefined;
        const hasEndIndicator = atEnd !== undefined;
        expect(
          hasStepIndicator || hasEndIndicator,
          `beyond-last navigation response should contain step index or end indicator, got ${JSON.stringify(beyondData)}`
        ).toBe(true);
        if (hasStepIndicator) {
          expect(beyondStep, `should not advance past last step index ${slides.length - 1}`).toBeLessThanOrEqual(slides.length - 1);
        }
        if (hasEndIndicator) {
          expect(atEnd, `should indicate at end of presentation`).toBe(true);
        }
      }
    } finally {
      for (const boardId of cleanupBoardIds.reverse()) {
        await deleteBoard(boardId);
      }
    }
  });
});

import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function request(method, path, body) {
  const res = await fetch(`${BASE_URL}${path}`, {
    method,
    headers: { 'Content-Type': 'application/json' },
    body: body === undefined ? undefined : JSON.stringify(body),
  });
  let data = null;
  try {
    data = await res.json();
  } catch {
    data = null;
  }
  return { res, data };
}

async function safeDelete(path) {
  try {
    await fetch(`${BASE_URL}${path}`, { method: 'DELETE' });
  } catch {}
}

function findItem(items, itemId) {
  return Array.isArray(items) ? items.find(i => i.itemId === itemId) : undefined;
}

describe('shop_trade_updates_gold_inventory_and_stats', () => {
  it('should correctly update gold, inventory usage, and character stats after shop buy and sell operations', async () => {
    const suffix = `${Date.now()}_${Math.random().toString(36).slice(2, 8)}`;
    const playerId = `shop-player-${suffix}`;
    const shopId = `shop-${suffix}`;
    const charmId = `atk-charm-${suffix}`;

    await request('POST', '/api/test/items', {
      items: [
        { itemId: charmId, type: 'equipment', slot: 'accessory', requiredLevel: 1, stats: { atk: 3 }, buyPrice: 40, sellPrice: 20 },
      ],
    });

    await request('POST', '/api/test/shops', {
      shopId,
      inventory: [{ itemId: charmId, stock: 99, buyPrice: 40, sellPrice: 20 }],
    });

    await request('POST', '/api/test/players', {
      playerId,
      gold: 100,
      stats: { atk: 10 },
      bagCapacity: 10,
      inventory: [],
      equipment: {},
    });

    const buyRes = await request('POST', `/api/shops/${shopId}/buy`, { playerId, itemId: charmId, quantity: 1 });
    expect(buyRes.res.status, `expected shop buy status 200 or 201, got ${buyRes.res.status}`).toBeGreaterThanOrEqual(200);
    expect(buyRes.res.status, `expected shop buy status < 300, got ${buyRes.res.status}`).toBeLessThan(300);

    const afterBuy = await request('GET', `/api/players/${playerId}`, undefined);
    expect(afterBuy.res.status, `expected player fetch after buy status 200, got ${afterBuy.res.status}`).toBe(200);
    const playerAfterBuy = afterBuy.data.player || afterBuy.data;
    expect(playerAfterBuy.gold, `gold should decrease from 100 to 60 after buying item, got ${playerAfterBuy.gold}`).toBe(60);
    expect(findItem(playerAfterBuy.inventory || [], charmId)?.quantity || 0, `inventory should contain bought item ${charmId} quantity 1`).toBe(1);
    expect((playerAfterBuy.inventory || []).length, `inventory used slots should become 1 after purchase, got ${(playerAfterBuy.inventory || []).length}`).toBe(1);

    const equipRes = await request('POST', `/api/players/${playerId}/equipment/equip`, { itemId: charmId });
    expect(equipRes.res.status, `expected equip bought item status 200 or 201, got ${equipRes.res.status}`).toBeGreaterThanOrEqual(200);
    expect(equipRes.res.status, `expected equip bought item status < 300, got ${equipRes.res.status}`).toBeLessThan(300);

    const afterEquip = await request('GET', `/api/players/${playerId}`, undefined);
    const playerAfterEquip = afterEquip.data.player || afterEquip.data;
    expect(playerAfterEquip.stats?.atk, `atk should increase from 10 to 13 after equipping bought item, got ${playerAfterEquip.stats?.atk}`).toBe(13);

    const unequipRes = await request('POST', `/api/players/${playerId}/equipment/unequip`, { slot: 'accessory' });
    expect(unequipRes.res.status, `expected unequip before selling status 200 or 201, got ${unequipRes.res.status}`).toBeGreaterThanOrEqual(200);
    expect(unequipRes.res.status, `expected unequip before selling status < 300, got ${unequipRes.res.status}`).toBeLessThan(300);

    const sellRes = await request('POST', `/api/shops/${shopId}/sell`, { playerId, itemId: charmId, quantity: 1 });
    expect(sellRes.res.status, `expected shop sell status 200 or 201, got ${sellRes.res.status}`).toBeGreaterThanOrEqual(200);
    expect(sellRes.res.status, `expected shop sell status < 300, got ${sellRes.res.status}`).toBeLessThan(300);

    const afterSell = await request('GET', `/api/players/${playerId}`, undefined);
    expect(afterSell.res.status, `expected player fetch after sell status 200, got ${afterSell.res.status}`).toBe(200);
    const playerAfterSell = afterSell.data.player || afterSell.data;
    expect(playerAfterSell.gold, `gold should increase from 60 to 80 after selling item, got ${playerAfterSell.gold}`).toBe(80);
    expect(findItem(playerAfterSell.inventory || [], charmId), `sold item ${charmId} should be removed from inventory`).toBeUndefined();
    expect((playerAfterSell.inventory || []).length, `inventory used slots should return to 0 after selling, got ${(playerAfterSell.inventory || []).length}`).toBe(0);
    expect(playerAfterSell.stats?.atk, `atk should return from 13 to 10 after unequip and sell, got ${playerAfterSell.stats?.atk}`).toBe(10);

    await safeDelete('/api/test/items');
    await safeDelete(`/api/test/shops/${shopId}`);
    await safeDelete(`/api/test/players/${playerId}`);
  });
});

import { describe, it, expect, afterAll } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function request(method, path, body) {
  const res = await fetch(`${BASE_URL}${path}`, {
    method,
    headers: { 'Content-Type': 'application/json' },
    body: body === undefined ? undefined : JSON.stringify(body),
  });
  const text = await res.text();
  let data = null;
  try {
    data = text ? JSON.parse(text) : null;
