describe('quest_progress_updates_from_cross_module_actions', () => {
  const suffix = `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
  const playerId = `quest-player-${suffix}`;
  let questId;
  let mapId;

  afterAll(async () => {
    if (mapId) {
      await safeDelete(`/api/editor/maps/${mapId}`);
    }
    await safeDelete(`/api/players/${playerId}`);
  });

  it('should sync quest progress independently from separate cross-module actions and show correct state transitions', async () => {
    // --- Step 1: Create player ---
    const { res: playerRes, data: playerData } = await request('POST', '/api/players', {
      id: playerId,
      name: `quest-player-${suffix}`,
      level: 5,
      gold: 100,
      skillPoints: 0,
      inventory: [],
      equipment: {},
    });
    expect(playerRes.status, `create player should succeed, got ${playerRes.status}`).toBeLessThan(300);
    const actualPlayerId = playerData?.id || playerData?.playerId || playerId;
    expect(actualPlayerId, 'player id should exist').toBeTruthy();

    // --- Step 2: Create a quest with cross-module objectives ---
    const questPayload = {
      title: `Cross Module Quest ${suffix}`,
      type: 'main',
      playerId: actualPlayerId,
      objectives: [
        { type: 'clear_level', target: 'level_1', required: 1, current: 0 },
        { type: 'defeat_enemy', target: 'slime', required: 2, current: 0 },
        { type: 'obtain_item', target: 'quest_gem', required: 1, current: 0 },
        { type: 'test_map', target: 'any', required: 1, current: 0 },
      ],
    };
    const { res: questRes, data: questData } = await request('POST', `/api/players/${actualPlayerId}/quests`, questPayload);
    expect(questRes.status, `create quest should succeed, got ${questRes.status}`).toBeLessThan(300);
    questId = questData?.id || questData?.questId;
    expect(questId, 'quest id should exist').toBeTruthy();

    // --- Step 2b: Verify initial quest status is 'active' / 'in_progress' ---
    const { res: initialQuestRes, data: initialQuestData } = await request(
      'GET',
      `/api/players/${actualPlayerId}/quests/${questId}`
    );
    expect(initialQuestRes.status, 'get initial quest should return 200').toBe(200);
    const initialStatus = String(initialQuestData?.status || '').toLowerCase();
    expect(
      ['active', 'in_progress', 'accepted'].includes(initialStatus),
      `initial quest status should be active/in_progress, got '${initialStatus}'`
    ).toBe(true);

    // --- Step 3: Defeat enemies (independent action) ---
    const { res: enemyRes } = await request('POST', `/api/players/${actualPlayerId}/combat/defeat`, {
      enemies: [{ enemyCode: 'slime', count: 2 }],
    });
    expect(
      [200, 201].includes(enemyRes.status),
      `defeat enemies should succeed, got ${enemyRes.status}`
    ).toBe(true);

    // Check quest progress after defeating enemies — should still be in_progress
    const { res: midQuestRes1, data: midQuestData1 } = await request(
      'GET',
      `/api/players/${actualPlayerId}/quests/${questId}`
    );
    expect(midQuestRes1.status).toBe(200);
    const midStatus1 = String(midQuestData1?.status || '').toLowerCase();
    expect(
      ['active', 'in_progress', 'accepted'].includes(midStatus1),
      `quest should still be in_progress after partial completion, got '${midStatus1}'`
    ).toBe(true);
    // defeat_enemy objective should have progressed
    const enemyObj1 = (midQuestData1?.objectives || []).find(o => o.type === 'defeat_enemy');
    if (enemyObj1) {
      expect(enemyObj1.current, 'defeat_enemy progress should be >= 2').toBeGreaterThanOrEqual(2);
    }

    // --- Step 4: Obtain item (independent action) ---
    const { res: itemRes } = await request('POST', `/api/players/${actualPlayerId}/inventory/add`, {
      items: [{ itemId: 'quest_gem', qty: 1 }],
    });
    expect(
      [200, 201].includes(itemRes.status),
      `obtain item should succeed, got ${itemRes.status}`
    ).toBe(true);

    // --- Step 5: Complete level (independent action) ---
    const { res: levelRes } = await request('POST', `/api/players/${actualPlayerId}/levels/level_1/complete`, {
      clearTime: 60,
    });
    expect(
      [200, 201].includes(levelRes.status),
      `complete level should succeed, got ${levelRes.status}`
    ).toBe(true);

    // --- Step 6: Create and test a map (independent action) ---
    const { res: mapRes, data: mapData } = await request('POST', '/api/editor/maps', {
      name: `Quest Test Map ${suffix}`,
      ownerId: actualPlayerId,
      width: 8,
      height: 4,
      tiles: [['S', '.', '.', '.', '.', '.', '.', 'E']],
      spawn: { x: 0, y: 0 },
      goal: { x: 7, y: 0 },
    });
    expect(mapRes.status, `create map should succeed, got ${mapRes.status}`).toBeLessThan(300);
    mapId = mapData?.id || mapData?.mapId;
    expect(mapId, 'map id should exist').toBeTruthy();

    const { res: testRes } = await request('POST', `/api/editor/maps/${mapId}/test`, {
      playerId: actualPlayerId,
      result: 'success',
    });
    expect(
      [200, 201].includes(testRes.status),
      `test map should succeed, got ${testRes.status}`
    ).toBe(true);

    // --- Step 7: Verify all quest objectives are now met ---
    const { res: finalQuestRes, data: finalQuestData } = await request(
      'GET',
      `/api/players/${actualPlayerId}/quests/${questId}`
    );
    expect(finalQuestRes.status, `get quest should return 200, got ${finalQuestRes.status}`).toBe(200);
    expect(finalQuestData, 'quest data should be returned').toBeTruthy();

    const finalStatus = String(finalQuestData.status || '').toLowerCase();
    expect(
      ['claimable', 'completed', 'ready'].includes(finalStatus),
      `all objectives met; quest status should be claimable/completed, got '${finalStatus}'`
    ).toBe(true);

    expect(Array.isArray(finalQuestData.objectives), 'quest objectives should be array').toBe(true);

    const clearObj = finalQuestData.objectives.find(o => o.type === 'clear_level');
    const enemyObj = finalQuestData.objectives.find(o => o.type === 'defeat_enemy');
    const itemObj = finalQuestData.objectives.find(o => o.type === 'obtain_item');
    const testObj = finalQuestData.objectives.find(o => o.type === 'test_map');

    expect(clearObj, 'clear_level objective should exist').toBeTruthy();
    expect(enemyObj, 'defeat_enemy objective should exist').toBeTruthy();
    expect(itemObj, 'obtain_item objective should exist').toBeTruthy();
    expect(testObj, 'test_map objective should exist').toBeTruthy();

    expect(clearObj.current, 'clear_level current >= 1').toBeGreaterThanOrEqual(1);
    expect(enemyObj.current, 'defeat_enemy current >= 2').toBeGreaterThanOrEqual(2);
    expect(itemObj.current, 'obtain_item current >= 1').toBeGreaterThanOrEqual(1);
    expect(testObj.current, 'test_map current >= 1').toBeGreaterThanOrEqual(1);

    // --- Step 8: Re-query to simulate refresh / persistence ---
    const { res: refreshRes, data: refreshData } = await request(
      'GET',
      `/api/players/${actualPlayerId}/quests/${questId}`
    );
    expect(refreshRes.status, 'quest data should persist after re-query').toBe(200);
    const refreshStatus = String(refreshData?.status || '').toLowerCase();
    expect(
      ['claimable', 'completed', 'ready'].includes(refreshStatus),
      `quest status should persist after refresh, got '${refreshStatus}'`
    ).toBe(true);
  });
});

