describe('buff_consumable_prevents_infinite_stacking', () => {
  it('should prevent infinite stacking of the same temporary buff by refreshing duration or keeping a single active instance', async () => {
    const suffix = `${Date.now()}_${Math.random().toString(36).slice(2, 8)}`;
    const playerId = `buff-player-${suffix}`;
    const buffItemId = `atk-buff-${suffix}`;

    await request('POST', '/api/test/items', {
      items: [
        {
          itemId: buffItemId,
          type: 'consumable',
          effects: [{ kind: 'buff', buffId: 'atk_up', stat: 'atk', value: 10, durationSec: 300 }],
        },
      ],
    });

    await request('POST', '/api/test/players', {
      playerId,
      stats: { atk: 20 },
      inventory: [{ itemId: buffItemId, quantity: 2 }],
      activeBuffs: [],
    });

    const firstUse = await request('POST', `/api/players/${playerId}/items/use`, { itemId: buffItemId, quantity: 1 });
    expect(firstUse.res.status, `expected first buff use status 200 or 201, got ${firstUse.res.status}`).toBeGreaterThanOrEqual(200);
    expect(firstUse.res.status, `expected first buff use status < 300, got ${firstUse.res.status}`).toBeLessThan(300);

    const afterFirst = await request('GET', `/api/players/${playerId}`, undefined);
    expect(afterFirst.res.status, `expected player fetch after first buff use status 200, got ${afterFirst.res.status}`).toBe(200);
    const p1 = afterFirst.data.player || afterFirst.data;
    const buffs1 = p1.activeBuffs || [];
    const atkBuff1 = buffs1.filter(b => (b.buffId || b.id) === 'atk_up');
    expect(atkBuff1.length, `expected one active atk_up buff after first use, got ${atkBuff1.length}`).toBe(1);
    expect(p1.stats?.atk, `atk should be 30 after first buff use, got ${p1.stats?.atk}`).toBe(30);

    const firstRemaining = atkBuff1[0]?.remainingSec ?? atkBuff1[0]?.durationSec;

    const secondUse = await request('POST', `/api/players/${playerId}/items/use`, { itemId: buffItemId, quantity: 1 });
    expect(secondUse.res.status, `expected second buff use to succeed or be gracefully handled, got ${secondUse.res.status}`).toBeGreaterThanOrEqual(200);
    expect(secondUse.res.status, `expected second buff use status < 300, got ${secondUse.res.status}`).toBeLessThan(300);

    const afterSecond = await request('GET', `/api/players/${playerId}`, undefined);
    expect(afterSecond.res.status, `expected player fetch after second buff use status 200, got ${afterSecond.res.status}`).toBe(200);
    const p2 = afterSecond.data.player || afterSecond.data;
    const buffs2 = p2.activeBuffs || [];
    const atkBuff2 = buffs2.filter(b => (b.buffId || b.id) === 'atk_up');
    expect(atkBuff2.length, `same buff should not stack into multiple active entries, got ${atkBuff2.length}`).toBe(1);
    expect(p2.stats?.atk, `atk should not infinitely stack beyond a single buff instance; expected 30, got ${p2.stats?.atk}`).toBe(30);

    const secondRemaining = atkBuff2[0]?.remainingSec ?? atkBuff2[0]?.durationSec;
    expect(secondRemaining, 'expected remaining/duration field to exist for active buff').toBeTruthy();
    expect(secondRemaining, `second use should refresh or keep duration, expected >= first duration ${firstRemaining}, got ${secondRemaining}`).toBeGreaterThanOrEqual(firstRemaining || 0);

    await safeDelete('/api/test/items');
    await safeDelete(`/api/test/players/${playerId}`);
  });
});

