describe('round20_editor_validation_rules', () => {
  const profileId = randomId('round20-profile');
  const cleanupPaths = [];

  afterAll(async () => {
    await safeDelete(cleanupPaths);
  });

  it('should return all validation issues at once for a map violating path, spike-on-spawn, and size rules', async () => {
    // Build a map that violates ALL rules simultaneously:
    // 1. Size exceeds limit (999x999)
    // 2. Spike directly on spawn point
    // 3. Path from spawn to goal is truly blocked (wall between them)
    // Construct tiles where spawn and goal are separated by a solid wall column
    const height = 999;
    const width = 999;
    const tiles = [];
    for (let y = 0; y < Math.min(height, 5); y++) {
      const row = [];
      for (let x = 0; x < Math.min(width, 10); x++) {
        if (x === 3) row.push('W'); // Wall column blocking path
        else if (x === 0 && y === 0) row.push('S'); // Spawn
        else if (x === 9 && y === 0) row.push('E'); // Goal
        else row.push('.');
      }
      tiles.push(row);
    }

    const invalidMap = {
      profileId,
      name: randomId('round20-badmap'),
      width,
      height,
      tiles,
      spawn: { x: 0, y: 0 },
      goal: { x: 9, y: 0 },
      hazards: [{ type: 'spike', x: 0, y: 0 }], // Spike on spawn
    };

    // Validate: expect all issues returned at once
    const validate = await request('POST', '/api/editor/maps/validate', invalidMap);
    expect(
      [200, 400, 422].includes(validate.res.status),
      `validation endpoint should respond 200/400/422, got ${validate.res.status}`
    ).toBe(true);

    const issues = validate.body?.issues || validate.body?.errors || validate.body?.problems || [];
    expect(Array.isArray(issues), `expected issues array, got ${typeof issues}: ${JSON.stringify(validate.body)}`).toBe(true);

    // Must have at least 3 distinct issues (path, spike-on-spawn, size)
    expect(
      issues.length,
      `expected at least 3 validation issues, got ${issues.length}: ${JSON.stringify(issues)}`
    ).toBeGreaterThanOrEqual(3);

    const issuesText = JSON.stringify(issues).toLowerCase();

    // Path-blocked issue
    expect(
      /path|unreachable|blocked|不可达|路径|通路/.test(issuesText),
      `should mention path problem: ${issuesText}`
    ).toBe(true);

    // Spike-on-spawn issue
    expect(
      /spike.*spawn|spawn.*spike|出生.*尖刺|尖刺.*出生|hazard.*spawn/.test(issuesText),
      `should mention spike on spawn: ${issuesText}`
    ).toBe(true);

    // Size limit issue
    expect(
      /size|dimension|width|height|尺寸|上限|超出/.test(issuesText),
      `should mention size limit: ${issuesText}`
    ).toBe(true);
  });

  it('should reject saving an oversized/invalid map', async () => {
    const invalidMap = {
      profileId,
      name: randomId('round20-oversized'),
      width: 999,
      height: 999,
      tiles: [['S', '.', 'E']],
      spawn: { x: 0, y: 0 },
      goal: { x: 2, y: 0 },
      hazards: [{ type: 'spike', x: 0, y: 0 }],
    };

    const saveBroken = await request('POST', '/api/editor/maps', invalidMap);
    expect(
      [400, 422, 403, 409].includes(saveBroken.res.status),
      `saving oversized/invalid map should be rejected with 4xx, got ${saveBroken.res.status}`
    ).toBe(true);
  });

  it('should reject testing an invalid map', async () => {
    // Create a map that is valid enough to save but then corrupt it
    const validMapName = randomId('round20-testblock');
    const validMap = {
      profileId,
      name: validMapName,
      width: 5,
      height: 3,
      tiles: [
        ['S', '.', '.', '.', 'E'],
        ['.', '.', '.', '.', '.'],
        ['.', '.', '.', '.', '.'],
      ],
