    });
    // Try PATCH if PUT fails
    if (corrupt.res.status >= 400) {
      await request('PATCH', `/api/editor/maps/${mapId}`, {
        spawn: null,
        goal: null,
        hazards: [{ type: 'spike', x: 0, y: 0 }],
      });
    }

    // Check map list for anomaly marker
    const list = await request('GET', `/api/editor/maps?profileId=${encodeURIComponent(profileId)}`);
    expect(list.res.status, 'map list should return 200').toBe(200);

    const maps = list.body?.maps || list.body || [];
    expect(Array.isArray(maps), 'map list should be an array').toBe(true);

    const corruptedEntry = maps.find(m =>
      (m.id || m.mapId) === mapId || (m.name || m.title) === validMapName
    );
    expect(corruptedEntry, 'corrupted map should appear in map list').toBeTruthy();

    const hasAnomaly = Boolean(
      corruptedEntry.invalid ||
      corruptedEntry.hasIssues ||
      corruptedEntry.validationFailed ||
      corruptedEntry.broken ||
      corruptedEntry.status === 'invalid' ||
      corruptedEntry.status === 'broken' ||
      corruptedEntry.anomaly ||
      corruptedEntry.error
    );
    expect(
      hasAnomaly,
      `corrupted map should have anomaly marker, got entry: ${JSON.stringify(corruptedEntry)}`
    ).toBe(true);
  });
});

import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function request(method, path, body) {
  const res = await fetch(`${BASE_URL}${path}`, {
    method,
    headers: { 'Content-Type': 'application/json' },
    body: body === undefined ? undefined : JSON.stringify(body),
  });
  const text = await res.text();
  let json = null;
  try {
    json = text ? JSON.parse(text) : null;
  } catch {
    json = text;
  }
  return { res, body: json };
}

function randomId(prefix) {
  return `${prefix}-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
}

async function safeDelete(paths) {
  for (const path of paths) {
    try {
      await fetch(`${BASE_URL}${path}`, { method: 'DELETE' });
    } catch {}
  }
}

async function tryPaths(method, paths, body) {
  for (const path of paths) {
    const result = await request(method, path, body);
    if (result.res.status < 400) return { ...result, usedPath: path };
  }
  const last = await request(method, paths[paths.length - 1], body);
  return { ...last, usedPath: paths[paths.length - 1] };
}

describe('round15_regression_baseline_unchanged', () => {
  it('should verify: (1) editor test mode isolated from formal progress, (2) load-save fully restores state, (3) best score only updates when improved', async () => {
    const profileId = randomId('round15-profile');
    const mapName = randomId('round15-map');
    const cleanupPaths = [];

    try {
      // === Setup: create a profile/save with known state ===
      const createProfile = await tryPaths('POST', [
        '/api/saves',
        '/api/players',
        '/api/test-players',
      ], {
        profileId,
        playerId: profileId,
        playerName: 'Verifier Round15',
        gold: 100,
        bestScore: 12,
        progress: { currentLevel: 2, completedLevels: [1] },
        inventory: [{ itemId: 'health-potion', qty: 3 }],
        skills: { slash: 1, fireball: 1 },
        activeSkills: ['fireball'],
        equipment: { weapon: 'basic-sword' },
        levelUnlocks: [1, 2],
        profile: {
          gold: 100,
          bestScore: 12,
          progress: { currentLevel: 2, completedLevels: [1] },
          inventory: [{ itemId: 'health-potion', qty: 3 }],
          skills: { slash: 1, fireball: 1 },
          activeSkills: ['fireball'],
          equipment: { weapon: 'basic-sword' },
          levelUnlocks: [1, 2],
        },
      });

      expect(createProfile.res.status, `Save creation endpoint must succeed, got ${createProfile.res.status}`).toBeGreaterThanOrEqual(200);
      expect(createProfile.res.status).toBeLessThan(300);

      const saveId = createProfile.body?.id || createProfile.body?.saveId || createProfile.body?.profileId || profileId;
      cleanupPaths.push(`/api/saves/${saveId}`, `/api/players/${saveId}`, `/api/test-players/${saveId}`);

      // === Create an editor map ===
      const createMap = await tryPaths('POST', [
        '/api/editor/maps',
        `/api/players/${saveId}/maps`,
        '/api/maps',
      ], {
        profileId: saveId,
        playerId: saveId,
        name: mapName,
        width: 12,
        height: 8,
        tiles: Array.from({ length: 8 }, () => Array.from({ length: 12 }, () => 0)),
        spawn: { x: 1, y: 1 },
        goal: { x: 10, y: 6 },
      });

      expect(createMap.res.status, `Map creation must succeed, got ${createMap.res.status}`).toBeGreaterThanOrEqual(200);
      expect(createMap.res.status).toBeLessThan(300);

      const mapId = createMap.body?.id || createMap.body?.mapId;
      if (mapId) {
        cleanupPaths.push(`/api/editor/maps/${mapId}`, `/api/maps/${mapId}`);
      }

      // === (1) Test mode isolation: run editor test, verify no formal pollution ===
      const testModeRun = await tryPaths('POST', [
        '/api/editor/test-runs',
        `/api/editor/maps/${mapId}/test`,
        `/api/players/${saveId}/test-run`,
      ], {
        profileId: saveId,
        playerId: saveId,
        mapId,
        result: 'success',
        deaths: 3,
      });
      // Test mode endpoint must exist and succeed
      expect(testModeRun.res.status, `Test mode run endpoint must succeed, got ${testModeRun.res.status}`).toBeGreaterThanOrEqual(200);
      expect(testModeRun.res.status).toBeLessThan(300);

      // Fetch state after test mode
      const afterTestMode = await tryPaths('GET', [
        `/api/saves/${encodeURIComponent(saveId)}`,
        `/api/players/${encodeURIComponent(saveId)}/state`,
        `/api/players/${encodeURIComponent(saveId)}`,
      ]);
      expect(afterTestMode.res.status).toBeGreaterThanOrEqual(200);
      expect(afterTestMode.res.status).toBeLessThan(300);
      const afterTestBody = afterTestMode.body || {};

      // Test mode items should NOT appear in formal inventory
      const inventory = afterTestBody.inventory ?? afterTestBody.profile?.inventory ?? afterTestBody.items ?? [];
      const invStr = JSON.stringify(inventory);
      expect(invStr, 'test-mode rewards should not appear in formal inventory').not.toMatch(/test-gem/);

      // Test mode gold should NOT be added to formal gold
      const goldAfterTest = afterTestBody.gold ?? afterTestBody.profile?.gold;
      expect(goldAfterTest, 'gold should remain 100, not increased by test mode').toBe(100);

      // Test mode deaths should NOT be in formal death/failure count
      const formalDeaths = afterTestBody.deaths ?? afterTestBody.failureCount ?? afterTestBody.progress?.deaths ?? afterTestBody.profile?.deaths;
      if (typeof formalDeaths === 'number') {
        expect(formalDeaths, 'test mode deaths should not be counted in formal records').toBe(0);
      }

      // Test mode completion should NOT affect formal completion status
      const completedLevels = afterTestBody.progress?.completedLevels ?? afterTestBody.profile?.progress?.completedLevels ?? [];
      expect(completedLevels, 'test mode should not add to completed levels').toEqual([1]);

      // Test mode should NOT affect level unlocks
      const levelUnlocks = afterTestBody.levelUnlocks ?? afterTestBody.profile?.levelUnlocks ?? [];
      if (Array.isArray(levelUnlocks) && levelUnlocks.length > 0) {
        expect(levelUnlocks, 'test mode should not unlock new formal levels').toEqual(expect.arrayContaining([1, 2]));
        expect(levelUnlocks.length, 'level unlocks should not grow from test mode').toBeLessThanOrEqual(2);
      }

      // === (2) Load-save fully restores state ===
      // Modify the state: add gold, change skill
      const modifyState = await tryPaths('PATCH', [
        `/api/saves/${encodeURIComponent(saveId)}`,
        `/api/players/${encodeURIComponent(saveId)}/state`,
        `/api/players/${encodeURIComponent(saveId)}`,
      ], {
        gold: 200,
        skills: { slash: 1, fireball: 1, shield: 1 },
        activeSkills: ['fireball', 'shield'],
        equipment: { weapon: 'basic-sword', armor: 'leather-vest' },
        inventory: [
          { itemId: 'health-potion', qty: 3 },
          { itemId: 'magic-stone', qty: 1 },
        ],
      });
      expect(modifyState.res.status, `State modification must succeed, got ${modifyState.res.status}`).toBeLessThan(300);

      // Now load (read) the save and verify full restoration
      const loadedSave = await tryPaths('GET', [
        `/api/saves/${encodeURIComponent(saveId)}`,
        `/api/players/${encodeURIComponent(saveId)}/state`,
        `/api/players/${encodeURIComponent(saveId)}`,
      ]);
      expect(loadedSave.res.status).toBeGreaterThanOrEqual(200);
      expect(loadedSave.res.status).toBeLessThan(300);

      const loaded = loadedSave.body || {};
      expect(loaded, 'loaded save should exist').toBeTruthy();

      // Verify skills restored - unconditional assertion
      const skills = loaded.skills ?? loaded.profile?.skills;
      expect(skills, 'skills should be present in loaded save').toBeDefined();
      expect(skills.slash, 'skill slash should be restored').toBe(1);
      expect(skills.fireball, 'skill fireball should be restored').toBe(1);

      // Verify active skill slots restored - unconditional
      const activeSkills = loaded.activeSkills ?? loaded.profile?.activeSkills;
      expect(activeSkills, 'activeSkills should be present in loaded save').toBeDefined();
      expect(Array.isArray(activeSkills), 'activeSkills should be an array').toBe(true);
      expect(activeSkills, 'active skills should include fireball').toEqual(expect.arrayContaining(['fireball']));

      // Verify equipment restored - unconditional
      const equip = loaded.equipment ?? loaded.profile?.equipment;
      expect(equip, 'equipment should be present in loaded save').toBeDefined();
      expect(equip.weapon, 'weapon equipment should be restored').toBe('basic-sword');

      // Verify inventory restored
      const inv = loaded.inventory ?? loaded.profile?.inventory ?? loaded.items ?? [];
      expect(Array.isArray(inv), 'inventory should be an array').toBe(true);
      expect(inv.length, 'inventory should not be empty').toBeGreaterThan(0);

      // Verify level unlocks / progress restored
      const progress = loaded.progress ?? loaded.profile?.progress ?? {};
      expect(progress.completedLevels || [], 'completed levels should be restored').toEqual(expect.arrayContaining([1]));
      expect(progress.currentLevel, 'current level should be restored').toBe(2);

      // Verify bestScore restored
      const bestScore = loaded.bestScore ?? loaded.profile?.bestScore;
      expect(bestScore, 'best score should be restored').toBe(12);

      // === (3) Best score only updates when improved ===
      const bestBefore = bestScore;
      expect(typeof bestBefore, 'bestScore should be a number').toBe('number');

      // Attempt to submit a WORSE score
      const lowerScoreUpdate = await tryPaths('POST', [
        `/api/saves/${encodeURIComponent(saveId)}/best-score`,
        `/api/players/${encodeURIComponent(saveId)}/best-score`,
        `/api/players/${encodeURIComponent(saveId)}/score`,
      ], {
        score: 5,
        levelId: 'level-1',
      });
      // This endpoint must exist
      expect(lowerScoreUpdate.res.status, `Best score update endpoint must exist, got ${lowerScoreUpdate.res.status}`).not.toBe(404);

      const progressAfterWorse = await tryPaths('GET', [
        `/api/saves/${encodeURIComponent(saveId)}`,
        `/api/players/${encodeURIComponent(saveId)}/state`,
        `/api/players/${encodeURIComponent(saveId)}`,
      ]);
      expect(progressAfterWorse.res.status).toBeLessThan(300);
      const bestAfterWorse = progressAfterWorse.body?.bestScore ?? progressAfterWorse.body?.profile?.bestScore;
      expect(bestAfterWorse, `worse score (5) should NOT replace best score (${bestBefore})`).toBe(bestBefore);

      // Attempt to submit a BETTER score
      const betterScoreUpdate = await tryPaths('POST', [
        `/api/saves/${encodeURIComponent(saveId)}/best-score`,
        `/api/players/${encodeURIComponent(saveId)}/best-score`,
        `/api/players/${encodeURIComponent(saveId)}/score`,
      ], {
        score: 99,
        levelId: 'level-1',
      });
      expect(betterScoreUpdate.res.status, `Better score update must succeed, got ${betterScoreUpdate.res.status}`).toBeLessThan(300);

      const progressAfterBetter = await tryPaths('GET', [
        `/api/saves/${encodeURIComponent(saveId)}`,
        `/api/players/${encodeURIComponent(saveId)}/state`,
        `/api/players/${encodeURIComponent(saveId)}`,
      ]);
      expect(progressAfterBetter.res.status).toBeLessThan(300);
      const bestAfterBetter = progressAfterBetter.body?.bestScore ?? progressAfterBetter.body?.profile?.bestScore;
      expect(bestAfterBetter, 'better score (99) should update best score').toBe(99);
    } finally {
      await safeDelete(cleanupPaths);
    }
  });
});

