      expect(manualSaveData.slot, `saved slot should be 1, got ${manualSaveData?.slot}`).toBe(1);
      expect(String(manualSaveData.type || '').toLowerCase(), `save type should be manual, got ${manualSaveData?.type}`).toBe('manual');

      const { res: mutateRes } = await request('PATCH', `/api/players/${playerId}`, {
        gold: 5,
        level: 1,
        currentStage: 'stage_mutated',
      });
      expect([200, 204].includes(mutateRes.status), `mutate progress status should be 200/204, got ${mutateRes.status}`).toBe(true);

      const { res: autoSaveRes } = await request('POST', `/api/players/${playerId}/saves/auto`, {
        slot: 0,
      });
      expect([200, 201].includes(autoSaveRes.status), `auto save status should be 200/201, got ${autoSaveRes.status}`).toBe(true);

      const { res: loadManualRes, data: loadManualData } = await request('POST', `/api/players/${playerId}/saves/load`, {
