      expect(String(loadManualData.loadedFromType || loadManualData.type || '').toLowerCase()).toMatch(/manual/);

      const { res: playerAfterManualRes, data: playerAfterManualData } = await request('GET', `/api/players/${playerId}`);
      expect(playerAfterManualRes.status, `get player after manual load should be 200, got ${playerAfterManualRes.status}`).toBe(200);
      expect(playerAfterManualData.gold, `gold after loading manual save should restore to 100, got ${playerAfterManualData?.gold}`).toBe(100);
      expect(playerAfterManualData.level, `level after loading manual save should restore to 3, got ${playerAfterManualData?.level}`).toBe(3);

      const { res: mutateAgainRes } = await request('PATCH', `/api/players/${playerId}`, {
        gold: 999,
        level: 9,
      });
      expect([200, 204].includes(mutateAgainRes.status), `second mutate status should be 200/204, got ${mutateAgainRes.status}`).toBe(true);

      const { res: loadAutoRes, data: loadAutoData } = await request('POST', `/api/players/${playerId}/saves/load`, {
        slot: 0,
        type: 'auto',
      });
      expect([200, 201].includes(loadAutoRes.status), `load auto save status should be 200/201, got ${loadAutoRes.status}`).toBe(true);
      expect(String(loadAutoData.loadedFromType || loadAutoData.type || '').toLowerCase()).toMatch(/auto/);

      const { res: deleteRes } = await request('DELETE', `/api/players/${playerId}/saves/manual/1`);
      expect([200, 204].includes(deleteRes.status), `delete manual save status should be 200/204, got ${deleteRes.status}`).toBe(true);

      const { res: loadDeletedRes, data: loadDeletedData } = await request('POST', `/api/players/${playerId}/saves/load`, {
        slot: 1,
        type: 'manual',
      });
      expect([400, 404, 409, 422].includes(loadDeletedRes.status), `loading deleted slot should fail with 400/404/409/422, got ${loadDeletedRes.status}`).toBe(true);
      expect(String(loadDeletedData?.reason || loadDeletedData?.code || loadDeletedData?.message || '').toLowerCase()).toMatch(/empty|not found|deleted|no save|slot/);
    } finally {
      if (playerId) await safeDelete(`/api/players/${playerId}`);
    }
  });
});

import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function request(method: string, path: string, body?: any) {
  const res = await fetch(`${BASE_URL}${path}`, {
    method,
    headers: { 'Content-Type': 'application/json' },
    body: body === undefined ? undefined : JSON.stringify(body),
  });
  let data: any = null;
  try {
    data = await res.json();
  } catch {
    data = null;
  }
  return { res, data };
}

async function tryPaths(method: string, paths: string[], body?: any) {
  for (const path of paths) {
    try {
      const r = await request(method, path, body);
      if (r.res.status > 0 && r.res.status < 500) return { ...r, usedPath: path };
    } catch {}
  }
  return { res: { status: 0 } as any, data: null, usedPath: '' };
}

async function safeDelete(path: string) {
  try {
    await fetch(`${BASE_URL}${path}`, { method: 'DELETE' });
  } catch {}
}

function extractSkillSlots(data: any): any {
  return data?.slots || data?.activeSkillSlots || data?.equippedSkills || data?.skillSlots || data;
}

describe('equipped_skills_persist_across_pages', () => {
  it('should persist active skill bar configuration across reads, page transitions, level entry/exit, and enforce max 3 slots', async () => {
    const suffix = `${Date.now()}_${Math.random().toString(36).slice(2, 8)}`;
    const playerId = `persist-skill-player-${suffix}`;
    const levelId = `persist-level-${suffix}`;
    const slots = ['slash', 'roll', 'focus'];

    try {
      // Setup player with learned skills
      const playerCreate = await tryPaths('POST', ['/api/test/players', '/api/test-players', '/api/players'], {
        playerId,
        learnedSkills: ['slash', 'roll', 'focus', 'extra-skill'],
        activeSkillSlots: [],
        skills: {
          learned: ['slash', 'roll', 'focus', 'extra-skill'],
          active: [],
        },
      });
      expect(playerCreate.res.status, 'player creation should succeed').toBeGreaterThanOrEqual(200);
      expect(playerCreate.res.status).toBeLessThan(300);

      // Setup test level
      await tryPaths('POST', ['/api/test/levels', '/api/levels'], { levelId });

      // === Step 1: Save skill slots (3 skills) ===
      const saveRes = await tryPaths('PUT', [
        `/api/players/${playerId}/skill-slots`,
        `/api/players/${playerId}/active-skills`,
        `/api/players/${playerId}/skills/active`,
      ], { slots });
      expect(saveRes.res.status, 'save skill slots should succeed (2xx)').toBeGreaterThanOrEqual(200);
      expect(saveRes.res.status).toBeLessThan(300);
      const saveSlotPath = saveRes.usedPath;

      // === Step 2: First read - verify slots persisted ===
      const firstRead = await tryPaths('GET', [
        `/api/players/${playerId}/skill-slots`,
        `/api/players/${playerId}/active-skills`,
        `/api/players/${playerId}/skills/active`,
      ]);
      expect(firstRead.res.status, 'first slot read should return 200').toBe(200);
      const firstSlots = extractSkillSlots(firstRead.data);
      expect(firstSlots, 'stored slots should equal configured slots').toEqual(slots);
      expect(Array.isArray(firstSlots) ? firstSlots.length : 0, 'should have exactly 3 equipped skills').toBe(3);
      const readSlotPath = firstRead.usedPath;

      // === Step 3: Simulate page switch to character page - verify consistency ===
      const charPage = await tryPaths('GET', [
        `/api/players/${playerId}`,
        `/api/players/${playerId}/state`,
      ]);
      expect(charPage.res.status, 'character page fetch should succeed').toBe(200);
      const charData = charPage.data?.player || charPage.data?.profile || charPage.data;
      const charSkills = charData?.activeSkillSlots || charData?.equippedSkills || charData?.skills?.active;
      // Character page should show same skill configuration
      expect(charSkills, 'character page must show skill slots').toBeDefined();
      if (charSkills) {
        expect(charSkills, 'character page should show same skill slots').toEqual(slots);
      }

      // === Step 4: Simulate page switch to inventory/backpack ===
      await tryPaths('GET', [
        `/api/players/${playerId}/inventory`,
        `/api/players/${playerId}/backpack`,
      ]);

      // === Step 5: Read skill slots again after "page switches" ===
      const afterPageSwitch = await request('GET', `${BASE_URL.replace(BASE_URL, '')}${readSlotPath || `/api/players/${playerId}/skill-slots`}`);
      // Use the same path that worked before
      const afterSwitchRead = await tryPaths('GET', [
        `/api/players/${playerId}/skill-slots`,
        `/api/players/${playerId}/active-skills`,
        `/api/players/${playerId}/skills/active`,
      ]);
      expect(afterSwitchRead.res.status, 'slot read after page switch should return 200').toBe(200);
      const afterSwitchSlots = extractSkillSlots(afterSwitchRead.data);
      expect(afterSwitchSlots, 'slots should persist after page switches').toEqual(slots);

      // === Step 6: Enter a level and verify slots persist ===
      const enterLevel = await tryPaths('POST', [
        `/api/levels/${levelId}/enter`,
        `/api/adventure/${levelId}/enter`,
        `/api/players/${playerId}/levels/${levelId}/enter`,
      ], { playerId });
      if (enterLevel.res.status >= 200 && enterLevel.res.status < 300) {
        const inLevelSlots = enterLevel.data?.activeSkillSlots || enterLevel.data?.skillSlots || enterLevel.data?.skills?.active;
        expect(inLevelSlots, 'skill slots in level context must be present').toBeDefined();
        if (inLevelSlots) {
          expect(inLevelSlots, 'skill slots in level should match configured slots').toEqual(slots);
        }
      }

      // === Step 7: Read slots again after level entry (simulates returning from level) ===
      const afterLevel = await tryPaths('GET', [
        `/api/players/${playerId}/skill-slots`,
        `/api/players/${playerId}/active-skills`,
        `/api/players/${playerId}/skills/active`,
      ]);
      expect(afterLevel.res.status, 'slot read after level should return 200').toBe(200);
      const afterLevelSlots = extractSkillSlots(afterLevel.data);
      expect(afterLevelSlots, 'slots should persist after level transition').toEqual(slots);

      // === Step 8: Boundary - try to equip more than 3 active skills ===
      const overLimitSlots = ['slash', 'roll', 'focus', 'extra-skill'];
      const overLimitRes = await tryPaths('PUT', [
        `/api/players/${playerId}/skill-slots`,
        `/api/players/${playerId}/active-skills`,
        `/api/players/${playerId}/skills/active`,
      ], { slots: overLimitSlots });
      // Should be rejected (4xx) since max is 3
      expect(
        overLimitRes.res.status,
        `equipping 4 skills should be rejected with 4xx, got ${overLimitRes.res.status}`
      ).toBeGreaterThanOrEqual(400);
      expect(overLimitRes.res.status).toBeLessThan(500);

      // Verify slots are still the original 3 after rejected over-limit attempt
      const afterOverLimit = await tryPaths('GET', [
        `/api/players/${playerId}/skill-slots`,
        `/api/players/${playerId}/active-skills`,
        `/api/players/${playerId}/skills/active`,
      ]);
      expect(afterOverLimit.res.status).toBe(200);
      const finalSlots = extractSkillSlots(afterOverLimit.data);
      expect(finalSlots, 'slots should remain unchanged after rejected over-limit attempt').toEqual(slots);
      expect(Array.isArray(finalSlots) ? finalSlots.length : 0, 'should still have exactly 3 skills').toBe(3);

    } finally {
      // Cleanup
      await safeDelete(`/api/test/levels/${levelId}`);
      await safeDelete(`/api/levels/${levelId}`);
      await safeDelete(`/api/test/players/${playerId}`);
      await safeDelete(`/api/test-players/${playerId}`);
      await safeDelete(`/api/players/${playerId}`);
    }
  });
});

import { describe, it, expect, afterAll } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function request(method, path, body) {
  const res = await fetch(`${BASE_URL}${path}`, {
    method,
    headers: { 'Content-Type': 'application/json' },
    body: body === undefined ? undefined : JSON.stringify(body),
  });
  const text = await res.text();
  let json = null;
  try {
    json = text ? JSON.parse(text) : null;
  } catch {
    json = { raw: text };
  }
  return { res, body: json };
}

async function cleanup(paths) {
  for (const path of paths) {
    try {
      await fetch(`${BASE_URL}${path}`, { method: 'DELETE' });
    } catch {}
  }
}

describe('end_to_end_progress_and_saved_state_remain_consistent', () => {
  const playerId = `vt-e2e-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
  const mapId = `e2e-map-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
  const slotId = `slot-${Date.now()}`;
  const cleanupPaths = [
    `/api/players/${playerId}`,
    `/api/editor/maps/${mapId}`,
    `/api/players/${playerId}/saves/${slotId}`,
  ];

  afterAll(async () => {
    await cleanup(cleanupPaths);
  });

  it('should keep official progress, inventory, shop, skill, editor data, and quest state consistent through end-to-end flow including failure branch', async () => {
    // ---- Step 1: Create player ----
    const createPlayer = await request('POST', '/api/players', {
      id: playerId,
      level: 4,
      exp: 90,
      gold: 500,
      skillPoints: 3,
      inventory: [
        { itemId: 'cloth-armor', qty: 1 },
        { itemId: 'old-sword', qty: 1 },
      ],
      equipment: { weapon: 'old-sword', armor: 'cloth-armor' },
      quests: { q1: { progress: 1, status: 'active' } },
      progress: { clearedLevels: ['level-1'], bestRecords: { 'level-1': { time: 88 } } },
    });
    expect(createPlayer.res.status, `create player failed: ${createPlayer.res.status}`).toBeLessThan(300);
    const createdId = createPlayer.body?.id || createPlayer.body?.playerId || playerId;
    expect(createdId, 'player id should be returned').toBeTruthy();

    // ---- Step 2: Create custom map in editor ----
    const createMap = await request('POST', '/api/editor/maps', {
      id: mapId,
      ownerId: playerId,
      name: 'Persistent Edited Map',
      tiles: [['S', '.', '.', '.', 'E']],
      spawn: { x: 0, y: 0 },
      goal: { x: 4, y: 0 },
    });
    expect(createMap.res.status, `create map failed: ${createMap.res.status}`).toBeLessThan(300);

    // ---- Step 3: Run editor test mode (should not pollute formal progress) ----
    const testRun = await request('POST', `/api/editor/maps/${mapId}/test`, {
      playerId,
      mode: 'test',
    });
    if (testRun.res.status < 300) {
      const afterTestState = await request('GET', `/api/players/${playerId}`);
      expect(afterTestState.res.status).toBe(200);
      const clearedAfterTest = afterTestState.body?.progress?.clearedLevels || [];
      expect(clearedAfterTest, 'test mode should not add to formal cleared levels').not.toContain(mapId);
    }

    // ---- Step 4: Save initial progress ----
    const saveInitial = await request('POST', `/api/players/${playerId}/saves/${slotId}`, {
      label: 'pre-flow',
    });
    expect(saveInitial.res.status, `initial save failed: ${saveInitial.res.status}`).toBeLessThan(300);

    // ---- Step 5: Shop - Buy steel-sword ----
    const buy = await request('POST', `/api/players/${playerId}/shop/buy`, {
      itemId: 'steel-sword',
      qty: 1,
    });
    expect(buy.res.status, `buy failed: ${buy.res.status}`).toBeLessThan(300);

    // Verify gold decreased and item in inventory
    const afterBuy = await request('GET', `/api/players/${playerId}`);
    expect(afterBuy.res.status).toBe(200);
    expect(afterBuy.body.gold, 'gold should decrease after buying').toBeLessThan(500);
    const invAfterBuy = afterBuy.body.inventory || [];
    expect(
      invAfterBuy.some(i => (i.itemId || i.id) === 'steel-sword'),
      'steel-sword should be in inventory after buying'
    ).toBe(true);

    // ---- Step 6: Shop - Sell old-sword ----
    const sell = await request('POST', `/api/players/${playerId}/shop/sell`, {
      itemId: 'old-sword',
      qty: 1,
    });
    expect(sell.res.status, `sell failed: ${sell.res.status}`).toBeLessThan(300);

    const afterSell = await request('GET', `/api/players/${playerId}`);
    expect(afterSell.res.status).toBe(200);
    expect(afterSell.body.gold, 'gold should increase after selling').toBeGreaterThan(afterBuy.body.gold);
    const invAfterSell = afterSell.body.inventory || [];
    expect(
      invAfterSell.some(i => (i.itemId || i.id) === 'old-sword'),
      'old-sword should be removed from inventory after selling'
    ).toBe(false);

    // ---- Step 7: Equip steel-sword ----
    const equip = await request('POST', `/api/players/${playerId}/equipment`, {
      slot: 'weapon',
      itemId: 'steel-sword',
    });
    expect(equip.res.status, `equip failed: ${equip.res.status}`).toBeLessThan(300);

    // ---- Step 8: Allocate skill point and verify ----
    const beforeSkill = await request('GET', `/api/players/${playerId}`);
    expect(beforeSkill.res.status).toBe(200);
    const spBefore = beforeSkill.body.skillPoints;

    const skill = await request('POST', `/api/players/${playerId}/skills/allocate`, {
      skillId: 'fireball',
      points: 1,
    });
    expect(skill.res.status, `skill allocation failed: ${skill.res.status}`).toBeLessThan(300);

    // Verify skill points decreased and skill is unlocked
    const afterSkill = await request('GET', `/api/players/${playerId}`);
    expect(afterSkill.res.status).toBe(200);
    expect(afterSkill.body.skillPoints, 'skill points should decrease after allocation').toBeLessThan(spBefore);
    const playerSkills = afterSkill.body.skills || afterSkill.body.unlockedSkills || {};
    if (typeof playerSkills === 'object' && !Array.isArray(playerSkills)) {
      expect(playerSkills.fireball, 'fireball should be in unlocked skills').toBeTruthy();
    }

    // ---- Step 9: Complete level-2 with rewards ----
    const levelClear = await request('POST', `/api/players/${playerId}/levels/level-2/complete`, {
      clearTime: 75,
      rewards: { gold: 50, items: [{ itemId: 'gem', qty: 1 }] },
      expGained: 40,
    });
    expect(levelClear.res.status, `level clear failed: ${levelClear.res.status}`).toBeLessThan(300);

    // Verify leveling: check if exp caused level up
    const afterLevel = await request('GET', `/api/players/${playerId}`);
    expect(afterLevel.res.status).toBe(200);
    expect(afterLevel.body.exp, 'exp should have increased').toBeGreaterThanOrEqual(90);
    // If exp was enough for level up, level should increase
    // (90 base + 40 gained = 130, which should be enough for a level up from level 4)
    // We at least verify the field exists and is >= original
    expect(afterLevel.body.level, 'level should be >= original').toBeGreaterThanOrEqual(4);

    // ---- Snapshot state after completion for later comparison ----
    const statePostClear = afterLevel.body;
    const goldPostClear = statePostClear.gold;
    const levelPostClear = statePostClear.level;
    const invPostClear = statePostClear.inventory || [];

    // Verify gem is in inventory from rewards
    expect(
      invPostClear.some(i => (i.itemId || i.id) === 'gem'),
      'gem from reward should be in inventory'
    ).toBe(true);

    // Level-2 should be cleared
    const clearedLevels = statePostClear.progress?.clearedLevels || [];
    expect(clearedLevels, 'level-2 should be in cleared levels').toContain('level-2');

    // ---- Step 10: Save after completion ----
    const saveAfterClear = await request('POST', `/api/players/${playerId}/saves/${slotId}`, {
      label: 'post-clear',
    });
    expect(saveAfterClear.res.status, `save after clear failed`).toBeLessThan(300);

    // ---- Step 11: Verify editor map still intact ----
    const editedMap = await request('GET', `/api/editor/maps/${mapId}`);
    expect(editedMap.res.status, 'editor map should still exist').toBe(200);
    expect(
      editedMap.body?.name || editedMap.body?.title,
      'editor map name should be preserved'
    ).toBe('Persistent Edited Map');

    // ---- Step 12: Fail a formal level - temp drops should NOT persist ----
    const failRun = await request('POST', `/api/players/${playerId}/levels/level-3/fail`, {
      tempDrops: [{ itemId: 'should-not-persist', qty: 2 }],
      cause: 'death',
    });
    expect(
      [200, 201].includes(failRun.res.status),
      `fail run should be handled, got ${failRun.res.status}`
    ).toBe(true);

    // ---- Step 13: Verify failure did NOT corrupt saved progress ----
    const afterFail = await request('GET', `/api/players/${playerId}`);
    expect(afterFail.res.status).toBe(200);

    // Key fields should match post-clear state (failure should not corrupt)
    expect(afterFail.body.equipment?.weapon, 'weapon should still be steel-sword after failure').toBe('steel-sword');
    expect(afterFail.body.gold, 'gold should not decrease from failure').toBeGreaterThanOrEqual(goldPostClear);
    expect(afterFail.body.level, 'level should not decrease from failure').toBeGreaterThanOrEqual(levelPostClear);

    // Temp drops from failed level should NOT be in inventory
    const failInv = afterFail.body.inventory || [];
    expect(
      failInv.some(i => (i.itemId || i.id) === 'should-not-persist'),
      'failed run temporary drops should not be in inventory'
    ).toBe(false);

    // Gem should still be in inventory
    expect(
      failInv.some(i => (i.itemId || i.id) === 'gem'),
      'gem from earlier reward should still be in inventory'
    ).toBe(true);

    // ---- Step 14: Load save and verify persistence ----
    const loadSave = await request('POST', `/api/players/${playerId}/saves/${slotId}/load`, {
      confirm: true,
    });
    expect(loadSave.res.status, `load save failed: ${loadSave.res.status}`).toBeLessThan(300);

    const stateAfterLoad = await request('GET', `/api/players/${playerId}`);
    expect(stateAfterLoad.res.status).toBe(200);
    expect(stateAfterLoad.body.equipment?.weapon, 'weapon should be steel-sword after load').toBe('steel-sword');
    const clearedAfterLoad = stateAfterLoad.body.progress?.clearedLevels || [];
    expect(clearedAfterLoad, 'level-2 should be in cleared levels after load').toContain('level-2');
    expect(
      (stateAfterLoad.body.inventory || []).some(i => (i.itemId || i.id) === 'gem'),
      'gem should still be in inventory after load'
    ).toBe(true);

    // ---- Step 15: Verify editor map survived the whole flow ----
    const editedMapFinal = await request('GET', `/api/editor/maps/${mapId}`);
    expect(editedMapFinal.res.status, 'editor map should survive entire flow').toBe(200);
    expect(
      editedMapFinal.body?.name || editedMapFinal.body?.title,
      'editor map data should be unchanged after formal level failure'
    ).toBe('Persistent Edited Map');

    // ---- Step 16: Verify quest state ----
    const questState = await request('GET', `/api/players/${playerId}/quests`);
    expect(questState.res.status, 'quest endpoint should return 200').toBe(200);
    expect(questState.body, 'quest state should be returned').toBeTruthy();
    const questStr = JSON.stringify(questState.body);
    expect(questStr, 'quest data should include q1').toMatch(/q1/);

    // ---- Step 17: Verify summary consistency ----
    const summary = await request('GET', `/api/players/${playerId}/summary`);
    expect(summary.res.status, 'summary endpoint should return 200').toBe(200);
    expect(summary.body, 'summary should be returned').toBeTruthy();
    if (summary.body.gold !== undefined && stateAfterLoad.body.gold !== undefined) {
      expect(summary.body.gold, 'summary gold should match state gold').toBe(stateAfterLoad.body.gold);
    }
    if (summary.body.level !== undefined && stateAfterLoad.body.level !== undefined) {
      expect(summary.body.level, 'summary level should match state level').toBe(stateAfterLoad.body.level);
    }
  });
});

