describe('round11_skill_tree_revision_active_passive', () => {
  const playerId = `vt-skill-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
  const poorPlayerId = `vt-skill-poor-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
  const legacyPlayerId = `vt-skill-legacy-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
  const cleanupPaths = [
    `/api/players/${playerId}`,
    `/api/players/${poorPlayerId}`,
    `/api/players/${legacyPlayerId}`,
  ];

  afterAll(async () => {
    await cleanup(cleanupPaths);
  });

  it('should support migration from legacy skill data without type distinction to active/passive classification', async () => {
    // Create a player with old-format skill data (no type field)
    const createLegacy = await request('POST', '/api/players', {
      id: legacyPlayerId,
      level: 5,
      gold: 300,
      skillPoints: 2,
      skills: {
        slash: { points: 1 },
        vitality: { points: 1 },
      },
      activeSkillSlots: [],
      equipment: {},
    });
    expect(createLegacy.res.status, `create legacy player should succeed, got ${createLegacy.res.status}`).toBeLessThan(300);

    // Query skill tree — system should auto-classify or accept the data
    const tree = await request('GET', `/api/players/${legacyPlayerId}/skills`);
    expect(tree.res.status, `get skills should succeed, got ${tree.res.status}`).toBe(200);
    expect(tree.body, 'skill tree response body should exist').toBeTruthy();

    // The system should return skills with type information even for legacy data
    const skills = tree.body.skills || tree.body.unlockedSkills || tree.body;
    expect(skills, 'skills data should be returned').toBeTruthy();
  });

  it('should preserve unlock data, distinguish active/passive, enforce max 3 active equipped, and clearly separate learned vs equipped', async () => {
    // Setup player with 4 active skills unlocked but only 3 equipped, plus passive skills
    const createPlayer = await request('POST', '/api/players', {
      id: playerId,
      level: 12,
      gold: 500,
      skillPoints: 0,
      skills: {
        slash: { type: 'active', points: 2 },
        fireball: { type: 'active', points: 3 },
        dash: { type: 'active', points: 1 },
        shockwave: { type: 'active', points: 1 },
        vitality: { type: 'passive', points: 2 },
        focus: { type: 'passive', points: 1 },
      },
      activeSkillSlots: ['slash', 'fireball', 'dash'],
      equipment: { weapon: 'mythril-sword', armor: 'knight-armor' },
    });
    expect(createPlayer.res.status, `create player should succeed, got ${createPlayer.res.status}`).toBeLessThan(300);

    // Verify active/passive distinction in returned skill data
    const tree = await request('GET', `/api/players/${playerId}/skills`);
    expect(tree.res.status, `get skills should return 200, got ${tree.res.status}`).toBe(200);
    expect(tree.body, 'skill tree response should exist').toBeTruthy();

    const skills = tree.body.skills || tree.body.unlockedSkills;
    expect(skills, 'skills should be defined in response').toBeTruthy();

    // Passive skills must be identifiable
    if (typeof skills === 'object' && !Array.isArray(skills)) {
      expect(skills.vitality, 'vitality skill should exist in unlocked skills').toBeTruthy();
      expect(skills.vitality.type, 'vitality should be classified as passive').toBe('passive');
      expect(skills.slash, 'slash skill should exist in unlocked skills').toBeTruthy();
      expect(skills.slash.type, 'slash should be classified as active').toBe('active');
    } else if (Array.isArray(skills)) {
      const vitalitySkill = skills.find(s => s.id === 'vitality' || s.skillId === 'vitality');
      expect(vitalitySkill, 'vitality should exist in skill list').toBeTruthy();
      expect(vitalitySkill.type, 'vitality should be passive').toBe('passive');
      const slashSkill = skills.find(s => s.id === 'slash' || s.skillId === 'slash');
      expect(slashSkill, 'slash should exist in skill list').toBeTruthy();
      expect(slashSkill.type, 'slash should be active').toBe('active');
    }

    // Active skill bar should have at most 3 equipped
    const activeBar = tree.body.activeSkillSlots || tree.body.equippedActiveSkills || tree.body.activeSkills || [];
    expect(Array.isArray(activeBar), 'active skill bar should be an array').toBe(true);
    expect(activeBar.length, 'active skill bar should have at most 3 skills').toBeLessThanOrEqual(3);

    // Verify "unlocked ≠ equipped": shockwave is unlocked but NOT in activeBar
    const shockwaveEquipped = activeBar.some(s =>
      (typeof s === 'string' ? s : (s.id || s.skillId)) === 'shockwave'
    );
    expect(shockwaveEquipped, 'shockwave should NOT be in equipped active skills (unlocked ≠ equipped)').toBe(false);

    // But shockwave IS in unlocked skills
    if (typeof skills === 'object' && !Array.isArray(skills)) {
      expect(skills.shockwave, 'shockwave should be present in unlocked skills').toBeTruthy();
    } else if (Array.isArray(skills)) {
      const sw = skills.find(s => s.id === 'shockwave' || s.skillId === 'shockwave');
      expect(sw, 'shockwave should be present in unlocked skills list').toBeTruthy();
    }

    // Verify slash IS in equipped active skills
    const slashEquipped = activeBar.some(s =>
      (typeof s === 'string' ? s : (s.id || s.skillId)) === 'slash'
    );
    expect(slashEquipped, 'slash should be in equipped active skills (learned AND in effect)').toBe(true);
  });

  it('should reject equipping a 4th active skill when 3 are already equipped', async () => {
    const equipFourth = await request('POST', `/api/players/${playerId}/skills/equip`, {
      skillId: 'shockwave',
    });
    expect(
      [400, 409, 422].includes(equipFourth.res.status),
      `4th active skill equip should be rejected (max 3 limit), got ${equipFourth.res.status}`
    ).toBe(true);
    const msg = JSON.stringify(equipFourth.body || {}).toLowerCase();
    expect(msg).toMatch(/3|max|active|slot|上限|已满|limit/);
  });

  it('should reset skill tree consuming gold, return skill points, clear active bar, preserve level and equipment', async () => {
    // Get state before reset
    const beforeReset = await request('GET', `/api/players/${playerId}`);
    expect(beforeReset.res.status, `get player state should return 200`).toBe(200);
    const goldBefore = beforeReset.body.gold;
    const levelBefore = beforeReset.body.level;
    const equipmentBefore = beforeReset.body.equipment;
    const skillPointsBefore = beforeReset.body.skillPoints;

    expect(goldBefore, 'gold before reset should be defined').toBeDefined();
    expect(levelBefore, 'level before reset should be defined').toBeDefined();
    expect(equipmentBefore, 'equipment before reset should be defined').toBeDefined();

    // Reset skill tree
    const reset = await request('POST', `/api/players/${playerId}/skills/reset`);
    expect(reset.res.status, `skill reset should succeed, got ${reset.res.status}`).toBeLessThan(300);

    // Verify state after reset
    const afterReset = await request('GET', `/api/players/${playerId}`);
    expect(afterReset.res.status).toBe(200);

    // Level unchanged
    expect(afterReset.body.level, 'level should be unchanged after skill reset').toBe(levelBefore);

    // Equipment unchanged
    expect(afterReset.body.equipment, 'equipment should be unchanged after skill reset').toEqual(equipmentBefore);

    // Active skill bar cleared
    const activeAfter = afterReset.body.activeSkillSlots || afterReset.body.equippedActiveSkills || afterReset.body.activeSkills || [];
    expect(activeAfter.length, 'active skill bar should be empty after reset').toBe(0);

    // Gold reduced
    expect(afterReset.body.gold, 'gold should decrease after reset').toBeLessThan(goldBefore);

    // Skill points returned (should be more than before)
    expect(
      afterReset.body.skillPoints,
      'skill points should be refunded after reset'
    ).toBeGreaterThan(skillPointsBefore);

    // Unlocked skills should be cleared
    const unlockedAfter = afterReset.body.skills || afterReset.body.unlockedSkills;
    if (typeof unlockedAfter === 'object' && !Array.isArray(unlockedAfter)) {
      const allCleared = Object.keys(unlockedAfter).length === 0 ||
        Object.values(unlockedAfter).every(v =>
          v === 0 || v === null || (typeof v === 'object' && (v.points === 0 || v.level === 0))
        );
      expect(allCleared, 'all unlocked skills should be cleared after reset').toBe(true);
    } else if (Array.isArray(unlockedAfter)) {
      expect(unlockedAfter.length, 'unlocked skills array should be empty after reset').toBe(0);
    }
  });

  it('should reject skill reset when gold is insufficient', async () => {
    const createPoor = await request('POST', '/api/players', {
      id: poorPlayerId,
      level: 5,
      gold: 1,
      skillPoints: 0,
      skills: {
        slash: { type: 'active', points: 1 },
      },
      activeSkillSlots: ['slash'],
      equipment: {},
    });
    expect(createPoor.res.status, `create poor player should succeed`).toBeLessThan(300);

    const poorReset = await request('POST', `/api/players/${poorPlayerId}/skills/reset`);
    expect(
      [400, 403, 409, 422].includes(poorReset.res.status),
      `reset should be rejected when gold insufficient, got ${poorReset.res.status}`
    ).toBe(true);
    const msg = JSON.stringify(poorReset.body || {}).toLowerCase();
    expect(msg).toMatch(/gold|insufficient|not enough|金币|不足/);

    // Verify state unchanged after failed reset
    const poorState = await request('GET', `/api/players/${poorPlayerId}`);
    expect(poorState.res.status).toBe(200);
    expect(poorState.body.gold, 'gold should be unchanged after failed reset').toBe(1);
    const poorActive = poorState.body.activeSkillSlots || poorState.body.equippedActiveSkills || poorState.body.activeSkills || [];
    const hasSlash = poorActive.some(s =>
      (typeof s === 'string' ? s : (s.id || s.skillId)) === 'slash'
    );
    expect(hasSlash, 'active skills should be unchanged after failed reset').toBe(true);
  });
});

import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function request(method, path, body) {
  const res = await fetch(`${BASE_URL}${path}`, {
    method,
    headers: { 'Content-Type': 'application/json' },
    body: body === undefined ? undefined : JSON.stringify(body),
  });
  let data = null;
  try {
    data = await res.json();
  } catch {
    data = null;
  }
  return { res, data };
}

async function safeDelete(path) {
  try {
    await fetch(`${BASE_URL}${path}`, { method: 'DELETE' });
  } catch {}
}

function qtyOf(items, itemId) {
  if (!Array.isArray(items)) return 0;
  return items.filter(i => i.itemId === itemId).reduce((sum, i) => sum + (i.quantity || 1), 0);
}

