import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function request(method, path, body) {
  const res = await fetch(`${BASE_URL}${path}`, {
    method,
    headers: { 'Content-Type': 'application/json' },
    body: body === undefined ? undefined : JSON.stringify(body),
  });
  const text = await res.text();
  let json = null;
  try {
    json = text ? JSON.parse(text) : null;
  } catch {
    json = { raw: text };
  }
  return { res, body: json };
}

async function cleanup(paths) {
  for (const path of paths) {
    try {
      await fetch(`${BASE_URL}${path}`, { method: 'DELETE' });
    } catch {}
  }
}

async function tryPaths(method, paths, body) {
  for (const path of paths) {
    const result = await request(method, path, body);
    if (result.res.status < 400) return { ...result, usedPath: path };
  }
  const last = await request(method, paths[paths.length - 1], body);
  return { ...last, usedPath: paths[paths.length - 1] };
}

describe('round13_battle_temp_loot_isolated', () => {
  it('should apply shield before HP, mark failure when player HP reaches zero, keep enemy drops only in temp settlement, discard all temp loot on failure', async () => {
    const playerId = `vt-battle-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
    const cleanupPaths = [
      `/api/test-players/${playerId}`,
      `/api/players/${playerId}`,
      `/api/saves/${playerId}`,
    ];

    try {
      // Create player with shield and HP
      const createPlayer = await tryPaths('POST', [
        '/api/test-players',
        '/api/players',
        '/api/saves',
      ], {
        playerId,
        profileId: playerId,
        playerName: 'BattleTester',
        profile: {
          hp: 30,
          shield: 10,
          inventory: [{ itemId: 'potion', qty: 1 }],
          gold: 0,
        },
        hp: 30,
        shield: 10,
        inventory: [{ itemId: 'potion', qty: 1 }],
        gold: 0,
      });
      expect(createPlayer.res.status, `expected player creation success, got ${createPlayer.res.status}`).toBeLessThan(300);

      // === FAILURE scenario: player dies, temp loot discarded ===
      const battle = await tryPaths('POST', [
        `/api/players/${playerId}/battle/simulate`,
        `/api/players/${playerId}/battle`,
        `/api/players/${playerId}/combat/simulate`,
        `/api/battle/simulate`,
      ], {
        playerId,
        enemies: [
          { enemyId: 'slime-patrol', type: 'patrol', hp: 1, behavior: 'patrol', drop: { gold: 5, items: [{ itemId: 'slime-gel', qty: 1 }] } },
          { enemyId: 'boss-chase', type: 'chase', hp: 1, behavior: 'chase', drop: { gold: 20, items: [{ itemId: 'boss-core', qty: 1 }] } },
        ],
        turns: [
          { action: 'enemyAttack', damage: 8 },    // shield: 10 -> 2, hp stays 30
          { action: 'playerAttack', target: 'slime-patrol', damage: 99 }, // slime dies, drops slime-gel
          { action: 'enemyAttack', damage: 40 },    // shield: 2 -> 0, remaining 38 hits hp: 30 -> -8
        ],
      });
      expect(battle.res.status, `expected battle simulation success, got ${battle.res.status}`).toBeLessThan(300);

      const battleBody = battle.body || {};

      // Verify failure result - do not fallback
      const result = battleBody.result ?? battleBody.outcome ?? battleBody.status;
      expect(result, 'battle result field should exist').toBeDefined();
      expect(String(result).toLowerCase(), 'battle should result in failure/defeat').toMatch(/fail|defeat|dead|death|lose|lost/);

      // Verify shield was consumed first
      const finalShield = battleBody.player?.shield ?? battleBody.remainingShield ?? battleBody.finalShield ?? battleBody.shield;
      expect(finalShield, 'final shield field should exist').toBeDefined();
      expect(finalShield, 'final shield should be 0 after being fully consumed').toBe(0);

      // Verify HP reached zero or below
      const finalHp = battleBody.player?.hp ?? battleBody.remainingHp ?? battleBody.finalHp ?? battleBody.hp;
      expect(finalHp, 'final HP field should exist').toBeDefined();
      expect(finalHp, 'player hp should be zero or below after lethal hit').toBeLessThanOrEqual(0);

      // If the API returns per-turn state, verify shield priority on first hit
      const turns = battleBody.turns ?? battleBody.turnDetails ?? battleBody.turnLog;
      if (Array.isArray(turns) && turns.length >= 1) {
        const afterFirstHit = turns[0];
        const shieldAfterFirst = afterFirstHit.player?.shield ?? afterFirstHit.shield;
        const hpAfterFirst = afterFirstHit.player?.hp ?? afterFirstHit.hp;
        if (shieldAfterFirst !== undefined) {
          expect(shieldAfterFirst, 'after first 8-dmg hit, shield should be 2').toBe(2);
        }
        if (hpAfterFirst !== undefined) {
          expect(hpAfterFirst, 'after first hit, HP should still be 30 (shield absorbs)').toBe(30);
        }
      }

      // Verify slain enemy drop appears in temporary settlement
      const tempLoot = battleBody.temporaryLoot ?? battleBody.tempLoot ?? battleBody.settlement ?? battleBody.drops ?? battleBody.tempDrops;
      expect(tempLoot, 'temporary loot field should exist in battle response').toBeDefined();
      const tempLootStr = JSON.stringify(tempLoot);
      expect(tempLootStr, 'slain enemy drop should appear in temporary settlement').toMatch(/slime-gel/i);

      // Verify formal inventory is NOT polluted after failure
      const stateAfterFail = await tryPaths('GET', [
        `/api/players/${playerId}/state`,
        `/api/players/${playerId}`,
        `/api/saves/${playerId}`,
      ]);
      expect(stateAfterFail.res.status, 'state fetch should succeed').toBeLessThan(300);
      const failBody = stateAfterFail.body || {};
      const invStr = JSON.stringify(failBody.inventory ?? failBody.profile?.inventory ?? []);
      expect(invStr, 'failed battle temp loot (slime-gel) should not be in formal inventory').not.toMatch(/slime-gel/);
      expect(invStr, 'failed battle temp loot (boss-core) should not be in formal inventory').not.toMatch(/boss-core/);
      const goldAfterFail = failBody.gold ?? failBody.profile?.gold;
      expect(goldAfterFail, 'failed battle temp gold should not be persisted').toBe(0);

      // === SUCCESS scenario: player wins, temp loot goes to settlement ===
      // Reset player state for a success run
      const resetPlayer = await tryPaths('POST', [
        '/api/test-players',
        '/api/players',
        '/api/saves',
      ], {
        playerId,
        profileId: playerId,
        playerName: 'BattleTester',
        profile: {
          hp: 100,
          shield: 0,
          inventory: [{ itemId: 'potion', qty: 1 }],
          gold: 0,
        },
        hp: 100,
        shield: 0,
        inventory: [{ itemId: 'potion', qty: 1 }],
        gold: 0,
      });
      expect(resetPlayer.res.status, `expected player reset success, got ${resetPlayer.res.status}`).toBeLessThan(300);

      const successBattle = await tryPaths('POST', [
        `/api/players/${playerId}/battle/simulate`,
        `/api/players/${playerId}/battle`,
        `/api/players/${playerId}/combat/simulate`,
        `/api/battle/simulate`,
      ], {
        playerId,
        enemies: [
          { enemyId: 'ranged-archer', type: 'ranged', hp: 1, behavior: 'ranged', drop: { gold: 5, items: [{ itemId: 'arrow-shard', qty: 1 }] } },
        ],
        turns: [
          { action: 'playerAttack', target: 'ranged-archer', damage: 99 },
        ],
        result: 'success',
      });
      expect(successBattle.res.status, `expected success battle simulation, got ${successBattle.res.status}`).toBeLessThan(300);

      const successBody = successBattle.body || {};
      const successResult = successBody.result ?? successBody.outcome ?? successBody.status;
      expect(successResult, 'success battle result field should exist').toBeDefined();
      expect(String(successResult).toLowerCase(), 'successful battle should indicate success/victory').toMatch(/success|victory|win|clear|passed/);

      // Temp loot should be in temporary settlement, separate from stage fixed rewards
      const successTempLoot = successBody.temporaryLoot ?? successBody.tempLoot ?? successBody.settlement ?? successBody.drops ?? successBody.tempDrops;
      expect(successTempLoot, 'temp loot field should exist on success').toBeDefined();
      const successTempStr = JSON.stringify(successTempLoot);
      expect(successTempStr, 'enemy drop should appear in temp settlement on success').toMatch(/arrow-shard/i);

      // Verify temp loot is categorized separately from fixed stage rewards
      const stageRewards = successBody.stageRewards ?? successBody.rewards ?? successBody.fixedRewards ?? successBody.levelRewards;
      if (stageRewards) {
        // Stage rewards and temp drops should be in different fields
        expect(stageRewards !== successTempLoot,
          'temp enemy drops and stage fixed rewards should be in separate fields').toBe(true);
      }

      // Before confirmation, formal inventory should still not have the drops
      const stateBeforeConfirm = await tryPaths('GET', [
        `/api/players/${playerId}/state`,
        `/api/players/${playerId}`,
        `/api/saves/${playerId}`,
      ]);
      expect(stateBeforeConfirm.res.status).toBeLessThan(300);
      const preConfirmInv = JSON.stringify(stateBeforeConfirm.body?.inventory ?? stateBeforeConfirm.body?.profile?.inventory ?? []);
      expect(preConfirmInv, 'temp loot should not be in formal inventory before confirmation').not.toMatch(/arrow-shard/);
    } finally {
      await cleanup(cleanupPaths);
    }
  });
});

