describe('import_modes_preserve_existing_progress_on_merge', () => {
  it('should preserve existing formal progress on merge, avoid clearing best scores on legacy migration, and keep data unchanged on failed import', async () => {
    const suffix = `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
    let playerId;

    try {
      const { data: player } = await request('POST', '/api/players', {
        name: `merge-player-${suffix}`,
        level: 7,
        gold: 500,
      });
      playerId = player.id;
      expect(playerId, 'player id should exist').toBeTruthy();

      await request('POST', `/api/players/${playerId}/levels/complete`, {
        levelId: 'level_3',
        bestScore: 9999,
        stars: 3,
      });
      await request('POST', `/api/players/${playerId}/maps`, {
        name: `Existing Map ${suffix}`,
        layout: { width: 3, height: 1, tiles: [['S', '.', 'E']] },
      });

      const mergePayload = {
        version: 2,
        customMaps: [
          {
            name: `Imported Merge Map ${suffix}`,
            layout: { width: 5, height: 1, tiles: [['S', '.', '.', '.', 'E']] },
          },
        ],
      };

      const { res: mergeRes } = await request('POST', `/api/players/${playerId}/import-save`, {
        mode: 'merge_maps',
        payload: mergePayload,
      });
      expect([200, 201].includes(mergeRes.status), `merge maps import status should be 200/201, got ${mergeRes.status}`).toBe(true);

      const { res: mergedStateRes, data: mergedState } = await request('GET', `/api/players/${playerId}/state`);
      expect(mergedStateRes.status, `get state after merge should be 200, got ${mergedStateRes.status}`).toBe(200);
      expect(mergedState.level, `level should remain 7 after merge, got ${mergedState?.level}`).toBe(7);
      expect(mergedState.gold, `gold should remain 500 after merge, got ${mergedState?.gold}`).toBe(500);
      const level3 = (mergedState.levelResults || []).find(r => r.levelId === 'level_3');
      expect(level3, 'existing best score record for level_3 should remain after merge').toBeTruthy();
      expect(level3.bestScore, `best score for level_3 should remain 9999, got ${level3?.bestScore}`).toBe(9999);
      expect((mergedState.customMaps || []).some(m => m.name === `Existing Map ${suffix}`), 'existing map should remain after merge').toBe(true);
      expect((mergedState.customMaps || []).some(m => m.name === `Imported Merge Map ${suffix}`), 'merged imported map should be added').toBe(true);

      const legacyPayload = {
        version: 1,
        legacyEditorMap: {
          width: 4,
          height: 1,
          tiles: [['S', '.', '.', 'E']],
          name: `Legacy Merge ${suffix}`,
        },
      };
      const { res: legacyMergeRes } = await request('POST', `/api/players/${playerId}/import-save`, {
        mode: 'merge_maps',
        payload: legacyPayload,
      });
      expect([200, 201].includes(legacyMergeRes.status), `legacy merge import status should be 200/201, got ${legacyMergeRes.status}`).toBe(true);

      const { res: afterLegacyRes, data: afterLegacy } = await request('GET', `/api/players/${playerId}/state`);
      expect(afterLegacyRes.status, `get state after legacy merge should be 200, got ${afterLegacyRes.status}`).toBe(200);
      expect(afterLegacy.level, `level should remain 7 after legacy merge, got ${afterLegacy?.level}`).toBe(7);
      const level3AfterLegacy = (afterLegacy.levelResults || []).find(r => r.levelId === 'level_3');
      expect(level3AfterLegacy, 'best score record should still exist after legacy migration').toBeTruthy();
      expect(level3AfterLegacy.bestScore, `best score should still be 9999 after legacy migration, got ${level3AfterLegacy?.bestScore}`).toBe(9999);

      const snapshot = JSON.stringify(afterLegacy);
      const { res: badImportRes } = await request('POST', `/api/players/${playerId}/import-save`, {
        mode: 'overwrite',
        payload: { malformed: true, customMaps: 'not-an-array' },
      });
      expect([400, 422].includes(badImportRes.status), `bad import should fail with 400/422, got ${badImportRes.status}`).toBe(true);

      const { res: finalStateRes, data: finalState } = await request('GET', `/api/players/${playerId}/state`);
      expect(finalStateRes.status, `get final state after failed import should be 200, got ${finalStateRes.status}`).toBe(200);
      expect(JSON.stringify(finalState), 'state should remain unchanged after failed import').toBe(snapshot);
    } finally {
      if (playerId) await safeDelete(`/api/players/${playerId}`);
    }
  });
});

