      });
      expect([200, 201].includes(legacyImportRes.status), `legacy import status should be 200/201, got ${legacyImportRes.status}`).toBe(true);
      const legacyImportStr = String(legacyImportData?.migration || legacyImportData?.message || JSON.stringify(legacyImportData) || '').toLowerCase();
      expect(legacyImportStr).toMatch(/legacy|migrat|default|map|转换|迁移/);

      const { res: legacyStateRes, data: legacyState } = await request('GET', `/api/players/${legacyImportPlayerId}/state`);
      expect(legacyStateRes.status, `get legacy imported state status should be 200, got ${legacyStateRes.status}`).toBe(200);
      const legacyMaps = legacyState.customMaps || legacyState.maps || [];
      expect(Array.isArray(legacyMaps), 'legacy imported customMaps should be array').toBe(true);
      expect(legacyMaps.length, 'legacy import should create at least one custom map').toBeGreaterThan(0);

      // Verify migrated map name and tile content
      const migratedMap = legacyMaps[0];
      const migratedName = (migratedMap.name || migratedMap.title || '').toLowerCase();
      expect(
        migratedName.includes('legacy') || migratedName.includes('default') || migratedName.includes('single') || migratedName.includes('迁移'),
        `expected migrated map name to indicate legacy/default, got "${migratedName}"`
      ).toBe(true);

      // Verify tiles are preserved
      const migratedTiles = migratedMap.layout?.tiles || migratedMap.tiles;
      expect(migratedTiles, 'migrated map should retain tile content').toBeTruthy();
      expect(JSON.stringify(migratedTiles)).toContain('S');
      expect(JSON.stringify(migratedTiles)).toContain('E');

      // ---- Import failure: invalid/corrupt data should preserve current state ----
      const { data: failPlayer } = await request('POST', '/api/players', {
        name: `fail-import-${suffix}`,
        level: 5,
        gold: 200,
      });
      failImportPlayerId = failPlayer?.id || failPlayer?.playerId;
      expect(failImportPlayerId, 'fail import player id should exist').toBeTruthy();

      const failStateBefore = await request('GET', `/api/players/${failImportPlayerId}/state`);
      expect(failStateBefore.res.status).toBe(200);

      const { res: failImportRes, data: failImportData } = await request('POST', `/api/players/${failImportPlayerId}/import-save`, {
        mode: 'overwrite',
        payload: { corrupted: true, notAValidSave: 'garbage-data', version: -999 },
      });
      expect(
        [400, 422, 409].includes(failImportRes.status),
        `expected import failure for corrupt data, got ${failImportRes.status}`
      ).toBe(true);
      const failStr = JSON.stringify(failImportData || {}).toLowerCase();
      expect(failStr).toMatch(/fail|error|invalid|corrupt|reason|原因|失败/);

      // Verify current data is preserved after failed import
      const failStateAfter = await request('GET', `/api/players/${failImportPlayerId}/state`);
      expect(failStateAfter.res.status).toBe(200);
      expect(failStateAfter.data?.gold, 'gold should be unchanged after failed import').toBe(failStateBefore.data?.gold);
      expect(
        failStateAfter.data?.level || failStateAfter.data?.characterLevel,
        'level should be unchanged after failed import'
      ).toBe(failStateBefore.data?.level || failStateBefore.data?.characterLevel);

      // ---- Verify save summary reflects changes after successful import ----
      const saveSummary = await request('GET', `/api/players/${importPlayerId}/saves`);
      if (saveSummary.res.status === 200) {
        const summaryStr = JSON.stringify(saveSummary.data || {}).toLowerCase();
        // Summary should reflect the imported state (not be stale)
        expect(
          summaryStr.length > 2,
          'save summary should contain data after import'
        ).toBe(true);
      }
    } finally {
      if (sourcePlayerId) await safeDelete(`/api/players/${sourcePlayerId}`);
      if (importPlayerId) await safeDelete(`/api/players/${importPlayerId}`);
      if (legacyImportPlayerId) await safeDelete(`/api/players/${legacyImportPlayerId}`);
      if (mergePlayerId) await safeDelete(`/api/players/${mergePlayerId}`);
      if (failImportPlayerId) await safeDelete(`/api/players/${failImportPlayerId}`);
    }
  });
});

import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function request(method: string, path: string, body?: any) {
  const res = await fetch(`${BASE_URL}${path}`, {
    method,
    headers: { 'Content-Type': 'application/json' },
    body: body === undefined ? undefined : JSON.stringify(body),
  });
  const text = await res.text();
  let json: any = null;
  try { json = text ? JSON.parse(text) : null; } catch { json = text; }
  return { res, body: json };
}

function randomId(prefix: string) {
  return `${prefix}-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
}

async function safeDelete(paths: string[]) {
  for (const path of paths) {
    try { await fetch(`${BASE_URL}${path}`, { method: 'DELETE' }); } catch {}
  }
}

async function tryPaths(method: string, paths: string[], body?: any) {
  for (const p of paths) {
    const r = await request(method, p, body);
    if (r.res.status !== 404) return { ...r, usedPath: p };
  }
  return { res: { status: 404 } as any, body: null, usedPath: paths[0] };
}

describe('round22_quest_progress_and_reward_claim', () => {
  it('should update quest progress for multiple condition types, persist across refresh, track status transitions including not_accepted, and claim rewards safely', async () => {
    const profileId = randomId('round22-profile');
    const cleanupPaths: string[] = [];

    try {
      // --- Create save with quests covering all condition types and limited inventory ---
      const savePayload = {
        profileId,
        playerName: 'Round22',
        gold: 10,
        exp: 0,
        level: 1,
        inventory: [],
        inventoryCapacity: 1,
        quests: [
          {
            id: 'quest-editor-test',
            type: 'daily',
            category: 'editor_test',
            condition: { type: 'editor_test', target: 1 },
            target: 1,
            progress: 0,
            status: 'in_progress',
            reward: { gold: 20, exp: 5, items: [{ itemId: 'reward-item', quantity: 1 }] },
          },
          {
            id: 'quest-collect-item',
            type: 'main',
            category: 'collect_item',
            condition: { type: 'collect_item', itemId: 'quest-gem', target: 2 },
            target: 2,
            progress: 0,
            status: 'in_progress',
            reward: { gold: 10, exp: 0, items: [] },
          },
          {
            id: 'quest-defeat-enemy',
            type: 'daily',
            category: 'defeat_enemy',
            condition: { type: 'defeat_enemy', enemyType: 'slime', target: 3 },
            target: 3,
            progress: 0,
            status: 'in_progress',
            reward: { gold: 15, exp: 10, items: [] },
          },
          {
            id: 'quest-clear-level',
            type: 'main',
            category: 'clear_level',
            condition: { type: 'clear_level', levelId: 'level-1', target: 1 },
            target: 1,
            progress: 0,
            status: 'in_progress',
            reward: { gold: 5, exp: 0, items: [] },
          },
          {
            id: 'quest-not-accepted',
            type: 'main',
            category: 'clear_level',
            condition: { type: 'clear_level', levelId: 'level-5', target: 1 },
            target: 1,
            progress: 0,
            status: 'not_accepted',
            reward: { gold: 50, exp: 20, items: [] },
          },
        ],
      };

      const create = await tryPaths('POST', [
        '/api/saves',
        '/api/profiles',
        '/api/users',
        '/api/game/saves',
      ], savePayload);

      if (create.res.status === 404) {
        expect.fail('No save/profile creation endpoint found. Cannot verify quest system.');
        return;
      }

      expect(create.res.status).toBeGreaterThanOrEqual(200);
      expect(create.res.status).toBeLessThan(300);
      const saveId = create.body?.id || create.body?.saveId || create.body?.profileId || profileId;
      cleanupPaths.push(`/api/saves/${saveId}`, `/api/profiles/${saveId}`, `/api/users/${saveId}`);

      // --- Discover quest event endpoint ---
      const eventPaths = [
        `/api/quests/${encodeURIComponent(saveId)}/events`,
        `/api/saves/${encodeURIComponent(saveId)}/quest-events`,
        `/api/profiles/${encodeURIComponent(saveId)}/quest-events`,
        `/api/quests/events`,
      ];

      // --- 1. Trigger editor_test quest progress ---
      const editorEvent = await tryPaths('POST', eventPaths, {
        type: 'editor_test',
        amount: 1,
        profileId: saveId,
      });

      if (editorEvent.res.status === 404) {
        expect.fail('No quest event endpoint found. Cannot verify quest progress.');
        return;
      }

      expect(editorEvent.res.status).toBeGreaterThanOrEqual(200);
      expect(editorEvent.res.status).toBeLessThan(300);

      // --- 2. Trigger defeat_enemy quest progress ---
      const defeatEvent = await request('POST', editorEvent.usedPath!, {
        type: 'defeat_enemy',
        enemyType: 'slime',
        amount: 3,
        profileId: saveId,
      });
      expect(defeatEvent.res.status).toBeGreaterThanOrEqual(200);
      expect(defeatEvent.res.status).toBeLessThan(300);

      // --- 3. Trigger clear_level quest progress ---
      const clearEvent = await request('POST', editorEvent.usedPath!, {
        type: 'clear_level',
        levelId: 'level-1',
        amount: 1,
        profileId: saveId,
      });
      expect(clearEvent.res.status).toBeGreaterThanOrEqual(200);
      expect(clearEvent.res.status).toBeLessThan(300);

      // --- Simulate refresh: GET to verify persisted quest progress ---
      const fetched = await tryPaths('GET', [
        `/api/saves/${encodeURIComponent(saveId)}`,
        `/api/profiles/${encodeURIComponent(saveId)}`,
        `/api/users/${encodeURIComponent(saveId)}`,
      ]);
      expect(fetched.res.status).toBeGreaterThanOrEqual(200);
      expect(fetched.res.status).toBeLessThan(300);

      const quests = fetched.body?.quests || [];
      expect(Array.isArray(quests), 'quests should be an array').toBe(true);

      // Verify editor_test quest -> should be claimable
      const editorQuest = quests.find((q: any) => q.id === 'quest-editor-test');
      expect(editorQuest, 'editor-test quest should exist in save').toBeTruthy();
      expect(editorQuest.progress, 'editor-test quest progress should be >= 1').toBeGreaterThanOrEqual(1);
      const claimableStatuses = ['claimable', 'completable', 'ready', 'completed'];
      const editorStatus = String(editorQuest.status || editorQuest.state).toLowerCase();
      expect(
        claimableStatuses.some(s => editorStatus.includes(s)),
        `editor-test quest should be claimable, got '${editorStatus}'`
      ).toBe(true);

      // Verify defeat_enemy quest -> should be claimable after 3 kills
      const defeatQuest = quests.find((q: any) => q.id === 'quest-defeat-enemy');
      expect(defeatQuest, 'defeat-enemy quest should exist in save').toBeTruthy();
      expect(defeatQuest.progress, 'defeat-enemy quest progress should be >= 3').toBeGreaterThanOrEqual(3);
      const defeatStatus = String(defeatQuest.status || defeatQuest.state).toLowerCase();
      expect(
        claimableStatuses.some(s => defeatStatus.includes(s)),
        `defeat-enemy quest should be claimable after meeting target, got '${defeatStatus}'`
      ).toBe(true);

      // Verify clear_level quest -> should be claimable
      const clearQuest = quests.find((q: any) => q.id === 'quest-clear-level');
      expect(clearQuest, 'clear-level quest should exist in save').toBeTruthy();
      expect(clearQuest.progress, 'clear-level quest progress should be >= 1').toBeGreaterThanOrEqual(1);

      // Verify collect_item quest -> still in progress
      const collectQuest = quests.find((q: any) => q.id === 'quest-collect-item');
      if (collectQuest) {
        const ipStatuses = ['in_progress', 'active', 'accepted'];
        const cStatus = String(collectQuest.status || collectQuest.state).toLowerCase();
        expect(
          ipStatuses.some(s => cStatus.includes(s)),
          `collect quest should still be in progress, got '${cStatus}'`
        ).toBe(true);
      }

      // Verify not_accepted quest -> should remain not_accepted
      const notAcceptedQuest = quests.find((q: any) => q.id === 'quest-not-accepted');
      if (notAcceptedQuest) {
        const naStatuses = ['not_accepted', 'available', 'pending', 'unaccepted'];
        const naStatus = String(notAcceptedQuest.status || notAcceptedQuest.state).toLowerCase();
        expect(
          naStatuses.some(s => naStatus.includes(s)),
          `not-accepted quest should remain in not-accepted state, got '${naStatus}'`
        ).toBe(true);
      }

      // --- Query quest list (verify status filtering/grouping) ---
      const questList = await tryPaths('GET', [
        `/api/quests?profileId=${encodeURIComponent(saveId)}`,
        `/api/saves/${encodeURIComponent(saveId)}/quests`,
        `/api/profiles/${encodeURIComponent(saveId)}/quests`,
      ]);
      if (questList.res.status >= 200 && questList.res.status < 300) {
        const allQuests = questList.body?.quests || questList.body || [];
        expect(Array.isArray(allQuests), 'quest list should be an array').toBe(true);
        // Should have quests in various states
        expect(allQuests.length, 'quest list should contain our quests').toBeGreaterThanOrEqual(3);
      }

      // --- Claim reward (backpack capacity = 1, so item reward may not fit) ---
      const claimPaths = [
        `/api/quests/${encodeURIComponent(saveId)}/claim`,
        `/api/saves/${encodeURIComponent(saveId)}/quests/claim`,
        `/api/quests/claim`,
      ];
      const claim = await tryPaths('POST', claimPaths, {
        questId: 'quest-editor-test',
        profileId: saveId,
      });

      if (claim.res.status === 404) {
        expect.fail('No quest claim endpoint found. Cannot verify reward claiming.');
        return;
      }

      expect([200, 201, 206, 400, 409, 422].includes(claim.res.status),
        `expected claim to return a known status, got ${claim.res.status}`).toBe(true);

      // --- Verify gold and exp arrive regardless of item overflow ---
      const claimedState = await tryPaths('GET', [
        `/api/saves/${encodeURIComponent(saveId)}`,
        `/api/profiles/${encodeURIComponent(saveId)}`,
        `/api/users/${encodeURIComponent(saveId)}`,
      ]);
      expect(claimedState.res.status).toBeGreaterThanOrEqual(200);
      expect(claimedState.res.status).toBeLessThan(300);

      const finalGold = claimedState.body?.gold;
      const finalExp = claimedState.body?.exp ?? claimedState.body?.experience;
      expect(typeof finalGold, `expected gold field after claim`).toBe('number');
      expect(typeof finalExp, `expected exp field after claim`).toBe('number');

      // Gold and exp MUST arrive even if backpack is full
      expect(finalGold, `expected gold >= 30 (10 initial + 20 reward), got ${finalGold}`).toBeGreaterThanOrEqual(30);
      expect(finalExp, `expected exp >= 5, got ${finalExp}`).toBeGreaterThanOrEqual(5);

      // If claim returned an error status, it means item part was blocked
      if (claim.res.status >= 400) {
        const msg = JSON.stringify(claim.body);
        expect(msg).toMatch(/inventory|full|pending|claim|backpack|space|bag|待领|背包/i);
        // Check pending/overflow area exists
        const pendingItems = claimedState.body?.pendingItems || claimedState.body?.pendingRewards || claimedState.body?.overflow;
        if (pendingItems) {
          expect(Array.isArray(pendingItems) ? pendingItems.length : Object.keys(pendingItems).length).toBeGreaterThan(0);
        }
      }

      // Verify quest status is now completed after successful claim
      const postClaimQuests = claimedState.body?.quests || [];
      const postClaimQuest = postClaimQuests.find((q: any) => q.id === 'quest-editor-test');
      if (postClaimQuest && claim.res.status < 300) {
        const completedStatuses = ['completed', 'done', 'finished', 'claimed'];
        const pStatus = String(postClaimQuest.status || postClaimQuest.state).toLowerCase();
        expect(
          completedStatuses.some(s => pStatus.includes(s)),
          `expected quest status to be completed after claim, got '${pStatus}'`
        ).toBe(true);
      }

      // --- Second refresh verification: GET again to simulate page refresh ---
      const refreshState = await tryPaths('GET', [
        `/api/saves/${encodeURIComponent(saveId)}`,
        `/api/profiles/${encodeURIComponent(saveId)}`,
      ]);
      expect(refreshState.res.status).toBeGreaterThanOrEqual(200);
      expect(refreshState.res.status).toBeLessThan(300);
      const refreshGold = refreshState.body?.gold;
      expect(refreshGold, 'gold should persist after simulated refresh').toBe(finalGold);
      const refreshQuests = refreshState.body?.quests || [];
      expect(refreshQuests.length, 'quests should persist after simulated refresh').toBeGreaterThanOrEqual(1);

      // --- Task item reservation: items occupied by quest cannot be sold ---
      const itemReservePayload = {
        inventory: [
          { itemId: 'quest-gem', quantity: 3 },
        ],
        inventoryCapacity: 10,
        quests: [
          {
            id: 'quest-need-gem',
            type: 'main',
            category: 'collect_item',
            condition: { type: 'collect_item', itemId: 'quest-gem', target: 3 },
            target: 3,
            progress: 2,
            status: 'in_progress',
            reward: { gold: 5, exp: 0, items: [] },
            reservedItems: [{ itemId: 'quest-gem', quantity: 2 }],
            occupiedItems: [{ itemId: 'quest-gem', quantity: 2 }],
          },
        ],
      };
      const patchForReserve = await tryPaths('PATCH', [
        `/api/saves/${encodeURIComponent(saveId)}`,
        `/api/profiles/${encodeURIComponent(saveId)}`,
      ], itemReservePayload);

      if (patchForReserve.res.status >= 200 && patchForReserve.res.status < 300) {
        // Try to sell all 3 quest-gems (2 are reserved) — should be blocked or limited
        const sellPaths = [
          '/api/shop/sell',
          `/api/shop/${encodeURIComponent(saveId)}/sell`,
          `/api/saves/${encodeURIComponent(saveId)}/shop/sell`,
        ];
        const sellReserved = await tryPaths('POST', sellPaths, {
          userId: saveId,
          profileId: saveId,
          itemId: 'quest-gem',
          quantity: 3,
        });

        if (sellReserved.res.status === 404) {
          // Try consume path instead
          const consumePaths = [
            `/api/items/use`,
            `/api/saves/${encodeURIComponent(saveId)}/items/use`,
            `/api/inventory/use`,
          ];
          const consumeReserved = await tryPaths('POST', consumePaths, {
            userId: saveId,
            profileId: saveId,
            itemId: 'quest-gem',
            quantity: 3,
          });
          if (consumeReserved.res.status !== 404) {
            expect([400, 409, 422].includes(consumeReserved.res.status),
              `expected consuming reserved quest items to fail, got ${consumeReserved.res.status}`).toBe(true);
          }
        } else {
          expect([400, 409, 422].includes(sellReserved.res.status),
            `expected selling 3 quest-gems (2 reserved) to fail, got ${sellReserved.res.status}`).toBe(true);
          const msg = JSON.stringify(sellReserved.body);
          expect(msg).toMatch(/quest|reserved|占用|任务|locked|occupied/i);
        }
      }
    } finally {
      await safeDelete(cleanupPaths);
    }
  });
});

import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function request(method, path, body) {
