}

describe('editor_test_mode_uses_current_unsaved_layout', () => {
  it('should generate test run from current unsaved layout and keep editor unsaved state unchanged after returning', async () => {
    const suffix = `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
    let playerId;
    let mapId;

    try {
      // Create a player
      const { res: playerRes, data: player } = await request('POST', '/api/players', { name: `editor-player-${suffix}` });
      expect(playerRes.status, `player creation should succeed, got ${playerRes.status}`).toBeLessThan(300);
      playerId = player?.id || player?.playerId;
      expect(playerId, 'player id should exist').toBeTruthy();

      const savedLayout = { width: 5, height: 1, tiles: [['S', '.', '.', '.', 'E']] };
      const unsavedLayout = { width: 5, height: 1, tiles: [['S', '#', '#', '.', 'E']] };

      // Create a map with initial saved layout
      const { res: mapRes, data: mapData } = await request('POST', `/api/players/${playerId}/maps`, {
        name: `Unsaved Test Map ${suffix}`,
        layout: savedLayout,
      });
      expect(mapRes.status, `create map status should be 2xx, got ${mapRes.status}`).toBeLessThan(300);
      mapId = mapData?.id || mapData?.mapId;
      expect(mapId, 'map id should exist').toBeTruthy();

      // Update draft with unsaved changes (dirty state)
      const { res: draftRes, data: draftData } = await request('PATCH', `/api/players/${playerId}/maps/${mapId}/draft`, {
        layout: unsavedLayout,
        dirty: true,
      });
      expect(draftRes.status, `update draft status should be 2xx, got ${draftRes.status}`).toBeLessThan(300);
      if (draftData && typeof draftData === 'object') {
        const dirty = draftData.dirty ?? draftData.unsavedChanges ?? true;
        expect(dirty, 'draft response should mark map as dirty/unsaved').toBe(true);
      }

      // Start test run using the draft (unsaved) layout
      const { res: testRes, data: testData } = await request('POST', `/api/players/${playerId}/maps/${mapId}/test-run`, {
        useDraft: true,
      });
      expect(testRes.status, `start test run status should be 2xx, got ${testRes.status}`).toBeLessThan(300);
      expect(testData && typeof testData === 'object', 'test run response should be an object').toBeTruthy();
      // Verify the test run uses the unsaved draft layout (contains '#' blocks)
      const generatedLayout = testData?.generatedLayout || testData?.layout || testData?.mapLayout;
      const generatedStr = JSON.stringify(generatedLayout || {});
      expect(generatedStr, 'test run should use current unsaved draft layout containing # blocks').toContain('#');

      // Finish the test run
      const { res: finishRes } = await request('POST', `/api/players/${playerId}/maps/${mapId}/test-run/finish`, {
        result: 'success',
      });
      expect(finishRes.status, `finish test run status should be 2xx, got ${finishRes.status}`).toBeLessThan(300);

      // Verify editor state after returning from test mode
      const { res: editorStateRes, data: editorState } = await request('GET', `/api/players/${playerId}/maps/${mapId}/editor-state`);
      expect(editorStateRes.status, `get editor state status should be 200, got ${editorStateRes.status}`).toBe(200);

      // Dirty flag should still be true (unsaved changes preserved)
      const dirtyAfter = editorState?.dirty ?? editorState?.unsavedChanges;
      expect(dirtyAfter, 'editor should still indicate unsaved changes after returning from test mode').toBe(true);

      // Draft layout should remain the unsaved version
      const draftLayout = editorState?.draftLayout || editorState?.currentLayout || editorState?.draft;
      expect(JSON.stringify(draftLayout || {}), 'editor draft layout should remain unchanged after test mode').toBe(JSON.stringify(unsavedLayout));

      // Saved/persisted layout should remain the original (not overwritten by test mode)
      const persistedLayout = editorState?.savedLayout || editorState?.persistedLayout || editorState?.saved;
      expect(JSON.stringify(persistedLayout || {}), 'saved layout should remain original and not be overwritten by test mode').toBe(JSON.stringify(savedLayout));

      // Verify test mode results did NOT pollute formal adventure progress
      const { res: progressRes, data: progressData } = await request('GET', `/api/players/${playerId}/state`);
      if (progressRes.status === 200 && progressData) {
        // Test mode deaths/completions should not appear in formal records
        const formalStr = JSON.stringify(progressData);
        expect(formalStr, 'test mode results should not appear in formal progress').not.toMatch(new RegExp(`Unsaved Test Map ${suffix}`));
      }
    } finally {
      if (playerId && mapId) await safeDelete(`/api/players/${playerId}/maps/${mapId}`);
      if (playerId) await safeDelete(`/api/players/${playerId}`);
    }
  });
});

