        `/api/players/${profileId}/state`,
        `/api/players/${profileId}`,
      ]);
      expect(beforeFailure.res.status, 'state fetch before failure test should succeed').toBe(200);
      const stateBefore = beforeFailure.body?.profile || beforeFailure.body?.state || beforeFailure.body;
      expect(stateBefore, 'baseline state should be defined').toBeTruthy();
      const goldBefore = stateBefore?.gold;
      const progressBefore = JSON.stringify(stateBefore?.progress || stateBefore?.formalProgress || {});
      const invBefore = stateBefore?.inventory || stateBefore?.items || [];

      // === Step 8: Run a failed adventure - temp drops must NOT persist ===
      await tryPaths('POST', [
        `/api/saves/${resolvedId}/adventure-runs`,
        `/api/players/${profileId}/levels/level-2/complete`,
        `/api/adventure/level-2/complete`,
      ], {
        result: 'failed',
        levelId: 'level-2',
        temporaryDrops: ['temp-gem', 'temp-potion'],
      });

      // === Step 9: Verify state after failure ===
      const afterFailure = await tryPaths('GET', [
        `/api/saves/${resolvedId}`,
        `/api/players/${profileId}/state`,
        `/api/players/${profileId}`,
      ]);
      expect(afterFailure.res.status, 'state fetch after failure should succeed').toBe(200);
      const stateAfter = afterFailure.body?.profile || afterFailure.body?.state || afterFailure.body;

      // Temp drops must not be in inventory
      const invAfter = stateAfter?.inventory || stateAfter?.items || [];
      if (Array.isArray(invAfter)) {
        const hasTempDrop = invAfter.some((i: any) => {
          const id = i?.itemId || i?.id || i;
          return id === 'temp-gem' || id === 'temp-potion';
        });
        expect(hasTempDrop, 'temporary drops from failed adventure must not appear in inventory').toBe(false);
      }

      // Progress should not be corrupted
      const progressAfter = JSON.stringify(stateAfter?.progress || stateAfter?.formalProgress || {});
      expect(progressAfter, 'formal progress should not change after failed adventure').toBe(progressBefore);

      // Gold should not decrease from failure
      const goldAfter = stateAfter?.gold;
      if (goldBefore !== undefined && goldAfter !== undefined) {
        expect(goldAfter, 'gold should not decrease from failed adventure').toBeGreaterThanOrEqual(goldBefore);
      }

      // === Step 10: Verify custom map data is intact ===
      const mapCheck = await tryPaths('GET', [`/api/editor/maps/${mapId}`, `/api/maps/${mapId}`]);
      if (mapCheck.res.status === 200) {
        expect(mapCheck.body?.tiles, 'custom map should be intact after failed adventure').toEqual(mapPayload.tiles);
        expect(mapCheck.body?.name, 'custom map name should persist').toBe('TestMap');
      }

      // === Step 11: Simulate refresh - re-fetch and do full comparison ===
      const refreshState = await tryPaths('GET', [
        `/api/saves/${resolvedId}`,
        `/api/players/${profileId}/state`,
        `/api/players/${profileId}`,
      ]);
      expect(refreshState.res.status, 'state after refresh should be 200').toBe(200);
      const sRefresh = refreshState.body?.profile || refreshState.body?.state || refreshState.body;

      // Verify profile identifiable
      const idField = sRefresh?.id || sRefresh?.saveId || sRefresh?.profileId || sRefresh?.playerId || refreshState.body?.id;
      expect(idField, 'profile should be identifiable after refresh').toBeTruthy();

      // Verify temp drops still not present
      const invRefresh = sRefresh?.inventory || sRefresh?.items || [];
      if (Array.isArray(invRefresh)) {
        expect(
          invRefresh.some((i: any) => (i?.itemId || i?.id || i) === 'temp-gem'),
          'temp-gem must not appear after refresh'
        ).toBe(false);
      }

      // Gold should match post-failure state
      const goldRefresh = sRefresh?.gold;
      if (goldAfter !== undefined && goldRefresh !== undefined) {
        expect(goldRefresh, 'gold should be consistent after refresh').toBe(goldAfter);
      }

      // Equipment should persist
      const eqRefresh = sRefresh?.equipment;
      const eqAfter = stateAfter?.equipment;
      if (eqRefresh && eqAfter) {
        expect(JSON.stringify(eqRefresh), 'equipment should be consistent after refresh').toBe(JSON.stringify(eqAfter));
      }

      // Progress should persist
      const progressRefresh = JSON.stringify(sRefresh?.progress || sRefresh?.formalProgress || {});
      expect(progressRefresh, 'progress should be consistent after refresh').toBe(progressAfter);

    } finally {
      await safeDelete(cleanupPaths);
    }
  });
});

import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function request(method: string, path: string, body?: any) {
  const res = await fetch(`${BASE_URL}${path}`, {
    method,
    headers: { 'Content-Type': 'application/json' },
    body: body === undefined ? undefined : JSON.stringify(body),
  });
  const text = await res.text();
  let json: any = null;
  try {
    json = text ? JSON.parse(text) : null;
  } catch {
    json = { raw: text };
  }
  return { res, body: json };
}

async function tryPaths(method: string, paths: string[], body?: any) {
  for (const p of paths) {
    const r = await request(method, p, body);
    if (r.res.status !== 404) return { ...r, usedPath: p };
  }
  return { res: { status: 404 } as any, body: null, usedPath: paths[0] };
}

async function cleanup(paths: string[]) {
  for (const path of paths) {
    try {
      await fetch(`${BASE_URL}${path}`, { method: 'DELETE' });
    } catch {}
  }
}

describe('round8_multi_level_progression', () => {
  it('should support at least 5 levels, unlock next level after previous clear, persist full best records, reject access to locked levels, show placeholder for no-record levels, refresh list after return, and keep best record from being overwritten by worse performance', async () => {
    const playerId = `vt-levels-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
    const cleanupPaths: string[] = [];

    try {
      // --- Create player/save ---
      const createPlayer = await tryPaths('POST', [
        '/api/test-players',
        '/api/players',
        '/api/saves',
        '/api/profiles',
        '/api/users',
      ], {
        playerId,
        id: playerId,
        profileId: playerId,
        playerName: 'LevelTester',
        profile: { level: 1, formalProgress: { clearedLevels: [], bestRecords: {} } },
        level: 1,
        formalProgress: { clearedLevels: [], bestRecords: {} },
      });

      if (createPlayer.res.status === 404) {
        expect.fail('No player/save creation endpoint found. Cannot run level progression test.');
        return;
      }
      expect(createPlayer.res.status).toBeLessThan(300);
      cleanupPaths.push(
        `/api/test-players/${playerId}`,
        `/api/players/${playerId}`,
        `/api/saves/${playerId}`,
        `/api/profiles/${playerId}`,
        `/api/users/${playerId}`
      );

      // --- Get level list ---
      const levels = await tryPaths('GET', [
        '/api/levels',
        '/api/game/levels',
        '/api/adventure/levels',
      ]);

      if (levels.res.status === 404) {
        expect.fail('No levels endpoint found. Cannot run level progression test.');
        return;
      }
      expect(levels.res.status, `expected levels list 200, got ${levels.res.status}`).toBe(200);

      const levelList = Array.isArray(levels.body) ? levels.body : (levels.body?.levels || []);
      expect(Array.isArray(levelList), 'expected levels to return an array').toBe(true);
      expect(levelList.length, `expected at least 5 levels, got ${levelList.length}`).toBeGreaterThanOrEqual(5);

      // --- Verify initial state: no records, placeholder text (not empty numbers) ---
      const initialProgress = await tryPaths('GET', [
        `/api/players/${playerId}/progress`,
        `/api/saves/${playerId}`,
        `/api/profiles/${playerId}`,
        `/api/users/${playerId}`,
      ]);
      expect(initialProgress.res.status).toBeGreaterThanOrEqual(200);
      expect(initialProgress.res.status).toBeLessThan(300);
      const prog = initialProgress.body?.formalProgress || initialProgress.body;
      const records = prog?.bestRecords || {};
      expect(Object.keys(records).length, 'expected no best records initially').toBe(0);

      // Check level list entries for placeholder/initial text (not 0 or null numbers)
      const levelListWithPlayer = await tryPaths('GET', [
        `/api/levels?playerId=${encodeURIComponent(playerId)}`,
        `/api/game/levels?playerId=${encodeURIComponent(playerId)}`,
        `/api/players/${playerId}/levels`,
      ]);
      if (levelListWithPlayer.res.status >= 200 && levelListWithPlayer.res.status < 300) {
        const playerLevels = Array.isArray(levelListWithPlayer.body) ? levelListWithPlayer.body : (levelListWithPlayer.body?.levels || []);
        if (playerLevels.length > 0) {
          const firstLevel = playerLevels[0];
          // If there's a bestTime/score field for unplayed levels, it should be null/undefined or a placeholder string, not 0
          const bestTime = firstLevel.bestTime ?? firstLevel.clearTime ?? firstLevel.fastestTime;
          if (bestTime !== undefined && bestTime !== null) {
            // If present, should be a placeholder string, not the number 0
            if (typeof bestTime === 'number') {
              // Some implementations may not include the field at all for unplayed levels
              // We note this but the key check is that it's not falsely showing 0
            }
          }
          // Check for placeholder text
          const displayText = firstLevel.displayText || firstLevel.recordText || firstLevel.statusText;
          if (displayText) {
            expect(typeof displayText, 'placeholder should be a string').toBe('string');
            expect(displayText.length, 'placeholder text should not be empty').toBeGreaterThan(0);
          }
        }
      }

      // --- Verify locked level cannot be entered/completed ---
      const lockedLevelId = levelList[1]?.id || levelList[1]?.levelId || 'level-2';
      const completePaths = [
        `/api/players/${playerId}/levels/${lockedLevelId}/complete`,
        `/api/saves/${playerId}/levels/${lockedLevelId}/complete`,
        `/api/adventure/${playerId}/levels/${lockedLevelId}/complete`,
      ];
      const attemptLocked = await tryPaths('POST', completePaths, {
        clearTime: 50,
        deathCount: 0,
        playedAt: new Date().toISOString(),
        confirmSettlement: true,
      });

      if (attemptLocked.res.status === 404) {
        // If ALL complete endpoints return 404, we can't test this
        // but we should still validate the concept
      } else {
        expect(
          attemptLocked.res.status >= 400,
          `expected completing locked level to be rejected, got ${attemptLocked.res.status}`
        ).toBe(true);
        // Verify rejection reason mentions locked/unlock
        const lockMsg = JSON.stringify(attemptLocked.body).toLowerCase();
        expect(
          /lock|unlock|access|denied|unavailable|not.*available/i.test(lockMsg),
          `expected rejection message about locked level, got: ${lockMsg}`
        ).toBe(true);
      }

      // --- Sequentially clear 5 levels ---
      let completeEndpoint = '';
      for (let i = 1; i <= 5; i++) {
        const levelId = levelList[i - 1]?.id || levelList[i - 1]?.levelId || `level-${i}`;

        const now = new Date().toISOString();
        const clearTime = 100 - i; // Better times for earlier levels
        const deathCount = i; // Different death counts

        const clearPaths = [
          `/api/players/${playerId}/levels/${levelId}/complete`,
          `/api/saves/${playerId}/levels/${levelId}/complete`,
          `/api/adventure/${playerId}/levels/${levelId}/complete`,
        ];
        const clear = await tryPaths('POST', clearPaths, {
          clearTime,
          deathCount,
          playedAt: now,
          confirmSettlement: true,
        });

        if (clear.res.status === 404) {
          expect.fail(`No level complete endpoint found for ${levelId}. Cannot verify level progression.`);
          return;
        }
        expect(clear.res.status, `expected ${levelId} clear success, got ${clear.res.status}`).toBeLessThan(300);
        completeEndpoint = clear.usedPath!;

        // Verify progress after clearing
        const progress = await tryPaths('GET', [
          `/api/players/${playerId}/progress`,
          `/api/saves/${playerId}`,
          `/api/profiles/${playerId}`,
        ]);
        expect(progress.res.status).toBeGreaterThanOrEqual(200);
        expect(progress.res.status).toBeLessThan(300);

        const currentProg = progress.body?.formalProgress || progress.body;
        const clearedLevels = currentProg?.clearedLevels || [];
        const bestRecords = currentProg?.bestRecords || {};

        expect(clearedLevels, `expected clearedLevels to include ${levelId}`).toContain(levelId);

        // Verify all record fields including cleared/completed status
        const record = bestRecords[levelId];
        expect(record, `expected best record for ${levelId}`).toBeTruthy();
        if (typeof record === 'object' && record !== null) {
          const bestTime = record.clearTime ?? record.bestTime ?? record.fastestTime;
          expect(bestTime, `expected clearTime recorded for ${levelId}`).toBe(clearTime);
          const bestDeaths = record.deathCount ?? record.deaths ?? record.minDeaths;
          expect(bestDeaths, `expected deathCount recorded for ${levelId}`).toBe(deathCount);
          const playedAt = record.playedAt ?? record.lastPlayed ?? record.recentPlayTime;
          expect(playedAt, `expected playedAt recorded for ${levelId}`).toBeTruthy();
          // Check cleared/completed boolean field
          const cleared = record.cleared ?? record.completed ?? record.passed;
          if (cleared !== undefined) {
            expect(cleared, `expected cleared=true for ${levelId}`).toBe(true);
          }
        }

        // --- After clearing, re-fetch level list to verify it refreshes (simulates returning to list) ---
        const refreshedLevels = await tryPaths('GET', [
          `/api/levels?playerId=${encodeURIComponent(playerId)}`,
          `/api/game/levels?playerId=${encodeURIComponent(playerId)}`,
          `/api/players/${playerId}/levels`,
        ]);
        if (refreshedLevels.res.status >= 200 && refreshedLevels.res.status < 300) {
          const refreshedList = Array.isArray(refreshedLevels.body) ? refreshedLevels.body : (refreshedLevels.body?.levels || []);
          // Find the cleared level in the refreshed list
          const clearedEntry = refreshedList.find((l: any) => (l.id || l.levelId) === levelId);
          if (clearedEntry) {
            // The level entry should show the best record, not placeholder
            const entryBest = clearedEntry.bestTime ?? clearedEntry.clearTime ?? clearedEntry.fastestTime;
            if (entryBest !== undefined) {
              expect(entryBest, `level list should reflect best time for ${levelId}`).toBe(clearTime);
            }
          }
          // Verify next level is shown as unlocked in the list
          if (i < 5) {
            const nextLevelId = levelList[i]?.id || levelList[i]?.levelId || `level-${i + 1}`;
            const nextEntry = refreshedList.find((l: any) => (l.id || l.levelId) === nextLevelId);
            if (nextEntry) {
              const unlocked = nextEntry.unlocked ?? nextEntry.accessible ?? nextEntry.available;
              if (unlocked !== undefined) {
                expect(unlocked, `${nextLevelId} should be unlocked in list after clearing ${levelId}`).toBe(true);
              }
            }
          }
        }
      }

      // --- Test that worse records do NOT overwrite best records ---
      const testLevelId = levelList[2]?.id || levelList[2]?.levelId || 'level-3';
      const originalClearTime = 100 - 3; // 97
      const originalDeathCount = 3;

      // Submit a much worse record
      const worseCompletePath = completeEndpoint.replace(/\/[^\/]+\/complete$/, `/${testLevelId}/complete`);
      const worseRecord = await request('POST', worseCompletePath, {
        clearTime: 999,
        deathCount: 50,
        playedAt: new Date().toISOString(),
        confirmSettlement: true,
      });
      expect(worseRecord.res.status).toBeLessThan(300);

      const finalProgress = await tryPaths('GET', [
        `/api/players/${playerId}/progress`,
        `/api/saves/${playerId}`,
        `/api/profiles/${playerId}`,
      ]);
      expect(finalProgress.res.status).toBeGreaterThanOrEqual(200);
      expect(finalProgress.res.status).toBeLessThan(300);

      const finalProg = finalProgress.body?.formalProgress || finalProgress.body;
      const finalRecords = finalProg?.bestRecords || {};
      const finalRecord = finalRecords[testLevelId];
      expect(finalRecord, `expected final best record for ${testLevelId}`).toBeTruthy();

      if (typeof finalRecord === 'object' && finalRecord !== null) {
        const bestTime = finalRecord.clearTime ?? finalRecord.bestTime ?? finalRecord.fastestTime;
        expect(bestTime, 'expected worse clearTime not to overwrite better best record').toBe(originalClearTime);
        const bestDeaths = finalRecord.deathCount ?? finalRecord.deaths ?? finalRecord.minDeaths;
        expect(bestDeaths, 'expected worse deathCount not to overwrite better best record').toBe(originalDeathCount);
        const playedAt = finalRecord.playedAt ?? finalRecord.lastPlayed ?? finalRecord.recentPlayTime;
        expect(playedAt, 'expected playedAt to still be present').toBeTruthy();
      } else if (typeof finalRecord === 'number') {
        expect(finalRecord, 'expected worse score not to overwrite better best record').toBe(originalClearTime);
      }

      // Submit a better record and verify it DOES update
      const betterRecord = await request('POST', worseCompletePath, {
        clearTime: 10,
        deathCount: 0,
        playedAt: new Date().toISOString(),
        confirmSettlement: true,
      });
      expect(betterRecord.res.status).toBeLessThan(300);

      const betterProgress = await tryPaths('GET', [
        `/api/players/${playerId}/progress`,
        `/api/saves/${playerId}`,
        `/api/profiles/${playerId}`,
      ]);
      expect(betterProgress.res.status).toBeGreaterThanOrEqual(200);
      expect(betterProgress.res.status).toBeLessThan(300);
      const betterProg = betterProgress.body?.formalProgress || betterProgress.body;
      const betterRecords = betterProg?.bestRecords || {};
      const betterFinalRecord = betterRecords[testLevelId];
      if (typeof betterFinalRecord === 'object' && betterFinalRecord !== null) {
        const improvedTime = betterFinalRecord.clearTime ?? betterFinalRecord.bestTime ?? betterFinalRecord.fastestTime;
        expect(improvedTime, 'better clearTime should update best record').toBe(10);
        const improvedDeaths = betterFinalRecord.deathCount ?? betterFinalRecord.deaths ?? betterFinalRecord.minDeaths;
        expect(improvedDeaths, 'better deathCount should update best record').toBe(0);
      }
    } finally {
      await cleanup(cleanupPaths);
    }
  });
});

import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function request(method: string, path: string, body?: any) {
  const res = await fetch(`${BASE_URL}${path}`, {
    method,
    headers: { 'Content-Type': 'application/json' },
    body: body === undefined ? undefined : JSON.stringify(body),
  });
  const text = await res.text();
  let json: any = null;
  try { json = text ? JSON.parse(text) : null; } catch { json = text; }
  return { res, body: json };
}

function randomId(prefix: string) {
  return `${prefix}-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
}

async function safeDelete(paths: string[]) {
  for (const path of paths) {
    try { await fetch(`${BASE_URL}${path}`, { method: 'DELETE' }); } catch {}
  }
}

async function tryRequest(method: string, paths: string[], body?: any) {
  for (const path of paths) {
    const result = await request(method, path, body);
    if (result.res.status !== 404) return { ...result, usedPath: path };
  }
  return { ...(await request(method, paths[paths.length - 1], body)), usedPath: paths[paths.length - 1] };
}

describe('round17_import_export_with_legacy_map_migration', () => {
