        expect(
          [200, 204].includes(deleteNoConfirm.res.status),
          `expected delete success, got ${deleteNoConfirm.res.status}`
        ).toBe(true);
      }

      // ---- Verify deleting slot did not corrupt current state ----
      const afterDeleteState = await tryPaths('GET', [
        `/api/players/${playerId}/state`,
        `/api/players/${playerId}`,
        `/api/saves/${playerId}`,
      ]);
      expect(afterDeleteState.res.status).toBeLessThan(300);
      const goldAfterDelete = afterDeleteState.body?.gold ?? afterDeleteState.body?.profile?.gold;
      expect(
        goldAfterDelete,
        'expected deleting slots not to partially overwrite current state'
      ).toBe(goldBeforeDelete);

      const equipAfterDelete = afterDeleteState.body?.equipment ?? afterDeleteState.body?.profile?.equipment;
      const equipBeforeDelete = beforeDeleteState.body?.equipment ?? beforeDeleteState.body?.profile?.equipment;
      expect(equipAfterDelete, 'equipment should be unchanged after slot deletion').toEqual(equipBeforeDelete);
    } finally {
      await cleanup(cleanupPaths);
    }
  });
});

