describe('map_crud_validates_unique_and_nonempty_name', () => {
  it('should support create/rename/copy/delete and validate non-empty unique names', async () => {
    const suffix = `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
    let playerId;
    let mapId;
    let copiedMapId;

    try {
      const { data: player } = await request('POST', '/api/players', { name: `map-player-${suffix}` });
      playerId = player.id;
      expect(playerId, 'player id should exist').toBeTruthy();

      const originalName = `My Map ${suffix}`;
      const layout = { width: 5, height: 2, tiles: [['S', '.', '.', '.', 'E']] };
      const { res: createRes, data: createData } = await request('POST', `/api/players/${playerId}/maps`, {
        name: originalName,
        layout,
      });
      expect(createRes.status, `create map status should be 201, got ${createRes.status}`).toBe(201);
      mapId = createData.id;
      expect(mapId, 'created map id should exist').toBeTruthy();
      expect(createData.name, `created map name should be ${originalName}, got ${createData?.name}`).toBe(originalName);

      const { res: emptyNameRes, data: emptyNameData } = await request('POST', `/api/players/${playerId}/maps`, {
        name: '   ',
        layout,
      });
      expect([400, 409, 422].includes(emptyNameRes.status), `empty name create should fail with 400/409/422, got ${emptyNameRes.status}`).toBe(true);
      expect(String(emptyNameData?.reason || emptyNameData?.code || emptyNameData?.message || '').toLowerCase()).toMatch(/name|empty|required/);

      const { res: dupNameRes, data: dupNameData } = await request('POST', `/api/players/${playerId}/maps`, {
        name: originalName,
        layout,
      });
      expect([400, 409, 422].includes(dupNameRes.status), `duplicate name create should fail with 400/409/422, got ${dupNameRes.status}`).toBe(true);
      expect(String(dupNameData?.reason || dupNameData?.code || dupNameData?.message || '').toLowerCase()).toMatch(/duplicate|exist|unique|name/);

      const renamed = `Renamed Map ${suffix}`;
      const { res: renameRes, data: renameData } = await request('PATCH', `/api/players/${playerId}/maps/${mapId}`, {
        name: renamed,
      });
      expect([200, 204].includes(renameRes.status), `rename map status should be 200/204, got ${renameRes.status}`).toBe(true);
      if (renameData && typeof renameData === 'object') {
        expect(renameData.name, `renamed map name should be ${renamed}, got ${renameData?.name}`).toBe(renamed);
      }

      const { res: copyRes, data: copyData } = await request('POST', `/api/players/${playerId}/maps/${mapId}/copy`, {});
      expect([200, 201].includes(copyRes.status), `copy map status should be 200/201, got ${copyRes.status}`).toBe(true);
      copiedMapId = copyData.id;
      expect(copiedMapId, 'copied map id should exist').toBeTruthy();
      expect(copyData.name, 'copied map should have derived name with suffix').toMatch(new RegExp(`^${renamed.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}`));
      expect(copyData.name, 'copied map name should differ from original renamed map name').not.toBe(renamed);
      expect(copyData.layout, 'copied map should include layout').toBeTruthy();
      expect(JSON.stringify(copyData.layout), 'copied map should inherit original layout').toBe(JSON.stringify(layout));

      const { res: deleteRes } = await request('DELETE', `/api/players/${playerId}/maps/${mapId}`);
      expect([200, 204].includes(deleteRes.status), `delete map status should be 200/204, got ${deleteRes.status}`).toBe(true);

      const { res: listRes, data: listData } = await request('GET', `/api/players/${playerId}/maps`);
      expect(listRes.status, `list maps status should be 200, got ${listRes.status}`).toBe(200);
      expect(Array.isArray(listData), 'map list should be array').toBe(true);
      expect(listData.some(m => m.id === copiedMapId), 'copied map should remain in list').toBe(true);
      expect(listData.some(m => m.id === mapId), 'deleted original map should not remain in list').toBe(false);
    } finally {
      if (playerId && copiedMapId) await safeDelete(`/api/players/${playerId}/maps/${copiedMapId}`);
      if (playerId) await safeDelete(`/api/players/${playerId}`);
    }
  });
});

