describe('equip_swap_validates_bag_capacity_and_level_requirement', () => {
  const suffix = `${Date.now()}_${Math.random().toString(36).slice(2, 8)}`;
  const playerId = `equip-player-${suffix}`;

  // Item definitions
  const swordA = { itemId: `sword-a-${suffix}`, name: 'Sword A', type: 'equipment', slot: 'weapon', requiredLevel: 1, stats: { atk: 10 } };
  const swordB = { itemId: `sword-b-${suffix}`, name: 'Sword B', type: 'equipment', slot: 'weapon', requiredLevel: 1, stats: { atk: 18 } };
  const highSword = { itemId: `sword-high-${suffix}`, name: 'High Sword', type: 'equipment', slot: 'weapon', requiredLevel: 20, stats: { atk: 99 } };
  const helmetA = { itemId: `helmet-a-${suffix}`, name: 'Helmet A', type: 'equipment', slot: 'head', requiredLevel: 1, stats: { def: 5 } };
  const armorA = { itemId: `armor-a-${suffix}`, name: 'Armor A', type: 'equipment', slot: 'armor', requiredLevel: 1, stats: { def: 10 } };
  const accessoryA = { itemId: `accessory-a-${suffix}`, name: 'Accessory A', type: 'equipment', slot: 'accessory', requiredLevel: 1, stats: { hp: 20 } };

  // Try multiple API path patterns for a given action
  async function tryPaths(method, paths, body) {
    for (const path of paths) {
      try {
        const r = await request(method, path, body);
        if (r.res.status > 0 && r.res.status < 500) return r;
      } catch {}
    }
    return { res: { status: 0 }, data: null };
  }

  async function setupPlayer(setup) {
    return tryPaths('POST', [
      '/api/test/players',
      '/api/test-players',
      '/api/players',
    ], setup);
  }

  async function getPlayer() {
    return tryPaths('GET', [
      `/api/players/${playerId}`,
      `/api/players/${playerId}/state`,
      `/api/test/players/${playerId}`,
    ]);
  }

  async function equipItem(itemId) {
    return tryPaths('POST', [
      `/api/players/${playerId}/equipment/equip`,
      `/api/players/${playerId}/equipment`,
      `/api/players/${playerId}/equip`,
    ], { itemId });
  }

  async function patchPlayer(body) {
    const r = await tryPaths('PATCH', [
      `/api/test/players/${playerId}`,
      `/api/players/${playerId}`,
      `/api/test-players/${playerId}`,
    ], body);
    if (r.res.status >= 200 && r.res.status < 300) return r;
    return tryPaths('PUT', [
      `/api/players/${playerId}/inventory`,
      `/api/players/${playerId}`,
    ], body);
  }

  function extractPlayer(data) {
    return data?.player || data?.profile || data;
  }

  it('should update stats on equip, swap returning old gear to bag, reject swap when bag full, reject high-level equip, persist state', async () => {
    try {
      // Setup: create items
      const allItems = [swordA, swordB, highSword, helmetA, armorA, accessoryA];
      await tryPaths('POST', ['/api/test/items', '/api/items'], { items: allItems });
      // Also try individual creation
      for (const item of allItems) {
        await tryPaths('POST', ['/api/items', '/api/test/items'], item);
      }

      // Setup: create player at level 10 with items in bag
      const createRes = await setupPlayer({
        playerId,
        level: 10,
        stats: { atk: 5, def: 0, hp: 100 },
        bagCapacity: 20,
        inventory: allItems.map(i => ({ itemId: i.itemId, quantity: 1 })),
        equipment: {},
        profile: {
          level: 10,
          stats: { atk: 5, def: 0, hp: 100 },
          bagCapacity: 20,
          inventory: allItems.map(i => ({ itemId: i.itemId, quantity: 1 })),
          equipment: {},
        },
      });
      expect(createRes.res.status, 'player creation should succeed').toBeGreaterThanOrEqual(200);
      expect(createRes.res.status).toBeLessThan(300);

      // ---- Test 1: Equip weapon swordA and verify stats update ----
      const equipA = await equipItem(swordA.itemId);
      expect(equipA.res.status, `equip swordA should succeed (2xx)`).toBeGreaterThanOrEqual(200);
      expect(equipA.res.status).toBeLessThan(300);

      const afterEquipA = await getPlayer();
      expect(afterEquipA.res.status).toBe(200);
      const pA = extractPlayer(afterEquipA.data);
      const eqStrA = JSON.stringify(pA?.equipment || {});
      expect(eqStrA, `weapon slot should contain ${swordA.itemId}`).toContain(swordA.itemId);
      // Verify atk changed (base 5 + sword 10 = 15)
      const statsA = pA?.stats || pA;
      if (statsA?.atk !== undefined) {
        expect(statsA.atk, 'atk should be 15 after equipping swordA').toBe(15);
      }

      // ---- Test 2: Equip multiple slots (head, armor, accessory) ----
      const equipHelmet = await equipItem(helmetA.itemId);
      expect(equipHelmet.res.status, 'helmet equip should succeed').toBeGreaterThanOrEqual(200);
      expect(equipHelmet.res.status).toBeLessThan(300);

      const equipArmor = await equipItem(armorA.itemId);
      expect(equipArmor.res.status, 'armor equip should succeed').toBeGreaterThanOrEqual(200);
      expect(equipArmor.res.status).toBeLessThan(300);

      const equipAccessory = await equipItem(accessoryA.itemId);
      expect(equipAccessory.res.status, 'accessory equip should succeed').toBeGreaterThanOrEqual(200);
      expect(equipAccessory.res.status).toBeLessThan(300);

      const afterMultiEquip = await getPlayer();
      expect(afterMultiEquip.res.status).toBe(200);
      const pMulti = extractPlayer(afterMultiEquip.data);
      const eqStrMulti = JSON.stringify(pMulti?.equipment || {});
      expect(eqStrMulti, 'helmet should be equipped').toContain(helmetA.itemId);
      expect(eqStrMulti, 'armor should be equipped').toContain(armorA.itemId);
      expect(eqStrMulti, 'accessory should be equipped').toContain(accessoryA.itemId);
      const statsMulti = pMulti?.stats || pMulti;
      if (statsMulti?.def !== undefined) {
        expect(statsMulti.def, 'def should reflect helmet(5) + armor(10) = 15').toBe(15);
      }

      // ---- Test 2b: Normal swap - replace weapon swordA with swordB when bag has space ----
      //   swordA should return to bag, swordB goes to weapon slot
      const swapNormal = await equipItem(swordB.itemId);
      expect(swapNormal.res.status, 'normal swap should succeed (2xx)').toBeGreaterThanOrEqual(200);
      expect(swapNormal.res.status).toBeLessThan(300);

      const afterSwap = await getPlayer();
      expect(afterSwap.res.status).toBe(200);
      const pSwap = extractPlayer(afterSwap.data);
      const eqStrSwap = JSON.stringify(pSwap?.equipment || {});
      // swordB should now be in weapon slot
      expect(eqStrSwap, 'weapon slot should now contain swordB').toContain(swordB.itemId);
      // swordA should NOT be in weapon slot anymore
      expect(eqStrSwap, 'swordA should no longer be in weapon slot').not.toContain(swordA.itemId);
      // swordA should have returned to inventory
      const invSwap = pSwap?.inventory || pSwap?.items || [];
      expect(Array.isArray(invSwap), 'inventory should be an array').toBe(true);
      const swordAInBag = invSwap.some(i => (i.itemId || i.id) === swordA.itemId);
      expect(swordAInBag, 'swordA should be back in inventory after normal swap').toBe(true);

      // ---- Test 3: Full bag swap rejection ----
      // Swap back to swordA first so swordB is in bag
      const swapBack = await equipItem(swordA.itemId);
      expect(swapBack.res.status).toBeGreaterThanOrEqual(200);
      expect(swapBack.res.status).toBeLessThan(300);

      // Now fill the bag to capacity so old weapon can't return
      const fillerItems = Array.from({ length: 18 }, (_, i) => ({ itemId: `filler-${i}-${suffix}`, quantity: 1 }));
      // Keep swordB in inventory too
      const fullInventory = [...fillerItems, { itemId: swordB.itemId, quantity: 1 }];
      const patchRes = await patchPlayer({
        inventory: fullInventory,
        bagCapacity: fullInventory.length, // bag is exactly full
      });

      // Verify bag is actually full before attempting swap
      const beforeFullSwap = await getPlayer();
      expect(beforeFullSwap.res.status).toBe(200);
      const pBeforeFull = extractPlayer(beforeFullSwap.data);
      const invBeforeFull = pBeforeFull?.inventory || pBeforeFull?.items || [];
      const bagCap = pBeforeFull?.bagCapacity || pBeforeFull?.bagSize || fullInventory.length;
      expect(invBeforeFull.length, 'bag should be full before swap test').toBeGreaterThanOrEqual(bagCap);

      const swapFullBag = await equipItem(swordB.itemId);
      expect(swapFullBag.res.status, 'swap with full bag should be rejected (4xx)').toBeGreaterThanOrEqual(400);
      expect(swapFullBag.res.status).toBeLessThan(500);
      const swapMsg = JSON.stringify(swapFullBag.data || {});
      expect(swapMsg, 'should mention bag/capacity issue').toMatch(/bag|inventory|capacity|空间|背包|full|满/i);

      // Verify nothing changed after rejected swap
      const afterRejectedSwap = await getPlayer();
      const pRej = extractPlayer(afterRejectedSwap.data);
      const eqRej = JSON.stringify(pRej?.equipment || {});
      expect(eqRej, 'weapon should remain swordA after rejected swap').toContain(swordA.itemId);
      const invRej = pRej?.inventory || pRej?.items || [];
      const hasSwordBStill = invRej.some(i => (i.itemId || i.id) === swordB.itemId);
      expect(hasSwordBStill, 'swordB should still be in inventory after rejected swap').toBe(true);

      // ---- Test 4: Level restriction ----
      // Restore bag to have space and add highSword, confirm level is still 10 < 20
      await patchPlayer({
        inventory: [{ itemId: highSword.itemId, quantity: 1 }],
        bagCapacity: 5,
      });

      // Confirm player level is still 10
      const levelCheck = await getPlayer();
      expect(levelCheck.res.status).toBe(200);
      const pLevel = extractPlayer(levelCheck.data);
      const currentLevel = pLevel?.level;
      expect(currentLevel, 'player level should still be 10').toBe(10);

      const levelReject = await equipItem(highSword.itemId);
      expect(levelReject.res.status, 'equip high-level item should be rejected (4xx)').toBeGreaterThanOrEqual(400);
      expect(levelReject.res.status).toBeLessThan(500);
      const levelMsg = JSON.stringify(levelReject.data || {});
      expect(levelMsg, 'should mention level requirement').toMatch(/level|require|等级/i);

      // ---- Test 5: Persistence after simulated refresh ----
      const persistCheck = await getPlayer();
      expect(persistCheck.res.status).toBe(200);
      const pPersist = extractPlayer(persistCheck.data);
      const eqPersist = JSON.stringify(pPersist?.equipment || {});
      expect(eqPersist, 'weapon should persist as swordA').toContain(swordA.itemId);
      expect(eqPersist, 'helmet should persist').toContain(helmetA.itemId);
      expect(eqPersist, 'armor should persist').toContain(armorA.itemId);
