describe('round26_replay_isolation_strict', () => {
  const playerId = randomId('round26-player');
  const mapName = randomId('round26-map');
  const cleanupPaths = [];
  let mapId;

  afterAll(async () => {
    await safeDelete(cleanupPaths);
  });

  it('should isolate all replay side effects from formal save data, including equipment durability and consumable counts', async () => {
    // --- Create player with consumables, equipment, quests, death count ---
    const createPlayer = await request('POST', '/api/players', {
      id: playerId,
      name: 'Round26',
      level: 8,
      gold: 50,
      deaths: 3,
      bestRecords: { 'level-1': { time: 20, deaths: 1 } },
      quests: [{ id: 'q1', progress: 0, status: 'active' }],
      inventory: [
        { itemId: 'health-potion', qty: 5 },
        { itemId: 'starter-sword', qty: 1, durability: 100 },
      ],
      equipment: { weapon: 'starter-sword' },
      skills: { slash: { points: 2 } },
      activeSkillSlots: ['slash'],
      cooldowns: { slash: 0 },
    });
    expect(createPlayer.res.status, `create player should succeed, got ${createPlayer.res.status}`).toBeLessThan(300);
    cleanupPaths.push(`/api/players/${playerId}`);

    // --- Create a valid map for testing ---
    const createMap = await request('POST', '/api/editor/maps', {
      ownerId: playerId,
      name: mapName,
      width: 10,
      height: 5,
      tiles: [
        ['S', '.', '.', '.', '.', '.', '.', '.', '.', 'E'],
        ['.', '.', '.', '.', '.', '.', '.', '.', '.', '.'],
        ['.', '.', '.', 'X', '.', '.', '.', '.', '.', '.'],
        ['.', '.', '.', '.', '.', '.', '.', '.', '.', '.'],
        ['G', 'G', 'G', 'G', 'G', 'G', 'G', 'G', 'G', 'G'],
      ],
      spawn: { x: 0, y: 0 },
      goal: { x: 9, y: 0 },
      hazards: [{ type: 'spike', x: 3, y: 2 }],
    });
    expect(createMap.res.status, `create map should succeed, got ${createMap.res.status}`).toBeLessThan(300);
    mapId = createMap.body?.id || createMap.body?.mapId;
    expect(mapId, 'map id should be returned').toBeTruthy();
    cleanupPaths.push(`/api/editor/maps/${mapId}`);

    // --- Snapshot formal state before replay ---
    const before = await request('GET', `/api/players/${playerId}`);
    expect(before.res.status, `GET player state should succeed, got ${before.res.status}`).toBe(200);
    expect(before.body, 'player state should be returned').toBeTruthy();

    const goldBefore = before.body.gold;
    const deathsBefore = before.body.deaths;
    const inventoryBefore = JSON.parse(JSON.stringify(before.body.inventory || []));
    const equipmentBefore = JSON.parse(JSON.stringify(before.body.equipment || {}));
    const questsBefore = JSON.parse(JSON.stringify(before.body.quests || []));
    const skillsBefore = JSON.parse(JSON.stringify(before.body.skills || {}));
    const cooldownsBefore = JSON.parse(JSON.stringify(before.body.cooldowns || {}));
    const bestRecordsBefore = JSON.parse(JSON.stringify(before.body.bestRecords || {}));

    // --- Execute replay with script that would cause death, use skills, trigger consumable use ---
    const replay = await request('POST', `/api/editor/maps/${mapId}/replay`, {
      playerId,
      mapId,
      useOfficialLoadout: true,
      script: [
        'MOVE_RIGHT',
        'MOVE_RIGHT',
        'MOVE_RIGHT',
        'SKILL_1',
        'MOVE_RIGHT',
        'JUMP',
        'MOVE_RIGHT',
        'MOVE_RIGHT',
        'MOVE_RIGHT',
        'MOVE_RIGHT',
        'MOVE_RIGHT',
      ],
    });

    expect(
      [200, 201, 400, 422].includes(replay.res.status),
      `replay should respond 200/201 (success) or 400/422 (validation), got ${replay.res.status}`
    ).toBe(true);

    // --- Check replay result summary if successful ---
    if (replay.res.status >= 200 && replay.res.status < 300) {
      const result = replay.body?.result || replay.body?.summary || replay.body;
      expect(result, 'replay should return a result summary').toBeTruthy();

      // Summary should contain observable gameplay data
      const resultStr = JSON.stringify(result).toLowerCase();
      const hasGameplayData = /position|health|life|hp|cleared|passed|spike|death|complete/.test(resultStr);
      expect(
        hasGameplayData,
        `replay summary should contain gameplay result data, got: ${resultStr.substring(0, 200)}`
      ).toBe(true);
    }

    // --- Snapshot formal state AFTER replay ---
    const after = await request('GET', `/api/players/${playerId}`);
    expect(after.res.status, 'GET player after replay should succeed').toBe(200);
    expect(after.body, 'player state after replay should be returned').toBeTruthy();

    // --- Assert formal state is NOT polluted ---

    // Gold unchanged
    expect(after.body.gold, 'formal gold should not change from replay').toBe(goldBefore);

    // Deaths unchanged (replay deaths must not count)
    if (deathsBefore !== undefined) {
      expect(after.body.deaths, 'formal death count should not change from replay').toBe(deathsBefore);
    }

    // Best records unchanged
    expect(after.body.bestRecords || {}, 'formal best records should not be polluted').toEqual(bestRecordsBefore);

    // Quests unchanged
    expect(after.body.quests || [], 'formal quests should not be altered by replay').toEqual(questsBefore);

    // Inventory unchanged (consumable quantities must not decrease, no replay drops added)
    expect(after.body.inventory || [], 'formal inventory should not be polluted by replay').toEqual(inventoryBefore);

    // Equipment unchanged (durability must not decrease)
    expect(after.body.equipment || {}, 'formal equipment should not be polluted by replay').toEqual(equipmentBefore);

    // Skills unchanged
    expect(after.body.skills || {}, 'formal skills should not be polluted by replay').toEqual(skillsBefore);

    // Cooldowns unchanged
    expect(after.body.cooldowns || {}, 'formal cooldowns should not be polluted by replay').toEqual(cooldownsBefore);
  });

  it('should reject replay in formal adventure context', async () => {
    const adventureReplay = await request('POST', '/api/adventure/replay', {
      playerId,
      levelId: 'level-1',
      script: ['MOVE_RIGHT', 'MOVE_RIGHT'],
    });
    expect(
      [400, 403, 404, 405, 422].includes(adventureReplay.res.status),
      `replay in formal adventure context should be rejected, got ${adventureReplay.res.status}`
    ).toBe(true);

    // Also try player-scoped adventure replay
    const adventureReplay2 = await request('POST', `/api/players/${playerId}/adventure/replay`, {
      levelId: 'level-1',
      script: ['MOVE_RIGHT', 'MOVE_RIGHT'],
    });
    expect(
      [400, 403, 404, 405, 422].includes(adventureReplay2.res.status),
      `player-scoped adventure replay should also be rejected, got ${adventureReplay2.res.status}`
    ).toBe(true);
  });

  it('should not persist replay results long-term', async () => {
    // Attempt to retrieve replay history — should be empty or non-existent
    const replayHistory = await request('GET', `/api/players/${playerId}/replay-history`);
    if (replayHistory.res.status >= 200 && replayHistory.res.status < 300) {
      const items = replayHistory.body?.results || replayHistory.body?.runs || replayHistory.body;
      if (Array.isArray(items)) {
        expect(items.length, 'replay results should not be persisted long-term').toBe(0);
      }
    }
    // 404 is also acceptable — no persistence endpoint means no long-term storage
    expect(
      [200, 404].includes(replayHistory.res.status),
      `replay history should be empty (200) or not exist (404), got ${replayHistory.res.status}`
    ).toBe(true);
  });
});

