async function tryPaths(method, paths, body) {
  for (const path of paths) {
    const result = await request(method, path, body);
    if (result.res.status < 400) return { ...result, usedPath: path };
  }
  const last = await request(method, paths[paths.length - 1], body);
  return { ...last, usedPath: paths[paths.length - 1] };
}

describe('round24_compatibility_regression_unchanged', () => {
  it('should preserve formal progress, best score, gold and quest state during legacy migration, and global quick panel info should be available', async () => {
    const profileId = randomId('round24-profile');
    const cleanupPaths = [];

    try {
      // Create a save with known formal progress, gold, bestScore, and quest state
      const create = await tryPaths('POST', [
        '/api/saves',
        '/api/players',
        '/api/test-players',
      ], {
        profileId,
        playerId: profileId,
