          bestScore: 66,
          progress: { currentLevel: 7, completedLevels: [1, 2, 3, 4, 5, 6] },
          quests: [{ id: 'q-compat', status: 'completed', progress: 3 }],
        },
      });

      expect(create.res.status, `Save creation endpoint must return success, got ${create.res.status}`).toBeGreaterThanOrEqual(200);
      expect(create.res.status).toBeLessThan(300);
      const saveId = create.body?.id || create.body?.saveId || create.body?.profileId || profileId;
