      expect(Array.isArray(quests), 'quests should be an array').toBe(true);
      const compatQuest = quests.find((q) => q.id === 'q-compat');
      expect(compatQuest, `quest q-compat should survive migration, got ${JSON.stringify(quests)}`).toBeTruthy();
      expect(compatQuest.status, 'quest status should be preserved').toBe('completed');
      expect(compatQuest.progress, 'quest progress should be preserved').toBe(3);

      // Verify legacy map was migrated to custom maps list
