        `/api/saves/${encodeURIComponent(saveId)}/summary`,
      ]);

      if (panelInfo.res.status >= 200 && panelInfo.res.status < 300 && panelInfo.body) {
        const panel = panelInfo.body;
        // Quick panel should expose specific fields, not just contain keywords
        const panelGold = panel.gold ?? panel.coins ?? panel.resources?.gold;
        expect(panelGold, 'global panel should include gold value').toBeDefined();
        expect(typeof panelGold, 'panel gold should be a number').toBe('number');

        const panelHp = panel.hp ?? panel.health ?? panel.life ?? panel.maxHp;
        expect(panelHp, 'global panel should include health/hp info').toBeDefined();

        // Check for experience or level info
        const panelLevel = panel.level ?? panel.characterLevel ?? panel.playerLevel;
        expect(panelLevel, 'global panel should include level info').toBeDefined();
      } else {
        // If no dedicated panel endpoint, verify save response itself has all necessary display fields
        expect(gold, 'save data should contain gold for display').toBeDefined();
        expect(typeof gold, 'gold should be a number').toBe('number');
        expect(progress, 'save data should contain progress for display').toBeDefined();
        expect(quests, 'save data should contain quests for display').toBeDefined();
        // The save data should also contain enough info for a panel
        const hasLevel = fetchedBody.level ?? fetchedBody.profile?.level ?? fetchedBody.characterLevel;
        expect(hasLevel !== undefined || progress.currentLevel !== undefined,
          'save data should contain level/characterLevel for display').toBe(true);
      }

      // Verify player name still accessible (original page info not lost)
      const playerName = fetchedBody.playerName ?? fetchedBody.name ?? fetchedBody.profile?.playerName;
      expect(playerName, 'player name should still be accessible after migration').toBeTruthy();
    } finally {
      await safeDelete(cleanupPaths);
    }
  });
});

