    expect(successReset.res.status, `expected successful reset status < 300, got ${successReset.res.status}`).toBeLessThan(300);

    const playerRes = await request('GET', `/api/players/${playerId}`, undefined);
    expect(playerRes.res.status, `expected player fetch status 200, got ${playerRes.res.status}`).toBe(200);
    const player = playerRes.data.player || playerRes.data;
    expect(player.gold, `gold should be reduced by reset cost to 50, got ${player.gold}`).toBe(50);
    expect(player.skillPoints, `skill points should be refunded to 3 after reset, got ${player.skillPoints}`).toBe(3);
    expect(Array.isArray(player.activeSkillSlots) ? player.activeSkillSlots.length : -1, `active skill slots should be cleared after reset, got ${JSON.stringify(player.activeSkillSlots)}`).toBe(0);
    expect(player.level, `player level should remain 12 after skill reset, got ${player.level}`).toBe(12);
    expect(player.equipment?.weapon?.itemId, `equipped weapon should remain ${weaponId} after skill reset, got ${player.equipment?.weapon?.itemId}`).toBe(weaponId);

    await safeDelete(`/api/test/players/${playerId}`);
    await safeDelete('/api/test/config');
  });
});

import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function request(method, path, body) {
  const res = await fetch(`${BASE_URL}${path}`, {
    method,
    headers: { 'Content-Type': 'application/json' },
    body: body === undefined ? undefined : JSON.stringify(body),
  });
  const text = await res.text();
  let json;
  try {
    json = text ? JSON.parse(text) : null;
  } catch {
    json = text;
  }
  return { res, body: json };
}

async function findWorkingEndpoint(method, pathCandidates, body) {
  for (const path of pathCandidates) {
    const result = await request(method, path, body);
    if (result.res.status < 500) return { ...result, usedPath: path };
  }
  const last = pathCandidates[pathCandidates.length - 1];
  return { ...(await request(method, last, body)), usedPath: last };
}

async function cleanup(paths) {
  for (const path of paths) {
    try {
      await fetch(`${BASE_URL}${path}`, { method: 'DELETE' });
    } catch {
      // ignore cleanup errors
    }
  }
}

describe('confirm_reward_updates_account_state', () => {
  it('should only write adventure rewards after confirmation, track overflow items persistently, show remaining bag slots, and allow repeat claims', async () => {
    const id = `reward-case-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
    const cleanupPaths = [];

    try {
      // Step 1: Create test user with small inventory capacity to trigger overflow
      const createResult = await findWorkingEndpoint('POST', [
        '/api/test/users',
        '/api/users',
        '/api/players',
