      expect(beforeBody.exp).toBe(0);
      const initialInventory = beforeBody.inventory || beforeBody.items || [];
      expect(Array.isArray(initialInventory)).toBe(true);
      expect(initialInventory.length).toBe(0);

      // Verify initial remaining bag slots
      const initialSlots = beforeBody.remainingSlots ?? beforeBody.freeSlots ?? beforeBody.availableSlots;
      if (initialSlots !== undefined) {
        expect(initialSlots).toBe(1);
      }

      // Step 3: Complete a stage — rewards should NOT be applied yet
      const settleResult = await findWorkingEndpoint('POST', [
        '/api/adventure/complete',
        '/api/adventure/settle',
        '/api/stages/complete',
        '/api/adventure/stages/complete',
