          ],
        },
      });
      expect([200, 201]).toContain(settleResult.res.status);
      expect(settleResult.body && typeof settleResult.body).toBe('object');

      // Verify confirmation is required
      const confirmRequired = settleResult.body.confirmationRequired ?? settleResult.body.requiresConfirmation ?? settleResult.body.pending;
      expect(confirmRequired, `Expected settlement to require confirmation: ${JSON.stringify(settleResult.body)}`).toBeTruthy();

      // Verify reward summary in settlement response
      const settleReward = settleResult.body.reward || settleResult.body.rewards;
      expect(settleReward, 'Settlement should include reward summary').toBeTruthy();

      // Verify stage indicates repeatable rewards
      const repeatable = settleResult.body.repeatable ?? settleResult.body.isRepeatable ?? (settleReward && settleReward.repeatable);
      // Just check the field exists if available - the key requirement is that repeat claims work

      const settlementId = settleResult.body.settlementId || settleResult.body.settlement_id || settleResult.body.id;
      expect(settlementId, `missing settlementId in response: ${JSON.stringify(settleResult.body)}`).toBeTruthy();

      // Step 4: Before confirmation, account should be unchanged
      const notConfirmedResult = await findWorkingEndpoint('GET', [
        `/api/users/${id}/account`,
        `/api/players/${id}`,
        `/api/users/${id}`,
      ]);
      expect(notConfirmedResult.res.status).toBe(200);
      expect(notConfirmedResult.body.gold).toBe(10);
      expect(notConfirmedResult.body.exp).toBe(0);
      const ncInventory = notConfirmedResult.body.inventory || notConfirmedResult.body.items || [];
      expect(ncInventory.length).toBe(0);

      // Step 5: Confirm the settlement
