        `/api/adventure/settlements/${settlementId}/confirm`,
        `/api/settlements/${settlementId}/confirm`,
        `/api/adventure/confirm/${settlementId}`,
      ], {
        userId: id,
      });
      expect([200, 201]).toContain(confirmResult.res.status);
      const applied = confirmResult.body.applied ?? confirmResult.body.success ?? confirmResult.body.confirmed;
      expect(applied, `Expected confirmation to succeed: ${JSON.stringify(confirmResult.body)}`).toBe(true);

      // Verify gold and exp were credited
      const confirmAccount = confirmResult.body.account || confirmResult.body.player || confirmResult.body;
      expect(confirmAccount.gold).toBe(60);
      expect(confirmAccount.exp).toBe(20);

      // Verify overflow items (capacity=1 but 2 items rewarded)
      const overflowItems = confirmResult.body.overflowItems || confirmResult.body.overflow || confirmResult.body.pendingItems || confirmResult.body.unclaimedItems || [];
      expect(Array.isArray(overflowItems), `overflowItems should be an array when capacity is insufficient: ${JSON.stringify(confirmResult.body)}`).toBe(true);
      expect(overflowItems.length).toBeGreaterThan(0);
      const firstOverflow = overflowItems[0];
      expect(firstOverflow.itemId || firstOverflow.id, 'Overflow item should have an item identifier').toBeTruthy();
      expect(firstOverflow.quantity || firstOverflow.count, 'Overflow item should have a quantity').toBeGreaterThan(0);

      // Step 6: Verify account state after confirmation via GET, including bag slots
      const afterResult = await findWorkingEndpoint('GET', [
        `/api/users/${id}/account`,
        `/api/players/${id}`,
        `/api/users/${id}`,
      ]);
