      expect(afterResult.body.gold).toBe(60);
      expect(afterResult.body.exp).toBe(20);
      const afterInventory = afterResult.body.inventory || afterResult.body.items || [];
      expect(Array.isArray(afterInventory)).toBe(true);
      // Only 1 item should fit in inventory
      expect(afterInventory.length).toBe(1);

      // Verify remaining bag slots updated
      const afterSlots = afterResult.body.remainingSlots ?? afterResult.body.freeSlots ?? afterResult.body.availableSlots;
      if (afterSlots !== undefined) {
        expect(afterSlots).toBe(0);
      }

      // Step 7: Verify overflow items are persisted/queryable (not just one-time response)
      const pendingResult = await findWorkingEndpoint('GET', [
        `/api/users/${id}/pending-rewards`,
        `/api/users/${id}/overflow`,
        `/api/users/${id}/unclaimed`,
        `/api/players/${id}/pending-rewards`,
      ]);
      // Overflow must be persisted - this is a hard requirement
      expect(pendingResult.res.status, `Overflow items must be queryable after confirmation. Status: ${pendingResult.res.status}`).toBe(200);
      const pendingItems = pendingResult.body.items || pendingResult.body.pendingItems || pendingResult.body.overflow || pendingResult.body || [];
      if (Array.isArray(pendingItems)) {
        expect(pendingItems.length, 'Overflow items should be persisted and retrievable').toBeGreaterThan(0);
      }

      // Step 8: Repeat completion of the same stage (rewards are repeatable)
      const settle2Result = await findWorkingEndpoint('POST', [
        '/api/adventure/complete',
        '/api/adventure/settle',
        '/api/stages/complete',
      ], {
        userId: id,
        mode: 'formal',
        stageId: 'stage-reward-1',
        reward: {
          gold: 50,
          exp: 20,
          items: [{ itemId: 'potion_small', quantity: 1 }],
        },
      });
      expect([200, 201]).toContain(settle2Result.res.status);
      const settlementId2 = settle2Result.body.settlementId || settle2Result.body.settlement_id || settle2Result.body.id;
      expect(settlementId2, 'Repeat settlement should produce a new settlement ID').toBeTruthy();

      const confirm2Result = await findWorkingEndpoint('POST', [
        `/api/adventure/settlements/${settlementId2}/confirm`,
        `/api/settlements/${settlementId2}/confirm`,
        `/api/adventure/confirm/${settlementId2}`,
      ], {
        userId: id,
      });
      expect([200, 201]).toContain(confirm2Result.res.status);
      const applied2 = confirm2Result.body.applied ?? confirm2Result.body.success ?? confirm2Result.body.confirmed;
      expect(applied2, 'Repeat reward confirmation should succeed').toBe(true);

      // Gold and exp should accumulate
      const confirm2Account = confirm2Result.body.account || confirm2Result.body.player || confirm2Result.body;
      expect(confirm2Account.gold).toBe(110);
      expect(confirm2Account.exp).toBe(40);

      // Second reward item should also overflow since inventory is full
      const overflow2 = confirm2Result.body.overflowItems || confirm2Result.body.overflow || confirm2Result.body.pendingItems || confirm2Result.body.unclaimedItems || [];
      expect(Array.isArray(overflow2), 'Second reward overflow should be an array').toBe(true);
      expect(overflow2.length, 'Inventory was full, so new item should overflow').toBeGreaterThan(0);

      // Verify final account state with all synced updates
      const finalResult = await findWorkingEndpoint('GET', [
        `/api/users/${id}/account`,
        `/api/players/${id}`,
        `/api/users/${id}`,
      ]);
      expect(finalResult.res.status).toBe(200);
      expect(finalResult.body.gold).toBe(110);
      expect(finalResult.body.exp).toBe(40);
      const finalInventory = finalResult.body.inventory || finalResult.body.items || [];
      expect(finalInventory.length).toBe(1);

      // Verify final bag slots
      const finalSlots = finalResult.body.remainingSlots ?? finalResult.body.freeSlots ?? finalResult.body.availableSlots;
      if (finalSlots !== undefined) {
        expect(finalSlots).toBe(0);
      }
    } finally {
      await cleanup(cleanupPaths);
    }
  });
});

