describe('skill_prerequisite_and_points_validation', () => {
  it('should enforce initial points, active/passive distinction, prerequisites, insufficient point errors, effect descriptions, unlocked count, and active skill equip limit', async () => {
    const id = `skill-case-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
    const cleanupPaths = [];

    try {
      // Step 1: Create test user with initial 5 skill points and some gold for reset test
      const create = await findWorkingEndpoint('POST', [
        '/api/test/users',
        '/api/users',
        '/api/players',
      ], {
        id,
        level: 1,
        gold: 500,
        skillPoints: 5,
        learnedSkills: [],
      });
      expect([200, 201]).toContain(create.res.status);
      cleanupPaths.push(`/api/test/users/${id}`, `/api/users/${id}`, `/api/players/${id}`);

      // Step 2: Fetch skill tree and verify initial state
      const tree = await findWorkingEndpoint('GET', [
        `/api/skills/tree?userId=${encodeURIComponent(id)}`,
        `/api/users/${id}/skills/tree`,
        `/api/players/${id}/skill-tree`,
        `/api/skill-tree?userId=${encodeURIComponent(id)}`,
      ]);
      expect(tree.res.status).toBe(200);

      const availablePoints = tree.body.availablePoints ?? tree.body.skillPoints ?? tree.body.points;
      expect(availablePoints).toBe(5);

      const skills = tree.body.skills || tree.body.skillTree || tree.body.nodes || [];
      expect(Array.isArray(skills)).toBe(true);
      expect(skills.length).toBeGreaterThan(0);

      // Verify initial unlocked count
      const initialUnlockedCount = tree.body.unlockedCount ?? tree.body.learnedCount ?? 0;
      expect(initialUnlockedCount).toBe(0);

      // Step 3: Dynamically find active and passive skills, and one with prerequisites
      const activeSkillsNoPrereq = skills.filter((s) => s.type === 'active' && (!s.prerequisites || s.prerequisites.length === 0));
      const passiveSkillsNoPrereq = skills.filter((s) => s.type === 'passive' && (!s.prerequisites || s.prerequisites.length === 0));
      const advancedSkill = skills.find(
        (s) => s.prerequisites && s.prerequisites.length > 0
      );

      const activeSkill = activeSkillsNoPrereq[0];
      const passiveSkill = passiveSkillsNoPrereq[0];

      expect(activeSkill, `expected at least one active skill without prerequisites`).toBeTruthy();
      expect(passiveSkill, `expected at least one passive skill without prerequisites`).toBeTruthy();
      expect(advancedSkill, `expected at least one skill with prerequisites`).toBeTruthy();

      expect(activeSkill.type).toBe('active');
      expect(passiveSkill.type).toBe('passive');
      expect(Array.isArray(advancedSkill.prerequisites)).toBe(true);
      expect(advancedSkill.prerequisites.length).toBeGreaterThan(0);

      // Step 4: Try to learn advanced skill without prerequisites — should fail
      const invalidLearn = await findWorkingEndpoint('POST', [
        '/api/skills/learn',
        `/api/users/${id}/skills/learn`,
        `/api/players/${id}/skills/learn`,
      ], {
        userId: id,
        skillId: advancedSkill.id,
      });
      expect([400, 409, 422]).toContain(invalidLearn.res.status);
      const invalidMsg = String(invalidLearn.body.error || invalidLearn.body.message || '');
      expect(invalidMsg).toMatch(/prereq|前置|require|unlock|解锁/i);
      // Should tell the player what they're missing
      const missingInfo = invalidLearn.body.missingPrerequisites || invalidLearn.body.missing || invalidLearn.body.details || invalidLearn.body.required;
      expect(missingInfo, `should indicate what prerequisites are missing: ${JSON.stringify(invalidLearn.body)}`).toBeTruthy();

      // Step 5: Learn the active skill (no prereqs)
      const learn1 = await findWorkingEndpoint('POST', [
        '/api/skills/learn',
        `/api/users/${id}/skills/learn`,
      ], {
        userId: id,
        skillId: activeSkill.id,
      });
      expect([200, 201]).toContain(learn1.res.status);
      const remaining1 = learn1.body.remainingPoints ?? learn1.body.skillPoints ?? learn1.body.availablePoints;
      expect(remaining1).toBe(4);

      // Verify unlocked count updated
      const count1 = learn1.body.unlockedCount ?? learn1.body.learnedCount;
      if (count1 !== undefined) {
        expect(count1).toBe(1);
      }

      // Step 6: Verify learned skill has effect description
      const treeAfterLearn = await findWorkingEndpoint('GET', [
        `/api/skills/tree?userId=${encodeURIComponent(id)}`,
        `/api/users/${id}/skills/tree`,
      ]);
      expect(treeAfterLearn.res.status).toBe(200);
      const learnedSkillsData = treeAfterLearn.body.skills || treeAfterLearn.body.skillTree || treeAfterLearn.body.nodes || [];
      const learnedActiveSkill = learnedSkillsData.find((s) => s.id === activeSkill.id);
      expect(learnedActiveSkill).toBeTruthy();
      const effectDesc = learnedActiveSkill.effectDescription || learnedActiveSkill.effect || learnedActiveSkill.description;
      expect(effectDesc, `learned skill should have effect description`).toBeTruthy();
      expect(typeof effectDesc === 'string' && effectDesc.length > 0).toBe(true);

      // Verify unlocked count in tree response
      const treeUnlockedCount1 = treeAfterLearn.body.unlockedCount ?? treeAfterLearn.body.learnedCount;
      if (treeUnlockedCount1 !== undefined) {
        expect(treeUnlockedCount1).toBe(1);
      }

      // Step 7: Learn the passive skill
      const learn2 = await findWorkingEndpoint('POST', [
        '/api/skills/learn',
        `/api/users/${id}/skills/learn`,
      ], {
        userId: id,
        skillId: passiveSkill.id,
      });
      expect([200, 201]).toContain(learn2.res.status);
      const remaining2 = learn2.body.remainingPoints ?? learn2.body.skillPoints ?? learn2.body.availablePoints;
      expect(remaining2).toBe(3);

      // Verify unlocked count updated to 2
      const count2 = learn2.body.unlockedCount ?? learn2.body.learnedCount;
      if (count2 !== undefined) {
        expect(count2).toBe(2);
      }

      // Step 8: Learn more skills to exhaust all 5 points
      const alreadyLearned = [activeSkill.id, passiveSkill.id];
      const learnableSkills = skills.filter(
        (s) =>
          !alreadyLearned.includes(s.id) &&
          (!s.prerequisites || s.prerequisites.length === 0 || s.prerequisites.every((p) => alreadyLearned.includes(p)))
      );

      let expectedRemaining = 3;
      const additionalLearned = [];
      for (const skill of learnableSkills) {
        if (expectedRemaining <= 0) break;
        const r = await findWorkingEndpoint('POST', [
          '/api/skills/learn',
          `/api/users/${id}/skills/learn`,
        ], { userId: id, skillId: skill.id });
        if ([200, 201].includes(r.res.status)) {
          expectedRemaining -= 1;
          const rem = r.body.remainingPoints ?? r.body.skillPoints ?? r.body.availablePoints;
          expect(rem).toBe(expectedRemaining);
          additionalLearned.push(skill.id);
        }
      }
      expect(expectedRemaining).toBe(0);

      // Step 9: Try to learn with 0 points — should fail with point-related error
      const noPointsTarget = learnableSkills.find(s => !alreadyLearned.includes(s.id) && !additionalLearned.includes(s.id)) || advancedSkill;
      const noPoints = await findWorkingEndpoint('POST', [
        '/api/skills/learn',
        `/api/users/${id}/skills/learn`,
      ], {
        userId: id,
        skillId: noPointsTarget.id,
      });
      expect([400, 409, 422]).toContain(noPoints.res.status);
      const noPointsMsg = String(noPoints.body.error || noPoints.body.message || '');
      expect(noPointsMsg).toMatch(/point|点数|insufficient|不足/i);

      // Step 10: Verify final skill tree state and persistence
      const finalTree = await findWorkingEndpoint('GET', [
        `/api/skills/tree?userId=${encodeURIComponent(id)}`,
        `/api/users/${id}/skills/tree`,
      ]);
      expect(finalTree.res.status).toBe(200);
      const finalPoints = finalTree.body.availablePoints ?? finalTree.body.skillPoints ?? finalTree.body.points;
      expect(finalPoints).toBe(0);
      const finalLearned = finalTree.body.learnedSkills || finalTree.body.learned || [];
      expect(Array.isArray(finalLearned)).toBe(true);
      const learnedIds = finalLearned.map((s) => (typeof s === 'string' ? s : s.id || s.skillId));
      expect(learnedIds).toContain(activeSkill.id);
      expect(learnedIds).toContain(passiveSkill.id);

      // Verify final unlocked count
      const finalUnlockedCount = finalTree.body.unlockedCount ?? finalTree.body.learnedCount ?? learnedIds.length;
      expect(finalUnlockedCount).toBe(5);

      // Step 11: Verify persistence — re-fetch should return same state
      const persistTree = await findWorkingEndpoint('GET', [
        `/api/skills/tree?userId=${encodeURIComponent(id)}`,
        `/api/users/${id}/skills/tree`,
      ]);
      expect(persistTree.res.status).toBe(200);
      const persistPoints = persistTree.body.availablePoints ?? persistTree.body.skillPoints ?? persistTree.body.points;
      expect(persistPoints).toBe(0);
      const persistLearned = persistTree.body.learnedSkills || persistTree.body.learned || [];
      const persistIds = persistLearned.map((s) => (typeof s === 'string' ? s : s.id || s.skillId));
      expect(persistIds).toContain(activeSkill.id);
      expect(persistIds).toContain(passiveSkill.id);

      // Step 12: Test active skill equip limit (max 3 simultaneously equipped)
      const allLearnedIds = [activeSkill.id, passiveSkill.id, ...additionalLearned];
      const allSkillDetails = finalTree.body.skills || finalTree.body.skillTree || finalTree.body.nodes || [];
      const learnedActiveSkills = allSkillDetails.filter(
        (s) => s.type === 'active' && allLearnedIds.includes(s.id) && (s.learned || s.unlocked || learnedIds.includes(s.id))
      );

      // Equip active skills up to limit
      const equippedActive = [];
      for (const skill of learnedActiveSkills) {
        if (equippedActive.length >= 4) break; // try up to 4 to test the limit
        const equipRes = await findWorkingEndpoint('POST', [
          '/api/skills/equip',
          `/api/users/${id}/skills/equip`,
          `/api/players/${id}/skills/equip`,
        ], {
          userId: id,
          skillId: skill.id,
        });
        if ([200, 201].includes(equipRes.res.status)) {
          equippedActive.push(skill.id);
        } else if ([400, 409, 422].includes(equipRes.res.status) && equippedActive.length >= 3) {
          // This is the 4th attempt being correctly rejected
          const overEquipMsg = String(equipRes.body.error || equipRes.body.message || '');
          expect(overEquipMsg).toMatch(/max|limit|上限|最多|3|slot|栏位/i);
        }
      }

      // If we managed to equip exactly 3, verify the limit is enforced
      if (equippedActive.length >= 3) {
        const unequippedActive = learnedActiveSkills.find((s) => !equippedActive.includes(s.id));
        if (unequippedActive) {
          const overEquip = await findWorkingEndpoint('POST', [
            '/api/skills/equip',
            `/api/users/${id}/skills/equip`,
          ], {
            userId: id,
            skillId: unequippedActive.id,
          });
          expect([400, 409, 422]).toContain(overEquip.res.status);
          const overEquipMsg = String(overEquip.body.error || overEquip.body.message || '');
          expect(overEquipMsg).toMatch(/max|limit|上限|最多|3|slot|栏位/i);
        }
      }

      // Verify passive skill is NOT in equipped active skill slots
      const equippedRes = await findWorkingEndpoint('GET', [
        `/api/skills/equipped?userId=${encodeURIComponent(id)}`,
        `/api/users/${id}/skills/equipped`,
        `/api/players/${id}/equipped-skills`,
      ]);
      if (equippedRes.res.status === 200) {
        const equippedList = equippedRes.body.equipped || equippedRes.body.activeSkills || equippedRes.body || [];
        if (Array.isArray(equippedList)) {
          const equippedIds = equippedList.map((s) => (typeof s === 'string' ? s : s.id || s.skillId));
          expect(equippedIds).not.toContain(passiveSkill.id);
        }
      }

      // Step 13: Test skill reset (costs gold, returns points, clears active slots)
      const resetRes = await findWorkingEndpoint('POST', [
        '/api/skills/reset',
        `/api/users/${id}/skills/reset`,
        `/api/players/${id}/skills/reset`,
      ], {
        userId: id,
      });
