    } catch {}
  }
}

describe('shop_purchase_and_sell_validate_constraints', () => {
  it('should validate gold, bag capacity, level limits on buy, block selling equipped/quest-locked items, protect quest items from other consumption, and verify price format and linked updates', async () => {
    const id = `shop-case-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
    const cleanupPaths = [];

    try {
      // Step 1: Create test user with specific constraints
      const create = await findWorkingEndpoint('POST', [
        '/api/test/users',
        '/api/users',
        '/api/players',
      ], {
        id,
        gold: 100,
        level: 3,
        inventoryCapacity: 2,
        inventory: [
          { itemId: 'bronze_sword', quantity: 1, equipped: true, slot: 'weapon' },
          { itemId: 'quest_gem', quantity: 3, reservedByQuest: 2 },
        ],
      });
      expect([200, 201]).toContain(create.res.status);
      cleanupPaths.push(`/api/test/users/${id}`, `/api/users/${id}`, `/api/players/${id}`);

      // Step 2: Verify shop product list and price format
      const shopList = await findWorkingEndpoint('GET', [
        '/api/shop/products',
        '/api/shop/items',
        '/api/shop',
        '/api/store/products',
      ]);
      expect(shopList.res.status).toBe(200);
      const products = shopList.body.products || shopList.body.items || shopList.body || [];
      expect(Array.isArray(products)).toBe(true);
      expect(products.length).toBeGreaterThan(0);

      // Verify every product has a valid price (non-negative integer)
      for (const product of products) {
        const price = product.price ?? product.cost ?? product.buyPrice;
        expect(price, `product ${product.itemId || product.id || product.name} should have a price`).toBeDefined();
        expect(typeof price).toBe('number');
        expect(price).toBeGreaterThanOrEqual(0);
        expect(Number.isInteger(price), `price ${price} should be an integer, not a decimal`).toBe(true);
      }

      // Find products for different test scenarios
      const expensiveItem = products.find((p) => (p.price ?? p.cost ?? p.buyPrice) > 100);
      const highLevelItem = products.find((p) => (p.requiredLevel ?? p.levelRequired ?? p.minLevel ?? 0) > 3);
      const affordableItem = products.find(
        (p) =>
          (p.price ?? p.cost ?? p.buyPrice) <= 100 &&
          (p.requiredLevel ?? p.levelRequired ?? p.minLevel ?? 0) <= 3
      );

      // Step 3: Test purchase blocked by insufficient gold
      if (expensiveItem) {
        const noGold = await findWorkingEndpoint('POST', [
          '/api/shop/purchase',
          '/api/shop/buy',
          '/api/store/purchase',
        ], {
          userId: id,
          itemId: expensiveItem.itemId || expensiveItem.id,
          quantity: 1,
        });
        expect([400, 409, 422]).toContain(noGold.res.status);
        expect(String(noGold.body.error || noGold.body.message || '')).toMatch(/gold|金币|insufficient|不足/i);
      }

      // Step 4: Test purchase blocked by level restriction
      if (highLevelItem) {
        const levelBlocked = await findWorkingEndpoint('POST', [
          '/api/shop/purchase',
          '/api/shop/buy',
        ], {
          userId: id,
          itemId: highLevelItem.itemId || highLevelItem.id,
          quantity: 1,
        });
        expect([400, 409, 422]).toContain(levelBlocked.res.status);
        expect(String(levelBlocked.body.error || levelBlocked.body.message || '')).toMatch(/level|等级/i);
      }

      // Step 5: Test purchase blocked by inventory capacity (already 2/2)
      if (affordableItem) {
        const capacityBlocked = await findWorkingEndpoint('POST', [
          '/api/shop/purchase',
          '/api/shop/buy',
        ], {
          userId: id,
          itemId: affordableItem.itemId || affordableItem.id,
          quantity: 1,
        });
        expect([400, 409, 422]).toContain(capacityBlocked.res.status);
        expect(String(capacityBlocked.body.error || capacityBlocked.body.message || '')).toMatch(/capacity|背包|inventory|空间|full|满/i);
      }

      // Step 6: Expand inventory capacity and do a successful purchase, then verify linked updates
      await findWorkingEndpoint('POST', [
        `/api/test/users/${id}/inventory-capacity`,
        `/api/test/users/${id}`,
      ], {
        inventoryCapacity: 10,
      });
      // Also try PATCH as fallback
      await findWorkingEndpoint('PATCH', [
        `/api/test/users/${id}`,
        `/api/users/${id}`,
      ], { inventoryCapacity: 10 });

      // Record gold before purchase
      const beforeBuyState = await findWorkingEndpoint('GET', [
        `/api/users/${id}/account`,
        `/api/players/${id}`,
        `/api/users/${id}`,
      ]);
      const goldBeforeBuy = beforeBuyState.body.gold;

      if (affordableItem) {
        const itemPrice = affordableItem.price ?? affordableItem.cost ?? affordableItem.buyPrice;
        const okBuy = await findWorkingEndpoint('POST', [
          '/api/shop/purchase',
          '/api/shop/buy',
        ], {
          userId: id,
          itemId: affordableItem.itemId || affordableItem.id,
          quantity: 1,
        });
        expect([200, 201]).toContain(okBuy.res.status);

        // Verify linked updates after purchase: gold decreased, bag slot count changed
        const afterBuyState = await findWorkingEndpoint('GET', [
          `/api/users/${id}/account`,
          `/api/players/${id}`,
          `/api/users/${id}`,
        ]);
        expect(afterBuyState.res.status).toBe(200);
        expect(afterBuyState.body.gold).toBeLessThan(goldBeforeBuy);
        // Bag slot count should decrease
        const afterBuySlots = afterBuyState.body.remainingSlots ?? afterBuyState.body.freeSlots ?? afterBuyState.body.availableSlots;
        const afterBuyInventory = afterBuyState.body.inventory || afterBuyState.body.items || [];
        expect(afterBuyInventory.length).toBeGreaterThan(0);
      }

      // Step 7: Try selling equipped item — should be blocked
      const equippedSellBlocked = await findWorkingEndpoint('POST', [
        '/api/shop/sell',
        '/api/store/sell',
      ], {
        userId: id,
        itemId: 'bronze_sword',
        quantity: 1,
      });
      expect([400, 409, 422]).toContain(equippedSellBlocked.res.status);
      expect(String(equippedSellBlocked.body.error || equippedSellBlocked.body.message || '')).toMatch(/equip|穿戴|equipped|装备/i);

      // Step 8: Try selling quest-locked item beyond free amount — should be blocked
      // quest_gem has 3 total, 2 reserved. Trying to sell 2 would drop below reserved.
      const questSell2 = await findWorkingEndpoint('POST', [
        '/api/shop/sell',
        '/api/store/sell',
      ], {
        userId: id,
        itemId: 'quest_gem',
        quantity: 2,
      });
      expect([400, 409, 422]).toContain(questSell2.res.status);
      expect(String(questSell2.body.error || questSell2.body.message || '')).toMatch(/quest|任务|reserved|占用|lock/i);

      // Step 9: Test partial occupation — selling the non-occupied portion should succeed
      // quest_gem: 3 total, 2 reserved → 1 free to sell
      const goldBeforeSell = (await findWorkingEndpoint('GET', [
        `/api/users/${id}/account`,
        `/api/players/${id}`,
        `/api/users/${id}`,
      ])).body.gold;

      const questSellPartial = await findWorkingEndpoint('POST', [
        '/api/shop/sell',
        '/api/store/sell',
      ], {
        userId: id,
        itemId: 'quest_gem',
        quantity: 1,
      });
      expect([200, 201]).toContain(questSellPartial.res.status);

      // Verify gold increased from the sale
      const goldAfterPartialSell = (await findWorkingEndpoint('GET', [
        `/api/users/${id}/account`,
        `/api/players/${id}`,
        `/api/users/${id}`,
      ])).body.gold;
      expect(goldAfterPartialSell).toBeGreaterThan(goldBeforeSell);

      // Step 10: Verify quest-occupied items cannot be consumed via other means
      // Try to use/consume the quest_gem which is occupied by quest
      const useQuestItem = await findWorkingEndpoint('POST', [
        '/api/items/use',
        `/api/users/${id}/items/use`,
        `/api/players/${id}/items/use`,
        '/api/items/consume',
      ], {
        userId: id,
        itemId: 'quest_gem',
        quantity: 1,
      });
      // Should be blocked since all remaining quest_gems are occupied
      if (useQuestItem.res.status >= 400) {
        const useMsg = String(useQuestItem.body.error || useQuestItem.body.message || '');
        expect(useMsg).toMatch(/quest|任务|reserved|占用|lock|cannot|禁止/i);
      }

      // Step 11: Sell a free (non-equipped, non-quest) item and verify gold increase
      // Add a free item for selling
      await findWorkingEndpoint('POST', [
        `/api/test/users/${id}/inventory`,
        `/api/test/users/${id}/items`,
      ], {
        itemId: 'wolf_pelt',
        quantity: 3,
      });

      const goldBeforeFreeSell = (await findWorkingEndpoint('GET', [
        `/api/users/${id}/account`,
        `/api/players/${id}`,
        `/api/users/${id}`,
      ])).body.gold;

      const sellOk = await findWorkingEndpoint('POST', [
        '/api/shop/sell',
        '/api/store/sell',
      ], {
        userId: id,
        itemId: 'wolf_pelt',
        quantity: 2,
      });
      expect([200, 201]).toContain(sellOk.res.status);

      // Verify gold actually increased from the sale
      const goldAfterFreeSell = (await findWorkingEndpoint('GET', [
        `/api/users/${id}/account`,
        `/api/players/${id}`,
        `/api/users/${id}`,
      ])).body.gold;
      expect(goldAfterFreeSell).toBeGreaterThan(goldBeforeFreeSell);

      // Verify inventory state is consistent
      const finalState = await findWorkingEndpoint('GET', [
        `/api/users/${id}/account`,
        `/api/players/${id}`,
        `/api/users/${id}`,
      ]);
      expect(finalState.res.status).toBe(200);
      const finalInventory = finalState.body.inventory || finalState.body.items || [];
      expect(Array.isArray(finalInventory)).toBe(true);
      // wolf_pelt should have 1 remaining (had 3, sold 2)
      const remainingPelt = finalInventory.find(i => (i.itemId || i.id) === 'wolf_pelt');
      if (remainingPelt) {
        expect(remainingPelt.quantity || remainingPelt.count).toBe(1);
      }
    } finally {
      await cleanup(cleanupPaths);
    }
  });
});

