describe('editor_test_mode_does_not_write_formal_progress', () => {
  it('should keep editor test results fully isolated from formal progression including all tracked dimensions', async () => {
    const id = `editor-test-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
    const mapId = `temp-map-${Date.now()}`;
    const cleanupPaths = [];

    try {
      // Step 1: Create user with known formal state including all tracked dimensions
