        '/api/test/users',
        '/api/users',
        '/api/players',
      ], {
        id,
        gold: 100,
        exp: 10,
        level: 2,
        inventoryCapacity: 10,
        inventory: [{ itemId: 'healing_potion', quantity: 5 }],
        cooldowns: { fireball: 0 },
