        durability: { bronze_sword: 90 },
        equippedSkills: ['fireball'],
        equippedItems: ['bronze_sword'],
      });
      expect([200, 201]).toContain(create.res.status);
      cleanupPaths.push(`/api/test/users/${id}`, `/api/users/${id}`, `/api/players/${id}`);

      // Step 2: Create an editor map with valid testable layout
      const createMap = await findWorkingEndpoint('POST', [
        '/api/editor/maps',
        `/api/users/${id}/editor/maps`,
        '/api/maps',
      ], {
        userId: id,
        mapId,
        name: 'Isolation Test Map',
        elements: [
          { type: 'spawn', x: 0, y: 0 },
          { type: 'goal', x: 4, y: 0 },
          { type: 'ground', x: 0, y: 1 },
          { type: 'ground', x: 1, y: 1 },
          { type: 'ground', x: 2, y: 1 },
          { type: 'ground', x: 3, y: 1 },
          { type: 'ground', x: 4, y: 1 },
        ],
      });
      expect([200, 201]).toContain(createMap.res.status);
      cleanupPaths.push(
        `/api/editor/maps/${mapId}?userId=${encodeURIComponent(id)}`,
        `/api/maps/${mapId}`,
      );

      // Step 3: Snapshot full formal state before test mode
      const beforeResult = await findWorkingEndpoint('GET', [
        `/api/users/${id}/account`,
        `/api/players/${id}`,
        `/api/users/${id}`,
        `/api/users/${id}/state`,
      ]);
      expect(beforeResult.res.status).toBe(200);
      const beforeData = beforeResult.body;
      expect(beforeData.gold).toBe(100);
      expect(beforeData.exp).toBe(10);

      const beforePotion = Array.isArray(beforeData.inventory)
        ? (beforeData.inventory.find((i) => (i.itemId || i.id) === 'healing_potion') || {})
        : {};
      expect(beforePotion.quantity || beforePotion.count).toBe(5);

      // Step 4: Start editor test mode (uses formal gear/skills for testing)
      const startTest = await findWorkingEndpoint('POST', [
        '/api/editor/test-mode/start',
        '/api/editor/test-mode/run',
        `/api/editor/maps/${mapId}/test`,
        `/api/users/${id}/editor/test`,
      ], {
        userId: id,
        mapId,
        useFormalLoadout: true,
      });
      expect([200, 201]).toContain(startTest.res.status);

      // Verify it's recognized as editor/test mode
      const mode = startTest.body.mode || startTest.body.testMode || startTest.body.type;
      if (mode) {
        expect(String(mode)).toMatch(/editor|test/i);
      }

      // Step 5: Simulate actions in test mode — death, skill use, item use, completion
      const testSessionId = startTest.body.sessionId || startTest.body.testId || startTest.body.id;

      // Simulate death in test
      await findWorkingEndpoint('POST', [
        '/api/editor/test-mode/event',
        `/api/editor/test-mode/${testSessionId}/event`,
