        '/api/editor/test-mode/event',
        `/api/editor/test-mode/${testSessionId}/event`,
      ], {
        userId: id,
        sessionId: testSessionId,
        event: 'skillUse',
        skillId: 'fireball',
      });

      // Simulate consumable use in test mode
      await findWorkingEndpoint('POST', [
        '/api/editor/test-mode/event',
        `/api/editor/test-mode/${testSessionId}/event`,
      ], {
        userId: id,
        sessionId: testSessionId,
        event: 'useItem',
        itemId: 'healing_potion',
        quantity: 2,
      });

      // Complete test mode
      const completeTest = await findWorkingEndpoint('POST', [
        '/api/editor/test-mode/complete',
        `/api/editor/test-mode/${testSessionId}/complete`,
        '/api/editor/test-mode/end',
      ], {
        userId: id,
        sessionId: testSessionId,
        mapId,
        completed: true,
        deaths: 3,
        reward: { gold: 999, exp: 999, items: [{ itemId: 'rare_drop', quantity: 2 }] },
