      // Verify formal progress was NOT written
      const formalWritten = completeTest.body.formalProgressWritten ?? completeTest.body.writtenToFormal ?? completeTest.body.affectedFormal;
      if (formalWritten !== undefined) {
        expect(formalWritten).toBe(false);
      }

      // Step 6: Verify ALL formal state dimensions are COMPLETELY unchanged after test mode
      const afterResult = await findWorkingEndpoint('GET', [
        `/api/users/${id}/account`,
        `/api/players/${id}`,
        `/api/users/${id}`,
        `/api/users/${id}/state`,
