      // Gold unchanged (test rewards not applied)
      expect(afterData.gold, 'Gold should be unchanged after editor test').toBe(100);

      // Exp unchanged
      expect(afterData.exp, 'Exp should be unchanged after editor test').toBe(10);

      // Inventory unchanged — healing potion still at 5, no rare_drop
      const afterInventory = afterData.inventory || afterData.items || [];
      expect(Array.isArray(afterInventory)).toBe(true);
      const afterPotion = afterInventory.find((i) => (i.itemId || i.id) === 'healing_potion');
      expect(afterPotion, 'healing_potion should still be in formal inventory').toBeTruthy();
      expect(afterPotion.quantity || afterPotion.count, 'healing_potion quantity should be unchanged').toBe(5);
      const rareDrop = afterInventory.find((i) => (i.itemId || i.id) === 'rare_drop');
      expect(rareDrop, 'rare_drop from test mode should NOT appear in formal inventory').toBeFalsy();

      // Quest progress unchanged
      const afterQuest = afterData.questProgress || afterData.quests;
      if (afterQuest) {
        expect(afterQuest.quest_main_1, 'Quest progress should be unchanged').toBe(1);
      } else {
        // If quest progress is accessed via separate endpoint, check it
        const questResult = await findWorkingEndpoint('GET', [
          `/api/users/${id}/quests`,
          `/api/players/${id}/quests`,
        ]);
        if (questResult.res.status === 200) {
          const questData = questResult.body.quests || questResult.body;
          if (questData.quest_main_1 !== undefined) {
            expect(questData.quest_main_1).toBe(1);
          }
        }
      }

      // Best records unchanged
      const afterRecords = afterData.bestRecords || afterData.records;
      if (afterRecords) {
        expect(afterRecords.stage_1, 'Best records should be unchanged').toBe(120);
      }

      // Durability unchanged
      const afterDurability = afterData.durability || afterData.itemDurability;
      if (afterDurability) {
        expect(afterDurability.bronze_sword, 'Durability should be unchanged').toBe(90);
      }

      // Cooldowns unchanged
      const afterCooldowns = afterData.cooldowns || afterData.skillCooldowns;
      if (afterCooldowns) {
        expect(afterCooldowns.fireball, 'Cooldowns should be unchanged').toBe(0);
      }

      // Step 7: Verify editor test deaths/completion did not pollute formal adventure progress
      const formalProgress = await findWorkingEndpoint('GET', [
        `/api/adventure/progress?userId=${encodeURIComponent(id)}`,
        `/api/users/${id}/adventure/progress`,
        `/api/players/${id}/adventure`,
      ]);
      if (formalProgress.res.status === 200) {
        const lastMode = formalProgress.body.lastMode || formalProgress.body.mode;
        if (lastMode !== null && lastMode !== undefined) {
          expect(String(lastMode)).not.toMatch(/editor/i);
        }
        // Death count should not include editor test deaths
        const formalDeaths = formalProgress.body.totalDeaths ?? formalProgress.body.deaths;
        if (formalDeaths !== undefined) {
          expect(formalDeaths, 'Formal death count should not include editor test deaths').toBe(0);
        }
      }

      // Step 8: Verify map layout is preserved after test mode run
      const mapAfter = await findWorkingEndpoint('GET', [
        `/api/editor/maps/${mapId}?userId=${encodeURIComponent(id)}`,
        `/api/maps/${mapId}`,
        `/api/users/${id}/editor/maps/${mapId}`,
      ]);
      expect(mapAfter.res.status).toBe(200);
      const afterElements = mapAfter.body.elements || mapAfter.body.tiles || [];
      if (Array.isArray(afterElements)) {
        const hasSpawn = afterElements.some((e) => e.type === 'spawn');
        const hasGoal = afterElements.some((e) => e.type === 'goal');
        expect(hasSpawn, 'spawn point should still exist after test run').toBe(true);
        expect(hasGoal, 'goal point should still exist after test run').toBe(true);
        // Verify ground tiles preserved
        const groundCount = afterElements.filter((e) => e.type === 'ground').length;
        expect(groundCount).toBeGreaterThanOrEqual(5);
      }
    } finally {
      await cleanup(cleanupPaths);
    }
  });
});

