      const wasRefreshed = buff2.body.used === true || buff2.body.refreshed === true;
      const wasRejected = buff2.body.used === false || buff2.body.rejected === true;

      if (wasRefreshed) {
        // Refresh rule: duration/expiresAt should be refreshed, stacks bounded
        const buff2Duration = buff2Effect.duration ?? buff2Effect.remainingDuration;
        const buff2Stacks = buff2Effect.stacks ?? buff2Effect.stackCount;
        if (buff2Duration != null && buff1Duration != null) {
          expect(buff2Duration).toBeGreaterThanOrEqual(buff1Duration);
        }
        if (buff2Stacks != null) {
          expect(buff2Stacks).toBeLessThanOrEqual(10);
        }
      } else if (wasRejected) {
        // Reject rule: should have clear message
        const msg = JSON.stringify(buff2.body).toLowerCase();
        expect(msg).toMatch(/stack|duplicate|already|cannot|无法|叠加|重复/);
      } else {
        expect(wasRefreshed || wasRejected, 'Repeat buff use must either refresh or reject').toBe(true);
      }

      // === Third buff use — confirm rule consistency ===
      const buff3 = await findWorkingEndpoint('POST', [
        '/api/items/use',
        `/api/users/${userId}/items/use`,
      ], {
        userId,
        itemId: 'attack_tonic',
      });
      expect([200, 201]).toContain(buff3.res.status);
      const buff3Refreshed = buff3.body.used === true || buff3.body.refreshed === true;
      const buff3Rejected = buff3.body.used === false || buff3.body.rejected === true;
      if (wasRefreshed) {
        expect(buff3Refreshed, 'Rule should be consistent: refresh on third use too').toBe(true);
      } else if (wasRejected) {
        expect(buff3Rejected, 'Rule should be consistent: reject on third use too').toBe(true);
      }

      // === Verify active buffs list — must show active buff status (strict check) ===
      const activeBuffs = await findWorkingEndpoint('GET', [
        `/api/items/buffs?userId=${encodeURIComponent(userId)}`,
        `/api/users/${userId}/buffs`,
        `/api/players/${userId}/buffs`,
        `/api/users/${userId}/active-buffs`,
      ]);
      expect(activeBuffs.res.status, 'Active buffs endpoint should return 200').toBe(200);
      const buffs = activeBuffs.body.buffs || activeBuffs.body.activeBuffs || activeBuffs.body || [];
      expect(Array.isArray(buffs), 'Active buffs should be an array').toBe(true);
      if (wasRefreshed) {
        // Buff should be present
        const matchingBuffs = buffs.filter(b => {
          const bKey = b.buffKey || b.buffId || b.name || b.id || b.itemId;
          return bKey === buffKey1 || bKey === 'attack_tonic';
        });
        expect(matchingBuffs.length, 'Should have exactly one entry for the buff (no infinite stacking)').toBe(1);
        // Verify duration/remaining time is shown
        const activeBuff = matchingBuffs[0];
        const hasDuration = (activeBuff.duration !== undefined) || (activeBuff.remainingDuration !== undefined) || (activeBuff.expiresAt !== undefined) || (activeBuff.remainingTime !== undefined);
        expect(hasDuration, 'Active buff should show duration/remaining time for status display').toBe(true);
        if (activeBuff.stacks != null || activeBuff.stackCount != null) {
          const stacks = activeBuff.stacks ?? activeBuff.stackCount;
          expect(stacks).toBeGreaterThanOrEqual(1);
          expect(stacks).toBeLessThanOrEqual(10);
        }
      }

      // === Equipment comparison with core attribute delta ===
      // Use steel_helmet which was added to inventory, compare against equipped iron_helmet
      const compare = await findWorkingEndpoint('GET', [
        `/api/items/compare?userId=${encodeURIComponent(userId)}&candidateItemId=steel_helmet&slot=head`,
        `/api/users/${userId}/items/compare?candidateItemId=steel_helmet&slot=head`,
        `/api/players/${userId}/items/compare?candidateItemId=steel_helmet&slot=head`,
      ]);
      expect(compare.res.status).toBe(200);

      const compareSlot = compare.body.slot;
      expect(compareSlot).toBe('head');

      const currentItem = compare.body.currentItem || compare.body.current || compare.body.equipped;
      const candidateItem = compare.body.candidateItem || compare.body.candidate || compare.body.newItem;
      expect(currentItem, 'Comparison should include current equipped item').toBeTruthy();
      expect(candidateItem, 'Comparison should include candidate item').toBeTruthy();

      const currentId = currentItem.itemId || currentItem.id;
      const candidateId = candidateItem.itemId || candidateItem.id;
      expect(currentId).toBe('iron_helmet');
      expect(candidateId).toBe('steel_helmet');

      const delta = compare.body.delta || compare.body.diff || compare.body.comparison || compare.body.changes;
      expect(delta, 'Comparison should include attribute delta').toBeTruthy();
      expect(typeof delta).toBe('object');

      // Verify delta contains at least one core attribute with numeric value
      const coreAttrKeys = ['attack', 'defense', 'hp', 'atk', 'def', 'strength', 'power', 'damage', 'protection', 'health'];
      const deltaKeys = Object.keys(delta);
      const hasCoreAttr = deltaKeys.some(k => coreAttrKeys.includes(k.toLowerCase()) && typeof delta[k] === 'number');
      expect(hasCoreAttr, `delta should contain at least one core attribute with numeric value, got keys: ${deltaKeys.join(', ')}`).toBe(true);

      // === Verify long name/description item data integrity ===
      const itemDetail = await findWorkingEndpoint('GET', [
        `/api/items/long_name_item?userId=${encodeURIComponent(userId)}`,
        `/api/users/${userId}/inventory/long_name_item`,
        `/api/items/detail?userId=${encodeURIComponent(userId)}&itemId=long_name_item`,
      ]);
      if (itemDetail.res.status === 200) {
        const itemName = itemDetail.body.name || itemDetail.body.itemName;
        const itemDesc = itemDetail.body.description || itemDetail.body.desc;
        if (itemName) {
          // Name should be complete or at least contain the full data in some field
          expect(itemName.length).toBeGreaterThanOrEqual(100);
        }
        if (itemDesc) {
          expect(itemDesc.length).toBeGreaterThanOrEqual(100);
        }
      } else {
        // If no separate item detail endpoint, check inventory listing
        const invResult = await findWorkingEndpoint('GET', [
          `/api/users/${userId}/account`,
          `/api/players/${userId}`,
        ]);
        if (invResult.res.status === 200) {
          const inv = invResult.body.inventory || invResult.body.items || [];
          const longItem = inv.find(i => (i.itemId || i.id) === 'long_name_item');
          if (longItem && longItem.name) {
            // Data should not be truncated in the API response
            expect(longItem.name.length).toBeGreaterThanOrEqual(100);
          }
        }
      }
    } finally {
      await cleanup(cleanupPaths);
    }
  });
});

import { describe, it, expect } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function request(method, path, body) {
  const res = await fetch(`${BASE_URL}${path}`, {
    method,
    headers: { 'Content-Type': 'application/json' },
    body: body === undefined ? undefined : JSON.stringify(body),
  });
  const text = await res.text();
  let json;
  try {
    json = text ? JSON.parse(text) : null;
  } catch {
    json = text;
  }
  return { res, body: json };
}

async function cleanup(paths) {
  for (const path of paths) {
    try {
      await fetch(`${BASE_URL}${path}`, { method: 'DELETE' });
    } catch {}
  }
}

describe('round16_multi_map_editor_migration', () => {
