      cleanupPaths.push(`/api/test/users/${userId}`);

      const listInitial = await request('GET', `/api/editor/maps?userId=${encodeURIComponent(userId)}`, undefined);
      expect(listInitial.res.status).toBe(200);
      expect(Array.isArray(listInitial.body.maps)).toBe(true);
      expect(listInitial.body.maps.length).toBeGreaterThan(0);
      const defaultMap = listInitial.body.maps.find((m) => m.isDefault || m.isMigratedDefault);
      expect(defaultMap, `expected migrated default map in list: ${JSON.stringify(listInitial.body.maps)}`).toBeTruthy();

      const createMap = await request('POST', '/api/editor/maps', {
        userId,
