        layout: [[0]],
      });
      expect([200, 201]).toContain(createMap.res.status);
      expect(createMap.body.mapId).toBeTruthy();
      expect(createMap.body.name).toBe('My Custom Map A');
      const mapA = createMap.body.mapId;
      cleanupPaths.push(`/api/editor/maps/${mapA}?userId=${encodeURIComponent(userId)}`);

      const emptyRename = await request('PATCH', `/api/editor/maps/${mapA}`, {
        userId,
        name: '',
      });
      expect([400, 409, 422]).toContain(emptyRename.res.status);
      expect(String(emptyRename.body.error || emptyRename.body.message || '')).toMatch(/name|名称|empty|required/i);

      const duplicateRename = await request('PATCH', `/api/editor/maps/${mapA}`, {
        userId,
        name: defaultMap.name,
      });
      expect([400, 409, 422]).toContain(duplicateRename.res.status);
      expect(String(duplicateRename.body.error || duplicateRename.body.message || '')).toMatch(/unique|重复|exists|duplicate/i);

      const renameOk = await request('PATCH', `/api/editor/maps/${mapA}`, {
        userId,
        name: 'My Custom Map Renamed',
      });
      expect([200, 201]).toContain(renameOk.res.status);
      expect(renameOk.body.name).toBe('My Custom Map Renamed');

      const copyMap = await request('POST', `/api/editor/maps/${mapA}/copy`, {
        userId,
        name: 'My Custom Map Copy',
      });
      expect([200, 201]).toContain(copyMap.res.status);
      expect(copyMap.body.mapId).toBeTruthy();
      expect(copyMap.body.mapId).not.toBe(mapA);
      expect(copyMap.body.name).toBe('My Custom Map Copy');
      const mapCopy = copyMap.body.mapId;
      cleanupPaths.push(`/api/editor/maps/${mapCopy}?userId=${encodeURIComponent(userId)}`);

      const setCurrent = await request('POST', '/api/editor/current-map', {
        userId,
        mapId: mapCopy,
      });
      expect([200, 201]).toContain(setCurrent.res.status);
      expect(setCurrent.body.currentMapId).toBe(mapCopy);

      const delCurrent = await request('DELETE', `/api/editor/maps/${mapCopy}?userId=${encodeURIComponent(userId)}`, undefined);
      expect([200, 204]).toContain(delCurrent.res.status);

      const currentAfterDelete = await request('GET', `/api/editor/current-map?userId=${encodeURIComponent(userId)}`, undefined);
      expect(currentAfterDelete.res.status).toBe(200);
      expect(currentAfterDelete.body.currentMapId).toBeTruthy();
      expect(currentAfterDelete.body.currentMapId).not.toBe(mapCopy);
    } finally {
      await cleanup(cleanupPaths);
    }
  });
});

