function pickItem(items, predicate, fallbackMsg) {
  const found = Array.isArray(items) ? items.find(predicate) : undefined;
  expect(found, fallbackMsg).toBeTruthy();
  return found;
}

describe('round21_shop_economy_flow', () => {
  it('should validate shop buy/sell loop with gold, capacity, level, equipped and quest-item protections, and immediate state linkage', async () => {
    const createdIds = [];

    const setup = await request('POST', '/api/test/setup/shop-economy', {
      scenario: 'shop-economy-flow',
      hero: {
        name: `shop-flow-${Date.now()}`,
        level: 3,
        gold: 100,
        inventoryCapacity: 5,
      },
    });

    expect([200, 201], `setup status expected 200/201, got ${setup.res.status}`).toContain(setup.res.status);
    expect(setup.body && typeof setup.body === 'object', 'setup response should be an object').toBeTruthy();
    expect(setup.body.characterId, `setup should return characterId, got ${JSON.stringify(setup.body)}`).toBeTruthy();
    expect(setup.body.shopId, `setup should return shopId, got ${JSON.stringify(setup.body)}`).toBeTruthy();

    const characterId = setup.body.characterId;
    const shopId = setup.body.shopId;
    createdIds.push(characterId);

    const shopItems = setup.body.items || setup.body.shopItems || [];
    const lowLevelItem = pickItem(
      shopItems,
      (i) => Number.isInteger(i.price) && i.price >= 0 && (i.requiredLevel ?? 1) <= 3 && (i.price ?? 0) <= 100,
      'expected at least one affordable item with non-negative integer price and allowed level'
    );

    expect(Number.isInteger(lowLevelItem.price), `item price should be integer, got ${lowLevelItem.price}`).toBe(true);
    expect(lowLevelItem.price).toBeGreaterThanOrEqual(0);

    const highLevelItem = pickItem(
      shopItems,
      (i) => Number.isInteger(i.requiredLevel) && i.requiredLevel > 3,
      'expected at least one level-restricted item in setup payload'
    );

    const expensiveItem = pickItem(
      shopItems,
      (i) => Number.isInteger(i.price) && i.price > 100,
      'expected at least one too-expensive item in setup payload'
    );

    const fill = await request('POST', `/api/characters/${characterId}/inventory/fill`, {
      reservedFreeSlots: 1,
    });
    expect([200, 201], `fill inventory status expected 200/201, got ${fill.res.status}`).toContain(fill.res.status);

    const stateBeforeFullBuy = await request('GET', `/api/characters/${characterId}`);
    expect(stateBeforeFullBuy.res.status, `character fetch should be 200, got ${stateBeforeFullBuy.res.status}`).toBe(200);
    expect(stateBeforeFullBuy.body.inventory, 'character inventory should exist').toBeTruthy();
    expect(typeof stateBeforeFullBuy.body.inventory.usedSlots, 'inventory.usedSlots should be number').toBe('number');
    expect(typeof stateBeforeFullBuy.body.inventory.capacity, 'inventory.capacity should be number').toBe('number');

    const noCapacityBuy = await request('POST', `/api/shop/${shopId}/buy`, {
      characterId,
      itemId: lowLevelItem.id,
      quantity: 1,
    });
    expect([400, 409, 422], `full-capacity buy should fail with 400/409/422, got ${noCapacityBuy.res.status}`).toContain(noCapacityBuy.res.status);
    expect(JSON.stringify(noCapacityBuy.body || {}).toLowerCase(), 'capacity failure message should mention inventory/capacity/full').toMatch(/inventory|capacity|full|背包/);

    const freeOne = await request('POST', `/api/characters/${characterId}/inventory/free-slots`, { slots: 1 });
    expect([200, 201], `free-slots status expected 200/201, got ${freeOne.res.status}`).toContain(freeOne.res.status);

    const levelDenied = await request('POST', `/api/shop/${shopId}/buy`, {
      characterId,
      itemId: highLevelItem.id,
      quantity: 1,
    });
    expect([400, 403, 409, 422], `level-restricted buy should fail, got ${levelDenied.res.status}`).toContain(levelDenied.res.status);
    expect(JSON.stringify(levelDenied.body || {}).toLowerCase(), 'level failure message should mention level').toMatch(/level|等级/);

    const goldDenied = await request('POST', `/api/shop/${shopId}/buy`, {
      characterId,
      itemId: expensiveItem.id,
      quantity: 1,
    });
    expect([400, 403, 409, 422], `insufficient-gold buy should fail, got ${goldDenied.res.status}`).toContain(goldDenied.res.status);
    expect(JSON.stringify(goldDenied.body || {}).toLowerCase(), 'gold failure message should mention gold/money/coin').toMatch(/gold|coin|money|金币/);

    const beforeBuy = await request('GET', `/api/characters/${characterId}`);
    expect(beforeBuy.res.status).toBe(200);
    const oldGold = beforeBuy.body.gold;
    const oldUsedSlots = beforeBuy.body.inventory.usedSlots;
    const oldAttack = beforeBuy.body.stats?.attack ?? beforeBuy.body.attributes?.attack ?? 0;

    const buyOk = await request('POST', `/api/shop/${shopId}/buy`, {
      characterId,
      itemId: lowLevelItem.id,
      quantity: 1,
    });
    expect([200, 201], `successful buy should return 200/201, got ${buyOk.res.status}`).toContain(buyOk.res.status);
    expect(buyOk.body, 'buy response body should exist').toBeTruthy();
    expect(buyOk.body.transaction || buyOk.body.item || buyOk.body.inventory, 'buy response should include transaction/item/inventory data').toBeTruthy();

    const afterBuy = await request('GET', `/api/characters/${characterId}`);
    expect(afterBuy.res.status).toBe(200);
    expect(afterBuy.body.gold, `gold should decrease by item price ${lowLevelItem.price}, before=${oldGold}, after=${afterBuy.body.gold}`).toBe(oldGold - lowLevelItem.price);
    expect(afterBuy.body.inventory.usedSlots, `used slots should increase after buy, before=${oldUsedSlots}, after=${afterBuy.body.inventory.usedSlots}`).toBeGreaterThanOrEqual(oldUsedSlots);

    const ownedItem = pickItem(
      afterBuy.body.inventory.items,
      (i) => i.itemId === lowLevelItem.id || i.id === lowLevelItem.id || i.templateId === lowLevelItem.id,
      'bought item should appear in inventory'
    );

    const equip = await request('POST', `/api/characters/${characterId}/equipment/equip`, {
      itemId: ownedItem.itemId || ownedItem.id || ownedItem.templateId,
    });
    expect([200, 201], `equip should return 200/201, got ${equip.res.status}`).toContain(equip.res.status);

    const afterEquip = await request('GET', `/api/characters/${characterId}`);
    expect(afterEquip.res.status).toBe(200);
    const newAttack = afterEquip.body.stats?.attack ?? afterEquip.body.attributes?.attack ?? 0;
    expect(newAttack, `equipping should immediately affect attack or keep non-decreasing, before=${oldAttack}, after=${newAttack}`).toBeGreaterThanOrEqual(oldAttack);

    const sellEquippedDenied = await request('POST', `/api/shop/${shopId}/sell`, {
      characterId,
      itemId: ownedItem.itemId || ownedItem.id || ownedItem.templateId,
      quantity: 1,
    });
    expect([400, 403, 409, 422], `selling equipped item should fail, got ${sellEquippedDenied.res.status}`).toContain(sellEquippedDenied.res.status);
    expect(JSON.stringify(sellEquippedDenied.body || {}).toLowerCase(), 'equipped-item sell rejection should mention equipped').toMatch(/equip|equipped|穿戴/);

    const questItem = pickItem(
      afterEquip.body.inventory.items,
      (i) => i.isQuestItem === true || i.protectedQuantity > 0 || i.lockedForQuest === true,
      'setup should provide at least one quest/protected item in inventory'
    );

    const sellQuestDenied = await request('POST', `/api/shop/${shopId}/sell`, {
      characterId,
      itemId: questItem.itemId || questItem.id || questItem.templateId,
      quantity: (questItem.protectedQuantity || 1),
    });
    expect([400, 403, 409, 422], `selling protected quest item should fail, got ${sellQuestDenied.res.status}`).toContain(sellQuestDenied.res.status);
    expect(JSON.stringify(sellQuestDenied.body || {}).toLowerCase(), 'quest-item protection message should mention quest/protected').toMatch(/quest|protected|任务|保护/);

    const unequip = await request('POST', `/api/characters/${characterId}/equipment/unequip`, {
      slot: lowLevelItem.slot || ownedItem.slot || 'weapon',
    });
    expect([200, 201], `unequip should return 200/201, got ${unequip.res.status}`).toContain(unequip.res.status);

    const beforeSell = await request('GET', `/api/characters/${characterId}`);
    expect(beforeSell.res.status).toBe(200);
    const beforeSellGold = beforeSell.body.gold;
    const beforeSellSlots = beforeSell.body.inventory.usedSlots;

    const sellOk = await request('POST', `/api/shop/${shopId}/sell`, {
      characterId,
      itemId: ownedItem.itemId || ownedItem.id || ownedItem.templateId,
      quantity: 1,
    });
    expect([200, 201], `successful sell should return 200/201, got ${sellOk.res.status}`).toContain(sellOk.res.status);
    expect(sellOk.body, 'sell response should exist').toBeTruthy();
    const sellPrice = sellOk.body.goldGained ?? sellOk.body.price ?? sellOk.body.totalPrice;
    expect(Number.isInteger(sellPrice), `sell price should be integer, got ${sellPrice}`).toBe(true);
    expect(sellPrice, `sell price should be non-negative, got ${sellPrice}`).toBeGreaterThanOrEqual(0);

    const afterSell = await request('GET', `/api/characters/${characterId}`);
    expect(afterSell.res.status).toBe(200);
    expect(afterSell.body.gold, `gold should increase by sell price ${sellPrice}, before=${beforeSellGold}, after=${afterSell.body.gold}`).toBe(beforeSellGold + sellPrice);
    expect(afterSell.body.inventory.usedSlots, `used slots should not increase after selling, before=${beforeSellSlots}, after=${afterSell.body.inventory.usedSlots}`).toBeLessThanOrEqual(beforeSellSlots);

    await safeDelete(`/api/characters/${characterId}`);
  });
});

