describe('round25_deterministic_script_replay', () => {
  it('should only start replay when map passes validation, keep command sequence <=20, produce deterministic outcomes, and reject manual interruption', async () => {
    const createdMapIds = [];

    const invalidMap = await request('POST', '/api/editor/maps', {
      name: `invalid-replay-map-${Date.now()}`,
      width: 8,
      height: 6,
      tiles: [
        '########',
        '#......#',
        '#..^...#',
        '#......#',
        '#......#',
        '########'
      ],
      start: null,
      goal: { x: 6, y: 4 },
      testMode: true,
    });

    expect([200, 201], `map creation should return 200/201, got ${invalidMap.res.status}`).toContain(invalidMap.res.status);
    expect(invalidMap.body && invalidMap.body.id, `invalid map creation should return id, got ${JSON.stringify(invalidMap.body)}`).toBeTruthy();
    createdMapIds.push(invalidMap.body.id);

    const invalidReplay = await request('POST', `/api/editor/maps/${invalidMap.body.id}/script-replay/start`, {
      script: ['RIGHT', 'RIGHT'],
      tickMs: 50,
      initialState: { hp: 10 },
    });
    expect([400, 409, 422], `replay on invalid map should fail, got ${invalidReplay.res.status}`).toContain(invalidReplay.res.status);
    expect(JSON.stringify(invalidReplay.body || {}).toLowerCase(), 'invalid-map replay failure should mention map/test/validation').toMatch(/map|test|valid|validation|校验/);

    const validMap = await request('POST', '/api/editor/maps', {
      name: `valid-replay-map-${Date.now()}`,
      width: 8,
      height: 6,
      tiles: [
        '########',
        '#S.....#',
        '#..^...#',
        '#......#',
        '#.....G#',
        '########'
      ],
      start: { x: 1, y: 1 },
      goal: { x: 6, y: 4 },
      testMode: true,
    });

    expect([200, 201], `valid map creation should return 200/201, got ${validMap.res.status}`).toContain(validMap.res.status);
    expect(validMap.body && validMap.body.id, `valid map creation should return id, got ${JSON.stringify(validMap.body)}`).toBeTruthy();
    createdMapIds.push(validMap.body.id);

    const tooLongScript = Array.from({ length: 21 }, () => 'RIGHT');
    const tooLongReplay = await request('POST', `/api/editor/maps/${validMap.body.id}/script-replay/start`, {
      script: tooLongScript,
      tickMs: 50,
      initialState: { hp: 10 },
    });
    expect([400, 409, 422], `script length >20 should be rejected, got ${tooLongReplay.res.status}`).toContain(tooLongReplay.res.status);
    expect(JSON.stringify(tooLongReplay.body || {}).toLowerCase(), 'too-long script failure should mention 20/step/length').toMatch(/20|step|length|limit|步/);

    const script = ['RIGHT', 'RIGHT', 'DOWN', 'RIGHT', 'RIGHT', 'DOWN', 'DOWN', 'RIGHT'];
    expect(script.length, 'script should be fixed and no more than 20 steps').toBeLessThanOrEqual(20);

    const firstRun = await request('POST', `/api/editor/maps/${validMap.body.id}/script-replay/start`, {
      script,
      tickMs: 50,
      initialState: { hp: 10, x: 1, y: 1 },
    });
