    expect(firstResult.body.completed, 'first replay should be marked completed').toBe(true);
    expect(firstResult.body.stepsExecuted, `stepsExecuted should equal script length ${script.length}, got ${firstResult.body.stepsExecuted}`).toBe(script.length);
    expect(firstResult.body.finalPosition, 'first replay should include finalPosition').toBeTruthy();
    expect(typeof firstResult.body.finalPosition.x, 'finalPosition.x should be number').toBe('number');
    expect(typeof firstResult.body.finalPosition.y, 'finalPosition.y should be number').toBe('number');
    expect(typeof firstResult.body.remainingHp, 'remainingHp should be number').toBe('number');
    expect(typeof firstResult.body.spikeTriggerCount, 'spikeTriggerCount should be number').toBe('number');
    expect(typeof firstResult.body.cleared, 'cleared should be boolean').toBe('boolean');

    const secondRun = await request('POST', `/api/editor/maps/${validMap.body.id}/script-replay/start`, {
      script,
      tickMs: 50,
      initialState: { hp: 10, x: 1, y: 1 },
    });
    expect([200, 201], `second replay start should return 200/201, got ${secondRun.res.status}`).toContain(secondRun.res.status);
    expect(secondRun.body && secondRun.body.runId, `second replay should return runId, got ${JSON.stringify(secondRun.body)}`).toBeTruthy();

    const secondResult = await request('GET', `/api/editor/maps/${validMap.body.id}/script-replay/${secondRun.body.runId}/result`);
    expect(secondResult.res.status, `second replay result should be 200, got ${secondResult.res.status}`).toBe(200);
    expect(secondResult.body.completed, 'second replay should be marked completed').toBe(true);

    expect(secondResult.body.finalPosition, 'second replay should include finalPosition').toEqual(firstResult.body.finalPosition);
    expect(secondResult.body.remainingHp, `remainingHp should be deterministic, first=${firstResult.body.remainingHp}, second=${secondResult.body.remainingHp}`).toBe(firstResult.body.remainingHp);
    expect(secondResult.body.cleared, `cleared flag should be deterministic, first=${firstResult.body.cleared}, second=${secondResult.body.cleared}`).toBe(firstResult.body.cleared);
    expect(secondResult.body.spikeTriggerCount, `spikeTriggerCount should be deterministic, first=${firstResult.body.spikeTriggerCount}, second=${secondResult.body.spikeTriggerCount}`).toBe(firstResult.body.spikeTriggerCount);

    await Promise.all(createdMapIds.map((id) => safeDelete(`/api/editor/maps/${id}`)));
  });
});

import { describe, it, expect, afterAll } from 'vitest';

const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';

async function request(method: string, path: string, body?: any) {
  const res = await fetch(`${BASE_URL}${path}`, {
    method,
    headers: { 'Content-Type': 'application/json' },
    body: body === undefined ? undefined : JSON.stringify(body),
  });
  const text = await res.text();
  let json: any;
  try {
    json = text ? JSON.parse(text) : null;
  } catch {
    json = text;
  }
  return { res, body: json };
}

async function safeDelete(path: string) {
  try {
    await fetch(`${BASE_URL}${path}`, { method: 'DELETE' });
  } catch {
    // ignore cleanup failures
  }
}

function lower(v: any): string {
  return JSON.stringify(v || {}).toLowerCase();
}

/**
 * Helper: try multiple candidate paths/methods until one succeeds.
 * Returns the first successful result or the last failure.
 */
async function tryEndpoints(candidates: Array<{ method: string; path: string; body?: any }>): Promise<{ res: Response; body: any; matchedPath?: string }> {
  let last: any;
  for (const c of candidates) {
    const result = await request(c.method, c.path, c.body);
    if (result.res.status >= 200 && result.res.status < 300) {
      return { ...result, matchedPath: c.path };
    }
    last = result;
  }
  return last;
}

describe('round27_product_flow_consistency_and_error_feedback', () => {
