    expect(loadSave.res.status, 'loading save slot should return 200').toBe(200);
    expect(loadSave.body, 'save slot payload should exist').toBeTruthy();
    // Verify saved data contains character-relevant info
    const savedData = loadSave.body?.data || loadSave.body;
    const savedGold = savedData?.gold ?? savedData?.character?.gold ?? savedData?.playerData?.gold;
    const savedLevel = savedData?.level ?? savedData?.character?.level ?? savedData?.playerData?.level;
    expect(savedGold != null || savedLevel != null, 'saved data should contain character gold or level').toBe(true);

    // ================================================================
    // SNAPSHOT before script replay (to verify isolation)
    // ================================================================
    const characterBeforeReplay = await request('GET', `/api/characters/${characterId}`);
    expect(characterBeforeReplay.res.status).toBe(200);
    const inventoryBeforeReplay = await tryEndpoints([
      { method: 'GET', path: `/api/characters/${characterId}/inventory` },
      { method: 'GET', path: `/api/players/${playerId}/inventory` },
    ]);
    expect(inventoryBeforeReplay.res.status).toBe(200);
    const questsBeforeReplay = await tryEndpoints([
      { method: 'GET', path: `/api/players/${playerId}/quests` },
      { method: 'GET', path: `/api/characters/${characterId}/quests` },
    ]);
    expect(questsBeforeReplay.res.status).toBe(200);

    const snapshotBefore = {
      gold: characterBeforeReplay.body?.gold ?? characterBeforeReplay.body?.currency,
      level: characterBeforeReplay.body?.level,
      exp: characterBeforeReplay.body?.exp ?? characterBeforeReplay.body?.experience,
      inventoryCount: (inventoryBeforeReplay.body?.items || (Array.isArray(inventoryBeforeReplay.body) ? inventoryBeforeReplay.body : [])).length,
      questCount: (questsBeforeReplay.body?.items || questsBeforeReplay.body?.quests || (Array.isArray(questsBeforeReplay.body) ? questsBeforeReplay.body : [])).length,
    };

    // ================================================================
    // CREATE CUSTOM MAP
    // ================================================================
    const mapCreate = await tryEndpoints([
      { method: 'POST', path: '/api/editor/maps', body: {
        name: `product-map-${ts}`,
        width: 6, height: 5,
        tiles: ['######', '#S...#', '#..^.#', '#...G#', '######'],
        start: { x: 1, y: 1 }, goal: { x: 4, y: 3 },
        testMode: true,
      }},
      { method: 'POST', path: '/api/maps', body: {
        name: `product-map-${ts}`,
        width: 6, height: 5,
        tiles: ['######', '#S...#', '#..^.#', '#...G#', '######'],
        start: { x: 1, y: 1 }, goal: { x: 4, y: 3 },
        testMode: true,
      }},
    ]);
    expect([200, 201]).toContain(mapCreate.res.status);
    const mapId = mapCreate.body?.id || mapCreate.body?.mapId;
    expect(mapId, `custom map create should return id, got ${JSON.stringify(mapCreate.body)}`).toBeTruthy();
    cleanupPaths.push(`/api/editor/maps/${mapId}`);

    // ================================================================
    // SCRIPT REPLAY
    // ================================================================
    const replay = await tryEndpoints([
      { method: 'POST', path: `/api/editor/maps/${mapId}/script-replay/start`, body: {
        script: ['RIGHT', 'RIGHT', 'DOWN', 'DOWN', 'RIGHT'],
        tickMs: 50,
        initialState: { hp: 10, x: 1, y: 1 },
      }},
      { method: 'POST', path: `/api/editor/maps/${mapId}/replay`, body: {
        script: ['RIGHT', 'RIGHT', 'DOWN', 'DOWN', 'RIGHT'],
        tickMs: 50,
        initialState: { hp: 10, x: 1, y: 1 },
      }},
      { method: 'POST', path: `/api/maps/${mapId}/test`, body: {
        script: ['RIGHT', 'RIGHT', 'DOWN', 'DOWN', 'RIGHT'],
        tickMs: 50,
      }},
    ]);
    expect([200, 201]).toContain(replay.res.status);
    const replayRunId = replay.body?.runId || replay.body?.id || replay.body?.replayId;
    expect(replayRunId, `script replay should return runId, got ${JSON.stringify(replay.body)}`).toBeTruthy();

    // Check replay result
    const replayResult = await tryEndpoints([
      { method: 'GET', path: `/api/editor/maps/${mapId}/script-replay/${replayRunId}/result` },
      { method: 'GET', path: `/api/editor/maps/${mapId}/replay/${replayRunId}` },
      { method: 'GET', path: `/api/maps/${mapId}/test/${replayRunId}` },
    ]);
    expect(replayResult.res.status).toBe(200);
    const replayCompleted = replayResult.body?.completed === true || replayResult.body?.status === 'completed' || replayResult.body?.success === true;
    expect(replayCompleted, `script replay should complete, got ${JSON.stringify(replayResult.body)}`).toBe(true);

    // ================================================================
    // VERIFY REPLAY DID NOT CORRUPT FORMAL PROGRESS
    // ================================================================
    const characterAfterReplay = await request('GET', `/api/characters/${characterId}`);
    expect(characterAfterReplay.res.status).toBe(200);
    const inventoryAfterReplay = await tryEndpoints([
      { method: 'GET', path: `/api/characters/${characterId}/inventory` },
      { method: 'GET', path: `/api/players/${playerId}/inventory` },
    ]);
    expect(inventoryAfterReplay.res.status).toBe(200);
    const questsAfterReplay = await tryEndpoints([
      { method: 'GET', path: `/api/players/${playerId}/quests` },
      { method: 'GET', path: `/api/characters/${characterId}/quests` },
    ]);
    expect(questsAfterReplay.res.status).toBe(200);

    const goldAfter = characterAfterReplay.body?.gold ?? characterAfterReplay.body?.currency;
    expect(goldAfter, 'gold should not change after script replay').toBe(snapshotBefore.gold);
    expect(characterAfterReplay.body?.level, 'level should not change after script replay').toBe(snapshotBefore.level);
    const expAfter = characterAfterReplay.body?.exp ?? characterAfterReplay.body?.experience;
    expect(expAfter, 'exp should not change after script replay').toBe(snapshotBefore.exp);
    const invCountAfter = (inventoryAfterReplay.body?.items || (Array.isArray(inventoryAfterReplay.body) ? inventoryAfterReplay.body : [])).length;
    expect(invCountAfter, 'inventory count should not change after script replay').toBe(snapshotBefore.inventoryCount);
    const questCountAfter = (questsAfterReplay.body?.items || questsAfterReplay.body?.quests || (Array.isArray(questsAfterReplay.body) ? questsAfterReplay.body : [])).length;
    expect(questCountAfter, 'quest count should not change after script replay').toBe(snapshotBefore.questCount);

    // ================================================================
    // FINAL CONSISTENCY CHECK
    // ================================================================
    const characterFinal = await request('GET', `/api/characters/${characterId}`);
    expect(characterFinal.res.status).toBe(200);

    if (hasSummaryEndpoint) {
      const summaryFinal = await tryEndpoints([
        { method: 'GET', path: `/api/ui/summary?playerId=${encodeURIComponent(playerId)}` },
        { method: 'GET', path: `/api/players/${playerId}/summary` },
      ]);
      expect(summaryFinal.res.status).toBe(200);

      const sumGold = summaryFinal.body?.gold ?? summaryFinal.body?.playerGold;
      const charGold = characterFinal.body?.gold ?? characterFinal.body?.currency;
      if (sumGold !== undefined && charGold !== undefined) {
        expect(sumGold, 'summary gold should match character gold').toBe(charGold);
      }
      const sumLevel = summaryFinal.body?.level ?? summaryFinal.body?.playerLevel;
      if (sumLevel !== undefined) {
        expect(sumLevel, 'summary level should match character level').toBe(characterFinal.body?.level);
      }

      if (hasShortcutsEndpoint) {
        const shortcutsFinal = await tryEndpoints([
          { method: 'GET', path: `/api/ui/shortcuts?playerId=${encodeURIComponent(playerId)}` },
          { method: 'GET', path: `/api/players/${playerId}/shortcuts` },
        ]);
        expect(shortcutsFinal.res.status).toBe(200);
        const scGold = shortcutsFinal.body?.gold ?? shortcutsFinal.body?.playerGold;
        if (scGold !== undefined && sumGold !== undefined) {
          expect(scGold, 'shortcut gold should match summary gold').toBe(sumGold);
        }
        const scLevel = shortcutsFinal.body?.level ?? shortcutsFinal.body?.playerLevel;
        if (scLevel !== undefined && sumLevel !== undefined) {
          expect(scLevel, 'shortcut level should match summary level').toBe(sumLevel);
        }
      }
    }

    // ================================================================
    // ERROR: Adventure failure scenario (failure state feedback)
    // ================================================================
    const failAdventure = await tryEndpoints([
      { method: 'POST', path: '/api/adventure/start', body: { characterId, stageId: 'impossible-boss-stage-999' } },
      { method: 'POST', path: `/api/characters/${characterId}/adventure/start`, body: { stageId: 'impossible-boss-stage-999' } },
    ]);
    if ([200, 201].includes(failAdventure.res.status)) {
      // Adventure started on an impossible stage - try to complete (should fail)
      const failRunId = failAdventure.body?.runId || failAdventure.body?.adventureId || failAdventure.body?.id;
      const failComplete = await tryEndpoints([
        { method: 'POST', path: '/api/adventure/complete', body: { characterId, stageId: 'impossible-boss-stage-999', runId: failRunId, simulateDefeat: true } },
        { method: 'POST', path: `/api/adventure/${failRunId}/complete`, body: { result: 'defeat' } },
      ]);
      // Whether 200 with failure result or 4xx, must have clear feedback
      if ([200, 201].includes(failComplete.res.status)) {
        const failResult = failComplete.body?.result || failComplete.body?.status;
        expect(failResult, 'failed adventure should indicate failure/defeat').toMatch(/fail|defeat|lost|死亡|失败/);
      } else {
        expect([400, 403, 404, 409, 422]).toContain(failComplete.res.status);
        expect(lower(failComplete.body)).toMatch(/fail|defeat|dead|hp|impossible|lost|失败|死亡/);
      }
    } else {
      // Stage doesn't exist - that's also a valid failure feedback
      expect([400, 404, 422]).toContain(failAdventure.res.status);
      expect(lower(failAdventure.body)).toMatch(/stage|not.found|invalid|fail|不存在|失败|关卡/);
    }

    // Verify formal progress not affected by failed adventure
    const charAfterFail = await request('GET', `/api/characters/${characterId}`);
    expect(charAfterFail.res.status).toBe(200);
    expect(charAfterFail.body?.level, 'level should not change after failed adventure').toBe(characterFinal.body?.level);

    // ================================================================
    // ERROR: Insufficient gold
    // ================================================================
    const currentGold = characterFinal.body?.gold ?? characterFinal.body?.currency ?? 0;
    let expensiveItem = shopItems.find((i: any) => (i.price || 0) > currentGold);
    const noGold = await tryEndpoints([
      { method: 'POST', path: `/api/shop/${shopId}/buy`, body: { characterId, itemId: (expensiveItem || { id: 'too-expensive-item' }).id, quantity: 9999 } },
      { method: 'POST', path: `/api/shop/buy`, body: { characterId, shopId, itemId: (expensiveItem || { id: 'too-expensive-item' }).id, quantity: 9999 } },
    ]);
    expect([400, 403, 409, 422]).toContain(noGold.res.status);
    expect(lower(noGold.body), 'insufficient-gold response should mention gold/coin').toMatch(/gold|coin|金币|insufficient|余额|不足|afford/);

    // ================================================================
    // ERROR: Bag full
    // ================================================================
    // Try to fill inventory
    const bagFill = await tryEndpoints([
      { method: 'POST', path: `/api/characters/${characterId}/inventory/fill`, body: { reservedFreeSlots: 0 } },
      { method: 'POST', path: `/api/test/fill-inventory`, body: { characterId, reservedFreeSlots: 0 } },
      { method: 'POST', path: `/api/players/${playerId}/inventory/fill`, body: { reservedFreeSlots: 0 } },
    ]);
    const bagFilled = [200, 201].includes(bagFill.res.status);

    if (bagFilled && buyTarget) {
      const fullBuy = await tryEndpoints([
        { method: 'POST', path: `/api/shop/${shopId}/buy`, body: { characterId, itemId: buyTarget.id, quantity: 1 } },
        { method: 'POST', path: `/api/shop/buy`, body: { characterId, shopId, itemId: buyTarget.id, quantity: 1 } },
      ]);
      expect([400, 409, 422]).toContain(fullBuy.res.status);
      expect(lower(fullBuy.body), 'full-bag response should mention bag/inventory/full').toMatch(/bag|inventory|full|背包|容量|空间|满/);

      // Reward claim when bag is full → should warn or go to pending
      const rewardWhenFull = await tryEndpoints([
        { method: 'POST', path: `/api/players/${playerId}/rewards/claim`, body: { questId: completedQuestId || 'test-reward-when-full' } },
        { method: 'POST', path: `/api/characters/${characterId}/rewards/claim`, body: { questId: completedQuestId || 'test-reward-when-full' } },
      ]);
      if ([400, 409, 422].includes(rewardWhenFull.res.status)) {
        expect(lower(rewardWhenFull.body), 'full bag reward rejection should mention bag/full/space').toMatch(/bag|full|space|inventory|背包|清理|容量|pending|待领|满|溢出/);
      } else if ([200, 201].includes(rewardWhenFull.res.status)) {
        const pendingInfo = rewardWhenFull.body?.pendingItems || rewardWhenFull.body?.overflow || rewardWhenFull.body?.mailbox;
        expect(pendingInfo, 'when bag is full, reward items should go to pending/overflow area').toBeTruthy();
      }
    }

    // ================================================================
    // ERROR: Level restricted
    // ================================================================
    const levelRestricted = shopItems.find((i: any) => Number.isInteger(i.requiredLevel) && i.requiredLevel > (characterFinal.body?.level || 1));
    if (levelRestricted) {
      const lowLevelBuy = await tryEndpoints([
        { method: 'POST', path: `/api/shop/${shopId}/buy`, body: { characterId, itemId: levelRestricted.id, quantity: 1 } },
        { method: 'POST', path: `/api/shop/buy`, body: { characterId, shopId, itemId: levelRestricted.id, quantity: 1 } },
      ]);
      expect([400, 403, 409, 422]).toContain(lowLevelBuy.res.status);
      expect(lower(lowLevelBuy.body), 'level-restricted response should mention level').toMatch(/level|等级|不足/);
    }

    // ================================================================
    // ERROR: Import failure
    // ================================================================
    const importFail = await tryEndpoints([
      { method: 'POST', path: '/api/editor/maps/import', body: { format: 'json', content: '{ invalid json' } },
      { method: 'POST', path: '/api/maps/import', body: { format: 'json', content: '{ invalid json' } },
    ]);
    expect([400, 422]).toContain(importFail.res.status);
    expect(lower(importFail.body), 'import failure should mention import/parse/invalid').toMatch(/import|parse|invalid|导入|格式|json|error/);

    // ================================================================
    // ERROR: Map validation failure
    // ================================================================
    const invalidMap = await tryEndpoints([
      { method: 'POST', path: '/api/editor/maps', body: {
        name: `invalid-map-${ts}`, width: 4, height: 4,
        tiles: ['####', '#..#', '#..#', '####'],
        start: null, goal: null,
        testMode: true,
      }},
      { method: 'POST', path: '/api/maps', body: {
        name: `invalid-map-${ts}`, width: 4, height: 4,
        tiles: ['####', '#..#', '#..#', '####'],
        start: null, goal: null,
        testMode: true,
      }},
    ]);

    if ([200, 201].includes(invalidMap.res.status) && invalidMap.body?.id) {
      // Map saved as draft; replay should fail validation
      const invalidMapId = invalidMap.body.id;
      cleanupPaths.push(`/api/editor/maps/${invalidMapId}`);

      const invalidReplay = await tryEndpoints([
        { method: 'POST', path: `/api/editor/maps/${invalidMapId}/script-replay/start`, body: { script: ['RIGHT'], tickMs: 50, initialState: { hp: 10 } } },
        { method: 'POST', path: `/api/editor/maps/${invalidMapId}/replay`, body: { script: ['RIGHT'] } },
        { method: 'POST', path: `/api/maps/${invalidMapId}/test`, body: { script: ['RIGHT'] } },
      ]);
      expect([400, 409, 422]).toContain(invalidReplay.res.status);
      expect(lower(invalidReplay.body), 'map validation failure should mention map/validation/start/goal').toMatch(/map|valid|validation|校验|start|goal|起点|终点/);
    } else if ([400, 422].includes(invalidMap.res.status)) {
      // Map rejected outright with validation error - also acceptable
      expect(lower(invalidMap.body), 'map creation rejection should mention validation').toMatch(/valid|start|goal|map|校验|起点|终点/);
    }

    // ================================================================
    // VERIFY: Formal progress still intact after all error scenarios
    // ================================================================
    const progressAfterErrors = await tryEndpoints([
      { method: 'GET', path: `/api/players/${playerId}/progress` },
      { method: 'GET', path: `/api/characters/${characterId}/progress` },
      { method: 'GET', path: `/api/players/${playerId}` },
    ]);
    expect(progressAfterErrors.res.status).toBe(200);
    expect(progressAfterErrors.body, 'progress payload should exist').toBeTruthy();
    const hasProgress =
      progressAfterErrors.body?.lastClearedStage ||
      (progressAfterErrors.body?.completedStages && progressAfterErrors.body.completedStages.length > 0) ||
      progressAfterErrors.body?.formalProgress ||
      progressAfterErrors.body?.level ||
      progressAfterErrors.body?.progress;
    expect(hasProgress, 'formal progress should still exist after error scenarios').toBeTruthy();

    // Final refresh consistency - level should not have changed
    if (hasSummaryEndpoint) {
      const summaryPostErrors = await tryEndpoints([
        { method: 'GET', path: `/api/ui/summary?playerId=${encodeURIComponent(playerId)}` },
        { method: 'GET', path: `/api/players/${playerId}/summary` },
      ]);
      if (summaryPostErrors.res.status === 200) {
        const finalSumLevel = summaryPostErrors.body?.level ?? summaryPostErrors.body?.playerLevel;
        if (finalSumLevel !== undefined) {
          expect(finalSumLevel, 'summary level should remain stable after error scenarios').toBe(characterFinal.body?.level);
        }
      }
    }
  });
});
